(window.GIM_TP=window.GIM_TP||{})["Z.Mishpatim.0"]={"from":0,"a":[[["[אמרו המגיהים מתחלת הפרשה עד מעשה ידי להתפאר קי\"ד א' הוא מן הסבא ויגענו ומצאנו הנסחא מדויקת תלי\"ת.] פָּתַח ר' שִׁמְעוֹן ואָמַר, (שמות כ״א:א׳) וְאֵלֶּה הַמִּשְׁפָּטִים אֲשֶׁר תָּשִׂים לִפְנֵיהֶם, תַּרְגוּם, וְאִלֵּין דִּינַיָּא דִּתְסַדֵּר קֳדָמֵיהוֹן. אִלֵּין אִינּוּן סִדּוּרִין דְּגִלְגּוּלָא, דִּינִין דְּנִשְׁמָתִין, דְּאִתְדָּנוּ כָּל חַד וְחַד לָקֳבֵל עוֹנְשֵׁיהּ.","(שמות כ״א:ב׳) כִּי תִקְנֶה עֶבֶד עִבְרִי שֵׁשׁ שָׁנִים יַעֲבֹד וּבַשְּׁבִיעִית יֵצֵא לַחָפְשִׁי חִנָּם. חַבְרַיָּיא, עִידָן הָכָא, לְגַלָּאָה כַּמָּה רָזִין טְמִירִין דְּגִלְגּוּלָא. כִּי תִקְנֶה עֶבֶד עִבְרִי שֵׁשׁ שָׁנִים יַעֲבֹד. כַּד נִשְׁמְתָא אִתְחַיְּיבַת בְּגִלְגּוּלָא, אִם הִיא מִסִּטְרָא דְּהַהוּא עֶבֶד מְטַטְרוֹן, דְּאִיהוּ (ק\"ה ע\"ב, ט\"ו ע\"א, צ\"ו ע\"א) כָּלִיל שִׁית סִטְרִין, כְּתִיב בֵּיהּ שֵׁשׁ שָׁנִים יַעֲבֹד, גִּלְגּוּלִין דִּילָהּ לָא מִתְחַיְּיבָא אֶלָּא שִׁית שְׁנִין, עַד דְּאַשְׁלִימָת שֵׁשׁ דַּרְגִין, מֵהַהוּא אֲתַר דְּאִתְנְטִילָת.","אֲבָל אִם נִשְׁמְתָא הִיא מִסִּטְרָא דִּשְׁכִינְתָּא, דְּאִיהִי שְׁבִיעִית וַדַאי מַה כְּתִיב, וּבַשְּׁבִיעִית יֵצֵא לַחָפְשִׁי חִנָּם, דְּצַדִּיק, וַדַאי לֵית בֵּיהּ מְלָאכָה, כֵּיוָן דְּלֵית בֵּיהּ מְלָאכָה, לֵית בֵּיהּ שִׁעְבּוּד. וְנִשְׁמְתָא דְּאִיהִי מִתַּמָּן, אִתְּמַר בָּהּ וּבַשְּׁבִיעִית יֵצֵא לַחָפְשִׁי חִנָּם, לֵית בָּהּ שִׁעְבּוּדָא."],[[0,"פתח ר' שמעון וכו':","פתח ר\"ש ואמר, ואלה המשפטים אשר תשים לפניהם, התרגום, ואלין דיניא דתסדר קדמיהון. אלו הם סדרים של גלגול, כי משפטים פירושו דינים, דהיינו דינים של נשמות החוזרות ומתגלגלות לעוה\"ז הנדונות כל אחת ואחת לפי עונשה."],[1,"כי תקנה עבד עברי שש שנים וגו':","אמר להם ר\"ש, חברים, כאן הזמן לגלות כמה סודות נסתרים של גלגול, כי תקנה עבד עברי שש שנים יעבד, היינו, כשהנשמה מתחייבת בגלגול, או מחמת עונות, או שלא השלימה בחייה התורה ומצות. מחייבים אותה לחזור לעולם הזה ולהתלבש בגוף, דהיינו לחזור ולהולד ולהשלים המוטל עליה בשבעים שנות חיים בעולם הזה. אם היא מצד המלאך מטטרון שבעולם הבריאה, הכלול שש מדרגות חג\"ת נה\"י, כתוב בו שש שנים יעבד, אינה מתחייבת בגלגולים אלא עד שמשלמת לתקן שש מדרגות, חג\"ת נה\"י, מאותו המקום שנלקחה משם, דהיינו מטטרון."],[2,"אבל אם נשמתא וכו':","אבל אם הנשמה היא מצד השכינה, שהיא שביעית, דהיינו מלכות דאצילות, השביעית לחג\"ת נה\"י דאצילות, ודאי מה כתוב בה, ובשביעית יצא לחפשי חנם, כי צדיק שזכה לנשמה ממלכות דאצילות, אין בו מלאכה, שהוא בחינת שבת, שאין מלאכה, דהיינו בירורי מוחין, נוהג בו, וכיון שאין בו מלאכה אין בו שעבוד. והנשמה שהיא משם, נאמר בה ובשביעית יצא לחפשי חנם, אין בה שעבוד."]],[[0,"","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, וְאֵלֶּה הַמִּשְׁפָּטִים אֲשֶׁר תָּשִׂים לִפְנֵיהֶם. תַּרְגּוּם: וְאִלֵּין דִּינַיָּא דִּי תַסְדַּר קֳדָמֵיהוֹן. אֵלֶּה אוֹתָם סִדּוּרִים שֶׁל הַגִּלְגּוּל, דִּינֵי הַנְּשָׁמוֹת שֶׁנִּדּוֹנוּ כָּל אֶחָד וְאֶחָד לְקַבֵּל עָנְשׁוֹ. כִּי תִקְנֶה עֶבֶד עִבְרִי שֵׁשׁ שָׁנִים יַעֲבֹד וּבַשְּׁבִיעִית יֵצֵא לַחָפְשִׁי חִנָּם. חֲבֵרִים, הַזְּמַן כָּעֵת לְגַלּוֹת כַּמָּה סוֹדוֹת נִסְתָּרִים שֶׁל הַגִּלְגּוּל."],[1,"","כִּי תִקְנֶה עֶבֶד עִבְרִי שֵׁשׁ שָׁנִים יַעֲבֹד, כְּשֶׁהַנְּשָׁמָה הִתְחַיְּבָה בְּגִלְגּוּל, אִם הִיא מִצַּד אוֹתוֹ הָעֶבֶד מטטרו\"ן, שֶׁהוּא כּוֹלֵל שִׁשָּׁה צְדָדִים, כָּתוּב בּוֹ שֵׁשׁ שָׁנִים יַעֲבֹד. גִּלְגּוּלִים שֶׁלָּהּ לֹא מִתְחַיֶּבֶת אֶלָּא שֵׁשׁ שָׁנִים, עַד שֶׁמַּשְׁלִימָה שֵׁשׁ דְּרָגוֹת מֵאוֹתוֹ הַמָּקוֹם שֶׁנִּלְקְחָה."],[2,"","אֲבָל אִם הַנְּשָׁמָה הִיא מִצַּד הַשְּׁכִינָה שֶׁהִיא שְׁבִיעִית, וַדַּאי מַה כָּתוּב? וּבַשְּׁבִיעִית יֵצֵא לַחָפְשִׁי חִנָּם. שֶׁצַּדִּיק וַדַּאי אֵין בּוֹ מְלָאכָה, וְכֵיוָן שֶׁאֵין בּוֹ מְלָאכָה, אֵין בּוֹ שִׁעְבּוּד. וְהַנְּשָׁמָה שֶׁהִיא מִשָּׁם, נֶאֱמַר בָּהּ וּבַשְּׁבִיעִית יֵצֵא לַחָפְשִׁי חִנָּם, אֵין בָּהּ שִׁעְבּוּד."]]],[["אַדְהָכִי, הָא סָבָא נָחַת לְגַבֵּיהּ, אֲמַר לֵיהּ, אִי הָכִי, רַבִּי, מַה תּוֹסֶפֶת לְנִשְׁמְתָא דְּאִיהִי מִנָּהּ, דְּאִתְּמַר בָּהּ, (שמות כ׳:י׳) לֹא תַעֲשֶׂה כָל מְלָאכָה אַתָּה וּבִנְךָ וּבִתֶךָ וְעַבְדְךָ וְגוֹ'.","אֲמַר לֵיהּ, סָבָא סָבָא, וְאַתְּ שָׁאִיל דָּא, דְּוַדַּאי הַאי עַל נִשְׁמְתָא דְּצַדִּיק אִתְּמַר, דְאַף עַל גַּב דְּאִתְחַיָּיב לְאַחֲתָא בְּגִלְגּוּלָא בְּכָל אִלֵּין, אֲפִילּוּ בְּעֶבֶד וְאָמָה, וּבְעִירָן דְּאִינּוּן אוֹפַנִּים, אוֹ בְּכָל חֵיוָן, דְּמִנְּהוֹן נִשְׁמָתִין דִּבְנִי נָשָׁא, כְּתִיב בָּהּ לא תַּעֲשֶׂה כָל מְלָאכָה. וְהַאי אִיהוּ, (ויקרא כ״ה:ל״ט) לא תַעֲבֹד בּוֹ עֲבוֹדַת עָבֶד, בְּצַדִיק דְּאִיהוּ יוֹם הַשַּׁבָּת, לא תַעֲבֹד בּוֹ עֲבוֹדַת עָבֶד, דְּאִיהוּ יוֹם דְּחוֹל.","אֲבָל סָבָא סָבָא, שַׁבָּת (ד\"א נשמתא) דְּאִיהִי בַּת יְחִידָה, וְאִיהִי בַּת זוּגֵיהּ דְּצַדִּיק, דְּאִיהוּ שַׁבָּת. מַאי אִם אַחֶרֶת יִקַּח לוֹ. אֲמַר לֵיהּ הָא וַדָאי הַבְדָלָה, חוּלוֹ שֶׁל שַׁבָּת, דְּאִית אַחֲרָא דְּלָא אִתְקְרִיאַת חוּלוֹ שֶׁל שַׁבָּת, אֶלָּא חוּלוֹ שֶׁל טֻמְאָה שִׁפְחָה. אֲמַר לֵיהּ. וְהָא חוּלוֹ שֶׁל שַׁבָּת מַאי הִיא. אֲמַר לֵיהּ, דָּא אֲמָתָא, דְּאִיהִי גּוּפָא דְּבַת יְחִידָה דְּעָלָהּ אִתְּמַר, אִם אַחֶרֶת יִקַּח לוֹ.","תָּא חֲזִי, נִשְׁמְתָא אִית דְּאִתְקְרִיאַת אָמָה, וְאִית (נשמתא) שְׁכִינְתָּא דְּאִתְקְרִיאַת שִׁפְחָה, (ונשמתא) וְשְׁכִינְתָּא אִית דְּאִתְקְרִיאַת בְּרָתָא דְּמַלְכָּא. הָכָא אִית אִישׁ, דְּאִתְּמַר בֵּיהּ (שמות ט״ו:ג׳) יְיָ' אִישׁ מִלְחָמָה. וְאִית אִישׁ, דְּאִתְּמַר בֵּיהּ (דניאל ט׳:כ״א) וְהָאִישׁ גַּבְרִיאֵל.","וּבְגִין דָּא, נִשְׁמְתָא דְּאִיהִי מִחַיְיבָא בְּגִלְגוּל, אִם הִיא בְּרָתָא דְקוּדְשָׁא בְּרִיךְ הוּא, אִי תֵּימָא דְּאִזְדְבָן בְּגוּפָא נוּכְרָאָה, דְּתַמָּן שֻׁלְטָנוּתָא דְּיֵצֶר הָרָע דְּאִיהוּ מִסִּטְרָא דְּסָמָאֵ\"ל. חַס וְשָׁלוֹם. דְּהָא כְּתִיב, (ישעיהו מ״ב:ח׳) אֲנִי יְיָ' הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לא אֶתֵּן דְּאִיהוּ יֵצֶר הָרָע.","וְהַהוּא גּוּפָא, דְּשַׁרְיָא בְּרָתָא דְּמַלְכָּא, אִי תֵּימָא דְּאִזְדְבָן בְּכִתְרִין תַּתָּאִין דִּמְסָאַבוּ, חֲלִילָה וְחָס. עָלָהּ אִתְּמַר (ויקרא כ״ה:כ״ג) וְהָאָרֶץ לֹא תִמָּכֵר לִצְמִיתוּת כִּי לִי הָאָרֶץ. מַאן גּוּפָא דִּבְרָתָא דְּמַלְכָּא. דָּא מְטַטְרוֹן. וְהַאי גּוּפָא אִיהוּ אָמָה דִּשְׁכִינְתָא, אַף עַל גַּב דְּאִיהִי נִשְׁמְתָא דְּאִיהִי בְּרָתָא דְּמַלְכָּא שְׁבוּיָה תַּמָּן, בְּגִלְגּוּלָא אַתְיָא דְּאַתְיָין גִלְגּוּלִין בְּגִין דְּאַתִּית תַּמָּן, מַה כְּתִיב בָּהּ (שמות כ״א:ז׳) וְכִי יִמְכּוֹר אִישׁ אֶת בִּתּוֹ לְאָמָה לא תֵּצֵא כְּצֵאת הָעֲבָדִים.","וְעוֹד וְכִי יִמְכּוֹר אִישׁ, דָּא קוּדְשָׁא בְּרִיךְ הוּא. אֶת בִּתּוֹ: אֵלּוּ יִשְׂרָאֵל, דְּאִינּוּן מִסִּטְרָא דְּבַת יְחִידָה, אִתְקְרִיאוּ בִּתּוֹ. וְאִי תֵּימָא דְּיִפְקוּן, כְּגַוְונָא דְּאִלֵין מִסִּטְרָא דְּעֶבֶד, דְּאִיהוּ מְטַטְרוֹ\"ן, דְּנַפְקוּ בִּמְנוּסָה מִמִּצְרַיִם, לא תֵצֵא כְּצֵאת הָעֲבָדִים, הֲדָא הוּא דִכְתִיב, (ישעיהו נ״ב:י״ב) כִּי לא בְּחִפָּזוֹן תֵּצֵאוּ וּבִמְנוּסָה לֹא תֵלֵכוּן.","תָּא חֲזִי, בַּר נָשׁ כַּד אִתְיְלִיד, (ויקרא רכ\"ד ע\"ב) יָהֲבִין לֵיהּ נַפְשָׁא מִסִּטְרָא דִּבְעִירָא, מִסִּטְרָא דְּדַכְיוּ, מִסִּטְרָא דְּאִלֵּין דְּאִתְקְרוּן אוֹפַנֵּי הַקּוֹדֶשׁ. זָכָה יַתִּיר, יַהֲבִין לֵיהּ רוּחָא, מִסִּטְרָא דְּחַיּוֹת הַקּוֹדֶשׁ. זָכָה יַתִּיר, יַהֲבִין לֵיהּ נִשְׁמְתָא, מִסִּטְרָא דְּכֻרְסְיָיא. וּתְלַת אִלֵּין, אִינּוּן אָמָה עֶבֶד וְשִׁפְחָה דִּבְרָתָא דְּמַלְכָּא.","זָכָה יַתִּיר, יַהֲבִין לֵיהּ נַפְשָׁא בְּאֹרַח אֲצִילוּת, מִסִּטְרָא דְּבַת יְחִידָה, וְאִתְקְרִיאַת אִיהִי בַּת מֶלֶךְ. זָכָה יַתִּיר, יַהֲבִין לֵיהּ רוּחָא דְּאֲצִילוּת. מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא, וְאִקְרֵי בֵּן לְּקוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב, (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ' אֱלֹהֵיכֶם. זָכָה יַתִּיר, יַהֲבִין לֵיהּ נִשְׁמְתָא, מִסִּטְרָא דְּאַבָּא וְאִמָא. הֲדָא הוּא דִכְתִיב, (בראשית ב׳:ז׳) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים. מַאי חַיִּים. אֶלָּא אִינּוּן י\"ה, דְּעָלַיְיהוּ אִתְּמַר, (תהילים ק״נ:ו׳) כָּל הַנְּשָׁמָה תְּהַלֵּל יָהּ, וְאִשְׁתְּלִים בֵּיהּ ידו\"ד.","זָכָה יַתִּיר, יַהֲבִין לֵיהּ ידו\"ד בִּשְׁלִימוּ דְּאַתְוָון, יוּ\"ד הֵ\"א וָא\"ו הֵ\"א, דְּאִיהוּ אָדָם, בְּאֹרַח אֲצִילוּת דְּעֵילָּא, וְאִתְקְרֵי בְּדִיּוּקְנָא דְּמָארֵיהּ. וְעָלֵיהּ אִתְּמַר, (בראשית א׳:כ״ח) וּרְדוּ בִּדְגַת הַיָּם וְגוֹ'. וְהַאי אִיהוּ שׁוּלְטָנוּתֵיהּ בְּכָל רְקִיעִין, וּבְכָל אוֹפַנִּים וּשְׂרָפִים וְחֵיוָון, וּבְכָל חַיָּילִין וְתוּקְפִין דִּלְעֵילָּא וְתַתָּא. וּבְגִין דָּא, כַּד בַּר נָשׁ זָכֵי בְּנֶפֶשׁ מִסִּטְרָא דְּבַת יְחִידָה, אִתְּמַר בֵּיהּ, לא תֵצֵא כְּצֵאת הָעֲבָדִים.","רַבִּי חִיָּיא וְרַבִּי יוֹסִי אִעֲרָעוּ חַד לֵילְיָא בְּמִגְדַּל דְּצוֹר. אִתְאֲרָחוּ תַּמָּן וְחַדּוּ דָּא בְּדָא. אָמַר רַבִּי יוֹסִי, כַּמָּה חַדֵּינָא דַּחֲמֵינָא אַנְפֵּי שְׁכִינְתָּא, דְּהַשְׁתָּא בְּכָל אָרְחָא דָּא, אִצְטָעַרְנָא בַּחֲדָא סָבָא, טַיָּיעָא, דְּהֲוָה שָׁאִיל לִי כָּל אָרְחָא."],[[0,"אדהכי הא סבא וכו':","בתוך כך, הנה זקן ירד אליו, אמר לו, אם כן, רבי, מהו התוספת אל הנשמה שהיא ממנה, שנאמר בה, לא תעשה כל מלאכה אתה ובנך ובתך ועבדך ואמתך וגו'. פירוש, כי אתה ובנך ובתך, פירושו נשמה רוח נפש דאצילות, ועבדך ואמתך ובהמתך, פירושו נשמה רוח נפש דבריאה יצירה עשיה. הרי שאפילו בנשמה דבריאה, ששם מטטרון נאמר בה לא תעשה כל מלאכה, ויש בה ג\"כ תוספת הזה שאין בה שעבוד, כמו נשמה דאצילות."],[1,"א\"ל סבא סבא וכו':","אמר לו ר\"ש, סבא סבא ואתה שואל זה, כי ודאי על נשמה של צדיק נאמר, שהיא מאצילות, שאע\"פ שנתחייב לרדת בגלגול בכל אלו, דהיינו אפילו בעבד ואמה, ובבהמות שהם אופנים, דהיינו בעולם עשיה, או בכל חיות שמהן הנשמות של בני אדם, כתוב בה לא תעשה כל מלאכה. כלומר שעצם הנשמה היא מאצילות, אלא שנתחייבה להתגלגל בעבד ואמה ובהמה, אז דינה שאין בה מלאכה ושעבוד. אבל אם עצם הנשמה נמשכת מבי\"ע אז יש בה מלאכה ושעבוד. וזה שכתוב לא תעבוד בו עבודת עבד, דהיינו בצדיק שהוא יום השבת לא תעבוד בו עבודת עבד, שהוא מטטרון, שהוא יום החול."],[2,"אבל סבא סבא וכו':","אבל, זקן זקן, שבת, שהיא בת יחידה, דהיינו מלכות, והיא בת זוגו של הצדיק, שהוא ג\"כ שבת, דהיינו כמו שביאר בכתוב, ובשביעית יצא לחפשי חנם. א\"כ מהו שכתוב בו, אם אחרת יקח לו. אמר לו זהו ודאי ההבדל, שהיא חולו של שבת, ועליו נאמר אם אחרת יקח לו. כי יש חול אחר שאינו נקרא חולו של שבת, אלא של טמאה שפחה. א\"ל, וחולו של שבת מה הוא. אמר לו, זה הוא אמה שבבריאה, שהיא גוף של בת יחידה, שהבת יחידה, שהיא מלכות דאצילות, מתלבשת בה כמו נשמה בגוף. שעליה נאמר, אם אחרת יקח לו."],[3,"תא חזי נשמתא וכו':","בוא וראה, יש נשמה שנקראת אמה, ויש נשמה שנקראת שפחה ויש נשמה שנקראת בת מלך, כי כל אחת נקראת על שם המקום שנמשכה משם, או שנתגלגלה שמה. וכאן יש איש, דהיינו ואיש אשר ימכור את בתו לאמה, שנאמר בו, ה' איש מלחמה, דהיינו ז\"א דאצילות ויש איש, שנאמר בו, והאיש גבריאל, שהוא בעולם הבריאה. והיינו שכתוב, וכי ימכור \u0003איש,\u0004 שהוא הקב\"ה, את \u0003בתו,\u0004 היינו נשמה דאצילות הנקראת \u0003בת\u0004 יחידה \u0003לאמה,\u0004 שתתגלגל בעולם הבריאה, ששם בחינת גוף השכינה שנקרא אמה."],[4,"ובגין דא נשמתא וכו':","ומשום זה, נשמה שנתחייבה בגלגול, אם היא בת הקב\"ה, דהיינו שנמשכה ממלכות דאצילות, אל תאמר שנמכר בגוף נכרי של קליפה, ששם שליטת היצר הרע שהוא מצד סמאל, חס ושלום לומר כן, כי כתוב, אני ה' הוא שמי וכבודי לאחר לא אתן, שהוא יצר הרע. כי אם הנשמה היא מאצילות אע\"פ שנתגלגלה לעולם הבריאה אין בה מלאכה ואין בה שעבוד לקליפות כנ\"ל."],[5,"וההוא גופא דשריא וכו':","וגוף ההוא, שבו שורה בת מלך, שנקרא אמה, אם תאמר שנמכר בכתרים התחתונים של הטומאה, חס וחלילה. עליה נאמר, והארץ לא תמכר לצמיתות כי לי הארץ. מי הוא גוף של בת מלך, זה הוא מטטרון, וגוף ההוא הוא אמה של השכינה, שהשכינה מתלבשת בו ואע\"פ שהיא נשמה של בת מלך השבויה שם, היא באה שמה בגלגול. מה כתוב בה, וכי ימכור איש וגו'."],[6,"ועוד, וכי ימכור איש:","זה הקב\"ה. \u0003את בתו,\u0004 אלו ישראל, שהם מצד הבת יחידה, דהיינו ממה שנמשכו מן המלכות נקראים בתו. ואם תאמר שיצאו לעתיד כמו אלו שיצאו ממצרים שהיו מצד \u0003העבד,\u0004 שהוא מטטרון, שהם יצאו במנוסה ממצרים, על זה נאמר, לא תצא כצאת ה \u0003עבדים,\u0004 וז\"ש, כי לא בחפזון תצאו ובמנוסה לא תלכון. כמו שהיה ביציאה מצד העבד מטטרון."],[7,"תא חזי ב\"נ וכו':","בוא וראה אדם כשנולד, נותנים לו \u0003נפש\u0004 מצד הבהמה מצד הטהרה, מצד אלו שנקראו אופני הקודש. דהיינו מעולם העשיה. זכה יותר, נותנים לו \u0003רוח\u0004 מצד חיות הקודש. דהיינו מעולם היצירה. זכה יותר נותנים לו \u0003נשמה\u0004 מצד הכסא, דהיינו מעולם הבריאה. ושלשה אלו, הם אמה עבד ושפחה של הבת מלך. דהיינו נשמה רוח ונפש מהתפשטות המלכות בבי\"ע. אמה, היא נשמה שבבריאה. עבד, הוא רוח שביצירה. שפחה, היא נפש שבעשיה."],[8,"זכה יתיר יהבין וכו':","זכה יותר, נותנים לו \u0003נפש\u0004 בדרך אצילות, מצד הבת יחידה שנקראת בת מלך, דהיינו המלכות דאצילות. זכה יותר, נותנים לו רוח דאצילות מצד עמוד האמצעי שהוא ז\"א, ונקרא בן אל הקב\"ה, ז\"ש, בנים אתם לה' אלקיכם. זכה יותר נותנים לו נשמה מצד או\"א, שהם בינה. ז\"ש ויפח באפיו נשמת חיים. מהו חיים, אלא הם \u0003י\"ה\u0004 שהוא או\"א, שעליהם נאמר, כל הנשמה תהלל יה, ונשלם בהם השם הויה. כי רוח ונפש דאצילות הם \u0003ו\"ה\u0004 ונשמה דאצילות הוא \u0003י\"ה\u0004 שביחד הם, \u0003הוי\"ה.\u0004"],[9,"זכה יתיר יהבין וכו':","זכה יותר נותנים לו הוי\"ה במילוי האותיות, כזה, \u0003יוד הא ואו הא.\u0004 שהוא סוד אדם, שבגמטריא מ\"ה, בדרך אצילות של מעלה, דהיינו ז\"א בשעה שמלביש או\"א עלאין שה\"ס חכמה, שהיא אותיות כ\"ח מ\"ה. ונקרא בצורת אדונו. ועליו נאמר ורדו בדגת הים וגו'. וזה הוא ששליטתו בכל הרקיעים ובכל האופנים והשרפים וחיות ובכל צבאות וכחות של מעלה ומטה. ומשום זה כשהאדם זכה בנפש מצד הבת יחידה. נאמר בו לא תצא כצאת העבדים."],[10,"ר\"ח ור' יוסי וכו':","רבי חייא ור\"י נפגשו בלילה אחד במגדל של צור. התארחו שם, ושמחו זה בזה. א\"ר יוסי, כמה אני שמח שראיתי פני השכינה, כי עתה בכל הדרך הזה, נצטערתי בזקן אחד סוחר, שהיה שואל אותי בכל הדרך."]],[[0,"","בֵּין כָּךְ יָרַד הַזָּקֵן אֵלָיו, אָמַר לוֹ, אִם כָּךְ רַבִּי, מַה תּוֹסֶפֶת לַנְּשָׁמָה שֶׁהִיא מִמֶּנָּה, שֶׁנֶּאֱמַר בָּהּ (שמות כ) לֹא תַעֲשֶׂה כָל מְלָאכָה אַתָּה וּבִנְךְ וּבִתֶּךְ עַבְדְּךְ וְגוֹ'?"],[1,"","אָמַר לוֹ, זָקֵן זָקֵן, וְאַתָּה שׁוֹאֵל אֶת זֶה? שֶׁוַּדַּאי זֶה נֶאֱמַר עַל נִשְׁמַת הַצַּדִּיק, שֶׁאַף עַל גַּב שֶׁהִתְחַיֵּב לָרֶדֶת בְּגִלְגּוּל בְּכָל אֵלֶּה, אֲפִלּוּ בְּעֶבֶד וְאָמָה, וּבְהֵמוֹת שֶׁהֵם אוֹפַנִּים, אוֹ בְכָל הַחַיּוֹת שֶׁמֵּהֶם נִשְׁמוֹת בְּנֵי אָדָם, כָּתוּב בָּהּ לֹא תַעֲשֶׂה כָל מְלָאכָה, וְזֶהוּ (ויקרא כה) לא תעבד בו עבדת עבד. בצדיק, שהוא יום השבת, לא תעבד בו עבדת עבד, שהוא יום של חל."],[2,"","אֲבָל זָקֵן זָקֵן, שַׁבָּת (הגשמה) שֶׁהִיא בַּת יְחִידָה, וְהִיא בַּת זוּגוֹ שֶׁל צַדִּיק שֶׁהוּא שַׁבָּת. מַה זֶּה אִם אַחֶרֶת יִקַּח לוֹ? אָמַר לוֹ, הֲרֵי וַדַּאי הַבְדָּלָה חֻלּוֹ שֶׁל שַׁבָּת, שֶׁיֵּשׁ אַחֵר שֶׁלֹּא נִקְרָא חֻלּוֹ שֶׁל שַׁבָּת, אֶלָּא חֻלּוֹ שֶׁל טֻמְאָה שִׁפְחָה. אָמַר לוֹ, וַהֲרֵי חֻלּוֹ שֶׁל שַׁבָּת מַה זֶּה? אָמַר לוֹ, זוֹ אָמָה, שֶׁהִיא גּוּף שֶׁל בַּת יְחִידָה, שֶׁעָלֶיהָ נֶאֱמַר אִם אַחֶרֶת יִקַּח לוֹ."],[3,"","בֹּא וּרְאֵה, נְשָׁמָה יֵשׁ שֶׁנִּקְרֵאת אָמָה, וְיֵשׁ (נשמה) שְׁכִינָה שֶׁנִּקְרֵאת שִׁפְחָה, (ונשמה) וּשְׁכִינָה יֵשׁ שֶׁנִּקְרֵאת בַּת הַמֶּלֶךְ. כָּאן יֵשׁ אִישׁ שֶׁנֶּאֱמַר בּוֹ (שמות טו) ה' אִישׁ מִלְחָמָה. וְיֵשׁ אִישׁ שֶׁנֶּאֱמַר בּוֹ (דניאל ט) וְהָאִישׁ גַּבְרִיאֵל."],[4,"","וְלָכֵן, נְשָׁמָה שֶׁמְּחֻיֶּבֶת בְּגִלְגּוּל, אִם הִיא בִּתּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, אִם תֹּאמַר שֶׁתִּמָּכֵר לְגוּף נָכְרִי שֶׁשָּׁם שִׁלְטוֹן יֵצֶר הָרָע שֶׁהוּא מִצַּד סָמָאֵ\"ל - חַס וְשָׁלוֹם, שֶׁהֲרֵי כָּתוּב (ישעיה מב) אֲנִי ה' הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן, שֶׁהוּא יֵצֶר הָרָע."],[5,"","וְאוֹתוֹ הַגּוּף שֶׁשָּׁם שׁוֹרָה בַּת הַמֶּלֶךְ, אִם תֹּאמַר שֶׁנִּמְכָּר בִּכְתָרִים תַּחְתּוֹנִים שֶׁנִּטְמְאוּ - חָלִילָה וְחַס. עָלָיו נֶאֱמַר (ויקרא כה) וְהָאָרֶץ לֹא תִמָּכֵר לִצְמִתֻת כִּי לִי הָאָרֶץ. מִי גוּף שֶׁל בַּת הַמֶּלֶךְ? זֶה מטטרו\"ן, וְגוּף זֶה הוּא אָמָה שֶׁל הַשְּׁכִינָה, אַף עַל גַּב שֶׁהִיא נְשָׁמָה שֶׁהִיא בַּת הַמֶּלֶךְ, שְׁבוּיָה שָׁם, בְּגִלְגּוּל בָּאָה, שֶׁבָּאִים גִּלְגּוּלִים מִשּׁוּם שֶׁבָּאָה שָׁם. מַה כָּתוּב בָּהּ? וְכִי יִמְכֹּר אִישׁ אֶת בִּתּוֹ לְאָמָה לֹא תֵצֵא כְּצֵאת הָעֲבָדִים."],[6,"","וְעוֹד, וְכִי יִמְכֹּר אִישׁ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. אֶת בִּתּוֹ - אֵלּוּ יִשְׂרָאֵל, שֶׁהֵם מִצַּד שֶׁל בַּת יְחִידָה נִקְרְאוּ בִּתּוֹ. וְאִם תֹּאמַר שֶׁיֵּצְאוּ, כְּמוֹ שֶׁאֵלֶּה מִצַּד שֶׁל הָעֶבֶד שֶׁהוּא מטטרו\"ן, שֶׁיָּצְאוּ בִּמְנוּסָה מִמִּצְרַיִם, לֹא תֵצֵא כְּצֵאת הָעֲבָדִים. זֶהוּ שֶׁכָּתוּב (ישעיה נב) כִּי לֹא בְחִפָּזוֹן תֵּצֵאוּ וּבִמְנוּסָה לֹא תֵלֵכוּן."],[7,"","בֹּא וּרְאֵה, כְּשֶׁנּוֹלָד אִישׁ, נוֹתְנִים לוֹ נֶפֶשׁ מִצַּד הַבְּהֵמָה מִצַּד שֶׁל טֹהַר, מִצַּד אֵלֶּה שֶׁנִּקְרָאִים אוֹפַנֵּי הַקֹּדֶשׁ. זָכָה יוֹתֵר - נוֹתְנִים לוּ רוּחַ מִצַּד שֶׁל חַיּוֹת הַקֹּדֶשׁ. זָכָה יוֹתֵר - נוֹתְנִים לוֹ נְשָׁמָה מִצַּד שֶׁל הַכִּסֵּא. וּשְׁלֹשֶׁת אֵלּוּ הֵם אָמָה, עֶבֶד וְשִׁפְחָה שֶׁל בַּת הַמֶּלֶךְ."],[8,"","אִם זָכָה יוֹתֵר - נוֹתְנִים לוֹ נֶפֶשׁ בְּדֶרֶךְ אֲצִילוּת, מִצַּד שֶׁל בַּת יְחִידָה, וְנִקְרֵאת בַּת מֶלֶךְ. זָכָה יוֹתֵר - נוֹתְנִים לוֹ רוּחַ שֶׁל אֲצִילוּת מִצַּד הָעַמּוּד הָאֶמְצָעִי, וְנִקְרָא בֵּן לַקָּדוֹשׁ-בָּרוּךְ-הוּא. זֶהוּ שֶׁכָּתוּב (דברים יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. זָכָה יוֹתֵר - נוֹתְנִים לוֹ נְשָׁמָה מִצַּד שֶׁל אַבָּא וְאִמָּא. זֶהוּ שֶׁכָּתוּב (בראשיתב) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים. אֵיזֶה חַיִּים? אֶלָּא אוֹתָם י\"ה שֶׁעֲלֵיהֶם נֶאֱמַר (תהלים קנ) כָּל הַנְּשָׁמָה תְּהַלֵּל יָהּ, וְנִשְׁלְמָה בָּהּ יהו\"ה."],[9,"","זָכָה יוֹתֵר - נוֹתְנִים לוֹ יהו\"ה בִּשְׁלֵמוּת הָאוֹתִיּוֹת - יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, שֶׁהוּא אָדָם, בְּאֹרַח אֲצִילוּת לְמַעְלָה. וְנִקְרָא בִּדְמוּת רִבּוֹנוֹ. וְעָלָיו נֶאֱמַר (בראשית א) וּרְדוּ בִּדְגַת הַיָּם וְגוֹ'. וְזֶהוּ שִׁלְטוֹנוֹ בְּכָל הָרְקִיעִים וּבְכָל הָאוֹפַנִּים וְהַשְּׂרָפִים וְהַחַיוֹת וּבְכָל הַחֲיָלוֹת וְהַכֹּחוֹת שֶׁלְּמַעְלָה וּלְמַטָּה. וְלָכֵן, כְּשֶׁבֶּן אָדָם זוֹכֶה בְּנֶפֶשׁ מִצַּד שֶׁל בַּת יְחִידָה, נֶאֱמַר בּוֹ לֹא תֵצֵא כְּצֵאת הָעֲבָדִים."],[10,"","רַבִּי חִיָּיא וְרַבִּי יוֹסֵי נִפְגְּשׁוּ לַיְלָה אֶחָד בְּמִגְדַּל צוֹר. הִתְאָרְחוּ שָׁם וְשָׂמְחוּ זֶה בָּזֶה. אָמַר רַבִּי יוֹסֵי, כַּמָּה שָׂמַחְתִּי שֶׁרָאִיתִי פְּנֵי הַשְּׁכִינָה, שֶׁעַכְשָׁו בְּכָל הַדֶּרֶךְ הַזֹּאת הִצְטַעַרְתִּי בְּזָקֵן אֶחָד סוֹחֵר שֶׁהָיָה שׁוֹאֵל אוֹתִי כָּל הַדֶּרֶךְ:"]]],[["מַאן הוּא נְחָשָׁא, דְּפָרַח בַּאֲוִירָא, וְאָזִיל בְּפִרוּדָא, וּבֵין כַּךְ וּבֵין כַּךְ, אִית נַיְיחָא לְחַד נְמָלָה, דְּשָׁכִיב בֵּין שִׁנּוֹי. שָׁרֵי בְּחִבּוּרָא וְסִיֵּים בְּפִרוּדָא. וּמַאי אִיהוּ נִשְׁרָא, דְּקָא מְקַנְּנָא, בְּאִילָן דְּלָא הֲוָה. בְּנוֹי דְּאִתְגְּזָלוּ, וְלָאו מִן בִּרְיָין. דְּאִתְבְּרִיאוּ בַּאֲתָר דְּלָא אִתְבְּרִיאוּ. כַּד סַלְּקִין נַחְתִּין, כַּד נַחְתִּין סַלְּקִין. תְּרֵין דְּאִינּוּן חַד, וְחַד דְּאִינּוּן תְּלָתָא. מַהוּ עוּלֵימְתָּא שַׁפִּירְתָּא, וְלֵית לָהּ עֵיינִין, וְגוּפָא טְמִירְתָּא וְאִתְגַּלְיָא, אִיהִי נַפְקַת בְּצַפְרָא, וְאִתְכַּסִּיאַת בִּימָמָא. אִתְקַשְׁטַת בְּקִשּׁוּטִין דְּלָא הָווֹ.","כָּל דָּא שָׁאִיל בְּאָרְחָא, וְאִצְטָעַרְנָא. וְהַשְׁתָּא אִית לִי נַיְיחָא. דְּאִילּוּ הֲוֵינָא כַּחֲדָא, אִתְעֲסַקְנָא בְּמִלֵּי דְּאוֹרַיְיתָא, מַה דַּהֲוֵינָן בְּמִלִּין אַחֲרָנִין דְּתֹהוּ. אָמַר רַבִּי חִיָּיא, וְהַהוּא סָבָא טַיָּיעָא, יַדְעַת בֵּיהּ כְּלוּם. אָמַר לֵיהּ, יָדַעְנָא, דְּלֵית מַמָּשׁוּ בְּמִלּוֹי. דְּאִילּוּ הֲוָה יָדַע, יִפְתָּח בְּאוֹרַיְיתָא, וְלָא הֲוָה אָרְחָא בְּרֵיקָנַיָּיא. אָמַר רַבִּי חִיָּיא, וְהַהוּא טַיָּיעָא אִית הָכָא, דְּהָא לְזִמְנִין בְּאִינּוּן רֵיקָנִין, יִשְׁכַּח גְּבָר זַגִּין דְּדַהֲבָא. אָמַר לֵיהּ, הָא הָכָא אִיהוּ, וְאַתְקִין חֲמָרֵיהּ בְּמֵיכְלָא.","קָרוּ לֵיהּ, וְאָתָא לְקָמַיְיהוּ. אָמַר לוֹן, הַשְׁתָּא תְּרֵין אִינּוּן תְּלַת, וּתְלַת אִינּוּן כְּחַד. אָמַר רַבִּי יוֹסִי, לָא אֲמֵינָא לָךְ, דְּכָל מִלּוֹי רֵיקָנִין, וְאִינּוּן בְּרֵיקָנַיָּיא, יָתִיב קָמַיְיהוּ.","אָמַר לוֹן רַבָּנָן, אֲנָא טַיָּיעָא אִתְעַבִידְנָא, וּמִיּוֹמִין זְעִירִין, דְּהָא בְּקַדְמִיתָא לָא הֲוֵינָא טַיָּיעָא, אֲבָל בְּרָא חַד זְעִירָא אִית לִי, וְיָהֲבִית לֵיהּ בְּבֵי סִפְרָא, וּבָעֵינָא דְּיִשְׁתָּדַּל בְּאוֹרַיְיתָא. וְכַד אֲנָא אַשְׁכַּחְנָא חַד מֵרַבָּנָן דְּאָזִיל בְּאָרְחָא, אֲנָא טָעִין אֲבַתְרֵיהּ, וְהַאי יוֹמָא, חֲשִׁיבְנָא דְּאֶשְׁמַע מִלִּין חַדְתִּין בְּאוֹרַיְיתָא, וְלָא שְׁמַעְנָא מִדִי.","אָמַר ר' יוֹסִי, בְּכָל מִלִּין דְּשָׁמַעְנָא דְּקָאַמָרְתּ, לָא תַּוָוהְנָא, אֶלָּא מֵחַד. אוֹ אַנְתְּ בִּשְׁטּוּתָא אָמַרְת, אוֹ מִלִּין רֵיקָנִין אִינּוּן. אָמַר הַהוּא סָבָא, וּמַאן אִיהִי. אָמַר עוּלֵימְתָּא שַׁפִּירְתָּא וְכוּ'.","פָּתַח הַהוּא סָבָא וְאָמַר, (תהילים קי״ח:ו׳-ז׳) יְיָ' לִי לא אִירָא מַה יַּעֲשֶׂה לִי אָדָם. יְיָ' לִי בְּעֹזְרָי וְגוֹ'. טוֹב לַחֲסוֹת בַּיְיָ' וְגוֹ'. כָּמָּה טָבִין וּנְעִימִין וְיַקִּירִין וְעִלָּאִין מִלִּין דְּאוֹרַיְיתָא, וַאֲנָא הֵיכִי אֵימָא קָמֵי רַבָּנָן, דְּלָא שְׁמַעְנָא מִפּוּמַיְיהוּ עַד הַשְׁתָּא, אֲפִילּוּ מִלָּה חֲדָא. אֲבָל אִית לִי לְמֵימָר, דְּהָא לֵית כִּסּוּפָא כְּלָל לְמֵימָר מִלֵּי דְּאוֹרַיְיתָא קָמֵי כֹּלָּא.","אִתְעַטָּף הַהוּא סָבָא, פָּתַח וְאָמַר, (ויקרא כ״ב:י״ב) וּבַת כֹּהֵן כִּי תִהְיֶה לְאִישׁ זָר הִיא בִּתְרוּמַת הַקֳּדָשִׁים לא תֹאכֵל. הַאי קְרָא, אַקְרָא אַחֲרָא סָמִיךְ, (ויקרא כ״ב:י״ג) וּבַת כֹּהֵן כִּי תִהְיֶה אַלְמָנָה וּגְרוּשָׁה וְזֶרַע אֵין לָהּ וְשָׁבָה אֶל בֵּית אָבִיהָ כִּנְעוּרֶיהָ מִלֶּחֶם אָבִיהָ תֹּאכֵל וְכָל זָר לא יֹאכַל בּוֹ. הָנֵי קְרָאֵי כְּמַשְׁמָעָן. אֲבָל מִלִּין דְּאוֹרַיְיתָא מִלִּין סְתִימִין אִינּוּן","וְכַמָּה אִינּוּן מִלִּין דְּחָכְמְתָא דִּסְתִּימִין בְּכָל מִלָּה וּמִלָּה דְּאוֹרַיְיתָא, וְאִשְׁתְּמוֹדְעָן, אִינּוּן לְגַבֵּי חַכִּימִין, דְּיַדְעִין אָרְחִין דְּאוֹרַיְיתָא. דְּהָא אוֹרַיְיתָא לָאו מִלִּין דְּחֶלְמָא אִינּוּן, דְּקָא אִתְמָסְרָן לְמַאן דְּפָשַׁר לוֹן, וְאִתְמַשְּׁכָן בָּתַר פּוּמָא, וְעִם כָּל דָּא אִצְטְרִיכוּ לְמִפְשַׁר לוֹן לְפוּם אָרְחוֹי. וּמַה אִי מִלִּין דְּחֶלְמָא אִצְטְרִיכוּ לְמִפְשַׁר לוֹן לְפוּם אָרְחוֹי, מִלִּין דְּאוֹרַיְיתָא דְּאִינּוּן שַׁעֲשׁוּעִין דְּמַלְכָּא קַדִּישָׁא, עַל אַחַת כַּמָּה וְכַמָּה דְּאִצְטְרִיכוּ לְמֵהָךְ בְּאֹרַח קְשׁוֹט בְּהוּ, דִּכְתִּיב, (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי יְיָ' וְגוֹ'.","הַשְׁתָּא אִית לְמֵימָר, וּבַת כֹּהֵן, דָּא נִשְׁמְתָא עִלָּאָה, בְּרַתֵיהּ דְּאַבְרָהָם אָבִינוּ קַדְמָאָה לַגִּיּוֹרִין, וְאִיהוּ מָשִׁיךְ, לָהּ לְהַאי נִשְׁמְתָא מֵאֲתָר עִלָּאָה. מַה בֵּין קְרָא דְּאָמַר וּבַת אִישׁ כֹּהֵן, וּבֵין קְרָא דְּאָמַר וּבַת כֹּהֵן, וְלָא כְּתִיב אִישׁ. אֶלָּא, אִית כֹּהֵן דְּאִקְרֵי אִישׁ כֹּהֵן, וְלֹא כֹּהֵן מַמָּשׁ. וְעַל אָרְחָא דָּא, הֲוָה (איש) כֹּהֵן, וַהֲוָה סְגָן, וַהֲוָה כֹּהֵן גָּדוֹל, וַהֲוָה כֹּהֵן דְּלָאו אִיהוּ גָּדוֹל. כֹּהֵן סְתָם, רַב וְעִלָּאָה יַתִּיר מֵאִישׁ כֹּהֵן. וְעַל דָּא אִית נִשְׁמְתָא, וְאִית רוּחָא, וְאִית נֶפֶשׁ."],[[0,"מאן הוא נחשא וכו':","שהיה שואל אותי מי הוא נחש הפורח באויר והולך בפירוד, ובין כך ובין כך יש מנוחה לנמלה אחת השוכבת בין שניו. מתחיל בחבור, ומסיים בפירוד. ומי הוא, נשר המקנן באילן שלא היה. בניו שנגזלו אינם מן הבריות, כי נבראו במקום שלא נבראו. כשעולים יורדים, וכשיורדים עולים. שנים שהם אחד ואחד שהם שלשה. מהו עלמה יפה שאין לה עינים, והגוף נסתר ונגלה, היא יוצאת בבקר ומתכסית ביום. מתקשטת בקישוטין שלא היו."],[0,"","פנימיות הדברים. המוחין דשמאל המתגלים ע\"י יציאת י' מאויר בסוד נקודת השורק (כנ\"ל בראשית א' דף ט\"ו ד\"ה ההוא ע\"ש) מכונים \u0003שפורחים באויר\u0004 (עי' בראשית א' דף מ\"ה ד\"ה כד) ואז המלכות בלי זווג עם ז\"א. ואז יש יניקה לס\"א, כל עוד היותם בלי ימין, והנחש יונק מהקדושה, וז\"ש, \u0003נחשא דפרח באוירא.\u0004 וכשבא קו האמצעי וע\"י המסך דנקודת החירק, ממעט את השמאל שלא יאיר ממעלה למטה אלא ממטה למעלה לבד, שעי\"ז מחברו עם הימין, (כנ\"ל בראשית א' דף ס' ד\"ה מחלוקת) אז נפרד הנחש מן הקדושה, כי אין לו עוד מה לינק. וז\"ש \u0003ואזיל בפרודא.\u0004"],[0,"","והדינים האלו דמסך דחירק, הדוחים את הנחש מלינק מקו שמאל, הם מדינים דצמצום ב', שבאו מכח עלית המסך לבינה. ונאחז הנחש בדינים אלו. והארם שבין שיני הנחש שבו ממית בני אדם הוא מדינים דצמצום א', שהם ממלכות לבד. והארס הזה מכונה נמלה. וז\"ש, \u0003ובין כך ובין כך, אית נייחא לחד נמלה דשכיב בין שנוי.\u0004 כי בעת שיש כח לנחש להתאחז בדינים דצמצום ב', העולים עד הבינה, הוא עוזב את הדינים דצמצום א' שאינם אלא במלכות. וע\"כ יש מנוחה לאותה הנמלה ששוכבת בין שיניו, שהיא מדינים דצמצום א'."],[0,"","וכשהמלכות היא בזווג עם ז\"א ומאיר בה קו השמאל. אם הנחש מתקרב אז לינק מהשמאל, תכף נפרד הזווג ואין לו מה לינק. וז\"ש \u0003שרי בחבורא,\u0004 שמתחל לינק מחבור ז\"א עם הנוקבא, \u0003וסיים בפרודא,\u0004 שתיכף נפרד הזווג."],[0,"","ונודע שהבינה הנקראת \u0003נשר,\u0004 אין בה שום דין כלל, אלא שהוא רחמני על בניו, שהם זו\"ן, ומקבלת אליה את הדינים של המלכות, שמתמעטת עי\"ז לו\"ק, כדי להשפיע מוחין לזו\"ן. כי לעת גדלות חוזרים ויורדים הדינים מן הבינה למקומם למלכות והבינה חוזרת לג\"ר ומשפעת מוחין לזו\"ן. (כנ\"ל בראשית א' ד\"ה וכבר ע\"ש)."],[0,"","וז\"ס, \u0003נשרא דקא מקננא באילן דלא הוה,\u0004 המוחין דו\"ק מכונים אילן, שהנשר שהוא בינה מקנן שם מחמת שקיבלה הדינים של המלכות, אבל אילן הזה הוא כמו שלא היה. כי אח\"כ לעת גדלות יורדים הדינים מבינה, ונגלה הדבר למפרע שלא היה שום דין בבינה."],[0,"","והנה כשישראל בגלות, נגזלו הבנים, שהם זו\"ן מן האם, שהיא בינה, כלומר שהס\"א יונקת מדינים שבזו\"ן. אמנם הדינים ההם באים מן הבינה מעת שהיא בקטנות מחמת עלית המלכות אליה, וכיון שהדינים דבינה הם באילן דלא הוו, מכ\"ש הדינים שבזו\"ן המקובלים ממנה. שהם כלא היו. ואלו הדינים הנמשכים מן הבינה מכונים ברא, או בריאה (כנ\"ל בראשית א' דף י' ד\"ה בהאי)."],[0,"","וז\"ש, \u0003בנוי דאתגזלו,\u0004 שהס\"א יונקת מן הדינים שבהם, שבכח זה גוזלים את השפע, בעת הגלות, ולאו מן בריין ואינם מן הבריות, כלומר, שאין בהם הדינים דבריאה, משום, \u0003דאתבריאו באתר דלא אתבריאו\u0004 כי מה שנבראו בדינים דבינה, בסוד בראשית ברא, (כמ\"ש שם) הוא במקום שלא נבראו, כלומר שהמקום עצמו שהיא בינה אינה בחינת בריאה, כי הדינים שבה הם באילן דלא הוה, מכ\"ש זו\"ן המקבלים ממנה. ונמצא כל אחיזת הס\"א בזו\"ן בזמן הגלות הוא שלא בצדק."],[0,"","ונודע, כשקו אמצעי מכריע בין ימין ושמאל, מתקן את השמאל שיאיר רק ממטה למעלה, והימין ממעלה למטה, (כנ\"ל ב\"א דף ס' ד\"ה מחלוקת) וז\"ש \u0003כד סלקין נחתין,\u0004 שהארות הימין שמקודם לכן היו מאירים בעליה ממטה למעלה, שהיו בבחינת ו\"ק, מאירים עתה בירידה ממעלה למטה. \u0003וכד נחתין סלקין,\u0004 והארות השמאל שהיו מאירים מקודם לכן ממעלה למטה בירידה, מאירים עתה בדרך עליה ממטה למעלה. \u0003תרין דאינון חד,\u0004 שעי\"ז נעשו ב' הקוים ימין ושמאל לאחד. \u0003וחד דאינון תלתא,\u0004 שקו האמצעי שהוא אחד, יורש כל ג' הקוין ונעשה שלשה. ומ\"ש הסבא להלן (באות קט\"ז) ודא הוא חד דאינון תרין, אמר זה בדרך אגב, כמו שאומר כאן (באות י\"ז) השתא תרין אינון תלת ותלת אינון כחד. שהוא בדרך אגב."],[0,"","והנה המלכות אחר שנתמעטה וירדה לבחינת מחזה ולמטה דז\"א, אין לה עוד חכמה מעצמה, וז\"ש \u0003עולימתא שפירתא ולית לה עיינין.\u0004 כי החכמה נקראת עינים. והחכמה שיש לה היא מקבלת מז\"א \u0003וגופא טמירתא ואתגליא,\u0004 שפעם היא מכוסה מהארת חכמה, ופעם מגולה בה החכמה. ומפרש \u0003איהי נפקת בצפרא,\u0004 שיוצאת להאיר בחכמה בזווג דקדרותא דצפרא, \u0003ואתכסיאת ביממא,\u0004 ביום היא בשליטת ז\"א, והחכמה מתכסה בה, כמו בז\"א. \u0003אתקשטת בקשוטין דלא הוה,\u0004 שהקישוטין נמשכים לה מדינים וקטנות דבינה, (כנ\"ל בהקסה\"ז דף כ' ד\"ה וזה אמרו) וכיון שהדינים דבינה הם באילן דלא הוה, כנ\"ל, הרי גם הקישוטים ההם בבחינת דלא הוו."],[1,"כל דא שאיל וכו':","כל זה שאל בדרך, ונצטערתי, ועתה יש לי נחת. ואלו היינו יחד היינו עוסקים בדברי תורה, מה שהייתי בדברים אחרים של תהו. אמר ר' חייא, וסוחר הזקן ההוא, כלום אתה יודע אותו. אמר לו יודע אני שאין תכן בדבריו, שאלו היה יודע היה פותח בתורה והדרך לא היה בריק. אמר ר' חייא, והסוחר ההוא יש כאן, כי לפעמים באלו הריקים, ימצא אדם זגים של זהב, כלומר ענבל של זהב. אמר לו הוא כאן, ומתקן את חמורו באכילה."],[2,"קרו ליה ואתא וכו':","קראו אותו, ובא לפניהם. אמר להם עתה, שנים הם שלשה, כי אחד שנתחבר עמהם נעשו שלשה. ושלשה הם כאחד. דהיינו שנתחברו יחד. אמר ר' יוסי לא אמרתי לך שכל דבריו ריקים והם לריק. ישב לפניהם."],[3,"אמר לון רבנן וכו':","אמר להם, רבנן. אני, הנה נעשיתי סוחר, ומימים מועטים, כי בתחילה לא הייתי סוחר, אבל בן אחד קטן היה לי, ונתתי אותו בבית הספר, ורציתי שיעסוק בתורה, לכן נעשיתי סוחר, כדי שאוכל לסעדו. וכשאני מוצא אחד מן הרבנים ההולך בדרך אני מחמר אחריו. וביום הזה חשבתי שאשמע דברים חדשים בתורה, ולא שמעתי כלום."],[4,"אמר ר' יוסי וכו':","אר\"י, בכל הדברים ששמעתי, שאמרת, לא נפלאתי אלא מאחד, או אתה בסכלות אמרת, או דברים ריקים הם. אמר זקן ההוא ומה הוא. אמר ר\"י עלמה יפה ואין לה עינים וכו'."],[5,"פתח ההוא סבא וכו':","פתח זקן ההוא ואמר, ה' לי לא אירא מה יעשה לי אדם. ה' לי בעזרי וגו'. טוב לחסות בה' וגו'. כמה טובים ונעימים ויקרים ועליונים דברי תורה, ואני איך אומר לפני רבנן שלא שמעתי מפיהם עד עתה אפילו מלה אחת. אבל יש לי לומר, כי אין בושה כלל לומר דברי תורה לפני הכל."],[6,"אתעטף ההוא סבא וכו':","נתעטף אותו הזקן, פתח ואמר, ובת כהן כי תהיה לאיש זר היא בתרומת הקדשים לא תאכל. מקרא זה נסמך על מקרא אחר, ובת כהן כי תהיה אלמנה וגרושה וזרע אין לה ושבה אל בית אביה כנעוריה מלחם אביה תאכל וגו'. מקראות אלה הם כפשוטם. אבל דברי תורה דברים סתומים המה, שיש סודות לכל דבר ודבר."],[7,"וכמה אלין מלין וכו':","וכמה הם דברי החכמה הסתומים בכל מלה ומלה שבתורה והם נודעים לחכמים היודעים דרכי התורה. כי התורה אינם דברי חלומות, שנמסרו למי שפותר אותם, והולכים אחר הפה של הפותר אותם, ועם כל זה צריכים לפתור אותם לפי דרכיהם. ומה אם דברי חלומות צריכים לפתור אותם לפי דרכיהם, דברי תורה, שהם שעשועים של המלך הקדוש, על אחת כמה וכמה שצריכים ללכת בהם בדרך אמת, שכתוב, כי ישרים דרכי ה' וגו'."],[8,"השתא אית למימר וכו':","עתה יש לומר, \u0003ובת כהן,\u0004 זו היא נשמה עליונה, בתו של אברהם אבינו, הראשון לגרים. שהוא חסד, והוא מושך לנשמה הזו ממקום עליון שהוא בינה. שואל, ומה בין המקרא שאמר ובת איש כהן, ובין המקרא שאמר ובת כהן, ולא כתוב איש. ומשיב, אלא יש כהן שנקרא איש כהן ולא כהן ממש. ועל דרך זה, יש כהן, ויש סגן, ויש כהן גדול, ויש כהן שאינו גדול. כהן סתם גדול ועליון יותר מאיש כהן. וע\"כ יש מדרגות בנשמה, שיש נשמה ויש רוח ויש נפש. שמכהן גדול היא נשמה. ומכהן סתם הוא רוח. ומאיש כהן היא נפש."]],[[0,"","מִי הוּא נָחָשׁ הַפּוֹרֵחַ בָּאֲוִיר וְהוֹלֵךְ בְּפֵרוּד, וּבֵין כָּךְ וּבֵין כָּךְ יֵשׁ מְנוּחָה לִנְמָלָה אַחַת שֶׁשּׁוֹכֶבֶת בֵּין שִׁנָּיו, הִתְחִיל בְּחִבּוּר וְסִיֵּם בְּפֵרוּד? וּמַה הוּא נֶשֶׁר שֶׁמְּקַנֵּן בְּאִילָן שֶׁלֹּא הָיָה? בָּנָיו שֶׁנִּגְזְלוּ, וְלֹא מֵהַבְּרִיּוֹת? שֶׁנִּבְרְאוּ בְמָקוֹם שֶׁלֹּא נִבְרְאוּ? כְּשֶׁעוֹלִים יוֹרְדִים, כְּשֶׁיּוֹרְדִים עוֹלִים? שְׁנַיִם שֶׁהֵם אֶחָד, וְאֶחָד שֶׁהֵם שָׁלֹשׁ? מַה זֶּה עַלְמָה יָפָה וְאֵין לָהּ עֵינַיִם, וְהַגּוּף נִסְתָּר וּמִתְגַּלֶּה? הִיא יוֹצֵאת בַּבֹּקֶר וְנִתְכַּסֵּית בַּיּוֹם, וּמִתְקַשֶּׁטֶת בְּקִשּׁוּטִים שֶׁלֹּא הָיוּ?"],[1,"","כָּל זֶה שָׁאַל בַּדֶּרֶךְ, וְהִצְטַעַרְתִּי. וְעַכְשָׁו יֵשׁ לִי מְנוּחָה. שֶׁאִלּוּ הָיִינוּ כְּאֶחָד, הִתְעַסַּקְנוּ בְּדִבְרֵי תוֹרָה מַה שֶּׁהָיִינוּ בִּדְבָרִים אֲחֵרִים שֶׁל תֹּהוּ. אָמַר רַבִּי חִיָּיא, וְאוֹתוֹ זָקֵן סוֹחֵר יָדַעְתָּ בּוֹ מַשֶּׁהוּ? אָמַר לוֹ, יָדַעְתִּי שֶׁאֵין מַמָּשׁ בִּדְבָרָיו, שֶׁאִלּוּ הָיָה יוֹדֵעַ, יִפְתַּח בַּתּוֹרָה, וְלֹא הָיְתָה הַדֶּרֶךְ בְּרֵיקָנוּת. אָמַר רַבִּי חִיָּיא, וְאוֹתוֹ הַסּוֹחֵר יֶשְׁנוֹ כָּאן, שֶׁהֲרֵי לִפְעָמִים בְּאוֹתָם הָרֵיקָנִים יִמָּצֵא אִישׁ פַּעֲמוֹנֵי זָהָב. אָמַר לוֹ, הֲרֵי הוּא כָּאן, וְהִתְקִין חֲמוֹרוֹ לְמַאֲכָל."],[2,"","קָרְאוּ לוֹ וּבָא לִפְנֵיהֶם. אָמַר לָהֶם, כָּעֵת שְׁנַיִם הֵם שְׁלֹשָׁה, וּשְׁלֹשָׁה הֵם כְּאֶחָד. אָמַר רַבִּי יוֹסֵי, וְלֹא אָמַרְתִּי לְךְ שֶׁכָּל דְּבָרָיו רֵיקָנִים וְהֵם בְּרֵיקָנוּת?! יָשַׁב לִפְנֵיהֶם."],[3,"","אָמַר לָהֶם, רַבּוֹתֵינוּ, אֲנִי נַעֲשֵׂיתִי סוֹחֵר, וְרַק מִלִּפְנֵי מְעַט יָמִים, שֶׁהֲרֵי בַּהַתְחָלָה לֹא הָיִיתִי סוֹחֵר, אֲבָל בֵּן אֶחָד קָטָן יֵשׁ לִי, וְנָתַתִּי אוֹתוֹ לְבֵית הַסֵּפֶר, וַאֲנִי רוֹצֶה שֶׁיַּעֲסֹק בַּתּוֹרָה, וּכְשֶׁאֲנִי מוֹצֵא אֶחָד מֵהָרַבָּנִים שֶׁהוֹלֵךְ בַּדֶּרֶךְ, אֲנִי טוֹעֵן אַחֲרָיו, וְהַיּוֹם הַזֶּה חָשַׁבְתִּי שֶׁאֶשְׁמַע דְּבָרִים חֲדָשִׁים בַּתּוֹרָה, וְלֹא שָׁמַעְתִּי דָבָר."],[4,"","אָמַר רַבִּי יוֹסֵי, בְּכָל הַדְּבָרִים שֶׁשָּׁמַעְתִּי שֶׁאָמַרְתָּ לֹא תָמַהְתִּי, אֶלָּא רַק מֵאֶחָד - אוֹ שֶׁאַתָּה אָמַרְתָּ בִּשְׁטוּת, אוֹ שֶׁהֵם דְּבָרִים רֵיקִים. אָמַר אוֹתוֹ זָקֵן, וּמַה הִיא? אָמַר, נַעֲרָה יָפָה וְכוּ'."],[5,"","פָּתַח אוֹתוֹ זָקֵן וְאָמַר, (תהלים קיח) ה' לִי לֹא אִירָא מַה יַּעֲשֶׂה לִי אָדָם. ה' לִי בְּעֹזְרָי וְגוֹ'. טוֹב לַחֲסוֹת בַּה' וְגוֹ'. כַּמָּה טוֹבִים וּנְעִימִים וְנִכְבָּדִים וְעֶלְיוֹנִים דִּבְרֵי הַתּוֹרָה, וַאֲנִי אֵיךְ אֹמַר לִפְנֵי רַבּוֹתֵינוּ, שֶׁלֹּא שָׁמַעְתִּי מִפִּיהֶם עַד עַכְשָׁו אֲפִלּוּ דָּבָר אֶחָד?! אֲבָל יֵשׁ לִי לוֹמַר, שֶׁאֵין בּוּשָׁה כְּלָל לוֹמַר דִּבְרֵי תוֹרָה לִפְנֵי הַכֹּל."],[6,"","הִתְעַטֵף אוֹתוֹ הַזָּקֵן, פָּתַח וְאָמַר, (ויקרא כב) וּבַת כֹּהֵן כִּי תִהְיֶה לְאִישׁ זָר הִיא בִּתְרוּמַת הַקְּדָשִׁים לֹא תֹאכֵל. פָּסוּק זֶה סָמוּךְ עַל פָּסוּק אַחֵר - (שם) וּבַת כֹּהֵן כִּי תִהְיֶה אַלְמָנָה וּגְרוּשָׁה וְזֶרַע אֵין לָהּ וְשָׁבָה אֶל בֵּית אָבִיהָ כִּנְעוּרֶיהָ מִלֶּחֶם אָבִיהָ תֹּאכֵל וְכָל זָר לֹא יֹאכַל בּוֹ. פְּסוּקִים הַלָּלוּ כְּמַשְׁמָעָם, אֲבָל דִּבְרֵי הַתּוֹרָה הֵם דְּבָרִים סְתוּמִים."],[7,"","וְכַמָּה הֵם דִּבְרֵי חָכְמָה שֶׁסְּתוּמִים בְּכָל דָּבָר וְדָבָר שֶׁבַּתּוֹרָה, וְנוֹדָעִים לְאוֹתָם הַחֲכָמִים שֶׁיּוֹדְעִים דַּרְכֵי הַתּוֹרָה, שֶׁהֲרֵי הַתּוֹרָה אֵינָם דִּבְרֵי חֲלוֹם הֵם, שֶׁנִּמְסְרוּ לְמִי שֶׁפּוֹתֵר אוֹתָם וְנִמְשָׁכִים אַחַר הַפֶּה, וְעִם כָּל זֶה צָרִיךְ לִפְתֹּר אוֹתָם לְפִי דַרְכָּם. וּמָה אִם דִּבְרֵי חֲלוֹם צָרִיךְ לִפְתֹּר אוֹתָם לְפִי דַרְכָּם - דִּבְרֵי הַתּוֹרָה שֶׁהֵם שַׁעֲשׁוּעֵי הַמֶּלֶךְ הַקָּדוֹשׁ עַל אַחַת כַּמָּה וְכַמָּה שֶׁצְּרִיכִים לָלֶכֶת בְּדֶרֶךְ אֱמֶת בָּהֶם, שֶׁכָּתוּב (הושעיד) כִּי יְשָׁרִים דַּרְכֵי ה' וְגוֹ'."],[8,"","עַכְשָׁו יֵשׁ לוֹמַר, וּבַת כֹּהֵן - זוֹ הַנְּשָׁמָה הָעֶלְיוֹנָה, בִּתּוֹ שֶׁל אַבְרָהָם אָבִינוּ רִאשׁוֹן לַגֵּרִים, וְהוּא מוֹשֵׁךְ אֶת אוֹתָהּ נְשָׁמָה מִמָּקוֹם עֶלְיוֹן. מַה בֵּין פָּסוּק שֶׁאָמַר וּבַת אִישׁ כֹּהֵן, וּבֵין פָּסוּק שֶׁאָמַר וּבַת כֹּהֵן, וְלֹא כָתוּב אִישׁ? אֶלָּא יֵשׁ כֹּהֵן שֶׁנִּקְרָא אִישׁ כֹּהֵן, וְלֹא כֹּהֵן מַמָּשׁ. וְעַל הַדֶּרֶךְ הַזֶּה הָיָה (איש) כֹּהֵן, וְהָיָה סְגָן, וְהָיָה כֹּהֵן גָּדוֹל, וְהָיָה כֹּהֵן שֶׁאֵינוֹ גָּדוֹל. כֹּהֵן סְתָם גָּדוֹל וְעֶלְיוֹן מֵאִישׁ כֹּהֵן. וְעַל זֶה יֵשׁ נְשָׁמָה, וְיֵשׁ רוּחַ, וְיֵשׁ נֶפֶשׁ."]]],[["וּבַת כֹּהֵן כִּי תִהְיֶה לְאִישׁ זָר, דָּא נִשְׁמְתָא קַדִּישָׁא, דְּאִתְמַשְּׁכַת מֵאֲתָר עִלָּאָה, וְעָאלַת לְגוֹ סְתִימוּ דְּאִילָנָא דְּחַיֵּי. וְכַד רוּחָא דְּכַהֲנָא עִלָּאָה נָשְׁבָא, וְיָהִיב נִשְׁמָתִין בְּאִילָנָא דָּא, פַּרְחִין מִתַּמָּן אִינּוּן נִשְׁמָתִין, וְעָאלִין בְּאוֹצָר חַד.","וַוי לְעָלְמָא, דְּלָא יַדְעִין בְּנֵי נָשָׁא לְאִסְתַּמְּרָא, דְּקָא מַשְׁכִין מְשִׁיכוּ בַּהֲדֵי יֵצֶר הָרָע, דְּאִיהוּ אִישׁ זָר, וְהַאי בַּת כֹּהֵן פַּרְחַת לְתַתָּא, וְאַשְׁכְּחַת בִּנְיָינָא בְּאִישׁ זָר. וּבְגִין דְּאִיהוּ רְעוּתָא דְּמָרָה, עָאלַת תַּמָּן וְאִתְכַּפִיאַת, וְלָא יָכִילַת לְשַׁלְּטָאָה, וְלָא אִשְׁתַּלִּימַת בְּהַאי עָלְמָא. כַּד נַפְקַת מִנֵּיהּ, הִיא בִּתְרוּמַת הַקֳּדָשִׁים לֹא תֹּאכֵל, כִּשְׁאַר כָּל נִשְׁמָתִין, דְּאִשְׁתְּלִימוּ בְּהַאי עָלְמָא.","תּוּ אִית בְּהַאי קְרָא, וּבַת כֹּהֵן כִּי תִהְיֶה לְאִישׁ זָר. עֲלוּבָתָא אִיהִי נִשְׁמְתָא קַדִּישָׁא, כִּי תִהְיֶה לְאִישׁ זָר, דְּקָא אִתְמַשְּׁכָת, עַל גִּיּוֹרָא דְּאִתְגְּיַיר, וּפַרְחַת עָלֵיהּ מִגַּן עֵדֶן בְּאֹרַח סָתִים, עַל בִּנְיָינָא דְּאִתְבְּנִי מֵעָרְלָה מִסְאֲבָא, דָּא הֲוַת לְאִישׁ זָר.","וְדָא הוּא רָזָא עִלָּאָה יְתֵירָא מִכֹּלָּא. בְּעַמּוּדָא דְּקַיְּימָא לְטִקְלִין, גּוֹ אֲוִירָא דְּנָשְׁבָת, אִית טִיקְלָא חֲדָא בְּהַאי סִטְרָא, וְאִית טִיקְלָא אַחֲרָא בְּהַאי סִטְרָא. בְּהַאי סִטְרָא מֹאזְנִי צֶדֶק. וּבְהַאי סִטְרָא מֹאזְנֵי מִרְמָה. וְהַאי טִיקְלָא, לָא שָׁכִיךְ לְעָלְמִין, וְנִשְׁמָתִין סַלְּקִין וְנַחְתִּין עָאלִין וְתָבִין, וְאִית נִשְׁמָתִין עֲשִׁיקִין, כַּד שַׁלְטָא אָדָם בְּאָדָם, דִּכְתִּיב, (קהלת ח׳:ט׳) עֵת אֲשֶׁר שָׁלַט הָאָדָם בְּאָדָם לְרַע לוֹ, לְרַע לוֹ וַדַּאי.","אֲבָל הַאי נִשְׁמְתָא, דַּהֲוַת לְסִטְרָא אַחֲרָא, אִישׁ זָר, וְאִתְעַשְּׁקָת מִנֵּיהּ, דָּא אִיהִי לְרַע לוֹ. לוֹ: לְהַהוּא אִישׁ זָר, וְאִיהִי בִּתְרוּמַת הַקֳּדָשִׁים לא תֹּאכֵל, עַד דְּעָבִיד בָּהּ קוּדְשָׁא בְּרִיךְ הוּא מַה דְּעָבִיד, אָתָא קְרָא וְאָמַר וּבַת כֹּהֵן כִּי תִהְיֶה לְאִישׁ זָר הָכִי הוּא.","הָכָא אִית רָזָא, הֵיךְ מִתְעַשְּׁקָן נִשְׁמָתִין. אֶלָּא הַאי עָלְמָא אִתְנְהַג כֹּלָּא, בְּאִילָנָא דְּדַעַת טוֹב וָרָע. וְכַד אִתְנַהֲגָן בְּנֵי עָלְמָא בְּסִטְרָא דְּטוֹב, טִיקְלָא קַיְּימָא וְאַכְרַע לְסִטְרָא דְּטוֹב. וְכַד אִתְנַהֲגָן בְּסִטְרָא דְּרַע, אַכְרַע לְהַהוּא סִטְרָא. וְכָל נִשְׁמָתִין דַּהֲווֹ בְּהַהִיא שַׁעֲתָא בְּטִיקְלָא, הֲוָה עָשִׁיק לוֹן, וְנָטִיל לוֹן.","אֲבָל לְרַע לוֹ, דְּאִינּוּן נִשְׁמָתִין כַּפְיָין (ס\"א חפיין) לְכָל מַה דְּאַשְׁכְּחָן מִסִּטְרָא בִּישָׁא, וְשַׁיצְאָן לֵיהּ. וְסִימָנָא לְדָא, אֲרוֹנָא קַדִּישָׁא, דְּאִתְעֲשָׁק גּוֹ פְּלִשְׁתִּים, וּשְׁלִיטוּ בֵּיהּ, לְרַע לוֹן. אוּף הָכִי. הָנֵי נִשְׁמָתִין אִתְעְשַׁקִין מִסִּטְרָא אַחֲרָא לְרַע לוֹן.","מָה אִתְעֲבִידוּ מֵאִינּוּן נִשְׁמָתִין. חֲמֵינָן בְּסִפְרֵי קַדְמָאֵי, דְּמִנַּיְיהוּ הֲווֹ אִינּוּן חֲסִידֵי אוּמוֹת הָעוֹלָם. וְאִינּוּן מַמְזְרֵי תַּלְמִידֵי חֲכָמִים, דְּקַדְמָן לְכַהֲנָא רַבָּא עַמָּא דְּאַרְעָא, וְחָשׁוּב בְּעָלְמָא, אַף עַל גַּב דְּעָאל לִפְנַי וְלִפְנִים. בָּכָה הַאי סָבָא רִגְעָא חֲדָא, תַּוְוהוּ חַבְרַיָּיא, וְלָא אָמְרוּ מִדִי.","פָּתַח הַהוּא סָבָא וְאָמַר, (שמות כ״א:ח׳) אִם רָעָה בְּעֵינֵי אֲדֹנְיהָ אֲשֶׁר לֹא יְעָדָהּ וְהֶפְדָּהּ לְעַם נָכְרִי וְגוֹ'. הַאי פַּרְשְׁתָּא עַל רָזָא דָּא אִתְּמַר, וְכִי יִמְכֹּר אִישׁ אֶת בִּתּוֹ לְאָמָה לא תֵצֵא כְּצֵאת הָעֲבָדִים אִם רָעָה וְגוֹ'. מָארֵיהּ דְּעָלְמָא מַאן לָא יִדְחַל מִינָךְ, דְּאַנְתְּ שָׁלִיט עַל כָּל מַלְכִין דְּעָלְמָא, כְּמָה דְאַתְּ אָמֵר (ירמיהו י׳:ז׳) מִי לֹא יִרָאֲךָ מֶלֶךְ הַגּוֹיִם כִּי לְךָ יָאָתָה וְגוֹ'.","כַּמָּה אִינּוּן בְּנֵי נָשָׁא בְּעָלְמָא, דְּקָא מִשְׁתַּבְּשָׁן בְּהַאי קְרָא, וְכֻלְּהוּ אַמְרִי, אֲבָל קְרָא דָּא לָא אִתְיָישָּׁר בְּפוּמַיְיהוּ. וְכִי קוּדְשָׁא בְּרִיךְ הוּא מֶלֶךְ הַגּוֹיִם אִיהוּ, וַהֲלֹא מֶלֶךְ יִשְׂרָאֵל אִיהוּ, וְהָכִי אִקְרֵי, דְּהָא כְּתִיב, (דברים לב) בְּהַנְחֵל עֶלְיוֹן גּוֹיִם וְגוֹ'. וּכְתִיב (דברים לב) כִּי חֵלֶק יְיָ' עַמּוֹ. וְעַל דָּא אִקְרֵי מֶלֶךְ יִשְׂרָאֵל. וְאִי תֵּימָא דְּאִיהוּ מֶלֶךְ הַגּוֹיִם אִקְרֵי, הָא שְׁבָחָא דִּלְהוֹן דְקוּדְשָׁא בְּרִיךְ הוּא מֶלֶךְ עָלַיְיהוּ, וְלָא כְּמָה דְּאַמְרִין דְּאִתְמַסְרִין לְשַׁמָּשִׁין וְלִמְמָנָן דִּילֵיהּ.","וְתוּ סֵיפָא דִּקְרָא, דִּכְתִּיב, (ירמיהו י׳:ז׳) כִּי בְּכָל חַכְמֵי הַגּוֹיִם וּבְכָל מַלְכוּתָם מֵאֵין כָּמוֹךָ. כָּל הַאי, שְׁבָחָא אִיהוּ לִשְׁאַר עַמִּין, וּתְוָוהָא אִיהוּ, הֵיךְ לָא מִסְתַּלְּקֵי בְּהַאי קְרָא לְרוּם רְקִיעָא. אֶלָּא, דְקוּדְשָׁא בְּרִיךְ הוּא סָמָא עֵינַיְיהוּ, וְלָא יַדְעֵי בֵּיהּ כְּלָל, דְּהָא מַה דַּאֲנַן אַמְרֵי דְּכֻלְּהוּ אַיִן, וָאֶפֶס, וָתֹהוּ. דִּכְתִּיב, (ישעיהו מ׳:י״ז) כָּל הַגּוֹיִם כְּאַיִן נֶגְדּוֹ מֵאֶפֶס וָתֹהוּ נֶחְשְׁבוּ לוֹ, הָא עִקָרָא עִלָּאָה רַבָּא וְיַקִּירָא שָׁוֵי לוֹן קְרָא דָּא."],[[0,"ובת כהן כי תהיה לאיש זר:","זו היא נשמה הקדושה שנמשכה ממקום עליון, שהוא בינה, ונכנסת לתוך הסתום של עץ החיים, שהוא ז\"א, וכשהרוח של כהן העליון, שהוא חסד דז\"א, נושב ונותן נשמות, דהיינו שמלביש את הנשמות בחסד ונותן אותם באילן הזה, שהוא ז\"א פורחות משם הנשמות ונכנסות באוצר אחד, שהוא מלכות."],[1,"ווי לעלמא דלא וכו':","אוי לעולם, שבני אדם אינם יודעים להשמר, שהם מושכים המשכת, הנשמה לתוך גוף בעת זווגם, עם היצר הרע, שהוא \u0003איש זר, ובת כהן\u0004 ההיא שהיא הנשמה פרחת למטה ומוצאת בנין, דהיינו גוף, באיש זר. ומשום שזה רצון אדונה, נכנסת שמה ונכנעת, ואינה יכולה לשלוט, ואינה נשלמת בעולם הזה כשיוצאת ממנו, היא \u0003בתרומת הקדשים לא תאכל,\u0004 כשאר כל הנשמות שנשלמו בעולם הזה."],[2,"תו אית בהאי וכו':","עוד יש במקרא הזה, ובת כהן כי תהיה לאיש זר. נכלמת היא הנשמה הקדושה, כי תהיה לאיש זר, דהיינו שנמשכת על גר שנתגייר, ופורחת עליו מג\"ע בדרך סתום, על בנין, דהיינו גוף, שנבנה מערלה הטמאה, כי אבותיו לא נמולו. זה הוא \u0003לאיש זר.\u0004"],[3,"ודא איהו רזא וכו':","וזה הוא סוד עליון יותר מכל. בעמוד העומד לשקול עליו, תוך האויר הנושב, יש מאזנים בצד זה בימין, ויש מאזנים אחרים בצד זה משמאל. בצד זה, בימין, מאזני צדק. ובצד זה בשמאל, מאזני מרמה. ומאזנים אלו, אינם שקטים לעולם, והנשמות עולות ויורדות באות וחוזרות. דרך מאזנים האלו, ויש נשמות עשוקות, כששולט אדם דס\"א באדם דקדושה, שכתוב, עת אשר שלט האדם באדם לרע לו. לרע לו ודאי."],[3,"","ביאור הדברים. כבר ידעת אשר קו האמצעי המכריע ומקיים ב' הקוין ימין ושמאל, מבדיל ביניהם, אשר קו ימין מאיר ממעלה למטה, והקו שמאל יאיר ממטה למעלה, ולא ממעלה למטה. (כמ\"ש לעיל בראשית א' דף ס' ד\"ה מחלוקת ע\"ש) וז\"ס \u0003עמודא דקיימא לטקלין,\u0004 שהוא עמוד האמצעי המקיים ב' האורות ימין ושמאל. ושוקל אותם כמו במאזנים שהארת קו הימין הוא מושך למטה לתחתונים, והארת קו השמאל מעלה למעלה, ועל ידי זה עומד לשון המאזנים באמצע, שאינו נוטה לא לימין ולא לשמאל, אלא לשניהם יחד, כל אחד לפי דרכו. ומ\"ש \u0003גו אוירא דנשבת,\u0004 הוא כי הארת השמאל מתגלה על ידי יציאת ה \u0003י'\u0004 מאויר. בסוד נקודת השורק. (כמ\"ש באורך לעיל בראשית א' דף מ\"ה ד\"ה כד)."],[3,"","וכשהעמוד האמצעי הזה מאיר במלכות, נעשה שמה ב' בחינות מאזנים, א) \u0003מאזני צדק,\u0004 דהיינו כמשקל עמוד האמצעי, למשוך הארת הימין מלמעלה למטה, והארת השמאל רק ממטה למעלה. ב) \u0003מאזני מרמה,\u0004 שהוא אחיזת ס\"א, המושכים הארת השמאל ממעלה למטה. ומטעם ב' מאזנים האלו, נקראת המלכות עץ הדעת טוב ורע כמ\"ש להלן. ואם הנשמה מקבלת ממאזני מרמה, אז נעשקת בידי הס\"א, ונופלת לידיה, והן הנקראות, \u0003נשמות העשוקות.\u0004 ואז נאמר \u0003עת אשר שלט אדם באדם לרע לו,\u0004 דהיינו שאדם דס\"א שולט באדם דקדושה. אבל הוא לרע לו. כמ\"ש לפנינו."],[4,"אבל האי נשמתא וכו':","אבל נשמה זו שהיתה לסטרא אחרא הנקרא איש זר, ונעשקה על ידו, זה הוא לרע לו, לו, לאיש זר ההוא, והיא בתרומת הקדשים לא תאכל, כשאר הנשמות, עד שעושה בה הקב\"ה מה שעושה, דהיינו עד שיתקן אותה. כמ\"ש להלן. לזה בא הכתוב ואמר, ובת כהן כי תהיה לאיש זר, יהיה כך, שבתרומת הקדשים לא תאכל."],[5,"הכא אית רזא וכו':","כאן יש סוד איך מתעשקות הנשמות. כי עולם הזה מתנהג בו הכל על ידי עץ הדעת טוב ורע, שהוא המלכות. וכשבני העולם מתנהגים בצד הטוב בהכרעת קו האמצעי, כנ\"ל, המאזנים עומדים ומכריעים לצד הטוב. וכשמתנהגים כצד הרע, דהיינו שממשיכים הארת השמאל ממעלה למטה, מכריעים המאזנים לצד ההוא, לס\"א. וכל הנשמות שהיו בשעה ההיא במאזנים עושק אותן הס\"א ולוקח אותן."],[6,"אבל לרע לו וכו':","אבל לרע לו, לס\"א, כי אלו הנשמות מכניעים כל מה שמוצאות מצד הרע, ומכלות אותו. והסימן לזה, הוא ארון הקדוש שנעשק על ידי הפלשתים ושלטו בו, לרע להם. כי נגפו על ידו הם ואלהיהם, (שמואל א' ה') אף כאן אלו הנשמות שנעשקו ע\"י הס\"א, הוא לרע להם."],[7,"מה אתעבידו מאינון וכו':","מה נעשה מאלו הנשמות העשוקות. ראינו בספרים הראשונים, שמהם היו אלו חסידי אומות העולם, ואלו ממזרים תלמידי חכמים, והם הממזרים תלמידי חכמים הקודמים לכהן גדול עם הארץ, והם חשובים יותר בעולם, אע\"פ שהכה\"ג נכנס לפני ולפנים בקודש הקדשים. בכה זקן ההוא רגע אחד. תמהו החברים, ולא אמרו כלום."],[8,"פתח ההוא סבא וכו':","פתח זקן ההוא ואמר, אם רעה בעיני אדניה אשר לא יעדה והפדה לעם נכרי וגו'. פרשה זו נאמרה על סוד זה, של נשמות העשוקות, וכי ימכור איש את בתו לאמה לא תצא כצאת העבדים אם רעה בעיני וגו'. רבונו של עולם, מי לא יירא ממך, שאתה מושל על כל מלכי העולם, כש\"א, מי לא יראך מלך הגוים כי לך יאתה וגו'."],[9,"כמה אינון בני וכו':","כמה הם בני אדם בעולם שמשתבשים וטועים במקרא הזה. וכולם אומרים אותו אבל המקרא אינו מתישר בפיהם. וכי הקב\"ה מלך הגוים נקרא, והלא מלך ישראל הוא, ובו הוא נקרא, שכתוב, בהנחל עליון גוים וגו'. וכתוב, כי חלק ה' עמו. וע\"כ נקרא מלך ישראל. ואם תאמר, שהוא מלך הגוים נקרא, הרי זה שבח להם שהקב\"ה מולך עליהם, ולא כמו שאומרים, שנמסרו למשמשים ולממונים שלו."],[10,"ותו סיפא דקרא וכו':","ועוד, סוף המקרא, שכתוב, כי בכל חכמי הגוים ובכל מלכותם מאין כמוך. כל זה שבח הוא לשאר העמים, ופלא הוא, איך אינם מתעלים במקרא הזה לרום הרקיע, שהמקרא נותן לחכמיהם ומלכותם איזה יחס אל הקב\"ה, שצריך משום זה לומר, שהקב\"ה גדול מהם. אלא הקב\"ה מעוור עיניהם, ואינם יודעים בו כלל, שזהו מה שאנו אומרים שכולם אין, ואפס, ותוהו. שכתוב, כל הגוים כאין נגדו מאפס ותוהו נחשבו לו. והרי עיקר עליון גדול ויקר משים אותם המקרא הזה, שאומר, שבכל חכמי הגוים ובכל מלכותם מאין כמוך."]],[[0,"","וּבַת כֹּהֵן כִּי תִהְיֶה לְאִישׁ זָר - זוֹ הַנְּשָׁמָה הַקְּדוֹשָׁה שֶׁנִּמְשְׁכָה מִמָּקוֹם עֶלְיוֹן וְנִכְנְסָה לְתוֹךְ סֵתֶר עֵץ הַחַיִּים, וּכְשֶׁרוּחַ הַכֹּהֵן הָעֶלְיוֹן נוֹשֶׁבֶת וְנוֹתֶנֶת נְשָׁמוֹת בָּאִילָן הַזֶּה, פּוֹרְחוֹת מִשָּׁם אוֹתָם נְשָׁמוֹת וְנִכְנָסוֹת בְּאוֹצָר אֶחָד."],[1,"","אוֹי לָעוֹלָם, שֶׁלֹּא יוֹדְעִים בְּנֵי אָדָם לְהִשָּׁמֵר, שֶׁמּוֹשְׁכִים מְשִׁיכָה עִם יֵצֶר הָרָע, שֶׁהוּא אִישׁ זָר, וּבַת הַכֹּהֵן הַ את פּוֹרַחַת לְמַטָּה וּמוֹצֵאת בִּנְיָן בְּאִישׁ זָר. וּמִשּׁוּם שֶׁהוּא רָצוֹן שֶׁל אֲדוֹנָהּ, נִכְנֶסֶת לְשָׁם וְנִכְפֵּית, וְלֹא יְכוֹלָה לִשְׁלֹט, וְלֹא הִשְׁתַּלְּמָה בָּעוֹלָם הַזֶּה. וּכְשֶׁיּוֹצֵאת מִמֶּנּוּ, הִיא בִּתְרוּמַת הַקְּדָשִׁים לֹא תֹאכֵל, כִּשְׁאָר כָּל הַנְּשָׁמוֹת שֶׁהִשְׁתַּלְּמוּ בָּעוֹלָם הַזֶּה."],[2,"","עוֹד יֵשׁ בַּפָּסוּק הַזֶּה, וּבַת כֹּהֵן כִּי תִהְיֶה לְאִישׁ זָר. עֲלוּבָה הִיא הַנְּשָׁמָה הַקְּדוֹשָׁה כִּי תִהְיֶה לְאִישׁ זָר, שֶׁנִּמְשְׁכָה עַל הַגֵּר שֶׁהִתְגַּיֵּר, וּפָרְחָה אֵלָיו מִגַּן עֵדֶן בְּדֶרֶךְ נִסְתָּר עַל בִּנְיָן שֶׁנִּבְנֶה מֵעָרְלָה טְמֵאָה, זוֹ הָיְתָה לְאִישׁ זָר."],[3,"","וְזְהִוּ סוֹד עֶלְיוֹן יוֹתֵר מֵהַכֹּל. בָּעַמּוּד שֶׁעוֹמֵד לַמֹּאזְנַיִם בְּתוֹךְ אֲוִיר שֶׁנּוֹשֵׁב, יֵשׁ מִשְׁקָל אֶחָד בְּצַד זֶה, וְיֵשׁ מִשְׁקָל אַחֵר בְּצַד זֶה. בְּצַד זֶה מֹאזְנֵי צֶדֶק, וּבְצַד זֶה מֹאזְנֵי מִרְמָה. וְהַמִּשְׁקָל הַזֶּה לֹא שׁוֹכֵךְ לְעוֹלָמִים, וּנְשָׁמוֹת עוֹלוֹת וְיוֹרְדוֹת, נִכְנָסוֹת וְיוֹצְאוֹת, וְיֵשׁ נְשָׁמוֹת עֲשׁוּקוֹת, כְּשֶׁשּׁוֹלֵט אָדָם בְּאָדָם, שֶׁכָּתוּב (קהלת ח) עֵת אֲשֶׁר שָׁלַט הָאָדָם בְּאָדָם לְרַע לוֹ. לְרַע לוֹ וַדַּאי."],[4,"","אֲבָל נְשָׁמָה זוֹ שֶׁהָיְתָה לַצַּד הָאַחֵר, אִישׁ זָר, וְנֶעֶשְׁקָה מִמֶּנּוּ, זוֹהִי לְרַע לוֹ. לוֹ - לְאוֹתוֹ אִישׁ זָר, וְהִיא בִּתְרוּמַת הַקְּדָשִׁים לֹא תֹאכֵל, עַד שֶׁעוֹשֶׂה בָּהּ הַקָּדוֹשׁ בָּרוּךְ הוּא מַה שֶּׁעוֹשֶׂה. בָּא הַפָּסוּק וְאָמַר, וּבַת כֹּהֵן כִּי תִהְיֶה לְאִישׁ זָר, כָּךְ זֶה."],[5,"","כָּאן יֵשׁ סוֹד אֵיךְ נֶעֱשָׁקוֹת הַנְּשָׁמוֹת. אֶלָּא הָעוֹלָם הַזֶּה מִתְנַהֵג הַכֹּל בְּעֵץ הַדַּעַת טוֹב וָרָע. וּכְשֶׁמִּתְנַהֲגִים בְּנֵי הָעוֹלָם בַּצַּד הַטּוֹב, הַמִּשְׁקֹלֶת עוֹמֶדֶת וּמַכְרִיעָה לַצַּד הַטּוֹב, וּכְשֶׁמִּתְנַהֲגִים בַּצַּד הָרָע - מַכְרִיעָה לְאוֹתוֹ הַצַּד. וְכָל הַנְּשָׁמוֹת שֶׁהָיוּ בְּאוֹתָהּ שָׁעָה בַּמִּשְׁקֹלֶת, הָיָה עוֹשֵׁק אוֹתָן וְלוֹקֵחַ אוֹתָן."],[6,"","אֲבָל לְרַע לוֹ, שֶׁאוֹתָן נְשָׁמוֹת מַכְנִיעוֹת (מכסות) אֶת כָּל מַה שֶּׁמּוֹצְאוֹת מִצַּד הָרָע וּמַשְׁמִידוֹת אוֹתוֹ, וְסִימָן לָזֶה - אֲרוֹן הַקֹּדֶשׁ שֶׁנֶּעֱשַׁק לְתוֹךְ פְּלִשְׁתִּים וְשָׁלְטוּ לְהָרַע לָהֶם. אַף כָּאן, אֵלּוּ הַנְּשָׁמוֹת נֶעֱשָׁקוֹת מֵהַצַּד הָאַחֵר לְהָרַע לָהֶן."],[7,"","מַה נַּעֲשָׂה מֵאוֹתָן נְשָׁמוֹת? רָאִינוּ בְּסִפְרֵי הַקַּדְמוֹנִים, שֶׁמֵּהֶם הָיוּ אוֹתָם חֲסִידֵי אֻמּוֹת הָעוֹלָם. וְאוֹתָם הַמַּמְזֵרִים שֶׁהֵם תַּלְמִידֵי חֲכָמִים שֶׁקּוֹדְמִים לְכֹהֵן גָּדוֹל עַם הָאָרֶץ וְחָשׁוּב בָּעוֹלָם, אַף עַל גַּב שֶׁהוּא נִכְנָס לִפְנַי וְלִפְנִים. בָּכָה הַזָּקֵן הַזֶּה רֶגַע אֶחָד. תָּמְהוּ הַחֲבֵרִים וְלֹא אָמְרוּ דָבָר."],[8,"","פָּתַח אוֹתוֹ זָקֵן וְאָמַר, אִם רָעָה בְּעֵינֵי אֲדנֶיהָ אֲשֶׁר לֹא יְעָדָהּ וְהֶפְדָּהּ לְעַם נָכְרִי וְגוֹ'. פָּרָשָׁה זוֹ נֶאֶמְרָה עַל הַסּוֹד הַזֶּה, וְכִי יִמְכֹּר אִישׁ אֶת בִּתּוֹ לְאָמָה לֹא תֵצֵא כְּצֵאת הָעֲבָדִים אִם וְגוֹ'. רִבּוֹן הָעוֹלָם, מִי לֹא יִפְחַד מִמְּךְ, שֶׁאַתָּה שׁוֹלֵט עַל כָּל מַלְכֵי הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה י) מִי לֹא יִרָאֲךְ מֶלֶךְ הַגּוֹיִם כִּי לְךְ יָאָתָה וְגוֹ'."],[9,"","כַּמָּה הֵם בְּנֵי הָאָדָם בָּעוֹלָם שֶׁמִּשְׁתַּבְּשִׁים בַּפָּסוּק הַזֶּה, וְכֻלָּם אוֹמְרִים, אֲבָל הַפָּסוּק הַזֶּה לֹא מִתְיַשֵּׁר בְּפִיהֶם. וְכִי הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא מֶלֶךְ הַגּוֹיִם?! וַהֲלֹא הוּא מֶלֶךְ יִשְׂרָאֵל, וְכָךְ נִקְרָא! שֶׁהֲרֵי כָּתוּב (דבריםלב) בְּהַנְחֵל עֶלְיוֹן גּוֹיִם וְגוֹ', וְכָתוּב (שם) כִּי חֵלֶק ה' עַמּוֹ. וְעַל זֶה הוּא נִקְרָא מֶלֶךְ יִשְׂרָאֵל. וְאִם תֹּאמַר שֶׁהוּא נִקְרָא מֶלֶךְ הַגּוֹיִם, הֲרֵי שֶׁבַח שֶׁלָּהֶם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מֶלֶךְ עֲלֵיהֶם, וְלֹא כְּמוֹ שֶׁאוֹמְרִים שֶׁהֵם נִמְסְרוּ לַשַּׁמָּשִׁים וְלַמְמֻנִּים שֶׁלּוֹ."],[10,"","וְעוֹד סוֹף הַפָּסוּק, שֶׁכָּתוּב (ירמיה י) כִּי בְכָל חַכְמֵי הַגּוֹיִם וּבְכָל מַלְכוּתָם מֵאֵין כָּמוֹךְ. כָּל זֶה הוּא שֶׁבַח לִשְׁאָר הָעַמִּים. וּתְמִיהָה הִיא אֵיךְ לֹא מִתְעַלִּים בַּפָּסוּק הַזֶּה לְרוּם הָרָקִיעַ? אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא סִמֵּא אֶת עֵינֵיהֶם וְלֹא יוֹדְעִים בּוֹ כְּלָל, שֶׁהֲרֵי מַה שֶּׁאָנוּ אוֹמְרִים שֶׁכֻּלָּם אַיִן וְאֶפֶס וְתֹהוּ, שֶׁכָּתוּב (ישעיה מ) כָּל הַגּוֹיִם כְּאַיִן נֶגְדּוֹ מֵאֶפֶס וָתֹהוּ נֶחְשְׁבוּ לוֹ, הֲרֵי הָעִקָּר הָעֶלְיוֹן הַגָּדוֹל וְהַנִּכְבָּד שָׂם אוֹתָם הַכָּתוּב הַזֶּה."]]],[["אָמַר לֵיהּ ר' חִיָּיא וְהָא כְּתִיב (תהילים מ״ז:ט׳) מָלַךְ אֱלהִים עַל גּוֹיִם וְגוֹ'. אָמַר לֵיהּ, אֲנָא חֲמֵינָא דְּבָתַר כֹּתְלַיְיהוּ הֲוִית, וְנַפְקַת בְּהַאי קְרָא לְסַיְּיעָא לוֹן, הֲוָה לִי לְאָתָבָא בְּקַדְמִיתָא, עַל מַה דַּאֲמֵינָא. אֲבָל כֵּיוָן דְּאַשְׁכַּחְנָא לָךְ בְּאָרְחָא, אַעְבַּר לָךְ מִתַּמָּן, וּמִתַּמָּן אֵיהָךְ לְאַעְבְּרָא כֹּלָּא.","תָּא חֲזֵי, כָּל שְׁמָהָן, וְכָל כִּנּוּיָין דִּשְׁמָהָן, דְּאִית לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, כֻּלְּהוּ מִתְפַּשְּׁטָן לְאָרְחַיְיהוּ, וְכֻלְּהוּ מִתְלַבְּשִׁין אִלֵּין בְּאִלֵּין, וְכֻלְּהוּ מִתְפַּלְגִין לְאָרְחִין וּשְׁבִילִין יְדִיעָן. בַּר שְׁמָא יְחִידָאָה, בָּרִיר דְּכָל שְׁאַר שְׁמָהָן, דְּאַחֲסִין לְעַמָּא יְחִידָאָה, בָּרִיר מִכָּל שְׁאַר עַמִּין, וְאִיהוּ יוּ\"ד הֵ\"א וָא\"ו הֵ\"א, דִּכְתִּיב, (דברים לב) כִּי חֵלֶק יְיָ' עַמּוֹ. וּכְתִיב (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ' בִּשְׁמָא דָּא מַמָּשׁ, יַתִּיר מִכָּל שְׁאַר שְׁמָהָן.","וּשְׁמָא חַד מִכָּל שְׁאַר שְׁמָהָן דִּילֵיהּ, הַהוּא דְּאִתְפְּשַׁט וְאִתְפְּלַג לְכַמָּה אָרְחִין וּשְׁבִילִין, וְאִקְרֵי אֱלֹהִים. וְאַחֲסִין שְׁמָא דָּא, וְאִתְפְּלַג לְתַתָּאֵי דְהַאי עָלְמָא, וְאִתְפְּלַג שְׁמָא דָּא, לְשַׁמָּשִׁין וְלִמְמָנָן דִּמְנַהֲגֵי לִשְׁאַר עַמִּין. כְּמָה דְאַתְּ אָמֵר, (במדבר כ״ב:כ׳) וַיָּבֹא אֱלהִים אֶל בִּלְעָם לַיְלָה. (בראשית כ׳:ג׳) וַיָּבֹא אֱלהִים אֶל אֲבִימֶלֶךְ בַּחֲלוֹם הַלַּיְלָה. וְכֵן כָּל מְמָנָא וּמְמַנָּא דְּאַחֲסִין לוֹן קוּדְשָׁא בְּרִיךְ הוּא לִשְׁאַר עַמִּין, בִּשְׁמָא דָּא כְּלִילָן. וַאֲפִילּוּ עֲבוֹדָה זָרָה בִּשְׁמָא דָּא אִקְרֵי. וּשְׁמָא דָּא מָלַךְ עַל גּוֹיִם, וְלָא הַהוּא שְׁמָא, דָּא הַהוּא דְּמָלַךְ עַל יִשְׂרָאֵל, דְּאִיהוּ יְחִידָאָה, לְעַמָּא יְחִידָאָה, לְעַמָּא דְּיִשְׂרָאֵל, עַמָּא קַדִּישָׁא.","וְאִי תֵּימָא, עַל אָרְחָא דָּא נוֹקִים קְרָא דִּכְתִּיב, (ירמיהו י׳:ז׳) מִי לא יִרָאֲךָ מֶלֶךְ הַגּוֹיִם, דְּדָא אִיהוּ שְׁמָא דְּקָא מָלַךְ עַל גּוֹיִם, אֱלֹהִים דְּהָא דְּחִילוּ בֵּיהּ שַׁרְיָא וְדִינָא בֵּיהּ שַׁרְיָא. לָאו הָכִי, וְלָאו עַל דָּא אִתְּמַר, דְּאִי הָכִי אֲפִילּוּ עֲבוֹדָה זָרָה בִּכְלָלָא דָּא אִיהוּ.","אֲבָל כֵּיוָן דְּכֹתָלָא דַּהֲוֵית סָמִיךְ אֲבַתְרֵיהּ, אִתְנְסַח, קְרָא קָאִים עַל קִיּוּמָא, בְּאִסְתַּכְּלוּתָא זְעֵיר. מִי לֹא יִרָאֲךָ מֶלֶךְ הַגּוֹיִם, וְאִי תֵּימָא דְּמֶלֶךְ הַגּוֹיִם עַל קוּדְשָׁא בְּרִיךְ הוּא אִתְּמַר, לָאו הָכִי. אֶלָּא, מַאן הוּא מֶלֶךְ הַגּוֹיִם דְּלָא יִרָאֲךָ, דְּלָא דָּחִיל מִינָךְ, וְלָא יִזְדַּעְזַע מִינָךְ. מִי מֶלֶךְ הַגּוֹיִם דְּלָא יִרָאֲךָ. כְּגַוְונָא דָּא (תהילים קי״ג:א׳) הַלְלוּיָהּ הַלְלוּ עַבְדֵי יְיָ' הַלְלוּ אֶת שֵׁם יְיָ'. מַאן דִּשְׁמַע לֵיהּ, לָא יָדַע מַאי קָאָמַר, כֵּיוָן דְּאָמַר הַלְלוּיָהּ, אוּף הָכִי הַלְלוּ עַבְדֵי יְיָ', דְּהֲוָה לֵיהּ לְמִכְתַּב, עַבְדֵי יְיָ' הַלְלוּ אֶת שֵׁם יְיָ'. אוּף הָכָא. הֲוָה לֵיהּ לְמִכְתַּב, מִי מִמֶּלֶךְ הַגּוֹיִם דְּלָא יִרָאֲךָ. אֶלָּא כֹּלָּא עַל תְקּוּנֵיהּ אִתְּמַר.","כִּי בְכָל חַכְמֵי הַגּוֹיִם וּבְכָל מַלְכוּתָם מֵאֵין כָּמוֹךָ, מַהוּ מִלָּה דְּאִתְפָּשַּׁט בֵּינַיְיהוּ בְּחָכְמְתָא דִּלְּהוֹן, מֵאֵין כָּמוֹךָ וְכֻלְּהוּ אוֹדָאן עַל דָּא, כַּד חָמָאן בְּחָכְמְתָא דִּלְהוֹן עוֹבָדָךְ וּגְבוּרְתָּךְ, אִתְפָּשַׁט מִלָּה דָּא בֵּינַיְיהוּ, וְאַמְרֵי מֵאֵין כָּמוֹךָ בְּכָל חַכְמֵי הַגּוֹיִם וּבְכָל מַלְכוּתָם. מֵאֵין כָּמוֹךָ אַמְרֵי, וְאִתְפָּשַּׁט בֵּינַיְיהוּ. חַדּוּ חַבְרַיָּיא, וּבָכוּ וְלָא אָמְרוּ מִדִי. אוּף הָכִי בָּכָה אִיהוּ כְּמִלְּקַדְּמִין.","פָּתַח וְאָמַר (בראשית כ״א:י׳) וַתֹּאמֶר לְאַבְרָהָם גָּרֵשׁ הָאָמָה הַזֹּאת וְאֶת בְּנָהּ וְגוֹ', חַבְרַיָּיא אִתְּעֲרוּ, דְּבָעָאת שָׂרָה לְפַנָּאָה עֲבוֹדָה זָרָה מִבֵּיתָא, וְעַל דָּא כְּתִיב כָּל אֲשֶׁר תֹּאמַר אֵלֶיךָ שָׂרָה שְׁמַע בְּקוֹלָהּ. הָכָא כְּתִיב וְכִי יִמְכֹּר אִישׁ אֶת בִּתּוֹ, דָּא נִשְׁמְתָא בְּגִלְגּוּלֵי עַל עוֹבָדִין בִּישִׁין דְּעָלְמָא. לְאָמָה: הַהוּא סִטְרָא אַחֲרָא בְּגִלְגּוּלָא בִּישָׁא דְּטִיקְלָא, דְּאַהֲדָר, וְהָא אִתְעַשְּׁקַת, לְאַפָּקָא לָהּ מִתַּמָּן. וַדַּאי לֹא תֵּצֵא כְּצֵאת הָעֲבָדִים, כָּל אִינּוּן נִשְׁמָתִין דְּמִתְעַשְּׁקָן.","מַאן אִינּוּן הָכָא. אִיהוּ רָזָא, אִלֵּין אִינּוּן נִשְׁמָתִין דִּינוֹקִין זְעִירִין, כַּד אִינּוּן יַנְקֵי מִגּוֹ תּוּקְפָּא דְּאִמְּהוֹן. וְקוּדְשָׁא בְּרִיךְ הוּא חָמֵי, דְּאִי יִתְקַיְּימוּן בְּעָלְמָא, יְבַאֲשׁוּן רֵיחֵיהוֹן, וְיַחְמְצוּן כְּחוֹמֶץ דָּא. לָקִיט לוֹן (רמ\"ח ע\"ב, רמ\"ט ע\"ב) זְעִירִין, בְּעוֹד דְּיַהֲבֵי רֵיחָא.","מַה עָבִיד. שָׁבִיק לוֹן לְאִתְעַשְּׁקָא בִּידָא דְּהַהִיא אָמָה, וְדָא אִיהִי לִילִית דְּכֵיוָן דְּאִתְיְיהִיבוּ בִּרְשׁוּתָהּ, חַדָּאת (נ\"א אחדא) בְּהַהוּא יְנוֹקָא, וַעֲשִׁיקַת לֵיהּ, וְאַפִּיקַת לֵיהּ מֵעָלְמָא, כַּד אִיהוּ יָנִיק בְּתוּקְפָּא דְּאִמֵּיהּ."],[[0,"אמר ליה ר' חייא וכו':","א\"ל ר\"ח, והרי כתוב, מלך אלקים על גוים וגו'. אמר לו, אני רואה שאחר הכותל שלהם היית, ויצאת במקרא הזה לעזור אותם. היה לי להשיב מתחילה על מה שאמרתי. אבל כיון שמצאתי אותך בדרך, אעביר אותך משם, ומשם אלך להעביר הכל."],[1,"ת\"ח כל שמהן וכו':","בוא וראה, כל השמות וכל כינוי של השמות שיש להקב\"ה. כולם מתפשטים לדרכם, וכולם מתלבשים אלו באלו, וכולם מתחלקים לדרכים ושבילים ידועים חוץ מן שם אחד, הברור מכל שאר השמות, שהוריש לעם היחידי, הברור מכל שאר העמים, והוא יוד הא ואו הא. שכתוב, כי חלק ה' עמו. וכתוב ואתם הדבקים בהוי\"ה, שדבוקים בשם הזה ממש, יותר מבכל שאר השמות."],[2,"ושמא חד מכל וכו':","ושם אחד מכל השמות שלו, ההוא, שנתפשט לכמה דרכים ושבילים, שנקרא אלקים, והוריש שם הזה, ונחלק לתחתונים שבעולם הזה, ונחלק שם הזה למשמשים ולממונים המנהיגים שאר העמים. כמש\"א, ויבא אלקים אל בלעם לילה. ויבא אלקים אל אבימלך בחלום הלילה. וכן כל ממונה וממונה, שהוריש אותם הקב\"ה לשאר העמים, כלולים בשם הזה. ואפילו עבודה זרה נקרא בשם הזה. ושם הזה מלך על גוים, ולא שם ההוא של ההוא שמלך על ישראל, שהוא שם הויה, שהוא יחידי לעם היחידי, לעם ישראל, לעם הקדוש."],[3,"ואי תימא על וכו':","ואם תאמר, על דרך זה נעמיד הכתוב, שכתוב, מי לא יראך מלך הגוים, שזה השם שמלך על גוים, הוא אלקים. כי בו שורה יראה, ודין שורה בו. אינו כן, ולא על זה נאמר, כי אם כן אפילו עבודה זרה הוא בכלל הזה, של מי לא יראך, שגם עבודה זרה נקראת אלהים."],[4,"אבל כיון דכתלא וכו':","אבל כיון שהכותל, שהיית נסמך אחריו, נתעקר, עומד הכתוב על קיומו, במעט הסתכלות. מי לא יראך מלך הגוים, אם תאמר שאומר על הקב\"ה, מלך הגוים, אינו כן, אלא הפירוש הוא, מי הוא מלך הגוים שלא יראך, ולא יפחד ממך, ולא יזדעזע ממך, ודומה כמו שהיה כתוב, מי מלך הגוים שלא יראך. כעין זה הללויה הללו עבדי ה' הללו את שם ה'. מי ששומע אותו אינו יודע מה אמר, כיון שאמר הללויה, אומר גם כן הללו עבדי ה', שהיה לו לכתוב, עבדי ה' הללו את שם ה'. ועם זה הכרח שאע\"פ שאמר מקודם הללויה סובב הוא על עבדי ה', אף כאן אע\"פ שאמר מקודם מי לא יראך, סובב הוא על מלך הגוים, ודומה, כמו שהיה כתוב מי ממלך הגוים שלא יראך, והכל נאמר כמו שהיה צריך."],[5,"כי בכל חכמי וגו':","כי בכל חכמי הגוים ובכל מלכותם מאין כמוך, פירושו, מהו המלה שנתפשט ביניהם בחכמה שלהם. הוא, \u0003מאין כמוך,\u0004 וכולם מודים על זה. כאשר רואים בחכמה שלהם מעשיך וגבורותיך, מתפשט מלה זו ביניהם, ואומרים, \u0003מאין כמוך.\u0004 ושיעור הכתוב, הוא בכל חכמי הגוים ובכל מלכותם, מאין כמוך אומרים, ומתפשט ביניהם. שמחו החברים, ובכו, ולא אמרו כלום. אף הוא בכה כמקודם."],[6,"פתח ואמר ותאמר וגו':","פתח ואמר, ותאמר לאברהם גרש את \u0003האמה\u0004 הזאת ואת בנה וגו'. החברים העירו, שרצתה שרה לפנות עבודה זרה מבית. וע\"כ כתוב, כל אשר תאמר אליך שרה שמע בקולה. הרי שאמה, היא בחינת ע\"ז. כאן כתוב \u0003כי ימכור איש את בתו,\u0004 דהיינו הנשמה הבאה בגלגולים על מעשים רעים שבעולם. לאמה, היינו צד האחר ההוא, שבגלגול הרע של המאזנים שחזרו למאזני מרמה כנ\"ל, והיא נעשקה ע\"י הס\"א. להוציא אותה משם, לא תצא כצאת העבדים,שהם כל אלו נשמות הנעשקות. אלא מתעטרת בעטרה על ראשה, כמ\"ש לפנינו."],[7,"מאן אינון הכא וכו':","שואל, מי הן הנשמות שבכאן. ומשיב, הוא סוד. אלו הן נשמות של ילדים קטנים, היונקים מתוקפן של אמותיהם, והקב\"ה רואה, שאם יתקיימו בעולם, יבאישו ריחם ויחמצו כחומץ הזה, ע\"כ לוקטם כשהם קטנים בעוד שנותנים ריח טוב."],[8,"מה עביד לון וכו':","מה עושה להם הקב\"ה, עוזב אותם להתעשק ביד אמה ההיא, וזו היא לילית, וכיון שניתנו ברשותה, שמחה בילד ההוא, ועושקת אותו, ומוציאה אותו מן העולם בעוד שהוא יונק מתוקפה של אמו."]],[[0,"","אָמַר לוֹ רַבִּי חִיָּיא, וַהֲרֵי כָּתוּב מָלַךְ אֱלֹהִים עַל גּוֹיִם וְגוֹ'. אָמַר לוֹ, אֲנִי רָאִיתִי שֶׁאַחַר הַכֹּתֶל שֶׁלָּהֶם הָיִיתָ, וְיָצָאתָ בַּפָּסוּק הַזֶּה לַעֲזר לָהֶם. הָיָה לִי לְהָשִׁיב בַּתְּחִלָּה עַל מַה שֶּׁאָמַרְתִּי. אֲבָל כֵּיוָן שֶׁמָּצָאתִי אוֹתְךְ בַּדֶּרֶךְ, אַעֲבִיר אוֹתְךְ מִשָּׁם, וּמִשָּׁם אֵלֵךְ לְהַעֲבִיר אֶת הַכֹּל."],[1,"","בֹּא וּרְאֵה, כָּל הַשֵּׁמוֹת וְכָל כִּנּוּיֵי הַשֵּׁמוֹת שֶׁיֵּשׁ לַקָּדוֹשׁ-בָּרוּךְ-הוּא, כֻּלָּם מִתְפַּשְּׁטִים לְדַרְכֵיהֶם, וְכֻלָּם מִתְלַבְּשִׁים אֵלֶּה בְּאֵלֶּה, וְכֻלָּם נֶחֱלָקִים לִדְרָכִים וּשְׁבִילִים יְדוּעִים, פְּרָט לַשֵּׁם הַיְחִידִי, הַנִּבְחָר שֶׁל כָּל שְׁאָר הַשֵּׁמוֹת, שֶׁהוֹרִישׁ לָעָם הַיָּחִיד הַנִּבְחָר מִכָּל הָעַמִּים, וְהוּא - יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ. וְכָתוּב (שם) וְאַתֶּם הַדְּבֵקִים בַּה', בְּשֵׁם זֶה מַמָּשׁ יוֹתֵר מִכָּל שְׁאָר הַשֵּׁמוֹת."],[2,"","וְשֵׁם אֶחָד מִכָּל שְׁאָר שְׁמוֹתָיו, אוֹתוֹ שֶׁהִתְפַּשֵּׁט וְנֶחֱלָק לְכַמָּה דְרָכִים וּשְׁבִילִים וְנִקְרָא אֱלֹהִים. וְהוֹרִישׁ אֶת הַשֵּׁם הַזֶּה, וְנֶחֱלָק לַתַּחְתּוֹנִים שֶׁל הָעוֹלָם הַזֶּה, וְנֶחֱלָק הַשֵּׁם הַזֶּה לְשַׁמָּשִׁים וְלִמְמֻנִּים שֶׁמַּנְהִיגִים אֶת שְׁאָר הָעַמִּים, כְּמוֹ שֶׁנֶּאֱמַר (במדבר כב) וַיָּבֹא אֱלֹהִים אֶל בִּלְעָם לַיְלָה. (בראשית כ) וַיָּבֹא אֱלֹהִים אֶל אֲבִימֶלֶךְ בַּחֲלוֹם הַלַּיְלָה. וְכֵן כָּל מְמֻנֶּה וּמְמֻנֶּה שֶׁהוֹרִישׁ הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתָם לִשְׁאָר הָעַמִּים נִכְלָלִים בַּשֵּׁם הַזֶּה, וַאֲפִלּוּ עֲבוֹדָה זָרָה נִקְרֵאת בַּשֵּׁם הַזֶּה. וְשֵׁם זֶה מָלַךְ עַל גּוֹיִם, וְלֹא אוֹתוֹ הַשֵּׁם, שֶׁהוּא מֶלֶךְ עַל יִשְׂרָאֵל, שֶׁהוּא יְחִידִי לָעָם הַיְחִידִי, לְעַם יִשְׂרָאֵל, הָעָם הַקָּדוֹשׁ."],[3,"","וְאִם תֹּאמַר, עַל דֶּרֶךְ זוֹ נְבָאֵר אֶת הַפָּסוּק, שֶׁכָּתוּב (ירמיהי) מִי לֹא יִרָאֲךְ מֶלֶךְ הַגּוֹיִם, שֶׁהֲרֵי הוּא שֵׁם שֶׁמּוֹלֵךְ עַל גּוֹיִם - אֱלֹהִים, שֶׁהֲרֵי הַיִּרְאָה שְׁרוּיָה בּוֹ וְהַדִּין שָׁרוּי בּוֹ - לֹא כָּךְ, וְלֹא עַל זֶה נֶאֱמַר. שֶׁאִם כָּךְ, אֲפִלּוּ עֲבוֹדָה זָרָה בִּכְלַל זֶה הִיא."],[4,"","אֲבָל כֵּיוָן שֶׁהַכֹּתֶל שֶׁהָיִיתָ סָמוּךְ אַחֲרָיו נֶעֱקַר, הַפָּסוּק עוֹמֵד עַל קִיּוּמוֹ בְּהִסְתַּכְּלוּת קְטַנָּה. מִי לֹא יִרָאֲךְ מֶלֶךְ הַגּוֹיִם. וְאִם תֹּאמַר שֶׁמֶּלֶךְ הַגּוֹיִם נֶאֱמַר עַל הַקָּדוֹשׁ בָּרוּךְ הוּא - לֹא כָּךְ. אֶלָּא מִי הוּא מֶלֶךְ הַגּוֹיִם שֶׁלֹּא יִרָאֲךְ, שֶׁלֹּא פוֹחֵד מִמְּךְ וְלֹא יִזְדַּעֲזַע מִמְּךְ, מִי מֶלֶךְ הַגּוֹיִם שֶׁלֹּא יִרָאֲךְ? כְּמוֹ זֶה, (תהלים קיג) הַלְלוּיָהּ הַלְלוּ עַבְדֵי ה' הַלְלוּ אֶת שֵׁם ה'. מִי שֶׁשָּׁמַע אוֹתוֹ, לֹא יוֹדֵעַ מָה אָמַר. כֵּיוָן שֶׁאָמַר הַלְלוּיָהּ, אַף כָּךְ הַלְלוּ עַבְדֵי ה'! שֶׁהָיָה לוֹ לִכְתֹּב, עַבְדֵי ה' הַלְלוּ אֶת שֵׁם ה'. אַף כָּאן הָיָה לוֹ לִכְתֹּב, מִי מִמֶּלֶךְ הַגּוֹיִם שֶׁלֹּא יִרָאֲךְ, אֶלָּא הַכֹּל עַל תִּקּוּנוֹ נִתְבָּאֵר."],[5,"","כִּי בְכָל חַכְמֵי הַגּוֹיִם וּבְכָל מַלְכוּתָם מֵאֵין כָּמוֹךְ. מָה הַדָּבָר שֶׁהִתְפַּשֵּׁט בֵּינֵיהֶם בַּחָכְמָה שֶׁלָּהֶם? מֵאֵין כָּמוֹךְ, וְכֻלָּם מוֹדִים עַל זֶה. כְּשֶׁרוֹאִים בְּחָכְמָתָם מַעֲשֶׂיךְ וּגְבוּרוֹתֶיךְ, הִתְפַּשֵּׁט דָּבָר זֶה בֵּינֵיהֶם, וְאוֹמְרִים מֵאֵין כָּמוֹךְ בְּכָל חַכְמֵי הַגּוֹיִם וּבְכָל מַלְכוּתָם. מֵאֵין כָּמוֹךְ אוֹמְרִים, וְהִתְפַּשֵּׁט בֵּינֵיהֶם. שָׂמְחוּ הַחֲבֵרִים, וּבָכוּ וְלֹא אָמְרוּ דָבָר. אַף כָּךְ הוּא בָּכָה כְּמִקֹּדֶם."],[6,"","פָּתַח וְאָמַר, (בראשית כא) וַתֹּאמֶר לְאַבְרָהָם גָּרֵשׁ הָאָמָה הַ את וְאֶת בְּנָהּ וְגוֹ'. הַחֲבֵרִים הִתְעוֹרְרוּ, שֶׁרָצְתָה שָׂרָה לְפַנּוֹת מִבֵּיתָהּ עֲבוֹדָה זָרָה, וְעַל זֶה כָּתוּב כֹּל אֲשֶׁר תֹּאמַר אֵלֶיךְ שָׂרָה שְׁמַע בְּקֹלָהּ. כָּאן כָּתוּב וְכִי יִמְכֹּר אִישׁ אֶת בִּתּוֹ - זוֹ הַנְּשָׁמָה בְּגִלְגּוּלִים עַל מַעֲשִׂים רָעִים שֶׁבָּעוֹלָם. לְאָמָה - לְאוֹתוֹ הַצַּד הָאַחֵר בְּגִלְגּוּל רַע שֶׁל הַמִּשְׁקָל שֶׁחוֹזֵר, וַהֲרֵי נֶעֶשְׁקָה לְהוֹצִיא אוֹתָהּ מִשָּׁם. וַדַּאי לֹא תֵצֵא כְּצֵאת הָעֲבָדִים, כָּל אוֹתָן נְשָׁמוֹת שֶׁנֶּעֱשָׁקוֹת."],[7,"","מִי הֵן כָּאן? הוּא סוֹד אֵלֶּה אוֹתָן נִשְׁמוֹת הַתִּינוֹקוֹת הַקְּטַנִּים, כְּשֶׁהֵם יוֹנְקִים מִתּוֹךְ תֹּקֶף שֶׁל אִמָּם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה שֶׁאִם יִתְקַיְּמוּ בָּעוֹלָם, יִבְאַשׁ רֵיחָם וְיַחֲמִיצוּ כְּמוֹ הַחֹמֶץ הַזֶּה. לוֹקֵחַ אוֹתָם קְטַנִּים, בְּעוֹדָם נוֹתְנִים רֵיחַ."],[8,"","מָה עוֹשֶׂה? מַשְׁאִיר אוֹתָם לְהֵעָשֵׁק בְּיַד אוֹתָהּ הָאָמָה, וְזוֹהִי לִילִי\"ת. שֶׁכֵּיוָן שֶׁנִּתְּנוּ בִּרְשׁוּתָהּ, שְׂמֵחָה (אוחזת) בְּאוֹתוֹ תִינוֹק וְעוֹשֶׁקֶת אוֹתוֹ, וּמוֹצִיאָה אוֹתוֹ מִן הָעוֹלָם כְּשֶׁהוּא יוֹנֵק מִכֹּחַ אִמּוֹ."]]],[["וְאִי תֵּימָא, אִינּוּן נִשְׁמָתִין דְּיַעַבְדוּן טַב לְעָלְמָא. לָאו הָכִי. דִּכְתִּיב אִם רָעָה בְּעֵינֵי אֲדֹנֶיהָ, דְּיַחֲמִיץ הַהוּא גַּבְרָא בָּהּ לְבָתַר יוֹמִין, אִי אִתְקַיַּים בָּהּ. דָּא אִתְעַשְׁקַת, וְאַחֲרָא לָא אִתְעַשְּׁקַת. וְעַל אִלֵּין כְּתִיב, (קהלת ד׳:א׳) וָאֶרְאֶה אֶת כָּל הָעֲשׁוּקִים וְגוֹ' וְהַיְינוּ אִם רָעָה בְּעֵינֵי אֲדֹנֶיהָ.","אֲשֶׁר לֹא יְעָדָהּ, לֹא בְּאָלֶף כְּתִיב. אִי תֵּימָא, דְּהָא בְּהַהוּא סִטְרָא אַחֲרָא, אַזְמִין לָהּ קוּדְשָׁא בְּרִיךְ הוּא מִיּוֹמָא דַּהֲוַת. לָא. וְהַשְׁתָּא בְּגִלְגּוּלֵי טִיקְלָא, לוֹ יְעָדָהּ בְּוָא\"ו. מַה דְּלָא הֲוַת מִקַּדְמַת דְּנָא.","וְהֶפְדָּהּ, מַאי וְהֶפְדָּהּ. פָּרִיק לָהּ קוּדְשָׁא בְּרִיךְ הוּא הַשְׁתָּא, דְּסַלְּקָא רֵיחָא, עַד לָא תַּחֲמִיץ, וְסָלִיק לָהּ לְרוּמֵי מְרוֹמִים, (קי\"ג ע\"ב) בִּמְתִיבְתָּא דִּילֵיהּ, וְאִי תֵּימָא כֵּיוָן דְּאִתְעַשְּׁקָת מֵהַהוּא סִטְרָא אַחֲרָא, יָהִיב לָהּ, כְּמָה דְּאָמְרוּ לַחֲסִידֵי (ר\"ה ע\"ב) שְׁאַר עַמִּין, וּלְאִינּוּן מַמְזְרֵי תָּא חֲזֵי. אָתָא קְרָא וְאוֹכַח, לְעַם נָכְרִי לֹא יִמְשׁוֹל לְמָכְרָהּ וַדַּאי, בְּבִגְדוֹ בָהּ, דְּעָשִׁיק לָהּ בַּעֲשִׁיקוּ דְּגִלְגּוּלָא דְּטִיקְלָא, אֶלָּא לְיִשְׂרָאֵל וַדַּאי, וְלָא לְאַחֲרָא. וְכַד נַפְקַת מִן טִיקְלָא, לֹא תֵצֵא כְּצֵאת הָעֲבָדִים, אֶלָּא מִתְעַטְּרָא בְּעִטְּרָהָא בַּאֲרָמָא עַל רֵישֵׁיהּ.","וְאִי תֵּימָא, דְּהַאי סִטְרָא עָאלַת לָהּ בְּהַהוּא יַנּוּקָא. לָאו הָכִי. אֶלָּא נַטְלַת לָהּ, וְחַדָּאת בַּהֲדָהּ, וּפַרְחַת מִן יְדָהָא, וְעָאלַת בְּהַהוּא אֲתָר, וְאִיהִי פְּקִידַת לְהַהוּא יְנוֹקָא, וְחַדָּאת בֵּיהּ, וְחַיְּיכַת בֵּיהּ, וְתָאִיבַת (נ\"ח, ס\"ה ע\"א) לְהַהוּא בָּשָׂר, עַד דִּלְבָתַר נָטִיל קוּדְשָׁא בְּרִיךְ הוּא נִשְׁמָתֵיהּ, וְהִיא לְגוּפָא. וּלְבָתַר כֹּלָּא אִיהוּ בִּרְשׁוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא.","תָּא חֲזֵי, (שמות כ״א:ז׳) לא תֵצֵא כְּצֵאת הָעֲבָדִים, מַאי הוּא. אֶלָּא, בְּשַׁעֲתָא דְּנַפְקַת מִן טִיקְלָא וְהַהוּא סִטְרָא בְּחֵדוּ, רָשִׁים לָהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, וְחָתִים לָהּ בְּחַד גּוּשְׁפַּנְקָא, וּפָרִישׂ עָלָהּ לְבוּשׁ יְקָר דִּילֵיהּ, וּמַאן אִיהוּ. שְׁמָא קַדִּישָׁא דְּאִקְרֵי אֱלוֹהַּ. וְדָא הוּא בְּבִגְדוֹ בָהּ, לְבוּשָׁא יַקִּירָא דְּמַלְכָּא פָּרִישׂ עָלָהּ וּכְדֵין אִיהִי נְטִירָא, דְּלָא אִתְמַסְּרַת לְעַם נָכְרִי, אֶלָּא לְיִשְׂרָאֵל לְחוּד.","וְדָא אִיהוּ דִּכְתִּיב, (איוב כ״ט:ב׳) כִּימֵי אֱלוֹהַּ יִשְׁמְרֵנִי, וְעַל רָזָא דָּא כְּתִיב הָכָא, לְעַם נָכְרִי לֹא יִמְשֹׁל לְמָכְרָהּ בְּבִגְדוֹ בָהּ, בְּעוֹד דִּלְבוּשׁ יְקָר דְּמַלְכָּא בָּהּ. כֵּיוָן (בראשית צ\"ד ע\"א, שמות קע\"ב ע\"ב, ויקרא ע\"ב ע\"ב) דְּבִגְדוֹ בָהּ, כְּתִיב לְעַם נָכְרִי לֹא יִמְשֹׂל לְמָכְרָהּ.","מַה רְשׁוּ אִית לְהַהוּא סִטְרָא בָּהּ. תָּא חֲזֵי, כָּל בְּנֵי עָלְמָא כֻּלְּהוּ, בִּרְשׁוּתֵיהּ דְּמַלְכָּא קַדִּישָׁא, וְכֻלְּהוּ אִית לוֹן זִמְנָא בְּהַאי עָלְמָא, עַד דְּאִיהוּ בָּעֵי לְסַלְּקָא לוֹן מִן עָלְמָא, וְדָא לֵית לֵיהּ זִמְנָא, וְעַל דָּא אִיהִי חַיְיכָת בְּהוּ, וְחַדָּאת בְּהוּ.","תּוּ, אַזְהָרוּתָא לְבַר נָשׁ (בהאי עלמא) אִית בְּהָנֵי קְרָאֵי, וְכַמָּה עֵיטִין טָבִין עִלָּאִין אִינּוּן, בְּכָל מִילֵי דְּאוֹרַיְיתָא, וְכֻלְּהוּ קְשׁוֹט, בְּאֹרַח קְשׁוֹט, וְאִשְׁתְּמוֹדְעָן לְגַבֵּי חַכִּימִין, דְּיַדְעֵי וְאַזְלֵי בְּאֹרַח קְשׁוֹט. בְּזִמְנָא דְּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְמִבְרֵי עָלְמָא, סָלִיק בִּרְעוּתָא קָמֵיהּ, וְצִיֵּיר כָּל נִשְׁמָתִין דְּאִינּוּן זְמִינִין לְמֵיהָב בִּבְנִי נָשָׁא לְבָתַר, וְכֻלְּהוּ אִתְצְיָּירוּ קָמֵיהּ בְּהַהוּא צִיּוּרָא מַמָּשׁ, דִּזְמִינִין לְמֶהֱוֵי בִּבְנִי נָשָׁא לְבָתַר, וְחָמָא כָּל חַד וְחַד.","וְאִית מִנְּהוֹן דִּזְמִינִין לְאַבְאָשָׁא אָרְחַיְיהוּ בְּעָלְמָא, וּבְשַׁעֲתָא דְּמָטָא זִמְנַיְיהוּ, קָרֵי קוּדְשָׁא בְּרִיךְ הוּא לְהַהִיא נִשְׁמְתָא, אָמַר לָהּ, זִילִי עוּלִי בְּדוֹךְ פְּלָן. בְּגוּף פְּלָן. אָתִיבַת קָמֵיהּ, מָארֵיהּ דְּעָלְמָא, דַּי לִי בְּעָלְמָא דָּא דַּאֲנָא יָתְבָא בֵּיהּ, וְלָא אֵיהָךְ לְעָלְמָא אַחֲרָא, דְּיִשְׁתַּעְבְּדוּן בִּי, וְאֵהֶא מְלוּכְלְכָא בֵּינַיְיהוּ. אָמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא, מִן יוֹמָא דְּאִתְבְּרִיאַת, עַל דָּא אִתְבְּרִיאַת לְמֶהוֵי בְּהַהוּא עָלְמָא. כֵּיוָן דְּחָמָאת נִשְׁמְתָא כַּךְ, בְּעַל כָּרְחָהּ נַחְתַּת וְעָאלַת תַּמָּן.","אוֹרַיְיתָא דְּיָהִבַת עֵיטָא לְכָל עָלְמָא חָמָאת הָכִי, אַזְהִירַת לִבְנֵי עָלְמָא, וְאַמְרַת, חָמוּ כַּמָּה חָס קוּדְשָׁא בְּרִיךְ הוּא עָלַיְיכוּ, מַרְגָּלִיתָא טָבָא דַּהֲוַת לֵיהּ, זַבִּין לְכוּ לְמַגָּנָא, דְּתִשְׁתַּעְבְּדוּן בָּהּ בְּהַאי עָלְמָא."],[[0,"ואי תימא אינון וכו':","ואם תאמר, שאלו הנשמות יעשו טוב בעולם, אינו כן, שכתוב, אם רעה בעיני אדניה, כי איש הזה יוחמץ בה לאחר זמן, אם יתקיים בה. נשמה זו נעשקת, ואחרת אינה נעשקת, ועל אלו כתוב, ואראה את כל העשוקים וגו'. והיינו אם רעה בעיני אדניה."],[1,"אשר לא יעדה:","לא כתוב עם \u0003א'.\u0004 אם תאמר שבצד האחר ההוא נתן אותה הקב\"ה מיום שהיתה. לא. כי עתה בגלגולי המאזנים לו יעדה, לו עם \u0003ו',\u0004 מה שלא היה מקודם לכן."],[2,"והפדה, מאי והפדה וכו':","כתוב והפדה, מהו והפדה. ומשיב, פודה אותה הקב\"ה עתה, בעוד שמעלית ריח טוב, מטרם שתחמץ, ומעלה אותה לגבהי מרומים אל הישיבה שלו. ואם תאמר, כיון שנעשקה בידי צד האחר ההוא, נותן אותה, כמו שאמרו, (לעיל אות ל\"א) לחסידי שאר העמים ולממזרים תלמידי חכמים בא הכתוב, ומוכיח, לעם נכרי לא ימשול למכרה ודאי, בבגדו בה, שעשק אותה בעושק גלגול המאזנים, אלא יתן אותה ודאי לישראל ולא לאחר. וכשיוצאת מן המאזנים, לא תצא כצאת העבדים אלא מתעטרית בעטרה ברמה על ראשה."],[3,"ואי תימא דהאי וכו':","ואם תאמר, שצד ההוא באה בילד ההוא, כלומר שיש לה שליטה בנשמתו. אינו כן, אלא לוקחת אותה ושמחה עמה, והיא פורחת מן ידיה ונכנסת במקום ההוא של הס\"א והיא פוקדת את הילד ההוא, ושמחה עמו וצוחקת בו, ומתאוית לבשר ההוא, עד שלאחר כך לוקח הקב\"ה נשמתו, והיא לוקחת גופו. ולאחר כך הכל הוא ברשות הקב\"ה."],[4,"ת\"ח לא תצא כצאת העבדים:","שואל מהו כצאת העבדים. ומשיב, אלא בשעה שיוצאת מן המאזנים וצד ההוא, בשמחה, רושם אותה הקב\"ה וחותם אותה בטבעת אחת, ופורש עליה לבוש יקר שלו, ומי הוא. הוא השם הקדוש הנקרא \u0003אלוה\u0004. וזה הוא בבגדו בה, דהיינו לבוש יקר של המלך פורש עליה, ואז היא שמורה שלא תהיה נמסרת לעם נכרי, דהיינו לחסידי אומות העולם ולממזרים תלמידי חכמים כנ\"ל, אלא לישראל בלבד."],[5,"ודא איהו דכתיב וכו':","וזהו שכתוב, כימי אלוה ישמרני. דהיינו הלבוש יקר שנקרא אלוה כנ\"ל. ועל סוד הזה כתוב כאן, לעם נכרי לא ימשול למכרה בבגדו בה, דהיינו בעוד שלבוש יקר של המלך בה. כיון דבגדו בה, ע\"כ כתוב, לעם נכרי לא ימשול למכרה."],[6,"מה רשו אית וכו':","שואל, מהו הרשות שיש לצד ההוא באותה הנשמה. כי אמר לעיל אות מ\"ג שהקב\"ה נותן רשות לס\"א לעשוק הנשמה. ומשיב, בוא וראה, כל בני העולם כולם הם ברשות המלך הקדוש, שכולם יש להם זמן לחיות בעולם הזה, עד שהוא רוצה להעלותם מן העולם ואין רשות לס\"א לפגוע בהם לפני הזמן. וזו, אין לה זמן קצוב לחיות בו, וע\"כ היא צוחקת בה ושמחה בה ומוציאה אותה מן העולם. נמצא שבזה שלא ניתן לה זמן, ניתנה רשות לס\"א לעשוק אותה."],[7,"תו, אזהרותא לבר וכו':","עוד, יש הזהרות לבני אדם במקראות אלו, וכמה עצות טובות עליונות הם בכל דברי התורה, וכולם אמת בדרך אמת, ונודעות לחכמים היודעים והולכים בדרך אמת. בזמן, שרצה הקב\"ה לברוא העולם, עלה ברצון לפניו, וצייר כל הנשמות העתידות להנתן בבני אדם אחר כך, וכולן נצטיירו לפניו בצורה ההיא ממש שעתידות להיות אחר כך בבני אדם, וראה כל אחת ואחת."],[8,"ואית מנהון דזמינין וכו':","ויש מהן שעתידות להרע דרכיהם בעולם, ובשעה שהגיע זמנם לרדת לעולם קורא הקב\"ה לנשמה ההיא, אמר לה, לכי בואי במקום פלוני בגוף פלוני. השיבה לפניו, רבון העולם, די לי עולם הזה שאני יושבת בו, ולא אלך לעולם אחר, שיעבדו בי ואהיה מלוכלכת ביניהם. אמר לה הקב\"ה, מיום שנבראת על זה נבראת להיות בעולם ההוא, בגוף. כיון שהנשמה רואה כך, יורדת בעל כרחה ונכנסת שם בגוף."],[9,"אורייתא דיהבת עיטא וכו':","התורה שנותנת עצה לכל העולם שרואית כן, היא מזהירה לבני העולם ואמרת, ראו כמה מרחם הקב\"ה עליכם. מרגלית טובה שהיה לו, דהיינו הנשמה מכר אותה בחנם שתעבדו בה בעולם הזה."]],[[0,"","וְאִם תֹּאמַר שֶׁאוֹתָן נְשָׁמוֹת יַעֲשׂוּ טוֹב לָעוֹלָם - לֹא כָּךְ, שֶׁכָּתוּב אִם רָעָה בְּעֵינֵי אֲדנֶיהָ, שֶׁיַּחֲמִיץ אוֹתוֹ הָאִישׁ בָּהּ לְאַחַר יָמִים, אִם יִתְקַיֵּם בָּהּ. זוֹ נֶעֱשֶׁקֶת, וְאַחֶרֶת לֹא נֶעֱשֶׁקֶת, וְעַל אֵלֶּה כָּתוּב, (קהלת ד) וָאֶרְאֶה אֶת כָּל הָעֲשׁוּקִים וְגוֹ', וְהַיְנוּ אִם רָעָה בְּעֵינֵי אֲדנֶיהָ."],[1,"","אֲשֶׁר לֹא יְעָדָהּ. לֹא - כָּתוּב בְּאָלֶ\"ף. אִם תֹּאמַר שֶׁהֲרֵי בְּאוֹתוֹ הַצַּד הָאַחֵר הִזְמִין לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא מִיּוֹם שֶׁהָיְתָה - לֹא! וְעַכְשָׁו בְּגִלְגּוּלֵי הַמֹּאזְנַיִם - לוֹ יְעָדָהּ, בְּוָא\"ו, מַה שֶּׁלֹּא הָיָה מִקֹּדֶם לָכֵן."],[2,"","וְהֶפְדָּהּ, מַה זֶּה וְהֶפְדָּהּ? גָּאַל אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא עַכְשָׁו, שֶׁמַּעֲלָה רֵיחַ, טֶרֶם שֶׁתַּחֲמִיץ, וּמַעֲלֶה אוֹתָהּ לְרוּמֵי מְרוֹמִים בַּיְשִׁיבָה שֶׁלּוֹ. וְאִם תֹּאמַר, כֵּיוָן שֶׁנֶּעֶשְׁקָה מֵאוֹתוֹ הַצַּד הָרָע, נוֹתֵן אוֹתָהּ, כְּמוֹ שֶׁאָמְרוּ לַחֲסִידֵי אֻמּוֹת הָעוֹלָם וּלְאוֹתָם מַמְזֵרִים תַּלְמִידֵי חֲכָמִים - בָּא הַכָּתוּב וּמוֹכִיחַ, לְעַם נָכְרִי לֹא יִמְשֹׁל לְמָכְרָהּ, וַדַּאי, בְּבִגְדוֹ בָהּ, שֶׁעוֹשֵׁק אוֹתָהּ בָּעֹשֶׁק שֶׁל גִּלְגּוּל הַמֹּאזְנַיִם, אֶלָּא לְיִשְׂרָאֵל וַדַּאי, וְלֹא לְאַחֵר. וּכְשֶׁיּוֹצֵאת מִן הַמֹּאזְנַיִם, לֹא תֵצֵא כְּצֵאת הָעֲבָדִים, אֶלָּא מִתְעַטֶּרֶת בַּעֲטַרְתָּהּ בַּהֲרָמַה עַל רֹאשָׁהּ."],[3,"","וְאִם תֹּאמַר שֶׁהַצַּד הַזֶּה הִכְנִיס אוֹתוֹ לְאוֹתוֹ תִינוֹק - לֹא כָּךְ, אֶלָּא נוֹטֶלֶת אוֹתָהּ וּשְׂמֵחָה עִמָּהּ וּפוֹרַחַת מִיָּדָהּ וְנִכְנֶסֶת לְאוֹתוֹ מָקוֹם, וְהִיא פּוֹקֶדֶת אֶת אוֹתוֹ תִינוֹק וּשְׂמֵחָה בּוֹ וְצוֹחֶקֶת בּוֹ, וּתְאֵבָה אֶת אוֹתוֹ הַבָּשָׂר, עַד שֶׁאַחַר כָּךְ נוֹטֵל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת נִשְׁמָתוֹ, וְהִיא לַגּוּף. וְאַחַר כָּךְ הַכֹּל בִּרְשׁוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא."],[4,"","בֹּא וּרְאֵה, לֹא תֵצֵא כְּצֵאת הָעֲבָדִים, מַה זֶּה? אֶלָּא בְּשָׁעָה שֶׁיּוֹצֵאת מִן הַמֹּאזְנַיִם וְאוֹתוֹ הַצַּד בְּשִׂמְחָה, רוֹשֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא וְחוֹתֵם אוֹתָהּ בְּחוֹתֶמֶת אַחַת, וּפוֹרֵס עָלֶיהָ לְבוּשׁ כָּבוֹד שֶׁלּוֹ, וּמִיהוּ? הַשֵּׁם הַקָּדוֹשׁ שֶׁנִּקְרָא אֱלוֹהַּ. וְזֶהוּ בְּבִגְדוֹ בָהּ, הַלְּבוּשׁ הַנִּכְבָּד שֶׁל הַמֶּלֶךְ פּוֹרֵשׂ עָלֶיהָ, וְאָז הִיא שְׁמוּרָה, שֶׁלֹּא נִמְסְרָה לְעַם נָכְרִי אֶלָּא לְיִשְׂרָאֵל לְחוּד."],[5,"","וְזְהִוּ שֶׁכָּתוּב (איוב כטו) כִּימֵי אֱלוֹהַּ יִשְׁמְרֵנִי, וְעַל סוֹד זֶה כָּתוּב כָּאן, לְעַם נָכְרִי לֹא יִמְשֹׁל לְמָכְרָהּ בְּבִגְדוֹ בָהּ, בְּעוֹד שֶׁלְּבוּשׁ כְּבוֹד הַמֶּלֶךְ בָּהּ. כֵּיוָן שֶׁבִּגְדוֹ בָהּ, כָּתוּב לְעַם נָכְרִי לֹא יִמְשֹׁל לְמָכְרָהּ."],[6,"","מָה רְשׁוּת יֵשׁ לְאוֹתוֹ צַד בָּהּ? בֹּא וּרְאֵה, כָּל בְּנֵי הָעוֹלָם כֻּלָּם בִּרְשׁוּת הַמֶּלֶךְ הַקָּדוֹשׁ, וּלְכֻלָּם יֵשׁ זְמַן בָּעוֹלָם הַזֶּה, עַד שֶׁהוּא רוֹצֶה לְסַלְּקָם מִן הָעוֹלָם, וְזֶה אֵין לוֹ זְמַן, וְעַל כָּךְ הִיא צוֹחֶקֶת בָּהֶם וּשְׂמֵחָה בָהֶם."],[7,"","עוֹד, אַזְהָרָה לָאָדָם (בעולם הזה) יֵשׁ בַּפְּסוּקִים הַלָּלוּ וְכַמָּה עֵצוֹת טוֹבוֹת עֶלְיוֹנוֹת הֵן בְּכָל דִּבְרֵי הַתּוֹרָה, וְכֻלָּן אֱמֶת בְּדֶרֶךְ אֱמֶת, וְנוֹדָעוֹת לַחֲכָמִים שֶׁיּוֹדְעִים וְהוֹלְכִים בְּדֶרֶךְ אֱמֶת. בִּזְמַן שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אֶת הָעוֹלָם, עָלָה בְרָצוֹן לְפָנָיו, וְצִיֵּר אֶת כָּל הַנְּשָׁמוֹת שֶׁהֵן עֲתִידוֹת לְהִנָּתֵן בִּבְנֵי אָדָם אַחַר כָּךְ, וְכֻלָּן הִצְטַיְּרוּ לְפָנָיו בְּאוֹתוֹ צִיּוּר מַמָּשׁ שֶׁעֲתִידִים לִהְיוֹת בְּנֵי אָדָם לְאַחַר מִכֵּן, וְרָאָה כָּל אֶחָד וְאֶחָד."],[8,"","וְיִשִׁ מֵהֶן שֶׁעֲתִידוֹת לְהָרַע אֶת דַּרְכֵיהֶן בָּעוֹלָם, וּבְשָׁעָה שֶׁמַּגִּיעַ זְמַנָּן, קוֹרֵא הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתָהּ נְשָׁמָה וְאוֹמֵר לָהּ: לְכִי וְהִכָּנְסִי בְּמָקוֹם פְּלוֹנִי לְגוּף פְּלוֹנִי. וְהִיא מְשִׁיבָה לְפָנָיו: רִבּוֹן הָעוֹלָם, דַּי לִי בָּעוֹלָם הַזֶּה שֶׁאֲנִי יוֹשֶׁבֶת בּוֹ, וְלֹא אֵלֵךְ לְעוֹלָם אַחֵר שֶׁיִּשְׁתַּעְבְּדוּ בִי וְאֶהְיֶה מְלֻכְלֶכֶת בֵּינֵיהֶם. אוֹמֵר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא: מִיּוֹם שֶׁנִּבְרֵאת, עַל מְנָת כֵּן נִבְרֵאת, לִהְיוֹת בְּאוֹתוֹ עוֹלָם. כֵּיוָן שֶׁרוֹאָה הַנְּשָׁמָה כָּךְ, בְּעַל כָּרְחָהּ יוֹרֶדֶת וְנִכְנֶסֶת לְשָׁם."],[9,"","הַתּוֹרָה שֶׁנּוֹתֶנֶת עֵצָה לְכָל הָעוֹלָם רוֹאָה כָּךְ, וּמַזְהִירָה אֶת בְּנֵי הָעוֹלָם וְאוֹמֶרֶת: רְאוּ כַּמָּה חָס הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיכֶם. מַרְגָּלִית טוֹבָה שֶׁהָיְתָה לוֹ, מָכַר לָכֶם בְּחִנָּם כְּדֵי שֶׁתִּשְׁתַּעְבְּדוּ בָהּ בָּעוֹלָם הַזֶּה."]]],[["וְכִי יִמְכֹּר אִישׁ: דָּא קוּדְשָׁא בְּרִיךְ הוּא. אֶת בִּתּוֹ: דָּא נִשְׁמְתָא קַדִּישָׁא. לְאָמָה: לְמֶהֱוֵי אָמָה מִשְׁתַּעְבְּדָא בֵּינַיְיכוּ בְּהַאי עָלְמָא. בְּמָטוּ מִנַּיְיכוּ, בְּשַׁעֲתָא דְּמָטֵי זִמְנָא לְנָפְקָא מֵהַאי עָלְמָא, לֹא תֵצֵא כְּצֵאת הָעֲבָדִים, לָא תִּפּוּק מִתְטַנְּפָא בְּחוֹבִין, תִּפּוּק בַּת חוֹרִין, בְּרִירָה נְקִיָּה, בְּגִין דְּיֶחֱדֵי בָּהּ מָארָהּ וְיִשְׁתָּבַּח בָּהּ וְיָהִיב לָהּ אֲגַר טָב, בְּצִחְצוּחֵי דְּגִנְתָּא דְּעֵדֶן. כְּמָה דְאַתְּ אָמֵר (ישעיהו נ״ח:י״א) וְהִשְׁבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךָ, וַדַּאי כַּד תִּפּוּק בְּרִירָה נְקִיָּה כְּדְקָא יֵאוֹת.","אֲבָל אִם רָעָה בְּעֵינִי אֲדֹנֶיהָ, כַּד נַפְקַת מְלוּכְלָכָא בְּטִנוּפֵי חוֹבִין, וְלָא אִתְחֲזִיאַת קָמֵיהּ כְּדְקָא יֵאוֹת, וַוי לְהַהוּא גּוּפָא, דְּאִתְאֲבִיד מֵהַהִיא נִשְׁמְתָא לְעָלְמִין. בְּגִין, דְּכַד נִשְׁמָתִין סַלְּקִין בְּרִירָן, וְנָפְקִין נְקִיִּין מֵהַאי עָלְמָא, כָּל נִשְׁמְתָא וְנִשְׁמְתָא, עָאלַת בְּסִפְרָא (שלח קנ\"ו ע\"ב) דְּאַחְמָתָא דְּמַלְכָּא, וְכֻלְּהוּ בִּשְׁמָהָן, וְאָמַר דָּא הִיא נִשְׁמְתָא דִּפְלַנְיָא, זְמִינַת תְּהֵא לְהַהוּא גּוּפָא דְּשַׁבְקַת, וּכְדֵין כְּתִיב, לוֹ יְעָדָהּ, בְּו'.","וְכַד נַפְקַת רָעָה בְּעֵינֵי אֲדֹנֶיהָ, דְּקָא אִסְתְּאָבַא בְּחוֹבִין, וּבְטִנּוּפָא דְּחַטָּאִין, כְּדֵין לא יְעָדָהּ בְּא'. וְאִתְאֲבִיד הַהוּא גּוּפָא מִינָהּ וְאִיהִי לָא אִזְדַּמְּנַת לְגַבֵּיהּ בַּר הַהִיא דְּמָארָהּ אִתְרְעֵי, וְתָב בְּתִיוּבְתָּא דְּגוּפָא בָּהּ, כְּדֵין כְּתִיב, וְהֶפְדָּה. כְּמָה דְאַתְּ אָמֵר (איוב לג) פָדָה נַפְשׁוֹ מֵעֲבוֹר בַּשָּׁחַת. וְהֶפְדָּהּ, הַאי אִיהוּ בְּבַר נָשׁ, דְּעֵיטָא דִּילֵיהּ, דְּיִפְרוֹק לָהּ, וְיֵתוּב בְּתִיוּבְתָּא, וְלִתְרֵין סִטְרִין קָאָמַר קוּדְשָׁא בְּרִיךְ הוּא, וְהֶפְדָהּ בְּתִיוּבְתָּא. לְבָתַר דְּתָב בְּתִיוּבְתָּא, פָּדָא לָהּ מֵאָרְחָא דְּגֵיהִנָּם.","לְעַם נָכְרִי לֹא יִמְשֹׁל לְמָכְרָהּ. מַאן עַם נָכְרִי. עֲלוּבָתָא אִיהִי נִשְׁמְתָא, דְּכַד נַפְקַת מֵעָלְמָא, וּבַר נָשׁ אַסְטֵי אָרְחֵיהּ בַּהֲדָהּ, הִיא בָּעָאת לְסַלְּקָא לְעֵילָּא, גּוֹ מַשְׁרְיָין קַדִּישִׁין, בְּגִין דְּמַשְׁרְיָין קַדִּישִׁין קַיְימִין בְּהַהוּא אָרְחָא דְגַּן עֵדֶן, וּמַשְׁרְיָין נוּכְרָאִין קַיְימִין בְּהַהוּא אָרְחָא דְּגֵיהִנָּם.","זָכְתָה נִשְׁמְתָא, וְהַהוּא נְטִירוּ, וּפְרִישׂוּ דִּלְבוּשָׁא יַקִּירָא עָלָהּ. כַּמָּה מַשְׁרְיָין קַדִּישִׁין, קָא מִתְעַתְּדָן לָהּ, לְאִתְחַבְּרָא בַּהֲדָהּ, וּלְמֵיעָאל לָהּ לְגַּן עֵדֶן. לֹא זָכְתָה, כַּמָּה מַשְׁיירְיָן נוּכְרָאִין מִתְעַתְּדָן לְמֵיעַל לָהּ בְּאָרְחָא דְּגֵיהִנָּם. וְאִינּוּן מַשְׁרְיָין דְּמַלְאֲכֵי חַבָּלָה זְמִינִין לְמֶעְבַּד בָּהּ נוּקְמִין, אָתָא קְרָא וְאוֹכַח, לְעַם נָכְרִי לא יִמְשֹׂל לְמָכְרָהּ, אִלֵּין מַלְאֲכֵי חַבָּלָה. בְּבִגְדוֹ בָהּ, אִיהוּ נְטִירָא, דְּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד לָהּ נְטִירָא, דְּלָא יִשְׁלוֹט בָּהּ עַם נָכְרִי, בְּהַהוּא פְּרִיסוּ דִּנְטִירוּ עָלָּה.","(שמות כ״א:ט׳) וְאִם לִבְנוֹ יִיעָדֶנָּה, תָּא חֲזֵי כַּמָּה אִית לֵיהּ לְּבַּר נָשׁ לְאִזְדַּהֲרָא דְּלָא יִסְטֵי אָרְחוֹי בְּהַאי עָלְמָא, דְּאִי זָכָה בַּר נָשׁ בְּהַאי עָלְמָא, וְנָטִיר לָהּ לְנִשְׁמְתָא כְּדְקָא יֵאוֹת, הַאי אִיהוּ בַּר נָשׁ דְקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בֵּיהּ, וְאִשְׁתָּבַח בֵּיהּ בְּכָל יוֹמַיָּא, בְּפָמַלְיָיא דִּילֵיהּ, וְאָמַר, חֲמוּ בְּרָא קַדִּישָׁא דְּאִית לִי בְּהַהוּא עָלְמָא, כַּךְ וְכָךְ עָבִיד, כַּךְ וְכָךְ עוֹבָדוֹי מִתְתַּקְּנָן.","וְכַד הַאי נִשְׁמְתָא, נַפְקַת מְהַאי עָלְמָא, זַכְיָיא נְקִיָּיה בְּרִירָה, קוּדְשָׁא בְּרִיךְ הוּא אַנְהִיר לָהּ בְּכַמָּה נְהוֹרִין, בְּכָל יוֹמָא קָארֵי עָלָהּ, דָּא הִיא נִשְׁמְתָא דִּפְלַנְיָא בְּרִי, נְטִירָא לִיהֲוִי לֵיהּ לְהַהוּא גּוּפָא דְּשָׁבַק.","וְדָא הוּא דִּכְתִּיב, וְאִם לִבְנוֹ יִיעָדֶנָּה כְּמִשְׁפַּט הַבָּנוֹת יַעֲשֶׂה לָּהּ, מַאי כְּמִשְׁפַּט הַבָּנוֹת. הָכָא אִית רָזָא לְחַכִּימִין, בְּגוֹ טִנָרָא תַּקִּיפָא, רְקִיעָא טְמִירָא, אִית הֵיכָלָא חֲדָא, דְּאִקְרֵי הֵיכַל אַהֲבָה. (קמ\"ו ע\"א) וְתַמָּן אִינּוּן גִּנְזִין טְמִירִין, וְכָל נְשִׁיקִין דִּרְחִימוּ דְמַלְכָּא אִינּוּן תַּמָּן, וְאִינּוּן נִשְׁמָתִין רְחִימָאן דְּמַלְכָּא עָאלִין תַּמָּן.","כֵּיוָן דְּמַלְכָּא עָאל בְּהַהוּא הֵיכָלָא דְּמַלְכָּא, תַּמָּן כְּתִיב, (בראשית כ״ט:י״א) וַיִּשַּׁק יַעֲקֹב לְרָחֵל, וְקוּדְשָׁא בְּרִיךְ הוּא אַשְׁכַּח תַּמָּן לְהַהִיא נִשְׁמְתָא קַדִּישָׁא, קָדִים מִיַּד וְנָשִׁיק לָהּ, וְגָפִיף לָהּ, וְסָלִיק לָהּ בַּהֲדֵיהּ, וְאִשְׁתַּעֲשַׁע בָּהּ.","וְדָא הוּא כְּמִשְׁפַּט הַבָּנוֹת יַעֲשֶׂה לָהּ, כְּדִינָא דְּאַבָּא עָבִיד לִבְרַתֵיהּ, דְּאִיהִי חֲבִיבָא לְגַבֵּיהּ, דְּנָשִׁיק לָהּ, וְגָפִיף לָהּ, וְיָהִיב לָהּ מַתְנָן. כַּךְ קוּדְשָׁא בְּרִיךְ הוּא עָבִיד, לְנִשְׁמְתָא זַכָּאָה בְּכָל יוֹמָא, כְּמָה דְּכְתִּיב כְּמִשְׁפַּט הַבָּנוֹת יַעֲשֶׂה לָהּ.","הַיְינוּ דְּכְתִּיב (ישעיהו ס״ד:ג׳) יַעֲשֶׂה לִמְחַכֵּה לוֹ, כְּמָה דְּהַאי בְּרַתָא, אַשְׁלִימַת עֲשִׂיָּיה בְּהַאי עָלְמָא. אוּף הָכִי קוּדְשָׁא בְּרִיךְ הוּא אַשְׁלִים לָהּ עֲשִׂיָּיה אַחֲרָא בְּעַלְמָא דְּאָתֵי, דְּכְתִּיב, עַיִן לא רָאָתָה אֱלהִים זוּלָתְךָ יַעֲשֶׂה לִמְחַכֵּה לוֹ. וְהָכָא כְּתִיב יַעֲשֶׂה לָהּ. עַל כֵּן. הַהוּא סָבָא אִשְׁתָּטַּח, וְצַלֵּי צְלוֹתָא. בָּכָה כְּמִלְקַדְּמִין."],[[0,"וכי ימכר איש:","זה הקב\"ה. \u0003את בתו,\u0004 זו היא נשמה הקדושה. \u0003לאמה,\u0004 להיות אמה משועבדת ביניכם בעולם הזה. בבקשה מכם, שבשעה שיגיע זמנה לצאת מעולם הזה, לא תצא כצאת העבדים, לא תצא מטונפת בעונות, תצא בת חורין ברורה ונקיה, כדי שישמח בה אדונה, וישתבח בה, ויתן לה שכר טוב בצחצחות שבגן עדן. כש\"א והשביע בצחצחות נפשך. זה ודאי כשתצא הנשמה ברורה ונקיה כראוי."],[1,"אבל אם רעה וכו':","אבל אם רעה בעיני אדניה, כשיוצאת מלוכלכת בטנוף של עבירות, ואינה נראית לפניו כראוי, אוי לגוף ההוא שנאבד מנשמה ההיא לעולם. משום כשהנשמות עולות ברורות ויוצאות נקיות מעולם הזה, כל נשמה ונשמה נכנסת בספר שבחמת המלך. אחמתא פירושו חמת, היינו כיס עור שמניחים בו ספרים ושטרות וניירות. וכולן נקובות בשמות, ואמר זו היא הנשמה של פלוני תהיה נועדת לגוף ההוא שעזבה. ואז כתוב, אשר לו יעדה. עם ו'."],[2,"וכד נפקת רעה וכו':","וכשיוצאת רעה בעיני אדניה, כי נטמאה בעונות ובטנוף של חטאים, אז לא יעדה, עם א', כתוב, ונאבד גוף ההוא ממנה, והיא לא נועדת לו. חוץ מנשמה ההיא שאדונה רוצה בה, שהגוף חזר בו בתשובה אז כתוב, \u0003והפדה,\u0004 כמש\"א, פדה נפשו מעבור בשחת. והפדה, זה סובב על האדם, שהעצה שלו הוא, שיפדה אותה וישוב בתשובה. ולב' צדדים אומר הכתוב והפדה, א' על הקב\"ה, והפדה מגיהנם. ב' על האדם, והפדה בתשובה, לאחר שחזר בתשובה, פודה אותם הקב\"ה מדרך הגיהנם."],[3,"לעם נכרי לא ימשול למכרה:","שואל, מי הוא עם נכרי. ומשיב, נכלמת היא הנשמה, כשיוצאת מן העולם, והאדם נטה מן הדרך, עמה. היא מבקשת לעלות למעלה לתוך המחנות הקדושות. כי מחנות קדושים עומדים בדרך ההוא של גן העדן, ומחנות נכרים, דהיינו מלאכי חבלה, עומדים בדרך ההוא של הגיהנם."],[4,"זכתה נשמתא וההוא וכו':","זכתה הנשמה ושמירה ההיא של פרישת לבוש יקר עליה, דהיינו השם אלוה, (כנ\"ל אות מ\"ח) כמה מחנות קדושות נועדים לה להתחבר עמה ולהביא אותה לגן העדן. לא זכתה, כמה מחנות נכרים נועדים להביאה אל הגיהנם, ואלו המחנות של מלאכי חבלה עתידים לעשות בה נקמות. לזה בא הכתוב, והורה, \u0003לעם נכרי לא ימשול למכרה,\u0004 אלו הם מלאכי החבלה. \u0003בבגדו בה,\u0004 הוא לבוש השמירה, שהקב\"ה עושה לה שמירה שלא ישלוט בה עם נכרי בההוא פרישת השמירה עליה, שהוא השם אלוה."],[5,"ואם לבנו ייעדנה:","בוא וראה, כמה יש לאדם להזהר שלא יטה דרכיו בעולם הזה, שאם זכה האדם בעולם הזה, ושומר את הנשמה כראוי, זה הוא אדם שהקב\"ה רוצה בו, ומשתבח בו בכל יום בפמליא שלו, ואומר, ראו בן הקדוש שיש לי בעולם ההוא, כך וכך עשה, כך כך מעשיו מתוקנים."],[6,"וכד האי נשמתא וכו':","וכשהנשמה הזאת יוצאת מעולם הזה, זכה נקיה וברורה, הקב\"ה מאיר לה בכמה אורות, בכל יום קורא עליה זו היא הנשמה של פלוני בני, שמירה תהיה לגוף ההוא שעזבה."],[7,"ודא הוא דכתיב וכו':","וזהו שכתוב, ואם לבנו ייעדנה כמשפט הבנות יעשה לה. מהו כמשפט הבנות. כאן יש סוד לחכמים. בתוך סלע החזק, שהוא עולם הבריאה, ברקיע הנסתר, העליון מכל הרקיעים אשר שם, יש היכל אחד, הנקרא היכל אהבה. שהוא עומד תחת קדש קדשים דבריאה ושם אוצרות נסתרות, וכל נשיקין של אהבת המלך הן שמה, ואלו הנשמות שהן אהובות המלך נכנסות שם."],[8,"כיון דמלכא עאל וכו':","כיון שהמלך נכנס בהיכל המלך ההוא, שם כתוב, וישק יעקב לרחל, שזווג דנשיקין שם הוא, והקב\"ה מוצא שמה את נשמה הקדושה ההיא, מיד מקדים ונושק אותה ומחבק אותה ומעלה אותה עמו ומשתעשע בה."],[9,"ודא הוא כמשפט וכו':","וזה הוא כמשפט הבנות יעשה לה, כדין שהאב עושה לבתו שהיא חביבה לו, שנושק אותה ומחבק אותה ונותן לה מתנות. כך עושה הקב\"ה אל הנשמה הזכאה בכל יום. כמ\"ש כמשפט הבנות יעשה לה."],[10,"היינו דכתיב וכו':","היינו שכתוב, יעשה למחכה לו. כמו שהבת הזאת דהיינו הנשמה, השלימה העשיה בעולם הזה. כך הקב\"ה משלים לה עשיה אחרת בעולם הבא. שכתוב, עין לא ראתה אלקים זולתך \u0003יעשה\u0004 למחכה לו. וכאן כתוב \u0003יעשה\u0004 לה. לומד גזירה שוה יעשה יעשה. שאף יעשה שבכאן הוא בחי' עין לא ראתה וגו'. ע\"כ. זקן ההוא שטח את עצמו על הקרקע והתפלל תפלה. בכה כמקודם."]],[[0,"","וְכִי יִמְכֹּר אִישׁ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. אֶת בִּתּוֹ - זוֹ הַנְּשָׁמָה הַקְּדוֹשָׁה. לְאָמָה - לִהְיוֹת אָמָה מְשֻׁעְבֶּדֶת בֵּינֵיכֶם בָּעוֹלָם הַזֶּה. בְּבַקָּשָׁה מִכֶּם, בְּשָׁעָה שֶׁמַּגִּיעַ זְמַנָּהּ לָצֵאת מִן הָעוֹלָם הַזֶּה, לֹא תֵצֵא כְּצֵאת הָעֲבָדִים, לֹא תֵצֵא מְטֻנֶּפֶת בַּחֲטָאִים. תֵּצֵא בַּת חוֹרִין, בְּרוּרָה נְקִיָּה, כְּדֵי שֶׁיִּשְׂמַח בָּהּ אֲדוֹנָהּ וְיִשְׁתַּבַּח בָּהּ וְיִתֵּן לָהּ שָׂכָר טוֹב בְּצִחְצוּחֵי גַּן עֵדֶן, כְּמוֹ שֶׁנֶּאֱמַר וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךְ. וַדַּאי כַּאֲשֶׁר תֵּצֵא בְּרוּרָה נְקִיָּה כָּרָאוּי."],[1,"","אֲבָל אִם רָעָה בְּעֵינֵי אֲדנֶיהָ, כְּשֶׁיּוֹצֵאת מְלֻכְלֶכֶת בְּטִנּוּפֵי הַחֲטָאִים וְלֹא נִרְאֵית לְפָנָיו כָּרָאוּי - אוֹי לְאוֹתוֹ הַגּוּף שֶׁאָבַד מֵאוֹתָהּ נְשָׁמָה לְעוֹלָמִים. מִשּׁוּם שֶׁכַּאֲשֶׁר הַנְּשָׁמוֹת עוֹלוֹת בְּרוּרוֹת וְיוֹצְאוֹת נְקִיּוֹת מִן הָעוֹלָם הַזֶּה, כָּל נְשָׁמָה וּנְשָׁמָה נִכְנֶסֶת לְסֵפֶר אוֹצַר הַמֶּלֶךְ, וְכֻלָּן בְּשֵׁמוֹת, וְאוֹמֵר: זוֹ הִיא נִשְׁמַת פְּלוֹנִי עֲתִידָה תִּהְיֶה לְאוֹתוֹ הַגּוּף שֶׁעָזְבָה. וְאָז כָּתוּב לוֹ יְעָדָהּ, בְּו'."],[2,"","וּכְשֶׁיּוֹצֵאת רָעָה בְּעֵינֵי אֲדנֶיהָ, שֶׁנִּטְמְאָה בַּחֲטָאִים וּבַטִּנּוּף שֶׁל הַחֲטָאִים, אָז לֹא יְעָדָהּ, בְּא'. וְנֶאֱבָד אוֹתוֹ הַגּוּף מִמֶּנָּה, וְהִיא לֹא מִזְדַּמֶּנֶת אֵלָיו, פְּרָט לְאוֹתָה שֶׁבַּעְלָהּ הִתְרַצָּה וְשָׁב בִּתְשׁוּבָה שֶׁל הַגּוּף בָּהּ, אָז כָּתוּב וְהֶפְדָּהּ, כְּמוֹ שֶׁנֶּאֱמַר (איוב לג) פָּדָה נַפְשׁוֹ מֵעֲבֹר בַּשָּׁחַת. וְהֶפְדָּהּ, זֶהוּ בָּאָדָם, שֶׁהָעֵצָה שֶׁלּוֹ שֶׁיִּפְדֶּה אוֹתָהּ וְיָשׁוּב בִּתְשׁוּבָה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר אֶת זֶה לִשְׁנֵי צְדָדִים, וְהֶפְדָּהּ בִּתְשׁוּבָה. אַחַר שֶׁשָּׁב בִּתְשׁוּבָה, פָּדָה אוֹתָהּ מִדֶּרֶךְ הַגֵּיהִנֹּם."],[3,"","לְעַם נָכְרִי לֹא יִמְשֹׁל לְמָכְרָהּ. מִי זֶה עַם נָכְרִי? עֲלוּבָה הִיא הַנְּשָׁמָה, שֶׁכַּאֲשֶׁר יוֹצֵאת מִן הָעוֹלָם וּבֶן אָדָם מַסְטֶה דַרְכּוֹ עִמָּהּ, הִיא רוֹצָה לַעֲלוֹת לְמַעְלָה לְתוֹךְ הַמַּחֲנוֹת הַקְּדוֹשִׁים, מִשּׁוּם שֶׁהַמַּחֲנוֹת הַקְּדוֹשִׁים עוֹמְדִים בְּאוֹתָהּ דֶּרֶךְ שֶׁל גַּן עֵדֶן, וּמַחֲנוֹת נָכְרִיִּים עוֹמְדִים בְּאוֹתָהּ דֶּרֶךְ שֶׁל הַגֵּיהִנֹּם."],[4,"","זָכְתָה הַנְּשָׁמָה, וְאוֹתָהּ שְׁמִירָה וּפְרִישַׂת לְבוּשׁ הַנִּכְבָּד עָלֶיהָ. כַּמָּה מַחֲנוֹת קְדוֹשִׁים מְעֻתָּדִים לָהּ לְהִתְחַבֵּר עִמָּהּ וּלְהַכְנִיס אוֹתָהּ לְגַן עֵדֶן. לֹא זָכְתָה - כַּמָּה מַחֲנוֹת נָכְרִיִּים מְזֻמָּנִים לְהַכְנִיס אוֹתָהּ בְּדֶרֶךְ הַגֵּיהִנָּם, וְאוֹתָם מַחֲנוֹת שֶׁל מַלְאֲכֵי חַבָּלָה מְזֻמָּנִים לַעֲשׂוֹת בָּהּ נְקָמוֹת. בָּא הַכָּתוּב וּמוֹכִיחַ, לְעַם נָכְרִי לֹא יִמְשֹׁל לְמָכְרָהּ - אֵלּוּ מַלְאֲכֵי חַבָּלָה. בְּבִגְדוֹ בָהּ - אוֹתָהּ שְׁמִירָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לָהּ שְׁמִירָה שֶׁלֹּא יִשְׁלֹט בָּה עַם נָכְרִי בְּאוֹתָהּ הַפְּרִיסָה שֶׁשּׁוֹמֶרֶת עָלֶיהָ."],[5,"","וְאִם לִבְנוֹ יִיעָדֶנָּה. בּא וּרְאֵה כַּמָּה יֵשׁ לָאָדָם לְהִזָּהֵר שֶׁלֹּא יִסְטוּ דְרָכָיו בָּעוֹלָם הַזֶּה. שֶׁאִם זָכָה אָדָם בָּעוֹלָם הַזֶּה וְשׁוֹמֵר אֶת הַנְּשָׁמָה כָּרָאוּי, זֶהוּ אָדָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְרֻצֶּה מִמֶּנּוּ, וּמִשְׁתַּבֵּחַ בּוֹ בְּכָל הַיָּמִים בַּפָּמַלְיָה שֶׁלּוֹ וְאוֹמֵר: רְאוּ בֵן קָדוֹשׁ שֶׁיֵּשׁ לִי בְּאוֹתוֹ הָעוֹלָם, כָּךְ וְכָךְ עָשָׂה, כָּךְ וְכָךְ מַעֲשָׂיו מְתֻקָּנִים."],[6,"","וּכְשֶׁנְּשָׁמָה זוֹ יוֹצֵאת מֵהָעוֹלָם הַזֶּה זַכָּה נְקִיָּה וּבְרוּרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאִיר לָהּ בְּכַמָּה אוֹרוֹת, בְּכָל יוֹם קוֹרֵא עָלֶיהָ: זוֹהִי נִשְׁמַת פְּלוֹנִי בְּנִי, שְׁמִירָה תִּהְיֶה לְאוֹתוֹ הַגּוּף שֶׁעָזְבָה."],[7,"","וְזְהִוּ שֶׁכָּתוּב וְאִם לִבְנוֹ יִיעָדֶנָּה כְּמִשְׁפַּט הַבָּנוֹת יַעֲשֶׂה לָּהּ. מַה זֶּה כְּמִשְׁפַּט הַבָּנוֹת? כָּאן יֵשׁ סוֹד לַחֲכָמִים. בְּתוֹךְ הַסֶּלַע הֶחָזָק, הָרָקִיעַ הַטָּמוּן, יֵשׁ הֵיכָל אֶחָד שֶׁנִּקְרָא הֵיכַל הָאַהֲבָה, וְשָׁם הַגְּנָזִים טְמוּנִים, וְכָל נְשִׁיקוֹת הָאַהֲבָה שֶׁל מֶלֶךְ הֵן שָׁם, וְאוֹתָן נְשָׁמוֹת אֲהוּבוֹת הַמֶּלֶךְ נִכְנָסוֹת לְשָׁם."],[8,"","כֵּיוָן שֶׁהַמֶּלֶךְ נִכְנָס לְאוֹתוֹ הֵיכַל הַמֶּלֶךְ, שָׁם כָּתוּב (בראשית כט) וַיִּשַּׁק יַעֲקֹב לְרָחֵל. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹצֵא שָׁם אֶת אוֹתָהּ נְשָׁמָה קְדוֹשָׁה, מַקְדִּים מִיָּד וְנוֹשֵׁק לָהּ, וּמְגַפֵּף אוֹתָהּ וּמַעֲלֶה אוֹתָהּ אֵלָיו וּמִשְׁתַּעֲשֵׁעַ בָּהּ."],[9,"","וְזְהִוּ כְּמִשְׁפַּט הַבָּנוֹת יַעֲשֶׂה לָּהּ, כְּדִין שֶׁאָב עוֹשֶׂה לְבִתּוֹ, שֶׁהִיא חֲבִיבָה עָלָיו, שֶׁנּוֹשֵׁק לָהּ וּמְגַפֵּף אוֹתָהּ וְנוֹתֵן לָהּ מַתָּנוֹת. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לַנְּשָׁמָה הַצַּדִּיקָה בְּכָל יוֹם, כְּמוֹ שֶׁכָּתוּב כְּמִשְׁפַּט הַבָּנוֹת יַעֲשֶׂה לָּהּ."],[10,"","הַיְנוּ שֶׁכָּתוּב (ישעיה סד) יַעֲשֶׂה לִמְחַכֵּה לוֹ. כְּמוֹ שֶׁהַבַּת הַזֹּאת מַשְׁלִימָה עֲשִׂיָּה בָּעוֹלָם הַזֶּה, אַף כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁלִים לָהּ עֲשִׂיָּה אַחֶרֶת בָּעוֹלָם הַבָּא, שֶׁכָּתוּב עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ. וְכָאן כָּתוּב יַעֲשֶׂה לָּהּ. עַד כָּאן. אוֹתוֹ הַזָּקֵן הִשְׁתַּטַּח וְהִתְפַּלֵּל תְּפִלָּה, וּבָכָה כְּמִקֹּדֶם."]]],[["וְאָמַר (שמות כ״א:י׳) אִם אַחֶרֶת יִקַּח לוֹ וְגוֹ', מַאי אִם אַחֶרֶת, וְכִי נִשְׁמְתָא אַחֲרָא זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאָתָבָא לְצַדִּיקַיָּיא בְּהַאי עָלְמָא, וְלָאו הַאי נִשְׁמְתָא דְּאַשְׁלִימַת בְּהַאי עָלְמָא רְעוּתָא דְּמָארָהּ, אִי הָכִי לֵית אַבְטָחוּתָא לְצַדִּיקַיָּיא כְּלָל. מַאי אִם אַחֶרֶת יִקַּח לוֹ.","פָּתַח הַהוּא סָבָא וְאָמַר, (קהלת י״ב:ז׳) וְיָשׁוֹב הֶעָפָר עַל הָאָרֶץ כְּשֶׁהָיָה וְהָרוּחַ תָּשׁוּב אֶל הָאֱלהִים אֲשֶׁר נְתָנָהּ. הַאי קְרָא אוּקְמוּהָ חַבְרַיָּיא, בְּחָרְבַּן בֵּי מַקְדְּשָׁא. (ותמן תנינן) וְיָשׁוֹב הֶעָפָר עַל הָאָרֶץ כְּשֶׁהָיָה. הָכָא אִיהוּ מַאי דְּכְתִּיב, (בראשית י״ב:ו׳) וְהַכְּנַעֲנִי אָז בָּאָרְץ, כְּשֶׁהָיָה וַדַּאי. וְהָרוּחַ תָּשׁוּב אֶל הָאֱלהִים אֲשֶׁר נְתָנָהּ, מַאי וְהָרוּחַ תָּשׁוּב. דָּא שְׁכִינְתָּא, דְּאִיהִי רוּחַ קַדִּישָׁא. כַּד חָמָאת שְׁכִינְתָּא, בְּאִינוּן עֶשֶׂר מַסָּעוֹת דְּקָא נַטְלָא, וְלָא בָּעוּן יִשְׂרָאֵל לְאָתָבָא בִּתְיוּבְתָּא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְשָׁלְטָא סִטְרָא אַחֲרָא עַל אַרְעָא קַדִּישָׁא, וְאוּקְמוּהָ חַבְרַיָּיא.","תָּא חֲזִי, רוּחָא דְּבַר נָשׁ זַכָּאָה, אִתְעַטָּר בְּדִיּוּקְנָא בְּגַּן עֵדֶן דִּלְתַתָּא, וּבְכָל שַׁבָּתֵי וּמוֹעֲדֵי וְרֵישֵׁי יַרְחֵי, מִתְעַטְּרָן רוּחֵי, וּמִתְפַּשְּׁטָן, וְסַלְּקִין לְעֵילָּא. כְּמָּה דְּעָבִיד קוּדְשָׁא בְּרִיךְ הוּא, בְּהַהִיא נִשְׁמְתָא עִלָּאָה קַדִּישָׁא לְעֵילָּא, הָכִי נָמֵי עָבִיד בְּהַאי רוּחָא, לְתַתָּא בְּגַּן עֵדֶן לְתַתָּא, דְּקָא סַלְקַת קָמֵיהּ. וְאָמַר דָּא אִיהִי רוּחָא דִּפְלַנְיָא גּוּפָא, מִיָּד מְעַטְּרָא לָהּ קוּדְשָׁא בְּרִיךְ הוּא לְהַאי רוּחָא בְּכַמָּה עִטְרִין, וְאִשְׁתַּעֲשַׁע בָּהּ.","וְאִי תֵּימָא, דְּהָא בְּגִין רוּחָא דָּא, שָׁבִיק קוּדְשָׁא בְּרִיךְ הוּא מַה דְּעָבִיד לְנִשְׁמְתָא. לָאו הָכִי. אֶלָּא שְׁאֵרָהּ כְּסוּתָהּ וְעֹנָתָהּ לא יִגְרָע, אִלֵּין אִינּוּן תְּלַת שְׁמָהָן עִלָּאִין, דְּעַיִן לא רָאָתָה אֱלהִים זוּלָתְךָ.","וְכֻלְּהוּ בְּעָלְמָא דְּאָתֵי וְאִתְמַשְּׁכוּ מִתַּמָּן. חַד מִנַּיְיהוּ שְׁאֵרָהּ, מְשִׁיכוּ דִּנְצִיצוּ וּנְהִירוּ, דְּנָהִיר בְּאֹרַח סָתִים, מְזוֹנָא (לן) דְּזָן כֹּלָּא, וְאִקְרֵי ידו\"ד בִּנְקוּדַת אֱלהִים. שְׁאֵרָהּ בְּהִפּוּךְ אַתְוָון, אשר ה' וְדָּא (בראשית מ״ט:כ׳) מֵאָשֶׁר שְׁמֵּנָה לַחְמוֹ, וְדָא הוּא שְׁאֵרָהּ.","כְּסוּתָהּ: פְּרִישׂוּ דְּמַלְכָּא. דָּא מְשִׁיכוּ אַחֲרָא, דְּנָהִיר וְנָטִיר לָהּ תָּדִיר, פְרִישׂוּ דִּלְבוּשָׁא דְּמַלְכָּא, דְּפָרִשׂ עָלָהּ אֱלוֹהַּ. דָּא בְּבִגְדוֹ בָהּ תָּדִיר, דְּלָא אִתְעָדֵי מִינָּהּ, וְהַאי אִיהוּ כְּסוּתָהּ.","וְעֹנָתָהּ, מַאן אִיהוּ. דָּא מְשִׁיכוּ דְּעָלְמָא דְּאָתֵי, דְּבֵיהּ כֹּלָּא. יְיָ' צְבָאוֹת אִיהוּ, וְדָא אִיהוּ דְּנָהִיר בְּכָל נְהוֹרִין סְתִימִין עִלָּאִין דְּאִילָנָא דְּחַיֵּי, דְּבֵיהּ עוֹנָה טְמִירָא, דְּמִתַּמָּן נַפְקַת. וְכָל דָּא בְּעִדּוּנָא וְכִסּוּפָא דְּעָלְמָא דְּאָתֵי.","תְּלָתָא הָנֵי לא יִגְרָע לָהּ, כַּד אִיהִי זַכָּאת כַּדְּקָא יֵאוּת. וְאִי לָאו אִיהִי כַּדְקָא יֵאוּת, הָנֵי תְּלָתָא גַּרְעָאן מִנָהּ, דְּלָא יִתְעֲבִיד לָהּ עֲטָּרָה אֲפִילּוּ מֵחָד מִנַּיְיהוּ, תָּא חֲזִי, מַה כְּתִיב, וְאִם שְׁלָשׁ אֵלֶּה לֹא יַעֲשֶׂה לָהּ, דְּלָא זָכָאת בְּהוּ, וְיָצְאָה חִנָּם אֵין כָּסֶף תִּפּוּק מִקַּמֵיהּ, וְדַחְיָין לָהּ לְבַר. אֵין כָּסֶף, לֵית לָהּ כִּסּוּפָא, וְלֵית לָהּ עִדּוּנָא כְּלַל.","עַד כָּאן אוֹכִיחַת אוֹרַיְיתָא, דְּכָל עֵיטִין בָּהּ תַּלְיָין, וְיָהִיבַת עֵיטָא טָבָא לִבְנִי נָשָׁא. מִכָּאן וּלְהָלְאָה נֶהְדָּר לְמִלִּין קַדְמָאִין, בְּהַהוּא נְטִירוּ עִלָּאָה, דְּקָא פָּרִישׂ עָלָהּ קוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּלָא תְּהֵא לְעַם נָכְרִי, דְּהָא בִּגְדוֹ בָהּ, וּנְטִירוּ אִיהוּ לָהּ תָּדִיר.","(שמות כ״א:ט׳) וְאִם לִבְנוֹ יִיעָדֶנָּה כְּמִשְׁפַּט הַבָּנוֹת יַעֲשֶׂה לָהּ. אָמַר הַהוּא סָבָא, חַבְרַיָּיא, כַּד תַּהֲכוּן לְגַבֵּי הַהוּא טִינָרָא דְּעָלְמָא סָמִיךְ עָלֵיהּ, אִמְרוּ לֵיהּ, דְּיִדְכַּר יוֹמָא דְּתַלְגָּא דְּאִזְדְּרָעוּ פּוֹלִין לְחַמְשִׁין וּתְרֵין גַּוְונִין, וַהֲדַר אַקְרֵינָן הַאי קְרָא, וְהוּא יֵימָא לְכוֹן.","אָמְרוּ בְּמָטוּ מִינָךְ מַאן דְּשָׁארִי מִלָּה הוּא יֵימָא. אָמַר לוֹן, וַדַּאי דְּיָדַעְנָא דְּזַכָּאִין אַתּוּן, וְאִית לְרַמְּזָא לְכוּן רְמָזָא דְּחַכִּימִין, וְעַל מָה דַּאֲנָא אֵימָא, כַּד תִּדְכְּרוּן לֵיהּ סִימָנָא דָּא, הוּא יַשְׁלִים עַל דָּא. הַשְׁתָּא אִית לוֹמַר, מַאן הוּא דְּאִקְרֵי בֵּן לְקוּדְשָׁא בְּרִיךְ הוּא."],[[0,"ואמר, אם אחרת יקח וכו':","שואל, מה אם אחרת, וכי נשמה אחרת הכין הקב\"ה להשיב לצדיקים בעולם הזה, ואין זו אותה הנשמה שהשלימה בעולם הזה רצון אדונה, א\"כ אין הבטחה כלל לצדיקים. מהו אם אחרת יקח לו."],[1,"פתח ההוא סבא וכו':","פתח זקן ההוא ואמר, וישוב העפר על הארץ כשהיה והרוח תשוב אל האלקים אשר נתנה. מקרא זה העמידו החברים בחורבן בית המקדש, וישוב העפר על הארץ כשהיה, כאן הוא מ\"ש, והכנעני אז בארץ. כשהיה ודאי. שאחר החורבן חזרה הארץ לרשות קליפת כנען כמו שהיה מתחילה. והרוח תשוב אל האלקים אשר נתנה, מהו והרוח תשוב, זו היא השכינה, שהיא רוח הקדוש, בעת שראתה השכינה, באלו עשרה מסעות שנסעה, שישראל אינם רוצים לשוב בתשובה לפני הקב\"ה והסטרא אחרא שלטת על ארץ הקדושה, נסתלקה השכינה ושבה אל האלקים. והעמידוה החברים."],[2,"תא חזי רוחא וכו':","בוא וראה, רוח של אדם צדיק, מתעטר בצורה בגן העדן התחתון. ובכל שבתות ומועדים וראשי חדשים, מתעטרים הרוחות ופושטים צורתם מג\"ע התחתון, ועולים למעלה לג\"ע העליון. וכמו שעשה הקב\"ה בנשמה הקדושה למעלה (כנ\"ל באות ס\"ב) כן עושה עם הרוח הזה, שלמטה בגן העדן התחתון, שעלה לפניו. ואמר זה הוא הרוח של גוף פלוני. מיד מעטר הקב\"ה לרוח הזה בכמה עטרות ומשתעשע בה."],[3,"ואי תימא דהא וכו':","ואם תאמר שבשביל רוח הזה עוזב הקב\"ה את מה שעושה לנשמה, אינו כן, אלא \u0003שארה כסותה וענתה לא יגרע.\u0004 אלו הם ג' שמות עליונים שעין לא ראתה אלקים זולתך. שה\"ס בינה."],[4,"וכלהו בעלמא דאתי וכו':","וכולם הם בעולם הבא, שהוא בינה, ונמשכו משם. אחד מהם הוא \u0003שארה,\u0004 הוא המשכה של התנוצצות ואור, שהם או\"ח ואו\"י, המאיר בדרך סתום. הוא מזון הזן את הכל, ונקרא, הויה בניקוד אלקים, שהוא שם הבינה. שארה בהפוך האותיות הוא \u0003אשר ה',\u0004 אשר, היא בינה, (כנ\"ל בראשית א' אות ו') שהיא \u0003ה'\u0004 ראשונה של הויה. וזהו מאשר שמנה לחמו, כי ממנה נמשך המזון. וזה הוא \u0003שארה.\u0004"],[5,"כסותה, פרישו דמלכא וכו':","כסותה, היא הפרישה שפורש עליה המלך, דהיינו לבוש יקר של השם אלוה, (כנ\"ל אות מ\"ח) זה הוא המשכה אחרת המאירה ושומר אותה, את הנשמה, תמיד. הוא פרישה של לבוש המלך שפורש עליה אלוה. וזהו, בבגדו בה, תמיד,שלא נעדר ממנה, וזה הוא \u0003כסותה.\u0004"],[6,"וענתה, מאן איהו וכו':","ומה הוא \u0003ענתה.\u0004 זו היא המשכה מעולם הבא, שהיא בינה שבה הכל, הויה צבאות הוא, שהוא השם שבנה\"י דבינה, וזה הוא המאיר בכל האורות הסתומים העליונים של עץ החיים, שבו העונה הנסתרת, שמשם היא יוצאת. וכל זה בעדון והשתוקקות של עולם הבא. שהוא בינה."],[7,"תלתא הני לא וכו':","שלשה אלו לא יגרע ממנה כשהיא זכאת כראוי. ואם אינה כראוי, גורעים ממנה אלו שלשה, שלא נעשה לה עטרה אפילו מאחד מהם. בוא וראה, מה כתוב, ואם שלש אלה לא יעשה לה, דהיינו שלא זכתה בהם, \u0003ויצאה חנם אין כסף,\u0004 תצא ממנו, ודוחים אותה לחוץ. \u0003אין כסף,\u0004 אין לה כיסוף דהיינו השתוקקות, ואין לה עדון כלל."],[8,"עד כאן אוכיחת וכו':","עד כאן הוכיחה התורה, שכל העצות תלויות בה, ונותנת עצה טובה לבני אדם. מכאן ולהלאה, נחזור לדברים הראשונים, בשמירה העליונה ההיא שפורש עליה, על הנשמה, הקב\"ה, כדי שלא תהיה לעם נכרי, כי בגדו בה, ושמירה הוא לה תמיד."],[9,"ואם לבנו ייעדנה וגו':","אמר זקן ההוא, חברים, כשתלכו אל סלע ההוא שהעולם סמוך עליו, שהוא ר' שמעון, תאמרו לו, שיזכר יום השלג שנזרעו פולים לנ\"ב אפנים. ואחר כך תקראו מקרא הזה, והוא יאמר לכם, פירושו."],[9,"","ביאור הדברים, \u0003יומא דתלגא,\u0004 הוא דינין דדכורא הנמשכים משליטת קו השמאל. (כמ\"ש בהקדמת ספר הזהר אות צ\"ח בהסולם) \u0003זריעה\u0004 פירושו, הכנת העלמת אור, שבסופו מתהפך ההעלם לגילוי גדול, שהוא כמו זריעת חטים טובים בקרקע, שנעלמים ונרקבים שם, אבל סופם לחזור ולצמוח מאה שערים. (כנ\"ל פרשת בא אות נ\"ז ע\"ש) \u0003דאזדרעו פולין,\u0004 פולין היא לשון נפילה, והוא הזריעה של עלית המלכות לבינה, שגרמה \u0003לנפילת\u0004 בינה, ותו\"מ מכל המדרגות למדרגה שמתחתיה. \u0003נ\"ב גוונין,\u0004 הוא רמז לבחינת \u0003בן\u0004 שהוא אותיות נ\"ב. והוקשה לו לסבא, לפרש הכתוב, \u0003אם לבנו ייעדנה,\u0004 על הקב\"ה שאיך אפשר לומר בנו של הקב\"ה. ואיך אפשר שיהיה בחינת אב ובן במדרגות העליונות ולפיכך שלח אותם לר\"ש, שהוא יבאר להם את זה."],[9,"","וז\"ש, \u0003כד תהכון לגבי ההוא טנרא\u0004 וכו' שהוא ר\"ש, אמרו ליה, \u0003דידכר יומא דתלגא,\u0004 דהיינו יום שליטת קו השמאל שדינין שלו מכונים תלגא. \u0003דאזדרעו פולין לנ\"ב גוונין,\u0004 שאז ע\"י קו האמצעי, עלתה המלכות לבינה, (כמ\"ש פרשת לך דף י\"ג ד\"ה ונתבאר ע\"ש.) ובינה ותו\"מ שלה נפלו לז\"א, וכן עלתה המלכות לבינה דזו\"ן, ובינה ותו\"מ שלהם נפלו לנשמות הצדיקים. ועל ידי העלם הזה יצאו כל המוחין דזו\"ן ובי\"ע (כמ\"ש בבראשית א' דף ז' ד\"ה וכבר) וע\"כ מכונה זה זריעת פולין. \u0003זריעה\u0004 מפני שההעלם נעשה אח\"כ בעת גדלות לגילוי גדול. \u0003פולין\u0004 על שם נפילת חצאי מדרגות התחתונות מכל מדרגה למדרגה שמתחתיה. ונודע שעליה זו של המלכות לבינה, עשתה קשר בין בינה וז\"א שחו\"ב דבינה נעשו לבחינת או\"א לז\"א, וז\"א נעשה לבן אליהם (כנ\"ל פרשת יתרו דף צ' ע\"א ד\"י בד\"ה כבד ע\"ש) וז\"ש \u0003לנ\"ב גוונין,\u0004 שהוא רומז על בן. שע\"י \u0003זריעת הפולין\u0004 נעשה קשר בין המדרגות, שחו\"ב דעליון נעשו לאו\"א והתחתון נעשה \u0003לב\"ן,\u0004 וע\"כ כמו שז\"א נעשה עי\"ז \u0003בן\u0004 לחכמה ובינה, כן נעשה הצדיק \u0003בן\u0004 לז\"א. ובזה רמז לר\"ש, שיבאר זה לר' חייא ור' יוסי, ויבינו הכתוב ואם לבנו ייעדנה. שהצדיק התחתון נבחן \u0003לב\"ן\u0004 אל הקב\"ה, כמו ז\"א לבינה. (ועי' לעיל בראשית ב' דף קנ\"ב ד\"ה ביאור)."],[10,"אמרו במטו מינך וכו':","אמרו לו, בבקשה ממך, מי שהתחיל הדבר הוא יאמר. אמר להם ודאי שידעתי שצדיקים אתם, ויש לרמז לכם רמז חכמים. ועל מה שאני אומר לפניכם, כשתזכירו אותו, את ר\"ש, סימן הזה, הוא ישלים על זה. דהיינו שישלים דברי. כי הסבא אינו מבאר להם, למה נקרא התחתון בן אל הקב\"ה, וע\"י הסימן שנתן, יבאר להם ר\"ש את זה, וישלים את דבריו. עתה יש לומר מי הוא שנקרא \u0003בן\u0004 אל הקב\"ה."]],[[0,"","וְאָמַר, אִם אַחֶרֶת יִקַּח לוֹ וְגוֹ', מַה זֶּה אִם אַחֶרֶת? וְכִי נְשָׁמָה אַחֶרֶת עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָשִׁיב לַצַּדִּיקִים בָּעוֹלָם הַזֶּה, וְלֹא נְשָׁמָה זוֹ שֶׁהִשְׁלִימָה בָּעוֹלָם הַזֶּה אֶת רְצוֹן רִבּוֹנָהּ? אִם כָּךְ, אָז אֵין הַבְטָחָה לַצַּדִּיקִים כְּלָל. מַה זֶּה אִם אַחֶרֶת יִקַּח לוֹ?"],[1,"","פָּתַח אוֹתוֹ זָקֵן וְאָמַר, (קהלת יב) וְיָשׁוֹב הֶעָפָר עַל הָאָרֶץ כְּשֶׁהָיָה וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ. פָּסוּק זֶה פֵּרְשׁוּהוּ הַחֲבֵרִים בְּחֻרְבַּן בֵּית הַמִּקְדָּשׁ. (ושם שנינו) וְיָשׁוֹב הֶעָפָר עַל הָאָרֶץ כְּשֶׁהָיָה. כָּאן הוּא מַה שֶּׁכָּתוּב וְהַכְּנַעֲנִי אָז בָּאָרֶץ, כְּשֶׁהָיָה וַדַּאי. וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ, מַה זֶּה וְהָרוּחַ תָּשׁוּב? זוֹ שְׁכִינָה, שֶׁהִיא רוּחַ הַקֹּדֶשׁ. כְּשֶׁרָאֲתָה שְׁכִינָה בְּאוֹתָם עֲשָׂרָה מַסָּעוֹת שֶׁנָּסְעָה, וְלֹא רָצוּ בְּנֵי יִשְׂרָאֵל לָשׁוּב בִּתְשׁוּבָה שְׁלֵמָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְשׁוֹלֵט הַסִּטְרָא אַחֲרָא עַל הָאָרֶץ הַקְּדוֹשָׁה, וּפֵרְשׁוּהָ הַחֲבֵרִים."],[2,"","בֹּא וּרְאֵה, רוּחַ שֶׁל אִישׁ צַדִּיק מִתְעַטֶּרֶת בִּדְמוּת בְּגַן עֵדֶן שֶׁלְּמַטָּה, וּבְכָל הַשַּׁבָּתוֹת וְהַמּוֹעֲדִים וְרָאשֵׁי חֳדָשִׁים מִתְעַטְּרוֹת רוּחוֹת וּמִתְפַּשְּׁטוֹת, וְעוֹלוֹת לְמַעְלָה. כְּמוֹ שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָהּ נְשָׁמָה עֶלְיוֹנָה קְדוֹשָׁה לְמַעְלָה, כָּךְ גַּם עוֹשֶּׂה בָּרוּחַ הַ את לְמַטָּה בְּגַן עֵדֶן הַתַּחְתּוֹן כְּשֶׁעוֹלָה לְפָנָיו, וְאוֹמֵר: זוֹהִי רוּחַ פְּלוֹנִי הַגּוּף. מִיָּד מְעַטֵּר אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתָהּ רוּחַ בְּכַמָּה עֲטָרוֹת וּמִשְׁתַּעֲשֵׁעַ בָּהּ."],[3,"","וְאִם תֹּאמַר, שֶׁהֲרֵי מִשּׁוּם רוּחַ זוֹ הִשְׁאִיר הַקָּדוֹשׁ בָּרוּךְ הוּא מַה שֶּׁעָשָׂה לַנְּשָׁמָה - לֹא כָּךְ! אֶלָּא שְׁאֵרָהּ כְּסוּתָהּ וְעֹנָתָהּ לֹא יִגְרָע. אֵלֶּה אוֹתָם שְׁלֹשֶׁת הַשֵּׁמוֹת הָעֶלְיוֹנִים שֶׁעַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ."],[4,"","וְכֻלָּם בָּעוֹלָם הַבָּא וְנִמְשְׁכוּ מִשָּׁם. אֶחָד מֵהֶם שְׁאֵרָהּ - מְשִׁיכָה שֶׁל הִתְנוֹצְצוּת וְאוֹר שֶׁמֵּאִיר בְּדֶרֶךְ נִסְתָּר, מָזוֹן (לנו) שֶׁזָּן לַכֹּל, וְנִקְרָא יהו\"ה עִם נִקּוּד אֱלֹהִי\"ם. שְׁאֵרָהּ בְּהִפּוּךְ אוֹתִיּוֹת - אָשֵׁר ה', וְזֶה (בראשית מט) מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ, וְזה הוּא שְׁאֵרָהּ."],[5,"","כְּסוּתָהּ - פְּרִישָׂה שֶׁל הַמֶּלֶךְ. זוֹ מְשִׁיכָה אַחֶרֶת שֶׁמְּאִירָה וְשׁוֹמֶרֶת אוֹתָהּ תָּמִיד, פְּרִישָׂה שֶׁל לְבוּשׁ הַמֶּלֶךְ שֶׁפּוֹרֵשׂ עָלֶיהָ אֱלוֹהַּ. זֶה בְּבִגְדוֹ בָהּ תָּמִיד, שֶׁלֹּא זָז מִמֶּנָּה, וְזֶהוּ כְּסוּתָהּ."],[6,"","וְעֹנָתָהּ, מִי הוּא? זוֹ מְשִׁיכָה מִן הָעוֹלָם הַבָּא שֶׁבּוֹ הַכֹּל. ה' צְבָאוֹת הוּא, וְזֶהוּ שֶׁמֵּאִיר בְּכָל הָאוֹרוֹת הַנִּסְתָּרִים הָעֶלְיוֹנִים שֶׁל עֵץ הַחַיִּים שֶׁבּוֹ שְׁמוּרָה עוֹנָה, שֶׁמִּשָּׁם הִיא יוֹצֵאת, וְכָל זֶה בְּעִדּוּן וּתְשׁוּקָה שֶׁל הָעוֹלָם הַבָּא."],[7,"","שְׁלש אֵלֶּה לֹא יִגְרַע לָהּ, כְּשֶׁהִיא זַכָּאִית כָּרָאוּי. וְאִם אֵינָהּ כָּרָאוּי, שְׁלֹשׁ אֵלֶּה נִגְרָעוֹת מִמֶּנָּה, שֶׁלֹּא יַעֲשֶׂה לָהּ עֲטָרָה אֲפִלּוּ מֵאֶחָד מֵהֶם. בֹּא וּרְאֵה מַה כָּתוּב, וְאִם שְׁלָשׁ אֵלֶּה לֹא יַעֲשֶׂה לָהּ - שֶׁלֹּא זָכְתָה בָהֶם, וְיָצְאָה חִנָּם אֵין כָּסֶף - תֵּצֵא מִלְּפָנָיו, וְדוֹחֶה אוֹתָהּ הַחוּצָה. אֵין כָּסֶף - אֵין לָהּ כִּסּוּף וְלֹא עִדּוּן כְּלָל."],[8,"","עֵד כָּאן מוֹכִיחָה הַתּוֹרָה שֶׁכָּל הָעֵצוֹת תְּלוּיוֹת בָּהּ, וְנוֹתֶנֶת עֵצָה טוֹבָה לִבְנֵי אָדָם. מִכָּאן וָהָלְאָה נַחֲזֹר לַדְּבָרִים הָרִאשׁוֹנִים, בְּאוֹתָהּ שְׁמִירָה עֶלְיוֹנָה שֶׁפּוֹרֵשׂ עָלֶיהָ הַקָּדוֹשׁ בָּרוּךְ הוּא כְּדֵי שֶׁלֹּא תִהְיֶה לְעַם נָכְרִי, שֶׁהֲרֵי בִּגְדוֹ בָהּ, וּשְׁמִירָה הִיא לָהּ תָּמִיד."],[9,"","וְאִם לִבְנוֹ יִיעָדֶנָּה כְּמִשְׁפַּט הַבָּנוֹת יַעֲשֶׂה לָּהּ. אָמַר אוֹתוֹ זָקֵן, חֲבֵרִים, כְּשֶׁתֵּלְכוּ לְאוֹתוֹ הַסֶּלַע שֶׁהָעוֹלָם סָמוּךְ עָלָיו, אִמְרוּ לוֹ שֶׁיִּזְכֹּר אֶת יוֹם הַשֶּׁלֶג שֶׁנִּזְרְעוּ פּוֹלִים לַחֲמִשִּׁים וּשְׁנַיִם גְּוָנִים, וְאַחַר כָּךְ קִרְאוּ אֶת הַפָּסוּק הַזֶּה, וְהוּא יֹאמַר לָכֶם."],[10,"","אָמְרוּ, בְּבַקָּשָׁה מִמְּךְ, מִי שֶׁהִתְחִיל אֶת הַדָּבָר - הוּא שֶׁיֹּאמַר! אָמַר לָהֶם, וַדַּאי שֶׁיָּדַעְתִּי שֶׁאַתֶּם צַדִּיקִים, וְיֵשׁ לִרְמֹז לָכֶם רֶמֶז שֶׁל חֲכָמִים. וְעַל מַה שֶּׁאֲנִי אוֹמֵר, כְּשֶׁתַּזְכִּירוּ לוֹ סִימָן זֶה, הוּא יַשְׁלִים אֶת זֶה. עַכְשָׁו יֵשׁ לוֹמַר מִי הוּא שֶׁנִּקְרָא בֵּן לַקָּדוֹשׁ-בָּרוּךְ- הוּא."]]],[["תָּא חֲזֵי כָּל הַהוּא דְּזָכֵי (ק\"א ע\"א, קי\"ג ע\"א) לִתְלֵיסַר שְׁנִין וּלְהָלְאָה, אִקְרֵי בֵּן לִכְּנֶסֶת יִשְׂרָאֵל. וְכָל מַאן דְּאִיהוּ מִבֶּן עֶשְׂרִין שְׁנִין וּלְעֵילָא וְזָכֵי בְּהוּ, אִקְרֵי בֵּן לְּקוּדְשָׁא בְּרִיךְ הוּא וַדַּאי (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ' אֱלהֵיכֶם.","כַּד מָטָה דָּוִד לִתְלֵיסַר שְׁנִין, וְזָכָה בְּהַהוּא יוֹמָא דְּעָאל לְאַרְבֵּיסָר, כְּדֵין כְּתִיב, (תהילים ב׳:ז׳) יְיָ' אָמַר אֵלַי בְּנִי אַתָּה אֲנִי הַיּוֹם יְלִדְתִּיךָ. מַאי טַעְמָא. דְּהָא מִקַּדְמָת דְּנָא לָא הֲוָה לֵיהּ בְּרָא, וְלָא שָׁרָאת עָלֵיהּ נִשְׁמְתָא עִלָּאָה, דְּהָא בִּשְׁנֵי עָרְלָה הֲוָה, וּבְגִין כָּךְ, (קכ\"ח ע\"ב) אֲנִי הַיּוֹם יְלִדְתִּיךָ, הַיּוֹם וַדַּאי יְלִדְתִּיךָ. אֲנִי, וְלָא סִטְרָא אַחֲרָא, כְּמָה דְּהֲוָה עַד הַשְׁתָּא, אֲנִי בִּלְחוֹדָאי. בַּר עֶשְׂרִין שְׁנִין, מַה כְּתִיב בִּשְׁלֹמֹה, (משלי ד׳:ג׳) כִּי בֵן הָיִיתִי לְאָבִי, לְאָבִי מַמָּשׁ וַדַּאי.","וְאִם לִבְנוֹ יִיעָדֶנָּה. בַּר תְּלֵיסַר שְׁנִין וּלְהָלְאָה, דְּהָא נַפְקָא מֵרְשׁוּ דְּסִטְרָא אַחֲרָא דְּאִזְדַּמְּנַת לֵיהּ, מַה כְּתִיב כְּמִשְׁפַּט הַבָּנוֹת יַעֲשֶׂה לָהּ. מַהוּ כְּמִשְׁפַּט הַבָּנוֹת. תָּנֵינָן, בְּכָל יוֹמָא וְיוֹמָא, חָמֵי קוּדְשָׁא בְּרִיךְ הוּא לְהַהוּא יְנוֹקָא דְּקָאֵי בִּרְשׁוּ דְּעָרְלָה, וְאִיהוּ נָפִיק מִינָהּ, וְאִתְמְשַׁךְ לְבֵי סִפְרָא, וְתַבַּר לָהּ, וְאָזִיל לְבֵי כְּנִישְׁתָּא, וְתַבַּר לָהּ. מַה עָבִיד קוּדְשָׁא בְּרִיךְ הוּא לְהַהִיא נִשְׁמְתָא. אָעִיל לָהּ לְאִדָּרָא דִּילֵיהּ, וְיָהִיב לָהּ מַתְּנָן, וּנְבִזְבְּזָן סַגִּיאִין, וְקָשִׁיט לָהּ בְּקִשּׁוּטִין עִלָּאִין, עַד זִמְנָא דְּאָעִיל (בראשית קמ\"ז ע\"ב) לָהּ לַחוּפָּה בְּהַהוּא (גו ההוא) בַּר, מִתְּלֵיסַר שְׁנִין וּלְעֵילָא.","אִם אַחֶרֶת יִקַּח לוֹ. הָכָא אִית רָזָא דְּרָזִין, לְחַכִּימִין אִתְמְסָרֵי, וְאִית לְאוֹדָעָא בְּקַדְמִיתָא מִלָּה חֲדָא. תָּא חֲזֵי, בְּיוֹמָא דְּשַׁבְּתָא בְּשַׁעֲתָא דְּאִתְקַדָּשׁ יוֹמֵי, נַפְקֵי נִשְׁמָתִין מִגּוֹ אִילָנִי דְּחַיֵּי, וּמְנַשְּׁבָן אִינּוּן נִשְׁמָתִין קַדִּישִׁין לְתַתָּאֵי, וְנַיְיחִין בְּהוּ כָּל יוֹמָא דְּשַׁבְּתָא. וּלְבָתַר דְּנָפִיק שַׁבְּתָא, סַלְּקִין כֻּלְּהוּ נִשְׁמָתִין וּמִתְעַטְּרָן בְּעִטְרִין קַדִּישִׁין לְעֵילָּא. (וכד מתעטרן בההוא טבא אלין אינון בעליו דההוא טיבו ודאי) אוּף הָכִי, קוּדְשָׁא בְּרִיךְ הוּא אַזְמִין לְהַהוּא בַּר נָשׁ, וְדָא הוּא נִשְׁמְתָא אַחֶרֶת, וְאַף עַל גַּב דְּדָא זְמִינָא לֵיהּ, נִשְׁמְתָא דַּהֲוָת לֵיהּ בְּקַדְמִיתָא, שְׁאֵרָהּ דְקַדְמֵיתָא, כְּסוּתָהּ וְעֹנָתָהּ לֹא יִגְרָע, כְּמָה דְּאִתְּמַר.","בָּכָה הַהוּא סָבָא כְּמִלְקַדְּמִין, וְאָמַר אִיהוּ לְנַפְשֵׁיהּ, סָבָא סָבָא, כַּמָּה יָגַעְתָּ לְאַדְבְּקָא מִלִּין קַדִּישִׁין אִלֵּין, וְהַשְׁתָּא תֵּימָא לוֹן בְּרִגְעָא חֲדָא. אִי תֵּימָא דְּתֵיחָס עָלַיְיהוּ עַל אִינּוּן מִלִּין וְלָא תֵּימָא לוֹן, הָא כְּתִיב (משלי ג׳:כ״ז) אַל תִּמְנָע טוֹב מִבְּעָלָיו בִּהְיוֹת לְאֵל יָדְךָ לַעֲשׂוֹת.","מַאי אַל תִּמְנָע טוֹב מִבְּעָלָיו. אֶלָּא, קוּדְשָׁא בְּרִיךְ הוּא וּכְּנְסֶת יִשְׂרָאֵל אִינּוּן הָכָא. דְּהָא בְּכָל אֲתָר דְּמִלִּין דְּאוֹרַיְיתָא אַמְרִין, קוּדְשָׁא בְּרִיךְ הוּא וּכְּנְסֶת יִשְׂרָאֵל אִינּוּן תַּמָן, וְצַיְיתֵי לוֹן. וּכְדֵין, הַהוּא אִילָנָא דְּטוֹב וָרָע, בְּשַׁעֲתָא דְּאַזְלִין מִתַּמָּן, וְצַיְיתוּ אִינּוּן מִלִּין, הַהוּא סִטְרָא דְּטוֹב אִתְגַּבָּר, וְאִסְתַּלָּק לְעֵילָּא, וְקוּדְשָׁא בְּרִיךְ הוּא וּכְּנְסֶת יִשְׂרָאֵל מִתְעַטְּרָן בְּהַהוּא טוֹב, וְאִלֵּין אִינּוּן בְּעָלָיו דְּהַהוּא טוֹב.","סָבָא סָבָא, אַתְּ אָמַרְתְּ מִלִּין אִלֵּין, וְלָא יָדַעְתְּ אִי קוּדְשָׁא בְּרִיךְ הוּא הָכָא, וְאִי אִלֵּין דְּקַיְימֵי הָכָא זַכָּאִין לְמִלִּין אִלֵּין. לָא תִּדְחַל סָבָא, דְּהָא הֲוֵית בְּכַמָּה קְרָבִין דְּגַבְרִין תַּקִּיפִין, וְלָא דָּחִילַת, וְהַשְׁתָּא אַנְתְּ דָּחִיל, אֵימָא מִילָךְ, דְּהָא וַדַּאי הָכָא אִיהוּ קוּדְשָׁא בְּרִיךְ הוּא וּכְּנְסֶת יִשְׂרָאֵל, וְזַכָּאִין אִינּוּן אִלֵּין דְּהָכָא. וְאִי לָאו הָכִי, לָא אַעֲרַעְנָא בְּהוּ, וְלָא שָׁרֵינָא בְּאִלֵּין מִלִּין. אֵימָא מִלּוּלָךְ סָבָא, אֵימָא בְּלָא דְּחִילוּ.","פָּתַח וְאָמַר, (תהילים ק״ד:א׳) יְיָ' אֱלהַי גָּדַלְתָּ מְאֹד הוֹד וְהָדָר לָבָשְׁתָּ. יְיָ' אֱלהַי: (ט' ע\"א, רי\"ו ע\"ב) דָּא שֵׁירוּתָא דִּמְהֵימְנוּתָא, סְלִיקוּ דְּמַחֲשָׁבָה, וְעָלְמָא דְּאָתֵי, רָזָא חֲדָא בְּלָא פִּרוּדָא. גָּדַלְתָּ: דָּא שֵׁירוּתָא, יוֹמָא קַדְמָאָה, וְאִינּוּן יוֹמִין עַתִּיקִין, סִטְרָא דִּימִינָא. מְאֹד: דָּא (ס\"ח ע\"ב) הוּא סִטְרָא דִּשְׂמָאלָא.","הוֹד וְהָדָר לָבַשְׁתָּ: אִלֵּין תְּרֵין בַּדֵּי (ויחי רכ\"ב) עֲרָבוֹת. עַד הָכָא, כֵּיוָן דְּמָטָא לְגוֹ אִילָנָא דְּחַיֵּי, אִתְטָמַּר, וְלָא אִסְתַּלָּק (ס\"א ולא בעי) לְמֶהֱוֵי בְּמִנְיָינָא, בְּגִין הַהוּא מְאֹד. מַאי מְאֹד. שְׂמָאלָא, דְּכָל עַנְפִּין דִּלְתַתָּא וּבִכְלָלָא עֲנָפָא מְרִירָא חֲדָא. וְעַל דָּא אִתְטָמַּר הַהוּא אִילָנָא דְּחַיֵּי, וְלָא בָּעָא לְמֶהֱוִי בְּמִנְיָינָא דָּא, עַד דְּאַהֲדָר כְּמִלְּקַדְּמִין, וְשַׁבַּח בְּגַוְונָא אַחֲרָא."],[[0,"ת\"ח כל ההוא וכו':","בוא וראה, כל מי שזכה לי\"ג שנים והלאה נקרא בן לכנסת ישראל, שהיא המלכות. וכל מי שהוא מבן עשרים ומעלה, וזוכה בהם, נקרא בן אל הקב\"ה ודאי, דהיינו ז\"א, כמ\"ש בנים אתם לה' אלקיכם."],[0,"","פירוש. יש ב' מיני ג\"ר, יש ג\"ר הנמשכים מישסו\"ת, והם מוחין דנשמה לזו\"ן. ורק זו\"ן הקטנים המלבישים לז\"א מחזה ולמטה, הם מקבלים ג\"ר אלו. אבל ז\"א עצמו עדיין נשאר בבחי' ו\"ק חסר ג\"ר. עד שנמשכים לו הג\"ר דאו\"א עלאין, ואז גם ז\"א עצמו משיג ג\"ר. והם מוחין דחיה. וזו\"ן הקטנים, שלהם מספיק גם ג\"ר דישסו\"ת, שנבחנים שניהם לבחינת מלכות, להיותם מלבישים במקום מחזה ולמטה דז\"א, שמקום זה שייך כולו למלכות. וכן הוא בתחתונים, שאם אדם משיג מוחין דנשמה, הוא מקבל אותם מזו\"ן הקטנים שהם מקבלים מישסו\"ת. ואם אדם משיג מוחין דחיה הוא מקבל אותם מז\"א עצמו. וכשהוא בן י\"ג שנה ומעלה מקבל מוחין דנשמה. וכשהוא בן עשרים ומעלה מקבל מוחין דחיה."],[0,"","וזה אמרו, \u0003כל ההוא דזכי לי\"ג שנין ולהלאה אקרי בן לכנסת ישראל.\u0004 כי אז מקבל מוחין דנשמה מזו\"ן הקטנים ששניהם הם כנסת ישראל שהיא מלכות. וע\"כ נקרא בן אליה. אבל לא לז\"א עצמו, כנ\"ל. \u0003וכל מאן דאיהו מבן כ' שנין ולמעלה וזכי בהו, אקרי בן לקב\"ה.\u0004 כי אז מקבל מוחין דחיה מז\"א עצמו המקבל מאו\"א עלאין. וע\"כ נקרא בן לז\"א דהיינו להקב\"ה."],[1,"כד מטא דוד וכו':","כשהגיע דוד לי\"ג שנים, וזכה ביום ההוא שנכנס לי\"ד, אז כתוב, ה' אמר אלי בני אתה אני היום ילדתיך. מה הטעם. כי מקודם לכן לא היה בן אליו, שלא שרתה עליו נשמה העליונה, כי בשני ערלה היה, ומשום זה כתוב, אני היום ילדתיך, היום ודאי ילדתיך. \u0003אני,\u0004 ולא הצד האחר, כמו שהיה עד עתה. אבל עתה אני בלבדי. בן עשרים שנה, מה כתוב בשלמה, כי בן הייתי לאבי \u0003לאבי\u0004 ממש ודאי. דהיינו להקב\"ה. שהוא בכ' שנים זכה למוחין דחיה, ונעשה על ידיהם בן להקב\"ה, דהיינו לז\"א."],[2,"ואם לבנו ייעדנה:","היינו מי\"ג שנים ולהלאה, שאז יוצא מרשות הצד האחר שנזדמן לו, מה כתוב, כמשפט הבנות יעשה לה. מהו כמשפט הבנות. ומשיב, למדנו, בכל יום ויום רואה הקב\"ה את ילד ההוא העומד ברשות הערלה, והוא יוצא ממנה, ונמשך לבית הספר ומשבר אותה, והולך לבית הכנסת ומשבר אותה. מה עושה הקב\"ה לנשמה ההיא, הוא מכניסה אל חדרו, ונותן לה מתנות ומנחות רבות ומקשט אותה בקשוטים עליונים, עד הזמן שמביאה לחופה בבן ההוא, דהיינו שמלבישה בו, מי\"ג, שנים ולמעלה."],[3,"אם אחרת יקח לו:","מהו אחרת. כאן יש סודי סודות, ונמסרו לחכמים. ויש להודיע תחילה דבר אחד. בוא וראה, ביום השבת, בשעה שנתקדש היום, יוצאות נשמות מתוך עץ החיים, דהיינו ז\"א, ואלו הנשמות נושבות לתחתונים, ונחים התחתונים בהן כל יום השבת. שהן סוד נשמה יתירה שצדיקים משיגים ביום השבת. ואחר שיוצא השבת, חוזרות ועולות כל הנשמות ומתעטרות בעטרות קדושות למעלה. אף כך, כאן, הקב\"ה מזמין לאדם ההוא ביום השבת נשמה יתירה, וזו היא נשמה אחרת, שעליה אומר הכתוב ואם אחרת יקח לו. ואע\"פ שנזדמנה לו נשמה זו, הנשמה שהיה לו מתחילה שארה של הראשונה, וכסותה ועונתה לא יגרע. שפירושם כמו שנתבאר. (לעיל באות ס\"ח)."],[4,"בכה ההוא סבא וכו':","בכה זקן ההוא כבתחילה, ואמר הוא לעצמו, זקן זקן, כמה יגעת להשיג דברים הקדושים האלו, ועתה תאמר אותם ברגע אחד. ואם תאמר לחוס עליהם על אלו הדברים ולא תאמר אותם, הרי כתוב אל תמנע טוב מבעליו בהיות לאל ידך לעשות."],[5,"מאי אל תמנע טוב מבעליו:","מהו הפירוש של אל תמנע טוב מבעליו. ואומר, אלא הקב\"ה וכנסת ישראל, שהיא המלכות, הם כאן. כי בכל מקום שנאמרים דברי תורה, הקב\"ה וכנסת ישראל הם שם, ומקשיבים להם. ואז, עץ ההוא של טוב ורע, שהוא המלכות, בשעה שהקב\"ה וכנסת ישראל הולכים משם, ומקשיבים דברי תורה אלו, צד ההוא של \u0003הטוב\u0004 מתגבר ומתעלה למעלה, והקב\"ה וכנסת ישראל מתעטרים \u0003בטוב\u0004 ההוא, ואלו הם בעליו של \u0003טוב\u0004 ההוא. וע\"כ על הקב\"ה וכנסת ישראל נאמר אל תמנע טוב מבעליו."],[6,"סבא סבא, את וכו':","שוב אמר לעצמו, זקן זקן, אתה אמרת דברים אלו, ולא ידעת אם הקב\"ה כאן, ואם אלו העומדים כאן הם כדאים לדברים האלו. אל תירא זקן, כי היית בכמה מלחמות עם אנשים גבורים ולא יראת, ועתה אתה מתירא. אמור דבריך, כי ודאי כאן הם הקב\"ה וכנסת ישראל, וצדיקים הם אלו שבכאן. ואם לא היה כן, לא פגשתי אותם, ולא התחלתי בדברים האלו. אמור דבריך זקן. אמור בלי פחד."],[7,"פתח ואמר ה' וכו':","פתח ואמר, ה' אלקי גדלת מאד הוד והדר לבשת. \u0003ה' אלקי,\u0004 זהו תחילת האמונה, עלית המחשבה, שהוא חכמה, ועולם הבא שהוא בינה, והם בסוד אחד, בלא פרוד. כי או\"א שהם חו\"ב, הם תרין רעין דלא מתפרשין לעלמין. \u0003גדלת,\u0004 זהו התחלה, לז\"ס תחתונות, יום הראשון, שהוא ספירה ראשונה \u0003חסד,\u0004 והם ימים עתיקים, דהיינו שהיא מקבלת מספירות דעתיק, והיא צד ימין. \u0003מאד\u0004 זה הוא צד שמאל, דהיינו \u0003גבורה.\u0004"],[8,"הוד והדר לבשת:","אלו הם ב' בדי ערבות, שהם \u0003נצח והוד.\u0004 עד כאן אמר, כיון שהגיע לעץ החיים, שהוא \u0003תפארת,\u0004 נחבא, ולא עלה להיות במנין, משום \u0003מאד\u0004 הזה. מהו \u0003מאד.\u0004 הוא שמאל, שכל הענפים שלמטה שבכללם ענף מר אחד, שהוא סמאל, נכללים בשמאל. וע\"כ נחבא עץ החיים ההוא, ולא רצה להיות במנין הזה עד שחזר כבתחילה, ושבח באפן אחר."]],[[0,"","בֹּא וּרְאֵה, כָּל מִי שֶׁהוּא זוֹכֶה לִשְׁלֹשׁ עֶשְׂרֵה שָׁנִים וָמַעְלָה, נִקְרָא בֵּן לִכְנֶסֶת יִשְׂרָאֵל. וְכָל מִי שֶׁהוּא מִבֶּן עֶשְׂרִים שָׁנָה וָמַעְלָה וְזוֹכֶה בָהֶם, נִקְרָא בֵּן לַקָּדוֹשׁ-בָּרוּךְ-הוּא וַדַּאי. (דברים יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם."],[1,"","כְּשֶׁהִגִּיעַ דָּוִד לִשְׁלֹשׁ עֶשְׂרֵה שָׁנָה וְזָכָה בְּאוֹתוֹ יוֹם שֶׁנִּכְנַס לָאַרְבַּע עֶשְׂרֵה, אָז כָּתוּב (תהלים ב) ה' אָמַר אֵלַי בְּנִי אַתָּה אֲנִי הַיּוֹם יְלִדְתִּיךְ. מָה הַטַּעַם? שֶׁהֲרֵי מִקֹּדֶם לָזֶה לֹא הָיָה לוֹ בֵּן, וְלֹא שָׁרְתָה עָלָיו נְשָׁמָה עֶלְיוֹנָה, שֶׁהֲרֵי בִּשְׁנוֹת עָרְלָה הוּא הָיָה, וּמִשּׁוּם כָּךְ אֲנִי הַיּוֹם יְלִדְתִּיךְ, הַיּוֹם וַדַּאי יְלִדְתִּיךְ. אֲנִי, וְלֹא הַצַּד הָאַחֵר, כְּמוֹ שֶׁהָיָה עַד עַכְשָׁו, אֲנִי לְבַדִּי. בֶּן עֶשְׂרִים שָׁנִים, מַה כָּתוּב בִּשְׁלֹמֹה? (משלי ד) כִּי בֵן הָיִיתִי לְאָבִי, לְאָבִי מַמָּשׁ וַדַּאי."],[2,"","וְאִם לִבְנוֹ יִיעָדֶנָה. בֶּן שְׁלֹשׁ עֶשְׂרֵה שָׁנִים וָמַעְלָה, שֶׁהֲרֵי יָצָא מֵרְשׁוּת הַצַּד הָאַחֵר שֶׁהִזְדַּמֵּן לוֹ. מַה כָּתוּב? כְּמִשְׁפַּט הַבָּנוֹת יַעֲשֶׂה לָהּ. מַה זֶּה כְּמִשְׁפַּט הַבָּנוֹת? שָׁנִינוּ, בְּכָל יוֹם וָיוֹם רוֹאֶה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אוֹתוֹ תִינוֹק שֶׁעוֹמֵד בִּרְשׁוּת הָעָרְלָה, וְהוּא יוֹצֵא מִמֶּנָּה וְנִמְשָׁךְ לְבֵית הַסֵּפֶר, וְשׁוֹבֵר אוֹתָהּ. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתָהּ נְשָׁמָה? מַכְנִיס אוֹתָהּ לַגֹּרֶן (חדר למוד) שֶׁלּוֹ, וְנוֹתֵן לָהּ מַתָּנוֹת וְאוֹצָרוֹת רַבִּים וּמְקַשֵּׁט אוֹתָהּ בְּקִשּׁוּטִים עִלָּאִיִּים, עַד הַזְּמַן שֶׁמַּכְנִיסָהּ לַחֻפָּה עִם אוֹתוֹ (תוך אותו) בֵּן מִשְּׁלֹשׁ עֶשְׂרֵה שָׁנִים וָמַעְלָה."],[3,"","אִם אַחֶרֶת יִקַּח לוֹ. כָּאן יֵשׁ סוֹד הַסּוֹדוֹת שֶׁלַּחֲכָמִים נִמְסְרוּ, וְיֵשׁ לְהוֹדִיעַ בָּרִאשׁוֹנָה דָּבָר אֶחָד. בֹּא וּרְאֵה, בְּיוֹם הַשַּׁבָּת, בְּשָׁעָה שֶׁמִּתְקַדֵּשׁ הַיּוֹם, יוֹצְאוֹת נְשָׁמוֹת מִתּוֹךְ עֵץ הַחַיִּים, וּמְנַשְּׁבוֹת אוֹתָן הַנְּשָׁמוֹת הַקְּדוֹשׁוֹת לַתַּחְתּוֹנִים וְנָחִים בָּהֶם כָּל יוֹם הַשַּׁבָּת. וְאַחַר שֶׁיּוֹצֵאת הַשַּׁבָּת, עוֹלוֹת כָּל הַנְּשָׁמוֹת וּמִתְעַטְּרוֹת בַּעֲטָרוֹת קְדוֹשׁוֹת לְמַעְלָה. (וכשמתעטרותבאותו טוב, אלו הם בעליו של אותו טוב ודאי) אַף כָּאן מַזְמִין הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אוֹתוֹ הָאִישׁ, וְזוֹהִי נְשָׁמָה אַחֶרֶת, וְאַף עַל גַּב שֶׁזּוֹ מְזֻמֶּנֶת לוֹ, הַנְּשָׁמָה שֶׁהָיְתָה לוֹ בָּרִאשׁוֹנָה, שְׁאֵרָהּ הָרִאשׁוֹנָה, כְּסוּתָהּ וְעֹנָתָהּ לֹא יִגְרָע, כְּמוֹ שֶׁנִּתְבָּאֵר."],[4,"","בָּכָה אוֹתוֹ זָקֵן כְּמִקֹּדֶם, וְהוּא אָמַר לְנַפְשׁוֹ, זָקֵן זָקֵן, כַּמָּה יָגַעְתָּ לְהַשִּׂיג דְּבָרִים קְדוֹשִׁים אֵלּוּ, וְעַכְשָׁו תֹּאמַר אוֹתָם בְּרֶגַע אֶחָד?! אִם תֹּאמַר שֶׁתָּחוּס עַל אוֹתָם הַדְּבָרִים וְלֹא תֹאמַר אוֹתָם - הֲרֵי כָּתוּב (משלי ג) אַל תִּמְנַע טוֹב מִבְּעָלָיו בִּהְיוֹת לְאֵל יָדְךְ לַעֲשׂוֹת."],[5,"","מַה זֶּה אַל תִּמְנַע טוֹב מִבְּעָלָיו? אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל הֵם כָּאן, שֶׁהֲרֵי בְּכָל מָקוֹם שֶׁנֶּאֱמָרִים דִּבְרֵי תוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל שָׁם וּמַקְשִׁיבִים לָהֶם. וְאָז אוֹתוֹ עֵץ שֶׁל טוֹב וָרָע, בְּשָׁעָה שֶׁהוֹלְכִים מִשָּׁם וּמַקְשִׁיבִים לְאוֹתָם דְּבָרִים, אוֹתוֹ צַד הַטּוֹב מִתְגַּבֵּר וּמִתְעַלֶּה לְמַעְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עִם כְּנֶסֶת יִשְׂרָאֵל מִתְעַטְּרִים בְּאוֹתוֹ טוֹב, וְאֵלֶּה הֵם בְּעָלָיו שֶׁל אוֹתוֹ טוֹב."],[6,"","זָקֵן זָקֵן, אַתָּה אָמַרְתָּ דְּבָרִים אֵלּוּ וְלֹא יָדַעְתָּ אִם הַקָּדוֹשׁ בָּרוּךְ הוּא כָּאן, וְאִם אֵלֶּה שֶׁעוֹמְדִים כָּאן זַכָּאִים לַדְּבָרִים הָאֵלֶּה. אַל תִּפְחַד, זָקֵן, שֶׁהֲרֵי הָיִיתָ בְּכַמָּה קְרָבוֹת שֶׁל גְּבָרִים חֲזָקִים וְלֹא פָחַדְתָּ, וְעַכְשָׁו אַתָּה פּוֹחֵד?! אֱמֹר דְּבָרֶיךְ, שֶׁהֲרֵי וַדַּאי כָּאן הַקָּדוֹשׁ בָּרוּךְ הוּא עִם כְּנֶסֶת יִשְׂרָאֵל, וְאַשְׁרֵי הֵם אֵלֶּה שֶׁכָּאן. וְאִם לֹא כָּךְ, לֹא הָיִינוּ פּוֹגְשִׁים אוֹתָם וְלֹא הִתְחַלְנוּ בַּדְּבָרִים הַלָּלוּ. אֱמֹר דִּבּוּרְךְ, זָקֵן, אֱמֹר לְלֹא פַּחַד."],[7,"","פָּתַח וְאָמַר, (תהלים קד) ה' אֱלֹהַי גָּדַלְתָּ מְּאֹד הוֹד וְהָדָר לָבָשְׁתָּ. ה' אֱלֹהַי - זוֹ רֵאשִׁית הָאֱמוּנָה, עֲלִיַּת הַמַּחֲשָׁבָה וְהָעוֹלָם הַבָּא, סוֹד אֶחָד בְּלֹא פֵרוּד. גָּדַלְתָּ - זוֹ הָרֵאשִׁית, הַיּוֹם הָרִאשׁוֹן וְאוֹתָם יָמִים עַתִּיקִים, צַד הַיָּמִין. מְאֹד - זֶהוּ צַד הַשְּׂמֹאל."],[8,"","הוֹד וְהָדָר לָבָשְׁתָּ - אֵלּוּ שְׁנֵי בַּדֵּי עֲרָבוֹת. עַד כָּאן, כֵּיוָן שֶׁהִגִּיעַ לְתוֹךְ עֵץ הַחַיִּים, נִטְמַן וְלֹא הִתְעַלֶּה לִהְיוֹת בְּמִנְיָן מִשּׁוּם אוֹתוֹ מְאֹד. מַה זֶּה מְאֹד? הַשְּׂמֹאל, שֶׁכָּל הָעֲנָפִים שֶׁלְּמַטָּה וּבִכְלָל עָנָף מַר אֶחָד. וְלָכֵן נִטְמַן אוֹתוֹ עֵץ הַחַיִּים וְלֹא רָצָה לִהְיוֹת בַּמִּנְיָן הַזֶּה, עַד שֶׁחָזַר כְּמוֹ מִקֹּדֶם וְשִׁבַּח בְּגָוֶן אַחֵר."]]],[["וְאָמַר, עֹטֶה אוֹר כַּשַּׂלְמָא דָּא שֵׁירוּתָא (דאור) דְּיוֹמָא קַדְמָאָה. נוֹטֶה שָׁמַיִם, הָכָא אִתְכְּלִיל שְׂמָאלָא, וְלָא אָמַר מְאֹד, אִתְכְּלִיל שְׂמָאלָא בִּימִינָא, לְמֶהוֵי נָהִיר בִּכְלָלָא דְּשָׁמַיִם. (תהילים ק״ד:ג׳) הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו, הָכָא נָפִיק בְּחֶדְוָה הַהוּא אִילָנָא דְּחַיֵּי, נָהָר דְּנָפִיק מֵעֵדֶן, וְאִשְׁתְּרָשׁוּ בֵּיהּ בְּמֵימוֹי אִינּוּן תְּרֵי בַּדֵּי עֲרָבוֹת, דְּאִינּוּן גַּדְלִין בְּמֵימוֹי, הֲדָא הוּא דִכְתִיב (נ\"א ההוא אילנא דחיי ואשתרשו ביה אינון תרי בדי ערבות, דאינון גדלין במימוי וההוא נהרז דנפיק מעדן ודא הוא) הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו. מַאן עֲלִיּוֹתָיו. אִלֵּין בַּדֵּי עֲרָבוֹת.","וְדָא הוּא דִּכְתִּיב, (ירמיהו י״ז:ח׳) וְעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו. וְדָא הוּא רָזָא דִּכְתִּיב, (תהילים מ״ו:ה׳) נָהָר פְּלָגָיו יְשַׂמְחוּ עִיר אֱלהִים. מַאן פְּלָגָיו. אִלֵּין אִינּוּן שָׁרָשָׁיו. וְהָכִי אִקְרוּן, עֲלִיּוֹתָיו, שָׁרָשָׁיו, פְּלָגָיו, כֻּלְּהוּ אִשְׁתְּרָשׁוּ בְּאִינּוּן מַיִין דְּהַהוּא נָהָר.","(תהילים ק״ד:ג׳) הַשָּׂם עָבִים רְכוּבוֹ. דָּא מִיכָאֵל וְגַבְרִיאֵל, אִלֵּין הֵם עָבִים. הַמְהַלֵּךְ עַל כַּנְפֵי רוּחַ, לְמֵיהַב אַסְוָותָא לְעָלְמָא, וְדָא אִיהוּ רְפָאֵל. מִכָּאן וּלְהָלְאָה עוֹשֶׂה מַלְאָכָיו רוּחוֹת וְגוֹ'. סָבָא סָבָא, אִי כָּל הָנֵי יָדַעְתְּ, אֵימָא וְלָא תִּדְחַל, אֵימָה מִילָךְ וְיִנְהֲרוּן מִלִּין דְּפוּמָךְ. חַדּוּ חַבְרַיָּיא, וַהֲווּ צַיְיתִין בְּחֶדְוָה לְמִלּוֹי קַדִּישִׁין. אָמַר אִי סָבָא אִי סָבָא, בְּמָה עַיְילַת גַּרְמָךְ, עָאלַת בְּיַמָּא רַבָּא, אִית לָךְ לְשַׁטְּטָא וְּלְנָפְקָא מִתַּמָּן.","(שמות כ״א:י׳) אִם אַחֶרֶת יִקַּח לוֹ, כַּמָּה גִּלְגּוּלִין עַתִּיקִין הָכָא, דְּלָא אִתְגַּלּוּן עַד הָאִידָּנָא, וְכֻלְּהוּ קְשׁוֹט כְּדְקָא יֵאוֹת, דְּלֵית לְאַסְטָאָה מֵאֹרַח קְשׁוֹט, אֲפִילּוּ כִּמְלא נִימָא. בְּקַדְמִיתָא (נ\"א השתא) אִית לְאִתְּעָרָא, (צ\"ה ע\"ב) נִשְׁמָתִין דְּגִיּוֹרִין כֻּלְּהוּ, פַּרְחָן מִגּוֹ גִּנְתָּא דְּעֵדֶן בְּאֹרַח סָתִים, כַּד מִסְתַּלְּקָן מֵהַאי עָלְמָא, נִשְׁמָתְהוֹן דְּקָא רְוָוחָא מִגּוֹ גִּנְתָּא דְּעֵדֶן, לְאָן אֲתָר תַּיְיבִין.","אֶלָּא תָּנֵינָן, מַאן דְּנָטִיל וְאָחִיד בְּנִכְסֵי גִּיּוֹרִין בְּקַדְמִיתָא, זָכֵי בְּהוּ. אוּף הָכִי כָּל אִינּוּן נִשְׁמָתִין קַדִּישִׁין עִלָּאִין, דְּקָא זַמִּין לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְתַתָּא כִּדְקָאמְרַן, כֻּלְּהוּ נָפְקִין לְזִמְנִין יְדִיעָן. (וסלקין) (בראשית ל\"ה ע\"ב) בְּגִין לְאִשְׁתַּעְשְׁעָא בְּגַּן עֵדֶן, (דלעילא) וּפַגְעָן בְּאִינּוּן נִשְׁמָתִין דְּגִיּוֹרִין, מַאן דְּאָחִיד בְּהוּ מֵאִלֵּין נִשְׁמָתִין, (דסלקין) אָחִיד בְּהוּ וְזָכֵי בְּהוּ, וּמִתְלַבְּשָׁן בְּהוּ, וְסַלְּקִין. וְכֻלְּהוּ קַיְימֵי בְּהַאי לְבוּשָׁא וְנַחְתּוּ גּוֹ גִּנְתָּא בִּלְבוּשָׁא דָּא. בְּגִין דִּבְגִּנְתָּא דְּעֵדֶן, לָא קַיְּימָאן תַּמָּן, אֶלָּא בִּלְבוּשָׁא, כָּל אִינּוּן דְּקַיְימֵי תַּמָּן.","אִי תֵּימָא, דִּבְגִין הַאי לְבוּשָׁא, גַּרְעָן אִינּוּן נִשְׁמָתִין מִכָּל עִנּוּגָא דְּהֲוָה לוֹן בְּקַדְמִיתָא. הָא כְּתִיב, אִם אַחֶרֶת יִקַּח לוֹ שְׁאֵרָהּ כְּסוּתָהּ וְעוֹנָתָהּ לא יִגְרָע. בְּגִנְתָּא קַיְימֵי בִּלְבוּשֵׁי דָּא, דְּקַדְמָן לְאַחֲדָא בְּהוּ וְזָכֵי בְּהוּ, וְכַד סַלְּקִין לְעֵילָּא, מִתְפַּשְּׁטָן מִנֵּיהּ, דְּהָא תַּמָּן לָא קַיְימָן (קפ\"ו ע\"ב, ר\"י ע\"ב, רכ\"ט, נ', נ\"ח, ס\"ז) בִּלְבוּשָׁא.","בָּכָה הַהוּא סָבָא כְּמִלְּקַדְּמִין, וְאָמַר לְנַפְשֵׁיהּ, סָבָא סָבָא, בְּוַדַּאי אִית לָךְ לְמִבְכֵּי, בְּוַדַּאי אִית לָךְ לְאוֹשָדָא דִּמְעִין, עַל כָּל מִלָּה וּמִלָּה, אֲבָל גַּלֵּי קָמֵי קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ קַדִּישָׁא, דַּאֲנָא בִּרְעוּ דְּלִבָּא, וּבְפוּלְחָנָא דִּלְהוֹן קָאמֵינָא, בְּגִין דְּאִינּוּן בְּעָלָיו דְּכָל מִלָּה, וּמִתְעַטְּרָן בְּהוּ.","כָּל אִינּוּן נִשְׁמָתִין קַדִּישִׁין, כַּד נַחְתֵּי לְהַאי עָלְמָא, בְּגִין לְמִשְׁרֵי כָּל חַד עַל דּוּכְתַּיְיהוּ, דְּאִתְחָזוּן בְּהוּ, לִבְנִי נָשָׁא. כֻּלְּהוּ נַחְתֵּי מִתְלַבְּשָׁן בְּאִינּוּן נִשְׁמָתִין דְּקָא אַמָרָן, וְהָכִי עָאלִין בְזַרְעָא קַדִּישָׁא. וּבְמַלְבּוּשָׁא דָּא, קַיְימֵי לְאִשְׁתַּעְבְּדָא מִנַּיְיהוּ בְּהַאי עָלְמָא. וְכַד אִשְׁתַּאֲבָן אִינּוּן מַלְבּוּשִׁין מִמִּלִּין דְּהַאי עָלְמָא, אִינּוּן נִשְׁמָתִין קַדִּישִׁין, אִתְּזְנָן (נ\"א אתהנון) מֵרֵיחָא דְּקָא אֲרִיחָא, מִגּוֹ לְבוּשֵׁיהוֹן אִלֵּין.","קוּדְשָׁא בְּרִיךְ הוּא כָּל מִלִּין סְתִימִין דְּאִיהוּ עָבִיד, עָאל לוֹן בְּאוֹרַיְיתָא קַדִּישָׁא, וְכֹלָּא אִשְׁתְּכַח בְּאוֹרַיְיתָא, וְהַהִיא מִלָּה סְתִימָא גַּלֵּי לָהּ אוֹרַיְיתָא, וּמִיָּד אִתְלַבְּשָׁא בִּלְבוּשָׁא אַחֲרָא, וְאִתְטָמַּר תַּמָּן, וְלָא אִתְגְּלֵי. וְחַכִּימִין דְּאִינּוּן מַלְיָין עַיְינִין, אַף עַל גַּב דְּהַהִיא מִלָּה אַסְתִּים בִּלְבוּשָׁה (תמן), חָמָאן לָהּ מִגּוֹ לְבוּשָׁה, וּבְשַׁעֲתָא דְּאִתְגְלֵי הַהִיא מִלָּה עַד לָא תֵּיעוּל בִּלְבוּשָׁא, רָמָאן בָּהּ פְּקִיחוּ דְּעֵינָא, וְאַף עַל גַּב דְּמִיָּד אַסְתִּים, לָא אִתְאֲבִיד מֵעֵינַיְיהוּ. (נ\"א מינייהו)","בְּכַמָּה דּוּכְתִּין אַזְהַר קוּדְשָׁא בְּרִיךְ הוּא עַל גִּיּוֹרָא, (בגין) דְּזַרְעָא קַדִּישָׁא, יִזְדָּהֲרוּן בֵּיהּ, וּלְבָתַר נָפִיק מִלָּה סְתִימָא מִנַּרְתִּקָהּ. וְכֵיוָן דְּאִתְגְלֵי אַהְדָּר לְנַרְתִּקָהּ מִיָּד, וְאִתְלָבַשׁ תַּמָּן."],[[0,"ואמר, עוטה אור כשלמה:","זהו התחלה של יום הראשון, דהיינו ספירה ראשונה שהוא \u0003חסד. נוטה שמים,\u0004 הוא \u0003תפארת\u0004 הנקרא שמים, וכאן נכלל צד השמאל שהוא \u0003גבורה,\u0004 ואינו אומר \u0003מאד.\u0004 כי נכלל השמאל בימין שיהיה מאיר בכלל השמים שהוא תפארת \u0003המקרה במים עליותיו,\u0004 כאן יצא בחדוה עץ החיים ההוא, שהוא נהר היוצא מעדן, דהיינו ת\"ת, ונשרשו בו במימיו אלו שני בדי ערבות, שהם נצח והוד, שהם גדלים במימיו, ז\"ש, המקרה במים עליותיו. מי הוא עליותיו. אלו הם בדי ערבות. נו\"ה."],[1,"ודא הוא דכתיב וכו':","וז\"ש ועל יובל ישלח שרשיו. וזהו סוד, שכתוב, נהר פלגיו ישמחו עיר האלקים. מי הם פלגיו, אלו הם שרשיו, דהיינו נצח והוד, וכך נקראים, עליותיו שרשיו פלגיו, כולם נשרשו במים האלו של ההוא נהר, שהוא ת\"ת."],[2,"השם עבים רכובו:","זהו מיכאל וגבריאל, אלו הם עבים. \u0003המהלך על כנפי רוח,\u0004 לתת רפואה לעולם. וזהו רפאל. מכאן ולהלאה, עושה מלאכיו רוחות וגו'. זקן זקן, אם כל אלו ידעת, אמור ולא תפחד, אמור דבריך ויאירו דברי פיך. שמחו החברים, והיו מקשיבים בשמחה לדבריו הקדושים. אמר לעצמו הסבא, אי זקן אי זקן, במה הכנסת עצמך באת בים הגדול יש לך לשוט ולצאת משם."],[3,"אם אחרת יקח לו:","כמה גלגולים ישנים כאן שלא נגלו עד עתה, וכולם אמת כראוי כי אין לנטות מדרך אמת אפילו כמלוא חוט השערה. בתחילה יש להעיר, נשמות הגרים כולם, פורחות מגן העדן בדרך סתום ומתלבשות בגרים. ושואל כשמסתלקים מעולם הזה, הנשמות שהרויחו הגרים מגן עדן לאיזה מקום הן חוזרות. כלומר, מי מעלה אותן בחזרה למקום שיצאו משם, דהיינו לגן עדן."],[4,"אלא תנינן מאן וכו':","אלא למדנו, מי שלוקח ואוחז מתחילה בנכסי הגר, שאין לו יורשים, זוכה בהם. אף כאן, כל אלו נשמות הקדושות העליונות, שהקב\"ה הזמין אותם לבא למטה, כמו שאמרנו, כולן יוצאות בזמנים ידועים, דהיינו בשבת ויו\"ט ור\"ח, להשתעשע בגן עדן ופוגשות באלו נשמות הגרים, מי מאלו הנשמות שאוחזת בהן, זוכית בהן, ומתלבשות בהן ועולות. וכולן עומדות בלבוש הזה, ויורדות לגן העדן בלבוש הזה, משום שבגן העדן אינם עומדים שם אלא בלבוש, כל אלו הנמצאים שם. ונמצא, שאותן הנשמות מעלים את נשמות הגרים בחזרה לגן העדן."],[5,"אי תימא דבגין וכו':","אם תאמר, שבשביל לבוש ההוא, של נשמות הגרים, גורעים לנשמות האלו מכל הענג שהיה להם מתחילה, על זה כתוב, אם אחרת יקח לו שארה כסותה ועונתה לא יגרע. בגן העדן עומדות בלבוש הזה, שקדמו לאחוז בהם וזכו בהם, דהיינו הלבוש מנשמות הגרים, וכשעולים למעלה, מתפשטות ממנו, כי שם למעלה, אין עומדים בלבוש."],[6,"בכה ההוא סבא וכו':","בכה זקן ההוא כבתחילה, ואמר לעצמו, זקן זקן, בודאי יש לך לבכות בודאי יש לך לשפוך דמעות על כל מלה ומלה. אבל גלוי לפני הקב\"ה ושכינתו הקדושה, שאני בחפץ לב ובעבודתם אני אומר, משום שהם בעליו של כל מלה, והם מתעטרים בהן."],[7,"כל אינון נשמתין וכו':","כל אלו הנשמות הקדושות כשיורדות לעולם הזה, כדי שכל אחת תשרה על מקומה הראוי להם, בבני אדם. כולן יורדות מתלבשות באלו נשמות הגרים שאמרנו, וכך נכנסות בזרע הקדוש ובמלבוש הזה עומדות להשתעבד מהם בעולם הזה, במצוות ובמעשים טובים, וכשנשתאבו המלבושים מדברי עולם הזה, דהיינו המצות, אלו נשמות הקדושות נזונות מן הריח שמריחות מן לבושיהן האלו."],[7,"","פירוש. שהמלבושים מנשמות הגרים נעשו אמצעים בין הנשמות ובין הגוף, והמצות שאדם עושה מגיעים למלבושים, והנשמות מקבלים מזונות מריח שמריחים מן המלבושים וז\"ש \u0003ובמלבושא דא קיימי לאשתעבדא מנייהו.\u0004 שהנשמות עצמן גבוהות ואינן משתעבדות ממעשה הגוף, אלא המלבושים שלהן משתעבדות במעשה המצות. \u0003וכד אשתאבן אינון מלבושין וכו':\u0004 מקבלות הנשמות מריח המלבושים."],[8,"קב\"ה, כל מלין סתימין וכו':","הקב\"ה, כל דברים הסתומים שעושה, הכניסם בתורה הקדושה, והכל נמצא בתורה. ודבר סתום ההוא מגלה אותו התורה, ומיד מתלבשת בלבוש אחר ומסתתרת שם, ואינה מתגלית. והחכמים שהם מלאים עינים, אע\"פ שהדבר ההוא נסתתר בלבוש שלו, הם רואים אותו מתוך הלבוש, ובשעה שנתגלה דבר ההוא, מטרם שנכנס בחזרה ללבושו, מטילים בו פקיחת עינים, ואע\"פ שנעלם מיד, אינו נאבד עוד מעיניהם."],[9,"בכמה דוכתין אזהר וכו':","בכמה מקומות הזהיר הקב\"ה על הגר, שזרע הקדוש, דהיינו ישראל, יהיו נזהרים בו, ושלאחר זה יצא דבר הסתום מנרתיקו, דהיינו מן הכיסוי שלו, ולאחר שנגלה חזר מיד לנרתיקה ומתלבש שם."]],[[0,"","וְאָמַר, עֹטֶה אוֹר כַּשַּׂלְמָה - זוֹ רֵאשִׁיתוֹ (של האור) שֶׁל הַיּוֹם הָרִאשׁוֹן. נוֹטֶה שָׁמַיִם - כָּאן נִכְלָל הַשְּׂמֹאל, וְלֹא אָמַר מְאֹד, נִכְלָל הַשְּׂמֹאל בַּיָּמִין לִהְיוֹת מֵאִיר בִּכְלָל שֶׁל שָׁמַיִם. הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו - כָּאן יוֹצֵא בְשִׂמְחָה אוֹתוֹ עֵץ הַחַיִּים, הַנָּהָר שֶׁיּוֹצֵא מֵעֵדֶן, וְנִשְׁרְשׁוּ בוֹ בְּמֵימָיו אוֹתָם שְׁנֵי בַּדֵּי עֲרָבוֹת, שֶׁהֵם גְּדֵלִים בְּמֵימָיו. זֶהוּ שֶׁכָּתוּב (אותו אילן החיים, ונשרשו בו אותם שני בדי ערבות, שהם גדלים במימיו, ואותו נהר יוצא מעדן, וזהו) (תהלים קד) הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו. מִי הֵם עֲלִיּוֹתָיו? אֵלּוּ בַּדֵּי עֲרָבוֹת."],[1,"","וְזְהִוּ שֶׁכָּתוּב (ירמיה יז) וְעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו. וְזֶהוּ סוֹד הַכָּתוּב (תהלים מו) נָהָר פְּלָגָיו יְשַׂמְּחוּ עִיר אֱלֹהִים. מִי הֵם פְּלָגָיו? אֵלּוּ הֵם שָׁרָשָׁיו, וְכָךְ נִקְרָאִים. עֲלִיּוֹתָיו, שָׁרָשָׁיו, פְּלָגָיו - כֻּלָּם נִשְׁרְשׁוּ בְּאוֹתָם הַמַּיִם שֶׁל אוֹתוֹ נָהָר."],[2,"","הַשָּׂם עָבִים רְכוּבוֹ - זֶה מִיכָאֵל וְגַבְרִיאֵל, אֵלֶּה הֵם עָבִים. הַמְהַלֵּךְ עַל כַּנְפֵי רוּחַ, לָתֵת רְפוּאָה לָעוֹלָם, וְזֶהוּ רְפָאֵל. מִכָּאן וָהָלְאָה עֹשֶׂה מַלְאָכָיו רוּחוֹת וְגוֹ'. זָקֵן זָקֵן, אִם כָּל אֵלֶּה יָדַעְתָּ, אֱמֹר וְאַל תִּפְחַד, אֱמֹר דְּבָרֶיךְ וְיָאִירוּ דִּבְרֵי פִיךְ! שָׂמְחוּ הַחֲבֵרִים, וְהָיוּ מַקְשִׁיבִים בְּשִׂמְחָה לִדְבָרָיו הַקְּדוֹשִׁים. אָמַר, אִי זָקֵן, אִי זָקֵן, בַּמָּה הִכְנַסְתָּ אֶת עַצְמְךְ, נִכְנַסְתָּ לַיָּם הַגָּדוֹל? יֵשׁ לְךְ לְשׁוֹטֵט וְלָצֵאת מִשָּׁם."],[3,"","אִם אַחֶרֶת יִקַּח לוֹ. כַּמָּה גִלְגּוּלִים עַתִּיקִים יֵשׁ כָּאן שֶׁלֹּא הִתְגַּלּוּ עַד עַכְשָׁו, וְכֻלָּם אֱמֶת כָּרָאוּי, שֶׁאֵין לִסְטוֹת מִדֶּרֶךְ אֱמֶת אֲפִלּוּ כִּמְלֹא נִימָה. בַּתְּחִלָּה (עתה) יֵשׁ לְהִתְעוֹרֵר, נִשְׁמוֹת הַגֵּרִים כֻּלָּן פּוֹרְחוֹת מִתּוֹךְ גַּן עֵדֶן בְּדֶרֶךְ נִסְתָּר. כְּשֶׁמִּסְתַּלְּקוֹת מִן הָעוֹלָם הַזֶּה, נִשְׁמוֹתָם שֶׁהִרְוִיחוּ מִתּוֹךְ גַּן הָעֵדֶן, לְאֵיזֶה מָקוֹם חוֹזְרוֹת?"],[4,"","אֶלָּא שָׁנִינוּ, מִי שֶׁנּוֹטֵל וְאוֹחֵז בְּנִכְסֵי הַגֵּר בַּתְּחִלָּה, זוֹכֶה בָהֶם. אַף כָּךְ כָּל אוֹתָן הַנְּשָׁמוֹת הַקְּדוֹשׁוֹת הָעֶלְיוֹנוֹת שֶׁמַּזְמִין אוֹתָן הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַטָּה, כְּפִי שֶׁאָמַרְנוּ, כֻּלָּן יוֹצְאוֹת לִזְמַנִּים יְדוּעִים, (ועולות) כְּדֵי לְהִשְׁתַּעֲשֵׁעַ בְּגַן עֵדֶן (העליון), וּפוֹגְעוֹת בְּאוֹתָן נִשְׁמוֹת הַגֵּרִים. מִי שֶׁאוֹחֵז בָּהֶן מֵאוֹתָן הַנְּשָׁמוֹת (שעולות), אוֹחֵז בָּהֶם וְזוֹכֶה בָהֶם, וּמִתְלַבְּשִׁים בָּהֶם וְעוֹלִים. וְכֻלָּן עוֹמְדוֹת בִּלְבוּשׁ זֶה, וְיָרְדוּ לְתוֹךְ הַגָּן בַּלְּבוּשׁ הַזֶּה, מִשּׁוּם שֶׁבְּגַן עֵדֶן לֹא עוֹמְדוֹת שָׁם אֶלָּא בִּלְבוּשׁ כָּל אֵלּוּ שֶׁעוֹמְדוֹת שָׁם."],[5,"","אִם תֹּאמַר שֶׁבִּשְׁבִיל הַלְּבוּשׁ הַזֶּה גּוֹרְעִים אוֹתָן נְשָׁמוֹת מִכָּל הָעֹנֶג שֶׁהָיָה לָהֶן בַּתְּחִלָּה, הֲרֵי כָּתוּב אִם אַחֶרֶת יִקַּח לוֹ שְׁאֵרָהּ כְּסוּתָהּ וְעֹנָתָהּ לֹא יִגְרָע? בַּגָּן עוֹמְדוֹת בִּלְבוּשׁ זֶה, שֶׁקָּדְמוּ לֶאֱחֹז בָּהֶם וְזוֹכוֹת בָּהֶם, וּכְשֶׁעוֹלוֹת לְמַעְלָה מִתְפַּשְּׁטוֹת מִמֶּנּוּ, שֶׁהֲרֵי שָׁם לֹא עוֹמְדוֹת בִּלְבוּשׁ."],[6,"","בָּכָה אוֹתוֹ זָקֵן כְּמִקֹּדֶם וְאָמַר לְנַפְשׁוֹ, זָקֵן זָקֵן, בְּוַדַּאי יֵשׁ לְךְ לִבְכּוֹת, בְּוַדַּאי יֵשׁ לְךְ לִשְׁפֹּךְ דְּמָעוֹת עַל כָּל דָּבָר וְדָבָר, אֲבָל גָּלוּי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ הַקְּדוֹשָׁה שֶׁאֲנִי בִּרְצוֹן הַלֵּב וּבַעֲבוֹדָתָם אָמַרְתִּי, מִשּׁוּם שֶׁהֵם בְּעָלָיו שֶׁל כָּל דָּבָר וּמִתְעַטְּרִים בָּהֶם."],[7,"","כָּל אוֹתָן נְשָׁמוֹת קְדוֹשׁוֹת, כְּשֶׁיּוֹרְדוֹת לָעוֹלָם הַזֶּה כְּדֵי לִשְׁרוֹת כָּל אַחַת עַל מְקוֹמָן שֶׁרְאוּיִים לָהֶם לִבְנֵי אָדָם, כֻּלָּן יוֹרְדוֹת מְלֻבָּשׁוֹת בְּאוֹתָן הַנְּשָׁמוֹת שֶׁאָמַרְנוּ, וְכָךְ נִכְנָסוֹת לְזֶרַע הַקֹּדֶשׁ. וּבְמַלְבּוּשׁ זֶה עוֹמְדוֹת לְהִשְׁתַּעְבֵּד מֵהֶם בָּעוֹלָם הַזֶּה. וּכְשֶׁנִּשְׁאָבִים אוֹתָם לְבוּשִׁים מִדִּבְרֵי הָעוֹלָם הַזֶּה, אוֹתָן נְשָׁמוֹת קְדוֹשׁוֹת נִזּוֹנוֹת (נהנות) מֵהָרֵיחַ שֶׁמֵּרִיחַ מִתּוֹךְ הַלְּבוּשִׁים הַלָּלוּ."],[8,"","כָּל הַדְּבָרִים הַנִּסְתָּרִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה, הִכְנִיס אוֹתָם לַתּוֹרָה הַקְּדוֹשָׁה, וְהַכֹּל נִמְצָא בַּתּוֹרָה, וְאוֹתוֹ דָבָר נִסְתָּר גִּלְּתָה אוֹתוֹ הַתּוֹרָה, וּמִיָּד הִתְלַבֵּשׁ בִּלְבוּשׁ אַחֵר, וְנִטְמַן שָׁם וְלֹא הִתְגַּלָּה. וְהַחֲכָמִים שֶׁהֵם מְלֵאִים עֵינַיִם, אַף עַל גַּב שֶׁאוֹתוֹ הַדָּבָר נִסְתָּר בִּלְבוּשׁוֹ (שם), רוֹאִים אוֹתוֹ מִתּוֹךְ לְבוּשׁוֹ, וּבְשָׁעָה שֶׁהִתְגַּלָּה אוֹתוֹ דָבָר, טֶרֶם יִכָּנֵס לַלְּבוּשׁ, זוֹרְקִים בּוֹ פְּקִיחַת עַיִן, וְאַף עַל גַּב שֶׁמִּיָּד נִסְתָּר, לֹא נֶאֱבָד מֵעֵינֵיהֶם (נ\"א מהם)."],[9,"","בְּכַמָּה מְקוֹמוֹת הִזְהִיר הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הַגֵּר (כדי) שֶׁיִּזָּהֲרוּ בוֹ זֶרַע הַקֹּדֶשׁ, וְאַחַר הוֹצִיא דָבָר נִסְתָּר מִנַּרְתִּיקוֹ. וְכֵיוָן שֶׁהִתְגַּלָּה, חוֹזֵר מִיָּד לְנַרְתִּיקוֹ וְהִתְלַבֵּשׁ שָׁם."]]],[["כֵּיוָן דְּאַזְהַר עַל גִּיּוֹרָא בְּכָל אִינּוּן דּוּכְתִּין, נָפַק מִלָּה מִנַּרְתִּקָהּ וְאִתְגְּלֵי, וְאָמַר (שמות כ״ג:ט׳) וְאַתֶּם יְדַעְתֶּם אֶת נֶפֶשׁ הַגֵר. מִיָּד עָאלַת לְנַרְתִּקָהּ, וְאָהַדְרַת בִּלְבוּשָׁה וְאִתְטַמְּרַת, דִּכְתִּיב כִּי גֵּרִים היִיתֶם בְּאֶרֶץ מִצְרָיִם, דְּחָשִׁיב קְרָא, דִּבְגִין דְּאִתְלְבַּשׁ מִיָּד, לָא הֲוָה מַאן דְּאַשְׁגַּח בָּהּ. בְּהַאי נֶפֶשׁ הַגֵר, יַדְעַת נִשְׁמְתָא קַדִּישָׁא בְּמִלִּין דְּהַאי עָלְמָא, וְאִתְהֲנִיאַת (ואשתאבת) מִנַּיְיהוּ.","פָּתַח הַהוּא סָבָא וְאָמַר, (שמות כ״ד:י״ח) וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן וַיַּעַל אֶל הָהָר וְגוֹ', עָנָן דָּא מַאי הִיא. אֶלָּא דָּא הוּא דִּכְתִּיב, (בראשית ט׳:י״ג) אֶת קַשְׁתִּי נָתַתִּי בֶּעָנָן. תָּנֵינָן, דְּהַהוּא קֶשֶׁת אַשְׁלַחַת לְבוּשׁוֹי, וְיָהִיב לוֹן לְמֹשֶׁה, (רכ\"ט ע\"א) וּבְהַהוּא לְבוּשָׁא סָלִיק מֹשֶׁה לְטוּרָא וּמִנֵּיהּ חָמָא מַה דְּחָמָא, וְאִתְהֲנֵי מִכֹּלָּא. עַד הַהוּא אֲתָר, אָתוּ אִינּוּן חַבְרַיָּיא, וְאִשְׁתְּטָחוּ קָמֵיהּ דְּהַהוּא סָבָא, וּבָכוּ וְאָמְרוּ, אִלְמָלֵא לָא אֲתֵינָא לְעָלְמָא, אֶלָּא לְמִשְׁמַע מִלִּין אִלֵּין מִפּוּמָךְ דַּי לָן.","אָמַר הַהוּא סָבָא, (אם אחרת יקח לו) חַבְרַיָּיא, לָאו בְּגִין דָּא בִּלְחוֹדוֹי שָׁרֵינָא מִלָּה, דְּהָא סָבָא כְּגִינִי, לָאו בְּמִלָּה חֲדָא עָבִיד קִישׁ קִישׁ, וְלָא קָרֵי, כַּמָּה בְּנֵי עָלְמָא בְּעִרְבּוּבְיָא בְּסָכְלְתָנוּ דִּלְהוֹן, וְלָא חָמָאן בְּאֹרַח קְשׁוֹט בְּאוֹרַיְיתָא, וְאוֹרַיְיתָא קָרֵי בְּכָל יוֹמָא בִּנְהִימוּ (נ\"א ברחימו) לְגַבַּיְיהוּ, (דבני נשא) וְלָא בָּעָאן לְאָתָבָא רֵישָׁא.","וְאַף עַל גַּב דַּאֲמֵינָא, דְּהָא אוֹרַיְיתָא מִלָּה נָפְקָא מִנַּרְתִּקָהּ, וְאִתְחֲזִיאַת זְעֵיר, וּמִיָּד אִתְטַמָּרַת. הָכִי הוּא וַדַּאי. וּבְזִמְנָא דְּאִתְגְּלִיאַת מִגּוֹ נַרְתִּקָהּ וְאִתְטַמְּרַת מִיָּד, לָא עַבְדַת דָּא, אֶלָּא לְאִינוּן דְּיַדְעִין בָּהּ, וְאִשְׁתְּמוֹדְעָאן בָּהּ.","מָשָׁל לְמָה הַדָּבָר דּוֹמֶה, לִרְחִימָתָא, דְּאִיהִי (צ\"ה ע\"א) שַׁפִּירְתָּא בְּחֵיזוּ, וּשְׁפִירְתָּא בְּרֵיוָא, וְאִיהִי טְמִירְתָּא בִּטְמִירוּ גּוֹ הֵיכָלָא דִּילָהּ, וְאִית לָהּ רְחִימָא יְחִידָאָה, דְּלָא יַדְעִין בֵּיהּ בְּנֵי נָשָׁא, אֶלָּא אִיהוּ בִּטְמִירוּ. הַהוּא רְחִימָא, מִגּוֹ רְחִימָא דְּרָחִים לָהּ עָבַר לִתְרַע בֵּיתָה תָּדִיר, זָקִיף עֵינוֹי לְכָל סְטָר. אִיהִי, יַדְעַת דְּהָא רְחִימָא אַסְחַר תְּרַע בֵּיתָה תָּדִיר, מָה עַבְדַת, פָּתְחַת פִּתְחָא זְעֵירָא בְּהַהוּא הֵיכָלָא טְמִירָא, דְּאִיהִי תַּמָּן, וּגְלִיאַת אַנְפָּהָא לְגַבֵּי רְחִימְאָה, וּמִיָּד אִתְהַדְּרַת וְאִתְכַּסִיאַת. כָּל אִינּוּן דַּהֲווֹ לְגַבֵּי רְחִימָא, לָא חָמוּ וְלָא אִסְתַּכָּלוּ, בַּר רְחִימָא בִּלְחוֹדוֹי, וּמֵעוֹי וְלִבֵּיהּ וְנַפְשֵׁיהּ אָזְלוּ אֲבַתְרָהּ. וְיָדַע דְּמִגּוֹ רְחִימוּ דִּרְחִימָת לֵיהּ, אִתְגְּלִיאַת לְגַבֵּיהּ רִגְעָא חֲדָא, לְאִתְּעָרָא (ס\"א לגביה רחימו ליה). הָכִי הוּא מִלָּה דְּאוֹרַיְיתָא, לָא (ר\"ל ע\"ב) אִתְגְּלִיאַת, אֶלָּא לְגַבֵּי רְחִימְאָה. יַדְעַת אוֹרַיְיתָא, דְּהַהוּא חַכִּימָא דְּלִבָּא אַסְחַר לִתְרַע בֵּיתָה כָּל יוֹמָא, מָה עַבְדַת, גְּלִיאַת אַנְפָּהָא לְגַבֵּיהּ, מִגּוֹ הֵיכָלָא, וְאַרְמִיזַת לֵיהּ רְמִיזָא, וּמִיָּד אָהַדְרַת לְאַתְרָהּ וְאִתְטַמְּרַת. כָּל אִינּוּן דְּתַמָּן, לָא יַדְעֵי, וְלָא מִסְתַּכְּלֵי, אֶלָּא אִיהוּ בִּלְחוֹדוֹי, וּמֵעוֹי וְלִבֵּיהּ וְנַפְשֵׁיהּ אָזִיל אֲבַתְרָהּ. וְעַל דָּא, אוֹרַיְיתָא אִתְגְּלִיאַת וְאִתְכַּסִּיאַת, וְאַזְלַת בִּרְחִימוּ לְגַבֵּי רְחִימְהָא, לְאִתְּעָרָא בַּהֲדֵיהּ רְחִימוּ.","תָּא חֲזֵי, אָרְחָא דְּאוֹרַיְיתָא כַּךְ הוּא, בְּקַדְמִיתָא כַּד שַׁרְיָא לְאִתְגַּלָּאָה לְגַבֵּי בַּר נָשׁ, (ברגעא) אַרְמִיזַת לֵיהּ בִּרְמִיזוּ, אִי יָדַע טָב. וְאִי לָא יָדַע, שַׁדְרַת לְגַבֵּיהּ, וְקָרָאתָ לֵיהּ פֶּתִי. וְאַמְרַת אוֹרַיְיתָא, לְהַהוּא דְּשַׁדְרַת לְגַבֵּיהּ, אִמְרוּ לְהַהוּא פֶּתִי, דְּיִקְרַב הָכָא, וְאִשְׁתָּעֵי בַּהֲדֵיהּ. הֲדָא הוּא דִכְתִיב, (משלי ט׳:ד׳) מִי פֶּתִי יָסוּר הֵנָּה חָסֵר לֵב וְגוֹ'. קָרִיב לְגַבָּהּ, שָׁרִיאַת לְמַלְּלָא עִמֵּיהּ, מִבָּתַר פָּרוֹכְתָּא דְּפַרְסָא לֵיהּ, מִלִּין לְפוּם אָרְחוֹי, עַד דְּיִסְתַּכַּל זְעֵיר זְעֵיר, וְדָא הוּא דְּרָשָׁא.","לְבָתַר, תִּשְׁתָּעֵי בַּהֲדֵיהּ, מִבָּתַר שׁוּשִׁיפָא דָּקִיק, מִלִּין דְּחִידָה, וְדָא אִיהוּ הַגָּדָה. לְבָתַר דְּאִיהוּ רָגִיל לְגַבָּהּ, אִתְגְּלִיאַת לְגַבֵּיהּ אַנְפִּין בְּאַנְפִּין, וּמְלִילַת בַּהֲדֵיהּ כָּל רָזִין סְתִימִין דִּילָהּ, וְכָל אָרְחִין סְתִימִין, דַּהֲווֹ בְּלִבְּאָה טְמִירִין, מִיּוֹמִין קַדְמָאִין. כְּדֵין אִיהוּ בַּר נָשׁ שְׁלִים, בַּעַל תּוֹרָה וַדַּאי, מָארֵי דְּבֵיתָא, דְּהָא כָּל רָזִין דִּילָהּ גְּלִיאַת לֵיהּ, וְלָא רְחִיקַת, וְלָא כַּסִּיאַת מִינֵּיהּ כְּלוּם."],[[0,"כיון דאזהר וכו':","כיון שהזהיר על הגר בכל אלו המקומות, יצא הדבר מנרתקה, ונתגלה ואמר, כי אתם ידעתם את נפש הגר, דהיינו מתוך שהנשמות מלובשות בו כנ\"ל, ומיד נכנסת לנרתקה וחוזרת ללבושה ומסתתרת שכתוב, כי גרים היתם בארץ מצרים. שהוא טעם צדדי, והכתוב חושב שמשום שנתלבש מיד לא היה מי שישגיח בה. בנפש הגר הזו, \u0003יודעת\u0004 הנשמה בדברי עולם הזה, ונהנית מהם. להיותה אמצעי בין הנשמה ובין הגוף כנ\"ל. וע\"כ אומר ואתם ידעתם וגו'."],[1,"פתח ההוא סבא וכו':","פתח זקן ההוא ואמר, ויבא משה בתוך הענן ויעל אל ההר וגו', שואל, ענן זה מה הוא. ומשיב, אלא זה הוא שכתוב, את קשתי נתתי בענן, למדנו, שקשת הזה, שה\"ס המלכות בעת שמקבלת ג' גוונין לבן אדום ירוק מג' קוין דז\"א, פשטה את לבושיה, שהם ג' גוונים לבן אדום ירוק, ונתנה אותם למשה, ובלבוש ההוא עלה משה אל ההר, וממנו, ראה מה שראה, ונהנה מכל. כשהגיע הזקן עד מקום הזה, באו אליו החברים, דהיינו ר' חייא ור' יוסי, והשתטחו לפני אותו זקן, ובכו, ואמרו, אם לא באנו לעולם אלא לשמוע דברים אלו מפיך, די לנו."],[2,"אמר ההוא סבא וכו':","אמר זקן ההוא, חברים, לא משום זה בלבד התחלתי לדבר, כי זקן כמותי לא בדבר אחד עושה רעש, ואינו קורא, לפרסם את עצמו. דהיינו לא כטבע אדם ריק שאם יודע איזה דבר עושה רעש ומפרסם עצמו, כמ\"ש (ב\"מ פה:) אסתירא בלגינא קיש קיש קריא. כמה הם בני העולם בבלבול הדעת, ואינם רואים בתורה בדרך אמת, והתורה קוראה אותם בכל יום באהבה אליהם, ואינם רוצים להחזיר ראשם להקשיב אליה."],[3,"ואע\"ג דאמינא דהא וכו':","ואע\"פ שאמרתי, כי בתורה, יוצא דבר מנרתקו, ונראה מעט מעט, ומיד מסתתר. כך הוא ודאי, ובזמן שנתגלה מתוך הנרתק ומסתתר מיד, אין התורה עושה זה, אלא לאלו שיודעים בה ונודעים בה."],[4,"משל למה\"ד לרחימתא וכו':","משל למה הדבר דומה, לאהובה, שהיא יפת מראה ויפת תואר, והיא מסתתרת בסתר בתוך ההיכל שלה. ויש לה אוהב אחד, שבני אדם אינם יודעים בו, אלא הוא מסתתר. אוהב ההוא מתוך האהבה שאוהב אותה, עובר תמיד בשער ביתה, נושא עיניו לכל צד. היא, יודעת שאוהבה מסבב תמיד שער ביתה, מה עושה, היא פותחת פתח קטן בהיכל ההוא הנסתר, שהיא שם, ומגלה פניה אל אהובה, ומיד חוזרת ומתכסית. כל אלו שהיו עם האוהב, לא ראו ולא הסתכלו, רק האוהב לבדו, שמעיו ולבו ונפשו הולכים אחריה, ויודע שמשום האהבה שהיא אוהבת אותו, נתגלית אליו רגע אחד, לעורר האהבה אליו. כך הוא דבר תורה אינה מתגלית אלא לאוהבה יודעת התורה שחכם לב ההוא, מסבב שער ביתה בכל יום, מה עשאה, גילתה פניה אליו מתוך ההיכל, ורמזה לו רמז, ומיד חזרה למקומה ונסתרה, כל אלו משם לא ידעו ולא הסתכלו אלא הוא בלבדו ומעיו ולבו ונפשו הולכים אחריה. ועל כן התורה מתגלה ומתכסה והולכת באהבה אל אוהבה, לעורר עמו האהבה."],[5,"ת\"ח ארחא דאורייתא וכו':","בוא וראה, דרך התורה כך היא. בתחילה, כשמתחילה להתגלות לאדם, רומזת אליו \u0003ברמז\u0004 אם יודע, טוב. ואם אינו יודע, שולחת אצלו וקוראת לו פתי, והתורה אמרה לאותו ששלחה אליו, אמרו לפתי ההוא שיקרב כאן ואדבר עמו. ז\"ש מי פתי יסור הנה וחסר לב וגו'. האדם קרב אצלה מתחילה לדבר עמו מאחרי הפרכת, שפורשת אליו דברים לפי דרכיו, עד שיסתכל מעט מעט. וזהו \u0003דרוש.\u0004"],[6,"לבתר תשתעי בהדיה וכו':","אחר כך היא מדברת עמו מאחורי סדין דק דברי חידה, וזהו \u0003הגדה.\u0004 ואחר שנעשה רגיל אצלה, היא מתגלית אליו פנים בפנים, ומדברת עמו כל סודות הסתומים, וכל דרכים הסתומים, שהיו חבוים בלבה מימים ראשונים. אז הוא אדם מושל, בעל תורה, ודאי שהוא אדון הבית, שהרי גילתה לו כל הסודות שלה, ולא הרחיקה ולא כיסתה ממנו כלום."]],[[0,"","כֵּיוָן שֶׁהִזְהִיר עַל הַגֵּר בְּכָל אוֹתָם מְקוֹמוֹת, יָצָא הַדָּבָר מִנַּרְתִּיקוֹ וְהִתְגַּלָּה וְאָמַר, וְאַתֶּם יְדַעְתֶּם אֶת נֶפֶשׁ הַגֵּר. מִיָּד נִכְנְסָה לְנַרְתִּיקָהּ, וְחָזְרָה בִּלְבוּשׁ וְנִטְמְנָה, שֶׁכָּתוּב כִּי גֵרִים הֱיִיתֶם בְּאֶרֶץ מִצְרָיִם, שֶׁחָשַׁב הַכָּתוּב, שֶׁבִּגְלַל שֶׁמִּיָּד הִתְלַבֵּשׁ, לֹא הָיָה מִי שֶׁיַּשְׁגִּיחַ בּוֹ. בְּנֶפֶשׁ הַגֵּר הַזּוֹ יוֹדַעַת הַנְּשָׁמָה הַקְּדוֹשָׁה בְּדִבְרֵי הָעוֹלָם הַזֶּה וְנֶהֱנֵית (ושואבת) מֵהֶם."],[1,"","פָּתַח אוֹתוֹ זָקֵן וְאָמַר, (שם כד) וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן וַיַּעַל אֶל הָהָר וְגוֹ'. עָנָן זֶה מַהוּ? אֶלָּא זֶהוּ הַכָּתוּב (בראשית ט) אֶת קַשְׁתִּי נָתַתִּי בֶּעָנָן. שָׁנִינוּ שֶׁאוֹתָהּ קֶשֶׁת הִפְשִׁיטָה אֶת לְבוּשֶׁיהָ וְנָתְנָה אוֹתָם לְמֹשֶׁה, וּבְאוֹתוֹ לְבוּשׁ עָלָה מֹשֶׁה לָהָר, וּמִמֶּנּוּ רָאָה מַה שֶּׁרָאָה וְנֶהֱנָה מֵהַכֹּל. עַד אוֹתוֹ מָקוֹם בָּאוּ אוֹתָם הַחֲבֵרִים, וְהִשְׁתַּטְּחוּ לִפְנֵי אוֹתוֹ זָקֵן וּבָכוּ וְאָמְרוּ, אִלְמָלֵא לֹא בָאנוּ לָעוֹלָם אֶלָּא כְּדֵי לִשְׁמֹעַ דְּבָרִים אֵלּוּ מִפִּיךְ - דַּי לָנוּ!"],[2,"","אָמַר אוֹתוֹ זָקֵן, (אם אחרת יקח לו) חֲבֵרִים, לֹא בִּשְׁבִיל זֶה בִּלְבַד הִתְחַלְתִּי אֶת הַדָּבָר, שֶׁהֲרֵי זָקֵן כָּמוֹנִי לֹא בְּדָבָר אֶחָד עוֹשֶׂה קִישׁ קִישׁ וְלֹא קוֹרֵא, כַּמָּה בְּנֵי הָעוֹלָם שֶׁהֵם בְּעִרְבּוּבְיָה בַּתְּבוּנָה שֶׁלָּהֶם, וְלֹא רוֹאִים בְּדֶרֶךְ אֱמֶת בַּתּוֹרָה, וְתוֹרָה קוֹרֵאת בְּכָל יוֹם בִּנְהִימָה (באהבה) אֲלֵיהֶם, וְלֹא רוֹצִים לְהָשִׁיב רֹאשָׁם."],[3,"","וְאַף עַל גַּב שֶׁאָמַרְנוּ שֶׁהֲרֵי הַתּוֹרָה הוֹצִיאָה דָבָר מִנַּרְתִּיקָהּ, וְנִרְאָה קָטָן וּמִיָּד נִטְמַן - כָּךְ הוּא וַדַּאי. וּבִזְמַן שֶׁנִּתְגַּלָּה מִתּוֹךְ נַרְתִּיקָהּ וְנִטְמַן מִיָּד, לֹא עוֹשֶׂה אֶת זֶה אֶלָּא לְאוֹתָם שֶׁיּוֹדְעִים בָּהּ וְנוֹדָעִים בָּהּ."],[4,"","מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לַאֲהוּבָה, שֶׁהִיא יָפָה בְּמַרְאֶה וְיָפָה בְּתֹאַר, וְהִיא טְמוּנָה בְּהֶסְתֵּר בְּתוֹךְ הַהֵיכָל שֶׁלָּהּ, וְיֵשׁ לָהּ אוֹהֵב יְחִידִי שֶׁלֹּא יוֹדְעִים עָלָיו בְּנֵי אָדָם, אֶלָּא שֶׁהוּא בְּנִסְתָּר. אוֹתוֹ אוֹהֵב, מִתּוֹךְ הָאַהֲבָה שֶׁאוֹהֵב אוֹתָהּ, עוֹבֵר עַל שַׁעַר בֵּיתָהּ תָּמִיד, מֵרִים עֵינָיו לְכָל צַד. הִיא יוֹדַעַת שֶׁהֲרֵי הָאוֹהֵב סוֹבֵב שַׁעַר בֵּיתָהּ תָּמִיד. מָה עוֹשָׂה? פּוֹתַחַת פֶּתַח קָטָן בְּאוֹתוֹ הֵיכָל נִסְתָּר שֶׁהִיא שָׁם וּמְגַלָּה אֶת פָּנֶיהַ לְאוֹהֲבָהּ, וּמִיָּד חוֹזֶרֶת וְנִתְכַּסֵּית. כָּל אוֹתָם שֶׁהָיוּ אֵצֶל הָאוֹהֵב, לֹא רָאוּ וְלֹא הִסְתַּכְּלוּ, פְּרָט לָאוֹהֵב לְבַדּוֹ, וּמֵעָיו וְלִבּוֹ וְנַפְשׁוֹ הָלְכוּ אַחֲרֶיהָ. וְיוֹדֵעַ שֶׁמִּתּוֹךְ הָאַהֲבָה שֶׁהִיא אוֹהֶבֶת אוֹתוֹ, נִגְלֵית אֵלָיו רֶגַע אֶחָד לְעוֹרֵר (אליו אהבה) אוֹתוֹ. כָּךְ הוּא דְּבַר הַתּוֹרָה לֹא נִגְלֶה אֶלָּא לְאוֹהֲבוֹ. יוֹדַעַת הַתּוֹרָה שֶׁאוֹתוֹ חֲכַם לֵב סוֹבֵב שַׁעַר בֵּיתָהּ כָּל יוֹם. מַה הִיא עוֹשָׂה? מְגַלָּה פָנֶיהָ אֵלָיו מִתּוֹךְ הַהֵיכָל, וְרוֹמֶזֶת לוֹ רֶמֶז, וּמִיָּד חוֹזֶרֶת לִמְקוֹמָהּ וְנִסְתֶּרֶת. כָּל אֵלּוּ שֶׁשָּׁם לֹא יוֹדְעִים וְלֹא מִסְתַּכְּלִים, אֶלָּא רַק הוּא בִּלְבַדּוֹ, וּמֵעָיו וְלִבּוֹ וְנַפְשׁוֹ הוֹלְכִים אַחֲרֶיהָ, וְעַל זֶה הַתּוֹרָה נִגְלֵית וְנִכְסֵית וְהוֹלֶכֶת בְּאַהֲבָה לַאֲהוּבָה לְעוֹרֵר עִמּוֹ אַהֲבָה."],[5,"","בֹּא וּרְאֵה, כָּךְ הִיא דַּרְכָּהּ שֶׁל תּוֹרָה: בָּרִאשׁוֹנָה כְּשֶׁמַּתְחִילָה לְהִתְגַּלּוֹת אֶל הָאָדָם, (ברגע) רוֹמֶזֶת לוֹ בְּרֶמֶז. אִם יוֹדֵעַ - אָז טוֹב, וְאִם לֹא יוֹדֵעַ - שׁוֹלַחַת אֵלָיו וְקוֹרֵאת לוֹ פֶּתִי. וְהַתּוֹרָה אוֹמֶרֶת לְאוֹתוֹ שֶׁשָּׁלְחָה אֵלָיו: אִמְרוּ לְאוֹתוֹ הַפֶּתִי שֶׁיִּקְרַב לְכָאן וַאֲדַבֵּר עִמּוֹ. זֶהוּ שֶׁכָּתוּב מִי פֶתִי יָסֻר הֵנָּה חֲסַר לֵב וְגוֹ'. קָרַב אֵלֶיהָ, וּמַתְחִילָה לְדַבֵּר עִמּוֹ מֵאַחַר פָּרֹכֶת שֶׁפּוֹרֶשֶׂת לוֹ דְּבָרִים לְפִי דַרְכּוֹ, עַד שֶׁיִּתְבּוֹנֵן לְאַט לְאַט, וְזֶהוּ הַדְּרָשׁ."],[6,"","אַחַר כָּךְ תְּדַבֵּר עִמּוֹ מֵאַחַר פִּשְׁפֵּשׁ קָטָן דִּבְרֵי חִידָה, וְזוֹהִי הַגָּדָה. אַחַר שֶׁהִתְרַגֵּל אֵלֶיהָ, נִגְלֵית אֵלָיו פָּנִים בְּפָנִים וּמְדַבֶּרֶת עִמּוֹ כָּל הַסּוֹדוֹת הַנִּסְתָּרִים שֶׁלָּהּ, וְכָל הַדְּרָכִים הַנִּסְתָּרוֹת שֶׁהָיוּ שְׁמוּרִים בְּלִבָּהּ מִיָּמִים רִאשׁוֹנִים, וְאָז אוֹתוֹ אָדָם הוּא שָׁלֵם, בַּעַל תּוֹרָה וַדַּאי, בַּעַל הַבַּיִת, שֶׁהֲרֵי כָּל סוֹדוֹתֶיהָ גִּלְּתָה לוֹ, וְלֹא רִחֲקָה וְלֹא כִסְּתָה מִמֶּנּוּ כְּלוּם."]]],[["אָמְרָה לֵיהּ, חָמִית מִלָּה דִּרְמִזָא דְּקָא רָמִיזְנָא לָךְ בְּקַדְמִיתָא, כַּךְ וְכָךְ רָזִין הֲווֹ, כַּךְ וְכָךְ הוּא. כְּדֵין חָמֵי, (ס\"א דעלאין) דְּעַל אִינּוּן מִלִּין לָאו לְאוֹסָפָא, וְלָאו לְמִגְרַע מִנַּיְיהוּ. וּכְדֵין פְּשָׁטֵיהּ דִּקְרָא, כְּמָה דְּאִיהוּ, דְּלָאו לְאוֹסָפָא וְלָא לְמִגְרַע אֲפִילּוּ אָת חַד. וְעַל דָּא, בְּנִי נָשָׁא אִצְטְרִיכוּ לְאִזְדַּהֲרָא, וּלְמִרְדַּף אֲבַתְרָא דְּאוֹרַיְיתָא, לְמֶהוֵי רְחִימִין דִּילָהּ, כְּמָה דְּאִתְּמַר.","תָּא חֲזֵי (שמות כ״א:י׳) אִם אַחֶרֶת יִקַּח לוֹ, גִּלְגּוּלִין דְּמִתְגַּלְגְּלָן בְּהַאי קְרָא, כַּמָּה רַבְרְבִין וְעִלָּאִין אִינּוּן, דְּהָא כָּל נִשְׁמָתִין עָאלִין בְּגִלְגּוּלָא. וְלָא יַדְעִין בְּנֵי נָשָׁא אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, וְהֵיאַךְ קַיְּימָא טִיקְלָא, וְהֵיךְ אִתְדָּנוּ בְּנֵי נָשָׁא בְּכָל יוֹמָא, וּבְכָל עִידָּן, וְהֵיךְ נִשְׁמָתִין עָאלִין בְּדִינָא, עַד לָא יֵיתוּן לְהַאי עָלְמָא, וְהֵיךְ עָאלִין בְּדִינָא, לְבָתַר דְּנַפְקֵי מֵהַאי עָלְמָא.","כַּמָּה גִּלְגּוּלִין, וְכַמָּה עוֹבָדִין סְתִימִין, עָבִיד קוּדְשָׁא בְּרִיךְ הוּא בַּהֲדֵי כַּמָּה נִשְׁמָתִין עַרְטִילָאִין, וְכַמָּה רוּחִין עַרְטִילָאִין אַזְלִין בְּהַהוּא עָלְמָא, דְּלָא עָאלִין לְפַרְגּוֹדָא דְּמַלְכָּא. וְכַמָּה עָלְמִין אִתְהַפַּךְ בְּהוּ וְעָלְמָא דְּאִתְהַפָּךְ בְּכַמָּה פְּלִיאָן סְתִימִין. וּבְנֵי נָשָׁא לָא יַדְעִין, וְלָא מַשְׁגִּיחִין, וְהֵיךְ מִתְגַּלְגְּלִין נִשְׁמָתִין, כְּאַבְנָא בְּקוּסְפִּיתָא. כְּמָה דְאַתְּ אָמֵר, (שמואל א כ״ה:כ״ט) וְאֵת נֶפֶשׁ אוֹיְבֶיךָ יְקַלְעֶנָּה בְּתוֹךְ כַּף הַקָּלַע.","(והואיל אתדכי לגלאה) הַשְׁתָּא אִית לְגַלָּאָה, דְּהָא כָּל (ויקרא כ\"ט ע\"א) נִשְׁמָתִין, מֵאִילָנָא רַבְרְבָא וְתַקִּיפָא דְּהוּא נָהָר דְּנָפִיק מֵעֵדֶן נַפְקֵי. וְכָל רוּחִין, מֵאִילָנָא אַחֲרָא זְעֵירָא נָפְקִין. נְשָׁמָה מִלְּעֵילָּא רוּחַ מִלְּתַתָּא, וּמִתְחַבְּרָן כַּחֲדָא, כְּגַוְונָא דְּדָכַר וְנוּקְבָּא. וְכַד מִתְחַבְּרָן כַּחֲדָא, כְּדֵין נְהִרִין נְהִירוּ עִלָּאָה. וּבְחִבּוּרָא דְּתַרְוַיְיהוּ אִקְרֵי נֵר. (משלי כ׳:כ״ז) נֵר יְיָ' נִשְׁמַת אָדָם. מַהוּ נ\"ר. נְשָׁמָה רוּחַ. וְעַל חִבּוּרָא דְּתַרְוַיְיהוּ כַּחֲדָא אִקְרֵי נֵר, דִּכְתִּיב נֵר יְיָ' נִשְׁמַת אָדָם.","נְשָׁמָה וְרוּחַ: דְּכַר וְנוּקְבָּא לְאַנְהֲרָא כַּחֲדָא, וְדָא בְּלֹא דָּא, לָא נְהִרִין, וְלָא אִקְרֵי נֵר, וְכַד מִתְּחַבְּרָן כַּחֲדָא, אִקְרֵי כֹּלָּא נֵר. וּכְדֵין אִתְעַטָּף נְשָׁמָה בְּרוּחַ, לְקַיְּימָא תַּמָּן לְעֵילָּא, בְּהֵיכְלָא טְמִירָא, דִּכְתִּיב, (ישעיהו נ״ז:ט״ז) כִּי רוּחַ מִלְּפָנַי יַעֲטוֹף. יִתְעַטֵּף לָא כְּתִיב, אֶלָּא יַעֲטוֹף. מַאי טַעְמָא. בְּגִין דִּנְשָׁמוֹת אֲנִי עָשִׂיתִי, תַּמָּן לְעֵילָּא בְּגִנְתָּא, בְּהֵיכְלָא טְמִירָא, אִתְעַטָּף וְאִתְלָבַשׁ נְשָׁמָה בְּרוּחַ, כְּמָה דְּאִתְחָזֵי.","וְכֵיוָן דִּבְהַהוּא הֵיכָלָא, לָא הֲוֵי, וְלָא אִשְׁתַּמַּשׁ אֶלָּא בְּרוּחַ וּנְשָׁמָה, נֶפֶשׁ לָא אָתֵי לְתַמָּן, (נ\"א מתמן) אֶלָּא מִתְלַבַשׁ בְּהַהוּא רוּחַ תַּמָּן, וְכַד נַחְתָּא לְגוֹ גַּן עֵדֶן דִּלְתַתָּא, (בהאי עלמא) אִתְלָבַשׁ בְּהַהוּא רוּחָא אַחֲרָא דַּאֲמֵינָא, הַהוּא דְּנָפִיק מִתַּמָּן, וַהֲוָה מִתַּמָּן, וּבְכֻלְּהוּ שַׁרְיָא בְּהַאי עָלְמָא, וְאִתְלָבַשׁ בְּהוּ.","הַהוּא רוּחַ דְּנָפִיק מֵהַאי עָלְמָא, דְּלָא אִתְרַבֵּי (דלא אתדכי) וְלָא אִתְפָּשַׁט בְּהַאי עָלְמָא. אַזְלָא בְּגִלְגּוּלָא, וְלָא אַשְׁכַּח נַיְיחָא, אִתִּי בְּגִלְגּוּלָא בְּעָלְמָא, כְּאַבְנָא בְּקוּסְפִיתָא, עַד דְּיִשְׁכַּח הַהוּא פָּרוֹקָא דְּיִפְרוֹק לֵיהּ, וְאַיְיתֵי לֵיהּ בְּהַהוּא מָאנָא מַמָּשׁ, דְּהֲוָה אִיהוּ אִשְׁתַּמַּשׁ בֵּיהּ, וְדָבִיק בֵּיהּ תָּדִיר רוּחֵיהּ וְנַפְשֵׁיהּ, וַהֲוַת בַּת זוּגֵיהּ, רוּחָא בְּרוּחָא, וְהַהוּא פָּרוֹקָא בָּנִי לֵיהּ כְּמִלְּקַדְּמִין.","וְהַהוּא רוּחָא דְּשָׁבַק וְאִתְדְּבַק בְּהַהוּא מָאנָא, לָא אִתְאֲבִיד. דְּהָא לֵית מִלָּה אֲפִילּוּ זְעֵירָא בְּעָלְמָא, דְּלָא הֲוֵי לֵיהּ אֲתָר וְדוּכְתָּא לְאִתְטַמְּרָא וּלְאִתְכַּנְּשָׁא תַּמָּן, וְלָא אִתְאֲבִיד לְעָלְמִין. וּבְּגִין כָּךְ, הַהוּא רוּחָא דְּשָׁבַק בְּהַהוּא מָנָא, תַּמָּן הוּא, וַדַּאי רָדִיף בָּתַר עִקָרָא וִיסוֹדָא דִּילֵיהּ, דְּקָא נָפִיק מִינֵּיהּ, וְאַיְיתֵי לֵיהּ, וּבָנֵי לֵיהּ בְּדוּכְתֵּיהּ, בַּאֲתָר דְּהַהוּא רוּחַ בַּת זוּגֵיהּ, (לך לך פ\"ה ע\"ב) דְּנַפְקַת בַּהֲדֵיהּ, וְאִתְבְּנֵי תַּמָּן כְּמִלְּקַדְּמִין. וְדָא אִיהוּ בִּרְיָה חַדְתָּא הַשְׁתָּא בְּעָלְמָא, רוּחָא חַדְתָּא וְגוּפָא חַדְתָּא."],[[0,"אמרה ליה חמית וכו':","אמרה לו התורה, ראית דבר רמז שרמזתי לך בתחילה, כך וכך סודות היו בו, כך וכך הוא. אז רואה שעל אלו מלים שבתורה אין להוסיף ואין לגרוע מהם. ואז פשט המקרא הוא כמות שהוא, שלא להוסיף ולא לגרוע אפילו אות אחת. וע\"כ בני אדם צריכים להזהר ולרדוף אחר התורה, להיות מן האוהבים שלה, כמושלמדנו."],[1,"ת\"ח אם אחרת יקח לו:","הגלגולים שמתגלגלים במקרא הזה, כמה גדולים ועליונים הם. שהרי כל הנשמות באים בגלגול, ובני אדם אינם יודעים דרכיו של הקב\"ה, ואיך עומדים המאזנים, ואיך בני אדם נדונים בכל יום ובכל זמן, ואיך הנשמות באות בדין מטרם שבאים לעולם הזה, ואיך באות בדין לאחר שיוצאות מעולם הזה."],[2,"כמה גלגולין וכמה וכו':","כמה גלגולים וכמה מעשים סתומים עושה הקב\"ה עם כמה נשמות ערומות, שאין להם לבוש מתורה ומצות, וכמה רוחות ערומים הולכים בעולם ההוא, שאינם נכנסים למחיצתו של המלך, וכמה עולמות מתהפך להם, דהיינו שמשתנות בשבילם סדרי המדרגות, הנקראות עולמות. ועולם המתהפך בכמה פליאות סתומות. (כמ\"ש וירא דף ס\"ג ד\"ה פנימיות, ע\"ש) ובני אדם אינם יודעים ואינם מסתכלים. ואיך מתגלגלים נשמות כאבן בכף הקלע. כש\"א, ואת נפש אויביך יקלענה בתוך כף הקלע."],[3,"השתא אית לגלאה וכו':","עתה יש לגלות. כי כל הנשמות יוצאות מעץ הגדול והחזק שהוא נהר היוצא מעדן, דהיינו ז\"א. וכל הרוחות מעץ אחר קטן יוצאים, שהוא המלכות. נשמה יוצאת מלמעלה, ורוח מלמטה, ומתחברים יחד כעין דכר ונוקבא, וכשמתחברים יחד אז מאירים אור עליון. ובחבור שניהם נקרא נר. שהוא ר\"ת נשמה רוח, שכתוב נר ה' נשמת אדם. מהו נ\"ר. נשמה רוח. ועל חבור שניהם יחדיו נקרא נר, שכתוב עליהם, נר ה' נשמת אדם."],[4,"נשמה ורוח וכו':","נשמה ורוח הם דכר ונוקבא להאיר יחדיו, וזה בלא זה אינם מאירים, וכשמתחברים יחדיו נקרא הכל נר. ואז התעטפה הנשמה ברוח, כדי לעמוד שם למעלה בגן עדן העליון בהיכל הנסתר, שכתוב, כי רוח מלפני יעטוף, יתעטף לא כתוב, אלא יעטוף, שפירושו שעוטף אחרים. מה הטעם. משום, שהנשמות אני עשיתי, ששם למעלה בגן עדן העליון, בהיכל נסתר, מתעטפת ומתלבשת הנשמה ברוח, כמו שראוי."],[5,"וכיון דבההוא היכלא וכו':","וכיון שבהיכל הזה, לא יש, ולא השתמש, אלא בנשמה ורוח, הנפש אינה באה שם, אלא הנשמה מתלבשת שם ברוח ההוא. וכשיורדת לגן עדן התחתון היא מתלבשת ברוח אחר שאמרתי (לעיל אות פ\"ט) ברוח ההוא היוצא משם, והיה משם, דהיינו נשמות הגרים. ובכולם הנשמה שורה בעולם הזה, ומתלבשת בהם. דהיינו הן ברוח שלה והן בנשמות הגרים."],[6,"ההוא רוח דנפיק וכו':","רוח ההוא היוצא מעולם הזה, שלא נתגדל ולא התפשט בעולם הזה, דהיינו שאין לו בנים, הולך בגלגול ואינו מוצא מנוחה, ובא בגלגול בעולם כאבן בכף הקלע, עד שימצא גואל ההוא שיגאל אותו, דהיינו יבם שמיבם את אשתו, ומביא אותו באותו הכלי ממש, שהוא היה משתמש בו והיה דבוק בו תמיד, רוחו ונפשו, והיתה בת זוגו רוח ברוח, דהיינו באשתו. וגואל ההוא בונה אותו כבתחילה, דהיינו שמביאו בבן שנולד מן היבמה, שהיא אשתו, וחוזר לחיי עולם הזה כבתחילה."],[7,"וההוא רוחא דשבק וכו':","ורוח ההוא שעזב אצלה בביאה הראשונה, כמ\"ש להלן, שהבעל משאיר באשתו את רוחו בביאה הראשנה, ומתדבק בכלי ההוא, דהיינו באשתו, שאינו נעדר ממנה לעולם אפילו לאחר מיתתו, אינו נאבד. כי אין לך דבר בעולם אפילו קטן, שאין לו מקום ומעמד להסתתר ולבא שמה, ואינו נאבד לעולם. ומשום זה, רוח ההוא שעזב בכלי ההוא, הוא שם, והוא ודאי רודף אחר השורש ויסוד שלו, שמשם יצא, דהיינו אחר הבעל המת בלי בנים, והוא מביא אותו ובונה אותו במקומו, דהיינו במקום רוח ההוא שהוא בת זוגו, שיצאה עמו, דהיינו באשתו, ונבנה, שם כבתחילה. וזה הוא עתה בריה חדשה בעולם, רוח חדש וגוף חדש."]],[[0,"","אוֹמֶרֶת לוֹ, רָאִיתָ דְּבַר הָרֶמֶז שֶׁרָמַזְתִּי לְךְ בַּתְּחִלָּה? כָּךְ וְכָךְ הָיוּ הַסּוֹדוֹת, כָּךְ וְכָךְ הוּא. וְאָז רוֹאֶה (שהעליונים) שֶׁעַל הַדְּבָרִים הַלָּלוּ אֵין לְהוֹסִיף וְאֵין לִגְרֹעַ מֵהֶם, וְאָז פְּשַׁט הַכָּתוּב כְּמוֹ שֶׁהוּא, שֶׁלֹּא לְהוֹסִיף וְלֹא לִגְרֹעַ אֲפִלּוּ אוֹת אַחַת. וְעַל כָּךְ אֲנָשִׁים צְרִיכִים לְהִזָּהֵר וְלִרְדּף אַחֲרֵי הַתּוֹרָה לִהְיוֹת אוֹהֲבִים שֶׁלָּהּ, כְּמוֹ שֶׁנִּתְבָּאֵר."],[1,"","בֹּא וּרְאֵה, אִם אַחֶרֶת יִקַּח לוֹ. הַגִּלְגּוּלִים שֶׁמִּתְגַּלְגְּלִים בַּפָּסוּק הַזֶּה כַּמָּה גְדוֹלִים וְעֶלְיוֹנִים הֵם, שֶׁהֲרֵי כָּל הַנְּשָׁמוֹת נִכְנָסוֹת בְּגִלְגּוּל, וְלֹא יוֹדְעִים בְּנֵי אָדָם דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא אֵיךְ עוֹמְדִים הַמֹּאזְנַיִם וְאֵיךְ נִדּוֹנִים בְּנֵי אָדָם בְּכָל יוֹם וּבְכָל זְמַן, וְאֵיךְ נְשָׁמוֹת נִכְנָסוֹת לַדִּין עַד שֶׁלֹּא בָאוֹת לָעוֹלָם הַזֶּה, וְאֵיךְ נִכְנָסוֹת לַדִּין אַחַר שֶׁיּוֹצְאוֹת מִן הָעוֹלָם הַזֶּה."],[2,"","כַּמָּה גִלְגּוּלִים וְכַמָּה מַעֲשִׂים נִסְתָּרִים עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא עִם כַּמָּה נְשָׁמוֹת מְעֻרְטָלוֹת, וְכַמָּה רוּחוֹת מְעֻרְטָלוֹת הוֹלְכוֹת בְּאוֹתוֹ הָעוֹלָם שֶׁלֹּא נִכְנָסוֹת לַפַּרְגּוֹד שֶׁל הַמֶּלֶךְ, וְכַמָּה עוֹלָמוֹת מִתְהַפֵּךְ בָּהֶם, וְהָעוֹלָם שֶׁמִּתְהַפֵּךְ בְּכַמָּה פְלָאִים נִסְתָּרִים, וּבְנֵי אָדָם לֹא יוֹדְעִים וְלֹא מַשְׁגִּיחִים, וְאֵיךְ מִתְגַּלְגְּלוֹת הַנְּשָׁמוֹת כְּאֶבֶן בְּכַף הַקֶּלַע, כְּמוֹ שֶׁנֶּאֱמַר וְאֵת נֶפֶשׁ אֹיְבֶיךְ יְקַלְּעֶנָּה בְּתוֹךְ כַּף הַקָּלַע."],[3,"","(והואיל והתחלנו לגלות) עַכְשָׁו יֵשׁ לְגַלּוֹת, שֶׁהֲרֵי כָּל הַנְּשָׁמוֹת מֵהָאִילָן הַגָּדוֹל וְהַתַּקִּיף, שֶׁהוּא הַנָּהָר שֶׁיּוֹצֵא מֵעֵדֶן, יוֹצְאוֹת, וְכָל הָרוּחוֹת מֵעֵץ אַחֵר קָטָן יוֹצְאוֹת. הַנְּשָׁמָה מִלְמַעְלָה וְהָרוּחַ מִלְּמַטָּה, וּמִתְחַבְּרוֹת כְּאַחַת כְּמוֹ זָכָר וּנְקֵבָה. וְכַאֲשֶׁר מִתְחַבְּרוֹת כְּאַחַת, אָז מְאִירוֹת אוֹר עֶלְיוֹן, וּבְחִבּוּר שֶׁל שְׁנֵיהֶם נִקְרָא נֵר. נֵר ה' נִשְׁמַת אָדָם. מַהוּ נֵ\"ר? נְ'שָׁמָה ר'וּחַ. וְעַל הַחִבּוּר שֶׁל שְׁנֵיהֶם כְּאֶחָד נִקְרָא נֵר, שֶׁכָּתוּב (משליב) נֵר ה' נִשְׁמַת אָדָם."],[4,"","נְשָׁמָה וְרוּחַ - זָכָר וּנְקֵבָה לְהָאִיר כְּאֶחָד, וְזֶה בְּלִי זֶה לֹא מְאִירִים וְלֹא נִקְרָא נֵר. וּכְשֶׁמִּתְחַבְּרִים כְּאֶחָד, הַכֹּל נִקְרָא נֵר. וְאָז מִתְעַטֶּפֶת הַנְּשָׁמָה בְּרוּחַ לַעֲמֹד שָׁם לְמַעְלָה בַּהֵיכָל הַגָּנוּז, שֶׁכָּתוּב (ישעיה נז) כִּי רוּחַ מִלְּפָנַי יַעֲטוֹף. לֹא כָתוּב יִתְעַטֵּף, אֶלָּא יַעֲטוֹף, מָה הַטַּעַם? מִשּׁוּם שֶׁנְּשָׁמוֹת אֲנִי עָשִׂיתִי. שָׁם לְמַעְלָה בַּגָּן, בַּהֵיכָל הַגָּנוּז, מִתְעַטֶּפֶת וּמִתְלַבֶּשֶׁת הַנְּשָׁמָה בְּרוּחַ כְּמוֹ שֶׁרָאוּי."],[5,"","וְכֵיוָן שֶׁבְּאוֹתוֹ הֵיכָל לֹא הָיָה וְלֹא הִשְׁתַּמֵּשׁ אֶלָּא בְּרוּחַ וּנְשָׁמָה, הַנֶּפֶשׁ לֹא בָאָה לְשָׁם (משם), אֶלָּא מִתְלַבֶּשֶׁת בְּאוֹתָהּ רוּחַ שָׁם, וּכְשֶׁיּוֹרֶדֶת לְתוֹךְ גַּן עֵדֶן הַתַּחְתּוֹן, (בעולם הזה) מִתְלַבֶּשֶׁת בְּאוֹתָהּ רוּחַ אַחֶרֶת שֶׁאָמַרְנוּ, אוֹתָהּ שֶׁיָּצְאָה מִשָּׁם וְהָיְתָה מִשָּׁם, וּבְכֻלָּן הִיא שׁוֹרָה בָּעוֹלָם הַזֶּה וּמִתְלַבֶּשֶׁת בָּהֶם."],[6,"","אוֹתָהּ רוּחַ שֶׁיּוֹצֵאת מִן הָעוֹלָם הַזֶּה, שֶׁלֹּא הִתְרַבְּתָה (שלא נטהרה) וְלֹא הִתְפַּשְּׁטָה בָּעוֹלָם הַזֶּה, הוֹלֶכֶת בְּגִלְגּוּל וְלֹא מוֹצֵאת מְנוּחָה. בָּאָה בְּגִלְגּוּל בָּעוֹלָם כְּאֶבֶן בְּכַף הַקָּלַע, עַד שֶׁיִּמָּצֵא אוֹתוֹ גוֹאֵל שֶׁיִּגְאֲלֶנָּה, וּמֵבִיא אוֹתוֹ בְּאוֹתוֹ כְּלִי מַמָּשׁ שֶׁהוּא הָיָה מִשְׁתַּמֵּשׁ בּוֹ, וּמַדְבִּיק בּוֹ תָּמִיד רוּחוֹ וְנַפְשׁוֹ, וְהָיְתָה בַּת זוּגוֹ, רוּחַ בְּרוּחַ, וְאוֹתוֹ הַגּוֹאֵל בּוֹנֶה אוֹתוֹ כְּמִקֹּדֶם."],[7,"","וְאוֹתָהּ רוּחַ שֶׁהִשְׁאִיר וְנִדְבְּקָה בְּאוֹתוֹ הַכְּלִי, לֹא נֶאֶבְדָה. שֶׁהֲרֵי אֵין אֲפִלּוּ דָּבָר קָטָן בָּעוֹלָם שֶׁאֵין לוֹ אֲתַר וּמָקוֹם לְהִטָּמֵן וּלְהִתְכַּנֵּס לְשָׁם, וְלֹא נֶאֱבָד לְעוֹלָמִים. וּמִשּׁוּם כָּךְ, אוֹתָהּ הָרוּחַ שֶׁהִשְׁאִיר בְּאוֹתוֹ כְּלִי שָׁם, הוּא וַדַּאי רוֹדֵף אַחַר הָעִקָּר וְהַיְסוֹד שֶׁלּוֹ שֶׁיָּצָא מִמֶּנּוּ, וּמֵבִיא אוֹתוֹ וּבוֹנֶה אוֹתוֹ בִּמְקוֹמוֹ, בְּמָקוֹם שֶׁל אוֹתָהּ רוּחַ בַּת זוּגוֹ שֶׁיָּצְאָה עִמּוֹ, וְנִבְנֶה שָׁם כְּמִקֹּדֶם, וְזוֹהִי בְּרִיָּה חֲדָשָׁה עַכְשָׁו בָּעוֹלָם, רוּחַ חֲדָשָׁה וְגוּף חָדָשׁ."]]],[["וְאִי תֵּימָא, רוּחַ דָּא הוּא מַה דְּהֲוָה. הָכִי הוּא אֲבָל לָא אִתְבְּנֵי, אֶלָּא בְּגִין הַהוּא רוּחָא אַחֲרָא דְּקָא שָׁבַק בְּהַהוּא מָאנָא, הָכָא אִית רָזִין (ס\"א רזא דרזין בההוא מאנא.) בְּסִפְרָא דְּחֲנוֹךְ, בִּנְיָינָא דָּא דְּאִתְבְּנֵי, לָא אִתְבְּנֵי, אֶלָּא בְּהַהוּא רוּחָא אַחֲרָא דְּשָׁבִיק תַּמָּן, בְּהַהוּא מָאנָא. וְכַד שָׁארֵי לְאִתְבְּנָאָה, דָּא מָשִׁיךְ אֲבַתְרֵיהּ דְּהַהוּא רוּחַ דְּאָזִיל עַרְטִילָאָה, וּמָשִׁיךְ לֵיהּ לְגַבֵּיהּ, וְתַמָּן תְּרֵי רוּחוֹת דְּאִינּוּן חַד. לְבָתַר, דָּא אִיהוּ רוּחַ, וְדָא אִיהוּ נְשָׁמָה, וְתַרְוַויְיהוּ חַד.","אִי זָכָה לְאִתְדַכְּאָה כְּדְקָא יֵאוֹת, תַּרְוַויְיהוּ אִינּוּן חַד, לְאִתְלַבְּשָׁא בְּהוּ נִשְׁמְתָא אַחֲרָא עִלָּאָה. כְּמָה דְּאִית לִשְׁאַר בְּנֵי עָלְמָא, רוּחַ, דְּזַכָּאִין בְּהוּ נִשְׁמָתִין, אִינּוּן דְּקַדְמָן וְאֲחִידָן בְּהוּ, וְרוּחָא אַחֲרָא מִלְּעֵילָּא. וְנִשְׁמְתָא קַדִּישָׁא אִתְלַבְּשָׁא בְּהוּ. אוּף הָכִי נָמֵי, מִדִּילֵיהּ מַמָּשׁ אִית תְּרֵין רוּחִין, בְּגִין לְאִתְלַבְּשָׁא בְּהוּ נְשָׁמָה עִלָּאָה.","יְהֵא לְדֵין גּוּפָא אַחֲרָא, דְּקָא אִתְבְּנֵי הַשְׁתָּא חַדְתָּא, הַהוּא גּוּפָא קַדְמָאָה דְּשָׁבַק, מָה אִתְעָבִיד מִנִּיהּ. אוֹ הַאי בְּרֵיקָנַיָּיא, אוֹ הַאי בְּרֵיקָנַיָּיא. לְפוּם סָכְלְתָנוּ דְּבַּר נָשׁ אִשְׁתְּמַע, דְּהַאי קַדְמָאָה דְּלָא אִשְׁתְּלִים בְּקַדְמִיתָא, אִתְאֲבִיד, הוֹאִיל וְלָא זָכָה. אִי הָכִי, לְמַגָּנָא אִשְׁתַּדַּל בְּפִקּוּדֵי אוֹרַיְיתָא, אוֹ אֲפִילּוּ בְּחַד מִנַּיְיהוּ. וְהָא אֲנָן יַדְעֵינָן, דְּאֲפִילּוּ רֵיקָנִין שֶׁבְּיִשְׂרָאֵל, כֻּלְּהוּ מַלְיָין מִצְוֹת כָּרִמּוֹן. וְגוּפָא דָּא, אַף עַל גַּב דְּלָא אִשְׁתְּלִים, לְאִתְרַבְּאָה, וּלְמִזְכֵּי וּלְמִסְגֵּי בְּעָלְמָא, פִּקּוּדִין אַחֲרָנִין דְּאוֹרַיְיתָא נָטַר, דְּלָא אִתְאֲבִידוּ מִנֵּיהּ, וְכִי לְמַגָּנָא הֲווֹ.","חַבְרַיָּיא חַבְרַיָּיא, פְּקִיחוּ עֵינַיְיכוּ, דְּהָא אֲנָא יְדַעְנָא, דְּהָכִי אַתּוּן סַבְרִין וְיַדְעִין, (נ\"א סלקא דעתין) דְּכָל אִינּוּן גּוּפִין, צִיּוּנִין אִינּוּן בְּרֵיקָנַיָּיא, דְּלָא אִית לוֹן קִיּוּמָא לְעָלְמִין. לָאו הָכִי, וְחָס לָן לְאִסְתַּכְּלָא בְּאִלֵּין מִלִּין.","פָּתַח סָבָא וְאָמַר, (תהילים ק״ו:ב׳) מִי יְמַלֵּל גְּבוּרוֹת יְיָ' יַשְׁמִיעַ כָּל תְּהִלָּתוֹ. מַאן הוּא בְּעָלְמָא, דְּיָכִיל לְמַלְּלָא גְּבוּרָן, דְּעָבִיד קוּדְשָׁא בְּרִיךְ הוּא בְּעָלְמָא תָּדִיר. הַהוּא גּוּפָא קַדְמָאָה דְּשָׁבַק, לָא אִתְאֲבִיד, וְקִיּוּמָא לֶהוֵי לֵיהּ לְזִמְנָא דְּאָתֵי. דְּהָא עוֹנְשֵׁיהּ סָבַל בְּכַמָּה זִינִין, וְקוּדְשָׁא בְּרִיךְ הוּא לָא מְקַפֵּחַ אַגְרָא דְּשׁוּם בִּרְיָין דְּבָרָא, בַּר אִינּוּן דְּנַפְקוּ מִגּוֹ מְהֵימָנוּתָא דִּילֵיהּ, וְלָא הֲוָה בְּהוּ טָב לְעָלְמִין. וּבַר מֵאִינּוּן דְּלָא כָּרְעוּ בְּמוֹדִים, דְּהָנֵי קוּדְשָׁא בְּרִיךְ הוּא עָבִיד מִנַּיְיהוּ בִּרְיָין אַחֲרָנִין, בְּגִין דְּלָא יִתְבְּנֵי הַהוּא גּוּפָא דִּיּוּקְנָא דְּבַר נָשׁ, וְלָא יְקוּם לְעָלְמִין. אֲבָל הָנֵי לָאו הָכִי.","מַה עָבֵד קוּדְשָׁא בְּרִיךְ הוּא. אִי הַהוּא רוּחַ, זָכֵי לְאִתְתָּקְנָא בְּהַאי עָלְמָא, בְּהַהוּא גּוּפָא אַחֲרָא, מֶה עָבִיד קוּדְשָׁא בְּרִיךְ הוּא. הַהוּא פָּרוֹקָא דְּקָא פָּרִיק לֵיהּ, הַהוּא רוּחַ דִּילֵיהּ דְּקָא אָעִיל תַּמָּן, וְשָׁתַף וְעָרַב בְּהַהוּא רוּחַ דְּהֲוָה בְּהַהוּא מָאנָא, וַדַּאי לָא אִתְאֲבִיד, וּמַה אִתְעָבִיד, דְּהָא תְּלַת רוּחִין תַּמָּן, (ס\"א בההוא גופא אחרא ביה יקום ומה עביד קודשא בריך הוא. תא חזי ההוא פרוקא דקא פריק ליה. רוח דיליה הא אעיל המן ושביק ושחף וערב בההוא מאנא. וההוא רוחא קדמאה דהוא בההוא מאנא ואתדבק ביה ודאי אשתאר תמן ולא אתאביד ובגין כך ההוא רוחא דשבק בההוא מאנא ואתדבק תמן הוא רדיף בתר עיקרא דיליה ויסודא דיליה דקא נפיק מיניה ואייתיה ליה ובני ליה בדוכתיה באתר דהוות בת זוגיה. הא תלת רוחין תמן) חַד, דְּהֲוָה בְּהַהוּא מָאנָא, וְאִשְׁתְּאָר תַּמָּן. וְחַד, הַהוּא דְּאִתְמְשָׁךְ תַּמָּן דְּהֲוָה עַרְטִילָאָה. וְחַד, הַהוּא דְּאָעִיל תַּמָּן הַהוּא פָּרוֹקָא, וְאִתְעֲרַב בְּהוּ. לְמֶהוֵי בִּתְלַת רוּחִין אִי אֶפְשָׁר. וּמָה אִתְעָבִיד.","אֶלָּא, כָּךְ אִינּוּן גְּבוּרָן עִלָּאִין, דְּעָבִיד קוּדְשָׁא בְּרִיךְ הוּא. הַהוּא רוּחָא דְּאָעִיל תַּמָּן הַהוּא פָּרוֹקָא, בֵּיהּ אִתְלָבַשׁ הַהִיא נִשְׁמְתָא, בַּאֲתָר דִּלְבוּשָׁא דְּגִיּוֹרֵי, (והוא) וְהַהוּא רוּחָא עַרְטִילָאָה, דְּתָב תַּמָּן לְאִתְבְּנָאָה, לֶהוֵי לְבוּשָׁא לְנִשְׁמְתָא עִלָּאָה. וְהַהוּא רוּחַ דְּהֲוָה בְּקַדְמִיתָא, דְּאִשְׁתְּאַר בְּהַהוּא מָנָא, פָּרַח מִתַּמָּן. וְקוּדְשָׁא בְּרִיךְ הוּא אַזְמִין לֵיהּ אֲתָר, בְּגוֹ רָזִין כַּוִּין דְּטִנָרָא, דְּבָתַר כִּתְפוֹי דְגַּן עֵדֶן, וְאִתְטָמַּר תַּמָּן. וְאִסְתַּלָּק לְהַהוּא גּוּפָא קַדְמָאָה, דְּהוּא בְּקַדְמִיתָא. וּבְהַהוּא רוּחַ יְקוּם הַהוּא גּוּפָא, וְדָא אִיהוּ חַד דְּאִינּוּן תְּרֵין, דְּקָא אֲמֵינָא (לעילא).","אֲבָל הַהוּא גּוּפָא, עַד דְּלָא יְקוּם, עוֹנְשֵׁיהּ סַגְיָא דְּהָא בְּגִין דְּלָא זָכָה לְאִתְרַבְּאָה, נַחְתֵּי לֵיהּ לְגוֹ (תיקונין ע\"ט ע\"א) אֲדָמָה, דְּסָמִיךְ לְאַרְקָא. וְאִתְדָן תַּמָּן. וּלְבָתַר סַלְּקִין לֵיהּ לְהַאי תֵּבֵל. הַשְׁתָּא נָחִית, וְהַשְׁתָּא סָלִיק, הָא סָלִיק, וְהָא נָחִית, לֵית לֵיהּ שְׁכִיכוּ בַּר בְּשַׁבָּתֵי, וּבְיוֹמִין טָבִין וּבְרֵישֵׁי יַרְחֵי."],[[0,"ואי תימא רוח וכו':","ואם תאמר, רוח הזה שהוא בבן הנולד, הוא מה שהיה, דהיינו האיש עצמו, ולא הרוח שעזב אצלה בביאה הראשונה, שהוא רק חלק ממנו. ומשיב, כך הוא, אבל לא נבנה בבן הנולד, אלא בכח רוח ההוא האחר שעזב בכלי ההוא, באשתו. כאן יש סוד הסודות, בספרו של חנוך. בנין זה שנבנה, בבן הנולד מן היבום, לא נבנה אלא בכח רוח האחר שעזב שם בכלי ההוא, דהיינו באשתו בביאת הראשונה. וכשהתחיל להבנות, רוח זה, מושך אחריו את רוח ההוא שהלך ערום, בלי בנים, ומושך אותו אצלו. ונעשה שם ב' רוחות שהם אחד. לאח\"כ נעשה זה רוח וזה נשמה, ושניהם אחד."],[1,"אי זכה לאתדכאה וכו':","אם זכה להטהר כראוי, נעשו שניהם אחד, שיתלבש בהם נשמה אחרת עליונה. כמו שיש לשאר בני העולם, רוח, שהנשמות זוכות בו אלו שמקדימות ואוחזות בו, דהיינו נשמות הגרים, ועוד רוח אחר מלמעלה והנשמה הקדושה מתלבשת בהם בשניהם (כנ\"ל אות ק\"ז) אף כך, גם משלו ממש יש שני רוחות, דהיינו רוח עצמו ורוח שעזב באשתו בביאה ראשונה, כדי שיתלבש בהם הנשמה העליונה."],[2,"יהא לדין גופא וכו':","שואל הרי יש לזה גוף אחר שנבנה עתה מחדש, על ידי היבום, גוף ההוא הראשון שעזב, מה נעשה ממנו. או זה לריק או זה לריק. לפי שכלו של האדם, משמע, שגוף הראשון הזה שלא נשלם תחילה, נאבד, משום שלא זכה. אם כן, בחנם עסק במצות התורה, ואפילו אם עסק רק באחת מהן, והרי אנו יודעים, שאפילו הריקים שבישראל מלאים כולם מצות כרמון, וגוף הזה, אע\"פ שלא נשלם להתרבות ולזכות ולגדול בעולם, הרי מצות אחרות שבתורה שמר, ולא נאבדו ממנו, וכי לחנם היה."],[3,"חבריא חבריא פקיחו וכו':","חברים חברים, פקחו עיניכם, שהרי יודע אני שאתם סבורים ויודעים שכל אלו הגופים מצוינים הם בציונים בחנם, שאין להם קיום לעולם. אינו כן. וחלילה לנו להסתכל בדברים כאלו."],[4,"פתח סבא ואמר וכו':","פתח הזקן מי ימלל גבורות ה' ישמיע כל תהלתו. מי הוא בעולם שיוכל לדבר, הגבורות שעושה הקב\"ה תמיד בעולם. גוף ההוא הראשון שעזב, אינו נאבד, וקיום יהיה לו לעתיד לבא. כי כבר קבל עונשו בכמה אפנים, והקב\"ה אינו מקפח שכר כל בריה שברא, חוץ מאלו שיצאו מאמונה שלו, ולא היה בהם טוב מעולם. וחוץ מאלו שלא כרעו במודים, בתפילת שמונה עשרה, שאלו עושה הקב\"ה מהם בריות אחרות, משום שלא יבנה גוף ההוא בצורת בן אדם, ולא יקום לעולם. אבל אלו, שמתו בלי בנים, אינו כן."],[5,"מה עבד קב\"ה וכו':","מה עושה הקב\"ה. אם רוח ההוא זכה להתתקן בעולם הזה בגוף ההוא האחר, מה עושה הקב\"ה, גואל ההוא שגאל אותו, דהיינו היבם, רוח ההוא שלו שהכניס שם, ושיתף וערב באותו רוח שהיה בכלי ההוא, שעזב בה אחיו בביאה הראשונה, ודאי אינו נאבד, ומה נעשה, שהרי ג' רוחות שם א' רוח שהיה בכלי ההוא ונשאר שם: דהיינו שעזב בה אחיו המת, בביאה ראשונה. וא' רוח של אחיו המת עצמו שנמשך שמה, שהיה ערום בלי בנים. וא' רוח ההוא שהכניס שם אותו הגואל, דהיינו היבם, ונתערב בהם. להיות בג' רוחות אי אפשר, ומה נעשה."],[6,"אלא כך אינון וכו':","אלא כך הם גבורות עליונות שעושה הקב\"ה. רוח ההוא שהכניס שמה אותו הגואל, בו מתלבשת הנשמה, במקום הלבוש מנשמות הגרים, ורוח ההוא של המת, הערום בלי בנים, שחזר שמה להבנות מחדש, יהיה לבוש לנשמה העליונה. ורוח ההוא שהיה מתחילה שנשאר בכלי ההוא, דהיינו הרוח שעזב בה בעלה המת, בביאה הראשונה, פרח משם, והקב\"ה מזמין מקום בתוך סוד החלון שבסלע שלאחר כתפיו של הגן עדן ונסתר שמה, והוא עולה לגוף ההוא הראשון של המת בלי בנים שהיה לו מתחילה. וברוח ההוא יקום גוף ההוא לתחיית המתים. וזהו אחד שהם שנים, שאמרתי (לעיל אות ט\"ו)."],[7,"אבל ההוא גופא וכו':","אבל גוף ההוא, עד שלא יקום לתחיה, עונשו גדול, כי משום שלא זכה להתגדל בבנים, מורידים אותו לתוך אדמה הסמוך לארקא, שז' ארצות יש, ארץ אדמה גיא נשיה ציה ארקא תבל (בראשית ב' אות ל\"ו), ונדון שם, ואח\"כ מעלים אותו לתבל הזה, שאנו נמצאים בו. עתה יורד בחזרה לאדמה, ועתה עולה, הנה עולה והנה יורד, אין לו מנוחה חוץ בשבתות ובימים טובים ובראשי חדשים."]],[[0,"","וְאִם תֹּאמַר, רוּחַ זוֹ הִיא מַה שֶּׁהָיָה - כָּךְ זֶה, אֲבָל לֹא נִבְנֵית אֶלָּא בִּשְׁבִיל אוֹתָהּ רוּחַ אַחֶרֶת שֶׁהִשְׁאִיר בְּאוֹתוֹ כְּלִי. כָּאן יֵשׁ סוֹדוֹת (סוד הסודות באותו כלי). בְּסִפְרוֹ שֶׁל חֲנוֹךְ, בִּנְיָן זֶה שֶׁנִּבְנֶה, לֹא נִבְנֶה אֶלָּא בְּאוֹתָהּ רוּחַ אַחֶרֶת שֶׁהִשְׁאִיר שָׁם, בְּאוֹתוֹ הַכְּלִי. וּכְשֶׁהִתְחִיל לְהִבָּנוֹת, זֶה מוֹשֵׁךְ אַחֲרָיו שֶׁל אוֹתָהּ רוּחַ שֶׁהוֹלֶכֶת עַרְטִילָאִית וּמוֹשֵׁךְ אוֹתָהּ אֵלָיו, וְשָׁם שְׁתֵּי רוּחוֹת שֶׁהֵן אַחַת. אַחַר כָּךְ זוֹהִי רוּחַ, וְזוֹהִי נְשָׁמָה, וּשְׁתֵּיהֶן אַחַת."],[1,"","אִם זָכָה לְהִטָּהֵר כָּרָאוּי, שְׁתֵּיהֶן הֵן אַחַת לְהִתְלַבֵּשׁ בָּהֶן נְשָׁמָה אַחֶרֶת עֶלְיוֹנָה. כְּמוֹ שֶׁיֵּשׁ לִשְׁאָר בְּנֵי הָעוֹלָם רוּחַ שֶׁזּוֹכוֹת בָּהֶן הַנְּשָׁמוֹת, אוֹתָן שֶׁקּוֹדְמוֹת וְאוֹחֲזוֹת בָּהֶן, וְרוּחַ אַחֶרֶת מִלְמַעְלָה, וְהַנְּשָׁמָה הַקְּדוֹשָׁה הִתְלַבְּשָׁה בָהֶן - אַף כָּךְ גַּם מִשֶּׁלּוֹ מַמָּשׁ יֵשׁ שְׁתֵּי רוּחוֹת כְּדֵי לְהַלְבִּישׁ בָּהֶן הַנְּשָׁמָה הָעֶלְיוֹנָה."],[2,"","יִהְיְהִ לָזֶה גּוּף אַחֵר שֶׁנִּבְנֶה עַכְשָׁו חָדָשׁ. אוֹתוֹ הַגּוּף הָרִאשׁוֹן שֶׁהִשְׁאִיר, מַה נַּעֲשֶׂה מִמֶּנּוּ? אוֹ שֶׁזֶּה בְּרֵיקָנוּת, אוֹ שֶׁזֶּה בְּרֵיקָנוּת. לְפִי תְבוּנַת אָדָם נִשְׁמָע, שֶׁהָרִאשׁוֹן הַזֶּה שֶׁלֹּא נִשְׁתַּלֵּם בַּתְּחִלָּה נֶאֱבָד, הוֹאִיל וְלֹא זָכָה. אִם כָּךְ, לְחִנָּם הִשְׁתַּדֵּל בְּמִצְווֹת הַתּוֹרָה, אוֹ אֲפִלּוּ בְּאַחַת מֵהֶן? וַהֲרֵי אָנוּ יוֹדְעִים שֶׁאֲפִלּוּ רֵיקָנִים שֶׁבְּיִשְׂרָאֵל, כֻּלָּם מְלֵאִים מִצְווֹת כָּרִמּוֹן. וְגוּף זֶה, אַף עַל גַּב שֶׁלֹּא הִשְׁתַּלֵּם לְהִתְרַבּוֹת וְלִזְכּוֹת וּלְהִשְׁתַּדֵּל בָּעוֹלָם, מִצְווֹת אֲחֵרוֹת שֶׁל הַתּוֹרָה הוּא שָׁמַר, שֶׁלֹּא נֶאֶבְדוּ מִמֶּנּוּ, וְכִי לְחִנָּם הֵם הָיוּ?"],[3,"","חֲבֵרִים חֲבֵרִים, פִּקְחוּ עֵינֵיכֶם, שֶׁהֲרֵי אֲנִי יָדַעְתִּי שֶׁכָּךְ אַתֶּם סְבוּרִים וְיוֹדְעִים, (היעלה על הדעת) שֶׁכָּל אוֹתָם גּוּפִים נִצְטַיְּרוּ הֵם בְּרֵיקָנוּת, שֶׁאֵין לָהֶם קִיּוּם לְעוֹלָמִים. לֹא כָּךְ, וְחָס לָנוּ לְהִסְתַּכֵּל בַּדְּבָרִים הַלָּלוּ."],[4,"","פָּתַח הַזָּקֵן וְאָמַר, (תהלים קו) מִי יְמַלֵּל גְּבוּרוֹת ה' יַשְׁמִיעַ כָּל תְּהִלָּתוֹ. מִי הוּא בָּעוֹלָם שֶׁיָּכוֹל לְמַלֵּל הַגְּבוּרוֹת שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם תָּמִיד? אוֹתוֹ גוּף הָרִאשׁוֹן שֶׁהִשְׁאִיר, לֹא נֶאֱבָד, וְיִהֶיה לוֹ קִיּוּם לֶעָתִיד לָבֹא, שֶׁהֲרֵי אֶת עָנְשׁוֹ סָבַל בְּכַמָּה מִינִים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מְקַפֵּחַ שְׂכַר שׁוּם בְּרִיּוֹת שֶׁבָּרָא, פְּרָט לְאוֹתָם שֶׁיָּצְאוּ מִתּוֹךְ הָאֱמוּנָה שֶׁלּוֹ וְלֹא הָיָה בָהֶם טוֹב לְעוֹלָמִים, וּפְרָט לְאֵלּוּ שֶׁלֹּא כָרְעוּ בְּמוֹדִים, שֶׁמֵּאֵלֶּה עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּרִיּוֹת אֲחֵרוֹת, כְּדֵי שֶׁלֹּא יִבָּנֶה בְּאוֹתוֹ הַגּוּף בִּדְמוּת שֶׁל אָדָם וְלֹא יָקוּם לְעוֹלָמִים. אֲבָל אֵלֶּה לֹא כָּךְ."],[5,"","מָה עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? אִם אוֹתָהּ רוּחַ זוֹכָה לְהִתְתַּקֵּן בָּעוֹלָם הַזֶּה בְּאוֹתוֹ הַגּוּף הָאַחֵר, מָה עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? אוֹתוֹ הַגּוֹאֵל שֶׁגּוֹאֵל אוֹתָהּ, אוֹתָהּ הָרוּחַ שֶׁלּוֹ שֶׁמַּכְנִיס לְשָׁם, וּמְשַׁתֵּף וּמְעָרֵב בְּאוֹתָהּ רוּחַ שֶׁהָיְתָה בְּאוֹתוֹ הַכְּלִי, וַדַּאי שֶׁלֹּא נֶאֱבֶדֶת. וּמַה נַּעֲשֶׂה? שֶׁהֲרֵי יֵשׁ שָׁם שָׁלֹשׁ רוּחוֹת (באותו גוף אחר בו יקום. ומה עשה הקדוש ברוך הוא, ' בא וראה, הגאלה ההיא שהיה גואל אותה, רוח שלו הרי נכנסת שם ונעזבת, ומשתתפת ומתערבת בכלי ההוא. ואותה הרוח הראשונה שהיתה באותו כלי ונדבקת בו, ודאי שגשארת שם ולא נאבדת, ומשוםזהאותההרוח שעזבבאותו הכליונדבקה שם, הוא רודף אחר השרש שלו והיסוד שלו שהיה יוצא ממגו ומביאו אליו, ובונה אותו במקום שהיתה בת זוגו. הרי שלש רוחות שם) - אַחַת שֶׁהָיְתָה בְּאוֹתוֹ הַכְּלִי וְנִשְׁאֲרָה שָׁם, וְאַחַת אוֹתָהּ שֶׁנִּמְשְׁכָה לְשָׁם וְהָיְתָה עַרְטִילָאִית, וְאַחַת אוֹתָהּ שֶׁהִכְנִיס לְשָׁם אוֹתוֹ הַגּוֹאֵל וְהִתְעָרֵב בָּהֶן. לִהְיוֹת שָׁלֹשׁ רוּחוֹת אִי אֶפְשָׁר, וּמָה נַעֲשֶׂה?"],[6,"","אֶלָּא כָּךְ הֵן הַגְּבוּרוֹת הָעֶלְיוֹנוֹת שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא. אוֹתָהּ רוּחַ שֶׁהִכְנִיס לְשָׁם אוֹתוֹ הַגּוֹאֵל, בּוֹ הִתְלַבְּשָׁה הַנְּשָׁמָה הַזּוֹ בְּמָקוֹם שֶׁל לְבוּשׁ הַגֵּרִים, (והוא) וְאוֹתָהּ רוּחַ עַרְטִילָאִית שֶׁשָּׁבָה שָׁם לְהִבָּנוֹת לִהְיוֹת לְבוּשׁ לַנְּשָׁמָה הָעֶלְיוֹנָה. וְאוֹתָהּ רוּחַ שֶׁהָיְתָה בַּתְּחִלָּה שֶׁנִּשְׁאֲרָה בְּאוֹתוֹ כְלִי, פָּרְחָה מִשָּׁם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַזְמִין לָהּ מָקוֹם בְּתוֹךְ סוֹדוֹת הַחַלּוֹנוֹת שֶׁבַּסֶּלַע שֶׁאַחַר כִּתְפֵי הַגָּן עֵדֶן, וְנִטְמֶנֶת שָׁם. וּמִתְעַלָּה לְאוֹתוֹ הַגּוּף הָרִאשׁוֹן שֶׁהָיָה בַּתְּחִלָּה, וּבְאוֹתָהּ רוּחַ יָקוּם אוֹתוֹ הַגּוף, וְזֶהוּ אֶחָד מֵאוֹתָם הַשְּׁנַיִם שֶׁאָמַרְנוּ (למעלה)."],[7,"","אֲבָל אוֹתוֹ הַגּוּף טֶרֶם שֶׁיָּקוּם עָנְשׁוֹ גָּדוֹל, שֶׁהֲרֵי מִשּׁוּם שֶׁלֹּא זָכָה לְהִתְרַבּוֹת, הוֹרִידוּ אוֹתוֹ לְתוֹךְ הָאֲדָמָה, שֶׁסְּמוּכָה לְאַרְקָא, וְנִדּוֹן שָׁם. וְאַחַר כָּךְ מַעֲלִים אוֹתוֹ לַתֵּבֵל הַ את. עַכְשָׁו יוֹרֵד וְעַכְשָׁו עוֹלֶה, הִנֵּה עָלָה וְהִנֵּה יָרַד, אֵין לוֹ מְנוּחָה, פְּרָט לְשַׁבָּתוֹת וְיָמִים טוֹבִים וּבְרָאשֵׁי חֳדָשִׁים."]]],[["וְאִלֵּין דְּמִיכִין בְּאַדְמַת עָפָר, אַדְמַת, מֵאֲדָמָה. עָפָר מִתֵּבֵל. וְעַל אִלֵּין כְּתִיב, (דניאל י״ב:ב׳) וְרַבִּים מִיְשֵׁינִי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת וּלְדִרְאוֹן עוֹלָם. כָּל אִלֵּין דְלָא זָכוּ לְאִתְתַּקְנָא אֲבָל אִי זָכָה הַהוּא רוּחָא עַרְטִילָאָה, דְּתָב כְּמִלְּקַדְּמִין, לְאִתְתַּקְנָא. זַכָּאָה אִיהוּ, דְּהָא הַהוּא רוּחָא דְּאִתְּמַר בֵּיהּ, דְּאִתְטְמַּר בְּטִנָרָא, יִתְתָּקַּן בְּהַהוּא גּוּפָא קַדְמָאָה. וְעַל אִלֵּין כְּתִּיב אֵלֶה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת וְגוֹ'. כָּל אִינּוּן דְּלָא זָכוּ לְאִתְתַּקְנָא.","וְאִלֵּין אִינּוּן גְּבוּרָן עִלָּאִין, דְּמַלְכָּא עִלָּאָה קַדִּישָׁא, וְלָא אִתְאֲבִיד כְּלוּם. אֲפִילּוּ הֲבַל דְּפוּמָא אֲתָר וְדוּכְתָּא אִית לֵיהּ, וְקוּדְשָׁא בְּרִיךְ הוּא עָבִיד מִינֵהּ מַה דְּעָבִיד. וַאֲפִילּוּ מִלָּה דְּבַר נָשׁ, וַאֲפִילּוּ קָלָא, לָא הֲוֵי בְּרֵיקָנַיָּיא, וַאֲתָר וְדוּכְתָּא אִית לְהוּ לְכֹלָּא.","הַאי דְּאִתְבְּנֵי הַשְׁתָּא, וְנָפַק לְעָלְמָא בִּרְיָה חַדְתָּא, לֵית לֵיהּ בַּת זוּג. וְעַל דָּא לָא מַכְרִיזֵי, דְּהָא בַּת זוּגֵיהּ אִתְאֲבִידַת מִנֵּיהּ, בַּת זוּגֵיהּ דַּהֲוַת לֵיהּ, אִתְעָבִידַת אִמֵּיהּ, וְאָחוּהָ אָבוּהָ.","סָבָא סָבָא, מַה עַבְדַת, טָב הֲוָה לָךְ שְׁתִיקָא, סָבָא סָבָא, הָא אֲמֵינָא דְּעָאלָת בְּיַמָּא רַבָּא, בְּלָא חַבְלִין, וּבְלָא דִּגְלָא, מָה תַּעֲבֵיד. אִי תֵּימָא דְּתִסְלַּק לְעֵילָּא, לָא תִּיכוֹל. אִי תֵּימָא דְּתֵיחוּת לְתַתָּא, הָא עִמְקָא דִּתְהוֹמָא רַבָּא, מַה תַּעֲבֵיד. אִי סָבָא אִי סָבָא, לָא אִית לָךְ לְאָהַדְּרָא לַאֲחוֹרָא. בְּעִדָנִין אִלֵּין, לָא הֲוֵית, וְלָא אִתְרְגִּילַת, לְאִתְחַלְּשָׁא בְּתוּקְפָךְ, דְּהָא יַדְעַת, דְּבַר נָשׁ אַחֲרָא בְּכָל דָּרָא דָּא, לָא עָאל בְּאַרְבָּא בְּעֲמִיקָא דָּא דְּאַנְתְּ תַּמָּן.","בְּרֵיהּ דְּיוֹחָאי יָדַע לְאִסְתַּמְּרָא אָרְחוֹי, וְאִי עָאל בְּיַמָּא עֲמִיקָא, אַשְׁגַּח בְּקַדְמִיתָא, הֵיךְ יַעֲבָר בְּזִמְנָא חֲדָא, וִישׁוֹטֵט בְּיַמָּא, עַד לָא יֵיעוּל וְאַנְתְּ סָבָא, לָא אַשְׁגַּחְת בְּקַדְמִיתָא. הַשְׁתָּא סָבָא, הוֹאִיל וְאַנְתְּ תַּמָּן, לָא תֶּחלַשׁ בְּתוּקְפָךְ, לָא תִּשְׁבּוֹק כָּל אָרְחָךְ, לִמְשַׁטְּטָא לִימִינָא וְלִשְׂמָאלָא, לְאָרְכָּא וּלְפוּתְיָיא, לְעָמְקָא וּלְרוּמָא, לָא תִּדְחַל. סָבָא סָבָא, אִתְתָּקַּף בְּתֻקְפָךְ, כַּמָּה גַּבְרִין תַּקִּיפִין תָּבַרְתְּ בְּתֻקְפֵיהוֹן, וְכַמָּה קְרָבִין נָצַחְתְּ.","בָּכָה, פָּתַח וְאָמַר, (שיר השירים ג׳:י״א) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה בַּעֲטָרָה שֶׁעִטְּרָה לוֹ אִמּוֹ בְּיוֹם חֲתֻנָּתּוֹ וּבְיוֹם שִׁמְחַת לִבּוֹ. הַאי קְרָא אוּקְמוּהָ, וְהָכִי הוּא. אֲבָל צְאֶינָה וּרְאֶינָה, וְכִי מַאן יָכִיל לְמֵחמֵי בַּמֶּלֶךְ שְׁלֹמֹה, דְּהוּא מַלְכָּא דִּשְׁלָמָא דִּילֵיהּ, וְהָא סָתִים הוּא, מִכָּל חֵילֵי מְרוֹמִין דִּלְעֵילָּא, בְּהַהוּא אֲתָר, (ישעיהו ס״ד:ג׳) דְּעַיִן לָא רָאָתָה אֱלהִים זוּלָתְךָ. וְאַתְּ אָמַרְתְּ צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלמֹה. וְתוּ, דְּהָא כָּבוֹד דִּילֵיהּ, כֻּלְּהוּ מַלְאֲכֵי עִלָּאֵי שַׁאֲלִי וְאַמְרֵי, אַיֵּה מְקוֹם כְּבוֹדוֹ.","אֶלָּא, מַה דְּאָמַר צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה, בַּעֲטָרָה כְּתִיב, וְלָא כְּתִיב וּבַעֲטָרָה דְּכָל מַאן דְּחָמֵי הַהוּא עֲטָּרָה, חָמֵי נֹעַם מַלְכָּא דִּשְׁלָמָא דִּילֵיהּ. שֶׁעִטְּרָה לוֹ אִמּוֹ, הָא תָּנֵינָן, קָרֵי לָהּ בַּת, וְקָרֵי לָהּ אָחוֹת, קָרֵי לָהּ אֵם, וְכֹלָּא אִיהוּ. וְכֹלָּא הֲוֵי, מַאן דְּיִסְתָּכַּל וְיִנְדַּע בְּהַאי, יִנְדַּע חָכְמְתָא יַקִּירָא.","הַשְׁתָּא מָה אַעְבִיד, אִי אֵימָא, רָזָא סְתִימָא דָּא, לָא אִצְטְרִיךְ לְגַלָּאָה. אִי לָא אֵימָא, יִשְׁתַּאֲרוּן זַכָּאִין אִלֵּין, יַתְמִין מֵהַאי רָזָא, נָפַל הַהוּא סָבָא עַל אַנְפּוֹי, וְאָמַר, (תהילים ל״א:ו׳) בְּיָדְךָ אַפְקִיד רוּחִי פָּדִיתָ אוֹתִי יְיָ' אֵל אֱמֶת. מָאנָא דַּהֲוַת לְתַתָּא, הֵיךְ יִתְעֲבִיד לְעֵילָּא, בַּעְלָהּ דְּהֲוָה לְעֵילָּא, הֵיךְ יִתְהַפֵּךְ וַהֲוָה לְתַתָּא. בַּת זוּגֵיהּ אִתְעָבִידַת אִמֵּיהּ. תָּוָוהָא עַל תָּוָוהָא. אָחוּהָ אָבוּהָ. אִי אָבוּהָ דְּקַדְמֵיתָא, יִפְרוֹק לֵיהּ, יֵאוֹת, אֲבָל אָחוּהָ דְּלֶיהֱוֵי אָבוּהָ, וְכִי לָא תָּוָוהָא אִיהוּ דָּא. עָלְמָא בְּהִפּוּכָא אִיהוּ. וַדַּאי עִלָּאִין לְתַתָּא, וְתַתָּאִין לְעֵילָּא.","אֶלָּא, (דניאל ב׳:כ׳) לֶהוֵא שְׁמֵיהּ דִּי אֱלָהָא מְבָרַךְ מִן עָלְמָא וְעַד עָלְמָא דִּי חָכְמְתָא וּגְבוּרְתָּא דִּילֵיהּ הִיא. וְהוּא מְהַשְׁנֵא עִדָּנַיָּא וְזִמְנַיָא וְגוֹ' יָדַע מָה בְּחָשׁוֹכָא וּנְהוֹרָא עִמֵּיהּ שָׁרָא. תָּא חֲזִי, מַאן דִּשְׁרֵי בִּנְהוֹרָא, לָא יָכִיל לְאִסְתַּכְּלָא וּלְמֶחמֵי בְּחָשׁוֹכָא. אֲבָל קוּדְשָׁא בְּרִיךְ הוּא לָאו הָכִי, יָדַע מָה בַחֲשׁוֹכָא, אַף עַל גַּב דִּנְהוֹרָא עִמֵּיהּ שָׁרָא. מִגּוֹ נְהוֹרָא, אִסְתָּכַּל בַּחֲשׁוֹכָא, וְיָדַע כָּל מַה דְּתַמָּן."],[[0,"ואלין דמיכין באדמת וכו':","ואלו הם הישנים באדמת עפר, אדמת נקרא על שם שהוא \u0003מאדמה,\u0004 עפר נקרא על שם שהוא מ \u0003תבל,\u0004 ועל אלו כתוב, ורבים מישיני אדמת עפר יקיצו אלה לחיי עולם ואלה לחרפות ולדראון עולם, אם רוח ההוא הערום זכה, דהיינו הרוח של המת בלי בנים, כי חזר לעולם הזה כבתחילה, דהיינו בבן הנולד מן היבום, להתתקן הוא זכאי. כי רוח ההוא, שעזב בביאה הראשונה באשתו, שאמרנו בו, שנסתתר בסלע (לעיל אות קט\"ז) יתתקן בגוף ההוא הראשון, שהניח המת בלי בנים. (כנ\"ל אות קט\"ו) ועל אלו כתוב, אלה לחיי עולם ואלה לחרפות וגו' דהיינו כל אלו שלא זכו להתתקן."],[1,"ואלין אינון גבורן וכו':","ואלו הם גבורות עליונות של מלך העליון הקדוש, שלא נאבד כלום, אפילו הבל פה יש לו מקום ומעמד, והקב\"ה עושה ממנו מה שעושה. ואפילו מלה של אדם, ואפילו קול, אינם לריק, ומקום ומעמד יש לכל."],[2,"האי דאתבני השתא וכו':","זה שנבנה עתה, דהיינו המת בלי בנים שנתגלגל בבן הנולד מן היבום, ויצא לעולם בריה חדשה, אין לו בת זוג, ועל זה אינם מכריזים על בת זוגו קודם שנולד, כי בת זוגו נאבד ממנו, הבת זוג שהיתה לו נעשית אמו, ואחיו נעשה אביו."],[3,"סבא סבא מה וכו':","אמר לעצמו, זקן זקן, מה עשית, שתיקה היתה טובה לך, זקן זקן, הרי אמרתי שנכנסת בים הגדול בלי חבלים ובלי דגל. מה תעשה. אם תאמר שתעלה למעלה, לא תוכל. אם תאמר שתרד למטה, הרי העומק של תהום הגדול. מה תעשה. אי סבא, אי סבא, לא יש לך לחזור לאחור. בזמנים כאלה לא היית ולא התרגלת להתחלש בתוקפך, כי ידעת שכל אדם אחר, בכל דור הזה, לא נכנס באניה בעמקות הזה שאתה שמה."],[4,"בריה דיוחאי ידע וכו':","בנו של יוחאי, דהיינו ר\"ש, יודע לשמור דרכיו, ואם נכנס בים עמוק, משגיח מתחילה מטרם שנכנס, איך יעבור בפעם אחת, וישוטט בים. ואתה זקן לא הסתכלת בתחילה. עתה זקן, כיון שאתה שם, לא תחלש בתוקפך, לא תעזוב בכל דרכך לשוטט לימין ולשמאל, לאורך ולרוחב, לעומק ולרום, אל תירא, זקן זקן, התחזק בגבורתך, כמה גבורים חזקים שברת בגבורתם, וכמה מלחמות נצחת."],[5,"בכה פתח ואמר וכו':","בכה פתח ואמר, צאנה וראנה בנות ציון במלך שלמה בעטרה וגו'. מקרא זה העמידוהו, וכך הוא, אבל צאנה וראנה, וכי מי יכול לראות במלך שלמה, שהוא המלך שהשלום שלו, דהיינו ז\"א, והרי הוא סתום מכל צבאות מרומים שלמעלה במקום ההוא, דעין לא ראתה אלקים זולתך, שהוא בינה, ואתה אמרת צאנה וראינה בנות ציון במלך שלמה. ועוד, הרי כבוד שלו, כל מלאכים העליונים שואלים ואומרים, איה מקום כבודו. דהיינו ההסתר, ומהו השבח של, צאנה וראינה."],[6,"אלא מה דאמר וכו':","ומשיב, אלא מה שאמר, צאנה וראינה בנות ציון במלך שלמה כתוב בעטרה, ולא כתוב ובעטרה, שכל מי שרואה עטרה ההיא שהיא המלכות, רואה הנעם של המלך שהשלום שלו. שעטרה לו אמו. היינו המלכות המקפת את ז\"א, שלמדנו, קורא לה בת וקורא לה אחות וקורא לה אם. והיא הכל והכל הוא בה. מי שיסתכל וידע בזו, במלכות, ידע חכמה יקרה."],[7,"השתא מה אעביד וכו':","אמר הזקן לעצמו, ועתה מה אעשה, אם אומר, סוד סתום זה אין צריך לגלותו. אם לא אומר ישארו צדיקים אלו יתומים מסוד הזה. נפל זקן ההוא על פניו, ואמר, בידך אפקיד רוחי פדית אותי ה' אל אמת. הכלי שהיה למטה דהיינו היבמה שהיתה מקודם אשתו של המת בלי בנים, והיתה למטה ממנו, איך יעשה למעלה, שיהיה אמו. בעלה, דהיינו המת בלי בנים, שהיה למעלה ממנה, איך יתהפך והיה למטה. שנעשה בנה. בת זוגו נעשה לאמו. פליאה על פליאה, אחיו הוא אביו. אם אביו של הראשונה, דהיינו אשתו, היה גואל אותו, שהיה מיבם את אשתו, היה יפה, אבל אחיו שיהיה אביו. וכי אין זה פליאה, ודאי עולם הפוך הוא, עליונים למטה ותחתונים למעלה."],[8,"אלא להוא שמיה וכו':","אלא להוא שמיה די אלהא מברך מן עלמא ועד עלמא די חכמתא וגו' ידע מה בחשוכא ונהורא עמיה שרא, בוא וראה, מי שהוא במקום האור, אינו יכול להסתכל ולראות בחושך. אבל הקב\"ה אינו כן, יודע מה בחשך אע\"פ שהאור שורה עמו. מתוך האור מסתכל בחשך, ויודע כל מה שיש שם."]],[[0,"","וְאֵלֶּה יְשֵׁנִים בְּאַדְמַת עָפָר. אַדְמַת - מֵאֲדָמָה. עָפָר - מִתֵּבֵל. וְעַל אֵלּוּ כָּתוּב (דניאליב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת וּלְדִרְאוֹן עוֹלָם. כָּל אֵלֶּה שֶׁלֹּא זָכוּ לְהִתְתַּקֵּן. אֲבָל אִם זָכְתָה אוֹתָהּ רוּחַ עַרְטִילָאִית שֶׁשָּׁבָה כְּמוֹ מִקֹּדֶם לְהִתְתַּקֵּן, אָז צַדִּיק הוּא, שֶׁהֲרֵי אוֹתָהּ רוּחַ שֶׁנֶּאֱמַר בָּהּ שֶׁנִּשְׁמְרָה בַּסֶּלַע, תְּתֻקַּן בְּאוֹתוֹ הַגּוּף הָרִאשׁוֹן, וְעַל אֵלֶּה כָּתוּב אֵלֶּה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת וְגוֹ'. כָּל אוֹתָם שֶׁלֹּא זָכוּ לְהִתַּקֵּן."],[1,"","וְאֵלּוּ הֵן הַגְּבוּרוֹת הָעֶלְיוֹנוֹת שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן הַקָּדוֹשׁ, וּכְלוּם לֹא נֶאֱבָד. אֲפִלּוּ הֶבֶל הַפֶּה יֵשׁ לוֹ אֲתַר וּמָקוֹם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה מִמֶּנּוּ מַה שֶּׁעוֹשֶׂה, וַאֲפִלּוּ דִבּוּר שֶׁל אָדָם וַאֲפִלּוּ קוֹל אֵינוֹ בְרֵיקָנוּת, וַאֲתַר וּמָקוֹם יֵשׁ לְכֻלָּם."],[2,"","זְהִ שֶׁנִּבְנֶה עַכְשָׁו וְיָצָא לָעוֹלָם בְּרִיָּה חֲדָשָׁה, אֵין לוֹ בַּת זוּג, וְעַל זֶה לֹא מַכְרִיזִים, שֶׁהֲרֵי בַּת זוּגוֹ אָבְדָה מִמֶּנּוּ. בַּת הַזּוּג שֶׁהָיְתָה לוֹ נֵעֶשְׂתָה אִמּוֹ, וְאָחִיו לְאָבִיו."],[3,"","זָקֵןֹ זָקֵן, מֶה עָשִׂיתָ? טוֹבָה הָיְתָה לְךְ הַשְּׁתִיקָה. זָקֵן זָקֵן, הֲרֵי אָמַרְנוּ שֶׁנִּכְנַסְתָּ לַיָּם הַגָּדוֹל בְּלִי חֲבָלִים וּבְלִי דֶגֶל, מַה תַּעֲשֶׂה? אִם תֹּאמַר שֶׁתַּעֲלֶה לְמַעְלָה - לֹא תוּכַל. וְאִם תֹּאמַר שֶׁתֵּרֵד לְמַטָּה - הֲרֵי עָמְקוֹ שֶׁל הַתְּהוֹם גָּדוֹל. מַה תַּעֲשֶׂה? אִי זָקֵן, אִי זָקֵן, אֵין לְךְ לַחֲזֹר לְאָחוֹר. בַּזְּמַנִּים הַלָּלוּ לֹא הָיִיתָ, וְלֹא הִתְרַגַּלְתָּ לְהֵחָלֵשׁ בְּכֹחֲךְ, שֶׁהֲרֵי יָדַעְתָּ שֶׁאָדָם אַחֵר בְּכָל הַדּוֹר הַזֶּה לֹא נִכְנָס לָאֳנִיָּה בָּעֹמֶק הַזֶּה שֶׁאַתָּה שָׁם."],[4,"","בֶּן יוֹחַאי יוֹדֵעַ לִשְׁמֹר אֶת דַּרְכּוֹ, וְאִם הוּא נִכְנָס לַיָּם הֶעָמֹק, הוּא מַשְׁגִּיחַ בַּהַתְחָלָה אֵיךְ יַעֲבֹר בְּפַעַם אַחַת וְיָשׁוּט בַּיָּם טֶרֶם שֶׁיִּכָּנֵס. וְאַתָּה, זָקֵן, לֹא הִשְׁגַּחְתָּ בַּתְּחִלָּה. עַכְשָׁו, זָקֵן, הוֹאִיל וְאַתָּה שָׁם, אַל תֶּחֱלַשׁ בְּכֹחֲךְ, אַל תַּעֲזב אֶת כָּל דַּרְכְּךְ, לָשׁוּט לְיָמִין וְלִשְׂמֹאל, לָאֹרֶךְ וְלָרֹחַב, לָעֹמֶק וְלַגֹּבַהּ. אַל תִּפְחַד. זָקֵן זָקֵן, הִתְחַזֵּק בְּכֹחֲךְ. כַּמָּה גְבָרִים חֲזָקִים שָׁבַרְתָּ בְּכֹחָם וְכַמָּה קְרָבוֹת נָצַחְתָּ."],[5,"","בָּכָה, פָּתַח וְאָמַר, (שיר ג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה בָּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ בְּיוֹם חֲתֻנָּתוֹ וּבְיוֹם שִׂמְחַת לִבּוֹ. פָּסוּק זֶה פֵּרְשׁוּהוּ, וְכָךְ הוּא. אֲבָל צְאֶינָה וּרְאֶינָה, וְכִי מִי יָכוֹל לִרְאוֹת בַּמֶּלֶךְ שְׁלֹמֹה, שֶׁהוּא הַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ? וַהֲרֵי הוּא נִסְתָּר מִכָּל חֵילוֹת הַמְּרוֹמִים שֶׁלְּמַעְלָה בְּאוֹתוֹ מָקוֹם, (ישעיה סד) שֶׁעַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ, וְאַתָּה אָמַרְתָּ צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה? וְעוֹד, שֶׁהֲרֵי כְּבוֹדוֹ, כָּל הַמַּלְאָכִים הָעֶלְיוֹנִים שׁוֹאֲלִים וְאוֹמְרִים אַיֵּה מְקוֹם כְּבוֹדוֹ?"],[6,"","אֶלָּא, מַה שֶּׁאָמַר צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה, בָּעֲטָרָה כָּתוּב, וְלֹא כָתוּב וּבָעֲטָרָה. שֶׁכָּל מִי שֶׁרוֹאֶה אוֹתָהּ עֲטָרָה, רוֹאֶה אֶת הַנֹּעַם שֶׁל הַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ. שֶׁעִטְּרָה לּוֹ אִמּוֹ, הֲרֵי שָׁנִינוּ, קוֹרֵא לָהּ בַּת וְקוֹרֵא לָהּ אָחוֹת, קוֹרֵא לָהּ אֵם, וְהַכֹּל הוּא, וְהַכֹּל הָיָה. מִי שֶׁיִּסְתַּכֵּל וְיֵדַע אֶת זֶה, יֵדַע חָכְמָה נִכְבָּדָה."],[7,"","עַכְשָׁו מָה אֶעֱשֶׂה? אִם אֹמַר סוֹד נִסְתָּר זֶה - לֹא צָרִיךְ לְגַלּוֹת. אִם לֹא אֹמַר - יִשָּׁאֲרוּ הַצַּדִּיקִים הַלָּלוּ יְתוֹמִים מִן הַסּוֹד הַזֶּה. נָפַל אוֹתוֹ הַזָּקֵן עַל פָּנָיו וְאָמַר, (תהלים לא) בְּיָדְךְ אַפְקִיד רוּחִי פָּדִיתָה אוֹתִי ה' אֵל אֱמֶת. כְּלִי שֶׁהָיָה לְמַטָּה, אֵיךְ יֵעָשֶׂה לְמַעְלָה? בַּעְלָהּ שֶׁהָיָה לְמַעְלָה, אֵיךְ יִתְהַפֵּךְ וְיִהְיֶה לְמַטָּה? בַּת זוּגוֹ נֶעֶשְׂתָה אִמּוֹ? תְּמִיהָה עַל תְּמִיהָה. אָחִיו הוֹפֵךְ לְאָבִיו? אִם אָבִיו שֶׁבָּרִאשׁוֹנָה יִגְאַל אוֹתוֹ - יָפֶה, אֲבָל אָחִיו שֶׁיִּהְיֶה אָבִיו? וְכִי זוֹ לֹא תְמִיהָה?! עוֹלָם הָפוּךְ הוּא! וַדַּאי שֶׁעֶלְיוֹנִים לְמַטָּה וְתַחְתּוֹנִים לְמַעְלָה."],[8,"","אֶלָּא, (דניאל ב) יִהְיֶה שֵׁם הָאֱלוֹהַּ מְבֹרָךְ מִן הָעוֹלָם וְעַד הָעוֹלָם, שֶׁהַחָכְמָה וְהַגְּבוּרָה שֶׁלּוֹ הִיא, וְהוּא מְשַׁנֶּה עִדָּנִים וּזְמַנִּים וְגוֹ'. יוֹדֵעַ מַה בַּחֲשֵׁכָה, וְהָאוֹר עִמּוֹ שָׁרוּי. בֹּא וּרְאֵה, מִי שֶׁשָּׁרוּי בְּאוֹר לֹא יוּכַל לְהִסְתַּכֵּל וְלִרְאוֹת מַה שֶּׁבַּחֲשֵׁכָה. אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא כָּךְ, יוֹדֵעַ מַה בַּחֲשֵׁכָה אַף עַל גַּב שֶׁהָאוֹר שָׁרוּי עִמּוֹ. מִתּוֹךְ הָאוֹר מִסְתַּכֵּל בַּחֹשֶׁךְ וְיוֹדֵעַ כָּל מַה שֶּׁשָּׁם."]]],[["הָכָא, אִית לְאַקְדְּמָא בְּקַדְמִיתָא, מִלָּה חֲדָא, דְּאָמְרוּ קַדְמָאֵי, בְּאִינּוּן חֶזְוֵי לֵילְיָא. דִּתְנָן, מַאן דְּאָתֵי עַל אִמֵּיהּ בְּחֶלְמָא, יְצַפֶּה לַבִּינָה. דִּכְתִּיב, (משלי ב׳:ג׳) כִּי אִם לַבִּינָה תִקְרָא, הָכָא אִית לְאִסְתַּכְּלָא, אִי בְּגִין דְּאִיהִי אֵם יֵאוֹת, וַהֲוָה לֵיהּ לְמִכְתַּב הָכִי, דְּמַאן דְּחָמָא אִמֵּיהּ בְּחֶלְמָא, יִזְכֵּי לַבִּינָה. אֲבָל מַאן דְּאָתֵי עַל אִמֵּיהּ אֲמַאי.","אֶלָּא רָזָא עִלָּאָה אִיהוּ, בְּגִין דְּאִתְהַפָּךְ וְסָלִיק מִתַּתָּא לְעֵילָּא. בְּרָא הֲוָה בְּקַדְמִיתָא, כֵּיוָן דְּסָלִיק לְעֵילָּא, אִתְהַפַּךְ אִילָנָא, וְאִתְעָבִיד אִיהוּ מֵעָלְמָא עִלָּאָה, וְשָׁלִיט עָלָהּ, וְזָכֵי לַבִּינָה.","בְּקַדְמִיתָא כַּד סָלִיק אֵינָשׁ לי\"ג (צ\"ח ע\"א) שְׁנִין, מַה כְּתִיב, (תהילים ב׳:ז׳) יְיָ' אָמַר אֵלַי בְּנִי אַתָּה אֲנִי הַיּוֹם יְלִדְתִּיךָ, כְּדֵין אִיהוּ לְתַתָּא מִינָהּ. כֵּיוָן דְּסָלִיק עָלָהּ, הַאי אִיהוּ מֵעָלְמָא עִלָּאָה. דְּהָא אִסְתַּלָּק בְּדַרְגָּא דְּיוֹסֵף, וְדָא (ס\"א ודאי) זָכֵי לַבִּינָה.","אוּף הָכִי הַאי מָאנָא, בְּקַדְמִיתָא אִיהוּ הֲוָה בְּדַרְגָּא דְּיוֹסֵף, בַּעַל אִילָנָא תַּתָּאָה, קַיְּימָא בִּרְעוּתֵיהּ, וְשָׁלִיט עָלֵיהּ, דְּהָא כָּל נוּקְבָּא, בְּדִיּוּקְנָא דְּנוּקְבָּא אִילָנָא תַּתָּאָה קַיְּימָא. כֵּיוָן דְּאִיהוּ לָא בָּעָא לְקַיְּימָא בְּהַהוּא דַּרְגָּא דְּיוֹסֵף, וְלָא אִתְקְיָים לְשַׁמְּשָׁא בֵּיהּ, וּלְאַפָּשָׁא בְּעָלְמָא, וּלְמֶעְבַּד תּוֹלָדִין, כְּדֵין נָחִית לְתַתָּא, וְאִתְעָבִידַת אִיהִי אִמֵּיהּ. וְהַהוּא פָּרוֹקָא, יָרִית יָרוּתָא דְּיוֹסֵף, דְּהֲוָה הוּא בְּקַדְמִיתָא וְאִיהוּ נָחִית לְתַתָּא.","כֵּיוָן דְּנָחִית לְתַתָּא, כְּדֵין אִתְקַיָּים בֵּיהּ, יְיָ' אָמַר אֵלַי בְּנִי אַתָּה אֲנִי הַיּוֹם יְלִדְתִּיךָ. אִתְהַפַּךְ אִילָנָא, מַה דְּהֲוָה תְּחוֹתֵיהּ וְאִיהוּ שָׁלִיט עָלֵיהּ, אִתְהַדַּר וְשָׁלִיט הַהוּא אִילָנָא עָלֵיהּ, וְאִיהוּ נָחִית לְתַתָּא. כֵּיוָן דְּאִיהוּ נָחִית לְתַתָּא, הַהוּא דְּיָרִית יָרוּתָא אֲתָר דְּיוֹסֵף, אֲבוֹי אִקְרֵי, אֲבוֹי הֲוֵי וַדַּאי, כֹּלָּא אִיהוּ עַל תְקּוּנֵיהּ וַדַּאי כְּדְקָא יֵאוֹת.","בְּקַדְמִיתָא הֲוָה מֵעָלְמָא דִּדְכוּרָא, וְהָא אִתְעַקָּר מִתַּמָּן, וְהַשְׁתָּא אִיהוּ מֵעָלְמָא דְּנוּקְבָּא. וּמַה דְּהֲוָה אִיהוּ שָׁלִיט עָלָהּ, שַׁלְטָא אִיהִי עָלֵיהּ, וְאִתְהַדָּר לְמֶהוֵי בְּעָלְמָא דְּנוּקְבָּא. וְעַל דָּא לֵית לֵיהּ בַּת זוּג כְּלָל. וְלָא מַכְרִיזֵי עָלֵיהּ, עַל נוּקְבָּא. דְּהָא מֵעָלְמָא דְּנוּקְבָּא אִתְהַדַּר אִיהוּ.","וְהַהוּא גּוּפָא קַדְמָאָה דְּשָׁבַק, אִלְמָלֵא יִנְדְּעוּן וְיִסְתַּכְּלוּן בְּנִי עָלְמָא, צַעֲרָא דְּאִית לֵיהּ, כַּד יִתְעָקָּר מֵעָלְמָא דִּדְכוּרָא, וְאִתְהַדָּר לְעָלְמָא דְּנוּקְבָּא. יִנְדְּעוּן, דְּהָא לֵית צַעֲרָא בְּעָלְמָא, כְּהַהוּא צַעֲרָא. בַּת זוּג לֵית לֵיהּ, דְּהָא לָא קַיְּימָא בְּאֲתָר דִּדְכוּרָא. לָא מַכְרִזֵי עָלֵיהּ, עַל נוּקְבָּא, דְּהָא מֵעָלְמָא דְּנוּקְבָּא אִיהוּ. וְאִי אִית לֵיהּ בַּת זוּג, הֲוִי בְּרַחֲמֵי, אִעֲרְעַת בַּהֲדֵי (נ\"א בחד) נוּקְבָּא, דְּעַד כְּעַן לָא אִית לָהּ בַּר זוּג. וְעַל דָּא תָּנֵינָן, דִּילְמָא יְקַדְּמֶנוּ אַחֵר בְּרַחֲמִים. אַחֵר תְּנָן. וְכֹלָּא אִיהוּ עַל תְקּוּנֵיהּ.","וְעַל דָּא כְּתִיב (ויקרא כ״ב:י״ג) וּבַת כֹּהֵן כִּי תִּהְיֶה אַלְמָנָה וּגְרוּשָׁה וְזֶרַע אֵין לָהּ וְשָׁבָה אֶל בֵּית אָבִיהָ כִּנְעוּרֶיהָ. וּבַת כֹּהֵן, הָא אוֹקִימְנָא מִלָּה דָּא. אַלְמָנָה, מֵהַהוּא גּוּפָא קַדְמָאָה. וּגְרוּשָׁה, דְּלָא עָאלַת לְפַרְגּוֹדָא דְּמַלְכָּא, דְּכָל אִינּוּן דְּלָא קַיְימֵי בְּעָלְמָא דִּדְכוּרָא, לָא אִית לְהוּ בֵּיהּ חוּלָקָא. הוּא אִשְׁתְּמִיט וְאַעְקַר גַּרְמֵיהּ מֵעָלְמָא דִּדְכוּרָא, לָא אִית לֵיהּ חוּלָקָא בֵּיהּ וְעַל דָּא אִיהִי גְּרוּשָׁה. וְזֶרַע אֵין לָהּ, דְּאִי הֲוָה לָהּ זֶרַע, לָא אִתְעַקָּר מִנֵּיהּ, וְלָא הֲוָה נָחִית לְעָלְמָא דְּנוּקְבָּא.","וְשָׁבָה אֶל בֵּית אָבִיהָ, מַאן בֵּית אָבִיהָ. דָּא עָלְמָא דְּנוּקְבָּא, דְּהַהוּא עָלְמָא בֵּית אָבִיהָ אִקְרֵי, וְהַהוּא מָאנָא דְּהֲוָה אִתְתָּקַּן לְאִשְׁתַּמְּשָׁא בֵּיהּ, אִתְהַפַּךְ וְאִיהוּ נָחִית לְתַתָּא, וְהַהוּא מָאנָא סָלִיק לְעֵילָּא. כִּנְעוּרֶיהָ, כְּהַהוּא זִמְנָא דִּכְתִּיב, אֲנִי הַיּוֹם יְלִדְתִּיךָ, יְלִדְתִּיךָ וַדַּאי, יָשׁוּב לִימֵי עֲלוּמָיו, כְּמָה דְּהֲוָה (בקדמיתא) מִתְּלֵיסַר שְׁנִין וּלְעֵילָּא."],[[0,"הכא אית לאקדמא וכו':","כאן יש להקדים בתחילה דבר אחד שאמרו הראשונים באלו מראות הלילה. שלמדנו מי שבא על אמו בחלום יצפה לבינה, שכתוב, כי אם לבינה תקרא. כאן יש להסתכל, אם משום שהוא אם, ע\"כ יצפה לבינה, יפה הוא, אלא שהיה לו לכתוב כך, שמי שראה את אמו בחלום יזכה לבינה, אבל מי שבא על אמו, למה זה."],[1,"אלא רזא עלאה וכו':","ומשיב, אלא סוד עליון הוא, שהוא משום שהתהפך ועלה ממטה למעלה, בן היה תחילה, דהיינו למטה ממנה, כיון שעלה למעלה, שבא עליה, נתהפך האילן, והוא נעשה מעולם העליון ושולט עליה, וזוכה לבינה."],[2,"בקדמיתא כד סליק וכו':","ומפרש דבריו, בתחילה, כשעלה אדם לי\"ג שנים, מה כתוב, ה' אמר אלי בני אתה אני היום ילדתיך. שנעשה בן אל המלכות, והמלכות היא אמו. ואז הוא למטה ממנה, כיון שעלה עליה, שנעשה בעלה, זה הוא מעולם העליון, ז\"א, כי עלה למדרגת יוסף, שהוא יסוד דז\"א, וזה ודאי זכה לבינה. כמו ז\"א שיש לו מוחין דבינה."],[3,"אוף הכי האי וכו':","אף כן כלי הזה, שהוא אשת המת, בתחילה היה הוא, בעלה המת, במדרגת יוסף, שהוא יסוד דז\"א, דהיינו הבעל של אילן התחתון, שהוא מלכות, שנשמעת לרצונו ושולט עליה, כי כל נקבה עומדת בצורת הנוקבא, שהיא אילן התחתון, שהיא מלכות. כיון שהוא לא רצה להתקיים במדרגת יוסף, ולא נתקיים לשמש בו, ולהרבות בעולם ולעשות תולדות, ומת בלי בנים, אז ירד למטה, שמתגלגל בבן הנולד מן היבום, והיא, אשתו, נעשית אמו. וגואל ההוא, דהיינו היבם, ירש ירושת יוסף שהיה הוא, אחיו, בתחילה, והוא ירד למטה, שנתגלגל בבן הנולד."],[4,"כיון דנחית וכו':","כיון שירד למטה אז נתקיים בו, ה' אמר אלי בני אתה אני היום ילדתיך. שנעשה בן אליה, נתהפך האילן, מה שהיה למטה והוא היה שולט עליה, כבעל על אשתו, כיון שהוא ירד למטה, שנתגלגל בבן הנולד מן היבום, ההוא, שירש ירושת מקום יוסף, דהיינו אחיו היבם, נקרא אביו, ואביו הוא ודאי, הכל הוא ודאי על תקונו כראוי."],[5,"בקדמיתא הוה מעלמא וכו':","בתחילה היה מעולם הזכר, בבחינת יוסף, והוא נעקר משם, ועתה הוא מעולם הנקבה, שהוא המלכות. ומה שהיה הוא שולט עליה, שולטת עתה היא עליו, והוחזר להיות בעולם הנקבה. וע\"כ אין לו בת זוג כלל, ואין מכריזים עליו על נקבה, כמו שמכריזים על כל אדם בטרם שנולד, בת פלוני לפלוני. כי הוחזר לעולם הנקבה."],[6,"וההוא גופא קדמאה וכו':","וגוף ההוא הראשון שעזב, המת בלי בנים, אם היו יודעים ומסתכלים בני העולם, הצער שיש לו בעת שנעקר מעולם הזכר ומוחזר לעולם הנקבה היו יודעים שאין צער בעולם כצער ההוא, בת זוגו אין לו, משום שאינו עומד במקום הזכר. אין מכריזים עליו על נקבה, משום שהוא מעולם הנקבה. ואם יש לו בת זוג, הוא ברחמים על ידי תפלה, הוא נפגש עם נקבה, שעד עתה, לא היה לה בן זוג. ועל זה למדנו, אולי יקדמנו אחר ברחמים (מועד קטן יח:) \u0003אחר\u0004 למדנו. כי המת בלי בנים נקרא \u0003אחר\u0004 (כמ\"ש להלן אות קס\"ב) והכל הוא על תקונו."],[7,"ועל דא כתיב וכו':","ועל זה כתוב, ובת כהן כי תהיה אלמנה וגרושה וזרע אין לה ושבה אל בית אביה כנעוריה. \u0003ובת כהן\u0004 כבר העמדנו מלה זו, שהיא הנשמה, \u0003אלמנה,\u0004 מגוף ההוא הראשון, של המת בלי בנים, \u0003וגרושה,\u0004 שאינה נכנסת לפרגוד המלך, כי כל אלו שאינם עומדים בעולם הזכר, אין להם חלק בו, הוא הסתלק ועקר את עצמו מעולם הזכר אין לו חלק במלך, שהוא ז\"א. ועל כן היא גרושה. \u0003וזרע אין לה,\u0004 כי אם היה לה זרע לא היתה נעקרת ממנו, מעולם הזכר, ולא היתה יורדת לעולם הנקבה."],[8,"ושבה אל בית אביה:","מי הוא בית אביה. ומשיב, זהו עולם הנקבה, כי עולם ההוא נקרא בית אביה. וכלי ההוא, דהיינו אשתו שהיה מתוקן להשתמש בו, נהפך, והוא ירד למטה וכלי ההוא עלה למעלה. כנ\"ל. \u0003כנעוריה\u0004 כזמן ההוא שכתוב אני היום ילדתיך, שנעשה בן אל הנקבה שהיא המלכות, ילדתיך ודאי, ישוב לימי עלומיו, כמו שהיה מי\"ג שנים ומעלה."]],[[0,"","עֵכְשָׁו יֵשׁ לְהַקְדִּים בָּרִאשׁוֹנָה דָּבָר אֶחָד שֶׁאָמְרוּ הַקַּדְמוֹנִים בְּאוֹתָם מַרְאוֹת הַלַּיְלָה. שֶׁשָּׁנִינוּ, מִי שֶׁבָּא עַל אִמּוֹ בַּחֲלוֹם, יִצְפֶּה לְבִינָה, שֶׁכָּתוּב (משלי ב) כִּי אִם לַבִּינָה תִקְרָא. כָּאן יֵשׁ לְהִתְבּוֹנֵן, אִם מִשּׁוּם שֶׁהִיא אֵם - יָפֶה, וְהָיָה לוֹ לִכְתֹּב כָּךְ: שֶׁמִּי שֶׁרוֹאֶה אִמּוֹ בַּחֲלוֹם, יִזְכֶּה לְבִינָה. אֲבָל מִי שֶׁבָּא עַל אִמּוֹ לָמָּה?"],[1,"","אֶלָּא סוֹד עֶלְיוֹן הוּא, מִשּׁוּם שֶׁהִתְהַפֵּךְ וְעָלָה מִלְּמַטָּה לְמַעְלָה. בֵּן הָיָה בַּתְּחִלָּה, כֵּיוָן שֶׁעָלָה לְמַעְלָה, מִתְהַפֵּךְ הָאִילָן, וְנַעֲשֶׂה הוּא מֵעוֹלָם עֶלְיוֹן, וְשׁוֹלֵט עָלֶיהָ וְזוֹכֶה לְבִינָה."],[2,"","בַּתְּחִלָּה כְּשֶׁעוֹלֶה אָדָם לִשְׁלֹשׁ עֶשְׂרֵה שָׁנָה, מַה כָּתוּב? (תהלים ב) ה' אָמַר אֵלַי בְּנִי אַתָּה אֲנִי הַיּוֹם יְלִדְתִּיךְ. אָז הוּא לְמַטָּה מִמֶּנָּה. כֵּיוָן שֶׁעָלָה אֵלֶיהָ, הֲרֵי הוּא מִן הָעוֹלָם הָעֶלְיוֹן, שֶׁהֲרֵי הִתְעַלָּה לְדַרְגַּת יוֹסֵף, וְזֶה (ודאי) זוֹכֶה לְבִינָה."],[3,"","אַף כָּךְ הַכְּלִי הַזֶּה בַּתְּחִלָּה הוּא הָיָה בְּדַרְגַּת יוֹסֵף, בַּעַל הָאִילָן הַתַּחְתּוֹן, עוֹמֵד בִּרְצוֹנוֹ וְשׁוֹלֵט עָלָיו, שֶׁהֲרֵי כָּל נְקֵבָה בִּדְמוּת הַנְּקֵבָה הָעֵץ הַתַּחְתּוֹן עוֹמֶדֶת. כֵּיוָן שֶׁהוּא לֹא רָצָה לַעֲמֹד בְּאוֹתָהּ דַּרְגָּה שֶׁל יוֹסֵף וְלֹא הִתְקַיֵּם לְשַׁמֵּשׁ בָּהּ וּלְהִתְרַבּוֹת בָּעוֹלָם וְלַעֲשׂוֹת תּוֹלָדוֹת, אָז יוֹרֵד לְמַטָּה, וְהִיא נַעֲשֵׂית אִמּוֹ. וְאוֹתוֹ הַגּוֹאֵל יוֹרֵשׁ אֶת יְרֻשַּׁת יוֹסֵף, שֶׁהָיָה הוּא בָרִאשׁוֹנָה וְהוּא יָרַד לְמַטָּה."],[4,"","כֵּיוָן שֶׁיָּרַד לְמַטָּה, אָז הִתְקַיֵּם בּוֹ, ה' אָמַר אֵלַי בְּנִי אַתָּה אֲנִי הַיּוֹם יְלִדְתִּיךְ. הִתְהַפֵּךְ הָאִילָן. מַה שֶּׁהָיָה תַחְתָּיו וְהוּא שָׁלַט עָלָיו, חָזַר וְשָׁלַט הָאִילָן הַהוּא עָלָיו, וְהוּא יָרַד לְמַטָּה. כֵּיוָן שֶׁהוּא יָרַד לְמַטָּה, אוֹתוֹ שֶׁיָּרַשׁ יְרֻשַּׁת מְקוֹם יוֹסֵף, אָבִיו נִקְרָא, אָבִיו יִהְיֶה וַדַּאי, וְהַכֹּל בָּא עַל תִּקּוּנוֹ וַדַּאי כָּרָאוּי."],[5,"","בַּתְּחִלָּה הָיָה מֵעוֹלַם הַזָּכָר, וַהֲרֵי נֶעֱקַר מִשָּׁם, וְעַכְשָׁו הוּא מֵעוֹלַם הַנְּקֵבָה. וּמַה שֶּׁהוּא הָיָה שׁוֹלֵט עָלֶיהָ - הִיא שׁוֹלֶטֶת עָלָיו, וְחוֹזֵר לִהְיוֹת בְּעוֹלַם הַנְּקֵבָה, וְעַל זֶה אֵין לוֹ בִּכְלָל בַּת זוּג, וְלֹא מַכְרִיזִים עָלָיו עַל הַנְּקֵבָה, שֶׁהֲרֵי הוּא חָזַר לִהְיוֹת מֵעוֹלַם הַנְּקֵבָה."],[6,"","וְאוֹתוֹ הַגּוּף הָרִאשׁוֹן שֶׁהִשְׁאִיר, אִלְמָלֵא יֵדְעוּ וְיִסְתַּכְּלוּ בְּנֵי הָעוֹלָם אֶת הַצַּעַר שֶׁיֵּשׁ לוֹ כְּשֶׁיֵּעָקֵר מִן עוֹלַם הַזָּכָר וְחוֹזֵר לְעוֹלַם הַנְּקֵבָה, יֵדְעוּ שֶׁהֲרֵי אֵין צַעַר בָּעוֹלָם כְּאוֹתוֹ הַצַּעַר. בַּת זוּג אֵין לוֹ, שֶׁהֲרֵי אֵינוֹ עוֹמֵד בְּמָקוֹם שֶׁל זָכָר. לֹא מַכְרִיזִים עָלָיו עַל הַנְּקֵבָה, שֶׁהֲרֵי הוּא מֵעוֹלַם הַנְּקֵבָה. וְאִם יֵשׁ לוֹ בַּת זוּג, זֶה בְּרַחֲמִים נִפְגָּשׁ עִם (באחת) נְקֵבָה, שֶׁעַד עַכְשָׁו אֵין לָהּ בֶּן זוּג. וְעַל זֶה שָׁנִינוּ, שֶׁמָּא יְקַדְּמֶנּוּ אַחֵר בְּרַחֲמִים, אַחֵר שֶׁשָּׁנִינוּ. וְהַכֹּל הוּא עַל תִּקּוּנוֹ."],[7,"","וְעַל זֶה כָּתוּב, (ויקרא כב) וּבַת כֹּהֵן כִּי תִהְיֶה אַלְמָנָה וּגְרוּשָׁה וְזֶרַע אֵין לָהּ וְשָׁבָה אֶל בֵּית אָבִיהָ כִּנְעוּרֶיהָ. וּבַת כֹּהֵן - הֲרֵי בֵּאַרְנוּ דָבָר זֶה. אַלְמָנָה - מֵאוֹתוֹ הַגּוּף הָרִאשׁוֹן. וּגְרוּשָׁה - שֶׁלֹּא נִכְנְסָה לְפַרְגּוֹד הַמֶּלֶךְ. שֶׁכָּל אוֹתָם שֶׁלֹּא עוֹמְדִים בְּעוֹלַם הַזָּכָר, אֵין לָהֶם בּוֹ חֵלֶק. הוּא הִשְׁתַּמֵּט וְעָקַר עַצְמוֹ מֵעוֹלַם הַזָּכָר, אָז אֵין לוֹ חֵלֶק בּוֹ, וְעַל כָּךְ הִיא גְרוּשָׁה. וְזֶרַע אֵין לָהּ - שֶׁאִם הָיָה לָהּ זֶרַע, לֹא נֶעֱקַר מִמֶּנּוּ וְלֹא הָיָה יוֹרֵד לְעוֹלַם הַנְּקֵבָה."],[8,"","וְשָׁבָה אֶל בֵּית אָבִיהָ, מַה זֶּה בֵּית אָבִיהָ? זֶה עוֹלַם הַנְּקֵבָה, שֶׁאוֹתוֹ הָעוֹלָם נִקְרָא בֵּית אָבִיהָ, וְאוֹתוֹ כְּלִי שֶׁהָיָה מֻתְקָן לְהִשְׁתַּמֵּשׁ בּוֹ, הִתְהַפֵּךְ וְהוּא יוֹרֵד לְמַטָּה, וְאוֹתוֹ כְּלִי עוֹלֶה לְמַעְלָה. כִּנְעוּרֶיהָ - כְּמוֹ אוֹתוֹ זְמַן שֶׁכָּתוּב אֲנִי הַיּוֹם יְלִדְתִּיךְ. יְלִדְתִּיךְ וַדַּאי, יָשׁוּב לִימֵי עֲלוּמָיו, כְּמוֹ שֶׁהָיָה (בתחלה) מִשְּׁלֹשׁ עֶשְׂרֵה שָׁנִים וָמַעְלָה."]]],[["אִי זָכָאת לְאִתְתַּקְנָא, הוֹאִיל וְשָׁבָה אֶל בֵּית אָבִיהָ, מִלֶּחֶם אָבִיהָ תֹּאכֵל, תִּתְעַנַּג מֵהַהוּא עִנּוּגָא. דְּעָלְמָא דְּנוּקְבָּא, דְּאַכְלֵי מִנַּהֲמָא דְּאַבִּירִים, דְּנָחִית מִלְּעֵילָּא. אֲבָל לְאִסְתַּכְּלָא וּלְאִתְהֲנֵי בְּמַה דְּאִתְהֲנוּן שְׁאַר צַדִּיקַיָּיא, לָא יַכְלָא בְּגִין דְּהֲוָה זָר לְתַמָּן. וְעַל דָּא לָא אָכִיל קֹדֶשׁ אֲבָל אָכִיל תְּרוּמָה, דְּאִיהוּ יָתִיב בְּעָלְמָא דְּנוּקְבָּא.","וּמִגּוֹ דְּאִיהוּ מֵעָלְמָא דְּנוּקְבָּא, לָא אָכִיל לֵיהּ אֶלָּא בַּלַּיְלָה, דִּכְתִּיב, (ויקרא כ״ב:ז׳) וּבָא הַשָּׁמֶשׁ וְטָהֵר וְאַחַר יֹאכַל מִן הַקֳּדָשִׁים כִּי לַחְמוֹ הוּא. דְּהָא קֹדֶשׁ דְּאִיהוּ מֵעָלְמָא דִּדְכוּרָא, לָא אִתְאֲכִיל אֶלָּא בַּיּוֹם. בְּגִינֵי כַּךְ (ירמיהו ב׳:ג׳) קֹדֶשׁ יִשְׂרָאֵל לַיְיָ' רֵאשִׁית תְּבוּאָתֹה, (בראשית ל\"א ע\"ב) שֵׁירוּתָא עִלָּאָה דְּכָל עָלְמָא דִּדְכוּרָא, (נ\"ט ע\"א) קֹדֶשׁ אִיהוּ, וּמַה דְּסָלִיק בֵּיהּ, בַּקֹּדֶשׁ יִשְׂרָאֵל הֲוָה, וּבְגִינִי כַּךְ קֹדֶשׁ יִשְׂרָאֵל לַיְיָ' רִאשִׁית תְּבוּאָתֹה.","כַּד רוּחִין פְּקִידַאן, בְּאִינּוּן זִמְנִין דְּפַקְדִין לְבֵי קִבְרֵי, אִינּוּן לָא פַּקְדִין, דְּהָא לָא זָכָאן לְעָלְמָא דְּקֹדֶשׁ, דִּכְתִּיב, (ויקרא כ״ב:י׳) וְכָל זָר לֹא יֹאכַל קֹדֶשׁ. וְאִי לָא זָכָה הַהוּא רוּחָא לְאִתְתַּקְנָא כְּדְקָא יֵאוֹת, כֵּיוָן דְּאַהֲדָר בְּגִלְגּוּלָא, אֲפִילּוּ בְּהַהוּא אֲתָר, בִּתְרוּמָה לָא אָכִיל, וְזָר אִקְרֵי, אֲפִילּוּ לְעָלְמָא תַּתָּאָה וְלָא אָכִיל בָּהּ. עַד הָכָא בְּרָזָא דָּא.","סָבָא סָבָא, כֵּיוָן דִּשְׁרִיאַת לְשַׁטְּטָא בְּיַמָּא רַבָּא, זִיל בִּרְעוּתָךְ, לְכָל סִטְרִין דְּיַמָּא. הַשְׁתָּא אִית לְגַלָּאָה, דְּהָא אֲמֵינָא, דְּהַאי פָּרוֹקָא כַּד אָתֵי, עָאל גַּבֵּי הַהוּא מָאנָא, דְּקָא אֲמֵינָא, אָעִיל תַּמָּן, וְדָבִיק תַּמָּן רוּחָא (דעלמא) דִּילֵיהּ בְּהַהוּא מָאנָא וְלָא אִתְאֲבִיד כְּלוּם, אֲפִילּוּ הֲבַל דְּפוּמָא, יֵאוֹת הוּא וְכָךְ הוּא. סָבָא סָבָא, אִי תֵּימָא וּתְגָלֵי, אֵימָא בְּלָא דְּחִילוּ.","שְׁאַר בְּנֵי נָשָׁא דְּעָלְמָא, דְּקָא מִסְתַּלְּקֵי מִנֵּיהּ, וְהָא יְדַעְנָא, דְּרוּחַ דִּילֵיהּ שָׁבִיק בְּהַהִיא אִתְּתָא דַּהֲוַת לֵיהּ, וְרוּחָא אָעִיל תַּמָּן, מָה אִתְעָבִיד מֵהַהוּא רוּחַ. וְאִי נַסְבָא הַאי אִתְּתָא, אוּף הָכִי, מָה אִתְעָבִיד מֵהַהוּא רוּחַ דְּשָׁבַק בָּהּ בַּעְלָהּ קַדְמָאָה, דְּהָא גְּבַר אַחֲרָא אָתֵי עָלָהּ.","לְאִתְקַיְּימָא רוּחַ בְּרוּחַ לָא אֶפְשָׁר, דְּהָא הַאי דְּאָתֵי עָלָהּ הַשְׁתָּא, רוּחַ אָעִיל בָּהּ. וְכֵן הַהוּא קַדְמָאָה דְּאִסְתָּלִיק, רוּחַ אָעִיל בָּהּ. הַהוּא קַדְמָאָה דְּאִסְתַּלָּק בְּנִין הֲווֹ לֵיהּ, וְדָא דְּהַשְׁתָּא לָאו פָּרוֹקָא אִיהוּ, רוּחַ דְּשָׁבַק הַהוּא קַדְמָאָה בְּהַהוּא מָאנָא, וְאָתָא הַאי אַחֲרָא וְאָעִיל בָּהּ רוּחַ, וַדַּאי לָא יַכְלֵי תַּרְוַיְיהוּ לְאִתְקַיְּימָא בְּהַהוּא גּוּפָא דְּאִתְּתָא כַּחֲדָא, אִי נִימָא דְּאִתְאֲבִיד, אִי אֶפְשָׁר, מָה אִתְעָבִיד מִנֵּיהּ.","אוּף הָכִי אִי אִיהִי לָא אִתְנְסִיבַת, הַהוּא רוּחָא דְּשָׁבַק בָּהּ בַּעְלָהּ, מַאי אִתְעָבִיד מִנִּיהּ. אִי נִימָא דְּאִתְאֲבִיד, לָאו הָכִי. כָּל דָּא צָרִיךְ לְגַלָּאָה הַשְׁתָּא. סָבָא סָבָא, חָמֵי מָה עַבְדַת, וּבַמֶּה אָעִילַת גַּרְמָךְ. קוּם סָבָא, אָרִים דִּגְלָךְ. קוּם סָבָא, וְאַשְׁפִּיל גַּרְמָךְ קָמֵי מָארָךְ.","פָּתַח הַהוּא סָבָא וְאָמַר, (תהילים קל״א:א׳) יְיָ' לא גָּבַהּ לִבִּי וְלֹא רָמוּ עֵינַי וְגוֹ'. דָּוִד מַלְכָּא אָמַר דָּא, בְּגִין דְּהֲוָה מַלְכָּא עִלָּאָה, וְשַׁלִּיטָא עַל כָּל מַלְכִין עִלָּאִין, וְשַׁלִּיטִין דְּאִית מִמִּזְרָח וְעַד מַעֲרָב, וְלָא סָלִיק עַל לִבֵּיהּ לְאַסְטָאָה מֵאָרְחָא, וְתָדִיר שָׁפִיל לִבֵּיהּ קָמֵי מָארֵיהּ, וְכַד הֲוָה לָעֵי בְּאוֹרַיְיתָא, הֲוָה מִתְגַּבַּר כְּאַרְיָא, וְעֵינוֹי תָּדִיר מְאִיכִין בְּאַרְעָא, מִדְּחִילוּ דְּמָארֵיהּ. וְכַד הֲוָה אָזִיל בֵּין עַמָּא, לָא הֲוָה בֵּיהּ גַּסּוּת רוּחָא כְּלַל.","וְעַל דָּא כְּתִיב, יְיָ' לֹא גָּבַהּ לִבִּי וְגוֹ', לֹא גָּבַהּ לִבִּי, אַף עַל גַּב דַּאֲנָא מַלְכָּא שַׁלִּיטָא עַל כָּל שְׁאַר מַלְכִין דְּעָלְמָא. וְלֹא רָמוּ עֵינֵי, בְּזִמְנָא דַּאֲנָא קַיְּימָא קַמָּךְ, לָעֵי בְּאוֹרַיְיתָא. וְלא הִלַּכְתִּי בִּגְדוֹלוֹת וּבְנִפְלָאוֹת מִמֶּנִּי, בְּשַׁעֲתָא דַּאֲנָא אָזִיל בֵּין עַמָּא. וְאִי דָּוִד מַלְכָּא אָמַר הָכִי, שְׁאַר בְּנֵי עָלְמָא עַל אַחַת כַּמָּה וְכַמָּה. וַאֲנָא כַּמָּה אֲנָא שָׁפִיל לִבָּא, וּמָאִיךְ עֵינָא קָמֵי מַלְכָּא קַדִּישָׁא. וְחָס לִי, דִּבְמִלִּין קַדִּישִׁין דְּאוֹרַיְיתָא, יְרוֹם לִבָּאי. בָּכָה וְדִמְעוֹי נַפְלִין עַל דִּיקְנֵיהּ.","אָמַר, סָבָא לָאֵי בְּחֵילָא, כַּמָּה שַׁפִּירָאן דִּמְעִין עַל דִּיקְנָךְ, כְּמָה דְּהֲוָה שַׁפִּיר מִשְׁחָא טָבָא, כַּד הֲוָה נָחִית עַל דִּיקְנָא דְּסָבָא טָבָא דְּאַהֲרֹן. אֵימָא מִילָךְ סָבָא דְּהָא מַלְכָּא קַדִּישָׁא הָכָא. שְׁאַר בְּנֵי נָשָׁא דְּעָלְמָא, דְּקָא אִסְתָּלָקוּ מִנֵּיהּ, וְשָׁבְקוּ רוּחָא בְּהַהוּא מָאנָא, דַּהֲווֹ מִשְׁתַּמְּשֵׁי בֵּיהּ, וְאִתְנְסִיבַת, וְאָתָא אַחֲרָא וְאָעִיל בְּהַהוּא מָאנָא רוּחָא אַחֲרָא, מָה אִתְעָבִיד מֵהַהוּא קַדְמָאָה, כְּמָה דְּאִתְּמַר."],[[0,"אי זכאת לאתתקנא וכו':","אם זכתה להתתקן, כיון ששבה אל בית אביה, \u0003מלחם אביה תאכל,\u0004 תתענג מעונג ההוא של עולם הנקבה, שאוכלים מלחם אבירים היורד מלמעלה, מז\"א. אבל להסתכל ולהנות במה שנהנים שאר הצדיקים אינה יכולה, משום שהיא זר שמה. שכתוב עליה כל זר לא יאכל קדש. מפני שקדש הוא בעולם הזכר. אבל אוכלת תרומה, מפני שהיא יושבת בעולם הנקבה."],[1,"ומגו דאיהו מעלמא וכו':","ומשום שהיא מעולם הנקבה, אינה אוכלת אותו אלא בלילה, שאז שליטת הנוקבא שהיא המלכות, שכתוב, ובא השמש וטהר ואחר יאכל מן הקדשים כי לחמו הוא. כי קדש שהוא מעולם הזכר, אינו נאכל אלא ביום. שאז שליטת הזכר שהוא ז\"א. משום זה כתוב, קדש ישראל לה' ראשית תבואתה. ונקרא ראשית, כי התחלה עליונה של כל עולם הזכר הוא קדש, דהיינו או\"א עלאין שהם המוחין דז\"א, ומה שעלה מן הקדש הוא ישראל, דהיינו ז\"א, ומשום זה קדש ישראל לה' ראשית תבואתה."],[2,"כד רוחין פקידאן וכו':","כשהרוחות פוקדים, באלו הזמנים שפוקדים, בבית הקברות, דהיינו משהחשיך עד חצות לילה (כמ\"ש שלח קס\"ו:) להם, המתים בלא בנים, אינם פוקדים, כי אינם זוכים לעולם דקדש, שכתוב, וכל זר לא יאכל קדש. ואין לרוחות שלהם שפע להשפיע לגוף בבית הקברות. ואם לא זכה רוח ההוא להתתקן כראוי, כיון שחזר בגלגול, אפילו במקום ההוא, של עולם הנקבה, אינו אוכל בתרומה, ונקרא זר אפילו לעולם התחתון, שהוא עולם הנקבה, ואינו אוכל בה. עד כאן בסוד הזה של יבום."],[3,"סבא סבא, כיון וכו':","אמר לעצמו זקן זקן, כיון שהתחלת לשוט בים הגדול לך ברצונך לכל הצדדים של הים. עתה יש לגלות, כי אמרתי שגואל הזה, דהיינו היבם, כשבא ונכנס אל כלי ההוא שאמרתי, דהיינו היבמה, הביא שמה והדביק שם הרוח שלו בכלי ההוא, ואין נאבד כלום אפילו הבל פה, (כנ\"ל אות קי\"ט) יפה הוא וכך הוא. זקן זקן, אם תאמר ותגלה אמור בלי פחד."],[4,"שאר בני נשא וכו':","שאר אנשים שבעולם, הנפטרים ממנו, הרי יודעים אנו, שהרוח שלו עזב באשה ההיא שהיתה לו, ורוח הביא שם בביאה הראשונה. מה נעשה מרוח ההוא. ואם נשאת אשה ההיא, אף כן, מה נעשה מרוח ההוא שעזב בה בעלה הראשון, שהרי איש אחר בא עליה."],[5,"לאתקיימא רוח ברוח וכו':","להתקיים רוח עם רוח לא אפשר, שהרי זה שבא עליה עתה, הכניס בה רוח, וכן הראשון שנסתלק הכניס בה רוח. הראשון ההוא שנסתלק היה לו בנים, וזה של עתה אינו גואל, וע\"כ, רוח שעזב בה הראשון בכלי ההוא, ובא אחר הזה והביא בה רוח גם הוא, ודאי שאינם יכולים שניהם להתקיים יחד בגוף ההוא של האשה. ואם נאמר שנאבד. זה לא אפשר. כי שום דבר אינו נאבד, כנ\"ל. וא\"כ מה נעשה ממנו."],[6,"אוף הכי אי וכו':","אף כן, אם היא לא נשאת, רוח ההוא שעזב בה בעלה מה נעשה ממנו. אם נאמר שנאבד. אינו כן. כל זה צריך לגלות עתה. אמר לעצמו, זקן זקן, ראה מה עשית, ובמה הכנסת את עצמך. קום זקן הרם את דגלך. קום זקן, והשפל את עצמך לפני אדונך."],[7,"פתח ההוא סבא וכו':","פתח זקן ההוא ואמר, ה' לא גבה לבי ולא רמו עיני וגו'. דוד המלך אמר זה, משום שהיה מלך עליון, ושליט על כל מלכים עליונים, והשליטים שיש ממזרח עד מערב, דהיינו שהיו מפחדים מגבורתו, ולא עלה על לבו לסור מן הדרך, ותמיד השפיל לבו לפני אדונו. וכשהיה עוסק בתורה היה מתגבר כארי, ועיניו תמיד היו מושפלות לארץ מפחד אדונו. וכשהיה הולך בין העם לא היה בו גסות הרוח כלל."],[8,"ועל דא כתיב וכו':","ועל זה כתוב, ה' לא גבה לבי וגו'. \u0003לא גבה לבי,\u0004 אע\"פ שאני מלך ושליט על כל שאר מלכי העולם. \u0003ולא רמו עיני,\u0004 בזמן שאני עומד לפניך עוסק בתורה. \u0003ולא הלכתי בגדולות ובנפלאות ממני,\u0004 בשעה שאני הולך בין העם. ואם דוד המלך אמר כן, שאר בני העולם על אחת כמה וכמה. ואני כמה אני שפל לב, ומשפיל עיניו לפני מלך הקדוש. וחלילה לי שבדברים הקדושים של התורה ירום לבי."],[9,"אמר, סבא לאי וכו':","אמר לעצמו זקן עיף בלי כח, כמה יפות הן הדמעות שעל זקנך כמו שהיה יפה, השמן הטוב כשהיה יורד על זקנו של אהרון, הזקן הטוב. אמור דבריך זקן, כי המלך הקדוש כאן. שאר אנשים שבעולם, שנפטרו ממנו, ועזבו רוח בכלי ההוא שהיו משתמשים בו, דהיינו בנשיהם, ונשאת ובא אחר והכניס בכלי ההוא רוח אחר מה נעשה מרוח הראשון. כמושאמרתי."]],[[0,"","אִם זָכְתָה לְהִתַּקֵּן - הוֹאִיל וְשָׁבָה אֶל בֵּית אָבִיהָ, מִלֶּחֶם אָבִיהָ תֹּאכֵל, תִּתְעַנֵּג מֵאוֹתוֹ הָעֹנֶג שֶׁל עוֹלַם הַנְּקֵבָה שֶׁאוֹכְלִים מִלֶּחֶם אַבִּירִים שֶׁיּוֹרֵד מִלְמַעְלָה. אֲבָל לְהִסְתַּכֵּל וְלֵהָנוֹת בְּמַה שֶּׁנֶּהֱנִים שְׁאָר הַצַּדִּיקִים לֹא יָכוֹל, מִשּׁוּם שֶׁהָיָה זָר לְשָׁם. וְעַל זֶה הוּא לֹא אוֹכֵל קֹדֶשׁ, אֲבָל אוֹכֵל תְּרוּמָה, כִּי הוּא יוֹשֵׁב בְּעוֹלַם הַנְּקֵבָה."],[1,"","וּמִתּוֹךָ שֶׁהוּא מֵעוֹלַם הַנְּקֵבָה, לֹא אוֹכֵל אוֹתוֹ אֶלָּא בַּלַּיְלָה, שֶׁכָּתוּב (ויקרא כב) וּבָא הַשֶּׁמֶשׁ וְטָהֵר וְאַחַר יֹאכַל מִן הַקְּדָשִׁים כִּי לַחְמוֹ הוּא. שֶׁהֲרֵי קֹדֶשׁ שֶׁהוּא מֵעוֹלַם הַזָּכָר לֹא נֶאֱכָל אֶלָּא בַּיּוֹם. מִשּׁוּם כָּךְ (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה, רֵאשִׁית עֶלְיוֹנָה שֶׁל כָּל עוֹלַם הַזָּכָר הִיא קֹדֶשׁ, וּמַה שֶּׁעוֹלֶה בּוֹ, בַּקֹּדֶשׁ הָיָה יִשְׂרָאֵל, וּמִשּׁוּם כָּךְ קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה."],[2,"","כְּשֶׁרוּחוֹת פּוֹקְדוֹת, בְּאוֹתָם זְמַנִּים שֶׁפּוֹקְדִים אֶת בֵּית הַקְּבָרוֹת, אוֹתָם לֹא פוֹקְדִים, שֶׁהֲרֵי לֹא זוֹכוֹת לְעוֹלַם הַקֹּדֶשׁ, שֶׁכָּתוּב (ויקרא כב) וְכָל זָר לֹא יֹאכַל קֹדֶשׁ. וְאִם אוֹתָהּ רוּחַ לֹא זָכְתָה לְהִתַּקֵּן כָּרָאוּי, כֵּיוָן שֶׁחָזַר בְּגִלְגּוּל אֲפִלּוּ בְּאוֹתוֹ מָקוֹם, לֹא אוֹכֵל בִּתְרוּמָה, וְנִקְרָא זָר אֲפִלּוּ לָעוֹלָם הַתַּחְתּוֹן וְלֹא אוֹכֵל בָּהּ. עַד כָּאן בְּסוֹד זֶה."],[3,"","זָקֵן זָקֵן, כֵּיוָן שֶׁהִתְחַלְתָּ לָשׁוּט בַּיָּם הַגָּדוֹל, לֵךְ בִּרְצוֹנְךְ לְכָל צִדְדֵי הַיָּם. עַכְשָׁו יֵשׁ לְגַלּוֹת, שֶׁהֲרֵי אָמַרְנוּ, שֶׁכְּשֶׁבָּא הַגּוֹאֵל הַזֶּה וְנִכְנָס אֶל אוֹתוֹ הַכְּלִי שֶׁאָמַרְנוּ, מַכְנִיס לְשָׁם וּמַדְבִּיק שָׁם אֶת הָרוּחַ (של העולם) שֶׁלּוֹ בְּאוֹתוֹ כְּלִי וּכְלוּם לֹא נֶאֱבָד, אֲפִלּוּ הֶבֶל הַפֶּה - יָפֶה הוּא וְכָךְ הוּא. זָקֵן זָקֵן, אִם תֹּאמַר וּתְגַלֶּה, אֱמֹר בְּלִי פַחַד."],[4,"","שְׁאָר בְּנֵי הָאָדָם שֶׁל הָעוֹלָם שֶׁעוֹלִים מִמֶּנּוּ, וַהֲרֵי יָדַעְנוּ שֶׁרוּחוֹ הִשְׁאִיר בְּאוֹתָהּ אִשָּׁה שֶׁהָיְתָה לוֹ, וְהִכְנִיס לְשָׁם רוּחַ, מַה נַּעֲשֶׂה מֵאוֹתָהּ הָרוּחַ? וְאִם נִשֵּׂאת הָאִשָּׁה הַזּוֹ, אַף כָּךְ - מַה נַּעֲשֶׂה מֵאוֹתָהּ רוּחַ שֶׁהִשְׁאִיר בָּהּ בַּעְלָהּ הָרִאשׁוֹן, שֶׁהֲרֵי אִישׁ אַחֵר בָּא עָלֶיהָ?"],[5,"","לְהִתְקַיִּםִ רוּחַ עִם רוּחַ אִי אֶפְשָׁר, שֶׁהֲרֵי זֶה שֶׁעַכְשָׁו בָּא עָלֶיהָ, הִכְנִיס בָּהּ רוּחַ, וְכֵן אוֹתוֹ הָרִאשׁוֹן שֶׁהִסְתַּלֵּק הִכְנִיס בָּהּ רוּחַ. אוֹתוֹ רִאשׁוֹן שֶׁהִסְתַּלֵּק הָיוּ לוֹ בָּנִים, וְזֶה שֶׁל עַכְשָׁו אֵינוֹ גוֹאֵל רוּחַ שֶׁהִשְׁאִיר אוֹתוֹ רִאשׁוֹן בְּאוֹתוֹ כְּלִי, וּבָא הָאַחֵר הַזֶּה וְהִכְנִיס בָּהּ רוּחַ, וַדַּאי שֶׁלֹּא יוּכְלוּ שְׁנֵיהֶם לְהִתְקַיֵּם בְּאוֹתוֹ גוּף הָאִשָּׁה כְּאֶחָד. וְאִם נֹאמַר שֶׁנֶּאֱבַד - אִי אֶפְשָׁר. מַה נַּעֲשָׂה מִמֶּנּוּ?"],[6,"","אַף כָּךְ אִם הִיא לֹא נִשְׂאָה, אוֹתָהּ רוּחַ שֶׁהִשְׁאִיר בָּהּ בַּעְלָהּ מַה נַּעֲשֶׂה מִמֶּנָּה? אִם נֹאמַר שֶׁתֹּאבַד - לֹא כָּךְ. כָּל זֶה צָרִיךְ עַכְשָׁו לְגַלּוֹת. זָקֵן זָקֵן, רְאֵה מֶה עָשִׂיתָ וּבַמָּה הִכְנַסְתָּ אֶת עַצְמְךְ. קוּם זָקֵן הָרֵם דִּגְלְךְ! קוּם זָקֵן וְהַשְׁפֵּל עַצְמְךְ לִפְנֵי רִבּוֹנְךְ!"],[7,"","פָּתַח אוֹתוֹ זָקֵן וְאָמַר, (תהלים קלא) ה' לֹא גָבַהּ לִבִּי וְלֹא רָמוּ עֵינַי וְגוֹ'. דָּוִד הַמֶּלֶךְ אָמַר אֶת זֶה מִשּׁוּם שֶׁהָיָה מֶלֶךְ עֶלְיוֹן וְשׁוֹלֵט עַל כָּל הַמְּלָכִים הָעֶלְיוֹנִים וְהַשַּׁלִּיטִים שֶׁיֵּשׁ מִמִּזְרָח וְעַד מַעֲרָב, וְלֹא עָלָה עַל לִבּוֹ לִסְטוֹת מִן הַדֶּרֶךְ, וְתָמִיד שָׁפַל לִבּוֹ לִפְנֵי רִבּוֹנוֹ, וּכְשֶׁהָיָה עוֹסֵק בַּתּוֹרָה, הָיָה מִתְגַּבֵּר כָּאַרְיֵה, וְעֵינָיו תָּמִיד מֻנְמָכוֹת לָאָרֶץ מִפַּחַד רִבּוֹנוֹ, וּכְשֶׁהָיָה הוֹלֵךְ בֵּין הָעָם, לֹא הָיְתָה בּוֹ גַּסּוּת הָרוּחַ כְּלָל."],[8,"","וְעַל זֶה כָּתוּב (תהלים קלא) ה' לֹא גָבַהּ לִבִּי וְגוֹ'. לֹא גָבַהּ לִבִּי, אַף עַל גַּב שֶׁאֲנִי מֶלֶךְ שַׁלִּיט עַל כָּל שְׁאָר מַלְכֵי הָעוֹלָם. וְלֹא רָמוּ עֵינַי, בִּזְמַן שֶׁאֲנִי עוֹמֵד לְפָנֶיךְ וְעוֹסֵק בַּתּוֹרָה. וְלֹא הִלַּכְתִּי בִּגְדֹלוֹת וּבְנִפְלָאוֹת מִמֶּנִּי, בְּשָׁעָה שֶׁאֲנִי הוֹלֵךְ בֵּין הָעָם. וְאִם דָּוִד הַמֶּלֶךְ אָמַר כָּךְ - שְׁאָר בְּנֵי הָעוֹלָם עַל אַחַת כַּמָּה וְכַמָּה. וַאֲנִי כַּמָּה אֲנִי שְׁפַל לֵב עִם עַיִן נְמוּכָה לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וַחֲבָל לִי שֶׁבִּדְבָרִים קְדוֹשִׁים שֶׁל הַתּוֹרָה יָרוּם לִבִּי. בָּכָה וְדִמְעוֹתָיו נוֹפְלוֹת עַל זְקָנוֹ."],[9,"","אָמַר, זָקֵן עָיֵף בְּכֹחַ, כַּמָּה יָפוֹת הַדְּמָעוֹת עַל זְקָנְךְ, כְּמוֹ שֶׁהָיָה יָפֶה הַשֶּׁמֶן הַטּוֹב כְּשֶׁהָיָה יוֹרֵד עַל הַזָּקָן שֶׁל הַזָּקֵן הַטּוֹב אַהֲרֹן. אֱמֹר דְּבָרְךְ, זָקֵן, שֶׁהֲרֵי הַמֶּלֶךְ הַקָּדוֹשׁ כָּאן. שְׁאָר בְּנֵי אָדָם שֶׁל הָעוֹלָם שֶׁהִסְתַּלְּקוּ מִמֶּנּוּ, וְהִשְׁאִירוּ רוּחַ בְּאוֹתוֹ כְּלִי שֶׁהָיוּ מִשְׁתַּמְּשִׁים בּוֹ, וְנִשְּׂאָה, וּבָא אַחֵר וְהִכְנִיס לְאוֹתוֹ כְּלִי רוּחַ אַחֶרֶת, מַה נַּעֲשֶׂה מֵאוֹתוֹ רִאשׁוֹן, כְּמוֹ שֶׁנִּתְבָּאֵר?"]]],[["תָּא חֲזִי, כַּמָּה עִלָּאִין גְּבוּרָאן דְּמַלְכָּא קַדִּישָׁא, דְּקָא עָבִיד, וּמַאן יָכִיל לְמַלְּלָא לוֹן. כַּד הַאי בַּעְלָהּ תִּנְיָינָא, אָתֵי וְאָעִיל רוּחָא בְּהַהוּא מָאנָא, רוּחָא קַדְמָאָה, מְקַטְרְגָא בְּהַאי רוּחַ דְּעָאל, וְלָא אִתְיַישְּׁבָן כַּחֲדָא.","וּבְגִינֵי כַּךְ, אִתְּתָא לָא אִתְיַישְּׁבַת כְּדְקָא יֵאוֹת, בַּהֲדֵי בַּעְלָהּ תִּנְיָינָא, בְּגִין דְּרוּחָא קַדְמָאָה מְכַשְׁכְּשָׁא בָּהּ, וּכְדֵין אִיהִי דְּכִירַת לֵיהּ תָּדִיר, וּבָכָאת עָלֵיהּ, אוֹ אִתְאַנְחַת עָלֵיהּ, דְּהָא רוּחָא דִּילֵיהּ, מְכַשְׁכְּשָׁא בִּמְעָהָא כְּחִוְיָא, וּמְקַטְרְגָא בַּהֲדֵי רוּחַ אַחֲרָא, דְּעָאל בָּהּ מִבַּעְלָהּ תִנְיָנָא. עַד זְמָן סַגִּי מְקַטְרְגִין דָּא בְּדָא.","וְאִי אַעְבָּר דָּא דְּעָאל, לְהַהוּא (אתערו) דְּהֲוָה קַדְמָאָה (לבתר), דָּא קַדְמָאָה נָפִיק וְאָזִיל לֵיהּ. וּלְזִמְנִין, דְּדָחֵי דָּא קַדְמָאָה לְהַהוּא תִּנְיָינָא, וְאִתְעָבִיד לֵיהּ מְקַטְרְגָא, עַד דְּאַפִּיק לֵיהּ מֵעָלְמָא. וְעַל דָּא תָּנֵינָן, דְּמִתְּרֵין וּלְהָלְאָה, לָא יִסַּב בַּר נָשׁ לְהַאי אִתְּתָא, דְּהָא מַלְאַךְ הַמָּוֶת אִתְתָּקַּף בָּהּ, וּבְנֵי עָלְמָא לָא יַדְעִין, דְּהָא רוּחָא כֵּיוָן דְּאִתְתָּקַּף וְקָא נָצַח לְהַהוּא רוּחָא אַחֲרָא תִּנְיָינָא, מִכָּאן וּלְהָלְאָה לָא יִתְעָרַב בַּר נָשׁ אַחֲרָא בַּהֲדָהּ.","חַבְרַיָּיא, הָא יְדַעְנָא דִּבַאֲתָר דָּא אִית לְכוּ לְמִקְשֵׁי, וְלֵימָא אִי הָכִי לָא מִית בְּדִינָא הַאי תִּנְיָינָא, וְלָא דַּיְינִין לֵיהּ מִלְּעֵילָּא. תָּא חֲזִי, כֹּלָּא אִיהוּ בְּדִינָא, דְּיִנְצַח פְּלוֹנִי לִפְלוֹנִי אוֹ דְּלָא יְקַטְרֵג עָלֵיהּ פְּלוֹנִי לִפְלוֹנִי. וּמַאן דְּנָסִיב אַרְמַלְתָא, כְּמַאן דְּעָאל בְּיַמָּא, בְּרוּחִין תַּקִּיפִין, בְּלֹא חַבְלִין, וְלָא יָדַע אִי יַעֲבָר בִּשְׁלָם, אִי יִטְבַּע גּוֹ תְּהוֹמֵי.","וְאִי דָּא דְּעָאל הַהוּא רוּחָא תִּנְיָינָא, אִתְתָּקִיף וְנָצַח לְהַהוּא קַדְמָאָה, הַהוּא קַדְמָאָה נָפַק מִתַּמָּן וְאָזִיל לֵיהּ. לְאָן אֲתָר אָזִיל לֵיהּ, וּמָה אִתְעָבִיד. סָבָא סָבָא מָה עַבְדַת. חָשַׁבְתּ דִּתְמַלֵּל זְעֵיר, וְנַפְקַת לְהַאי, הָא עָאלַת בַּאֲתַר דְּלָא עָאל בַּר נָשׁ אַחֲרָא, מִן יוֹמָא דְּדוֹאֵג וַאֲחִיתוֹפֶל עָבְדוּ בַּעְיָין אִלֵּין, בְּאִינּוּן אַרְבַּע מֵאָה בַּעְיִיִ, דַּהֲווֹ בָּעָאן עַל מִגֲדְּלָא דְּפָרַח בַּאֲוִירָא, וְלָא אָתִיב עָלַיְיהוּ בַּר נָשׁ, עַד דְּאָתָא שְׁלמֹה מַלְכָּא, וּבִירֵר לוֹן כָּל חַד וְחַד עַל תְקּוּנֵיהּ. סָבָא סָבָא, רָזָא עִלָּאָה דְּהֲוָה טְמִירָא, אָתִית לְגַלָּאָה, מָה עֲבָדִית.","סָבָא סָבָא, בְּקַדְמִיתָא הֲוָה לָךְ לְנַטְרָא אָרְחָךְ, וְתִסְתַּכַּל בְּרֵישָׁךְ. אֲבָל הַשְׁתָּא, לָאו שַׁעֲתָא לְאִתְטַמְּרָא. סָבָא, אַהְדָּר בְּתֻקְפָךְ. הַהוּא רוּחַ דְּנָפַק, לְאָן אָזִל. בָּכָה וְאָמַר, חַבְרַיָּא, כָּל הָנִי בִּכְיָין דְּקָא בָּכֵינָא, לָאו בְּגִינַיְיכוּ הוּא, אֶלָּא דָּחִילְנָא לְמָארֵי עָלְמָא, דְּגַלֵּינָא אָרְחִין סְתִימִין, בְּלֹא רְשׁוּ. אֲבָל גַּלֵּי קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, דְּלָא לִיקָרָא דִּילִי עֲבִידְנָא, וְלָא לִיקָרָא דְּאַבָּא, אֲבָל רְעוּתִי לְפוּלְחָנָא דִּילֵיהּ, וַאֲנָא חֲמֵינָא, יְקָרָא דְּחָד מִנַּיְיכוּ, בְּהַהוּא עָלְמָא, וְאַחֲרָא יְדַעְנָא דְּהָכִי הוּא. אֲבָל לָא גַּלֵּי קָמָאי, וְהַשְׁתָּא חֲמֵינָא.","תָּנֵינָן, דַּחְיָין גַּבְרָא מִקָּמֵי גַּבְרָא, בְּכַמָּה אָרְחִין סְתִימִין (וילך רפ\"ד ע\"א) אִתְדַּחְיָין. הַהוּא רוּחָא קַדְמָאָה, דְּאִתְדָּחֵי מִקָּמֵי הַהוּא תִּנְיָינָא, לְאָן אָזִיל. הַהוּא רוּחָא, נָפִיק וְאָזִיל, וּמְשַׁטְּטָא בְּעָלְמָא, וְלָא יְדִיעַ, וְאָזִיל לְגוֹ קִבְרָא דְּהַהוּא בַּר נָשׁ, וּמִתַּמָּן מְשַׁטְּטָא בְּעָלְמָא, וְאִתְחַזֵּי בְּחֶלְמָא לִבְנִי נָשָׁא, וְחָמָאן בְּחֶלְמָא דִּיּוּקְנָא דְּהַהוּא בַּר נָשׁ, וְאוֹדַע לוֹן מִלִּין לְפוּם אָרְחֵיהּ דְּהַהוּא רוּחַ קַדְמָאָה, דְּקָא אִתְמְשַׁךְ מִנֵיהּ, כְּמָה דְּאִיהוּ בְּהַהוּא עָלְמָא, הָכִי מְשַׁטְּטָא הַאי, וְאוֹדַע בְּהַאי עָלְמָא.","וְהָכִי אָזִיל וּמְשַׁטְּטָא בְּעָלְמָא, וּפַקְדַת תָּדִיר לְהַהוּא קִבְרָא, עַד (אחורי הדף) זִמְנָא דְּרוּחוֹת פַּקְדָן לְגַבֵּי קִבְרַיְיהוּ דְּגוּפִין. כְּדֵין, הַאי רוּחָא, אִתְחַבָּר בְּהַהוּא רוּחַ דִּילֵיהּ, וְאִתְלָבַשׁ בֵּיהּ, וְאָזִיל לֵיהּ. כַּד עָאל לְדוּכְתֵּיהּ, אִתְפָּשַׁט מִנֵּיהּ. וְדוּכְתָּא אִית לֵיהּ (באינון רוחין בגן עדן) בְּאִינּוּן הֵיכָלִין דְּגַן עֵדֶן, אוֹ לְבַר, לְפוּם אָרְחוֹי דְּכָל חַד וְחַד, וְתַמָּן אִתְטָמַּר."],[[0,"תא חזי כמה וכו':","בוא וראה, כמה גבוהות הגבורות שעושה המלך הקדוש, ומי יכול לספר אותם. כשבעל השני הזה בא ומכניס רוח בכלי ההוא, באשה, רוח הראשון, של בעל הראשון, מקטרג ברוח הזה שנכנס, ואינם מתישבים יחד."],[1,"ובגיני כך אתתא וכו':","ומשום כך, אשה אינה מתישבת כראוי עם בעל שני, משום שרוחו של הראשון דופק בה, ואז היא זוכרת אותו תמיד, ובוכה עליו או נאנחת עליו, כי הרוח שלו דופק במעיה כנחש, ומקטרג על רוח האחר שנכנס בה מבעל השני. עד זמן רב מקטרגים זה בזה."],[2,"ואי אעבר דא וכו':","ואם העביר, זה שנכנס מבעל השני, לאותו הרוח שהיה ראשון, מבעל הראשון, זה הראשון יוצא והולך לו. ולפעמים שהראשון דוחה את השני ההוא, ונעשה לו מקטרג, עד שמוציאו מן העולם. ועל זה למדנו, שמשנים והלאה, דהיינו אחר שמתו שני בעליה, לא יקח אדם את האשה ההיא. כי מלאך המות התחזק בה. ובני העולם אינם יודעים, כי הרוח הזה, של בעל הראשון, כיון שנתחזק ונצח לרוח ההוא האחר השני, ודחה אותו מן העולם, מכאן ולהלאה, לא יתערב איש אחר עמה."],[3,"חבריא הא ידענא וכו':","חברים, הרי אני יודע, שבמקום זה יש לכם להקשות ולומר, אם כן לא מת בדין בעל השני הזה, ולא דנו אותו מלמעלה, אלא הרוח של בעל הראשון דחה אותו. בוא וראה, הכל הוא בדין, כי דנים למעלה, שינצח פלוני לפלוני, או שלא יקטרג פלוני על פלוני. ומי שלוקח אלמנה דומה כמי שנכנס לים, כשנושבים רוחות חזקות, בלי חבלים ואינו יודע אם יעבור בשלום או שיטבע תוך התהומות."],[4,"ואי דא דעאל וכו':","ואם זה שנכנס עתה דהיינו רוח ההוא השני נתחזק ונצח את רוח הראשון, ראשון ההוא יוצא משם והולך לו. ושואל לאיזה מקום הלך לו, ומה נעשה ממנו. אמר לעצמו, זקן זקן, מה עשית, חשבת שתדבר מעט ותצא מזה, הרי נכנסת במקום שלא נכנס אדם אחר, מיום שדואג ואחיתופל עשו שאלות אלו, באלו ד' מאות שאלות שהיו שואלים על מגדל הפורח באויר. ולא השיב עליהם אדם עד שבא שלמה המלך, ובירר כל אחת ואחת על תקונה. זקן זקן, סוד עליון שהיה סתום באת לגלות, מה עשית."],[5,"סבא סבא בקדמיתא וכו':","זקן זקן, בתחילה היה לך לשמור דרכך, ולהסתכל בתחילתך, אבל עתה אין השעה להסתתר, זקן, השב בגבורתך. רוח ההוא שיצא איפה הלך. בכה ואמר, חברים, כל אלו בכיות שבכיתי לא בשבילכם היה, אלא יראתי מפני רבון העולם, שגליתי דרכים סתומים בלא רשות. אבל גלוי לפני הקב\"ה, שלא לכבודי עשיתי ולא לכבוד אבי, אבל רצוני לעבודתו. ואני ראיתי יקר של אחד מכם בעולם ההוא, והאחר, אני יודע שגם הוא כך, אבל לא היה גלוי לפני. ועתה אני רואה."],[6,"תנינן דחיין גברא וכו':","למדנו, דוחים אדם מפני אדם, בכמה דרכים סתומים נדחים. רוח ההוא הראשון שנדחה מפני שני ההוא. איפה הלך. ומשיב, רוח ההוא יוצא והולך ומשוטט בעולם, ולא ידוע והולך אל הקבר של אדם ההוא, ומשם משוטט בעולם, ונראה בחלום לבני אדם, ורואים בחלום הצורה של אדם ההוא, ומודיע להם דברים לפי דרכו של רוח ההוא הראשון שנמשך ממנו, כמו שהוא בעולם ההוא, כן משוטט זה ומודיע בעולם הזה."],[7,"והכי אזיל ומשטטא וכו':","וכך הולך ומשוטט בעולם, ופוקד תמיד לקבר ההוא, עד שהרוחות פוקדים בקברים של הגופים, שאז בא גם הרוח עצמו של בעל הראשון אל הקבר לפקוד את גופו, ואז רוח הזה, שהוא רק חלק מן הרוח ההוא העקרי, מתחבר ברוח שלו העקרי, והוא מתלבש בו והולך לו. וכשהרוח נכנס למקומו, הוא מתפשט ממנו. ומקום יש לו באלו היכלות שבגן עדן, או לחוץ, לפי דרכיו של כל אחד ואחד, ושם מסתתר."]],[[0,"","בֹּא וּרְאֵה, כַּמָּה עֶלְיוֹנִים גְּבוּרוֹת הַמֶּלֶךְ הַקָּדוֹשׁ שֶׁהוּא עוֹשֶׂה, וּמִי יָכוֹל לְהַגִּיד אוֹתָם. כְּשֶׁהַבַּעַל הַשֵּׁנִי הַזֶּה בָּא וּמַכְנִיס רוּחַ לְאוֹתוֹ כְּלִי, הָרוּחַ הָרִאשׁוֹנָה מְקַטְרֶגֶת בָּרוּחַ הזּוֹ שֶׁנִּכְנְסָה (נלחמת), וְלֹא מִתְיַשְּׁבוֹת כְּאֶחָד."],[1,"","וּמִשּׁוּם כָּךְ הָאִשָּׁה לֹא מְיֻשֶּׁבֶת כָּרָאוּי עִם בַּעְלָהּ הַשֵּׁנִי, מִשּׁוּם שֶׁהָרוּחַ הָרִאשׁוֹנָה מְכַשְׁכֶּשֶׁת בָּהּ, וְאָז הִיא זוֹכֶרֶת אוֹתוֹ תָּמִיד וּבוֹכָה עָלָיו אוֹ נֶאֱנַחַת עָלָיו, שֶׁהֲרֵי רוּחוֹ מְכַשְׁכֶּשֶׁת בְּמֵעֶיהָ כְּנָחָשׁ, וּמְקַטְרֶגֶת עִם הָרוּחַ הָאַחֶרֶת שֶׁנִּכְנְסָה בָּהּ מֵהַבַּעַל הַשֵּׁנִי. עַד זְמַן רַב מְקַטְרְגִים זֶה בָּזֶה."],[2,"","וְאִם מַעֲבִירָה זוֹ שֶׁנִּכְנְסָה לְאוֹתָהּ (התעוררות) שֶׁהָיְתָה רִאשׁוֹנָה (לאחר כך) - זוֹ הָרִאשׁוֹנָה יוֹצֵאת וְהוֹלֶכֶת לָהּ. וְלִפְעָמִים שֶׁדּוֹחָה הָרִאשׁוֹנָה הַזּוֹ אֶת אוֹתָהּ הַשְּׁנִיָּה וְנַעֲשֵׂית לָהּ מְקַטְרֵג, עַד שֶׁמּוֹצִיאָה אוֹתָהּ מִן הָעוֹלָם. וְעַל זֶה שָׁנִינוּ, שֶׁמִּשְּׁנַיִם וָמַעְלָה לֹא יִשָּׂא אָדָם אֶת הָאִשָּׁה הַזּוֹ, שֶׁהֲרֵי מַלְאַךְ הַמָּוֶת הִתְחַזֵּק בָּהּ, וּבְנֵי הָעוֹלָם לֹא יוֹדְעִים שֶׁהֲרֵי הָרוּחַ, כֵּיוָן שֶׁנִתְחַזֵּק וְנִצַּח אֶת אוֹתָהּ הָרוּחַ הָאַחֶרֶת הַשְּׁנִיָּה, מִכָּאן וָהָלְאָה לֹא יִתְעָרֵב אִישׁ אַחֵר עִמָּהּ."],[3,"","חֲבֵרִים, הֲרֵי יָדַעְנוּ שֶׁבְּמָקוֹם זֶה יֵשׁ לָכֶם לְהַקְשׁוֹת וְלוֹמַר, אִם כָּךְ, הַשֵּׁנִי הַזֶּה לֹא מֵת בַּדִּין וְלֹא דָנוּ אוֹתוֹ מִלְמַעְלָה. בֹּא וּרְאֵה, הַכֹּל הוּא בְּדִין שֶׁיְּנַצַּח פְּלוֹנִי אֶת פְּלוֹנִי אוֹ שֶׁלֹּא יְקַטְרֵג עָלָיו פְּלוֹנִי לִפְלוֹנִי, וּמִי שֶׁנּוֹשֵׂא אַלְמָנָה כְּמוֹ שֶׁנִּכְנָס לַיָּם בְּרוּחוֹת עַזּוֹת בְּלִי חֲבָלִים, וְלֹא יוֹדֵעַ אִם יַעֲבֹר בְּשָׁלוֹם אוֹ יִטְבַּע לְתוֹךְ הַתְּהוֹמוֹת."],[4,"","וְאִם זֶה שֶׁהִכְנִיס אוֹתָהּ רוּחַ שְׁנִיָּה הִתְחַזֵּק וְנִצַּח אֶת אוֹתוֹ הָרִאשׁוֹן - אוֹתוֹ הָרִאשׁוֹן יוֹצֵא מִשָּׁם וְהוֹלֵךְ לוֹ. לְאֵיזֶה מָקוֹם הוֹלֵךְ לוֹ וּמַה נַּעֲשֶׂה אִתּוֹ? זָקֵן זָקֵן, מֶה עָשִׂיתָ? חָשַׁבְתָּ שֶׁתְּדַבֵּר מְעַט וְיָצָאתָ לָזֶה? הֲרֵי נִכְנַסְתָּ לְמָקוֹם שֶׁלֹּא נִכְנַס לְשָׁם אִישׁ אַחֵר, וּמִיּוֹם שֶׁדּוֹאֵג וַאֲחִיתֹפֶל עָשׂוּ קֻשְׁיוֹת אֵלּוּ, בְּאוֹתָם אַרְבַּע מֵאוֹת קֻשְׁיוֹת, שֶׁהָיוּ מַקְשִׁים עַל מִגְדָּל הַפּוֹרֵחַ בָּאֲוִיר וְלֹא הֵשִׁיב עֲלֵיהֶן אִישׁ, עַד שֶׁבָּא שְׁלֹמֹה הַמֶּלֶךְ וּבֵרַר אוֹתָם כָּל אֶחָד וְאֶחָד עַל תִּקּוּנוֹ. זָקֵן זָקֵן, הַסּוֹד הָעֶלְיוֹן שֶׁהָיָה טָמִיר בָּאתָ לְגַלּוֹת, מֶה עָשִׂיתָ?"],[5,"","זָקֵן זָקֵן, בַּתְּחִלָּה הָיָה לְךְ לִשְׁמֹר דַּרְכְּךְ, וְתִסְתַּכֵּל בְּרֹאשְׁךְ. אֲבָל עַכְשָׁו אֵינָהּ שָׁעָה לְהִתְחַבֵּא. זָקֵן, חֲזֹר בְּכֹחֲךְ. אוֹתָהּ רוּחַ שֶׁיָּצְאָה, לְאָן הוֹלֶכֶת? בָּכָה וְאָמַר, חֲבֵרִים, כָּל הַבְּכִיּוֹת הַלָּלוּ שֶׁאֲנִי בּוֹכֶה אֵינָם בִּגְלַלְכֶם, אֶלָּא פּוֹחֵד אֲנִי לְרִבּוֹן הָעוֹלָם שֶׁאֲנִי מְגַלֶּה דְרָכִים נִסְתָּרוֹת בְּלִי רְשׁוּת. אֲבָל גָּלוּי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא לִכְבוֹדִי עָשִׂיתִי וְלֹא לִכְבוֹד אָבִי, אֲבָל רְצוֹנִי הוּא לַעֲבוֹדָתוֹ, וַאֲנִי רוֹאֶה הַכָּבוֹד שֶׁל אֶחָד מִכֶּם בְּאוֹתוֹ עוֹלָם, וְאַחֵר יָדַעְתִּי שֶׁכָּךְ הוּא, אֲבָל לֹא גָלוּי לְפָנַי, וְעַכְשָׁו רָאִיתִי."],[6,"","שָׁנִינוּ, דּוֹחִים אִישׁ מִפְּנֵי אִישׁ, בְּכַמָּה דְרָכִים נִסְתָּרוֹת נִדְחִים. אוֹתָהּ רוּחַ רִאשׁוֹנָה שֶׁנִּדְחֲתָה מִלִּפְנֵי אוֹתָהּ הַשְּׁנִיָּה, לְאָן הוֹלֶכֶת? אוֹתָהּ רוּחַ יוֹצֵאת וְהוֹלֶכֶת וּמְשׁוֹטֶטֶת בָּעוֹלָם, וְלֹא יָדוּעַ, וְהוֹלֶכֶת לְקִבְרוֹ שֶׁל אוֹתוֹ הָאִישׁ, וּמִשָּׁם מְשׁוֹטֶטֶת בָּעוֹלָם וְנִרְאֵית בַּחֲלוֹם לִבְנֵי אָדָם, וְרוֹאִים בַּחֲלוֹם אֶת דְּמוּת אוֹתוֹ הָאִישׁ, וּמוֹדִיעַ לָהֶם דְּבָרִים לְפִי דַרְכָּהּ שֶׁל אוֹתָהּ רוּחַ רִאשׁוֹנָה שֶׁנִּמְשְׁכָה מִמֶּנּוּ, כְּמוֹ שֶׁהוּא בְּאוֹתוֹ עוֹלָם, כָּךְ מְשׁוֹטֶטֶת זוֹ וּמוֹדִיעָה בָּעוֹלָם הַזֶּה."],[7,"","וְכָךְ הוֹלֵךְ וּמְשׁוֹטֵט בָּעוֹלָם, וּפוֹקֶדֶת תָּמִיד אֶת אוֹתוֹ הַקֶּבֶר עַד הַזְּמַן שֶׁהָרוּחוֹת פּוֹקְדוֹת לְקִבְרוֹת הַגּוּפִים. אָז הָרוּחַ הַזּוֹ מִתְחַבֶּרֶת בְּאוֹתָהּ רוּחַ שֶׁלּוֹ, וּמִתְלַבֶּשֶׁת בָּהּ, וְהוֹלֵךְ לוֹ. כְּשֶׁנִּכְנָס לִמְקוֹמוֹ, מִתְפַּשֵּׁט מִמֶּנּוּ, וְיֵשׁ לוֹ מָקוֹם (באותן רוחותבגן עדן) בְּאוֹתָם הֵיכָלוֹת שֶׁל גַּן עֵדֶן אוֹ בַּחוּץ לְפִי דַרְכֵי כָּל אֶחָד וְאֶחָד, וְשָׁם נִשְׁמָר."]]],[["וְכַד רוּחִין פַּקְדָן לְהַאי עָלְמָא, דְּמֵתִין נִזְקָקִין לְגַבֵּי חַיִּין, לָא נִזְקָקִין אֶלָּא בְּהַהוּא מְשִׁיכוּ דְּרוּחָא, וּבֵיהּ אִתְלָבַשׁ רוּחָא אַחֲרָא. וְאִי תֵּימָא, אִי הָכִי, תּוֹעַלְתָּא אִיהוּ לְרוּחָא, וְהַאי אִתְּתָא תּוֹעַלְתָּא עַבְדַת לְכֹלָּא. לָאו הָכִי, דְּאִלְמָלֵא לָא אִתְנְסִיבַת לְגַבֵּי אַחֲרָא, וְהַאי רוּחָא קַדְמָאָה לָא מִתְדַּחְיָיא מִקָּמֵי הַאי גַּבְרָא אָחֳרָא, תּוֹעַלְתָּא אַחֲרָא הֲוָה לֵיהּ, בְּגַוְונָא אַחֲרָא, וְלָא יְהֵא לָאֵי בְּעָלְמָא, כְּמָה דְּהַוֵי, וְלָא יִזְדַּקֵּק לְגַבֵּי חַיִּין דְּהַאי עָלְמָא, כְּמָה דְּהַוֵי מְשַׁטְּטָא הָכָא וְהָכָא.","אִי הָכִי זִוּוּגָא תִּנְיָינָא דְּהַאי אִתְּתָא, לָא הֲוֵי מִלְּעֵילָּא. וְאַתְּ אַמָרְתְ דְּאִתְדַּחְיָיא גְּבַר מִקָּמֵי גְּבַר, וַאֲמֵינָא דְּהַאי בַּעְלָהּ תִּנְיָינָא, דְּנָסִיב לְאִתְּתָא דָּא, אִיהוּ בַּת זוּגֵיהּ מַמָּשׁ. וְהַהוּא קַדְמָאָה לָאו בַּר זוּגֵיהּ מַמָּשׁ הֲוָה. וְהַאי תִּנְיָינָא דִּילָיהּ הֲוָה, וְכַד מָטָא זִמְנֵיהּ, אִתְדַּחְיָיא דָּא מִקַּמֵּיהּ. וַדָאי הָכִי הוּא, דְּהָא לָא אִתְדַּחְיָיא הַהוּא רוּחַ קַדְמָאָה, דְּהֲוָה בְּהַאי אִתְּתָא. אֶלָּא בְּגִין דְּהַאי תִּנְיָינָא, דְּאִיהוּ בַּר זוּגָהּ. (דבר איהי בת זוגיה) (האי תניינא).","וְכָל אִינּוּן תִּנְיָינִין, דְאִתְדַּחְיָין מִקָּמֵי קַדְמָאִין. קַדְמָאִין הֲווֹ בְּנֵי זוּגַיְיהוּ, וְלָא הָנֵי. וּבְגִין כַּךְ, לָא אִית לוֹן קִיּוּמָא בַּהֲדַיְיהוּ, וְאִתְדַּחְיָיא רוּחַ תִּנְיָינָא מִקָּמֵי רוּחָא קַדְמָאָה. וּבְגִין כַּךְ, מַאן דְּנָסִיב אַרְמַלְתָא, קָרֵינָן עָלֵיהּ, (משלי ז׳:כ״ג) וְלא יָדַע כִּי בְנַפְשׁוֹ הוּא. (משלי א׳:י״ז) כִּי חִנָּם מְזוֹרָה הָרָשֶׁת וְגוֹ' וְלָא יְדִיעַ אִי הִיא בַּת זוּגֵיהּ מַמָּשׁ אִי לָאו.","אַרְמַלְתָא דְּלָא נְסִיבַת, אַף עַל גַּב דְּאָתֵי בַּר זוּגָהּ, וְאִיהִי לָא בָּעָאת לְאִתְנַסְּבָא, קוּדְשָׁא בְּרִיךְ הוּא לָא כַּיִיף לָהּ מִן דִּינָא, וְקוּדְשָׁא בְּרִיךְ הוּא אַזְמִין לְהַהוּא בַּר נָשׁ אִתְּתָא אַחֲרָא, וְלָא עָאלַת בְּדִינָא כְּהַאי (ס\"א ולית עליה בי דינא בהאי) בְּהַהוּא עָלְמָא, וְאַף עַל גַּב דְּלֵית לָהּ בַּר, דְּהָא אִתְּתָּא לָא אִתְפַּקְּדַת אַפִּרְיָה וּרְבִיָּה, כְּמָה דְּאוּקְמוּהָ.","אִתְּתָא דָּא דְּלָא אִתְנְסִיבַת זִמְנָא תִּנְיָינָא, הַהוּא רוּחַ דְּשָׁבַק בָּהּ בַּעְלָהּ מָה אִתְעָבִיד מִנֵּיהּ. יָתִיב תַּמָּן תְּרֵיסַר יַרְחֵי, וּבְכָל לֵילְיָא וְלֵילְיָא, נָפִיק וּפַקְדָּא לְנַפְשָׁא, וְאִתְהַדָּר לְאַתְרֵיהּ. לְבָתַר תְּרֵיסַר יַרְחֵי, דְּקָא אִסְתַּלָּק דִּינָא דְּהַהוּא גַּבְרָא, דְּהָא כָּל אִינּוּן תְּרֵיסַר יַרְחֵי, הָא רוּחָא אִתְכַּפְיָיא בַּעֲצִיבוּ כָּל יוֹמָא. לְבָתַר תְּרֵיסַר יַרְחֵי, נָפִיק מִתַּמָּן, וְאָזִיל וְקַיְּימָא לִתְרַע גַּן עֵדֶן, (אחורי הדף) וּפַקְדָּא לְהַאי עָלְמָא, לְגַבֵּי הַהוּא מָאנָא, דְּנָפִיק מִנֵּיהּ. וְכַד הַאי אִתְּתָא אִסְתַּלָּקַת מֵעָלְמָא, הַהוּא רוּחַ נָפִיק וְאִתְלָבַשׁ בְּהַהוּא רוּחַ דִּילָהּ, וְזָכָאת בֵּיהּ לְגַבֵּי בַּעְלָהּ, וְנָהֲרִין תַּרְוַויְיהוּ, כְּדְקָא יֵאוֹת, בְּחִבּוּרָא חֲדָא.","כֵּיוָן דְּאָתֵינָא לְהַאי אֲתָר, הַשְׁתָּא אִית לְגַלָּאָה אָרְחִין סְתִימִין, דְּמָארֵי עָלְמָא, לָא יַדְעִין בְּהוּ בְּנֵי נָשָׁא. וְכֻלְּהוּ אַזְלִין בְּאֹרַח קְשׁוֹט, כְּמָה דְאַתְּ אָמֵר (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי יְיָ' וְצַדִּיקִים יֵלְכוּ בָּם וּפוֹשְׁעִים יִכָּשְׁלוּ בָּם. וּבְנִי נָשָׁא לָא יַדְעִין, וְלָא מַשְׁגִּיחִין, כַּמָּה אִינּוּן עִלָּאִין, עוֹבָדִין דְּקוּדְשָׁא בְּרִיךְ הוּא, וְכַמָּה מְשַׁנְיָין אִינּוּן, וּבְנִי עָלְמָא לָא יַדְעִין, וְכֻלְּהוּ בְּאֹרַח קְשׁוֹט, דְּלָא סָטָאן לִימִינָא וְלִשְׂמָאלָא.","הָנֵי דְּמִתְגַּלְגְּלִין, דְּקָא אִתְתְּרָכוּ בְּתִרוּכִין מֵהַהוּא עָלְמָא, וְלֵית לוֹן בַּת זוּג. בַּת זוּג דְּקָא מִזְדַּוְּוגָן בְּהַאי עָלְמָא, מֵאָן אִינּוּן, אִינּוּן נָשִׁין, דְּקָא מִזְדַּוְּוגָן בַּהֲדַיְיהוּ בְּהַאי עָלְמָא. דְּהָא (תריך לה ולית ליה בת זוג כאינון גברין דלא תריכו וקא מזדווגן בהדי נשייהו) לְכֻלְּהוּ בְּנֵי נָשָׁא, אִית לוֹן בַּת זוּג, בַּר מֵהַאי.","חֲמוּ הַשְׁתָּא, כַּמָּה אִינּוּן רַבְרְבִין וְעִלָּאִין גְּבוּרָן דִּילֵיהּ. תָּנֵינָן, מַאן דִּמְתָּרֵךְ אִתְּתֵיהּ קַדְמָאָה, מַדְבְּחָא אָחִית עֲלוֹי דִּמְעִין. מַדְבְּחָא אֲמַאי. אֶלָּא, הָא אֲמֵינָא, דְּכָל נָשִׁין דְּעָלְמָא בְּדִיּוּקְנָא דְּהַאי מִזְבַּח קַיְימֵי, וְעַל דָּא (נשא קפ\"ד ע\"א) יָרְתָאן אִינּוּן שֶׁבַע בִּרְכָּאן, דְּכֻלְּהוּ מִכְּנְסֶת יִשְׂרָאֵל אִינּוּן. וְאִי אִיהוּ מְתָרַךְ לָהּ, אַהְדָּר אַבְנָא (נ\"א דמדבחא עלאה) לְגִרְעוֹנָא. מַאי טַעְמָא. בְּגִין דְּמִתְחַבְּרָן תִּרוּכִין בַּהֲדֵי הֲדָדֵי."],[[0,"וכד רוחין פקדן וכו':","וכשהרוחות פוקדים את עולם הזה, הנה המתים שמומצאים אצל החיים, אינם מומצאים אלא בהמשכת הרוח ההוא דהיינו הרוח שהבעל עוזב באשתו בביאה הראשונה, ובו מתלבש רוח האחר העקרי. ואם נאמר, א\"כ תועלת הוא לרוח ואשה זו עושה תועלת לכל. כי ע\"י הרוח שעזב בה בעלה מזדקק הרוח אל החיים, אינו כן. כי אם לא היתה נשאת לאחר, ורוח הראשון לא היה נדחה מפני איש האחר, דהיינו בעל השני, תועלת אחר היה לו באפן אחר, ולא היה מתיגע בעולם כמו שהוא מתיגע, ולא היה מזדקק אל החיים שבעולם הזה, כמו שהוא משוטט כאן וכאן."],[1,"אי הכי זווגא וכו':","שואל, אם כן, זווג השני של אשה ההיא לא היתה מלמעלה כי אתה אמרת, שנדחה איש מפני איש, ומשיב, ואני אומר, שבעל הזה השני שלקח אשה זו, זו היא בת זוגו ממש, והראשון ההוא אינו בן זוגה ממש, וע\"כ שני הזה שלו היא, וכשמגיע זמנו ולוקח אותה, נדחה הראשון מפניו. ודאי כן הוא, כי לא נדחה רוח ההוא הראשון שהיה באשה ההיא, אלא משום השני שהוא בן זוגה. הרי שזווג השני הוא מלמעלה."],[2,"וכל אינון תנינין וכו':","וכל אלו בעלים השניים הנדחים מפני בעלים הראשונים, הראשונים היו בני זווגם ולא אלו, ומשום זה אין להם קיום עמהן, ונדחה רוח השני מפני רוח הראשון. ומשום זה מי שלוקח אלמנה קוראים עליו, ולא ידע כי בנפשו הוא, כי חנם מזורה הרשת וגו'. שלא ידוע אם היא בת זוגיה ממש או לא."],[3,"ארמלתא דלא נסיבת וכו':","אלמנה שלא נשאת, אע\"פ שבא בת זוגה והיא אינה רוצה להנשא, הקב\"ה אינו מכריח אותה מן הדין, והקב\"ה מזמין לאיש ההוא אשה אחרת, והאלמנה אינה נכנסת לדין בזה. בעולם ההוא, ואע\"פ שאין לה בן, כי אשה אינה מצווה על פריה ורביה. כמו שהעמדנו."],[4,"אתתא דא דלא וכו':","אשה זו שלא נשאת פעם שנית, רוח ההוא שעזב בה בעלה בביאה הראשונה, מה נעשה ממנו. ומשיב, הוא יושב שם, באשה, י\"ב חדשים, ובכל לילה ולילה יוצא ופוקד את הנפש וחוזר למקומו. לאחר י\"ב חדשים, שנסתלק הדין של האיש ההוא, דהיינו בעלה, כי כל אלו י\"ב חדשים הרוח מושפל בעצבות כל היום, לאחר י\"ב חדשים יוצא משם, מן האשה, והולך ועומד בשער גן העדן, ופוקד בעולם הזה את הכלי ההוא דהיינו האשה, שיצא ממנו. וכשהאשה מסתלקת מן העולם, יוצא רוח ההוא ומתלבש ברוח שלה, של האשה, וזוכה בו אצל בעלה, ומאירים שניהם כראוי, בחבור אחד."],[5,"כיון דאתינא להאי וכו':","כיון שבאתי למקום הזה, יש לגלות עתה דרכים הסתומים של רבון העולם, שבני אדם אינם יודעים בהם. וכולם הולכים בדרך אמת, כש\"א, כי ישרים דרכי ה' וצדיקים ילכו בם ופושעים יכשלו בם. ובני אדם אינם יודעים ואינם משגיחים, כמה הם עליונים מעשי הקב\"ה וכמה משונים הם, ובני עולם אינם יודעים, וכולם בדרך אמת שאינם סרים לימין ולשמאל."],[6,"הני דמתגלגלין דקא וכו':","אלו המגולגלים שנגרשו בגרושין מעולם ההוא, ואין להם בת זוג, שואל, הבת זוג שמזדווגים עמהן בעולם הזה, מי הן אותן הנשים שמזדווגים עמהן בעולם הזה. שהרי לכל אדם יש בת זוג חוץ מזה המגולגל."],[7,"חמו השתא כמה וכו':","ראו עתה כמה הן גדולות וחשובות הגבורות שלו. למדנו, מי שמגרש אשתו הראשונה, המזבח מוריד עליו דמעות. שואל, המזבח למה. ומשיב, אלא אני אומר, שכל הנשים שבעולם עומדות בצורה של מזבח הזה, שהוא המלכות, שכל אשה יש לה שורש במלכות. ועל כן הן יורשות שבע ברכות, שכולן מכנסת ישראל הן, שהיא המלכות. ואם הוא מגרש אותה, את אשתו הראשונה, חוזרת האבן של מזבח העליון דהיינו השורש של האשה הזו שהוא במלכות למיעוט וגרעון מהו הטעם. הוא משום שמתחברות הגרושות יחד. שכמו שנגרשה מבעלה, כן נגרשה משורשה שבמלכות."]],[[0,"","וּכְשֶׁהָרוּחוֹת פּוֹקְדוֹת אֶת הָעוֹלָם הַזֶּה, שֶׁהַמֵּתִים נִזְקָקִים אֶל הַחַיִּים, הֵם לֹא נִזְקָקִים אֶלָּא רַק בְּאוֹתָהּ מְשִׁיכַת הָרוּחַ, וּבָהּ מִתְלַבֶּשֶׁת רוּחַ אַחֶרֶת. וְאִם תֹּאמַר, אִם כָּךְ, אָז זוֹ תּוֹעֶלֶת לָרוּחַ, וְהָאִשָּׁה הַזּוֹ עוֹשָׂה תוֹעֶלֶת לַכֹּל - לֹא כָּךְ, שֶׁאִלְמָלֵא לֹא נִשְׂאָה לְאַחֵר וְאוֹתָהּ רוּחַ רִאשׁוֹנָה לֹא הָיְתָה נִדְחֵית מִלִּפְנֵי הָאִישׁ הָאַחֵר הַזֶּה, תּוֹעֶלֶת אַחֶרֶת הָיְתָה לוֹ בְּגָוֶן אַחֵר, וְלֹא יִהְיֶה יָגֵעַ בָּעוֹלָם כְּמוֹ שֶׁהוּא, וְלֹא יִזְדַּקֵּק לַחַיִּים שֶׁל הָעוֹלָם הַזֶּה כְּמוֹ שֶׁהָיָה מְשׁוֹטֵט כָּאן וְכָאן."],[1,"","אִם כָּךְ, הַזִּוּוּג הַשֵּׁנִי שֶׁל הָאִשָּׁה הַזּוֹ לֹא הָיָה מִלְמַעְלָה, וְאַתָּה אוֹמֵר שֶׁנִּדְחֶה אִישׁ מִפְּנֵי אִישׁ? וְאָמַרְנוּ שֶׁהַבַּעַל הַשֵּׁנִי שֶׁנָּשָׂא אֶת הָאִשָּׁה הַזּוֹ הִיא בַּת זוּגוֹ מַמָּשׁ, וְאוֹתוֹ הָרִאשׁוֹן לֹא הָיָה מַמָּשׁ בֶּן זוּגָהּ, וְהַשֵּׁנִי הָיָה שֶׁלָּהּ, וּכְשֶׁהִגִּיעַ זְמַנּוֹ נִדְחֶה זֶה מִפָּנָיו - וַדַּאי זֶה כָּךְ, שֶׁהֲרֵי לֹא נִדְחֵית אוֹתָהּ רוּחַ רִאשׁוֹנָה שֶׁהָיְתָה בָּאִשָּׁה הַזּוֹ אֶלָּא בִּשְׁבִיל הַשֵּׁנִי הַזֶּה, שֶׁהוּא בֶּן זוּגָהּ. (שהבן היא בת זוגו) (זה השני)."],[2,"","וְכָל אוֹתָם הַשְּׁנִיִּים שֶׁנִּדְחִים מִלִּפְנֵי הָרִאשׁוֹנִים - הָרִאשׁוֹנִים הָיוּ בְּנֵי זוּגָם וְלֹא אֵלֶּה, וְלָכֵן אֵין לָהֶם קִיּוּם עִמָּם, וְנִדְחֵית הָרוּחַ הַשְּׁנִיָּה מִלִּפְנֵי הָרוּחַ הָרִאשׁוֹנָה. וְלָכֵן מִי שֶׁנּוֹשֵׂא אַלְמָנָה, קוֹרְאִים עָלָיו (משלי ז) וְלֹא יָדַע כִּי בְנַפְשׁוֹ הוּא. (שם א) כִּי חִנָּם מְזרָה הָרָשֶׁת וְגוֹ'. וְלֹא יָדוּעַ אִם הִיא בַּת זוּגוֹ מַמָּשׁ וְאִם לֹא."],[3,"","אַלְמָנָה שֶׁלֹּא נִשֵּׂאת, אַף עַל גַּב שֶׁבָּא בֶּן זוּגָהּ וְהִיא לֹא רוֹצָה לְהִנָּשֵׂא - הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא כוֹפֶה אוֹתָהּ מִן הַדִּין, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַזְמִין לְאוֹתוֹ הָאִישׁ אִשָּׁה אַחֶרֶת, וְלֹא נִכְנֶסֶת בְּדִין כָּזֶה (ואין עליה בית דין בזה) בְּאוֹתוֹ הָעוֹלָם, וְאַף עַל גַּב שֶׁאֵין לָהּ בֵּן, שֶׁהֲרֵי אִשָּׁה לֹא מְצֻוָּה עַל פְּרִיָּה וּרְבִיָּה, כְּמוֹ שֶׁבֵּאֲרוּהָ."],[4,"","הָאִשָּׁה הַזּוֹ שֶׁלֹּא נִשְּׂאָה פַּעַם שְׁנִיָּה, אוֹתָהּ רוּחַ שֶׁהִשְׁאִיר בָּהּ בַּעְלָהּ, מַה נַּעֲשֶׂה מִמֶּנָּה? יוֹשֶׁבֶת שָׁם שְׁנֵים עָשָׂר חֳדָשִׁים, וּבְכָל לַיְלָה וְלַיְלָה יוֹצֵא וּפוֹקֵד אֶת הַנֶּפֶשׁ, וְחוֹזֵר לִמְקוֹמוֹ אַחַר שְׁנֵים עָשָׂר חֳדָשִׁים, כְּשֶׁהִסְתַּלֵּק דִּינוֹ שֶׁל אוֹתוֹ הָאִישׁ. שֶׁהֲרֵי כָּל אוֹתָם שְׁנֵים עָשָׂר חֳדָשִׁים, זוֹ הָרוּחַ כְּפוּפָה בְּעַצְבוּת כָּל יוֹם. אַחַר שְׁנֵים עָשָׂר חֳדָשִׁים יוֹצֵאת מִשָּׁם וְהוֹלֶכֶת וְעוֹמֶדֶת בְּשַׁעַר גַּן עֵדֶן וּפוֹקֶדֶת אֶת הָעוֹלָם הַזֶּה אֶל אוֹתוֹ הַכְּלִי שֶׁיּוֹצֵאת מִמֶּנּוּ. וּכְשֶׁהָאִשָּׁה הַזּוֹ מִסְתַּלֶּקֶת מִן הָעוֹלָם, אוֹתָהּ רוּחַ יוֹצֵאת וּמִתְלַבֶּשֶׁת בְּאוֹתָהּ רוּחַ שֶׁלָּהּ, וְזוֹכָה בָּהּ לְבַעְלָהּ, וּשְׁנֵיהֶם מְאִירִים כָּרָאוּי בְּחִבּוּר אֶחָד."],[5,"","כֵּיוָן שֶׁבָּאנוּ לְמָקוֹם זֶה, עַכְשָׁו יֵשׁ לְגַלּוֹת דְּרָכִים נִסְתָּרוֹת שֶׁל רִבּוֹן הָעוֹלָם וְלֹא יוֹדְעִים בָּהֶם בְּנֵי אָדָם, וְכֻלָּם הוֹלְכִים בְּדֶרֶךְ אֱמֶת, כְּמוֹ שֶׁנֶּאֱמַר (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה' וְצַדִּקִים יֵלְכוּ בָם וּפֹשְׁעִים יִכָּשְׁלוּ בָם. וּבְנֵי אָדָם לֹא יוֹדְעִים וְלֹא מַשְׁגִּיחִים כַּמָּה הֵם עֶלְיוֹנִים מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא וְכַמָּה הֵם מְשֻׁנִּים, וּבְנֵי הָעוֹלָם לֹא יוֹדְעִים, וְכֻלָּם בְּדֶרֶךְ אֱמֶת, שֶׁלֹּא סוֹטִים יָמִינָה וּשְׂמֹאלָה."],[6,"","אֵלֶּה שֶׁמִּתְגַּלְגְּלִים, שֶׁגֹּרְשׁוּ בְגֵרוּשִׁין מֵאוֹתוֹ הָעוֹלָם וְאֵין לָהֶם בַּת זוּג, בַּת הַזּוּג שֶׁהֵם מִזְדַּוְּגִים בָּעוֹלָם הַזֶּה, מֵאֵיפֹה הֵן אוֹתָן נָשִׁים שֶׁמִּזְדַּוְּגוֹת עִמָּם בָּעוֹלָם הַזֶּה, שֶׁהֲרֵי (גרש אותה ואין לו בת זוג כאותם גברים שלא גרשו ומזדוגים עם נשותיהם) לְכָל בְּנֵי הָאָדם יֵשׁ בַּת זוּג, חוּץ מִזֶּה?"],[7,"","רְאוּ עַכְשָׁו כַּמָּה גְדוֹלִים וְעֶלְיוֹנִים גְּבוּרוֹתָיו. שָׁנִינוּ, מִי שֶׁמְּגָרֵשׁ אִשְׁתּוֹ הָרִאשׁוֹנָה, מִזְבֵּחַ מוֹרִיד עָלָיו דְּמָעוֹת. לָמָּה מִזְבֵּחַ? אֶלָּא הֲרֵי אָמַרְנוּ שֶׁכָּל נְשׁוֹת הָעוֹלָם עוֹמְדוֹת בִּדְמוּת הַמִּזְבֵּחַ הַזֶּה, וְעַל זֶה הֵן יוֹרְשׁוֹת שֶׁבַּע בְּרָכוֹת, שֶׁכֻּלָּן הֵן מִכְּנֶסֶת יִשְׂרָאֵל. וְאִם הוּא מְגָרֵשׁ אוֹתָהּ, חוֹזֶרֶת הָאֶבֶן (של המזבח העליון) לְגֵרָעוֹן. מָה הַטַּעַם? מִשּׁוּם שֶׁמִּתְחַבְּרִים הַגֵּרוּשִׁין זֶה עִם זֶה."]]],[["וְרָזָא דָּא דִּכְתִּיב, (דברים כ״ד:ב׳) וְכָתַב לָהּ סֵפֶר כְּרִיתוּת וְנָתַן בְּיָדָהּ וְגוֹ', וְיָצְאָה מִבֵּיתוֹ וְהָלְכָה וְהָיְתָה לְאִישׁ אַחֵר. מִמַּשְׁמַע דְּאָמַר, וְהָלְכָה וְהָיְתָה לְאִישׁ, לָא יְדַעְנָא (דההיא אזלה לגבי בעלה דתריך לה, (נ\"א דליתיה) ההוא דתריך לה') מַאי אַחֵר. אֶלָּא כְּמָה דְּאִתְּמַר, אַחֵר תְּנָן, וְאַחֵר כְּתִיב, וְאַחֵר קָרֵינָן לֵיהּ, דִּכְתִּיב, (איוב ח׳:י״ט) וּמֵעָפָר אַחֵר יִצְמָחוּ. וְתִרוּכִין מִתְחַבְּרָן כַּחֲדָא, תִּרוּכִין דְּהַהוּא עָלְמָא, וְתִרוּכִין דְּהַאי עָלְמָא. וּמַה דַּהֲוַת הַאי אִתְּתָא, בְּדִיּוּקְנָא עִלָּאָה, הָא אִשְׁתַּעְבְּדָא לְדִיּוּקְנָא תַּתָּאָה, קָרֵינָא לֵיהּ אַחֵר.","וְקָּרֵינָן לֵיהּ אַחֲרוֹן, אַחֲרוֹן מְנָלָן. דִּכְתִּיב, (איוב י״ט:כ״ה) וְאַחֲרוֹן (ק\"ה ע\"ב) עַל עָפָר יָקוּם. וְהָכָא כְּתִיב וּשְׂנֵאָהּ הָאִישׁ הָאַחֲרוֹן. אוֹ כִּי יָמוּת הַאִישׁ הָאַחֲרוֹן. אַחֲרוֹן, שֵׁנִי מִבָּעֵי לֵיהּ. וְאִי תֵּימָא, דְּלָא תִּזְדַּוֵּוג אֲפִילּוּ לַעֲשָׂרָה, דָּא בָּתַר דָּא. לָאו הָכִי. וְכִי לְבַעְלָהּ דָּא תִּזְדַּוֵּוג, וְלא לְאַחֲרָא, מַאי אַחֲרוֹן.","אֶלָּא דָּא אִיהוּ הַאי אַחֵר דְּקַאָמְרָן, וְאִיהוּ אַחֵר, וְאִיהוּ אַחֲרוֹן. הַשְׁתָּא אַבְנָא מִתְגַּלְגְּלָא בְּקוּסְפִתָא. אַחֵר אֲמַאי אִקְרֵי הָכִי דְּהָא כָּל בִּנְיָינָא נָפַל, וְאִתְהַדָּר לְעַפְרָא, אִיהוּ הֲוָה מַה דְּהֲוָה, וְלָא אַחֲרָא. אֲמַאי קָרֵינָן לֵיהּ אַחֵר. אוּף הָכִי אֲמַאי אִקְרֵי אַחֲרוֹן, וְכִי אַחֲרוֹן אִיהוּ, וְהָא אִי יִתְיְשַׁר יֵאוֹת, וְאִי לָא, יֶהְדַּר וְיִתְגַּלְגֵּל וְיִתְנְטַע כְּמִלְּקַדְּמִין, אֲמַאי אִקְרֵי אַחֲרוֹן.","אֲבָל תָּא חֲזִי, כְּתִיב (בראשית א׳:ל״א) וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד, מַאי טוֹב. תָּנֵינָן, דָּא מַלְאָךְ דְּטוֹב. מְאֹד, דָּא מַלְאַךְ הַמָּוֶת. וּלְכֹלָּא קוּדְשָׁא בְּרִיךְ הוּא אַזְמִין תִּקּוּנוֹי.","תָּא חֲזֵי, כְּתִיב (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן, נָהָר דָּא, לָא שָׁכִיךְ לְעָלְמִין, מִלְּאַפָּשָׁא וּלְמִסְגֵּי וּלְמֶעְבַּד פֵּירִין. וְאֵל אַחֵר אִסְתְּרַס, וְלֵית לֵיהּ תִּיאוּבְתָּא לְעָלְמִין, וְלָא אָפִּישׁ, וְלָא עָבִיד פֵּירִין, דְּאִלְמָלֵי עָבִיד פֵּירִין, יְטַשְׁטֵשׁ לְכָל עָלְמָא.","וּבְּגִין כָּךְ, בַּר נָשׁ דְּגָרִים לְהַהוּא סְטַר דְּיִפּוּשׁ בְּעָלְמָא, אִקְרֵי רַע, וְלָא חָמֵי אַפֵּי שְׁכִינְתָּא לְעָלְמִין, דִּכְתִּיב, (תהילים ה׳:ה׳) לֹא יְגוּרְךָ רָע. הַאי בַּר נָשׁ, דְּמִתְגַּלְגְּלָא בְּגִלְגּוּלָא, אִי אִיהוּ עָבַר וְאִתְדַּבָּק בְּהַהוּא אֵל אַחֵר, דְּלָא עָבִיד פֵּירִין, וְלָא אָפִּישׁ בְּעָלְמָא, בְּגִין כַּךְ אִקְרֵי אַחֵר, וּשְׁמָא גָּרִים לֵיהּ, אִיהוּ הוּא, וְאַחַר אִקְרֵי, אַחֵר וַדַּאי.","אַחֲרוֹן: מִקַּדְמָאָה וְאֵילָךְ, אַחֲרוֹן קָרֵינָן לֵיהּ, וְאַחֲרוֹן אִקְרֵי. תִּנְיָינָא אִיהוּ, וּמִיָּד אִקְרֵי אַחֲרוֹן, וְהָכִי קָרֵי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא אַחֲרוֹן, בְּגִין דְּיִתְתָּקַּן לְמֶהוֵי אַחֲרוֹן, וְלָא יְתוּב כְּמִלְּקַדְּמִין. תְּלִיתָאָה אוּף הָכִי. וְכֵן בְּכָל זִמְנִין, מִקַּדְמָאָה וְאֵילָךְ. הָכִי אִקְרֵי אַחֲרוֹן, וְהָכִי אִצְטְרִיךְ לְמִקְרֵי אַחֲרוֹן, דְּאִלְמָלֵא אִתְקְרֵי מִיַד תִּנְיָינָא, הָא פְּתִיחוּ דְּפוּמָא לְאָהַדְּרָא כְּמִלְקַדְּמִין, וְהַהוּא בִּנְיָינָא אִסְתְּתַר.","מְנָלָן. מִבַּיִת שֵׁנִי דְּאִקְרֵי אַחֲרוֹן, דִּכְתִּיב, (חגי ב׳:ט׳) גָּדוֹל יִהְיֶה כְּבוֹד הַבַּיִת הַזֶּה הָאַחֲרוֹן מִן הָרִאשׁוֹן. דְּהָא מִקַּדְמָאָה וְאֵילָךְ, אַחֲרוֹן אִקְרֵי, דְּהָא לָא יְהֵא פְּתִיחוּ דְּפוּמָא, דְּהַהוּא בִּנְיָינָא יִנְפּוֹל, וְיִתְהַדָּר כְּמִלְקַדְּמִין.","אוּף הָכִי דָּא, אַחֲרוֹן קָרֵינָן לֵיהּ. וּבְגִין כַּךְ כְּתִיב, לא יוּכַל בַּעְלָהּ הָרִאשׁוֹן אֲשֶׁר שִׁלְּחָהּ לָשׁוּב לְקַחְתָּה. לא יוּכַל, לֹא יִקָּחֶנָּה מִבָּעֵי לֵיהּ, מַאי לא יוּכַל. אֶלָּא כֵּיוָן דְּהַאי אִתְּתָא אִתְדַּבְּקַת בְּאַחֵר, וְנַחְתַּת לְאִשְׁתַּעְבְּדָא בְּדַרְגָּא תַּתָּאָה, לָא בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהוּ יְתוּב מִדַּרְגָּא דִּילֵיהּ, לְמֵיהָב אִיבָא, וּלְאִתְדַּבְּקָא בְּהַהוּא דַּרְגָּא דְּלָאו דִּילֵיהּ.","וְתָּא חֲזֵי, אִי הַאי אִתְּתָא לָא אִתְנְסִיבַת, אֲפִילּוּ תִּזְנֶה בְּכָל גּוּבְרִין דְּעָלְמָא, אִי בָּעֵי בַּעְלָהּ יְתוּב לְגַבָּהּ, אֲבָל אִי אִתְדַּבְּקָא בְּנִשּׂוּאִין לְאַחֵר, (נ\"א ואחר) דָּא (האי) לא יוּכַל לָשׁוּב לְדַרְגָּא קַדְמָאָה, דְּהֲוָה בְּקַדְמִיתָא לְגַבָּהּ. לא יוּכַל וַדַּאי לְאָתָבָא לְהַהוּא דַּרְגָּא לְעָלְמִין.","אַחֲרֵי אֲשֶׁר הֻטַּמָּאָה. תָּנִינָן, דְּהֻטַּמָּאָה בְּלִבֵּיהּ. אִי הָכִי, אֲפִילּוּ אִי תִּתְרַחֵק וְתִזְנֶה בְּלָא נִשּׂוּאִין. אֶלָּא, כֵּיוָן דְּאִתְדַּבְּקַת לְאַחֵר, הָא קַבִּילַת עָלָה חוּלָקָא דְּהַהוּא סִטְרָא, וְבַּעְלָהּ קַדְמָאָה דְּאִיהוּ מִסִּטְרָא אַחֲרָא טָבָא דְּטוֹב, לָא יְהֵא לֵיהּ בָּהּ חוּלָקָא לְעָלְמִין, וְלָא יַפִּישׁ כְּלָל לְהַהוּא אֲתָר. הָא אִם שִׁלְּחָהּ הָאִישׁ הָאַחֲרוֹן, אוֹ כִּי יָמוּת הָאִישׁ הָאַחֲרוֹן, לְקַדְמָאָה אֲסוּרָא, אֲבָל לִשְׁאַר בְּנִי נָשָׁא, תִּשְׁתְּרֵי. דִּילְמָא תִּשְׁכַּח אַתְרָא כְּמִלְקַדְּמִין, וְאַחֲרוֹן יָקוּם דְּיִזְדַּוִּוג בַּהֲדָהּ."],[[0,"ורזא דא דכתיב וכו':","וזה סוד שכתוב, וכתב לה ספר כריתות ונתן בידה וגו' ויצאה והלכה והיתה לאיש אחר. שואל, כיון שאמר והלכה והיתה לאיש, איני יודע, שאינו אותו שגרש אותה, ולמה כתוב, אחר. ומשיב, אלא כמו שלמדנו, אחר למדנו, ואחר כתוב, ואחר קוראים אותו. שכתוב ומעפר \u0003אחר\u0004 יצמחו הרי שהמגולגל נקרא אחר, והגרושות מתחברות יחד, גרוש שבעולם ההוא, דהיינו האיש המגולגל, שאין לו בת זוג, הנגרש מעולם ההוא לעולם הזה, שלקח הגרושה, ואשה הגרושה שבעולם הזה, מבעלה. ומה שאשה הזו היתה בצורה עליונה, במלכות, נשתעבדה עתה לצורה תחתונה, דהיינו להמגולגל, שאין לו בת זוג, שלקחה אותה לאשה, וקוראים אותו \u0003אחר.\u0004 כמ\"ש להלן, משום שנתדבק באל אחר, שעל כן חזר ונתגלגל לעולם הזה."],[1,"וקרינן ליה אחרון וכו':","וקוראים אותו אחרון. מאין לנו שקוראים אותו אחרון, שכתוב ואחרון על עפר יקום. הרי שהמגולגל נקרא אחרון. וכאן כתוב, ושנאה האיש האחרון, או כי ימות האיש האחרון. שואל, אומר אחרון, שני היה צריך לומר. ואם תאמר, שהכתוב בא לאסור שלא תזדווג לעשרה בזה אחר זה. אינו כן, וכי לבעל הזה תזדווג ולא לאחר ולמה תהיה אסורה לאחר. וא\"כ למה נקרא אחרון."],[2,"אלא דא הוא וכו':","ומשיב, אלא זה הוא \u0003אחר\u0004 הזה שאמרנו, והוא אחר והוא אחרון. כי עתה האבן מתגלגלת בכף הקלע. כלומר, שביחס גוף הראשון שמת, נקרא המגולגל בכף הקלע, שחזר שנית לעולם, בשם, \u0003אחר\u0004 ואחרון. ומשום שאין לו בת זוג לקח הגרושה, וע\"כ מכנהו הכתוב, אחר, ואחרון. \u0003אחר אמאי אקרי וכו':\u0004 שואל, למה נקרא אחר ביחס הגוף הראשון שמת הרי כל הבנין נפל, דהיינו הגוף הראשון, וחזר לעפר, והוא כמו שלא היה, והמגולגל הוא היה מה שהיה גוף הראשון, ולא אחר. ולמה קוראים אותו אחר. וכן למה נקרא אחרון, וכי אחרון הוא, כי אם מישר דרכיו ומתתקן, יפה, שהוא אחרון ואינו מתגלגל עוד, אבל אם לא, הרי הוא חוזר ומתגלגל ויהיה נטוע כבתחילה, למה נקרא אחרון."],[3,"אבל תא חזי וכו':","אבל בוא וראה, כתוב, וירא אלקים את כל אשר עשה והנה טוב מאד. מהו \u0003טוב.\u0004 למדנו, שזהו מלאך הטוב. \u0003מאד,\u0004 זהו מלאך המות. ולכל הקב\"ה מזמין את תקוניו, עד שאפילו מלאך המות חוזר להיות טוב מאד."],[4,"ת\"ח כתיב ונהר וכו':","בוא וראה, כתוב, ונהר יוצא מעדן להשקות את הגן, שהוא ז\"א המשקה את המלכות שנקראת גן. נהר זה אינו שוקט לעולם מלהפרות ולהרבות ולעשות פירות, ואל אחר נסתרס ואין לו תאוה לעולם, ואינו מפרה ואינו עושה פירות, כי אם היה עושה פירות, היה מעכר את כל העולם."],[5,"ובג\"כ בר נש וכו':","ומשום זה, האדם שגרם לצד ההוא שיתרבה בעולם, נקרא \u0003רע,\u0004 ואינו רואה פני השכינה לעולם, שכתוב, לא יגורך \u0003רע.\u0004 אדם ההוא המתגלגל בגלגול, אם הוא עבר ונתדבק באל \u0003אחר\u0004 ההוא, שאינו עושה פירות ואינו מרבה בעולם, משום זה נקרא \u0003אחר.\u0004 והשם של הס\"א, גרם לו, שאע\"פ שהוא המת הוא המתגלגל נקרא אחר, כמו הס\"א, אחר ודאי."],[6,"אחרון, מקדמאה ואילך וכו':","אחרון נקרא, כי מראשון והלאה אחרון קוראים אותו, ונקרא בתורה, אחרון, שני הוא, ומיד נקרא אחרון, וכך קורא אותו הקב\"ה אחרון, כדי שיתתקן בגלגול זה להיות אחרון, ולא ישוב להתגלגל יותר. השלישי גם כן נקרא אחרון, וכן בכל פעם שמתגלגל מן הראשון והלאה נקרא כן אחרון. וכך צריכים לקראו אחרון, כי אם היה נקרא מיד, שני, ניתן פתחון פה, שיחזור עוד ויתגלגל כבתחילה, ובנין ההוא של עתה יסתר."],[7,"מנלן, מבית שני וכו':","מאין לנו זה, מבית שני, שנקרא אחרון, שכתוב, גדול יהיה כבוד הבית הזה האחרון מן הראשון. כי מן הראשון והלאה נקרא אחרון, כדי שלא יהיה פתחון פה, שבנין ההוא יפול, ויחזרו לבנותו כבתחילה."],[8,"אוף הכי דא וכו':","אף כן זה, המתגלגל, קוראים אותו אחרון. כמו לבית שני. ומשום זה כתוב, לא יוכל בעלה הראשון אשר שלחה לשוב לקחתה. שואל, מה לא יוכל, לא יקחנה היה צריך לומר. ומשיב, כיון שאשה הזו נתדבקה ב \u0003אחר,\u0004 וירדה להשתעבד במדרגה תחתונה, של הס\"א, אין הקב\"ה רוצה, שהוא, הראשון, ירד ממדרגתו לתת פירות ולהתדבק במדרגה ההיא שאינה שלו."],[9,"ות\"ח אי האי וכו':","ובוא וראה, אם אשה ההיא לא נשאת, אפילו אם היא תזנה בכל האנשים שבעולם, אם בעלה רוצה יוכל לשוב אליה. אבל אם נתדבקה בנשואין לאחר, זו לא תוכל לשוב למדרגה הקודמת שהיתה לה מתחילה. וע\"כ כתוב לא יוכל, לא יוכל ודאי לשוב למדרגה ההיא לעולם."],[10,"אחרי אשר הטמאה:","למדנו, שהטמאה בלבו. שואל, אם כן אפילו אם תתרחק ותזנה בלא נשואין תהיה אסורה. ומשיב, כיון שנתדבקה ב \u0003אחר,\u0004 הרי קבלה עליה החלק של צד ההוא הרע. ובעלה הראשון שהוא מצד האחר הטוב, הרי הטוב לא יהיה לו בה חלק לעולם, ולא ירבה כלל למקום ההוא. וע\"כ, אם שלחה איש האחרון או כי ימות האיש האחרון, היא אסורה לראשון. אבל לשאר בני אדם מותרת, אולי תשכח מקום כבתחילה, ואחרון יקום שיזדווג עמה."]],[[0,"","וְסוֹד זֶה, שֶׁכָּתוּב (דברים כד) וְכָתַב לָהּ סֵפֶר כְּרִיתֻת וְנָתַן בְּיָדָהּ וְגוֹ', וְיָצְאָה מִבֵּיתוֹ וְהָלְכָה וְהָיְתָה לְאִישׁ אַחֵר. מִמַּשְׁמָע שֶׁאָמַר וְהָלְכָה וְהָיְתָה לְאִישׁ, לֹא יָדַעְנוּ (שאותה שהולכת אצל בעלה שגרש אותה) (שזה אינו) (אותו שגרש אותה) ? מַה זֶּה אַחֵר? אֶלָּא כְּמוֹ שֶׁנֶּאֱמַר, שָׁנִינוּ אַחֵר, וְאַחֵר כָּתוּב, וְאַחֵר קוֹרְאִים אוֹתוֹ, שֶׁכָּתוּב (איוב ח) וּמֵעָפָר אַחֵר יִצְמָחוּ. וְהַגֵּרוּשִׁים מִתְחַבְּרִים כְּאֶחָד, גֵּרוּשִׁים שֶׁל אוֹתוֹ הָעוֹלָם וְגֵרוּשִׁים שֶׁל הָעוֹלָם הַזֶּה. וּמַה שֶּׁהָאִשָּׁה הַזּוֹ הָיְתָה בִּדְיוֹקָן עֶלְיוֹן, הֲרֵי הִשְׁתַּעְבְּדָה לִדִיוֹקָן תַּחְתּוֹן, קוֹרְאִים לוֹ אַחֵר."],[1,"","וְקֹוֹרְאִים לוֹ אַחֲרוֹן. מִנַּיִן לָנוּ אַחֲרוֹן. ? שֶׁכָּתוּב (שםיט) וְאַחֲרוֹן עַל עָפָר יָקוּם. וְכָאן כָּתוּב וּשְׂנֵאָהּ הָאִישׁ הָאַחֲרוֹן. אוֹ, כִּי יָמוּת הָאִישׁ הָאַחֲרוֹן. אַחֲרוֹן? שֵׁנִי הָיָה צָרִיךְ לִהְיוֹת! וְאִם תֹּאמַר שֶׁלֹּא תִזְדַּוֵּג אֲפִלּוּ לַעֲשָׂרָה זֶה אַחַר זֶה - לֹא כָּךְ. וְכִי לַבַּעַל הַזֶּה תִּזְדַּוֵּג וְלֹא לְאַחֵר. מַה זֶּה אַחֲרוֹן?"],[2,"","אֶלָּא זֶהוּ הָאַחֵר הַזֶּה שֶׁאָמַרְנוּ, וְהוּא אַחֵר, וְהוּא אַחֲרוֹן. עַכְשָׁו הָאֶבֶן מִתְגַּלְגֶּלֶת בְּכַף הַקֶּלַע. לָמָּה אַחֵר נִקְרָא כָּךְ? שֶׁהֲרֵי כָּל הַבִּנְיָן נָפַל וְחָזַר לְעָפָר, הוּא הָיָה מַה שֶּׁהָיָה וְלֹא אַחֵר. לָמָּה קוֹרְאִים לוֹ אַחֵר? אַף כָּךְ לָמָּה נִקְרָא אַחֲרוֹן, וְכִי הוּא אַחֲרוֹן? וַהֲרֵי אִם יִתְיַשֵּׁר - יָפֶה, וְאִם לֹא - יַחֲזֹר וְיִתְגַּלְגֵּל וְיִנָּטַע כְּמִקֹּדֶם. לָמָּה נִקְרָא אַחֲרוֹן?"],[3,"","אֲבָל בּא וּרְאֵה, כָּתוּב (בראשית א) וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד. מַה זֶּה טוֹב? שָׁנִינוּ, זֶה מַלְאַךְ הַטּוֹב. מְאֹד - זֶה מַלְאַךְ הַמָּוֶת. וְלַכֹּל הַקָּדוֹשׁ בָּרוּךְ הוּא הִזְמִין תִּקּוּנוֹ."],[4,"","בֹּא וּרְאֵה, כָּתוּב (שם ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. נָהָר זֶה לֹא שׁוֹכֵךְ לְעוֹלָמִים מִלִּרְבּוֹת וּמִלִּגְדֹּל וְלַעֲשׂוֹת פֵּרוֹת. וְאֵל אַחֵר הִסְתָּרֵס, וְאֵין לוֹ תְּשׁוּקָה לְעוֹלָמִים, וְלֹא מַרְבֶּה וְלֹא עוֹשֶׂה פֵרוֹת. שֶׁאִלְמָלֵא עָשָׂה פֵרוֹת, יְבַלְבֵּל אֶת כָּל הָעוֹלָם."],[5,"","וּמִשּׁוּם כָּךְ אָדָם שֶׁגּוֹרֵם לְאוֹתוֹ הַצַּד לִגְדֹּל בָּעוֹלָם נִקְרָא רַע, וְלֹא רוֹאֶה פְּנֵי שְׁכִינָה לְעוֹלָמִים, שֶׁכָּתוּב (תהלים ה) לֹא יְגֻרְךְ רָע. הָאִישׁ הַזֶּה שֶׁמִּתְגַּלְגֵּל בְּגִלְגּוּל, אִם עָבַר וְנִדְבַּק בְּאוֹתוֹ אֵל אַחֵר שֶׁלֹּא עוֹשֶׂה פֵרוֹת וְלֹא מִתְרַבֶּה בָּעוֹלָם, מִשּׁוּם כָּךְ נִקְרָא אַחֵר, וְהַשֵּׁם גּוֹרֵם לוֹ. הוּא הוּא, וְאַחֵר נִקְרָא, אַחֵר וַדַּאי."],[6,"","אַחֲרוֹן - מֵרִאשׁוֹן וְאֵילָךְ אַחֲרוֹן קוֹרְאִים לוֹ, וְאַחֲרוֹן נִקְרָא. שֵׁנִי הוּא, וּמִיָּד נִקְרָא אַחֲרוֹן, וְכָךְ קוֹרֵא לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא אַחֲרוֹן, מִשּׁוּם שֶׁנִּתְקָן לִהְיוֹת אַחֲרוֹן וְלֹא יָשׁוּב כְּמִקֹּדֶם. הַשְּׁלִישִׁי אַף כָּךְ. וְכֵן בְּכָל הַפְּעָמִים מֵהָרִאשׁוֹן וְאֵילָךְ, כָּךְ נִקְרָא אַחֲרוֹן, וְכֵן צָרִיךְ לִקְרֹא אַחֲרוֹן, שֶׁאִלְמָלֵא נִקְרָא מִיָּד שֵׁנִי, הֲרֵי יֵשׁ פִּתְחוֹן פֶּה לַחֲזֹר כְּמִקֹּדֶם, וְאוֹתוֹ בִּנְיָן נֶהֱרַס."],[7,"","מִנַּיִן לָנוּ? מִבַּיִת שֵׁנִי שֶׁנִּקְרָא אַחֲרוֹן, שֶׁכָּתוּב (חגי ב) גָּדוֹל יִהְיֶה כְּבוֹד הַבַּיִת הַזֶּה הָאַחֲרוֹן מִן הָרִאשׁוֹן. שֶׁהֲרֵי מֵרִאשׁוֹן וְאֵילָךְ נִקְרָא אַחֲרוֹן, שֶׁהֲרֵי לֹא יִהְיֶה פִּתְחוֹן פֶּה שֶׁאוֹתוֹ בִּנְיָן יִפֹּל וְיַחֲזֹר כְּמִקֹּדֶם."],[8,"","אַף זֶה כָּךְ, אַחֲרוֹן קוֹרְאִים לוֹ. וְלָכֵן כָּתוּב לֹא יוּכַל בַּעְלָהּ הָרִאשׁוֹן אֲשֶׁר שִׁלְּחָהּ לָשׁוּב לְקַחְתָּהּ. לֹא יוּכַל? לֹא יִקָּחֶנָּה הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה לֹא יוּכַל? אֶלָּא כֵּיוָן שֶׁהָאִשָּׁה הַזּוֹ נִדְבְּקָה בְּאַחֵר וְיָרְדָה לְהִשְׁתַּעְבֵּד בְּדַרְגָּה תַחְתּוֹנָה, לֹא רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיָּשׁוּב מִדַּרְגָּתוֹ לָתֵת פְּרִי וּלְהִדָּבֵק בְּאוֹתָהּ דַּרְגָּה שֶׁאֵינָהּ שֶׁלּוֹ."],[9,"","וּבֹא רְאֵה, אִם הָאִשָּׁה הַזּוֹ לֹא נִשֵּׂאת, אֲפִלּוּ תִּזְנֶה עִם כָּל הָאֲנָשִׁים שֶׁבָּעוֹלָם - אִם רוֹצֶה בַעְלָהּ, יָשׁוּב אֵלֶיהָ. אֲבָל אִם נִדְבְּקָה בְּנִשּׂוּאִין לְאַחֵר, (ואחר) זֶה (זה) לֹא יוּכַל לָשׁוּב לְדַרְגָּתוֹ הָרִאשׁוֹנָה שֶׁהָיָה בַּתְּחִלָּה אֵלֶיהָ. לֹא יוּכַל וַדַּאי לְהָשִׁיב אוֹתָהּ הַדַּרְגָּה לְעוֹלָמִים."],[10,"","אַחֲרֵי אֲשֶׁר הֻטַּמָּאָה. שָׁנִינוּ, שֶׁהֻטַּמָּאָה בְּלִבּוֹ. אִם כָּךְ, אֲפִלּוּ אִם תִּתְרַחֵק וְתִזְנֶה בְּלִי נִשּׂוּאִין? אֶלָּא כֵּיוָן שֶׁנִּדְבְּקָה לְאַחֵר, הֲרֵי קִבְּלָה עָלֶיהָ אֶת הַחֵלֶק שֶׁל אוֹתוֹ הַצַּד, וּבַעְלָהּ הָרִאשׁוֹן שֶׁהוּא מִצַּד אַחֵר טוֹב שֶׁל טוֹב, לֹא יִהְיֶה לוֹ בָּהּ חֵלֶק לְעוֹלָמִים, וְלֹא יַרְבֶּה כְּלָל אֶת אוֹתוֹ מָקוֹם. הֲרֵי אִם שִׁלְּחָהּ הָאִישׁ הָאַחֲרוֹן אוֹ כִי יָמוּת הָאִישׁ הָאַחֲרוֹן - לָרִאשׁוֹן אֲסוּרָה, אֲבָל לִשְׁאָר בְּנֵי אָדָם מֻתֶּרֶת. אוּלַי תִּמְצָא מָקוֹם כְּמוֹ מִקֹּדֶם, וְאַחֲרוֹן יָקוּם וְיִזְדַּוֵּג עִמָּהּ."]]],[["מַאן דְּאִית לֵיהּ בְּנִין מְאִתְּתֵיהּ קַדְמִיתָא, וְאָעִיל הַאי לְגוֹ בֵּיתֵיהּ, הַהוּא יוֹמָא אִתְדַּבָּק בְּחַרְבָּא קַשְׁיָא דְּמִתְהַפְּכָא, בְּגִין תְּרֵין סִטְרִין. חַד, דְּהָא תְּרֵין דָּחַת לוֹן לְבַר, וְהַשְׁתָּא אִיהוּ תְּלִיתָאָה. וְתוּ, מָאנָא דְאִשְׁתָּעֲבֶּד (נ\"א דאשתתף) בֵּיהּ אַחֵר, הֵיךְ יֵיתֵי אִיהוּ לְמֵיהַב בֵּיהּ רוּחָא דִּילֵיהּ, וְיִשְׁתַּתַּף בַּהֲדָהּ, וְיִתְדַּבַּק בָּהּ. לָאו דְּאִיהִי אֲסוּרָא, אֲבָל וַדַּאי שִׁתּוּפָא בִּישָׁא אִיהוּ לְגַרְמֵיהּ. (כדאמרן)","רַבִּי לְוִיטַס אִישׁ כְּפַר אוֹנוֹ, הֲוָה חַיִיךְ וּמִתְלוֹצֵץ עַל אִתְּתָא דָּא, כַּד חָמֵי מַאן דְּאִזְדַּוָּג בַּהֲדָהּ, וַהֲוָה אָמַר, (משלי ל״א:כ״ה) וַתִּשְׂחַק לְיוֹם אַחֲרוֹן כְּתִיב, מַאן דְּאִתְדַּבְּקָת בֵּיהּ בְּאִישׁ אַחֲרוֹן, חִיּוּכָא אִיהִי לְבָתַר.","הַשְׁתָּא, אִית לְאָהַדְרָא וּלְעַיְינָא, עַל אֲתָר (נ\"א אילנא) חַד רַב וְעִלָּאָה, דְּהֲוָה בְּעָלְמָא, וְגִזְעָא וְשָׁרְשָׁא דִּקְשׁוֹט, וְאִיהוּ עוֹבֵד אֲבִי יִשַׁי אֲבִי דָּוִד. דְּהָא אִתְּמַר דְּאַחֲרוֹן הֲוָה, הֵיךְ נָפַק שָׁרְשָׁא דִּקְשׁוֹט, מִגּוֹ אֲתָר דָּא.","אֶלָּא, עוֹבֵד אִתְתָּקַּן בְּתִקּוּנָא עִלָּאָה, וְאַהְדָּר שָׁרְשָׁא דְּאִילָנָא דְּקָא אִתְהַפַּךְ, עַל תְקּוּנֵיהּ, וְאִסְתְּלִיק בֵּיהּ, וְאִתְתָּקַּן כְּדְקָא יֵאוֹת, וְעַל דָּא אִקְרֵי עוֹבֵד. מַה דְּלָא זָכוּ הָכִי, שְׁאַר בְּנֵי עָלְמָא.","אָתָא אִיהוּ, פָּלַח וְאַעְדָּר עִקָרָא וְשָׁרְשָׁא דְּאִילָנָא, וְנָפַק מֵאַנְפִין מְרִירָן, וְאַהְדָּר (נ\"א ואעדר) וְאִתָּקַן בְּנוֹפָא דְּאִילָנָא אַחֲרָא עִלָּאָה, אָתָא יִשַׁי בְּרֵיהּ, וְאַחֲסִין לֵיהּ, וְתָקִין לֵיהּ, וְאִתְאֲחָד בְּעַנְפּוֹי (קע\"ה ע\"ב) דְּאִילָנָא אַחֲרָא עִלָּאָה, וְחִבֵר אִילָנָא בְּאִילָנָא, וְאִסְתְּבָּכוּ דָּא בְּדָא. כֵּיוָן דְּאָתָא (ק\"ע ע\"א) דָּוִד, אַשְׁכַּח אִילָנִין מִסְתַבְכָן וּמִתְאַחֲדָן דָּא בְּדָא, כְּדֵין יָרִית שֻלְטָנוּ בְּאַרְעָא, וְעוֹבֵד גָּרִים דָּא.","בָּכָה הַהוּא סָבָא וְאָמַר, אִי סָבָא סָבָא, וְלָא אֲמֵינָא לָךְ, דְּעָלַת בְּיַמָּא רַבָּא, הַשְׁתָּא אַנְתְּ הוּא גּוֹ תְּהוֹמֵי רַבְרְבִין, אִתְתָּקַּן לְסַלְּקָא. סָבָא סָבָא, אַנְתְּ גָּרַמְתְּ דָּא, דְּאִלְמָלֵא הֲוֵית שָׁתִיק בְּקַדְמִיתָא, הֲוָה יֵאוֹת לָךְ, אֲבָל הַשְׁתָּא לָא יָכִילַת וְלֵית מַאן דְּאָחִיד בִּידָךְ, אֶלָּא אַנְתְּ בִּלְחוֹדָךְ. קוּם סָבָא וְאִסְתַּלָּק בִּסְלִיקוּ.","עוֹבֵד דָּא, אִתְתָּקַּן וְנְפַק מִגּוֹ חֲקַל בִּישָׁא, דְּגוּבִין בִּישִׁין. אָתָא יִשַׁי בְּרֵיהּ, וְאַתְקִין וְאַעְדָּר אִילָנָא, וְעִם כָּל דָּא, (ועובד) דָּא רָזָא דְּרָזִין, וְלָא יְדַעְנָא אִי אֵימָא, אִי לָא אֵימָא. אֵימָא מִילָךְ סָבָא, וַדַּאי אֵימָא, בְּדָא יְדִיעָאן כָּל שְׁאַר בְּנֵי גִּלְגּוּלָא. (נ\"א עובד אילנא אתקין) עוֹבֵד עִם כָּל דָּא אִילָנָא אַתְקִין. כַּד אָתָא דָּוִד מַלְכָּא, בְּאִילָנָא תַּתָּאָה דְּנוּקְבָּא אִשְׁתְּאַר, וְאִצְטְרִיךְ לְקַבְּלָא (בראשית קס\"ה ע\"א) חַיִּין מְאַחֲרָא, וּמָה אִי הַאי דְּאִתְתָּקַּן, וְאַתְקִין כֹּלָּא, הָכִי. שְׁאַר בְּנֵי עָלְמָא דְּאַתְיָין בְּגִלְגּוּלָא, דְּלָא יַכְלִין לְאִתְתַּקְנָא הָכִי, עַל אַחַת כַּמָּה וְכַמָּה.","בְּכָל סִטְרִין אִתְהַפַּךְ בְּגִלְגּוּלָא. פֶּרֶץ הָכִי הֲוָה. בֹּעַז הָכִי הֲוָה. עוֹבֵד הָכִי הֲוָה. (ס\"א ועם כל דא אילנא אתתקן) וּבְכֹלָּא נָפִיק אִילָנָא מִסִּטְרָא דְּרַע, וְאִתְדָּבַּק לְבָתַר בְּסִטְרָא דְּטוֹב. בְּקַדְמִיתָא, (בראשית ל״ח:ז׳) וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע. (אונן אוף הכי) מַחְלוֹן אוּף הָכִי, וְלָאו כָּל כַּךְ. אֲבָל בְּהָנִי אִתְעַכָּל רָע, וְנָפִיק טוֹב לְבָתַר, (נפק) הַהוּא דִּכְתִּיב בֵּיהּ, (שמואל א ט״ז:י״ב) וְטוֹב רֹאִי. (שמואל א ט״ז:י״ב) וַיְיָ' עִמּוֹ. הָכָא קַיְּימָא אִילָנָא תַּתָּאָה עַל תְקּוּנֵיהּ, וּמֶלֶךְ אֱלֹהִים עַל גּוֹיִם.","בְּשֵׁירוּתָא דְּכֹלָּא, מֵעִקָרָא וִיסוֹדָא עִלָּאָה, אִשְׁתְּרָשׁוּ דַּרְגִּין, רְאוּבֵן שִׁמְעוֹן לֵוִי יְהוּדָה, מַה כְּתִיב בֵּיהּ, (בראשית כ״ט:ל״ה) הַפַּעַם אוֹדֶה אֶת יְיָ', וּכְתִיב וַתַּעֲמוֹד מִלֶּדֶת. הַיְינוּ (ישעיהו נ״ד:א׳) רָנִּי עֲקָרָה לֹא יָלָדָה. בְּגִין דְּכַד אִתְיְלִיד יְהוּדָה, נַפְקַת נוּקְבָּא מִתְדַּבְּקָא בִּדְכוּרָא, וְלָא הֲוַת עַל תִּקּוּנָהָא אַנְפִּין בְּאַנְפִּין, וְלָא אִתְכְּשָׁרַת לְאוֹלָדָא כֵּיוָן דְּנָסַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא, וְאַתְקִין לָהּ, (ס\"א אנפין באנפין) כְּדֵין אִתְכְּשָׁרַת לְאִתְעַבְּרָא וּלְאוֹלָדָא.","וּבְסִפְרָא דְּחֲנוֹךְ, וַתַּעֲמוֹד מִלֶּדֶת, לָאו עַל לֵאָה אִתְּמַר, אֶלָּא עַל רָחֵל אִתְּמַר, הַהִיא דִּמְבַכָּה עַל בָּנֶיהָ, הַהִיא דְּאִשְׁתָּרָשַׁת בִּיהוּדָה: יְה\"וּ ד\"ה. וַתַּעֲמוֹד מִלֶּדֶת, דְּהָא לָא אִתְתַּקְנָא."],[[0,"מאן דאית ליה וכו':","מי שיש לו בנים מאשה הראשונה, ומכניס אשה הזו לתוך ביתו, ביום ההוא, הוא מתדבק בחרב הקשה המתהפכת, משום ב' טעמים, א', כי כבר דחתה ב' אנשים לחוץ, ועתה הוא השלישי. ועוד, הכלי שנשתתף בה \u0003אחר,\u0004 איך יבא הוא לתת בו הרוח שלו. וישתתף עמה ויתדבק בה. לא משום שהיא אסורה, אבל ודאי שותפות רעה הוא לעצמו."],[1,"רבי לויטס וכו':","ר' לויטס איש כפר אונו, היה צוחק ומתלוצץ על אשה זו, כשראה מי שהיה מזדווג עמה. והיה אומר, ותשחק ליום אחרון, כתוב, מי שמתדבק באיש אחרון, הוא צחוק לאחר כך."],[2,"השתא אית להדרא וכו':","עתה יש לחזור ולעיין על מקום אחד גדול ועליון שהיה בעולם, וגזע ושורש אמת, והוא, עובד אבי ישי אבי דוד. כי למדנו, שהמגולגל הוא \u0003אחרון,\u0004 ועובד היה גלגול של מחלון, המת בלי בנים, ואיך יצא שורש אמת ממקום הזה."],[3,"אלא עובד אתתקן וכו':","ומשיב, אלא, עובד נתתקן בתקון העליון, והשורש של האילן שנתהפך, שאשתו נעשית אמו וכו' (כנ\"ל אות ק\"ל.) החזיר על תקונו, ונתעלה בו ונתתקן כראוי. וע\"כ נקרא עובד, שהוא לשון עבדות, מה שלא זכו כן שאר בני העולם."],[4,"אתא איהו פלח וכו':","בא הוא, עובד, עבד ועדר את עיקר ושורש האילן, ויצא מפנים המרים, וחזר ותקן בנוף האילן, שהוא המלכות. בא ישי בנו, וחיזק אותו ותקן אותו, ונאחז בענפיו של אילן אחר עליון, שהוא ז\"א, וחיבר אילן באילן, ונסתבכו זה בזה. כיון שבא דוד, מצא האילנות, שהם ז\"א ומלכות, מסתבכים ונאחזים זה בזה, אז ירש ממשלה בארץ. ועובד גרם את זה."],[5,"בכה ההוא סבא וכו':","בכה זקן ההוא ואמר לעצמו, אי זקן זקן, ולא אמרתי לך שנכנסת בים הגדול. עתה, אתה הוא בתוך תהומות הגדולים. התתקן לעלות. זקן זקן, אתה גרמת את זה, כי אם היית שותק בתחילה, היה יפה לך, אבל עתה אינך יכול, ואין מי שיאחז בידך אלא עתה לבדך. קום זקן, ועלה במעלה."],[6,"עובד דא אתתקן וכו':","עובד זה נתתקן ויצא מתוך השדה הרע של בורות רעים. בא ישי בנו והתקין ועדר האילן, ועם כל זה, זה סוד הסודות, ואיני יודע אם אומר או לא אומר. אמור דבריך זקן, ודאי אומר, בזה ניכרים כל שאר בני הגלגול. עובד עכ\"ז התקין האילן, כשבא דוד המלך, נשאר באילן התחתון של הנקבה, שהיא המלכות, והיה צריך לקבל חיים מאחר, כי מעצמו לא היה לו חיים, (כנ\"ל וישלח אות נ\"ג) ומה אם זה שנתתקן והתקין הכל, היה כך, שאר בני העולם הבאים בגלגול, שאינם יכולים להתתקן כך, על אחת כמה וכמה."],[7,"בכל סטרין אתהפך וכו':","בכל הצדדים הוא פונה לגלגול. פרץ היה כן, שהיה גלגול ער, בעז היה כן, שהיה גלגול יהודה, עובד היה כן, שהיה גלגול מחלון. ובכולם יצא האילן מצד הרע ונתדבק אח\"כ בצד הטוב. בתחילה, ויהי ער בכור יהודה רע. מחלון גם כן היה רע, ולא כל כך. אבל באלו נתבער הרע, ויצא הטוב לאחר כך, דהיינו ההוא שכתוב בו, וטוב ראי. וה' עמו. כאן עמד אילן התחתון, שהוא המלכות, על תקונו. ומלך אלקים על גוים."],[8,"בשירותא דכלא מעקרא וכו':","בתחילת הכל, מעיקר ויסוד העליון, נשרשו המדרגות, ראובן שמעון לוי יהודה, שהם חסד גבורה ת\"ת ומלכות. מה כתוב בו, הפעם אודה את ה'. וכתוב ותעמוד מלדת. והיינו, רני עקרה לא ילדה. משום כי כשנולד יהודה, יצאה הנוקבא, שהיא המלכות דבוקה בדכר, שהוא ז\"א, ולא היו על תקונם פנים בפנים, ולא היתה המלכות מוכשרת להוליד. כיון שנסר אותה הקב\"ה, דהיינו שהפרידה מאחורי הדכר, והתקין אותה, אז נעשתה מוכשרת להתעבר ולהוליד. כמו שמפרש לפנינו."],[9,"ובספרא דחנוך וכו':","ובספרו של חנוך, כתוב, ותעמוד מלדת, אינו נאמר על לאה שהיא נוקבא דז\"א שלמעלה מחזה, אלא על רחל נאמר ההיא שמבכה על בניה, ההיא שנשתרשה ביהודה, שהיא הנוקבא שלמטה מחזה שהוא אותיות \u0003יה\"ו ד\"ה.\u0004 ותעמוד מלדת, כי עוד לא נתתקנה."]],[[0,"","מִי שֶׁיֵּשׁ לוֹ בָּנִים מֵאִשְׁתּוֹ הָרִאשׁוֹנָה וּמַכְנִיס אֶת זוֹ לְתוֹךְ בֵּיתוֹ, אוֹתוֹ הַיּוֹם הוּא נִדְבָּק בְּחֶרֶב קָשָׁה שֶׁמִּתְהַפֶּכֶת בִּשְׁבִיל שְׁנֵי צְדָדִים. אֶחָד - שֶׁהֲרֵי שְׁנַיִם הִיא דָּחֲתָה הַחוּצָה, וְעַכְשָׁו הוּא הַשְּׁלִישִׁי. וְעוֹד - כְּלִי שֶׁהִשְׁתַּעְבֵּד (שהשתתף) בּוֹ אַחֵר, אֵיךְ הוּא יָבֹא לָתֵת בָּהּ רוּחוֹ שֶׁלּוֹ וְיִשְׁתַּתֵּף עִמָּהּ וְיִדְבַּק בָּהּ? לֹא שֶׁהִיא אֲסוּרָה, אֲבָל וַדַּאי שִׁתּוּף רַע הוּא לְעַצְמוֹ (כמו שבארנו)."],[1,"","רַבִּי לְוִיטַס אִישׁ כְּפַר אוֹנוֹ הָיָה צוֹחֵק וּמִתְלוֹצֵץ עַל הָאִשָּׁה הַזּוֹ, כְּשֶׁרָאָה מִי מִזְדַּוֵּג עִמָּהּ, וְהָיָה אוֹמֵר, (משלי לא) וַתִּשְׂחַק לְיוֹם אַחֲרוֹן כָּתוּב. מִי שֶׁנִּדְבֶּקֶת בּוֹ בְּאִישׁ אַחֲרוֹן, אַחַר כָּךְ הִיא צְחוֹק."],[2,"","עֵכְשָׁו יֵשׁ לַחֲזֹר וּלְעַיֵּן עַל מָקוֹם (נ\"א אילן) אֶחָד גָּדוֹל וְעֶלְיוֹן שֶׁהָיָה בָּעוֹלָם, וְגֶזַע וְשֹׁרֶשׁ שֶׁל אֱמֶת, וְהוּא עוֹבֵד אֲבִי יִשַׁי אֲבִי דָוִד, שֶׁהֲרֵי נֶאֱמַר שֶׁהָיָה אַחֲרוֹן, אֵיךְ יָצָא שֹׁרֶשׁ אֱמֶת מֵהַמָּקוֹם הַזֶּה?"],[3,"","אֶלָּא עוֹבֵד נִתְקָן בְּתִקּוּן עֶלְיוֹן, וְחָזַר הַשֹּׁרֶשׁ שֶׁל הָאִילָן שֶׁהִתְהַפֵּךְ עַל תִּקּוּנוֹ, וְהִתְעַלָּה בּוֹ וְהִתְתַּקֵּן כָּרָאוּי, וְעַל זֶה נִקְרָא עוֹבֵד, מַה שֶּׁלֹּא זָכוּ כָּךְ שְׁאָר בְּנֵי הָעוֹלָם."],[4,"","הוּא בָּא, עָבַד וְעָדַר אֶת עִקַּר וְשֹׁרֶשׁ הָאִילָן, וְיָצָא מֵהַפָּנִים הַמָּרִים, וְחָזַר וְנִתְקָן בְּנוֹף שֶׁל אִילָן אַחֵר עֶלְיוֹן. בָּא יִשַׁי בְּנוֹ וְחִזֵּק אוֹתוֹ וְתִקֵּן אוֹתוֹ, וְנֶאֱחַז בְּעַנְפֵי הָאִילָן הָעֶלְיוֹן הָאַחֵר, וְחִבֵּר אִילָן בְּאִילָן, וְהִסְתַּבְּכוּ זֶה בָּזֶה. כֵּיוָן שֶׁבָּא דָוִד, מָצָא אִילָנוֹת מְסֻבָּכִים וּמְאֻחָדִים זֶה בָּזֶה. אָז יָרַשׁ הַשִּׁלְטוֹן בָּאָרֶץ, וְעוֹבֵד גָּרַם אֶת זֶה."],[5,"","בָּכָה אוֹתוֹ זָקֵן וְאָמַר, אִי זָקֵן זָקֵן, וְלֹא אָמַרְנוּ לְךְ שֶׁנִּכְנַסְתָּ לַיָּם הַגָּדוֹל?! עַכְשָׁו אַתָּה הוּא בְּתוֹךְ הַתְּהוֹמוֹת הַגְּדוֹלִים. הִתְתַּקֵּן לַעֲלוֹת. זָקֵן זָקֵן, אַתָּה גָּרַמְתָּ לָזֶה, שֶׁאִלְמָלֵא הָיִיתָ שׁוֹתֵק בַּתְּחִלָּה, הָיָה נָאֶה לְךְ, אֲבָל עַכְשָׁו לֹא יָכֹלְתָּ וְאֵין מִי שֶׁיֹּאחֵז בְּיָדְךְ, אֶלָּא אַתָּה בִּלְבַדְּךְ. קוּם זָקֵן וַעֲלֵה בְמַעֲלָה."],[6,"","עוֹבֵד זֶה הִתְתַּקֵּן וְיָצָא מִתּוֹךְ שָׂדֶה רַע שֶׁל בּוֹרוֹת רָעִים. בָּא יִשַׁי בְּנוֹ וְהִתְקִין וְעָדַר אֶת הָאִילָן, וְעִם כָּל זֶה, (ועובד) זֶה סוֹד הַסּוֹדוֹת, וְלֹא יָדַעְתִּי אִם אֹמַר וְאִם לֹא אֹמַר. אֱמֹר דְּבָרֶיךְ, זָקֵן, וַדַּאי אֱמֹר, בָּזֶה יְדוּעִים כָּל שְׁאָר בְּנֵי הַגִּלְגּוּל. (עובד התקין אילן, ועם כל זה שהתקין אילן) עוֹבֵד עִם כָּל זֶה הִתְקִין אִילָן. כְּשֶׁבָּא דָוִד הַמֶּלֶךְ, נִשְׁאַר בָּאִילָן הַתַּחְתּוֹן שֶׁל הַנְּקֵבָה, וְהִצְטָרֵךְ לְקַבֵּל חַיִּים מֵאַחֵר. וּמָה אִם זֶה שֶׁהִתְתַּקֵּן וְהִתְקִין הַכֹּל כָּךְ - שְׁאָר בְּנֵי הָעוֹלָם שֶׁבָּאִים בְּגִלְגּוּל, שֶׁלֹּא יְכוֹלִים לְהִתְתַּקֵּן כָּךְ, עַל אַחַת כַּמָּה וְכַמָּה."],[7,"","בְּכָל הַצְּדָדִים מִתְהַפֵּךְ בְּגִלְגּוּל. כָּךְ הָיָה פֶּרֶץ. כָּךְ הָיָה בּעַז. כָּךְ הָיָה עוֹבֵד. (ועםכלזההאילןנתקן) וּבַכֹּל יוֹצֵא אִילָן מִצַּד הָרָע, וְאַחַר כָּךְ נִדְבָּק בַּצַּד הַטּוֹב. בַּתְּחִלָּה, וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע. (אונן אף כך) מַחְלוֹן אַף כָּךְ וְלֹא כָּל כָּךְ. אֲבָל בְּאֵלֶּה הִתְעַכֵּל הָרָע, וְיָצָא אַחַר כָּךְ טוֹב, (יצא) אוֹתוֹ שֶׁכָּתוּב בּוֹ (שמואל א טז) וְטוֹב רֹאִי. וַה' עִמּוֹ. עַכְשָׁו עוֹמֵד אִילָן תַּחְתּוֹן עַל תִּקּוּנוֹ, וּמֶלֶךְ אֱלֹהִים עַל גּוֹיִם."],[8,"","בְּרֵאשִׁית הַכֹּל, מֵעִקַּר וִיסוֹד עֶלְיוֹן הִשְׁתָּרְשׁוּ דְרָגוֹת, רְאוּבֵן שִׁמְעוֹן לֵוִי יְהוּדָה. מַה כָּתוּב בּוֹ? (בראשית כט) הַפַּעַם אוֹדֶה אֶת ה'. וְכָתוּב וַתַּעֲמֹד מִלֶּדֶת. הַיְנוּ (ישעיה נד) רָנִּי עֲקָרָה לֹא יָלָדָה. מִשּׁוּם שֶׁכְּשֶׁנּוֹלַד יְהוּדָה, יָצְאָה נְקֵבָה דְּבוּקָה בְזָכָר, וְלֹא הָיְתָה עַל תִּקּוּנֶיהָ פָּנִים בְּפָנִים וְלֹא הֻכְשְׁרָה לָלֶדֶת. כֵּיוָן שֶׁנִּסֵּר אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא וְהִתְקִין אוֹתָהּ, (פנים בפנים) אָז הֻכְשְׁרָה לְהִתְעַבֵּר וְלָלֶדֶת."],[9,"","וּבְסִפְרוֹ שֶׁל חֲנוֹךְ, וַתַּעֲמֹד מִלֶּדֶת לֹא נֶאֱמַר עַל לֵאָה, אֶלָּא נֶאֱמַר עַל רָחֵל, אוֹתָהּ שֶׁמְּבַכָּה עַל בָּנֶיהָ, אוֹתָהּ שֶׁנִּשְׁרְשָׁה בִּיהוּדָה - יְה\"וּ דָ\"ה. וַתַּעֲמֹד מִלֶּדֶת, שֶׁהֲרֵי לֹא נִתְקְנָה."]]],[["בְּקַדְמִיתָא, דִּיּוּקְנָא דִּלְעֵילָּא הֲוָה כֹּלָּא רְאוּבֵן: אוֹ\"ר בֵּ\"ן. (בראשית א׳:ו׳) וַיֹּאמֶר אֱלהִים יְהִי אוֹר, יְמִינָא אוֹר. (ב\"ן) שִׁמְעוֹן שְׂמָאלָא אוֹר בְּהַהוּא סִיגָא דְּדַהֲבָא בַּהֲדֵיהּ שֵׁם עָוֹן. לֵוִ\"י: חִבּוּרָא דְּכֹלָּא, לְאִתְחַבְּרָא מִתְּרֵין סִטְרִין. יְהוּדָה: נוּקְבָּא בַּהֲדֵי דְּכוּרָא מִתְדַּבְּקָת, יְה\"וּ, דָּא דְּכוּרָא. ד\"ה, דָּא נוּקְבָּא דַּהֲוַת בַּהֲדֵיהּ.","ד\"ה, אֲמַאי ד\"ה. אֶלָּא ד', בְּאִתְדַּבְּקוּתָא דְּרַע בַּהֲדָהּ, אִיהִי דָּלֶ\"ת, מִסְכְּנָא אִיהִי, וְאִצְטְרִיךְ לְאָתָבָא בְּגִלְגּוּלָא, לְאִתְעַכְּלָא הַהוּא רַע, וּלְמִתְבְּלֵי בְּעַפְרָא. וּלְבָתַר לְצַמְחָא בְּסִטְרָא דְּטוֹב, וְּלְנָפְקָא מִמִּסְכְּנוּ לַעֲתִירוּ, וּכְדֵין ה'. וְעַל דָּא, יְה\"וּ ד\"ה.","פּוּק סָבָא, מִגּוֹ תְּהוֹמֵי, לָא תִּדְחַל, כַּמָּה אַרְבִּין זְמִינִין לָךְ, בְּשַׁעֲתָא דִּתְשׁוֹטֵט יַמָּא, בְּגִין לְנַיְיחָא בְּהוּ. בָּכָה כְּמִלְּקַדְּמִין וְאָמַר, מָארֵי דְּעָלְמָא, דִּילְמָא יֵימְרוּן מַשְׁרְיָין עִלָּאִין, דַּאֲנָא סָבָא, וּבָכֵי כִּינוֹקָא. גַּלֵּי קַמָּךְ, דְּעַל יְקָרָךְ אֲנָא עָבִיד, וְלָא עֲבִידְנָא עַל יְקָרָא דִּילִי, דְּהָא בְּקַדְמִיתָא הֲוָה לִי לְאִסְתַּמְּרָא, דְּלָא אֵיעוּל בְּיַמָּא רַבָּא, וְהַשְׁתָּא כֵּיוָן דַּאֲנָא בֵּיהּ, אִית לִי לְשַׁטְּטָא בְּכָל סִטְרִין, וְּלְנָפְקָא מִנֵיהּ.","(בראשית כט) יְהוּדָה אַתָּה יוֹדוּךָ אַחֶיךָ, (ס\"א כולהו אודאן על שמא דא והיינו וכו') הַיְינוּ דַּאֲנַן אַמְרִין בָּרוּךְ אַתָּה. אִיהוּ בָּרוּךְ וְאִיהִי אַתָּה, לְכֻלְּהוּ בְּנוֹי לָא אָמַר יַעֲקֹב אַתָּה, אֶלָּא לַאֲתָר דְּאִצְטְרִיךְ. דָּא אִיהוּ אַתָּה.","שְׁמָא דָּא, (נ\"א ודאי אתה) יוֹדוּךָ אַחֶיךָ, כֻּלְּהוּ אוֹדָן לָךְ עַל שְׁמָא דָּא, וַדַּאי אַתָּה יוֹדוּךָ אַחֶיךָ, עַל שְׁמָא דָּא, אִסְתַּלָּק וְאִתְכַּפְיָא סְטָר אַחֲרָא, בְּגִין דְּכַד אִתְקְרֵי וְאַדְכַּר, הָא נַפְקַת סִטְרָא אַחֲרָא בַּהֲדָהּ. כֵּיוָן דְּאַמְרֵי אַתָּה, שֻלְטָנוּ וְרַבְרְבָנוּ אִית לָהּ, וְסִטְרָא אַחֲרָא אִתְכַּפְיָיא, וְלָא אִתְחֲזִיאַת תַּמָּן. וַדַּאי בִּשְׁמָא דָּא אִתְרְשִׁים וְאִתְבְּרִיר מִסִּטְרָא אַחֲרָא. וְדָא אִסְתָּלָקוּ וְשֻלְטָנוּ דִּילָיהּ, וּתְבִירוּ וּבִישׁ לְסִטְרָא אַחֲרָא. כֵּיוָן דְּיוֹדוּךָ אַחֶיךָ עַל שְׁמָא דָּא, אַתָּה, כְּדֵין יָדְךָ בְּעֹרֶף אוֹיְבֶיךָ, מִיָּד אִתְכַּפְיָין לְגַבָּךְ, וּשְׁמָא דָּא גָּרִים.","יָדַעְנָא חַבְרַיָּיא יָדַעְנָא, דְּהָא אַתָּה שְׁמָא דָּא, אַתּוּן אַמְרִין לַאֲתַר אַחֲרָא עִלָּאָה, דִּכְתִּיב, (תהילים ק״י:ד׳) אַתָּה כֹּהֵן לְעוֹלָם, בִּימִינָא עִלָּאָה. שַׁפִּיר אִיהוּ, דְּהָא כֵּיוָן דְּרַבִּי שִׁמְעוֹן אוֹדָן לֵיהּ עִלָּאִין וְתַתָּאִין, וְזָכָה לְכֹלָּא, כָּל מַה דְּאִיהוּ אָמַר, הָכִי אִיהוּ וְשַׁפִּיר.","אֲבָל כַּד תֶּהֱווֹן מָטָאן לְגַבֵּיהּ, אִמְרוּ לֵיהּ, וְאַדְכְּרוּ לֵיהּ, יוֹמָא דְּתַלְגָּא, כַּד (צ\"ז ע\"ב) זְרַעְנָא פּוֹלִין, לְחַמְשִׁין וּתְרֵין גַּוְונִין. דְּהָא אַתָּה כֹּהֵן, הָכָא אִתְקָשַּׁר כּוֹס דִּבְרָכָה בִּימִינָא, בְּלֹא פִּרוּדָא כְּלָל. וּבְגִין כַּךְ, אַתָּה כֹּהֵן לְעוֹלָם, הָכָא אִתְקָשָּׁר כּוֹס בִּימִינָא, כְּדְקָא יֵאוֹת.","וְעַל דָּא אָמַר קְרָא, יְהוּדָה אַתָּה, לְהַאי אַתָּה יוֹדוּךָ אַחֶיךָ, וְלָא כְּתִיב יְהוּדָה יוֹדוּךָ אַחֶיךָ, וְלָא יַתִּיר, אֶלָּא עַל שְׁמָא דְּאַתָּ\"ה. אַתָּה, אֲתָר דָּא, אִצְטְרִיךְ לִשְׁמָא דָּא, וְלָא אַחֲרָא.","יְהוּדָה, אַבָּא קַדְמָאָה, וְאַבָּא תִּנְיָינָא, וְלָא הֲוָה בֵּיהּ חִלּוּפָא לְעָלְמִין. וּבְּגִין כָּךְ פֶּרֶץ אִתְתָּקַּף בֵּיהּ בְּתוֹקְפוֹי, מַה דְּלָא הֲוָה הָכִי לְכָל בְּנֵי עָלְמָא. וְעַל דָּא בִּנְיָינָא דְּדָוִד, שָׁארֵי חֶשְׁבֹּנָא מִפֶּרֶץ, וְלָא מִבֹּעַז, דְּהֲוָה בֵּיהּ שִׁנּוּיָא. חַבְרַיָּיא, אִי תַּשְׁגְּחוּן, לָאו מִלִּין בִּסְתִימוּ קָא אֲמֵינָא, וְאַף עַל גַּב דִּסְתִּימִין אִינּוּן.","וְעַל דָּא, יְהוּדָה רָוַוח שְׁמָא דָּא, דְּאִקְרֵי אַתָּה. קָם עַל בּוּרְיֵהּ זִמְנָא קַדְמָאָה, וְזִמְנָא תִּנְיָינָא, וְלָא אִשְׁתָּנִי לְעָלַם. וּבְנוֹי דִּיהוּדָה וְזַרְעָא דִּילֵיהּ, אוֹדָן וְאָמְרִין כִּי אַתָּה אָבִינוּ. מַה דְּלֵית הָכִי לִשְׁאַר בְּנִי גִּלְגּוּלָא לְעָלְמִין. שְׁאַר בְּנֵי גִּלְגּוּלָא, תְּרֵין אֲבָהָן, תְּרֵין אִמָּהָן, אִית לוֹן גּוָֹון לְבִנְיָינָא. וְרָזִין אִלֵּין, בְּעִמְקֵי יַמָּא, בְּלִבָּא דִּתְהוֹמֵי אִינּוּן, מַאן יָכִיל לְאַפָּקָא לוֹן. קוּם סָבָא, אִתְגַּבָּר וְאִתָּקַף בְּתוּקְפָךְ, אַפִּיק מַרְגְּלָן מִגּוֹ תְּהוֹמֵי.","בֹּעַז, אִתְחָזֵי דְּהֲוָה בֵּיהּ שִׁנּוּיָא, כַּד אוֹלִיד לְעוֹבֵד, דְּהָא עוֹבֵד (ס\"א עובדא) בְּשִׁנּוּיָא הוּא. לָאו הָכִי. אִבְצַן הוּא בֹּעַז, הוּא אַבָּא קַדְמָאָה, דְּלָא עָבֵד שִׁנּוּיָא. וְאִי תֵּימָא, אִיהוּ הֲוָה, וַדַּאי כַּד אִתְּעַר לְעוֹבָדָא דָּא, בֵּיהּ הֲוָה, מַאן דְּהוּא תַּקִּיף כְּאַרְיָא וּכְלֵיתָא בֵּיהּ הֲוָה. בְּגִין דְּלָא לֶהוֵי שִׁנּוּיָא בֵּיהּ בְּדָוִד, וְאִתְהַדָּר מִלָּה לְעִקָרָא קַדְמָאָה, בְּגִין דִּיהֵא כֹּלָּא מֵאַבָּא חֲדָא, וְשַׁלְשְׁלָא חֲדָא. וְכֹלָּא חַד, וְלָא הֲוָה שִׁנּוּיָא בְּגִלְגּוּלָא דְּזַרְעָא דְּדָוִד. וְעַל דָּא, אַתָּה מֵרֵישָׁא וְעַד סוֹפָא, בְּלא שִׁנוּיָיא כְּלָל."],[[0,"בקדמיתא דיוקנא דלעילא:","בתחילה הצורה שלמעלה היתה הכל, שאפילו רחל, עלתה והיתה למעלה מחזה. \u0003ראובן\u0004 הוא אותיות אור בן, שה\"ס ויאמר אלקים יהי אור, שהוא ימין, דהיינו \u0003חסד,\u0004 של ז\"א. \u0003שמעון,\u0004 הוא שמאל, והוא אור, עם ההיא פסולת של זהב, כי שמעון הוא אותיות \u0003שם עון.\u0004 שהוא שמאל, \u0003גבורה\u0004 דז\"א. \u0003לוי,\u0004 היא חיבור הכל, להתחבר ב' הצדדים. כי הוא קו האמצעי המחבר ימין עם השמאל. והוא \u0003תפארת\u0004 דז\"א. ואחר שיצאו חג\"ת דז\"א שלמעלה מחזה, יצאה הנוקבא הנק' רחל. והיינו \u0003יהודה,\u0004 שהיא הנוקבא, והנוקבא מתדבקת בדכר, שהוא חג\"ת דז\"א, \u0003יה\"ו\u0004 זה דכר, דהיינו חג\"ת \u0003ד\"ה\u0004 זו היא הנוקבא, רחל, שהיתה עמו, עם הדכר."],[1,"ד\"ה אמאי ד\"ה וכו':","שואל, הנוקבא מרומזת באותיות ד\"ה, למה ד\"ה. ומשיב, אלא \u0003ד'\u0004 נקראת הנוקבא, בעת שדבקות הרע עמה, דהיינו בעת שהיא בבחינת שמאל בלבד, והיא דבוקה באחורי הדכר. היא דל\"ת שפירושו שהיא עניה, וצריכה לשוב בגלגול, דהיינו הגלגולים מן יהודה עד דוד המלך לבער רע ההיא, ולבלות בעפר ולצמוח אח\"כ בצד הטוב, דהיינו ע\"י בנין או\"א מחדש, בסו\"ה ויבן ה' אלקים את הצלע וגו', ולצאת מעניות לעשירות ואז נקראת \u0003ה'\u0004 ועל כן יהודה, הוא אותיות \u0003יה\"ו ד\"ה,\u0004 שיה\"ו חג\"ת דדכר, ד' ה' הם הנוקבא בב' מצבים שלה הנ\"ל המתחברת עם הדכר."],[2,"פוק סבא מגו וכו':","אמר לעצמו, צא זקן מתוך התהומות, לא תפחד. כמה אניות מזומנות לך, בשעה שתשוט בים, כדי לנוח בהם. בכה כבתחילה, ואמר, רבון העולם, פן יאמרו מחנות העליונים שאני זקן ובוכה כילד. גלוי לפניך, שעל כבודך אני עושה, ואיני עושה על כבודי, כי בתחילה היה לי להשמר מלכנוס בים הגדול, ועתה כיון שאני בו, יש לי לשוט בכל הצדדים ולצאת ממנו."],[3,"יהודה אתה יודוך אחיך:","היינו שאנו אומרים, \u0003ברוך אתה,\u0004 הוא ברוך, כשהיסוד דז\"א משפיע חסדים למלכות, נקרא הוא \u0003ברוך,\u0004 והיא \u0003אתה.\u0004 והמלכות נקראת אתה. כי השם אתה רומז על חסדים, בסו\"ה אתה כהן, כמ\"ש לפנינו. לכל הבנים לא אמר יעקב \u0003אתה,\u0004 אלא למקום שצריך. כי המלכות נמשכת מצד שמאל, ששם מאירה החכמה בלי חסדים, והיא צריכה להשם אתה, שהוא חסדים להלביש בו החכמה. כי בלי חסדים אין החכמה מאירה, והיא בסוד חושך. זהו שאמר לו ליהודה אתה."],[4,"שמא דא יודוך וכו':","יודוך אחיך, כולם יודו לך על שם הזה, ודאי, \u0003אתה\u0004 יודוך אחיך, על שם הזה נסתלק ונכנע צד האחר. משום, כי כשנקרא ונזכר השם יהודה, הרי יוצאת הס\"א עמה, דהיינו ב \u0003ד'\u0004 של יהודה, הרומזת על מצב הא' שלה שנמשכת משמאל לבד, ששם יונקת הס\"א, מחמת חסרון החסדים שבימין, כיון שאומרים \u0003אתה,\u0004 שהוא המשכת החסדים מימין, אז יש לה ממשלה וגדולה, והס\"א נכנעת, ואינה נראית שם. ודאי בשם הזה נרשמת ונבררת מן הס\"א, כי כשמתלבשת בחסדים, נרחקת הס\"א ממנה, וזהו ההתעלות והממשלה שלה, של המלכות, ושבירה ורע לצד האחר. כיון דיודוך אחיך על שם הזה, אתה, אז \u0003ידך בערף אויביך,\u0004 מיד הס\"א נכנע לך. ושם הזה גרם."],[5,"ידענא חבריא ידענא וכו':","אני יודע, חברים, אני יודע שהשם הזה \u0003אתה,\u0004 אתם אומרים למקום אחר עליון, שכתוב, אתה כהן לעולם, שהוא בימין העליון, דהיינו בחכמה. יפה הוא, כיון שר' שמעון, עליונים ותחתונים מודים לו, וזכה לכל, כל מה שאמר, כן הוא, ויפה."],[6,"אבל כד תהוון וכו':","אבל כשתהיו מגיעים אליו, אמרו לו והזכירו לו, יום השלג, כשזרענו פולין לחמשים ושנים גוונים. כי אתה כהן, פירושו, כאן נקשר כוס של ברכה, שהיא המלכות הנקראת אתה, בימין, שהוא החסד שנקרא כהן, בלא פרוד כלל. ומשום זה אתה כהן לעולם, כי כאן נקשר הכוס, שהוא המלכות, כראוי. וע\"כ קיים, לעולם."],[6,"","ענין יום השלג וזריעת הפולין לב\"ן גוונין, כבר נתבאר לעיל (אות ע\"ד) ש \u0003יום השלג,\u0004 הוא בעת שהמלכות נאחזת בקו שמאל לבד, שאז היא מלאה דינים המכונים קרח ושלג, וזה נמשך עד שבא קו האמצעי, שהוא ז\"א, ומעלה המסך דמלכות אל הבינה, וכו' שה\"ס \u0003זריעת הפולין,\u0004 ואז מתגלים החסדים, והארת החכמה שבשמאל שבבנין המלכות, מתלבשת בחסדים האלו, שה\"ס \u0003אתה,\u0004 ואז מסתלקים הדינים דשלג והחכמה מאירה בכל השלמות. וזה שרמז הסבא שעל ענין זה סובב הכתוב, אתה כהן לעולם. כי אחר ש \u0003אתה\u0004 שהוא המלכות נקשרת בחסדים שה\"ס \u0003כהן\u0004 ע\"י זריעת הפולין של קו האמצעי אז הוא מתקיים לעולם."],[7,"ועל דא אמר וכו':","ועל זה אומר הכתוב, יהודה אתה, לאתה הזה יודוך אחיך, שלא כתוב, יהודה יודוך אחיך, ולא יותר, אלא על השם אתה יודו אחיו. \u0003אתה,\u0004 מקום זה, שהוא המלכות, צריך לשם הזה, להיותה בלעדו, בדינים בשלג וקרח מצד השמאל, כנ\"ל בדבור הסמוך. ולא אחר, שמדרגה אחרת אינה צריכה לו, שרק המלכות נמשכת משמאל ונבנית כולה ממנו, ולא אחרת."],[8,"יהודה אבא קדמאה וכו':","יהודה הוא אב הראשון, של ער ואונן, ואב השני של פרץ וזרח, שהם גלגולי ער ואונן, ולא היה בו חלוף לעולם. שלא נתחלף המדרגה שהאח נעשה לאב. שהמת בלי בנים מתגלגל בבן הנולד מן אחיו היבם, ואחיו נעשה אביו שזה ירידת המדרגה ופגם. אבל יהודה לא היה בו חלוף וירידת מדרגה, כי הוא היה גם אב הראשון, של ער ואונן המגולגלים בפרץ וזרח. ומשום כך פרץ התגבר בגבורתו, שכתוב בו, מה פרצת עליך פרץ. משום שלא היה בו ירידת מדרגה, מה שלא היה כן לכל בני העולם הבאים בגלגול שיש להם ירידה, שהאח נעשה אביו. וע\"כ בנינו של דוד מתחיל החשבון מפרץ ולא מבועז, שהיה בו שינוי, כי לא היה האב הראשון של המגולגל, שהוא מחלון. חברים, אם תסתכלו בדברי, אינם דברים הנאמרים בסתום, בלא אפשרות להבינם, אע\"פ שהם סתומים."],[9,"וע\"ד יהודה רווח וכו':","ועל זה, הרויח יהודה שם הזה שנקרא, אתה. קם על בירורו בפעם הראשונה, בער ואונן, ובפעם השניה, בפרץ וזרח, ולא נשתנה לעולם. ובניו של יהודה וזרעו, מודים ואומרים כי אתה אבינו שלא נעשה להם ירידה שהאח יעשה לאב. מה שאין כן לשאר בני הגלגול לעולם. שאר בני הגלגול, שני אבות ושני אמהות יש להם אפן לבנין שלו. כי נוסף לאביו הראשון נעשה גם אחיו לאביו, ויש לו ב' אבות, וכן ב' אמהות, שנוסף לאמו הראשונה נעשה גם אשתו לאמו. וסודות אלו הם בעומק הים בלב התהומות, מי יכול להוציאם משם. קום זקן, התגבר והתחזק בתוקפך, והוצא מרגליות מן התהומות."],[10,"בעז אתחזי דהוה וכו':","בעז, נראה שהיה בו שינוי כשהוליד לעובד, כי עובד הוא בשינוי, שהוא אביו השני. ואומר, אינו כן, אבצן הוא בעז, ולמה נקרא בעז, מפני שהוא אב הראשון שלא עשה שינוי, דהיינו שיהודה, שהוא אב הראשון, נתגלגל בו. ואם תאמר, שהוא היה, ואינו גלגול יהודה, אבל ודאי בעת שנתעורר למעשה הזו של יבום, היה בו מי שהוא עז כאריה וכלביא דהיינו יהודה, היה בו, וע\"כ נקרא בועז, מלשון בו עז, שהוא יהודה, והיה זה, כדי שלא יהיה שינוי בדוד, ומשום שנתגלגל בו יהודה חזר הדבר לשורש הראשון, כדי שיהיו כולם מאב אחד, ושלשלת אחת. והכל אחד, ולא היה שינוי בגלגול הזרע של דוד. ועל כן, אתה, מראש, ועד סוף בלא שינוי כלל."]],[[0,"","בַּתְּחִלָּה דְּיוֹקַן הָעֶלְיוֹן הָיָה הַכֹּל רְאוּבֵן - אוֹ\"ר בֵּ\"ן. (בראשית א) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר, יָמִין אוֹר. (ב\"ן) שִׁמְעוֹן שְׂמֹאל אוֹר, בְּאוֹתוֹ סִיג שֶׁהַזָּהָב עִמּוֹ - שָׁם עָון. לֵוִי - חִבּוּר שֶׁל הַכֹּל לְהִתְחַבֵּר מִשְּׁנֵי צְדָדִים. יְהוּדָה - נְקֵבָה עִם זָכָר נִדְבֶּקֶת. יְה\"וּ - זֶה זָכָר. דָ\"ה - זוֹ נְקֵבָה שֶׁהָיְתָה עִמּוֹ."],[1,"","דָ\"ה, לָמָּה דָ\"ה? אֶלָּא ד' בְּהִדָּבְקוּת שֶׁל רַע עִמָּהּ הִיא דָלֶ\"ת, הִיא עֲנִיָּה, וּצְרִיכָה לָשׁוּב בְּגִלְגּוּל לְבַעֵר אֶת אוֹתוֹ הָרָע וּלְהִתְבַּלּוֹת בֶּעָפָר, וְאַחַר לִצְמֹחַ בַּצַּד הַטּוֹב וְלָצֵאת מֵעֹנִי לְעֹשֶׁר, וְאָז ה'. וְעַל זֶה יְה\"וּ דָ\"ה."],[2,"","צֵא זָקֵן מִתּוֹךְ הַתְּהוֹמוֹת, אַל תִּפְחַד, כַּמָּה סְפִינוֹת מְזֻמָּנוֹת לְךְ בְּשָׁעָה שֶׁתָּשׁוּט בַּיָּם כְּדֵי לָנוּחַ בָּהֶן. בָּכָה כְּמוֹ מִקֹּדֶם וְאָמַר, רִבּוֹן הָעוֹלָם, אוּלַי יֹאמְרוּ הַמַּחֲנוֹת הָעֶלְיוֹנִים שֶׁאֲנִי זָקֵן וּבוֹכֶה כְּתִינוֹק. גָּלוּי לְפָנֶיךְ שֶׁעַל כְּבוֹדְךְ אֲנִי עוֹשֶׂה, וְלֹא עָשִׂיתִי לִכְבוֹדִי, שֶׁהֲרֵי בַּתְּחִלָּה הָיָה לִי לְהִשָּׁמֵר שֶׁלֹּא אֶכָּנֵס לַיָּם הַגָּדוֹל, וְעַכְשָׁו כֵּיוָן שֶׁאֲנִי בּוֹ, יֵשׁ לִי לְשׁוֹטֵט בְּכָל הַצְּדָדִים וְלָצֵאת מִמֶּנּוּ."],[3,"","יְהוּדָה אַתָּה יוֹדוּךְ אַחֶיךְ, (כולם מודים על השם הזה) הַיְנוּ מַה שֶּׁאָנוּ אוֹמְרִים בָּרוּךְ אַתָּה, הוּא בָּרוּךְ וְהִיא אַתָּה. לְכָל בָּנָיו לֹא אָמַר יַעֲקֹב אַתָּה, אֶלָּא לְמָקוֹם שֶׁהִצְטָרֵךְ. זֶהוּ אַתָּה."],[4,"","הַשֵּׁם הַזֶּה (ודאי אתה) יוֹדוּךְ אַחֶיךְ. כֻּלָּם מוֹדִים לְךְ עַל הַשֵּׁם הַזֶּה. וַדַּאי אַתָּה יוֹדוּךְ אַחֶיךְ, עַל הַשֵּׁם הַזֶּה הִסְתַּלֵּק וְנִכְפָּה הַצַּד הָאַחֵר, מִשּׁוּם שֶׁכְּשֶׁנִּקְרָא וְנִזְכָּר, הֲרֵי יוֹצֵא אִתּוֹ הַצַּד הָאַחֵר. כֵּיוָן שֶׁאוֹמְרִים אַתָּה, שִׁלְטוֹן וּגְדֻלָּה יֵשׁ לָהּ, וְהַצַּד הָאַחֵר נִכְפֶּה וְלֹא נִרְאֶה שָׁם. וַדַּאי שֶׁבַּשֵּׁם הַזֶּה נִרְשָׁם וְנִבְחָר מֵהַצַּד הָאַחֵר. וְזוֹ הָעֲלִיָּה וְהַמֶּמְשָׁלָה שֶׁלָּהּ, וְשֶׁבֶר וְרַע לַצַּד הָאַחֵר. כֵּיוָן שֶׁיּוֹדוּךְ אַחֶיךְ עַל הַשֵּׁם הַזֶּה, אַתָּה, אָז יָדְךְ בְּעֹרֶף אֹיְבֶיךְ, מִיָּד נִכְנָעִים אֵלֶיךְ, וְהַשֵּׁם הַזֶּה גּוֹרֵם."],[5,"","יָדַעִִתִּי, חֲבֵרִים, יָדַעְתִּי, שֶׁאַתָּה הֲרֵי הַשֵּׁם הַזֶּה, אַתֶּם אוֹמְרִים לְמָקוֹם עֶלְיוֹן אַחֵר, שֶׁכָּתוּב (תהלים קי) אַתָּה כֹהֵן לְעוֹלָם, בַּיָּמִין הָעֶלְיוֹן. יָפֶה הוּא, שֶׁהֲרֵי כֵּיוָן שֶׁרַבִּי שִׁמְעוֹן מוֹדִים לוֹ עֶלְיוֹנִים וְתַחְתּוֹנִים, וְזָכָה לַכֹּל. כָּל מַה שֶּׁהוּא אוֹמֵר, כָּךְ זֶה וְיָפֶה."],[6,"","אֲבָל כְּשֶׁתִּהְיוּ מַגִּיעִים אֵלָיו, אִמְרוּ לוֹ וְהַזְכִּירוּ לוֹ אֶת יוֹם הַשֶּׁלֶג כְּשֶׁזָּרַעְנוּ פּוֹלִים לַחֲמִשִּׁים וּשְׁנַיִם גְּוָנִים, שֶׁהֲרֵי אַתָּה כֹהֵן. כָּאן נִקְשָׁר כּוֹס שֶׁל בְּרָכָה בַּיָּמִין בְּלִי פֵרוּד כְּלָל, וּמִשּׁוּם כָּךְ, אַתָּה כֹהֵן לְעוֹלָם. כָּאן נִקְשָׁר כּוֹס בַּיָּמִין כָּרָאוּי."],[7,"","וְעַל זֶה אָמַר הַכָּתוּב, יְהוּדָה אַתָּה, לָאַתָּה הַזֶּה יוֹדוּךְ אַחֶיךְ, וְלֹא כָתוּב יְהוּדָה יוֹדוּךְ אַחֶיךְ וְלֹא יוֹתֵר, אֶלָּא עַל שֵׁם שֶׁל אַתָּ\"ה. אַתָּה - מָקוֹם זֶה הִצְטָרֵךְ לַשֵּׁם הַזֶּה, וְלֹא אַחֵר."],[8,"","יְהוּדָה - הָאָב הָרִאשׁוֹן וְהָאָב הַשֵּׁנִי, וְלֹא הָיָה בּוֹ חִלּוּף לְעוֹלָמִים. וּמִשּׁוּם כָּךְ פֶּרֶץ הִתְגַּבֵּר בּוֹ בִּגְבוּרָתוֹ מַה שֶּׁלֹּא הָיָה כָּךְ לְכָל בְּנֵי הָעוֹלָם. וְעַל כָּךְ בִּנְיָנוֹ שֶׁל דָּוִד מַתְחִיל אֶת הַחֶשְׁבּוֹן מִפֶּרֶץ, וְלֹא מִבֹּעַז, שֶׁהָיָה בּוֹ שִׁנּוּי. חֲבֵרִים, אִם תַּשְׁגִּיחוּ, לֹא אָמַרְתִּי דְבָרִים בְּסֵתֶר, וְאַף עַל גַּב שֶׁהֵם נִסְתָּרִים."],[9,"","וְעַל כָּךְ יְהוּדָה הִרְוִיחַ אֶת הַשֵּׁם הַזֶּה שֶׁנִּקְרָא אַתָּ\"ה. עָמַד עַל בֻּרְיוֹ פַּעַם רִאשׁוֹנָה וּפַעַם שְׁנִיָּה וְלֹא הִשְׁתַּנָּה לְעוֹלָם. וּבְנֵי יְהוּדָה וְזַרְעוֹ מוֹדִים וְאוֹמְרִים כִּי אַתָּה אָבִינוּ, מַה שֶּׁאֵין כֵּן לִשְׁאָר בְּנֵי הַגִּלְגּוּל לְעוֹלָמִים. שְׁאָר בְּנֵי הַגִּלְגּוּל, שְׁנֵי אָבוֹת, שְׁתֵּי אִמָּהוֹת, יֵשׁ לָהֶם גָּוֶן לַבִּנְיָן. וְסוֹדוֹת הַלָּלוּ בְּעִמְקֵי הַיָּם, הֵם בְּלֵב הַתְּהוֹמוֹת, מִי יָכוֹל לְהוֹצִיא אוֹתָם? קוּם זָקֵן, הִתְגַּבֵּר וְהִתְחַזֵּק בְּחָזְקְךְ וְהוֹצֵא מַרְגָּלִיּוֹת מִתּוֹךְ הַתְּהוֹמוֹת!"],[10,"","בֹּעַז נִרְאֶה שֶׁהָיָה בּוֹ שִׁנּוּי כְּשֶׁהוֹלִיד אֶת עוֹבֵד, שֶׁהֲרֵי עוֹבֵד (מעשה) הוּא בְּשִׁנּוּי. לֹא כָּךְ. אִבְצַן הוּא בּעַז, הוּא הָאָב הָרִאשׁוֹן שֶׁלֹּא עָשָׂה שִׁנּוּי. וְאִם תֹּאמַר שֶׁהוּא הָיָה, וַדַּאי כְּשֶׁהִתְעוֹרֵר לַמַּעֲשֶׂה הַזֶּה הָיָה בּוֹ, מִי שֶׁהוּא גִּבּוֹר כַּאֲרִי וּכְלָבִיא הָיָה בּוֹ, כְּדֵי שֶׁלֹּא יִהְיֶה שִׁנּוּי בְּדָוִד, וְחָזַר הַדָּבָר לָעִקָּר הָרִאשׁוֹן כְּדֵי שֶׁהַכֹּל יִהְיֶה מֵאָב אֶחָד, וְשַׁלְשֶׁלֶת אַחַת. וְהַכֹּל אֶחָד, וְלֹא הָיָה שִׁנּוּי בַּגִּלְגּוּל שֶׁל זֶרַע דָּוִד. וְעַל זֶה אַתָּה, מֵרֹאשׁ וְעַד סוֹף, בְּלִי שִׁנּוּי כְּלָל."]]],[["הַשְׁתָּא, נַפְקַת סָבָא, מֵעִמְקֵי לִבָּא דְּיַמָּא. יְהוּדָה אַתָּה, וַדַּאי מֵרֵישָׁא וְעַד סוֹפָא וְלָא אִתְחָזֵי לְכָל שְׁאַר בְּנִין, לְאִתְקְרֵי אַתָּה, אֶלָּא לֵיהּ בִּלְחוֹדוֹי. זַכָּאָה חוּלָקֵיהּ דְּדָוִד, דְּהָכִי אִתְבְּרִיר, וְאִסְתַּלָּק מִשְּׁאָר עִקָרָא דִּבְנֵי נָשָׁא בְּאַרְעָא.","יוֹדוּךָ אַחֶיךָ, יוֹדוּךָ כָּל בְּנֵי עָלְמָא מִבָּעֵי לֵיהּ, מַאי טַעְמָא אַחֶיךָ. אֶלָּא אֹרַח כָּל בְּנֵי עָלְמָא, לָא מִתְיַבְּמִין לְגִלְגּוּלָא, אֶלָּא מִסִּטְרָא דְּאַחִין, וְאָחָא אִזְדָּמַן לְיִּבוּמָא, (ואתה בגרמך, אזדמנת ליבומא.) וְהָכָא כֻּלְּהוּ אַחֶיךָ יוֹדוּךָ, דְּלָא יִשְׁתַּלְשֵׁל מִנַּיְיהוּ, וְלָא מֵחָד מִנַּיְיהוּ, שִׁלְשׁוּלָא דְּמַלְכוּ, אֶלָּא אַתָּה בִּלְחוֹדָךְ. אַתָּה, מֵרִישָׁא וְעַד סוֹפָא אַתָּה עַבְדַת, וּמִינָךְ נָפַק, כָּל שִׁלְשׁוּלָא וְגִזְעָא (דיוקנא וגופא) דְּאַרְיֵה.","בָּנֶיךָ, בְּנֵי אַרְיֵה, דְּלָא אִתְעֲבָרוּ לְשִׁנּוּיָא דְּאָחֶיךָ, לָא אִתְחְלָפוּ לְטָלֶה, וְלָא לְשׁוֹר, וְלָא לִגְדִי, וְלָא לְשׁוּם דִּיּוּקְנָא אַחֲרָא, אֶלָּא אַרְיֵה שָׁארֵי לְמִבְנֵי, וְאַרְיֵה סִיֵּים בִּנְיָינָא. כָּל שִׁלְשׁוּלָךְ, בְּנֵי אַרְיֵה נִינְהוּ. דְּאִלְמָלֵא אָתָא גִּלְגּוּלָא מִסִּטְרָא דְּאַחוּךְ, יִתְחַלְּפוּן כָּל דִּיּוּקְנִין, וְיִתְעָרְבוּן אִלֵּין בְּאִלֵּין. וְעַל דָּא יוֹדוּךָ אַחֶיךָ, דְּלָא הֲוָה חַד מִנְּהוֹן, בְּגִלְגּוּלָא דְּשַׁלְשְׁלָאָה דִּבְנָךְ. יָדְךָ זָקִיף, דְּלָא הֲוָה בָּךְ עִרְבּוּבְיָא אַחֲרָא מִנַּיְיהוּ.","וְהַיְינוּ מִטֶּרֶף בְּנִי עָלִית, דְּלָא הֲוָה טַרְפָּא לְאַחֲרָא עַל פָּתוֹרָךְ. כָּרַע, בְּמִיתַת עֵר. רָבַץ, בְּמִיתַת אוֹנָן. לְבָתַר אִתְגַּבָּר כַּאֲרִי, לְאָקָמָא לְפֶרֶץ. וּכְלָבִיא, לְאָקָמָא לְזֶרַח. מִי יְקִימֶנּוּ, דִּכְתִּיב, (בראשית ל״ח:כ״ו) וְלֹא יָסַף עוֹד לְדַעְתָּהּ. וְתַרְגּוּם וְלָא פָּסַק. מִי יְקִימֶנּוּ, מַאן הוּא דְּיֵימָא, אֲסוּרָה אִתְּתָא דָּא. מַאן הוּא דְּיֵימָא, הוֹאִיל וְאִשְׁלִימַת אָרְחָהָא, לָא אִצְטְרִיכָא לָךְ יַתִּיר, יְבָמָה דָּא, כֵּיוָן דְּאַשְׁלִימַת אָרְחָהָא, לָא אִצְטְרִיכַת לָךְ יַתִּיר, וְאִתְחֲזִיאַת לְאִתְפָּרְשָׁא מִינָהּ, אֲבָל מִי יְקִימֶנּוּ, וַדַּאי מִתַּמָּן וּלְהָלְאָה אִיהִי דִּילֵיהּ. דְּהָא אַפִּיק מַאן דִּמְכַשְׁכֵּשׁ בִּמְעָהָא.","רָזָא סְתִימָא הָכָא, אָחוּהָ דְּבַר נָשׁ אֲמַאי. תּוּ יְהוּדָה דְּהֲוָה אֲבוֹי אֲמַאי. אֶלָּא, הַהוּא דִּמְכַשְׁכֵּשָׁא בִּמְעָהָא, חָמֵי דְּמַאן דְּהֲוָה נָטִיר לֵיהּ, מְקַטְרֵג לֵיהּ קִטְרוּגִין, בְּכָל סִטְרִין. בָּעֵי לְאַפָּקָא. כֵּיוָן דְּנָפִיק, זַמִּין לְאַחֲרָא הַהוּא רוּחַ אַחֲרָא, וְאַתְיָין לְאָעָלָא כְּמִלְּקַדְּמִין, עַד דְּאִתְבְּנֵי כְּמִלְּקַדְּמִין, בְּחֵילָא דְּקִטְרוּגָא תַּקִּיף דְּקָא מְקַטְרֵג בְּאָחוּהּ. מִתַּמָּן וּלְהָלְאָה שָׁרִיאַת אִתְּתָא דָּא לֵיהּ.","זַכָּאָה חוּלָקָא דִּיהוּדָה, בְּקַדְמִיתָא הֲוָה גּוּר. לְבָתַר אַרְיֵה, דְּקָא אִתְגַּבָּר וְאִתְפָּשַּׁט בְּחֵילֵיהּ (ולבתר) אַרְיֵה. וְסִיֵּים בְּלָבִיא. כָּל שְׁאַר בְּנֵי עָלְמָא לָאו הָכִי, וְעַל דָּא יְהוּדָה כִּדְקַאָמְרָן.","רְאוּבֵן שִׁמְעוֹן לֵוִי, הָא תְּלָתָא, כִּדְקַאָמְרָן. יְהוּדָה אִתְחַבָּר בַּהֲדַיְיהוּ, וְכֹלָּא כְּדְקָא יֵאוֹת. יִשָּׂשׂכָר זְבוּלוּן, תְּרֵין יַרְכִין. אֲתָר דְּיַנְקֵי נְבִיאֵי קְשׁוֹט. יִשָּׂשׂכָר יַרְכָא יְמִינָא, כְּתִיב (דברי הימים א י״ב:ל״ג) וּמִבְּנִי יִשָּׂשׂכָר יוֹדְעֵי בִינָה לָעִתִּים (ס\"א זבולון ירכא שמאלא) וּכְתִיב, (דברים ל״ג:י״ח) שְׂמַח זְבוּלוּן בְּצֵאתֶךָ, וּבְשִׁעוּרָא רַבְרְבָא, כְּתִיב, (בראשית מ״ט:י״ג) זְבוּלוּן לְחוֹף יַמִּים יִשְׁכֹּן וְהוּא לְחוֹף אֳנִיּוֹת. מַאי טַעְמָא. בְּגִין דְּוְיַרְכָתוֹ עַל צִידוֹן. שִׁיעוּרָא (ס\"א דירך דידיה) עַד צִידוֹן.","בִּנְיָמִין, אִשְׁתְּאַר לְעֵילָּא בֵּין יַרְכִין, דְּהָא (בראשית קמ\"ג ע\"ב) יוֹסֵף הֲוָה דִּיּוּקְנֵיהּ בְּאַרְעָא, וּלְאִשְׁתַּמְּשָׁא בְּעָלְמָא דָּא, וְעִמֵּיהּ אִשְׁתָּמַּשׁ מֹשֶׁה, דִּכְתִּיב, (שמות י״ג:י״ט) וַיִּקַּח מֹשֶׁה אֶת עַצְמוֹת יוֹסֵף עִמּוֹ. בִּנְיָמִין אִסְתַּלָּק לְעֵילָּא, בִּנְיָמִין צַדִּיקוֹ דְּעָלְמָא.","מְבָרְכִין לְתַתָּא, דָּן וְנַפְתָּלִי גָּד וְאָשֵׁר. בְּיַרְכָא שְׂמָאלָא, דָּן עַד פִּרְקָא דְּרַגְלָא. פִּרְקָא דְּרַגְלָא נַפְתָּלִי. וּבְּגִין כָּךְ, נַפְתָּלִי אַיָּלָה שְׁלוּחָה, קַל בְּרַגְלוֹי. בְּיַרְכָא יְמִינָא. גָּד, וְהוּא יָגוּד עָקֵב, עַד פִּרְקָא דְּעָקֵב. אָשֵׁר פִּרְקָא דְּעָקֵב יְמִינָא. (דברים ל״ג:כ״ה) וְטוֹבֵל בַּשֶּׁמֶן רַגְלוֹ. וּכְתִיב בַּרְזֶל וּנְחֹשֶׁת מִנְעָלֶיךָ. כָּל אִלֵּין, אִינּוּן דִּיּוּקְנִין עִלָּאִין, דִּיּוּקְנָא דִּלְעֵילָּא. וּבְגִין דַּהֲווֹ בִּרְיָין מַמָּשׁ בְּהַאי עָלְמָא, אִתַקְנַת בְּהוּ שְׁכִינְתָּא, בְּאִלֵּין תְּרֵיסַר פִּרְקִין, תְּרֵיסַר מְתִיחִין, דְּאִתְמְתָחוּ מִיִּשְׂרָאֵל מַמָּשׁ. דִּכְתִּיב, (בראשית מ״ט:כ״ח) כָּל אֵלֶּה שִׁבְטֵי יִשְׂרָאֵל שְׁנֵים עָשָׂר. מְתִיחִין דְּיִשְׂרָאֵל, אֵלֶּה אִקְרוּן. לְאִתְמַתְּחָא שְׁמָא דְּמִ\"י, לְמֶהוֵי בִּנְיָינָא כַּדְקָא יֵאוֹת, לְמֶהֱוֵי יִשְׂרָאֵל בִּכְלָלָא דִּשְׁמָא דֶּאֱלהִים. אֵלֶּ\"ה אִיהוּ יִשְׂרָאֵל בִּכְלָל. מִ\"י חִבֵּר (נ\"א ברא) אֵלֶּה בַּהֲדֵיהּ, וַהֲוָה בִּנְיָינָא שְׁלִים עַל תְקּוּנֵיהּ, שְׁמָא חֲדָא מַמָּשׁ."],[[0,"השתא נפקת סבא וכו':","עתה יצאת, זקן, מעומק לב הים, יהודה אתה, ודאי מראש ועד סוף, ואינו ראוי לכל שאר הבנים שיקראו אתה, חוץ לו לבדו. אשרי חלקו של דוד, שנברר כן, ועלה משאר שורשי בני אדם בארץ."],[1,"יודוך אחיך:","שואל, יודוך כל בני העולם היה צריך לומר, מה הטעם, שאומר, אחיך. ומשיב, אלא דרך כל בני העולם, אינם מיבמים לגלגול המת בלי בנים, אלא מצד האחים, והאח מזדמן ליבום, ואתה, בעצמך הזדמנת ליבום. וכאן כל אחיך יודוך, שלא נשתלשלה מהם, ולא מאחד מהם, שלשלת המלוכה, אלא אתה בלבדך. אתה, מראש ועד סוף אתה עשית, וממך יצא כל השלשלת והגזע של אריה."],[2,"בניך בני אריה וכו':","בניך בני אריה, שלא נעברו לשינוי של אחיך, ולא נחלפו לא לטלה ולא לשור ולא לגדי, כי י\"ב צורות הן בי\"ב מזלות, שהם כנגד י\"ב שבטים. ובני יהודה כולם היו בצורת אריה, ולא בצורות שאר השבטים. אלא אריה התחיל לבנות ואריה השלים הבנין. כל שלשלת שלך בני אריה הם, שאם היה בא גלגול מצד אחיך בבניך, היו מתחלפות כל הצורות והיו מתערבות אלו באלו. ועל זה יודוך אחיך, שלא היה אחד מהם בגלגול בתוך השלשלת של בניך. ידך הרם, שלא היה בך ערבוב אחד מהם."],[3,"והיינו מטרף וגו':","והיינו \u0003מטרף בני עלית.\u0004 שלא היה טרף ומזון לאחר על שלחנך. \u0003כרע\u0004 במיתת ער. \u0003רבץ,\u0004 במיתת אונן. ואח\"כ התגבר \u0003כארי\u0004 להקים את פרץ. \u0003וכלביא,\u0004 להקים את זרח. מי \u0003יקימנו,\u0004 שכתוב, ולא יסף עוד לדעתה, ותרגום, לא פסק. וזהו \u0003מי יקימנו,\u0004 מי הוא שאמר שאשה זו אסורה, מי הוא שיאמר כיון שהשלימה דרכיה, אינה נצרכת לך יותר, שיבמה זו, כיון שהשלימה דרכיה אינה נצרכה לך יותר, וראוי לפרוש ממנה, אבל \u0003מי יקימנהו,\u0004 ודאי משם ולהלאה היא שלו. כי הוציאה מי שמכשכש במעיה. דהיינו הרוח של בעלה הראשון שעזב בה בביאה הראשונה, והוא מכשכש במעיה. ועתה הוציאתו."],[4,"רזא סתימא הכא וכו':","סוד סתום כאן. אחיו של האדם למה מיבם את אשתו. ועוד יהודה שהוא אביו למה יבם את אשתו. ולמה לא אדם זר שאינו קרוב. ומשיב, אלא ההוא שמכשכש במעיה של היבמה, דהיינו הרוח שעזב בה בעלה המת, רואה שמי שהוא שומר אותו, דהיינו הקרוב שלו, מקטרג עליו קטרוגים בכל הצדדים. ואם היה אדם זר היה דוחה אותו, (כנ\"ל אות קמ\"ו) אבל לקרובו אינו רוצה לדחותו, לכן רוצה לצאת משם. כיון שיוצא מזמין את האחר, דהיינו רוח ההוא האחר העיקרי של המת, ובאים שניהם להכנס במעי האשה כבתחילה, עד שהוא נבנה כבתחילה, דהיינו שנתגלגל בטפה הזרעית של היבם. שזה היה בכח הקטרוג חזק שקטרג על אחיו. שעל כן החליט לצאת ממנה כנ\"ל. ומשם ולהלאה מותרת לו אשה הזו. כי כבר יצא רוח המקטרג ממנה. וע\"כ צריך הקרוב ליבם אותה, כי אדם זר שאינו קרוב, היה הרוח דוחה אותו."],[5,"זכאה חולקיה דיהודה וכו':","אשרי חלקו של יהודה בתחלה היה \u0003גור,\u0004 ואחר כך \u0003אריה,\u0004 שנתגבר ונתפשט בכחו כאריה. וסיים \u0003בלביא.\u0004 כל שאר בני העולם אינו כן. ועל כן יהודה אתה, כמו שאמרנו."],[6,"ראובן שמעון וכו':","ראובן שמעון לוי, הרי שלשה, כמו שאמרנו, שהם חג\"ת. יהודה נתחבר עמהם, שהוא מלכות, והכל כראוי. יששכר זבולון שתי ירכים, שהם נצח והוד, המקום שיונקים ממנו נביאי אמת. יששכר הוא ירך ימין, שהוא נצח. כתוב, ומבני יששכר יודעי בינה לעתים, שפירושו שהנצח ממשיך אור הבינה אל המלכות הנקראת \u0003עתים.\u0004 וכתוב, שמח זבולון בצאתך, שפירושו שההוד הוא סיום ה' הספירות חג\"ת נ\"ה, שהוא שיעור התפשטות אור הבינה, שממנו ולמטה נבחן \u0003ליציאה\u0004 מן המדרגות. ובשיעור גדול, יש ז' ספירות חג\"ת נהי\"מ, ואז כתוב, זבולון לחוף ימים ישכן, והוא לחוף אניות, דהיינו עד המלכות הנקראת ים ונקראת אניה. מה הטעם ששוכן עד המלכות, הוא משום וירכתו על צדון, ששיעור הירך שלו שהוא הוד, מתפשט עד המלכות שנקראת צדון."],[7,"בנימין אשתאר לעילא וכו':","בנימין נשאר למעלה בין הירכים, שהוא יסוד, ואע\"פ שיוסף הוא יסוד, יוסף היה צורתו בארץ, שהוא המלכות, ולהשתמש בעולם הזה, שהוא המלכות, ועמו השתמש משה, שכתוב, ויקח משה את עצמות יוסף עמו. בנימין, נתעלה למעלה ביסוד דז\"א, ובנימין צדיק העולם, שהוא יסוד. וכבר נתבאר היטב (לעיל ויצא ע\"ב ד\"ה פירוש) ההפרש שבין יוסף לבנימין עש\"ה."],[8,"מברכין ולתתא וכו':","מן הברכים ולמטה, שיש עוד ב' פרקים, הם דן ונפתלי גד ואשר. בירך השמאלית, דן עד הפרק של הרגל, דהיינו בפרק האמצעי, נפתלי, הוא בפרק הרגל, דהיינו פרק התחתון. ומשום זה, נפתלי אילה שלוחה, שהוא קל ברגליו. בירך הימין, גד, והוא יגוד עקב, היינו עד הפרק של העקב, שהוא פרק האמצעי, אשר, בפרק העקב הימין, דהיינו פרק התחתון, וז\"ש וטובל בשמן רגלו. וכתוב ברזל ונחשת מנעליך. באופן שבג' פרקים של ירך הימין, נמצא יששכר בפרק העליון, וגד באמצעי, ואשר בתחתון. ובג' פרקים של ירך השמאל, נמצא זבולון בפרק העליון, ודן באמצעי, ונפתלי בתחתון."],[8,"כל אלין וכו':","כל אלו, י\"ב השבטים, הם צורות עליונות בצורה שלמעלה. ומשום שהיו בריות ממש בעולם הזה, נתתקן בהם השכינה, באלו י\"ב פרקים, שהם י\"ב המשכות שנמשכו מישראל ממש, שהוא ז\"א, שכתוב, כל \u0003אלה\u0004 שבטי ישראל שנים עשר. ההמשכות של ישראל נקראים \u0003אל\"ה\u0004 להתפשט בהם השם \u0003מ\"י,\u0004 שיהיה הבנין כראוי, שיהיה ישראל בכלל השם \u0003אלקים, אל\"ה\u0004 הוא ישראל בכלל, \u0003מ\"י\u0004 מחבר עמו \u0003אל\"ה,\u0004 ויהיה הבנין שלם על תקונו, שם אחד ממש."],[8,"","ביאור הדברים. כי נודע שבעת השפעת הקטנות, עולה המלכות למקום בינה שבכל מדרגה, שאז נבקעת כל מדרגה לשתים, כי המלכות שעלתה למקום בינה, סיימה שם המדרגה מתחת לחכמה, ולא נשאר בכל מדרגה אלא ב' ספירות כתר וחכמה, וג' ספירות, בינה ות\"ת ומלכות שבכל מדרגה נפלו למדרגה שמתחתיה. ואלו ה' ספירות כח\"ב תו\"מ, ה\"ס ה' אותיות של השם \u0003אלקים,\u0004 ונבחן שב' אותיות \u0003מ\"י\u0004 דאלקים, שהם כו\"ח, נשארו במדרגה, וג' אותיות \u0003אל\"ה,\u0004 שהם בינה ות\"ת ומלכות נפלו מכל מדרגה למדרגה שמתחתיה. באפן, שב' אותיות \u0003מ\"י\u0004 נשארו בבינה, וג' אותיות \u0003אל\"ה\u0004 נפלו למדרגה שמתחתיה, שהיא זו\"ן. וכן בזו\"ן נשארו ב' אותיות \u0003מ\"י\u0004 של מדרגתם, וג' אותיות \u0003אל\"ה\u0004 נפלו למדרגה שמתחתיהם, שהם נשמות הצדיקים."],[8,"","ולעת גדלות, חוזרת המלכות ויורדת ממקום בינה למקומה עצמה, ונתבטל מסך המלכות שבקע כל מדרגה, ואז עולות בחזרה, כל חצאי מדרגות התחתונות שנפלו ממדרגתם, ומתחברות עם העליונות, דהיינו שחוזרות למדרגתם, ואותיות \u0003אל\"ה\u0004 דבינה שנפלו לזו\"ן, חוזרות ועולות לבינה, ומתחברות לאחת עם ב' אותיות מ\"י שנשארו בה. ונשלם השם \u0003אלקים.\u0004 דהיינו ה' כלים כח\"ב תו\"מ, עם ה' אורות נרנח\"י. ואז כיון שאותיות \u0003אל\"ה\u0004 דבינה היו בזו\"ן, הנה כשעולות לוקחות עמהן גם זו\"ן שהיו מלובשות שם. וזו\"ן מקבלים שם מוחין דבינה. ועד\"ז כשעולות אל\"ה דזו\"ן, שהיו נפולות בנשמות הצדיקים, ומתחברות בב' אותיות מ\"י דזו\"ן, ונשלם בהם השם \u0003אלקים,\u0004 לוקחת עמהם גם נשמות הצדיקים שהיו לבושות בהן, והנשמות מקבלות שם המוחין דזו\"ן. (כמ\"ש כל זה באורך, לעיל בהקדמת ספר הזוהר, באות י\"ג ואות י\"ד ובאות י\"ז בהסולם, עש\"ה)."],[8,"","ויש בזה ב' בנינים, בנין א', הוא, חזרת אתוון \u0003אל\"ה\u0004 לאותיות מ\"י שנשלם בזה השם \u0003אלקים,\u0004 כנ\"ל. וה\"ס נקודת השורק. בנין ב', עלית קו אמצעי למ\"ן בסוד המסך שבו, הממעט הג\"ר דג\"ר ומלביש החכמה בחסדים, שזה נקודת החירק. (כמ\"ש לעיל בראשית א' דף ט\"ו ד\"ה ההוא. ע\"ש)."],[8,"","וזה אמרו, \u0003מתיחין דישראל אל\"ה אקרון.\u0004 היינו חצי מדרגה התחתונה בינה ות\"ת ומלכות דזו\"ן, הנק' ג' אותיות \u0003אל\"ה,\u0004 שנפלו לנשמות הצדיקים. וע\"כ אמר מקודם לכן, \u0003מתיחין דאתמתחו מישראל ממש,\u0004 דהיינו מישראל העליון שהוא ז\"א. וזהו בעת קטנות, ולעת גדלות. \u0003לאתמתחא שמא דמ\"י למהוי בניינא כדקא יאות,\u0004 שלעת גדלות חוזרות אותיות מ\"י ומתחברות עם אותיות אל\"ה והבנין של השם אלקים נשלם בזו\"ן. ואז עולות עם האותיות אל\"ה, גם נשמות הצדיקים שהן היו לבושות שמה, כנ\"ל. וז\"ש \u0003למהוי ישראל בכללא דשמא דאלקים,\u0004 והיינו ישראל שלמטה שהם השבטים שעולות עם האותיות אל\"ה הנשלמות ב \u0003מ\"י,\u0004 ונכללות גם הן בשם אלקים הנשלם. כנ\"ל. וז\"ש \u0003אל\"ה איהו ישראל בכלל,\u0004 דהיינו השבטים, \u0003מ\"י חבר אל\"ה בהדיה,\u0004 היינו אחר שיורדת המלכות למקומה, חוזרות מ\"י ומתחברות באל\"ה כנ\"ל. \u0003והוה בניינא שלים על תקוניה,\u0004 שב' חצאי המדרגות \u0003מ\"י אל\"ה,\u0004 מתחברות ונבנות יחד לבנין אחד שלם, \u0003שמא חדא ממש,\u0004 דהיינו לשם \u0003אלקים.\u0004"]],[[0,"","עֵכְשָׁו יָצָאתָ זָקֵן מֵעֹמֶק שֶׁל לֵב הַיָּם. יְהוּדָה אַתָּה, וַדַּאי מֵרֹאשׁ וְעַד סוֹף, וְלֹא רָאוּי לְכָל שְׁאָר הַבָּנִים שֶׁיִּקָּרְאוּ אַתָּה, אֶלָּא לוֹ לְבַדּוֹ. אַשְׁרֵי חֶלְקוֹ שֶׁל דָּוִד שֶׁכָּךְ נִבְחַר וְהִתְעַלָּה מִשְּׁאָר הָעִקָּר שֶׁל אָדָם בָּאָרֶץ."],[1,"","יוֹדוּךָ אַחֶיךְ, יוֹדוּךְ כָּל בְּנֵי הָעוֹלָם הָיָה צָרִיךְ לִהְיוֹת! מָה הַטַּעַם אַחֶיךְ? אֶלָּא שֶׁדֶּרֶךְ כָּל בְּנֵי הָעוֹלָם לֹא מִתְיַבְּמִים לְגִלְגּוּל אֶלָּא מֵהַצַּד שֶׁל הָאַחִים, וְהָאָח מְזֻמָּן לְיִבּוּם, (ואתה בעצמך הזדמנת ליבום), וְכָאן כָּל אַחֶיךְ יוֹדוּךְ, שֶׁלֹּא יִשְׁתַּלְשֵׁל מֵהֶם וְלֹא מֵאֶחָד מֵהֶם שַׁלְשֶׁלֶת הַמְּלוּכָה, אֶלָּא אַתָּה לְבַדְּךְ. אַתָּה מֵרֹאשׁ וְעַד סוֹף אַתָּה עָשִׂיתָ, וּמִמְּךְ יָצָא כָּל הַשַּׁלְשֶׁלֶת וְגֶזַע (דמות וגוף) שֶׁל הָאַרְיֵה."],[2,"","בָּנֶיךָ בְּנֵי אַרְיֵה, שֶׁלֹּא עָבְרוּ לְשִׁנּוּי שֶׁל אַחֶיךְ, לֹא הִתְחַלְּפוּ לְטָלֶה וְלֹא לְשׁוֹר וְלֹא לִגְדִי וְלֹא לְשׁוּם דְּיוֹקָן אַחֵר, אֶלָּא אַרְיֵה הִתְחִיל לִבְנוֹת, וְאַרְיֵה סִיֵּם אֶת הַבִּנְיָן. כָּל הַשַּׁלְשֶׁלֶת שֶׁלְּךְ הֵם בְּנֵי אַרְיֵה, שֶׁאִלְמָלֵא בָּא גִלְגּוּל מִצַּד אַחֶיךְ, יִתְחַלְּפוּ כָּל הַדְּיוֹקְנָאוֹת וְיִתְעָרְבוּ אֵלֶּה בְאֵלֶּה. וְלָכֵן יוֹדוּךְ אַחֶיךְ, שֶׁלֹּא הָיָה אֶחָד מֵהֶם בְּגִלְגּוּל הַשַּׁלְשֶׁלֶת שֶׁל בָּנֶיךְ. יָדְךְ הָרֵם, שֶׁלֹּא הָיָה בְּךְ עִרְבּוּבְיָה אַחֶרֶת מֵהֶם."],[3,"","וְהַיְנוּ מִטֶּרֶף בְּנִי עָלִיתָ, שֶׁלֹּא הָיָה טֶרֶף לְאַחֵר עַל שֻׁלְחָנְךְ. כָּרַע - בְּמִיתַת עֵר. רָבַץ - בְּמִיתַת אוֹנָן. אַחַר כָּךְ הִתְגַּבֵּר כַּאֲרִי לְהָקִים אֶת פֶּרֶץ, וּכְלָבִיא לְהָקִים אֶת זֶרַח. מִי יְקִימֶנּוּ? שֶׁכָּתוּב (בראשית לח) וְלֹא יָסַף עוֹד לְדַעְתָּהּ, וְתַרְגּוּם: וְלָא פָסַק. מִי יְקִימֶנּוּ, מִי הוּא שֶׁאָמַר אֲסוּרָה אִשָּׁה זוֹ. מִי הוּא שֶׁאָמַר, הוֹאִיל וְהִשְׁלִימָה אֶת צְרָכֶיהָ, לֹא הִצְטָרְכָה לְךְ יוֹתֵר, יְבָמָה זוֹ, כֵּיוָן שֶׁהִשְׁלִימָה דְרָכֶיהָ, לֹא הִצְטָרְכָה לְךְ יוֹתֵר, וְנִרְאֵית לִפְרשׁ מִמֶּנָּה. אֲבָל מִי יְקִימֶנּוּ, וַדַּאי שֶׁמִּשָּׁם וָהָלְאָה הִיא שֶׁלּוֹ, שֶׁהֲרֵי הוֹצִיאָה מִי שֶׁמְּכַשְׁכֵּשׁ בְּמֵעֶיהָ."],[4,"","סוֹד נִסְתָּר כָּאן, אֲחֵי הָאָדָם לָמָּה? וְעוֹד, יְהוּדָה שֶׁהָיָה אָבִיו לָמָּה? אֶלָּא אוֹתוֹ שֶׁמְּכַשְׁכֵּשׁ בְּמֵעֶיהָ רוֹאֶה שֶׁמִּי שֶׁשּׁוֹמֵר אוֹתוֹ, מְקַטְרֵג עָלָיו קִטְרוּגִים בְּכָל הַצְּדָדִים וְרוֹצֶה לָצֵאת. כֵּיוָן שֶׁיָּצָא, מַזְמִין אַחֵר אוֹתָהּ רוּחַ אַחֶרֶת, וּבָאִים לְהִכָּנֵס כְּמוֹ מִקֹּדֶם, עַד שֶׁנִּבְנֶה כְּמוֹ מִקֹּדֶם בְּכֹחַ הַקִּטְרוּג הַקָּשֶׁה שֶׁמְּקַטְרֵג בְּאָחִיו. מִשָּׁם וָהָלְאָה מֻתֶּרֶת לוֹ הָאִשָּׁה הַזּוֹ."],[5,"","אַשְׁרֵי חֶלְקוֹ שֶׁל יְהוּדָה. בַּהַתְחָלָה הָיָה גּוּר. אַחַר כָּךְ אַרְיֵה, שֶׁמִּתְגַּבֵּר וּמִתְפַּשֵּׁט בְּכֹחוֹ (ואחר כך) כְּאַרְיֵה. וְסִיֵּם בְּלָבִיא. כָּל שְׁאָר בְּנֵי הָעוֹלָם לֹא כָּךְ, וְעַל זֶה יְהוּדָה, כְּמוֹ שֶׁאָמַרְנוּ."],[6,"","רְאוּבֵן שִׁמְעוֹן לֵוִי - הֲרֵי שְׁלֹשָׁה, כְּמוֹ שֶׁאָמַרְנוּ. יְהוּדָה הִתְחַבֵּר עִמָּם, וְהַכֹּל כָּרָאוּי. יִשָּׂשכָר וּזְבוּלוּן שְׁתֵּי יְרֵכַיִם. מָקוֹם שֶׁיּוֹנְקִים נְבִיאֵי הָאֱמֶת. יִשָּׂשכָר יָרֵךְ יָמִין, כָּתוּב וּמִבְּנֵי יִשָּׂשכָר יוֹדְעֵי בִינָה לָעִתִּים (זבולון ירך שמאל), וְכָתוּב (דברים לג) שְׂמַח זְבוּלֻן בְּצֵאתֶךְ. וּבְשִׁעוּר גָּדוֹל כָּתוּב (בראשית מט) זְבוּלֻן לְחוֹף יַמִּים יִשְׁכֹּן וְהוּא לְחוֹף אֳנִיֹּת. מָה הַטַּעַם? מִשּׁוּם שֶׁוְּיַרְכָתוֹ עַל צִידן. שִׁעוּר (הירך שלו) עַד צִידוֹן."],[7,"","בִּנְיָמִין נִשְׁאָר לְמַעְלָה בֵּין הַיְרֵכַיִם, שֶׁהֲרֵי יוֹסֵף הָיָה דְיוֹקְנוֹ בָּאָרֶץ, וּלְהִשְׁתַּמֵּשׁ בָּעוֹלָם הַזֶּה, וְעִמּוֹ הִשְׁתַּמֵּשׁ מֹשֶׁה, שֶׁכָּתוּב (שמות יג) וַיִּקַּח מֹשֶׁה אֶת עַצְמוֹת יוֹסֵף עִמּוֹ. בִּנְיָמִין הִסְתַּלֵּק לְמַעְלָה, בִּנְיָמִין צַדִּיקוֹ שֶׁל עוֹלָם."],[8,"","מְבָרְכִים לְמַטָּה - דָּן וְנַפְתָּלִי גָּד וְאָשֵׁר. בְּיֶרֶךְ שְׂמֹאל - דָּן עַד פֶּרֶק הָרֶגֶל, פֶּרֶק הָרֶגֶל נַפְתָּלִי, וּמִשּׁוּם כָּךְ נַפְתָּלִי אַיָּלָה שְׁלֻחָה, קַל בְּרַגְלָיו. בְּיֶרֶךְ יָמִין גָּד, וְהוּא יָגֻד עָקֵב, עַד פֶּרֶק הֶעָקֵב. אָשֵׁר פֶּרֶק שֶׁל עָקֵב יָמִין, וְטֹבֵל בַּשֶּׁמֶן רַגְלוֹ, וְכָתוּב בַּרְזֶל וּנְחֹשֶׁת מִנְעָלֶיךְ. כָּל אֵלֶּה הֵם דְּיוֹקְנָאוֹת עֶלְיוֹנִים, דְּיוֹקָן שֶׁלְּמַעְלָה. וּמִשּׁוּם שֶׁהָיוּ בְּרִיּוֹת מַמָּשׁ בָּעוֹלָם הַזֶּה, נִתְקְנָה בָהֶם הַשְּׁכִינָה בִּשְׁנֵים עָשָׂר הַפְּרָקִים הַלָּלוּ שְׁתֵּים עֶשְׂרֵה הִתְפַּשְּׁטֻיּוֹת שֶׁנִּתְפַּשְּׁטוּ מַמָּשׁ מִיִּשְׂרָאֵל, שֶׁכָּתוּב כָּל אֵלֶּה שִׁבְטֵי יִשְׂרָאֵל שְׁנֵים עָשָׂר. הִתְפַּשְּׁטֻיּוֹת שֶׁל יִשְׂרָאֵל, אֵלֶּה נִקְרָאִים. לְהִתְפַּשְּׁטוּת שֵׁם שֶׁל מִ\"י לִהְיוֹת בִּנְיָן כָּרָאוּי, לִהְיוֹת יִשְׂרָאֵל בִּכְלָל שֶׁל שֵׁם אֱלֹהִים. אֵלֶּ\"ה הוּא יִשְׂרָאֵל בִּכְלָל. מִ\"י חִבֵּר (ברא) אֵלֶּה עִמּוֹ, וְהָיָה בִּנְיָן שָׁלֵם עַל תִּקּוּנוֹ, שֵׁם אֶחָד מַמָּשׁ."]]],[["הֲדָא הוּא דְּאָמַר לֵיהּ לְיַעֲקֹב, הַהוּא מְמָנָא דְּעֵשָׂו, דִּכְתִּיב, (בראשית ל״ב:כ״ט) כִּי שָׂרִיתָ עִם אֱלהִים, (עם אנשים ותוכל) לְעֵילָּא, בְּתִקּוּנָא קַדְמָאָה, בְּבִנְיָינָא קַדְמָאָה. כָּל אֵלֶּה, וַדַּאי בִּנְיָינָא קַדְמָאָה אִיהוּ.","וְעַל דָּא, לֵית שְׁצִיאוּ לְיִשְׂרָאֵל, לְעָלַם וּלְעָלְמֵי עָלְמִין. וְחָס וְשָׁלוֹם אִלְמָלֵא יִשְׁתְּצִיאוּ, שְׁמָא דָּא לָא הֲוֵי, הֲדָא הוּא דִכְתִיב, (יהושע ז׳:ט׳) וְהִכְרִיתוּ אֶת שְׁמֵנוּ מִן הָאָרֶץ וּמַה תַּעֲשֵׂה לְשִׁמְךָ הַגָּדוֹל. שְׁמָא גָּדוֹל, דָּא, בִּנְיָינָא קַדְמָאָה, שְׁמָא קַדְמָאָה אֱלֹהִים. וְהַשְׁתָּא דְּיִשְׂרָאֵל אִינּוּן בְּגָלוּתָא, כִּבְיָכוֹל כָּל בִּנְיָינָא נָפַל. לְזִמְנָא דְּאָתֵי, כַּד יִפְרוֹק קוּדְשָׁא בְּרִיךְ הוּא לִבְנוֹי מִגָּלוּתָא, (מתחבר) מִ\"י וְאֵלֶּ\"ה דְּהֲוָה בְּפֵרוּדָא בְּגָלוּתָא, יִתְחַבְּרוּן כַּחֲדָא, וּשְׁמָא דֶּאֱלֹהִים יְהֵא שְׁלִים עַל תְקּוּנֵיהּ, וְעָלְמָא יִתְבְּסָם. הֲדָא הוּא דִכְתִיב, (ישעיהו ס׳:ח׳) מִי אֵלֶּה כָּעָב תְּעוּפֶינָּה וְכַיּוֹנִים אֶל אֲרֻבֹּתֵיהֶם.","וּבְגִין דְּאִיהוּ שְׁמָא חֲדָא, לָא כְּתִיב מִי וְאֵלֶּה, אֶלָּא מִי אֵלֶּה, שְׁמָא חֲדָא, בְּלָא פִּרוּדָא, וְהוּא אֱלֹהִים. דְּהַשְׁתָּא בְּגָלוּתָא, אִסְתַּלָּק מִי לְעֵילָּא, כִּבְיָכוֹל אִימָא מֵעַל בְּנִין. וּבְנִין נַפְלוּ. וּשְׁמָא דְּהֲוָה שְׁלִים, דְּהוּא שְׁמָא עִלָּאָה רַבְרְבָא קַדְמָאָה, נָפִיל.","וְעַל דָּא, אֲנָן מְצָלָן, וּמְקַדְּשָׁן בְּבָתֵּי כְּנֵסִיּוֹת, עַל שְׁמָא דָּא, דְּיִתְבְּנֵי כְּמָה דְּהֲוָה. וְאַמְרֵי יִתְגַּדַּל וְיִתְקַדַּשׁ שְׁמֵיהּ רַבָּא. אָמֵן (קס\"ה ע\"ב) יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ. מַאן שְׁמֵיהּ רַבָּא. הַהוּא קַדְמָאָה דְּכֹלָּא, בְּגִין דְּלֵית לֵיהּ בִּנְיָינָא אֶלָּא בַּהֲדָן. מִ\"י לָא יִתְבְּנִי לְעוֹלָם, אֶלָּא בְּאֵלֶּה. וְעַל דָּא, בְּהַהוּא זִמְנָא, מִי אֵלֶּה כָּעָב תְּעוּפֶינָּה. וְיֶחמוּן כָּל עָלְמָא, דְּהָא שְׁמָא עִלָּאָה אִתְתָּקַּן עַל תְקּוּנֵיהּ.","וְאִי שְׁמֵיהּ רַבָּא דָּא אִתְקַּן, וְאִתְבְּנִי עַל תְקּוּנֵיהּ, הָא יִשְׂרָאֵל שַׁלִּיטִין עַל כֹּלָּא, וְכָל שְׁאַר שְׁמָהָן יִתְהַדְּרוּן עַל תִּקּוּנַיְיהוּ, וְיִשְׂרָאֵל שַׁלִּיטִין עַל כֹּלָּא, דְּהָא כֻּלְּהוּ תַּלְיָין בִּשְׁמֵיהּ רַבָּא, קַדְמָאָה לְכָל בִּנְיָינִין.","רָזָא דָּא, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמִין. קַדְמָאָה לְכָל בִּנְיָינִין, שְׁמָא דָּא אִתְבְּנֵי. דִּכְתִּיב, (ישעיהו מ׳:כ״ו) שְׂאוּ מָרוֹם עֵינֵיכֶם וּרְאוּ מִי בָרָא אֵלֶּה, בָּרָא שְׁמֵיהּ עַל תְקּוּנֵיהּ, וְכַד בָּרָא אֵלֶּה, בָּרָא (שמיה) לֵיהּ בְּכָל חֵילִין דְּיִתְחֲזוּן לֵיהּ, לְמֶהֱוֵי שְׁמֵיהּ עַל תְקּוּנֵיהּ כְּדְקָא יֵאוֹת, דִּכְתִּיב, (ישעיהו מ׳:כ״ו) הַמּוֹצִיא בְּמִסְפָּר צְבָאָם.","מַאי בְּמִסְפָּר. אֶלָּא בְּרָא חַד דְּנָהִיר מִסַּיְיפֵי עָלְמָא עַד סַיְיפֵי עָלְמָא, אִית לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְהוּא אִילָנָא רַבָּא וְתַקִּיף. רֵישֵׁיהּ מָטֵי לְצֵית שְׁמַיָּא, וְסוֹפֵיהּ מַתְחִן שָׁרְשׁוֹי, וְאִשְׁתָּרְשָׁן בֶּעָפָר קַדִּישָׁא, וּמִסְפָּר שְׁמֵיהּ. וְתַלְיָא בַּשָּׁמַיִם עִלָּאִין, וְחָמֵשׁ רְקִיעִין תַּלְיָין מִנֵּיהּ, עַד הַאי מִסְפָּר, וְכֻלְּהוּ נַטְלִין שְׁמָא דָּא בְּגִינֵיהּ דִּכְתִּיב, (תהילים י״ט:ב׳) הַשָּׁמַיִם מְסַפְּרִים, בְּגִין הַאי מִסְפָּר, כֻּלְּהוּ (ד\"א בגין האי שמא מספר) שָׁמַיִם רַוְוחִין שְׁמָא דָּא בְּגִינֵיהּ, וְעַל דָּא הַמּוֹצִיא בְּמִסְפָּר צְבָאָם, דְּאִלְמָלֵא מִסְפָּר דָּא, לָא יִשְׁתְּכְּחוּן חַיָּילִין וְתּוֹלָדִין לְעָלְמִין.","וְעַל דָּא כְּתִיב, (במדבר כ״ג:י׳) מִי מָנָה עֲפַר יַעֲקֹב וּמִסְפָּר אֶת רֹבַע יִשְׂרָאֵל, תְּרֵין אִינּוּן, דְּמָנוּ עָאנָא, וְעָאלוּ בְּחוּשְׁבָּנָא עַל יְדַיְיהוּ, בְּגִין דְּלָא שַׁלְטָא בְּהוּ עֵינָא בִּישָׁא. מִי מָנָה עֲפַר יַעֲקֹב, הָא חַד, דְּעָבִיד חוּשְׁבָּנָא. וּמִסְפָּר אֶת רֹבַע יִשְׂרָאֵל, הָא מוֹנֶה אַחֲרָא.","וְעַל תְּרֵין אִלֵּין לָא שַׁלְטָא בְּהוּ עֵינָא בִּישָׁא, דְּהָא מִי מָנָה לְעָפָר יַעֲקֹב, אִלֵּין אִינּוּן אֲבָנִין (ד\"א דרגין) קַדִּישִׁין, אֲבָנִין מְפוּלָמִין, דְּמִנְּהוֹן נַפְקֵי מַיִין לְעָלְמָא. וְעַל דָּא כְּתִיב (בראשית כ״ח:י״ד) וְהָיָה זַרְעֲךָ כַּעֲפַר הָאָרֶץ. מַה הַהוּא (וישלח ק\"ע) עֲפַר, עָלְמָא מִתְבָּרִךְ בְּגִינֵיהּ. אוּף הָכִי (בראשית כ״ב:י״ח) וְהִתְבָּרַכוּ בְזַרְעֲךָ כָּל גּוֹיֵי הָאָרֶץ. כַּעֲפַר הָאָרֶץ מַמָּשׁ. וּמִסְפָּר דְּאִיהוּ מוֹנֶה תִּנְיָינָא, מָנָה לְרֹבַע כָּל אִינּוּן נוּקְבִין, מַרְגְּלָן עִלָּאִין, דְּמִטָּה דְּשָׁכִיב עָלֵיהּ יִשְׂרָאֵל."],[[0,"הדא הוא דאמר וכו':","זה הוא שאמר ליעקב, ממונה ההוא של עשו, שכתוב, כי שרית עם \u0003אלקים,\u0004 היינו למעלה, שעלה עם אותיות \u0003אל\"ה\u0004 דזו\"ן ונכלל בשם \u0003אלקים,\u0004 אשר נתחבר ונשלם שם, בתקון הא' בבנין הא', היינו בבנין של סוד נקודת השורק, כמבואר בדבור הסמוך. כל \u0003אלה\u0004 שבטי ישראל, ודאי בנין ראשון הוא, כי התחברות \u0003מ\"י\u0004 ב \u0003אל\"ה\u0004 נעשה בבנין א' כנ\"ל."],[1,"ועל דא לית וכו':","ועל כן אין כליה לישראל לעולם ולעולמי עולמים. וחס ושלום, אם היו כלים, שם הזה אלקים, לא היה, כי ג' אותיות אל\"ה מאלקים מלובשות בנשמות ישראל כנ\"ל בדבור הסמוך, ז\"ש והכריתו את שמנו מן הארץ ומה תעשה לשמך הגדול. היינו שם גדול הזה, בנין הראשון, שם הראשון, \u0003אלקים.\u0004 שהיה נחסר מאותיות אל\"ה המלובשות בנשמות ישראל, ועתה שישראל הם בגלות, כביכול, כל הבנין נפל, שחסרים אותיות אל\"ה מן בנין השם. לעתיד לבא, כשיגאל הקב\"ה את בניו מן הגלות, \u0003מ\"י ואל\"ה\u0004 שהיו בפרוד בגלות, יתחברו יחד, והשם אלקים יהיה שלם על תקונו. והעולם יתבשם. ז\"ש \u0003מי אלה\u0004 כעב תעופינה וכיונים אל ארובותיהם."],[2,"ובגין דאיהו שמא וכו':","ומשום שהוא שם אחד, לא כתוב מי ואלה כעב תעופינה, אלא מי אלה, דהיינו שם אחד בלא פרוד, והוא השם אלקים. שעתה בגלות נסתלק \u0003מ\"י\u0004 למעלה כביכול, במלכות, ונסתלקה האם, דהיינו מלכות, מן הבנים, מישראל. והבנים נפלו, והשם אלקים שהיה שלם, שהוא שם גדול הראשון, נפל. כי נחסרו ממנו אותיות \u0003אל\"ה\u0004 המלובשות בישראל."],[3,"ועל דא וכו':","ועל זה אנו מתפללים ומקדשים בבתי כנסיות על שם זה, אלקים, שיהיה נבנה כמו שהיה. ואומרים יתגדל ויתקדש שמיה רבא. אמן יהא שמיה רבא מברך מי הוא שמו הגדול, ההוא הראשון מכל, דהיינו השם אלקים שנשלם בבנין הראשון כנ\"ל. משום שאין לו בנין אלא עמנו, כי \u0003מ\"י\u0004 לא יהיה נבנה מעולם אלא באותיות \u0003אל\"ה,\u0004 שהן מלובשות בנשמות ישראל כנ\"ל. ועל כן בזמן ההוא, מי אלה כעב תעופינה. ויראו כל העולם שהשם העליון נתתקן על תקונו."],[4,"ואי שמיה רבא וכו':","ואם שמו הגדול אלקים הזה נתתקן ונבנה על תקונו, הרי ישראל מושלים על הכל, וכל שאר השמות חוזרים ובאים על תקונם. וישראל שולטים על הכל כי כולם תלוים בשמו הגדול הראשון לכל בנינים, שהוא השם אלקים, כי על ידו מתגלה הארת החכמה, ואור החכמה מכניע כל הקליפות, וע\"כ שולטים ישראל על כל. וכן כל השמות מקבלים ממנו חכמה, ונשלמים על ידו. והיינו אחר בנין הב', כי בהיותו בבנין הא' הוא חסר חסדים ואינו יכול להאיר, ובבנין הב' הוא משיג חסדים כנ\"ל."],[5,"רזא דא כד וכו':","סוד זה, הוא, כשברא הקב\"ה שהוא בינה, את העולמות, זו\"ן, הראשון לכל הבנינים נבנה שם הזה. שהוא הראשון לכל בחינות ג\"ר. להיותו ג\"ר דרוח. שכתוב, שאו מרום עיניכם וראו \u0003מי\u0004 ברא \u0003אלה\u0004 ברא שמו אלקים על תקונו. וכשברא \u0003אל\"ה,\u0004 ברא אותו בכל הכחות הראוים לו, להיות שמו על תקונו כראוי. דהיינו שהלבישו בחסדים. שכתוב המוציא במספר צבאם."],[6,"מאי במספר וכו':","שואל, מהו במספר, שאומר המוציא במספר. ומשיב, אלא בן אחד המאיר מסוף העולם עד סוף העולם, יש לו להקב\"ה, והוא אילן גדול וחזק, שהוא יסוד דז\"א, ראשו מגיע לגובה השמים, שהוא ז\"א הנקרא שמים, וסופו מתפשטים שרשיו ומשתרשים בעפר הקדוש, שהוא המלכות. בסו\"ה כי כל בשמים וארץ. ושמו מספר. ותלוי בשמים העליונים, שהוא ז\"א, וחמשה רקיעים תלוים בשמים, שהם חג\"ת נ\"ה, עד מספר הזה, שהוא רקיע הששי, דהיינו יסוד. וכולם, וכל הרקיעים, מקבלים שם הזה, מספר, בשביל היסוד, שכתוב, השמים מספרים, משום מספר הזה, כל השמים, שהם ה' רקיעים, מרויחים שם הזה בשבילו. וע\"ז המוציא במספר צבאם. שאם לא מספר הזה, לא היה נמצאים צבאות ותולדות לעולם. כי היסוד מוליד תולדות."],[7,"ועל דא כתיב וכו':","ועל זה כתוב, מי מנה עפר יעקב ומספר את רובע ישראל. שנים הם, שמנו הצאן, ובאו בחשבון על ידיהם, משום שלא שלט בהם עין הרע. מי מנה עפר יעקב, הרי אחד שעושה חשבון. ומספר את רובע ישראל, זהו מונה האחר."],[8,"ועל תרין אלין וכו':","ועל שנים אלו אינו שולט בהם עין הרע, כי מי מנה עפר יעקב אלו הן אבנים הקדושות, אבנים חזקים, שמהם יוצא מים לעולם. ועל זה כתוב, והיה זרעך כעפר הארץ, מה עפר ההוא העולם מתברך בשבילו אף כן, והתברכו בזרעך כל גויי הארץ. כעפר הארץ ממש."],[8,"","פירוש. \u0003אבנים,\u0004 הן מדרגות המלכות שנקראת אבן. וכשהמלכות היא בשליטת השמאל בלא ימין, האבנים מתקשים מאד, ואז הן \u0003מפולמות.\u0004 והן מונחות על התהום, דהיינו שמחמת דינין דשמאל הן סותמים מוצא המים, שהם חסדים. וכדי שהעולם יוכל להתקיים הן מתנקבים ע\"י המסך דצמצום א'. ויוצאים המים דרך הנקבים, ועי\"ז מתקיים העולם. (ועי' בראשית א' דף ל\"ד ד\"ה ועל דא) ובמצב הזה של שליטת המסך דצמצום א', נקראת המלכות \u0003עפר,\u0004 וז\"ש, ועל זה כתוב, והיה זרעך כעפר הארץ. וע\"כ היא \u0003מונה הראשון,\u0004 שעליה כתוב מי מנה \u0003עפר\u0004 יעקב. \u0003ומספר דאיהו מונה וכו':\u0004 ומספר, שהוא \u0003מונה השני,\u0004 מנה להרביץ כל אלו הנוקבין, מרגליות עליונות, שהן מדרגות הבינה, של המטה ששכב עליה יעקב, שהיא המלכות. פירוש \u0003ומספר,\u0004 הוא יסוד, שהוא הנושא של המסך דצמצום ב', המעלה את המלכות לבינה, שמשום העלאה זו נקראת הבינה בשם מרגלא עלאה, (כנ\"ל פרשת יתרו אות תקל\"ד ד\"ה האי) וז\"ש \u0003מנה לרבע כל אינון נוקבין מרגלאן עלאין\u0004 שמעלה המלכות לבינה, ומשום זה נעשה הבינה בסוד האם \u0003רובצת\u0004 על הבנים, ונקראת מרגלא עלאה. שעי\"ז נמתקת המלכות, שהיא \u0003המטה דשכיב עליה ישראל.\u0004"]],[[0,"","זֶהוּ שֶׁאָמַר לוֹ לְיַעֲקֹב אוֹתוֹ הַמְמֻנֶּה שֶׁל עֵשָׂו, שֶׁכָּתוּב (בראשית לב) כִּי שָׂרִיתָ עִם אֱלֹהִים, (עם אנשים ותוכל) לְמַעְלָה, בְּתִקּוּן רִאשׁוֹן בְּבִנְיָן רִאשׁוֹן. כָּל אֵלֶּה, וַדַּאי בִּנְיָן רִאשׁוֹן הוּא."],[1,"","וְלָכֵן אֵין כִּלָּיוֹן לְיִשְׂרָאֵל לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים. וְחַס וְשָׁלוֹם, אִלְמָלֵא יִכְלוּ, הַשֵּׁם הַזֶּה לֹא הָיָה. זֶהוּ שֶׁכָּתוּב (יהושע ז) וְהִכְרִיתוּ אֶת שְׁמֵנוּ מִן הָאָרֶץ וּמַה תַּעֲשֵׂה לְשִׁמְךְ הַגָּדוֹל. שֵׁם הַגָּדוֹל זֶה הַבִּנְיָן הָרִאשׁוֹן, שֵׁם הָרִאשׁוֹן אֱלֹהִים. וְעַכְשָׁו שֶׁיִּשְׂרָאֵל בַּגָּלוּת, (יתחבר) כִּבְיָכוֹל נָפַל כָּל הַבִּנְיָן, וְלֶעָתִיד לָבֹא כְּשֶׁיִּגְאַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת בָּנָיו מֵהַגָּלוּת, מִ\"י וְאֵלֶּ\"ה שֶׁהָיוּ בְפֵרוּד בַּגָּלוּת יִתְחַבְּרוּ כְאֶחָד, וְשֵׁם הָאֱלֹהִים יִהְיֶה שָׁלֵם עַל תִּקּוּנוֹ וְהָעוֹלָם יִתְבַּסֵּם. זֶהוּ שֶׁכָּתוּב (ישעיה ס) מִי אֵלֶּה כָּעָב תְּעוּפֶינָה וְכַיּוֹנִים אֶל אֲרֻבּתֵיהֶם."],[2,"","וּמִשּׁוּם שֶׁהוּא שֵׁם אֶחָד, לֹא כָתוּב מִי וְאֵלֶּה, אֶלָּא מִי אֵלֶּה, שֵׁם אֶחָד לְלֹא פֵרוּד, וְהוּא אֱלֹהִים. שֶׁעַכְשָׁו בַּגָּלוּת הִתְעַלָּה מִי לְמַעְלָה, כִּבְיָכוֹל הָאֵם מֵעַל הַבָּנִים, וְהַבָּנִים נָפְלוּ, וְהַשֵּׁם שֶׁהָיָה שָׁלֵם, שֶׁהוּא הַשֵּׁם הָעֶלְיוֹן הַגָּדוֹל הָרִאשׁוֹן, נָפַל."],[3,"","וְעל זֶה אָנוּ מִתְפַּלְלִים וּמְקַדְּשִׁים בְּבָתֵּי כְּנֵסִיּוֹת עַל הַשֵּׁם הַזֶּה שֶׁיִּבָּנֶה כְּמוֹ שֶׁהָיָה, וְאוֹמְרִים יִתְגַּדַּל וְיִתְקַדַּשׁ שְׁמֵיהּ רַבָּא. אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ. מִי זֶה שְׁמוֹ הַגָּדוֹל? אוֹתוֹ הָרִאשׁוֹן שֶׁל הַכֹּל, מִשּׁוּם שֶׁאֵין לוֹ בִּנְיָן אֶלָּא עִמָּנוּ. מִ\"י לֹא יִבָּנֶה לְעוֹלָם אֶלָּא בְּאֵלֶּה. וְעַל זֶה בְּאוֹתוֹ זְמַן, מִי אֵלֶּה כָּעָב תְּעוּפֶינָה, וְיִרְאוּ כָּל הָעוֹלָם שֶׁהֲרֵי הַשֵּׁם הָעֶלְיוֹן נִתְקָן עַל תִּקּוּנוֹ."],[4,"","וְאִם שְׁמוֹ הַגָּדוֹל הַזֶּה נִתְקָן וְנִבְנֶה עַל תִּקּוּנוֹ, הֲרֵי יִשְׂרָאֵל שׁוֹלְטִים עַל הַכֹּל, וְכָל שְׁאָר הַשֵּׁמוֹת יַחְזְרוּ עַל תִּקּוּנָם, וְיִשְׂרָאֵל שׁוֹלְטִים עַל הַכֹּל, שֶׁהֲרֵי כֻּלָּם תְּלוּיִים בִּשְׁמוֹ הַגָּדוֹל, רִאשׁוֹן לְכָל הַבִּנְיָנִים."],[5,"","סוֹד זֶה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָמוֹת. רִאשׁוֹן לְכָל הַבִּנְיָנִים, שֵׁם זֶה נִבְנָה, שֶׁכָּתוּב (ישעיה מ) שְׂאוּ מָרוֹם עֵינֵיכֶם וּרְאוּ מִי בָרָא אֵלֶּה. בָּרָא שְׁמוֹ עַל תִּקּוּנוֹ. וּכְשֶׁבָּרָא אֵלֶּה, בָּרָא (שמו) אוֹתוֹ בְּכָל הַחֲיָלוֹת שֶׁנִּרְאִים לוֹ לִהְיוֹת שְׁמוֹ עַל תִּקּוּנוֹ כָּרָאוּי, שֶׁכָּתוּב הַמּוֹצִיא בְמִסְפָּר צְבָאָם."],[6,"","מַה זֶּה בְּמִסְפָּר? אֶלָּא בֵּן אֶחָד שֶׁמֵּאִיר מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם יֵשׁ לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְהוּא עֵץ גָּדוֹל וְחָזָק. רֹאשׁוֹ מַגִּיעַ לְגֹבַהּ הַשָּׁמַיִם, וְסוֹפוֹ מִתְפַּשְּׁטִים שָׁרָשָׁיו, וּמֻשְׁרָשִׁים בֶּעָפָר הַקָּדוֹשׁ, וּמִסְפָּר שְׁמוֹ. וְתָלוּי בַּשָּׁמַיִם הָעֶלְיוֹנִים, וַחֲמִשָּׁה רְקִיעִים תְּלוּיִים מִמֶּנּוּ עַד הַמִּסְפָּר הַזֶּה, וְכֻלָּם נוֹטְלִים שֵׁם זֶה בִּגְלָלוֹ, שֶׁכָּתוּב (תהלים יט) הַשָּׁמַיִם מְסַפְּרִים, בִּגְלַל מִסְפָּר זֶה. כָּל (בשביל השם הזה מספר) הַשָּׁמַיִם מַרְוִיחִים אֶת הַשֵּׁם הַזֶּה בִּגְלָלוֹ. וְעַל זֶה הַמּוֹצִיא בְמִסְפָּר צְבָאָם, שֶׁאִלְמָלֵא מִסְפָּר זֶה לֹא יִמָּצְאוּ חֲיָלוֹת וְתוֹלָדוֹת לְעוֹלָמִים."],[7,"","וְעַל זֶה כָּתוּב (במדבר כג) מִי מָנָה עֲפַר יַעֲקֹב וּמִסְפָּר אֶת רֹבַע יִשְׂרָאֵל. שְׁנַיִם הֵם שֶׁמָּנוּ צֹאן וְנִכְנְסוּ בְחֶשְׁבּוֹן עַל יְדֵיהֶם, בִּגְלַל שֶׁלֹּא שָׁלְטָה בָהֶם עַיִן הָרָע. מִי מָנָה עֲפַר יַעֲקֹב - הֲרֵי אֶחָד שֶׁעָשָׂה חֶשְׁבּוֹן. וּמִסְפָּר אֶת רֹבַע יִשְׂרָאֵל - הֲרֵי מוֹנֶה אַחֵר."],[8,"","וְעַל שְׁנֵי אֵלֶּה לֹא שָׁלְטָה בָהֶם עַיִן הָרָע, שֶׁהֲרֵי מִי מָנָה לַעֲפַר יַעֲקֹב - אֵלֶּה אוֹתָן אֲבָנִים (דרגות) קְדוֹשׁוֹת, אֲבָנִים מְפֻלָּמוֹת שֶׁמֵּהֶן יוֹצְאִים מַיִם לְעוֹלָם. וְעַל זֶה כָּתוּב (בראשית כח) וְהָיָה זַרְעֲךְ כַּעֲפַר הָאָרֶץ. מָה אוֹתוֹ עָפָר הָעוֹלָם מִתְבָּרֵךְ בִּשְׁבִילוֹ, אַף כָּךְ (בראשית כב) וְהִתְבָּרֲכוּ בְזַרְעֲךְ כֹּל גּוֹיֵי הָאָרֶץ. כַּעֲפַר הָאָרֶץ מַמָּשׁ. וּמִסְפָּר, שֶׁהוּא מוֹנֶה שֵׁנִי, מָנָה אֶת רֹבַע כָּל אוֹתָן נְקֵבוֹת, מַרְגָּלִיּוֹת עֶלְיוֹנוֹת, שֶׁל הַמִּטָּה שֶׁשּׁוֹכֵב עָלֶיהָ יִשְׂרָאֵל."]]],[["וּמִתַּמָּן וּלְהָלְאָה, אִיהוּ מוֹנֶה לְכֹלָּא, בְּגִין דְּאִיהוּ טוֹב עַיִן. הֲדָא הוּא דִּכְתִּיב, מוֹנֶה מִסְפָּר לַכֹּכָבִים. מַאן הוּא מוֹנֶה לַכֹּכָבִים. מִסְפָּר. מוֹנֶה מִסְפָּר לַכֹּכָבִים, עַל יְדוֹי עַבְרִין כֻּלְּהוּ בְּחֻשְׁבָּנָא, וּלְזִמְנָא דְּאָתֵי, (ירמיהו ל״ג:י״ג) עוֹד תַּעֲבוֹרְנָה הַצֹּאן עַל יְדֵי מוֹנֶה, וְלָא יַדְעִינָן מַאן הוּא. אֶלָּא בְּגִין דִּבְהַהוּא זִמְנָא, יְהֵא כֹּלָּא בְּיִחוּדָא בְּלא פִּרוּדָא, כֹּלָּא לִיהֲוֵי (וכלא ליהוי) מוֹנֶה חַד.","קוּם סָבָא, אִתְּעַר וְאִתְגַּבַּר בְּחֵילָךְ, וְשׁוּט יַמָּא. פָּתַח וְאָמַר, (במדבר כ״ג:י׳) מִי מָנָה עֲפַר יַעֲקֹב וּמִסְפָּר אֶת רֹבַע יִשְׂרָאֵל. בְּשַׁעֲתָא דְּיִתְּעַר קוּדְשָׁא בְּרִיךְ הוּא לְאַחֲיָיא מֵתַיָּא, הָנֵי דְּאִתְהַדָּרוּ בְּגִלְגּוּלָא, תְּרֵין גּוּפִין בְּרוּחָא חֲדָא, תְּרֵין אֲבָהָן, תְּרֵין אִמָּהָן, כַּמָּה גִּלְגּוּלִין מִתְגַּלְגְּלָן עַל (ודא) דָּא, אַף עַל גַּב דְּאִתְּמַר, וְהָכִי הוּא, אֲבָל מִי מָנָה עֲפַר יַעֲקֹב, וְאִיהוּ יַתְקִין כֹּלָּא, וְלָא יִתְאֲבִיד כְּלוּם, וְכֹלָּא יְקוּם.","וְהָא אִתְּמַר, (דניאל י״ב:ב׳) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ. אַדְמַת עָפָר הָנֵי, כְּמָה דְּאִתְּמַר בְּסִפְרָא דְּחֲנוֹךְ, כַּד חַבְרַיָּיא אִסְתַּכָּלוּ בְּאִינּוּן אַתְוָון (דטסין) בַּאֲוִירָא בֵּיהּ, וְאִינּוּן אע\"ד פמת\"ר, הַיְינוּ, אַדְמַ\"ת עָפָ\"ר.","הַיְינוּ (קהלת ד׳:ב׳) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, אַדְמַת עָפָר אִינּוּן אַתְוָון וְקָלָא אִתְּעַר וְאוֹדַע וְהָכִי אָמַר בְּבִנְיָינָא (ק\"ג ע\"ב) תִּנְיָינָא. עָפָר, עָפָר קַדְמָאָה. אַדְמַת תִּנְיָינָא, דְּאִתְתָּקַּן עִקָר קַדְמָאָה פְּסוֹלֶת לְגַבֵּיהּ.","אַדְמַת עָפָר כֻּלְּהוּ, יָקִיצוּ. אֵלֶּה דְּאִתָּקָנוּ, לְחַיֵּי עוֹלָם. (ס\"א יקיצו כמה דאתמר בספרא דחנוך. חברייא איסתכלו באינון אתוון אדמ\"ת עפ\"ר (ואינון אע\"ד פמת\"ר) אינון אתוון טסאן באוירא וקלא אתער ואודע (ס\"א ואכריז) הקיצו ורננו שוכני עפר ודא איהו בניינא תניינא דאתתקן והכי אמר בספרא דחנוך בניינא תניינא עפר דאתתקן. קדמאה אדמת. וההוא קדמאה פסולת לגבי תניינא דאתתקן והני ישני אדמת עפר כלהו יקיצו אלה דאתתקנו לחיי עולם) מַאן עוֹלָם. דָּא עוֹלָם דִּלְתַתָּא דְּהָא לָא זָכוּ לְמהרֵ בָּעוֹלָם דִּלְעֵילָּא. וְאֵלֶּה דְּלָא זָכוּ, לַחֲרָפוֹת וּלְדִרְאוֹן עוֹלָם. מַאי לַחֲרָפוֹת, אֶלָּא בְּגִין דְּסִטְרָא אַחֲרָא יִתְעַבָּר מֵעָלְמָא, וְקוּדְשָׁא בְּרִיךְ הוּא, אִלֵּין דַּהֲווֹ מִנְּבִיעוּ דְּהַהוּא סִטְרָא, יָשְׁאַר לוֹן, לְתַוְּוהָא בְּהוֹן כָּל בְּנֵי עָלְמָא.","כָּל דָּא מַאן גָּרִים, הַהוּא דְּלָא בָּעֵי לְאַפָּשָׁא בְּעָלְמָא, וְלָא בָּעֵי לְקַיְּימָא (ס\"א בדרגא דההוא נהר דאיהו) בְּרִית קַדִּישָׁא, עַל דָּא גָּרִים כָּל מַה דְּגָרִים, וְכָל הָנֵי גִּלְגּוּלִין דְּקָא אֲמֵינָא עָלָהּ עַד הָכָא. (הדא הוא) עַד כָּאן סָבָא. שָׁתִיק רִגְעָא חֲדָא, וְחַבְרַיָּיא הֲווֹ תָּוְוהִין, וְלָא הֲווֹ יַדְעִין, אִי הֲוָה יְמָמָא, אִי הֲוָה לֵילְיָא, אִי קַיְימֵי תַּמָּן, אִי לָא קַיְימֵי.","פָּתַח הַהוּא סָבָא וְאָמַר, (שמות כ״א:ב׳) כִּי תִקְנֶה עֶבֶד עִבְרִי שֵׁשׁ שָׁנִים יַעֲבֹד וּבַשְּׁבִיעִית וְגוֹ'. קְרָא דָּא אוֹכַח, עַל כָּל מַה דְּאִתְּמַר. תָּא חֲזֵי, כָּל דְּכוּרָא, קָאִים בְּדִיּוּקְנָא, בְּעָלְמָא דִּדְכוּרָא. וְכָל נוּקְבָּא קָאִים בְּדִיּוּקְנָא, בְּעָלְמָא דְּנוּקְבָּא. בְּעוֹד דְּאִיהוּ עַבְדָּא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְדָּבַּק בֵּיהּ, בְּאִינּוּן שֵׁשׁ שָׁנִים קַדְמוֹנִיּוֹת, וְאִי אִעֲקָר גַּרְמֵיהּ מִפּוּלְחָנֵיהּ, יַעְקָר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא מֵאִינּוּן שֵׁשׁ שָׁנִים, דְּעָלְמָא דִּדְכוּרָא, וְאִתְמְסַר (צ\"ד ע\"א) לְּבַּר נָשׁ, דְּאִיהוּ מִשִּׁית סִטְרִין, יִפְלַח לֵיהּ שִׁית שְׁנִין, וְיִתְעַקָּר מִשִּׁית שְׁנִין (קדמוניות) דִּלְעֵילָּא.","לְבָתַר נָחִית מִתַּמָּן, וְאִתְמְסַר בְּעָלְמָא דְּנוּקְבָּא. הוּא לָא בָּעָא לְקַיְּימָא בִּדְכוּרָא, נָחִית וְקַיְּימָא בְּנוּקְבָא. אָתָאת נוּקְבָּא, דְּאִיהִי שְׁבִיעִית, וְנָטְלָא לֵיהּ, הָא מִכָּאן וּלְהָלְאָה, מֵעָלְמָא דְּנוּקְבָּא אִיהוּ.","לָא בָּעָא לְקַיְּימָא בָּהּ, וּבְפִירוּקָא דִּילָהּ, נָחִית לְתַתָּא, וְאִתְדָבַּק לְתַתָּא, וְאִתְאֲחִיד בְּסִטְרָא אַחֲרָא. מִכָּאן וּלְהָלְאָה, אִתְעַקָּר מֵעָלְמָא דִּדְכוּרָא, וּמֵעָלְמָא דְּנוּקְבָּא. הָא אִתְאֲחָד, בְּאִינּוּן עֲבָדִים דְּאִינּוּן מִסִּטְרָא אַחֲרָא.","הַשְׁתָּא כֵּיוָן דְּהָכִי הוּא, אִיצְטְרִיךְ פְּגָם, וּלְמֶעְבַּד בֵּיהּ רְשִׁימוּ דִּפְגָם, דְּהָא כָּל פְּגָם דְּסִטְרָא אַחֲרָא אִיהוּ, וּמִיּוֹבֵל וּלְהָלְאָה אִתְהַדַּר לְגִלְגּוּלָא, וְתָב לְעָלְמָא כְּמִלְּקַדְּמִין. (ס\"א אי זכי ואתתקן גרמיה אתבר) וְאִתְדַּבָּק בְּהַהוּא עָלְמָא דְּנוּקְבָּא, וְלָא יַתִּיר. זָכָה עָבִיד תּוֹלָדִין בְּעָלְמָא דְּנוּקְבָּא, וְכֻלְּהוּ רָזָא דִּכְתִּיב, (תהילים מ״ה:ט״ו) בְּתוּלוֹת אַחֲרֶיהָ רֵעוֹתֶיהָ מוּבָאוֹת לָךְ. וְזַכָּאָה אִיהוּ כַּד אִתְתָּקַּן וְזָכֵי לְכָךְ.","וְאִי לָא זָכָה אֲפִילּוּ בְּגִלְגּוּלָא דְּיוֹבְלָא, הָא אִיהוּ כְּלָא הֲוָה אִתְהַדַּר, וְלָא אַשְׁלִימוּ יוֹמוֹי, לְאִתְנַסְּבָא בְּעָלְמָא, וּלְמֶעְבַּד תּוֹלָדִין. מַה כְּתִיב, אִם בְּגַפּוֹ יָבֹא בְּגַפּוֹ יֵצֵא. אִי יְחִידָאי יֵעוּל בְּהַהוּא עָלְמָא בְּלָא תּוֹלָדִין, וְלָא בָּעָא לְאִשְׁתַּדְּלָא בְּהַאי, וְנָפַק מֵהַאי עָלְמָא יְחִידָאי, בְּלָא זַרְעָא, אָזִיל כְּאַבְנָא בְּקוּסְפִיתָא, עַד הַהוּא אֲתָר דְּטִנָרָא (ק' ע\"א) תַּקִּיפָא, וְעָאל תַּמָּן וּמִיַּד נָשַׁב רוּחָא דְּהַהוּא יְחִידָאי, דְּקָא אִשְׁתְּבִיק מִנּוּקְבֵיהּ, וְאָזִיל יְחִידָאי, (צ\"ה ע\"א) כְּחִוְיָא דְּלָא אִתְחַבָּר בְּאַחֲרָא בְּאוֹרְחָא, וְנָשִׁיב בֵּיהּ."],[[0,"ומתמן ולהלאה איהו וכו':","משם ולהלאה, דהיינו אחר שנתקן היסוד, להיות מונה בכח המסך דצמצום ב', הוא מונה לכל. כי מונה הא' נגנז, מפני שהוא היסוד, טוב עין. ז\"ש, מונה מספר לככבים. מי הוא מונה לככבים \u0003מספר.\u0004 מונה מספר לככבים, היינו שעל ידו עוברים כולם בחשבון. ולעתיד לבא, כתוב, עוד תעבורנה הצאן על ידי מונה. ואין אנו יודעים מי הוא, אם הוא מונה הא' או הב' אלא משום שבזמן ההוא יהיה הכל ביחוד בלא פרוד, הכל יהיה על ידי מונה אחד. דהיינו המונה הא', כי אז יתוקן המסך דצמצום א', והמסך דצמצום ב' יתבטל. כי לא יהיה עוד שום דין במלכות שתהיה צריכה להתמתק בבינה. וע\"כ לא נשאר כי אם המונה הא'. כמ\"ש לפנינו, שעליו נאמר, מי מנה עפר יעקב."],[1,"קום סבא אתער וכו':","אמר לעצמו קום זקן התעורר והתגבר בכחך ושוט בים. פתח ואמר, מי מנה עפר יעקב ומספר את רובע ישראל. בשעה שיתעורר הקב\"ה להחיות המתים אותם שבאו בגלגול, שהם ב' גופים ברוח אחד, דהיינו גוף המת וגוף המתגלגל, שלשניהם רק רוח אחד. ב' אבות. אב של המת, ואב של גוף המתגלגל. וכן ב' אמהות. כמה גלגולים מתגלגלים על זה, עד שיתוקן, אע\"פ שלמדנו זה, וכך הוא, אבל, מי מנה עפר יעקב, שהוא המונה הראשון, הוא יתקן הכל, כל הגופים המגולגלים, ולא יהיה נאבד כלום, והכל יקום לתחיה."],[2,"והא אתמר ורבים וכו':","והרי למדנו. ורבים מישני אדמת עפר יקיצו. אדמת עפר אלו, הוא כמו שלמדנו בספרו של חנוך, כשהחברים הסתכלו באלו האותיות השטים באויר, והם \u0003אע\"ד פמת\"ר.\u0004 שפירושו אדמת עפר."],[2,"","פירוש. \u0003השטים באויר,\u0004 היינו שיש להם קומת רוח. והוא או מכח המסך דצמצום א', אז נקראות \u0003עפר.\u0004 ואם ע\"י המסך דצמצום ב', אז נקראות \u0003אדמת\u0004. כי הבינה נקראת אדום, והמלכות הממותקת בה, נקראת אדמת."],[3,"היינו ושבח אני וכו':","היינו, ושבח אני את המתים שכבר מתו, שהן האותיות \u0003אדמת עפר,\u0004 כלומר הן המתים מבחינת עפר והן המתים מבחינת אדמת. וקול נתעורר ומודיע ואומר כן, בבנין השני. שהוא גוף המגולגל, והוא המתקן הן גוף המת, שהוא מבחינת \u0003עפר.\u0004 והן גוף עצמו שהוא בחי' \u0003אדמת.\u0004 והוא שאומר, ושבח אני את המתים, דהיינו שמתקן אותם. \u0003עפר,\u0004 היינו עפר הראשון, שהוא גוף המת. \u0003אדמת,\u0004 היינו השני שנתקן, שהוא גוף המגולגל. אשר עקר הראשון הוא פסולת אצלו. כי גוף המת בלי בנים, שהוא עקר, הוא אצל גוף שנתגלגל, בבחינת פסולת, שהוא המתקן אותו. וע\"כ אומר ושבח אני את המתים, דהיינו שמתקן אותם."],[4,"אדמת עפר כלהו וכו':","ישני אדמת עפר כולם יקיצו. אלו שנתקנו, יהיו לחיי עולם. מי הוא עולם. זה הוא עולם התחתון, דהיינו המלכות. כי לא זכו להיות בעולם העליון, אלא שירדו לעלמא דנוקבא (כנ\"ל אות קל\"ב) ואלה שלא זכו להתתקן, יהיו לחרפות ולדראון עולם. שואל, מהו לחרפות. ואומר, אלא משום שהצד האחר יהיה נעבר מן העולם, והקב\"ה, אלו שהיו מנביעה של צד ההוא, ישאיר אותם, להתמיה בהם כל בני עולם. וז\"ש לחרפות ולדראון עולם."],[5,"כל דא מאן וכו':","כל זה מי גרם. אדם ההוא, שלא רצה להפרות ולהרבות בעולם ולא רצה לקיים ברית הקדוש, על כן גרם כל מה שגרם, וכל אלו הגלגולים שאמרתי עליהם עד כאן. אמר לעצמו, עד כאן זקן. שתק רגע אחד, והחברים היו תמהים ולא היו יודעים אם הוא יום אם הוא לילה, אם עומדים שם או לאעומדים שם."],[6,"פתח ההוא סבא וכו':","פתח זקן ההוא ואמר, כי תקנה עבד עברי שש שנים יעבד ובשביעית וגו'. מקרא זה מוכיח על כל מה שאמרנו. בוא וראה, כל זכר עומד בצורת עולם הדכר, שהוא ז\"א. וכל נקבה עומדת בצורת עולם הנקבה שהיא המלכות. בעוד שהוא עבד של הקב\"ה, הוא מתדבק באלו שש שנים הקדמוניות, דהיינו חג\"ת נה\"י דז\"א. ואם עוקר את עצמו מעבודתו, עוקר אותו הקב\"ה מאלו שש שנים של עולם הזכר, דהיינו חג\"ת נה\"י דז\"א, ונמסר לאדם שהוא משש קצוות, חג\"ת נה\"י, ועובד אותו שש שנים, ונעקר משש שנים שלמעלה. דז\"א."],[7,"לבתר נחית מתמן וכו':","אחר כך יורד משם ונמסר בעולם הנקבה, הוא לא רצה לעמוד בדכר, יורד ועומד בנוקבא, שהיא המלכות. באה הנוקבא, שהיא ספירה השביעית ולוקחת אותו, שעליה נאמר ובשביעית יצא לחפשי חנם. הנה מכאן ולהלאה הוא מעולם הנוקבא."],[8,"לא בעא לקיימא וכו':","לא רצה לעמוד בה ובגאולה שלה, שאמר אהבתי וגו' לא אצא חפשי, יורד למטה, ומתדבק למטה, ונאחז בצד האחר. מכאן ולהלאה הוא נעקר מעולם הזכר ומעולם הנקבה, כי נתאחד באלו העבדים שהם מצד האחר."],[9,"השתא כיון דהכי הוא וכו':","עתה, כיון שכך הוא, שנאחז בס\"א, הוא צריך פגם, ולעשות בו רשימו של פגם, דהיינו ורצע אדוניו את אזנו במרצע, כי כל פגם הוא מצד האחר. ואז ועבדו לעולם. דהיינו עד היובל שנקרא עולם. ומיובל ולהלאה, חוזר להתגלגל וחוזר לעולם כבתחילה, ומתדבק בעולם הנקבה ולא יותר. זכה, עושה תולדות בעולם הנקבה, שהיא המלכות, וכולם הם סוד, שכתוב, בתולות אחריה רעותיה מובאות לך. והוא זכאי כשהוא נתקן וזכה לכך."],[10,"ואי לא זכה וכו':","ואם לא זכה אפילו בגלגול היובל, הרי הוא כמו שלא היה. שחזר בגלגול ולא השלים ימיו להנשא בעולם, ולעשות תולדות. מה כתוב. אם בגפו יבא בגפו יצא. אם יחידי נכנס בעולם ההוא, בלי תולדות, ולא רצה להשתדל בזה, ויצא מעולם הזה יחידי בלא זרע, הולך כאבן בכף הקלע עד מקום ההוא של הסלע החזק שהוא אחר כתפיו של גן העדן (כנ\"ל אות קט\"ז) ונכנס שמה ומיד נושב רוח ההוא היחידי, שעזב את הנוקבא, ובא שמה, שהוא הרוח הנשאר בהנוקבא מבעלה הראשון (כנ\"ל באות קט\"ז) והולך יחידי כנחש שאינו מתחבר באחר בדרך, כי הוא נפרד מב' רוחין שבאשה והלך יחידי (כנ\"ל באות הנזכר.) והוא נושב בו, ברוח הזה של המת בלי בנים שבא עתה שמה. דהיינו שדוחה אותו משם, כדי שיבא להתגלגל ויתתקן."]],[[0,"","וּמִשָּׁם וָהָלְאָה הוּא מוֹנֶה לַכֹּל, מִשּׁוּם שֶׁהוּא טוֹב עַיִן. זֶהוּ שֶׁכָּתוּב מוֹנֶה מִסְפָּר לַכּוֹכָבִים. מִי הוּא שֶׁמּוֹנֶה אֶת הַכּוֹכָבִים? מִסְפָּר. מוֹנֶה מִסְפָּר לַכּוֹכָבִים. וְעַל יָדוֹ עוֹבְרִים כֻּלָּם בְּחֶשְׁבּוֹן. וְלֶעָתִיד לָבא, (ירמיה לג) עוֹד תַּעֲברְנָה הַצּאן עַל יְמֵי מוֹנֶה. וְלֹא יוֹדְעִים מִי הוּא. אֶלָּא מִשּׁוּם שֶׁבְּאוֹתוֹ זְמַן יִהְיֶה הַכֹּל בְּיִחוּד בְּלֹא פֵרוּד, הַכֹּל יִהְיֶה (והכל יהיה) מוֹנֶה אֶחָד."],[1,"","קוּם זָקֵן, הִתְעוֹרֵר וְהִתְגַּבֵּר בְּכֹחֲךְ וְשׁוּט בַּיָּם. פָּתַח וְאָמַר, (במדבר כג) מִי מָנָה עֲפַר יַעֲקֹב וּמִסְפָּר אֶת רֹבַע יִשְׂרָאֵל. בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִתְעוֹרֵר לְהַחֲיוֹת מֵתִים - אֵלּוּ שֶׁחָזְרוּ בְגִלְגּוּל שְׁנֵי גוּפִים בְּרוּחַ אַחַת, שְׁנֵי אָבוֹת, שְׁתֵּי אִמָּהוֹת, כַּמָּה גִלְגּוּלִים מִתְגַּלְגְּלִים עַל יְדֵי זֶה, אַף עַל גַּב שֶׁנִּתְבָּאֵר, וְכָךְ הוּא. אֲבָל מִי מָנָה עֲפַר יַעֲקֹב, וְהוּא יְתַקֵּן הַכֹּל, וְלֹא יאבַד כְּלוּם, וְהַכֹּל יָקוּם."],[2,"","וַהֲרֵי נֶאֱמַר (דניאל יב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ. אַדְמַת עָפָר אֵלֶּה, כְּמוֹ שֶׁנֶּאֱמַר בְּסִפְרוֹ שֶׁל חֲנוֹךְ, כְּשֶׁהַחֲבֵרִים הִסְתַּכְּלוּ בְּאוֹתָן אוֹתִיּוֹת (שטסות) בָּאֲוִיר בּוֹ, וְהֵם אע\"ד פמת\"ר, הַיְנוּ אַדְמַ\"ת עָפָ\"ר."],[3,"","הַיְנוּ (קהלת ד) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ. אַדְמַת עָפָר הֵן אוֹתִיּוֹת, וְקוֹל מִתְעוֹרֵר וּמוֹדִיעַ וְכָךְ אוֹמֵר בַּבִּנְיָן הַשֵּׁנִי. עָפָר - עָפָר רִאשׁוֹן. אַדְמַת - שֵׁנִי. שֶׁהִתְתַּקֵּן הָעִקָּר הָרִאשׁוֹן פְּסֹלֶת אֵלָיו."],[4,"","אַדְמַת עָפָר - כֻּלָּם - יָקִיצוּ, אֵלֶּה שֶׁהִתְתַּקְּנוּ לְחַיֵּי עוֹלָם. (יקיצו, כמו שגאמר בספרו של חנוך. חברים הסתכלו באלו האותיות אדמ\"ת עפ\"ר (והן אע\"ד פמת\"ר) אותן אותיות טסות באויר, וקול מתעורר ומודיע (וּמכריז) הקיצו ורגנו שכני עפר, וזהו בנין שני שגתקן. וכך אמר בספרו של חנוך, ' בנין שני עפר שגתקן. ראשון אדמת. ואותו ראשון פסלת לגבי שני שגתקן. ואלו ישני אדמת עפר כלם יקיצו אלה שגתקנו לחיי עולם) מִי זֶה עוֹלָם? זֶהוּ עוֹלָם שֶׁלְּמַטָּה, שֶׁהֲרֵי לֹא זָכוּ לִהְיוֹת בָּעוֹלָם שֶׁלְּמַעְלָה. וְאֵלֶּה שֶׁלֹּא זָכוּ - לַחֲרָפוֹת וּלְדִרְאוֹן עוֹלָם. מַה זֶּה לַחֲרָפוֹת? מִשּׁוּם שֶׁצַּד הָאַחֵר יַעֲבֹר מִן הָעוֹלָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יַשְׁאִיר אֶת אֵלֶּה שֶׁהָיוּ מִנְּבִיעַת אוֹתוֹ הַצַּד לְהַתְמִיהַּ בָּהֶם אֶת כָּל בְּנֵי הָעוֹלָם."],[5,"","מִי גָרַם כָּל זֶה? אוֹתוֹ שֶׁלֹּא רָצָה לְהִתְרַבּוֹת בָּעוֹלָם וְלֹא רָצָה לְקַיֵּם (בדרגה של אותו נהר שהוא) בְּרִית הַקֹּדֶשׁ, וְלָכֵן גָּרַם כָּל מַה שֶּׁגָּרַם וְכָל הַגִּלְגּוּלִים הַלָּלוּ שֶׁאָמַרְנוּ עָלֶיהָ עַד כָּאן. (וזהו) עַד כָּאן זָקֵן. שָׁתַק רֶגַע אֶחָד, וְהַחֲבֵרִים הָיוּ תְּמֵהִים, וְלֹא הָיוּ יוֹדְעִים אִם הָיָה יוֹם אִם הָיָה לַיְלָה, אִם עוֹמְדִים שָׁם אִם לֹא עוֹמְדִים."],[6,"","פָּתַח אוֹתוֹ זָקֵן וְאָמַר, כִּי תִקְנֶה עֶבֶד עִבְרִי שֵׁשׁ שָׁנִים יַעֲבֹד וּבַשְּׁבִיעִית וְגוֹ'. פָּסוּק זֶה מוֹכִיחַ עַל כָּל מַה שֶּׁנִּתְבָּאֵר. בּא וּרְאֵה, כָּל זָכָר עוֹמֵד בִּדְיוֹקָן בְּעוֹלַם הַזָּכָר, וְכָל נְקֵבָה עוֹמֶדֶת בִּדְיוֹקָן בְּעוֹלַם הַנְּקֵבָה. בְּעוֹד שֶׁהוּא עֶבֶד שֶׁנִּדְבָּק בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָן שֵׁשׁ שָׁנִים קַדְמוֹנִיּוֹת, וְאִם עָקַר עַצְמוֹ מֵעֲבוֹדָתוֹ, יַעֲקֹר אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאוֹתָן שֵׁשׁ שָׁנִים שֶׁל עוֹלַם הַזָּכָר, וְיִמָסֵר לְאָדָם שֶׁהוּא מִשִּׁשָּׁה צְדָדִים, יַעֲבֹד לוֹ שֵׁשׁ שָׁנִים, וְיֵעָקֵר מִשֵּׁשׁ שָׁנִים (קדמוניות) שֶׁלְּמַעְלָה."],[7,"","אַחַר כָּךְ יוֹרֵד מִשָּׁם וְנִמְסָר לְעוֹלַם הַנְּקֵבָה. הוּא לֹא רָצָה לַעֲמֹד (בעולם) בַּזָּכָר - יוֹרֵד וְעוֹמֵד בַּנְּקֵבָה. בָּאָה הַנְּקֵבָה, שֶׁהִיא שְׁבִיעִית, וְנוֹטֶלֶת אוֹתוֹ. הֲרֵי מִכָּאן וָהָלְאָה הוּא מֵעוֹלַם הַנְּקֵבָה."],[8,"","לֹא רָצָה לַעֲמֹד בָּהּ וּבַגְּאֻלָּה שֶׁלָּהּ - יוֹרֵד לְמַטָּה וְנִדְבָּק לְמַטָּה וְנֶאֱחָז בַּצַּד הָאַחֵר. מִכָּאן וָהָלְאָה נֶעֱקָר מֵעוֹלַם הַזָּכָר וּמֵעוֹלַם הַנְּקֵבָה. הֲרֵי נֶאֱחָז בְּאוֹתָם עֲבָדִים שֶׁהֵם מִצַּד הָאַחֵר."],[9,"","עַכְשָׁו, כֵּיוָן שֶׁכָּךְ הוּא, הִצְטָרֵךְ פְּגָם וְלַעֲשׂוֹת בּוֹ רֹשֶׁם שֶׁל פְּגָם, שֶׁהֲרֵי כָּל פְּגָם הוּא שֶׁל צַד הָאַחֵר, וּמִיּוֹבֵל וָהָלְאָה חוֹזֵר לְגִלְגּוּל, וְשָׁב לָעוֹלָם כְּמִקֹּדֶם, (אם זוכה ומתקן עצמו, נדבק) וְנִדְבָּק בְּאוֹתוֹ עוֹלַם הַנְּקֵבָה וְלֹא יוֹתֵר. זָכָה - עוֹשֶׂה תוֹלָדוֹת בְּעוֹלַם הַנְּקֵבָה, וְכֻלָּם סוֹד הַכָּתוּב (תהלים מה) בְּתוּלוֹת אַחֲרֶיהָ רֵעוֹתֶיהָ מוּבָאוֹת לָךְ. וְאַשְׁרָיו כְּשֶׁמִּתְתַּקֵּן וְזוֹכֶה לְכָךְ."],[10,"","וְאִם לֹא זָכָה אֲפִלּוּ בְּגִלְגּוּל הַיּוֹבֵל, הֲרֵי הוּא כְּלֹא הָיָה, שֶׁחָזַר וְלֹא הִשְׁלִים יָמָיו לְהִנָּשֵׂא בָּעוֹלָם וְלַעֲשׂוֹת תּוֹלָדוֹת. מַה כָּתוּב? אִם בְּגַפּוֹ יָבֹא בְּגַפּוֹ יֵצֵא. אִם יְחִידִי יִכָּנֵס לְאוֹתוֹ הָעוֹלָם בְּלִי תוֹלָדוֹת וְלֹא רָצָה לְהִשְׁתַּדֵּל בְּכָךְ, וְיָצָא מֵהָעוֹלָם הַזֶּה יְחִידִי בְּלִי זֶרַע - הוֹלֵךְ כְּמוֹ אֶבֶן בְּכַף הַקֶּלַע עַד אוֹתוֹ מָקוֹם שֶׁל הַסֶּלַע הֶחָזָק, וְנִכְנָס לְשָׁם, וּמִיָּד נוֹשֶׁבֶת רוּחַ שֶׁל אוֹתוֹ יָחִיד שֶׁנֶּעֱזַב מִנְּקֵבָתוֹ, וְהוֹלֵךְ יְחִידִי כְּנָחָשׁ שֶׁלֹּא מִתְחַבֵּר עִם אַחֵר בַּדֶּרֶךְ, וְנוֹשֵׁב בּוֹ."]]],[["וּמִיָּד נָפַק מִגּוֹ הַהוּא אֲתָר דְּטִנָרָא תַּקִּיפָא, הוּא בִּלְחוֹדוֹי, וְאָזִיל וּמְשַׁטְּטָא בְּעָלְמָא, עַד דְּקָא אַשְׁכַּח פָּרוֹקָא לְאָתָבָא. וְהַיְינוּ אִם בְּגַפּוֹ יָבֹא בְּגַפּוֹ יֵצֵא, הַאי דְּלָא בָּעָא לְאִתְנַסְּבָא, לְמֶהֱוֵי לֵיהּ תּוֹלָדִין.","אֲבָל אִם בַּעַל אִשָּׁה הוּא, דְּקָא אִתְנְסִיב, וְאִשְׁתָּדַּל בְּאִתְּתֵיהּ, וְלָא יָכִיל, הַהוּא לָא אִתְתָּרַךְ כְּהַהוּא אַחֲרָא, לָא יֵיעוּל יְחִידָאי, וְלָא נָפִיק יְחִידָאי, אֶלָּא אִם בַּעַל אִשָּׁה הוּא, קוּדְשָׁא בְּרִיךְ הוּא לָא מְקַפֵּחַ אֲגַר כָּל בִּרְיָין, אַף עַל גַּב דְּלָא זָכוּ בִּבְנֵי, מַה כְּתִיב וְיָצְאָה אִשְׁתּוֹ עִמּוֹ. וְתַרְוַויְיהוּ אַתְיָין בְּגִלְגּוּלָא, וְזַכְיָין לְאִתְחַבְּרָא כַּחֲדָא כְּמִלְּקַדְּמִין. וְהַאי לָא נָסִיב אִתְּתָא דִּתְרוּכִין, אֶלָּא הַהִיא דְּאִשְׁתַּדַּל בָּהּ בְּקַדְמִיתָא, וְלָא זָכוּ, הַשְּׁתָּא יִזְכּוּ כַּחֲדָא, אִי יְתַקְּנוּן עוֹבָדִין, וְעַל דָּא וְיָצְאָה אִשְׁתּוֹ עִמּוֹ.","(שמות כ״א:ד׳) אִם אֲדוֹנָיו יִתֵּן לוֹ אִשָּׁה וְגוֹ'. (השתא) אַהְדָּר קְרָא לְמִלִּין אַחֲרָנִין, (ס\"א למלה קדמאה) לְהַהוּא דְּנָפִיק יְחִידָאי בְּלָא נוּקְבָּא כְּלָל, וַיִפְרוֹק לֵיהּ הַהוּא דּוּכְתָּא דְּאִקְרֵי שְׁבִיעִית. וְהַהוּא שְׁבִיעִית אִקְרֵי אֲדוֹנָיו, אֲדוֹן כָּל הָאָרֶץ אִיהוּ. אִם דָּא אֲדוֹנָיו חָס עָלֵיהּ, וְאָתִיב לֵיהּ לְהַאי עָלְמָא יְחִידָאי כְּמָה דְּהֲוָה, וְיָהִיב לֵיהּ אִתְּתָא הַהִיא דְּמִזְבֵּחַ אֲחִיתַת עֲלוֹי דִּמְעִין, וְאִתְחַבְּרָא כַּחֲדָא. וְיָלְדָה לּוֹ בָנִים אוֹ בָנוֹת הָאִשָּׁה וִילָדֶיהָ תִּהְיֶה לַאדֹנֶיהָ כְּמָה דְּאִתְּמַר.","דְּהָא אִי תָּב, וְאַתְקִין הַהוּא אֲתָר דְּפָגִים בְּחַיּיוֹי, אִתְקַבַּל קָמֵי מַלְכָּא קַדִּישָׁא, נָטִיל לֵיהּ, וְאַתְקִין לֵיהּ עַל תִּקּוּנוֹי לְבָתַר. וְדָא אִקְרֵי בַּעַל תְּשׁוּבָה, דְּהָא יָרִית מוֹתְבֵיהּ, דְּהַהוּא אֲתָר, דְּהַהוּא נָהָר דְּנָגִיד וְנָפִיק, וְאַתְקִין גַּרְמֵיהּ מִמַּה דְּהֲוָה בְּקַדְמִיתָא. (ס\"א ההוא אתר דפגים ואתקין ליה על תיקונוי בחיוי אתקבל קמי מלכא קדישא ונטיל ליה לבתר ודא אקרי בעל תשובה דהא אתקין גרמיה ממה דהוה בקדמיתא) כֵּיוָן דְּאִתְתָּקַּן וְתָב בְּתִיוּבְתָּא, הָא סָלִיק עַל תְקּוּנֵיהּ. דְּלֵית מִלָּה בְּעָלְמָא, וְלֵית מַפְתְחָא בְּעָלְמָא, דְּלָא תָּבַר הַהוּא דְּתָב בְּתִיוּבְתָּא.","מַאי יֵצֵא בְּגַפּוֹ. הָא אִתְּמַר, אֲבָל תּוּ רָזָא אִית בֵּיהּ, יֵצֵא בְּגַפּוֹ, כְּמָה דְּאַתְּ אָמַר, (משלי ט׳:ג׳) עַל גַּפֵּי מְרוֹמֵי קָרֶת, מַה לְהָתָם עִלּוּיָיא וּסְלִיקוּ, אוּף הָכָא עִלּוּיָיא וּסְלִיקוּ, אֲתָר דְמָרֵיהוֹן דְּתִיוּבְתָּא סַלְּקִין, אֲפִילּוּ צַדִּיקִים גְּמוּרִים לָא יַכְלִין לְמֵיקָם תַּמָּן. וּבְּגִין כָּךְ כֵּיוָן דְּתָב בְּתִיוּבְתָּא, קוּדְשָׁא בְּרִיךְ הוּא מְקַבֵּל לֵיהּ וַדַּאי מִיָּד.","תָּנֵינָן, לֵית מִלָּה בְּעָלְמָא דְּקַיְּימָא קַמֵּי תְּשׁוּבָה, וּלְכֹלָּא קוּדְשָׁא בְּרִיךְ הוּא מְקַבֵּל וַדַּאי. וְאִי תָּב בְּתִיוּבְתָּא הָא אִזְדָּמַן לָקֳבְלֵיהּ אֹרַח חַיִּים, וְאַף עַל גַּב דְּפָגִים מַה דְּפָגִים, כֹּלָּא אִתְתָּקַּן, וְכֹלָּא אִתְהַדַּר עַל תְקּוּנֵיהּ, דְּהָא אֲפִילּוּ בְּמַה דְּאִית בֵּיהּ אוֹמָאָה, (קמי קודשא בריך הוא קרי ביה כי יי' צבאות יעץ ומי יפר דא איהו רזא סתימא. ותו כד קודשא בריך הוא אומי אומאה לא אומי אלא אם לא יעביד תיובתא דהא לית פתגמא דקיימא קמי תיובתא ועל כלא מכפר קודשא בריך הוא כד עבדין תיובתא שלימתא) קוּדְשָׁא בְּרִיךְ הוּא מְקַבֵּל, דִּכְתִּיב, (ירמיהו כ״ב:כ״ד) חַי אֲנִי נְאֻם יְיָ' כִּי אִם יִהְיֶה כָּנְיָהוּ וְגוֹ' וּכְתִיב (ירמיהו כ״ב:ל׳) כִּתְבוּ אֶת הָאִישׁ הַזֶּה עֲרִירִי וְגוֹ'. וּבָתַר דְּתָב בְּתִיוּבְתָּא כְּתִיב, (דברי הימים א ג׳:י״ז) וּבְנֵי יְכָנְיָה אָסִיר בְּנוֹ וְגוֹ', מִכָּאן דִּתְשׁוּבָה מִתְּבַּר כַּמָּה גִּזְרִין וְדִינִין, וְכַמָּה שַׁלְשְׁלָאִין דְּפַרְזְלָא, וְלֵית מַאן דְּקַיְּימָא קַמֵּי דְּתִיוּבְתָּא.","וְעַל דָּא כְּתִיב, (ישעיהו ס״ו:כ״ד) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפּוֹשְׁעִים בִּי. אֲשֶׁר פָּשְׁעוּ בִּי, לָא כְּתִיב, אֶלָּא הַפּוֹשְׁעִים בִּי, דְּלָא בָּעָאן לְאָתָבָא, וּלְאִתְנַחֲמָא עַל מַה דְּעָבְדוּ. אֲבָל כֵּיוָן דְּאִתְנַחֲמוּ, הָא מְקַבֵּל לוֹן קוּדְשָׁא בְּרִיךְ הוּא."],[[0,"ומיד נפק מגו וכו':","ומיד יוצא ממקום ההוא, של סלע החזק, הוא לבדו, בלי נקבה, והולך ומשוטט בעולם עד שמוצא גואל להשיבו לעולם הזה להתתקן. והיינו אם בגפו יבא בגפו יצא, בלי נוקבא, זה שלא רצה לישא אשה שיהיה לו תולדות. וכיון שאין לו בת זוג, הוא מוכרח לישא אשה גרושה (כנ\"ל אות קס\"ב)."],[1,"אבל אם בעל אשה הוא:","שנשא אשה והשתדל בה, ולא יכול להוליד בנים, ההוא, אינו נגרש, כמו האחר, אינו בא יחידי ואינו יוצא יחידי, אלא אם בעל אשה הוא, הקב\"ה אינו מקפח שכר כל בריה, ואע\"פ שלא זכה בבנים, מה כתוב, ויצאה אשתו עמו. ושניהם באים בגלגול, וזוכים להתחבר יחד כבתחילה. והוא אינו לוקח אשה גרושה, כמו האחר שאין לו בת זוג, אלא לוקח אותה האשה שהשתדל בה בתחילה ולא זכו לבנים, עתה יזכו יחד, אם הם מתקנים מעשיהם, ועל זה כתוב, ויצאה אשתו עמו."],[2,"אם אדוניו יתן לו אשה:","הכתוב חוזר לדברים אחרים, לאותו שיצא יחידי בלי נוקבא כלל. ויגאל אותו מקום ההוא שנקרא שביעית, דהיינו המלכות, ושביעית ההוא נקראת אדוניו, אדון כל הארץ היא, אם אדוניו זה מרחם עליו, ומחזירו לעולם הזה כמו שהיה, ונותן לו אשה ההיא, אשר המזבח מוריד עליו דמעות, דהיינו אשה גרושה (כנ\"ל אות קס\"א) ומתחברים יחד, וילדה לו בנים או בנות, האשה וילדיה תהיה לאדונה. למלכות הקדושה. כמו שלמדנו."],[3,"דהא אי תב וכו':","כי אם חזר בתשובה, ותקן אותו המקום שפגם בחייו, הוא מתקבל לפני המלך הקדוש, הוא לוקחו ומתקן אותו על תקונו, אחר כך. וזה נקרא בעל תשובה. כי ירש מושבו של מקום ההוא, של ההוא נהר הנמשך ויוצא, דהיינו המלכות, כי נהר הנמשך ויוצא הוא יסוד, ומושבו, הוא המלכות. ומתקן את עצמו ממה שהיה בתחילה. כיון שנתתקן ושב בתשובה, הוא עולה על תקונו. שאין דבר בעולם, ואין מפתח בעולם, שלא ישבור, אותו השב בתשובה."],[4,"מאי יצא בגפו וכו':","שואל, מהו יצא בגפו. ומשיב, כבר למדנו, אבל עוד יש סוד בו, יצא בגפו, הוא כמש\"א, על גפי מרומי קרת, מה שם, גפי, פירושו, שבח והתעלות, אף גפו שבכאן, פירושו שבח והתעלות, המקום שבעלי תשובה עולים, שאפילו צדיקים גמורים אינם יכולים לעמוד שם. ומשום זה, כיון ששב בתשובה הקב\"ה מקבלו מיד."],[5,"תנינן לית מלה וכו':","למדנו אין דבר בעולם העומד לפני תשובה, ולכולם הקב\"ה ודאי מקבל. ואם שב בתשובה, הרי מזומן לו דרך החיים. ואע\"פ שפגם מה שפגם, הכל מתתקן, והכל חוזר על תקונו. כי אפילו במה שיש בו שבועה הקב\"ה מקבלו, שכתוב, חי אני נאם ה' כי אם יהיה כניהו וגו'. וכתוב, כתבו את האיש ערירי וגו', ואחר ששב בתשובה, כתוב, ובני יכניה אסיר בנו וגו'. מכאן, שהתשובה משברת כמה גזרות ודינים וכמה שרשרות של ברזל, ואין מי שעומד לפני תשובה."],[6,"ועל דא כתיב וכו':","ועל זה כתוב, ויצאו וראו בפגרי האנשים הפושעים בי. אשר פשעו בי, אינו כתוב, אלא הפושעים בי. דהיינו אותם שלא רצו לשוב בתשובה ולהתנחם על מה שעשו. אבל אם התנחמו ועשו תשובה, מקבל אותם הקב\"ה."]],[[0,"","וּמִיָּד יוֹצֵא מִתּוֹךְ אוֹתוֹ מָקוֹם שֶׁל הַסֶּלַע הֶחָזָק הוּא לְבַדּוֹ, וְהוֹלֵךְ וּמְשׁוֹטֵט בָּעוֹלָם עַד שֶׁמּוֹצֵא גוֹאֵל לַהֲשִׁיבוֹ. וְהַיְנוּ אִם בְּגַפּוֹ יָבֹא בְּגַפּוֹ יֵצֵא, זֶה שֶׁלֹּא רָצָה לָשֵׂאת שֶׁיִּהְיוּ לוֹ תוֹלָדוֹת."],[1,"","אֲבָל אִם בַּעַל אִשָּׁה הוּא, שֶׁנָּשָׂא וְהִשְׁתַּדֵּל בְּאִשְׁתּוֹ וְלֹא יָכֹל - הַהוּא לֹא מְגֹרָשׁ כְּאוֹתוֹ אַחֵר, לֹא יִכָּנֵס יְחִידִי וְלֹא יֵצֵא יְחִידִי. אֶלָּא אִם בַּעַל אִשָּׁה הוּא, הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מְקַפֵּחַ שְׂכַר כָּל בְּרִיּוֹתָיו, אַף עַל גַּב שֶׁלֹּא זָכוּ לְבָנִים, מַה כָּתוּב? וְיָצְאָה אִשְׁתּוֹ עִמּוֹ. וּשְׁנֵיהֶם בָּאִים בְּגִלְגּוּל וְזוֹכִים לְהִתְחַבֵּר כְּאֶחָד כְּמִקֹּדֶם. וְזֶה לֹא נָשָׂא אִשָּׁה שֶׁל גֵּרוּשִׁין, אֶלָּא אוֹתָהּ שֶׁהִשְׁתַּדֵּל בָּהּ בַּהַתְחָלָה וְלֹא זָכוּ - כָּעֵת יִזְכּוּ כְּאֶחָד אִם יְתַקְנוּ מַעֲשֵׂיהֶם, וְעַל זֶה וְיָצְאָה אִשְׁתּוֹ עִמּוֹ."],[2,"","אִם אֲדנָיו יִתֶּן לוֹ אִשָּׁה וְגוֹ'. (עתה) חוֹזֵר הַכָּתוּב לִדְבָרִים אֲחֵרִים (לדבר הראשון), לְאוֹתוֹ שֶׁיָּצָא יְחִידִי בְּלִי נְקֵבָה כְּלָל, וְיִגְאַל אוֹתוֹ אוֹתוֹ מָקוֹם שֶׁנִּקְרָא שְׁבִיעִית, וְאוֹתָהּ שְׁבִיעִית נִקְרֵאת אֲדנָיו, הוּא אֲדוֹן כָּל הָאָרֶץ. אִם אֲדנָיו - זֶה חָס עָלָיו וּמֵשִׁיב אוֹתוֹ לָעוֹלָם הַזֶּה יְחִידִי כְּמוֹ שֶׁהָיָה, וְנוֹתֵן לוֹ אִשָּׁה, אוֹתָהּ שֶׁמִּזְבֵּחַ הוֹרִיד עָלֶיהָ דְּמָעוֹת, וּמִתְחַבְּרִים כְּאֶחָד. וְיָלְדָה לּוֹ בָנִים אוֹ בָנוֹת הָאִשָּׁה וִילָדֶיהָ תִּהְיֶה לַאדנֶיהָ, כְּמוֹ שֶׁנֶּאֱמַר."],[3,"","שֶׁהֲרֵי אִם שָׁב וְהִתְקִין אוֹתוֹ מָקוֹם שֶׁפָּגַם בְּחַיָּיו, מִתְקַבֵּל לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, נוֹטֵל אוֹתוֹ וּמְתַקְּנוֹ עַל תִּקּוּנוֹ אַחַר כָּךְ. וְזֶה נִקְרָא בַּעַל תְּשׁוּבָה, שֶׁהֲרֵי יָרַשׁ אֶת מוֹשָׁבוֹ שֶׁל אוֹתוֹ הַמָּקוֹם שֶׁל אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, וּמְתַקֵּן אֶת עַצְמוֹ מִמַּה שֶּׁהָיָה בַּתְּחִלָּה. (אותו מקום שגפגם ומתקן אותו על תקונו בחייו, מתקבל לפני המלך הקדוש ולוקח אותו אחר כך, וזה נקרא בעל תשובה, שהרי תקן עצמו ממה שהיה בתחלה) כֵּיוָן שֶׁנִּתְקַן וְשָׁב בִּתְשׁוּבָה, הֲרֵי עָלָה עַל תִּקּוּנוֹ. שֶׁאֵין דָּבָר בָּעוֹלָם וְאֵין מַפְתֵּחַ בָּעוֹלָם שֶׁלֹּא שׁוֹבֵר אוֹתוֹ שֶׁשָּׁב בִּתְשׁוּבָה."],[4,"","מַה זֶּה יֵצֵא בְגַפּוֹ? הֲרֵי נִתְבָּאֵר. אֲבָל עוֹד סוֹד יֵשׁ בּוֹ, יֵצֵא בְּגַפּוֹ - כְּמוֹ שֶׁנֶּאֱמַר (משלי ט) עַל גַּפֵּי מְרֹמֵי קָרֶת. מַה לְּשָׁם עִלּוּי וְהִתְעַלּוּת, אַף כָּאן עִלּוּי וְהִתְעַלּוּת. מָקוֹם שֶׁבַּעֲלֵי תְשׁוּבָה עוֹלִים, אֲפִלּוּ צַדִּיקִים גְּמוּרִים לֹא יְכוֹלִים לַעֲמֹד שָׁם. וּמִשּׁוּם כָּךְ, כֵּיוָן שֶׁשָּׁב בִּתְשׁוּבָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַבֵּל אוֹתוֹ וַדַּאי מִיָּד."],[5,"","שָׁנִינוּ, אֵין דָּבָר בָּעוֹלָם שֶׁעוֹמֵד לִפְנֵי הַתְּשׁוּבָה, וְאֶת הַכֹּל הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַבֵּל וַדַּאי. וְאִם שָׁב בִּתְשׁוּבָה, הֲרֵי מְזֻמָּן כְּנֶגְדּוֹ אֹרַח חַיִּים. וְאַף עַל גַּב שֶׁפָּגַם מַה שֶּׁפָּגַם - הַכֹּל נִתְקָן וְהַכֹּל חוֹזֵר עַל תִּקּוּנוֹ, שֶׁהֲרֵי אֲפִלּוּ בְּמַה שֶּׁיֵּשׁ בּוֹ שְׁבוּעָה, (לפני הקדוש ברוך הוא נקרא בו כי ה' צבאות יעץ ומי יפר. זהו סוד סתום. ועוד, כאשר הקדושברוך הוא נשבע שבועה, לא נשבע אלא אם לא יעשה תשובה, שהרי אין דבר שעומד בפני התשובה, ועל הכל מכפר הקדוש ברוך הוא כאשר עושים תשובה שלמה) הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַבֵּל, שֶׁכָּתוּב חַי אֲנִי נְאֻם ה' כִּי אִם יִהְיֶה כָּנְיָהוּ וְגוֹ'. וְכָתוּב כִּתְבוּ אֶת הָאִישׁ הַזֶּה עֲרִירִי וְגוֹ'. וְאַחַר שֶׁשָּׁב בִּתְשׁוּבָה כָּתוּב, וּבְנֵי יְכָנְיָה אַסִּר בְּנוֹ וְגוֹ'. מִכָּאן שֶׁתְּשׁוּבָה מְשַׁבֶּרֶת כַּמָּה גְזֵרת וְדִינִים וְכַמָּה שַׁלְשְׁלָאוֹת בַּרְזֶל, וְאֵין מִי שֶׁעוֹמֵד לִפְנֵי הַתְּשׁוּבָה."],[6,"","וְעַל זֶה כָּתוּב, (ישעיה סו) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפֹּשְׁעִים בִּי. אֲשֶׁר פָּשְׁעוּ בִּי לֹא כָתוּב, אֶלָּא הַפֹּשְׁעִים בִּי. שֶׁלֹּא רוֹצִים לָשׁוּב וּלְהִתְנַחֵם עַל מַה שֶּׁעָשׂוּ. אֲבָל כֵּיוָן שֶׁהִתְנַחֲמוּ, הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַבֵּל אוֹתָם."]]],[["בְּגִין כַּךְ, בַּר נָשׁ דָּא, אַף עַל גַּב דְּפָשַׁע בֵּיהּ, וּפָגִים בְּאַתְרָא דְּלָא אִצְטְרִיךְ, וְתָב לְקַמֵיהּ, מְקַבֵּל לֵיהּ, וְחָס עָלֵיהּ, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא מָלֵא רַחֲמִין אִיהוּ, וְאִתְמְלֵי רַחֲמִים עַל כָּל עוֹבָדוֹי, כְּמָה דְאַתְּ אָמֵר (תהילים קמ״ה:ט׳) וְרַחֲמָיו עַל כָּל מַעֲשָׂיו. אֲפִילּוּ עַל בְּעִירֵי וְעוֹפוֹי מָאטוּן רַחֲמוֹי. אִי עָלַיְיהוּ מָאטוּן רַחֲמוֹי, כָּל שֶׁכֵּן עַל בְּנֵי נָשָׁא, דְּיַדְעִין וְאִשְׁתְּמוֹדְעָאן לְשָׁבְחָא לְמָארֵיהוֹן, דְּרַחֲמוֹי מָאטוּן עָלַיְיהוּ, וְשָׁרָאן עָלַיְיהוּ. וְעַל דָּא אָמַר דָּוִד, (תהילים קי״ט:קנ״ו) רַחֲמֶיךָ רַבִּים יְיָ' כְּמִשְׁפָּטֶיךָ חַיֵּינִי.","אִי עַל חַיָּיבִין מָאטוּן רַחֲמוֹי, כָּל שֶׁכֵּן עַל זַכָּאִין. אֶלָּא מַאן בָּעֵי אַסְוָותָא, אִינּוּן מָארֵי כְּאֵבִין, וּמַאן אִינּוּן מָארֵי כְּאֵבִין. אִלֵּין אִינּוּן חַיָּיבִין, אִינּוּן בָּעָאן אַסְוָותָא וְרַחֲמֵי, דְּקוּדְשָׁא בְּרִיךְ הוּא (רחמי) עָלַיְיהוּ, דְּלָא יְהוֹן שְׁבִיקִין מִנֵּיהּ, וְאִיהוּ דְּלָא אִסְתָּלַק מִנַּיְיהוּ, וִיתוּבוּן לָקֳבְלֵיהּ. כַּד מְקָרֵב קוּדְשָׁא בְּרִיךְ הוּא, בִּימִינָא מְקָרֵב. וְכַד דָּחֵי, בִּשְׂמָאלָא דָּחֵי. וּבְשַׁעֲתָא דְּדָחֵי, יְמִינָא מְקָרֵב. מִסִּטְרָא דָּא דָּחֵי, וּמִסִּטְרָא דָּא מְקָרֵב, וְקוּדְשָׁא בְּרִיךְ הוּא לָא שָׁבִיק רַחֲמוֹי מִנַּיְיהוּ.","תָּא חֲזֵי, מַה כְּתִיב (ישעיהו נ״ז:י״ח) וַיֵּלֶךְ שׁוֹבָב בְּדֶרֶך לִבּוֹ. וּכְתִיב בַּתְרֵיהּ, דְּרָכָיו רָאִיתִי וְאֶרְפָּאֵהוּ וְאַנְחֵהוּ וַאֲשַׁלֵּם נִחֻמִים לוֹ וְלַאֲבֵלָיו. וַיֵּלֶךְ שׁוֹבָב, אַף עַל גַּב דְּחַיָּיבִין עַבְדִין, כָּל מַה דְּעַבְדִין בְּזָדוֹן דְּאַזְלִין בְּאָרְחָא דְּלִבַּיְיהוּ, וְאַחֲרָנִין עַבְדִין בְּהוּ הַתְרָאָה, וְלָא בָּעָאן לְצַיְיתָא לוֹן. בְּשַׁעֲתָא דְּתָבִין בִּתְיוּבְתָּא, וְנַטְלִין אָרְחָא טָבָא דִּתְיוּבְתָּא, הָא אַסְוָותָא זְמִינָא לָקֳבְלַיְהוּ.","הַשְׁתָּא אִית לְאִסְתַּכְּלָא, אִי עַל חַיָּיא אָמַר קְרָא, אוֹ עַל מֵתַיָּיא אָמַר קְרָא. דְּהָא רֵישָׁא דִּקְרָא, לָאו אִיהוּ סֵיפָא. וְסֵיפָא, לָאו אִיהוּ רֵישָׁא. רֵישָׁא דִּקְרָא, אַחְזֵי עַל חַיָּיא. וְסוֹפֵיהּ אַחְזֵי עַל מֵתַיָּיא. אֶלָּא, קְרָא (ס\"א רישא דקרא) אָמַר, בְּעוֹד דְּבַר נָשׁ אִיהוּ בְּחַיּיוֹ, וְהָכִי הוּא, וַיֵּלֶךְ שׁוֹבָב בְּדֶרֶך לִבּוֹ, בְּגִין דְּיֵצֶר הָרַע דְּבֵיהּ, תַּקִּיף וְאִתְתָּקַּף בֵּיהּ, וְעַל דָּא אָזִל שׁוֹבָב, וְלָא בָּעֵי לְאָתָבָא בִּתְיוּבְתָּא.","קוּדְשָׁא בְּרִיךְ הוּא חָמֵי אָרְחוֹי, דְּקָא אַזְלִין בְּבִישׁ, בְּלָא תּוֹעַלְתָּא, אָמַר קוּדְשָׁא בְּרִיךְ הוּא, אֲנָא אִצְטְרִיכְנָא לְאַתְקְפָא בִּידֵיהּ, הֲדָא הוּא דִכְתִיב דְּרָכָיו רָאִיתִי, (וארפאהו) דְּקָא אַזְלִין בְּחָשׁוֹכָא, אֲנָא בָּעֵי לְמֵיהָב לֵיהּ אַסְוָותָא הֲדָא הוּא דִכְתִיב וְאֶרְפָּאֵהוּ, קוּדְשָׁא בְּרִיךְ הוּא אִיהוּ אָעִיל בְּלִבֵּיהּ אָרְחֵיהּ דִתִיוּבְתָּא וְאַסְוָותָא לְנִשְׁמָתֵיהּ. וְאַנְחֵהוּ, מַאי וְאַנְחֵהוּ. כְּמָה דְאַתְּ אָמֵר (שמות לכ) לֵךְ נְחֵה אֶת הָעָם. אַנְהִיג לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בְּאֹרַח מֵישָׁר, כְּמַאן דְּאַתְקִיף בִּידָא דְּאַחֲרָא, וְאַפְקֵיהּ מִגּוֹ חֲשׁוֹכָא.","וַאֲשַׁלֵּם נִחוּמִים לוֹ וְלַאֲבֵלָיו, הָא אִתְחָזֵי דְּמִיתָא אִיהוּ, (אלא) אִין, וַדַּאי מֵיתָא אִיהוּ, וְקַיְּימָא בַּחַיִּין דְּהוֹאִיל (אלא דאיהי איהו וקיימא בחיין והואיל) וְאִיהוּ רָשָׁע, מֵיתָא אִקְרֵי. מַהוּ וַאֲשַׁלֵּם נִחוּמִים לוֹ וְלַאֲבֵלָיו. אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא עָבִיד טִיבוּ עִם בְּנֵי נָשָׁא, דְּכֵיוָן דְּעָאל מִי\"ג שְׁנִין וּלְהָלְאָה, פָּקִיד עִמֵּיהּ (בראשית קמ\"ד ע\"ב, קס\"ה ע\"ב) תְּרֵין מַלְאָכִין נְטוּרִין דְּנַטְרֵי לֵיהּ, חַד מִימִינֵּיהּ, וְחַד מִשּׂמָאלֵיהּ.","כַּד אָזִיל בַּר נָשׁ בְּאֹרַח מֵישָׁר, אִינּוּן חַדָּאן בֵּיהּ, וְאִתָּקִיפוּ עִמֵּיהּ בְּחֶדְוָה, מַכְרְזָן קָמֵיהּ וְאַמְרִין, הָבוּ יְקָר לְדִיּוּקְנָא דְּמַלְכָּא. וְכַד אָזִיל בְּאֹרַח עָקִימוּ, אִינּוּן מִתְאַבְּלָן עָלֵיהּ, וּמִתְעַבְרָן מִנֵיה. כֵּיוָן דְּאַתְקִיף בֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְאַנְהִיג לֵיהּ בְּאֹרַח מֵישָׁר, כְּדֵין כְּתִיב, וַאֲשַׁלֵּם נִחֻמִים לוֹ וְלַאֲבֵלָיו. וַאֲשַׁלֵּם נִחוּמִים לוֹ בְּקַדְמִיתָא, דְּאִיהוּ אִתְנְחַם עַל מַה דְּעָבַד בְּקַדְמִיתָא, וְעַל מַה דְּעָבַד הַשְׁתָּא, וְתָב בִּתְיוּבְתָּא. וּבָתַר כֵּן וְלַאֲבֵלָיו, אִינּוּן מַלְאָכִין דַּהֲווֹ מִתְאַבְּלָן עָלֵיהּ כַּד אִתְעֲבָרוּ מִנֵּיהּ, וְהַשְׁתָּא דְּאִתְהַדָּרוּ בַּהֲדֵיהּ, הָא וַדַּאי נִחוּמִים לְכָל סִטְרִין.","וְהַשְׁתָּא אִיהוּ חַי וַדַּאי. חַי בְּכָל סִטְרִין, אָחִיד בְּאִילָנָא דְּחַיֵּי, וְכֵיוָן דְּאָחִיד בְּאִילָנָא דְּחַיֵּי, כְּדֵין אִקְרֵי בַּעַל תְּשׁוּבָה, (נשא קכ\"ב ע\"ב) דְּהָא כְּנֶסֶת יִשְׂרָאֵל, תְּשׁוּבָה אוּף הָכִי אִקְרֵי. וְאִיהוּ בַּעַל תְּשׁוּבָה אִקְרֵי. וְקַדְמָאֵי אָמְרוּ, בַּעַל תְּשׁוּבָה מַמָּשׁ. וְעַל דָּא, אֲפִילּוּ צַדִּיקִים גְּמוּרִים אֵינָם יְכוֹלִים לַעֲמוֹד, בְּמָקוֹם שֶׁבַּעֲלֵי תְּשׁוּבָה עוֹמְדִים.","דָּוִד מַלְכָּא אָמַר, (תהילים נ״א:ו׳) לְךָ לְבַדְּךָ חָטָאתִי וְהָרַע בְּעֵינֶיךָ עָשִׂיתִי וְגוֹ', לְךָ לְבַדְּךָ, מַאי לְךָ לְבַדְּךָ. אֶלָּא, בְּגִין דְּאִית חוֹבִין, דְּחָטֵי בַּר נָשׁ לְקוּדְשָׁא בְּרִיךְ הוּא וְלִבְנַי נָשָׁא. וְאִית חוֹבִין דְּחָטָא לִבְנֵי נָשָׁא, וְלָא לְקוּדְשָׁא בְּרִיךְ הוּא. וְאִית חוֹבִין דְּחָטֵי לְקוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי וְלָא לִבְנִי נָשָׁא. (אחרא) דָּוִד מַלְכָּא, חָב לְקוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, וְלָא לִבְנֵי נָשָׁא."],[[0,"בגין כך בר נש וכו':","משום זה אדם זה, אע\"פ שפשע בו, ופגם במקום שלא צריך, ושב לפניו, הוא מקבלו ומרחם עליו. כי הקב\"ה הוא מלא רחמים, ומתמלא רחמים על כל מעשיו, כש\"א ורחמיו על כל מעשיו. אפילו על בהמות ועופות מגיעים רחמיו. אם עליהם מגיעים רחמיו, כל שכן על בני אדם היודעים ונודעים לשבח לאדונם, שמגיעיב עליהם רחמיו, ושורים עליהם. ועל זה אמר דוד, רחמיך רבים ה' במשפטיך חייני."],[1,"אי על חייבין וכו':","אם על רשעים מגיעים רחמיו כל שכן על צדיקים. אלא מי צריך רפואה, אלו שהם בעלי כאבים. ומי הם בעלי כאבים, אלו הם הרשעים, והם הצריכים רפואה ורחמים, שקב\"ה מרחם עליהם שלא יהיו נעזבים ממנו, והוא אינו מסתלק מהם, וישובו לפניו בתשובה. כשהקב\"ה מקרב, מקרב בימין וכשהוא דוחה דוחה בשמאל. ובשעה שדוחה, הימין מקרב, מצד זה דוחה, ומצד זה מקרב, והקב\"ה אינו עוזב רחמיו מהם."],[2,"ת\"ח וילך שובב וכו':","בוא וראה, וילך שובב בדרך לבו, וכתוב אחריו, דרכיו ראיתי וארפאהו ואנחהו ואשלם נחומים לו ולאבליו. ומפרש. \u0003וילך שובב,\u0004 היינו, אע\"פ שהרשעים עושים כל מה שעושים, בזדון. והולכים בדרך לבם, ואחרים עושים בהם התראה, ואינם רוצים להקשיב להם. עם כל זה, בשעה שחוזרים בתשובה, ולוקחים דרך הטוב של תשובה, הרי רפואה מוכנת לפניהם."],[3,"השתא אית לאסתכלא וכו':","עתה יש להסתכל. אם על חיים מדבר הכתוב, או על מתים מדבר הכתוב, כי תחילת הכתוב אינו סופו, וסופו אינו כתחילתו. בתחלת הכתוב, מראה על חיים, שאומר וילך שובב וגו'. וסופו מראה על מתים, שאומר ואשלם נחומים לו ולאבליו. ומשיב, אלא הכתוב מדבר, בעוד שאדם הוא בחיים, וכך הוא, וילך שובב בדרך לבו, משום שיצר הרע שבו חזק ומתגבר בו, וע\"כ הולך שובב, ואינו רוצה לשוב בתשובה."],[4,"קב\"ה חמי אורחוי וכו':","הקב\"ה רואה דרכיו, שהולך ברע בלא תועלת, אומר הקב\"ה, אני צריך לאחוז אותו בידו, ז\"ש, \u0003דרכיו ראיתי,\u0004 שהולך בחשך, אני רוצה לתת לו רפואה. ז\"ש, \u0003וארפאהו,\u0004 הקב\"ה מביא בלבו דרך התשובה והרפואה לנשמתו. \u0003ואנחהו.\u0004 מהו ואנחהו. הוא כמש\"א, לך נחה את העם, הקב\"ה מנהיג אותו בדרך הישר, כמי שאוחז בידו של אחר ומוציאו מתוך החושך."],[5,"ואשלם נחומים לו ולאבליו:","שואל, הרי נראה שמת הוא, ואינו כתחילת הכתוב. ומשיב, כן ודאי שהוא מת, והוא עומד בחיים, שכיון שהוא רשע נקרא מת. מהו ואשלם נחומים לו ולאבליו. ואומר, אלא הקב\"ה עושה חסד עם בני אדם, שכיון שנכנס לשנת י\"ג ולהלאה, נותן עמו שני מלאכים שומרים ששומרים אותו, אחד מימינו ואחד משמאלו."],[6,"כד אזיל בר נש וכו':","כשהאדם הולך בדרך הישר, הם שמחים בו, ומחזקים אותו בשמחה, מכריזים לפניו ואומרים, תנו כבוד לצורתו של המלך. וכשהולך בדרך עקום, הם מתאבלים עליו ונעברים ממנו. כיון שהחזיק בו הקב\"ה, והנהיג אותו בדרך הישר, אז כתוב, ואשלם נחומים לו ולאבליו. \u0003ואשלם נחומים לו,\u0004 בתחילה, שהוא מתנחם על מה שעשה בתחילה, ועל מה שעשה עתה, וחוזר בתשובה. ואח\"כ, \u0003ולאבליו,\u0004 שהם המלאכים שהיו מתאבלים עליו כשעברו ממנו, ועתה שחזרו אליו, הרי נחומים לכל הצדדים, הן שמתנחם על מעשיו והן שמתנחם על צרותיו ואבלו."],[7,"והשתא איהו חי וכו':","ועתה הוא חי ודאי. חי בכל הצדדים, אוחז בעץ החיים, וכיון שאוחז בעץ החיים אז נקרא בעל תשובה, כי כנסת ישראל, שהוא המלכות, נקראת ג\"כ תשובה. כי תשובה הוא אותיות תשוב \u0003ו'\u0004 לגבי \u0003ה'\u0004, שה \u0003ו'\u0004 הוא עץ החיים, שהוא ז\"א, ו \u0003ה'\u0004 היא המלכות. וע\"כ נקראת המלכות תשובה. והוא נקרא בעל תשובה. והראשונים אמרו בעל תשובה ממש. דהיינו בעלה של המלכות הנקראת תשובה. כלומר שהוא משפיע לה. ועל כן, אפילו צדיקים גמורים אינם יכולים לעמוד במקום שבעלי תשובה עומדים."],[8,"דוד מלכא אמר וכו':","דוד המלך אמר, לך לבדך חטאתי והרע בעיניך עשיתי וגו'. \u0003לך לבדך\u0004 מהו לך לבדך. ומשיב, אלא משום שיש חטאים שהאדם חוטא להקב\"ה ולבני אדם. ויש חטאים שהאדם חוטא לבני אדם ולא להקב\"ה. ויש חטאים שחוטא להקב\"ה לבדו ולא לבני אדם. דוד המלך חטא להקב\"ה בלבדו ולא לבני אדם. וע\"כ אמר לך לבדך חטאתי."]],[[0,"","לָכֵן הָאָדָם הַזֶּה, אַף עַל גַּב שֶׁפָּשַׁע בּוֹ וּפָגַם בְּמָקוֹם שֶׁלֹּא צָרִיךְ וְשָׁב לְפָנָיו - מְקַבֵּל אוֹתוֹ וְחָס עָלָיו, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא מָלֵא רַחֲמִים, וּמִתְמַלֵּא רַחֲמִים עַל כָּל מַעֲשָׂיו, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קמה) וְרַחֲמָיו עַל כָּל מַעֲשָׂיו. אֲפִלּוּ עַל בְּהֵמוֹת וְעוֹפוֹת מַגִּיעִים רַחֲמָיו. אִם עֲלֵיהֶם מַגִּיעִים רַחֲמָיו, כָּל שֶׁכֵּן עַל בְּנֵי אָדָם שֶׁיּוֹדְעִים וּמַכִּירִים לְשַׁבֵּחַ רִבּוֹנָם שֶׁרַחֲמָיו מַגִּיעִים עֲלֵיהֶם וְשׁוֹרִים עֲלֵיהֶם. וְעַל זֶה אָמַר דָּוִד, (שם קיט) רַחֲמֶיךְ רַבִּים ה' כְּמִשְׁפָּטֶיךְ חַיֵּנִי."],[1,"","אִם עַל רְשָׁעִים מַגִּיעִים רַחֲמָיו, כָּל שֶׁכֵּן עַל צַדִּיקִים. אֶלָּא מִי צָרִיךְ רְפוּאָה? אוֹתָם בַּעֲלֵי כְאֵבִים. וּמִי הֵם בַּעֲלֵי כְאֵבִים? אֵלֶּה אוֹתָם רְשָׁעִים, הֵם צְרִיכִים רְפוּאָה וְרַחֲמִים, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא (מרחם) עֲלֵיהֶם שֶׁלֹּא יִהְיוּ עֲזוּבִים מִמֶּנּוּ, וְהוּא - שֶׁלֹּא מִסְתַּלּק מֵהֶם, וְיָשׁוּבוּ כְנֶגְדּוֹ. כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְקָרֵב, הוּא מְקָרֵב בַּיָּמִין. וּכְשֶׁדּוֹחֶה, דּוֹחֶה בַּשְּׂמֹאל. וּבְשָׁעָה שֶׁדּוֹחֶה, הַיָּמִין מְקָרֶבֶת. מִצַּד הַזֶּה דּוֹחֶה וּמֵהַצַּד הַזֶּה מְקָרֵב, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא עוֹזֵב אֶת רַחֲמָיו מֵהֶם."],[2,"","בֹּא וּרְאֵה מַה כָּתוּב, (ישעיה נז) וַיֵּלֶךְ שׁוֹבָב בְּדֶרֶךְ לִבּוֹ. וְכָתוּב אַחֲרָיו, דְּרָכָיו רָאִיתִי וְאֶרְפָּאֵהוּ וְאַנְחֵהוּ וַאֲשַׁלֵּם נִחֻמִים לוֹ וְלַאֲבֵלָיו. וַיֵּלֶךְ שׁוֹבָב, אַף עַל גַּב שֶׁהָרְשָׁעִים עוֹשִׂים כָּל מַה שֶּׁעוֹשִׂים בְּזָדוֹן, שֶׁהוֹלְכִים בְּדֶרֶךְ לִבָּם, וַאֲחֵרִים עוֹשִׂים בָּהֶם הַתְרָאָה וְלֹא רוֹצִים לְצַיֵּת לָהֶם - בְּשָׁעָה שֶׁשָּׁבִים בִּתְשׁוּבָה וְנוֹטְלִים דֶּרֶךְ טוֹבָה שֶׁל תְּשׁוּבָה, הֲרֵי הָרְפוּאָה מְזֻמֶּנֶת כְּנֶגְדָּם."],[3,"","עַכְשָׁו יֵשׁ לְהִתְבּוֹנֵן, אִם עַל הַחַיִּים אוֹמֵר הַכָּתוּב, אוֹ שֶׁעַל הַמֵּתִים אוֹמֵר הַכָּתוּב, שֶׁהֲרֵי רֹאשׁ הַפָּסוּק אֵינוֹ סוֹף, וְהַסּוֹף אֵינוֹ רֹאשׁ - רֹאשׁ הַכָּתוּב מַרְאֶה עַל הַחַיִּים, וְסוֹפוֹ מַרְאֶה עַל הַמֵּתִים. אֶלָּא שֶׁהַפָּסוּק (ראש הפסוק) אוֹמֵר, בְּעוֹד שֶׁהָאָדָם הוּא בְּחַיָּיו, וְכָךְ הוּא - וַיֵּלֶךְ שׁוֹבָב בְּדֶרֶךְ לִבּוֹ, מִשּׁוּם שֶׁיֵּשׁ בּוֹ יֵצֶר הָרָע חָזָק וּמַחֲזִיק בּוֹ, וְלָכֵן הוֹלֵךְ שׁוֹבָב וְלֹא רוֹצֶה לָשׁוּב בִּתְשׁוּבָה."],[4,"","הַקָּדוֹשׁ בָּרוּךָ הוּא רוֹאֶה אֶת דְּרָכָיו שֶׁהוֹלְכִים בְּרַע בְּלִי תוֹעֶלֶת, אוֹמֵר הַקָּדוֹשׁ בָּרוּךְ הוּא: אֲנִי צָרִיךְ לְהַחֲזִיק בְּיָדוֹ. זֶהוּ שֶׁכָּתוּב דְּרָכָיו רָאִיתִי (וארפאהו), שֶׁהוֹלְכִים בַּחֲשֵׁכָה, אֲנִי רוֹצֶה תֵת לוֹ רְפוּאָה. זֶהוּ שֶׁכָּתוּב וְאֶרְפָּאֵהוּ. הַקָּדוֹשׁ בָּרוּךְ הוּא מַכְנִיס לְלִבּוֹ דֶּרֶךְ הַתְּשׁוּבָה שֶׁלּוֹ וּרְפוּאָה לְנִשְׁמָתוֹ. וְאַנְחֵהוּ, מַה זֶּה וְאַנְחֵהוּ? כְּמוֹ שֶׁנֶּאֱמַר (שמותלב) לֵךְ נְחֵה אֶת הָעָם. הַקָּדוֹשׁ בָּרוּךְ הוּא מַנְהִיג אוֹתוֹ בְּדֶרֶךְ יָשָׁר כְּמִי שֶׁמַּחֲזִיק בְּיָדוֹ שֶׁל אַחֵר וּמוֹצִיא אוֹתוֹ מִתּוֹךְ הַחֲשֵׁכָה."],[5,"","וַאֲשַׁלֵּם נִחֻמִים לוֹ וְלַאֲבֵלָיו, הֲרֵי נִרְאֶה שֶׁהוּא מֵת! (אלא) כֵּן הוּא וַדַּאי מֵת וְעוֹמֵד בַּחַיִּים. שֶׁהוֹאִיל (אלא שהיא הוא ועומדים בחיים, והואיל) וְהוּא רָשָׁע, נִקְרָא מֵת. מַה זֶּה וַאֲשַׁלֵּם נִחֻמִים לוֹ וְלַאֲבֵלָיו? אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה טוֹב עִם בְּנֵי אָדָם, שֶׁכֵּיוָן שֶׁנִּכְנָס מִשְּׁלֹשׁ עֶשְׂרֵה שָׁנִים וָמַעְלָה, מַפְקִיד עִמּוֹ שְׁנֵי מַלְאָכִים שׁוֹמְרִים שֶׁשּׁוֹמְרִים אוֹתוֹ, אֶחָד מִימִינוֹ וְאֶחָד מִשְּׂמֹאלוֹ."],[6,"","כְּשֶׁאָדָם הוֹלֵךְ בְּדֶרֶךְ יָשָׁר, הֵם שְׂמֵחִים בּוֹ וּמַחֲזִיקִים אוֹתוֹ בְּשִׂמְחָה, מַכְרִיזִים לְפָנָיו וְאוֹמְרִים: תְּנוּ כָבוֹד לִדְמוּת הַמֶּלֶךְ. וּכְשֶׁהוֹלֵךְ בְּדֶרֶךְ עָקֹם, הֵם מִתְאַבְּלִים עָלָיו וְעוֹבְרִים מִמֶּנּוּ. כֵּיוָן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַחֲזִיק בּוֹ וּמַנְהִיג אוֹתוֹ בְּדֶרֶךְ יְשָׁרָה, אָז כָּתוּב וַאֲשַׁלֵּם נִחֻמִים לוֹ וְלַאֲבֵלָיו. וַאֲשַׁלֵּם נִחֻמִים לוֹ בַּתְּחִלָּה, שֶׁהוּא הִתְנַחֵם עַל מַה שֶּׁעָשָׂה בַּתְּחִלָּה וְעַל מַה שֶּׁעוֹשֶׂה עַכְשָׁו וְשָׁב בִּתְשׁוּבָה. וְאַחַר כָּךְ וְלַאֲבֵלָיו, אוֹתָם מַלְאָכִים שֶׁהָיוּ מִתְאַבְּלִים עָלָיו כְּשֶׁעָבְרוּ מִמֶּנּוּ, וְעַכְשָׁו שֶׁחָזְרוּ עִמּוֹ, הֲרֵי וַדַּאי נִחוּמִים לְכָל הַצְּדָדִים."],[7,"","וְעַכְשָׁו הוּא וַדַּאי חַי. חַי בְּכָל הַצְּדָדִים, אָחוּז בְּעֵץ הַחַיִּים. וְכֵיוָן שֶׁאָחוּז בְּעֵץ הַחַיִּים, אָז נִקְרָא בַּעַל תְּשׁוּבָה, שֶׁהֲרֵי כְּנֶסֶת יִשְׂרָאֵל נִקְרֵאת אַף כָּךְ תְּשׁוּבָה, וְהוּא נִקְרָא בַּעַל תְּשׁוּבָה. וְהָרִאשׁוֹנִים אָמְרוּ, בַּעַל תְּשׁוּבָה מַמָּשׁ. וְעַל זֶה אֲפִלּוּ צַדִּיקִים גְּמוּרִים אֵינָם יְכוֹלִים לַעֲמֹד בְּמָקוֹם שֶׁבַּעֲלֵי תְשׁוּבָה עוֹמְדִים."],[8,"","דָּוִד הַמֶּלֶךְ אָמַר, (תהלים נא) לְךְ לְבַדְּךְ חָטָאתִי וְהָרַע בְּעֵינֶיךְ עָשִׂיתִי וְגוֹ'. לְךְ לְבַדְּךְ, מַה זֶּה לְךְ לְבַדְּךְ? אֶלָּא מִשּׁוּם שֶׁיֵּשׁ חֲטָאִים שֶׁחוֹטֵא אָדָם לַקָּדוֹשׁ-בָּרוּךְ-הוּא וְלִבְנֵי אָדָם, וְיֵשׁ חֲטָאִים שֶׁחָטָא לִבְנֵי אָדָם וְלֹא לַקָּדוֹשׁ-בָּרוּךְ- הוּא, וְיֵשׁ חֲטָאִים שֶׁחוֹטֵא לַקָּדוֹשׁ-בָּרוּךְ-הוּא לְבַדּוֹ וְלֹא לִבְנֵי אָדָם (אחרים). דָּוִד הַמֶּלֶךְ חָטָא לַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ וְלֹא לִבְנֵי אָדָם."]]],[["וְאִי תֵּימָא הָא חָב הַהוּא חוֹבָה דְּבַת שֶׁבַע, וְתָנֵינָן, מַאן דְּאָתֵי עַל עֶרְוָה אִתְּתָא בִּרְעוּתָהּ אָסְרָה עַל בַּעְלָהּ, וְחָב לְחַבְרֵיהּ, וְחָב לְקוּדְשָׁא בְּרִיךְ הוּא. לָאו הָכִי הוּא דְּהַהוּא דְּאַתְּ אָמַר. בְּהֶיתֵּרָא הֲוָה, וְדָוִד דִּילֵיהּ נָקַט, וְגֵט הֲוָה לָהּ מִבַּעְלָהּ, עַד לָא יֵהַךְ לִקְרָבָא, דְּהָכִי הֲוָה מִנְהֲגָא דְּכָל יִשְׂרָאֵל, דְּיַהֲבִין גֵּט זְמַן לְאִתְּתֵיהּ, כָּל דְּנָפִיק חֵילָא. וְכֵן עָבֵד אוּרִיָּה לְבַת שֶׁבַע. וּלְבָתַר דְּעָבַר זְמַן וַהֲוַת פְּטוּרָא לְכֹלָּא, נָטַל לָהּ דָּוִד. וּבְהֶיתֵּרָא עָבַד כָּל מַה דְּעָבַד.","דְּאִלְמָלֵא לָאו הָכִי, וּבְאִסוּרָא הֲוָה, לָא שַׁבְקָה קוּדְשָׁא בְּרִיךְ הוּא לְגַבֵּיהּ. וְהַיְינוּ דִּכְתִּיב לְסַהֲדוּתָא, (שמואל ב י״ב:כ״ד) וַיְנַחֵם דָּוִד אֵת בַּת שֶׁבַע אִשְׁתּוֹ. סַהֲדוּתָא דְּאִשְׁתּוֹ הִיא, וַדַּאִי אִשְׁתּוֹ, וּבַת זוּגוֹ הֲוַת, דְּאִזְדַּמְּנַת לְגַבֵּיהּ, מִיּוֹמָא דְּאִתְבְּרִי עָלְמָא. (ורזא דמלתא מלכותא דלעילא דאיהו אתעביד רגלה רביעא למרכבתא עלאה ואתקרי בת שבע על אבן אחת שבע עיניים) הָא סַהֲדוּתָא דְּלָא חָב דָּוִד חוֹבָה דְּבַת שֶׁבַע כִּדְקָאמְרַן.","וּמַה הִיא חוֹבָה דְּחָב, (אלא) לְקוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, וְלָא לְאַחֲרָא. דְּקָטַל לְאוּרִיָּה בְּחֶרֶב בְּנֵי עַמּוֹן, וְלָא קַטְלֵיהּ אִיהוּ בְּשַׁעֲתָא דְּאָמַר לֵיהּ וַאֲדֹנִי יוֹאָב, דְּהָא דָּוִד הֲוָה רִבּוֹן עָלֵיהּ, (ועל יואב) וְקָרָא אוֹכַח, דִּכְתִּיב, (שמואל בכג) אֵלֶּה שְׁמוֹת הַגִּבּוֹרִים אֲשֶׁר לְדָוִד, וְלא אֲשֶׁר לְיוֹאָב, וְלֹא קַטְלֵיהּ הַהִיא שַׁעֲתָא, וְקַטְלֵיהּ בְּחֶרֶב בְּנֵי עַמּוֹן.","וְקָרָא אָמַר, וְלא נִמְצָא אִתּוֹ דָּבָר, (מלכים א ט״ו:ה׳) רַק בִּדְבַר אוּרִיָּה הַחִתִּי. רַק לְמָעוּטֵי קָא אָתֵי, בִּדְבַר אוּרִיָּה, וְלָא בְּאוּרִיָּה. וְקוּדְשָׁא בְּרִיךְ הוּא אָמַר, וְאוֹתוֹ הָרַגְתָּ בְּחֶרֶב בְּנֵי עַמּוֹן, וְכָל חֶרֶב בְּנִי עַמּוֹן, הֲוָה חָקִיק בֵּיהּ חִוְיָא עָקִים, דִּיּוּקְנָא דְּדַרְקוֹן, וְאִיהוּ עֲבוֹדָה זָרָה דִּלְהוֹן. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, יָהָבַת חֵילָא לְהַהוּא שִׁקּוּץ. (ד\"א דכיון דחרב בני עמון אתגבר ההיא שעתא על אוריה כמה תוקפא תקיף ההוא חויא עקימא) בְּגִין דִּבְשַׁעֲתָא דְּקָטְלוּ בְּנֵי עַמּוֹן לְאוּרִיָּה, וְסַגִּיאִין מִבְּנִי יִשְׂרָאֵל עִמֵּיהּ, וְאִתְגַּבַּר בְּהַהִיא שַׁעֲתָא חֶרֶב בְּנֵי עַמּוֹן, כַּמָּה תֻּקְפָּא אִתְתָּקַּף הַהִיא עֲבוֹדָה זָרָה שִׁקּוּץ.","וְאִי תֵּימָא, אוּרִיָּה לָא הֲוָה זַכָּאי, כֵּיוָן דִּכְתִּיב עָלֵיהּ אוּרִיָּה הַחִתִּי. לָאו הָכִי, זַכָּאָה הֲוָה, אֶלָּא דִּשְׁמָא דְּאַתְרֵיהּ הֲוָה חִתִּי. כְּמָה דְאַתְּ אָמֵר (שופטים י״א:א׳) וְיִפְתָּח הַגִּלְעָדִי, עַל שׁוּם אַתְרֵיהּ אִתְקְרֵי הָכִי.","וְעַל דָּא בִּדְבַר אוּרִיָּה הַחִתִּי, דְּשִׁקּוּץ בְּנֵי עַמּוֹן אִתְגַּבָּר עַל מַחֲנִה אֱלֹהִים, דְּמַשִּׁרְיָתָא דְּדָוִד, דִּיּוּקְנָא מַמָּשׁ דִּלְעֵילָּא הֲווֹ. וּבְהַהוּא שַׁעֲתָא דְּפָגִים דָּוִד מַשִּׁרְיָתָא דָּא, פָּגִים לְעֵילָּא מַשִּׁרְיָתָא אַחֲרָא. וְעַל דָּא אָמַר דָּוִד, (תהילים נ״א:ו׳) לְךָ לְבַדְּךָ חָטָאתִי. לְבַדְּךָ, וְלָא לְאַחֲרָא. דָּא הֲוָה הַהוּא חוֹבָה דְּחָב לְגַבֵּיהּ. וְדָא הוּא בִּדְבַר אוּרִיָּה. וְדָא הוּא בְּחֶרֶב בְּנֵי עַמּוֹן.","כְּתִיב, (דברי הימים ב ט״ז:ט׳) כִּי יְיָ' עֵינָיו מְשׁוֹטְטוֹת בְּכָל הָאָרֶץ, אִלֵּין (ויחי רמ\"ח ע\"א) נוּקְבִין. וּכְתִיב (זכריה ד׳:י׳) עֵינִי יְיָ' הֵמָּה מְשׁוֹטְטִים, אִלֵּין דְּכוּרִין, וְהָא יְדִיעָן אִינּוּן. דָּוִד אֲמַר (תהילים נ״א:ו׳) וְהָרַע בְּעֵינְיךָ עָשִׂיתִי. בְּעֵינֶיךָ, לִפְנֵי עֵינֶיךָ מִבָּעֵי לֵיהּ. אֶלָּא מַאי בְּעֵינֶיךָ, אָמַר דָּוִד, בְּהַהוּא אֲתָר דְּחַבְנָא, בְּעֵינֶיךָ הֲוָה. דַּהֲוֵינָא יָדַע, דְּהָא עֵינְיךָ הֲווֹ זְמִינִין, וְקַיְּימִין קָמָאי, וְלָא חַשַׁבְּנָא לוֹן, הֲרֵי חוֹבָא דְּחַבְנָא, וְעַבַדְנָא, בְּאָן אֲתָר הֲוָה, בְּעֵינֶיךָ.","לְמַעַן תִּצְדַּק בְּדָבְרֶךָ תִּזְכֶּה בְשָׁפְטֶךָ, וְלֹא יְהֵא לִי פִּתְחוֹן פֶּה לְמֵימָר קַמָּךְ. תָּא חֲזֵי, כָּל אוּמָנָא, כַּד מַלִּיל, בְּאוּמָנֻתֵיהּ מַלִּיל. דָּוִד בְּדִיחָא דְּמַלְכָּא הֲוָה, וְאַף עַל גַּב דְּהֲוָה בְּצַעֲרָא, כֵּיוָן דְּהֲוָה קַמֵּי מַלְכָּא, תָּב לִבְדִיחוּתֵיהּ, כְּמָה דְּהֲוָה, בְּגִין לְבַדְּחָא לְמַלְכָּא.","אָמַר, מָארֵי דְּעָלְמָא, אֲנָא אֲמֵינָא, (תהלים כו) בְּחָנֵנִי יְיָ' וְנַסֵּנִי, וְאַתְּ אָמַרְתְּ דְּלָא אִיכוּל לְקַיְּימָא בְּנִסְיוֹנָךְ. הָא חָבְנָא, לְמַעַן תִּצְדַּק בְּדָבְרֶךָ, וִיהֵא מִילָּךְ קְשׁוֹט, דְּאִלְמָלֵא לָא חָבְנָא, יְהֵא מִלָּה דִּילִי קְשׁוֹט, וִיהֵא מִילָּךְ בְּרֵיקַנְיָּא, הַשְׁתָּא דְּחַבְנָא, בְּגִין דְּלֶהֱוֵי מִילָּךְ קְשׁוֹט, יָהִיבְנָא אֲתָר לְצַדְּקָא מִילָּךְ, בְּגִין כַּךְ עֲבִידְנָא, לְמַעַן תִּצְדַּק בְּדָבְרֶךָ תִּזְכֶּה בְשָׁפְטֶךָ. אַהְדָּר דָּוִד לְאוּמָנוּתֵיהּ, וְאָמַר גּוֹ צַעֲרֵיהּ מִלִּין דִּבְדִיחוּתָא לְמַלְכָּא."],[[0,"ואי תימא הא וכו':","שואל, ואם תאמר, הרי חטא, חטא ההוא של בת שבע. ולמדנו, מי שבא על ערוה, אסרה על בעלה, ונמצא חוטא לחבירו וחוטא להקב\"ה. ומשיב, אינו כן, חטא ההוא שאתה אומר, היה בהתר, ודוד לקח את שלו כי גט היה לה מבעלה עד שלא הלך למלחמה, כי כן היה המנהג של כל ישראל שנתנו גט על זמן לנשיהם, כל היוצא לצבא. וכן עשה אוריה לבת שבע. ולאחר שעבר הזמן והיתה מותרת לכל, לקחה דוד. ובהתר עשה כל מה שעשה."],[1,"דאלמלא לאו הכי וכו':","כי אם לא היה כן, ובאיסור היה, לא היה הקב\"ה עזב אותה אצלו. והיינו שכתוב לעדות, וינחם דוד את בת שבע אשתו. שזה עדות שהיא אשתו, ודאי אשתו ובת זוגו היתה, שהיא מוכנת לו מיום שנברא העולם. הרי עדות, שלא חטא דוד החטא של בת שבע, כמו שאמרנו."],[2,"ומה היא חובה וכו':","ומה הוא החטא שחטא להקב\"ה לבדו ולא לאחר. הוא, שהרג את אוריה בחרב בני עמון, והוא לא הרגו בשעה שאמר לו, ואדוני יואב, שהרי הוא היה אדונו, והמקרא מוכיח, שכתוב, ואלה שמות הגבורים אשר לדוד, ולא אשר ליואב, ונמצא שהוא מורד במלכות, והמורד במלכות חייב מיתה. ולא הרגו בשעה ההיא, אלא הרגו בחרב בני עמון."],[3,"וקרא אמר ולא וכו':","והכתוב, אומר, ולא נמצא אתו דבר רק בדבר אוריה החתי, רק, בא למעט, בדבר אוריה חטא, ולא חטא באוריה עצמו. והקב\"ה אמר ואותו הרגת בחרב בני עמון, וכל חרב מבני עמון היה חקוק בו נחש עקום, צורה של דרקון שהוא עבודה זרה שלהם אמר הקב\"ה נתת כח לשקוץ ההוא. משום שבשעה שהרגו בני עמון את אוריה, ורבים מבני ישראל עמו, נתגבר בשעה ההוא חרב בני עמון, וכמה תוקף נתחזק עבודה זרה ההיא, שקוץ."],[4,"ואי תימא אוריה וכו':","ואם תאמר, שאוריה לא היה צדיק, כיון שכתוב עליו אוריה החתי. אינו כן, היה צדיק, אלא שם מקומו היה חתי. כש\"א, ויפתח הגלעדי, שעל שם מקומו נקרא כך, וכן אוריה החתי."],[5,"ועל דא בדבר וכו':","ועל כן כתוב, בדבר אוריה החתי, ולא באוריה עצמו, כי כבר היה חייב מיתה מטעם מורד במלכות כנ\"ל. והיינו, כי גרם, ששקוץ בני עמון נתגבר על מחנה אלקים של מחנה דוד, שהיה ממש הצורה של מעלה. של צבאות המלכות העליונה. ובשעה שפגם דוד מחנה הזה שלו, פגם למעלה מחנה אחר. ועל כן אמר דוד, לך לבדך חטאתי, לבדך, ולא לאחר היה חטא ההוא שחטא לו. וזה הוא שהכתוב אומר, בדבר אוריה, וזהו שהכתוב אומר, בחרב בני עמון. דהיינו שהחטא לא היה באוריה עצמו אלא בדבר אוריה, והיינו מה שנתן כח לחרב בני עמון."],[6,"כתיב, כי ה' וגו':","כתוב, כי ה' עיניו משוטטות בכל הארץ, אלו הן נקבות, כי אומר בלשון נקבה. וכתוב, עיני ה' המה משוטטים, אלו הם זכרים, שאומר בלשון זכר והרי הם ידועים. כי יש בהם בחינת זכר ובחינת נקבה. דוד אמר, והרע בעיניך עשיתי. שואל אומר, בעיניך, לפני עיניך, היה צריך לומר. ומשיב, אלא מה שאומר בעיניך. הוא כי אמר דוד במקום ההוא שחטאתי, בעיניך היה, כי הייתי יודע, שעיניך מוכנים ועומדים לפני, ולא החשבתי אותם, הרי החטא שחטאתי ועשיתי, היה בעיניך."],[7,"למען תצדק בדברך תזכה בשפטך:","ולא יהיה לו פתחון פה לומר לפניך, בחנני ה' ונסני. בוא וראה כל אומן כשמדבר, הוא מדבר באומנותו. דוד היה הבדחן של המלך ואע\"פ שהיה בצער, כיון שהיה לפני המלך חזר לבדחנות שלו כמו שהיה, כדי לשמח את המלך."],[8,"אמר מארי דעלמא וכו':","אמר, רבון העולם, אני אמרתי בחנני ה' ונסני, ואתה אמרת שלא אוכל לעמוד בנסיונך. הרי חטאתי למען תצדק בדברך, ויהיה דברך אמת, כי אם לא חטאתי, היה הדבר שלי אמת ודברך בריק. עתה שחטאתי, הוא, כדי שדברך יהיה אמת. נתתי מקום להצדיק דברך, משום זה עשיתי, למען תצדק בדברך תזכה בשפטך. כי חזר דוד לאומנותו, ואמר בתוך צערו, דברי בדחנות אל המלך."]],[[0,"","וְאִם תֹּאמַר, הֲרֵי חָטָא אוֹתוֹ הַחֵטְא שֶׁל בַּת שֶׁבַע, וְשָׁנִינוּ, מִי שֶׁבָּא עַל אִשָּׁה עֶרְוָה בִּרְצוֹנָה אָסַר אוֹתָהּ עַל בַּעְלָהּ, וְחָטָא לַחֲבֵרוֹ, וְחָטָא לַקָּדוֹשׁ-בָּרוּךְ-הוּא - לֹא כָּךְ הוּא. שֶׁהַהוּא שֶׁאַתָּה אוֹמֵר בְּהֶתֵּר הָיָה, וְדָוִד לָקַח אֶת שֶׁלּוֹ, וְגֵט הָיָה לָהּ מִבַּעְלָהּ טֶרֶם שֶׁיָּצָא לַקְּרָב, שֶׁכָּךְ הָיָה מִנְהָג שֶׁל כָּל יִשְׂרָאֵל שֶׁנּוֹתְנִים גֵּט זְמַן לְאִשְׁתּוֹ כָּל שֶׁיּוֹצֵא לַחַיִל, וְכָךְ עָשָׂה אוּרִיָּה לְבַת שֶׁבַע, וְאַחַר שֶׁעָבַר זְמַן וְהָיְתָה פְּטוּרָה לַכֹּל, לָקַח אוֹתָהּ דָּוִד, וּבְהֶתֵּר עָשָׂה כָּל מַה שֶּׁעָשָׂה."],[1,"","שֶׁאִלְמָלֵא לֹא כָּךְ וְזֶה הָיָה בְּאִסּוּר, לֹא הָיָה מַשְׁאִיר אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּיָדוֹ. וְהַיְנוּ שֶׁכָּתוּב לְעֵדוּת, (שמואל ב יב) וַיְנַחֵם דָּוִד אֵת בַּת שֶׁבַע אִשְׁתּוֹ. עֵדוּת שֶׁאִשְׁתּוֹ הִיא, וַדַּאי אִשְׁתּוֹ, וּבַת זוּגוֹ הָיְתָה שֶׁהִזְדַּמְּנָה אֵלָיו מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם. (וסוד הדבר מלכות של מעלה שהוא נעשה רגל רביעית למרכבה העליונה, ונקראבתשבע, עלאבןאחתשבעהעינים) הֲרֵי עֵדוּת שֶׁלֹּא חָטָא דָוִד אֶת חֵטְא בַּת שֶׁבַע כְּמוֹ שֶׁאָמַרְנוּ."],[2,"","וּמָה הַחֵטְא שֶׁחָטָא? (אלא) לַקָּדוֹשׁ-בָּרוּךְ-הוּא לְבַדּוֹ וְלֹא לְאַחֵר. שֶׁהָרַג אֶת אוּרִיָּה בְּחֶרֶב בְּנֵי עַמּוֹן וְלֹא הָרַג אוֹתוֹ בְּשָׁעָה שֶׁאָמַר לוֹ וַאדנִי יוֹאָב, שֶׁהֲרֵי דָּוִד הָיָה רִבּוֹן עָלָיו (ועל יואב), וְהַכָּתוּב מוֹכִיחַ, שֶׁכָּתוּב (שם כג) אֵלֶּה שְׁמוֹת הַגִּבֹּרִים אֲשֶׁר לְדָוִד, וְלֹא אֲשֶׁר לְיוֹאָב. וְלֹא הָרַג אוֹתוֹ בְּאוֹתָהּ שָׁעָה, וְהָרַג אוֹתוֹ בְּחֶרֶב בְּנֵי עַמּוֹן."],[3,"","וְהַכָּתוּב אוֹמֵר וְלֹא נִמְצָא אִתּוֹ דָּבָר, רַק בִּדְבַר אוּרִיָּה הַחִתִּי. רַק לְמַעֵט הוּא בָּא. בִּדְבַר אוּרִיָּה, וְלֹא בְּאוּרִיָּה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר, וְאוֹתוֹ הָרַגְתָּ בְּחֶרֶב בְּנֵי עַמּוֹן. וְכָל חֶרֶב בְּנֵי עַמּוֹן הָיָה חָקוּק בּוֹ נָחָשׁ עָקֹם, דְּיוֹקָן שֶׁל דַּרְקוֹן, וְהוּא עֲבוֹדָה זָרָה שֶׁלָּהֶם. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, נָתַתָּ כֹּחַ לְאוֹתוֹ שִׁקּוּץ. (שכיון שחרב בני עמון התגברה אותה שעה על אוריה, כמה חזק התחזק אותו נחש עקם) מִשּׁוּם שֶׁבְּשָׁעָה שֶׁהָרְגוּ בְּנֵי עַמּוֹן אֶת אוּרִיָּה, וְעִמּוֹ רַבִּים מִבְּנֵי יִשְׂרָאֵל, וְהִתְגַּבְּרָה בְּאוֹתָהּ שָׁעָה חֶרֶב בְּנֵי עַמּוֹן, כַּמָּה חֹזֶק הִתְחַזְּקָה אוֹתָהּ עֲבוֹדָה זָרָה שִׁקּוּץ."],[4,"","וְאִם תֹּאמַר שֶׁאוּרִיָּה לֹא הָיָה צַדִּיק, כֵּיוָן שֶׁכָּתוּב עָלָיו אוּרִיָּה הַחִתִּי - לֹא כָּךְ! צַדִּיק הוּא הָיָה, אֶלָּא שֶׁשֵּׁם מְקוֹמוֹ הָיָה חִתִּי, כְּמוֹ שֶׁנֶּאֱמַר וְיִפְתָּח הַגִּלְעָדִי, עַל שֵׁם מְקוֹמוֹ נִקְרָא כָּךְ."],[5,"","וְעַל זֶה בִּדְבַר אוּרִיָּה הַחִתִּי, שֶׁשִּׁקּוּץ בְּנֵי עַמּוֹן הִתְגַּבֵּר עַל מַחֲנֵה אֱלֹהִים, שֶׁמַּחֲנוֹת דָּוִד הָיוּ מַמָּשׁ דְּיוֹקָן שֶׁלְּמַעְלָה, וּבְאוֹתָהּ שָׁעָה שֶׁפָּגַם דָּוִד מַחֲנֶה זֶה, פָּגַם לְמַעְלָה מַחֲנֶה אַחֵר. וְעַל זֶה אָמַר דָּוִד, לְךְ לְבַדְּךְ חָטָאתִי. לְבַדְּךְ וְלֹא לְאַחֵר. שֶׁהוּא הָיָה אוֹתוֹ הַחֵטְא שֶׁחָטָא אֵלָיו. וְזֶהוּ בִּדְבַר אוּרִיָּה, וְזֶהוּ בְּחֶרֶב בְּנֵי עַמּוֹן."],[6,"","כָּתוּב, כִּי ה' עֵינָיו מְשּטְטוֹת בְּכָל הָאָרֶץ, אֵלּוּ הַנְּקֵבוֹת. וְכָתוּב, (זכריה ד) עֵינֵי ה' הֵמָּה מְשׁוֹטְטִים, אֵלּוּ הַזְּכָרִים. וַהֲרֵי הֵם יְדוּעִים. דָּוִד אָמַר (תהלים נא) וְהָרַע בְּעֵינֶיךְ עָשִׂיתִי. בְּעֵינֶיךְ? לִפְנֵי עֵינֶיךְ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא מַה זֶּה בְּעֵינֶיךְ? אָמַר דָּוִד, בְּאוֹתוֹ מָקוֹם שֶׁחָטָאתִי, בְּעֵינֶיךְ הָיָה. שֶׁהָיִיתִי יוֹדֵעַ שֶׁהֲרֵי עֵינֶיךְ הָיוּ זְמִינִים וְעוֹמְדִים לְפָנַי וְלֹא הֶחְשַׁבְתִּי אוֹתָם, הֲרֵי הַחֵטְא שֶׁחָטָאתִי וְעָשִׂיתִי, בְּאֵיזֶה מָקוֹם הָיָה? בְּעֵינֶיךְ."],[7,"","לְמַעַן תִּצְדַּק בְּדָבְרֶךְ תִּזְכֶּה בְשָׁפְטֶךְ, וְלֹא יִהְיֶה לִי פִּתְחוֹן פֶּה לוֹמַר לְפָנֶיךְ. בֹּא וּרְאֵה, כָּל אֻמָּן כְּשֶׁמְּדַבֵּר, הוּא מְדַבֵּר בְּאֻמָּנוּתוֹ. דָּוִד הָיָה בַּדְּחַן הַמֶּלֶךְ, וְאַף עַל גַּב שֶׁהָיָה בְצַעַר, כֵּיוָן שֶׁהָיָה לִפְנֵי הַמֶּלֶךְ, שָׁב לְבַדְּחָנוּתוֹ כְּמוֹ שֶׁהָיָה כְּדֵי לְבַדֵּחַ אֶת הַמֶּלֶךְ."],[8,"","אָמַר, רִבּוֹן הָעוֹלָם, אֲנִי אָמַרְתִּי (שם כז) בְּחָנֵנִי ה' וְנַסֵּנִי, וְאַתָּה אָמַרְתָּ שֶׁלֹּא אוּכַל לַעֲמֹד בְּנִסְיוֹנְךְ. הֲרֵי חָטָאתִי לְמַעַן תִּצְדַּק בְּדָבְרֶךְ וְיִהְיֶה דְבָרְךְ אֱמֶת, שֶׁאִלְמָלֵא לֹא חָטָאתִי, יִהְיֶה דְבָרִי אֱמֶת, וְיִהְיֶה דְבָרְךְ בְּרֵיקָנוּת. עַכְשָׁו שֶׁחָטָאתִי, כְּדֵי שֶׁיִּהְיֶה דְבָרְךְ אֱמֶת, נָתַתִּי מָקוֹם לְצַדֵּק דְּבָרֶיךְ, לָכֵן עָשִׂיתִי, לְמַעַן תִּצְדַּק בְּדָבְרֶךְ תִּזְכֶּה בְשָׁפְטֶךְ. חָזַר דָּוִד לְאֻמָּנוּתוֹ וְאָמַר תּוֹךְ צַעֲרוֹ דִּבְרֵי בַּדְּחָנוּת לַמֶּלֶךְ."]]],[["תָּנֵינָן, לָאו דָּוִד אִתְחָזֵי לְהַהוּא עוֹבָדָא, דְּהָא אִיהוּ אָמַר, (תהילים ק״ט:כ״ב) וְלִבִּי חָלַל בְּקִרְבִּי (אנקיד חלל כבר הוה חלל בקרבי) הָכִי הוּא. אֲבָל אָמַר דָּוִד, בְּלִבָּא אִית תְּרֵין הֵיכָלִין, בְּחַד דָּמָא, וּבְחַד רוּחָא, הַהוּא חַד דְּמַלְיָיא דָּמָא, בֵּיהּ דִּיּוּרָא לְיֵצֶר הָרָע. וְלִבִּי לָאו הָכִי, דְּהָא רֵיקָן אִיהוּ, וְלָא יָהֲבִית דִּיּוּרָא לְדָמָא בִּישָׁא, לְשַׁכְנָא בֵּיהּ יֵצֶר הָרָע, וְלִבִּי וַדַּאי חָלַל אִיהוּ, בְּלָא דִּיּוּרָא (נ\"א דמא) בִּישָׁא, וְכֵיוָן דְּהָכִי הוּא, לָא אִתְחֲזֵי דָּוִד לְהַהוּא חוֹבָה דְּחָב אֶלָּא, בְּגִין לְמֵיהָב פְּתִיחוּ דְּפוּמָא לְחַיָּיבַיָּא, דְּיֵמְרוּן, דָּוִד מַלְכָּא חָב וְתָב בִּתְיוּבְתָא, וּמָחַל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, כָּל שֶׁכֵּן שְׁאַר בְּנֵי נָשָׁא. וְעַל דָּא אָמַר (תהילים נ״א:ט״ו) אֲלַמְּדָה פוֹשְׁעִים דְּרָכֶיךָ וְחַטָּאִים אֵלֶיךָ יָשׁוּבוּ.","וּכְתִיב, (שמואל ב ט״ו:ל׳) וְדָוִד עֹלֶה בְּמַעֲלֵה הַזֵּיתִים עוֹלֶה וּבוֹכֶה וְרֹאשׁ לוֹ חָפוּי וְהוּא הוֹלֵךְ יָחֵף. רֹאשׁ לוֹ חָפוּי, וְיָחֵף אֲמַאי. אֶלָּא, נָזוּף הֲוָה, עָבֵד גַּרְמֵיהּ נָזוּף, לְקַבְּלָא עֹנְשָׁא. וְעַמָּא הֲווֹ רְחִיקִין מִנֵּיהּ ד' אַמּוֹת. זַכָּאָה עַבְדָּא דְּהָכִי פָּלַח לְמָארֵיהּ, וְאִשְׁתְּמוֹדָע בְּחוֹבֵיהּ, לְאָתָבָא מִנֵיהּ בִּתְיוּבְתָא שְׁלֵימָתָא.","תָּא חֲזֵי, יַתִּיר הֲוָה, מַה דְּעָבַד לֵיהּ שִׁמְעִי בֶּן גֵּרָא, מִכָּל עַקְתִּין דְּעָבְרוּ עָלֵיהּ עַד הַהוּא יוֹמָא, וְלָא אָתִיב דָּוִד לָקֳבְלֵיהּ מִלָּה דְּהָכִי הֲוָה יֵאוֹת לֵיהּ, וּבְדָא אִתְכַּפָּרוּ חוֹבוֹי.","הַשְׁתָּא אִית לְאִסְתַּכְּלָא, שִׁמְעִי תַּלְמִיד חָכָם הֲוָה, וְחָכְמְתָא סַגִּיאָה הֲוַת בֵּיהּ, אֲמַאי נָפִיק לְגַבֵּי דָּוִד, וְעָבִיד לֵיהּ כָּל מַה דְּעָבַד. אֶלָּא מֵאֲתָר אַחֲרָא הֲוָה מִלָּה, וְאָעִיל לֵיהּ בְּלִבֵּיהּ מִלָּה דָּא. וְכָל דָּא לְתוֹעַלְתָּא דְּדָוִד. דְּהָא הַהוּא דְּעָבַד לֵיהּ שִׁמְעִי, גַּרְמָא לֵיהּ לְמֵיתָב בִּתְיוּבְתָּא שְׁלֵימָתָא, וְתָבַר לִבֵּיהּ בִּתְבִירוּ סַגִּי, וְאוֹשִׁיד דִּמְעִין סַגִּיאִין, מִגּוֹ לִבֵּיהּ קֳדָם קוּדְשָׁא בְּרִיךְ הוּא, וְעַל דָּא אָמַר, (שמואל ב טז) כִּי יְיָ' אָמַר לוֹ קַלֵּל. יָדַע, דְּהָא מֵאֲתָר עִלָּאָה אַחֲרָא נָחַת מִלָּה.","תְּרֵין פִּקּוּדִין, פָּקִיד דָּוִד לִשְׁלֹמֹה בְּרֵיהּ, חַד דְּיוֹאָב, וְחַד דְּשִׁמְעִי, עִם שְׁאַר פִּקּוּדִין דְּפָקִיד לֵיהּ. דְּיוֹאָב: דִּכְתִּיב, (מלכים א ב׳:ה׳) וְגַם אַתָּה יָדַעְתָּ אֵת אֲשֶׁר עָשָׂה לִי יוֹאָב בֶּן צְרוּיָה. מִלָּה סְתִימָא הֲוָה, דְּאֲפִילּוּ שְׁלמֹה לָא הֲוָה לֵיהּ לְמִנְדַּע, וְלָא יָדַע אֶלָּא בְּגִין דְּיָדְעוּ אַחֲרָנִין, אִתְגְּלֵי (ליה) לִשְׁלֹמֹה. וְעַל דָּא אָמַר, וְגַם אַתָּה יָדַעְתָּ וְגוֹ'. מַה דְּלָא אִתְחָזֵי לָךְ לְמִנְדַּע.","דְּשִׁמְעִי: כְּתִיב, וְהִנֵּה עִמְּךָ שִׁמְעִי בֶּן גֵּרָא. מַאי וְהִנֵּה עִמְּךָ, זַמִּין הוּא עִמְּךָ תָּדִיר, רַבּוֹ הֲוָה. וּבְגִין כַּךְ לָא אָמַר עַל יוֹאָב וְהִנֵּה עִמְּךָ יוֹאָב. אֲבָל שִׁמְעִי דָּא, דְּאִשְׁתְּכַח עִמֵּיהּ תָּדִיר, אָמַר וְהִנֵּה עִמְּךָ.","וַיִּשְׁלַח הַמֶּלֶךְ וַיִּקְרָא לְשִׁמְעִי וַיֹּאמֶר בְּנֵה לְךָ בַיִת בִּיְרוּשָׁלַם. אָן הוּא חָכְמְתָא דְּשְׁלֹמֹה מַלְכָּא בְּהַאי. אֶלָּא כֹּלָּא בְּחָכְמְתָא עָבַד, וּלְכָל סִטְרִין אַשְׁגַּח, דְּהָא חַכִּים הֲוָה שִׁמְעִי, וְאָמַר שְׁלמֹה, בְּעֵינָא דְּיִסְגֵי אוֹרַיְיתָא בְּאַרְעָא עַל יְדוֹי דְּשִׁמְעִי, וְלָא יִפּוּק לְבַר.","תּוּ מִלָּה אַחֲרָא אַשְׁגַּח שְׁלמֹה בְּחָכְמְתָא, דִּכְתִּיב, (שמואל ב ט״ז:ה׳) יֹצֵא יָצוֹא וּמְקַלֵּל. מַאי יֹצֵא יָצֹא תְּרֵי זִמְנֵי, וַיֵּצֵא וַיְקַלֵּל סַגִּי. (ליה) אֶלָּא, חַד יְצִיאָה, דְּנָפַק מִבֵּי מִדְרָשָׁא לְגַבֵּי דָּוִד. וְחַד יְצִיאָה, דְּנָפַק מִיְרוּשָׁלַ ם, לְגַבֵּי עַבְדּוֹי דְּמִית עָלוֹי. יְצִיאָה חֲדָא לְגַבֵּי מַלְכָּא, וִיצִיאָה תִּנְיָינָא לְגַבֵּי עַבְדִּין. וְכָל דָּא חָמָא שְׁלמֹה, וְאַשְׁגַּח בְּרוּחַ קוּדְשָׁא, הַהוּא יְצִיאָה תִּנְיָינָא. וְעַל דָּא אָמַר, וְהָיָה בְּיוֹם צֵאתְךָ, יָדַע דְּבִיצִיאָה יָמוּת.","(שמואל ב ט״ז:י״ג) וְעִפַּר בֶּעָפָר מַהוּ. אָמַר שְׁלֹמֹה לְגַבֵּי אַבָּא בֶּעָפָר הֲוָה. לְגַבֵּי שִׁמְעִי בְּמַיָּא, דִּכְתִּיב וְהָיָה בְּיוֹם צֵאתְךָ וְעָבַרְתָּ אֶת נַחַל קִדְרוֹן. עָפָר הָתָם, וְהָכָא מַיָּא. תַּרְוַויְיהוּ דָּן שְׁלֹמֹה, לְמֶהֱוֵי עָפָר וּמַיָּא כַּסּוֹטָה, לְמַאן דְּאַסְטִין אָרְחָא לְגַבֵּי אֲבוֹי.","כְּתִיב (מלכים א ב׳:ח׳) וְהוּא קִלְלַנִי קְלָלָה נִמְרֶצֶת. וּכְתִיב וָאֶשָּׁבַע לוֹ בַּיְיָ' לֵאמֹר אִם אֲמִיתְךָ בֶּחָרֶב. מַאי בֶּחָרֶב. וְכִי שִׁמְעִי טִפְּשָׁא הֲוָה, דְּאִילּוּ הָכִי אוֹמֵי לֵיהּ, דְּלָא יֵימָא בְּחֶרֶב לָא. אֲבָל בַּחֲנִית אוֹ בְּגִירָא אִין."],[[0,"תנינן לאו דוד וכו':","למדנו, לא היה דוד ראוי לאותו מעשה, כי הוא אמר, ולבי חלל בקרבי. כך הוא, אבל אמר דוד, בלב יש ב' היכלות באחד דם ובאחד רוח. אחד ההוא המלא דם הוא משכן ליצר הרע, ולבי אינו כן כי ריקן הוא, ולא נתתי משכן לדם הרע להשכין בו היצר הרע. ולבי ודאי חלל הוא בלא שכן רע. וכיון שכן הוא לא היה דוד ראוי לחטא ההוא שחטא. אלא כדי לתת פתחון פה לרשעים, שיאמרו דוד המלך חטא וחזר בתשובה, ומחל לו הקב\"ה,כל שכן שאר בני אדם.ועל זה אמר דוד, אלמדה פושעים דרכיך וחטאים אליך ישובו."],[1,"וכתיב ודוד עלה וכו':","וכתוב, ודוד עלה במעלה הזיתים עולה ובוכה, וראש לו חפוי והוא הולך יחף. שואל, ראש לו חפוי ויחף, למה זה. ומשיב, אלא נזוף היה, עשה עצמו נזוף, כדי לקבל עונש, והעם היו רחוקים ממנו ד' אמות. אשרי העבד שכך עובד לאדונו, ונודע בחטאו, כדי לשוב ממנו בתשובה שלמה."],[2,"ת\"ח יתיר הוה וכו':","בוא וראה, יותר היה מה שעשה לו שמעי בן גרא, מכל הצרות שעברו עליו עד היום ההוא, ודוד לא השיב כנגדו דבר. כי כן היה יפה לו, ובזה נתכפרו עונותיו."],[3,"השתא אית לאסתכלא וכו':","עתה יש להסתכל, שמעי תלמיד חכם היה, וחכמה רבה היתה בו, למה יצא אל דוד ועשה לו מה שעשה. ומשיב. אלא ממקום אחר היה הדבר, והכניס לו דבר זה בלבו. וכל זה עשה לתועלת לדוד. כי ההוא שעשה לו שמעי, גרם לו לחזור בתשובה שלמה, ושיבר לבו בשבירה רבה, ושפך דמעות רבות מתוך לבו לפני הקב\"ה ועל כן אמר, כי ה' אמר לו קלל. ידע שממקום אחר עליון, ירד הדבר."],[4,"תרין פקודין פקיד וכו':","שני ציווים צוה דוד לשלמה בנו, אחד של יואב, ואחד של שמעי, עם שאר הציווים שצוה אותו. של יואב, שכתוב, וגם אתה ידעת את אשר עשה לי יואב בן צרויה. דבר סתום היה, שאפילו שלמה לא היה לו לדעת, אלא משום שידעו אחרים נודע לשלמה. ע\"כ אמר וגם עתה ידעת וגו', מה שלא היה ראוי לו לדעת."],[5,"דשמעי כתיב והנה וכו':","של שמעי, שכתוב, והנה עמך שמעי בן גרא. מהו והנה עמך. ומשיב, הוא מוכן לך תמיד, כי רבו היה, ומשום זה לא אמר על יואב והנה עמך יואב. אבל שמעי זה, שנמצא עמו תמיד, אמר והנה עמך."],[6,"וישלח המלך וכו':","וישלח המלך ויקרא לשמעי ויאמר בנה לך בית בירושלים. שואל, איפה הוא החכמה של שלמה המלך בזה. ומשיב, אלא הכל בחכמה עשה, ולכל הצדדים השגיח, כי חכם היה שמעי, ואמר שלמה, אני רוצה שיתרבה התורה בארץ על ידי שמעי, ולא יצא לחוץ."],[7,"תו מלה אחרא וכו':","עוד. דבר אחר הסתכל שלמה בחכמה, שכתוב, יצא יצא ויקלל. מהו יצא יצא ב' פעמים, יצא ויקלל היה די. ומשיב, אלא יציאה אחת שיצא מבית המדרש לקלל את דוד. ויציאה אחת שיצא מירושלים אל עבדיו שמת עליה. יציאה אחת אל המלך, ויציאה אחת אל עבדיו. וכל זה ראה שלמה והסתכל ברוח הקדש ביציאה ההוא השניה. וע\"כ אמר, והיה ביום צאתך, ידע שביציאה ימות."],[8,"ועפר בעפר מהו וכו':","שואל, מהו ועפר בעפר. ומשיב, אמר שלמה אצל אבי היה בעפר, אצל שמעי יהיה במים. שכתוב, והיה ביום צאתך ועברת את נחל קדרון. שם היה עפר וכאן מים. שניהם דן שלמה, שיהיה נידון בעפר ומים כסוטה, למי שהשטין הדרך אצל אביו."],[9,"כתיב והוא קללני וגו':","כתוב, והוא קללני קללה נמרצת, וכתוב, ואשבע לו בה' לאמר אם אמיתך בחרב. שואל מהו בחרב. וכי שוטה היה שמעי, שלא הבין, שאלו נשבע לו כך, שלא יאמר אח\"כ, בחרב לא, אבל בחנית או בחץ כן."]],[[0,"","שָׁנִינוּ, דָּוִד לֹא הָיָה רָאוּי לְאוֹתוֹ הַמַּעֲשֶׂה, שֶׁהֲרֵי הוּא אָמַר, (שם קט) וְלִבִּי חָלַל בְּקִרְבִּי (נקוד חלל, שכבר היה חלל בקרבי) כָּךְ הוּא. אֲבָל דָּוִד אָמַר, בַּלֵּב יֵשׁ שְׁנֵי הֵיכָלוֹת, בְּאֶחָד דָּם וּבְאֶחָד רוּחַ. אוֹתוֹ אֶחָד שֶׁמָּלֵא בְדָם, בּוֹ יֵשׁ דִּיּוּר לַיֵּצֶר הָרָע, וְלִבִּי לֹא כָּךְ, שֶׁהֲרֵי הוּא רֵיקָן, וְלֹא נָתַתִּי דִיּוּר לְדָם רַע לִשְׁכֹּן בּוֹ יֵצֶר הָרָע, וְלִבִּי הוּא וַדַּאי חָלָל בְּלִי דִיּוּר (דם) רַע, וְכֵיוָן שֶׁכָּךְ זֶה, לֹא רָאוּי דָּוִד לְאוֹתוֹ חֵטְא שֶׁחָטָא, אֶלָּא כְּדֵי לָתֵת פִּתְחוֹן פֶּה לָרְשָׁעִים, שֶׁיֹּאמְרוּ, דָּוִד הַמֶּלֶךְ חָטָא וְשָׁב בִּתְשׁוּבָה וּמָחַל לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּל שֶׁכֵּן לִשְׁאָר בְּנֵי אָדָם. וְעַל זֶה אָמַר (תהלים נא) אֲלַמְּדָה פֹשְׁעִים דְּרָכֶיךְ וְחַטָּאִים אֵלֶיךְ יָשׁוּבוּ."],[1,"","וְכָתוּב, (שמואל ב טו) וְדָוִד עֹלֶה בְמַעֲלֵה הַזֵּיתִים עֹלֶה וּבוֹכֶה וְרֹאשׁ לוֹ חָפוּי וְהוּא הֹלֵךְ יָחֵף. רֹאשׁ לוֹ חָפוּי וְיָחֵף לָמָּה? אֶלָּא הָיָה נָזוּף, עָשָׂה עַצְמוֹ נָזוּף לְקַבֵּל עֹנֶשׁ, וְהֵם הָיוּ רְחוֹקִים מִמֶּנּוּ אַרְבַּע אַמּוֹת. אַשְׁרֵי הָעֶבֶד שֶׁכָּךְ עוֹבֵד לְרַבּוֹ וּמוּדָע לְחֶטְאוֹ לָשׁוּבּ מִמֶּנּוּ בִּתְשׁוּבָה שְׁלֵמָה."],[2,"","בֹּא וּרְאֵה, יוֹתֵר הָיָה מַה שֶּׁעָשָׂה לוֹ שִׁמְעִי בֶּן גֵּרָא מִכָּל הַצָּרוֹת שֶׁעָבְרוּ עָלָיו עַד אוֹתוֹ הַיּוֹם, וְלֹא הֵשִׁיב דָּוִד כְּנֶגְדּוֹ דָבָר, שֶׁכָּךְ הָיָה רָאוּי לוֹ, וּבָזֶה הִתְכַּפְּרוּ חֲטָאָיו."],[3,"","עַכְשָׁו יֵשׁ לְהִתְבּוֹנֵן, שִׁמְעִי הָיָה תַּלְמִיד חָכָם, וְחָכְמָה רַבָּה הָיְתָה בּוֹ, לָמָּה יָצָא לְדָוִד וְעָשָׂה לוֹ כָּל מַה שֶּׁעָשָׂה? אֶלָּא מִמָּקוֹם אַחֵר הָיָה הַדָּבָר, וְהִכְנִיס לוֹ בְּלִבּוֹ דָּבָר זֶה, וְכָל זֶה לְתוֹעַלְתּוֹ שֶׁל דָּוִד, שֶׁהֲרֵי מַה שֶּׁעָשָׂה לוֹ שִׁמְעִי, גָּרַם לוֹ לָשׁוּב בִּתְשׁוּבָה שְׁלֵמָה וְשָׁבַר לִבּוֹ בְּשֶׁבֶר רַב, וְשָׁפַךְ הַרְבֵּה דְמָעוֹת מִתּוֹךְ לִבּוֹ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְעַל זֶה אָמַר, כִּי ה' אָמַר לוֹ קַלֵּל. יָדַע שֶׁהֲרֵי מִמָּקוֹם עֶלְיוֹן יָרַד הַדָּבָר."],[4,"","שְׁנֵי צִוּוּיִים צִוָּה דָוִד אֶת שְׁלֹמֹה בְּנוֹ - אֶחָד שֶׁל יוֹאָב, וְאֶחָד שֶׁל שִׁמְעִי, עִם שְׁאָר הַצִּוּוּיִים שֶׁצִּוָּה אוֹתוֹ. שֶׁל יוֹאָב - שֶׁכָּתוּב (מלכים א ב) וְגַם אַתָּה יָדַעְתָּ אֵת עָשָׂה לִי יוֹאָב בֶּן צְרוּיָה. דָּבָר נִסְתָּר הָיָה, שֶׁהֲרֵי אֲפִלּוּ שְׁלֹמֹה לֹא הָיָה לוֹ לָדַעַת. אֶלָּא מִשּׁוּם שֶׁאֲחֵרִים יָדְעוּ (אותו), זֶה הִתְגַּלָּה לִשְׁלֹמֹה. וְעַל זֶה אָמַר, וְאַתָּה יָדַעְתָּ וְגוֹ', מַה שֶּׁלֹּא רָאוּי לְךְ לָדַעַת."],[5,"","שֶׁל שִׁמְעִי - שֶׁכָּתוּב וְהִנֵּה עִמְּךְ שִׁמְעִי בֶן גֵּרָא. מַה זֶּה וְהִנֵּה עִמְּךְ? מְזֻמָּן הוּא עִמְּךְ תָּמִיד, רַבּוֹ הָיָה, וּמִשּׁוּם כָּךְ לֹא אָמַר לוֹ עַל יוֹאָב וְהִנֵּה עִמְּךְ יוֹאָב. אֲבָל שִׁמְעִי זֶה שֶׁנִּמְצָא תָמִיד עִמּוֹ, אָמַר וְהִנֵּה עִמְּךְ."],[6,"","וַיִּשְׁלַח הַמֶּלֶךְ וַיִּקְרָא לְשִׁמְעִי וַיֹּאמֶר בְּנֵה לְךְ בַיִת בִּירוּשָׁ לם. אֵיפֹה הִיא חָכְמָתוֹ שֶׁל שְׁלֹמֹה בָּזֶה? אֶלָּא הַכֹּל עָשָׂה בְחָכְמָה, וּלְכָל הַצְּדָדִים הוּא הִתְבּוֹנֵן. שֶׁהֲרֵי שִׁמְעִי הָיָה חָכָם, וְאָמַר שְׁלֹמֹה, אֲנִי רוֹצֶה שֶׁתִּגְדַּל תּוֹרָה עַל יְדֵי שִׁמְעִי וְלֹא יֵצֵא הַחוּצָה."],[7,"","עוֹד דָּבָר אַחֵר הִשְׁגִּיחַ שְׁלֹמֹה בְּחָכְמָה, שֶׁכָּתוּב (שמואל ב טז) יֹצֵא יָצוֹא וּמְקַלֵּל. מַה זֶּה יצֵא יָצוֹא פַּעֲמַיִם? מַסְפִּיק וַיֵּצֵא וַיְקַלֵּל (לו). אֶלָּא יְצִיאָה אַחַת - שֶׁיָּצָא מִבֵּית מִדְרָשׁוֹ לְדָוִד, וִיצִיאָה אַחַת - שֶׁיָּצָא מִירוּשָׁלַיִם אֶל עַבְדּוֹ שֶׁמֵּת עָלָיו. יְצִיאָה אַחַת לַמֶּלֶךְ, וִיצִיאָה שְׁנִיָּה לָעֲבָדִים. וְכָל זֶה רָאָה שְׁלֹמֹה וְהִשְׁגִּיחַ בְּרוּחַ הַקֹּדֶשׁ אוֹתָהּ הַיְצִיאָה הַשְּׁנִיָּה, וְעַל זֶה אָמַר וְהָיָה בְּיוֹם צֵאתְךְ. יָדַע שֶׁבִּיצִיאָה יָמוּת."],[8,"","וְעִפַּר בֶּעָפָר מַהוּ? אָמַר שְׁלֹמֹה, אֶל אָבִי זֶה הָיָה בֶּעָפָר, אֶל שִׁמְעִי זֶה יִהְיֶה בְּמַיִם, שֶׁכָּתוּב וְהָיָה בְּיוֹם צֵאתְךְ וְעָבַרְתָּ אֶת נַחַל קִדְרוֹן. שָׁם עָפָר וְכָאן מַיִם. שְׁנֵיהֶם דָּן שְׁלֹמֹה, לִהְיוֹת עָפָר וּמַיִם כְּמוֹ סוֹטָה, לְמִי שֶׁהִסְטִין דַּרְכּוֹ לְאָבִיו."],[9,"","כָּתוּב וְהוּא קִלְלַנִי קְלָלָה נִמְרֶצֶת. וְכָתוּב וָאֶשָּׁבַע לוֹ בַה' לֵאמֹר אִם אֲמִיתְךְ בֶּחָרֶב. וְכִי שִׁמְעִי הָיָה טִפֵּשׁ? שֶׁאִלּוּ כָּךְ הִשְׁבִּיעַ אוֹתוֹ, שֶׁלֹּא יֹאמַר בַּחֶרֶב לֹא, אֲבָל בַּחֲנִית אוֹ בְּחֵץ כֵּן."]]],[["אֶלָּא תְּרֵין מִלִּין הָכָא. חַד אָמַר יַנּוֹקָא, בְּרֵיהּ דְּנוּנָא רַבָּא הַהוּא דְּקַשְׂקָשׂוֹי סָלְקִין לְרוּם עֲנָנִין. אוֹמָאָה דְּדָוִד מַלְכָּא, כַּד הֲוָה בָּעֵי לְאוּמָאָה, אַפִּיק חֲרְבָּא דִּילֵיהּ, דְּתַמָּן הֲוָה חָקִיק שְׁמָא גְּלִיפָן, וְתַמָּן אוֹמֵי. וְכָךְ עָבִיד לְשִׁמְעִי, דִּכְתִּיב וָאֶשָּׁבַע לוֹ בַיְיָ' לֵאמֹר אִם אֲמִיתְךָ בֶּחָרֶב. בְּמָאי הֲוָה אוֹמָאָה דָּא. בֶּחָרֶב. (ס\"א בהאי חרב דשמא קדישא חקיק ביה אומי) בֶּחָרֶב אוֹמֵי. וּמִלָּה אַחֲרָא, דָּן שְׁלֹמֹה, אָמַר, בִּקְלָלָה אָתָא לְגַבֵּי אַבָּא, בְּמִלִּין, הָא מִלִּין לְגַבֵּיהּ, וּבְשֵׁם הַמְּפוֹרָשׁ קַטְלֵיהּ, וְלא בֶּחָרֶב. וּבְגִין דָּא עָבַד שְׁלֹמֹה הָכִי.","הַשְׁתָּא אִית לְאִסְתַּכְּלָא, דְּכֵיוָן דְּאוֹמֵי לֵיהּ דָּוִד, אֲמַאי קַטְלֵיהּ, דְּאִתְחָזֵי דְּהָא אוֹמָאָה דָּא בַּעֲלִילָה הֲוָה, דְּהָא לִבָּא וּפוּמָא לָא הֲווֹ כַּחֲדָא. אֶלָּא וַדַּאי דָּוִד לָא קַטְלֵיהּ, וְהָא יְדִיעָא, כָּל שַׁיְיפִין דְּגוּפָא מְקַבְּלִין כֹּלָּא, וְלִבָּא לָא מְקַבְּלָא אֲפִילּוּ כְּחוּטָא דְּנֵימָא דְּשַׂעֲרָא. דָּוִד מַלְכָּא לִבָּא הֲוָה, וְקָבִּיל מַה דְּלָא אִתְחָזֵי לֵיהּ לְקַבְּלָא, וּבְגִין כָּךְ, (מלכים א ב׳:ט׳) וְיָדַעְתָּ אֵת אֲשֶׁר תַּעֲשֶׂה לוֹ כְּתִיב. וְתוּ, דְּהָא אִילָנָא גָּרִים לְמֶהֱוֵי נָטִיר וְנוֹקֵם כְּחִוְיָא.","כְּתִיב (תהילים נ״א:י״ח-י״ט) כִּי לא תַחְפּוֹץ זֶבַח וְאֶתֵּנָה עוֹלָה לא תִרְצֶה. זִבְחֵי אֱלהִים רוּחַ נִשְׁבָּרָה לֵב נִשְׁבָּר וְנִדְכֶּה אֱלהִים לא תִבְזֶה. כִּי לא תַחְפּוֹץ זֶבַח, וְכִי לָא בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא דְּיִקְרְבוּן קָמֵיהּ קָרְבְּנָא, וְהָא אִיהוּ אַתְקִין לְגַבֵּי חַיָּיבַיָּא קָרְבְּנָא, דְּיִקְרְבוּן וְיִתְכַּפֵּר לְהוּ חוֹבַיְיהוּ. אֶלָּא דָּוִד לְקָמֵי שְׁמָא דֶּאֱלהִים אָמַר, וְקָרְבָּנָא לָא קְרָבִין לִשְׁמָא דֶּאֱלֹהִים, אֶלָּא לִשְׁמָא דיו\"ד הֵ\"א וָא\"ו הֵ\"א. דְּהָא לְגַבֵּי דִּינָא קַשְׁיָא מִדַּת הַדִּין, לָא מְקָרְבִין קָרְבְּנָא. דִּכְתִּיב, (ויקרא א׳:ב׳) אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן לַיְיָ'. לַיְיָ', וְלָא (ויקרא ה' ע\"א) לִשְׁמָא דֶּאֱלהִים. וְכִי תַקְרִיב קָרְבָּן מִנְחָה לַיְיָ'. זֶבַח תּוֹדָה לַיְיָ'. זֶבַח שְׁלָמִים לַיְיָ'.","וּבְגִין כַּךְ, כֵּיוָן דְּדָוִד מַלְכָּא, לְגַבֵּי אֱלֹהִים אָמַר. אִצְטְרִיךְ לְמִכְתַּב, כִּי לֹא תַחְפּוֹץ זֶבַח וְאֶתֵּנָה עוֹלָה לא תִרְצֶה. דְּהָא לִשְׁמָא דָּא לָא מְקָרְבִין, אֶלָּא רוּחַ נִשְׁבָּרָה. דִּכְתִּיב זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה. קָרְבְּנָא דֶּאֱלהִים, עֲצִיבוּ, וּתְבִירוּ דְּלִבָּא. וּבְגִין כַּךְ, מַאן דְּחָלַם חֶלְמָא בִּישָׁא, עֲצִיבוּ אִצְטְרִיךְ לְאַחֲזָאָה, דְּהָא בְּמִדַּת אֱלהִים קַיְּימָא, וְזֶבַח דְּמִדַּת דִּינָא, עֲצִיבוּ אִצְטְרִיךְ וְרוּחַ נִשְׁבָּרָה, וְהַהוּא עֲצִיבוּ מִסְּתְיֵיהּ לְחֶלְמָא בִּישָׁא, וְלָא שַׁלְטָא דִּינָא עֲלוֹי. דְּהָא זֶבַח דְּאִתְחָזֵי לְמִדַּת דִּינָא, אַקְרִיב קָמֵיהּ.","לֵב נִשְׁבָּר וְנִדְכֶּה אֱלֹהִים לא תִבְזֶה, מַאי לֹא תִבְזֶה, מִכְּלָל דְּאִיכָּא לֵב דְּאִיהוּ בּוֹזֶה. אִין. הַיְינוּ לֵב דְּאִיהוּ גֵּאֶה, לֵב בְּגַסּוּת רוּחָא, הַיְינוּ לֵב דְּאִיהוּ בּוֹזֶה, אֲבָל לֵב נִשְׁבָּר וְנִדְכֶּה אֱלהִים לא תִבְזֶה.","הֵיטִיבָה בִרְצוֹנְךָ אֶת צִיּוֹן תִּבְנֶה חוֹמוֹת יְרוּשָׁלַם. מַאי הֵטִיבָה, אִתְחָזֵי דְּהָא טִיבוּ אִית בָּהּ, וְהַשְׁתָּא הֵטִיבָה עַל הַהוּא טִיבוּ. וַדַּאי הָכִי הוּא, דְּהָא מִן יוֹמָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִשְׁתָּדַּל בְּבִנְיַן בֵּי מַקְדְּשָׁא לְעֵילָּא, עַד (ויקרא רכ\"א ע\"א) כְּעַן, הַהוּא הֲטָבָה דְּרָצוֹן, לָא שַׁרְיָיא עַל הַהוּא בִּנְיָן, וְעַל דָּא לָא אִשְׁתָּכְלַל. דְּהָא בְּשַׁעֲתָא דְּרָצוֹן דִּלְעֵילָּא יִתְּעַר, יֵיטִיב וְיַדְלִיק נְהוֹרִין דְּהַהוּא בִּנְיָן, וְהַהוּא עֲבִידְתָּא, דְּאֲפִילּוּ מַלְאָכִין דִּלְעֵילָּא, לָא יֵיכְלוּן (לא) לְאִסְתַּכְּלָא בְּהַהוּא בֵּי מַקְדְּשָׁא, וְלָאו בְּהַהוּא בִּנְיָן. וּכְדֵין בֵּי מַקְדְּשָׁא, וְכָל עוֹבָדָא אִשְׁתָּכְלַל.","תִּבְנֶה חוֹמוֹת יְרוּשָׁלַם, וְכִי מִן יוֹמָא דְּאִשְׁתַּדַּל בְּבִנְיַן בֵּי מַקְדְּשָׁא עַד כְּעַן, לָא בָּנָה לוֹן. (או) אִי חוֹמוֹת יְרוּשָׁלַ ם עַד כְּעַן לָא בָּנָה, בֵּי מַקְדְּשָׁא עַל אַחַת כַּמָּה וְכַמָּה. אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא, כָּל עוֹבָדוֹי, לָאו כְּעוֹבָדֵי דְּבַּר נָשׁ. בְּנֵי נָשָׁא כַּד בָּנוּ בֵּי מַקְדְּשָׁא לְתַתָּא, בְּקַדְמִיתָא עָבְדוּ שׁוּרֵי קַרְתָּא, וּלְבַסּוֹף עָבְדוּ בֵּי מַקְדְּשָׁא. שׁוּרֵי קַרְתָּא בְּקַדְמִיתָא, בְּגִין לְאַגָּנָא עָלַיְיהוּ, וּלְבָתַר בִּנְיָינָא דְּבֵיתָא. קוּדְשָׁא בְּרִיךְ הוּא לָאו הָכִי, אֶלָּא בָּנֵי בֵּי מַקְדְּשָׁא בְּקַדְמִיתָא, וּלְבַסּוֹף, כַּד יָחִית לֵיהּ מִשְּׁמַיָּא, וְיוֹתִיב לֵיהּ עַל אַתְרֵיהּ, כְּדֵין יִבָּנֶה חוֹמוֹת יְרוּשָׁלַ ם דְּאִנּוּן שׁוּרִין דְּקַרְתָּא. וְעַל דָּא אָמַר דָּוִד עָלָיו הֲשָׁלוֹם, (תהילים נ״א:כ׳) הֵיטִיבָה בִרְצוֹנְךָ אֶת צִיּוֹן בְּקַדְמִיתָא, וּלְבָתַר תִּבְנֶה חוֹמוֹת יְרוּשָׁלַ ם."],[[0,"אלא תרין מלין וכו':","ומשיב. אלא ב' דברים כאן, א', שאמר הילד, בנו של דג הגדול ההוא שקשקשיו עולים עד רום עננים, השבועה של דוד המלך, כשהיה רוצה להשבע, הוציא החרב שלו, ששם היה חרות שם הנחקק ושם נשבע. וכך עשה לשמעי, שכתוב, ואשבע לו בה' לאמר אם אמיתך בחרב, במה היתה שבועה זו, בחרב. ודבר האחר הוא, כי דן שלמה, אמר, בקללה בא אל אבא, שהוא דברים, הרי גם אני בדברים אליו, ובשם המפורש הרגו, ולא בחרב. ומשום זה עשה שלמה כך."],[1,"השתא אית לאסתכלא וכו':","עתה יש להסתכל, כיון שנשבע לו דוד, למה הרגו, שנראה, אשר שבועה הזו היתה בעלילה, כי הלב והפה לא היו שוים. ומשיב, אלא ודאי דוד לא הרגו, והרי ידוע, שכל איברי הגוף מקבלים הכל, והלב אינו מקבל אפילו כחוט השערה. דוד המלך היה הלב של ישראל, וקבל מה שלא היה ראוי לו שיקבל, דהיינו מה ששמעי סיקל באבנים ועפר בעפר, ומשום זה, וידעת את אשר תעשה לו כתוב. ועוד, כי האילן, דהיינו מה שהיה בבחינת מלכות שהוא אילן זעירא, גרם לו להיות נוקם ונוטר כנחש."],[2,"כתיב, כי לא וגו':","כתוב, כי לא תחפוץ זבח ואתנה עולה לא תרצה זבחי אלקים רוח נשברה וגו'. שואל, \u0003כי לא תחפוץ זבח,\u0004 וכי אינו רוצה הקב\"ה שיקריבו לפניו קרבן, והרי הוא תקן לרשעים שיקריבו קרבן, ויתכפר להם עונותיהם. ומשיב, אלא דוד, לפני שם \u0003אלקים\u0004 אמר זה, שהוא מדת הדין, וקרבן אינם מקריבים לשם אלקים אלא לשם \u0003יוד הא ואו הא.\u0004 כי אל דין קשה שהוא מדת הדין אינם מקריבים קרבן. שכתוב, אדם כי יקריב מכם קרבן להוי\"ה, להוי\"ה ולא לשם אלקים, וכן כתוב, וכי תקריב קרבן מנחה להויה, זבח תודה להויה, זבח שלמים להויה. ולא כתוב השם אלקים."],[3,"ובגין כך כיון וכו':","ומשום זה, כיון שדוד המלך אמר אל השם \u0003אלקים,\u0004 צריך לכתוב, כי לא תחפוץ זבח ואתנה עולה לא תרצה. כי לשם זה אינם מקריבים אלא רוח נשברה, שכתוב, זבחי \u0003אלקים\u0004 רוח נשברה. קרבן של אלקים הוא עצבות ושבירת הלב. ומשום זה, מי שחלם חלום רע, הוא צריך להראות עצבות, כי הוא עומד במדת אלקים, וזבח של מדת הדין צריך להיות עצבות ורוח נשברה, ועצבות ההיא מועיל לחלום הרע, ואין הדין שולט עליו. כי זבח הראוי למדת הדין הקריב לפניו."],[4,"לב נשבר ונדכה אלקים לא תבזה:","שואל, מהו לא תבזה, משמע שיש לב, שהוא בוזה. ומשיב, כן, והיינו הלב שהוא גאה, הלב שהוא בגסות הרוח, היינו הלב שהוא בוזה. אבל לב נשבר ונדכה אלקים לא תבזה."],[5,"הטיבה ברצונך את ציון וגו':","שואל מהו הטיבה, הלא נראה שיש בה טוב, ועתה למה צריך להתפלל, הטיבה על ההוא טוב. ומשיב, ודאי כן הוא, שצריך להתפלל הטיבה, כי מיום שהקב\"ה השתדל בבנין בית המקדש למעלה עד עתה, הטבה של הרצון לא שרתה על בנין ההוא, ועל כן לא השתכלל. כי בשעה שהרצון של מעלה יתעורר, ייטיב וידליק האורות של בנין ההוא ומעשה ההוא, עד שאפילו המלאכים של מעלה לא יוכלו להסתכל בבית המקדש ההוא, ולא בבנין ההוא. ואז ישתכלל בית המקדש וכל מלאכתו. ועל זה התפלל, הטיבה ברצונך את ציון וגו'."],[6,"תבנה חומות ירושלים:","שואל, וכי מן היום שהשתדל בבנין בית המקדש עד עתה עוד לא בנה אותם, ואם חומות ירושלים לא בנה עד עתה, הבית המקדש, על אחת כמה וכמה שלא בנה. ואיך אמר הטיבה ברצונך את ציון, שהוא בהמ\"ק. כי מתחילה בונים החומות, ואח\"כ בית המקדש. ומשיב, אלא הקב\"ה, כל מעשיו אינם כמעשה בני אדם. בני אדם, כשבונים בית המקדש למטה, מתחילה עושים חומות העיר, ולבסוף בית המקדש. חומות העיר מתחילה כדי להגן עליהם, ואח\"כ בנין הבית. הקב\"ה, אינו כן, אלא בונה בית המקדש בתחילה, ולבסוף, כאשר הורידו מן השמים ומושיבו על מקומו, אז יבנה חומות ירושלים, שהם חומות העיר. וע\"כ אמר דוד עליו השלום, הטיבה ברצונך את ציון מתחילה, ואח\"כ תבנה חומות ירושלים."]],[[0,"","אֶלָּא שְׁנֵי דְבָרִים יֵשׁ כָּאן. אֶחָד אָמַר הַתִּינוֹק, בְּנוֹ שֶׁל הַדָּג הַגָּדוֹל, אוֹתוֹ שֶׁקַּשְׂקַשָּׂיו עוֹלִים לְרוּם הָעֲנָנִים. שְׁבוּעָתוֹ שֶׁל דָּוִד הַמֶּלֶךְ, כְּשֶׁהָיָה רוֹצֶה לְהִשָּׁבַע, הָיָה מוֹצִיא אֶת חַרְבּוֹ שֶׁשָּׁם הָיָה חָקוּק שֵׁם חָקוּק וְשָׁם נִשְׁבַּע. וְכָךְ עָשָׂה לְשִׁמְעִי, שֶׁכָּתוּב וָאֶשָּׁבַע לוֹ בַה' לֵאמֹר אִם אֲמִיתְךְ בֶּחָרֶב. בַּמָּה הָיְתָה הַשְּׁבוּעָה הַזּוֹ? בֶּחָרֶב. (בחרב הזו שהשם הקדוש חקק בה שבועה) בַּחֶרֶב נִשְׁבַּע. וְדָבָר אַחֵר דָּן שְׁלֹמֹה. אָמַר, בִּקְלָלָה בָּא אֶל אָבִי, בִּדְבָרִים - הֲרֵי דְּבָרִים אֵלָיו. וּבַשֵּׁם הַמְפֹרָשׁ הָרַג אוֹתוֹ וְלֹא בֶּחָרֶב. וְלָכֵן שְׁלֹמֹה עָשָׂה כָּךְ."],[1,"","עַכְשָׁו יֵשׁ לְהִתְבּוֹנֵן, שֶׁכֵּיוָן שֶׁדָּוִד הִשְׁבִּיעַ אוֹתוֹ, לָמָּה הָרַג אוֹתוֹ, שֶׁנִּרְאֶה שֶׁשְּׁבוּעָה זוֹ הָיְתָה בַּעֲלִילָה, שֶׁהֲרֵי הַלֵּב וְהַפֶּה לֹא הָיוּ כְאֶחָד? אֶלָּא וַדַּאי דָּוִד לֹא הָרַג אוֹתוֹ, וַהֲרֵי יָדוּעַ, כָּל אֵיבְרֵי הַגּוּף מְקַבְּלִים הַכֹּל, וְהַלֵּב לֹא מְקַבֵּל אֲפִלּוּ כְּחוּט שֶׁל נִימָה שֶׁל שַׂעֲרָה. דָּוִד הַמֶּלֶךְ הָיָה הַלֵּב, וְקִבֵּל מַה שֶּׁלֹּא רָאוּי לוֹ לְקַבֵּל, וּמִשּׁוּם כָּךְ, וְיָדַעְתָּ אֵת אֲשֶׁר תַּעֲשֶׂה לּוֹ כָּתוּב. וְעוֹד, שֶׁהֲרֵי הָאִילָן גּוֹרֵם לִהְיוֹת נוֹטֵר וְנוֹקֵם כְּנָחָשׁ."],[2,"","כָּתוּב (תהלים נא) כִּי לֹא תַחְפֹּץ זֶבַח וְאֶתֵּנֶה עוֹלָה לֹא תִרְצֶה. זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה לֵב נִשְׁבָּר וְנִדְכֶּה אֱלֹהִים לֹא תִבְזֶה. כִּי לֹא תַחְפֹּץ זֶבַח, וְכִי לֹא רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיַּקְרִיבוּ לְפָנָיו קָרְבָּן, וַהֲרֵי הוּא תִּקֵּן לָרְשָׁעִים קָרְבָּן שֶׁיַּקְרִיבוּ וְיִתְכַּפֵּר לָהֶם חֶטְאָם? אֶלָּא שֶׁדָּוִד אָמַר אֶת זֶה לַשֵּׁם אֱלֹהִים, וְקָרְבָּן לֹא מַקְרִיבִים לַשֵּׁם אֱלֹהִים, אֶלָּא לְשֵׁם יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. שֶׁהֲרֵי לַדִּין הַקָּשֶׁה, מִדַּת הַדִּין, לֹא מַקְרִיבִים קָרְבָּן, שֶׁכָּתוּב (ויקרא א) אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן לַה'. לַה', וְלֹא לְשֵׁם אֱלֹהִים. וְכִי תַקְרִיב קָרְבַּן מִנְחָה לַה'. זֶבַח תּוֹדָה לַה'. זֶבַח שְׁלָמִים לַה'."],[3,"","וּמִשּׁוּם כָּךְ, כֵּיוָן שֶׁדָּוִד הַמֶּלֶךְ אָמַר לֵאלֹהִים, הִצְטָרֵךְ לִכְתֹּב כִּי לֹא תַחְפֹּץ זֶבַח וְאֶתֵּנָה עוֹלָה לֹא תִרְצֶה. שֶׁהֲרֵי לַשֵּׁם הַזֶּה לֹא מַקְרִיבִים, אֶלָּא רוּחַ נִשְׁבָּרָה, שֶׁכָּתוּב זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה. קָרְבָּן שֶׁל אֱלֹהִים הוּא עֶצֶב וְשִׁבְרוֹן לֵב. וּמִשּׁוּם כָּךְ, מִי שֶׁחָלַם חֲלוֹם רַע, צָרִיךְ לְהַרְאוֹת עַצְבוּת, שֶׁהֲרֵי בְּמִדַּת אֱלֹהִים (דין) עוֹמֵד, וְזֶבַח שֶׁל מִדַּת הַדִּין צָרִיךְ עַצְבוּת וְרוּחַ נִשְׁבָּרָה, וְאוֹתָהּ עַצְבוּת מְרַפֵּאת אֶת הַחֲלוֹם הָרָע, וְלֹא שׁוֹלֵט עָלָיו הַדִּין. שֶׁהֲרֵי הַזֶּבַח שֶׁרָאוּי לְמִדַּת הַדִּין, הִקְרִיב לְפָנֶיהָ."],[4,"","לֵב נִשְׁבָּר וְנִדְכֶּה אֱלֹהִים לֹא תִבְזֶה. מַה זֶּה לֹא תִבְזֶה? מִכְּלָל שֶׁיֵּשׁ לֵב שֶׁהוּא בּוֹזֶה? כֵּן. זֶהוּ לֵב שֶׁהוּא גֵאֶה, לֵב בְּגַסּוּת הָרוּחַ, הַיְנוּ לֵב בּוֹזֶה, אֲבָל לֵב נִשְׁבָּר וְנִדְכֶּה אֱלֹהִים לֹא תִבְזֶה."],[5,"","הֵיטִיבָה בִרְצוֹנְךְ אֶת צִיּוֹן תִּבְנֶה חוֹמוֹת יְרוּשָׁלם. מַה זֶּה הֵיטִיבָה? נִרְאֶה שֶׁהֲרֵי טוֹב יֵשׁ בָּהּ, וְעַכְשָׁו הֵיטִיבָה עַל אוֹתוֹ הַטּוֹב?! וַדַּאי כָּךְ הוּא, שֶׁהֲרֵי מִן הַיּוֹם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִשְׁתַּדֵּל בְּבִנְיַן בֵּית הַמִּקְדָּשׁ שֶׁלְּמַעְלָה עַד עַכְשָׁו, אוֹתָהּ הֲטָבָה שֶׁל רָצוֹן לֹא שָׁרְתָה עַל אוֹתוֹ הַבִּנְיָן, וְעַל כֵּן לֹא נִתְקַן. שֶׁהֲרֵי בְּשָׁעָה שֶׁהָרָצוֹן הָעֶלְיוֹן יִתְעוֹרֵר, הוּא יֵיטִיב וְיַדְלִיק אֶת הַמְּנוֹרוֹת שֶׁל אוֹתוֹ הַבִּנְיָן וְאוֹתוֹ הַמַּעֲשֶׂה, שֶׁאֲפִלּוּ הַמַּלְאָכִים שֶׁל מַעְלָה לֹא יוּכְלוּ (לא) לְהִסְתַּכֵּל בְּאוֹתוֹ בֵּית מִקְדָּשׁ וְלֹא בְּאוֹתוֹ בִּנְיָן, וְאָז בֵּית הַמִּקְדָּשׁ וְכָל הַמַּעֲשֶׂה נִתְקָן."],[6,"","תִּבְנֶה חוֹמוֹת יְרוּשָׁלם. וְכִי מִיּוֹם שֶׁהִשְׁתַּדֵּל בְּבִנְיַן בֵּית הַמִּקְדָּשׁ עַד עַכְשָׁו לֹא בָנָה אוֹתָם? (או) אִם חוֹמוֹת יְרוּשָׁלַיִם עַד עַכְשָׁו לֹא בָנָה - בֵּית הַמִּקְדָּשׁ עַל אַחַת כַּמָּה וְכַמָּה. אֶלָּא שֶׁכָּל מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא אֵינָם כְּמַעֲשֵׂי בֶּן אָדָם. כְּשֶׁבְּנֵי אָדָם בָּנוּ בֵּית הַמִּקְדָּשׁ לְמַטָּה, בַּהַתְחָלָה עָשׂוּ אֶת חוֹמוֹת הָעִיר, וּלְבַסּוֹף עָשׂוּ אֶת בֵּית הַמִּקְדָּשׁ. חוֹמוֹת הָעִיר בַּהַתְחָלָה כְּדֵי לְהָגֵן עֲלֵיהֶם, וְאַחַר כָּךְ בִּנְיַן הַבַּיִת. וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא כָּךְ, אֶלָּא בּוֹנֶה בַּתְּחִלָּה אֶת בֵּית הַמִּקְדָּשׁ, וּבַסּוֹף כְּשֶׁיּוֹרִיד אוֹתוֹ מִן הַשָּׁמַיִם וְיוֹשִׁיב אוֹתוֹ עַל מְקוֹמוֹ, אָז יִבְנֶה אֶת חוֹמוֹת יְרוּשָׁלַיִם, שֶׁהֵן חוֹמוֹת הָעִיר. וְעַל זֶה אָמַר דָּוִד הַמֶּלֶךְ עָלָיו הַשָּׁלוֹם, (תהלים נא) הֵיטִיבָה בִרְצוֹנְךְ אֶת צִיּוֹן - בַּהַתְחָלָה, וְאַחַר כָּךְ תִּבְנֶה חוֹמוֹת יְרוּשָׁלם."]]],[["הָכָא אִית רָזָא, כָּל עוֹבָדִין דְּעָבִיד קוּדְשָׁא בְּרִיךְ הוּא, בְּקַדְמִיתָא אַקְדִּים הַהוּא דִּלְבַר, וּלְבָתַר מוֹחָא דִּלְגוֹ, וְהָכָא לָאו הָכִי. תָּא חֲזֵי, כָּל אִינּוּן עוֹבָדִין דְּעָבִיד קוּדְשָׁא בְּרִיךְ הוּא, וְאַקְדִּים הַהוּא דִּלְבַר, מוֹחָא אַקְדִּים בְּמַחֲשָׁבָה, וּבְעוֹבָדָא הַהוּא דִּלְבַר, דְּהָא כָּל קְלִיפָּה מִסִּטְרָא אַחֲרָא הֲוֵי, וּמוֹחָא מִן מוֹחָא, וְתָדִיר סִטְרָא אַחֲרָא אַקְדִּים וְרַבִּי וְאַגְדִּיל וְנָטִיר אִיבָּא. כֵּיוָן דְּאִתְרַבֵּי, זַרְקִין לֵיהּ לְבַר, (איוב כ״ז:י״ז) וְיָכִין רָשָׁע וְצַדִיק יִלְבַּשׁ, וְזַרְקִין לְהַהִיא קְלִיפָּה, וּמְבָרְכִין (עקב רע\"א ע\"א) לְצַדִּיקָא דְּעָלְמָא.","אֲבָל הָכָא, בְּבִנְיָינָא דְּבֵי מַקְדְּשָׁא, דְּסִטְרָא בִּישָׁא יִתְעַבָּר מֵעָלְמָא, לָא אִצְטְרִיךְ, דְּהָא מוֹחָא וּקְלִיפָּה דִּילֵיהּ הֲוֵי. אַקְדִּים מוֹחָא, דִּכְתִּיב הֵיטִיבָה בִרְצוֹנְךָ אֶת צִיּוֹן בְּקַדְמִיתָא, וּלְבָתַר תִּבְנֶה חוֹמוֹת יְרוּשָׁלַם. הַהִיא חוֹמָה דִּלְבַר, דְּאִיהִי קְלִיפָּה, דִּילֵיהּ הִיא מַמָּשׁ. דִּכְתִּיב, (זכריה ב׳:ט׳) וַאֲנִי אֶהְיֶה לָּהּ נְאֻם יְיָ' חוֹמַת אֵשׁ סָבִיב. אֲנִי וְלָא סִטְרָא בִּישָׁא.","יִשְׂרָאֵל, אִינּוּן מוֹחָא, עִלָּאָה דְּעָלְמָא. יִשְׂרָאֵל סְלִיקוּ בְּמַחֲשָׁבָה בְּקַדְמִיתָא, עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, דְּאִינּוּן קְלִיפָּה, אַקְדִּימוּ. דִּכְתִּיב, (בראשית ל״ו:ל״א) וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל. וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא, לְאַקְדְּמָא מוֹחָא, בְּלָא קְלִיפָּה. דִּכְתִּיב, (ירמיהו ב׳:ג׳) קֹדֶשׁ יִשְׂרָאֵל לַיְיָ' רֵאשִׁית תְּבוּאָתֹה, מוֹחָא קָדִים לִקְלִיפָּה. וְאַף עַל גַּב דְּמוֹחָא יְקוּם בְּלא קְלִיפָּה, מַאן הוּא דְּיוֹשִׁיט יַדָא לְמֵיכָל מִנֵּיהּ, בְּגִין, (ירמיהב) דְּכָל אוֹכְלָיו יֶאְשָׁמוּ רָעָה תָּבֹא אֲלֵיהֶם נְאֻם יְיָ'.","בְּהַהוּא זִמְנָא, (תהילים נ״א:כ״א) אָז תַּחְפּוֹץ זִבְחֵי צֶדֶק. בְּגִין, דְּהָא כְּדֵין, יִתְחַבָּר כֹּלָּא בְּחִבּוּרָא חֲדָא, וִיהֵא שְׁמָא שְׁלִים בְּכָל תְקּוּנֵיהּ. וּכְדֵין קָרְבְּנָא לֶהֱוֵי שְׁלִים, לַיְיָ' אֱלהִים. דְּהַשְׁתָּא אֱלהִים לָא אִתְחַבָּר לְקוֹרְבָּנָא, דְּאִלְמָלֵא אִתְחַבָּר בֵּיהּ, כַּמָה אֱלֹהִים יְסַלְקוּן אוּדְנִין לְאִתְחַבְּרָא תַּמָּן. אֲבָל בְּהַהוּא זִמְנָא, (תהילים פ״ו:י׳) כִּי גָּדוֹל אַתָּה וְעוֹשֶׂה נִפְלָאוֹת אַתָּה אֱלהִים לְבַדֶּךָ. וְאֵין אֱלֹהִים אַחֲרָא.","וּבְהַהוּא זִמְנָא כְּתִיב, (דברים ל״ב:ל״ט) רְאוּ עַתָּה כִּי אֲנִי אֲנִי הוּא וְאֵין אֱלהִים עִמָּדִי (ראו עתה) רְאוּ כִּי אֲנִי אֲנִי הוּא סַגִּי, מַאי עַתָּה. אֶלָּא דְּלָא הֲוָה קֹדֶם לָכֵן, וְהַהוּא זִמְנָא לִיהֲוֵי. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, עַתָּה רְאוּ, מַה דְּלָא תֵּיכְלוּן לְמֶיחֱמֵי מִקַּדְמַת דְּנָא.","כִּי אֲנִי אֲנִי, תְּרֵי זִמְנִי אֲמַאי. אֶלָּא לְדַיְיקָא, דְּהָא לֵית תַּמָּן אֱלֹהִים, אֶלָּא הוּא. דְּהָא כַּמָּה זִמְנִין, דְּאִתְּמַר אֲנִי זִמְנָא חֲדָא, וְלָא יַתִּיר, וַהֲוָה תַּמָּן סִטְרָא אַחֲרָא. אֲבָל הַשְׁתָּא אֲנִי אֲנִי הוּא וְאֵין אֱלֹהִים עִמָּדִי, דְּהָא כָּל סִטְרָא אַחֲרָא אִתְעֲבָר, וְדַיְיקָא אֲנִי אֲנִי.","אֲנִי אָמִית וַאֲחֲיֶּה, עַד הַשְׁתָּא מוֹתָא הֲוַת מִסִּטְרָא אַחֲרָא, מִכָּאן וּלְהָלְאָה, אֲנִי אָמִית וַאֲחֲיֶּה, מִכָּאן דִּבְהַהוּא זִמְנָא, כָּל אִינּוּן דְּלָא טַעֲמֵי טַעֲמָא דְּמוֹתָא. מִנֵּיהּ תְּהֵא לוֹן מוֹתָא, וְיָקִים לוֹן (מיד). אֲמַאי. בְּגִין דְּלָא יִשְׁתְּאַר מֵהַהוּא זוּהֲמָא בְּעָלְמָא כְּלָל, וִיהֵא עָלְמָא חַדְתָּא, בְּעוֹבְדֵי יְדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא.","(תנינן י' דברים כו' קי\"ג ע\"ב) (שייך לעיל ק\"ו ע\"א) (שמות כ״א:ה׳) וְאִם אָמֹר יֹאמַר וְגוֹ' לֹא אֵצֵא חָפְשִׁי. כְּמָה דְּאִתְּמַר כְּדֵין פָּגִים לֵיהּ פְּגִימוּ. אִם בְּגַפּוֹ יָבֹא, מַהוּ בְּגַפּוֹ. תָּנֵינָן, כְּתַרְגּוּמוֹ, בִּלְחוֹדוֹי. יֵאוֹת הוּא. אֲבָל הָא תָּנֵינָן, כָּל עָלְמָא, לָא קָאִים, אֶלָּא עַל גַּפָּא חֲדָא, דְּלִוְיָתָן.","וְרָזָא דָּא, בְּשַׁעֲתָא דְּקַיְּימָא דְּכַר וְנוּקְבָּא, דִּדְכַר וְנוּקְבָּא בָּרָא לוֹן קוּדְשָׁא בְּרִיךְ הוּא, וּבְכָל מַה דְּאַזְלִין, עָלְמָא מִזְדְּעַזְעָ, וְאִלְמָלֵא דְּסִרֵס קוּדְשָׁא בְּרִיךְ הוּא דְּכוּרָא, וְצִנֵּן יַת נוּקְבָּא, הֲווֹ מְטַשְׁטְשִׁין עָלְמָא. וְעַל דָּא לָא עַבְדִין תּוֹלָדִין, (דבר אחר ומאן דלא עביד תולדין בגפו) אִם בְּגַפּוֹ יָבֹא, תְּחוֹת הַהוּא גַּפָּא, דְּלָא עָבִיד תּוֹלָדִין עָאל. וְהוֹאִיל וְכֵן, בְּגַפּוֹ יֵצֵא, לְתַמָּן אִתְדַחָא, וְלָא עָאל לְפַרְגּוֹדָא כְּלָל, וְאִתְדֲחָא וְאִטְרִיד מֵהַהוּא עָלְמָא. בְּגַפּוֹ יֵצֵא, בְּגַפּוֹ יֵצֵא וַדַּאי.","תָּא חֲזֵי, מַה כְּתִיב, (ויקרא כ׳:כ׳) עֲרִירִים יָמוּתוּ, עֲרִירִים (כתיב) כְּלָל דְּכַר וְנוּקְבָּא. בְּרָזָא דִּדְכוּרָא עָאל, וּבְרָזָא דְּנוּקְבָּא יִפּוּק. עָאל בְּהַאי, וְיִפּוּק בְּהַאי. וְהַאי אִיהוּ אֲתָר, דְּקָא אִתְדָּבַּק בֵּיהּ בְּהַהוּא עָלְמָא, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא לָא בָּעֵי דְּיֵעוֹל קָמֵיהּ, מַאן דִּמְסָרֵס גַּרְמֵיהּ בְּהַאי עָלְמָא."],[[0,"הכא אית רזא וכו':","כאן יש סוד, כל המעשים שעושה הקב\"ה, מתחילה מקדים זה שמבחוץ, ואח\"כ עושה המוח שמבפנים. וכאן אינו כן כי הקדים בנין ביהמ\"ק, לבנין החומות, שהם מבחוץ. ומשיב, בוא וראה, כל אלו המעשים שעושה הקב\"ה ומקדים ההוא שמבחוץ, הנה במחשבה, מקדים את המוח, דהיינו ההוא שבפנים. ובמעשה, מקדים ההוא שמבחוץ. כי כל קליפה, דהיינו מה שמבחוץ, הוא מצד האחר, והמוח נמשך מן המוח, דהיינו צד הקדושה. ותמיד מקדים הצד האחר, ומתרבה וגדל ושומר הפרי. כיון שנתבשל הפרי זורקים הקליפה לחוץ, ויכין רשע וצדיק ילבש. וזורקים קליפה ההיא ומברכים לצדיקו של עולם."],[1,"אבל הכא בבנינא וכו':","אבל כאן בבנין בית המקדש, לעתיד לבא, שהצד האחר נעבר מן העולם, אינו צריך להקדים את ההוא שמבחוץ, כי המוח והקליפה שניהם הם שלו, וע\"כ מקדים המוח, שכתוב, הטיבה ברצונך את ציון מתחילה, ואח\"כ תבנה חומות ירושלים. כי חומה ההיא שמבחוץ, שהיא הקליפה, היא שלו ממש, שכתוב, ואני אהיה לה נאם ה' חומת אש סביב. אני ולא צד הרע."],[2,"ישראל אינון מוחא וכו':","ישראל הם מוח העליון של העולם, ישראל עלה במחשבה תחילה, כי במחשבה קדמה הפנימיות אל הקליפה כנ\"ל. העמים עכו\"ם שהם הקליפה של ישראל, הקדימו במעשה, כי במעשה הקליפה קדמה לפרי, כנ\"ל, שכתוב, ואלה המלכים אשר מלכו בארץ אדום לפני מלך מלך לבני ישראל. ועתיד הקב\"ה להקדים המוח בלא קליפה, שכתוב קדש ישראל לה' \u0003ראשית תבואתה\u0004 דהיינו שהמוח קודם לקליפה. ואע\"פ שהמוח יקום בלא קליפה, מי הוא שיושיט ידו לאכול ממנו, משום, שכל אוכליו יאשמו רעה תבא אליהם נאם ה'."],[3,"בההוא זמנא וכו':","בזמן ההוא כתוב, אז תחפוץ זבחי צדק, משום, כי אז, יתחבר הכל בחבור אחד ויהיה השם שלם בכל תקונו, ואז הקרבן יהיה שלם להויה אלקים. כי עתה אלקים אינו מתחבר אל הקרבן, כי אם היה מתחבר בו, כמה אלהים אחרים יעלו אזנים להתחבר שם, ויינקו מן הקדושה ח\"ו. אבל בזמן ההוא, כתוב, כי גדול אתה ועושה נפלאות אתה אלקים לבדך. ואין אלהים אחר."],[4,"ובההוא זמנא כתיב, וכו':","ובזמן ההוא כתוב, ראו עתה כי אני אני הוא ואין אלקים עמדי. ושואל, ראו כי אני אני הוא, היה די למה נאמר \u0003עתה.\u0004 ומשיב, אלא, שזה לא היה מקודם לכן ובזמן ההוא יהיה. אמר הקב\"ה, עתה ראו מה שלא יכלתם לראות מקודם לכן."],[5,"כי אני אני וכו':","שואל, כי אני אני, ב' פעמים למה. ומשיב, אלא לדייק, שאין שם אלקים אלא הוא. כי כמה פעמים שנאמר אני פעם אחת ולא יותר, והיה שם צד האחר, אבל עתה אני אני הוא ואין אלהים עמדי, כי כל צד האחר נעבר. ובדיוק הוא אני אני."],[6,"אני אמית ואחיה וכו':","עד עתה היה המות על ידי צד האחר, מכאן ולהלאה, אני אמית ואחיה. מכאן שבזמן ההוא, דהיינו לתחיית המתים, כל אלו שלא טעמו טעם המות, ממנו, מן הקב\"ה, יהיה להם המות ויקום אותם מיד לתחיה. למה נעשה המות ע\"י הקב\"ה. כדי שלא ישאר מן זוהמה ההיא כלום בעולם, ויהיה עולם חדש במעשה ידיו של הקב\"ה."],[7,"ואם אמר יאמר וגו':","לא אצא חפשי. כמו שבארנו (לעיל אות ר\"כ) אז פוגם אותו בפגם, דהיינו ורצע אדוניו את אזנו במרצע. אם בגפו יבא, מהו בגפו. למדנו, כתרגומו, בלחודוי. יפה הוא. אבל הרי למדנו, כל העולם אינו עומד אלא על סנפיר אחד של לויתן."],[8,"ורזא דא בשעתא וכו':","וסוד זה הוא, שבשעה שנמצא הלויתן דכר ונוקבא, כי דכר ונוקבא ברא אותם הקב\"ה, בכל מקום שהלכו היה העולם מזדעזע, ואם לא סרס הקב\"ה את הזכר וצינן את הנקבה, היו מעכירים את העולם. ועל כן אינו עושה תולדות. וזהו, אם בגפו יבא, אם בא תחת גף ההוא של לויתן, שאינו עושה תולדות, וכיון שכן, בגפו יצא, הוא נדחה שמה, ואינו נכנס למחיצתו של המלך כלל, ונדחה ונטרד מעולם ההוא. בגפו יצא, בגפו יצא ודאי."],[9,"ת\"ח מה כתיב וכו':","בוא וראה, מה כתוב, ערירים ימותו. ערירים כולל דכר ונוקבא, בסוד הדכר בא, ובסוד הנוקבא יצא, (כנ\"ל אות רי\"ט) בא בזה ויצא בזה. וזה הוא המקום שנתדבק בו בעולם ההוא. דהיינו במלכות. כי הקב\"ה אינו רוצה שיבא לפניו מי שסירס עצמו בעולם הזה."]],[[0,"","כָּאן יֵשׁ סוֹד. כָּל הַמַּעֲשִׂים שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, בַּהַתְחָלָה מַקְדִּים אוֹתוֹ שֶׁלְּבַחוּץ, וְאַחַר הַמֹּחַ שֶׁלִּפְנִים, וְכָאן לֹא כָּךְ. בֹּא וּרְאֵה, כָּל אוֹתָם הַמַּעֲשִׂים שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא וּמַקְדִּים אוֹתוֹ שֶׁל בַּחוּץ, הַמֹּחַ הִקְדִּים בְּמַחֲשָׁבָה, וּבְמַעֲשֶׂה אוֹתוֹ שֶׁל בַּחוּץ, שֶׁהֲרֵי כָּל קְלִפָּה הִיא מִצַּד הָאַחֵר, וְהַמֹּחַ מִן הַמֹּחַ, וְתָמִיד הַצַּד הָאַחֵר מַקְדִּים וְגָדֵל וּמִתְרַבֶּה וְשׁוֹמֵר הַפְּרִי. כֵּיוָן שֶׁמִּתְרַבֶּה, זוֹרְקִים אוֹתוֹ הַחוּצָה, וְיָכִין רָשָׁע וְצַדִּיק יִלְבַּשׁ, וְזוֹרְקִים אֶת אוֹתָהּ קְלִפָּה, וּמְבָרְכִים אֶת הַצַּדִּיק בָּעוֹלָם."],[1,"","אֲבָל כָּאן, בְּבִנְיַן בֵּית הַמִּקְדָּשׁ, שֶׁהַצַּד הָרָע יַעֲבֹר מֵהָעוֹלָם - לֹא צָרִיךְ, שֶׁהֲרֵי הַמֹּחַ וְהַקְּלִפָּה שֶׁלּוֹ הָיָה. הִקְדִּים הַמֹּחַ, שֶׁכָּתוּב הֵיטִיבָה בִרְצוֹנְךְ אֶת צִיּוֹן - בַּהַתְחָלָה, וְאַחַר כָּךְ תִּבְנֶה חוֹמוֹת יְרוּשָׁלם. אוֹתָהּ חוֹמָה הַחִיצוֹנִית, שֶׁהִיא קְלִפָּה, שֶׁלּוֹ הִיא מַמָּשׁ, שֶׁכָּתוּב (זכריה ב) וַאֲנִי אֶהְיֶה לָּהּ נְאֻם ה' חוֹמַת אֵשׁ סָבִיב. אֲנִי וְלֹא הַצַּד הָרָע."],[2,"","יִשְׂרָאֵל הֵם הַמֹּחַ הָעֶלְיוֹן שֶׁל הָעוֹלָם. יִשְׂרָאֵל עָלוּ בַמַּחֲשָׁבָה בַּתְּחִלָּה. הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, שֶׁהֵם קְלִפָּה, הִקְדִּימוּ, שֶׁכָּתוּב (בראשית לו) וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל. וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַקְדִּים אֶת הַמֹּחַ בְּלִי קְלִפָּה, שֶׁכָּתוּב (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה. הַמֹּחַ קוֹדֵם לַקְּלִפָּה. וְאַף עַל גַּב שֶׁהַמֹּחַ יַעֲמֹד בְּלִי קְלִפָּה, מִי הוּא שֶׁיּוֹשִׁיט יָד לֶאֱכֹל מִמֶּנּוּ? מִשּׁוּם שֶׁכָּל אֹכְלָיו יֶאְשָׁמוּ רָעָה תָּבא אֲלֵיהֶם נְאֻם ה'."],[3,"","בְּאוֹתוֹ זְמַן, (תהלים נא) אָז תַּחְפֹּץ זִבְחֵי צֶדֶק. הֱיוֹת שֶׁהֲרֵי אָז יִתְחַבֵּר הַכֹּל בְּחִבּוּר אֶחָד, וְיִהְיֶה הַשֵּׁם שָׁלֵם בְּכָל תִּקּוּנוֹ, וְאָז הַקָּרְבָּן יִהְיֶה שָׁלֵם לַה' אֱלֹהִים. שֶׁעַכְשָׁו אֱלֹהִים לֹא מִתְחַבֵּר לַקָּרְבָּן, שֶׁאִלְמָלֵא הִתְחַבֵּר בּוֹ, כַּמָּה אֱלֹהִים יַעֲלוּ אָזְנַיִם לְהִתְחַבֵּר לְשָׁם. אֲבָל בְּאוֹתוֹ זְמַן, (שם פו) כִּי גָדוֹל אַתָּה וְעוֹשֵׂה נִפְלָאוֹת אַתָּה אֱלֹהִים לְבַדֶּךְ. וְאֵין אֱלֹהִים אַחֵר."],[4,"","וּבְאתוֹ זְמַן כָּתוּב, (דברים לב) רְאוּ עַתָּה כִּי אֲנִי אֲנִי הוּא וְאֵין אֱלֹהִים עִמָּדִי. (ראועתה) רְאוּ כִּי אֲנִי אֲנִי הוּא גָּדוֹל, מַה זֶּה עַתָּה? אֶלָּא שֶׁלֹּא הָיָה קֹדֶם לָכֵן, וּבְאוֹתוֹ זְמַן זֶה יִהְיֶה. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, עַתָּה רְאוּ מַה שֶּׁלֹּא יְכָלְתֶּם לִרְאוֹת מִקֹּדֶם לָכֵן."],[5,"","כִּי אֲנִי אֲנִי, לָמָּה פַּעֲמַיִם? אֶלָּא כְּדֵי לְדַיֵּק, שֶׁהֲרֵי אֵין שָׁם אֱלֹהִים, אֶלָּא הוּא. שֶׁהֲרֵי כַּמָּה פְעָמִים שֶׁנֶּאֱמַר אֲנִי פַּעַם אַחַת וְלֹא יוֹתֵר, וְהָיָה שָׁם הַצַּד הָאַחֵר. אֲבָל עַכְשָׁו אֲנִי אֲנִי הוּא וְאֵין אֱלֹהִים עִמָּדִי, שֶׁהֲרֵי כָּל הַצַּד הָאַחֵר הָעֳבַר, וְדַוְקָא אֲנִי אֲנִי."],[6,"","אֲנִי אָמִית וַאֲחַיֶּה. עַד עַכְשָׁו הַמֹּחַ הָיָה מִן הַצַּד הָאַחֵר. מִכָּאן וָהָלְאָה, אֲנִי אָמִית וַאֲחַיֶּה. מִכָּאן שֶׁבְּאוֹתוֹ הַזְּמַן, כָּל אוֹתָם שֶׁלֹּא טָעֲמוּ טַעַם הַמָּוֶת - מִמֶּנּוּ יִהְיֶה לָהֶם מָוֶת, וְיָקִים אוֹתָם (מיד). לָמָּה? כְּדֵי שֶׁלֹּא תִשָּׁאֵר מֵאוֹתָהּ הַזֻּהֲמָה בָּעוֹלָם כְּלָל, וְיִהְיֶה עוֹלָם חָדָשׁ בְּמַעֲשֵׂי יְדֵי הַקָּדוֹשׁ בָּרוּךְ הוּא."],[7,"","וְאִם אָמֹר יֹאמַר וְגוֹ' לֹא אֵצֵא חָפְשִׁי, כְּמוֹ שֶׁנִּתְבָּאֵר, אָז פּוֹגֵם אוֹתוֹ בִּפְגָם. אִם בְּגַפּוֹ יָבא, מַה זֶּה בְּגַפּוֹ שָׁנִינוּ, כְּתַרְגּוּמוֹ - לְבַדּוֹ. יָפֶה הוּא. אֲבָל הֲרֵי שָׁנִינוּ, כָּל הָעוֹלָם לֹא עוֹמֵד אֶלָּא עַל סְנַפִּיר אֶחָד שֶׁל לִוְיָתָן."],[8,"","וְסוֹד זֶה, בְּשָׁעָה שֶׁעוֹמְדִים זָכָר וּנְקֵבָה, שֶׁזָּכָר וּנְקֵבָה בָּרָא אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבְכָל מַה שֶּׁהוֹלְכִים, הָעוֹלָם מִזְדַּעֲזֵעַ, וְאִלְמָלֵא שֶׁסֵּרַס הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַזָּכָר וְצִנֵּן אֶת הַנְּקֵבָה, הָיוּ מַחֲרִיבִים אֶת הָעוֹלָם, וְעַל כָּךְ לֹא עוֹשִׂים תּוֹלָדוֹת. (ומישלאעושהתולדות בגפו) אִם בְּגַפּוֹ יָבֹא, תַּחַת אוֹתוֹ סְנַפִּיר שֶׁלֹּא עוֹשֶׂה תוֹלָדוֹת נִכְנָס. וְהוֹאִיל וְכֵן בְּגַפּוֹ יֵצֵא, לְשָׁם נִדְחֶה, וְלֹא נִכְנָס לַפַּרְגּוֹד כְּלָל, וְנִדְחֶה וְנִטְרָד מֵאוֹתוֹ הָעוֹלָם. בְּגַפּוֹ יֵצֵא, בְּגַפּוֹ יֵצֵא וַדַּאי."],[9,"","בֹּא וּרְאֵה מַה כָּתוּב, (ויקרא כ) עֲרִירִים יָמֻתוּ. עֲרִירִים (כתוב) - כְּלָל שֶׁל זָכָר וּנְקֵבָה. בְּסוֹד שֶׁל זָכָר נִכְנָס, וּבְסוֹד שֶׁל נְקֵבָה יֵצֵא. נִכְנָס בָּזֶה וְיוֹצֵא בָּזֶה. וְזֶהוּ מָקוֹם שֶׁנִּדְבָּק בּוֹ בְּאוֹתוֹ הָעוֹלָם, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא רוֹצֶה שֶׁיִּכָּנֵס לְפָנָיו מִי שֶׁמְּסָרֵס עַצְמוֹ בָּעוֹלָם הַזֶּה."]]],[["תָּא חֲזִי, מִן קָרְבְּנָא. דְּלָא הֲווֹ מְקָרְבִין קָמֵיהּ סִרוּסָא, וְאַפִּיקוּ לֵיהּ, דְּלָא יִתְקָרִב לְקָמֵיהּ, וּפָקִיד וְאָמַר, (ויקרא כ״ב:כ״ד) וּבְאַרְצְכֶם לֹא תַּעֲשׂוּ. וְכֵן לְדָרֵי דָּרִין אָסִיר לְסָרוּסֵי בִּרְיָין, דְּבָרָא קוּדְשָׁא בְּרִיךְ הוּא בְּעָלְמָא. דְּהָא כָּל סִרוּסָא, דְּסִטְרָא אַחֲרָא אִיהוּ.","וְאִי אִיהוּ אִשְׁתָּדַּל, וְנָסִיב אִיתְּתָא, וְלָא עָבִיד תּוֹלָדִין, וְלָא בָּעָא, וְאַף עַל גַּב דְּאִית לֵיהּ אִיתְּתָא, אוֹ אִי הִיא לָא בָּעָאת, וְעָאל לְהַהוּא עָלְמָא, בְּלָא תּוֹלָדִין, מַה כְּתִיב. אִם בַּעַל אִשָּׁה הוּא, וְלָא אַשְׁגָּחוּ לְפֹעַל יְדוֹי דְּמָארֵיהוֹן, וְיָצְאָה אִשְׁתּוֹ עִמּוֹ, אִיהוּ יֵעוּל בְּגַפּוֹ דִּדְכוּרָא, וְאִיהִי בְּנוּקְבָא. בְּגַפּוֹ יָבֹא בְּגַפּוֹ יֵצֵא כְּמָה דְּאִתְּמַר, כֹּלָּא עַל תְקּוּנֵיהּ.","אִם אֲדֹנָיו יִתֶּן לוֹ אִשָּׁה, כְּמָה דְּאִתְּמַר, אִם אֲדֹנָיו, דָּא אִיהוּ אֲדוֹן כָּל הָאָרֶץ. יִתֶּן לוֹ אִשָּׁה, מֵהָכָא, דְּלָאו בִּרְשׁוּתָא דְּבַר נָשׁ קַיְּימָא לְמֵיסָב אִתְּתָא. אֶלָּא (כלא משלי ט״ז:י״א פלס מאזני משפט יי') כֹּלָּא בְּמֹאזְנַיִם לַעֲלוֹת. יִתֶּן לוֹ אִשָּׁה, דְּהָא לָאו בִּרְשׁוּתֵיהּ אִיהוּ. וּמַאן אִיהִי. הַהִיא דְּלָאו דִּילֵיהּ, וְלָא אִזְדַּמְּנַת לְגַבֵּיהּ, וּמַאן אִיהִי. הַהִיא דַּהֲוַת זְמִינָא לְאַחֲרָא, וְאַקְדִּים הַאי בְּרַחֲמֵי, וְנָטִיל לָהּ, דָּא אִתְיְיהִיבַת לֵיהּ, דְּלָא אִתְחֲזִיאַת לֵיהּ.","וְקוּדְשָׁא בְּרִיךְ הוּא חָמֵי מֵרָחִיק, וְחָמֵי לְהַהִיא אִתְּתָא, דִּזְמִינַת לְאַפָּקָא תּוֹלָדִין בְּעָלְמָא. אַקְדִּים הַאי בְּרַחֲמֵי, וְאִתְיְיהִיבַת לֵיהּ, וְעָבִיד אִיבִין, וְזָרַע זַרְעָא, בְּאִתְּתָא (ס\"א בגנתא) דְּלָאו דִּילֵיהּ, בְּגִין כָּךְ, הָאִשָּׁה וִילָדֶיהָ תִּהְיֶה לַאדֹנֶיהָ, וְהוּא יֵצֵא בְגַפּוֹ. אִי עַנְיָיא מִסְכְּנָא, כַּמָּה אִשְׁתָּדַּל בְּרֵיקַנְיָּא, לָאָה וְאִשְׁתָּדַּל לְמֶעְבַּד פֵּירִין, בְּגִנְתָּא דְּלָאו אִיהִי דִּילֵיהּ, וְנָפַק בְּרֵיקַנְיָּא.","סָבָא סָבָא, בְּעִדָנִין (נ\"א בעניינין) אִלֵּין, לָא הֲוֵית בְּרַגְלָיךְ דָּחֵי לְתַרְעָא, כְּמַאן דְּשָׁכִיב בְּאַרְעָא בְּלָא תּוּקְפָּא, דְּהָא אִתְחֲלָשׁ וּמֵחָלְשָׁא סַגִּי, דְּלָא יָכִיל, דָּחֵי בְּרַגְלוֹי. אִתְּתְקַף סָבָא, וְלָא תִּדְחַל. הָא עַנְיָיא מִסְכְּנָא, דְּאִשְׁתַּדַּל בְּרֵיקַנְיָּא, אֵימָא אֲמַאי. אִי בְּגִין דְּזָרַע בְּגִנְתָּא אַחֲרָא דְּלָאו דִּילֵיהּ, יֵאוֹת. אִי הָכִי (ס\"א אבל הכא) קוּדְשָׁא בְּרִיךְ הוּא יָהִיב לֵיהּ הַהוּא גִּנְתָּא לְמִזְרַע בָּהּ, דְּהָא אִיהוּ לָא נָטִיל לָהּ.","אֶלָּא תָּא חֲזֵי כָּל מִלִּין דְּקוּדְשָׁא בְּרִיךְ הוּא עֲבִיד כֻּלְּהוּ בְּדִינָא אִינּוּן וְלָא הֲוֵי מִלָּה בְּרֵיקַנְיָא הָאי דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב לֵיהּ אִתְּתָא וְעָבַד בָּהּ פֵּירִין וְאִיבִּין לָאו הָאי כִּשְׁאָר בְּנֵי גִלְגוּלָא וְלָא דָמֵי מָאן דְאִשְׁתַדָל בְּהָאי עָלְמָא לְאַסְגָּאָה אִילָנָא (ס\"א ולא יכיל) לְמָאן דְלָא בָּעָא לְאַסְגָּאָה וּלְאִשְׁתָּדְלָא וְאַעֲקָר וְאַפִּיל טַרְפִּין דְאִילָנָא וְאַזְעָר אִיבָּא דִּילֵיהּ.","הַאי דַּאֲדֹנָיו יָהִיב לֵיהּ אִתְּתָא, בְּגִין לְמֶעְבַּד אִיבִין, הָא אִשְׁתָּדַּל בְּקַדְמִיתָא בְּגִין לְאַסְגָּאָה אִילָנָא, וְלָא יָכִיל. זַכְיָין כָּל כַּךְ לֵית לֵיהּ, (ס\"א דבנין גם כן לית ליה) דְּאִי הֲוָה זַכָּאָה כְּדְקָא יֵאוֹת, לָא הֲוָה תָּב בְּגִלְגּוּלָא, (כאבנא בקוספיתא) דְּהָא כְּתִיב, (ישעיהו נ״ו:ה׳) וְנָתַתִּי לָכֶם בְּבֵיתִי וּבְחוֹמוֹתַי יָד וָשֵׁם טוֹב מִבָּנִים וּמִבָּנוֹת. וְהַשְׁתָּא דְּלָא זָכָה, קוּדְשָׁא בְּרִיךְ הוּא חָמֵי, דְּהָא אִשְׁתָּדַּל וְלָא יָכִיל, הַאי, אֲדוֹנָיו יִתֶּן לוֹ אִשָּׁה, כְּמָה דְּאִתְּמַר. וְכֵיוָן דְּחָס עָלֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְיָהַב לֵיהּ בְּרַחֲמֵי, קוּדְשָׁא בְּרִיךְ הוּא גַּבֵי מִדִּידֵיהּ בְּקַדְמִיתָא, וְנָטִיל מַה דְּגָרַע הַהוּא מַבּוּעָא, וּבְּגִין כָּךְ, הָאִשָּׁה וִילָדֶיהָ תִּהְיֶה לַאדֹנֶיהָ, וּלְבָתַר יֵיתוּב, וְיִשְׁתָּדֵּל עַל גַּרְמֵיהּ, לְאַשְׁלוּמֵי גִּרְעוֹנֵיהּ. עַד הָכָא רָזָא דִּקְרָא.","סָבָא סָבָא, אַתְּ אֲמַרְתְּ עַל דָּא, דִּבְרֵיקָנְיָא אִשְׁתָּדַּל, וְלָא אַשְׁגַּחְתּ עֲלָךְ, דִּבְרֵיקָנְיָא אַתְּ אָזִיל בְּמָה דַּאֲמַרְתְּ, דְּהָא קְרָא רָדִיף אֲבַתְרָךְ, דְּסָתִיר כָּל בִּנְיָינָא דְּבָנִית עַד הַשְׁתָּא, וְאַת חָשִׁיב דְּאַנְתְּ מְשַׁטְּטָא יַמָּא לִרְעוּתָךְ. וּמַאי אִיהוּ. דִּכְתִּיב, וְאִם אָמֹר יֹאמַר הָעֶבֶד אָהַבְתִּי אֶת אֲדוֹנִי אֶת אִשְׁתִּי וְגוֹ'.","אִי סָבָא סָבָא, לָאֵי חֵילָא, מַה תַּעֲבֵיד, חָשַׁבְתּ דְּלָא לִיהֲוֵי מַאן דְּרָדִיף אֲבַתְרָךְ, הָא הַאי קָרָא רָדִיף אֲבַתְרָךְ, וְנָפִיק מִבָּתַר כֹּתָלָא, כְּאַיָּלָה בְּחַקְלָא, מְדַלֵּג דִּלּוּגִין אֲבַתְרָךְ, תְּלֵיסַר דִּילּוּגִין דָּלִיג אֲבַתְרָךְ וְאַדְבִּיק לָךְ, מַה תַּעְבִּיד סָבָא. הַשְׁתָּא אִית לָךְ לְאִתְגַּבְּרָא בְּחֵילָךְ. דְּהָא גִּיבָּר תַּקִּיף הֲוֵית עַד יוֹמָא. סָבָא סָבָא, הֲוֵי דָּכִיר יוֹמָא (צ\"ז ע\"ב) דְּתַלְגָּא, כַּד זְרַעְנָא פּוֹלִין, וַהֲווּ כַּמָּה גּוּבְרִין בְּנִי חֵילָא, לָקֳבְלָךְ, וְאַנְתְּ בִּלְחוֹדָךְ, נָצַחְתְּ תְּלֵיסָר גַּבְרִין תַּקִּיפִין, בְּנֵי חֵילָא, דְּכָל חַד מִנַּיְיהוּ קָטִיל אַרְיָא, עַד לָא יֵיכוּל."],[[0,"תא חזי מן וכו':","בוא וראה מן הקרבן, שלא היו מקריבים לפניו מסורס, והוציאו אותו שלא יתקרב לפניו, וצוה ואמר, ובארצכם לא תעשו. וכן לדורי דורות אסור לסרס בריות שברא הקב\"ה בעולם. כי כל סירוס הוא מצד האחר."],[1,"ואי איהו אשתדל וכו':","ואם הוא השתדל ונשא אשה, ולא עשה תולדות, ולא רצה, ואע\"פ שיש לו אשה, או היא אינה רוצה, ובא לעולם ההוא בלא בנים, מה כתוב, אם בעל אשה הוא, ולא השגיחו לפועל ידיו של הקב\"ה, להוליד בנים, ויצאה אשתו עמו. הוא בא בגף של הזכר, והיא בגף של הנקבה, שהיא המלכות, וכל אחד, בגפו יבא בגפו יצא. כמו שבארנו, והכל על תקונו."],[2,"אם אדניו יתן לו אשה:","כמו שלמדנו, \u0003אם אדניו,\u0004 זה הוא אדון כל הארץ, שהוא מלכות, \u0003יתן לו אשה,\u0004 מכאן שאין ברשותו של אדם לישא אשה, אלא הכל במאזנים לעלות. דהיינו, לפי משקל הזכיות כך הוא עולה. וע\"כ, יתן לו אשה, כי הוא אינו ברשותו. ומי היא. היא ההיא שאינו שלו, שאינה בת זוגו, ואינה מוכנת לו, ומי היא, היא אשה ההיא שהיתה מוכנת לאחר, והקדים הוא ברחמים, ונשא אותה. זו ניתנה לו, שלא היתה ראויה לו."],[3,"וקב\"ה חמי מרחיק וכו':","והקב\"ה רואה מרחוק, ורואה שאשה ההיא מוכנת להוציא תולדות בעולם, ואחר שהקדים זה ברחמים, ניתנה לו, ועשה פירות, וזרע זרע, באשה שאינו שלו. משום זה האשה וילדיה תהיה לאדניה והוא יצא בגפו. אי עני מסכן, כמה השתדל לריק, עמל והשתדל לעשות פירות בגן שאינו שלו, ויצא ריקם."],[4,"סבא סבא בעדנין וכו':","אמר לעצמו, זקן זקן, בזמנים כאלו, לא היית דוחה את השער ברגליך, כמי ששוכב על הארץ בלא כח, כי נחלש, ומרוב חולשתו, שאינו יכול לפתוח את השער, דוחה אותו ברגליו. התחזק זקן ואל תפחד. זה העני המסכן שהשתדל לריק, למה. אם בשביל שזרע בגן אחר שאינו שלו, יפה, אבל כן, הקב\"ה נתן לו את גן ההוא לזרע בו, שהרי הוא לא לקחה מעצמו."],[5,"אלא ת\"ח וכו':","אלא בוא וראה, כל דברי הקב\"ה, עושה כולם בדין, ולא יש דבר ריק. זה שהקב\"ה נותן לו אשה, ועשה בה פירות ואבים, אין זה כשאר בני הגלגול, ואינו דומה מי שמשתדל בעולם הזה להרבות האילן, ואינו יכול, למי שלא רצה להשתדל להרבות, ועקר והפיל עלים מן האילן והמעיט פירות שלו."],[6,"האי דאדניו יהיב וכו':","זה שאדוניו יתן לו אשה כדי לעשות פירות, הוא השתדל מתחילה להרבות האילן, ולא יכול, זכיות כל כך אין לו, שאם היה זכאי כראוי, לא היה חוזר בגלגול, כי כתוב, ונתתי לכם בביתי ובחומותי יד ושם טוב מבנים ובנות. ועתה שלא זכה, הקב\"ה רואה שהשתדל להוליד בנים ולא יכול, זה, אדוניו יתן לו אשה, כמו שלמדנו, וכיון שרחם עליו הקב\"ה ונתן לו אשה ברחמים, הקב\"ה לוקח את שלו מתחילה, ולוקח מה שהוא גרע את המבוע ההוא מקודם לכן, ומשום זה, האשה וילדיה תהיה לאדניה. ואח\"כ יחזור וישתדל על עצמו להשלים את חסרונו. עד כאן סוד הכתוב."],[7,"סבא סבא את וכו':","אמר לעצמו, זקן זקן, אתה אמרת על זה, שהשתדל לריק להוליד בנים, ולא השגחת עליך, שאתה הולך ריקם, במה שאמרת, שהרי מקרא רודף אחריך, הסותר את כל הבנין שבנית עד עתה, ואתה חושב שאתה משוטט בים לרצונך. ומה הוא המקרא, שכתוב, ואם אמר יאמר העבד אהבתי את אדוני את אשתי ואת בני וגו'. הרי שחוזר וזוכה אותם, ולא השתדל לריק."],[8,"אי סבא סבא וכו':","אי זקן זקן עייף בלא כח, מה תעשה, חשבת שלא יהיה מי שירדוף אחריך, הרי מקרא זה רודף אחריך, ויצא מאחרי הכותל כאילה בשדה, כלומר, שלא זכרו מקודם ונזכר בו פתאום, וכמו מדלג דלוגים אחריך, י\"ג דלוגים דלג אחריך, שהם י\"ג מלות שבכתוב, ואם אמר יאמר עד המלה חפשי, ולא עד בכלל, והשיג אותך. מה תעשה זקן. עתה יש לך להתגבר בכחך כי גבור חזק היית עד היום, זקן זקן, הוי זוכר יום השלג כשזרענו פולין, והיו כמה גבורים אנשי חיל כנגדך, ואתה לבדך נצחת י\"ג גבורים אנשי חיל, שכל אחד מהם הרג אריה מטרם שיאכל."],[8,"","פירוש. זריעת פולין ביום השלג כבר ביארנו לעיל (באות נ\"ב). שהוא עלית המלכות למקום בינה, שמחמת זה נפלו בינה ותו\"מ מכל המדרגות, החל מבינה שיצאה מראש דא\"א עד סוף המדרגות. \u0003ביום השלג,\u0004 היינו במוחין דשמאל, הבאים עם נקודת השורק. ע\"ש. ונודע שע\"י עלית המלכות לבינה, בסוד נקודת החולם נחלקו הע\"ס לי\"ג ספירות, כי נעשו ב' פעמים חג\"ת (כמ\"ש לעיל בהקסה\"ז דף י\"ג ד\"ה והנה, עש\"ה) וז\"ש, \u0003יומא דתלגא כד זרענא פולין,\u0004 דהיינו שהעלה מ\"ן לעלית המלכות בבינה, כדי לבטל הדינים דשלג \u0003והוו כמה גוברין בני חילא לקבלך\u0004 דהיינו התחלקות הספירות לי\"ג, \u0003דכל חד מנייהו קטיל אריה עד לא ייכול,\u0004 שמחמת הדינים דיום השלג, בטלו החסדים המכונים אריה, הנבחן להריגה, כדי שיכלו לקבל אור החכמה מקו השמאל. והמשכת האורות, מכונה אכילה. \u0003ואנת בלחודך נצחת תליסר גברין תקיפין.\u0004 כי העלה מ\"ן לעלית המלכות למקום בינה, ואז נתמעטו הי\"ג גבורים מקו שמאל, ונתחברו עם החסדים שבקו ימין, המכונים אריה. ולא הרגו אותו יותר."]],[[0,"","בֹּא וּרְאֵה מִן הַקָּרְבָּן, שֶׁלֹּא הָיוּ מַקְרִיבִים לְפָנָיו מְסֹרָס, וְהוֹצִיאוּ אוֹתוֹ שֶׁלֹּא יִקְרַב לְפָנָיו, וְצִוָּה וְאָמַר, (ויקרא כב) וּבְאַרְצְכֶם לֹא תַעֲשׂוּ. וְכֵן לְדוֹרֵי דוֹרוֹת אָסַר לְסָרֵס אֶת הַבְּרִיּוֹת שֶׁבְּרָאָם הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם, שֶׁהֲרֵי כָּל סֵרוּס הוּא שֶׁל הַצַּד הָאַחֵר."],[1,"","וְאִם הוּא הִשְׁתַּדֵּל וְנָשָׂא אִשָּׁה וְלֹא עָשָׂה תוֹלָדוֹת וְלֹא רָצָה, וְאַף עַל גַּב שֶׁיֵּשׁ לוֹ אִשָּׁה, אוֹ שֶׁהִיא לֹא רָצְתָה, וְנִכְנָס לְאוֹתוֹ עוֹלָם בְּלִי תוֹלָדוֹת - מַה כָּתוּב? אִם בַּעַל אִשָּׁה הוּא, וְלֹא הִשְׁגִּיחוּ לְפֹעַל יְדֵי רִבּוֹנָם, וְיָצְאָה אִשְׁתּוֹ עִמּוֹ. הוּא יִכָּנֵס בְּגַפּוֹ שֶׁל זָכָר, וְהִיא בִּנְקֵבָה. בְּגַפּוֹ יָבא בְּגַפּוֹ יֵצֵא, כְּמוֹ שֶׁנִּתְבָּאֵר, הַכֹּל עַל תִּקּוּנוֹ."],[2,"","אִם אֲדנָיו יִתֶּן לוֹ אִשָּׁה, כְּמוֹ שֶׁנִּתְבָּאֵר. אִם אֲדנָיו - זֶה אֲדוֹן כָּל הָאָרֶץ. יִתֶּן לוֹ אִשָּׁה - מִכָּאן שֶׁלֹּא בִּרְשׁוּת הָאָדָם עוֹמֵד לָשֵׂאת אִשָּׁה, אֶלָּא (הכל (משלי טז) פלס ומאזני משפט לה') הַכֹּל בְּמֹאזְנַיִם לַעֲלוֹת. יִתֶּן לוֹ אִשָּׁה, שֶׁהֲרֵי זֶה לֹא בִּרְשׁוּתוֹ הוּא, וּמִי הִיא? הַהִיא שֶׁאֵינָהּ שֶׁלּוֹ וְלֹא הִזְדַּמְּנָה אֵלָיו, וּמִי הִיא? אוֹתָהּ שֶׁהָיְתָה מְזֻמֶּנֶת לְאַחֵר, וְהִקְדִּים זֶה בְּרַחֲמִים וְנָטַל אוֹתָהּ, זוֹ נִתְּנָה לוֹ, שֶׁלֹּא רְאוּיָה לוֹ."],[3,"","וְהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה מֵרָחוֹק וְרוֹאֶה אֶת אוֹתָהּ אִשָּׁה שֶׁעֲתִידָה לְהוֹצִיא תוֹלָדוֹת בָּעוֹלָם, מַקְדִּים זֶה בְּרַחֲמִים וְנִתֶּנֶת לוֹ, וְעוֹשֶׂה פֵרוֹת, וְזוֹרֵעַ זֶרַע בְּאִשָּׁה (בגן) שֶׁאֵינָהּ שֶׁלּוֹ, מִשּׁוּם כָּךְ הָאִשָּׁה וִילָדֶיהָ תִּהְיֶה לַאֲדנֶיהָ, וְהוּא יֵצֵא בְגַפּוֹ. אֵי עָנִי מִסְכֵּן, כַּמָּה הִשְׁתַּדֵּל בְּרֵיקָנוּת, הִתְיַגַּע וְנִשְׁתַּדֵּל לַעֲשׂוֹת פֵּרוֹת בְּגַן שֶׁאֵינוֹ שֶׁלּוֹ, וְיָצָא בְרֵיקָנוּת."],[4,"","זָקֵן זָקֵן, בַּזְּמַנִּים (בענינים) הַלָּלוּ לֹא הָיִית בְּרַגְלֶיךְ דּוֹחֶה אֶת הַשַּׁעַר, כְּמִי שֶׁשּׁוֹכֵב בָּאָרֶץ בְּלִי כֹּחַ, שֶׁהֲרֵי נֶחֱלַשׁ, וּמֵחֻלְשָׁה רַבָּה, שֶׁלֹּא יָכוֹל דּוֹחֶה בְרַגְלָיו. הִתְחַזֵּק זָקֵן וְאַל תְּפַחֵד. הֶעָנִי הַמִּסְכֵּן הַזֶּה שֶׁהִשְׁתַּדֵּל לָרִיק, אֱמֹר לָמָּה? אִם מִשּׁוּם שֶׁזָּרַע בְּגַן אַחֵר שֶׁאֵינוֹ שֶׁלּוֹ - יָפֶה. אִם כָּךְ (אבלכאן) הֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לוֹ אוֹתוֹ הַגָּן לִזְרֹעַ בּוֹ, שֶׁהֲרֵי לֹא הוּא שֶׁלָּקַח אוֹתָהּ."],[5,"","אֶלָּא בֹּא וּרְאֵה, כָּל הַדְּבָרִים שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, כֻּלָּם הֵם בְּדִין, וְלֹא הָיָה דָבָר לָרִיק. זֶה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לוֹ אִשָּׁה וְעָשָׂה בָּהּ פֵּרוֹת וְגִדּוּלִים, אֵין זֶה כִּשְׁאָר בְּנֵי הַגִּלְגּוּל, וְלֹא דוֹמֶה מִי שֶׁמִּשְׁתַּדֵּל בָּעוֹלָם הַזֶּה לְהַגְדִּיל אֶת הָאִילָן (ולא יכול), לְמִי שֶׁלֹּא רוֹצֶה לְהַגְדִּיל וּלְהִשְׁתַּדֵּל, וְעוֹקֵר וּמַפִּיל אֶת הֶעָלִים שֶׁל הָאִילָן וּמַקְטִין הַפְּרִי שֶׁלּוֹ."],[6,"","זֶה שֶׁאֲדוֹנָיו נָתַן לוֹ אִשָּׁה כְּדֵי לַעֲשׂוֹת פֵּרוֹת, הֲרֵי הִשְׁתַּדֵּל בַּהַתְחָלָה כְּדֵי לְהַגְדִּיל אֶת הָאִילָן וְלֹא יָכֹל. זְכֻיּוֹת כָּל כָּךְ אֵין לוֹ, (של בנים גם כן אין לו) שֶׁאִם הָיָה צַדִּיק כָּרָאוּי, לֹא הָיָה שָׁב בְּגִלְגּוּל (כאבן בכף הקלע), שֶׁהֲרֵי כָּתוּב (ישעיה נו) וְנָתַתִּי לָכֶם בְּבֵיתִי וּבְחֹמֹתַי יָד וָשֵׁם טוֹב מִבָּנִים וּמִבָּנוֹת. וְעַכְשָׁו שֶׁלֹּא זָכָה, הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה שֶׁהֲרֵי הִשְׁתַּדֵּל וְלֹא יָכֹל. זֶה אֲדוֹנָיו יִתֶּן לוֹ אִשָּׁה, כְּמוֹ שֶׁנֶּאֱמַר. וְכֵיוָן שֶׁחָס עָלָיו הַקָּדוֹשׁ בָּרוּךְ הוּא וְנָתַן לוֹ בְּרַחֲמִים, הַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹבֶה מִשֶּׁלּוֹ בַּתְּחִלָּה, וְנוֹטֵל מַה שֶּׁגָּרַע אוֹתוֹ הַמַּעְיָן. וּמִשּׁוּם כָּךְ, הָאִשָּׁה וִילָדֶיהָ תִּהְיֶה לַאדנֶיהָ, וְאַחַר כָּךְ יָשׁוּב וְיִשְׁתַּדֵּל עַל עַצְמוֹ לְהַשְׁלִים גִּרְעוֹנוֹ. עַד כָּאן סוֹד הַכָּתוּב."],[7,"","זָקֵן זָקֵן, אַתָּה אָמַרְתָּ עַל זֶה שֶׁלָּרִיק הִשְׁתַּדֵּל, וְלֹא הִשְׁגַּחְתָּ עָלֶיךְ שֶׁלָּרִיק אַתָּה הוֹלֵךְ בְּמַה שֶּׁאָמַרְתָּ, שֶׁהֲרֵי הַכָּתוּב רוֹדֵף אַחֲרֶיךְ, שֶׁסּוֹתֵר אֶת כָּל הַבִּנְיָן שֶׁבָּנִיתָ עַד עַכְשָׁו, וְאַתָּה חוֹשֵׁב שֶׁאַתָּה מֵשִׁיט אֶת הַיָּם לִרְצוֹנְךְ. וּמַהוּ? שֶׁכָּתוּב וְאִם אָמֹר יֹאמַר הָעֶבֶד אָהַבְתִּי אֶת אֲדנִי אֶת אִשְׁתִּי וְגוֹ'."],[8,"","אִי זָקֵן זָקֵן, עֲיֵף כֹּחַ, מַה תַּעֲשֶׂה? חָשַׁבְתָּ שֶׁלֹּא יִהְיֶה מִי שֶׁיִּרְדֹּף אַחֲרֶיךְ, הֲרֵי הַכָּתוּב הַזֶּה רוֹדֵף אַחֲרֶיךְ וְיוֹצֵא מֵאַחַר הַכֹּתֶל כְּאַיָּלָה בַּשָּׂדֶה, מְדַלֵּג דִּלּוּגִים אַחֲרֶיךְ, שְׁלֹשָׁה עָשָׂר דִּלּוּגִים דִּלֵּג אַחֲרֶיךְ וְהִשִּׂיג אוֹתְךְ. מַה תַּעֲשֶׂה, זָקֵן? עַכְשָׁו יֵשׁ לְךְ לְהִתְגַּבֵּר בְּכֹחֲךְ, שֶׁהֲרֵי גִּבּוֹר חָזָק הָיִיתָ עַד הַיּוֹם. זָקֵן זָקֵן, תִּהְיֶה זוֹכֵר אֶת יוֹם הַשֶּׁלֶג כְּשֶׁזָּרַעְנוּ פּוֹלִים, וְהָיוּ כַּמָּה גְבָרִים בְּנֵי חַיִל כְּנֶגְדְּךְ, וְאַתָּה לְבַדְּךְ נִצַּחְתָּ שְׁלֹשָׁה עָשָׂר גְּבָרִים חֲזָקִים בְּנֵי חַיִל, שֶׁכָּל אֶחָד מֵהֶם הוֹרֵג אַרְיֵה טֶרֶם שֶׁיֹּאכַל."]]],[["אִי לְאִינוּן תְּלֵיסַר גּוּבְרִין נָצַחְתְּ, הָנֵי תְּלֵיסָר דְּלֵית בְּהוּ חֵילָא, אֶלָּא מִלִּין, עַל אַחַת כַּמָּה וְכַמָּה. אָמֹר יֹאמַר כְּתִיב. אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא אָרְחֵיהּ לְמֶעְבַּד דִּינָא לְכֹלָּא. כַּד מָטָא זִמְנָא דְּהַאי אִתְּתָא לְאַשְׁכְּחָא בַּר זוּגֵיהּ מַה עָבִיד קָטִיל לְדֵין, וְנָטִיל לָהּ הַהוּא בַּר זוּגָא, וְאִיהוּ נָפִיק מֵהַאי עָלְמָא בִּלְחוֹדוֹי יְחִידָאָה.","וְאִם אָמֹר יֹאמַר, הָא אוּקְמוּהָ חַבְרַיָּיא כִּפְשָׁטֵיהּ דִּקְרָא. וְאִם אָמֹר, בְּשֵׁירוּתָא דְּשִׁית שְׁנִין, יאמַר, בְּסוֹפָא דְּשִׁית שְׁנִין, עַד לָא יֵעוּל שְׁבִיעָאָה, דְּהָא אִי אָמַר, כַּד אִיהוּ אֲפִילּוּ בְּיוֹמָא חַד מִשְּׁבִיעָאָה, מִלּוֹי בְּטֵלִין. מַאי טַעְמָא. הָעֶבֶד כְּתִיב, בְּעוֹד דְּאִיהוּ עֶבֶד, בְּשַׁתָּא שְׁתִיתָאָה. אָמַר בְּשֵׁירוּתָא דְּשִׁית שְׁנִין, וְלָא אָמַר בְּסוֹפָא דְּשִׁית שְׁנִין, לָאו כְּלוּם הוּא, וּבְגִין כַּךְ, תְּרֵי זִמְנִי אָמֹר יֹאמַר.","וְהָכָא, בְּעוֹד דְּאִיהוּ בְּהַאי אִתְּתָא, אַסְגֵּי (ויקרא רמ\"ד ע\"א) צְלוֹתִין וּבָעוּתִין בְּכָל יוֹמָא, לְגַבֵּי מַלְכָּא קַדִּישָׁא, כְּמָה דְּהֲוָה שֵׁירוּתָא בְּרַחֲמֵי, הָכִי הוּא סוֹפָא בְּרַחֲמֵי, וְדָא הוּא אָמֹר יֹאמַר. אֱמוֹר בְּקַדְמִיתָא, כַּד אַקְדִּים בְּרַחֲמֵי. יֹאמַר בְּסוֹפָא וְיִתְקַבֵּל בְּרַחֲמֵי. וּמַה יֹּאמַר. אָהַבְתִּי אֶת אֲדוֹנִי, דִּבְּגִין דָּא, וּבִסְגִּיאוּ דִּצְלוֹתִין, רָחִים לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. אַתְקִין עוֹבָדוֹי, וְאָמַר אָהַבְתִּי אֶת אֲדוֹנִי אֶת אִשְׁתִּי וְאֶת בָּנָי לֹא אֵצֵא חָפְשִׁי. וְקוּדְשָׁא בְּרִיךְ הוּא קַבִּיל לֵיהּ, בְּהַהוּא תִּיּוּבְתָּא, וּבְאִינּוּן סְגִּיאוּ דִּצְלוֹתִין.","מַה עָבִיד קוּדְשָׁא בְּרִיךְ הוּא, מַה דְּהֲוָה זַמִּין לְאָהַדְּרָא לֵיהּ בְּגִלְגּוּלָא, וּלְמִסְבַּל עוֹנָשִׁין בְּהַאי עָלְמָא, עַל מַה דְּעָבַד, לָא אַהְדָּר לֵיהּ לְהַאי עָלְמָא. וּמֶה עָבִיד, קָרִיב לֵיהּ לְבֵי דִּינָא דִּמְתִיבְתָּא דִּרְקִיעָא, וְדַיְינִין לֵיהּ, וּמַסְרִין לֵיהּ לְבֵי מַלְקִיּוּתָא, וְאַרְשִׁים לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, הֵיךְ אִתְמְסַר לְבֵי עוֹנְשָׁא, וּפָגִים לֵיהּ, לְמֶהֱוֵי תְּחוֹת שֻׁלְטָנֵיהּ דְּעָרְלָה, (נ\"א ופקיד ליה למהר תחות שולטנא דיובלא) עַד זְמַן יְדִיעָא, וּבָתַר פָּרִיק לֵיהּ.","אִי בְּהַהוּא זִמְנָא דְּקָא עַבְדִין לֵיהּ פְּגִימוּ, אִי מָטָא יוֹבְלָא, אֲפִילּוּ יוֹמָא חַד לְיוֹבְלָא, אִתְחֲשָׁב כְּמָה דְּאַשְׁכַּח זִמְנָא עַד יוֹבְלָא, הָכִי אִתְעַנָּשׁ וְלָא יַתִּיר. אָתָא יוֹבְלָא, וְאַפְרוּק, וְעָאלִין לֵיהּ גּוֹ פַּרְגּוֹדָא. עַד הָכָא. אַסְתִּים עֵינוֹי הַהוּא סָבָא, רִגְעָא חֲדָא.","פָּתַח וְאָמַר, (מיכה ו׳:ב׳) שִׁמְעוּ הָרִים אֶת רִיב יְיָ' וְהָאֵיתָנִים מוֹסְדֵי אָרֶץ כִּי רִיב לַיְיָ' עִם עַמּוֹ וְגוֹ'. אִי סָבָא, עַד הַשְׁתָּא הֲוֵית בְּעִמְקֵי יַמָּא, וְהַשְׁתָּא דָּלַגְתָּ בְּטוּרִין תַּקִּיפִין, לְמֶעְבַּד עִמְּהוֹן קְרָבָא. אֶלָּא וַדַּאי עַד כְּעָן, בְּיַמָּא תַּקִּיפָא אַנְתְּ, אֲבָל עַד דְּאַזְלַת בְּעִמְקֵי יַמָּא, פָּגַעְתְּ בְּאִינּוּן טוּרִין תַּקִּיפִין, דִּי בְּגוֹ יַמָּא, וְאִעֲרָעָת בְּהוּ. הַשְׁתָּא אִית לָךְ לְאַגָּחָא קְרָבָא בְּעִמְקֵי יַמָּא, וּבְהַנְהוּ טוּרִין.","סָבָא לָאֵי חֵילָא, מַאן יָהֲבָךְ בְּדָא, הֲוֵית בִּשְׁלָם, וּבָעִית לְכָל הַאי, אַנְתְּ עַבְדַת, אַנְתְּ סָבִיל. הַשְׁתָּא לֵית לָךְ, אֶלָּא לְאַגָּחָא קְרָבָא, וּלְנַצְּחָא כֹּלָּא, וְלָא לְמֶהֲדָר לַאֲחוֹרָא. אִתָּקַף בְּחֵילָךְ, חֲגוֹר חַרְצָךְ, וְלָא תִּדְחַל, לְתַבְרָא הָנֵי טוּרִין, דְּלָא יִתְתַּקְפוּן לְגַבָּךְ. אֵימָא לוֹן, טוּרִין רָמָאִין, טוּרִין תַּקִּיפִין, הֵיךְ אַתּוּן מִתְתַּקְפִין.","תְּרֵי קְרָאֵי כְּתִיבֵי, חַד כְּתִיב, (מיכה ו׳:א׳) קוּם רִיב אֶת הֶהָרִים וְתִשְׁמַעְנָה הַגְּבָעוֹת קוֹלֶךָ. וְחַד כְּתִיב, שִׁמְעוּ הָרִים אֶת רִיב יְיָ'. אֶלָּא אִית טוּרִין, וְאִית טוּרִין. אִית טוּרִין, דְּאִינּוּן טוּרִין (ג' ע\"א) רָמָאִין לְעֵילָּא לְעֵילָּא, לְאִלֵּין כְּתִיב, שִׁמְעוּ הָרִים אֶת רִיב יְיָ'. וְאִית הָרִים, דְּאִינּוּן טוּרִין תַּתָּאִין לְתַתָּא מִנַּיְיהוּ, לְאִלֵּין כְּתִיב, קוּם רִיב אֶת הֶהָרִים. דְּהָא רָדִיף מָצוּתִין, (תיקונין נ\"ג) אִית לְגַבַּיְיהוּ. וְעַל דָּא אִית טוּרִין וְאִית טוּרִין.","וְאִי תֵּימָא, סָבָא, הָא כְּתִיב וְתִשְׁמַעְנָה הַגְּבָעוֹת, אִלֵּין גִּבְעוֹת כָּל (ק\"ב ע\"ב, קכ\"ט ע\"ב) אִינּוּן דִּלְתַתָּא, וְהַשְׁתָּא אַנְתְּ עָבִיד לוֹן הָרִים. אֶלָּא הָכִי הוּא, לְגַבֵּי אִינּוּן טוּרִין רָמָאִין, אִקְרוּן גִּבְעוֹת. כַּד אִינּוּן בִּלְחוֹדַיְיהוּ אִינּוּן הָרִים אִקְרוּן."],[[0,"אי לאינון תליסר וכו':","אם לאלו י\"ג גבורים נצחת, אלו י\"ג מלות שבכתוב אם אמר יאמר, שאין בהם כח אלא רק מלות על אחת כמה וכמה. \u0003אמר יאמר\u0004 כתוב. כי הקב\"ה דרכו לעשות דין ומשפט לכל. כשהגיע הזמן של אשה ההיא שלקחה העבד, למצוא בן זוגה. מה עושה הקב\"ה, הורג את עבד הזה שלקחה ואינה בת זוגו, ולוקח אותה בן זוגה, והעבד יוצא מעולם הזה בגפו יחידי."],[1,"ואם אמר יאמר:","הרי העמידוהו החברים כפשוטו של המקרא, \u0003ואם אמר\u0004 בתחילת שש שנים, \u0003יאמר,\u0004 בסופם של שש שנים מטרם שנכנס שנה השביעית, כי אם אמר, כשהוא אפילו יום אחד בשנה השביעית, דבריו בטלים. מהו הטעם \u0003העבד\u0004 כתוב, כשיאמר בעוד שהוא עבד, בשנה הששית. אמר בתחילת שש שנים ולא אמר בסוף שש שנים, לא כלום הוא. ומשום זה כתוב ב' פעמים, אם אמר יאמר."],[2,"והכא בעוד דאיהו וכו':","וכאן, בעניננו בעוד שהעבד הוא עם אשה הזו. הוא מרבה תפלות ובקשות בכל יום למלך הקדוש, כמו שהיה תחלת לקיחתה ע\"י רחמים, (כנ\"ל באות רע\"ז) כך הוא הסוף ברחמים. וזה הוא \u0003אמר יאמר,\u0004 אמר, בתחילת, כשהקדים ברחמים. יאמר, בסוף, שיבקש שלא יהיה נדחה מפני בן זוגו, ויתקבל תפלתו ברחמים. ומה יאמר, אהבתי את אדני, שמשום זה, מחמת רוב התפלות, אוהב את הקב\"ה. מתקן את מעשיו, ואמר, אהבתי את אדני את אשתי ואת בני לא אצא חפשי. והקב\"ה מקבלו בתשובה ההיא, וברוב התפלות האלו."],[3,"מה עביד קב\"ה וכו':","מה עושה הקב\"ה, מה שהיה מוכן להחזירו בגלגול לסבול עונשים בעולם הזה על מה שעשה, אינו מחזירו לעולם הזה, ומה עושה, מקרב אותו לבית דין של המתיבתא דרקיע, ודנים אותו, ומוסרים אותו לבית ההכאות, ורושם אותו הקב\"ה, במרצע, איך נמסר לבית העונשין, ופוגם אותו, להיות תחת ממשלת הערלה עד זמן ידוע, ואח\"כ גואל אותו."],[4,"אי בההוא זמנא וכו':","אם בזמן ההוא, שעושים לו פגם, במרצע, הגיע היובל, ואפילו יום אחד ליובל, נחשב כמו שהיה נמצא כל הזמן עד יובל. כך נענש ולא יותר. בא היובל, ונגאל, ומכניסים אותו במחיצתו של הקב\"ה. עד כאן. סגר זקן ההוא את עיניו, רגע אחד."],[5,"פתח ואמר שמעו וגו':","פתח ואמר, שמעו הרים את ריב ה' והאיתנים מוסדי ארץ, וגו'. אמר לעצמו, אי זקן, עד עתה היית במעמקי הים ועתה דלגת בהרים חזקים לעשות עמהם מלחמה. אלא ודאי עד עתה, אתה היית בים החזק אבל מטרם שהלכת במעמקי הים, פגשת באלו הרים החזקים שבתוך הים, ונפגשת עמהם. עתה יש לך לעשות מלחמה במעמקי הים ובהרים האלו."],[6,"סבא לאי חילא וכו':","זקן עיף בלא כח, מי נתן אותך בזה, היית בשלום, ורצית בכל זה, אתה עשית זה, אתה תסבול. עתה אין לך אלא לעשות מלחמה, ולנצח הכל, ולא לחזור לאחור. התחזק בכחך אזור מתניך, ולא תפחד לשבר אלו ההרים, שלא יתקפו אותך. אמור להם, הרים הרמים, הרים החזקים, איך אתם מתחזקים."],[7,"תרי קראי כתיבי וכו':","ב' מקראות כתובים, אחד כתוב, קום ריב את ההרים ותשמענה הגבעות קולך. ואחד כתוב, שמעו הרים את ריב ה'. אלא יש הרים ויש הרים, יש הרים, שהם הרים רמים למעלה למעלה, שהם חג\"ת, לאלו כתוב, שמעו הרים את ריב ה'. ויש הרים שהם הרים תחתונים למטה מהם, שהם נה\"י, לאלו כתוב, קום ריב את ההרים. כי רודף מריבות יש אליהם. דהיינושיש בהם דינים. וע\"כ יש הרים ויש הרים."],[8,"ואי תימא סבא וכו':","ואם תאמר, זקן, הרי כתוב, ותשמענה הגבעות קולך. אלו הגבעות הם כל שלמטה, ואתה עושה אותם הרים. ומשיב, אלא כך הוא, כלפי אלו ההרים הרמים נקראים אלו גבעות, וכשהם בפני עצמם נקראים הרים."]],[[0,"","אִם אֶת אוֹתָם שְׁלֹשָׁה עָשָׂר גְּבָרִים נִצַּחְתָּ - אֵלֶּה שְׁלֹשָׁה עָשָׂר שֶׁאֵין בָּהֶם כֹּחַ, אֶלָּא דְבָרִים, עַל אַחַת כַּמָּה וְכַמָּה. כָּתוּב אָמֹר יֹאמַר. אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא דַּרְכּוֹ לַעֲשׂוֹת דִּין לַכֹּל. כְּשֶׁמַּגִּיעַ זְמַנָּהּ שֶׁל הָאִשָּׁה הַזּוֹ לִמְצֹא אֶת בֶּן זוּגָהּ, מָה עוֹשֶׂה? הוֹרֵג אֶת זֶה, וְנוֹטֵל אוֹתָהּ אוֹתוֹ בֶּן זוּגָהּ, וְהוּא יוֹצֵא מִן הָעוֹלָם הַזֶּה לְבַדּוֹ יְחִידִי."],[1,"","וְאִם אָמֹר יֹאמַר, הֲרֵי בֵּאֲרוּ הַחֲבֵרִים כִּפְשַׁט הַכָּתוּב. וְאִם אָמֹר - בְּרֵאשִׁית שֶׁל שֵׁשׁ הַשָּׁנִים. יֹאמַר - בְּסוֹף שֵׁשׁ הַשָּׁנִים טֶרֶם תִּכָּנֵס הַשְּׁבִיעִית. שֶׁהֲרֵי אִם אָמַר כְּשֶׁהוּא אֲפִלּוּ בְּיוֹם אֶחָד מֵהַשְּׁבִיעִית - דְּבָרָיו בְּטֵלִים. מָה הַטַּעַם? כָּתוּב הָעֶבֶד, בְּעוֹד שֶׁהוּא עֶבֶד, בַּשָּׁנָה הַשִּׁשִּׁית. אָמַר בְּרֵאשִׁית שֶׁל שֵׁשׁ הַשָּׁנִים וְלֹא אָמַר בְּסוֹף שֵׁשׁ הַשָּׁנִים - אֵינוֹ כְלוּם. וּמִשּׁוּם כָּךְ פַּעֲמַיִם אָמֹר יֹאמַר."],[2,"","וְכָאן בְּעוֹד שֶׁהוּא בָּאִשָּׁה הַזּוֹ, מַרְבֶּה תְפִלּוֹת וּבַקָּשׁוֹת בְּכָל יוֹם לַמֶּלֶךְ הַקָּדוֹשׁ. כְּמוֹ שֶׁהָיָה הָרֵאשִׁית בְּרַחֲמִים, כָּךְ הוּא הַסּוֹף בְּרַחֲמִים. וְזֶהוּ אָמֹר יֹאמַר. אָמֹר - בַּתְּחִלָּה, כְּשֶׁהִקְדִּים בְּרַחֲמִים. יֹאמַר - בַּסּוֹף, וְיִתְקַבֵּל בְּרַחֲמִים. וּמַה יֹּאמַר? אָהַבְתִּי אֶת אֲדנִי. שֶׁבִּגְלַל זֶה וּבְרֹב הַתְּפִלּוֹת אוֹהֵב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. מְתַקֵּן מַעֲשָׂיו, וְאוֹמֵר אָהַבְתִּי אֶת אֲדֹנִי אֶת אִשְׁתִּי וְאֶת בָּנָי לֹא אֵצֵא חָפְשִׁי. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְקַבֵּל אוֹתוֹ בְּאוֹתָהּ תְּשׁוּבָה וּבְאוֹתָן הַתְּפִלּוֹת הָרַבּוֹת."],[3,"","מָה עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? מַה שֶּׁהָיָה מְזֻמָּן לְהַחֲזִירוֹ בְגִלְגּוּל וְלִסְבֹּל עֳנָשִׁים בָּעוֹלָם הַזֶּה עַל מַה שֶּׁעָשָׂה - לֹא מַחֲזִירוֹ לָעוֹלָם הַזֶּה. וּמָה עוֹשֶׂה? מְקָרֵב אוֹתוֹ לְבֵית דִּין שֶׁל יְשִׁיבַת הָרָקִיעַ, וְדָנִים אוֹתוֹ וּמוֹסְרִים אוֹתוֹ לְבֵית הַמַּלְקוּת, וְרוֹשֵׁם אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא אֵיךְ נִמְסָר לְבֵית הָעֹנֶשׁ, וּפוֹגֵם אוֹתוֹ לִהְיוֹת תַּחַת שִׁלְטוֹן הָעָרְלָה (ומצוה אותו להיות תחת שלטון היובל) עַד זְמַן יָדוּעַ, וְאַחַר כָּךְ גּוֹאֵל אוֹתוֹ."],[4,"","אִם בְּאוֹתוֹ זְמַן שֶׁעוֹשִׂים לוֹ פְּגָם, אִם הִגִּיעַ יוֹבֵל, אֲפִלּוּ יוֹם אֶחָד לַיּוֹבֵל - נֶחְשָׁב כְּמִי שֶׁמָּצָא זְמַן עַד הַיּוֹבֵל. כָּךְ נֶעֱנָשׁ וְלֹא יוֹתֵר. בָּא הַיּוֹבֵּל וְנִגְאָל, וּמַכְנִיסִים אוֹתוֹ לְתוֹךְ הַפַּרְגּוֹד. עַד כָּאן. הִסְתִּיר אוֹתוֹ זָקֵן אֶת עֵינָיו רֶגַע אֶחָד."],[5,"","פָּתַח וְאָמַר, (מיכה ו) שִׁמְעוּ הָרִים אֶת רִיב ה' וְהָאֵתָנִים מֹסְדֵי אָרֶץ כִּי רִיב לַה' עִם עַמּוֹ וְגוֹ'. אֵי זָקֵן, עַד כָּאן הָיִיתָ בְּעִמְקֵי הַיָּם, וְעַכְשָׁו דִּלַּגְתָּ עַל הָרִים חֲזָקִים לַעֲשׂוֹת עִמָּהֶם קְרָב?! אֶלָּא וַדַּאי עַד עַכְשָׁו אַתָּה בַּיָּם הֶחָזָק, אֲבָל עַד שֶׁהָלַכְתָּ לְעִמְקֵי הַיָּם, פָּגַשְׁתָּ אֶת אוֹתָם הָרִים חֲזָקִים שֶׁבְּתוֹךְ הַיָּם וְנִתְקַלְתָּ בָּהֶם. עַכְשָׁו יֵשׁ לְךְ לַעֲרֹךְ קְרָב בְּעִמְקֵי הַיָּם וּבֶהָרִים הַלָּלוּ."],[6,"","זָקֵן עֲיֵף כֹּחַ, מִי נְתָנְךְ בָּזֶה? הָיִיתָ בְּשָׁלוֹם, וְרָצִיתָ אֶת כָּל זֶה?! אַתָּה עָשִׂיתָ - אַתָּה סוֹבֵל. עַכְשָׁו אֵין לְךְ אֶלָּא לַעֲרֹךְ קְרָב וּלְנַצֵּחַ אֶת הַכֹּל וְלֹא לַחֲזֹר לְאָחוֹר. הִתְחַזֵּק בְּכֹחֲךְ, חֲגֹר מָתְנֶיךְ וְאַל תִּפְחַד לִשְׁבֹּר אֶת הֶהָרִים הַלָּלוּ שֶׁלֹּא יִתְחַזְּקוּ עָלֶיךְ. אֱמֹר לָהֶם: הָרִים רָמִים, הָרִים חֲזָקִים, אֵיךְ אַתֶּם מִתְגַּבְּרִים?"],[7,"","שְׁנֵי פְסוּקִים כְּתוּבִים. אֶחָד כָּתוּב, (שם) קוּם רִיב אֶת הֶהָרִים וְתִשְׁמַעְנָה הַגְּבָעוֹת קוֹלֶךְ, וְאֶחָד כָּתוּב, שִׁמְעוּ הָרִים אֶת רִיב ה'. אֶלָּא יֵשׁ הָרִים וְיֵשׁ הָרִים. יֵשׁ הָרִים שֶׁהֵם הָרִים רָמִים לְמַעְלָה לְמַעְלָה, לְאֵלֶּה כָּתוּב שִׁמְעוּ הָרִים אֶת רִיב ה'. וְיֵשׁ הָרִים שֶׁהֵם הָרִים תַּחְתּוֹנִים לְמַטָּה מֵהֶם, וּלְאֵלֶּה כָּתוּב קוּם רִיב אֶת הֶהָרִים, שֶׁהֲרֵי רוֹדֵף מְרִיבוֹת יֵשׁ לָהֶם. וְלָכֵן יֵשׁ הָרִים וְיֵשׁ הָרִים."],[8,"","וְאִם תֹּאמַר, זָקֵן, הֲרֵי כָּתוּב וְתִשְׁמַעְנָה הַגְּבָעוֹת, אֵלֶּה גְבָעוֹת כָּל אוֹתָם שֶׁלְּמַטָּה, וְעַכְשָׁו אַתָּה עוֹשֶׂה אוֹתָם הָרִים? אֶלָּא כָּךְ הוּא - לְאוֹתָם הָרִים רָמִים נִקְרָאִים גְּבָעוֹת. כְּשֶׁהֵם לְבַדָּם הֵם נִקְרָאִים הָרִים."]]],[["תָּא חֲזִי, כְּתִיב וְהָאֵיתָנִים מוֹסְדֵי אָרֶץ, כֵּיוָן דִּכְתִּיב שִׁמְעוּ הָרִים, מַאן אִינּוּן הָרִים, וּמַאן אִינּוּן אֵיתָנִים. אֶלָּא, הָרִים וְאֵיתָנִים כֻּלְּהוּ חַד. אֲבָל אִינּוּן תְּלַת עִלָּאִין לְעֵילָּא עַל רֵישַׁיְיהוּ. וְאִינּוּן תְּלַת לְתַתָּא מִנַּיְיהוּ. וְכֻלְּהוּ חַד. הָרִים לְעֵילָּא, וְעָלַיְיהוּ אָמַר דָּוִד (תהילים קכ״א:א׳) אֶשָּׂא עֵינִי אֶל הֶהָרִים. וְאִלֵּין אִינּוּן תְּלַת קַדְמָאֵי. וְהָאֵיתָנִים מוֹסְדֵי אָרֶץ, אִלֵּין אִינּוּן תְּלַת בַּתְרָאֵי, לְתַתָּא מִנַּיְיהוּ, תְּרֵי סַמְכֵי בֵּיתָא, וְחַד חֶדְוָה דְּבֵיתָא, וְאִלֵּין אִקְרוּן מוֹסְדֵי אָרֶץ. אֵיתָנִים אִינּוּן, וְאֵיתָנִים אִקְרוּן.","סָבָא סָבָא, הָא יָדַעְתְּ, מַאן דְּאַגָּח קְרָבָא, אִי לָא יָדַע לְאִסְתַּמְּרָא, לָא יִנְצַח קְרָבִין, אִצְטְרִיךְ לְמָחָאָה בִּידֵיהּ, וּלְאִסְתַּמְּרָא בְּרַעְיוֹנֵיהּ, מַה דִּיהֵא חָשִׁיב אַחֲרָא, דִּיהֵא חָשִׁיב אִיהוּ, וְיַד יְמִינָא זְמִינָא תָּדִיר לְמָחָאָה. וּמַחֲשָׁבוֹי וִידָא שְׂמָאלִית, זְמִינָא תָּדִיר לְקַבְּלָא וּלְאִסְתַּמְּרָא, וִימִינָא כֹּלָּא.","הַשְׁתָּא אָמַרְתְּ וְהָאֵיתָנִים, אֵיתָנִים אִינּוּן לְתַתָּא, וְהָרִים לְעֵילָּא. אִסְתָּמַּר סָבָא, דְּהָא רַעְיוֹנָא אַחֲרָא לָקֳבְלָךְ, דִּכְתִּיב, (תהילים פ״ט:א׳) מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי. וְדָא אִיהוּ אַבְרָהָם סָבָא, וְאִקְרֵי אֵיתָן, וְאִי אַבְרָהָם אִיהוּ אֵיתָן, יִצְחָק וְיַעֲקֹב אֵיתָנִים אִקְרוּן. קוּם סָבָא, דְּהָא יַדָעְתְּ רַעְיוֹנָא דָּא הֲוֵי מָחֵי לְרַעְיוֹנָךְ.","(במדבר כ״ד:כ״א) וְיִשָּׂא מְשָׁלוֹ וַיֹּאמַר אֵיתָן מוֹשָׁבֶךָ וְשִׂים בַּסֶּלַע קִנֶּךָ. אֵיתָן: דָּא (קי\"ט ע\"ב, בלק י\"ד ע\"א) בֹּקֶר דְּאַבְרָהָם. וְהַיְינוּ, (בראשית מה) הַבֹּקֶר אוֹר. דָּא עַמּוּדָא, דְּכָל עָלְמָא קַיְּימָא עָלֵיהּ, וּנְהִירוּ דִּילֵיהּ מֵאַבְרָהָם יָרִית. נָהָר הַיּוֹצֵא מֵעֵדֶן אִקְרֵי. אִי סָבָא סָבָא, הָא רַעְיוֹנָא אַחֲרָא לָקֳבְלָךְ, וְלָא יָדַעְתְּ לְאִסְתַּמְּרָא, הֵיכִי מַגִּיחִין קְרָבָא. סָבָא, אָן הוּא תּוּקְפָּא דִּילָךְ, וַדַּאי (קהלת ט׳:י״א) לא לַגִּבּוֹרִים הַמִּלְחָמָה.","כְּתִיב מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי, וּכְתִיב מַשְׂכִּיל לְדָוִד, דָּא נָהָר הַיּוֹצֵא מֵעֵדֶן, דְּאִיהוּ תּוּרְגְמָן לְדָוִד, לְאוֹדָעָא לֵיהּ, מֵאִינּוּן מִלִּין סְתִימִין עִלָּאִין. אִי מַשְׂכִּיל אִיהוּ נָהָר דְּנָפִיק מֵעֵדֶן. אֵיתָן הָאֶזְרָחִי אַבְרָהָם, אִיהוּ לְעֵילָּא וַדַּאי, הָא יְדַעְנָא. וְאַף עַל גַּב דַּאֲנָא סָבָא, עַל רַעְיוֹנָא דָּא מָחֵינָא. אֵיתָן הָאֶזְרָחִי, תְּרִין דַּרְגִּין אִינּוּן. כְּמָה דְאַתְּ אָמֵר, בֹּקֶר אוֹר. אוֹר, הוּא אַבְרָהָם. (ויקרא ו' ע\"א, כ\"ב ע\"ב) בֹּקֶר הוּא נָהָר. אוּף הָכִי, אֵיתָן הָאֶזְרָחִי, אֶזְרָח, הוּא אַבְרָהָם. אֵיתָן, כְּמָה דְּאִתְּמַר, דָּא הַהוּא נָהָר דְּנָגֵיד וְנָפִיק מֵעֵדֶן.","הַשְׁתָּא סָבָא, קוּם קָאִים עַל רְתִיכָךְ, דְּהַשְׁתָּא תִּנְפּוֹל וְלָא תִּיכוּל לְמֵיקָם. הָא שְׁלֹמֹה מַלְכָּא, אָתֵי בְּחֵילוֹי וּרְתִיכוֹי וְגַבְרוֹי וּפָרָשׁוֹי, וְאָתֵי לָקֳבְלָךְ, קוּם פּוּק מִן חַקְלָא, דְּלָא יִשְׁכַּח לָךְ תַּמָּן. כְּתִיב (מלכים א ח׳:ב׳) וַיִּקָּהֲלוּ אֶל הַמֶּלֶךְ שְׁלֹמֹה כָּל אִישׁ יִשְׂרָאֵל בְּיֶרַח הָאֵיתָנִים בֶּחָג וְגוֹ'. יֶרַח דְּאִתְיְלִידוּ בֵּיהּ הָאֵיתָנִים, וּמַאן אִינּוּן. אֲבָהָן, וְאִינּוּן אֵיתָנֵי עוֹלָם. וַיָּרַח דָּא, אִיהוּ תִּשְׁרֵי. דְּאַלְפָא בֵּיתָא אַהְדָּר לְמַפְרֵעַ מִתַּתָּא לְעֵילָּא.","וְתוּ מִמִּילָּךְ, יֵאוֹת דְּתִפּוֹק מִן חַקְלָא, וְלָא תִּשְׁתְּכַח תַּמָּן. אִילוּ כְּתִיב מַשְׂכִּיל אֵיתָן הָאֶזְרָחִי כִּדְקָאָמַרְתְּ. הַשְׁתָּא דִּכְתִּיב מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי. לֵית קְרָבָךְ כְּלוּם, וְתִפּוֹק מִן חַקְלָא, בְּעַל כָּרְחָךְ וְלָא תִּתְחָזֵי תַּמָּן.","אִי סָבָא עַנְיָא מִסְכְּנָא, הֵיכִי תֵּפּוֹק. אִי הָכִי, יִנְצְחוּן לָךְ וְתַּעֲרוֹק מִן חַקְלָא, כָּל בְּנֵי עָלְמָא יִרְדְּפוּן אֲבַתְרָךְ, וְלֵית לָךְ אַנְפִּין לְאִתְחֲזָאָה קָמֵי בַּר נָשׁ לְעָלְמִין. הָכָא אוֹמֵינָא, דְּלָא אִפּוֹק מִן חַקְלָא, וְהָכָא אִתְחָזֵי אַנְפִּין בְּאַנְפִּין בִּשְׁלֹמֹה מַלְכָּא, וְכָל אִישׁ יִשְׂרָאֵל, וְגוּבְרִין וּפָרָשִׁין וּרְתִיכִין דִּילֵיהּ. קוּדְשָׁא בְּרִיךְ הוּא יְסַיֵּיעַ לָךְ סָבָא, דְּהָא לָאֵי חֵילָא אַנְתְּ. קוּם סָבָא אִתְגַּבָּר בְּחֵילָךְ וְאִתְתָּקַּף, דְּעַד יוֹמָא דָּא הֲוֵית גִּיבָּר תַּקִּיף בְּגוּבְרִין.","פָּתַח וְאָמַר, מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי. אֵלּוּ כְּתִיב מַשְׂכִּיל לְדָוִד, כִּדְקָאָמַרְתְּ, אֲבָל מַשְׂכִּיל לְאֵיתָן, אִית מַשְׂכִּיל וְאִית מַשְׂכִּיל. אִית מַשְׂכִּיל לְעֵילָּא, וְאִית מַשְׂכִּיל (בראשית ט\"ז ע\"ב) לְתַתָּא. מַשְׂכִּיל לְאֵיתָן בְּזִמְנָא דְּהַהוּא נָהָר, קָם בְּתִאוּבְתָּא כָּל שַׁיְיפִן חֲדָאן וּמִתְחַבְּרָן לְגַבֵּיהּ, וְאִי הוּא סָלִיק, עַד דְּמוֹחָא עִלָּאָה אִתְפָּיַּיס לְגַבֵּיהּ, וְחַדֵּי לָקֳבְלֵיהּ. וּכְדֵין מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי, מַשְׂכִּיל לֵיהּ, וְאוֹדַע לֵיהּ עַל יְדָא דְּאַבְרָהָם (ס\"א על ידוי דאברהם) רְחִימוֹי, כָּל מַה דְּאִצְטְרִיךְ, וְהַהוּא מוֹחָא עִלָּאָה מַשְׂכִּיל לְאֵיתָן. וְכַד דָּוִד מַלְכָּא, אִתְתָּקַּן בְּתִיאוּבְתָּא לְגַבֵּיהּ, אִיהוּ מַשְׂכִּיל לְדָוִד. כְּמָה דְּהֲוָה מוֹחָא עִלָּאָה, מַשְׂכִּיל לֵיהּ. וְעַל דָּא, אִית מַשְׂכִּיל, וְאִית מַשְׂכִּיל. (אית משכיל)."],[[0,"תא חזי כתיב וכו':","בוא וראה, כתוב, והאיתנים מוסדי ארץ. שואל, כיון שכתוב שמעו הרים, ומי הם אלו איתנים. ומשיב, אלא הרים ואיתנים כולם אחד, אבל הרים הם שלשה עליונים למעלה על ראשם של האיתנים, שהם חג\"ת. ואיתנים הם שלשה למטה מהם, שהם נה\"י. וכולם אחד. הרים למעלה, ועליהם אמר דוד אשא עיני אל ההרים, ואלו הם שלשה ראשונים, חג\"ת, והאיתנים מוסדי ארץ, אלו הם שלשה אחרונים שלמטה מהם, שהם, שני סומכים של הבית, דהיינו נצח והוד, ואחד חדות הבית, שהוא יסוד, ואלו נקראים מוסדי ארץ, איתנים הם, דהיינו חזקים, ואיתנים נקראים."],[1,"סבא סבא הא וכו':","אמר לעצמו, זקן זקן, הרי ידעת, מי שעושה מלחמה אם אינו יודע להשמר, לא ינצח מלחמות, צריך להכות בידו, ולהשמר במחשבתו, אשר מה שיחשוב האחר, יחשוב הוא, וישמור עצמו, ויד ימין נועדת תמיד להכות, ומחשבותיו ויד השמאלית, נועדות לקבל ולהשמר, המחשבות להשמר, ויד שמאלית מקבלת ההכאות מן האחר. והימין הוא לכל דבר."],[2,"השתא אמרת והאיתנים וגו':","עתה אמרת, והאיתנים וגו'. איתנים הם למטה, נה\"י. והרים למעלה, חג\"ת. השמר זקן, כי מחשבה אחרת כנגדך, שכתוב, משכיל לאיתן האזרחי. וזה הוא אברהם סבא, שנקרא איתן. ואם אברהם הוא איתן, יצחק ויעקב גם כן איתנים נקראים, והאבות הם חג\"ת, הרי שחג\"ת נקראים איתנים. קום זקן, כי ידעת שרעיון זה מכה לרעיונך."],[3,"וישא משלו ויאמר איתן וגו':","איתן, זה בקר של אברהם, והיינו הבקר אור, שזהו העמוד, דהיינו יסוד, שכל העולם, שהוא מלכות, עומד עליו. והאור שלו יורש מאברהם, שהוא חסד. נהר היוצא מעדן נקרא, שהוא יסוד, הרי שיסוד נקרא איתן. אמר לעצמו. אי זקן זקן, הרי רעיון אחד כנגדך, ואינך יודע להשמר, איך עושים מלחמה. זקן, איפה הוא גבורתך, ודאי לא לגבורים המלחמה."],[4,"כתיב משכיל לאיתן האזרחי","וכתוב, משכיל לדוד. זהו נהר היוצא מעדן, שהוא יסוד, שהוא המבאר אל דוד, שהוא מלכות, להודיעו מאלו דברים הסתומים העליונים. וע\"כ נקרא היסוד משכיל. ואם משכיל, הוא נהר היוצא מעדן, דהיינו יסוד שהוא למטה, בנה\"י, איתן האזרחי, יהיה אברהם, שאני יודע שהוא ודאי למעלה, בחג\"ת, ואע\"פ שאני זקן על רעיון הזה אני מכה. אלא \u0003איתן האזרחי\u0004 שתי מדרגות הן, כמש\"א בקר אור, \u0003אור,\u0004 הוא אברהם שהוא חסד, \u0003בקר,\u0004 הוא נהר, שהוא יסוד. אף כאן איתן האזרחי, \u0003אזרח\u0004 הוא אברהם, \u0003איתן\u0004 הוא כמו שאמרנו, שזה נהר ההוא הנמשך ויוצא מעדן. שהוא יסוד."],[5,"השתא סבא קום וכו':","עתה זקן קום עמוד על מרכבתך, כי עתה תפול ולא תוכל לקום. הרי שלמה המלך בא בצבאותיו, ומרכבותיו וגבוריו ופרשיו, ובאים לקראתך. קום צא מן השדה, שלא ימצאו אותך שם. כתוב, ויקהלו אל המלך שלמה כל איש ישראל בירח האיתנים בחג וגו'. היינו, ירח שנולדו בו האיתנים ומי הם. הם האבות שהם איתני עולם. וירח זה הוא תשרי, שהאלף בית חזר בו למפרע ממטה למעלה, דהיינו בסדר תשר\"ק צפע\"ס וכו'. כי סדר אותיות תשרי הן למפרע, הרי שהאיתנים הם האבות, שהם חג\"ת."],[6,"ותו ממילך יאות וכו':","ועוד, מדבריך עצמך, שאמר, איתן האזרחי הם ב' מדרגות, יפה לך שתצא מן השדה ולא תמצא שם. כי אלו היה כתוב, משכיל איתן האזרחי, היה טוב כמו שאמרת, שהן ב' מדרגות, עתה שכתוב משכיל לאיתן האזרחי, אין מלחמתך שוה כלום, כי משמע שהן מדרגה אחת, ולא שתים. ותצא מן השדה בהכרח, ולא תתראה שם."],[7,"אי סבא עניא וכו':","אי זקן עני ומסכן, איך תצא מן השדה, אם כן, שינצחו אותך ותברח מן השדה, כל בני העולם ירדפו אחריך, ולא יהיה לך פנים להראות לאדם לעולם. כאן נשבע אני שלא אצא מן השדה, וכאן אראה פנים בפנים עם שלמה המלך וכל איש ישראל, והגבורים והפרשים והמרכבות שלו. הקב\"ה יעזור לך זקן, כי עיף בלא כח אתה. קום זקן התגבר בכחך והתחזק, כי עד יום הזה, היית גבור אמיץ בגבורים."],[8,"פתח ואמר משכיל וכו':","פתח ואמר, משכיל לאיתן האזרחי, אלו כתוב, משכיל לדוד, היה הפירוש כמו שאמרת, שהוא יסוד המשפיע למלכות הנקרא דוד, אבל כתוב, משכיל לאיתן. ומשיב, יש משכיל ויש משכיל, יש משכיל למעלה ויש משכיל למטה. משכיל לאיתן, כי בזמן שנהר ההוא, שהוא יסוד, קם בהשתוקקות, כל האברים שמחים ומתחברים עמו. ואם הוא עולה עד שמוח העליון, שהוא חסד שנעשה לחכמה, מתרצה לו ושמח לקראתו, אז משכיל לאיתן האזרחי, שמשכיל את היסוד ומודיע לו, על ידי אברהם אוהבו שהוא חסד שעלה ונעשה חכמה, כל מה שצריך, ומוח העליון ההוא, שהוא חכמה, הוא משכיל לאיתן, שהוא יסוד. וכאשר דוד המלך, שהוא מלכות, מתתקן בהשתוקקות אל היסוד, היסוד משכיל לדוד, כמו מוח העליון משכיל ליסוד. ועל כן, יש משכיל ויש משכיל."]],[[0,"","בֹּא וּרְאֵה, כָּתוּב וְהָאֵתָנִים מֹסְדֵי אָרֶץ. כֵּיוָן שֶׁכָּתוּב שִׁמְעוּ הָרִים, מִי הֵם הָרִים וּמִי הֵם אֵתָנִים? אֶלָּא הָרִים וְאֵתָנִים הַכֹּל דָּבָר אֶחָד. אֲבָל אוֹתָם שְׁלֹשָׁה עֶלְיוֹנִים מֵעַל רָאשֵׁיהֶם, וְאוֹתָם שְׁלֹשָׁה לְמַטָּה מֵהֶם, וְכֻלָּם אֶחָד. הָרִים לְמַעְלָה, וַעֲלֵיהֶם אָמַר דָּוִד, (תהליםקכא) אֶשָּׂא עֵינַי אֶל הֶהָרִים. וְאֵלֶּה הֵם שְׁלֹשָׁה הָרִאשׁוֹנִים. וְהָאֵתָנִים מֹסְדֵי אָרֶץ, אֵלֶּה הֵם שְׁלֹשָׁה אַחֲרוֹנִים, לְמַטָּה מֵהֶם, שְׁנֵי עַמּוּדֵי הַבַּיִת וְאֶחָד שִׂמְחַת הַבַּיִת, וְאֵלֶּה נִקְרְאוּ מֹסְדֵי אָרֶץ. אֵתָנִים הֵם, וְאֵתָנִים נִקְרְאוּ."],[1,"","זָקֵן זָקֵן, הֲרֵי יָדַעְתָּ, מִי שֶׁעוֹרֵךְ קְרָב, אִם לֹא יוֹדֵעַ לְהִשָּׁמֵר, לֹא יְנַצַּח בַּקְּרָבוֹת. צָרִיךְ לְהַכּוֹת בְּיָדוֹ וּלְהִשָּׁמֵר בְּרַעְיוֹנוֹ, מַה שֶּׁיִּהְיֶה אַחֵר חָשׁוּב, שֶׁיִּהְיֶה הוּא חָשׁוּב, וְיַד יָמִין מְזֻמֶּנֶת תָּמִיד לְהַכּוֹת. וּמַחְשְׁבוֹתָיו וְיָד שְׂמָאלִית זְמִינִים תָּמִיד לְקַבֵּל וּלְהִשָּׁמֵר, וְיָמִין הַכֹּל."],[2,"","עֵכְשָׁו אָמַרְתָּ וְהָאֵתָנִים. אֵיתָנִים הֵם לְמַטָּה, וְהָרִים לְמַעְלָה. הִשָּׁמֵר זָקֵן, שֶׁהֲרֵי רַעְיוֹן אַחֵר כְּנֶגְדְּךְ, שֶׁכָּתוּב (שם פט) מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי. וְזֶהוּ אַבְרָהָם הַזָּקֵן, וְנִקְרָא אֵיתָן. וְאִם אַבְרָהָם הוּא אֵיתָן, יִצְחָק וְיַעֲקֹב נִקְרְאוּ אֵיתָנִים. קוּם זָקֵן, שֶׁהֲרֵי יָדַעְתָּ רַעְיוֹן זֶה הָיָה מַכֶּה אֶת רַעְיוֹנְךְ."],[3,"","וַיִּשָּׂא מְשָׁלוֹ וַיֹּאמַר אֵיתָן מוֹשָׁבֶךְ וְשִׂים בַּסֶּלַע קִנֶּךְ (במדבר כד). אֵיתָן - זֶה בּקֶר שֶׁל אַבְרָהָם, וְהַיְנוּ (בראשית מד) הַבֹּקֶר אוֹר. זֶה הָעַמּוּד שֶׁכָּל הָעוֹלָם עוֹמֵד עָלָיו, וְאֶת אוֹרוֹ יָרַשׁ מֵאַבְרָהָם. נִקְרָא נָהָר הַיּוֹצֵא מֵעֵדֶן. אִי זָקֵן זָקֵן, הִנֵּה רַעְיוֹן אַחֵר כְּנֶגְדְּךְ, וְלֹא יָדַעְתָּ לְהִשָּׁמֵר אֵיךְ עוֹרְכִים קְרָב. זָקֵן, אֵיפֹה הַכֹּחַ שֶׁלְּךְ? וַדַּאי לֹא לַגִּבּוֹרִים הַמִּלְחָמָה."],[4,"","כָּתוּב מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי, וְכָתוּב מַשְׂכִּיל לְדָוִד. זֶה נָהָר הַיּוֹצֵא מֵעֵדֶן, שֶׁהוּא תֻּרְגְּמָן לְדָוִד לְהוֹדִיעַ לוֹ מֵאוֹתָם דְּבָרִים הַנִּסְתָּרִים הָעֶלְיוֹנִים. אִם מַשְׂכִּיל הוּא נָהָר שֶׁיּוֹצֵא מֵעֵדֶן, אָז אֵיתָן הָאֶזְרָחִי אַבְרָהָם הוּא לְמַעְלָה וַדַּאי. זֶה יָדַעְתִּי. וְאַף עַל גַּב שֶׁאֲנִי זָקֵן, עַל רַעְיוֹן זֶה אֲנִי מוֹחֶה. אֵיתָן הָאֶזְרָחִי הֵם שְׁתֵּי דְרָגוֹת, כְּמוֹ שֶׁנֶּאֱמַר בֹּקֶר אוֹר. אוֹר זֶה אַבְרָהָם. בֹּקֶר זֶה נָהָר. אַף כָּךְ אֵיתָן הָאֶזְרָחִי. אֶזְרָח הוּא אַבְרָהָם."],[5,"","אֵיתָן, כְּמוֹ שֶׁנֶּאֱמַר, זֶה אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן. עֵכְשָׁו, זָקֵן, קוּם עֲמֹד עַל מֶרְכַּבְתְּךְ, שֶׁעַכְשָׁו תִּפֹּל וְלֹא תוּכַל לָקוּם. הֲרֵי שְׁלֹמֹה הַמֶּלֶךְ בָּא בְּכֹחוֹתָיו וּמַרְכְּבוֹתָיו וּגְבָרָיו וּפָרָשָׁיו וּבָא כְּנֶגְדְּךְ. קוּם צֵא מִן הַשָּׂדֶה, שֶׁלֹּא יִמְצָא אוֹתְךְ שָׁם. כָּתוּב (מלכים אח) וַיִּקָּהֲלוּ אֶל הַמֶּלֶךְ שְׁלֹמֹה כָּל אִישׁ יִשְׂרָאֵל בְּיֶרַח הָאֵתָנִים בֶּחָג וְגוֹ'. יֶרַח שֶׁנּוֹלְדוּ בוֹ הָאֵיתָנִים, וּמִי הֵם? הָאָבוֹת, וְהֵם אֵיתָנֵי הָעוֹלָם, וְיֶרַח זֶה הוּא תִּשְׁרֵי. שֶׁאַלְפָא בֵּיתָא חוֹזֵר לְמַפְרֵעַ מִמַּטָּה לְמַעְלָה."],[6,"","וְעוֹד מִדְּבָרֶיךְ, נָאֶה שֶׁתֵּצֵא מִן הַשָּׂדֶה וְלֹא תִמָּצֵא שָׁם. אִלּוּ כָּתוּב מַשְׂכִּיל אֵיתָן הָאֶזְרָחִי - אָז כְּמוֹ שֶׁאָמַרְתָּ. אֲבָל עַכְשָׁו שֶׁכָּתוּב מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי, הַקְּרָב שֶׁלְּךְ אֵינוֹ כְלוּם, וְתֵצֵא מִן הַשָּׂדֶה בְּעַל כָּרְחֲךְ וְלֹא תִתְרָאֶה שָׁם."],[7,"","אֵי זָקֵן, עָנִי מִסְכֵּן, אֵיךְ תֵּצֵא? אִם כָּךְ, יְנַצְּחוּ אוֹתְךְ וְתִבְרַח מִן הַשָּׂדֶה, כָּל בְּנֵי הָעוֹלָם יִרְדְּפוּ אַחֲרֶיךְ, וְאֵין לְךְ פָּנִים לְהֵרָאוֹת לִפְנֵי אִישׁ לְעוֹלָמִים. כָּאן נִשְׁבָּע אֲנִי שֶׁלֹּא אֵצֵא מֵהַשָּׂדֶה, וְכָאן אֶרָאֶה פָּנִים בְּפָנִים בִּשְׁלמֹה הַמֶּלֶךְ, וְכָל אִישׁ יִשְׂרָאֵל, וְהַגְּבָרִים וְהַפָּרָשִׁים וְהַמֶּרְכָּבוֹת שֶׁלּוֹ. הַקָּדוֹשׁ בָּרוּךְ הוּא יְסַיַּע לְךְ, זָקֵן, שֶׁהֲרֵי אַתָּה עֲיֵף כֹּחַ. קוּם זָקֵן, הִתְגַּבֵּר בְּכֹחֲךְ וְהִתְחַזֵּק, שֶׁעַד הַיּוֹם הַזֶּה הָיִיתָ גִּבּוֹר חָזָק בַּגְּבָרִים."],[8,"","פָּתַח וְאָמַר, מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי. אִלּוּ כָּתוּב מַשְׂכִּיל לְדָוִד - אָז כְּמוֹ שֶׁאָמַרְתָּ, אֲבָל מַשְׂכִּיל לְאֵיתָן כָּתוּב. יֵשׁ מַשְׂכִּיל וְיֵשׁ מַשְׂכִּיל. יֵשׁ מַשְׂכִּיל לְמַעְלָה וְיֵשׁ מַשְׂכִּיל לְמַטָּה. מַשְׂכִּיל לְאֵיתָן, בִּזְמַן שֶׁאוֹתוֹ אִישׁ (נהר) עוֹמֵד בִּתְשׁוּקָה, כָּל הָאֵיבָרִים שְׂמֵחִים וּמִתְחַבְּרִים עִמּוֹ. וְאִם הוּא עוֹלֶה, עַד שֶׁהַמֹּחַ הָעֶלְיוֹן מִתְפַּיֵּס אֵלָיו וְשָׂמֵחַ כְּנֶגְדּוֹ. וְאָז מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי, מַשְׂכִּיל אוֹתוֹ וּמוֹדִיעַ לוֹ עַל יְדֵי אַבְרָהָם (על ידיו של אברהם) אוֹהֲבוֹ כָּל מַה שֶּׁצָּרִיךְ, וְאוֹתוֹ מֹחַ עֶלְיוֹן מַשְׂכִּיל לְאֵיתָן. וּכְשֶׁדָּוִד הַמֶּלֶךְ נִתְקָן בִּתְשׁוּקָה אֵלָיו, הוּא מַשְׂכִּיל לְדָוִד, כְּמוֹ שֶׁהָיָה הַמֹּחַ הָעֶלְיוֹן מַשְׂכִּיל אוֹתוֹ. וְלָכֵן יֵשׁ מַשְׂכִּיל וְיֵשׁ מַשְׂכִּיל. (יש משכיל)."]]],[["בְּיֶרַח הָאֵיתָנִים, דְּאִתְיְלִידוּ בְּהָא יֶרַח אֵיתָנִים, בִּנְיָנָא לְתַתָּא אִיהוּ כְּגַוְונָא דִּלְעֵילָּא, וְאִתְיְלִידוּ בֵּיהּ הָרִים וְאֵיתָנִים. הָרִים סְתִימִין. אֵיתָנִים: יַרְכִין תַּקִּיפִין כִּנְחָשָׁא, וְהַהוּא אֵיתָן בֵּינַיְיהוּ.","קוּם סָבָא, הֲוֵי מָחֵי לְכָל סִטְרִין, בְּשַׁעֲתָא דְּסָלִיק מֹשֶׁה לְקַבְּלָא אוֹרַיְיתָא, מָסַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא שִׁבְעִין מַפְתְּחָן דְּאוֹרַיְיתָא. כַּד מָטָא לְתִשְׁעָה (ושיתין) וְחַמְשִׁין, הֲוָה חַד מַפְתְחָא גָּנִיז וְסָתִים, דְּלָא הֲוָה מָסַר לֵיהּ, אִתְחַנָּן לְקָמֵיהּ. אָמַר לֵיהּ, מֹשֶׁה, כָּל מַפְתְּחָן עִלָּאִין וְתַתָּאִין בְּהַאי מַפְתְחָא תַּלְיָין. אָמַר לְקַמֵּיהּ, מָארֵיהּ דְּעָלְמָא, מַה שְׁמֵיהּ. אָמַר לֵיהּ אֵיתָן. וְכָל אִינּוּן אֵיתָנִים בֵּיהּ תַּלְיָין, וּבֵיהּ קַיְימָן לְבַר מִגּוּפָא דְּתוֹרָה שֶׁבִּכְתָב אִיהוּ. אוֹדַע לֵיהּ, וּמַשְׂכִּיל לֵיהּ, אִיהוּ עִקָרָא וּמַפְתְּחָא דְּתוֹרָה שֶׁבִּכְתָב.","וְכַד אִתְתַּקְנַת תּוֹרָה שֶׁבְּעַל פֶּה לְגַבֵּיהּ, עִיקָרָא דְּהֵיכָלָא הוּא מַפְתְחָא (בראשית ל\"ז ע\"ב) דִּילָהּ, (לגביה) וַדַּאי כְּדֵין מַשְׂכִּיל לְדָוִד. וּמִגּוֹ (קי\"ח ע\"ב) דְּיָרְתָא תּוֹרָה שֶׁבְּעַל פֶּה, (לגביה) אַתְוָון לְמַפְרֵעַ. עַל דָּא אִקְרֵי תִּשְׁרֵ\"י תש\"ר אִיהוּ, אֲבָל בְּגִין דְּאִיהוּ רָזָא דִּשְׁמָא קַדִּישָׁא חָתִים בֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, אָת דִּשְׁמֵיהּ י'. בַּמִּזְבֵּחַ, חָתִים בֵּיהּ ה', הָרְשֶׁת עַד חֲצִי הַמִּזְבֵּחַ. אָתַת דְּבוֹרָה, וְחָתִים בֵּיהּ ו', וְהַיְינוּ דִּכְתִּיב, (שופטים ה׳:א׳) וַתָּשַׁר דְּבוֹרָה. וּבַאֲתַר דָּא, חָתִימוּ דִּשְׁמָא קַדִּישָׁא, דְּאַחְתִּים בֵּיהּ.","וְהַהוּא מַפְתְחָא, כַּד פַּתְחָא בַּתּוֹרָה שֶׁבְּעַל פֶּה, בָּעֵינָן לְאִשְׁתְּמוֹדְעָא לֵיהּ, וְדָא אִיהוּ (מ\"ז ע\"ב) תַּנְיָא, אֵיתָן מוֹשָׁבֶךָ, בָּרַיְיתָא לְבַר מִגּוּפָא. אֵיתָנִים: אִינּוּן תַּנָּאִים. עַמּוּדִים סַמְכִין, לְבַר מִגּוּפָא. הַשְׁתָּא אִית לְאוֹדָעָא מִלָּה, בְּזִמְנָא דְּאִלֵּין לְגַבֵּי תּוֹרָה שֶׁבִּכְתָב, אִקְרוּן אֵיתָנִים. לְגַבֵּי תּוֹרָה שֶׁבְּעַל פֶּה, אִקְרוּן תַּנָּאִים. אֵיתָן, לְגַבֵּי תּוֹרָה שֶׁבִּכְתָב. תַּנְיָא, לְגַבֵּי תּוֹרָה שֶׁבְּעַל פֶּה. וְכֹלָּא כַּדְקָא יֵאוֹת.","חַבְרַיָּיא, הָא אֲנָא בְּחַקְלָא. שְׁלֹמֹה מַלְכָּא, וְגוּבְרִין תַּקִּיפִין דִּילֵיהּ. יְיתֵי וְיִשְׁכַּח חַד סָבָא, לָאֵי בְּחֵילָא, תַּקִּיף גִּיבָּר, נָצַח קְרָבִין. הָא יְדַעְנָא דְּאָתָא, וְקַיְּימָא לְבָתַר טִינְרָא דְּחַקְלָא, וְהוּא אַשְׁגַּח בִּי, וְהֵיךְ גְּבוּרְתִי קַיְּימָא בְּחַקְלָא, בִּלְחוֹדוֹי אַשְׁגַּח, דְּאִיהוּ אִישׁ שָׁלוֹם, מָארֵיהּ דִּשְׁלָמָא, וְאָזַל לֵיהּ. הַשְׁתָּא סָבָא, גְּבוּרְתָּךְ עֲלָךְ, וְאַנְתְּ בִּלְחוֹדָךְ בְּחַקְלָא, תּוּב לְאֲתְרָךְ. וְשָׁארִי זִינָךְ מֵעֲלָךְ.","(ד\"א כמאן דנפיק מן חקלא) (מיכה ו׳:ב׳) שִׁמְעוּ הָרִים אֶת רִיב יְיָ' וְהָאֵתָנִים מוֹסְדֵי אָרֶץ. שִׁמְעוּ הָרִים כִּדְקַאמְרָן. וְהָאֵיתָנִים מוֹסְדֵי אָרֶץ, מוֹסְדֵי אָרֶץ וַדַּאי, דְּהָא מִנַּיְיהוּ אִתְּזָן, וּמִנַּיְיהוּ קַבִּיל כָּל יוֹמָא, וְאִינּוּן מוֹסְדֵי אָרֶץ.","(מיכה ו׳:ב׳) כִּי רִיב לַה' עִם עַמּוֹ, מַאן הוּא דְּיָכִיל לְמֵיקָם בְּרִיב דְּקוּדְשָׁא בְּרִיךְ הוּא (כל שכן) בְּיִשְׂרָאֵל. וְעַל דָּא אָמַר לְאִלֵּין, שִׁמְעוּ הָרִים אֶת רִיב ה', דָּא אִיהוּ מָצוּתָא חֲדָא. קוּם רִיב אֶת הֶהָרִים, מָצוּתָא תִּנְיָינָא. דְּנָצַח בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא, כָּל אִלֵּין רִיבוֹת לְיִשְׂרָאֵל, וְכָל אִינּוּן תּוֹכָחוֹת, כֻּלְּהוּ כְּאַבָּא דְּאוֹכַח לִבְרִיהּ, וְהָא אוּקְמוּהָ.","בְּיַעֲקֹב כְּתִיב, בְּשַׁעֲתָא דְּבָעָא לְנַצְּחָא בַּהֲדֵיהּ, מַה כְּתִיב, (הושע י״ב:ג׳) וְרִיב לַיְיָ' עִם יְהוּדָה וְלִפְקוֹד עַל יַעֲקֹב. מָה רִיב אִיהוּ, כְּמָה דִּכְתִּיב, (הושע י״ב:ד׳) בַּבֶּטֶן עָקַב אֶת אָחִיו. עַל הַאי מִלָּה אָתָא תּוֹכָחָה, וְכָל אִינּוּן רִיבוֹת. וְכִי לָאו מִלָּה רַבְרְבָא אִיהוּ, בַּבֶּטֶן עָקַב אֶת אָחִיו וְגוֹ'. הַאי לָאו מִלָּה זְעִירָא אִיהוּ, מַאי דְּעָבִיד בַּבֶּטֶן. וְכִי עוּקְבָא עָבִיד בַּבֶּטֶן, אִין וַדַּאי.","ס\"א (נ\"א והא אתמר) (אבל) בְּכֹלָּא, דָּחָה יַעֲקֹב לְעֵשָׂו אֲחוּי, בְּגִין דְּלָא יְהֵא לֵיהּ חוּלָקָא כְּלַל. עֵשָׂו לָא הִתְרַעַם אֶלָּא מֵחָד דְּאִינּוּן תְּרֵין, דִּכְתִּיב, (בראשית כ״ז:ל״ו) וַיַּעְקְבֵנִי זֶה פַעֲמַיִם. פַעֲמַיִם מִבָּעֵי לֵיהּ, מַאי זֶה. אֶלָּא, חַד דְּאָקִישׁ לִתְרֵין. חַד דְּנָפַק לִתְרֵין. וּמַאי נִיהוּ. בְּכֹרָתִי אִתְהַפְּכוּ אַתְוָון, וַהֲוָה בִּרְכָּתִי. זֶה פַעֲמַיִם: חַד, דְּאִתְּקַשׁ לִתְרִין."],[[0,"בירח האיתנים:","שנולדו בירח הזה, איתנים, כי הבנין שלמטה, נה\"י, הוא כעין שלמעלה, חג\"ת, וע\"כ נולדו בו הרים ואיתנים, \u0003ההרים,\u0004 שהם חג\"ת, סתומים, שהחכמה נסתמה בהם ואינה מאירה. \u0003איתנים,\u0004 הם ירכין, נו\"ה, חזקים כנחושת, ואיתן ההוא ביניהם, שהוא יסוד, המשפיע הארת החכמה."],[1,"קום סבא הוי וכו':","קום זקן, הכה לכל הצדדים. בשעה שעלה משה לקבל התורה, מסר לו הקב\"ה ע' מפתחות התורה, שהן ז\"ס חג\"ת נהי\"מ, שבכל אחת עשר ספירות, והן ע'. כשהגיע לחמשים ותשעה, שהוא יסוד שבע\"ס דיסוד, היה מפתח אחד גנוז וסתום, שהוא מלכות דע\"ס שביסוד, שנקרא עטרת יסוד, שלא היה מסר לו, התחנן לפניו, אמר לו, משה, כל מפתחות עליונים ותחתונים תלוים במפתח הזה. כי העטרה ה\"ס המסך דצמצום ב', שבו נתקנו כל פרצופי ו\"ק שבה' פרצופין דאצילות, והוא המפתח של כל המוחין, (כמ\"ש בהקדמת ס' הזהר, ד' מ\"ה, ד\"ה ההוא גליפי, ע\"ש כל ההמשך) אמר לפניו רבון העולם, מה שמו, אמר לו איתן, וכל האיתנים תלוים בו, כי נה\"י שמחזה ולמטה הנקראים איתנים, הם פרצוף ו\"ק של הגוף. וחג\"ת שמחזה ולמעלה הם ג\"ר של הגוף. וע\"כ שולט בהם המפתחא, שהוא עטרת יסוד, (כמ\"ש שם בהקסה\"ז דף מ\"ד ד\"ה וטעם ע\"ש) ובו מתקיימים, נה\"י, שהם מחוץ לגוף של תורה שבכתב, שהוא ז\"א, כי מחזה ולמטה נבחן, שהוא מחוץ לגוף שהוא חג\"ת. הוא, ז\"א, מודיע אותו, היינו השפעת הדעת, ומשכיל אותו. והוא, עטרת יסוד, הוא העיקר, והמפתח של תורה שבכתב. שהוא ז\"א. כי לולא המסך הזה דעטרת יסוד, שה\"ס צמצום ב', לא היה ז\"א ראוי לקבל הג\"ר. (כמ\"ש בבראשית א דף ז' ד\"ה וכבר, ע\"ש)."],[2,"וכד אתתקנת תורה וכו':","וכשמתתקנת אליו תורה שבעל פה, שהיא המלכות, הוא, עטרת יסוד, נעשה למפתח שלה, דהיינו ליסוד המלכות. ודאי אז נקרא היסוד משכיל לדוד. שהיא המלכות. ומשום שיורש אותו תורה שבעל פה, שהיא המלכות ונעשה ליסוד שלה הנקרא \u0003רש\"ת\u0004 (כנ\"ל ב\"ב דף קס\"ב ד\"ה אינון) המאירה ממטה למעלה, וע\"כ, בה, האותיות למפרע. וע\"כ נקרא אז היסוד שלה, בשם \u0003תשרי,\u0004 שהאותיות הן למפרע, בדרך השר\"ק. \u0003תש\"ר\u0004 הוא, אבל משום שהוא סוד השם הקדוש, דהיינו מלכות, חתם בו הקב\"ה אות משמו, שהוא \u0003י'.\u0004 ונקראת משום זה \u0003תשרי.\u0004 במזבח, שהוא ג\"כ שם המלכות, חתם בו ביסוד שלה, ה' דהויה דהיינו \u0003ה'\u0004 של \u0003הרשת\u0004 עד חצי המזבח. באה דבורה, שהיא ג\"כ שם המלכות, חתם בה \u0003ו',\u0004 והיינו שכתוב, \u0003ו\u0004 תשר דבורה. ובמקום הזה, שהוא יסוד המלכות, החותם שלהשם הקדוש שחתם בו."],[2,"","פירוש. כי האותיות רש\"ת הם שם יסוד המלכות. וז\"א חתם שמו שהוא יה\"ו באותיות רש\"ת אלו, בג' מקומות, כאן בתשר\"י \u0003י'.\u0004 וברש\"ת המזבח \u0003ה'.\u0004 ובותשר דבורה \u0003ו'.\u0004"],[3,"וההוא מפתחא כד וכו':","ומפתח ההוא, שהוא עטרת יסוד, כשפותח בתורה שבעל פה, דהיינו שנתקן ליסוד שלה כנ\"ל, צריכים לדעת אותו. וזהו שאנו אומרים \u0003תניא,\u0004 שהוא אותיות איתן, ואז נאמר איתן מושבך, כי המלכות נקראת \u0003מושב,\u0004 וכשמקבלת מעטרת יסוד נאמר בה, איתן מושבך. ונקראת \u0003ברייתא,\u0004 שפירושו לחוץ מן הגוף, שהוא ז\"א. כי ברייתא הוא מלשון לבר, שהוא חיצוניות. \u0003איתנים\u0004 שבתורה שבכתב שהוא ז\"א, הם \u0003תנאים\u0004 בתורה שבעל פה, שהוא המלכות. שהם עמודים סומכים לחוץ מן הגוף, דהיינו נה\"י, כנ\"ל. עתה יש להודיע הדברים, בזמן שאלו נה\"י נקראים אצל תורה שבכתב, שהוא ז\"א, איתנים, אצל תורה שבעל פה, נקראים תנאים. כי \u0003איתן\u0004 הוא אצל תורה שבכתב, \u0003תניא\u0004 אצל תורה שבעל פה. והכל כראוי."],[4,"חברייא הא אנא וכו':","חברים, הרי אני בשדה, שלמה המלך והגבורים האמיצים שלו, יבא וימצא זקן אחד עיף בלא כח, שהוא חזק, גבור, מנצח מלחמות, אני יודע שיבא, ועומד אחורי הסלע שבשדה, והוא מסתכל בי, איך גבורתי נמצאת בשדה, בלבדו מסתכל בי, הוא איש השלום בעל השלום, והולך לו עתה זקן, גבורתך עליך, ואתה בלבדך בשדה, חזור למקומך, והתר כלי זין שלך מעליך."],[5,"שמעו הרים את ריב ה' ואיתנים וגו':","שמעו הרים, פירושו כמו שאמרנו. והאיתנים מוסדי ארץ, מוסדי ארץ ודאי. שהיא המלכות הנקראת ארץ, כי מהם, מן האיתנים שהם נה\"י, נזונת המלכות. ומהם מקבלת שפעה כל יום, וע\"כ הם מוסדי ארץ."],[6,"כי ריב לה' עם עמו:","מי הוא שיכול לעמוד בריב של הקב\"ה בישראל. ועל זה אמר לאלו, שמעו הרים את ריב ה'. זה הוא ריב אחד. קום ריב את ההרים, הוא ריב השני. שנצח בהם הקב\"ה כל אלו ריבות עם ישראל וכל אלו תוכחות, כולם הם, כאב המוכיח את בנו. וכבר העמדנוהו."],[7,"ביעקב כתיב בשעתא וכו':","ביעקב כתוב, בשעה שבא לנצח אותו. מה כתוב, וריב לה' עם יהודה ולפקוד על יעקב. מה הוא הריב. הוא כמו שכתוב, בבטן עקב את אחיו וגו'. על דבר זה באה התוכחה וכל אלו המריבות. וכי אין זה דבר גדול, בבטן עקב את אחיו וגו'. זה אינו דבר קטן מה שעשה בבטן. שואל, וכי רמאות עשה בבטן. ומשיב, כן ודאי."],[8,"והא אתמר, בכלא דחה וכו':","וכן למדנו, בכל, דחה יעקב את עשו, כדי שלא יהיה לו שום חלק בקדושה. עשו לא התרעם אלא מאחד שהם שנים, שכתוב, ויעקבני זה פעמים, ויעקבני פעמים היה צריך לומר, מהו, זה. ומשיב אלא הוא רומז, על אחד השוה לשנים אחד שיצא לשנים. ומה הוא, הוא \u0003בכרתי\u0004 שנתהפכו האותיות והיה \u0003ברכתי.\u0004 זה פעמים, פירושו, אחד שנשתוה לשנים."]],[[0,"","בְּיֶרַח הָאֵתָנִים, שֶׁנּוֹלְדוּ הָאֵיתָנִים בַּיֶּרַח הַזֶּה. הַבִּנְיָן לְמַטָּה הוּא כְּמוֹ שֶׁלְּמַעְלָה, וְנוֹלְדוּ בוֹ הָרִים וְאֵיתָנִים. הָרִים נִסְתָּרִים. אֵתָנִים - יְרֵכַיִם חֲזָקוֹת כִּנְחֹשֶׁת, וְאוֹתוֹ הָאֵיתָן בֵּינֵיהֶם."],[1,"","קוּם זָקֵן, תַּכֶּה לְכָל הַצְּדָדִים. בְּשָׁעָה שֶׁעָלָה מֹשֶׁה לְקַבֵּל תּוֹרָה, מָסַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא שִׁבְעִים מַפְתְּחוֹת שֶׁל הַתּוֹרָה. כְּשֶׁהִגִּיעַ לַחֲמִשִּׁים (לששים) וְתִשְׁעָה, הָיָה מַפְתֵּחַ אֶחָד גָּנוּז וְנִסְתָּר, שֶׁלֹּא הָיָה מוֹסֵר לוֹ. הִתְחַנֵּן לְפָנָיו. אָמַר לוֹ: מֹשֶׁה, כָּל הַמַּפְתְּחוֹת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים תְּלוּיִים בַּמַּפְתֵּחַ הַזֶּה. אָמַר לְפָנָיו: רִבּוֹן הָעוֹלָם, מַה שְּׁמוֹ? אָמַר לוֹ: אֵיתָן. וְכָל אוֹתָם אֵיתָנִים תְּלוּיִים בּוֹ, וּבוֹ עוֹמְדִים מִחוּץ לַגּוּף, שֶׁתּוֹרָה שֶׁבִּכְתָב הוּא, מוֹדִיעַ לוֹ וּמַשְׂכִּיל אוֹתוֹ, הוּא עִקָּר וְהַמַּפְתֵּחַ שֶׁל תּוֹרָה שֶׁבִּכְתָב."],[2,"","וּכְשֶׁנִּתְקְנָה תוֹרָה שֶׁבְּעַל פֶּה אֵלָיו, עִקַּר הַהֵיכָל הוּא הַמַּפְתֵּחַ שֶׁלָּהּ (אליו), וַדַּאי שֶׁאָז מַשְׂכִּיל לְדָוִד. וּמִתּוֹךְ שֶׁיָּרְשָׁה תוֹרָה שֶׁבְּעַל פֶּה (אליו) אוֹתִיּוֹת לְמַפְרֵעַ. וְעַל זֶה הוּא נִקְרָא תִשְׁרֵ\"י, הוּא תש\"ר, אֲבָל מִשּׁוּם שֶׁהוּא סוֹד הַשֵּׁם הַקָּדוֹשׁ, חָתוּם בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹת שֶׁל שְׁמוֹ י'. בַּמִּזְבֵּחַ חָתוּם בּוֹ ה', הָרֶשֶׁת עַד חֲצִי הַמִּזְבֵּחַ. בָּאָה דְבוֹרָה וְחָתְמָה בּוֹ ו', וְהַיְנוּ מַה שֶּׁכָּתוּב (שופטים ה) וַתָּשַׁר דְּבוֹרָה. וּבַמָּקוֹם הַזֶּה הַחוֹתָם שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁחָתַם בּוֹ."],[3,"","וְאוֹתוֹ הַמַּפְתֵּחַ, כְּשֶׁפּוֹתֵחַ בַּתּוֹרָה שֶׁבְּעַל פֶּה, צְרִיכִים לְהִוָּדַע לוֹ, וְזֶהוּ תַּנְיָא, אֵיתָן מוֹשָׁבֶךְ, בָּרַיְתָא מִחוּץ לַגּוּף. אֵיתָנִים הֵם תַּנָּאִים, עַמּוּדִים תּוֹמְכִים מִחוּץ לַגּוּף. עַכְשָׁו יֵשׁ לְהוֹדִיעַ דָּבָר, בִּזְמַן שֶׁאֵלֶּה לַתּוֹרָה שֶׁבִּכְתָב נִקְרָאִים אֵיתָנִים - לַתּוֹרָה שֶׁבְּעַל פֶּה נִקְרָאִים תַּנָּאִים. אֵיתָן אֶל הַתּוֹרָה שֶׁבִּכְתָב. תַּנְיָא אֶל הַתּוֹרָה שֶׁבְּעַל פֶּה, וְהַכֹּל כָּרָאוּי."],[4,"","חֲבֵרִים, הֲרֵינִי בַּשָּׂדֶה. שְׁלֹמֹה הַמֶּלֶךְ וְהַגִּבּוֹרִים הַחֲזָקִים שֶׁלּוֹ יָבֹא וְיִמְצָא זָקֵן אֶחָד עָיֵף בְּכֹחוֹ, חָזָק גִּבּוֹר, מְנַצֵּחַ קְרָבוֹת. הֲרֵינִי יוֹדֵעַ שֶׁיָּבא, וְעוֹמֵד אַחַר סֶלַע הַשָּׂדֶה וְהוּא מַשְׁגִּיחַ בִּי וְאֵיךְ גְּבוּרָתִי עוֹמֶדֶת בַּשָּׂדֶה, לְבַדּוֹ מַשְׁגִּיחַ, שֶׁהוּא אִישׁ שָׁלוֹם, בַּעַל הַשָּׁלוֹם, וְהוֹלֵךְ לוֹ. עַכְשָׁו, זָקֵן, גְּבוּרָתְךְ עָלֶיךְ, וְאַתָּה לְבַד בַּשָּׂדֶה, שׁוּב לִמְקוֹמְךְ וְהַתֵּר כְּלִי זֵינְךְ מֵעָלֶיךְ."],[5,"","(כמי שיוצא מן השדה). שִׁמְעוּ הָרִים אֶת רִיב ה' וְהָאֵתָנִים מֹסְדֵי אָרֶץ (מיכה ו). שִׁמְעוּ הָרִים, כְּמוֹ שֶׁאָמַרְנוּ. וְהָאֵתָנִים מֹסְדֵי אָרֶץ, מֹסְדֵי אָרֶץ וַדַּאי, שֶׁהֲרֵי מִמֶּנּוּ נִזּוֹנֵית, וּמֵהֶם מְקַבֶּלֶת כָּל יוֹם, וְהֵם מֹסְדֵי אָרֶץ."],[6,"","כִּי רִיב לַה' עִם עַמּוֹ. מִי הוּא זֶה שֶׁיָּכוֹל לָקוּם בְּרִיב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא (כָּל שֶׁכֵּן) בְּיִשְׂרָאֵל? וְעַל זֶה אָמַר לְאֵלֶּה, שִׁמְעוּ הָרִים אֶת רִיב ה' - זֶהוּ רִיב אֶחָד. קוּם רִיב אֶת הֶהָרִים - זֶה רִיב שֵׁנִי. שֶׁמְּנַצֵּחַ בָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא כָּל הָרִיבוֹת הַלָּלוּ לְיִשְׂרָאֵל, וְכָל אוֹתָם תּוֹכָחוֹת, כֻּלָּם כְּאָב הַמּוֹכִיחַ אֶת בְּנוֹ, וַהֲרֵי פֵּרְשׁוּהָ."],[7,"","בְּיַעָקֹב כָּתוּב בְּשָׁעָה שֶׁרָצָה לְנַצֵּחַ עִמּוֹ, מַה כָּתוּב? (הושעיב) וְרִיב לַה' עִם יְהוּדָה וְלִפְקֹד עַל יַעֲקֹב. מַהוּ הָרִיב? כַּכָּתוּב, בַּבֶּטֶן עָקַב אֶת אָחִיו. עַל דָּבָר זֶה בָּאָה תוֹכָחָה, וְכָל אוֹתָם רִיבוֹת. וְכִי לֹא דָבָר גָּדוֹל הוּא, בַּבֶּטֶן עָקַב אֶת אָחִיו וְגוֹ'? זֶה אֵינוֹ דָבָר קָטָן מַה שֶּׁעָשָׂה בַּבֶּטֶן. וְכִי רַמָּאוּת עָשָׂה בַּבֶּטֶן? כֵּן, וַדַּאי."],[8,"","ס\"א (והרי נאמר) (אבל) שֶׁבַּכֹּל דָּחָה יַעֲקֹב אֶת עֵשָׂו אָחִיו, כְּדֵי שֶׁלֹּא יִהְיֶה לוֹ חֵלֶק כְּלָל. עֵשָׂו לֹא הִתְרַעֵם אֶלָּא מֵאֶחָד שֶׁהֵם שְׁנַיִם, שֶׁכָּתוּב (בראשית כז) וַיַּעְקְבֵנִי זֶה פַעֲמַיִם. פַּעֲמַיִם הָיָה צָרִיךְ (לכתב), מַה זֶּה \"זֶה\"? אֶלָּא אֶחָד שֶׁהִקִּישׁ לִשְׁנַיִם, אֶחָד שֶׁיָּצָא לִשְׁנַיִם, וּמַהוּ? בְּכֹרָתִי. שֶׁהִתְהַפְּכוּ הָאוֹתִיּוֹת וְנִהְיֶה בִּרְכָתִי. זֶה פַעֲמַיִם - אֶחָד שֶׁהֻקַּשׁ לִשְׁנַיִם."]]],[["וְלָא יָדַע עֵשָׂו מַה דְּעָבַד לֵיהּ בַּבֶּטֶן, אֲבָל רַב מְמָנָא דִּילֵיהּ יָדַע הֲוָה, וְקוּדְשָׁא בְּרִיךְ הוּא אַרְגִּישׁ שְׁמַיָּא וחֵיילַיְיהוּ לְקָלָא דָּא, דְּהָא בְּרָכָה וּבְכוֹרָה לָא תָּבַע מְמָנָא דִּילֵיהּ, וְלָא אָמַר. דְּהָא בְּרָכָה הֲוָה לֵיהּ לְמִתְבַּע, וְלָא תָּבַע. אָחוּהָ הָא תָּבַע ודַּאי, דִּכְתִּיב, (ישעיהו נ״ח:ז׳) וּמִבְּשָׂרְךָ לֹא תִתְעַלָּם וְלָא בָּעָא יַעֲקֹב לְמֵיהָב לֵיהּ לְמֵיכַל, עַד דְּנָטַל מִנֵּיה בְּכוֹרָתָא דִּילֵיהּ.","מָאי בְּכוֹרָה נָטַל מִנֵּיהּ, הַבְּכוֹרָה דִּלְעֵילָּא וְתַתָּא. בְּכֹרָה חָסֵר ו'. כְּדֵין עָקַב אֶת אָחִיו, ודַּאי דְּעָבַד לֵיהּ עוּקְבָא, וְאַרְמֵי לֵיהּ לַאֲחוֹרָא. מַאי אֲחוֹרָא. אַקְדִּים לֵיהּ, דְּיִפּוּק בְּקַדְמִיתָא לְהַאי עָלְמָא. אָמַר יַעֲקֹב לְעֵשָׂו, טוֹל אַתָּה הַאי עָלְמָא בְּקַדְמִיתָא, ואֲנָא לְבָתַר.","תָּא חֲזֵי, מַה כְּתִיב, (בראשית כ״ה:כ״ו) וְאַחֲרֵי כֵן יָצָּא אָחִיו וְיָדוֹ אֹחֶזֶת בַּעֲקֵב עֵשָׂו. מַאי בַּעֲקֵב עֵשָׂו. וְכִי סַלְּקָא דַּעְתָּךְ דְּהֲוָה אָחִיד יְדֵיהּ בְּרַגְלֵיהּ, לָאו הָכִי. אֶלָּא, יָדוֹ אֹחֶזֶת בְּמַאן דְּהַהוּא דְּהֲוָה עָקֵב, וּמַנּוֹ עֵשָׂו. דְּהָא עֵשָׂו עָקֵב אִקְרֵי, מִשַׁעֲתָא דְּעֲקַב לֵיהּ לְאָחוּי, וּמִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא עָקֵב קָרֵי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (בראשית ג׳:ט״ו) הוּא יְשׁוּפְךָ רֹאשׁ וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב. אַנְתְּ דְּאִקְרֵי עָקֵב, תְּשׁוּפֶנּוּ בְּקַדְמִיתָא. וּלְבַסּוֹף הוּא דְּיִמְחֵי רֵישָׁךְ מֵעָלָךְ. וּמַנּוֹ. סָמָאֵ\"ל. דְּאִיהוּ רֵישָׁא דְּחִויָא, דְּמָחֵי בְּהַאי עָלְמָא.","וְעַל דָּא בַּבֶּטֶן עָקַב אֶת אָחִיו, שָׁוִי עָלֵיהּ לְמֶהֱוִי עָקֵב, וְנָטַל עֵשָׂו הַאי עָלְמָא בְּקַדְמִיתָא, ודָא רָזָא דִּכְתִּיב, (בראשית ל״ו:ל״א) וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל. ודָא אִיהוּ רָזָא דְּאָמַר שְׁלֹמֹה מַלְכָּא, (משלי כ׳:כ״א) נַחֲלָה מְבוֹהֶלֶת בָּרִאשׁוֹנָה וְאַחֲרִיתָהּ לֹא תְבוֹרָךְ, בְּסוֹף עָלְמָא.","וְעַל דָּא (הושע י״ב:ד׳) בַּבֶּטֶן עָקַב אֶת אָחִיו וּבְאוֹנוֹ שָׂרָה אֶת אֱלהִים. מַאי וְאוֹנוֹ. הָכִי אָמְרוּ בְּחֵילָא וְתּוּקְפָּא דִּילֵיהּ יֵאוֹת, אֲבָל לָאו הָכִי. בְּרִירוּ דְּמִלָּה, יַעֲקֹב דִּיּוּקְנָא עִלָּאָה הֲוָה, וְגוּפָא קַדִּישָׁא. דְּלֵית גּוּפָא מִיּוֹמָא דְּהֲוָה אָדָם הָרִאשׁוֹן, כְּגוּפָא דְּיַעֲקֹב, וְשׁוּפְרֵיהּ דְּאָדָם הָרִאשׁוֹן, הַהוּא שׁוּפְרֵיהּ מַמָּשׁ הֲוָה לֵיהּ לְיַעֲקֹב. וְדִיּוּקְנֵיהּ דְּיַעֲקֹב, דִּיּוּקְנָא דְּאָדָם הָרִאשׁוֹן מַמָּשׁ."],[[0,"ולא ידע עשו וכו':","ולא ידע עשו מה שעשה לו בבטן, אבל השר הממנה שלו היה יודע. והקב\"ה הרעים את השמים וצבאם לקול הזה, של קטרוגו של שרו של עשו, כי ברכה ובכורה לא נשה הממונה שלו, ולא אמר. כי ברכה היה לו לנשות ולא נשה. אחוה הוא נשה ודאי, שכתוב ומבשרך לא תתעלם, ולא רצה יעקב לתת לו לאכול עד שלקח ממנו הבכרה שלו."],[1,"מאי בכורה נטל וכו':","מהו הבכורה שלקח. לקח ממנו הבכורה שלמעלה ושלמטה דהיינו קדושת הבכרה שלמעלה, להקריב קרבנות וכו'. ובכרה של מטה לקבל פי שנים וכדומה. בכרה כתוב חסר \u0003ו'.\u0004 אז עקב את אחיו ודאי, שעשה אותו עקב, והשליכו לאחור, מהו אחור, שהקדים אותו, שיצא תחילה לעולם הזה, אמר יעקב לעשו, קבל אתה עולם הזה תחילה, ואני אחר כך."],[2,"ת\"ח מה כתיב וכו':","בוא וראה, מה כתוב, ואחרי כן יצא אחיו וידו אוחזת בעקב עשו. מהו בעקב עשו, וכי יעלה על דעתך, שידו אוחזת ברגלו. אינו כן. אלא ידו אוחזת בההוא, מי שהוא עקב, ומי הוא, הוא עשו. כי עשו נקרא עקב, משעה שעקב אותו אחיו, ומיום שנברא העולם קרא אותו הקב\"ה עקב. כי עשו הוא בחינת נחש שכתוב בו, הוא ישופך ראש ואתה תשופנו עקב. שפירושו, אתה שנקראת עקב, תשופנו תחילה ולבסוף הוא ישוף ראשך מעליך. ומי הוא ראשו, הוא סמאל. שהוא ראש הנחש, שמכה בעולם הזה."],[3,"ועל דא בבטן וכו':","וע\"כ בבטן עקב את אחיו, ששם עליו להיות עקב. ולקח עשו את עולם הזה תחילה. וז\"ס שכתוב, ואלה המלכים אשר מלכו בארץ אדום לפני מלך מלך לבני ישראל. וזה סוד שאמר שלמה המלך, נחלה מבוהלת בראשונה ואחריתה לא תבורך. דהיינו באחרית העולם."],[4,"ועל דא בבטן עקב וכו':","וע\"כ בבטן עקב את אחיו ובאונו שרה את אלקים. שואל מהו ואונו. ומשיב, כך בארו, בכחו וגבורתו כראוי. אבל אינו כן. בירורו של הדבר הוא, יעקב היה צורה עליונה, וגוף הקדוש, שלא היה גוף מיום שהיה אדם הראשון כמו גוף של יעקב ויופי שלו. ויפיו של אדם הראשון, ההוא יופי ממש היה לו ליעקב, וצורתו של יעקב היתה צורתו של אדם הראשון ממש."]],[[0,"","וְלֹא יָדַע עֵשָׂו מַה שֶּׁעָשָׂה לוֹ בַּבֶּטֶן, אֲבָל הַשַּׂר הַמְמֻנֶּה שֶׁלּוֹ הָיָה יוֹדֵעַ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רִגֵּשׁ אֶת הַשָּׁמַיִם וְחֵילֵיהֶם לַקּוֹל הַזֶּה, שֶׁהֲרֵי בְּרָכָה וּבְכוֹרָה לֹא תָבַע הַמְמֻנֶּה שֶׁלּוֹ, וְלֹא אָמַר. שֶׁהֲרֵי בְּרָכָה הָיָה לוֹ לִתְבּעַ וְלֹא תָבַע. אָחִיו הֲרֵי וַדַּאי שֶׁתָּבַע, שֶׁכָּתוּב (ישעיה נח) וּמִבְּשָׂרְךְ לֹא תִתְעַלָּם, וְלֹא רָצָה יַעֲקֹב לָתֵת לוֹ לֶאֱכֹל, עַד שֶׁנָּטַל מִמֶּנּוּ אֶת בְּכוֹרָתוֹ."],[1,"","אֵיזוֹ בְּכוֹרָה נָטַל מִמֶּנּוּ? הַבְּכוֹרָה שֶׁלְּמַעְלָה וּלְמַטָּה. בְּכֹרָה חָסֵר ו'. אָז הוּא עָקַב אֶת אָחִיו. וַדַּאי שֶׁעָשָׂה אוֹתוֹ עָקֵב וְזָרַק אוֹתוֹ לְאָחוֹר. אֵיזֶה אָחוֹר? שֶׁהִקְדִּים אוֹתוֹ, שֶׁיָּצָא בָּרִאשׁוֹנָה לָעוֹלָם הַזֶּה. אָמַר יַעֲקֹב לְעֵשָׂו, טֹל אַתָּה אֶת הָעוֹלָם הַזֶּה בַּתְּחִלָּה, וַאֲנִי אַחַר כָּךְ."],[2,"","בֹּא וּרְאֵה מַה כָּתוּב, וְאַחֲרֵי כֵן יָצָא אָחִיו וְיָדוֹ אֹחֶזֶת בַּעֲקֵב עֵשָׂו. מַה זֶּה בַּעֲקֵב עֵשָׂו? וְכִי יַעֲלֶה עַל דַּעְתְּךְ שֶׁהָיָה אוֹחֵז אֶת יָדוֹ בְּרַגְלוֹ? לֹא כָּךְ. אֶלָּא יָדוֹ אוֹחֶזֶת בְּמִי שֶׁהוּא הָיָה עָקֵב. וּמִיהוּ? עֵשָׂו, שֶׁהֲרֵי עֵשָׂו נִקְרָא עָקֵב מִשָּׁעָה שֶׁעָקַב אֶת אָחִיו, וּמִיּוֹם שֶׁנִּבְרָא הָעוֹלָם קוֹרֵא לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא עָקֵב, שֶׁכָּתוּב הוּא יְשׁוּפְךְ רֹאשׁ וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב. אַתָּה שֶׁנִּקְרָא עָקֵב תְּשׁוּפֶנּוּ בַּתְּחִלָּה, וּלְבַסּוֹף הוּא שֶׁיִּמְחֶה אֶת רֹאשְׁךְ מֵעָלֶיךְ. וּמִיהוּ? סמא\"ל, שֶׁהוּא רֹאשׁ שֶׁל הַנָּחָשׁ שֶׁמַּכֶּה בָּעוֹלָם הַזֶּה."],[3,"","וְעַל זֶה בַּבֶּטֶן עָקַב אֶת אָחִיו, שָׂם עָלָיו לִקְיוֹת עָקֵב, וְנָטַל עֵשָׂו אֶת הָעוֹלָם הַזֶּה בַּהַתְחָלָה. וְזֶה סוֹד הַכָּתוּב וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל. וְזֶהוּ הַסּוֹד שֶׁאָמַר שְׁלֹמֹה הַמֶּלֶךְ, (משלי כ) נַחֲלָה מְבֹהֶלֶת בָּרִאשׁוֹנָה וְאַחֲרִיתָהּ לֹא תְבֹרָךְ, בְּסוֹף הָעוֹלָם."],[4,"","וְעַל זֶה (הושע יב) בַּבֶּטֶן עָקַב אֶת אָחִיו וּבְאוֹנוֹ שָׂרָה אֶת אֱלֹהִים. מַה זֶה וּבְאוֹנוֹ? כָּךְ אָמְרוּ, בְּכֹחַ וְהַתֹּקֶף שֶׁלּוֹ נָאֶה. אֲבָל לֹא כָּךְ. בֵּרוּר הַדָּבָר - שֶׁיַּעֲקֹב הָיָה דְיוֹקָן עֶלְיוֹן וְגוּף קָדוֹשׁ, שֶׁאֵין גּוּף מִיּוֹם שֶׁהָיָה אָדָם הָרִאשׁוֹן כְּמוֹ הַגּוּף שֶׁל יַעֲקֹב. וְיָפְיוֹ שֶׁל אָדָם, מַמָּשׁ אוֹתוֹ הַיֹּפִי הָיָה לְיַעֲקֹב. וּדְיוֹקָן שֶׁל יַעֲקֹב, דְּיוֹקָן שֶׁל אָדָם הָרִאשׁוֹן מַמָּשׁ."]]],[["אָדָם הָרִאשׁוֹן, בְּשַׁעֲתָא חִוְיָא דְּאָתָא וְאִתְפַּתָּה עַל יְדוֹי, יָכִיל חִוְיָא לֵיהּ. מַאי טַעְמָא. בְּגִין דְּלָא הֲוָה תּוּקְפָּא לְאָדָם הָרִאשׁוֹן, וְעַד כְּעָן לָא אִתְיילִיד מַאן דְּהֲוָה תּוּקְפָּא דִּילֵיהּ. וּמַנּוֹ תּוּקְפָּא דְּאָדָם הָרִאשׁוֹן. דָּא שֵׁת, דְּהֲוָה בְּדִיּוּקְנָא דְּאָדָם הָרִאשׁוֹן מַמָּשׁ, דִּכְתִּיב, (בראשית ה׳:ג׳) וַיּוֹלֶד בִּדְמוּתוֹ כְּצַּלְמוֹ ויִּקְרָא אֶת שְׁמוֹ שֵׁת. מַאי בִּדְמוּתוֹ כְּצַּלְמוֹ. דְּהֲוָה מָהוּל. וְכַד אָתָא מְמָנָא דְּעֵשָׂו לְגַבֵּי דְּיַעֲקֹב, כְּבַר אִתְיְלִיד תּוּקְפָּא דְּיַעֲקֹב, דְּאִיהוּ יוֹסֵף. וְזֶהוּ וּבְאוֹנוֹ שָׂרָה אֶת אֱלֹהִים. (עד כאן מצאתי)","הַאי קָלָא דְּאִתְּתָא, דְּיַכְלָא קָלָא דְּחִוְיָא לְאָחֲדָא בָּהּ, כְּכַלְבָּא בְּכַלְבְּתָא, מַאן אִיהוּ. אֶלָּא תָּא חֲזִי, דְּלֵית בְּכָל קָלִין דְּנָשִׁין דְּעָלְמָא, דְּיַכְלָא קָלָא דְּחִוְיָא לְאִתְדַּבְּקָא בָּהּ, וּלְאִתְאַחֲדָא בָּהּ, וּלְאִשְׁתַּתְּפָא בָּהּ. אֶלָּא תְּרִין נָשִׁין אִינּוּן דְּיַכְלָא קָלָא דְּחִוְיָא לְאִתְאַחֲדָא בְּהוֹן, חֲדָא. הַאי דְּלָא נְטִירַת סוֹאָבוּת נִדּוּתָהּ, וִימֵי לִבּוּנָהּ, כְּדְקָא יֵאוֹת, אוֹ דְּאַקְדִּימַת יוֹמָא חֲדָא לִטְבּוֹל. וַחֲדָא, הַאי אִתְּתָא דִּמְאַחְרֶת לְבַעְלָהּ עוֹנָה דִּילָהּ לְמֶעְבַּד צַעֲרָא לְבַעְלָהּ, בַּר אִי אִיהוּ לָא חָיִישׁ, וְלָא אַשְׁגַּח לְדָא.","אִלֵּין אִינּוּן תְּרֵין נָשִׁין, דְּהָא כְּמָה דְּאַקְדִּימוּ, הָכִי אִינּוּן מִתְאַחֲרָן, לְגַבֵּי קָלָא דְּנָחָשׁ, עַד דְּאַדְבִּיק קָלָא בְּקָלָא, וּכְמָה דְּמִתְאַחֲרָן לְמֶעְבַּד צַעֲרָא לְבַעְלָהּ (בעבודה) בְּעִכּוּבָא דְּמִצְוָה, הָכִי אַקְדִּים קָלָא דְּנָחָשׁ, לְאִתְדַּבְּקָא בְּהַהִיא קָלָא דְּאִתְּתָא. וְאִלֵּין אִינּוּן תְּרֵין נָשִׁין, דְּקָלָא דְּנָחָשׁ אָחִיד בְּקָלָא דִּלְהוֹן, כְּכַלְבָּא בְּכַלְבְּתָא, סִאוּבְתָּא בָּתַר סִאוּבְתָּא, זִּינָא בָּתַר זִינֵיהּ.","וְאִם תֹּאמַר, מָה אִיכְפַּת לָן, אִי אָחִיד קָלָא בְּקָלָא, אִי לא אָחִיד. וַוי דְּהָכִי מִתְאַבְּדָן בְּנֵי עָלְמָא בְּלא דַּעְתָּא. הַאי קָלָא דְּאִתְּתָא, כַּד אִתְעֲרָב וְאִשְׁתָּתַּף בַּהֲדֵי קָלָא דְּנָחָשׁ, בְּשַׁעֲתָא דְּחַיָּיבַת וּמַרְשָׁעַת נַפְקַת מִגּוֹ אֵיפָה וּמְשַׁטְּטָא בְּעָלְמָא, אִי עַרְעַת בְּהָנֵי תְּרֵין קַלִין, קָלָא דְּנָחָשׁ, וְקָלָא דְּאִתְּתָא, וְאִתְּתָא אִתְחַמְּמַת בְּהוּ, וְאִינּוּן בָּהּ, וְכֵיוָן (ס\"א דמתחממן רוחא אזלין בהדה) דְּאִתְחַמְּמָת, מִתְעַבְּדִין רוּחָא, וְאַגְלִים בַּהֲדָהּ, עַד דִּמְשַׁטְּטָא, וְעָאל בִּמְעָהָא דְּהַאי אִתְּתָא.","וְהַאי יָנּוֹקָא דִּיְלִידַת, כַּד אָתַאת הַהִיא חַיַּיבְתָּא, פְּקִידַת לֵיהּ לְהַהוּא רוּחָא, דְּאִיהוּ חִבּוּרָא בִּישָׁא, קָלָא דְּנָחָשׁ, דִּמְכַּשְׁכְּשָׁא בָּהּ, וְאִיהוּ מְחַיְיכָא בִּינּוֹקָא, עַד דְּאָתַת הַהִיא חַיַּיבְתָּא, כְּאִתְּתָא דְּפָקִידַת בְּרָא לְאִתְּתָא אַחֲרָא, וּמְפַטְפֶטֶת לֵיהּ וְחַיְּיכַת לֵיהּ, בְּפִטְפּוּטָא עַד דְּתֵיתֵי אִמֵּיהּ. כַּךְ עָבְדָא הַאי רוּחָא. וּזְמָנִין סַגִּיאִין, דְּאִיהוּ שְׁלִיחָא דְּהַהִיא חַיַּיבְתָּא, וְקַטְלָא לֵיהּ, הֲדָא הוּא דִּכְתִּיב, (קהלת ד׳:א׳) וּמִיַּד עוֹשְׁקֵיהֶם כֹּחַ. וְלָא כְּמָה דְּאַתּוּן אַמְרִין. אֶלָּא הַהוּא כֹּחַ דְּהַהוּא רוּחָא, וְעַל דָּא, תְּרִין זִמְנִין כְּתִיב בְּהַאי קְרָא, וְאֵין לָהֶם מְנַחֵם. חַד מִלִּילִית חַיַּיבְתָּא, וְחַד מֵהַהוּא רוּחָא.","אִי סָבָא, הַשְׁתָּא אִית לָךְ רְחִימִין, וְאַתְּ מִשְׁתָּעֵי, כְּמַאן דְּלָא חָמִית אִינּוּן מַגִּיחֵי קְרָבָא, הָא כֻּלְּהוּ בִּשְׁלָמָא עִמָּךְ. הַשְׁתָּא מִכָּאן וּלְהָלְאָה, לָא אַעְדֵּי מִנַּאי מָאנֵי קְרָבָא בְּדִיל לְאַדְכְּרָא שְׁמִי.","הַהוּא חַטָּאת רוֹבֵץ, קָאִים עַל פִּתְחָא כְּכַלְבָּא. בְּזִמְנָא דְּקָלָא בַּתְרַיְיתָא, דְּיָהִיבַת אִתְּתָא, נָפִיק, אִיהוּ דָּלִיג מֵעַל פִּתְחָא וְאִתְעֲבָר מִתַּמָּן, וְאָזִיל אֲבַתְרָהּ. מַאי טַעְמָא. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא שָׁדַר חַד מַפְתְחָא דִּילֵיהּ, וְקָלָא פַּרְחָא, וּמַפְתְּחָא אַתְיָא, וְחִוְיָא אָזַל בָּתַר קָלָא דְּהוּא נָפִיק לְעָלְמָא, וְעַד טוּרָא דְּבִטְנָא אָזִיל, וּמְכַשְׁכְּשָׁא, עַד עִידָּן דְּאִתְנְקִיאַת, מֵהַהוּא זוּהֲמָא, דִּנְשִׁיכִין דְּחִוְיָא בִּישָׁא. וְקוּדְשָׁא בְּרִיךְ הוּא, מְסַבֵּב סִבוּבִין, וְעָבִיד עוֹבָדִין כַּדְקָא יֵאוֹת.","וְכָל דָּא, בְּגִין דְּהַהוּא בֶּטֶן אִתְדַּחְיָא. הָא וַדַּאי, אִתְדַּחְיָא מֵהַהוּא בֶּטֶן, וְלֵית לֵיהּ חוּלָקָא, וְאִתְדָּחֵי מִבֶּטֶן דִּלְתַתָּא, דִּשְׁאַר נְשִׁין דְעַלְמָא דְּאַף עַל גַּב דְּעָבִיד צַעַר לָא אִתְיְיהִיב לֵיהּ רֵשׁוּ לְשַׁלְּטָאָה בֵּיהּ. וּמַאן בֶּטֶן אִתְיְיהִיב לֵיהּ, וְאִיהוּ שָׁלִיט עָלֵיהּ. הַהוּא בֶּטֶן דְּסוֹטָה, דִּכְתִּיב, (במדבר ה׳:כ״ז) וְצָבְתָה בִטְנָהּ, בְּגִין דְּהַאי בֶּטֶן, עָבִיד בֵּיהּ נוּקְמִין לִרְעוּתֵיהּ, וְהַאי בֶּטֶן דִּילֵיהּ אִיהוּ, וְקוּדְשָׁא בְּרִיךְ הוּא יָהִיב לֵיהּ בְּגִין דְּלָא אִתְדָּחֵי מִכֹּלָּא. הַשְׁתָּא רְחִימִין דִּילִי, אֲצִיתוּ. לָא חֲמֵינָא לְכוּ, וּמַלִּילְנָא לְכוּ. (קהלת א׳:ח׳) כָּל הַדְּבָרִים יְגֵעִים, לָא יָכִיל אִינִישׁ לְמַלְּלָא, אֲפִילּוּ מִלִּין דְּאוֹרַיְיתָא יְגֵעִים אִינּוּן.","כְּתִיב, (בראשית לכ) וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ וַיֵּאָבֵק אִישׁ עִמּוֹ, וּכְתִיב וַיַּרְא כִּי לא יָכוֹל לוֹ וַיִּגַּע בְּכַף יְרֵכוֹ. וְהַהוּא יָרֵךְ דְּרָוַוח מִיַּעֲקֹב. וְהַהוּא יָרֵךְ בַּחֲלִישׁוּ דִּילֵיהּ (בראשית נ\"א ע\"ב, קמ\"ד ע\"א) עַד דְּאָתָא שְׁמוּאֵל. מַאי בַּחֲלִישׁוּ דְּלָא מָשִׁיךְ נְבוּאָה. כַּד אָתָא שְׁמוּאֵל, נָטַל הַהוּא יָרֵךְ, וְסַלְקֵיהּ מֵהַהוּא אֲתָר, וְחָטַף לֵיהּ מִנֵּיהּ, וּמֵהַהוּא זִמְנָא אִתְעָדֵי מִנֵּיהּ, וְלָא הֲוָה לֵיהּ חוּלָקָא בִּקְדוּשָׁה כְּלָל.","קוּדְשָׁא בְּרִיךְ הוּא לָא קָפַח, וְלָא דָּחֵי לֵיהּ מִכֹּלָּא, בְּגִין דְּנָטַל שְׁמוּאֵל יָרֵךְ דִּילֵיהּ, אֶלָּא יָהִיב לֵיהּ חוּלָקָא חֲדָא. מַאי אִיהִי. יָהִיב לֵיהּ הַהוּא יָרֵךְ וּבֶטֶן דְּסוֹטָה, חֳלַף הַהוּא יָרֵךְ וּבֶטֶן, דְּאַעְדֵּי מִנֵּיהּ. וְעַל דָּא תַּרְוַויְיהוּ יָהִיב לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, לְמֶהוֵי אַתְרָא דְּקֻדְשָׁא פָּנוּי מִכָּל סַאֲבוּתָא.","וְלַנְפִּיל יָרֵךְ. מַהוּ וְלַנְפִּיל, וְנָפְלָה יְרֵכָהּ וְלַצְבּוֹת, וְצָבְתָה יְרֵכָהּ מִבָּעֵי לֵיהּ. אֶלָּא, כְּמַאן דְּאַשְׁדֵי גַּרְמָא לְכַלְבָּא, וְאָמַר לֵיהּ, טוֹל הַאי לְחוּלָקָךְ. וּמִכֹּלָּא לָא אַבְאִישׁ קָמֵיהּ, אֶלָּא דְּגָזְלוּ (ס\"א דאפיקו) מִנֵּיהּ יָרֵךְ, בְּגִין דְּאִיהוּ יָגַע וְלָאֵי עָלֵיהּ, וְרָוַוח לֵיהּ וְאַפִּיקוּ לֵיהּ מִנֵּיהּ. וְעַל דָּא, קוּדְשָׁא בְּרִיךְ הוּא אַפִּיל לֵיהּ, גַּרְמָא דָּא דְּסוֹטָה, וְאַפִּיק לֵיהּ כִּדְקַאמְרָן, וּבְדָא אִיהוּ רַוִּי וְחַדֵּי.","כָּל אִינּוּן רְתִיכִין וְסִיַּיעְתָּא דִּילֵיהּ, בָּעָאן תָּדִיר יָרֵךְ, וְאַזְלֵי בְּכִסוּפָא אֲבַתְרֵיהּ. וּבְגִין דָּא, (קי\"ב ע\"ב) הָנֵי בָּרְכִי דְּרַבָּנָן דְּשַׁלְהֵי, מִן דָּא אִיהוּ. דְּכָל כִּסּוּפָא דִּלְהוֹן, בָּתַר יָרֵךְ אִיהוּ, וְכָל שֶׁכֵּן יָרֵךְ דְּרַבָּנָן, וְכָל מִלָּה אַהְדָּר לְאַתְרֵיהּ, וְקוּדְשָׁא בְּרִיךְ הוּא לָא גָּרַע כְּלוּם, מִכָּל מַה דְּאִצְטְרִיךְ, וְלָא בָּעָא דְּיִקְרַב לִקְדוּשָׁה, בַּר עִמֵּיהּ וְעַדְבֵיהּ חוּלָקֵיהּ וְאַחֲסַנְתֵּיהּ. כְּמָה דְּעָבִיד קוּדְשָׁא בְּרִיךְ הוּא לְעֵילָּא, הָכִי עַבְדֵי יִשְׂרָאֵל לְתַתָּא, וְהָכִי אִצְטְרִיךְ לְמֶעְבַּד, וְהָכִי תָּנֵינָן, אָסִיר לֵיהּ לְיִשְׂרָאֵל, לְמֵילָף אוֹרַיְיתָא לְעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, דִּכְתִיב, (תהילים קמ״ז:כ׳) מַגִּיד דְּבָרָיו לְיַעֲקֹב וְגוֹ', לא עָשָׂה כֵן לְכָל גּוֹי וְגוֹ'."],[[0,"אדם הראשון בשעתא וכו':","אדם הראשון בשעה שבא הנחש ונתפתה על ידו, הנחש היה יכול לו. מהו הטעם, הוא משום שלא היה כח ועצמה לאדם הראשון, שעד עתה עוד לא נולד מי שהוא כח ועצמה שלו, ומי הוא כח ועצמה של אדם הראשון, הוא שת, שהיה בצורת אדם הראשון ממש, שכתוב, ויולד בדמותו בצלמו ויקרא את שמו שת, מהו בדמותו בצלמו. היינו שנולד מהול. וכשבא הממונה של עשו אל יעקב, כבר נולד כח ועצמה של יעקב, שהוא יוסף, זהו ובאונו שרה את אלקים. שהוא יוסף שהיה אונו."],[1,"האי קלא דאתתא וכו':","קול הזה של אשה, שקול הנחש יכול להתאחז בה, ככלב בכלבה, מי הוא. ומשיב, אלא בוא וראה, שאין בכל הקולות של הנשים שבעולם, שקול הנחש יוכל להתדבק בה, ולהתאחז בה, ולהשתתף בה, אלא ב' נשים הן, שקול הנחש יכול להתאחז בהן. אחת, מי שאינה שומרת טומאת נדתה וימי ליבונה כראוי, או שמקדמת יום אחד לטבול. ואחת, אשה הזו המאחרת העונה שלה, כדי לעשות צער לבעלה. חוץ אם הבעל אינו מקפיד ואינו משגיח על זה."],[2,"אלין אינון תרין וכו':","אלו הן שתי נשים. כי כמו שמקדימות לטבול לפני הזמן, כן הן מתאחרות אצל הקול של הנחש עד שמתדבק קול בקול. וכמו שמאחרות עונתה לעשות צער לבעלה בעכוב של מצוה, כך מקדים הקול של הנחש, להתדבק בקול ההיא של האשה. ואלו הן שתי נשים שהקול של הנחש נאחז בקולן ככלב בכלבה. טומאה הולכת אחר טומאה, מין אחר מינו."],[3,"וא\"ת מה איכפת וכו':","ואם תאמר, מה נוגע לנו, אם נאחז קול בקול או לא. ומשיב, אוי שכך נאבדים בני העולם בלא דעת. קול הזה של האשה, כשמתערב ומשתתף עם הקול של הנחש, בשעה שלילית החייבת והמרשעת יוצאת מתוך האיפה שלה, ומשוטטת בעולם, אם פוגשת באלו שני קולות, קול של הנחש וקול של האשה, והאשה לילית מתחממת בהם, והם בה, וכיון שמתחממת, נעשה רוח והולכות עמה עד שהרוח משוטט ונכנס במעיה של אשה ההיא."],[4,"והאי ינוקא דילידת וכו':","וילד הזה שהיא מולידה, כשבאה המרשעת ההיא, לילית, היא פוקדת את הרוח, שבא מחבור הרע של קול הנחש, הדופק בה, והוא, הרוח, מצחק עם הילד עד שבאה המרשעת ההיא לילית, כאשה הפוקדת בן של אשה אחרת, ומפטפטת עמו ומצחקת עמו עד שבאה אמו. כך עושה רוח הזה. ופעמים הרבה, שהוא הרוח, הוא שליח של מרשעת ההיא, לילית, והורג אותו. ז\"ש ומיד עושקיהם כח. ולא כמו שאתם מבארים הכתוב, אלא פירושו, כח ההוא של רוח ההוא עושק אותו. וע\"כ שתי פעמים כתוב במקרא הזה, ואין להם מנחם, אחד מלילית המרשעת, ואחד מרוח ההוא."],[4,"","ביאור המאמר. כי יש קול ודבור. ביחד, וה\"ס ג\"ר. ויש קול בחוסר דבור, והוא ו\"ק בלי ראש. והדינים הגורמים לו להיות ו\"ק, הם או ממסך דצמצום ב', או ממסך דצמצום א'. וזה ההפרש מקול האשה לקול הנחש, כי קול האשה הוא דוגמת הקול של מלכות שלמעלה, שהיא מקבלת מז\"א בעלה, והוא מצמצום ב'. וקול הנחש, הוא מצמצום א'."],[4,"","וז\"ש (באות שי\"ז) \u0003דלית בכל קלין דנשין דעלמא דיכלא קלא דחויא לאתדבקא בה.\u0004 כי קול האשה משומרת על ידי ז\"א, והוא מצמצום ב'. וקול הנחש הוא מצמצום א', ואין לו שליטה עליה. חוץ מב' נשים המרחקות בעליהן או על ידי הקדם טבילה לפני הזמן, שמביאה טומאה על בעלה. או שמאחרת עונתה ומצערת לבעלה. ומתוך שנעשה פירוד בין אשה לבעלה, מפסידים השמירה של ז\"א מלמעלה, וקול הנחש יכול להתדבק בהן. וז\"ש (באות שי\"ח) \u0003אלין אינון תרין נשין\u0004 וכו'."],[4,"","ועכ\"ז אין קול הנחש יכול להתחבר עם קול האשה אלא באמצעות הקליפה לילית שהיא נקבה ממין הס\"א והנחש. וז\"ש, \u0003אי ערעת בהני תרין קלין\u0004 וכו' \u0003וכיון דאתחממת מתעבדין רוחא\u0004 שרוח הזה הוא זוהמת הנחש, וכיון שנולד ויצא מב' הקולות של האשה ושל הנחש, יש בו תערובות מב' הדינים, מצמצום א' וצמצום ב'. וע\"כ יש לו השתוות עם בן האשה מצד שהוא מצמצום ב' כמוהו, וע\"כ \u0003איהו מחייכא בינוקא.\u0004 ויש לו כח להרג אותו עם כח הדין דצמצום א'. וז\"ש, \u0003ומיד עושקיהם כח, ולא כמה דאתון אמרין, אלא ההוא כח דההוא רוחא.\u0004 דהיינו כח הצמצום א' שבו."],[5,"אי סבא השתא וכו':","אמר לעצמו, אי זקן, עתה יש לך אוהבים, ואתה מדבר כמי שלא ראה אלו עורכי מלחמה, הרי כולם בשלום עמך. עתה מכאן ולהלאה, לא אסיר ממני כלי מלחמה, כדי להזכיר את שמי."],[6,"ההוא חטאת רובץ וכו':","חטאת רובץ ההוא, שהוא הנחש שעליו נאמר, לפתח חטאת רובץ, שהוא הפתח של המלכות עומד על הפתח ככלב. בזמן שקול האחרון יוצא, שאשה הכורעת ללדת נותנת, דהיינו לפני הלידה, הוא מדלג מן הפתח ונעבר משם והולך אחר האשה. מהו הטעם. משום שהקב\"ה שולח מפתח אחד לפתוח את רחמה, והקול פורח, והמפתח בא. והנחש הולך אחר הקול היוצא לעולם ועד ההר שבבטן הולך, שהוא היסוד, כי נה\"י נקראים הרים תחתונים, ונושך שם, ופותח את רחמה. (כנ\"ל בשלח אות קפ\"ג) ודופקשם, עד הזמן שהיא תנקה מזוהמא ההיא של נשיכות הנחש הרע. והקב\"ה מסבב סבות ועושה מעשים כראוי."],[6,"","פנימיות הדברים. ענין זה הוא מאמר ר' שמעון לעיל פרשת בשלח אות קפ\"ב וקפ\"ג. שאומר, \u0003חד איילתא אית בארעא וכו'\u0004 דהיינו הנוקבא דז\"א, \u0003וכד בעיא לאולדא היא סתימא מכל סטרין וכו'\u0004 ופירוש הדברים הוא. כי הנשמות נולדות מן הנוקבא דז\"א, ומטרם שנולדות ויוצאות בעולם הבריאה, הן צריכות לעיבור בנוקבא בתנה\"י שלה, מחזה שלה ולמטה המכונים בטן, ומקבלות שמה הארת החכמה על ידי הנוקבא שמקבלת חכמה משליטת קו השמאל ומשפעת לנשמות. ונודע שבעת שהנוקבא באה תחת שליטת קו השמאל היא נקפאת ונסתמים כל פתחיה ושעריה, (כנ\"ל בראשית א' אות שס\"ז בסולם). וז\"ש, \u0003וכד בעיא לאולדא היא סתימא מכל סטרין\u0004 להיותה קפואה מחמת שליטת השמאל. ומסיים שם, \u0003וקב\"ה חייס עלה וזמין לקבלה חד נחש ונשך בערייתא דילה וכו' ואולידת מיד.\u0004 פירוש. כי אז הקב\"ה, שהוא קו אמצעי, מעלה בחזרה את המלכות למקום בינה, וממעט קומת קו השמאל, ומיחדו עם הימין, ומשפיע לה חסדים, ואז היא נפתחת ומולידה. וכיון שהמלכות עולה למקום בינה, הנוקבא חוזרת לו\"ק, ונופלים בינה ותו\"מ של הנוקבא לעולם הבריאה, והנחש קונה כח לינק מנה\"י דנוקבא. כי בעת שיש לה ג\"ר נמצאים תנה\"י שלה באצילות, ואין הקליפות יכולים לינק מהנוקבא, כי באצילות כתוב, לא יגורך רע. אבל כשנפלו לבריאה, כבר יכולים לינק ממנה. ונבחן שמה שהעלה הקב\"ה את המלכות לבינה כדי ליחד הקוים זה בזה, ולפתוח את רחמה, היא הזמנת הנחש לנשוך בנה\"י שלה. כלומר לינק מהם. באופן, שפתיחת הרחם ויניקת הנחש באים כאחד. וז\"ש \u0003וזמין לקבלה חד נחש\u0004 ונשיך בערייתא. אמנם הקב\"ה עשה כך מתוך הכרח כדי שהנוקבא תוכל ללדת."],[6,"","וזה אמרו כאן, \u0003ההוא חטאת רובץ,\u0004 שהוא הנחש, \u0003קאים על פתחא ככלבא,\u0004 שעומד מחוץ לאצילות, ככלב העומד מחוץ לבית. ואין לו כח לינק משהו מן הנוקבא שבאצילות. \u0003בזמנא דקלא בתרייתא דיהיבת אתתא נפיק,\u0004 דהיינו הקול האחרון מן ע' קולות של הכורעת לילד, שהוא רגע לפני הלידה. \u0003איהו דליג מעל פתחא ואתעבר מתמן ואזיל אבתרה,\u0004 שדולג מעל הפתח, והולך אחר הנוקבא עצמה להתדבק בה. \u0003מ\"ט, בגין דקב\"ה שדר חד מפתחא דיליה,\u0004 שה\"ס מסך דחירק, שעליו יוצא קומת החסדים הפותח את רחמה, המעלה את מלכות דנוקבא לבינה דנוקבא, שהוא ת\"ת, ותנה\"י שמחזה ולמטה שלה נופלים לבריאה כנ\"ל, \u0003וקלא פרחא ומפתחא אתיא\u0004 והקול האחרון פורח והמפתח הנ\"ל בא, שהתנה\"י שלה נופלים לעולם הבריאה כנ\"ל אז \u0003וחויא אזל בתר קלא דהוא נפיק לעלמא,\u0004 הנחש הולך אחר הקול ומתדבק בו, \u0003ועד טורא דבטנא אזיל,\u0004 שהוא היסוד, ויונק שם, שזה מכונה בדברי ר\"ש הנ\"ל, ונושך בערייתא, כי כשתנה\"י דנוקבא הם בבריאה, יכול לינק מהם. \u0003ומכשכשא עד עידן דאתנקיאת מההוא זוהמא דנשיכין דחויא.\u0004 דהיינו עד שמחזרת התנה\"י שלה מבריאה לאצילות שחוזרת וממשכת ג\"ר, שאז נטהרת מנשיכת הנחש, דהיינו מיניקתו, כי אין לו כח לינק מאצילות, כלום."],[7,"וכל דא בגין וכו':","וכל זה היניקה של הנחש באה, משום שבטן ההיא, דהיינו תנה\"י דנוקבא, נדחתה, שנפלו לעולם הבריאה, כנ\"ל. זה ודאי, שהנחש נדחה מבטן ההיא ואין לו חלק בה, כי אח\"כ חוזרת וממשכת ג\"ר ואותם תנה\"י שנפלו לבריאה חוזרים לאצילות. וכן הוא נדחה מבטן שלמטה של שאר נשים שבעולם, כי הנשים למטה הם ענפי הנוקבא העליונה, שאע\"פ שעושה להם צער, לא ניתנה לו רשות לשלוט עליהם, ואיזו בטן ניתנה לו שהוא שולט עליה, הוא בטן ההיא של סוטה, שכתוב וצבתה בטנה. משום שבבטן הזו, עושה בה נקמות כרצונו, ובטן ההיא שלו היא, שהקב\"ה נתן לו, כדי שלא יהיה נדחה לגמרי. עתה אוהבי האזינו לא ראיתי אותכם ודברתי לכם. כל הדברים יגעים לא יוכל איש לדבר, אפילו דברי תורה יגעים הם."],[8,"כתיב ויותר יעקב וגו':","כתוב, ויותר יעקב לבדו ויאבק איש עמו, וכתוב, וירא כי לא יכול לו ויגע בכף ירכו. וירך ההיא הרויח הס\"א מיעקב, וירך ההוא היתה בחולשתה עד שבא שמואל. מהו חולשתה. היינו שלא המשיך אור הנבואה. כשבא שמואל לקח ירך ההיא, והעבירו ממקום ההוא של הס\"א, וחטף אותה ממנו. (כמ\"ש לעיל בראשית א' דף קל\"ג אות קמ\"ה בהסולם ע\"ש) ומזמן ההוא הוסרממנו, ואין לו חלק בקדושה כלל."],[9,"קב\"ה לא קפח וכו':","הקב\"ה אינו מקפחו ואינו דוחה אותו מכל, משום שלקח שמואל הירך שלו, אלא נותן לו חלק אחד, ומה הוא. נותן לו ירך ובטן של הסוטה, תמורת ירך ובטן שהסיר ממנו. וע\"כ שתיהן נתן לו הקב\"ה, לס\"א, שיהיה מקום הקדושה פנוי מכל טומאה."],[10,"ולנפיל ירך:","שואל ונפלה ירכה היה צריך לומר. ולצבות בטן, וצבתה בטנה היה צריך לומר. ומשיב, אלא כמי שזורק עצם לכלב, ואמר לו קבל את זה לחלקך. וע\"כ אוה\"כ ולנפיל, ולצבות. והכל לא הרע לו אלא מה שגזלו ממנו הירך, שהוא יגע ועמל עליה, דהיינו ויאבק איש עמו וגו', והרויח אותה, והוציאו אותה מידו. וע\"כ השליך אליו הקב\"ה עצם הזה של הסוטה, והוציאו אליו, כמו שאמרנו ובזה שבע ושמח."],[11,"כל אינון רתיכין וכו':","כל אלו המרכבות והחברה שלו, רוצים תמיד ירך והולכים בהשתוקקות אחריו. ומשום זה אלו ברכי רבנן העיפים מן זה הוא, מן הס\"א, שכל השתוקקותם הוא לירך, ומכל שכן ירך דרבנן. וכל דבר הוחזר למקומו, והקב\"ה אין גורע כלום מכל מה שצריך, ואינו רוצה שיקרב לקדושה חוץ מעמו וגורלו חלקו ונחלתו. כמו שעושה הקב\"ה למעלה, כך עושים ישראל למטה, וכך צריך לעשות, וכך למדנו, אסור לו לישראל ללמוד תורה לעכו\"ם, שכתוב, מגיד דבריו ליעקב וגו'. לא עשה כן לכל גוי וגו'. כי צריכים להרחיק אותם מקדושה."]],[[0,"","אָדָם הָרִאשׁוֹן, בְּשָׁעָה שֶׁבָּא הַנָּחָשׁ וְהִתְפַּתָּה עַל יָדוֹ, יָכֹל לוֹ הַנָּחָשׁ. מָה הַטַּעַם? כִּי לֹא הָיָה כֹּחַ לְאָדָם הָרִאשׁוֹן, וְעַד עַכְשָׁו לֹא נוֹלַד מִי שֶׁהָיָה הַכֹּחַ שֶׁלּוֹ. וּמִיהוּ תָקְפּוֹ שֶׁל אָדָם הָרִאשׁוֹן? זֶה שֵׁת, שֶׁהָיָה בִּדְיוֹקָן שֶׁל אָדָם הָרִאשׁוֹן מַמָּשׁ, שֶׁכָּתוּב (בראשית ה) וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ וַיִּקְרָא אֶת שְׁמוֹ שֵׁת. מַה זֶּה בִּדְמוּתוֹ כְּצַלְמוֹ? שֶׁהָיָה מָהוּל. וּכְשֶׁבָּא הַמְמֻנֶּה שֶׁל עֵשָׂו אֶל יַעֲקֹב, כְּבָר נוֹלַד תָּקְפּוֹ שֶׁל יַעֲקֹב, שֶׁהוּא יוֹסֵף, וְזֶהוּ וּבְאוֹנוֹ שָׂרָה אֶת אֱלֹהִים. (עד כאן מצאתי)."],[1,"","הַקּוֹל הַזֶּה שֶׁל הָאִשָּׁה שֶׁיָּכוֹל קוֹל הַנָּחָשׁ לְהֵאָחֵז בָּהּ כְּמוֹ כֶלֶב בְּכַלְבָּה, מַה הוּא? אֶלָּא בּא וּרְאֵה שֶׁאֵין בְּכָל קוֹלוֹת הַנָּשִׁים שֶׁל הָעוֹלָם שֶׁיָּכוֹל קוֹל הַנָּחָשׁ לְהִדָּבֵק בּוֹ וּלְהֵאָחֵז בּוֹ וּלְהִשְׁתַּתֵּף בּוֹ. אֶלָּא שְׁתֵּי נָשִׁים הֵן שֶׁיָּכוֹל קוֹל הַנָּחָשׁ לְהֵאָחֵז בָּהֶן - אַחַת זוֹ שֶׁלֹּא שׁוֹמֶרֶת טֻמְאַת נִדָּה וִימֵי לִבּוּנָהּ כָּרָאוּי, אוֹ שֶׁמַּקְדִּימָה יוֹם אֶחָד לִטְבֹּל, וְאַחַת זוֹ אִשָּׁה שֶׁמְּאַחֶרֶת לְבַעְלָהּ אֶת עוֹנָתָהּ לַעֲשׂוֹת צַעַר לְבַעְלָהּ, פְּרָט אִם אֵינוֹ מַקְפִּיד וְלֹא מַשְׁגִּיחַ עַל זֶה."],[2,"","אֵלּוּ הֵן שְׁתֵּי נָשִׁים. שֶׁהֲרֵי כְּמוֹ שֶׁהִקְדִּימוּ, כָּךְ הֵן מִתְאַחֲרוֹת לְקוֹל הַנָּחָשׁ, עַד שֶׁנִּדְבָּק קוֹל בְּקוֹל, וּכְמוֹ שֶׁמִּתְאַחֲדוֹת לַעֲשׂוֹת צַעַר לְבַעְלָהּ (בעבודה) בְּעִכּוּב מִצְוָה, כָּךְ מַקְדִּים קוֹל הַנָּחָשׁ לְהִדָּבֵק בְּקוֹל אוֹתָהּ הָאִשָּׁה. וְאֵלּוּ הֵן שְׁתֵּי נָשִׁים שֶׁקּוֹל הַנָּחָשׁ אוֹחֵז בַּקּוֹל שֶׁלָּהֶן כְּמוֹ כֶלֶב בְּכַלְבָּה, טֻמְאָה אַחַר טֻמְאָה, מִין אַחַר מִינוֹ."],[3,"","וְאִם תֹּאמַר, מָה אִכְפַּת לָנוּ אִם אוֹחֵז קוֹל בְּקוֹל וְאִם לֹא אוֹחֵז? אוֹי שֶׁכָּךְ מִתְאַבְּדִים בְּנֵי הָעוֹלָם בְּלִי דַעַת. הַקּוֹל הַזֶּה שֶׁל הָאִשָּׁה, כְּשֶׁמִּתְעָרֵב וּמִשְׁתַּתֵּף יַחַד עִם קוֹל הַנָּחָשׁ, בְּשָׁעָה שֶׁהָרְשָׁעָה וּמִרְשַׁעַת יוֹצֵאת מִתּוֹךְ (האיפה) וּמְשׁוֹטֶטֶת בָּעוֹלָם, אִם הִיא פּוֹגֶשֶׁת בְּאוֹתָם שְׁנֵי קוֹלוֹת, קוֹל הַנָּחָשׁ וְקוֹל הָאִשָּׁה, וְהָאִשָּׁה מִתְחַמֶּמֶת בָּהֶם וְהֵם בָּהּ, וְכֵיוָן (שמתחממים נעשים רוח והולכים עמה), שֶׁמִתְחַמֶּמֶת נַעֲשִׂים רוּחַ, וּמִתְגַּשֵּׁם עִמָּהּ, עַד שֶׁמְּשׁוֹטֶטֶת וְנִכְנֶסֵת לִמְעֵי אוֹתָהּ הָאִשָּׁה."],[4,"","וְהַתִּינוֹקֹ הַזֶּה שֶׁיּוֹלֶדֶת, כְּשֶׁבָּאָה אוֹתָהּ רְשָׁעִית (לילי\"ת), פּוֹקֶדֶת אֶת אוֹתָהּ הָרוּחַ שֶׁהוּא חִבּוּר רַע, קוֹל הַנָּחָשׁ שֶׁמְּכַשְׁכֵּשׁ בָּהּ, וְהוּא צוֹחֵק בַּתִּינוֹק, עַד שֶׁבָּאָה אוֹתָהּ הָרְשָׁעִית (לילי\"ת) כְּמוֹ אִשָּׁה שֶׁפּוֹקֶדֶת בֵּן לְאִשָּׁה אַחֶרֶת, וּמְפַטְפֶּטֶת לוֹ וְצוֹחֶקֶת לוֹ בְּפִטְפּוּט עַד שֶׁתָּבֹא אִמּוֹ. כָּךְ עוֹשָׂה אוֹתָהּ הָרוּחַ. וּפְעָמִים רַבּוֹת שֶׁהוּא שָׁלִיחַ שֶׁל אוֹתָהּ הָרְשָׁעִית, וְהוֹרֶגֶת אוֹתוֹ. זֶהוּ שֶׁכָּתוּב (קהלת ד) וּמִיַּד עֹשְׁקֵיהֶם כֹּחַ, וְלֹא כְּמוֹ שֶׁאַתֶּם אוֹמְרִים, אֶלָּא אוֹתוֹ כֹּחַ שֶׁל אוֹתָהּ רוּחַ. וְעַל זֶה פַּעֲמַיִם כָּתוּב בַּפָּסוּק הַזֶּה וְאֵין לָהֶם מְנַחֵם - אֶחַד מִלִּילִית הָרְשָׁעָה, וְאֶחָד מֵאוֹתָהּ הָרוּחַ."],[5,"","אֵי סָבָא, עַתָּה יֵשׁ לְךְ רַחֲמִים, וְאַתָּה מְדַבֵּר כְּמִי שֶׁלֹּא רָאָה אֵלּוּ הַיּוֹצְאִים לִקְרָב, הֲרֵי כֻּלָּם בְּשָׁלוֹם עִמְּךְ. עַתָּה מִכָּאן וּלְהָלְאָה לֹא"],[6,"","אֶפְשּט מֵעָלַי כְּלֵי הַקְּרָב בַּעֲבוּר שֶׁאַזְכִּיר שְׁמִי. אוֹתוֹ חַטָּאת רֹבֵץ עוֹמֵד עַל הַפֶּתַח כְּמוֹ כֶלֶב. בִּזְמַן שֶׁהַקּוֹל הָאַחֲרוֹן שֶׁנּוֹתֶנֶת הָאִשָּׁה יוֹצֵא, הוּא מְדַלֵּג מֵעַל הַפֶּתַח וְעוֹבֵר מִשָּׁם וְהוֹלֵךְ אַחֲרֶיהָ. מָה הַטַּעַם? מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵחַ מַפְתֵּחַ אֶחָד שֶׁלּוֹ, וְהַקּוֹל פּוֹרֵחַ, וְהַמַּפְתֵּחַ בָּא, וְהַנָּחָשׁ הוֹלֵךְ אַחַר הַקּוֹל שֶׁהוּא יוֹצֵא לָעוֹלָם, וְעַד הָהָר שֶׁבַּבֶּטֶן הוֹלֵךְ וּמְכַשְׁכֵּשׁ, עַד הַזְּמַן שֶׁמִּתְנַקֵּית מֵאוֹתָהּ הַזֻּהֲמָה שֶׁל נְשִׁיכוֹת הַנָּחָשׁ הָרָע. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְסַבֵּב סִבּוּבִים וְעוֹשֶׂה מַעֲשִׂים כָּרָאוּי."],[7,"","וְכָל זֶה מִשּׁוּם שֶׁאוֹתָהּ הַבֶּטֶן נִדְחֲתָה. הֲרֵי וַדַּאי שֶׁנִּדְחָה מֵאוֹתָהּ הַבֶּטֶן, וְאֵין לוֹ חֵלֶק, וְנִדְחָה מֵהַבֶּטֶן שֶׁלְּמַטָּה שֶׁל שְׁאָר נְשׁוֹת הָעוֹלָם. שֶׁאַף עַל גַּב שֶׁעוֹשֶׂה צַעַר, לֹא נִתֶּנֶת לוֹ רְשׁוּת לִשְׁלֹט בָּהֶם. וְאֵיזוֹ בֶּטֶן נִתֶּנֶת לוֹ וְשׁוֹלֵט עָלֶיהָ? אוֹתָהּ הַבֶּטֶן שֶׁל הַסּוֹטָה, שֶׁכָּתוּב (במדבר ה) וְצָבְתָה בִטְנָהּ. מִשּׁוּם שֶׁבַּבֶּטֶן הַזּוֹ עוֹשֶׂה בָּהּ נְקָמוֹת כִּרְצוֹנוֹ, וְהַבֶּטֶן הַזּוֹ הִיא שֶׁלּוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לוֹ בִּשְׁבִיל שֶׁלֹּא יִדָּחֶה מֵהַכֹּל. עַכְשָׁו, אֲהוּבִים שֶׁלִּי, הַקְשִׁיבוּ. לֹא רָאִיתִי אֶתְכֶם וְדִבַּרְתִּי עִמָּכֶם, (קהלת א) כָּל הַדְּבָרִים יְגֵעִים, לֹא יָכוֹל אִישׁ לְדַבֵּר, אֲפִלּוּ דִּבְרֵי הַתּוֹרָה הֵם יְגֵעִים."],[8,"","כָּתוּב (בראשית לה) וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ וַיֵּאָבֵק אִישׁ עִמּוֹ, וְכָתוּב וַיַּרְא כִּי לֹא יָכֹל לוֹ וַיִּגַּע בְּכַף יְרֵכוֹ. וְאוֹתָהּ יָרֵךְ שֶׁהִרְוִיחַ מִיַּעֲקֹב. וְאוֹתָהּ הַיָּרֵךְ בְּחֻלְשָׁתָהּ עַד שֶׁבָּא שְׁמוּאֵל. מַה זֶּה בְּחֻלְשָׁה? שֶׁלֹּא מָשַׁךְ נְבוּאָה. כְּשֶׁבָּא שְׁמוּאֵל, נָטַל אוֹתָהּ יָרֵךְ וְהֶעֱלָה אוֹתָהּ מֵאוֹתוֹ מָקוֹם וְחָטַף אוֹתָהּ מִמֶּנּוּ, וּמֵאוֹתוֹ זְמַן הָעָבְרָה מִמֶּנּוּ וְלֹא הָיָה לוֹ חֵלֶק בַּקְּדֻשָּׁה כְּלָל."],[9,"","הַקָּדוֹשׁ בָּרוּךָ הוּא לֹא קִפַּח וְלֹא דָחָה אוֹתוֹ מִן הַכֹּל, מִשּׁוּם שֶׁשְּׁמוּאֵל נָטַל אֶת הַיָּרֵךְ שֶׁלּוֹ, אֶלָּא נָתַן לוֹ חֵלֶק אֶחָד, וּמַהוּ? נָתַן לוֹ אוֹתָהּ יָרֵךְ וּבֶטֶן שֶׁל הַסּוֹטָה תְּמוּרַת אוֹתָהּ יָרֵךְ וּבֶטֶן שֶׁהֶעֱבִיר מִמֶּנּוּ, וְלָכֵן אֶת שְׁנֵיהֶם נָתַן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לִהְיוֹת הַמָּקוֹם הַקָּדוֹשׁ פָּנוּי מִכָּל טֻמְאָה."],[10,"","וְלַנְפִּל יָרֵךְ. מַה זֶה וְלַנְפִּל? וְנָפְלָה יְרֵכָהּ הָיָה צָרִיךְ לִהְיוֹת! וְלַצְבּוֹת, וְצָבְתָה הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא כְּמִי שֶׁזּוֹרֵק עֶצֶם לַכֶּלֶב וְאוֹמֵר לוֹ: טֹל אֶת זֶה לְחֶלְקְךְ. וּמֵהַכֹּל לֹא הֵרַע לְפָנָיו אֶלָּא שֶׁגָּזְלוּ (שהוציאו) מִמֶּנּוּ יָרֵךְ, מִשּׁוּם שֶׁהוּא יָגַע וְהִתְעַיֵּף עָלֶיהָ וְהִרְוִיחַ אוֹתָהּ וְהוֹצִיאוּ אוֹתָהּ מִמֶּנּוּ. וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא הִפִּיל לוֹ אֶת הָעֶצֶם הַזּוֹ שֶׁל הַסּוֹטָה וְהוֹצִיא אוֹתוֹ לוֹ, כְּמוֹ שֶׁאָמַרְנוּ, וּבָזֶה הוּא רָוָה וְשָׂמַח."],[11,"","כָּל אוֹתָן הַמֶּרְכָּבוֹת וְהַסִּיּוּעַ שֶׁלּוֹ תָּמִיד רוֹצִים יָרֵךְ, וְהוֹלְכִים בִּתְשׁוּקָה אַחֲרֶיהָ, וּמִשּׁוּם כָּךְ הַבִּרְכַּיִם שֶׁל הָרַבָּנִים עֲיֵפִים, וְזֶה מִן זֶה. שֶׁכָּל הַתְּשׁוּקָה שֶׁלָּהֶם אַחַר הַיָּרֵךְ הִיא, וְכָל שֶׁכֵּן יָרֵךְ שֶׁל חֲכָמִים, וְכָל דָּבָר חוֹזֵר לִמְקוֹמוֹ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא גוֹרֵעַ כְּלוּם מִכָּל מַה שֶּׁצָּרִיךְ, וְלֹא רוֹצֶה שֶׁיִּתְקָרֵב לַקְּדֻשָּׁה חוּץ מֵעַמּוֹ וְגוֹרָלוֹ, חֶלְקוֹ וְנַחֲלָתוֹ. כְּמוֹ שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה, כָּךְ עוֹשִׂים יִשְׂרָאֵל לְמַטָּה וְכָךְ צָרִיךְ לַעֲשׂוֹת. וְכָךְ שָׁנִינוּ, אָסוּר לְיִשְׂרָאֵל לְלַמֵּד תּוֹרָה לְעוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, שֶׁכָּתוּב (תהליםקמז) מַגִּיד דְּבָרָיו לְיַעֲקֹב וְגוֹ', לֹא עָשָׂה כֵן לְכָל גּוֹי וְגוֹ'."]]],[["וְעַל דָּא דָּחֵי לֵיהּ יַעֲקֹב, וְדָחֵי לֵיהּ שְׁמוּאֵל, דְּלָא יְהֵא לֵיהּ חוּלָקָא בִּקְדוּשָׁא. וּבְגִין דָּא, כָּל נְטִירוּ דְּבָבוּ לְיִשְׂרָאֵל, עַל דָּא אִיהוּ. לְכַלְבָּא דְּחָטִיף עוֹפָא דַּכְיָא מִן שׁוֹקָא, וְאַיְיתֵי לֵיהּ, וְעַד לָא אִתְּבַר, אָתָא חַד בַּר נָשׁ וְחַטְפָא מִנֵּיהּ, לְבָתַר יָהִיב לֵיהּ חַד גַּרְמָא גְּרִירָא בְּלָא תּוֹעַלְתָּא.","כַּךָ לְשָׂרוֹ שֶׁל עֵשָׂו, אַפִּיקוּ לֵיהּ מֵהַהוּא בֶּטֶן, חָטִיפוּ מִנֵּיהּ הַהוּא יָרֵךְ. לְבָתַר יָהֲבוּ לֵיהּ גַּרְמָא חַד, הַהוּא בֶּטֶן וְהַהוּא יָרֵךְ דְּסוֹטָה, וְלָא אָחֳרָא. הָא גַּרְמָא, דְּקָא יָהֲבוּ לֵיהּ לְחוּלָקֵיהּ וְעַדְבֵיהּ, וְעָרַב לֵיהּ. וּבְּגִין כָּךְ, כָּל דִּינִין דְּקוּדְשָׁא בְּרִיךְ הוּא דִּינִין דִּקְשׁוֹט אִינּוּן, וּבְנִי נָשָׁא לָא יַדְעִין, וְלָא מַשְׁגִּיחִין לְקוּדְשָׁא בְּרִיךְ הוּא. וְכֻלְּהוּ בְּאֹרַח קְשׁוֹט. הִיא אַסְטִיאַת גַּרְמָהּ מִבַּעְלָהּ, כְּמָה דְאַתְּ אָמֵר (משלי ב׳:י״ז) הָעוֹזֶבֶת אַלּוּף נְעוּרֶיהָ וְגוֹ', אוּף הָכִי אִתְּתָא, כְּגַוְונָא דִּילָהּ בְּאַרְעָא.","תָּא חֲזֵי, מַאן דְּאַשְׁכַּח חַבְרָא כְּוָותֵיהּ, דְּעָבִיד כְּעוֹבָדוֹי בְּעָלְמָא, רָחִים לֵיהּ, וְאִתְדָּבַּק בַּהֲדֵיהּ, וְעָבִיד עִמֵּיהּ טִיבוּ. אֲבָל סִטְרָא אָחֳרָא לָאו הָכִי, כֵּיוָן דְּאַשְׁכַּח מַאן דְּשָׁבַק סִטְרָא דִּקְדוּשָׁה דְּקוּדְשָׁא בְּרִיךְ הוּא, וְעָבִיד כְּעוֹבָדוֹי, וְאִתְדָּבַּק בָּהּ, כְּדֵין בַּעְיָא לְשֵׁיצָאָה וּלְאַפָּקָא לֵיהּ מֵעָלְמָא. הַאי אִתְּתָא, עַבְדַת כְּעוֹבָדָהָא, וְאִתְדַּבְּקַת בָּהּ, חֲזִי מַה דְּעַבְדַת בָּהּ, וְצָבְתָה בִטְנָהּ וְנָפְלָה יְרֵכָהּ. קוּדְשָׁא בְּרִיךְ הוּא לָאו הָכִי, מַאן דְּשָׁבִיק לְסִטְרָא אָחֳרָא, וְאִתְדַּבָּק בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, כְּדֵין רָחִים לֵיהּ, וְעָבִיד לֵיהּ כָּל טִיבוּ דְּעָלְמָא. הַשְׁתָּא סָבָא אַתְקִין גַּרְמִיךְ, דְּהָא חִוְיָא אָזִיל לֵיהּ, וּבָעָא לְאִתְגָּרָא בַּהֲדָךְ, וְלָא יָכִיל.","פָּתַח וְאָמַר (קהלת א׳:ג׳) מַה יִּתְרוֹן לָאָדָם בְּכָל עֲמָלוֹ שֶׁיַּעֲמוֹל תַּחַת הַשָּׁמֶשׁ, וְכִי לָא אָתָא שְׁלמֹה אֶלָּא לְאוֹלְפָא מִלָּה דָּא. אִלּוּ אָמַר (ס\"א וכי מה אתא שלמה מלכא לאלפא במלה דא ותו אלו אמר) בַּעֲמָלוֹ שֶׁיַּעֲמוֹל יֵאוֹת, דְּהָא אִשְׁתְּאַר עָמָל, דְּאִית בֵּיהּ יִּתְרוֹן. אֶלָּא כֵּיוָן דִּכְתִיב בְּכָל עֲמָלוֹ, הָא כְּלָלָא דְּכֹלָּא, דְּלָא אִשְׁתְּאַר כְּלוּם דְּאִית בֵּיהּ יִּתְרוֹן.","אֶלָּא, לָאו לְכָל אָדָם אָמַר שְׁלֹמֹה מִלָּה דָּא, אֶלָּא אָדָם אִית בְּעָלְמָא, דְּאִיהוּ מִשְׁתַּדֵּל תָּדִיר בְּבִישׁ וּלְאַבְאָשָּׁא, וְלָא אִשְׁתָּדַּל בְּטָב אֲפִילּוּ רִגְעָא חֲדָא. וְעַל דָּא כְּתִיב עֲמָלוֹ, וְלָא כְּתִיב יְגִיעוֹ. עֲמָלוֹ: כְּמָה דְאַתְּ אָמֵר, (תהילים ז׳:י״ז) יָשׁוּב עֲמָלוֹ בְרֹאשׁוֹ. (במדבר כ״ג:כ״א) וְלא רָאָה עָמָל בְּיִשְׂרָאֵל. יְגִיעוֹ: כְּמָה דְאַתְּ אָמֵר (תהילים קכ״ח:ב׳) יְגִיעַ כַּפֶּיךָ כִּי תֹאכֵל וְגוֹ'. וּכְתִיב (בראשית ל״א:מ״ב) וְאֶת יְגִיעַ כַּפַּי רָאָה אֱלֹהִים. אֲבָל עֲמָלוֹ, כְּתִיב, (תהילים י׳:י״ד) עָמָל וָכַעַס. אִשְׁתַּדְּלוּתֵיהּ הוּא תָּדִיר לְבִישׁ, וְעַל דָּא אִיהוּ תַּחַת הַשָּׁמֶשׁ.","בְּשַׁעֲתָא דְּהַאי אָדָם אִשְׁתָּדַּל בְּבִישׁ, עַל הַאי כְּתִיב, (איוב י״ח:י״ט) לֹא נִין לוֹ וְלֹא נְכֶד בְּעַמּוֹ וְגוֹ', דְּהָא קוּדְשָׁא בְּרִיךְ הוּא בָּעֵי, דְּלָא יַעְבִּיד תּוֹלָדִין, דְּאִלְמָלֵא יַעְבֵּיד תּוֹלָדִין, הֲוָה מְטַשְׁטֵשָׁא עָלְמָא. וְעַל דָּא כְּתִיב, מַה יִּתְרוֹן לָאָדָם בְּכָל עֲמָלוֹ. וּמַאן דְּלָא יִשְׁתָּדַּל לְמֶעְבַּד תּוֹלָדִין, אִתְדָּבַּק בְּהַאי סִטְרָא דְּאָדָם בִּישָׁא וְעָאל תְּחוֹת גַּדְפּוֹי.","רוּת אָמְרָה, (רות ג׳:ט׳) וּפָרַשְׂתָּ כְנָפֶיךָ עַל אֲמָתְךָ, בְּגִין לְאִזְדַּוְּוגָא בַּהֲדֵיהּ דְּצַדִּיק, לְמֶעְבַּד תּוֹלָדִין, וְקוּדְשָׁא בְּרִיךְ הוּא פָּרִישׂ גַּדְפּוֹי עַל בַּר נָשׁ, בְּגִין לְאַפָּשָׁא בְּעָלְמָא. לְמַאן דְּלָא בָּעֵי לְמֶעְבַּד תּוֹלָדִין, בְּגַפּוֹ יָבֹא, בְּגַפּוֹ דְּהַהוּא בִּישׁ, דְּאִיהוּ אָזִיל עֲרִירִי, כְּחִוְיָא דָּא, (צ\"ה ע\"א) דְּאָזִיל יְחִידָאי. בְּגַפּוֹ יֵצֵא, (כמה דאת אמר השתא) אִיהוּ דְּלָא אִשְׁתָּדַּל לְמֶעְבַּד תּוֹלָדִין, הָא אִתְּמַר כָּל מַה דְּאִצְטְרִיךְ. (ס\"א תא חזי, דאית לאהדרא סבא, במלין קדמאין)","רִיב דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא, הָא אִתְּמַר, רִיב: דִּכְתִיב, (מיכה ו׳:א׳) קוּם רִיב אֶת הֶהָרִים. מַאי אִיהוּ. אֶלָּא, אִינּוּן טוּרִין דִּלְתַתָּא. אֲמַאי רִיב דָּא. בְּגִין דִּבְהוּ תַּלְיָא, כָּל חוֹבָא דְּעַבְדִין יִשְׂרָאֵל, לְגַבֵּי אֲבוּהוֹן דְּבִשְׁמַיָּא. מַאי טַעֲמָא. בְּגִין דְּיִשְׂרָאֵל הֲווֹ יַדְעִין שִׁמּוּשָׁא דְּכָל מַלְאָכִין עִלָּאִין דְּבִשְׁמַיָּא, וְלָא אָנִיס לְהוּ, אֲפִילּוּ שְׁמָא דְּחָד מִנַּיְיהוּ, וְכָל שִׁמּוּשָׁא דִּלְהוֹן.","וּבִתְרֵין סִטְרִין הֲוֵי טָעָאן אֲבַתְרַיְיהוּ. חַד, דַּהֲווֹ יַדְעִין לְאַמְשָׁכָא חֵילָא דִּלְהוֹן, דְּכֹּכָבַיָּא וּמַזָּלֵי בְּאַרְעָא. וְחַד, דַּהֲווֹ יַדְעֵי לְאוּמָאָה לוֹן, בְּכָל מַה דְּאִצְטְרִיכוּ. וְעַל דָּא בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד בְּהוּ רִיב וְדִינָא. וְכֵיוָן דִּבְּהוֹן לֶהֱוֵי רִיב וְדִינָא, כָּל שִׁלְשׁוּלָא נָפַל דְּהָא לָא יֶהֱוֵי בֵּיהּ תּוֹעַלְתָּא. וּבְגִין כַּךְ, קוּם רִיב וְגוֹ'. וְתִשְׁמַעְנָה הַגְּבָעוֹת קוֹלֶךָ. מַאן גִּבְעוֹת. אִלֵּין אִינּוּן אִמָּהוֹת, (ק\"ט ע\"ב, קפ\"ט ע\"ב) דַּרְגִּין דְּאִקְרוּן (תהילים מ״ה:ט״ו) בְּתוּלוֹת אַחֲרֶיהָ וְגוֹ', וּבְגִין כַּךְ וְתִשְׁמַעְנָה הַגְּבָעוֹת קוֹלֶךָ. דְּהָכִי הֲווֹ עַבְדֵי יִשְׂרָאֵל, עַד דְּאִשְׁתַּתָּפוּ בְּדַרְגִּין תַּתָּאִין. תָּא חֲזֵי, דְּאִית לְאָהַדְּרָא סָבָא, בְּמִלִּין קַדְמָאִין,"],[[0,"ועל דא דחי ליה וכו':","וע\"כ דחה אותו יעקב ודחה אותו שמואל, שלא יהיה לו חלק בקדושה. ומשום זה כל נטירת שנאה לישראל הוא על זה. בדומה לכלב שחטף עוף טהור מן השוק והביא אותו. ומטרם שהספיק לשברו, בא אדם אחד וחטפו ממנו, אח\"כ נתן לו עצם אחד נגרר בלא תועלת."],[1,"כך לשרו של עשו וכו':","כך לשרו של עשו, הוציאו אותו מבטן ההוא, חטפו ממנו ירך ההוא, ואח\"כ נתנו לו עצם אחד, דהיינו בטן ההוא וירך ההוא של הסוטה, ולא אחר, זהו העצם שנתנו לו לחלקו ולגורלו וערב לו. ומשום זה כל הדינים של הקב\"ה, הם דינים של אמת, ובני אדם אינם יודעים ואינם משגיחים אל הקב\"ה. הכל הוא בדרך אמת. היא, הס\"א, השטתה את עצמה מבעלה, כש\"א, העוזבת אלוף נעוריה. אף כן האשה שהיא כמותה בארץ, דהיינו הסוטה, נמסרת לה."],[2,"ת\"ח מאן דאשכח וכו':","בוא וראה מי שמוצא את חברו כמוהו, שעושה כמעשיו בעולם, אוהב אותו ומתדבק בו ועושה עמו חסד. אבל הסטרא אחרא אינו כן, כיון שמוצא מי שעוזב את צד הקדושה של הקב\"ה, ועושה כמעשיו ומתדבק בו, אז הוא רוצה לכלותו ולהוציאו מן העולם. אשה זו עשתה כמעשיו והתדבקה בו, ראה מה שעשה בה, וצבתה בטנה ונפלה ירכה. הקב\"ה אינו כן, מי שעוזב את הס\"א ומתדבק בהקב\"ה, אז אוהב אותו, ועושה לו כל החסד שבעולם. אמר לעצמו, עתה זקן התקן את עצמך, כי הנחש הולך לו ורוצה להתגרות בך ואינו יכול."],[3,"פתח ואמר וכו':","פו\"א, מה יתרון לאדם בכל עמלו שיעמול תחת השמש. שואל, וכי לא בא שלמה אלא ללמד דבר זה. אלו אמר בעמלו שיעמול, היה יפה, כי היה נשאר עמל שיש בו יתרון, אבל כיון שכתוב, בכל עמלו, הרי זה כלל הכל, שלא נשאר כלום שיש בו יתרון."],[4,"אלא לאו לכל וכו':","ומשיב, אלא לא לכל אדם אמר שלמה דבר זה. אלא יש אדם בעולם שהוא עוסק תמיד ברע ולהרע, ואינו עוסק בטוב אפילו רגע אחד. וע\"כ כתוב, עמלו, ולא כתוב יגיעו, כי עמלו פירושו במעשים רעים, כמש\"א ישוב עמלו בראשו. ולא ראה עמל בישראל. אבל יגיעו, יורה על מעשים טובים, כמש\"א, יגיע כפיך כי תאכל וגו'. וכתוב, ואת יגיע כפי ראה אלקים. אבל עמלו, כתוב, עמל וכעס, כי השתדלותו הוא תמיד לרע. וע\"כ אמר, מה יתרון וגו' תחת השמש. שהוא תחת השמש, שיורה על הס\"א הנמצא תחת השמש."],[5,"בשעתא דהאי אדם וכו':","בשעה שאדם הזה עוסק ברע, על זה כתוב, לא נין לו ולא נכד בעמו, כי הקב\"ה רוצה שלא יעשה תולדות, שאם היה עושה תולדות היה מעכיר את העולם. וע\"כ כתוב מה יתרון לאדם בכל עמלו. ומי שאינו עוסק לעשות תולדות נתדבק בצד הזה של אדם הרע ונכנס תחת כנפיו."],[6,"רות אמרה וכו':","רות אמרה, ופרשת כנפיך על אמתך, כדי להזדווג עם הצדיק לעשות תולדות. והקב\"ה פורש כנפיו על אדם כדי שיפרה וירבה בעולם. אבל למי שאינו רוצה לעשות תולדות, \u0003בגפו יבוא,\u0004 בגף של אדם הרע ההולך ערירי כנחש הזה ההולך יחידי. \u0003בגפו יצא,\u0004 הוא שלא השתדל לעשות תולדות, וכבר למדנו בזה כל מה שצריך. (לעיל אות רכ\"א)."],[7,"ריב דעבד קב\"ה וכו':","ריב שעשה הקב\"ה הרי למדנו שהריב הוא, שכתוב, קום ריב את ההרים. מה הם. אלא הם ההרים שלמטה, שהם נה\"י. למה ריב הזה. הוא משום שבהם תלוי כל העון שעושים ישראל לאביהם שבשמים. מהו הטעם. משום שישראל היו יודעים השמוש, דהיינו ההשבעות, של כל המלאכים שבשמים. ולא היה חסר להם אפילו שם אחד מהם, וכל השמוש שלהם."],[8,"ובתרין סטרין הוי וכו':","ובשני צדדים היו זונים אחריהם. א', שהיו יודעים להמשיך הכחות של הככבים והמזלות בארץ. ואחד, שהיו יודעים להשביע אותם בכל מה שצריכים. ועל זה רצה הקב\"ה לעשות בהם, בהרים, ריב ודין, כי כל המלאכים והשרים העליונים מקבלים כחם מנה\"י אלו הנקראים הרים, וכיון שבהם יהיו ריב ודין, ויחלשו אורותיהם, כל השלשלת, דהיינו המלאכים והשרים שבבי\"ע, נופלת כי לא יהיה בהם תועלת. מחמת שפסק כחם. ומשום זה כתוב, קום ריב וגו'. \u0003ותשמענה הגבעות קולך:\u0004 שואל, מי הם גבעות. ומשיב, אלו הן אמהות, דהיינו ז' היכלות שבבריאה, שהן מדרגות הנקראות בתולות אחריה וגו' דהיינו שבע הנערות המשמשות להמלכות. שכך היו עושים ישראל עד שהשתתפו במדרגות התחתונות. אמר לעצמו, בוא וראה זקן, שצריכים לחזור לדברים הקודמים (כצ\"ל)."]],[[0,"","וְלָכֵן דָּחָה אוֹתוֹ יַעֲקֹב וְדָחָה אוֹתוֹ שְׁמוּאֵל, שֶׁלֹּא יִהְיֶה לוֹ חֵלֶק בַּקְּדֻשָּׁה. וּמִשּׁוּם כָּךְ כָּל שְׁמִירַת הַשִּׂנְאָה לְיִשְׂרָאֵל הִיא עַל כָּךְ. לְכֶלֶב שֶׁחָטַף עוֹף טָהוֹר מֵהַשּׁוּק וְהֵבִיא אוֹתוֹ, וְטֶרֶם שֶׁנִּשְׁבַּר בָּא אִישׁ אֶחָד וְחָטַף אוֹתוֹ מִמֶּנּוּ, וְאַחַר כָּךְ נָתַן לוֹ עֶצֶם נִגְרֶרֶת אַחַת בְּלִי תוֹעֶלֶת."],[1,"","כָּךָ לְשָׂרוֹ שֶׁל עֵשָׂו הוֹצִיאוּ אוֹתוֹ מֵאוֹתָהּ הַבֶּטֶן, חָטְפוּ מִמֶּנּוּ אֶת אוֹתָהּ הַיָּרֵךְ, אַחַר כָּךְ נָתְנוּ לוֹ עֶצֶם אַחַת - אוֹתָהּ הַבֶּטֶן וְאוֹתָהּ הַיָּרֵךְ שֶׁל הַסּוֹטָה, וְלֹא אַחֵר. זוֹ הָעֶצֶם שֶׁנָּתְנוּ לְחֶלְקוֹ וּלְגוֹרָלוֹ וְעָרְבָה לוֹ. וּמִשּׁוּם כָּךְ כָּל דִּינֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הֵם דִּינֵי אֱמֶת, וּבְנֵי אָדָם לֹא יוֹדְעִים וְלֹא מַשְׁגִּיחִים לַקָּדוֹשׁ בָּרוּךְ הוּא, וְכֻלָּם בְּדֶרֶךְ אֱמֶת. הִיא הִסְטְתָה אֶת עַצְמָהּ מִבַּעְלָהּ, כְּמוֹ שֶׁנֶּאֱמַר (משלי ב) הַעֹזֶבֶת אַלּוּף נְעוּרֶיהָ וְגוֹ'. אַף כָּךְ הָאִשָּׁה כְּגוֹן שֶׁלָּהּ בָּאָרֶץ."],[2,"","בֹּא וּרְאֵה, מִי שֶׁמּוֹצֵא חָבֵר כְּמוֹתוֹ שֶׁעוֹשֶׂה כְמַעֲשָׂיו בָּעוֹלָם, אוֹהֵב אוֹתוֹ וְנִדְבָּק עִמּוֹ וְעוֹשֶׂה עִמּוֹ טוֹב. אֲבָל הַצַּד הָאַחֵר לֹא כָּךְ; כֵּיוָן שֶׁמּוֹצֵא מִי שֶׁעָזַב אֶת צַד הַקְּדֻשָּׁה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְעוֹשֶׂה כְמַעֲשָׂיו וְנִדְבָּק בּוֹ, אָז הוּא רוֹצֶה לְכַלּוֹתוֹ וּלְהוֹצִיאוֹ מִן הָעוֹלָם. הָאִשָּׁה הַזּוֹ עָשְׂתָה כְמַעֲשָׂיו וְנִדְבְּקָה בּוֹ, רְאֵה מַה הוּא עָשָׂה בָּהּ - וְצָבְתָה בִטְנָהּ וְנָפְלָה יְרֵכָהּ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא אֵינוֹ כָּךְ; מִי שֶׁעוֹזֵב אֶת הַצַּד הָאַחֵר וְנִדְבָּק בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, אָז אוֹהֵב אוֹתוֹ וְעוֹשֶׂה לוֹ כָּל טוּב שֶׁבָּעוֹלָם. עַכְשָׁו, זָקֵן, תַּקֵּן עַצְמְךְ, שֶׁהֲרֵי הַנָּחָשׁ הָלַךְ לוֹ וְרוֹצֶה לְהִתְגָּרוֹת בְּךְ וְלֹא יָכוֹל."],[3,"","פָּתַח וְאָמַר, (קהלת א) מַה יִּתְרוֹן לָאָדָם בְּכָל עֲמָלוֹ שֶׁיַּעֲמֹל תַּחַת הַשָּׁמֶשׁ. וְכִי לֹא בָא שְׁלֹמֹה אֶלָּא לְלַמֵּד דָּבָר זֶה? אִלּוּ אָמַר (וכי מה בא שלמה המלך ללמד בדבר זה, ' ועוד, אלו אמר) בַּעֲמָלוֹ שֶׁיַּעֲמֹל - יָפֶה, שֶׁהֲרֵי נִשְׁאָר עָמָל שֶׁיֵּשׁ בּוֹ יִתְרוֹן. אֶלָּא כֵּיוָן שֶׁכָּתוּב בְּכָל עֲמָלוֹ, הֲרֵי הַכְּלָל שֶׁל הַכֹּל - שֶׁלֹּא נִשְׁאָר כְּלוּם שֶׁיֵּשׁ בּוֹ יִתְרוֹן."],[4,"","אֶלָּא שֶׁלֹּא לְכָל אָדָם אָמַר שְׁלֹמֹה אֶת הַדָּבָר הַזֶּה, אֶלָּא יֵשׁ אָדָם בָּעוֹלָם שֶׁמִּשְׁתַּדֵּל תָּמִיד בְּרַע וּלְהָרַע, וְלֹא מִשְׁתַּדֵּל בְּטוֹב אֲפִלּוּ רֶגַע אֶחָד, וְעַל זֶה כָּתוּב עֲמָלוֹ וְלֹא כָתוּב יְגִיעוֹ. עֲמָלוֹ - כְּמוֹ שֶׁנֶּאֱמַר (תהלים ס) יָשׁוּב עֲמָלוֹ בְרֹאשׁוֹ. וְלֹא רָאָה עָמָל בְּיִשְׂרָאֵל. יְגִיעוֹ - כְּמוֹ שֶׁנֶּאֱמַר (שם קכח) יְגִיעַ כַּפֶּיךְ כִּי תֹאכֵל וְגוֹ'. וְכָתוּב (בראשית לא) וְאֶת יְגִיעַ כַּפַּי רָאָה אֱלֹהִים. אֲבָל עֲמָלוֹ, כָּתוּב (תהלים י) עָמָל וָכַעַס. הִשְׁתַּדְּלוּתוֹ הִיא תָּמִיד לְרַע, וְעַל כָּךְ הוּא תַּחַת הַשָּׁמֶשׁ."],[5,"","בְּשָׁעָה שֶׁהָאָדָם הַזֶּה מִשְׁתַּדֵּל בְּרַע, עַל זֶה כָּתוּב (איוב יח) לֹא נִין לוֹ וְלֹא נֶכֶד בְּעַמּוֹ וְגוֹ', שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה שֶׁלֹּא יַעֲשֶׂה תוֹלָדוֹת, שֶׁאִלְמָלֵא יַעֲשֶׂה תוֹלָדוֹת, הָיָה מַחֲרִיב אֶת הָעוֹלָם, וְעַל זֶה כָּתוּב מַה יִּתְרוֹן לָאָדָם בְּכָל עֲמָלוֹ. וּמִי שֶׁלֹּא מִשְׁתַּדֵּל לַעֲשׂוֹת תּוֹלָדוֹת, נִדְבָּק בַּצַּד הַזֶּה שֶׁל אָדָם רַע, וְנִכְנָס תַּחַת כְּנָפָיו."],[6,"","רוּת אָמְרָה, (רות ג) וּפָרַשְׂתָּ כְנָפֶיךְ עַל אֲמָתְךְ, כְּדֵי לְהִזְדַּוֵּג עִם הַצַּדִּיק, לַעֲשׂוֹת תּוֹלָדוֹת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא פּוֹרֵס כְּפָנָיו עַל בֶּן אָדָם כְּדֵי לְהִתְרַבּוֹת בָּעוֹלָם, וּמִי שֶׁלֹּא רוֹצֶה לַעֲשׂוֹת תּוֹלָדוֹת, בְּגַפּוֹ יָבֹא - בְּגַפּוֹ שֶׁל אוֹתוֹ רַע, שֶׁהוּא הוֹלֵךְ עֲרִירִי כַּנָּחָשׁ הַזֶּה שֶׁהוֹלֵךְ יְחִידִי. בְּגַפּוֹ יֵצֵא - כְּמוֹ שֶׁנִּתְבָּאֵר, הוּא שֶׁלֹּא הִשְׁתַּדֵּל לַעֲשׂוֹת תּוֹלָדוֹת, הֲרֵי נִתְבָּאֵר כָּל מַה שֶּׁצָּרִיךְ. (בא וראה שיש לחזר זקן בדברים הראשונים)."],[7,"","הָרִיב שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא הֲרֵי נֶאֱמַר, רִיב - שֶׁכָּתוּב (מיכה ו) קוּם רִיב אֶת הֶהָרִים. מִי הֵם? אֶלָּא אוֹתָם הָרִים שֶׁלְּמַטָּה. לָמָּה הָרִיב הַזֶּה? מִשּׁוּם שֶׁבָּהֶם תְּלוּיִים כָּל הַחֲטָאִים שֶׁעוֹשִׂים יִשְׂרָאֵל לַאֲבִיהֶם שֶׁבַּשָּׁמַיִם. מָה הַטַּעַם? כִּי יִשְׂרָאֵל הָיוּ יוֹדְעִים שִׁמּוּשׁ שֶׁל כָּל הַמַּלְאָכִים הָעֶלְיוֹנִים שֶׁבַּשָּׁמַיִם, וְלֹא נֶעְלָם מֵהֶם אֲפִלּוּ שְׁמוֹ שֶׁל אֶחָד מֵהֶם, וְכָל הַשִּׁמּוּשׁ שֶׁלָּהֶם."],[8,"","וּבִשְׁנֵי צְדָדִים הָיוּ טוֹעִים אַחֲרֵיהֶם. אֶחָד - שֶׁהָיוּ יוֹדְעִים לִמְשֹׁךְ אֶת כֹּחָם שֶׁל הַכּוֹכָבִים וְהַמַּזָלוֹת לָאָרֶץ. וְאֶחָד - שֶׁהָיוּ יוֹדְעִים אֵיךְ לְהַשְׁבִּיעָם בְּכָל מַה שֶּׁהִצְטָרְכוּ, וְלָכֵן רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת בָּהֶם רִיב וְדִין. וְכֵיוָן שֶׁבָּהֶם יִהְיֶה רִיב וְדִין, כָּל הַשַּׁלְשֶׁלֶת נוֹפֶלֶת, שֶׁהֲרֵי לֹא תִהְיֶה בּוֹ תּוֹעֶלֶת, וּמִשּׁוּם כָּךְ קוּם רִיב וְגוֹ'. וְתִשְׁמַעְנָה הַגְּבָעוֹת קוֹלֶךְ, מִי הַגְּבָעוֹת? אֵלֶּה הֵן הָאִמָּהוֹת, הַדְּרָגוֹת שֶׁנִּקְרָאוֹת בְּתוּלוֹת אַחֲרֶיהָ וְגוֹ', וּמִשּׁוּם כָּךְ וְתִשְׁמַעְנָה הַגְּבָעוֹת קוֹלֶךְ."]]],[["דְּהָכִי הֲווֹ עַבְדֵי יִשְׂרָאֵל, עַד דְּאִשְׁתַּתָּפוּ בְּדַרְגִּין תַּתָּאִין יָרֵךְ דְּקָא אַמָרָן, סַגִּי אַתְקִיפוּ לוֹן יִשְׂרָאֵל, בְּהַהוּא יָרֵךְ. מָרְדְּכַי הֲוָה אַחְמֵי לְהַהוּא רָשָׁע דְּהָמָן הַהוּא יָרֵךְ דִּילֵיהּ, וְעַל דָּא הֲוָה רָגִיז, מִלָּה דְּאִתְחָזֵי לֵיהּ, וְאִיהוּ אַרְגִּיז לֵיהּ בַּהֲדֵיהּ. חָמוּ חַבְרַיָּיא, מַה כְּתִיב, (בראשית כ״ז:ט״ו) וַתִּקַּח רִבְקָה אֶת בִּגְדֵי עֵשָׂו בְּנָהּ הַגָּדֹל הַחֲמֻדֹת וְגוֹ'. בְּאִלֵּין לְבוּשִׁין דִּילֵיהּ, גָּזַל דִּילֵיהּ, וְאַפִּיק לֵיהּ מִכָּל בִּרְכָּאן דִּילֵיהּ, וּמִבְּכִרוּתָא.","וּבְגִין כַּךְ, עִילָה דְּקָא אַשְׁכָּחוּ רְתִיכִין דִּילֵיהּ, לְרַבָּנָן, אִיהוּ דְּחוּפְיָא דִּלְהוֹן לְמָאנֵי דְּרַבָּנָן תָּדִיר. (קי\"א) לְיַרְכִין דִּלְהוֹן. וּלְמָאנִין דִּלְהוֹן. וְאִלֵּין תְּרֵין מִלִּין דִּסְטָר אַחֲרָא הָווֹ, וְכָל דָּא בְּגִין דְּגָזְלוּ לוֹן מִנֵּיהּ. לֵית לְהוּ עִילָה אֶלָּא לְרַבָּנָן. וּבְגִין כַּךְ, הָנֵי מָאנִי דְּרַבָּנָן דְּקָא בָּלוּ מֵחוּפְיָא דִּלְהוֹן אִיהוּ, וְהָנִי בָּרְכִי דְּשַׁלְהֵי, מִנַּיְיהוּ הוּא וַדַּאי. וּמִדִּלְהוֹן הָווֹ, וּמִנְּהוֹן נַטְלֵי עִילָה, וּמִמַּה דַּהֲווֹ מִנַּיְיהוּ. בָּעָאן לְרַבָּנָן, דְּאִינּוּן כְּלָלָא דְּהַהוּא יוֹשֵׁב אֹהָלִים, וְעַל דָּא לֵית עִילָה בְּלָא עִילָה, וְעַל דָּא לֵית מִלָּה, בְּלָא דִּינָא, וְכָל מִלָּה תָּב לְאַתְרֵיהּ.","שְׁלמֹה אָמַר, (קהלת ד׳:א׳) וְשַׁבְתִּי אֲנִי וָאֶרְאֶה אֶת כָּל הָעֲשׁוּקִים אֲשֶׁר נַעֲשִׂים תַּחַת הַשָּׁמֶשׁ וְהִנֵּה דִּמְעַת הָעֲשׁוּקִים וְאֵין לָהֶם מְנַחֵם וּמִיַּד עוֹשְׁקֵיהֶם כֹּחַ וְאֵין לָהֶם מְנַחֵם. הַאי קְרָא אַרְמִיזְנָא בֵּיהּ, (קי\"א ע\"ב) וְאִתְּמַר. אֲבָל שַׁבְתִּי אֲנִי, וְכִי מֵאָן אֲתָר תָּב שְׁלֹמֹה. אִי נִימָא, לְבָתַר דְּאָמַר מִלָּה דָּא, תָּב כְּמִלְקַדְּמִין, וְאָמַר מִלָּה אָחֳרָא, יֵאוֹת אֲבָל שַׁבְתִּי וָאֶרְאֶה (ויקרא רל\"ג ע\"א).","תַּמָּן תָּנֵינָן, בְּכָל יוֹמָא הֲוָה אַקְדִּים שְׁלֹמֹה בְּצַפְרָא, וַהֲוֵי שַׁוֵּי אַנְפּוֹי לִסְטַר מִזְרָח, וְחָמֵי מַה דְּחָמֵי, וּלְבָתַר תָּב לִסְטַר דָּרוֹם, וְחָמֵי מַה דְּחָמֵי וְהָדָר תָּב לִסְטַר צָפוֹן, וְקָאִים תַּמָּן. מָאִיךְ עֵינוֹי וְזָקִיף רֵישֵׁיהּ.","בְּהַאי שַׁעֲתָא, הָא עַמּוּדָא דְּאֶשָּׁא וְעַמּוּדָא דַּעֲנָנָא, הֲווֹ אַתְיָין, וְעַל הַהוּא עַמּוּדָא דַּעֲנָנָא, הֲוָה אָתֵי נִשְׁרָא חֲדָא. וְהַהוּא נִשְׁרָא הוּא רַבְרְבָא וְתַקִּיף, וְכֵן הֲוָה אָתֵי, גַּדְפָּא יְמִינָא, עַל גַּבֵּי עַמּוּדָא דְּאֶשָּׁא, וְגוּפָא וְגַדְפָּא שְׂמָאלָא, עַל גַּבֵּי עַמּוּדָא דַּעֲנָנָא. וְהַהוּא נִשְׁרָא הֲוִי מַיְיתֵי תְּרֵין טַרְפִין בְּפוּמָהָא, אָתָא עַמּוּדָא דַּעֲנָנָא, וְעַמּוּדָא דְּאֶשָּׁא, וְהַהוּא נִשְׁרָא עָלַיְיהוּ, וְסַגְדִּין לְקָמֵיהּ דְּשְׁלֹמֹה מַלְכָּא.","אָתָא נִשְׁרָא, וּמָאִיךְ לְקָמֵיהּ, וְיָהִיב לֵיהּ אִינּוּן טַרְפִין, נָטִיל לוֹן שְׁלמֹה מַלְכָּא, וַהֲוָה מֵרִיחַ בְּהוּ, וַהֲוָה יָדַע בְּהוֹן סִימָן, וְאָמַר דָּא אִיהוּ דְּנוֹפֵל, וְדָא אִיהוּ דִּגְלוּי עֵינָיִם. בְּשַׁעֲתָא דִּתְרֵין טַרְפִין הָווֹ, הֲוָה יָדַע דְּתַרְוַויְיהוּ, (בלק ר\"ח ע\"א) נוֹפֵל וּגְלוּי עֵינָיִם בָּעָאן לְאוֹדָעָא לֵיהּ מִלִּין.","מַה עָבִיד, חָתִים כֻּרְסְיֵיהּ בְּגוּשְׁפַּנְקָא, דְּהֲוָה חָקִיק בֵּיהּ שְׁמָא קַדִּישָׁא. וְאִיהוּ נָטִיל עִזְקָא דְּחָקִיק עָלֵיהּ שְׁמָא קַדִּישָׁא, וְסָלִיק לְאִגְרָא, וְרָכִיב עַל הַהוּא נִשְׁרָא, וְאָזִיל לֵיהּ. וְהַהוּא נִשְׁרָא, הֲוָה מִסְתָּלַּק, לְרוּם עֲנָנִין, וּבְכָל אֲתָר דְּאִיהוּ עָבַר, הֲוָה אִתְחֲשָׁךְ נְהוֹרָא. חַכִּימֵי דַּהֲווֹ בְּהַהוּא אֲתָר דְּאִתְחֲשָׁךְ נְהוֹרָא, הֲווֹ יַדְעֵי, וַהֲווּ אַמְרֵי, שְׁלֹמֹה מַלְכָּא הָא אָזִיל, וְאַעְבַּר הָכָא, וְלָא יַדְעֵי לְאָן אֲתָר הֲוָה אָזִיל. טִפְּשִׁין דַּהֲווֹ תַּמָּן, הֲווֹ אַמְרֵי, עֲנָנִין הֲווֹ אִינּוּן, דְּקָא אַזְלֵי וְחָשִׁיךְ עָלְמָא.","גָּבַהּ נִשְׁרָא בַּהֲדֵיהּ, וּפָרַח אַרְבַּע מְאָה פַּרְסִין, עַד דְּמָטָא לְטוּרֵי חָשׁוֹךְ. וְתַמָּן אִיהוּ תַּרְמוּד בַּמִּדְבָּר בְּהָרִים, וְאִיהוּ נָחִית תַּמָּן. זָקִיף רֵישֵׁיהּ, וְחָמֵי טוּרָא חָשׁוֹךְ, וַהֲוָה יָדַע תַּמָּן כָּל מַה דְּאִצְטְרִיךְ. וַהֲוָה יָדַע דְּתַמָּן יֵעוּל. הֲוָה רָכִיב עַל נִשְׁרָא כְּמִלְּקַדְמִין, וְטָאס וְעָאל לְגוֹ טוּרִין, עַד הַהוּא אֲתָר דְּזֵיתָא תַּמָן, קָרָא בְּחֵילָא וְאָמַר, (ישעיהו כ״ו:י״א) יְיָ' רָמָה יָדְךָ בַּל יֶחזָיוּן וְגוֹ'.","עָאל תַּמָּן, עַד דְּקָרִיב לְהַהוּא אֲתָר, שַׁוֵּי עִזְקָא קָמַיְיהוּ, וְקָרִיב, וְתַמָּן הֲוָה יָדַע כָּל מַה דְּבָעֵי מֵאִינּוּן חָכְמְתָן נוּכְרָאִין, דְּבָעֵי לְמִנְדַּע. כֵּיוָן דַּהֲווֹ אַמְרִין לֵיהּ כָּל מַה דְּבָעֵי, כְּדֵין הֲוָה רָכִיב עַל הַהוּא נִשְׁרָא, וְתָב לְאַתְרֵיהּ. כֵּיוָן דְּהֲוָה יָתִיב עַל כּוּרְסְיֵיהּ, אִתְיָישַּׁב בְּדַעְתֵּיהּ וַהֲוָה מְמַלֵּל בְּדַעְתֵּיהּ מִלִּין דְּחָכְמְתָא יַקִּירָא. בְּהַהִיא שַׁעֲתָא הֲוָה אָמַר, וְשַׁבְתִּי אֲנִי וָאֶרְאֶה, שַׁבְתִּי וַדַּאי מֵהַהוּא אָרְחָא, שַׁבְתִּי מֵהַהִיא חָכְמְתָא, וְאִתְיְישָׁבִת בְּלִבָּאי וּבְדַעְתָּאי. וּכְדֵין וָאֶרְאֶה אֶת כָּל הָעֲשׁוּקִים. וְכִי זְעִירִין אִינּוּן בְּעָלְמָא דְאִיהוּ אֲמָר אֶת כָּל הֲעַשׁוּקִים"],[[0,"ירך דקא אמרן וכו':","ירך שאמרנו, הרבה התקיפו ישראל לס\"א בירך הזה. מרדכי היה מראה לאותו רשע המן, ירך ההוא שלו. (כמ\"ש בתרגום אסתר ה' ח') ועל זה היה כועס, שהוא דבר הראוי לו, שהרויחו מיעקב כנ\"ל, והוא, מרדכי, הכעיס אותו עמו. שהראה לו שכבר חטפו אותו ממנו, כנ\"ל. ראו חברים, מה כתוב, ותקח רבקה את בגדי עשו בנה הגדול החמודות וגו'. באלו הלבושים שלו גזל יעקב אותו, והוציאו מכל הברכות שלו ומן הבכרה."],[1,"ובגין כך עילה וכו':","ומשום זה תואנה מצאו המרכבות שלו, של הס\"א, לרבנן, והוא החיכוך שלהם שמחככים בבגדי רבנן תמיד. והיינו לירכים ולבגדיהם, כי אלו ב' דברים היו של הס\"א. וכל כעסם הוא מפני שגזלו אותם ממנו, ע\"כ, אין להם תואנה אלא לרבנן. ומשום זה אלו הבגדים של רבנן, שבלו, הוא מחיכוך שלהם, ואלו הברכים שעיפו מהם הוא ודאי. ומשלהם היו וע\"כ לוקחים תואנה מהם, מרבנן, וממה שהוא מהם. ומבקשים מרבנן משום שהם הכלל של יושב אהלים ההוא, יעקב. וע\"כ אין עלילה בלי סבה, וע\"כ אין דבר בלא דין ומשפט, וכל דבר חוזר למקומו."],[2,"שלמה אמר ושבתי וגו':","שלמה אמר, ושבתי אני ואראה את כל העשוקים וגו'. מקרא זה רמזנו בו, וכבר למדנו. (לעיל אות ש\"כ). אבל הכתוב אומר, ושבתי אני, וכי מאיזה מקום חזר שלמה. ואם תאמר, שהפירוש הוא, אחר שאמר דבר זה חזר כמקודם ואמר דבר אחר, וע\"כ נאמר ושבתי. יפה הוא. אבל היה לו לומר שבתי ואראה, למה אומר ושבתי אני."],[3,"תמן תנינן בכל וכו':","שם למדנו, בכל יום היה שלמה משכים בבקר, והיה שם פניו לצד מזרח, שהוא ת\"ת וקו אמצעי, וראה מה שראה. ואח\"כ חזר לצד דרום, שהוא חסד וקו ימין, וראה מה שראה. ואח\"כ חזר לצד צפון, שהוא גבורה, וקו שמאל, ועמד שם. השפיל עיניו וזקף את ראשו."],[4,"בהאי שעתא הא וכו':","בשעה ההוא, עמוד האש ועמוד הענן היו באים, ועל עמוד הענן ההוא בא נשר אחד. ונשר ההוא היה גדול וחזק. וכך היה בא הנשר, כנף הימין היה על עמוד האש, והגוף וכנף השמאל על עמוד הענן. ונשר ההוא היה מביא שני עלים בפיו. בא עמוד הענן ועמוד האש ונשר ההוא עליהם ומשתחווים לפני שלמה המלך."],[5,"אתא נשרא ומאיך וכו':","בא הנשר והרכין לפניו ונתן לו עלים האלו. לקחם שלמה המלך והיה מריח בהם, והיה יודע בהם סימן, ואמר זה הוא של \u0003נופל,\u0004 וזה הוא של \u0003גלוי עינים.\u0004 בשעה שהיו שני עלים, היה יודע, ששניהם, נופל וגלוי עינים, רוצים להודיע לו דברים."],[6,"מה עביד חתם וכו':","מה עשה, חתם את הכסא שלו בחותם שהיה חקוק בו השם הקדוש. והוא לקח טבעת שהיה חקוק עליה השם הקדוש ועלה לעליה, ורכב על אותו הנשר והלך לו. ונשר ההוא היה מתעלה לרום עננים, ובכל מקום שעבר היה נחשך האור. החכמים שהיו באותו מקום שנחשך האור, היו יודעים, והיו אומרים, שלמה המלך הולך ועובר כאן. ולא יודעים לאיזה מקום הולך, הכסילים שהיו שם היו אומרים עננים הם שהולכים ומחשיכים העולם."],[7,"גבה נשרא בהדיה וכו':","הנשר הגביה עוף עמו, ופרח ד' מאות פרסאות, עד שהגיע להרי חושך. ושם הוא תרמוד במדבר בהרים. והוא ירד שם. נשא את ראשו, וראה הרי החשך, והיה יודע שם כל מה שצריך. והיה יודע ששם צריך להכנס. היה רוכב על הנשר כמקודם, ופרח ונכנס לתוך ההרים עד אותו מקום ששם הזית. קרא בכח ואמר, ה' רמה ידך בל יחזיון."],[8,"עאל תמן עד וכו':","נכנס שם עד שקרב לאותו מקום של הזית שם לפניהם את הטבעת, וקרב, ושם היה יודע כל מה שרצה מאלו החכמות הזרות שרצה לדעת. כיון שאמרו לו כל מה שרצה, אז היה רוכב על אותו הנשר ושב למקומו. כיון שישב על כסאו, נתישב בדעתו, והיה מדבר בדעתו דברי חכמה היקרה. בשעה ההיא אמר, ושבתי אני ואראה. \u0003שבתי\u0004 ודאי מאותו הדרך, \u0003שבתי\u0004 מאותה החכמה, ונתישבה בלבי ובדעתי. ואז ואראה את כל העשוקים."],[8,"","פנימיות המאמר. הסבא מבאר כאן סדר קבלת המוחין דחכמה, ששלמה המלך, שנאמר עליו ויחכם מכל האדם, המשיכם בכל יום ויום. ומתוך שגילוי החכמה הוא רק במלכות שנקראת חכמה תתאה, וזמן שליטתה הוא בלילה, ע\"כ אומר, \u0003אקדים שלמה בצפרא,\u0004 דהיינו בעוד שהיה חושך. ויחד תחילה הג' קוין, המכונים דרום צפון מזרח, זה בזה, ותחילה יחד את ג' הקוין שבקו האמצעי, וז\"ש \u0003והוי שוי אנפוי לסטר מזרח,\u0004 שהוא קו האמצעי, \u0003וחמי מה דחמי,\u0004 דהיינו שהמשיך שם החכמה המכונה ראיה. \u0003ולבתר תב לסטר דרום,\u0004 שהוא קו ימין \u0003וחמי מה דחמי,\u0004 דהיינו שהמשיך שם החכמה המכונה ראיה. \u0003והדר תב לסטר צפון,\u0004 שהוא קו השמאל, ששם מקור יציאת החכמה, \u0003וקאים תמן,\u0004 לקבל חכמה, ונודע שמסבת הכרעת קו האמצעי, את ב' הקוין ימין ושמאל, נעלמו הג\"ר דחכמה, ונשארו רק הו\"ק דחכמה. וז\"ש \u0003מאיך עינוי,\u0004 שהשפיל העינים, שה\"ס חכמה, דהיינו שלא לקבל מג\"ר דחכמה, \u0003וזקיף רישיה,\u0004 והמשיך בחינת ראש, דהיינו רק ראש מו\"ק דחכמה, וע\"כ ביאר הסבא בדרך כלל. ועתה מבאר הפרטים הנוהגים בקבלת החכמה מצד השמאל."],[8,"","ונודע שמקום יציאת אור החכמה הוא בבינה, דהיינו אחר שחזרה להיות חכמה בסוד נקודת השורק, שהוא קו שמאל שלה. (ועי' בראשית א' דף ט\"ו ד\"ה ההוא, סוד ג' הנקודות) אבל מקום הגילוי של החכמה אינו אלא בהמלכות, שע\"כ נקראת חכמה תתאה. (כנ\"ל בראשית א' דף קע\"ו, ד\"ה ועוד כמה). וגילוי הזה הוא בב' קוין ימין ושמאל שבמלכות, הנקראים עמוד הענן ועמוד האש (כנ\"ל בשלח אות קנ\"ח) והבינה נקראת נשר גדול וחזק. כי נשר סתם הוא ז\"א."],[8,"","וזה אמרו, \u0003בהאי שעתא,\u0004 שמשך הו\"ק דחכמה, היה הסדר כך, \u0003הא עמודא דאשא ועמודא דעננא הוו אתיין,\u0004 שהם ב' קוין ימין ושמאל שבמלכות, שבהם הוא מקום גילוי של החכמה. \u0003ועל ההוא עמודא דעננא הוה אתי נשרא חדא,\u0004 דהיינו בינה וז\"ש \u0003וההוא נשרא הוה רברבא ותקיף.\u0004 כי כן נקראת הבינה נשר גדול וחזק. כנ\"ל. כי מבינה ממשיכים החכמה אל המלכות, שבבינה הוא מקום היציאה, ובמלכות הוא מקום הגילוי, וע\"כ צריכים לשתיהן, שצריכים לנשר, שהיא בינה, וצריכים לעמוד ענן ועמוד האש שבמלכות, ששם מקום הגילוי. וז\"ש וכן הוה אתי, \u0003גדפא ימינא,\u0004 שהוא קו ימין של הבינה, \u0003על גבי עמודא דאשא\u0004 היתה נסמכת על עמוד האש, שהוא קו שמאל של הנוקבא, ששם גם בחינת הדינים דנוקבא המכונים אש הנמשכים ממסך דחירק של קו האמצעי, שדינים אלו גרמו לכניעת קו שמאל ויחודו עם הימין. ונמצא שהימין דבינה קבל כח שליטתו ע\"י עמוד האש הזה, וע\"כ אומר הסבא שהימין נסמך על עמוד האש. \u0003וגופא וגדפא שמאלא על גבי עמודא דעננא\u0004 וכנף השמאלי שהוא קו שמאל דבינה, ששם מקום יציאת החכמה, נסמך על עמוד הענן שהוא קו ימין דמלכות, שהוא חסדים כי חכמה אינה יכולה להאיר בלי חסדים."],[8,"","וצריך שתדע, שקו השמאל, שמשם יוצא החכמה, נחלק על ב' בחינות, הנקראות נופל וגלוי עינים. כי ידעת שמכח המסך דחירק שעל ידו מיחד קו האמצעי ב' הקוין ימין ושמאל זה בזה, נעלמים הג\"ר דחכמה ונשארו רק הו\"ק דחכמה (כמ\"ש לך י\"ג ד\"ה ונתבאר עש\"ה) ומתוך שנסתלקו הג\"ר דחכמה מקו השמאל, נופלים ממנו ג' הכלים התחתונים נה\"י. ונשארו הכלים דחב\"ד חג\"ת בקו שמאל חסרים נה\"י. ומה שאורות עליונים גורמים לנפילת כלים התחתונים, הוא מטעם ערך ההפכי שיש בין כלים לאורות, שבאורות, התחתונים נכנסים תחילה, ובכלים, העליונים מתגדלים תחילה. (כמ\"ש בפתיחה לחכמת הקבלה אות כ\"ד) ואם לא נפלו נה\"י דכלים ע\"י קו האמצעי לא היתה יכולה החכמה להאיר. מטעם חסרון חסדים. וע\"כ חלק נה\"י שנפלו מקו שמאל מכונה \u0003נופל,\u0004 וחב\"ד חג\"ת שנשארו בקו שמאל עם האורות דו\"ק דחכמה המתוקנים בחסדים ע\"י היחוד עם הימין, נקראים \u0003גלוי עינים.\u0004 כי בהם נגלתה החכמה הנקראת עינים."],[8,"","וזה אמרו. \u0003וההוא נשרא הוי מייתי תרין טרפין בפומהא.\u0004 שהם ב' הבחינות שבקו השמאל דבינה, שהם נופל וגלוי עינים. \u0003אתא עמודא\u0004 וכו', \u0003וסגדין לקמיה דשלמה,\u0004 כי הרכנת הראש מכונה השתחואה, וכיון שנשאו ב' עלים נופל וגלוי עינים. כבר חסרו מג\"ר דחכמה שנקרא ראש, ונבחן זה, שהשפילו את ראשם והשתחוו כדי לתקן ההכמה לפני שלמה. וכן בשעת הנתינה, אומר, \u0003ומאיך לקמיה ויהיב ליה.\u0004 מטעם האמור. וז\"ש \u0003נטיל להון שלמה מלכא והוה מריח בהו,\u0004 שהמשיך חכמה, כי המשכת החכמה מכונה ריח. \u0003והוה ידע בהון סימן\u0004 שהיה יודע בהם סימן כמה מותר להמשיך החכמה, וכמה אסור, \u0003ואמר דא איהו דנופל,\u0004 השייך לג\"ר דחכמה, ואסור להמשיך, \u0003ודא איהו דגלוי עינים,\u0004 שהוא ו\"ק דחכמה ומותר להמשיך. והנה מתחילה לא היה מתוקן \u0003הנופל\u0004 כלל, אלא היה בנפילה ופגם. ואח\"כ נתקן גם הנופל, כי הנפילה שבו הוכרה לתקון, שלולא \u0003הנופל\u0004 שגרם קו האמצעי, לא היתה החכמה שבו\"ק יכולה להאיר, מפאת חוסר חסדים, כנודע. וע\"כ שרה התקון גם על \u0003נופל.\u0004 וז\"ש, \u0003בשעתא דתרין טרפין הוו,\u0004 דהיינו שגם \u0003הנופל\u0004 היה מתוקן, \u0003הוה ידע, דתרווייהו, נופל וגלוי עינים, בעאן לאודעא ליה מלין,\u0004 דהיינו, שגם \u0003נופל\u0004 היה מודיע לו דברי חכמה, כמו גלוי עינים, כי האירו זה בזה."],[8,"","עתה מבאר הסבא איך עלה שלמה ונתלבש בעצם קו השמאל דבינה, במקום החושך, שפירושו הארת חכמה בלא חסדים שהוא חושך ולא אור, אבל שם הוא יציאת החכמה, שאח\"כ שבא לקו האמצעי מלביש אותה החכמה בחסדים, ואז חזרה החכמה להיות אור, כנודע. ומטרם שהלך שלמה למקום החשך שבקו שמאל, היה מתירא שלא יכשל שם בהמשכת חכמה ממעלה למטה, שהיא בחינת החטא דעץ הדעת, ע\"כ \u0003מה עביד, חתים כרסיא בגושפנקא דהוה חקיק ביה שמא קדישא.\u0004 שהשם הקדוש היה שומר הכסא, שה\"ס המלכות, שלא תקבל החכמה בבחינת מלמעלה למטה. \u0003ואיהו נטיל עזקא דחקיק עליה שמא קדישא,\u0004 המוחין מכינים \u0003עזקא,\u0004 בעת שהשם הקדוש שורה עליהם, ושומרם, שלא ימשיכו חכמה ממעלה למטה. \u0003וסליק לאגרא,\u0004 דהיינו לבינה, כי המלכות נקראת בית, והבינה נקראת עליה, \u0003ורכיב על ההוא נשרא ואזיל ליה.\u0004 היינו שהתלבש בבינה הנקראת נשר. \u0003וההוא נשרא הוה מסתלק לרום עננין,\u0004 דהיינו שהמשיך חכמה בקו השמאל שהמשכה זו גורמת חושך,וז\"ש, \u0003ובכל אתר דאיהו עבר הוה אתחשך נהורא,\u0004 מחמת הארת השמאל, \u0003חכימי דהוו\u0004 וכו' היו מכירים שהחושך בא מכח הארת השמאל. \u0003טפשין דהוו תמן\u0004 וכו', היו חושבים שהוא מקרה, ועננים גרמו זה."],[8,"","וזה אמרו. \u0003גבה נשרא בהדיה ופרח ת' פרסין,\u0004 דהיינו שיחד את חו\"ג תו\"מ שלו, שהם ג' קוין והמלכות המקבלת, ומשום שהם מבינה שספירותיה בסוד מאות, הם ד' מאות. ומשום שהמקור שלהם הוא הפרסא, שהוא מסך דצמצום ב', ע\"כ נקראים ת' פרסאות. ויש לדעת שיחוד ג' הקוין הם בב' אפנים, תחילה מיחד קו האמצעי את ב' הקוין ימין ושמאל זה בזה תחת שליטת קו ימין. שאז מושפע רק חסדים לבד אלא שהם בהתכללות החכמה. ואחר כך מיחד ב' הקוין זה בזה תחת שליטת השמאל, שאז מושפע אור החכמה, וז\"ש \u0003עד דמטא לטורי חשוך.\u0004 דהיינו אפן הא' שיחד הקוין תחת שליטת קו ימין, וזה נבחן שהגיע להרי חושך מחמת התכללות החכמה בחסדים, אבל עוד לא בא להרי חושך ממש, ששם שליטת השמאל. \u0003ותמן איהו, תרמוד במדבר, בהרים.\u0004 שזסו\"ה, וילך שלמה וגו' ויבן את תדמור במדבר. שה\"ס יחוד הזה של ב' קוין זב\"ז תחת שליטת הימין, וע\"כ יכול שלמה לבנותה אע\"פ שהיתה במדבר. בארץ לא זרועה. שמשום התכללות השמאל היתה שם מדבר, ומשום שעקרו הוא חסדים היה יכול לעשותה מקום ישוב. \u0003ואיהו נחית תמן,\u0004 שירד מן הבינה לארץ, שפירושו שהמשיך אור הזה מלמעלה למטה. והוא מטעם שהוא אור החסדים. וז\"ש \u0003זקיף רישיה,\u0004 היינו שהמשיך ג\"ר הנקראות ראש, \u0003וחמי טורא חשוך,\u0004 שראה אותם מרחוק, כי מחמת התכללות החכמה בחסדים ראה אותם, אבל לא נכנס בהם, מחמת שהיה תחת שליטת הימין, שהוא חסדים. \u0003והוה ידע תמן כל מה דאצטריך,\u0004 שהיה לו הספקה שלמה מאור החסדים הזה להשלמת הג\"ר. \u0003והוה ידע דתמן יעול,\u0004 שהיה משיג שהוא ראוי כבר להכנס להרי חושך עצמם, תחת שליטת השמאל."],[8,"","וז\"ש, \u0003הוה רכיב על נשרא כמלקדמי\u0004 שחזר ועלה לבינה, ועשה שם היחוד, של אפן הב' הנ\"ל, דהיינו שיחד ב' הקוין ימין ושמאל תחת שליטת השמאל, \u0003וטאס ועאל לגו טורין,\u0004 שנכנס אל הרי חושך עצמם, שהם בקו שמאל. \u0003עד ההוא אתר דזיתא תמן,\u0004 הוא כח מסך דצמצם א', המכונה \u0003זית,\u0004 שהוא גנוז שם בהרי חושך. קרא בחילא ואמר, ה' רמה ידך \u0003בל יחזיון\u0004 וגו'. שהתפלל, שכח דין הזה יהיה מכוסה וגנוז שם \u0003בל יחזיון.\u0004 (ועי' ויצא י\"ג ד\"ה סתרא) \u0003עאל תמן עד דקריב לההוא אתר,\u0004 שנכנס בהרי חושך עד מקום ההוא של הזית, \u0003שוי עזקא קמייהו,\u0004 דהיינו הטבעת שחקוק עליה שם הקדוש, שהוא לשמירה שלא יכשל להמשיך החכמה ממעלה למטה כנ\"ל. \u0003ותמן הוה ידע כל מה דבעי מאינון חכמתן נוכראין דבעי למנדע\u0004 החכמה הנמשכת באיסור ממעלה למטה, נקראת חכמה זרה. ומהרי חושך קבל גם חכמה זו, אע\"פ שלא המשיכה בעצמו. \u0003כיון דהוו אמרין וכו' ותב לאתריה,\u0004 דהיינו שיצא מבחינת קו שמאל ושב למקומו לקו האמצעי. \u0003כיון דהוה יתיב על כורסיה אתיישב בדעתיה,\u0004 שהמשיך אור הדעת מקו האמצעי. \u0003והוה ממלל בדעתיה מלין דחכמתא יקירא\u0004 שהחכמה שקבל מקודם כשהיה בקו שמאל, היתה מאירה עתה בדעת שלו. \u0003בההוא שעתא הוה אמר ושבתי וכו' שבתי ודאי מההוא אורחא,\u0004 היינו הדרך שעשה בקו שמאל, \u0003שבתי מההוא חכמתא,\u0004 שחזר מאותו החכמה שקבל שם ובא לתוך הארת הדעת. \u0003ואתיישבת בלבאי ובדעתאי,\u0004 שהחכמה שקבל שם, נכללה בו, ונתישבה בלבו ודעתו. וכדין, ואראה את כל העשוקים, כי כל העשוקים המה מחמת התדבקותם בקו שמאל, ואינם רוצים ללכת בדרך קו האמצעי."]],[[0,"","שֶׁכָּךְ הָיוּ עוֹשִׂים יִשְׂרָאֵל עַד שֶׁהִשְׁתַּתְּפוּ בִּדְרָגוֹת תַּחְתּוֹנוֹת. בֹּא וּרְאֵה שֶׁיֵּשׁ לַחֲזֹר, זָקֵן, לִדְבָרִים רִאשׁוֹנִים, שֶׁכָּךְ הָיוּ עוֹשִׂים יִשְׂרָאֵל עַד שֶׁהִשְׁתַּתְּפוּ בַדְּרָגוֹת הַתַּחְתּוֹנוֹת. הַיָּרֵךְ שֶׁאָמַרְנוּ, הַרְבֵּה הִתְקִיפוּ אֶת יִשְׂרָאֵל בְּאוֹתָהּ הַיָּרֵךְ. מָרְדְּכַי הָיָה מַרְאֶה לְאוֹתוֹ הָמָן הָרָשָׁע אֶת אוֹתָהּ יָרֵךְ שֶׁלּוֹ, וְלָכֵן הָיָה רוֹגֵז, דָּבָר שֶׁנִּרְאָה לוֹ, וְהוּא הִרְגִּיז אוֹתוֹ עִמּוֹ. רְאוּ הַחֲבֵרִים מַה כָּתוּב - (בראשית כז) וַתִּקַּח רִבְקָה אֶת בִּגְדֵי עֵשָׂו בְּנָהּ הַגָּדֹל הַחֲמֻדת וְגוֹ'. בַּלְּבוּשׁ הַלָּלוּ שֶׁלּוֹ גָּזַל אוֹתוֹ וְהוֹצִיא אוֹתוֹ מִכָּל בִּרְכוֹתָיו וּמֵהַבְּכוֹרָה."],[1,"","וּמִשּׁוּם כָּךְ, הָעִלָּה שֶׁמָּצְאוּ הַמֶּרְכָּבוֹת שֶׁלּוֹ לַחֲכָמִים הוּא הַחִכּוּךְ שֶׁלָּהֶם עִם בִּגְדֵי רַבּוֹתֵינוּ תָּמִיד לַיְרֵכַיִם שֶׁלָּהֶם וְלַבְּגָדִים שֶׁלָּהֶם. וְאֵלּוּ שְׁנֵי הַדְּבָרִים הָיוּ שֶׁל הַצַּד הָאַחֵר, וְכָל זֶה מִשּׁוּם שֶׁגָּזְלוּ מִמֶּנּוּ אוֹתָם, וְאֵין לָהֶם עִלָּה אֶלָּא לַחֲכָמִים. וּמִשּׁוּם כָּךְ הַבְּגָדִים הַלָּלוּ שֶׁל הַחֲכָמִים הֵם מִתְבַּלִּים מֵהַחִכּוּךְ שֶׁלָּהֶם, וְהַבִּרְכַּיִם הַכּוֹשְׁלוֹת הַלָּלוּ זֶה מֵהֶם וַדַּאי, וּמִשֶּׁלָּהֶם הָיוּ, וּמֵהֶם נוֹטְלִים תּוֹאֲנָה, וּמִמַּה שֶּׁהָיוּ מֵהֶם. וְרוֹצִים לַחֲכָמִים, שֶׁהֵם כְּלָל שֶׁל אוֹתוֹ שֶׁיּוֹשֵׁב אֹהָלִים, וְלָכֵן אֵין עִלָּה בְּלִי עִלָּה, וְלָכֵן אֵין דָּבָר בְּלִי דִין, וְכָל דָּבָר שָׁב לִמְקוֹמוֹ."],[2,"","שְׁלֹמֹה אָמַר, (קהלת ד) וְשַׁבְתִּי אֲנִי וָאֶרְאֶה אֶת כָּל הָעֲשׁוּקִים אֲשֶׁר נַעֲשִׂים תַּחַת הַשָּׁמֶשׁ וְהִנֵּה דִּמְעַת הָעֲשׁוּקִים וְאֵין לָהֶם מְנַחֵם וּמִיַּד עֹשְׁקֵיהֶם כֹּחַ וְאֵין לָהֶם מְנַחֵם. הַפָּסוּק הַזֶּה רָמַזְנוּ בוֹ וְנִתְבָּאֵר. אֲבָל שַׁבְתִּי אֲנִי, וְכִי מֵאֵיזֶה מָקוֹם שָׁב שְׁלֹמֹה? אִם נֹאמַר, לְאַחַר שֶׁאָמַר דָּבָר זֶה שָׁב כְּמוֹ מִקֹּדֶם וְאָמַר דָּבָר אַחֵר - יָפֶה. אֲבָל שַׁבְתִּי וָאֶרְאֶה."],[3,"","שָׁם שָׁנִינוּ, בְּכָל יוֹם הָיָה מַקְדִּים שְׁלֹמֹה בַּבֹּקֶר וְהָיָה שָׂם פָּנָיו לְצַד מִזְרָח וְרוֹאֶה מַה שֶּׁרוֹאֶה, וְאַחַר כָּךְ שָׁב לְצַד דָּרוֹם וְרוֹאֶה מַה שֶּׁרוֹאֶה, וְאַחַר כָּךְ שָׁב לְצַד צָפוֹן וְעוֹמֵד שָׁם. מַנְמִיךְ עֵינָיו וּמֵרִים רֹאשׁוֹ."],[4,"","בַּשָּׁעָה הַזּוֹ הֲרֵי עַמּוּד אֵשׁ וְעַמּוּד עָנָן הָיוּ בָאִים, וְעַל אוֹתוֹ עַמּוּד הֶעָנָן הָיָה בָּא נֶשֶׁר אֶחָד, וְאוֹתוֹ הַנֶּשֶׁר הוּא גָּדוֹל וְחָזָק. וְכָךְ הָיָה בָּא: כָּנָף יָמִין עַל גַּבֵּי עַמּוּד הָאֵשׁ, וְהַגּוּף וְכָנָף שְׂמֹאל עַל גַּבֵּי עַמּוּד הָעָנָן. וְאוֹתוֹ נֶשֶׁר הָיָה מֵבִיא שְׁנֵי עָלִים בְּפִיו. בָּא עַמּוּד הֶעָנָן וְעַמּוּד הָאֵשׁ, וְאוֹתוֹ הַנֶּשֶׁר עֲלֵיהֶם, וּמִשְׁתַּחֲוִים לִפְנֵי שְׁלֹמֹה הַמֶּלֶךְ."],[5,"","בָּא הַנֶּשֶׁר וְהִנְמִיךְ לְפָנָיו, וְנָתַן לוֹ אוֹתָם עָלִים. לוֹקֵחַ אוֹתָם הַמֶּלֶךְ שְׁלֹמֹה וּמֵרִיחַ בָּהֶם, וְהָיָה יוֹדֵעַ בָּהֶם סִימָן וְאוֹמֵר: זֶהוּ הַנּוֹפֵל, וְזֶהוּ גְּלוּי הָעֵינַיִם. בְּשָׁעָה שֶׁשְּׁנֵי עָלִים הָיוּ, הָיָה יוֹדֵעַ שֶׁשְּׁנֵיהֶם - נוֹפֵל וּגְלוּי עֵינַיִם - רוֹצִים לְהוֹדִיעוֹ דְבָרִים."],[6,"","מֶה עָשָׂה? חָתַם אֶת כִּסְאוֹ בְּחוֹתָם שֶׁהָיָה חָקוּק בּוֹ הַשֵּׁם הַקָּדוֹשׁ, וְנוֹטֵל טַבַּעַת שֶׁחָקוּק עָלֶיהָ הַשֵּׁם הַקָּדוֹשׁ, וְעוֹלֶה לַגַּג וְרוֹכֵב עַל אוֹתוֹ הַנֶּשֶׁר וְהוֹלֵךְ לוֹ. וְאוֹתוֹ נֶשֶׁר הָיָה מִתְעַלֶּה לְרוּם הָעֲנָנִים, וּבְכָל מָקוֹם שֶׁהוּא עָבַר, הָיָה הָאוֹר נֶחְשָׁךְ. הַחֲכָמִים שֶׁהָיוּ בְּאוֹתוֹ הַמָּקוֹם שֶׁחָשַׁךְ הָאוֹר, הָיוּ יוֹדְעִים, וְהָיוּ אוֹמְרִים: שְׁלֹמֹה הַמֶּלֶךְ הֲרֵי הוֹלֵךְ וְעוֹבֵר כָּאן. וְלֹא יוֹדְעִים לְאֵיזֶה מָקוֹם הָיָה הוֹלֵךְ. הַטִּפְּשִׁים שֶׁהָיוּ שָׁם הָיוּ אוֹמְרִים, שֶׁהֵם הָיוּ עֲנָנִים שֶׁהוֹלְכִים וּמַחְשִׁיכִים אֶת הָעוֹלָם."],[7,"","הִגְבִּיהַּ הַנֶּשֶׁר עִמּוֹ וּפוֹרֵחַ אַרְבַּע מֵאוֹת פַּרְסָאוֹת, עַד שֶׁמַּגִּיעַ לְהָרֵי הַחֹשֶׁךְ. שָׁם הוּא תַּרְמוּד בַּמִּדְבָּר בֶּהָרִים, וְהוּא יוֹרֵד שָׁם. מֵרִים רֹאשׁוֹ וְרוֹאֶה הַר חָשׁוּךְ, וְשָׁם הָיָה יוֹדֵעַ כָּל מַה שֶּׁצָּרִיךְ, וְהָיָה יוֹדֵעַ שֶׁשָּׁם יִכָּנֵס. הָיָה רוֹכֵב עַל הַנֶּשֶׁר כְּמִקֹּדֶם, וְטָס וְנִכְנָס לְתוֹךְ הֶהָרִים עַד אוֹתוֹ מָקוֹם שֶׁשָּׁם הַזַּיִת, קוֹרֵא בְחַיִל וְאוֹמֵר, ה' רָמָה יָדְךְ בַּל יֶחֱזָיוּן וְגוֹ'."],[8,"","נִכְנָס לְשָׁם, עַד שֶׁקָּרַב לְאוֹתוֹ מָקוֹם, וְשָׂם טַבַּעַת לִפְנֵיהֶם וְקָרַב, וְשָׁם הָיָה יוֹדֵעַ כָּל מַה שֶּׁרָצָה מֵאוֹתָן חָכְמוֹת זָרוֹת שֶׁרָצָה לָדַעַת. כֵּיוָן שֶׁהָיוּ אוֹמְרִים לוֹ כָּל מַה שֶּׁרָצָה, אָז הָיָה רוֹכֵב עַל אוֹתוֹ נֶשֶׁר, וְשָׁב לִמְקוֹמוֹ. כֵּיוָן שֶׁהָיָה יוֹשֵׁב עַל כִּסְאוֹ, הִתְיַשֵּׁב בְּדַעְתּוֹ וְהָיָה מְדַבֵּר בְּדַעְתּוֹ דִּבְרֵי חָכְמָה נִכְבָּדָה. בְּאוֹתָהּ שָׁעָה הָיָה אוֹמֵר, וְשַׁבְתִּי אֲנִי וָאֶרְאֶה. שַׁבְתִּי וַדַּאי מֵאוֹתָהּ דֶּרֶךְ, שַׁבְתִּי מֵאוֹתָהּ חָכְמָה וְהִתְיַשְּׁבָה בְּלִבִּי וּבְדַעְתִּי. וְאָז, וָאֶרְאֶה אֶת כָּל הָעֲשׁוּקִים. (וכי מעטים הם בעולם שהוא אמר את כל העשוקים, ')."]]],[["(נ\"א סלקא דעתך דכל עשיקין דהוו בעלמא, הוה חמי שלמה מלכא.) אֶלָּא, מַאי עֲשׁוּקִים אִלֵּין דְּהוּא אָמַר. אִינּוּן יְנוֹקִין דְּמֵתִין בְּתּוּקְפָא דְּאִמְּהוֹן, דְּקָא עֲשׁוּקִים מִכַּמָּה סִטְרִין, עֲשׁוּקִים בַּאֲתָר עִלָּאָה דִּלְעֵילָּא, וַעֲשׁוּקִים לְתַתָּא. וְהָא חַבְרַיָּיא אִתְּעָרוּ, וְהָכִי הוּא, אֲבָל סַגִּיאִין אִינּוּן. קוּם סָבָא, אִתְּעַר בְּחֵילָךְ. סָבָא אֵימָא מִילָךְ, דְּוַדַּאי בְּלָא דְּחִילוּ תֵּימָא.","לֵית עָשׁוּק כְּאִינּוּן עֲשׁוּקִים, דְּהֲוָה אִיהוּ עָשִׁיק בְּקַדְמִיתָא, אוֹ מִתְּלָתָא לְאָחֳרָא, כְּמָה דִּכְתִיב, (שמות כ׳:ה׳) פּוֹקֵד עֲוֹן אָבוֹת עַל בָּנִים וְעַל בְּנֵי בָנִים עַל שִׁלֵּשִׁים וְעַל רִבֵּעִים.","הֵיךָ הֲוָה עָשִׁיק. שְׁלמֹה מַלְכָּא צָוַוח וְאָמַר (משלי כ״ח:י״ז) אָדָם עָשׁוּק בְּדָם נָפֶשׁ עַד בּוֹר יָנוּס אַל יִתְמְכוּ בוֹ. כֵּיוָן דְּהוּא עָשׁוּק, בְּדַם נֶפֶשׁ, הוּא, אוֹ בְּנוֹ, אוֹ בֶּן בְּנוֹ, יְהוֹן עֲשׁוּקִין בְּטִיקְלָא, דִּכְתִיב עַד בּוֹר יָנוּס אַל יִתְמְכוּ בוֹ. עַד הַהוּא בּוֹר רַק יָנוּס מֵאֲתָר קַדִּישָׁא, וְאַל יִתְמְכוּ בּוֹ בְּהַאי עָלְמָא. כֵּיוָן דְּאִיהוּ עָשׁוּק בְּדַם נֶפֶשׁ, אִיהוּ, אוֹ זַרְעֵיהּ, לֶהֱווֹ עֲשׁוּקִים מֵהַהוּא סִטְרָא אָחֳרָא.","אִית עָשׁוּק, מִשְּׁאָר עֲשׁוּקִים, כְּמָה דְאַתְּ אָמֵר (ויקרא י״ט:י״ג) לא תַעֲשׁוֹק אֶת רֵעֲךָ. אִיהוּ עָבַר וְעָשַׁק, אִיהוּ עָשׁוּק בִּבְנוֹי, מֵהַהוּא סִטְרָא אָחֳרָא. וּבְּגִין כָּךְ אָמַר, אֶת כָּל הָעֲשׁוּקִים. אָמַר שְׁלֹמֹה, קָאִימְנָא בְּכָל אִינּוּן עֲשׁוּקִים, בְּכָל סִטְרִין דַּעֲשָׁק.","וַאֲמַאי אִינּוּן עֲשׁוּקִים. אֲשֶׁר נַעֲשׂוּ תַּחַת הַשָּׁמֶשׁ. אֲשֶׁר נַעֲשׂוּ, אֲשֶׁר גָּרוּ מִבָּעֵי לֵיהּ, מַאי אֲשֶׁר נַעֲשׂוּ. אִי עֲשִׂיָּיה אִיהִי לִשְׁבָחָא, לָאו עֲשִׂיָּיה דִּלְהוֹן אֶלָּא לְעֵילָּא מִן שִׁמְשָׁא.","אֲבָל וַדַּאי נַעֲשׂוּ. הֵיךְ נַעֲשׂוּ. אֶלָּא כֵּיוָן דְּעֲשׁוּקִים מֵרוּחֵיהוֹן תַּמָּן, אֲמַאי אַתְיָין לְהַאי עָלְמָא. אֶלָּא רוּחִין וַדַּאי נַעֲשׂוּ, אִתְעָבִידוּ בְּרוּחִין וּבְגוּפָא בְּהַאי עָלְמָא, כֵּיוָן דְּאִשְׁתָּכְלַל גּוּפָא דִּלְהוֹן, וְאִתְעָבִיד הַהוּא רוּחָא בְּגוּפָא זַךְ וְנָקִי בְּלָא לִכְלוּכָא דְּחוֹבִין, בְּהַאי עָלְמָא, כְּדֵין אִתְעֲשָׁק גּוּפָא, כְּמָה דְּאִתְעֲשָׁק רוּחָא. וְהַאי אִיהוּ גּוּפָא, דְּאִתְהֲנֵי בֵּיהּ יַתִּיר מִכֹּלָּא. וַעֲשׁוּקִין אַחֲרָנִין אִית, בְּכַמָּה זִינִין מֵרוּחִין תַּמָּן, וְלָא נַעֲשׂוּ בְּגוּפִין. אֲבָל אִלֵּין, אִינּוּן עֲשׁוּקִים אֲשֶׁר נַעֲשׂוּ.","אִית אַחֲרָנִין, אֲשֶׁר נַעֲשׂוּ, וְאַטְרָחוּ בְּנֵי נָשָׁא לְמָארֵיהוֹן. וּמַאן אִיהוּ. מַאן דְּעָשִׁיק אִתְּתָא דְּחַבְרֵיהּ בִּטְמִירוּ, אוֹ בְּאִתְגַּלְּיָיא. וְהַהוּא וַלְדָּא דְּאִתְיְלִיד מִנַּיְיהוּ, עָשׁוּק אִיהוּ, בְּלָא רְעוּתָא דְּמָארִיהוֹן, וְלָא יָדַע בַּעְלָהּ דְּאִתְּתָא, אִינּוּן עוֹבָדִין עֲשׁוּקִין אִינּוּן, וְאַטְרָחוּ לְקוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד לוֹן גּוּפָא, וּלְצַיְּירָא לוֹן צוּרָה, אִלֵּין עֲשׁוּקִים אֲשֶׁר נַעֲשׂוּ. אֲשֶׁר נַעֲשׂוּ וַדַּאי גּוּפִין דִּלְהוֹן, עַל כָּרְחָא. בְּגִין כָּךְ, שְׁלמֹה מַלְכָּא אָמַר, (קהלת ד׳:א׳) וָאֶרְאֶה אֶת כָּל הָעֲשׁוּקִים, בְּכָל זִינֵי עֲשׁוּקִים קָאִימְנָא, אִינּוּן אֲשֶׁר נַעֲשׂוּ וְאִתְעָבִידוּ בַּעֲשִׂיָּיה.","כְּמָה דְּהָנֵי (דבר אחר איהו בערלה, אינו רבי ועביד ולבתר עשקין ליה מינה הכי) אִינּוּן עֲשׁוּקִין, דְּכְבָר נַעֲשׂוּ בְּעָרְלָה רַבֵּי וְנָטִיל וְגָדִיל גּוּפָא, וְעָבִיד לֵיהּ, וּלְבָתַר עַשְׁקִין לוֹן מִנֵּיהּ, וְנַטְלִין לוֹן, הֲרֵי עֲשׁוּקִים אֲשֶׁר נַעֲשׂוּ, וְעַל כֹּלָּא קָאִים שְׁלמֹה מַלְכָּא וְאָמַר, קָאִימְנָא עַל כָּל הָעֲשׁוּקִים אֲשֶׁר נַעֲשׂוּ.","וְהִנֵּה דִּמְעַת הָעֲשֻׁקִים, כֹּלָּא אוֹשְׁדִין דִּמְעִין, עִם טַעֲנָה קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. הָנֵי אוֹשְׁדִין דִּמְעִין, דְּהָא עָרְלָה רַבֵּי לוֹן, וְגָדִיל לוֹן, עַד י\"ג שְׁנִין, וּלְבָתַר עַשְׁקִין לוֹן מֵעָרְלָה, וְנָטִיל לוֹן קוּדְשָׁא בְּרִיךְ הוּא, הָא לָךְ עֲשׁוּקִין אֲשֶׁר נַעֲשׂוּ כְּבָר.","עָבַר עֲבֵירָה קַטְלִין לֵיהּ. לוֹן אִית טַעֲנָה, וּזְמִינִין לוֹמַר, מָארֵי דְּעָלְמָא, תִּינוֹק בַּר יוֹמֵיהּ דְּחָב, דַּיְינִין לֵיהּ דִּינָא. אֲנָא בַּר יוֹמֵיהּ הֲוֵינָא, דְּהָא (צ\"ח ע\"ב) מֵהַהוּא יוֹמָא קָרֵי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בֵּן, דִּכְתִיב (תהילים ב׳:ז׳) יְיָ' אָמַר אֵלַי בְּנִי אַתָּה אֲנִי הַיּוֹם יְלִדְתִּיךָ, מָארֵיהּ דְּעָלְמָא, יְלִיד בַּר יוֹמָא, דִּינָא עַבְדִין לֵיהּ, הֲרֵי דִּמְעַת אִינּוּן הָעֲשׁוּקִים וְאֵין לָהֶם מְנַחֵם."],[[0,"ס\"ד דכל עשיקין וכו':","היעלה על דעתך, שכל העשוקים שהיה בעולם ראה שלמה המלך. שהכתוב אומר, ואראה את כל העשוקים. ומשיב. אלא מה הם אלו עשוקים שאומר, הם הילדים שמתים על ברכי אמותם, שהם עשוקים מכמה צדדים, עשוקים במקום עליון של מעלה, מצד הרוח שלהם, ועשוקים מלמטה מצד הגוף. והרי העירו זה החברים, וכך הוא, אבל הרבה הם אלו העשוקים, מלבד זה. אמר לעצמו, קום זקן, התעורר בכוחך, זקן אמור דבריך, כי ודאי בלא פחד תאמר."],[1,"לית עשוק כאינון וכו':","אין עשוק כאלו העשוקים שהיה הוא עושק בתחילה, דהיינו שחטא, או שמחמת עונו נענש מדור שלישי לאחר, לרביעי, שהוא נעשק קשה להיות מחמת עון. כי הילדים הנ\"ל מתים בלי חטא, וע\"כ אינם נעשקים קשה, מה שאינו כן אלו שחטאו, או אביהם זקנם חטאו. כמ\"ש פוקד עון אבות על בנים על שלשים ועל רבעים."],[2,"היך הוה עשיק וכו':","שואל, איך היה עושק, דהיינו מה היה עונו. ומשיב. שלמה המלך צעק ואמר, אדם עשוק בדם נפש, עד בור ינוס אל יתמכו בו. כיון שהוא עשוק מחמת עון דם נפש ששפך, הוא או בנו או בן בנו יהיו נעשקים במאזנים (כנ\"ל אות כ\"ז) על ידי הס\"א, שכתוב, עד בור ינוס אל יתמכו בו, עד ההוא בור של הס\"א, רק ינוס ממקום הקדושה, ואל יתמכו בו בעולם הזה. כיון שהוא עשוק בעון דם נפש, הוא או זרעו יהיו עשוקים מההוא סטרא אחרא."],[3,"אית עשוק משאר וכו':","יש עשוק משאר עשוקים, שהוא עשוק מחמת עון של לא תעשוק, שעבר אביו או זקנו. כמש\"א לא תעשוק את רעך. והוא עבר ועשק, משלמים לו מדה כנגד מדה, שהוא עשוק בבניו, על ידי הסטרא אחרא ההוא. ומשום זה אמר, את כל העשוקים. אמר שלמה, אני עומד ויודע בכל אלו עשוקים, בכל צד שעשק, ולא שראה כל העשוקים שבעולם."],[4,"ואמאי אינון עשוקים וכו':","שואל, למה הם עשוקים אשר נעשו תחת השמש. אשר נעשו, אשר גרו היה צריך לומר, מהו אשר נעשו. ואם עשיה הוא לשבח, הרי אין עשיה שלהם אלא למעלה מן השמש, ששם מקום השבח והתקונים, ולמה אוה\"כ, תחת השמש."],[5,"אבל ודאי נעשו וכו':","ומשיב, אבל ודאי שנעשו, ואיך נעשו. אלא כיון שעשוקים שם מרוחיהם, למה באים לעולם הזה, בגלגול. כי עשיה, נופל על הגוף, שהוא בעולם עשיה. אלא הרוחות ודאי נעשו, שנעשו ברוח וגוף בעולם הזה. וכיון שנשתכלל הגוף שלהם, ורוח ההוא נעשה ונתלבש בגוף זך ונקי בלא לכלוך של עונות, בעולם הזה, אז נעשק הגוף כמו שנעשק הרוח. וזה הוא הגוף שהס\"א נהנית בו יותר מכל. ויש שם רוחות עשוקים אחרים בכמה מינים שלא נעשו בגופים, שלא נתגלגלו לעולם הזה, אבל אלו הם העשוקים שנעשו בגופים וע\"כ אוה\"כ אשר נעשו."],[6,"אית אחרנין אשר וכו':","יש אחרים אשר נעשו, שבני אדם הטריחו את רבונם. ומי הם. הוא, מי שעשק אשת חברו בסתר או בגלוי, ואותו הילד שנולד מהם, עשוק הוא, בלא רצון אדונם, ובלא ידיעת בעל האשה. אלו המעשים הם עשוקים, והטריחו את הקב\"ה לעשות להם גוף, ולצייר להם צורה. אלו הם עשוקים אשר נעשו, אשר ודאי נעשו הגופים שלהם באונס. משום זה אמר שלמה המלך, ואראה את כל העשוקים, בכל מיני עשוקים אני עומד ויודע, אלו אשר נעשו בעשיה."],[7,"כמה דהני אינון וכו':","כמו אלו, הם העשוקים שכבר נעשו בערלה, שלקח והרבה והגדיל הגוף, ועשה אותו ואח\"כ, כשנעשה בן י\"ג שנה. עושקים אותו ממנו ולוקחים אותו. הרי עשוקים אשר נעשו. ועל הכל עמד שלמה המלך, ואמר אני עומד, ויודע, על כל העשוקים אשר נעשו."],[8,"והנה דמעת העשוקים:","הכל שופכים דמעות עם טענה לפני הקב\"ה, אלו שופכים דמעות, כי הערלה, שהיא הס\"א, הרבה וגידל אותם עד י\"ג שנים ואה\"כ עושקים אותם מן הערלה, והקב\"ה לוקח אותם. הרי לך עשוקים אשר נעשו כבר."],[9,"עבר עבירה קטלין וכו':","בן י\"ג שנה ויום א' שעבר עבירה שעונשה מיתה, הורגים אותו. להם יש טענה, ועתידים לומר, רבון העולם, תינוק בן יומו שחטא הכי דנים אותו בדין. אני בן יומו הייתי, כי מיום ההוא אחר י\"ג שנים קורא אותי הקב\"ה בן, שכתוב ה' אמר אלי בני אתה אני היום ילדתיך. רבון העולם, ילד בן יום, עושים לו דין. הרי דמעת אלו העשוקים ואין להם מנחם."]],[[0,"","(העלה על דעתך שכל העשוקים שהיו בעולם היה רואה שלמה המלך?!) אֶלָּא מִי הָעֲשׁוּקִים הַלָּלוּ שֶׁהוּא אָמַר? אוֹתָם הַתִּינוֹקוֹת שֶׁמֵּתִים בְּחֵיק אִמּוֹתֵיהֶם, שֶׁהֲרֵי הֵם עֲשׁוּקִים מִכַּמָּה צְדָדִים - עֲשׁוּקִים בְּמָקוֹם עֶלְיוֹן שֶׁלְּמַעְלָה, וַעֲשׁוּקִים לְמַטָּה. וַהֲרֵי הִתְעוֹרְרוּ הַחֲבֵרִים, וְכָךְ הוּא, אֲבָל רַבִּים הֵם. קוּם זָקֵן, הִתְעוֹרֵר בְּכֹחֲךְ. זָקֵן, אֱמֹר דְּבָרְךְ, שֶׁוַּדַּאי תֹּאמַר בְּלִי פַּחַד."],[1,"","אֵין עָשׁוּק כְּאוֹתָם עֲשׁוּקִים, שֶׁהָיָה הוּא עָשׁוּק בַּהַתְחָלָה, אוֹ מִשְּׁלִישִׁי לְאַחֵר, כַּכָּתוּב (שמות לד) פֹּקֵד עֲוֹן אָבוֹת עַל בָּנִים וְעַל בְּנֵי בָנִים עַל שִׁלֵּשִׁים וְעַל רִבֵּעִים."],[2,"","אֵיךָ הָיָה עוֹשֵׁק? שְׁלֹמֹה הַמֶּלֶךְ צוֹוֵחַ וְאוֹמֵר, (משלי כח) אָדָם עָשֻׁק בְּדַם נָפֶשׁ עַד בּוֹר יָנוּס אַל יִתְמְכוּ בוֹ. כֵּיוָן שֶׁהוּא עָשׁוּק בְּדַם נֶפֶשׁ, הוּא אוֹ בְּנוֹ אוֹ בֶּן בְּנוֹ יִהְיוּ עֲשׁוּקִים בְּמֹאזְנַיִם, שֶׁכָּתוּב עַד בּוֹר יָנוּס אַל יִתְמְכוּ בוֹ. עַד אוֹתוֹ הַבּוֹר רַק יָנוּס מִמָּקוֹם קָדוֹשׁ, וְאַל יִתְמְכוּ בוֹ בָּעוֹלָם הַזֶּה. כֵּיוָן שֶׁהוּא עָשׁוּק בְּדַם נֶפֶשׁ, הוּא אוֹ זַרְעוֹ יִהְיוּ עֲשׁוּקִים מֵאוֹתוֹ הַצַּד הָאַחֵר."],[3,"","יִשִׁ עָשׁוּק מִשְּׁאָר עֲשׁוּקִים, כְּמוֹ שֶׁנֶּאֱמַר לֹא תַעֲֹשק אֶת רֵעֲךְ. הוּא עָבַר וְעָשַׁק, הוּא עָשׁוּק כְּבָנָיו, מֵאוֹתוֹ הַצַּד הָאַחֵר, וּמִשּׁוּם כָּךְ אָמַר אֶת כָּל הָעֲשׁוּקִים. אָמַר שְׁלֹמֹה, עָמַדְתִּי בְּכָל אוֹתָם עֲשׁוּקִים בְּכָל הַצְּדָדִים שֶׁעָשַׁק."],[4,"","וְלָמָּה הֵם עֲשׁוּקִים? אֲשֶׁר נַעֲשׂוּ תַּחַת הַשָּׁמֶשׁ. אֲשֶׁר נַעֲשׂוּ? אֲשֶׁר גָּרוּ הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה אֲשֶׁר נַעֲשׂוּ? אִם הָעֲשִׂיָּה הִיא לְשֶׁבַח, אֵין עֲשִׂיָּה שֶׁלָּהֶם אֶלָּא לְמַעְלָה מִן הַשֶּׁמֶשׁ."],[5,"","אֲבָל וַדַּאי נַעֲשׂוּ. אֵיךְ נַעֲשׂוּ? אֶלָּא כֵּיוָן שֶׁעֲשׁוּקִים מֵרוּחָם שָׁם, לָמָּה בָּאִים לָעוֹלָם הַזֶּה? אֶלָּא וַדַּאי רוּחוֹת נַעֲשׂוּ, נַעֲשׂוּ בְרוּחוֹת וְגוּף בָּעוֹלָם הַזֶּה. כֵּיוָן שֶׁנִּתְקַן הַגּוּף שֶׁלָּהֶם וְנֶעֶשְׂתָה אוֹתָהּ רוּחַ בְּגוּף זַךְ וְנָקִי בְּלִי לִכְלוּךְ שֶׁל חֲטָאִים בָּעוֹלָם הַזֶּה, אָז נֶעֱשַׁק הַגּוּף כְּמוֹ שֶׁנֶּעֶשְׁקָה הָרוּחַ. וְזֶהוּ הַגּוּף שֶׁנֶּהֱנָה בּוֹ יוֹתֵר מֵהַכֹּל. וְיֵשׁ עֲשׁוּקִים אֲחֵרִים בְּכַמָּה מִינִים מֵרוּחוֹת שָׁם, וְלֹא נַעֲשׂוּ בְגוּפִים. אֲבָל אֵלֶּה הֵם עֲשׁוּקִים אֲשֶׁר נַעֲשׂוּ."],[6,"","יִשִׁ אֲחֵרִים אֲשֶׁר נַעֲשׂוּ, וְהִטְרִיחוּ בְּנֵי אָדָם אֶת רִבּוֹנָם. וּמִי הֵם? מִי שֶׁעָשַׁק אֵשֶׁת חֲבֵרוֹ בַּסֵּתֶר אוֹ בַּגָּלוּי, וְאוֹתוֹ וָלָד שֶׁנּוֹלָד מֵהֶם הוּא עָשׁוּק, בְּלִי רְצוֹן רִבּוֹנָם, וְלֹא יוֹדֵעַ בַּעַל הָאִשָּׁה שֶׁאוֹתָם הַמַּעֲשִׂים הֵם עֲשׁוּקִים, וְהִטְרִיחוּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת לָהֶם גּוּף וּלְצַיֵּר לָהֶם צוּרָה. אֵלּוּ עֲשׁוּקִים אֲשֶׁר נַעֲשׂוּ. אֲשֶׁר נַעֲשׂוּ וַדַּאי הַגּוּפִים שֶׁלָּהֶם עַל כֹּרַח. מִשּׁוּם כָּךְ שְׁלֹמֹה הַמֶּלֶךְ אוֹמֵר, (קהלת ד) וָאֶרְאֶה אֶת כָּל הָעֲשׁוּקִים, בְּכָל מִינֵי עֲשׁוּקִים עָמַדְתִּי, אוֹתָם אֲשֶׁר נַעֲשׂוּ וְנַעֲשׂוּ בַּעֲשִׂיָּה."],[7,"","כְּמוֹ שֶׁאֵלֶּה (הואבערלה, אינו גדל ועושה, ואחר כך עושקים אותו ממגו, כך) אוֹתָם עֲשׁוּקִים, שֶׁכְּבָר נַעֲשׂוּ בְעָרְלָה, וְהִתְרַבָּה וְנָטַל וְגָדַל הַגּוּף, וְעָשָׂה אוֹתוֹ, וְאַחַר כָּךְ עוֹשְׁקִים אוֹתָם מִמֶּנּוּ וְלוֹקְחִים אוֹתָם, הֲרֵי עֲשׁוּקִים אֲשֶׁר נַעֲשׂוּ, וְעַל הַכֹּל עָמַד הַמֶּלֶךְ שְׁלֹמֹה וְאָמַר, עָמַדְתִּי עַל כָּל הָעֲשׁוּקִים אֲשֶׁר נַעֲשׂוּ."],[8,"","וְהִנֵּה דִּמְעַת הָעֲשׁוּקִים, כֻּלָּם שׁוֹפְכִים דְּמָעוֹת עִם טַעֲנָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. אֵלּוּ שׁוֹפְכִים דְּמָעוֹת, שֶׁהֲרֵי הָעָרְלָה מַרְבָּה וּמְגַדֶּלֶת אוֹתָם עַד שְׁלֹשׁ עֶשְׂרֵה שָׁנִים, וְאַחַר כָּךְ עוֹשְׁקִים אוֹתָם מֵהָעָרְלָה וְהַקָּדוֹשׁ בָּרוּךְ הוּא לוֹקֵחַ אוֹתָם. הֲרֵי לְךְ עֲשׁוּקִים אֲשֶׁר נַעֲשׂוּ כְּבָר."],[9,"","עָבַר עֲבֵרָה - הוֹרְגִים אוֹתוֹ. לָהֶם יֵשׁ טַעֲנָה, וַעֲתִידִים לוֹמַר: רִבּוֹן הָעוֹלָם, תִּינוֹק בֶּן יוֹמוֹ שֶׁחָטָא, דָּנִים אוֹתוֹ דִּין? אֲנִי בֶּן יוֹמִי הָיִיתִי, שֶׁהֲרֵי מֵאוֹתוֹ יוֹוֹ קוֹרֵא לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּן, שֶׁכָּתוּב (תהליםב) ה' אָמַר אֵלַי בְּנִי אַתָּה אֲנִי הַיּוֹם יְלִדְתִּיךְ. רִבּוֹן הָעוֹלָם, יְלִיד בֶּן יוֹם, דִּין עוֹשִׂים לוֹ? הֲרֵי דִּמְעַת אוֹתָם הָעֲשׁוּקִים וְאֵין לָהֶם מְנַחֵם."]]],[["וְאִית עָשׁוּק אַחֵר, הַהוּא עָשׁוּק דְּאִקְרֵי מַמְזֵר, כַּד נָפַק מֵעָלְמָא, מִיָּד מַפְרִישִׁין לֵיהּ מִקְּהִלָּתָא דְּעַמָּא קַדִּישָׁא. הַהוּא מַמְזֵר, עַנְיָא מִסְכְּנָא, אוֹשִׁיד דִּמְעִין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְאַטְעִין קָמֵיהּ, מָארֵיהּ דְּעָלְמָא, אִי אֲבָהָתַי חָאבוּ, אֲנָא מַה חוֹבָא עֲבִידְנָא, הָא עוֹבָדָאי, מִתְתַּקְּנָן לְקַמָּךְ הֲווֹ, וְהִנֵּה דִּמְעַת הָעֲשׁוּקִים וְאֵין לָהֶם מְנַחֵם. וְכֵן לְכָל אִינּוּן עֲשׁוּקִים, אִית לוֹן טַעֲנָה קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וּמֵהַהִיא טַעֲנָה לֵית לוֹן מְנַחֵם, וְלֵית דְּיָתִיב מִלָּה עַל לִבְּהוֹן.","וּמַה דְּאָמַר (את כל העשוקים) וְהִנִּה דִּמְעַת הָעֲשׁוּקִים, אִלֵּין אִינּוּן דְּמֵתִין בְּתּוּקְפָא דְּאִמְּהוֹן, אִלֵּין עַבְדִין לְאוֹשָדָא דִּמְעִין, לְכָל בְּנֵי עָלְמָא, בְּגִין דְּלֵית דִּמְעִין דְּנַפְקֵי מִלִּבָּא, כְּהָנֵי דִּמְעִין, דְּכָל בְּנִי עָלְמָא תָּוְוהִין וְאַמְרִין, דִּינִין דְּקוּדְשָׁא בְּרִיךְ הוּא קְשׁוֹט אִינּוּן, וְעַל אֹרַח קְשׁוֹט אַזְלֵי. הָנִי מִסְכְּנֵי יְנוּקֵי דְּלָא חָאבוּ, אֲמַאי מִיתוּ. אָן דִּינָא דִּקְשׁוֹט, דְּעָבִיד מָארֵי עָלְמָא. אִי בְּחוֹבֵי אֲבָהַתְהוֹן אִסְתַּלְּקֵי מֵעָלְמָא, אֲמַאי. וַדַּאי אֵין לָהֶם מְנַחֵם.","תּוּ, וְהִנֵּה דִּמְעַת הָעֲשׁוּקִים, הַהוּא דִּמְעָה דִּלְהוֹן בְּהַהוּא עָלְמָא, דְּקָא מְגִינִּין עַל חַיָּיָא. דִּתְנָן אֲתָר אִית מִתְתַּקְנָא לוֹן בְּהַהוּא עָלְמָא, דְּאֲפִילּוּ צַדִּיקִים גְּמוּרִים לָא יַכְלִין לְקַיְּימָא תַּמָן, וְקוּדְשָׁא בְּרִיךְ הוּא רָחִים לוֹן, וְאִתְדָּבַּק בְּהוּ, וְאַתְקִין בְּהוּ, (צ\"ו ע\"ב) מְתִיבְתָּא עִלָּאָה דִּילֵיהּ. וְעָלַיְיהוּ כְּתִיב, (תהילים ח׳:ג׳) מִפִּי עוֹלְלִים וְיוֹנְקִים יִסַּדְתָּ עֹז. וּמַאי תּוֹעַלְתָּא עַבְדִין תַּמָּן, וַאֲמַאי סַלְּקִין תַּמָּן. דִּכְתִּיב, (תהילים ח׳:ג׳) לְמַעַן צוֹרְרֶיךָ לְהַשְׁבִּית אוֹיֵב וּמִתְנַקֵּם. וְכֵן אִית אֲתָר אָחֳרָא לְבַעֲלֵי תִּיּוּבְתָּא. (תחזור לעיל דף ק\"ו תנינן לית מלה)","תָּנֵינָן, עֲשָׂרָה דְּבָרִים אִתְבְּרִיאוּ בְּעֶרֶב שַׁבָּת כוּ'. הַכְּתָב וְהַמִּכְתָּב וְהַלּוּחוֹת. דִּכְתִּיב וְהַלֻּחֹת מַעֲשֵׂה אֱלֹהִים הֵמָּה וְהַמִּכְתָּב מִכְתַּב אֱלֹהִים הוּא. מַאי אִירְיָא מִדְּהָכִי דְּעֶרֶב שַׁבָּת הֲוָה, וְדִילְמָא אֶלֶף שְׁנִין לְבָתַר, אוֹ בְּשַׁעֲתָא דְּקַיְימוּ יִשְׂרָאֵל עַל טוּרָא דְּסִינַי. אֶלָּא, וַדַּאי הָכִי הוּא דְּבְּעֶרֶב שַׁבָּת הֲוָה. תָּא חֲזֵי, בְּכָל עוֹבָדָא דִּבְרֵאשִׁית, לָא אִתְּמַר שֵׁם מָלֵא, אֶלָּא אֱלֹהִים, אֱלהִים, בְּכָל מַה דְּאִתְבְּרֵי. וְכֻלְּהוּ שֵׁם אֱלֹהִים, עַד דְּכָל עוֹבָדָא אִשְׁתָּכְלַל בְּעֶרֶב שַׁבָּת. מִדְּאִשְׁתָּכְלַלוּ כָּל עוֹבָדָא, אִקְרֵי יְיָ' אֱלֹהִים, שֵׁם מָלֵא.","וְאַף עַל גַּב דִּבְשֵׁם אֱלֹהִים אִתְבְּרֵי כֹּלָּא, לָא אִשְׁתָּכְלַל בַּעֲשִׂיָּה, כָּל מַה דְּאִתְבְּרֵי, עַד עֶרֶב שַׁבָּת. בְּהַהִיא שַׁעֲתָא אִשְׁתָּכְלַל כֹּלָּא בַּעֲשִׂיָּה, דִּכְתִּיב, (בראשית ב׳:ב׳) מְלַאכְתּוֹ אֲשֶׁר עָשָׂה. מִכָּל מְלַאכְתּוֹ אֲשֶׁר עָשָׂה. וְקַיְּימָא בְּמַעֲשֶׂה. וְעַל דָּא כְּתִיב, וְהַלֻּחֹת מַעֲשֵׂה אֱלהִים, כַּד אִשְׁתָּכְלַל עָלְמָא, בְּשֵׁם אֱלֹהִים בְּמַעֲשֶׂה, וְלָא לְבָתַר, דִּכְתִּיב יְיָ' אֱלֹהִים וּבְדָא אִשְׁתָּכְלַל עָלְמָא, וְקַיְּימָא עַל קִיוּמֵיהּ.","תָּא חֲזֵי, בְּהַהִיא שַׁעֲתָא דְּתָבַר מֹשֶׁה הַלּוּחוֹת, דִּכְתִּיב, (שמות ל״ב:י״ט) וַיְשַׁבֵּר אוֹתָם תַּחַת הָהָר. צָף אוֹקְיָינוּס מֵאַתְרֵיהּ, וְסָלִיק לְשַׁטְּפָא עָלְמָא. חָמָא מֹשֶׁה דְּאוֹקְיָינוּס סָלִיק לְגַבַּיְיהוּ, וַהֲוָה בָּעֵי לְשַׁטְּפָא עָלְמָא, מִיָּד וַיִּקַּח אֶת הָעֵגֶל אֲשֶׁר עָשׁוֹּ וַיִּשְׂרוֹף אוֹתוֹ בָּאֵשׁ וְגוֹ', וַיִּזֶר עַל פְּנִי הַמַּיִם. קָם מֹשֶׁה עַל מֵי אוֹקְיָינוּס וְאָמַר, מַיָּא מַיָּא מָה אַתּוּן בָּעָאן. אָמְרוּ וְכִי אִתְקַיָּים עָלְמָא אֶלָּא בְּאוֹרַיְיתָא דְּלוּחוֹת, וְעַל אוֹרַיְיתָא דְּשָׁקְרוּ בָּהּ יִשְׂרָאֵל (ד\"א ועבדו עגלא דדהבא, אנן בעאן לשטפא עלמא.)","מִיָּד אָמַר לוֹן, הָא כָּל מַה דְּעָבְדוּ בְּחוֹבָא דְּעֶגְלָא, הָא מָסִיר לְכוֹן, וְלָא דַּי כָּל אִינּוּן אַלְפִין דְּנָפְלוּ מִנַּיְיהוּ, מִיָּד וַיִּזֶר עַל פְּנִי הַמַּיִם. לָא הֲווֹ מִשְׁתַּכְכֵי מַיָּא, עַד דְּנָטִיל מַיָּא מִנַּיְיהוּ וְאַשְׁקֵי לוֹן, מִיָּד אִשְׁתְּקַע אוֹקְיָינוּס בְּאַתְרֵיהּ.","דְּהָא בְּהַהוּא מִדְבָּר לָא הֲווֹ מַיָּא, דִּכְתִּיב, (במדבר כ׳:ה׳) לא מְקוֹם זֶרַע וְגוֹ'. וּמַיִם אַיִן לִשְׁתּוֹת. וְאִי תֵּימָא, לְבֵירָא דְּמִרְיָם אַרְמִי לֵיהּ. חַס וְשָׁלוֹם, דְּתַמָּן שָׁדֵי מֹשֶׁה דֻּכְרָנָא בִּישָׁא דָּא לְמִשְׁתֵּי לְבָתַר. וְתוּ, דְּעַד כָּאן לָא הֲוָה לְהוּ בֵּירָא, עַד דְּאָתוּ לְמִדְבַּר מַתָּנָה, דִּכְתִּיב, (במדבר כ״א:י״ח) בְּאֵר חֲפָרוּהָ שָׂרִים וְגוֹ'. וּמִמִּדְבָּר מַתָּנָה. מִתַּמָּן יַרְתּוּ בֵּירָא. כְּתִיב הָכָא עַל פְּנֵי הַמַּיִם, וּכְתִיב הָתָם (בראשית א׳:ב׳) עַל פְּנִי תְהוֹם."],[[0,"ואית עשוק אחר וכו':","ויש עשוק אחר, עשוק ההוא שנקרא ממזר. כשנפטר מעולם מבדילים אותו מיד מקהלת העם הקדוש. ממזר ההוא העני והמסכן, שופך דמעות לפני הקב\"ה וטוען לפניו, רבון העולם, אם אבותי חטאו, אני איזה חוב עשיתי, הרי מעשי היו כשרים לפניך. והנה דמעת העשוקים ואין להם מנחם. וכן לכל אלו עשוקים יש להם טענה לפני הקב\"ה, ומטענה ההיא אין להם מנחם, ואין מי שישוב מלה על לבם."],[1,"ומה דאמר, והנה וכו':","ומה שאמר, והנה דמעת העשוקים, הם, אלו שמתו בחיק אמם, אלו עושים לשפוך דמעות לכל בני העולם, משום שאין דמעות יוצאות מן הלב כאלו דמעות, כי כל בני העולם תמהים ואומרים הרי דינים של הקב\"ה אמת הם, ועל דרך אמת הולכים, אלו ילדים המסכנים שלא חטאו למה מתו, איפה דין אמת שעושה רבון העולם. ואם בעונות אבותם נסתלקו מן העולם, למה. ודאי אין להם מנחם."],[2,"תו, והנה דמעת העשוקים:","דמעה ההיא שלהם, בעולם ההוא, הם מגינים על החיים. שלמדנו, מקום יש המתוקן להם בעולם ההוא, שאפילו צדיקים גמורים אינם יכולים לעמוד שם, והקב\"ה אוהב אותם ומתדבק בהם, ומתקן בהם ישיבה העליונה שלו. ועליהם כתוב, מפי עוללים ויונקים יסדת עז. ומהו התועלת שעושים שם ולמה עולים שם. הוא כמו שכתוב, למען צורריך להשבית אויב ומתנקם. וכן יש מקום אחר לבעלי תשובה."],[3,"תנינן עשרה דברים וכו':","למדנו עשרה דברים נבראו בערב שבת וכו'. הכתב והמכתב והלוחות. שכתוב והלוחות מעשה אלקים המה. והמכתב מכתב אלקים הוא. שואל, מהו הראיה מכאן שהיה בערב שבת, ואולי אלף שנה אחר כך. או בשעה שעמדו ישראל על הר סיני. ומשיב, אלא ודאי כן הוא, שבערב שבת היה. בוא וראה, בכל מעשה בראשית לא נאמר שם מלא, אלא אלקים אלקים נאמר בכל מה שנברא. וכולם הם שם אלקים עד שכל המלאכה נשתכללה בערב שבת. משנשתכללו כל המעשים נקרא הוי\"ה אלקים שם מלא."],[4,"ואע\"ג דבשם אלקים וכו':","ואע\"פ שבשם אלקים נברא הכל, לא נשתכלל בעשיה כל מה שנברא עד ערב שבת. בשעה ההיא נשתכלל הכל בעשיה, שכתוב מלאכתו אשר עשה. מכל מלאכתו אשר עשה. היינו שעמדה במעשה. וע\"כ כתוב, והלחת מעשה אלקים, דהיינו כאשר נשתכלל העולם בשם אלקים במעשה, שהוא בערב שבת, ולא לאחר כך שכתוב, הוי\"ה אלקים. ובזה נשתכלל העולם ועמד על קיומו."],[5,"ת\"ח בההיא שעתא וכו':","בוא וראה, בשעה ההיא ששבר משה את הלוחות, שכתוב וישבר אותם תחת ההר, צף הים אוקיינוס ממקומו, ועלה להטביע העולם. מיד, ויקח את העגל אשר עשו וישרוף אותו באש וגו', ויזר על פני המים. קם משה על מי אוקיינוס, ואמר, מים מים מה אתם רוצים. אמרו, הרי לא נתקיים העולם אלא על התורה דלוחות, ועל התורה ששקרו בה ישראל ועשו עגל הזהב, אנו רוצים לשטוף את העולם."],[6,"מיד אמר לון וכו':","מיד אמר להם, הנה כל מה שעשו בעון העגל מסור לכם, ולא די כל אלו האלפים שנפלו מהם, מיד ויזר על פני המים. ועוד לא היו משתככים המים, עד שלקח מים מהם, ממימי אוקיינוס, והשקה אותם. מיד נשקע האוקיינוס במקומו."],[7,"דהא בההוא מדבר וכו':","כי במדבר ההוא לא היה מים, שכתוב, לא מקום זרע וגו' ומים אין לשתות ובהכרח שלקח ממימי אוקיינוס. ואם תאמר, שלבארה של מרים השליך האפר. חס ושלום שישלך שם משה זכרון הרע הזה, ולשתות אחר כך. ועוד, דעד עתה עוד לא היתה להם באר, עד שבאו למדבר מתנה. שכתוב, באר חפרוה שרים וגו' וממדבר מתנה. משם ירשו הבאר. כתוב כאן, על פני המים, וכתוב שם על פני תהום. מה שם אוקיינוס אף כאן אוקיינוס."]],[[0,"","וְיִשִׁ עָשׁוּק אַחֵר, אוֹתוֹ עָשׁוּק שֶׁנִּקְרָא מַמְזֵר, כְּשֶׁיּוֹצֵא מִן הָעוֹלָם, מִיָּד מַפְרִידִים אוֹתוֹ מִקְּהִלַּת הָעָם הַקָּדוֹשׁ. אוֹתוֹ מַמְזֵר, עָנִי מִסְכֵּן, שׁוֹפֵךְ דְּמָעוֹת לִפֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְטוֹעֵן לְפָנָיו: רִבּוֹן הָעוֹלָם, אִם אֲבוֹתַי חָטְאוּ, אֵיזֶה חֵטְא אֲנִי עָשִׂיתִי? הֲרֵי מַעֲשַׂי תְּקִינִים הָיוּ לְפָנֶיךְ, וְהִנֵּה דִּמְעַת הָעֲשׁוּקִים וְאֵין לָהֶם מְנַחֵם. וְכֵן לְכָל אוֹתָם עֲשׁוּקִים יֵשׁ לָהֶם טַעֲנָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמֵאוֹתָהּ טַעֲנָה אֵין לָהֶם מְנַחֵם, וְאֵין שֶׁיָּשִׁיב דָּבָר עַל לִבָּם."],[1,"","וּמַה שֶּׁאָמַר וְהִנֵּה דִּמְעַת הָעֲשׁוּקִים - אֵלּוּ אוֹתָם שֶׁמֵּתִים בְּחֵיק אִמּוֹתֵיהֶם, אֵלֶּה עוֹשִׂים לִשְׁפֹּךְ דְּמָעוֹת לְכָל בְּנֵי הָעוֹלָם, מִשּׁוּם שֶׁאֵין דְּמָעוֹת שֶׁיּוֹצְאוֹת מִן הַלֵּב כַּדְּמָעוֹת הַלָּלוּ, שֶׁכָּל בְּנֵי הָעוֹלָם תּוֹהִים וְאוֹמְרִים: דִּינֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הֵם אֱמֶת, וְהוֹלְכִים עַל דֶּרֶךְ אֱמֶת. הַתִּינוֹקוֹת הַמִּסְכֵּנִים הַלָּלוּ שֶׁלֹּא חָטְאוּ, לָמָּה מֵתוּ? אֵיפֹה דִּין הָאֱמֶת שֶׁעוֹשֶׂה רִבּוֹן הָעוֹלָם? אִם בַּחֲטָאֵי אֲבוֹתָם מִסְתַּלְּקִים מִן הָעוֹלָם - לָמָּה? וַדַּאי אֵין לָהֶם מְנַחֵם."],[2,"","עוֹד, וְהִנֵּה דִּמְעַת הָעֲשׁוּקִים - אוֹתָהּ דִּמְעָה שֶׁלָּהֶם בְּאוֹתוֹ הָעוֹלָם, שֶׁמְּגִנִּים עַל הַחַיִּים. שֶׁשָּׁנִינוּ, יֵשׁ מָקוֹם מְתֻקָּן לָהֶם בְּאוֹתוֹ עוֹלָם שֶׁאֲפִלּוּ צַדִּיקִים גְּמוּרִים לֹא יְכוֹלִים לַעֲמֹד שָׁם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא אוֹהֵב אוֹתָם וְנִדְבָּק בָּהֶם, וּמְתַקֵּן בָּהֶם אֶת הַיְשִׁיבָה הָעֶלְיוֹנָה שֶׁלּוֹ, וַעֲלֵיהֶם כָּתוּב (תהלים ח) מִפִּי עוֹלְלִים וְיֹנְקִים יִסַּדְתָּ עֹז. וּמָה הַתּוֹעֶלֶת שֶׁעוֹשִׂים שָׁם, וְלָמָּה עוֹלִים לְשָׁם? שֶׁכָּתוּב לְמַעַן צוֹרְרֶיךְ לְהַשְׁבִּית אוֹיֵב וּמִתְנַקֵּם. וְכֵן יֵשׁ מָקוֹם אַחֵר לְבַעֲלֵי תְשׁוּבָה."],[3,"","שָׁנִינוּ, עֲשָׂרָה דְבָרִים נִבְרְאוּ בְּעֶרֶב שַׁבָּת וְכוּ'. הַכְּתָב וְהַמִּכְתָּב וְהַלּוּחוֹת, שֶׁכָּתוּב (שמות לב) וְהַלֻּחֹת מַעֲשֵׂה אֱלֹהִים הֵמָּה וְהַמִּכְתָּב מִכְתַּב אֱלֹהִים הוּא. מָה הַמְדֻבָּר מִכָּךְ שֶׁהָיָה עֶרֶב שַׁבָּת, וְאוּלַי זֶה הָיָה אֶלֶף שָׁנָה אַחַר כָּךְ, אוֹ בְּשָׁעָה שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי? אֶלָּא וַדַּאי שֶׁזֶּה הָיָה בְּעֶרֶב שַׁבָּת. בֹּא וּרְאֵה, בְּכָל מַעֲשֵׂה בְרֵאשִׁית לֹא נֶאֱמַר שֵׁם מָלֵא, אֶלָּא אֱלֹהִים אֱלֹהִים בְּכָל מַה שֶּׁנִּבְרָא, וְכֻלָּם שֵׁם אֱלֹהִים, עַד שֶׁכָּל הַמַּעֲשֶׂה נִתְקַן בְּעֶרֶב שַׁבָּת. מִשֶּׁנִּתְקְנוּ כָּל הַמַּעֲשִׂים, נִקְרָא ה' אֱלֹהִים, שֵׁם מָלֵא."],[4,"","וְאַף עַל גַּב שֶׁהַכֹּל נִבְרָא בְּשֵׁם אֱלֹהִים, לֹא נִתְקַן בָּעֲשִׂיָּה כָּל מַה שֶּׁנִּבְרָא עַד עֶרֶב שַׁבָּת. בְּאוֹתָהּ שָׁעָה הַכֹּל נִתְקַן בָּעֲשִׂיָּה, שֶׁכָּתוּב (בראשית ב) מְלַאכְתּוֹ אֲשֶׁר עָשָׂה. מִכָּל מְלַאכְתּוֹ אֲשֶׁר עָשָׂה. וְעוֹמֵד בְּמַעֲשֶׂה. וְלָכֵן כָּתוּב וְהַלֻּחֹת מַעֲשֵׂה אֱלֹהִים, כְּשֶׁנִּתְקַן הָעוֹלָם בְּשֵׁם אֱלֹהִים בְּמַעֲשֶׂה, וְלֹא אַחַר כָּךְ, שֶׁכָּתוּב ה' אֱלֹהִים. וּבָזֶה נִתְקַן הָעוֹלָם וְעָמַד עַל קִיּוּמוֹ."],[5,"","בֹּא וּרְאֵה, בְּאוֹתָהּ שָׁעָה שֶׁשָּׁבַר מֹשֶׁה אֶת הַלּוּחוֹת, שֶׁכָּתוּב (שמות לב) וַיְשַׁבֵּר אֹתָם תַּחַת הָהָר, צָף הָאוֹקְיָנוֹס מִמְּקוֹמוֹ וְעָלָה לִשְׁטֹף אֶת הָעוֹלָם. רָאָה מֹשֶׁה שֶׁאוֹקְיָנוֹס עוֹלֶה אֲלֵיהֶם וְהָיָה רוֹצֶה לִשְׁטֹף אֶת הָעוֹלָם, מִיָּד - וַיִּקַּח אֶת הָעֵגֶל אֲשֶׁר עָשׂוּ וַיִּשְׂרֹף בָּאֵשׁ וְגוֹ', וַיִּזֶר עַל פְּנֵי הַמַּיִם. עָמַד מֹשֶׁה עַל מֵי הָאוֹקְיָנוֹס וְאָמַר: מַיִם מַיִם, מָה אַתֶּם רוֹצִים? אָמְרוּ: וְכִי מִתְקַיֵּם הָעוֹלָם אֶלָּא בְּתוֹרַת הַלּוּחוֹת?! וְעַל הַתּוֹרָה שֶׁשִּׁקְּרוּ בָהּ בְּנֵי יִשְׂרָאֵל (ועשואתעגלהזהבאנורוציםלשטף את העולם)."],[6,"","מִיָּד אָמַר לָהֶם: הֲרֵי כָּל מַה שֶּׁעָשׂוּ בְּחֵטְא הָעֵגֶל, הֲרֵי מָסוּר לָכֶם, וְלֹא דַי כָּל אוֹתָם הָאֲלָפִים שֶׁנָּפְלוּ מֵהֶם?! מִיָּד - וַיִּזֶר עַל פְּנֵי הַמַּיִם. וְלֹא הָיוּ הַמַּיִם שׁוֹכְכִים עַד שֶׁנָּטַל מֵהֶם וְהִשְׁקָה אוֹתָם. מִיָּד נִשְׁקַע הָאוֹקְיָנוֹס בִּמְקוֹמוֹ."],[7,"","שֶׁהֲרֵי בְּאוֹתוֹ הַמִּדְבָּר לֹא הָיוּ מַיִם, שֶׁכָּתוּב (במדבר כ) לֹא מְקוֹם זֶרַע וְגוֹ'. וּמַיִם אַיִן לִשְׁתּוֹת. וְאִם תֹּאמַר, לִבְאֵר מִרְיָם זָרַק - חַס וְשָׁלוֹם שֶׁשָּׁם יִזְרֹק מֹשֶׁה אֶת הַזִּכָּרוֹן הָרָע הַזֶּה לִשְׁתּוֹת מִמֶּנּוּ אַחַר כָּךְ. וְעוֹד, שֶׁעַד עַכְשָׁו לֹא הָיְתָה לָהֶם בְּאֵר, עַד שֶׁבָּאוּ לְמִדְבַּר מַתָּנָה, שֶׁכָּתוּב בְּאֵר חֲפָרוּהָ שָׂרִים וְגוֹ'. וּמִמִּדְבָּר מַתָּנָה. מִשָּׁם יָרְשׁוּ בְאֵר. כָּתוּב עַל פְּנֵי הַמַּיִם, וְכָתוּב שָׁם עַל פְּנֵי תְהוֹם."]]],[["חָרוּת עַל הַלֻּחֹת, מַאי חָרוּת עַל הַלֻּחֹת. הָכִי אוּקְמוּהָ, חֵירוּת מִמַּלְאַךְ הַמָּוֶת, חֵירוּת מִשִּׁעְבּוּד מַלְכִיּוֹת, חֵירוּת מִכֹּלָּא, הָכִי הוּא. וּמַאי חָרוּת. גּוּשְׁפַּנְקָא דְּעָלְמָא דְּאָתֵי, דְּבֵיהּ הֲוָה חֵירוּת, בְּכָל מִינֵי חֵירוּת. וְאִלְמָלֵא לָא אִתְּבָּרוּ, כָּל מַה דְּאָתָא לְעָלְמָא לְבָתַר, לָא אָתָא, וַהֲווּ יִשְׂרָאֵל דִּיּוּקְנָא דְּמַלְאָכִין עִלָּאִין דִּלְעֵילָּא. וְעַל דָּא אַכְרִיז קְרָא וְאָמַר, וְהַלּוּחֹת מַעֲשֵׂה אֱלֹהִים וְגוֹ', לָא תֵּימָא דִּלְבָתַר דְּעָלְמָא אִשְׁתָּכְלַל, וְאַדְכַּר שֵׁם מָלֵא הָווֹ, אֶלָּא בְּשַׁעֲתָא דְּאִשְׁתָּכְלַל בְּשֵׁם אֱלהִים, עַד לָא יֵיעוּל שַׁבָּת.","הֵמָּה, מַאי הֵמָּה. הִפּוּךְ מה\"ה הָווֹ. מִתְּרֵין סִטְרִין הָווֹ. חֲדָא בְּעוֹבָדָא, וַחֲדָא דְּחֵירוּת לְעֵילָא, רָשִׁים לְעֵילָּא לְנַטְרָא לְכֹלָּא. וְעַל דָּא המ\"ה. וְהַמִּכְתָּב מִכְתַּב אֱלהִים הוּא, אֶשָּׁא אוּכָמָא עַל גַּבֵּי אֶשָּׁא חִוָּורָא. מִכְתַּב אֱלהִים הוּא, הַיְינוּ דִּכְתִּיב, (במדבר י״ח:כ״ג) וְעָבַד הַלֵּוִי הוּא. חָרוּת כְּמָה דְּאִתְּמַר, דְּהָא יוֹבֵל קָרֵי חָרוּת, וְעָבִיד חֵירוּת לְכָל עָלְמִין.","עֲד כָּאן חַבְרַיָּיא. מִכָּאן וְהָלְאָה תִּנְדְּעוּן, דְּהָא סִטְרָא בִּישָׁא, לָא שַׁלְטָא עָלַיְיכוּ וַאֲנָא יֵיבָא סָבָא, קָאִימְנָא קָמַיְיכוּ, לְאִתְּעָרָא מִלִּין אִלֵּין, קָמוּ אִינּוּן, כְּמַאן דְּאִתְּעַר מִשֵּׁינָתֵיהּ, וְאִשְׁתְּטָחוּ קָמֵיהּ, וְלָא הֲווֹ יַכְלִין לְמַלְּלָא. לְבָתַר שַׁעֲתָא בָּכוּ.","פָּתַח רַבִּי חִיָּיא וְאָמַר, (שיר השירים ח׳:ו׳) שִׂימֵנִי כַחוֹתָם עַל לִבֶּךָ כַּחוֹתָם עַל זְרוֹעֶךָ וְגוֹ', שִׂימֵנִי כַחוֹתָם, בְּשַׁעֲתָא דְּאִתְדַּבְּקָא כְּנֶסֶת יִשְׂרָאֵל בְּבַעְלָהּ, אִיהִי אַמְרַת שִׂימֵנִי כַחוֹתָם, (ויחי רמ\"ד ע\"ב) אָרְחָא דְּחוֹתָם, כֵּיוָן דְּאִתְדַּבָּק בְּהַהוּא אֲתָר דְּאִתְדַּבָּק שָׁבִיק בֵּיהּ כָּל דִּיּוּקְנֵיהּ, אַף עַל גַּב דְּהַהוּא חוֹתָם אָזִיל הָכָא וְהָכָא, וְלָא קַיְּימָא תַּמָּן, וְהָא אִתְעֲבָר מִנֵּיהּ, כָּל דִּיּוּקְנֵיהּ שָׁבִיק תַּמָּן, וְתַמָּן קַיְּימָא. אוּף הָכִי אַמְרַת כְּנֶסֶת יִשְׂרָאֵל, כֵּיוָן דְּאִתְדַּבָּקְנָא בָּךְ, כָּל דִּיּוּקְנִי לִיהֲוֵי חָקִיק בָּךְ, דְּאַף עַל גַּב דְּאֵיזִיל הָכָא אוֹ הָכָא, תִּשְׁכַּח דִּיּוּקְנִי חָקִיק בָּךְ, וְתִדְכַּר לִי.","וְכַחוֹתָם עַל זְרוֹעֶךָ, כְּמָה דִּכְתִּיב, (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי, אוּף הָכִי, תְּהֵא דִּיּוּקְנִי חָקִיק תַּמָּן. וּבְכֵן אֱהֵא בָּךְ מִתְדַּבְּקָא לְעָלְמִין, וְלָא אִתְנְּשֵׁי מִינָךְ. כִּי עַזָּה כַמָּוְת אַהֲבָה, תַּקִּיפָא כַּמָּוֶת אַהֲבָה, בְּתּוּקְפָא תַּקִּיף, כְּהַהוּא אֲתָר דְּשַׁרְיָא בֵּיהּ מוֹתָא. אַהֲבָה, הַהוּא אֲתָר דְּאִקְרֵי אַהֲבַת עוֹלָם.","קָשָׁה כִשְׁאוֹל קִנְאָה, אוּף הָכִי, דְּהָא אִלֵּין שְׁמָהָן, מֵהַהוּא סִטְרָא אִינּוּן. רְשָׁפֶיהָ רִשְׁפֵּי אֵשׁ, מַאן אִינּוּן רִשְׁפֵּי אִלֵּין. אִינּוּן אַבְנִין וּמַרְגְּלָן טָבָאן, דְּאִתְיְלִידוּ מֵהַהוּא אֵשׁ. שַׁלְהֶבֶת יָהּ. מֵהַהוּא שַׁלְהוֹבָא, דְּנָפְקָא מֵעָלְמָא עִלָּאָה, וְאִתְאַחֲדָא בִּכְנֶסֶת יִשְׂרָאֵל, לְמֶהֱוֵי כֹּלָּא חַד יִחוּדָא, וַאֲנָן, הָא אַהֲבָה וּרְשָׁפִין דְּשַׁלְהוֹבָא דְּלִבָּא אֲבַתְרָךְ, יְהֵא רַעֲוָא, דְּדִיּוּקְנָא דִּילָן, תְּהֵא חֲקוּקָה בְּלִבָּךְ, כְּמָה דְּדִיּוּקְנָא דִּילָךְ חַקּוּק בְּלִבָּן. נָשַׁק לוֹן, וּבָרִיךְ לוֹן וְאָזְלוּ.","כַּד מָטוּ לְגַבֵּי דְּרַבִּי שִׁמְעוֹן, וְסָחוּ לֵיהּ כָּל מַה דְּאִירַע לוֹן, חַדֵּי וְתַוָּוה, אָמַר, זַכָּאִין אַתּוּן דְּזָכִיתוּן לְכָל הַאי, וּמַה הֲוֵיתוּן בַּהֲדֵי אַרְיָא עִלָּאָה, גִּיבָּר תַּקִּיף, דְּלָא הֲווֹ כַּמָּה גִּיבָּרִין לְגַבֵּיהּ כְּלוּם, וְלָא יְדַעְתּוּן לְאִשְׁתְּמוֹדְעָא לֵיהּ מִיַּד. תַּוָוהְנָא, אֵיךְ אִשְׁתְּזַבְתּוּן מֵעוֹנְשָׁא דִּילֵיהּ, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְשֵׁזָבָא לְכוֹן, קָרָא עָלַיְיהוּ, (משלי ד׳:י״ח) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וְאוֹר עַד נְכוֹן הַיּוֹם. (משלי ד׳:י״ח) בְּלֶכְתְּךָ לא יֵצֶר צַעֲדֶךָ וְאִם תָּרוּץ לא תִכָּשֵׁל. (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִיקִים לְעוֹלָם יִרְשׁוּ אָרֶץ נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר. (ע\"כ מן רב ייבא סבא). אמרו המגיהים מצאנו ראינו הפקודים האלה בהעתקות הנמצאות עמנו היום מוטעים לכן אל נא ישיתו המעיינים עלינו חטאת. ועם העתקות מדויקות יתקנו המעוות וישימו העקוב למישור וכעת הגהנום כיד ה' הטובה עלינו","\u0003רעיא מהימנא\u0004 (מ) כִּי יִנָּצוּ אֲנָשִׁים. אִלֵּין, מִיכָאֵל וְס\"מ. וְנָגְפוּ אִשָּׁה הָרָה, דָּא כְּנֶסֶת יִשְׂרָאֵל. וְיָצְאוּ יְלָדֶיהָ, בְּגָלוּתָא. עָנוֹשׁ יֵעָנֵשׁ, דָּא ס\"מ, כַּאֲשֶׁר יָשִׁית עָלָיו בַּעַל הָאִשָּׁה, דָּא קוּדְשָׁא בְּרִיךְ הוּא.","פִּקּוּדָא (מא) בָּתַר דָּא, לְהָשִׁיב אֲבֵדָה. וַאֲבַתְרֵיהּ לְהָשִׁיב הַגֶּזֶל. אָמַר בּוּצִינָא קַדִּישָׁא, קוּדְשָׁא בְּרִיךְ הוּא עָתִיד לְאָהַדְרָא לָךְ, אֲבֵדָה דְּאָבְדַתּ בְּגִין עֵרֶב רַב, וְדָא כַּלָּה דִּילָךְ, דִּבְזִמְנָא דְּעָבְדוּ עֵרֶב רַב יַת עֶגְלָא, נַפְקַת כַּלָּה דִּילָךְ, הֲדָא הוּא דִכְתִיב, (שמות ל״ב:י״ט) וַיַּשְׁלֵךְ מִיָּדָו אֶת הַלֻּחֹת."],[[0,"חרות על הלחת:","מהו חרות על הלחת. ומשיב כך העמדנו, חירות ממלאך המות, חירות משעבוד מלכיות, חירות מכל. וכך הוא. ומהו חירות. הוא, החותם של עולם הבא, שבו הוא חירות בכל מיני חירות. ואם לא נשברו הלוחות, כל מה שבא אח\"כ לעולם לא היה בא, והיו ישראל בצורת מלאכים עליונים שלמעלה. ועל זה הכריז הכתוב, ואמר, והלחת מעשה אלקים וגו', שאל תאמר, שלאחר שנשתכלל העולם ונזכר שם מלא הויה אלקים, היו הלוחות, אלא משעה שנשתכלל העולם בשם אלקים, מטרם שבא השבת. כנ\"ל."],[1,"המה, מאי המה וכו':","שואל, כתוב מעשה אלקים המה, מהו המה. שהוא מיותר. ומשיב, הפוך המ\"ה ותמצא מה\"ה, שפירושו מב' צדדים, דהיינו מב' ההין של שם הוי\"ה. בינה ומלכות. אחד, במעשה, שהוא ה' אחרונה, מלכות. ואחד מחירות של מעלה, שהוא ה' ראשונה, בינה רשום למעלה, בבינה, לשמור הכל. ועל זה, כתוב, המה. \u0003והמכתב מכתב אלקים הוא,\u0004 היינו אש שחורה על אש לבנה, מכתב אלקים הוא היינו שכתוב, ועבד הלוי \u0003הוא\u0004, שהוא בינה הנקראת, \u0003הוא.\u0004 שהוא חירות, כמו שאמרנו, כי יובל, דהיינו בינה, הנקראת חירות, ועושה חירות לכל העולם."],[2,"ע\"כ חבריא, מכאן וכו':","עד כאן דברי, מכאן והלאה תדעו, שצד הרע לא ישלוט עליכם. ואני ייבא סבא עומד לפניכם להעיר דברים אלו. קמו אלו, ר\"ח ור\"י, כמי שהעיר משנתו והשתטחו לפניו, ולא יכלו לדבר, לאחר כך, בכו."],[3,"פתח ר' חייא וכו':","פתח ר\"ח ואמר, שימני כחותם על לבך כחותם על זרועך וגו'. \u0003שימני כחותם\u0004 בשעה שנתדבקה כנסת ישראל שהיא המלכות, בבעלה, ז\"א. היא אמרה, שימני כחותם, הדרך של החותם הוא, כיון שנתדבק במקום ההוא שנתדבק, עזב בו כל צורתו, אע\"פ שחותם ההוא הולך כאן וכאן, ואינו עומד שם, וכבר עבר ממנו, כל צורתו עזב שם, ושם עומדת צורתו. אף כנסת ישראל אמרה כן, כיון שנתדבקתי בך, כל צורתי תהיה חקוקה בך, ואע\"פ שאלך כאן או כאן תמצא צורתי חקוקה בך, ותזכור אותי."],[4,"וכחותם על זרועך:","היינו כמו שכתוב, שמאלו תחת לראשי וימינו תחבקני. אף כן, תהיה צורתי חקוקה שם, ובכן אהיה מתדבקת בך לעולם ולא אשכח ממך. \u0003כי עזה כמות אהבה,\u0004 חזק כמות האהבה, בגבורה חזקה כאותו מקום ששורה בו המות. \u0003אהבה,\u0004 הוא אותו מקום שנקרא אהבת עולם."],[5,"קשה כשאול קנאה וכו':","אף זה כן. כנ\"ל אצל האהבה, כי אלו השמות, אהבה קנאה, באים מצד ההוא, דהיינו מצד השמאל, \u0003רשפיה רשפי אש,\u0004 שואל, מי הם רשפים אלו. ואומר, אלו הם אבנים ומרגליות טובות שנולדו מאש הזה, שהן מדרגות עליונות, דהיינו משלהבת ההוא היוצאת מעולם העליון, מקו שמאל דבינה, ונאחזת בכנסת ישראל, שתהיה הכל יחוד אחד. ואמר אל הסבא ואנו, הרי אהבה ורשפי שלהבת הלב אחריך, יהי רצון שהצורה שלנו תהיה חקוקה בלבך, כמו שצורתך חקוקה בלבנו. נשק להם הסבא, וברך אותם והלכו."],[6,"כד מטו לגבי וכו':","כשהגיעו אל רבי שמעון וספרו לו כל מה שקרה אותם. תמה ואמר, אשריכם שזכיתם לכל זה. ומה, שהייתם עם אריה העליון, גבור אמיץ, שכמה גבורים הם אצלו כלום, ולא ידעתם להכיר אותו מיד. שמח ותמה אני, איך ניצלתם מעונשו, אלא הקב\"ה רצה להצילכם. קרא עליהם, וארח צדיקים כאור נגה הולך ואור עד נכון היום. בלכתך לא יצר צעדך וגו'. ועמך כלם צדיקים וגו'. עד כאן מן רב ייבא סבא."],[7,"כי ינצו אנשים וכו':","אלו מיכאל וסמאל. מיכאל מצד הקדושה וסמאל מצד הטומאה. \u0003ונגפו אשה הרה,\u0004 זו כנסת ישראל, דהיינו, המלכות, \u0003ויצאו ילדיה,\u0004 לגלות. \u0003ענוש יענש,\u0004 זה סמאל. כאשר ישית עליו בעל האשה, זה הקב\"ה."],[8,"פקודא בתר דא וכו':","המצוה שלאחר זה, הוא להשיב אבדה. ואחריה להשיב הגזל. אמר המאור הקדוש, היינו ר\"ש למשה רבנו, הקב\"ה עתיד להחזיר לך אבדה שאבדת מחמת הערב רב, וזו היא הכלה שלך, שהיא המלכות. כי משה הוא בעלה דמטרוניתא. כי בזמן שהערב רב עשו את העגל, נפלה הכלה שלך וז\"ש, וישלך מידיו את הלחת. הרומזים על המלכות."]],[[0,"","חָרוּת עַל הַלֻּחֹת. מַה זֶּה חָרוּת עַל הַלֻּחֹת? כָּךְ פֵּרְשׁוּהָ, חֵרוּת מִמַּלְאַךְ הַמָּוֶת, חֵרוּת מִשִּׁעְבּוּד מַלְכֻיּוֹת, חֵרוּת מֵהַכֹּל. כָּךְ הוּא. וּמַה זֶּה חֵרוּת? חוֹתָם שֶׁל הָעוֹלָם הַבָּא, שֶׁבּוֹ יֵשׁ חֵרוּת בְּכָל מִינֵי חֵרוּת. וְאִלְמָלֵא לֹא נִשְׁבְּרוּ, כָּל מַה שֶּׁבָּא לָעוֹלָם אַחַר כָּךְ - לֹא בָא, וְהָיוּ יִשְׂרָאֵל בִּדְיוֹקְנָאוֹת שֶׁל מַלְאָכִים עֶלְיוֹנִים שֶׁלְּמַעְלָה. וְעַל כָּךְ מַכְרִיז הַכָּתוּב וְאוֹמֵר וְהַלֻּחֹת מַעֲשֵׂה אֱלֹהִים וְגוֹ'. אַל תֹּאמַר שֶׁלְּאַחַר שֶׁהָעוֹלָם נִתְקַן וְנִזְכַּר שֵׁם מָלֵא הָיוּ, אֶלָּא בְּשָׁעָה שֶׁנִּתְקַן בְּשֵׁם אֱלֹהִים, טֶרֶם שֶׁנִּכְנְסָה שַׁבָּת."],[1,"","הֵמָּה, מַה זֶּה הֵמָּה? הָפוּךְ מה\"ה הָיוּ, מִשְּׁנֵי צְדָדִים הָיוּ - אֶחָד בְּמַעֲשֶׂה, וְאֶחָד מֵחֵרוּת שֶׁל מַעְלָה. רָשׁוּם לְמַעְלָה לִשְׁמֹר אֶת הַכֹּל. וְעַל זֶה הֵמָּ\"ה. וְהַמִּכְתָּב מִכְתַּב אֱלֹהִים הוּא - אֵשׁ שְׁחֹרָה עַל גַּבֵּי אֵשׁ לְבָנָה. מִכְתַּב אֱלֹהִים הוּא, הַיְנוּ שֶׁכָּתוּב וְעָבַד הַלֵּוִי הוּא. חָרוּת, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁהֲרֵי יוֹבֵל נִקְרָא חֵרוּת, וְעוֹשֶׂה חֵרוּת לְכָל הָעוֹלָמוֹת."],[2,"","לָכֵן, חֲבֵרִים, מִכָּאן וָהָלְאָה תֵּדְעוּ שֶׁהֲרֵי הַצַּד הָרָע לֹא שׁוֹלֵט עֲלֵיכֶם, וַאֲנִי יֵיבָא סָבָא עוֹמֵד לִפְנֵיכֶם לְעוֹרֵר דְּבָרִים אֵלּוּ. קָמוּ הֵם, כְּמִי שֶׁהִתְעוֹרֵר מִשְּׁנָתוֹ, וְהִשְׁתַּטְּחוּ לְפָנָיו, וְלֹא הָיוּ יְכוֹלִים לְדַבֵּר. אַחַר כְּשָׁעָה הֵם בָּכוּ."],[3,"","פָּתַח רַבִּי חִיָּיא וְאָמַר, שִׂימֵנִי כַחוֹתָם עַל לִבֶּךְ כַּחוֹתָם עַל זְרוֹעֶךְ וְגוֹ'. שִׂימֵנִי כַחוֹתָם, בְּשָׁעָה שֶׁנִּדְבְּקָה כְּנֶסֶת יִשְׂרָאֵל בְּבַעְלָהּ, הִיא אָמְרָה שִׂימֵנִי כַחוֹתָם עַל לִבֶּךְ. דֶּרֶךְ הַחוֹתָם, כֵּיוָן שֶׁנִּדְבָּק בְּאוֹתוֹ מָקוֹם שֶׁנִּדְבָּק, מַשְׁאִיר בּוֹ אֶת כָּל דְּיוֹקְנוֹ. אַף עַל גַּב שֶׁאוֹתוֹ חוֹתָם הוֹלֵךְ כָּאן וְכָאן וְלֹא עוֹמֵד שָׁם וְנֶעֱבָר מִמֶּנּוּ, כָּל דְּיוֹקְנוֹ מַשְׁאִיר שָׁם, וְשָׁם עוֹמֵד. אַף כָּךְ אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, כֵּיוָן שֶׁנִּדְבַּקְתִּי בְךְ, כָּל דְּיוֹקְנִי יִהְיֶה חָקוּק בְּךְ, שֶׁאַף עַל גַּב שֶׁאֵלֵךְ לְכָאן וּלְכָאן, תִּמְצָא אֶת דְּיוֹקְנִי חָקוּק בְּךְ וְתִזְכֹּר אוֹתִי."],[4,"","וְכַחוֹתָם עַל זְרוֹעֶךְ, כְּמוֹ שֶׁכָּתוּב (שירב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי, אַף כָּךְ יִהְיֶה דְיוֹקְנִי חָקוּק שָׁם, וּבְכֵן אֶהְיֶה דְבוּקָה בְּךְ לְעוֹלָמִים וְאַל אֶשְׁתַּכַּח מִמְּךְ. כִּי עַזָּה כַמָּוֶת אַהֲבָה, חֲזָקָה כַּמָּוֶת אַהֲבָה, בְּחֹזֶק חָזָק, כְּמוֹ אוֹתוֹ מָקוֹם שֶׁשּׁוֹרֶה בּוֹ הַמָּוֶת. אַהֲבָה - אוֹתוֹ מָקוֹם שֶׁנִּקְרָא אַהֲבַת עוֹלָם."],[5,"","קָשָׁה כִשְׁאוֹל קִנְאָה - אַף כָּךְ, שֶׁהֲרֵי אֵלּוּ הַשֵּׁמוֹת הֵם מֵאוֹתוֹ צַד. רְשָׁפֶיהָ רִשְׁפֵּי אֵשׁ, מַה הֵם רִשְׁפֵּי אֵשׁ הַלָּלוּ? אוֹתָם אֲבָנִים וּמַרְגָּלִיּוֹת טוֹבוֹת שֶׁנּוֹלְדוֹ מֵאוֹתָהּ אֵשׁ. שַׁלְהֶבֶת יָהּ, מֵאוֹתָהּ שַׁלְהֶבֶת שֶׁיּוֹצֵאת מִן הָעוֹלָם הָעֶלְיוֹן וְנֶאֶחְזָה בִּכְנֶסֶת יִשְׂרָאֵל, לִהְיוֹת הַכֹּל יִחוּד אֶחָד. וְאָנוּ, הֲרֵי אַהֲבָה וְרִשְׁפֵּי שַׁלְהֶבֶת שֶׁל הַלֵּב אַחֲרֶיךְ, יְהִי רָצוֹן שֶׁהַדְּיוֹקָן שֶׁלָּנוּ יִהְיֶה חָקוּק בְּלִבְּךְ כְּמוֹ שֶׁהַדְּיוֹקָן שֶׁלְּךְ חָקוּק בְּלִבֵּנוּ. נָשַׁק אוֹתָם וּבֵרַךְ אוֹתָם וְהָלְכוּ."],[6,"","כְּשֶׁהִגִּיעוּ אֶל רַבִּי שִׁמְעוֹן וְסִפְּרוּ לוֹ כָּל מַה שֶּׁקָּרָה לָהֶם, שָׂמַח וְתָמַהּ וְאָמַר, אַשְׁרֵיכֶם שֶׁזְּכִיתֶם לְכָל זֶה. וּמָה הֱיִיתֶם עִם הָאַרְיֵה הָעֶלְיוֹן גִּבּוֹר חָזָק, שֶׁכַּמָּה גִבּוֹרִים לֹא הָיוּ אֵלָיו כְּלוּם, וְלֹא יְדַעְתֶּם לְהִוָּדַע לוֹ מִיָּד, תָּמַהְתִּי אֵיךְ נִצַּלְתֶּם מֵעָנְשׁוֹ, אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה לְהַצִּילְכֶם. קָרָא עֲלֵיהֶם, וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם. בְּלֶכְתְּךְ לֹא יֵצַר צַעֲדֶךְ וְאִם תָּרוּץ לֹא תִכָּשֵׁל. (ישעיהס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר. (עד כאן מן רב ייבא סבא)."],[7,"","כִּי יִנָּצוּ אֲנָשִׁים - אֵלּוּ מִיכָאֵל וְס\"מ. וְנָגְפוּ אִשָּׁה הָרָה - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וְיָצְאוּ יְלָדֶיהָ - בַּגָּלוּת. עָנוֹשׁ יֵעָנֵשׁ - זֶה ס\"מ. כַּאֲשֶׁר יָשִׁית עָלָיו בַּעַל הָאִשָּׁה - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא."],[8,"","מִצְוָה (מא) אַחַר זוֹ - לְהָשִׁיב אֲבֵדָה, וְאַחֲרָיו - לְהָשִׁיב הַגָּזֵל. אָמַר מְנוֹרָה הַקְּדוֹשָׁה, הַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְהַחֲזִיר לְךְ אֶת הָאֲבֵדוֹת שֶׁאִבַּדְתָּ מִשּׁוּם הָעֵרֶב רַב, וְזוֹ הַכַּלָּה שֶׁלְּךְ, שֶׁבִּזְמַן שֶׁעָשׂוּ הָעֵרֶב רַב אֶת הָעֵגֶל, יָצְאָה הַכַּלָּה שֶׁלְּךְ. זֶהוּ שֶׁכָּתוּב (שמות לב) וַיַּשְׁלֵךְ מִיָּדָו אֶת הַלֻּחֹת."]]],[["וְאִתְּמַר בָּךְ לֵךְ רֵד, הָתָם קָא רָמִיז נְחִיתוּ דִּילָךְ, בְּגָלוּתָא רְבִיעָאָה, לֵךְ: כְּגוֹן (בראשית יב) לֶךְ לְךָ מֵאַרְצְךָ וְגוֹ'. הָכָא ש, (איוב ל״ג:כ״ט) הֵן כָּל אֵלֶּה יִפְעַל אֵל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר. הָכָא קָא רָמִיז לֶךְ, לְךָ ג' זִמְנִין (בגלגולא) בְּגָלוּתָא. רְבִיעָאָה רֵד, בְּגִין בַּת יְחִידָה, כַּלָּה דִּילָךְ, דְּנַפְלַה. הֲדָא הוּא דִכְתִיב, (עמוס ה׳:ב׳) נָפְלָה לא תוֹסִיף קוּם. וּמִיַּד דְּאַנְתְּ נָחִית בְּגִינֵיהּ, תָּקוּם עֲלָךְ וְהַאי (איהו השבת אבדה, והאי אורייתא דאתגליא על ידך האי) אִיהוּ הֲשָׁבַת אֲבֵדָה דִּילָךְ,","דְּלָאו לְמַגָּנָא אִתְגַּלְיָא לָךְ אוֹרַיְיתָא, יַתִּיר מִכָּל יִשְׂרָאֵל, וְאִסְתַּלָּקַת לְגַבָּךְ, כְּמַיָּא דִּבְאֵר דְּאִסְתַּלָּקוּ לְגַבָּךְ, וְלָא לַאֲבָהָן, וְלָא לְבַר נָשׁ, דְּהָא בְּאֵר מַכֶּרֶת אֲדוֹנֶיהָ. וְאוֹרַיְיתָא דָּא, אִתְּמַר עָלָהּ, (במדבר כ״א:ט״ז) וּמִשָּׁם בְּאֵרָה הִיא הַבְּאֵר וְגוֹ'. הַבְּאֵר הִיא מַלְיָא, וְלָא נָפְקִין מֵימוֹי לְבַר. וְאִיהוּ בְּאֵר מַיָּא דְּאוֹרַיְיתָא, דְּאַפִּיק כָּל מַיִין, וְכָל מַיִין דְּעָלְמָא עָאלִין בֵּיהּ, וְלָא נָפְקִין מֵימוֹי לְבַר.","וְאִיהוּ בְּאֵר דְּאֲפִילּוּ כָּל בְּנֵי עָלְמָא שָׁאֲבִין מִנֵּיהּ מַיָּא, וַאֲפִילּוּ כָּל עֲנָנֵי עָלְמָא, לָא חֲסֵרִין מִנֵּיהּ, אֲפִילּוּ כְּחוּט הַשַּׂעֲרָה. בְּגִין דִּבְאֵר דָּא, לֵית לֵיהּ סוֹף, יַתִּיר עָמוֹק הוּא מִדְּאוֹרַיְיתָא, דְּאִתְּמַר בָּהּ (איוב י״א:ט׳) וּרְחָבָה מִנִּי יָם. וּבְכַד דִּילֵיהּ, מַאן דְּשָׁאֲבֵי מִנֵּיהּ מַיָּא, אִיהוּ בָּלַע (ס\"א כל מימין וכל חכמתין) כָּל חָכְמָתִין דְּעָלְמָא, כָּל שֶׁכֵּן בְּאֵר עַצְמוֹ.","וְכֵן עָתִיד קוּדְשָׁא בְּרִיךְ הוּא לְאָהַדְרָא לָךְ גֶּזֶל דִּילָךְ, דְּאִיהוּ מַטֶּה, דְּאִתְּמַר בֵּיהּ (שמואל ב כ״ג:כ״א) וַיִּגְזוֹל אֶת הַחֲנִית מִיַּד הַמִּצְרִי, דְּעָלָךְ אִתְּמַר אִישׁ מִצְרִי. וּבְגָלוּתָא דִּילָךְ וּבְגִלְגּוּלָא דִּילָךְ, יַפְרִישׁ לָךְ עָרֵי מִקְלָט, לְשֵׁזָבָא, מִכַּמָּה דְּרַדְפִין אֲבַתְרָךְ, דְּלֵית לְהוֹן סוֹף.","וְהַאי אִיהוּ פִּקּוּדָא, (מב) (חדא) לְהַפְרִישׁ עָרֵי מִקְלָט, לְמַאן דְּקָטַל, בְּגִין הַהוּא מִצְרִי דְּקָטַלַת בְּמִצְרַיִם, דְּתַּמָּן הֲוָה נָחָשׁ הַקַּדְמוֹנִי וְכָל מַשִּׁרְיָיתֵיהּ, דַּהֲווֹ סָחֲרִין לֵיהּ, וְקָטְלַת לֵיהּ בְּלָא זִמְנֵיהּ, וְלָא דָּחַלְתָּ מֵרוֹדְפִין דִּילֵיהּ, דִּבְכַמָּה אַתְרִין רָדְפוּ אֲבָתְרָךְ, כַּמָּה נָשִׁין בְּנַעֲרוּתָךְ, דְּאִינּוּן נַעֲמָ\"ה אַגְרַ\"ת לִילִי\"ת אוּכָמָא. וְקוּדְשָׁא בְּרִיךְ הוּא יָהִיב לָךְ עָרֵי מִקְלָט, לְאִשְׁתְּזָבָא מִנְּהוֹן, וְאִינּוּן שַׁעֲרֵי תְּשׁוּבָה.","בְּגִין דְּאַתְּ בֵּן יָהּ, בְּרָא דְּאַבָּא וּדְאִמָא. בָּתַר דְּהַדְרַת בְּהֵ\"א בְּתִיוּבְתָּא, אִסְתְּלַּקְתּ בַּבִּינָה, יה\"ו, אִילָנָא דְּחַיֵּי, וּבְגִינָהּ אַתְּ זָכֵי לְאָת ה', בְּגִין דְּאַעִילַת גַּרְמָךְ אֲבַתְרָהָא, בְּתִיוּבְתָּא לְאָהַדְרָא לָהּ לְמָרָךְ, וּלְסַלְּקָא לָהּ מִגָּלוּתָא, וְלָא לְקַבְּלָא אַנְתְּ אַגְרָא.","וְקוּדְשָׁא בְּרִיךְ הוּא, שַׁוֵּי שְׁמֵיהּ בָּךְ, וּבְגִין דְּמַחֲשָׁבָה דִּילָךְ הֲוַת לְעִלַּת הָעִלּוֹת, שַׁוִּי בָּךְ מַחֲשַׁבְתֵּיהּ, דְּאִיהִי יוּ\"ד הֵ\"א וָא\"ו הֵ\"א. וְעִלַּת הָעִלּוֹת, אִיהוּ מְיַחֵד אִלֵּין אַתְוָון בָּךְ, לְאִשְׁתְּמוֹדְעָא לֵיהּ בְּאִלֵּין אַתְוָון.","וּבְגִין דְּאַתְּ הֲוֵית גּוֹמֵל חֶסֶד עִם שְׁכִינְתָּא, דְּכָל פִּקּוּדִין דִּילָךְ לְקַיְּימָא, אֵיזֶהוּ חָסִיד הַמִּתְחַסֵּד עִם קוֹנוֹ. יָהַב לָךְ מִדַּת חֶסֶד. וּבְגִין דְּנָטַרְתָּ פִּקּוּדִין דְּלָא תַּעֲשֶׂה, וַהֲוָה לָךְ לְאִתְגַּבְּרָא עַל יִצְרָךְ, לְמִקְשָׁר לֵיהּ תְּחוֹת יְדָךְ, וְלָא אִשְׁתַּדְּלַת בְּהַאי פִּקּוּדָא, אֶלָּא לְקַשְּׁרָא סָמָאֵ\"ל תְּחוֹת יְדָא דְּקוּדְשָׁא בְּרִיךְ הוּא. וּבַת זוּגֵיהּ דְּאִיהִי שִׁפְחָתָא בִּישָׁא, תְּחוֹת יַד גְּבִירְתָּא. לוֹן וּלְכָל מְמָנָן וּלְכָל מַשְׁרְיָין דִּלְהוֹן. קוּדְשָׁא בְּרִיךְ הוּא יָהַב לָךְ, מִדַּת גְּבוּרָה דִּילֵיהּ, לְמֶהוֵי בִּסְיַּעְתָּךְ דְּיִתְחַלְחַלוּן וִידַחֲלוּן מִינָךְ, סָמָאֵ\"ל וּבַת זוּגֵיהּ, וְכָל מְמָנָן וּמַשְׁרְיָין דִּלְהוֹן, וִיהוֹן קְשׁוּרִים בְּשַׁלְשְׁלָאֵי תְּחוֹת יְדָךְ.","וּבְגִין דְּהַדְרַת בְּתִיוּבְתָּא, בְּאוֹת בְּרִית, נָחִית בִּינָה יה\"ו, לְאִתְחַבְּרָא בְּצַדִיק. בְּגִינָךְ, קוּדְשָׁא בְּרִיךְ הוּא יָהִיב לָךְ אוֹת בְּרִית צַדִּיק דִּילֵיהּ. וּבְגִין דְּמַחֲשָׁבָה טוֹבָה עָבַדְתְּ כֹּלָּא, הָכִי נָחִית שְׁמָא מְפֹרָשׁ (דמרך) עָלָךְ, וּמִתַּמָּן, (נ\"א רשומא דנחית) נָחִית עָלָךְ.","וּבְגִין דְּאַנְתְּ תִּשְׁתָּדֵּל בְּכָל יוֹמָא, בִּתְרֵין שִׂפְוָון דִּילָךְ בִּצְלוֹתָא, לְשַׁבְּחָא לְמָרָךְ, בַּאֲדֹנָי שְׂפָתַי תִּפְתָּח, בִּתְרֵין שִׂפְוָון דִּילָךְ. בִּנְבִיאִים וּבַכְתוּבִים. וּבְכָל מִינֵי זֵמֶר וְנִגּוּן בִּצְלוֹתָא. קוּדְשָׁא בְּרִיךְ הוּא נָחִית לוֹן בְּשִׁפְוָון דִּילָךְ. כָּל שֶׁכֵּן דַּרְגָּא דִּילָךְ, עַמּוּדָא דְּאֶמְצָעִיתָא, וּבֵיהּ אִשְׁתַּדְּלַת בְּכָל יוֹמִין דִּילָךְ בִּקְשׁוֹט, קוּדְשָׁא בְּרִיךְ הוּא יָהֲבֵיהּ לָךְ, לְסַלְּקָא לָךְ בֵּיהּ, בְּתוֹרַת אֱמֶת, כְּלִילָא מִכָּל מִדּוֹת וְאַתְוָון. בִּשְׁמָא מְפֹרָשׁ, בְּד' אַתְוָון."],[[0,"ואתמר בך לך וכו':","ונאמר בך, \u0003לך רד.\u0004 שם רומז ירידה שלך בגלות הרביעית, \u0003לך\u0004 פירושו, כמו לך לך מארצך, דהיינו לגלות. כאן בשם משה, יש \u0003ש'\u0004 שבה ג' קוין, בסוד, הן כל אלה יפעל אל פעמים \u0003שלש\u0004 עם גבר. כאן בג' קוין של ה \u0003ש'\u0004 נרמז לך, \u0003לך\u0004 ג' פעמים בגלות. ובגלות הרביעי, \u0003רד,\u0004 בשביל בת יחידה שלך, דהיינו המלכות, שהיא כלה שלך, שנפלה. וז\"ש בגלות רביעית, נפלה לא תוסיף קום. ומיד שאתה תרד בשבילה, תקום עמך. כי לא תוסיף קום, מעצמה, אלא על ידי בעלה, שהוא משה. וזה הוא השבת אבדה שלך."],[1,"דלאו למגנא אתגליא וכו':","שלא לחנם נגלה לך התורה יותר מכל ישראל, ועלתה אליך כהמים של הבאר שעלו אליך ולא אל האבות, ולא לשום אדם, כי הבאר, שהיא המלכות, מכרת אדוניה. ותורה זו, נאמר עליה, ומשם בארה היא הבאר וגו'. הבאר היא מלאה, ומימיה אינם יוצאים לחוץ. והיא באר מים של התורה, שהתורה נקראת מים, שהוציאה כל המים, דהיינו כל התורה, וכל המים שבעולם נכנסים בה ומימיה אינם יוצאים לחוץ, אלא הם מכונסים בתוכה."],[2,"ואיהו באר דאפילו וכו':","והיא באר, שאפילו כל בני העולם ישאבו ממנה מים, ואפילו כל ענני העולם, לא יחסרו ממנה אפילו כחוט השערה. משום שבאר הזו אין לה סוף, והיא יותר עמוקה מן התורה, שכתוב בה, ורחבה מני ים. ומי ששואב מים בכד שלה, של הבאר, דהיינו כ\"ד ספרי הקדוש, הוא בולע כל החכמות שבעולם, כל שכן הבאר עצמו."],[3,"וכן עתיד קב\"ה וכו':","וכן עתיד הקב\"ה להשיב לך הגזילה שלך, שהוא המטה, שנאמר בו, ויגזול את החנית מיד המצרי, שעליך נאמר איש מצרי. (כמ\"ש לעיל בהקסה\"ז אות ק\"א וק\"ב בהסולם ע\"ש) ובגלות שלך ובגלגול שלך, שיש בכל דור התפשטות של משה, יפריש לך ערי מקלט להצילך מכמה שרודפים אחריך שאין להם סוף."],[4,"והאי איהו פקודא וכו':","וזהו המצוה להפריש ערי מקלט למי שהרג. משום שאותו המצרי שהרגת במצרים, שבו היה נחש הקדמוני, וכל המחנות שלו, שהיו סובבים אותו, והרגת אותו לפני זמנו, ולא יראת מרודפים שלו, שבכמה מקומות רדפו אחריך כמה נשים בנעוריך, שהן הקליפות, נעמה אגרת לילית אוכמא. והקב\"ה נתן לך ערי מקלט להנצל מהן, והם שערי תשובה."],[5,"בגין דאת בן י\"ה וכו':","משום שאתה בן \u0003י\"ה,\u0004 שמשה היה במדרגת \u0003ו'\u0004 שהוא ז\"א, שהוא בן של אבא ואמא, שהם חו\"ב, י\"ה, ואחר שחזרת בתשובה ב \u0003ה'\u0004 אחרונה של שם הוי\"ה, עלית לבינה, וזכית שם להשם \u0003יה\"ו\u0004 שהוא עץ החיים, כי הבינה נקראת אלקים חיים, וז\"א העולה לבינה נקרא עץ החיים. ובשבילה אתה זוכה לאות \u0003ה'\u0004 אחרונה, שהיא המלכות, משום שהכנסת עצמך אחריה בתשובה, להחזיר אותה לאדונך, ולהעלותה מן הגלות, ולא לקבל על זה שכר."],[6,"וקודשא בריך הוא וכו':","והקב\"ה שם שמו בך, ומשום שהמחשבה שלך היתה לעלת העלות, שהוא כתר, שם בך מחשבתו, שה\"ס חכמה, שהיא יוד הא ואו הא, דהיינו הויה בגי' מ\"ה, כי חכמה היא אותיות כ\"ח מ\"ה, שע\"י השם מ\"ה, שהוא קו האמצעי שבמוחין, נגלתה החכמה. ועילת העילות, מיחד אלו האותיות בך, כדי להכיר ולדעת אותו באלו האותיות."],[7,"ובגין דאת הוית וכו':","אחר שנכלל במחשבה, שה\"ס ג\"ר, ממשיך לבאר איך קבל שאר שש הספירות, ואומר, ומשום שאתה היית גומל חסד עם השכינה, שכל המצות שלך הם לקיים איזה חסיד המתחסד עם קונו, נתן לך מדת \u0003החסד\u0004 ומשום ששמרת מצות הלא תעשה, והיה לך להתגבר על יצרך, לקשר אותו תחת ידך, ולא השתדלת במצוה זו, אלא לקשר את סמאל תחת ידיו של הקב\"ה. ובת זוגו של סמאל, שהיא שפחה רעה, לקשר תחת יד הגבירה, שהוא מלכות, אותם וכל הממונים וכל המחנות שלהם. ע\"כ נתן לך הקב\"ה מדת \u0003גבורה\u0004 שלו, שתהיה בעזרתך שיתחלחלו ויפחדו ממך סמאל ובת זוגו וכל הממונים והמחנות שלהם, ויהיו קשורים בשרשרות תחת ידך."],[8,"ובגין דהדרת בתיובתא וכו':","ומשום שחזרת בתשובה באות ברית, שהוא יסוד, ירדה הבינה, שהיא אותיות יה\"ו, להתחבר עם צדיק, שהוא יסוד, בשבילך, וע\"כ נתן לך הקב\"ה אות ברית צדיק שלו, שהוא \u0003יסוד.\u0004 ומשום שבמחשבה טובה עשית הכל, כך ירד שם המפורש עליך, ומשם, ממחשבה, שהוא ג\"ר, ירד עליך."],[9,"ובגין דאנת תשתדל וכו':","ומשום שאתה משתדל בכל יום בשתי שפתים שלך בתפלה, לשבח את אדונך באדני שפתישפתי תפתח, בב' שפתים שלך בנביאים וכתובים ובכל מיני זמר וניגון בתפלה, הקב\"ה מוריד אותם בשתי שפתים שלך שהם \u0003נצח והוד.\u0004 כל שכן מדרגה שלך שהוא עמוד האמצעי, דהיינו \u0003תפארת,\u0004 שבו השתדלת בכל הימים שלך באמת, הקב\"ה נתנו לך להעלותך בו בתורת אמת, הכלולה מכל המדות ואותיות, שהם חג\"ת נה\"י, בשם המפורש בד' אותיות הוי\"ה. שהוא ג\"ר."]],[[0,"","וְנֶאֱמַר בְּךְ לֶךְ רֵד. שָׁם נִרְמְזָה יְרִידָה שֶׁלְּךְ לַגָּלוּת הָרְבִיעִית. לֶךְ - כְּמוֹ (בראשית יב) לֶךְ לְךְ מֵאַרְצְךְ וְגוֹ'. כָּאן שׁ, (איוב לב) הֶן כָּל אֵלֶּה יִפְעַל אֵל פַּעֲמַיִם שָׁלוֹשׁ עִם גָּבֶר. כָּאן רוֹמֵז לֶךְ לְךְ שָׁלֹשׁ פְּעָמִים (בגלגול) בַּגָּלוּת. בָּרְבִיעִית רֵד, בִּשְׁבִיל בַּת יְחִידָה, הַכַּלָּה שֶׁלְּךְ שֶׁנָּפְלָה. זֶהוּ שֶׁכָּתוּב (עמוס ה) נָפְלָה לֹא תוֹסִיף קוּם. וּמִיָּד שֶׁאַתָּה יוֹרֵד בִּשְׁבִילָהּ, תָּקוּם עָלִיּךְ, וזו (זו השבת אבדה, וזו התורה שהתגלתה על ידך, זו) הִיא הֲשָׁבַת הָאֲבֵדָה שֶׁלְּךְ."],[1,"","שֶׁלֹּא לְחִנָּם נִגְלְתָה לְךְ תּוֹרָה יוֹתֵר מִכָּל יִשְׂרָאֵל וְעָלְתָה אֵלֶיךְ כְּמוֹ מֵי הַבְּאֵר שֶׁעָלוּ אֵלֶיךְ, וְלֹא לָאָבוֹת וְלֹא לְאִישׁ, שֶׁהֲרֵי הַבְּאֵר מַכִּירָה אֶת אֲדוֹנֶיהָ. וְעַל הַתּוֹרָה הַזּוֹ נֶאֱמַר (במדבר כא) וּמִשָּׁם בְּאֵרָה הִיא הַבְּאֵר וְגוֹ'. הַבְּאֵר הִיא מְלֵאָה, וְלֹא יוֹצְאִים מֵימֶיהָ הַחוּצָה, וְהִיא בְּאֵר מֵי הַתּוֹרָה שֶׁמּוֹצִיאָה כָּל הַמַּיִם, וְכָל הַמַּיִם שֶׁל הָעוֹלָם נִכְנָסִים בָּהּ, וְלֹא יוֹצְאִים מֵימֶיהָ הַחוּצָה."],[2,"","וְהִיא הַבְּאֵר שֶׁאֲפִלּוּ כָּל בְּנֵי הָעוֹלָם שׁוֹאֲבִים מִמֶּנָּה מַיִם וַאֲפִלּוּ כָּל עַנְנֵי הָעוֹלָם, לֹא חֲסֵרִים מִמֶּנָּה אֲפִלּוּ כְּחוּט הַשַּׂעֲרָה. מִשּׁוּם שֶׁבְּאֵר זוֹ אֵין לָהּ סוֹף. יוֹתֵר עֲמֻקָּה הִיא מִן הַתּוֹרָה שֶׁנֶּאֱמַר בָּהּ (איוב יא) וּרְחָבָה מִנִּי יָם. וּבַכַּד שֶׁל מִי שֶׁשּׁוֹאֵב מִמֶּנָּה מַיִם, הוּא בּוֹלֵעַ (כל מימות וכל חכמות) אֶת כָּל חָכְמוֹת הָעוֹלָם. כָּל שֶׁכֵּן הַבְּאֵר עַצְמָהּ."],[3,"","וְכֵן עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲזִיר לְךְ אֶת הַגָּזֵל שֶׁלְּךְ, שֶׁהוּא הַמַּטֶּה, שֶׁנֶּאֱמַר בּוֹ (שמואל ב כג) וַיִּגְזל אֶת הַחֲנִית מִיַּד הַמִּצְרִי, שֶׁעָלֶיךְ נֶאֱמַר אִישׁ מִצְרִי. וּבַגָּלוּת שֶׁלְּךְ וּבַגִּלְגּוּל שֶׁלְּךְ יַפְרִישׁ לְךְ עָרֵי מִקְלָט לְהִנָּצֵל מִכַּמָּה שֶׁרוֹדְפִים אַחֲרֶיךְ שֶׁאֵין לָהֶם סוֹף."],[4,"","וְזוֹהִי מִצְוָה (מב) (אחת) לְהַפְרִישׁ עָרֵי מִקְלָט לְמִי שֶׁהָרַג, מִשּׁוּם אוֹתוֹ הַמִּצְרִי שֶׁהָרַגְתָּ בְּמִצְרַיִם, שֶׁשָּׁם הָיָה נָחָשׁ הַקַּדְמוֹנִי וְכָל מַחֲנוֹת שֶׁהָיוּ מַקִּיפִים אוֹתוֹ, וְהָרַגְתָּ אוֹתוֹ בְּלִי זְמַנּוֹ, וְלֹא פָחַדְתָּ מֵהָרוֹדְפִים שֶׁלּוֹ, שֶׁבְּכַמָּה מְקוֹמוֹת רָדְפוּ אַחֲרֶיךְ כַּמָּה נָשִׁים בְּנַעֲרוּתְךְ, שֶׁהֵן נַעֲמָ\"ה אַגְרַ\"ת לִילִי\"ת שְׁחֹרָה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לְךְ עָרֵי מִקְלָט לְהִנָּצֵל מֵהֶן, וְהֵם שַׁעֲרֵי תְשׁוּבָה."],[5,"","מִשּׁוּם שֶׁאַתָּה בֶּן יָהּ, בֵּן שֶׁל אַבָּא וְאִמָּא. אַחַר שֶׁחָזַרְתָּ בְּהֵ\"א בִּתְשׁוּבָה, עָלִיתָ לְבִינָה, יה\"ו, עֵץ הַחַיִּים, וּבִגְלָלָהּ זָכִיתָ לָאוֹת ה', מִשּׁוּם שֶׁהִכְנַסְתָּ אֶת עַצְמְךְ אַחֲרֶיהָ בִּתְשׁוּבָה לְהַחֲזִירָהּ לְרִבּוֹנְךְ וּלְהַעֲלוֹתָהּ מֵהַגָּלוּת, וְלֹא שֶׁתְּקַבֵּל אַתָּה שָׂכָר."],[6,"","וְהַקָּדוֹשׁ בָּרוּךָ הוּא שָׂם שְׁמוֹ בְּךְ, וּמִשּׁוּם שֶׁמַּחֲשַׁבְתְּךְ הָיְתָה לְעִלַּת הָעִלּוֹת, שָׂם בְּךְ מַחֲשַׁבְתּוֹ, שֶׁהִיא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. וְעִלַּת הָעִלּוֹת הוּא מְיַחֵד אֶת הָאוֹתִיּוֹת הַלָּלוּ בְּךְ כְּדֵי לְהַכִּיר אוֹתוֹ בָּאוֹתִיּוֹת הַלָּלוּ."],[7,"","וּמִשּׁוּם שֶׁאַתָּה הָיִיתָ גּוֹמֵל חֶסֶד עִם הַשְּׁכִינָה, שֶׁכָּל הַמִּצְווֹת שֶׁלְּךְ לְקַיֵּם, אֵיזֶהוּ חָסִיד? הַמִּתְחַסֵּד עִם קוֹנוֹ - נָתַן לְךְ מִדַּת חֶסֶד. וּמִשּׁוּם שֶׁשָּׁמַרְתָּ מִצְווֹת לֹא תַעֲשֶׂה, וְהָיָה לְךְ לְהִתְגַּבֵּר עַל יִצְרְךְ, לִקְשֹׁר אוֹתוֹ תַּחַת יָדְךְ, וְלֹא הִשְׁתַּדַּלְתָּ בַּמִּצְוָה הַזּוֹ, אֶלָּא לִקְשֹׁר אֶת סמא\"ל תַּחַת יָדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבַת זוּגוֹ, שֶׁהִיא שִׁפְחָה רָעָה, תַּחַת יַד גְּבִרְתָּהּ, אוֹתָם וְאֶת כָּל הַמְמֻנִּים וְהַמַּחֲנוֹת שֶׁלָּהֶם - הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לְךְ אֶת מִדַּת גְּבוּרָתוֹ לִהְיוֹת בְּעֶזְרְךְ שֶׁיִּתְחַלְחֲלוּ וְיִפְחֲדוּ מִמְּךְ סמא\"ל וּבַת זוּגוֹ, וְכָל הַמְמֻנִּים וְהַמַּחֲנוֹת שֶׁלָּהֶם, וְיִהְיוּ קְשׁוּרִים בְּשַׁלְשְׁלָאוֹת תַּחַת יָדְךְ."],[8,"","וּמִשּׁוּם שֶׁחָזַרְתָּ בִּתְשׁוּבָה בְּאוֹת הַבְּרִית, יָרְדָה בִּינָה יה\"ו לְהִתְחַבֵּר בְּצַדִּיק. בִּשְׁבִילְךְ הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן לְךְ אוֹת בְּרִית צַדִּיק שֶׁלּוֹ. וּמִשּׁוּם שֶׁבְּמַחֲשָׁבָה טוֹבָה עָשִׂיתָ אֶת הַכֹּל, כָּךְ יָרַד שֵׁם הַמְפֹרָשׁ (של רבונך) עָלֶיךְ, וּמִשָּׁם (הרשם שירד) יָרַד עָלֶיךְ."],[9,"","וּמִשּׁוּם שֶׁאַתָּה תִּשְׁתַּדֵּל בְּכָל יוֹם בִּשְׁתֵּי הַשְּׂפָתַיִם שֶׁלְּךְ בִּתְפִלָּה, לְשַׁבֵּחַ אֶת רִבּוֹנְךְ בַּאדנָי שְׂפָתַי תִּפְתָּח בִּשְׁתֵּי הַשְּׂפָתַיִם שֶׁלְּךְ, בִּנְבִיאִים וּבַכְּתוּבִים, וּבְכָל מִינֵי זֶמֶר וְנִגּוּן בַּתְּפִלָּה - הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹרִיד אוֹתָם בַּשְּׂפָתַיִם שֶׁלְּךְ. כָּל שֶׁכֵּן הַדַּרְגָּה שֶׁלְּךְ, עַמּוּד הָאֶמְצָעִי, וּבוֹ הִשְׁתַּדַּלְתָּ בְּכָל יָמֶיךְ בֶּאֱמֶת - הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן אוֹתוֹ לְךְ לְהַעֲלוֹת אוֹתְךְ בּוֹ, בְּתוֹרַת אֱמֶת, כְּלוּלָה מִכָּל הַמִּדּוֹת וְהָאוֹתִיּוֹת, בַּשֵּׁם הַמְפֹרָשׁ בְּאַרְבַּע הָאוֹתִיּוֹת."]]],[["דְּקֹדֶם דְּחָזַרְתְּ בְּתִיוּבְתָּא לָא הֲוֵית, אֶלָּא בְּאִילָנָא דְּטוֹב וָרָע, עֶבֶד וְנַעַר הֲוָה שְׁמָךְ בְּקַדְמִיתָא, (שמות ב׳:ו׳) וְהִנֵּה נַעַר בּוֹכֶה, עֶבֶד נֶאֱמָן, הֲדָא הוּא דִכְתִיב, (במדבר י״ב:ז׳) לֹא כֵן עַבְדִּי מֹשֶׁה בְּכָל בֵּיתִי נֶאֱמָן הוּא. וְהַהוּא רַע, שׁוּתָּפָא דְּעֶבֶד, גָּרַם לָךְ לְמֶחטֵי בַּסֶּלַע, בְּגִין דְּמַטֶּה דְּאִתְּמְסַר לָךְ, (נ\"א בידך) הֲוָה דְּאִילָנָא דְּטוֹב וָרָע, (תיקונין צ' ע\"ב) מְטַטְרוֹ\"ן טוֹב. סָמָאֵ\"ל רָע.","וּכְעָן, דְּחָזַרְתְּ בְּתִיוּבְתָּא, וְאִתְדַּבְּקַת בְּאִילָנָא דְּחַיֵּי, הָא נַפְקַת מֵעֶבֶד, וְאִתְהָדַרְתְּ בֶּן לְקוּדְשָׁא בְּרִיךְ הוּא. וּמַטֶּה דְּאִתְמְסָר בִּידָךְ, יְהֵא עֵץ חַיִּים, ו', דְּאִיהוּ בֶּן יָ\"הּ, וְתֵיעוּל (ד\"א ותיעול) בְּמ\"ט אַנְפִּין דִּילָךְ בְּאוֹרַיְיתָא, וְיִתְעֲבֵד מוֹט. וְיִתְקְיָים בָּךְ, (תהילים נ״ה:כ״ג) לא יִתֵּן לְעוֹלָם מוֹט לַצַּדִּיק. מ\"ט אַנְפִּין, מ\"ט אַתְוָון דִּשְׁמַע יִשְׂרָאֵל, וּבָרוּךְ שֵׁם, שִׁית תֵּיבִין דְּיִחוּדָא עִלָּאָה, ו' עִלָּאָה תִּפְאֶרֶת. שִׁית תֵּיבִין תִּנְיָינִין, דְּבָרוּךְ שֵׁם, ו' תִּנְיָינָא צַדִּיק. מ\"ט. בְּאֶמְצָעִיתָא א. וַיִּשָּׂאוּהוּ בַמּוֹט בִּשְׁנָיִם.","בְּלֹא וָא\"ו בְּאֶמְצָעִיתָא, אִיהוּ מ\"ט. (נ\"א בלא א' דאמצעיתא דו\"ו) וְצַדִיק מ\"ט לִפְנִי רָשָׁע. וּמַאן גָּרַע דָּא. א'. אֶחָד מֵחֲמִשִּׁים. דְּחַמְשִׁין תַּרְעִין אִתְיְהִיבוּ לָךְ, חָסֵר חַד, כְּמָה דְּאוּקְמוּהָ מָארֵי מַתְנִיתִין, חַמְשִׁים שַׁעֲרֵי בִּינָה נִמְסְרוּ לְמֹשֶׁה, חוּץ מְאֶחָד. וְהַאי אִיהוּ א', דְּחָסֵר מֵחַמְשִׁין, וְאִשְׁתְּאַר מ\"ט, וְדָא גָּרִים לָךְ צַדִּיק מ\"ט לִפְנֵי רָשָׁע. מַאי רָשָׁע. דָּא סָמָאֵ\"ל.","וְהַאי אִיהוּ מ\"ט, מִן מַטֶּה דִּילָךְ, דְּאִתְּמַר בֵּיהּ (שמות י״ז:ט׳) וּמַטֵּה הָאֱלהִים בְּיָדִי. (דמטה אחרא אית לך) מַטֵּה דִּילָךְ הוּא מַטֶּה דְּמֹשֶׁה, וּבְגִין דָּא א, דְּאִיהִי בִּינָה, חוֹזְרַת לָךְ, כְּמָה דְּאוּקְמוּהָ בְּמַתְנִיתִין, אָלֶף בִּינָה. דְּחָזְרַת לָךְ בְּתִיוּבְתָּא, וְתֵיעוּל בֵּין וָ\"ו, וְאִתְעָבִיד וָא\"ו, לְקַיֵּים בָּךְ לְיִשְׂרָאֵל, (ישעיהו נ״ד:ז׳) וּבְרַחֲמִים גְּדוֹלִים אֲקַבְּצֵךְ. (ירמיה ל\"א) (ובתחנונים אובילם) מִתַּמָּן וְאֵילָךְ יִתְקַיֵּים בָּךְ, לא יִתֵּן לְעוֹלָם מוֹט לַצַּדִּיק.","בְּהַהוּא זִמְנָא, יִתְקַיְּימוּ בָּךְ תְּרֵין פִּקּוּדִין. חַד, (דברים כ״ב:ד׳) הָקֵם תָּקִים עִמּוֹ. תִּנְיָינָא, (שמות כ״ג:ה׳) עָזוֹב תַּעֲזוֹב עִמּוֹ. הָקֵם עִם ו' עִלָּאָה, מָשִׁיחַ רִאשׁוֹן. תָּקִים עִם ו' תִּנְיָינָא. עִמּוֹ, דָּא בֶּן עַמְרָם, דִּסְלִיקַת לַבִּינָה דְּאִיהִי א'.","וּלְמַאן הָקֵם תָּקִים. לְאָת ה'. דְּנַפְלַת בְּאָלֶף חֲמִשָׁאָה, בָּתַר ע\"ב, כְּמִנְיָן עָזוֹ\"ב תַּעֲזוֹב עִמּוֹ. עָזוֹב: ע\"ב ז\"ו. וְדָא ע\"ב שְׁמָהָן, וַיִּסַּע וַיָּבֹא וַיֵּט. דָּא וָא\"ו מִן וה\"ו, תַּמָּן עֵזֶר, וְלָא קִימָה, וְהַאי אִיהוּ עָזוֹב תַּעֲזוֹב, תַּמָּן (דברים י״א:י״ד) בְּעִתּ\"וֹ יוֹרֶה וּמַלְקוֹשׁ וְאָסַפְתָּ דְּגָנֶךָ וְתִירֹשְׁךָ וְיִצְהָרֶךָ, דְּאִינּוּן יִשְׂרָאֵל. לֶקֶט שִׁכְחָה וּפֵאָה, (ויקרא י״ט:י׳) לֶעָנִי וְלַגֵּר תַּעֲזוֹב אוֹתָם. הָכָא אוֹלִיפְנָא. פִּקּוּדָא תְּלִיתָאָה.","וְצָרִיךָ לְאַחֲזָרָא עָלַיְיהוּ, דְּהָא מִסִּטְרָא דְּצַדִּיק, עָנִי, עָזוֹב תַּעֲזוֹב, צַדִּיק. עִמּוֹ, דָּא בֶּן עַמְרָם. וְהַאי אִיהוּ לֶעָנִי וְלַגֵּר תַּעֲזוֹב אוֹתָם. גֵּר אַנְתְּ כְּגַוְונָא דְּאִתְּמַר בָּךְ בְּקַדְמִיתָא עַם עָנִי, (שמות י״ח:ג׳) גֵּר הָיִיתִי בְּאֶרֶץ נָכְרִיָּה.","אֲבָל הֲקָמָה, בְּדַרְגָּא דִּילָךְ, הָקֵם ו' תַּתָּאָה. תָּקִים עִמּוֹ: עִם בֶּן עַמְרָם, בְּדַרְגָּא עִלָּאָה דִּילָךְ, תִּפְאֶרֶת. בְּמ\"ה דִּילָךְ, שְׁמָא מְפֹרָשׁ בִּשְׁלִימוּ. בָּתַר ק' ק' דְּהָקֵם תָּקִים, (ובגין דא הקם תקים) אִשְׁתְּאַר תים. מַאי קָא אַחְזֵי. (בראשית כ״ה:כ״ז) יַעֲקֹב אִישׁ תָּם. עִמּוֹ: עִם בֶּן עַמְרָם, יוֹקִים. הָקֵם: צַדִּיק. תָּקִים: תָּם.","פִּקּוּדָא בָּתַר דָּא לִפְדּוֹת עֶבֶד עִבְרִי וְאָמָה הָעִבְרִיָּה, לְיַעֵד אָמָה הָעִבְרִיָּה, לָדוּן בְּקִנְיַן עֶבֶד עִבְרִי, הַעֲנֵק תַּעֲנִיק לוֹ. הֲדָא הוּא דִכְתִיב, כִּי תִקְנֶה עֶבֶד עִבְרִי שֵׁשׁ שָׁנִים יַעֲבֹד. מַאי שֵׁשׁ שָׁנִים יַעֲבֹד. וּמַאי קִנְיָן דִּילֵיהּ. אֶלָּא בְּסִתְרֵי תּוֹרָה, מְטַטְרוֹ\"ן עֶבֶד יְיָ', כָּלִיל שִׁית (צ\"ה ע\"א) סִטְרִין, כְּחוּשְׁבָּן שִׁית אַתְוָון דִּילֵיהּ, שִׁית סִדְרֵי מִשְׁנָה. וּבְהוֹן אִית לֵיהּ לְבַר נָשׁ לְמִפְלַח לְמָארֵיהּ, לְמֶהֱוֵי לֵיהּ עֶבֶד, (ס\"א ממכר) לְמֶעְבָּד קִנְיַן כַּסְפּוֹ, דְּכֶסֶף יְמִינָא, דְּאַבְרָהָם חֶסֶד דַּרְגָּא דִּילֵיהּ, אוֹרַיְיתָא מִתַּמָּן אִתְיְהִיבַת.","וּמַאן דְּאִשְׁתָּדַּל בָּהּ, בְּגִין לְזַכָּאָה (בה) לְעָלְמָא דְּאָתֵי, אִקְרֵי קִנְיַן. כַּסְפּוֹ: עָלְמָא דְּכִסּוּפָא. קִנְיָן: עַל שֵׁם (בראשית י״ד:כ״ב) אֵל עֶלְיוֹן קוֹנֵה שָׁמַיִם וָאָרְץ. (משלי ד׳:ה׳) קְנֵה חָכְמָה קְנֵה בִינָה. קָנָה לוֹ ד\"ת.","רַבּוֹ בָּתַר דְּקָנָה לוֹ, גְּאוּלָה תִּהְיֶה לוֹ. אִית דְּאִיהוּ קָנוּי (ליה) לְעוֹלָם, וְאִית דְּאִיהוּ קָנוּי לֵיהּ שִׁית שְׁנִין. מַאן דְּאִיהוּ קָנוּי לֵיהּ לְעוֹלָם, כְּתִיב בֵּיהּ, וְרָצַע אֲדוֹנָיו אֶת אָזְנוֹ בַּמַּרְצֵעַ וַעֲבָדוֹ לְעוֹלָם. לֵית עוֹלָם, אֶלָּא עוֹלָמוֹ שֶׁל יוֹבֵל, דְּאִינּוּן חַמְשִׁין. וְדָא קְרִיאַת שְׁמַע, דְּתַמָּן כ\"ה כ\"ה אַתְוָון, עַרְבִית וְשַׁחֲרִית. נ' תַּרְעִין דְּבִינָה."],[[0,"דקדם דחזרת בתיובתא וכו':","כי מטרם שחזרת בתשובה, לא היית אלא באילן דטוב ורע, עבד ונער היה שמך מתחילה, והנה נער בוכה. עבד נאמן, ז\"ש, לא כן עבדי משה בכל ביתי נאמן הוא. ואותו הרע, שהוא שותפו של עבד, גרם לך לחטוא בסלע, משום שהמטה שנמסר לך היה מאילן של טוב ורע, דהיינו ממטטרון וסמאל, מטטרון טוב וסמאל רע."],[1,"וכען דחזרת בתיובתא וכו':","ועתה שחזרת בתשובה, ונתדבקת בעץ החיים, הרי יצאת ממדרגת עבד וחזרת להיות בן להקב\"ה, והמטה שנמסר בידך יהיה עץ החיים, שהוא \u0003ו',\u0004 בן \u0003י\"ה,\u0004 ותכנס ה \u0003ו'\u0004 במ\"ט פנים שלך בתורה, ותהיה \u0003מו\"ט\u0004 ויתקיים בך, לא יתן לעולם \u0003מוט\u0004 לצדיק, מ\"ט פנים, ה\"ס מ\"ט אותיות שבשמע ישראל, וברוך שם כבוד מלכותו לעולם ועד, שהם שש תבות של יחוד העליון, דהיינו \u0003ו'\u0004 עליונה הוא תפארת, ושש תבות של ברוך שם, שניות, של יחוד התחתון, הם \u0003ו'\u0004 שניה של מילוי ואו, שהוא צדיק, דהיינו יסוד. והם מוט. באמצעם של ב' ווין הוא \u0003א'.\u0004 וז\"ס וישאוהו במוט בשנים. דהיינו בשני ווין."],[2,"בלא ואו באמצעיתא וכו':","בלא ואו באמצע, הוא \u0003מט,\u0004 והיינו, צדיק \u0003מט\u0004 לפני רשע. ומי גרע זה, הוא \u0003א',\u0004 דהיינו אחד מחמשים. כי חמשים שערים ניתנו לך חסר אחד. כמו שהעמידוהו בעלי המשנה, חמשים שערי בינה נמסרו למשה חוץ מאחד. וזהו \u0003א'\u0004 החסר מחמשים, ונשאר \u0003מט,\u0004 וזה גרם לך, צדיק \u0003מט\u0004 לפני רשע. מי הוא רשע, זה סמאל."],[3,"והאי איהו מט וכו':","וזה הוא מ\"ט מן מטה שלך, שנאמר בו, ומטה אלקים בידי, המטה שלך הוא מטה משה ומשום זה \u0003א'\u0004 שהיא בינה חוזרת לך, כמו שהעמידוהו במשנה, אלף בינה. היא חוזרת לך, בתשובה, ותכנס בין \u0003ו\"ו\u0004 ותעשה \u0003וא\"ו,\u0004 לקיים בך לישראל, וברחמים גדולים אקבצך. משם והלאה, יתקיים בך, לא יתן לעולם מוט לצדיק."],[4,"בההוא זמנא יתקיימו וכו':","בזמן ההוא, יתקיימו בך שתי מצות, א', הקים תקים עמו, ב', עזוב תעזוב עמו. \u0003הקם\u0004 עם \u0003ו'\u0004 עליונה, שהוא משיח ראשון, משיח בן דוד. \u0003תקים\u0004 עם \u0003ו'\u0004 שניה, שהוא משיח שני, משיח בן יוסף. \u0003עמו,\u0004 זה בן עמרם, שעלית לבינה, שהוא \u0003א'\u0004 שבאמצע ב' ווין הנ\"ל, והם \u0003ו'\u0004 במילוי כזה. \u0003ואו.\u0004"],[5,"ולמאן הקם תקים וכו':","ולמי הקם תקים, לאות \u0003ה',\u0004 שהיא המלכות, שנפלה באלף החמשי אחר ע\"ב שנים, כמנין עזוב תעזוב עמו. \u0003עזוב,\u0004 אותיות \u0003ע\"ב ז\"ו, ע\"ב\u0004 היינו ע\"ב שמות ויסע ויבא ויט. (כנ\"ל בשלח אות קע\"ג ע\"ש) \u0003זו\u0004 היא ראשי תיבות, \u0003זה ואו.\u0004 וזה \u0003ו'\u0004 מן יה\"ו (כצ\"ל) שהוא ז\"א. שם, בחמשת אלפים וע\"ב שנה, עזר, לעזור ל \u0003ה'\u0004 הנופלת, ולא קימה, שאינו עוד זמן הקימה והגאולה, וזהו עזוב תעזוב, דהיינו עזרה בלבד, שם נוהג, בעתו יורה ומלקוש ואספת דגנך ותירשך ויצהרך, שהם ישראל. כלומר, שעל ידי התיקונים של יורה ומלקוש בעתו, נאספים ישראל מן הגלות, \u0003דגן,\u0004 אלו ישראל. \u0003תירש\u0004 אלו הלוים. \u0003ויצהר,\u0004 אלו הכהנים. וכן נוהגים התקונים של לקט שכחה ופאה, לעני ולגר תעזוב אותם. וכאן למדנו מצוה שלישית, דהיינו לקט שכחה פאה."],[6,"וצריך לאחזרא עלייהו וכו':","וצריכים לחזור אחריהם, לקיימם, כי מצד הצדיק, דהיינו יסוד, הוא העני. \u0003עזוב תעזוב,\u0004 היינו יסוד צדיק, \u0003עמו,\u0004 זה בן עמרם. וזה הוא לעני ולגר תעזוב אותם, אתה גר, עם עני, כמו שנאמר בך בתחילה, גר הייתי בארץ נכריה."],[7,"אבל הקמה בדרגא וכו':","אבל הקמה, שהיא הגאולה, הוא במדרגה שלך. \u0003הקם,\u0004 הוא \u0003ו'\u0004 תחתונה, שהיא המילוי של \u0003ו',\u0004 והיא יסוד. \u0003תקים עמו,\u0004 עם בן עמרם, במדרגה עליונה שלך, שהוא תפארת, בשם מ\"ה שלך, שהוא הויה במילוי אלפין שהוא בגימטריא \u0003מ\"ה,\u0004 שהוא שם המפורש בשלמות. אחר ק' ק' של הקם תקים נשארו \u0003תי\"מ.\u0004 שואל, מה זה יורה. ואומר, שזה יורה על יעקב איש \u0003תם.\u0004 שהוא ת\"ת. ופירוש הכתוב הוא, \u0003עמו,\u0004 היינו עם בן עמרם יקום. \u0003הקם,\u0004 זהו צדיק, דהיינו יסוד. \u0003תקום,\u0004 זהו תם. דהיינו תפארת."],[8,"פקודא בתר דא וכו':","המצוה שלאחר זו, הוא לפדות עבד עברי ואמה העבריה, ליעד אמה העבריה, לדון בקנין עבד עברי, הענק תעניק לו. ז\"ש, כי תקנה עבד עברי שש שנים יעבוד. שואל, מהו, שש שנים יעבוד, ומהו קנין שלו. ומשיב, אלא בסתרי תורה, המלאך מטטרון הוא עבד ה', כולל שש קצוות, חג\"ת נה\"י, כמספר שש אותיות שלו, שה\"ס ששה סדרי משנה. ובהם יש לו לאדם לעבוד את אדונו להיות לו עבד, להעשות קנין כספו. כסף, הוא ימין ואברהם, שחסד הוא מדרגה שלו. והתורה ניתנה משם."],[9,"ומאן דאשתדל בה וכו':","ומי שעוסק בתורה כדי לזכות לעולם הבא היא נקראת קנין. \u0003כספו,\u0004 נקראת על שם עולם התענוג \u0003קנין,\u0004 על שם אל עליון קונה שמים וארץ. קנה חכמה קנה בינה."],[10,"בתר דקנה לו וכו':","אחר שקנה אותה, גאולה תהיה לו. יש שקנוי לעולם, ויש שקנוי לו שש שנים מי שקנוי לעולם, כתוב בו, ורצע אדוניו את אזנו במרצע ועבדו לעולם, אין עולם אלא עולמו של יובל, שהוא בינה הנקראת יובל, שהוא חמשים, וזהו קריאת שמע, שיש בה כ\"ה כ\"ה אותיות, בערבית ושחרית, שהם נ' שערי בינה."]],[[0,"","שֶׁקֹּדֶם שֶׁחָזַרְתָּ בִּתְשׁוּבָה לֹא הָיִיתָ אֶלָּא בָּעֵץ שֶׁל טוֹב וְרַע. עֶבֶד וְנַעַר הָיָה שִׁמְךְ בַּתְּחִלָּה, וְהִנֵּה נַעַר בֹּכֶה, עֶבֶד נֶאֱמָן. זֶהוּ שֶׁכָּתוּב (במדבר יב) לֹא כֵן עַבְדִּי מֹשֶׁה בְּכָל בֵּיתִי נֶאֱמָן הוּא. וְאוֹתוֹ הָרָע, הַשֻּׁתָּף שֶׁל הָעֶבֶד, גָּרַם לְךְ לַחֲטֹא בַּסֶּלַע, מִשּׁוּם שֶׁהַמַּטֶּה שֶׁנִּמְסַר לְךְ (בידך) הָיָה שֶׁל הָעֵץ טוֹב וָרָע. מטטרו\"ן טוֹב, סמא\"ל רַע."],[1,"","וּכְשֵׁם שֶׁחָזַרְתָּ בִּתְשׁוּבָה וְנִדְבַּקְתָּ בְּעֵץ הַחַיִּים, הֲרֵי יָצָאתָ מֵעֶבֶד, וְהָפַכְתָּ לִהְיוֹת בֵּן לַקָּדוֹשׁ-בָּרוּךְ- הוּא. וְהַמַּטֶּה שֶׁנִּמְסַר בְּיָדְךְ יִהְיֶה עֵץ הַחַיִּים, ו', שֶׁהוּא בֶּן יָ\"הּ, וְתִכָּנֵס בְּאַרְבָּעִים וְתֵשַׁע הַפָּנִים שֶׁלְּךְ בַּתּוֹרָה, וְיֵעָשֶׂה מוֹט, וְיִתְקַיֵּם בְּךְ (תהלים נה) לֹא יִתֵּן לְעוֹלָם מוֹט לַצַּדִּיק. אַרְבָּעִים וְתֵשַׁע פָּנִים, אַרְבָּעִים וְתֵשַׁע אוֹתִיּוֹת שֶׁל שְׁמַע יִשְׂרָאֵל וּבָרוּךְ שֵׁם, שֵׁשׁ תֵּבוֹת הַתֵּבוֹת שֶׁל הַיִּחוּד הָעֶלְיוֹן, ו' עֶלְיוֹנָה תִּפְאֶרֶת. שֵׁשׁ תֵּבוֹת שְׁנִיּוֹת שֶׁל בָּרוּךְ שֵׁם, ו' שֵׁנִי צַדִּיק. מ\"ט. בָּאֶמְצַע ו. וַיִּשָּׂאוּהוּ בַמּוֹט בִּשְׁנָיִם."],[2,"","בְּלֹא וָא\"ו בָּאֶמְצַע, הוּא מ\"ט. (בלא א' האמצעית של ו\"ו) וְצַדִּיק מָ\"ט לִפְנֵי רָשָׁע, וּמִי גָרַע אֶת זֶה? א'. אֶחָד מֵחֲמִשִּׁים, שֶׁחֲמִשִּׁים שְׁעָרִים נִתְּנוּ לְךְ חָסֵר אֶחָד, כְּמוֹ שֶׁבֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, חֲמִשִּׁים שַׁעֲרֵי בִינָה נִמְסְרוּ לְמֹשֶׁה חוּץ מֵאֶחָד. וְזֶהוּ א' שֶׁחָסֵר מֵחֲמִשִּׁים, וְנִשְׁאֲרוּ מ\"ט, וְזֶה גָּרַם לְךְ צַדִּיק מָ\"ט לִפְנֵי רָשָׁע. מִי הָרָשָׁע? זֶה סמא\"ל."],[3,"","וְזְהִוּ מ\"ט, מֵהַמַּטֶּה שֶׁלְּךְ, שֶׁנֶּאֱמַר בּוֹ (שמות יז) וּמַטֵּה הָאֱלֹהִים בְּיָדִי. הַמַּטֶּה שֶׁלְּךְ הוּא הַמַּטֶּה שֶׁל מֹשֶׁה, וּמִשּׁוּם זֶה א, שֶׁהִיא בִּינָה, חוֹזֶרֶת לְךְ, כְּמוֹ שֶׁבֵּאֲרוּהָ בַּמִּשְׁנָה, אָלֶף בִּינָה. שֶׁהִיא חוֹזֶרֶת לְךְ בִּתְשׁוּבָה וְתִכָּנֵס בֵּין וָ\"ו, וְתֵעָשֶׂה וָא\"ו, לְקַיֵּם בְּךְ לְיִשְׂרָאֵל, (ישעיה נד) וּבְרַחֲמִים גְּדלִים אֲקַבְּצֵךְ (ירמיה לא) (ובתחנונים אובילם). מִשָּׁם וְאֵילָךְ יִתְקַיֵּם בְּךְ, לֹא יִתֵּן לְעוֹלָם מוֹט לַצַּדִּיק."],[4,"","בְּאוֹתוֹ זְמַן יִתְקַיְּמוּ בְךְ שְׁתֵּי מִצְווֹת: אַחַת - (דברים כב) הָקֵם תָּקִים עִמּוֹ. שְׁנִיָּה - עָזֹב תַּעֲזֹב עִמּוֹ. הָקֵם עִם ו' עֶלְיוֹנָה, מָשִׁיחַ רִאשׁוֹן. תָּקִים עִם ו' שְׁנִיָּה. עִמּוֹ - זֶה בֶּן עַמְרָם, שֶׁעָלִיתָ לַבִּינָה שֶׁהִיא א'."],[5,"","וְאֶת מִי הָקֵם תָּקִים? אֶת אוֹת ה', שֶׁנָּפְלָה בָּאֶלֶף הַחֲמִישִׁי אַחַר ע\"ב, כְּמִנְיַן עָזוֹ\"ב תַּעֲזוֹב עִמּוֹ. עָזוֹב - ע\"ב ז\"ו. וְזֶה שִׁבְעִים וּשְׁנַיִם שֵׁמוֹת, וַיִּסַּע וַיָּבֹא וַיֵּט. זֶה וָא\"ו מִן וה\"ו, שָׁם עֵזֶר, וְלֹא קִימָה, וְזֶהוּ עָזב תַּעֲזב, שָׁם (שם יא) בְּעִתּוֹ יוֹרֶה וּמַלְקוֹשׁ וְאָסַפְתָּ דְגָנֶךְ וְתִירשְׁךְ וְיִצְהָרֶךְ, שֶׁהֵם יִשְׂרָאֵל. לֶקֶט שִׁכְחָה וּפֵאָה, (ויקרא יט) לֶעָנִי וְלַגֵּר תַּעֲזֹב אֹתָם. כָּאן לָמַדְנוּ מִצְוָה שְׁלִישִׁית."],[6,"","וְצָרִיךְ לַחֲזר עֲלֵיהֶם, שֶׁהֲרֵי מִצַּד הַצַּדִּיק, עָנִי - עָזֹב תַּעֲזֹב, צַדִּיק. עִמּוֹ - זֶה בֶּן עַמְרָם. וְזֶהוּ לֶעָנִי וְלַגֵּר תַּעֲזֹב אֹתָם. גֵּר אַתָּה כְּמוֹ שֶׁנֶּאֱמַר בְּךְ בַּתְּחִלָּה עַם עָנִי, (שמות יח) גֵּר הָיִיתִי בְּאֶרֶץ נָכְרִיָּה."],[7,"","אֲבָל הֲקָמָה בַּדַּרְגָּה שֶׁלְּךְ, הָקֵם - ו' תַּחְתּוֹנָה. תָּקִים עִמּוֹ - עִם בֶּן עַמְרָם, בְּדַרְגָּה עֶלְיוֹנָה שֶׁלְּךְ, תִּפְאֶרֶת. בְּמ\"ה שֶׁלְּךְ הַשֵּׁם הַמְפֹרָשׁ בִּשְׁלֵמוּת. אַחַר ק' ק' שֶׁל הָקֵם תָּקִים (ומשוםכךהקםתקים) נִשְׁאָר תים. מַה זֶּה מַרְאֶה? (בראשית כה) יַעֲקֹב אִישׁ תָּם. עִמּוֹ - עִם בֶּן עַמְרָם יָקִים. הָקֵם - צַדִּיק. תָּקִים - תָּם."],[8,"","מִצְוָה אַחַר זוֹ לִפְדּוֹת עֶבֶד עִבְרִי וְאָמָה הָעִבְרִיָּה, לְיַעֵד אָמָה הָעִבְרִיָּה לָדוּן בְּקִנְיַן עֶבֶד עִבְרִי, הַעֲנֵיק תַּעֲנִיק לוֹ. זֶהוּ שֶׁכָּתוּב כִּי תִקְנֶה עֶבֶד עִבְרִי שֵׁשׁ שָׁנִים יַעֲבֹד. מָהֵן שֵׁשׁ שָׁנִים יַעֲבֹד, וּמַהוּ קִנְיָנוֹ? אֶלָּא בְּסִתְרֵי תוֹרָה, מְטַטְרוֹ\"ן עֶבֶד ה' כּוֹלֵל שִׁשָּׁה צְדָדִים כְּחֶשְׁבּוֹן שֵׁשׁ אוֹתִיּוֹתָיו, שִׁשָּׁה סִדְרֵי מִשְׁנָה. וּבָהֶן יֵשׁ לָאָדָם לַעֲבֹד לְרִבּוֹנוֹ לִהְיוֹת לוֹ עֶבֶד (ממכר), לַעֲשׂוֹת קִנְיַן כַּסְפּוֹ שֶׁל כֶּסֶף יָמִין, שֶׁאַבְרָהָם חֶסֶד הוּא הַדַּרְגָּה שֶׁלּוֹ, הַתּוֹרָה נִתְּנָה מִשָּׁם."],[9,"","וּמִי שֶׁמִּשְׁתַּדֵּל בָּהּ כְּדֵי לִזְכּוֹת לָעוֹלָם הַבָּא, נִקְרָא קִנְיָן. כַּסְפּוֹ - עוֹלַם הַכִּסּוּף. קִנְיָן - עַל שֵׁם (בראשית יד) אֵל עֶלְיוֹן קֹנֵה שָׁמַיִם וָאָרֶץ. קְנֵה חָכְמָה קְנֵה בִינָה. קָנָה לוֹ דִּבְרֵי תוֹרָה."],[10,"","רַבּוֹ אַחַר שֶׁקָּנָה לוֹ, גְּאֻלָּה תִּהְיֶה לּוֹ. יֵשׁ שֶׁהוּא קָנוּי (לו) לְעוֹלָם, וְיֵשׁ שֶׁהוּא קָנוּי לוֹ שֵׁשׁ שָׁנִים. מִי שֶׁהוּא קָנוּי לוֹ לְעוֹלָם, כָּתוּב בּוֹ וְרָצַע אֲדנָיו אֶת אָזְנוֹ בַּמַּרְצֵעַ וַעֲבָדוֹ לְעֹלָם. אֵין עוֹלָם אֶלָּא עוֹלָמוֹ שֶׁל יוֹבֵל, שֶׁהֵם חֲמִשִּׁים. וְזוֹ קְרִיאַת שְׁמַע שֶׁשָּׁם כ\"ה כ\"ה אוֹתִיּוֹת, עַרְבִית וְשַׁחֲרִית. חֲמִשִּׁים שַׁעֲרֵי בִינָה."]]],[["בָּתַר דִּמְיַחֵד בְּהוֹן בַּר נָשׁ לְקוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהוּ עֶבֶד דִּילֵיהּ, בְּעוֹל תְּפִלִּין עַל רֵישֵׁיהּ. וְאֹזֶּן דִּילֵיהּ רְצִיעָא פְּתִיחָא לְמִשְׁמַע קְרִיאַת שְׁמַע, דִּשְׁמַע, בְּכָל לָשׁוֹן שֶׁאַתָּה שׁוֹמֵעַ, דְּהַיְינוּ מַשְׁמָעוּת.","דְּמַאן דְּפִדְיוֹן דִּילֵיהּ תְּלוּיָה בִּקְרִיאַת שְׁמַע, דְּאִיהוּ רָזָא דְּחַמְשִׁין, לֵית לֵיהּ פִּדְיוֹן עַל יַד אַחֲרָא בְּגִלְגּוּלָא, דִּמְרוּצָע הוּא לְמָארֵיהּ, הָכָא לָא אִתְּמַר (ויקרא כ״ה:מ״ט) אוֹ דוֹדוֹ אוֹ בֶן דוֹדוֹ יִגְאָלֶנּוּ. דְּבִצְלוֹתָא דְּבַר נָשׁ, אִיהוּ כְּעֶבֶד, דְּאִתְּמַר בֵּיהּ שֵׁשׁ שָׁנִים יַעֲבֹד. וְאֵין עֲבוֹדָה, אֶלָּא תְּפִלָּה. שֵׁשׁ שָׁנִים יַעֲבֹד: ג' רִאשׁוֹנוֹת, וְג' אַחֲרוֹנוֹת דְּשְׁלִיחַ צִבּוּר אַפִּיק לֵיהּ לְבַר נָשׁ יְדֵי חוֹבָתוֹ, לְמַאן דְּלָא יָדַע לְצַלָּאָה בְּהוּ דְּצַדִּיק חַי עָלְמָא, אִתְקְרֵי בְּהוּ, עַל שְׁמֵיהּ. בֹּעַז, צַדִּיק, גּוֹאֵל, קָרוֹב, וְנֶאֱמָן.","(נ\"א ותמן) (תהילים קמ״ה:י״ח) קָרוֹב יְיָ' לְכָל קוֹרְאָיו. וְטָב לֵיהּ לְבַר נָשׁ, (משלי כ״ז:י׳) שָׁכֵּן קָרוֹב מֵאָח רָחוֹק, דְּהַיְינוּ עַמּוּדָא דְּאֶמְצָעִיתָא, דְּאִיהוּ בֶּן יָהּ, דְּאִסְתַּלָּק לְעֵילָּא דְּאִיהוּ בִּינָה, דְּעוֹלָם דָּא, עוֹלָמוֹ שֶׁל יוֹבֵל, דְּאִיהוּ חַמְשִׁין אַתְוָון דְּיִחוּדָא. דְּבְעָלְמָא דֵּין, יָכִיל בַּר נָשׁ, לְמֶהוֵי לֵיהּ פִּדְיוֹן בְּצַדִיק, ו' שְׁנִין דְּכָלִיל תְּלַת קַדְמָאִין, וּתְלַת בַּתְרָאִין דִּצְלוֹתָא. ו' זְעִירָא, אִינּוּן (נ\"א איהו) שִׁית שְׁנִין יַעֲבוֹד.","אֲבָל בְּעָלְמָא דְּאָתֵי, דְּאִיהוּ עוֹלָמוֹ שֶׁל יוֹבֵל, דְּתַּמָּן נ' אַתְוָון דִּקְרִיאַת שְׁמַע, לֵית שְׁלִיחַ צִבּוּר אַפִּיק לֵיהּ מֵחוֹבָה. בְּגִין דְּלֵית לֵיהּ פִּדְיוֹן עַל יְדֵי אֲחֵרִים. וּבְגִין דָּא שְׁמַע, בְּכָל לָשׁוֹן שֶׁאַתָּה שׁוֹמֵעַ. וּבְגִין דָּא קָא רָמִיז, אִם אֵין אֲנִי לִי מִי לִי. מִ\"י: וַדַּאי עוֹלָמוֹ שֶׁל יוֹבֵל.","מִיַּד דְּשָׁמְעוּ מִלִּין אִלֵּין, מָארֵי מְתִיבְתָּאן דַּהֲווֹ נַחְתֵּי עִם בּוּצִינָא קַדִּישָׁא, פָּתְחוּ וְאָמְרוּ, רַעְיָא מְהֵימָנָא, פִּי שְׁכִינְתָּא עִלָּאָה וְתַתָּאָה, דִּבְתַרְוַויְיהוּ קוּדְשָׁא בְּרִיךְ הוּא פֶּה אֵל פֶּה מַלִּיל עִמָּךְ בִּקְרִיאַת שְׁמַע, דְּאִתְּמַר בֵּיהּ, (תהילים קמ״ט:ו׳) רוֹמְמוֹת אֵל בִּגְרוֹנָם וְחֶרֶב פִּיפִיּוֹת בְּיָדָם. דְּהָא וַדַּאי, י', רֵישָׁא דְּחַרְבָּא, דְּאַסְחַר שָׂפָה דִּילָךְ. ו', לִישָׁנָא דְּחַרְבָּא דִּילָךְ. ה', ה', תְּרֵין פִּיפִיּוֹת, בִּתְרֵין שִׂפְוָון דִּילָךְ. וְהָא וַדַּאי, שְׁמָא דְּמָרָךְ, מְמַלֵּל בְּפוּמָךְ. יוּ\"ד הֵ\"א וָא\"ו הֵ\"א, אִיהוּ בְּמַחֲשַׁבְתָּךְ דְּאַפִּיק אִלֵּין חַמְשִׁין מִפּוּמָךְ.","בְּוַדַּאי, בְּגִין מִלִּין אִלֵּין, אֵלִיָּהוּ אִתְעַכָּב לְעֵילָּא, דְּתָפִיס אִיהוּ. דְּלָא נָחִית לְגַבָּךְ, דְּהָא בְּכַמָּה עֻתְרָא הֲוָה נָחִית לְגַבָּךְ. וְאִיהוּ תָּפִיס לְעֵילָּא, דְּלָא נָחִית לְגַבָּךְ. בְּגִין דַּעֲנִיּוּתָא דִּילָךְ, אִיהוּ פָּרוֹקָא לְיִשְׂרָאֵל. וּבְגִין דָּא מָשִׁיחַ אָמַר, עַד דְּיֵיתֵי עָנִי, וְהַאי אִיהוּ דִּכְתִּיב, (ישעיהו נ״ג:ה׳) וּבַחֲבוּרָתוֹ נִרְפָּא לָנוּ.","אָמַר לוֹן, אִי הָכִי, נַעְבִּד לֵיהּ הַתָּרָה, וִיהֵא נָחִית לְגַבָּאי, דְּחָשִׁיב הוּא גַּבָּאי, מִכָּל מָמוֹנָא דְּעָלְמָא. וְהָא אֲנָא מָחִיל וְשָׁרֵי לֵיהּ, וּמַתִּיר לֵיהּ אוֹמָאָה. וְאַתּוּן אוּף הָכִי שָׁרוּ לֵיהּ וְאִי צָרִיךְ הַתָּרָה יַתִּיר, נִשְׁתַּדֵּל בַּהַתָּרָתֵיהּ, דִּיהֵא נָחִית גַּבָּאי.","אָמַר לֵיהּ בּוּצִינָא קַדִּישָׁא, שְׁבוּעַת יְיָ', אִיהִי שְׁכִינְתָּא, בַּת יְחִידָה. וְלָא לְמַגָּנָא תַּקִּינוּ תְּלַת בְּנִי נָשָׁא, לְמִפְטַר לֵיהּ. אֶלָּא, ש' דְּשַׁבָּת, תְּלַת עַנְפֵי אֲבָהָן, בַּת יְחִידָה. שְׁבוּעָה. דְּאִשְׁתְּתָּפַת (ס\"א בה כורסיא ודאי) בְּהוּ.","בְּוַדַּאי, שְׁבוּעָה לָא חָלָה אֶלָּא עַל דָּבָר שֶׁיֵּשׁ בּוֹ מַמָּשׁ. נֵדֶר חָל, אֲפִילּוּ עַל דָּבָר שֶׁאֵין בּוֹ מַמָּשׁ. וְהָא אוּקְמוּהָ בְּמַתְנִיתִין. וְלא עוֹד, אֶלָּא יַתִּיר אָמְרוּ, נְדָרִים עַל גַּבֵּי שְׁבוּעוֹת עוֹלִין, וְכָל הַנִּשְׁבַּע כְּאִלּוּ נִשְׁבַּע בַּמֶּלֶךְ עַצְמוֹ. וְכָל הַנּוֹדֶר, כְּאִילּוּ נוֹדֵר בְּחַיֵּי הַמֶּלֶךְ.","אָמַר לוֹן רַעְיָא מְהֵימְנָא, מָארֵי דִּמְתִיבְתָאן, יְדַעְנָא בְּכוּ, דְּאַתּוּן יַדְעִין, אֲבָל הַהוּא דִּמְחַדֵּשׁ בְּכָל יוֹם תָּמִיד מַעֲשֵׂה בְּרֵאשִׁית, יְחַדֵּשׁ לוֹן חִדוּשִׁין, דְּהָא וַדַּאי אָמַר קֹהֶלֶת, (קהלת א׳:ט׳) אֵין כָּל חָדָשׁ תַּחַת הַשָּׁמֶשׁ, אֲבָל לְמַעְלָה מִן הַשֶּׁמֶשׁ, יֵשׁ לוֹ. וּבְסִתְרֵי תּוֹרָה אֲנָא בָּעֵינָא לְמֵימַר, (תהילים פ״ד:ט׳) שֶׁמֶשׁ וּמָגֵן יְיָ' אֱלֹהִים צְבָאוֹת, בְּעָלְמָא דִּילֵיהּ, וְלָא בְּעָלְמָא דְּהֶדְיוֹט, אַף עַל גַּב דְּזֶה לְעוּמַת זֶה עָשָׂה הָאֱלהִים, מִגּוֹ חֲשׁוֹכָא, נָפִיק נְהוֹרָא.","וּבְוַדַּאי עָלְמָא דְּאָתֵי, בִּינָה, אִיהִי לְמַעְלָה מֵהַשֶּׁמֶשׁ, דְּאִיהוּ עַמּוּדָא דְּאֶמְצָעִיתָא. נְדָרִים מִתַּמָּן, עַל גַּבֵּי שְׁבוּעָה עוֹלִים, וְחָלִין עַל דָּבָר שֶׁאֵין בּוֹ מַמָּשׁ, בְּגִין דִּשְׁבוּעָה אִיהוּ עָלְמָא דֵּין, דְּלֵית לֵיהּ קִיּוּמָא, אֶלָּא עַל יְסוֹד, הֲדָא הוּא דִכְתִיב, (משלי י׳:כ״ה) וְצַדִיק יְסוֹד עוֹלָם."],[[0,"בתר דמיחד בהון וכו':","אחר שאדם מיחד בהם את הקב\"ה, שהוא עבד שלו בעול בתפלין על ראשו, ואזנו נרצעת דהיינו שפתוחה לשמוע קריאת שמע. כי שמע, בכל לשון שאתה שומע, שומע, היינו משמעות, שצריך להבין משמעות הקריאת שמע, שה\"ס היחוד."],[1,"דמאן דפדיון דיליה וכו':","שמי שהפדיון שלו תלוי בקריאת שמע, שהוא סוד החמשים שהוא בינה, אין לו פדיון בגלגול על ידי אחר, כי נרצע הוא לאדונו, כאן לא נאמר, או דודו או בן דודו יגאלנו. כי בתפלה של אדם, הוא כעבד, שנאמר בו, שש שנים יעבד, ואין עבודה אלא תפלה. שש שנים יעבד, הוא ג' ראשונות וג' אחרונות, שבשמונה עשרה, שהשליח צבור מוציא האדם ידי חובתו, למי שאינו יודע להתפלל בהם. הרי שיש לו פדיון על ידי אחר, שהשליח צבור גואל אותו, שהצדיק חי העולם, שהוא יסוד, דהיינו השליח צבור, נקרא בהם, על שמו, של האינו יודע להתפלל, בשם, בעז, צדיק, גואל קרוב, ונאמן, שמשמעותם של השמות הללו הוא, שעוזרים ופודים את מי שאינו יכול לעזור את עצמו. שה\"ס היבום והגלגול."],[2,"קרוב ה' לכל קוראיו:","שטוב לו לאדם, שכן קרוב מאח רחוק, דהיינו עמוד האמצעי, שהוא ת\"ת, שהיסוד נקרא שכן קרוב, והת\"ת נקרא אח רחוק שהוא בן י\"ה, שעלה למעלה לבינה, כי עולם זה הוא עולמו של יובל, שהם חמשים אותיות על היחוד דקריאת שמע. שהם חמשים שערי בינה כנ\"ל. שבעולם הזה, שהוא המלכות, יכול להיות לאדם פדיון מצדיק, שהוא יסוד, שהוא שש שנים, הכולל ג' ברכות ראשונות וג' אחרונות של התפלה, וה\"ס \u0003ו'\u0004 קטנה, שהוא יסוד, והיינו שש שנים יעבד."],[3,"אבל בעלמא דאתי וכו':","אבל בעולם הבא, שהוא עולמו של יובל, דהיינו בינה ששם חמשים אותיות של קריאת שמע, אין השליח צבור יכול להוציא ידי חובתו, משום שאין לו פדיון על ידי אחרים. ומשום זה, שמע, בכל לשון שאתה שומע, רק שתקרא בעצמך. ומשום זה, הרמז, אם אין \u0003אני\u0004 לי \u0003מ\"י\u0004 לי. \u0003אני,\u0004 היא המלכות, \u0003מ\"י,\u0004 ודאי עולמו של יובל, שהוא בינה. והרמז הוא על ק\"ש, ששם אין אנ\"י אלא מ\"י."],[4,"מיד דשמעו מלין וכו':","ומיד ששמעו דברים אלו, אלו ראשי ישיבות שירדו עם המאור הקדוש, שהוא ר\"ש, פתחו ואמרו, למשה רבנו, רעיא מהימנא, אתה הוא, פי שכינה העליונה והתחתונה, שהן בינה ומלכות, שבשתיהן דבר עמך הקב\"ה פה אל פה בקריאת שמע, שנאמר בו רוממות אל בגרונם וחרב פיפיות בידם. כי ודאי \u0003י'\u0004 דהויה היא ראש החרב הסובב את השפה שלך. \u0003ו'\u0004 דהויה היא לשון החרב שלך. \u0003ה\"ה\u0004 דהויה, הן שתי פיפיות בשתי שפתים שלך. והרי ודאי, שם אדונך, שהיא השכינה, מדבר בפיך. יוד הא ואו הא, הוא במחשבתך, שהוציאה אלו חמשים שערי בינה מפיך."],[4,"","פירוש. התורה, ה\"ס המוחין המתגלים מן הבינה בסוד הדעת, לזו\"ן ולבי\"ע. וה\"ס \u0003החרב,\u0004 שהיא המכנעת והמשמידה את הס\"א. וגילויה הוא על ידי שיתוף המלכות בבינה, המשוה צורתן זו לזו (כנ\"ל בראשית א' דף ז' ד\"ה וכבר ע\"ש) שבעת קטנות יש לבינה צורת המלכות, ובעת גדלות יש למלכות צורת הבינה, דהיינו שמשגת המוחין שלה. וע\"כ יש לשתיהן אותה האות בשם הוי\"ה, דהיינו \u0003ה'.\u0004 וע\"כ הן בצורה אחת בפי החרב שנבחנות לב' פיות של החרב, שהיא התורה. ובהן עיקר הכח שבחרב, כי זולת ההשואה לא היה שום גילוי להתורה, ונמצאות שהן עיקר הפועלות להשמיד הס\"א, כמו החוד של החרב שהיא עיקר הפועל של החרב. וכן הן בצורה אחת בפה, ששם מקום הגילוי של המוחין ע\"י הדבור, שבינה היא שפה עלאה, והמלכות היא שפה תחתונה."],[4,"","וז\"ש \u0003רעיא מהימנא, פי שכינתא עלאה ותתאה.\u0004 שהוא נעשה לפה לשתיהן יחד שזה היא האפשרות היחידה לגילוי התורה כנ\"ל. \u0003דבתרווייהו, קב\"ה, פה אל פה מליל עמך בקריאת שמע,\u0004 שבפסוק שמע, יש חמשים אותיות, שהם שערי בינה, כנ\"ל, שמהם כללות כל המוחין הבאים בגילוי התורה. \u0003דאתמר ביה רוממות אל בגרונם וחרב פיפיות בידם,\u0004 שזה נאמר על פה של משה, ומפרש, ענין חרב פיפיות בשם הויה, ובפה של משה. ואומר, \u0003י' רישא דחרבא דאסחר שפה שלך, י'\u0004 דהויה ה\"ס חכמה המזדווגת עם \u0003שפה\u0004 עלאה שה\"ס בינה ו \u0003ה'\u0004 ראשונה דהויה, שהם סוד הראש של החרב, דהיינו הג\"ר. \u0003ו' לישנא דחרבא דילך,\u0004 ה \u0003ו'\u0004 של הויה ה\"ס \u0003הלשון\u0004 שבפה וה \u0003חרב\u0004 של משה, כי הוא סוד הדעת הנמשך מזווג \u0003י\"ה\u0004 הנ\"ל. והיא התורה. \u0003ה' ה' תרין פיפיות בתרין שפוון דילך,\u0004 ששפה עליונה היא בינה ושפה תחתונה היא מלכות, שהן עיקר הפועלות לגילוי המוחין, דהיינו בסוד התיקון של השואת צורתם זו לזו, (כנ\"ל ב\"א דף ז' ד\"ה וכבר) וכשנתקנה המלכות בדרך הזה היא נקראת, שם שמים. וז\"ש, \u0003והא ודאי שמאדמרך ממלל בפומך,\u0004 דהיינו המלכות המדברת ומגלית המוחין מן הבינה. \u0003יוד הא ואו הא, איהו במחשבתך,\u0004 שה\"ס קו האמצעי שבמחשבה שהיא הג\"ר, \u0003דאפיק אלין חמשין מפומך,\u0004 שהוא המוציא החמשים שערי בינה מפה משה. בסוד \u0003שמע,\u0004 וכו' כנ\"ל."],[5,"בודאי בגין מלין וכו':","בודאי משום דברים אלו, הנ\"ל, ששורשם הוא תקון המלכות בבינה, והשואת צורתם זו לזו הנה משום זה, אליהו מתעכב למעלה, שהוא אסור שם, כבבית האסורים, ואינו יורד אליך, כי בעשירות גדולה היה יורד אליך. והוא אסור למעלה ואינו יורד אליך, משום שהעניות שלך היא גאולה לישראל. ומשום זה אמר משיח עד שיבא העני. וזה הוא שכתוב, ובחבורתו נרפא לנו."],[5,"","פירוש. בסבת המתקת המלכות בבינה, הנ\"ל, נגנזה המלכות דמדת הדין, (כנ\"ל בהקדמת ספר הזהר דף קכ\"ג אות קכ\"ב ד\"ה ב' תרין ע\"ש) והיא שער הנ' הנעלם, מכח הגניזה הזו. וע\"כ נ' שערי בינה נמסרו למשה חסר אחד. דהיינו שער הנ' הנ\"ל. וזה הוא עניות של משה, שאין עני אלא מדעת, שהיה חסר לו שער הנ'. ועם גילוי אליהו מתגלה שער הנ'. וז\"ש, \u0003בגין מלין אלו,\u0004 דהיינו המתקת צורת המלכות בצורת הבינה, בסוד חרב פיפיות, \u0003אליהו אתעכב לעילא דתפיס איהו דלא נחית לגבך,\u0004 כי מטעם המתקת המלכות בבינה נגנזה המלכות דמדת הדין שהוא שער הנ', ואליהו, שה\"ס גילוי שער הנ', נעכב למעלה, כמו אסור בבית האסורים, ואינו יכול לירד ולגלותו. \u0003דהא בכמה עתרא הוה נחית לגבך,\u0004 דהיינו עשירות הדעת המגלה שער הנ'. ולמה הוא אסור למעלה, הוא מפרש, \u0003ואיהו תפיס לעילא דלא נחית לגבך, בגין דעניותא דילך איהו פרוקא לישראל.\u0004 כי לולא המתקת המלכות בבינה וגניזת המלכות דמדת הדין, לא היו זו\"ן והעולמות ראוים למוחין דג\"ר, (כנ\"ל בראשית א' דף ז' ד\"ה וכבר,) ונמצא שעניות של משה, שהוא העלם שער הנ' מחמת הגניזה, היא גאולת ישראל, שעל ידי כן נעשו זו\"ן והעולמות ראוים למוחין דג\"ר, להשפיע לישראל, שבזה תלוי הגאולה וגמר התקון, וע\"כ אליהו אסור למעלה ולא יוכל לגלות את שער הנ' מטרם שיספיקו ישראל לקבל כל המוחין הראוים להתגלות על ידי המתקה הזו של מלכות בבינה. וז\"ש \u0003דעניותא דילך איהו פרוקא לישראל.\u0004 וע\"כ בהכרח, אליהו אסור למעלה ולא יוכל לרדת לגלות שער הנ'. וז\"ש, \u0003ובגין דין משיח אמר עד דייתי עני,\u0004 דהיינו שהגאלה תלויה, עד שיבא העני משער הנ', שה\"ס משה, ויגלה כל המוחין המוכרחים להתגלות. \u0003והאי איהו דכתיב ובחבורתו נרפא לנו,\u0004 כי אותו הכאב והחבורה של חסרון שער הנ', הוא המגלה את כל המוחין, ומרפא את ישראל מכל חסרונותיהם."],[6,"אמר לון אי וכו':","אמר להם, אי הכי, נעשה לו התרה וירד אלי, כי חשוב הוא לי מכל כסף שבעולם. והרי אני מוחל לו ומשחרר אותו ומתיר לו השבועה, ואתם גם כן, התירו לו. ואם צריך להתרה יתרה מזו, נשתדל בהתרתו, שירד אלי."],[7,"אמר ליה בוצינא וכו':","א\"ל המאור הקדוש, שבועת ה', היא השכינה, בת היחידה, שנקראת שבועת ה'. ולא לחנם התקינו ג' אנשים להתיר את השבועה, אלא הוא סוד \u0003ש'\u0004 של שבת שג' ענפים של הש' רומזים לג' אבות, שהם חג\"ת, והקו העב המקשר את ג' הענפים מלמטה, היא הבת יחידה, הנקראת \u0003שבועה,\u0004 שמשתתפת בהם בג' הענפים שב \u0003ש'.\u0004 פירוש, המלכות נקראת שבועה, בעת שמחוברת עם חג\"ת דז\"א שלמעלה מחזה שלו, בסוד רגל רביעי לכסא העליון, שעל זה רומזת ש' של שבת, וע\"כ ג' אנשים, שהם כנגד חג\"ת האלו, יכולים להתיר את השבועה."],[8,"בודאי שבועה לא וכו':","בודאי שהשבועה אינה חלה אלא על דבר שיש בו ממש, נדר חל אפילו על דבר שאין בו ממש. וכבר העמידוהו במתניתין. ולא עוד אלא יותר מזה אמרו שנדרים עולים על שבועות, שכל הנשבע נשבע במלך עצמו, דהיינו במלכות, וכל הנודר כאלו נודר בחיי המלך, שהיא בינה שמשם נמשך החיים, שהם המוחין אל המלכות."],[8,"","פירוש. נודע שבג\"ר יכולה החכמה להאיר בלי לבוש החסדים מה שאין כן בז\"ס תחתוניות שבהן, אין החכמה מאירה בלי חסדים. וז\"ש \u0003שבועה לא חלה אלא דבר שיש בו ממש,\u0004 כי השבועה, שה\"ס המלכות הממשכת חכמה למעלה מחזה דז\"א בסוד רביעי לאבות (ב\"א ק\"י ד\"ה מלכותא ע\"ש) אינה מתקיימת שם מחמת חסרון חסדים, אלא מוכרחת לרדת למטה מחזה ולקבל חסדים מיסוד דז\"א להלביש בהם החכמה ואז חלה השבועה, דהיינו שמתקיימת. ומסך הזה של היסוד הממשיך חסדים מכונה דבר שיש בו ממש, דהיינו עוביות. משא\"כ \u0003נדר,\u0004 שה\"ס בינה וג\"ר, \u0003חל אפילו על דבר שאין בו ממש.\u0004 שאין צריך למסך להשפעת החסדים, כי בג\"ר יכולה החכמה להאיר אפילו בלא חסדים. (כמ\"ש בשער הכונות יוה\"כ דרוש ג' דף ק\"א) וחולק על דברי חז\"ל נדרים י\"ג:"],[9,"אמר לון ר\"מ וכו':","אמר להם רעיא מהימנא. בעלי הישיבות, יודע אני בכם שאתם יודעים, ענין השבועה והנדר, אבל ההוא, המחדש בכל יום תמיד מעשה בראשית יחדש לנו חדושים, כי ודאי אמר קהלת, אין כל חדש תחת השמש, שהוא ז\"א, אבל למעלה משמש יש חדושים. ובסתרי תורה אני רוצה לומר, שמש ומגן ה' אלקים צבאות, שמשמע שמאיר ומגן אפילו תחת השמש, זה הוא בעולם שלו, דהיינו בעולם אצילות, ולא בעולם של הדיוט, דהיינו בג' עולמות בריאה יצירה עשיה, שיש שם קליפות, המכחישים יחודו. ואע\"פ שזה לעומת זה עשה האלקים. דהיינו שהקליפות הן מעשה אלקים, כי מן החשך שהוא הקליפות יוצא אור, על ידי שבני אדם מתגברים עליהם. מכל מקום נחשבים לעולם של הדיוט, ואין אור השמש שהוא ז\"א דאצילות נמשך להגן עליהם."],[10,"ובודאי עלמא דאתי וכו':","ובודאי עולם הבא, שהוא בינה, הוא למעלה מן השמש שהוא עמוד האמצעי, דהיינו ז\"א. וע\"כ נדרים, שהם משם, עולים על שבועה וחלים על דבר שאין בו ממש, דהיינו שאין בו המסך הממשיך חסדים, כנ\"ל. ומשום ששבועה, הוא עולם הזה, דהיינו מלכות, שאין לו קיום אלא על יסוד, שהוא הנושא למסך דחסדים שיש בו ממש, כנ\"ל בדבור הסמוך, ז\"ש וצדיק יסוד עולם. ונמצא שאינה חלה אלא על דבר שיש בו ממש."]],[[0,"","אַחַר שֶׁמְּיַחֵד בָּהֶם הָאָדָם אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא עֶבֶד שֶׁלּוֹ, בְּעֹל תְּפִלִּין עַל רֹאשׁוֹ, וְאָזְנוֹ נִרְצְעָה וּפְתוּחָה לִשְׁמֹעַ קְרִיאַת שְׁמַע, הֲרֵי שְׁמַע - בְּכָל לָשׁוֹן שֶׁאַתָּה שׁוֹמֵעַ, שֶׁהַיְנוּ מַשְׁמָעוּת."],[1,"","שֶׁמִּי שֶׁפִּדְיוֹנוֹ תָּלוּי בַּקְּרִיאַת שְׁמַע, שֶׁהוּא סוֹד שֶׁל חֲמִשִּׁים, אֵין לוֹ פִּדְיוֹן עַל יְדֵי אַחֵר בְּגִלְגּוּל, שֶׁרָצוּעַ הוּא לְרִבּוֹנוֹ. כָּאן לֹא נֶאֱמַר אוֹ דוֹדוֹ אוֹ בֶן דוֹדוֹ יִגְאָלֶנּוּ. שֶׁבִּתְפִלַּת הָאָדָם הוּא כְּמוֹ עֶבֶד שֶׁנֶּאֱמַר בּוֹ שֵׁשׁ שָׁנִים יַעֲבֹד, וְאֵין עֲבוֹדָה אֶלָּא תְּפִלָּה. שֵׁשׁ שָׁנִים יַעֲבֹד - ג' רִאשׁוֹנוֹת וְג' אַחֲרוֹנוֹת שֶׁל שְׁלִיחַ צִבּוּר מוֹצִיא אֶת הָאָדָם יְדֵי חוֹבָתוֹ לְמִי שֶׁלֹּא יוֹדֵעַ לְהִתְפַּלֵּל בָּהֶם, שֶׁצַּדִּיק חַי הָעוֹלָם נִקְרָא בָהֶם עַל שְׁמוֹ. בּעַז, צַדִּיק, גּוֹאֵל, קָרוֹב וְנֶאֱמָן."],[2,"","(ושם) קָרוֹב ה' לְכָל קֹרְאָיו. וְטוֹב לוֹ לָאָדָם שָׁכֵן קָרוֹב מֵאָח רָחוֹק, שֶׁהַיְנוּ עַמּוּד הָאֶמְצָעִי, שֶׁהוּא בֶּן יָהּ, שֶׁהִתְעַלָּה לְמַעְלָה שֶׁהוּא לְבִינָה, שֶׁעוֹלָם זֶה הוּא עוֹלָמוֹ שֶׁל יוֹבֵל, שֶׁהוּא חֲמִשִּׁים אוֹתִיּוֹת הַיִּחוּד. שֶׁבָּעוֹלָם הַזֶּה יָכוֹל אָדָם לִהְיוֹת לוֹ פִּדְיוֹן בְּצַדִּיק ו' שָׁנִים שֶׁכּוֹלֵל שָׁלֹשׁ רִאשׁוֹנוֹת, וְשָׁלֹשׁ אַחֲרוֹנוֹת שֶׁל הַתְּפִלָּה. ו' קְטַנָּה הוּא שֵׁשׁ שָׁנִים יַעֲבֹד."],[3,"","אֲבָל בָּעוֹלָם הַבָּא, שֶׁהוּא עוֹלָמוֹ שֶׁל יוֹבֵל, שֶׁשָּׁם חֲמִשִּׁים אוֹתִיּוֹת שֶׁל קְרִיאַת שְׁמַע, אֵין שְׁלִיחַ צִבּוּר מוֹצִיא אוֹתוֹ יְדֵי חוֹבָתוֹ, מִשּׁוּם שֶׁאֵין לוֹ פִּדְיוֹן עַל יְדֵי אֲחֵרִים, וּמִשּׁוּם כָּךְ שְׁמַע, בְּכָל לָשׁוֹן שֶׁאַתָּה שׁוֹמֵעַ. וּמִשּׁוּם כָּךְ רוֹמֵז, אִם אֵין אֲנִי לִי מִי לִי. מִ\"י - וַדַּאי עוֹלָמוֹ שֶׁל יוֹבֵל."],[4,"","מִיָּד שֶׁשָּׁמְעוּ דְבָרִים הַלָּלוּ רָאשֵׁי הַיְשִׁיבוֹת שֶׁהָיוּ יוֹרְדִים עִם הַמְּנוֹרָה הַקְּדוֹשָׁה, פָּתְחוּ וְאָמְרוּ, רוֹעֶה הַנֶּאֱמָן, פִּי הַשְּׁכִינָה הָעֶלְיוֹנָה וְהַתַּחְתּוֹנָה, שֶׁבִּשְׁתֵּיהֶן הַקָּדוֹשׁ בָּרוּךְ הוּא דִּבֵּר עִמְּךְ פֶּה אֶל פֶּה בִּקְרִיאַת שְׁמַע, שֶׁנֶּאֱמַר בּוֹ (תהלים קמט) רוֹמְמוֹת אֵל בִּגְרוֹנָם וְחֶרֶב פִּיפִיּוֹת בְּיָדָם. שֶׁהֲרֵי וַדַּאי י' רֹאשׁ הַחֶרֶב שֶׁסּוֹבֶבֶת אֶת הַשָּׂפָה שֶׁלְּךְ. ו' לְשׁוֹן הַחֶרֶב שֶׁלְּךְ. ה' ה' שְׁתֵּי פִיפִיּוֹת, בִּשְׁתֵּי שִׂפְתוֹתֶיךְ. וַהֲרֵי וַדַּאי שֵׁם רִבּוֹנְךְ מְדַבֵּר בְּפִיךְ. יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א הוּא בְּמַחֲשַׁבְתְּךְ שֶׁמּוֹצִיא אֶת הַחֲמִשִּׁים הַלָּלוּ מִפִּיךְ."],[5,"","בְּוַדַּאי מִשּׁוּם הַדְּבָרִים הַלָּלוּ אֵלִיָּהוּ הִתְעַכֵּב לְמַעְלָה, שֶׁהוּא תָּפוּס, שֶׁלֹּא יוֹרֵד אֵלֶיךְ, שֶׁהֲרֵי בְּכַמָּה עֹשֶׁר הָיָה יוֹרֵד אֵלֶיךְ, וְהוּא תָּפוּס לְמַעְלָה, שֶׁלֹּא יוֹרֵד אֵלֶיךְ. מִשּׁוּם שֶׁהָעֹנִי שֶׁלְּךְ הוּא גְּאֻלָּה לְיִשְׂרָאֵל, וּמִשּׁוּם כָּךְ אָמַר מָשִׁיחַ, עַד שֶׁיָּבא עָנִי, וְזֶהוּ שֶׁכָּתוּב (ישעיה נג) וּבַחֲבֻרָתוֹ נִרְפָּא לָנוּ."],[6,"","אָמַר לָהֶם, אִם כָּךְ, נַעֲשֶׂה לוֹ הַתָּרָה וְיֵרֵד אֵלַי, שֶׁחָשׁוּב הוּא לִי מִכָּל מָמוֹן שֶׁל הָעוֹלָם, וַהֲרֵינִי מוֹחֵל וּמְשַׁחְרֵר אוֹתוֹ וּמַתִּיר לוֹ אֶת הַשְּׁבוּעָה, וְאַף אַתֶּם הַתִּירוּ לוֹ. וְאִם צָרִיךְ הַתָּרָה יוֹתֵר, נִשְׁתַּדֵּל בְּהַתָּרָתוֹ, כְּדֵי שֶׁיֵּרֵד אֵלַי."],[7,"","אָמַר לוֹ הַמְּנוֹרָה הַקְּדוֹשָׁה, שְׁבוּעַת ה', הִיא שְׁכִינָה, בַּת יְחִידָה. וְלֹא לְחִנָּם תִּקְּנוּ שְׁלֹשֶׁת בְּנֵי אָדָם לִפְטֹר אוֹתוֹ, אֶלָּא ש' שֶׁל שַׁבָּת, שְׁלֹשֶׁת עַנְפֵי הָאָבוֹת, בַּת יְחִידָה, שְׁבוּעָה שֶׁהִשְׁתַּתְּפָה (בה כסא ודאי) בָּהֶם."],[8,"","בְּוַדַּאי שְׁבוּעָה לֹא חָלָה אֶלָּא עַל דָּבָר שֶׁיֵּשׁ בּוֹ מַמָּשׁ. נֶדֶר חָל אֲפִלּוּ עַל דָּבָר שֶׁאֵין בּוֹ מַמָּשׁ, וַהֲרֵי פֵּרְשׁוּהָ בַּמִּשְׁנָה. וְלֹא עוֹד, אֶלָּא יוֹתֵר אָמְרוּ, נְדָרִים עַל גַּבֵּי שְׁבוּעוֹת עוֹלִים, וְכָל הַנִּשְׁבָּע כְּאִלּוּ נִשְׁבָּע בַּמֶּלֶךְ עַצְמוֹ, וְכָל הַנּוֹדֵר כְּאִלּוּ נוֹדֵר בְּחַיֵּי הַמֶּלֶךְ."],[9,"","אָמַר לָהֶם רוֹעֶה הַנֶּאֱמָן, רָאשֵׁי יְשִׁיבוֹת, יָדַעְתִּי בָכֶם שֶׁאַתֶּם יוֹדְעִים, אֲבָל אוֹתוֹ שֶׁמְּחַדֵּשׁ בְּכָל יוֹם מַעֲשֵׂה בְרֵאשִׁית יְחַדֵּשׁ לָכֶם חִדּוּשִׁים, שֶׁהֲרֵי וַדַּאי קֹהֶלֶת אָמַר, (קהלתא) אֵין כָּל חָדָשׁ תַּחַת הַשָּׁמֶשׁ. אֲבָל לְמַעְלָה מִן הַשֶּׁמֶשׁ יֵשׁ לוֹ. וּבְסִתְרֵי תוֹרָה אֲנִי רוֹצֶה לוֹמַר, (תהלים סד) שֶׁמֶשׁ וּמָגֵן ה' אֱלֹהִים צְבָאוֹת, בָּעוֹלָם שֶׁלּוֹ, וְלֹא בְּעוֹלָם שֶׁל הֶדְיוֹט. אַף עַל גַּב שֶׁזֶּה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים, מִתּוֹךְ הַחֲשֵׁכָה יוֹצֵא הָאוֹר."],[10,"","וּבְוַדַּאי בָּעוֹלָם הַבָּא, בִּינָה הִיא לְמַעְלָה מֵהַשֶּׁמֶשׁ, שֶׁהוּא עַמּוּד הָאֶמְצָעִי. מִשָּׁם עוֹלִים נְדָרִים עַל גַּבֵּי שְׁבוּעָה וְחָלִים עַל דָּבָר שֶׁאֵין בּוֹ מַמָּשׁ, מִשּׁוּם שֶׁהַשְּׁבוּעָה הוּא הָעוֹלָם הַזֶּה, שֶׁאֵין לוֹ קִיּוּם אֶלָּא עַל יְסוֹד. זֶהוּ שֶׁכָּתוּב (משליי) וְצַדִּיק יְסוֹד עוֹלָם."]]],[["וּבֵיהּ אוֹמָאָה, דִּכְתִּיב, (רות ג׳:י״ג) חַי יְיָ' שִׁכְבִי עַד הַבֹּקֶר. דִּשְׁכִינְתָּא תַּתָּאָה, כּוֹתֶל מַעֲרָבִי, דִּיּוּרָא דִּילֵיהּ. עַל שֵׁם דְּאִיהוּ תֵּל שֶׁהַכֹּל פּוֹנִים בּוֹ. כּ\"וֹ תֵּ\"ל, יְדוָֹ\"ד כּ\"וֹ, וַדַּאי שְׁכִינְתָּא, אִיהוּ תֵּל דִּילֵיהּ. עַל שֵׁם, (שיר השירים ה׳:י״א) קֶוִצּוֹתָיו תַּלְתַּלִּים שְׁחוֹרוֹת כָּעוֹרֵב וְאוּקְמוּהָ עַל כָּל קוֹץ וְקוֹץ תִּלֵּי תִּלִּים שֶׁל הֲלָכוֹת. (קוץ) ד' מִן אֶחָד, תֵּל שֶׁהַכֹּל פּוֹנִים בּוֹ. וְהַאי קוֹץ, הוּא אָחִיד בֵּין א\"ח, וּבֵין ד', הֲדָא הוּא דִכְתִיב, (דברי הימים א כ״ט:י״א) כִּי כֹל בַּשָּׁמַיִם וּבָאָרֶץ, וְתִרְגֵם יְהוֹנָתָן, דְּאָחִיד בִּשְׁמַיָּא וּבְאַרְעָא.","וְעָלֵיהּ אוּקְמוּהָ מִכָּל מָקוֹם בְּחֲגִיגָה, עַל מַה הָעוֹלָם עוֹמֵד, עַל עַמּוּד אֶחָד שֶׁשְּׁמוֹ צַדִּיק, שֶׁנֶּאֱמַר וְצַדִיק יְסוֹד עוֹלָם. וּבְוַדַּאי אִיהוּ בְּרִית דִּשְׁבוּעָה, דְּעָלֵיהּ קַיְימִין א\"ח ד', דְּאִינּוּן שְׁמַיָּא וְאַרְעָא, דִּכְתִּיב, (ירמיהו ל״ג:כ״ה) אִם לֹא בְרִיתִי יוֹמָם וְלַיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. א\"ח שָׁמַיִם, הֲדָא הוּא דִכְתִיב, (מלכים א ח׳:ל״ב) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם. ד', הָאָרֶץ. הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ו:א׳) וְהָאָרֶץ הֲדוֹם רַגְלָי.","וּבְגִין דִּבְרִית אָחִיד בֵּין שְׁמַיָּא וְאַרְעָא, וּבֵיהּ שְׁבוּעָה, הֲדָא הוּא דִכְתִיב, חַי יְיָ' שִׁכְבִי עַד הַבֹּקֶר. מַאן דְּאוּמֵי בִּשְׁמֵיהּ לְשִׁקְרָא, כְּאִילּוּ הָרַס בִּנְיָינָא דִּשְׁמַיָּא וְאַרְעָא, וְאַהְדָּר עָלְמָא לְתֹהוּ וָבֹהוּ. דְּאִי בַּר נָשׁ יַעְדֵי קוֹצָא דְּד' מִן אֶחָד יִשְׁתְּאַר אַחֵר, סָמָאֵל בְּאַתְרֵיהּ שֶׁקֶר. וּכְאִלּוּ הַהוּא בַּר נָשׁ בָּנֵי שְׁמַיָּא וְאַרְעָא עַל שֶׁקֶר. וְקוּשְׁטָא קָאֵי, שִׁקְרָא לָא קָאֵי. הָרַס בִּנְיָינָא, וְנָפְלוּ שְׁמַיָּא וְאַרְעָא.","וְהַאי אִיהוּ כְּאִילּוּ הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ תִּפְאֶרֶת יִשְׂרָאֵל. דְּמַאן יָהִיב אֶרֶץ בַּשָּׁמַיִם, דְּקָאָמַר (איכה ב׳:א׳) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ. אֶלָּא וַדַּאי דָּא שְׁכִינְתָּא, וְתִפְאֶרֶת עִמָּהּ, דְּלָא אִתְפְּרַשׁ מִינָהּ בִּנְפִילוּ דִּילָהּ, לְקַיֵּים בָּהּ (ישעיהו מ״ב:ח׳) אֲנִי יְיָ' הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לא אֶתֵּן. וּמְנָלָן דֶּאֱמֶת נָפַל עִמָּהּ, דִּכְתִּיב, (דניאל ח׳:י״ב) וְתַשְׁלֵךְ אֱמֶת אַרְצָה. וּמַאן דְּאוֹמֵי קוּשְׁטָא, הוּא מְקַיֵּים (תהלים פה) אֱ\"מֶת מֵ\"אֶרֶץ תִּ\"צְמָח, דְּאִיהוּ עַמּוּדָא דְּאֶמְצָעִיתָא, דְּבֵיהּ אִיהוּ קַיְּימָא בִּנְיָינָא. הֲדָא הוּא דִכְתִיב בָּרָ\"א אֱלֹהִי\"ם אֵ\"ת, וּלְבָתַר הַשָּׁמַיִם וְאֵת הָאָרֶץ.","וּבְגִין דִּשְׁבוּעָה, אִיהוּ בִּנְיָינָא דְּעָלְמָא דָּא, לֵית לֵיהּ קִיּוּמָא בְּלֹא יְסוֹד, דָּבָר שֶׁיֵּשׁ בּוֹ מַמָּשׁ. נֶדֶר, דְּאִיהוּ עָלְמָא דְּאָתֵי, עַל גַּבֵּי שְׁבוּעָה סְלִיקַת, וְאִיהִי חָלָה עַל דָּבָר שֶׁאֵין בּוֹ מַמָּשׁ, דְּלָא צְרִיכָה יְסוֹד לְקַיְּימָא עָלֵיהּ, דְּאִיהוּ בְּרִית, דְּבֵיהּ תַּשְׁמִישׁ הַמִּטָּה. וּבְגִין דָּא, בְּיוֹם הַכִּפּוּרִים, עָלְמָא דְּאָתֵי, דְּבֵיהּ תַּקִּינוּ כָּל נִדְרֵי, אָסוּר בְּתַשְׁמִישׁ הַמִּטָּה.","תַּמָּן אוֹת בְּרִית, י' אִיהִי תָּגָא עַל סֵפֶר תּוֹרָה צַדִּיק, כְּמָה דְּאוּקְמוּהָ הָעוֹלָם הַבָּא, אֵין בּוֹ, לֹא אֲכִילָה, וְלֹא שְׁתִיָּה, וְלא תַּשְׁמִישׁ הַמִּטָּה, אֶלָּא צַדִּיקִים יוֹשְׁבִים וְעַטְרוֹתֵיהֶם בְּרָאשֵׁיהֶם.","וּבְגִין דְּלֵית (ס\"א דאית) שִׁמּוּשׁ בְּעָלְמָא דֵּין בְּתָגָא, אוּקְמוּהָ מָארֵי מַתְנִיתִין, כָּל הַמִּשְׁתַּמֵּשׁ בְּתָגָא חֲלָף. דְּתָגָא לְתַתָּא, בְּעָלְמָא דֵּין אִיהִי. נְקוּדָה שִׁמּוּשָׁא דְּאַתְוָון. אֲבָל בְּעָלְמָא דְּאָתֵי, לֵית שִׁמּוּשָׁא בְּאַתְוָון, וּבְגִין דָּא סֵפֶר תּוֹרָה לֵית בֵּיהּ נְקוּדָה בְּאַתווֹי, אֶלָּא תָּגָא, וּבְגִין דָּא, מַאן דְּמִשְׁתַּמֵּשׁ בְּסֵפֶר תּוֹרָה חֲלָף. וְהָכִי, מַאן דְּמִשְׁתַּמֵּשׁ בְּמִי שֶׁשּׁוֹנֶה הֲלָכוֹת, עָלֵיהּ אוּקְמוּהָ רַבָּנָן, דְּאִשְׁתַּמַּשׁ בְּתָגָא חֲלָף.","אָתוּ כֻּלְּהוּ מָארֵי מְתִיבְתָּאן, וְאִשְׁתְּטָחוּ קָמֵיהּ, וְאָמְרוּ וַדַּאי קוּדְשָׁא בְּרִיךְ הוּא מַלִּיל בְּפוּמָךְ, וְלֵיהּ אֲנָן סַגְדִּין. וַאֲנָן אִשְׁתְּמוֹדְעִין בְּמִלִּין אִלֵּין, דְּלֵית יְלוּד אִשָּׁה אַחֲרָא בַּר מִינָךְ, יָכִיל לְמַלְּלָא לוֹן. וַדַּאי מִלִּין אִלֵּין, קָא סָהֲדִין בָּךְ, דְּאַנְתְּ הוּא דְּאִתְּמַר בֵּיהּ, (במדבר י״ב:ח׳) פֶּה אֶל פֶּה אֲדַבֵּר בּוֹ. לֵית לְעַכְּבָא לְאֵלִיָּהוּ גַּבָּךְ, אֶלָּא לְפַיְּיסָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, לְנַחְתָּא לֵיהּ לְגַבָּךְ, מַלְיָא עוּתְרָא, מַלְיָיא סְגוּלוֹת לְגַבָּךְ.","רַעְיָא מְהֵימָנָא, עֶבֶד נְאֱמָן, לְגַבָּךְ עֶבֶד עִבְרִי, (דברים ט״ו:י״ד) הַעֲנֵק תַּעֲנִיק לוֹ. הַעֲנֵק לֵיהּ, תַּעֲנִיק לִבְנוֹי, בְּמִלִּין גְּנִיזִין אִלֵּין. (דברים ט״ו:י״ד) וּמִגָּרְנְךָ: גָּרְנָהּ שֶׁל תּוֹרָה דִּילָךְ. וּמִיִּקְבֶךָ, בְּגֹרֶן וְיֶקֶב קְרָא מְמַלֵּל, כְּמָה דְּאוּקְמוּהָ מָארֵי מַתְנִיתִין, בִּפְסוֹלֶת גֹרֶן וְיֶקֶב הַכָּתוּב מִדְבָּר.","יֶקֶ\"ב: (קי\"ט ע\"א, רס\"ב ע\"א) יִ\"חוּד. קְ\"דוּשָׁה. בְּ\"רָכָה דְּקוּדְשָׁא בְּרִיךְ הוּא. וְדָא שְׁכִינְתָּא, דְּאִיהִי בְּרָכָה, דְּקוּדְשָׁא בְּרִיךְ הוּא, מִימִינָא. וְאִיהִי קְדוּשָּׁה מִשּׂמָאלֵיהּ. וְאִיהִי יִחוּדֵיהּ, בְּאֶמְצָעִיתָא. וְקוּדְשָׁא בְּרִיךְ הוּא, הָכִי סַלְּקִין אַתְווֹי דִּילֵיהּ, יַבֹּ\"ק. כְּגַוְונָא דָּא, הַקָדוֹשׁ בָּרוּךְ הוּא: בְּחֻשְׁבַּן יַבֹּ\"ק."],[[0,"וביה אומאה דכתיב וכו':","ובו, ביסוד נשבעים, שכתוב \u0003חי\u0004 ה' שכבי עד הבקר. והיסוד נקרא \u0003חי.\u0004 שהשכינה התחתונה הנקראת כותל מערבי, שהוא המלכות, היא משכן שלו, על שם שהיא תל שהכל פונים אליו. כי כותל הוא אותיות \u0003כ\"ו ת\"ל,\u0004 הוי\"ה, שהוא ז\"א, הוא בגימטריא \u0003כ\"ו,\u0004 וודאי השכינה, היא \u0003תל\u0004 של ז\"א, על שם, קווצותיו תלתלים שחורות כעורב, שהעמידוהו, שעל כל \u0003קוץ וקוץ\u0004 תלי תלים של הלכות. \u0003ד'\u0004 של אחד היא \u0003תל\u0004 שהכל פונים בו, דהיינו המלכות. \u0003וקוץ\u0004 הזה, של ה \u0003ד',\u0004 המבדילה מן צורת \u0003ר',\u0004 שהוא יסוד, הוא נאחז בין \u0003א\"ח\u0004 דאחד, שהוא ז\"א, ובין ד' דאחד, שהיא המלכות, ז\"ש כי \u0003כל\u0004 בשמים ובארץ, ותרגום יונתן דאחיד בשמיא ובארעא. כי \u0003כל\u0004 הוא שם היסוד, והוא נאחז בז\"א שנקרא שמים ובמלכות שנקראת ארץ."],[1,"ועליה אוקמוה מ\"מ וכו':","ועליו, על היסוד, העמידו בעלי המשנה בחגיגה, על מה העולם עומד, על עמוד אחד ששמו צדיק, דהיינו יסוד, שנאמר וצדיק יסוד עולם. ובודאי הוא ברית של השבועה, שהיא מלכות, כי עליו עומדים \u0003א\"ח ד',\u0004 שהם שמים וארץ, שכתוב, אם לא בריתי יומם ולילה חוקות שמים וארץ לא שמתי. \u0003א\"ח\u0004 הוא \u0003שמים,\u0004 ז\"ש, ואתה תשמע השמים, דהיינו ז\"א. \u0003ד'\u0004 היא \u0003ארץ\u0004 ז\"ש והארץ הדום רגלי. דהיינו המלכות."],[2,"ובגין דברית אחיד וכו':","ומשום שהברית, שהוא יסוד, אחוז בין שמים וארץ, שהם זו\"ן, ובו השבועה, שהיא המלכות, ז\"ש חי ה' שכבי עד הבקר. כי השבועה תלויה ביסוד הנקרא \u0003חי.\u0004 ומי שנשבע בשמו לשקר, הוא כאלו הרס הבנין של שמים וארץ, והחזיר את העולם לתהו ובהו. כי אם אדם מסיר הקוץ, שהוא יסוד, מן ה \u0003ד'\u0004 דאחד, שהיא המלכות, ישאר אחר. שהוא סמאל, הנקרא אחר, שבמקומו שקר, ודומה כאלו אדם ההוא בנה שמים וארץ על שקר. ואמת עומד, ושקר אינו עומד, שסופו להתבטל. והוא הרס הבנין ונפלו שמים וארץ."],[3,"והאי איהו כאלו וכו':","וזה, הנשבע לשקר, הוא כאלו השליך משמים ארץ תפארת ישראל. שואל, ומי נתן הארץ בשמים, שאומר, השליך משמים ארץ. ומשיב, אלא ודאי, זו היא השכינה שנקראת ארץ, ותפארת, הנקרא שמים, הוא עמה, שלא נפרד ממנה אפילו בנפילה שלה, לקיים בה, אני ה' הוא שמי וכבודי לאחר לא אתן. ומאין לנו, שהאמת, שהוא ז\"א, נפל עמה, שכתוב, ותשלך אמת ארצה. הרי שהגורם לנפילת המלכות גורם ג\"כ לנפילת ז\"א וע\"כ הנשבע לשקר גורם לנפילת שמים וארץ. ומי שנשבע אמת, הוא מקיים \u0003א\u0004 מת \u0003מ\u0004 ארץ \u0003ת\u0004 צמח, שהוא עמוד האמצעי דהיינו ז\"א הנקרא אמת, שבו עומד הבנין, ז\"ש בר \u0003א\u0004 אלקי \u0003ם\u0004 א \u0003ת\u0004 שסופי תיבות הוא \u0003אמת,\u0004 ואח\"כ, השמים ואת הארץ. הרי שבנין שמים וארץ מתקיים על אמת."],[4,"ובגין דשבועה איהו וכו':","ומשום שהשבועה היא בנין של עולם הזה, מלכות, אין לו קיום בלי יסוד, שהוא דבר שיש בו ממש, שהוא הנושא למסך, שעליו יוצא זווג החסדים כנ\"ל. נדר, שהוא עולם הבא, בינה, עולה על שבועה, והוא חל על דבר שאין בו ממש, שהבינה אינה צריכה יסוד להתקיים עליו, שהוא ברית, שבו תשמיש המטה. כי בג\"ר אין החכמה צריכה לחסדים להתלבש בהם, כנ\"ל. ומשום זה ביום הכפורים, שהוא עולם הבא, בינה, שבו תקנו \u0003כל נדרי,\u0004 משום שהנדר הוא מבינה, אסור בתשמיש המטה, שאין זווג דיסודות נוהג בבינה. כנ\"ל."],[5,"תמן אות ברית וכו':","שם, בבינה, אות ברית שהוא \u0003י',\u0004 דהיינו יסוד דבינה, הוא עטרה של ספר תורה, שהוא צדיק, דהיינו יסוד דז\"א. כמו שהעמדנוה, העולם הבא אין בו לא אכילה ולא שתיה, ולא תשמיש המטה, אלא צדיקים יושבים ועטרותיהם בראשיהם."],[6,"ובגין דלית שמוש וכו':","ומשום שאין שמוש בעולם הזה, שהוא מלכות, בתגא, שהוא עטרה על ראש צדיק, הנוהג רק בבינה, העמידו בעלי המשנה, כל המשתמש בתגא חלף, מן העולם. כי התגא בעולם הזה, הוא למטה מן היסוד ואינה בראש צדיק. הנקודות הן שמוש לאותיות, אבל בעולם הבא שהוא בינה, אין שימוש לאותיות, שרומזים לזו\"ן. ומשום זה בס\"ת, אין נקודות באותיות אלא תגין, שהם נמשכים מבינה, והם עטרה בראש האותיות שהם זו\"ן. ומשום זה מי שמשמש בספר תורה חלף מן העולם. וכך, מי שמשמש במי ששונה הלכות, עליו אמרו רבנן, דאשתמש בתגא חלף."],[7,"אתו כלהו מארי וכו':","באו כל ראשי הישיבות והשתטחו לפניו, ואמרו, ודאי שהקב\"ה מדבר בפיך, ולו אנו משתחוים, ואנו מכירים בדברים אלו, שאין ילוד אשה אחר חוץ ממך, יכל לדבר אותם. ודאי דברים אלו מעידים עליך, שאתה הוא שנאמר בו. פה אל פה אדבר בו. אין לעכב את אליהו ממך, אלא לבקש מן הקב\"ה שיוריד אותו אליך מלא עשירות מלא סגולותבשבילך."],[8,"רעיא מהימנא עבד וכו':","רועה הנאמן, עבד הנאמן, עליך עבד עברי, נאמר, הענק תעניק לו. הענק לו, תעניק לבניו, את דברים הנסתרים האלה. \u0003ומגרנך,\u0004 בגרנה של תורה שלך. \u0003ומיקבך,\u0004 בגרן ויקב הכתוב מדברעל דרך שהעמידוהו בעלי המשנה, בפסולת גורן ויקב הכתוב מדבר."],[8,"","פירוש. גרן, הוא ז\"א, יקב, היא המלכות. ויש בחינת דינים דדכורא, שהם נמשכים מנקודת השורק. והם \u0003פסולת גרן.\u0004 ויש דינים דנוקבא, הנמשכים מנקודת החירק (כמ\"ש לעיל בראשית א' ט\"ו ד\"ה ההיא ע\"ש) והם פסולת היקב. כי יקב הוא הנוקבא, דהיינו מלכות."],[9,"יקב, יחוד קדושה ברכה וכו':","יק\"ב, הוא ראשי תיבות \u0003י\u0004 חוד \u0003ק\u0004 דושה \u0003ב\u0004 רכה, דקודשא בריך הוא, והיא השכינה, דהיינו מלכות שהיא \u0003ברכה\u0004 של הקב\"ה, בעת שהיא בסוד הימין, דהיינו חסדים. והוא \u0003קדושה\u0004 של הקב\"ה בעת שהיא בשמאלו, דהיינו בחכמה. והיא \u0003יחוד\u0004 של הקב\"ה, בעת שהיא בקו האמצעי. והקב\"ה, כך עולות האותיות שלו במספר \u0003יב\"ק,\u0004 שהוא אותיות יקב, כזה \u0003הקב\"ה,\u0004 בחשבון \u0003יב\"ק.\u0004 כי הקב\"ה הוא ז\"א, והנוקבא ה\"ס החשבון של ז\"א."]],[[0,"","וּבוֹ שְׁבוּעָה, שֶׁכָּתוּב חַי ה' שִׁכְבִי עַד הַבֹּקֶר. שֶׁשְּׁכִינָה תַּחְתּוֹנָה, כֹּתֶל מַעֲרָבִי הוּא הַדִּיּוּר שֶׁלָּהּ, עַל שֵׁם שֶׁהוּא תֵּל שֶׁהַכֹּל פּוֹנִים בּוֹ. כּ\"וֹ תֵּ\"ל, יְדוָ\"ד כּ\"וֹ, וַדַּאי שְׁכִינָה הִיא תֵּל שֶׁלּוֹ, עַל שֵׁם (שיר ה) ק1ְוֵצּוֹתָיו תַּלְתַּלִּים שְׁחֹרוֹת כָּעוֹרֵב. וּפֵרְשׁוּהָ עַל כָּל קוֹץ וְקוֹץ תִּלֵּי תִלִּים שֶׁל הֲלָכוֹת. (קוץ) ד' מִן אֶחָד, תֵּל שֶׁהַכֹּל פּוֹנִים בּוֹ. וְהַקּוֹץ הַזֶּה אָחוּז בֵּין א\"ח וּבֵין ד'. זֶהוּ שֶׁכָּתוּב כִּי כֹל בַּשָּׁמַיִם וּבָאָרֶץ, וְתִרְגֵּם יְהוֹנָתָן, שֶׁאָחוּז בַּשָּׁמַיִם וּבָאָרֶץ."],[1,"","וְעָלָיו בֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה בַּחֲגִיגָה, עַל מָה הָעוֹלָם עוֹמֵד? עַל עַמּוּד אֶחָד שֶׁשְּׁמוֹ צַדִּיק, שֶׁנֶּאֱמַר וְצַדִּיק יְסוֹד עוֹלָם. וּבְוַדַּאי הוּא בְּרִית שֶׁל שְׁבוּעָה שֶׁעָלָיו עוֹמְדִים א\"ח ד', שֶׁהֵם שָׁמַיִם וָאָרֶץ, שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. א\"ח שָׁמַיִם, זֶהוּ שֶׁכָּתוּב (מלכים א ח) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם. ד' הָאָרֶץ, זֶהוּ שֶׁכָּתוּב (ישעיה סו) וְהָאָרֶץ הֲדם רַגְלָי."],[2,"","וּמִשּׁוּם שֶׁבְּרִית אֲחוּזָה בֵּין שָׁמַיִם וָאָרֶץ וּבָהּ שְׁבוּעָה, זֶהוּ שֶׁכָּתוּב חַי ה' שִׁכְבִי עַד הַבֹּקֶר. מִי שֶׁנִּשְׁבָּע בִּשְׁמוֹ לַשֶּׁקֶר, כְּאִלּוּ הָרַס אֶת בִּנְיַן הַשָּׁמַיִם וְהָאָרֶץ וְהֶחֱזִיר אֶת הָעוֹלָם לְתֹהוּ וָבהוּ. שֶׁאִם אָדָם יָזִיז הַקּוֹץ שֶׁל ד' מִן אֶחָד, יִשָּׁאֵר אַחֵר, סמא\"ל בִּמְקוֹמוֹ שֶׁקֶר. וּכְאִלּוּ אוֹתוֹ אִישׁ בּוֹנֶה שָׁמַיִם וָאָרֶץ עַל שֶׁקֶר. וֶאֱמֶת עוֹמֵד, שֶׁקֶר לֹא עוֹמֵד. הָרַס הַבִּנְיָן, וְנָפְלוּ שָׁמַיִם וָאָרֶץ."],[3,"","וְזְהִוּ כְּאִלּוּ הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ תִּפְאֶרֶת יִשְׂרָאֵל. שֶׁמִּי נוֹתֵן אֶרֶץ בַּשָּׁמַיִם, שֶׁאָמַר (איכה ב) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ? וַדַּאי זוֹ שְׁכִינָה, וְתִפְאֶרֶת עִמָּהּ, שֶׁלֹּא נִפְרָד מִמֶּנָּה בִּנְפִילָתָהּ, לְקַיֵּם בָּהּ (ישעיה מב) אֲנִי ה' הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן. וּמִנַּיִן לָנוּ שֶׁאֱמֶת נָפַל עִמָּהּ? שֶׁכָּתוּב (דניאל ח) וְתַשְׁלֵךְ אֱמֶת אַרְצָה. וּמִי שֶׁנִּשְׁבָּע אֱמֶת הוּא מְקַיֵּם (תהלים פה) אֱ\"מֶת מֵ\"אֶרֶץ תִּ\"צְמָח. שֶׁהוּא הָעַמּוּד הָאֶמְצָעִי שֶׁבּוֹ הַבִּנְיָן קַיָּם. זֶהוּ שֶׁכָּתוּב בָּרָ\"א אֱלֹהִי\"ם אֵ\"ת, וְאַחַר כָּךְ - הַשָּׁמַיִם וְאֵת הָאָרֶץ."],[4,"","וּמִשּׁוּם שֶׁשְּׁבוּעָה הִיא בִּנְיָן שֶׁל הָעוֹלָם הַזֶּה, אֵין לוֹ קִיּוּם לְלֹא יְסוֹד, דָּבָר שֶׁיֵּשׁ בּוֹ מַמָּשׁ. נֶדֶר, שֶׁהוּא עוֹלָם הַבָּא, עוֹלֶה עַל גַּבֵּי שְׁבוּעָה, וְהוּא חָל עַל דָּבָר שֶׁאֵין בּוֹ מַמָּשׁ, שֶׁלֹּא צְרִיכָה יְסוֹד לַעֲמֹד עָלָיו, שֶׁהוּא בְּרִית, שֶׁבּוֹ תַּשְׁמִישׁ הַמִּטָּה. וּמִשּׁוּם כָּךְ בְּיוֹם הַכִּפּוּרִים, הָעוֹלָם הַבָּא, שֶׁבּוֹ תִּקְּנוּ כָּל נִדְרֵי, אָסוּר בְּתַשְׁמִישׁ הַמִּטָּה."],[5,"","שָׁם אוֹת בְּרִית, י' הִיא תָּג עַל סֵפֶר תּוֹרָה צַדִּיק, כְּמוֹ שֶׁבֵּאֲרוּהָ, הָעוֹלָם הַבָּא אֵין בּוֹ לֹא אֲכִילָה וְלֹא שְׁתִיָּה וְלֹא תַּשְׁמִישׁ הַמִּטָּה, אֶלָּא צַדִּיקִים יוֹשְׁבִים וְעַטְרוֹתֵיהֶם בְּרָאשֵׁיהֶם."],[6,"","וּמִשּׁוּם שֶׁאֵין שִׁמּוּשׁ בָּעוֹלָם הַזֶּה בְּתָג, בֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, כָּל הַמִּשְׁתַּמֵּשׁ בְּתָגָא חֲלָף. שֶׁתָּג לְמַטָּה הוּא בָּעוֹלָם הַזֶּה. הַנְּקֻדָּה שִׁמּוּשׁ הָאוֹתִיּוֹת. אֲבָל בָּעוֹלָם הַבָּא אֵין שִׁמּוּשׁ בָּאוֹתִיּוֹת, וְלָכֵן בְּסֵתֶר תּוֹרָה אֵין נִקּוּד בְּאוֹתִיּוֹתָיו, אֶלָּא תָּגִים. וְלָכֵן מִי שֶׁמִּשְׁתַּמֵּשׁ בְּסֵפֶר תּוֹרָה חוֹלֵף, וְכָךְ מִי שֶׁמִּשְׁתַּמֵּשׁ בְּמִי שֶׁשּׁוֹנֶה הֲלָכוֹת, עָלָיו בֵּאֲרוּ רַבּוֹתֵינוּ שֶׁהַמִּשְׁתַּמֵּשׁ בְּתָגָא - חוֹלֵף."],[7,"","בָּאוּ כָּל רָאשֵׁי הַיְשִׁיבוֹת וְהִשְׁתַּטְּחוּ לְפָנָיו וְאָמְרוּ, וַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא מְדַבֵּר בְּפִיךְ, וְלוֹ אָנוּ מִשְׁתַּחֲוִים. וְאָנוּ מַכִּירִים בַּדְּבָרִים הַלָּלוּ שֶׁאֵין יְלוּד אִשָּׁה אַחֵר פְּרָט לְךְ שֶׁיָּכוֹל לְדַבֵּר אוֹתָם. וַדַּאי שֶׁהַדְּבָרִים הַלָּלוּ מְעִידִים בְּךְ שֶׁאַתָּה הוּא שֶׁנֶּאֱמַר בּוֹ (במדבר יב) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ. אֵין לְעַכֵּב אֶת אֵלִיָּהוּ אֵלֶיךְ, אֶלָּא לְפַיֵּס אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיּוֹרִיד אוֹתוֹ אֵלֶיךְ, מָלֵא עֹשֶׁר וּמָלֵא סְגֻלּוֹת אֵלֶיךְ."],[8,"","רוֹעָה הַנֶּאֱמָן, עֶבֶד נֶאֱמָן, אֵלֶיךְ עֶבֶד עִבְרִי - (דבריםטו) הַעֲנֵיק תַּעֲנִיק לוֹ. הַעֲנֵיק - לוֹ, תַּעֲנִיק - לְבָנָיו, בַּדְּבָרִים הַגְּנוּזִים הַלָּלוּ. וּמִגָּרְנְךְ - גָּרְנָהּ שֶׁל הַתּוֹרָה שֶׁלְּךְ. וּמִיִּקְבְךְ - בְּגֹרֶן וְיֶקֶב הַכָּתוּב מְדַבֵּר, כְּמוֹ שֶׁבֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, בִּפְסֹלֶת גֹּרֶן וְיֶקֶב הַכָּתוּב מְדַבֵּר."],[9,"","יֶקֶ\"ב - יִ\"חוּד, קְ\"דֻשָּׁה, בְּ\"רָכָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְזוֹ הַשְּׁכִינָה, שֶׁהִיא בְּרָכָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מִיָּמִין, וְהִיא קְדֻשָּׁה מִשְּׂמֹאלוֹ, וְהִיא יִחוּדוֹ בָּאֶמְצַע, וְכָךְ עוֹלוֹת אוֹתִיּוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא יַבֹּ\"ק. כְּמוֹ זֶה הקב\"ה בְּחֶשְׁבּוֹן יַבּ\"ק."]]],[["וּמַאן דְּאִיהוּ בָּקִ\"י בַּהֲלָכָה דִּילֵיהּ, דְּאִיהִי שְׁכִינְתָּא, קוּדְשָׁא בְּרִיךְ הוּא עִמֵּיהּ. דִּבְגִינָהּ לָא יָזוּז מִנֵּיהּ לְעָלַם. דְּאִית הֲלָכָה דְּאִיהִי נַעֲרָה דִּילָהּ, מִסִּטְרָא דְּנַעַר, וּבְגִינָהּ אִתְּמַר הֲלָכָה כִּפְלוֹנִי. אֲבָל הֲלָכָה דִּילָךְ, רַעְיָא מְהֵימָנָא, אִיהִי דְּאִתְּמַר בָּהּ, הֲלָכָה לְמֹשֶׁה מִסִּינַי, מִפִּי הַגְּבוּרָה, יָהִיב לָךְ קוּדְשָׁא בְּרִיךְ הוּא, בְּרָתָא דִּילֵיהּ.","וּבְגִין דָּא, עַל הֲלָכוֹת אַחֲרָנִין אִתְּמַר, (משלי ל״א:כ״ט) רַבּוֹת בָּנוֹת עָשׂוּ חָיִל. עַל הֲלָכָה דִּילָךְ אִתְּמַר, וְאַתְּ עָלִית עַל כֻּלָּנָה. דְּאִתְגַּבַּרְתּ עַל כֻּלְּהוּ, בִּגְבוּרָה. (שופטים ו׳:י״ב) יְיָ' עִמְּךָ גִּבּוֹר הֶחָיִל. אַתְקִין (ס\"א אתתקפת) בָּךְ, וְאַשְׁלִים בִּנְיָינָא דְּמַלְכָּא, וְאִיהוּ בָּנֵי בִּנְיָינֵיהּ עַל פּוּמָךְ, וְעַל יְדָךְ, זַכָּאָה חוּלָקָךְ.","פָּתַח רַעְיָא מְהֵימָנָא וְאָמַר, (בראשית מ״ח:ט״ז) הַמַּלְאָךְ הַגּוֹאֵל אוֹתִי מִכָּל רָע, דְּאִיהִי שְׁכִינְתָּא, דְּאִתְּמַר בָּהּ, (שמות י״ד:י״ט) וַיִּסַּע מַלְאַךְ הָאֱלֹהִים. יְבָרֵךְ לְכוּ בְּעָלְמָא דְּאָתֵי. וְיִדְגּוּ לָרֹב בְּקֶרֶב הָאָרֶץ, בְּעָלְמָא דֵּין. לְמֶהֱוֵי שֻׁלְטָנוּתֵכוֹן בִּתְרֵין עָלְמִין, דְּאַתּוּן חַיִּין. דְּמַאן דְּאִיהוּ מֵעָלְמָא דָּא, חַי אִתְקְרֵי. כְּמָה דִּכְתִּיב, (משלי ג׳:י״ח) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. חַיִּים תַּמָּן, חַיִּים הָכָא.","מַה דְּלָאו הָכִי, מַאן דְּאִיהוּ מְלוּבָּשׁ בְּאִלֵּין קְלִיפִין, דְּעוֹר וּבָשָׂר וַעֲצָמוֹת וְגִידִים דְּגוּפָא שְׁפֵלָא, דְּרוּחָא הוּא מִית תַּמָּן. מַה מֵיתָא, לָא חָמֵי וְלָא שָׁמַע וְלָא מְמַלֵּל וְלֵית לֵיהּ תְּנוּעָה בְּכָל אֵבָרִין דִּילֵיהּ. הָכִי רוּחָא, לָא חָזָא דִּלְעֵיל מִנִּיהּ. דְּאִתְּמַר בְּאוֹרַיְיתָא עָלַיְיהוּ, דָּע מַה לְמַעְלָה מִמָּךְ, עַיִן רוֹאֶה וְאֹזֶן שׁוֹמַעַת, וְכָל מַעֲשֶׂיךָ בְּסֵפֶר נִכְתָּבִים.","דְּכַמָּה מַלְאָכִין אַזְלִין עִמֵּיהּ, דְּאִתְּמַר בְּהוֹן, (תהילים צ״א:י״א) כִּי מַלְאָכָיו יְצַוֶּה לָךְ. וְלֵית לֵיהּ רְשׁוּ בְּהַאי גּוּפָא, לְאִסְתַּכְּלָא בְּהוֹן, וּלְמִשְׁמַע בְּקַלֵיהוֹן, דְּאִינּוּן חִיוָן דְּאֶשָּׁא, (פ\"א ע\"ב) מְמַלְּלָן וּמְקַדְּשָׁן וּמְבָרְכָן וּמְיַחֲדָן לְקוּדְשָׁא בְּרִיךְ הוּא, עִם יִשְׂרָאֵל כַּחֲדָא. כָּל שֶׁכֵּן לִשְׁכִינְתָּא, דְּאִיהִי עָלַיְיהוּ. כָּל שֶׁכֵּן קוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ לְעֵילָּא מִן שְׁכִינְתֵּיהּ, דְּבָהּ מְקַבֵּל צְלוֹתִין דְּיִשְׂרָאֵל.","וּבְגִין חוֹבִין, הֲווֹ מִתְלַבְּשִׁין בְּאִלֵּין קְלִיפִין. כְּגַוְונָא דְּאָדָם, דְּחוֹבֵי אֲבָהַתְהוֹן בִּידֵיהוֹן. וְהַאי אִיהוּ דְּאוּקְמוּהָ מָארֵי מַתְנִיתִין, כְּשֶׁאוֹחֲזִין מַעֲשֵׂה אֲבוֹתֵיהֶם בִּידֵיהֶם. וּבְגִין אִלֵּין קְלִיפִין דְּחוֹבִין, אָמַר קְרָא, (ישעיהו נ״ט:ב׳) כִּי אִם עֲוֹנוֹתֵיכֶם הָיוּ מַבְדִּילִים בֵּינֵיכֶם לְבֵין אֱלֹהֵיכֶם. וּבְגִין אִלֵּין קְלִיפִין, קוּדְשָׁא בְּרִיךְ הוּא מִתְכַּסְיָא בְּכַמָּה גַּדְפִּין. דְּאִתְּמַר בְּהוֹן, (ישעיהו ו׳:ב׳) בִּשְׁתַּיִם יְכַסֶּה פָּנָיו וּבִשְׁתַּיִם יְכַסֶּה רַגְלָיו וְגוֹ'.","לֶעָתִיד לָבֹא, (ישעיהו ל׳:כ׳) וְלא יִכָּנִף עוֹד מוֹרֶיךָ וְהָיוּ עֵינֶיךָ רוֹאוֹת אֶת מוֹרֶיךָ. דְּאַתּוּן בְּהַאי עָלְמָא, דְּלֵית לְכוֹן קְלִיפִין וְעוֹרִין, אִית לְכוֹן רְשׁוּ לְאִסְתַּכְּלָא בִּבְנִי עָלְמָא, וּבְנֵי עָלְמָא (ס\"א לית) אִית לוֹן רְשׁוּ לְאִסְתַּכְּלָא בְּכוּ. וּבְגִין דָּא, עָלַיְיכוּ אִתְּמַר דְּאַתּוּן חַיִּין, וְעָלְמָא דִּלְכוֹן, עוֹלָם הַחַיִּים. אֲבָל עָלְמָא שְׁפָלָא, דָּא עוֹלָם הַמֵּתִים, דְּכָל אֱלָהוּת דְּאוּמִין דְּעָלְמָא, מִבַּלְעֲדֵי יְיָ', כֻּלְּהוֹן מֵתִים.","אָמַר לֵיהּ רַבִּי שִׁמְעוֹן, (בוצינא קדישא) (נ\"א רעיא מהימנא') עִם כָּל דָּא, דְּאַנְתְּ לָא יָכִיל לְאִסְתַּכְּלָא בִּבְנֵי עָלְמָא דְּאָתֵי בְּעַיְינִין, וְלָא בְּמַלְאֲכַיָּא, כָּל שֶׁכֵּן בְּקוּדְשָׁא בְּרִיךְ הוּא וּבִשְׁכִינְתֵּיהּ, אֲבָל בְּעֵין הַשֵּׂכֶל דְּלִבָּךְ, אַתְּ חֲזִי בְּכֹלָּא בִּבְנֵי עָלְמָא דְּאָתֵי, וּבְמַלְאָכִין וּבְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ. דְּסַחֲרִין לָךְ. וּבְגִין דָּא אָמַר שְׁלֹמֹה, דִּכְתִּיב בֵּיהּ (מלכים א ה׳:י״א) וַיֶּחְכַּם מִכָּל הָאָדָם, (קהלת א׳:ט״ז) וְלִבִּי רָאָה הַרְבֵּה חָכְמָה וָדָעַת.","אֲבָל בַּנְּבוּאָה, לֵית לְכוֹן רְשׁוּ לְאִסְתַּכְּלָא בֵּיהּ (כל שכן) נָבִיא בְּעֵין הַשֵּׂכֶל, אֶלָּא בְּעַיְינִין, דְּאִיהִי מַרְאֶה וְחֶזְיוֹן דְּעַיְינִין, הֲדָא הוּא דִכְתִיב, (במדבר י״ב:ו׳) בַּמַּרְאָה אֵלָיו אֶתְוַדָּע. וְעוֹד בְּחֶזְיוֹן לַיְלָה, מַרְאֶה בִּימָמָא, חֶזְיוֹן בְּלֵילְיָא, וְכֹלָּא בְּעַיְינִין, וְלָא בְּעֵין הַשֵּׂכֶל דְּלִבָּא. וְעַיְינִין אִינּוּן תְּרֵי סַרְסוּרֵי דְּלִבָּא, וּמִשַּׁמָּשִׁין דִּילֵיהּ. וְאִיהוּ מַלְכָּא בֵּינַיְיהוּ (לגבייהו), וּבְגִין דָּא, חָכָם עָדִיף מִנָּבִיא. וְהָכִי הוּא תְּרֵין אוּדְנִין, תְּרֵין שַׁמָּשֵׁי דְּלִבָּא.","וּבְגִין דָּא אוּקְמוּהָ רַבָּנָן, הַלֵּב רוֹאֶה, וְהַלֵּב שׁוֹמֵעַ. וְלֹא עוֹד, אֶלָּא דְּאִתְּמַר בַּלֵּב, הַלֵּב מֵבִין, הַלֵּב יוֹדֵעַ. (שמות ל״א:ו׳) וּבְלֵב כָּל חָכָם לֵב נָתַתִּי חָכְמָה. הֲרֵי חָכְמָה וּתְבוּנָה וָדַעַת בְּלִבָּא. דִּבְּהוֹן אִתְעָבִידוּ שְׁמַיָּא וְאַרְעָא, וּתְהוֹמִין. וּבְהוֹן אִתְעָבִיד מַשְׁכְּנָא, הֲדָא הוּא דִכְתִיב, (שמות ל״א:ג׳) וָאֲמַלֵּא אוֹתוֹ רוּחַ אֱלֹהִים בְּחָכְמָה בִּתְבוּנָה וּבְדַעַת. מַה דְּלֵית כּוּלֵי הַאי בְּעַיְינִין."],[[0,"ומאן דאיהו בק\"י וכו':","ומי שהוא \u0003בקי,\u0004 שהוא אותיות יקב, \u0003בהלכה\u0004 שלו, שהיא השכינה, הקב\"ה עמו, שבשבילה לא יזוז ממנו לעולם. שיש \u0003הלכה\u0004 שהיא נערה משמשת שלה מצד הנער מטטרון שבבריאה, ובשבילה אמרו \u0003הלכה\u0004 כפלוני, שסובבת על הנערה שלה. אבל \u0003הלכה\u0004 שלך, רועה הנאמן, היא שנאמר בה, הלכה למשה מסיני, מפי הגבורה נתן לך הקב\"ה בתו שלו. שהיא השכינה."],[1,"ובגין דא על וכו':","ומשום זה, על הלכות אחרות נאמר, רבות בנות עשו חיל. על הלכה שלך נאמר, ואת עלית על כלנה, שנתגברה על כולן בגבורה. ה' עמך גבור החיל. התתקן בך, והשלם בנין המלך, שהוא השכינה. כי הוא בונה את בנינו על פיך ועל ידך. אשרי חלקך."],[2,"פתח רעיא מהימנא וכו':","פתחרועה הנאמן ואמר, המלאך הגואל אותי מכל רע, שהוא השכינה, שנאמר בה, ויסע מלאך האלקים, יברך אתכם בעולם הבא. שהוא בינה. וידגו לרוב בקרב הארץ, היינו בעולם הזה. שהוא מלכות. שיהיו ממשלתכם בשני עולמות שאתם חיים. שמי שהוא מעולם הזה, שהוא מלכות, נקרא חי, כמ\"ש עץ חיים היא למחזיקים בה. חיים שם בבינה, חיים כאן במלכות."],[3,"מה דלאו הכי וכו':","מה שאין כן, מי שמלובש באלו הקליפות, של עור בשר עצמות וגידים של גוף השפל, שהרוח הוא מת שם, מה מת אינו רואה אינו שומע אינו מדבר ואין לו תנועה בכל האיברים שלו, כך הרוח אינו רואה מה שלמעלה ממנו, שנאמר עליהם בתורה, דע מה למעלה ממך, עין רואה, ואזן שומעת, וכל מעשיך בספר נכתבים."],[4,"דכמה מלאכין אזלין וכו':","שכמה מלאכים הולכים עמו, שנאמר בהם כי מלאכיו יצוה לך, ואין לו רשות בגוף הזה, להסתכל בהם ולשמוע קולם, שהם חיות אש מדברות ומקדשות ומברכות להקב\"ה ולישראל יחד. כל שכן לשכינה שהיא עליהם, וכל שכן להקב\"ה שהוא למעלה משכינה, שבה מקבל תפלות ישראל."],[5,"ובגין חובין הוו וכו':","ובשביל העונות היו מתלבשים באלו הקליפות כמו האדם, שעונות אבותיהם בידיהם. וזהו שהעמידו בעלי המשנה, כשאוחזים מעשה אבותיהם בידיהם. ומשום אלו הקליפות שמחמת העונות, אמר הכתוב, כי אם עונותיכם היו מבדילים ביניכם לבין אלקיכם. ובשביל אלו הקליפות הקב\"ה מתכסה בכמה כנפים, שנאמר בהן בשתים יכסה פניו ובשתים יכסה רגליו וגו'."],[6,"לעתיד לבא ולא וכו':","לעתיד לבא, נאמר, ולא יכנף עוד מוריך והיה עיניך רואות את מוריך, כי כשאתם בעולם הזה דהיינו מלכות, שאין לכם קליפות, ועורות, יש לכם רשות להסתכל בבני העולם, ובני העולם יש להם רשות להסתכל בכם. ומשום זה נאמר עליכם שאתם חיים, והעולם שלכם הוא עולם החיים. אבל עולם השפל הזה, הוא עולם המתים, שכל האלהות של אומות העולם, מבלעדי ה', כולם מתים."],[7,"אמ\"ל רבי שמעון וכו':","אמר לו ר\"ש, רעיא מהימנא, עם כל זה שאתה אינך יכול להסתכל בבני העולם הבא בעינים ולא במלאכים כל שכן בהקב\"ה ושכינתו, אבל בעין השכל של לבך אתה רואה הכל, בבני עולם הבא ובמלאכים ובהקב\"ה ושכינתו המסבבים אותך. ומשום זה אמר שלמה, שכתוב בו, ויחכם מכל האדם, ולבי \u0003ראה\u0004 הרבה חכמה. דהיינו בעיני השכל."],[8,"אבל בנבואה לית וכו':","אבל בנבואה, אין רשות לנביא להסתכל בו בעין השכל, אלא בעינים, שהוא מראה וחזיון של העינים, ז\"ש במראה אליו אתודע. ועוד, בחזיון לילה. מראה היא ביום, חזיון הוא בלילה. והכל בעינים ולא בעיני השכל של הלב. וב' העינים הן ב' מתווכות של הלב, שמתווכות בין היצה\"ר שבלב לבין האדם, ומשמשים שלו. והוא מלך ביניהם. ומשום זה חכם, הרואה בעיני הלב, הוא טוב מנביא שרואה בעינים. וכן הוא ב' אזנים הם ב' משמשי הלב."],[9,"ובג\"ד אוקמוה רבנן וכו':","ומשום זה העמידו רבנן הלב רואה והלב שומע, ולא עוד אלא שאמרו בלב, הלב מבין, הלב יודע. ובלב כל חכם לב נתתי חכמה. הרי חכמה ותבונה ודעת כלב, שבהם נעשו שמים וארץ ותחומות, ובהם נעשה המשכן. ז\"ש, ואמלא אותו רוח אלקים בחכמה ובתבונה ובדעת. מה שאין כל כך בעינים."]],[[0,"","וּמִי שֶׁהוּא בָּקִ\"י בַּהֲלָכָה שֶׁלּוֹ, שֶׁהִיא הַשְּׁכִינָה - הַקָּדוֹשׁ בָּרוּךְ הוּא עִמּוֹ, שֶׁבִּשְׁבִילָהּ לֹא יָזוּז מִמֶּנּוּ לְעוֹלָם. שֶׁיֵּשׁ הֲלָכָה שֶׁהִיא נַעֲרָה שֶׁלָּהּ מִצַּד שֶׁל נַעַר, וּבִגְלָלָהּ נֶאֱמַר הֲלָכָה כִּפְלוֹנִי. אֲבָל הַהֲלָכָה שֶׁלְּךְ, רוֹעֶה הַנֶּאֱמָן, הִיא שֶׁנֶּאֱמַר בָּהּ הֲלָכָה לְמֹשֶׁה מִסִּינַי. מִפִּי הַגְּבוּרָה נָתַן לְךְ הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת בִּתּוֹ."],[1,"","וְלָכֵן עַל הֲלָכוֹת אֲחֵרוֹת נֶאֱמַר, (משלי לא) רַבּוֹת בָּנוֹת עָשׂוּ חָיִל. עַל הֲלָכָה שֶׁלְּךְ נֶאֱמַר, וְאַתְּ עָלִית עַל כֻּלָּנָה. שֶׁהִתְגַּבַּרְתָּ עַל כֻּלָּם בִּגְבוּרָה. (שופטים ו) ה' עִמְּךְ גִּבּוֹר הֶחָיִל. נִתְקַן (נתחזק) בְּךְ וְהִשְׁלִים בִּנְיַן הַמֶּלֶךְ, וְהוּא בּוֹנֶה בִּנְיָנוֹ עַל פִּיךְ וְעַל יָדְךְ. אַשְׁרֶיךְ!"],[2,"","פָּתַח הָרוֹעֶה הַנֶּאֱמָן וְאָמַר, (בראשית מח) הַמַּלְאָךְ הַגֹּאֵל אֹתִי מִכָּל רָע, שֶׁהִיא הַשְּׁכִינָה שֶׁנֶּאֱמַר בָּהּ (שמות יד) וַיִּסַּע מַלְאַךְ הָאֱלֹהִים. יְבָרֵךְ אֶתְכֶם בָּעוֹלָם הַבָּא, וְיִדְגּוּ לָרֹב בְּקֶרֶב הָאָרֶץ בָּעוֹלָם הַזֶּה. שֶׁתִּהְיֶה שְׁלִיטַתְכֶם בִּשְׁנֵי עוֹלָמוֹת שֶׁאַתֶּם חַיִּים. שֶׁמִּי שֶׁהוּא מֵהָעוֹלָם הַזֶּה נִקְרָא חַי, כַּכָּתוּב (משלי ג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. חַיִּים שָׁם - חַיִּים כָּאן."],[3,"","מַה שֶּׁאֵינוֹ כָּךְ, מִי שֶׁהוּא מְלֻבָּשׁ בַּקְּלִפּוֹת הַלָּלוּ, שֶׁל עוֹר וּבָשָׂר וַעֲצָמוֹת וְגִידִים שֶׁל הַגּוּף הַשָּׁפָל, שֶׁהָרוּחַ מֵתָה שָׁם. מָה הַמֵּת לֹא רוֹאֶה וְלֹא שׁוֹמֵעַ וְלֹא מְדַבֵּר וְאֵין לוֹ תְּנוּעָה בְּכָל אֵיבָרָיו, כָּךְ הָרוּחַ לֹא רוֹאָה לְמַעְלָה מִמֶּנָּה, שֶׁנֶּאֱמַר עֲלֵיהֶם בַּתּוֹרָה, דַּע מַה לְמַעְלָה מִמְּךְ - עַיִן רוֹאָה וְאֹזֶן שׁוֹמַעַת, וְכָל מַעֲשֶׂיךְ בְּסֵפֶר נִכְתָּבִים."],[4,"","שֶׁכַּמָּה מַלְאָכִים הוֹלְכִים עִמּוֹ, שֶׁנֶּאֱמַר בָּהֶם (תהלים צא) כִּי מַלְאָכָיו יְצַוֶּה לָּךְ. וְאֵין לוֹ רְשׁוּת בַּגּוּף הַזֶּה לְהִסְתַּכֵּל בָּהֶם וְלִשְׁמֹעַ בְּקוֹלָם, שֶׁהֵם חַיּוֹת שֶׁל אֵשׁ, מְדַבְּרוֹת וּמְקַדְּשׁוֹת וּמְבָרְכוֹת וּמְיַחֲדוֹת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא עִם יִשְׂרָאֵל כְּאֶחָד, כָּל שֶׁכֵּן אֶת הַשְּׁכִינָה שֶׁהִיא עֲלֵיהֶם, כָּל שֶׁכֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא מֵעַל לִשְׁכִינָתוֹ, שֶׁבָּהּ הוּא מְקַבֵּל אֶת תְּפִלּוֹת יִשְׂרָאֵל."],[5,"","וּמִשּׁוּם הַחֲטָאִים הָיוּ מִתְלַבְּשִׁים בַּקְּלִפּוֹת הַלָּלוּ, כְּמוֹ שֶׁאָדָם שֶׁחֲטָאֵי אֲבוֹתֵיהֶם בִּידֵיהֶם. וְזֶהוּ שֶׁבֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, כְּשֶׁאוֹחֲזִים מַעֲשֵׂה אֲבוֹתֵיהֶם בִּידֵיהֶם. וּמִשּׁוּם הַקְּלִפּוֹת הַלָּלוּ שֶׁל הַחֲטָאִים, אָמַר הַכָּתוּב (ישעיה נט) כִּי אִם עֲונֹתֵיכֶם הָיוּ מַבְדִּלִים בֵּינֵכֶם לְבֵין אֱלֹהֵיכֶם. וּבִשְׁבִיל הַקְּלִפּוֹת הַלָּלוּ הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְכַּסֶּה בְּכַמָּה כְנָפַיִם, שֶׁבָּהֶם נֶאֱמַר (שםו) בִּשְׁתַּיִם יְכַסֶּה פָנָיו וּבִשְׁתַּיִם יְכַסֶּה רַגְלָיו וְגוֹ'."],[6,"","לֶעָתִיד לָבא, (שם ל) וְלֹא יִכָּנֵף עוֹד מוֹרֶיךְ וְהָיוּ עֵינֶיךְ רֹאוֹת אֶת מוֹרֶיךְ. שֶׁאַתֶּם בָּעוֹלָם הַזֶּה, שֶׁאֵין לָכֶם קְלִפּוֹת וְעוֹרוֹת, יֵשׁ לָכֶם רְשׁוּת לְהִסְתַּכֵּל בִּבְנֵי הָעוֹלָם, וְלִבְנֵי הָעוֹלָם (אין) יֵשׁ רְשׁוּת לְהִסְתַּכֵּל בָּכֶם, וְלָכֵן עֲלֵיכֶם נֶאֱמַר שֶׁאַתֶּם חַיִּים, וְעוֹלַמְכֶם הוּא עוֹלַם הַחַיִּים. אֲבָל הָעוֹלָם הַשָּׁפָל הוּא עוֹלַם הַמֵּתִים, שֶׁכָּל אֱלָהוּת שֶׁל אֻמּוֹת הָעוֹלָם מִבִּלְעֲדֵי ה', כֻּלָּם מֵתִים."],[7,"","אָמַר לוֹ רַבִּי שִׁמְעוֹן, (המנורה הקדושה) (רועה הגאמן), עִם כָּל זֶה שֶׁאַתָּה לֹא יָכוֹל לְהִסְתַּכֵּל בִּבְנֵי הָעוֹלָם הַבָּא בָּעֵינַיִם וְלֹא בְּמַלְאָכִים, כָּל שֶׁכֵּן בַּקָּדוֹשׁ- בָּרוּךְ-הוּא וּשְׁכִינָתוֹ, אֲבָל בְּעֵין הַשֵּׂכֶל שֶׁל לִבְּךְ אַתָּה רוֹאֶה אֶת כָּל בְּנֵי הָעוֹלָם הַבָּא, וּבַמַּלְאָכִים וּבַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ שֶׁמַּקִּיפִים אוֹתְךְ. וּמִשּׁוּם זֶה אָמַר שְׁלֹמֹה, שֶׁכָּתוּב בּוֹ (מלכים א ה) וַיֶּחְכַּם מִכָּל הָאָדָם, (קהלת א) וְלִבִּי רָאָה הַרְבֵּה חָכְמָה וָדָעַת."],[8,"","אֲבָל בִּנְבוּאָה אֵין רְשׁוּת לְהִסְתַּכֵּל בּוֹ (כל שכן) נָבִיא בְּעֵין הַשֵּׂכֶל, אֶלָּא בָּעֵינַיִם, שֶׁהִיא מַרְאֶה וְחֶזְיוֹן הָעֵינַיִם. זֶהוּ שֶׁכָּתוּב בַּמַּרְאָה אֵלָיו אֶתְוַדָּע. וְעוֹד בְּחֶזְיוֹן לַיְלָה - מַרְאֶה בַּיּוֹם, חִזָּיוֹן בַּלַּיְלָה. וְהַכֹּל בָּעֵינַיִם, וְלֹא בְּעֵין הַשֵּׂכֶל שֶׁל הַלֵּב. וְהָעֵינַיִם הֵן שְׁנֵי סַרְסוּרֵי הַלֵּב, וּמִשַּׁמָּשִׁים שֶׁלּוֹ, וְהוּא מֶלֶךְ בֵּינֵיהֶם (אליהם), וְלָכֵן חָכָם עָדִיף מִנָּבִיא. וְכָךְ הֵם שְׁתֵּי הָאָזְנַיִם, שְׁנֵי שַׁמָּשֵׁי הַלֵּב."],[9,"","וּמִשּׁוּם זֶה פֵּרְשׁוּהָ רַבּוֹתֵינוּ, הַלֵּב רוֹאֶה וְהַלֵּב שׁוֹמֵעַ. וְלֹא עוֹד, אֶלָּא שֶׁנֶּאֱמַר בַּלֵּב, הַלֵּב מֵבִין, הַלֵּב יוֹדֵעַ. (שמות לא) וּבְלֵב כָּל חֲכַם לֵב נָתַתִּי חָכְמָה. הֲרֵי חָכְמָה וּתְבוּנָה וָדַעַת בַּלֵּב, שֶׁבָּהֶם נַעֲשׂוּ שָׁמַיִם וָאָרֶץ וּתְהוֹמוֹת, וּבָהֶם נַעֲשָׂה הַמִּשְׁכָּן. זֶהוּ שֶׁכָּתוּב (שם) וָאֲמַלֵּא אֹתוֹ רוּחַ אֱלֹהִים בְּחָכְמָה וּבִתְבוּנָה וּבְדַעַת. מַה שֶּׁאֵין כָּל זֶה בָּעֵינַיִם."]]],[["וְרַעְיָא מְהֵימָנָא, מַאן דְּכוּלֵי הַאי בְּלִבֵּיהּ, יַתִּיר חֲזִי מִן נָבִיא, כָּל שֶׁכֵּן מַחֲשַׁבְתָּא דִּילָךְ. דְּלֵית לָהּ סוֹף, וּבָהּ תִּסְתָּכַּל, בְּהַהוּא, דְּלֵית בֵּיהּ סוֹף, מַה דְּלָא הֲוָה לָךְ רְשׁוּ בְּקַדְמִיתָא לְאִסְתַּכְּלָא בְּעַיְינִין. הֲדָא הוּא דִכְתִיב, (שמות ל״ג:כ״ג) וְרָאִיתָ אֶת אֲחוֹרָי וּפָנַי לא יֵרָאוּ.","אִלֵּין טִפְּשֵׁי דְּלִבָּא, אִינּוּן מֵתִין, וְסוּמִין בְּאִלֵּין קְלִיפִין. אֲבָל לְגַבָּךְ, לָאו אִינּוּן חֲשִׁיבִין כְּלוּם, וְלָא מַפְסִיקִין בֵּינָךְ לְבֵין קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, וְכָל בְּנֵי עָלְמָא דְּאָתֵי, וּמַלְאָכִין, דְּהָכִי יֵיעוּל לְגַבָּךְ בְּאִינּוּן חַלּוֹנִין, דְּעַיְינִין, וְאוּדְנִין, וְנוּקְבֵי חוֹטָמָא, וּפוּמָא. כְּמַלְכָּא דְּיֵיעוּל בְּאִתְכַּסְיָיא לְחַדְרֵי חֲדָרִים, לְמַלְּלָא עִם בְּרֵיהּ. וּבְגִין דָּא, מְצָלִין יִשְׂרָאֵל בֵּיהּ בִּצְלוֹתָא דִּלְהוֹן, (משלי כ׳:כ״ז) אַתָּה חוֹפֵשׂ כָּל חַדְרֵי בֶּטֶן רוֹאֶה כְּלָיוֹת וָלֵב וְאֵין כָּל דָּבָר נֶעְלָם מִמְּךָּ.","וְהַיְינוּ דְּאָמַר שְׁלמֹה, (שיר השירים ב׳:ט׳) מַשְׁגִּיחַ מִן הַחַלּוֹנוֹת וְגוֹ'. וְאִלֵּין אִינּוּן חַלּוֹנוֹת, דְּעַיְינִין וְאוּדְנִין וְנוּקְבֵי חוֹטָמָא וּפוּמָא בְּאִלֵּין שִׁבְעָה נוּקְבִין, נִשְׁמְתָא סְלִיקַת, בְּשִׁבְעָה מִינֵי בּוּסְמִין, וְהָכִי צְלוֹתָא סְלִיקַת בְּאִלֵּין ז' בּוּסְמִין, דְּאִינּוּן (שיר השירים ד׳:י״ד) נַרְדְּ וְכַרְכֹּם קָנֶה וְקִנָּמוֹן עִם כָּל עֲצֵי לְבוֹנָה מֹר וַאֲהָלוֹת עִם כָּל רָאשֵׁי בְּשָׂמִים. בְּהַהוּא זִמְנָא דִּצְלוֹתָא הָכִי סְלִיקַת, מְקֻטֶּרֶת מֹר וְכוּ'. הַקָדוֹשׁ בָּרוּךְ הוּא שָׁאִיל עָלָהּ, (שיר השירים ג׳:ו׳) מִי זֹאת עוֹלָה מִן הַמִּדְבָּר מְקֻטֶּרֶת מֹר וּלְבֹנָה וְגוֹ'. מִי זֹאת וַדַּאי, מִסִּטְרָא דְּמִ\"י אִיהוּ וַדַּאי בִּינָה, כְּלִילָא מִשִּׁבְעָה מִינִי בּוּסְמִין.","וְדָא קְרִיאַת שְׁמַע, כְּלִילָא מֵחַמְשִׁין תַּרְעִין, דְּאִינּוּן כ\"ה כ\"ה. כְּלִילָא מִשִּׁבְעָה בִּרְכָּאן, בַּשַּׁחַר שְׁתַּיִם לְפָנֶיהָ, וְאַחַת לְאַחֲרֶיהָ, וּבְעֶרֶב שְׁתַּיִם לְפָנֶיהָ, וּשְׁתַּיִם לְאַחֲרֶיהָ. וְאִינּוּן, (דברי הימים א כ״ט:י״א) הַגְּדוֹלָה וְהַגְּבוּרָה וְהַתִּפְאֶרֶת וְהַנֵּצַח וְהַהוֹד, עַד לְךָ יְיָ' הַמַּמְלָכָה, דְּאִיהִי מַלְכוּת. דְּאִיהִי כְּלִילָא מִתְּלַת בּוּסְמִין. מְקֻטֶּרֶת מֹר, דָּא כֶּתֶר. וּלְבוֹנָה, דָּא חָכְמָה. מִכֹּל אַבְקַת רוֹכֵל, דָּא בִּינָה. קוּם אַשְׁלִים פִּקּוּדִין דְּמָרָךְ.","(שמות כ״ג:ב׳) לֹא תִהְיֶה אַחֲרֵי רַבִּים לְרָעוֹת וְגוֹ', אַחֲרֵי רַבִּים לְהַטּוֹת. אַחֲרֵי רַבִּים לְהַטּוֹת, לֵית רַבִּים פָּחוּת מִג' וְאִי לֵית בֵּית דִּין בְּג', לֵית לְהַטּוֹת בָּתַר דִּינֵיהּ. בֵּית דִּין: שְׁכִינְתָּא. בְּג': תְּלַת חִיוָן דְּמֶרְכַּבְתָּא דִּילָהּ, וְאִיהִי דִּין תּוֹרָה, דִּין אֱמֶת, עַמּוּדָא דְּאֶמְצָעִיתָא. וְכָל דַּיָּין דְּלָא דָּן דִּין אֱמֶת לַאֲמִתּוֹ, דָּא אִיהוּ כְּאִילּוּ אַשְׁלִיט סָמָאֵ\"ל בְּעָלְמָא. (דניאל ח׳:י״ב) וְתַשְׁלֵךְ אֱמֶת אַרְצָה, וְאַפִּיל שְׁכִינְתָּא עִמֵּיהּ, וְיָקִים גֵּיהִנָּם, בַּת זוּגֵיהּ דְּסָמָאֵ\"ל, עִם סָמָאֵ\"ל. בַּאֲתָר דְּדִין אֱמֶת, יוֹקִים שְׂפַת שָׁקֶר. דִּין אֱמֶת, עַמּוּדָא דְּאֶמְצָעִיתָא. שְׂפַת שָׁקֶר גֵּיהִנָּם וְסָמָאֵ\"ל.","וּבְגִין דָּא, כַּד דַּיָּין דָּן דִּין, גֵּיהִנָּם פְּתוּחָה לְפָנָיו מִשְֹּׁמֹאלוֹ, בַּת זוּגֵיהּ דְּסָמָאֵ\"ל. וְחֶרֶב עַל צַוָּארוֹ, מַלְאַךְ הַמָּוֶת. סָמָאֵ\"ל מֵאֲחוֹרוֹי מֵעַל צַוָּארֵיהּ. וְגַן עֵדֶן פָּתוּחַ לִימִינֵיהּ, וְעֵץ הַחַיִּים פָּתוּחַ לְקַמֵּיהּ, עַל רֵישֵׁיהּ.","אִי דָּן דִּינָא דְּשִׁקְרָא, שָׁלִיט עָלֵיהּ מַלְאַךְ הַמָּוֶת, וְשָׁחִיט לֵיהּ, וּלְבָתַר אוֹקִיד לֵיהּ בַּגִּיהִנָּם. וְאִי דָּן דִּין אֱמֶת, קוּדְשָׁא בְּרִיךְ הוּא יֵיעוּל לֵיהּ לְגַן עֵדֶן, וְאַטְעִים לֵיהּ מֵאִילָנָא דְּחַיֵּי, דִּכְתִּיב עָלֵיהּ, (בראשית ג׳:כ״ב) וְלָקַח גַּם מֵעֵץ הַחַיִּים וְאָכַל וָחַי לְעוֹלָם. דְּאִתְבְּרֵי בְּאוֹרַיְיתָא, דְּאִתְּמַר בָּהּ, עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. עֵץ חַיִּים, תִּפְאֶרֶת. (ויקרא נ\"ח ע\"א, תיקונים ס\"ו ע\"ב) חַיִּים דִּילֵיהּ חָכְמָה וּבִינָה. חַיֵּי הַמֶּלֶךְ וַדַּאי.","וּלְעוֹלָם, דִּינָא דְּמַלְכוּתָא, דִּינָא. וְדִינָא בַּלֵּב, וְאִתְּמַר בֵּיהּ, הַלֵּב רוֹאֶה. וּבְגִין דָּא, אֵין לוֹ לַדַּיָּין אֶלָּא מַה שֶׁעֵינָיו רוֹאוֹת. וְהָכָא לֵית דַּיָּין, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא. מַה שֶׁעֵינָיו רוֹאוֹת, (דברי הימים ב ט״ז:ט׳) כִּי יְיָ' עֵינָיו מְשׁוֹטְטוֹת. (איוב לה) עֵינָיו עַל דַּרְכֵי אִישׁ.","וּבְהוֹן, (שיר השירים ב׳:ט׳) מַשְׁגִּיחַ מִן הַחַלּוֹנוֹת. בְּז' נוּקְבִין דְּבַר נָשׁ, בִּתְרֵין עַיְינִין, וּתְרֵין אוּדְנִין, וּתְרֵין נוּקְבִין דְּחוֹטָמָא, וּפוּמָא. הָא ז' דְּאִמָא עִלָּאָה. וְהָכִי בְּעוֹבָדוֹי אִסְתָּכַּל בְּשֶׁבַע, מִסִּטְרָא דִּשְׁכִינְתָּא תַּתָּאָה, בְּב' יְדִין וְצַוָּאר תְּלַת, וְגוּף וּבְרִית תְּרֵין, הָא חֲמֵשׁ. תְּרֵין רַגְלִין, הָא שֶׁבַע. יָ\"הּ, יוּ\"ד הֵ\"א, בְּשֶׁבַע אַתְוָון דִּילֵיהּ, אִסְתָּכַּל בְּשֶׁבַע נוּקְבִין דְּרֵישָׁא, נְקָבִים: עַל שֵׁם נְקֵבָה, דִּנְקָבֶיהָ פְּתוּחוֹת לְקַבֵּל. ו\"ה, וא\"ו ה\"א, בְּשֶׁבַע אַתְוָון דִּילֵיהּ, אִסְתָּכַּל בְּשִׁבְעָה אֵבָרִין דִּלְתַתָּא, דְּאִינּוּן תִּקּוּנָא דְּגוּפָא, דִּבְּהוֹן עֲשִׂיַּית הַמִּצְוֹת."],[[0,"ורעיא מהימנא מאן וכו':","ורועה הנאמן, מי שכל כך בלבו, רואה יותר מנביא, כל שכן המחשבה שלך, שאין לה סוף, ובה תסתכל, בההוא שאין בו סוף, מה שלא היה לך רשות בתחילה להסתכל בעינים. ז\"ש וראית את אחורי ופני לא יראו."],[1,"אלין טפשי דלבא וכו':","אלו אוילי הלב, הם מתים, וסומים, באלו הקליפות של הגוף, אבל אצלך אין אלו חשובים כלום. ואינם מפסיקים בינך ובין הקב\"ה ושכינתו, וכל בני עולם הבא והמלאכים, כי כן יבא אליך באלו החלונות, של העינים, ואזנים, ונקבי האף, והפה. כמלך הבא בסתר לחדרי חדרים לדבר עם בנו. ומשום זה מתפללים ישראל בתפלתם, אתה חופש כל חדרי בטן רואה כליות ולב ואין כל דבר נעלם ממך."],[2,"והיינו דאמר שלמה וכו':","והיינו שאמר שלמה, משגיח מן החלונות. ואלו הם החלונות, של העינים והאזנים ונקבי האף והפה. בז' נקבים אלו עולה הנשמה בז' מיני בשמים וכן התפלה עולה בז' מיני בשמים אלו, שהם, נרד וכרכם קנה וקנמון עם כל עצי לבונה מור ואהלות עם כל ראשי בשמים. בזמן ההוא של התפלה, עולית כך, מקוטרת מר וגו'. הקב\"ה שואל עליה, מי זאת עולה מן המדבר מקטרת מר ולבונה וגו'. \u0003מי זאת,\u0004 ודאי מצד \u0003מ\"י\u0004 שהוא בינה, ודאי כלולה מז' מיני בשמים. שהם חג\"ת נהי\"מ שלה המאירים בסוד הריח שהוא הארת החכמה."],[3,"ודא ק\"ש כלילא וכו':","וקריאת שמע זו כלולה מחמשים שערים, שבבינה, שהם כ\"ה כ\"ה אותיות, כ\"ה שבק\"ש של שחרית וכ\"ה בק\"ש של ערבית, כלולים מז' ברכות, בשחר, שתים לפניה ואחת לאחריה, ובערב, שתים לפניה ושתים לאחריה. והם, ז' ספירות הגדולה והגבורה והתפארת והנצח וההוד, כי כל בשמים וארץ, שהוא יסוד, עד לך ה' הממלכה, שהיא מלכות. שהיא כלולה מג' בשמים, \u0003מקטרת מר,\u0004 זהו כתר. \u0003ולבונה,\u0004 זהו חכמה. \u0003מכל אבקת רוכל,\u0004 זהו בינה. קום השלם המצות של אדונך."],[4,"לא תהיה אחרי רבים לרעות וגו':","אחרי רבים להטות. ומפרש. \u0003אחר רבים להטות,\u0004 אין רבים פחות מג' ואם אין בית דין של ג' אין להטות אחרי דינו. בין דין, הוא השכינה. בג', הם ג' חיות של המרכבה שלה. שהם חג\"ת. והיא השכינה, נקראת דין תורה, דין של אמת, שעמוד האמצעי, שהוא ז\"א, נקרא אמת, והשכינה היא הדין שלו. וכל דיין שאינו דן דין אמת לאמתו, זה הוא כאלו השליט את סמאל בעולם. ותשלך אמת ארצה, שהוא ז\"א, ומפיל השכינה עמו, ומקים את הגיהנם, שהוא בת זוגו של סמאל, עם סמאל. במקום של דין אמת, הוא מקים שפת שקר. דין אמת, הוא עמוד האמצעי, שפת שקר, הוא גיהנם וסמאל."],[5,"ובג\"ד כד דיין וכו':","ומשום זה, כשהדיין דן דין, הגיהנם פתוח לפניו משמאלו, שהוא בת זוגו של סמאל. וחרב על צוארו. שהוא מלאך המות. סמאל מאחורו של הצואר, והגן עדן פתוח לימינו, ועץ החיים פתוח לפניו על ראשו."],[6,"אי דן דינא וכו':","אם דן דין שקר, שולט עליו מלאך המות ושוחט אותו, ואח\"כ שורף אותו בגיהנם, ואם דן דין אמת, הקב\"ה מביאו לגן עדן, ומטעימו מעץ החיים, שכתב עליו, ולקח גם מעץ החיים ואכל וחי לעולם. לעולם שנברא בתורה, שנאמר בה, עץ חיים היא למחזיקים בה. עץ חיים, הוא תפארת. חיים שלו, הוא חכמה ובינה. חיי המלך ודאי."],[7,"ולעולם דינא דמלכותא וכו':","ולעולם, דין המלכות הוא דין. והדין הוא בלב, ונאמר בו הלב רואה. ומשום זה אין לו לדיין אלא מה שעיניו רואות. וכאן אין \u0003דיין\u0004 אלא הקב\"ה. מה \u0003שעיניו רואות,\u0004 היינו כי ה' עיניו משוטטות. עיניו על דרכי איש."],[8,"ובהון, משגיח מן החלונות:","היינו בז' נקבי האדם, בשתי עינים בשתי אזנים, בשני נקבי האף והפה. הרי ז' ספירות של אמא עלאה. וכך מסתכל במעשיו בז', מצד השכינה, התחתונה, בשתי ידים והצואר, שהם ג'. ועם גוף וברית, שהם ת\"ת ויסוד, הם ה', ועם שתי רגלים, הרי שבע. שהם ז\"ס של השכינה התחתונה. ב' אותיות השם \u0003י\"ה,\u0004 שהוא בג\"ר, עם המילוי שלהן, שהן \u0003יו\"ד ה\"א,\u0004 הן שבע אותיות בשבע אותיות אלו שלו, מסתכל בשבעה נקבים של הראש. ונקראים נקבים על שם נקבה, שהוא אמא עליונה, שנקביה פתוחות לקבל. ב' אותיות \u0003ו\"ה,\u0004 שהן בגוף, דהיינו שכינה התחתונה, עם אותיות המילוי שלהן, שהן \u0003וא\"ו ה\"א,\u0004 הן ז' אותיות, בז' אותיות אלו שלו, מסתכל בז' אברים שלמטה, שהם הידים והצואר וכו', שהם תקון הגוף, שבהם עשיית המצות."]],[[0,"","וְרוֹעָה הַנֶּאֱמָן, מִי שֶׁכָּל זֶה בְּלִבּוֹ רוֹאֶה יוֹתֵר מִנָּבִיא, כָּל שֶׁכֵּן מַחֲשַׁבְתְּךְ שֶׁאֵין לָהּ סוֹף, וּבָהּ תִּסְתַּכֵּל בְּאוֹתוֹ שֶׁאֵין לוֹ סוֹף, מַה שֶּׁלֹּא הָיְתָה לְךְ רְשׁוּת בָּרִאשׁוֹנָה לְהִסְתַּכֵּל בָּעֵינַיִם. זֶהוּ שֶׁכָּתוּב (שם לג) וְרָאִיתָ אֶת אֲחֹרָי וּפָנַי לֹא יֵרָאוּ."],[1,"","טִפְּשֵׁי הַלֵּב הַלָּלוּ הֵם מֵתִים, וְעִוְרִים בַּקְּלִפּוֹת הַלָּלוּ. אֲבָל אֵלֶיךְ אֵינָם חֲשׁוּבִים לִכְלוּם, וְאֵינָם מַפְסִיקִים בֵּינְךְ לְבֵין הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ, וְכָל בְּנֵי הָעוֹלָם הַבָּא וְהַמַּלְאָכִים, שֶׁכָּךְ יִכָּנֵס אֵלֶיךְ בְּאוֹתָם חַלּוֹנוֹת שֶׁל הָעֵינַיִם וְהָאָזְנַיִם וְנִקְבֵי הַחֹטֶם וְהַפֶּה, כְּמוֹ מֶלֶךְ שֶׁנִּכְנָס בְּכִסּוּי לְחַדְרֵי חֲדָרִים לְדַבֵּר עִם בְּנוֹ. וּמִשּׁוּם זֶה מִתְפַּלְלִים יִשְׂרָאֵל בּוֹ בִּתְפִלָּתָם: אַתָּה חוֹפֵשׂ כָּל חַדְרֵי בָטֶן רוֹאֶה כְלָיוֹת וָלֵב וְאֵין כָּל דָּבָר נֶעְלָם מִמֶּךָּ."],[2,"","וְהַיְנוּ מַה שֶּׁאָמַר שְׁלֹמֹה, (שיר ב) מַשְׁגִּיחַ מִן הַחַלֹּנוֹת וְגוֹ'. וְאֵלֶּה הֵם הַחַלּוֹנוֹת שֶׁל עֵינַיִם וְאָזְנַיִם וְנִקְבֵי הַחֹטֶם וְהַפֶּה. בְּשִׁבְעַת הַנְּקָבִים הַלָּלוּ עוֹלָה הַנְּשָׁמָה בְּשִׁבְעָה מִינֵי בְשָׂמִים, וְכָךְ הַתְּפִלָּה עוֹלָה בְּשִׁבְעָה הַבְּשָׂמִים הַלָּלוּ, שֶׁהֵם: (שם ד) נֵרְדְּ וְכַרְכֹּם קָנֶה וְקִנָּמוֹן עִם כָּל עֲצֵי לְבוֹנָה מֹר וַאֲהָלוֹת עִם כָּל רָאשֵׁי בְשָׂמִים. בְּאוֹתוֹ זְמַן שֶׁכָּךְ הַתְּפִלָּה עוֹלָה, מְקֻטֶּרֶת מֹר וְכוּ'. הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹאֵל עָלֶיהָ, (שםג) מִי זאת עֹלָה מִן הַמִּדְבָּר וְגוֹ', מְקֻטֶּרֶת מֹר וּלְבֹנָה וְגוֹ'. מִי זֹאת וַדַּאי, מִצַּד שֶׁל מִ\"י הִיא וַדַּאי בִּינָה, כְּלוּלָה מִשִּׁבְעָה מִינֵי בְשָׂמִים."],[3,"","וְזוֹ קְרִיאַת שְׁמַע, כְּלוּלָה מֵחֲמִשִּׁים שְׁעָרִים, שֶׁהֵם כ\"ה כ\"ה, כְּלוּלָה מִשֶּׁבַע בְּרָכוֹת, בַּשַּׁחַר - שְׁתַּיִם לְפָנֶיהָ וְאַחַת לְאַחֲרֶיהָ, וּבָעֶרֶב - שְׁתַּיִם לְפָנֶיהָ וּשְׁתַּיִם לְאַחֲרֶיהָ, וְהֵם: הַגְּדֻלָּה וְהַגְּבוּרָה וְהַתִּפְאֶרֶת וְהַנֵּצַח וְהַהוֹד, עַד לְךְ ה' הַמַּמְלָכָה, שֶׁהִיא מַלְכוּת, שֶׁהִיא כְּלוּלָה מִשְּׁלֹשָׁה בְשָׂמִים: מְקֻטֶּרֶת מֹר - זֶה כֶּתֶר, וּלְבוֹנָה - זוֹ חָכְמָה, מִכֹּל אַבְקַת רוֹכֵל - זוֹ בִּינָה. קוּם וְהַשְׁלֵם אֶת מִצְווֹת רִבּוֹנְךְ."],[4,"","לֹא תִהְיֶה אַחֲרֵי רַבִּים לְרָעֹת וְגוֹ', אַחֲרֵי רַבִּים לְהַטֹּת. אַחֲרֵי רַבִּים לְהַטֹּת - אֵין רַבִּים פָּחוֹת מִשְּׁלֹשָׁה, וְאִם אֵין בֵּית דִּין בִּשְׁלֹשָׁה, אֵין לְהַטּוֹת אַחַר דִּינוֹ. בֵּית דִּין - שְׁכִינָה. בִּשְׁלֹשָׁה - שְׁלֹשׁ חַיּוֹת הַמֶּרְכָּבָה שֶׁלָּהּ, וְהִיא דִּין תּוֹרָה, דִּין אֱמֶת, הָעַמּוּד הָאֶמְצָעִי. וְכָל דַּיָּן שֶׁלֹּא דָן דִּין אֱמֶת לַאֲמִתּוֹ, זֶהוּ כְּאִלּוּ הִשְׁלִיט אֶת סמא\"ל בָּעוֹלָם. (דניאל ח) וְתַשְׁלֵךְ אֱמֶת אַרְצָה, וְהִפִּיל עִמָּהּ אֶת הַשְּׁכִינָה, וְיָקִים אֶת גֵּיהִנֹּם, בַּת הַזּוּג שֶׁל סמא\"ל עִם סמא\"ל. בַּמָּקוֹם שֶׁל דִּין הָאֱמֶת יָקִים שְׂפַת שֶׁקֶר. דִּין אֱמֶת - עַמּוּד הָאֶמְצָעִי. שְׂפַת שֶׁקֶר - גֵּיהִנֹּם וְסמא\"ל."],[5,"","וּמִשּׁוּם כָּךְ, כְּשֶׁדַּיָּן דָּן דִּין, גֵּיהִנֹּם פְּתוּחָה לְפָנָיו מִשְּׂמֹאלוֹ, בַּת זוּגוֹ שֶׁל סמא\"ל. וְחֶרֶב עַל צַוָּארוֹ, מַלְאַךְ הַמָּוֶת. סמא\"ל מֵאֲחוֹרָיו מֵעַל צַוָּארוֹ, וְגַן עֵדֶן פָּתוּחַ לִימִינוֹ, וְעֵץ הַחַיִּים פָּתוּחַ לְפָנָיו עַל רֹאשׁוֹ."],[6,"","אִם דָּן דִּין שֶׁקֶר, שׁוֹלֵט עָלָיו מַלְאַךְ הַמָּוֶת וְשׁוֹחֵט אוֹתוֹ, וְאַחַר כָּךְ שׂוֹרֵף אוֹתוֹ בַּגֵּיהִנֹּם. וְאִם דָּן דִּין אֱמֶת, הַקָּדוֹשׁ בָּרוּךְ הוּא יַכְנִיסוֹ לְגַן עֵדֶן וּמַטְעִים אוֹתוֹ מֵעֵץ הַחַיִּים, שֶׁכָּתוּב עָלָיו (בראשית ג) וְלָקַח גַּם מֵעֵץ הַחַיִּים וְאָכַל וָחַי לְעֹלָם. שֶׁנִּבְרָא בַּתּוֹרָה, שֶׁבָּהּ נֶאֱמַר (משלי ג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. עֵץ חַיִּים - תִּפְאֶרֶת. חַיִּים שֶׁלּוֹ חָכְמָה וּבִינָה. חַיֵּי הַמֶּלֶךְ וַדַּאי."],[7,"","וּלְעוֹלָם דִּין הַמַּלְכוּת הוּא דִּין, וְהַדִּין בַּלֵּב, וְנֶאֱמַר בּוֹ הַלֵּב רוֹאֶה. וְלָכֵן אֵין לוֹ לַדַּיָּן אֶלָּא מַה שֶּׁעֵינָיו רוֹאוֹת. וְכָאן אֵין דַּיָּן אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא. מַה שֶּׁעֵינָיו רוֹאוֹת, כִּי ה' עֵינָיו מְשׁוֹטְטוֹת. עֵינָיו עַל דַּרְכֵי אִישׁ."],[8,"","וּבָהֶן מַשְׁגִּיחַ מִן הַחַלּוֹנוֹת בְּשִׁבְעַת נִקְבֵי הָאָדָם: בִּשְׁתֵּי עֵינַיִם, וּשְׁתֵּי אָזְנַיִם, וּשְׁנֵי נִקְבֵי הַחֹטֶם, וְהַפֶּה. הֲרֵי שֶׁבַע שֶׁל הָאֵם הָעֶלְיוֹנָה. וְכָךְ בְּמַעֲשָׂיו הִסְתַּכֵּל בְּשֶׁבַע מִצַּד הַשְּׁכִינָה הַתַּחְתּוֹנָה, בִּשְׁתֵּי יָדַיִם וְצַוָּאר - שָׁלֹשׁ, וְגוּף וּבְרִית - שְׁתַּיִם. הֲרֵי חָמֵשׁ. שְׁתֵּי רַגְלַיִם - הֲרֵי שֶׁבַע. י\"ה, יוֹ\"ד הֵ\"א - בְּשֶׁבַע אוֹתִיּוֹתָיו מִסְתַּכֵּל בְּשִׁבְעַת נִקְבֵי הָרֹאשׁ. נְקָבִים, עַל שֵׁם נְקֵבָה, שֶׁנְּקָבֶיהָ פְּתוּחוֹת לְקַבֵּל. ו\"ה, וָא\"ו הֵ\"א - בְּשֶׁבַע אוֹתִיּוֹתָיו מִסְתַּכֵּל בְּשִׁבְעָה הָאֵיבָרִים שֶׁלְּמַטָּה, שֶׁהֵם תִּקּוּן הַגּוּף, שֶׁבָּהֶם עֲשִׂיַּת הַמִּצְווֹת."]]],[["אִשְׁתּוֹ כְּגוּפוֹ דַּמְיָא. וְעַל שֵׁם פִּקּוּדִין, אִתְקְרִיאוּ אֵבָרִים. עַל שֵׁם שְׁכִינְתָּא, גּוּפָא. דְּמִסְטְרָא אַחֲרָא לְבוּשָׁא, דְּאִינּוּן עוֹר וּבָשָׂר. הֲדָא הוּא דִכְתִיב, (איוב י׳:י״א) עוֹר וּבָשָׂר תַּלְבִּישֵׁנִי וּבַעֲצָמוֹת וְגִידִים תְּשֹׂכְכֵנִי, בַּאֲתַר דְּלֵית שְׁכִינְתָּא, הַהוּא גּוּפָא לָא אִתְקְרֵי, אֶלָּא לְבוּשָׁא דְּאָדָם. דְּאִיהוּ תּוֹרָה, (במדבר י״ט:י״ד) זֹאת הַתּוֹרָה אָדָם כִּי יָמוּת בְּאֹהֶל. (ישעיה מה) כְּתִפְאֶרֶת אָדָם לָשֶׁבֶת בָּיִת. וּבַאֲתַר דְּתַּמָּן מִצְוָה, אִתְקְרֵי גּוּפָא דְּאָדָם, כְּגוֹן גּוּפִי הֲלָכוֹת, וּפִסְקֵי דִּינִין.","קוּדְשָׁא בְּרִיךְ הוּא שׁוֹפֵט, עַמּוּדָא דְּאֶמְצָעִיתָא. מִסִּטְרָא דְּבִינָה, דְּאִיהוּ יְדוָֹ\"ד. (קי\"ח ע\"א) דַּיָּין, מִסִּטְרָא דְּמַלְכוּת. שׁוֹטֵר, הוּא שַׁלִּיט, (מסטרא דיוסף הצדיק מתמן (בראשית מ״ב:ו׳)) וְיוֹסֵף הוּא הַשַּׁלִּיט. וְכָל סְפִירָין, אִינּוּן שׁוֹפְטִים, מִסִּטְרָא דְּאִמָא עִלָּאָה, דְּתִפְאֶרֶת שׁוֹפֵט. וְאִינּוּן שׁוֹטְרִים, מִסִּטְרָא דְּמַלְכוּת. דְּצַדִּיק מִתַּמָּן שׁוֹטֵר וּמוֹשֵׁל. (ופקודא בתר דא מינוי שופטים וכו' תמצאנו בריש פרשת שופטים דף רע\"ד ע\"ב)","(שמות כ״ג:ז׳) מִדְּבַר שֶׁקֶר תִּרְחָק וְנָקִי וְצַדִיק אַל תַּהֲרוֹג וְגוֹ'. פִּקּוּדָא לְהַשְׁווֹת הַבַּעֲלֵי דִּינִין, וּלְהִתְרַחֵק מִדְּבַר שֶׁקֶר, דְּלָא יֵימְרוּן מַשּׂוֹא פָּנִים (יש בדבר). דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְּמַר בֵּיהּ, (דברים י׳:י״ז) אֲשֶׁר לֹא יִשָּׂא פָּנִים. וְלֹ\"א יִקַּ\"ח שֹׂחַ\"ד, בְּסוֹפֵי תֵּיבוֹת אֶחָד. הַאי דַּיָּין, צָרִיךְ לְמֶהוֵי כְּגַוְונָא דְּאֶחָד, דְּאִיהוּ יְדוָֹ\"ד אֶחָד, דְּלָא יִקַּח שֹׂחַד, דִּיהֵא אִיהוּ בְּדִיּוּקְנֵיהּ.","וּבְדִינָא לְהַשְׁווֹת תַּרְוַויְיהוּ כְּאֶחָד, וְלָא יַטֶּה דִּינָא לְדָא יַתִּיר מִן דָּא, אֶלָּא בְּתִקְלָא חַד, עַד דִּיקַבְּלוֹן דִּינָא. וּלְבָתַר, כָּל חַד אִתְּדָן, כְּפוּם עוֹבָדוֹי.","וְאוּקְמוּהָ מָארֵי מַתְנִיתִין, צַדִּיק יֵצֶר הַטּוֹב שׁוֹפְטוֹ. רָשָׁע, יֵצֶר הָרָע שׁוֹפְטוֹ. בֵּינוֹנִי, זֶה וְזֶה שׁוֹפְטוֹ. מַאן דְּאִיהוּ מֵאִילָנָא דְּחַיֵּי, לֵית לֵיהּ דִּינָא כְּלָל, לֵית לֵיהּ יֵצֶר הָרָע, וְדָא צַדִּיק גָּמוּר, וְדָא צַדִּיק וְטוֹב לוֹ. וְלֵית טוֹב, אֶלָּא תּוֹרָה. הֲדָא הוּא דִכְתִיב, (משלי ד׳:ב׳) כִּי לֶקַח טוֹב נָתַתִּי לָכֶם תּוֹרָתִי אַל תַּעֲזוֹבוּ. וְצַדִיק וְרָע לוֹ, מִסִּטְרָא דְּעֵץ הַדַּעַת טוֹב וָרָע. וַאֲמַאי אִתְקְרֵי צַדִּיק בָּתַר דְּרַע לוֹ, דְּאִיהוּ יֵצֶר הָרָע. אֶלָּא, בְּגִין דְּטוֹב שַׁלִּיט עָלֵיהּ, אִתְקְרֵי צַדִּיק וְרָע לוֹ. דְּהַהוּא רָע אִיהוּ תְּחוֹת רְשׁוּתֵיהּ. (ס\"א כעבדא תחות רביה)","רָשָׁע וְטוֹב לוֹ, אֲמַאי אִתְקְרֵי רָשָׁע. בְּגִין דְּאִיהוּ אִסְתַּלָּק לְמֶהוֵי רֵישָׁא יֵצֶר הָרָע דִּילֵיהּ, וְטוֹב אִיהוּ תְּחוֹת רְשׁוּתֵיהּ, כְּעַבְדָּא תְּחוֹת רַבֵּיהּ. וְאַף עַל גַּב דְּרָשָׁע אִיהוּ מַכְתִּיר אֶת הַצַּדִּיק, וְיָכִיל צַדִּיק גָּמוּר לְאַעְנָשָׁא לֵיהּ, (משלי י״ז:כ״ו) גַּם עֲנוֹשׁ לַצַּדִיק לא טוֹב, בְּגִין הַהוּא טוֹב דְּאִיהוּ תְּחוֹת רַגְלוֹי דְּרָשָׁע, לֵית לְאַעְנָשָׁא לֵיהּ, דְּאוּלַי יַחֲזוֹר בִּתְשׁוּבָה וְיִתְגַּבֵּר עַל יִצְרֵיהּ, וִיהֵא עָפָר תְּחוֹת רַגְלוֹי.","דְּמִסְטְרָא דְּרָשָׁע וְטוֹב לוֹ, (נ\"א שכינתא) שְׁכִיבַת, (רות ג׳:ז׳) וַתְּגַל מַרְגְּלוֹתָיו וַתִּשְׁכָּב. הַאי אִיהוּ (משלי ל׳:כ״ג) וְשִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ. (דבר אחר ומסטרא דצדיק גמור) שִׁפְחָה, יֵצֶר הָרָע נוּקְבָּא. יֵצֶר הָרָע, דְּכַר. בְּגִינֵיהּ אִתְּמַר, (ישעיהו מ״ב:ח׳) וּכְבוֹדִי לְאַחֵר לא אֶתֵּן. (במדבר א׳:נ״א) וְהַזָּר הַקָּרֵב יוּמָת.","וּמִסִּטְרָא דְּצַדִּיק וְרָע לוֹ, שְׁכִינְתָּא אִיהִי עֲטָּרָה עַל רֵישָׁא דְּבַר נָשׁ, וְשִׁפְחָה יֵצֶר הָרָע, אִתְכַּפְיָיא תְּחוֹת גְּבִירְתָּהּ. וּמִסִּטְרָא דְּצַדִּיק גָּמוּר, לֵית זָר, וְלֵית יֵצֶר הָרָע. וּמִסִּטְרָא דְּרָשָׁע גָּמוּר, לֵית לֵיהּ חוּלָקָא בִּשְׁכִינְתָּא, דְּלֵית חוּלָקָא לְבַּר נָשׁ בִּשְׁכִינְתָּא, אֶלָּא מִסִּטְרָא דְּטוֹב.","וְלֵית כָּל שְׁכִינְתָּא שְׁקִילִין, דְּהָא שְׁכִינְתָּא דְּאִילָנָא דְּטוֹב וָרָע, אִיהוּ כֻּרְסְיָיא, אֲבָל שְׁכִינְתָּא דְּאִילָנָא דְּחַיֵּי, עָלָהּ אִתְּמַר, (תהילים ה׳:ה׳) לֹא יְגוּרְךָ רָע. אֲבָל (ד\"א אלא) בְּגִין דְּאִתְּמַר בָּהּ, (תהילים ק״ג:י״ט) וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה, מַאן דְּפָגִים אֲתָר דִּילָהּ, אִתְחֲשִׁיב כְּאִילּוּ עָבִיד בְּמַטְרוֹנִיתָא קְלָנָא. דְּקָלָנָא דְּמַטְרוֹנִיתָא אִיהוּ, מַאן דִּמְזַלְזֵל בְּאַתְרָהָא. וּקְלָנָא דְּמַטְרוֹנִיתָא, דְּמַלְכָּא אִיהוּ.","כָּל שֶׁכֵּן מַאן דְּאַעְבַּר לָהּ מֵאַתְרָהָא, וְשַׁוֵּי שִׁפְחָה בְּאַתְרָהָא. דִּבְכָל אֲתָר דְּאִיהוּ פָּגִים, מַטְרוֹנִיתָא לָא שַׁרְיָא תַּמָּן, אֶלָּא שִׁפְחָה, דְּאִיהִי פְּגִימָא, שַׁרְיָא בַּאֲתָר פָּגִים. וּפְגִימוּ דְּבַר נָשׁ דְּחוֹבוֹי, פָּגִים בְּכָל אֵבָרִין דִּילֵיהּ, עַד דְּלָא אַשְׁכָּחַת מַטְרוֹנִיתָא אֲתָר לְשַׁרְיָא תַּמָּן. וְלֵית לֵיהּ תִּקּוּנָא עַד דְּיַחֲזִיר לָהּ עַל כָּל אֵבָרִין דִּילֵיהּ."],[[0,"אשתו כגופא דמיא וכו':","אשתו של ז\"א, שהיא השכינה, דומה לגוף, שגופו של אדם התחתון נמשך ממנה, ועל שם המצות, הוא נקרא אברים, דהיינו רמ\"ח אברים. ועל שם השכינה, הוא נקרא גוף. כי מצד האחר אין גוף, אלא לבוש, שהם עור ובשר וכו'. ז\"ס עור ובשר תלבישני ובעצמות וגידים תסוככני. שבמקום שאין השכינה שם, לא נקרא גוף ההוא של אדם התחתון אלא לבוש של האדם, שהוא ז\"א, שהוא תורה הנקראת אדם. זאת התורה \u0003אדם\u0004 כי ימות באהל. כתפארת \u0003אדם\u0004 לשבת בית. ובמקום ששם מצוה, שהיא השכינה, נקרא גופו של אדם התחתון, גופו של אדם. כמו גופי הלכות ופסקי דינים, שהם שמות השכינה."],[1,"קב\"ה שופט עמודא וכו':","הקב\"ה שופט, היינו עמוד האמצעי, שהוא ז\"א, שמצד הבינה, דהיינו המוחין דג\"ר הנמשכים מבינה, שהוא הוי\"ה, נקרא שופט. דיין, נקרא מצד המלכות. שוטר, הוא שליט, כמ\"ש ויוסף הוא השליט. וכל הספירות הן שופטים מצד אמא עלאה, שהיא בינה, שבה המוחין שהתפארת הנמשך ממנה הוא שופט, ובו כלולות כל הספירות. והן שוטרים מצד המלכות, שבה השליטה, והצדיק שוטר ומושל משם."],[2,"מדבר שקר תרחק וגו':","הוא מצוה להשוות את בעלי הדינים ולהתרחק מדבר שקר, שלא יאמרו, משא פנים יש בדבר. כי הקב\"ה נאמר בו אשר לא ישא פנים ול \u0003א\u0004 יק \u0003ח\u0004 שח \u0003ד,\u0004 בסופי תיבות נמצא \u0003אחד,\u0004 דיין הזה צריך להיות כמו האחד, שהוא הויה אחד, שלא יקח שחד, שהוא יהיה בצורתו."],[3,"ובדינא, להשוות תרווייהו וכו':","וכן בדין, צריך להשוות שני הבעלי דינים כאחד, שלא יטה הדין לזה יותר מזה, אלא במשקל אחד, עד שיקבלו הדין. ולאחר כך, כל אחד נידון לפי מעשיו."],[4,"ואוקמוה מארי מתניתין וכו':","והעמידוהו בעלי המשנה, צדיק, יצר הטוב שופטו. רשע, יצר הרע שופטו. בינוני, זה וזה שופטו. מי שהוא מעץ החיים, שנמשך מז\"א, אין לו דין כלל, אין לו יצר הרע. וזהו צדיק גמור, וזהו צדיק וטוב לו, ואין טוב אלא תורה, ז\"ש, כי לקח טוב נתתי לכם תורתי אל תעזובו. וצדיק ורע לו, הוא מעץ הדעת טוב ורע, שהוא המלכות. ולמה נקרא צדיק כיון שרע לו, שהוא היצה\"ר שנקרא רע. אלא משום שיצר הטוב שולט עליו נקרא צדיק ורע לו, שרע ההוא, הוא תחת רשותו."],[5,"רשע וטוב לו וכו':","שואל, רשע וטוב לו, שהוא התורה הנקראת טוב כנ\"ל, א\"כ למה נקרא רשע. ומשיב, משום שהוא עלה להיות ראש ביצר הרע שלו, והטוב הוא תחת רשותו, כעבד תחת רבו. ואע\"פ שרשע הוא מכתיר את הצדיק, וצדיק גמור יכול להענישו, גם ענוש לצדיק לא טוב, כי משום טוב ההוא שהוא תחת רגליו של הרשע, אין להענישו, אולי יחזור בתשובה ויתגבר על יצרו, והיצר הרע יהיה עפר תחת רגליו."],[6,"דמסטרא דרשע וטוב וכו':","שמצד הרשע וטוב לו, השכינה שוכבת, כש\"א, ותגל מרגלותיו ותשכב. זה הוא, ושפחה כי תירש גבירתה. שפחה היא נקבה דיצר הרע. יצר הרע הוא זכר, בשבילו נאמר, וכבודי לאחר לא אתן. והזר הקרב יומת. כי יצר הרע נקרא אחר, ונקרא זר."],[7,"ומסטרא דצדיק ורע לו וכו':","ומצד הצדיק ורע לו, השכינה היא עטרה על ראש האדם, והשפחה היצר הרע נכנעת תחת גבירתה. ומצד הצדיק הגמור, אין זר ואין יצר הרע. ומצד הרשע הגמור, אין לו חלק בשכינה, כי אין חלק לאדם בשכינה אלא מצד הטוב."],[8,"ולית כל שכינתא וכו':","ואין כל שכינה שוות. כי השכינה של העץ הדעת טוב ורע, הוא כסא, שהוא בעולם הבריאה. או בגוף האדם. אבל השכינה של עץ החיים, שהיא בעולם אצילות, עליה נאמר לא יגורך רע. אבל משום שנאמר בה ומלכותו בכל משלה מי שפוגם המקום שלה, שבבריאה או בגוף האדם, נחשב כאלו עשה קלון במטרוניתא עצמה שבאצילות. כי בזיון המטרוניתא היא מי שמזלזל במקומה. ובזיון המטרוניתא הוא בזיון של המלך שהוא ז\"א, ונמצא פוגם גם בז\"א."],[9,"כל שכן מאן וכו':","כל שכן מי שמעביר אותה ממקומה שבבריאה, ומשים שפחה תחתיה, כי בכל מקום שהוא פוגם אין המטרוניתא שורה שם אלא השפחה, שהיא פגומה ושורה במקום פגום. והפגם של האדם מחמת עונותיו, פוגם בכל האברים שלו, עד שאין המטרוניתא מוצאת מקום לשכון שם. ואין לו תקנה, עד שיחזיר אותה על כל האברים שלו. דהיינו שישוב על כל עונותיו."]],[[0,"","אִשְׁתּוֹ דּוֹמָה לְגוּפוֹ, וְעַל שֵׁם הַמִּצְווֹת נִקְרְאוּ אֵיבָרִים. עַל שֵׁם הַשְּׁכִינָה - הַגּוּף. שֶׁמִּצַּד הָאַחֵר לְבוּשׁוֹ, שֶׁהֵם עוֹר וּבָשָׂר. זֶהוּ שֶׁכָּתוּב (איוב י) עוֹר וּבָשָׂר תַּלְבִּישֵׁנִי וּבַעֲצָמוֹת וְגִידִים תְּשּכְכֵנִי. בְּמָקוֹם שֶׁאֵין שְׁכִינָה, אוֹתוֹ הַגּוּף לֹא נִקְרָא אֶלָּא לְבוּשׁ שֶׁל אָדָם, שֶׁהוּא תּוֹרָה, (ויקרא יט) זֹאת הַתּוֹרָה אָדָם כִּי יָמוּת בְּאֹהֶל. (ישעיה מד) כְּתִפְאֶרֶת אָדָם לָשֶׁבֶת בָּיִת. וּבְמָקוֹם שֶׁשָּׁם מִצְוָה נִקְרָא גוּף שֶׁל אָדָם, כְּמוֹ גוּפֵי הֲלָכוֹת וּפִסְקֵי דִינִים."],[1,"","הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹפֵט, הָעַמּוּד הָאֶמְצָעִי, מִצַּד שֶׁל הַבִּינָה, שֶׁהוּא יְדֹוָ\"ד. דַּיָּן מִצַּד הַמַּלְכוּת. שׁוֹטֵר הוּא שַׁלִּיט, (מצד של יוסף הצדיק משם) (בראשית מב) וְיוֹסֵף הוּא הַשַּׁלִּיט. וְכָל הַסְּפִירוֹת הָיוּ שׁוֹפְטִים מִצַּד שֶׁל הָאֵם הָעֶלְיוֹנָה (בינה), שֶׁתִּפְאֶרֶת שׁוֹפֵט. וְהֵם שׁוֹטְרִים מִצַּד הַמַּלְכוּת. שֶׁצַּדִּיק מִשָּׁם שׁוֹטֵר וּמוֹשֵׁל."],[2,"","מִדְּבַר שֶׁקֶר תִּרְחָק וְנָקִי וְצַדִּיק אַל תַּהֲרֹג וְגוֹ'. מִצְוָה לְהַשְׁווֹת בַּעֲלֵי דִינִים וּלְהִתְרַחֵק מִדְּבַר שֶׁקֶר, שֶׁלֹּא יֹאמְרוּ מַשּׂוֹא פָנִים (יש בדבר), שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נֶאֱמַר בּוֹ (דברים י) אֲשֶׁר לֹא יִשָּׂא פָּנִים. וְלֹ\"א יִקַּ\"ח שֹׁחַ\"ד - בְּסוֹפֵי תֵבוֹת אֶחָד. הַדַּיָּן הַזֶּה צָרִיךְ לִהְיוֹת כְּגָוֶן שֶׁל אֶחָד, שֶׁהוּא יְדוָ\"ד אֶחָד, שֶׁלֹּא יִקַּח שּחַד, שֶׁהוּא יִהְיֶה בִּדְיוֹקְנוֹ."],[3,"","וּבַדִּין לְהַשְׁווֹת שְׁנֵיהֶם כְּאֶחָד, וְלֹא יַטֶּה דִין לָזֶה יוֹתֵר מִזֶּה, אֶלָּא בְּמִשְׁקֹלֶת אַחַת עַד שֶׁיְּקַבְּלוּ הַדִּין. וְאַחַר כָּךְ כָּל אֶחָד נִדּוֹן לְפִי מַעֲשָׂיו."],[4,"","וּפֵרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, צַדִּיק - יֵצֶר הַטּוֹב שׁוֹפְטוֹ. רָשָׁע - יֵצֶר הָרָע שׁוֹפְטוֹ. בֵּינוֹנִי - זֶה וָזֶה שׁוֹפְטוֹ. מִי שֶׁהוּא מֵעֵץ הַחַיִּים אֵין לוֹ דִּין כְּלָל, אֵין לוֹ יֵצֶר הָרָע, וְזֶה צַדִּיק גָּמוּר, וְזֶה צַדִּיק וְטוֹב לוֹ. וְאֵין טוֹב אֶלָּא תּוֹרָה. זֶהוּ שֶׁכָּתוּב (משלי ד) כִּי לֶקַח טוֹב נָתַתִּי לָכֶם תּוֹרָתִי אַל תַּעֲזוֹבוּ. וְצַדִּיק וְרָע לוֹ, מִצַּד שֶׁל עֵץ הַדַּעַת טוֹב וָרָע. וְלָמָּה נִקְרָא צַדִּיק אַחֵר שֶׁרַע לוֹ, שֶׁהוּא יֵצֶר הָרָע? אֶלָּא מִשּׁוּם שֶׁטּוֹב שׁוֹלֵט עָלָיו נִקְרָא צַדִּיק וְרַע לוֹ, שֶׁאוֹתוֹ רַע הוּא תַּחַת רְשׁוּתוֹ. (כעבד תחת רבו)."],[5,"","רָשָׁע וְטוֹב לוֹ, לָמָּה נִקְרָא רָשָׁע? מִשּׁוּם שֶׁהוּא הִתְעַלָּה לִהְיוֹת רֹאשׁ בַּיֵּצֶר הָרָע שֶׁלּוֹ, וְהַטּוֹב הוּא תַּחַת רְשׁוּתוֹ כְּמוֹ עֶבֶד תַּחַת רַבּוֹ. וְאַף עַל גַּב שֶׁרָשָׁע הוּא מַכְתִּיר אֶת הַצַּדִּיק, וְיָכוֹל צַדִּיק גָּמוּר לְהַעֲנִישׁ אוֹתוֹ, גַּם עֲנוֹשׁ לַצַּדִּיק לֹא טוֹב. מִשּׁוּם אוֹתוֹ טוֹב שֶׁהוּא תַּחַת רַגְלֵי הָרָשָׁע, אֵין לְהַעֲנִישׁוֹ, שֶׁאוּלַי יַחֲזֹר בִּתְשׁוּבָה וְיִתְגַּבֵּר עַל יִצְרוֹ, וְיִהְיֶה עָפָר תַּחַת רַגְלָיו."],[6,"","שֶׁמִּצַד שֶׁל רָשָׁע וְטוֹב לוֹ (שכינה) שׁוֹכֶבֶת, (רות ג) וַתְּגַל מַרְגְּלֹתָיו וַתִּשְׁכָּב. זֶהוּ (משלי ל) וְשִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ. (ומצד של צדיק גמור) שִׁפְחָה - יֵצֶר הָרָע נְקֵבָה. יֵצֶר הָרָע - זָכָר. בִּגְלָלוֹ נֶאֱמַר (ישעיה מב) וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן, (במדבר א) וְהַזָּר הַקָּרֵב יוּמָת."],[7,"","וּמִצַד שֶׁל צַדִּיק וְרַע לוֹ, שְׁכִינָה הִיא עֲטָרָה עַל רֹאשׁוֹ שֶׁל אָדָם, וְשִׁפְחָה - יֵצֶר הָרָע - נִכְנַעַת תַּחַת גְּבִרְתָּהּ. וּמִצַּד שֶׁל צַדִּיק גָּמוּר אֵין זָר וְאֵין יֵצֶר הָרָע. וּמִצַּד שֶׁל רָשָׁע גָּמוּר אֵין לוֹ חֵלֶק בַּשְּׁכִינָה, שֶׁאֵין חֵלֶק לָאָדָם בַּשְּׁכִינָה אֶלָּא מִצַּד הַטּוֹב."],[8,"","וְאֵין כָּל שְׁכִינָה שְׁקוּלוֹת, שֶׁהֲרֵי שְׁכִינָה שֶׁל עֵץ טוֹב וָרָע הִיא כִּסֵּא, אֲבָל שְׁכִינָה שֶׁל עֵץ הַחַיִּים, עָלֶיהָ נֶאֱמַר (תהלים ה) לֹא יְגֻרְךְ רָע. (אלא) מִשּׁוּם שֶׁנֶּאֱמַר בָּהּ וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה, מִי שֶׁפּוֹגֵם אֶת מְקוֹמוֹ נֶחְשָׁב כְּאִלּוּ עָשָׂה קָלוֹן לַגְּבִירָה. שֶׁקְּלוֹן הַגְּבִירָה הוּא מִי שֶׁמְּזַלְזֵל בִּמְקוֹמָהּ, וּקְלוֹן הַגְּבִירָה הוּא שֶׁל הַמֶּלֶךְ."],[9,"","כָּל שֶׁכֵּן מִי שֶׁמַּעֲבִיר אוֹתָהּ מִמְּקוֹמָהּ וְשָׂם שִׁפְחָה בִּמְקוֹמָהּ, שֶׁבְּכָל מָקוֹם שֶׁהוּא פּוֹגֵם, הַגְּבִירָה אֵינָהּ שְׁרוּיָה שָׁם, אֶלָּא שִׁפְחָה, שֶׁהִיא פְּגוּמָה, שׁוֹרָה בְּמָקוֹם פָּגוּם. וּפְגָם שֶׁל אָדָם שֶׁל חֲטָאָיו פּוֹגֵם בְּכָל אֵיבָרָיו, עַד שֶׁלֹּא מוֹצֵאת הַגְּבִירָה מָקוֹם לִשְׁרוֹת שָׁם, וְאֵין לוֹ תִּקּוּן עַד שֶׁיַּחֲזִירֶנָּה לְכָל אֵיבָרָיו."]]],[["אָמַר בּוּצִינָא קַדִּישָׁא, רַעְיָא מְהֵימָנָא, בְּגִין דָּא, אַנְתְּ מְתַקֵּן, בְּחִבּוּרָא דָּא, דְּרמ\"ח פִּקּוּדִין. לְאַמְלְכָא לְקוּדְשָׁא בְּרִיךְ הוּא עַל כָּל אֵבָרִים דִּשְׁכִינְתָּא, בְּכָל פִּקּוּדָא וּפִקּוּדָא, וְלֵית אַנְתְּ חָיִישׁ לִיקָרָךְ. זַכָּאָה חוּלָקָךְ, דִּכְגַוְונָא דְּאַנְתְּ מַמְלִיךְ לְקוּדְשָׁא בְּרִיךְ הוּא בְּכָל אֵבָרִים דִּשְׁכִינְתָּא, דְּאִינּוּן בַּעֲלֵי מִדּוֹת, דְּכָל יִשְׂרָאֵל. מָארֵי מִדּוֹת אִינּוּן אֵבָרִים דִּשְׁכִינְתָּא, הָכִי עָבִיד קוּדְשָׁא בְּרִיךְ הוּא לְשַׁרְיָא שְׁמֵיהּ עָלָךְ, וְיַמְלְכִינָךְ, עַל כָּל מַשְׁרְיָין עִלָּאִין וְתַתָּאִין (שופטים ער\"ה ע\"א לא יקום עד אחד).","קוּם רַעְיָא מְהֵימָנָא, לְסַדְּרָא דִּינִין בְּהִלְכוֹת נְזִקִין, בְּסִדּוּרָא דִּשְׁמָא דָּא, הָוָיָ\"ה. דְּאִיהוּ, (תהילים ס״ח:י״ח) רֶכֶב אֱלהִים רִבּוֹתַיִם אַלְפֵי שִׁנְאָן, דְּאִינּוּן, שׁוֹר נֶשֶׁר אַרְיֵה אָדָם, דְּהָא מִסִּטְרָא דִּימִינָא, דְּתַּמָּן יְדוָֹ\"ד, ד' חִיוָון, הָכִי אִיהוּ סִדּוּרָא דִּלְהוֹן, אָדָם אַרְיֵה נֶשֶׁר שׁוֹר. וּכְפוּם שִׁנּוּיִין דְּהֲוָיָין, הָכִי אִיהוּ תְּנוּעָה וְסִדּוּרָא דְּחֵיוָן. וְחֵיוָן דְּסִטְרָא אַחֲרָא, דְּאִינּוּן נְזִיקִין דִּשְׂמָאלָא, הָכִי סִדּוּרַיְיהוּ, שִׁנְאָן. וּבְגִין דָּא, הַתְחָלָה דִּלְהוֹן, הַשּׁוֹר. קָשׁוּר בְּד' אָבוֹת נְזִיקִין, הַשּׁוֹר וְהַבּוֹר וְהַמַּבְעֶה וְהַהֶבְעֵר וְסִיּוּמָא דִּלְהוֹן אָדָם, מוּעָד.","קוּם אַתְעַר בְּדִינִין. פָּתַח רַעְיָא מְהֵימָנָא וְאָמַר, (תהילים נ״א:י״ז) אֲדֹנָי שְׂפָתַי תִּפְתָּח וּפִי יַגִּיד תְּהִלָּתֶךָ. אֲדֹנָ\"י, בְּהִפּוּךְ אַתְוָון דִּינָ\"א. וּבְגִין דָּא, אָמְרוּ מָארֵי מַתְנִיתִין, דִּינָ\"א דְּמַלְכוּתָא דִּינָא. כָּל דִּינִין בְּהַאי שְׁמָא אִתְדָנוּ. (ס\"א בה' בד' וכו') בְּד', בְּג'. בְּד': שְׁכִינְתָּא (ס\"א בית דין בג' בית דין שכינתא בג') לָקֳבֵל תְּלַת אֲבָהָן. עַמּוּדָא דְּאֶמְצָעִיתָא, דַּיָּין אֱמֶת, וְהוּא דַּיָּין, לָדוּן מִסִּטְרָא דַּאֲדֹנָ\"י, דְּתַּמָּן אִיהוּ דַּיָּין אֱמֶת. וּמִסִּטְרָא דְּשֵׁם אֱלהִים, שׁוֹפֵט. הֲדָא הוּא דִּכְתִּיב, (תהילים ע״ה:ח׳) כִּי אֱלֹהִים שׁוֹפֵט.","וּמַה דִּינִין אִינּוּן. חַד, לָדוּן בְּנִזְקֵי שׁוֹר. תִּנְיָינָא, לָדוּן בְּנִזְקֵי בּוֹר. תְּלִיתָאָה, לָדוּן בְּנִזְקֵי אֵשׁ. רְבִיעָאָה, לָדוּן בְּנִזְקֵי אָדָם. וַאֲבַתְרַיְיהוּ, לָדוּן בְּדִינֵי אַרְבַּע שׁוֹמְרִים. שׁוֹמֵר חִנָּם. וְשוֹמֵר שָׂכָר. וְהַשּׁוֹאֵל. וְנוֹשֵׂא שָׂכָר. (ס\"א והשוכר) לָקֳבְלַיְיהוּ, דִּינִין אַרְבְּעָה. דִּין חֲלוּקַת הַשּׁוּתָּפִים. דִּין חֲלוּקַת קַרְקָעוֹת. דִּינֵי עֲבָדִים וּשְׁפָחוֹת. דִּינֵי תּוֹבֵעַ וְנִתְבָּע, בְּכַמָּה מִינֵי תְּבִיעוֹת דְּחִיּוּב מָמוֹן, וְגֶזֶל, וַאַבֵדָה, אוֹ שֶׁמַּזִּיק לַחֲבֵרוֹ, וְהוֹרְגוֹ בְּאֶחָד מֵאַרְבַּע מִיתוֹת בֵּית דִּין.","אָדוֹן אִיהוּ קוּדְשָׁא בְּרִיךְ הוּא, בַּאֲדֹנָ\"י. לָדוּן בְּכָל מִינִי דִּינִין, לְשִׁפְחָה בִּישָׁא, כִּי תִירַשׁ גְּבִירְתָּהּ. דְּמִינָּהּ כָּל נְזִיקִין אִשְׁתְּכָחוּ, דְּאִינּוּן (כל) מַלְאֲכֵי חַבָּלָה, דְּמִנַּיְיהוּ נִשְׁמָתְהוֹן שֶׁל רְשָׁעִים, כְּמָה דְּאוּקְמוּהָ מָארֵי מַתְנִיתִין, (בראשית כ\"ט ע\"א) נִשְׁמוֹת הָרְשָׁעִים הֵן הֵן הַמַּזִּיקִים בָּעוֹלָם. אֵל אַחֵר, מַזִּיק, גַּזְלָן רָשָׁע. וּבַת זוּגֵיהּ, סַם הַמָּוֶת.","נֶזֶק שֶׁבֶת וּבֹשֶׁת וְרִפּוּיּ, לִשְׁכִינְתָּא וּבְנָהָא. שֶׁבֶת, דְּבִטוּלָא דְּאוֹרַיְיתָא, דְּבָטִילַת לִבְנָהָא. וְרִפּוּיּ, דְּגַרְמָת לוֹן דְּמִתְרַפִּין מִדִּבְרֵי תּוֹרָה. נְזֶק, בְּכַמָּה נְזִקִין דְּמַלְאֲכֵי חַבָּלָה, מָארֵי מַשְׁחִית אַף וְחֵימָה. וּבֹשֶׁת, דַּהֲווֹ מְבַזִּין לִשְׁכִינְתָּא בְּכּוֹכָבִים וּמַזָּלוֹת, שִׁקְרָא דִּלְהוֹן, וַהֲווּ אַמְרִין אַיֵּה אֱלֹהֶיךָ. וְכַמָּה גְּזֵלוֹת מִן שִׁפְחָה בִּישָׁא, דְּאִתְּמַר בָּהּ (ישעיהו ג׳:י״ד) גְּזֵלַת הֶעָנִי בְּבָתֵּיכֶם.","כַּמָּה בִּרְכָּאן, גַּזְלַת לִשְׁכִינְתָּא, שִׁפְחָא בִּישָׁא. בְּכוֹבֶד הַמַּס, וּבְכוֹבֶד כַּמָּה דִּינִין מְשׁוּנִים עַל בְּנָהָא, וְכַמָּה קָרְבְּנִין דְּבֵי מַקְדְּשָׁא, דִּבְטִילַת לְמַטְרוֹנִיתָא. וּבֹשֶׁת דְּמַטְרוֹנִיתָא, דְּאִשְׁתְּאָרַת עֲרוּמָה, מֵד' בִּגְדֵי זָהָב דְּנָהֲרִין, מֵד' טוּרֵי אָבֶן, בי\"ב אֲבָנִין מַרְגְּלָן. מְעִיל בְּכַמָּה זָגִין וְרִמּוֹנִים. וְאַרְבַּע בִּגְדֵי לָבָן, דִּבְּהוֹן הֲוַת מַטְרוֹנִיתָא, מִתְקַשְּׁטָא קֳדָם מַלְכָּא. הֲדָא הוּא דִכְתִיב, (בראשית ט׳:ט״ז) וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם. וְגָזְלַת לָהּ לִגְּבִרְתָּהּ, כַּמָּה מַאֲכָלִין דְּקָרְבְּנִין.","שׁוֹר מוּעָד בַּעְלָהּ, עָאל לְבֵי מַלְכָּא (קצ\"א ע\"א) רִבּוֹנֵיהּ, בְּאַרְבַּע אֲבוֹת נְזִיקִין דִּילֵיהּ, (דאינון, (יחזקאל א׳:י׳) ופני שור מהשמאל לארבעתם) עָוֹן וּמַשְׁחִית אַף וְחֵמָה, דְּכֻלְּהוּ מוּעָדִין לְקַלְקֵל. בְּגוּפָא דִּילֵיהּ, הִרְבִּיץ עַל הַכֵּלִים, מִזְבַּח מְנוֹרָה שֻלְחָן וּשְׁאַר מָאנִין, רָבַץ עָלַיְיהוּ וְשִׁבְּרָתָן. וּבְשֵׁן דִּילֵיהּ, אָכִיל כָּל קָרְבְּנִין דִּמַּאֲכָלִים דְּפָתוֹרָא, וְשַׁאֲרָא בְּרַגְלוֹי רַפְסָא. (ומדקא כלא ושארא דאינון אמוהן ופדרין שיירי מנחות ברגלוי רפסא) וּבְקֶרֶן דִּילֵיהּ, קָטַל כַּהֲנֵי וְלֵיוָאֵי. הָרַס כֹּלָּא, (איכה ב׳:ב׳) חִלֵּל מַמְלָכָה וְשָׂרֶיהָ."],[[0,"אמר בוצינא קדישא וכו':","אמר המאור הקדוש, ר\"ש, רועה הנאמן, משום זה אתה מתקן בחבור הזה של רמ\"ח מצות, להמליך את הקב\"ה על כל האברים של השכינה, בכל מצוה ומצוה, ואין אתה דואג לכבודך. אשרי חלקך, שכמו שאתה ממליך את הקב\"ה על כל אברי השכינה, שהם בעלי מדות של כל ישראל, כי בעלי מדות הם אברי השכינה, כך עושה הקב\"ה להשרות שמו עליך, וימליך אותך על כל מחנות עליונים והתחתונים."],[1,"קום רעיא מהימנא וכו':","קום רועה נאמן, לסדר דינים בהלכות נזיקין, בסדר של שם הזה, הויה. שהוא, רכב אלקים רבותים אלפי שנאן, שהם שור נשר אריה אדם. (1) כי מצד ימין, ששם הויה, כך הוא בסדר של ד' החיות, אדם אריה נשר שור. אשר שור, שהיא גבורה הוא לאחרונה. ולפי השינוי הנעשה בהם, כך הוא התנועה והסדר של החיות. והחיות של צד האחר, שהם הנזיקין שבשמאל, כך הוא סדורם, \u0003שנא\"ן,\u0004 שהוא שור נשר אריה אדם כנ\"ל, ומשום זה ההתחלה שלהם, השור, קשור בד' אבות נזיקין, השור והבור והמבעה וההבער, והסיום שלהם אדם, שהוא מועד לעולם."],[2,"קום אתער בדינין וכו':","קום התעורר בדינים. פתח רעיא מהימנא ואמר, אדני שפתי תפתח ופי יגיד תהלתך. \u0003אדני\u0004 בהפיכת האותיות היא \u0003דינא.\u0004 ומשום זה אמרו בעלי המשנה, דינא דמלכותא דינא, משום שהמלכות נקרא אדני שהוא אותיות דינא. כל הדינים בשם הזה נדונו. ונדונים ב \u0003ד'\u0004 וב \u0003ג',\u0004 ב \u0003ד'\u0004 היא השכינה שכנגד ג' אבות, שהיא רביעי אליהם. וב \u0003ג'\u0004 הוא עמוד האמצעי, דהיינו ז\"א שכולל חג\"ת, שהוא דיין אמת. והוא דיין, לדון מצד אדנ\"י, שהוא מלכות. ששם הוא דיין אמת. ומצד שם אלקים, שהוא בינה, הוא שופט. ז\"ש, כי אלקים שופט."],[3,"ומה דינין אינון וכו':","ומה הם הדינים. אחד לדון בנזקי שור. שני, לדון בנזקי בור. שלישי, לדון בנזקי אש. רביעי, לדון בנזקי אדם. ואחריהם לדון בדין ארבעה שומרים, שומר חנם, ושומר שכר, והשואל, ונושא שכר. כנגדם ארבעה דינים, דין חלוקת השותפין, דין חלוקת קרקעות, דיני עבדים ושפחות, דיני תובע ונתבע בכמה מיני תביעות דחיוב ממון, וגזל ואבדה או שמזיק לחבירו, והורגו באחד מד' מיתות בית דין."],[4,"אדון איהו קב\"ה וכו':","אדון, הוא הקב\"ה באדנ\"י, כי אדון הוא מלשון דין. לדון בכל מיני דינים לשפחה רעה כי תירש גבירתה, שממנה נמצאים כל הנזקים, שהם מלאכי חבלה, שמהם הנשמות של הרשעים. כמו שהעמידו בעלי המשנה, נשמות הרשעים הן הן המזיקים שבעולם. אל אחר, הוא מזיק גזלן רשע, ובת זוגיה הוא סם המות."],[5,"נזק שבת ובשת ורפוי וכו':","נזק שבת ובושת ורפוי צריכים לשלם להשכינה ובניה, שהם ישראל. ומפרש. \u0003שבת,\u0004 הוא בטול תורה שהס\"א בטלה מן הבנים. \u0003ורפוי,\u0004 שגרמה להם להתרפות מדברי תורה. \u0003נזק,\u0004 בכמה נזקים של מלאכי חבלה בעלי משחית אף וחימה. \u0003ובשת,\u0004 שהיו מבזים את השכינה באלילי שקר שלהם, והיו אומרים איה אלקיך. וכמה גזלות גזלה שפחה הרעה, שנאמר בה, גזלת העני בבתיכם."],[6,"כמה ברכאן גזלת וכו':","כמה ברכות גזלה שפחה הרעה מן השכינה, בכובד המס, ובכובד כמה דינים משונים על בניה, וכמה קרבנות של בית המקדש שבטלה מן המטרוניתא. ובשת של המטרוניתא, שנשארה ערומה מד' בגדי זהב המאירים מד' טורי אבן, שהם חו\"ג תו\"מ, בי\"ב אבנים מרגלית, שכל אחת מחו\"ג תו\"מ כלולה מג' קוין והם י\"ב. מעיל בכמה זגים ורמונים. וד' בגדי לבן, שבהם היתה המטרוניתא מתקשטת לפני המלך. ז\"ש וראיתיה לזכר ברית עולם. וגזלת הגבירה, שהיא השכינה, כמה מאכלים של הקרבנות."],[7,"שור מועד בעלה וכו':","שור המועד, בעלה של השפחה רעה, נכנס לבית המלך אדונו, בארבעה אבות נזיקין שלו, שהם, עון ומשחית אף וחימה, שכולם מועדים לקלקל. בגופו הרביץ על הכלים, מזבח מנורה שלחן ושאר כלים, רבץ עליהם ושבר אותם. ובשן שלו, אכל כל הקרבנות והמאכלים של השלחן, והשאר ברגליו רמס. ובקרן שלו, הרג כהנים ולוים, הרס הכל, חלל ממלכה ושריה."]],[[0,"","אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, רוֹעֶה הַנֶּאֱמָן, מִשּׁוּם זֶה אַתָּה מְתַקֵּן בַּחִבּוּר הַזֶּה שֶׁל רְמַ\"ח מִצווֹת לְהַמְלִיךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא עַל כָּל אֵיבְרֵי הַשְּׁכִינָה בְּכָל מִצְוָה וּמִצְוָה, וְאֵינְךְ חוֹשֵׁשׁ לִכְבוֹדְךְ. אַשְׁרֵי חֶלְקְךְ. שֶׁכְּמוֹ שֶׁאַתָּה מַמְלִיךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל אֵיבְרֵי הַשְּׁכִינָה, שֶׁהֵם בַּעֲלֵי מִדּוֹת שֶׁל כָּל יִשְׂרָאֵל, בַּעֲלֵי מִדּוֹת הֵם אֵיבְרֵי הַשְּׁכִינָה, כָּךְ עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׁרוֹת אֶת שְׁמוֹ עָלֶיךְ וְיַמְלִיךְ אוֹתְךְ עַל כָּל הַמַּחֲנוֹת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים."],[1,"","קוּם רוֹעֶה הַנֶּאֱמָן לְסַדֵּר דִּינִים בְּהִלְכוֹת נְזִיקִין, בַּסִּדּוּר שֶׁל הַשֵּׁם הַזֶּה, הֲוָיָ\"ה, שֶׁהוּא (תהלים סח) רֶכֶב אֱלֹהִים רִבֹּתַיִם אַלְפֵי שִׁנְאָן, שֶׁהֵם שׁוֹר נֶשֶׁר אַרְיֵה אָדָם, שֶׁהֲרֵי מִצַּד הַיָּמִין, שֶׁשָּׁם יְדוָ\"ד, אַרְבַּע חַיּוֹת, כָּךְ הוּא סִדּוּרָם: אָדָם אַרְיֵה נֶשֶׁר שׁוֹר. וּכְפִי הַשִּׁנּוּיִים שֶׁמִּתְהַוִּים, כָּךְ הִיא תְּנוּעַת וְסִדּוּר הַחַיּוֹת. וְהַחַיּוֹת שֶׁל הַצַּד הָאַחֵר, שֶׁהֵם נְזִיקִין שֶׁל שְׂמֹאל, כָּךְ סִדּוּרָם: שִׁנְאָן. וּמִשּׁוּם זֶה הַהַתְחָלָה שֶׁלָּהֶם - הַשּׁוֹר - קָשׁוּר לְאַרְבָּעָה אֲבוֹת נְזִיקִין - הַשּׁוֹר וְהַבּוֹר וְהַמַּבְעֶה וְהַהֶבְעֵר, וְהַסִּיּוּם שֶׁלָּהֶם אָדָם, מוּעָד."],[2,"","קוּם הִתְעוֹרֵר בְּדִינִים. פָּתַח רוֹעֶה הַנֶּאֱמָן וְאָמַר, (שם כא) אֲדנָי שְׂפָתַי תִּפְתָּח וּפִי יַגִּיד תְּהִלָּתֶךְ. אֲדֹנָ\"י בְּהִפּוּךְ אוֹתִיּוֹת - דִּינָ\"א, וּמִשּׁוּם זֶה אָמְרוּ בַּעֲלֵי הַמִּשְׁנָה, דִּינָא דְמַלְכוּתָא דִּינָא. כָּל הַדִּינִים בַּשֵּׁם הַזֶּה נִדּוֹנוּ. (בה' בד') בְּד', בְּג'. בְּד' - שְׁכִינָה (בית דין בשלשה, בית דין שכינה בשלשה) כְּנֶגֶד שְׁלֹשֶׁת הָאָבוֹת. עַמּוּד הָאֶמְצָעִי, דַּיַּן אֱמֶת, וְהוּא דַּיָּן לָדוּן מִצַּד שֶׁל אֲדֹנָ\"י, שֶׁשָּׁם הוּא דַּיַּן אֱמֶת. וּמִצַּד שֶׁל שֵׁם אֱלֹהִים, שׁוֹפֵט. זֶהוּ שֶׁכָּתוּב (שם עה) כִּי אֱלֹהִים שּפֵט."],[3,"","וּמָהֵם הַדִּינִים? אֶחָד, לָדוּן בְּנִזְקֵי שׁוֹר. שֵׁנִי, לָדוּן בְּנִזְקֵי בוֹר. שְׁלִישִׁי, לָדוּן בְּנִזְקֵי אֵשׁ. רְבִיעִי, לָדוּן בְּנִזְקֵי אָדָם. וְאַחֲרֵיהֶם לָדוּן בְּדִינֵי אַרְבָּעָה שׁוֹמְרִים: שׁוֹמֵר חִנָּם, וְשׁוֹמֵר שָׂכָר, וְהַשּׁוֹאֵל, וְנוֹשֵׂא שָׂכָר. (והשוכר) כְּנֶגְדָּם אַרְבָּעָה דִּינִים: דִּין חֲלֻקַּת הַשֻּׁתָּפִים, דִּין חֲלֻקַּת קַרְקָעוֹת, דִּינֵי עֲבָדִים וּשְׁפָחוֹת, דִּינֵי תוֹבֵעַ וְנִתְבָּע בְּכַמָּה מִינֵי תְבִיעוֹת שֶׁל חִיּוּב מָמוֹן וְגָזֵל וַאֲבֵדָה, אוֹ שֶׁמַּזִּיק לַחֲבֵרוֹ וְהוֹרְגוֹ בְּאַחַת מֵאַרְבַּע מִיתוֹת בֵּית דִּין."],[4,"","אָדוֹן הוּא הַקָּדוֹשׁ בָּרוּךְ הוּא, בַּאדנָ\"י, לָדוּן בְּכָל מִינֵי דִינִים אֶת הַשִּׁפְחָה הָרָעָה כִּי תִירַשׁ גְּבִרְתָּהּ, שֶׁמִּמֶּנָּה כָּל הַנְּזָקִים נִמְצָאִים, שֶׁהֵם (כל) מַלְאֲכֵי חַבָּלָה, שֶׁמֵּהֶם נִשְׁמוֹת הָרְשָׁעִים, כְּמוֹ שֶׁבֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, נִשְׁמוֹת הָרְשָׁעִים הֵן הֵן הַמַּזִּיקִים שֶׁל הָעוֹלָם. אֵל אַחֵר, מַזִּיק, גַּזְלָן רָשָׁע. וּבַת זוּגוֹ סַם הַמָּוֶת."],[5,"","נֶזֶק שֶׁבֶת וּבשֶׁת וְרִפּוּי - לַשְּׁכִינָה וּבָנֶיהָ. שֶׁבֶת - שֶׁל בִּטּוּל תּוֹרָה שֶׁבִּטְּלָה אֶת בָּנֶיהָ. וְרִפּוּי - שֶׁגָּרְמָה לָהֶם שֶׁמִּתְרַפִּים מִדִּבְרֵי תוֹרָה. נֶזֶק - בְּכַמָּה נְזָקִים שֶׁל מַלְאֲכֵי חַבָּלָה, בַּעֲלֵי מַשְׁחִית אַף וְחֵמָה. וּבֹשֶׁת - שֶׁהָיוּ מְבַזִּים אֶת הַשְּׁכִינָה בְּכוֹכָבִים וּמַזָּלוֹת, הַשֶּׁקֶר שֶׁלָּהֶם, וְהָיוּ אוֹמְרִים אַיֵּה אֱלֹהֶיךְ. וְכַמָּה גְזֵלוֹת מֵהַשִּׁפְחָה הָרָעָה, שֶׁנֶּאֱמַר בָּהּ (ישעיה ג) גְּזֵלַת הֶעָנִי בְּבָתֵּיכֶם."],[6,"","כַּמָּה בְרָכוֹת גּוֹזֶלֶת אֶת הַשְּׁכִינָה הַשִּׁפְחָה הָרָעָה; בְּכֹבֶד הַמַּס, וּבְכֹבֶד שֶׁל כַּמָּה דִינִים מְשֻׁנִּים עַל בָּנֶיהָ, וְכַמָּה קָרְבָּנוֹת שֶׁל בֵּית הַמִּקְדָּשׁ שֶׁבִּטְּלָה לַגְּבִירָה. וּבֹשֶׁת שֶׁל הַגְּבִירָה שֶׁנִּשְׁאֲרָה עֲרֻמָּה מֵאַרְבָּעָה בִּגְדֵי זָהָב שֶׁמְּאִירִים מֵאַרְבָּעָה טוּרֵי אֶבֶן בִּשְׁתֵּים עֶשְׂרֵה אֲבָנִים מַרְגָּלִיּוֹת. מְעִיל בְּכַמָּה זַגִּים וְרִמּוֹנִים. וְאַרְבָּעָה בִּגְדֵי לָבָן שֶׁבָּהֶם הָיְתָה הַגְּבִירָה מִתְקַשֶּׁטֶת לִפְנֵי הַמֶּלֶךְ. זֶהוּ שֶׁכָּתוּב (בראשית ט) וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם. וְגוֹזֶלֶת אֶת גְּבִרְתָּהּ כַּמָּה מַאַכְלֵי הַקָּרְבָּנוֹת."],[7,"","שׁוֹר מוּעָד בַּעְלָהּ, נִכְנָס לְבֵית הַמֶּלֶךְ רִבּוֹנוֹ בְּאַרְבָּעָה אֲבוֹת הַנְּזִיקִין שֶׁלּוֹ, (שהם (יחזקאלא) ופניהשור מהשמאול לארבּעתָּן) עון ומשחית אף וחמה, שכלם מועדים לקלקל. בגוף שלו הרביץ על הכלים, מזבח מנורה שלחן ושאר כלים. רבץ עליהם ושברם. ובשן שלו אכל כל הקרבנות של מאכלי השלחן, ואת השאר רמס ברגליו, (וּמָחק הכּל, והשאָר שהם אמוּרים וּפדָרים, שיָרי מנָחות, רָמסבּרגלָיו) ובקרנו הרג כהנים ולוים. הרס הכל, חלל ממלכה ושריה."]]],[["הַבּוֹר, נוּקְבָּא בִּישָׁא, לִילִית, בְּבַיִת דִּילָהּ, דְּאִיהִי בֵּית הַסֹּהַר, תְּפִיסַת לְמַטְרוֹנִיתָא וּבְנָהָא, שִׁפְחָה בִּישָׁא, בְּגָלוּתָא דִּילָהּ, וְשַׁוְויָיאן לוֹן, בְּכַמָּה שַׁלְשְׁלָאִין וַאֲסוּרִין לִבְנָהָא, יְדַיְיהוּ מְהַדְּקָן לַאֲחוֹרָא. (איכה א׳:ג׳) הִיא יָשְׁבָה בַּגּוֹיִם לא מָצְאָה מָנוֹחַ. וְלא עוֹד אֶלָּא (איכה א׳:ח׳) כָּל מְכַבְּדֶיהָ הִזִּילוּהָ כִּי רָאוּ עֶרְוָתָהּ גַּם הִיא נְאֶנְחָה וַתָּשָׁב אָחוֹר.","וְלא עוֹד, אֶלָּא זוֹנָה דְּאִיהִי הֶבְעֵר, דְּהַיְינוּ אֵשׁ, (איכה ד׳:י״א) וַיַּצֶּת אֵשׁ בְּצִיּוֹן. לְבָתַר קָם אָדָם בְּלִיַּעַ\"ל רָשָׁע, רְבִיעִי לַאֲבוֹת נְזִיקִין, דְּאִתְּמַר בֵּיהּ אָדָם מוּעָד לְעוֹלָם, בֵּין עֵר בֵּין יָשֵׁן, וְשִׁלַּח אֶת בְּעִירוֹ, וְאָכִיל וְשֵׁצֵי וְגָדַע כְּרָמִים וּפַרְדֵּסִים דִּיְרוּשָׁלַ ם, וְשֵׁצֵי כֹּלָּא.","רִבּוֹן עָלְמָא, אַנְתְּ קְשׁוֹט, וְאוֹרַיְיתָךְ קְשׁוֹט, יָהָבַת לָן מִצְוַת תְּפִילִין, (מ\"ג ע\"א) לַצַדִּיקִים גְּמוּרִים אִיהוּ אַגְרָא כְּפוּם עוֹבָדַיְיהוּ, פְּאֵר עַל רֵישַׁיְיהוּ. וּמְשַׁמְּשִׁין לַאֲבוּהוֹן וְאִמְּהוֹן, כְּגַוְונָא דְּגוּפָא, דְּכָל אֵבָרִים דִּילֵיהּ מְשַׁמְּשִׁין לְרֵישָׁא. הָכִי אִתְּתָא, מְשַׁמְּשָׁא לְבַעְלָהּ.","וְאִית מַלְאָכִין דְּאִינּוּן מְשַׁמְּשִׁין לְגוּפָא, וּמַלְאָכִין דִּמְשַׁמְּשִׁין לְנִשְׁמְתָא. וּכְגַוְונָא דְּאִית אַפְרָשׁוּתָא בֵּין גּוּפָא לְנִשְׁמְתָא, הָכִי אִית אַפְרָשׁוּתָא בֵּין מַלְאָכִין דְּגוּפָא, לְמַלְאָכִין דְּנִשְׁמְתָא. וְאִית נִשְׁמְתָא לְנִשְׁמְתָא. וּמַלְאָכִין לְמַלְאָכִין, (קהלת ה׳:ז׳) כִּי גָּבוֹהַּ מֵעַל גָּבוֹהַּ שֹׁמֵר וּגְבוֹהִים עֲלֵיהֶם. וְאִלֵּין דְּאִינּוּן נִשְׁמְתָא לְנִשְׁמְתָא, כֻּלְּהוּ חַד. וְאַף עַל גַּב דְּאֹרַח מִתְלָא, אִינּוּן כְּגוּפָא אֵצֶל נִשְׁמְתָא אִלֵּין לְאִלֵּין, בְּגִין דִּמְקַבְּלִין אִלֵּין מֵאִלֵּין. הָכִי שְׁכִינְתָּא, (נשמתא) אַף עַל גַּב דְּאִיהִי לָקֳבֵל שְׁאַר נְהוֹרִין דִּבְרִיאָה, כְּנִשְׁמְתָא אֵצֶל גּוּפָא, לָקֳבֵל קוּדְשָׁא בְּרִיךְ הוּא חֲשִׁיבָא כְּגוּפָא. אֲבָל כֹּלָּא חַד. הָכָא גּוּפָא וְנִשְׁמְתָא כֹּלָּא חַד. מַה דְּלָאו הָכִי בְּבַר נָשׁ, דְּגוּפֵיהּ וְנִשְׁמָתֵיהּ בְּפִרוּדָא. דָּא חוֹמֶר, וְדָא שֵּׂכֶל. דָּא חַיֵּי, וְדָא מוֹתָא. אֲבָל קוּדְשָׁא בְּרִיךְ הוּא חַיִּים, וּשְׁכִינְתֵּיהּ חַיִּים, הֲדָא הוּא דִכְתִיב, (משלי ג׳:י״ח) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ.","וְכָל אִינּוּן דִּרְשִׁימִין בְּסִימָנִין דְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, אִינּוּן רְשִׁימִין בְּיוֹמִין דְּחוֹל, בְּאוֹת דִּתְפִלִין, וּבְאוֹת דְּמִילָה. וּרְשִׁימִין בְּזָכוֹר וְשָׁמוֹר בְּשַׁבָּת. רְשִׁימִין בַּתּוֹרָה שֶׁבִּכְתָב, דְּאִתְיְהִיבַת מִימִינָא. וּבַתּוֹרָה שֶׁבְּעַל פֶּה, דְּאִתְיְהִיבַת מִשְּׂמָאלָא. וְקוּדְשָׁא בְּרִיךְ הוּא, זָכוֹר מִימִינָא, וְשָׁמוֹר מִשְּׂמָאלָא. וּשְׁכִינְתָּא, זְכִירָה מִימִינָא, וּשְׁמִירָה מִשְּׂמָאלָא. אִינּוּן תְּפִלִּין דְּרֵישָׁא דְּבַּר נָשׁ, וּתְפִלִּין דְּיָד. וְהָכִי שְׁכִינְתָּא, (תהלים יט) תּוֹרַת יְיָ' תְּמִימָה, וּמִצְוָה דִּילֵיהּ. וְהַאי מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא, דְּאִיהוּ כָּלִיל דִּינָא וְרַחֲמֵי. זָכוֹר וְשָׁמוֹר. אִתְקְרִיאַת אִיהִי זְכִירָה שְׁמִירָה. וּבְכָל פִּקּוּדִין אִיהִי שָׁקִילָה לְגַבֵּיהּ בְּמַדְרֵגָה.","אֲבָל מִסִּטְרָא דְּחֶסֶד, קוּדְשָׁא בְּרִיךְ הוּא זָכוֹר, וּשְׁכִינְתָּא שָׁמוֹר. כְּמָה דְּאוּקְמוּהָ מָארֵי מַתְנִיתִין, זָכוֹר לְזָכָר, וְשָׁמוֹר לְכַלָּה. בְּגִין דְּבִימִינָא וּבִשְׂמָאלָא עַנְפִּין מִתְפָּרְדִין, כְּגַוְונָא דְּכַנְפֵי רֵיאָה, דְּאִינּוּן פְּרוּדוֹת מִלְּמַעְלָה. לָקֳבְלַיְיהוּ חֵיוָן, (יחזקאל א׳:י״א) וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרוּדוֹת מִלְּמַעְלָה. וְלָקֳבֵל פְּתוּחוֹת דְּסֵפֶר תּוֹרָה. לְתַתָּא תַּרְוַויְיהוּ בְּיִחוּדָא חֲדָא, כְּגוֹן סְתוּמוֹת דְּסֵפֶר תּוֹרָה, דְּלֵית תַּמָּן פִּרוּדָא. וּבְגִין דָּא, בַּאֲתָר דְּיִחוּדָא, דְּאִיהוּ גּוּפָא, דּוֹמֶה לַשִּׁדְרָה דְּלוּלָב, אִם נִפְרְצוּ, אוֹ נִפְרְדוּ עָלָיו פָּסוּל.","בְּכַמָּה רְשִׁימִין רָשִׁים קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, לְאִשְׁתְּמוֹדְעָא לְגַבֵּי מַלְאָכִין. אִלֵּין דִּימִינָא, דְּתַלְיָין מְקוּדְשָׁא בְּרִיךְ הוּא. אוֹ אִלֵּין דִּשְׂמָאלָא, דְּתַלְיָין מִשְׁכִינְתָּא. אוֹ אִלֵּין דְּתַלְיָין מְקוּדְשָׁא בְּרִיךְ הוּא. וּשְׁכִינְתֵּיהּ בְּיִחוּדָא חֲדָא. וַדַּאי אִלֵּין דְּאִית בְּהוֹן תּוֹרָה, רְשִׁימִין בְּחֶסֶד. וְאִלֵּין דְּאִית בְּהוֹן מִצְוָה, רְשִׁימִין בִּגְבוּרָה. וְאִלֵּין מָארֵי דִּתְפִלִין, וְאוֹת שַׁבָּת, וְאוֹת בְּרִית, רְשִׁימִין בְּצַדִּיק.","וּבְעִירָן, עַמֵּי הָאָרֶץ, אִינּוּן רְשִׁימִין בְּאַעְבָּרוּ דְּעָרְלָה וּפְרִיעָה. עוֹפִין, בְּזֶפֶק וּבְקֻרְקְבָן נִקְלָף, בְּאַעְבָּרוּ דְּזֶפֶק, וּקְלִיפָה דְּקֻרְקְבָן אִינּוּן רְשִׁימִין עוֹפִין לְמֵיכַל, וּבְעִירָן, בִּתְרֵי סִימָנִין, מַעֲלַת גֵּרָה, וּמַפְרֶסֶת פַּרְסָה. כֻּלְּהוּ רְשִׁימִין בִּתְרֵי סִימָנִין, כְּגַוְונָא דְּעָרְלָה וּפְרִיעָה, דְּמִתְעַבְּרַן מִעַמָּא קַדִּישָׁא."],[[0,"הבור נוקבא בישא וכו':","הבור, הוא נקבה הרעה, לילית, בבית שלה שהוא בית האסורים, חטפה שפחה הרעה, את המטרוניתא ובניה, שהם ישראל, בגלות שלה, ושמה אותם בכמה שרשראות, ואסרו בניה, ידיהם מקושרים לאחור. היא ישבה בגוים וגו', ולא עוד אלא כל מכבדיה הזילוה וגו'."],[1,"ולא עוד אלא וכו':","ולא עוד אלא הקליפה הרעה, שהיא זונה שהיא הבער, דהיינו אש, ויצת אש בציון. אחר כך בא אדם בליעל, רשע, רביעי לאבות נזיקין, שהוא מבעה, שנאמר בו, אדם מועד לעולם בין ער בין ישן, ושלח את בעירו, דהיינו המחנות שלו, ואכל וכילה וקצץ כרמים ופרדסים של ירושלים, והשחית הכל."],[2,"רבון עלמא אנת וכו':","רבון העולם, אתה אמת, ותורתך אמת, נתת לנו מצות תפילין, שלצדיקים גמורים הוא שכר כפי מעשיהם, שהם פאר על ראשיהם. והם משמשים בזה את אביהם ואמם, שהם זו\"ן, כמו הגוף, שכל אבריו משמשים אל הראש. וכך האשה, שהיא המלכות ותפלה של יד, משמשת לבעלה, שהוא ז\"א."],[3,"ואית מלאכין דאינון וכו':","ויש מלאכים שהם משמשים את הגוף. ומלאכים המשמשים את הנשמה, וכמו שיש הפרש בין גוף לנשמה, כך יש הפרש בין מלאכים דגוף ומלאכים דנשמה. ויש נשמה לנשמה, ומלאכים למלאכים, כי גבוה מעל גבוה שומר וגבוהים עליהם. ואלו שהם נשמה לנשמה, שהוא מאצילות, כולם אחד, שאין בהן פירוד משהו, ואע\"פ שבדרך משל כל מדרגה תחתונה כלפי עליונה היא כגוף אל נשמה, משום שמקבלים אלו מאלו. וכך השכינה, אע\"פ שהיא כנגד שאר האורות שבעולם הבריאה, כנשמה אל גוף, כנגד הקב\"ה, שהוא ז\"א, נחשבת כגוף. אבל הכל אחד, כאן הגוף והנשמה הכל אחד. מה שאין כן באדם, שהגוף והנשמה הם בפרוד, זה חומר וזה שכל, זה חיים וזה מות, אבל הקב\"ה חיים, ושכינתו חיים. ז\"ש, עץ חיים היא למחזיקים בה."],[4,"וכל אינון דרשימין וכו':","וכל אלו הרשומים בסמנים של הקב\"ה ושכינתו, שבימות החול הם אות תפלין ואות מילה, ובשבת רשומים בזכור ושמור. ורשומים בתורה שבכתב שניתנה מימין, ובתורה שבעל פה שניתנה משמאל. והקב\"ה זכור מימין ושמור משמאל. והשכינה, זכירה מימין ושמירה משמאל. וכך הם תפלין של ראש של האדם היא מימין, ותפלין של יד. היא משמאל. וכך השכינה נקראת, תורת ה' תמימה מימין שבה, ומצוה משמאלה. וזהו מצד עמוד האמצעי, שהוא ז\"א, הכלול דין ורחמים שהם זכור ושמור, ומצדו נקראת גם המלכות זכירה ושמירה, כי מצד המצות היא שוה עמו במדרגה."],[5,"אבל מסטרא דחסד וכו':","אבל מצד החסד, הקב\"ה הוא זכור והשכינה שמור. כמו שהעמידו בעלי המשנה, זכור לזכר, ושמור לכלה. משום שבימין ושמאל שמחזה ולמעלה דז\"א, הענפים מתפרדים, כעין כנפי ריאה שהן פרודות מלעלה. וכנגדם החיות, שנאמר בהם ופניהם וכנפיהם פרודות מלמעלה, שהוא כנגד הפתוחות שבספר התורה. למטה, דהיינו מחזה ולמטה ששם הנוקבא הנקראת מצוה, שניהם, ז\"א ומלכות, הם ביחוד אחד, כמו הסתומות שבספר התורה, שאין שם פרוד. וע\"כ שניהם שוים, וכמו שז\"א נקרא זכור, נקראת גם היא זכירה ושמירה וכו' כנ\"ל. משא\"כ למעלה מחזה בימין ושמאל אשר שם, נקראת המלכות רק שמור ולא זכור. ומשום זה, במקום היחוד, שהוא גוף, דהיינו מלכות, דומה לשדרה של הלולב, אם נפרצו או נפרדו עליו פסול."],[6,"בכמה רשימין רשים וכו':","בכמה רשומות רשם הקב\"ה את ישראל, שיהיו ניכרים אל המלאכים. אלו מישראל הנמשכים מימין, תלוים בהקב\"ה. אלו שמשמאל תלוים בשכינה. או אלו התלוים בהקב\"ה ושכינתו ביחוד אחד. ומפרש, ודאי אלו שיש בהם תורה, רשומים בימין, בחסד. ואלו שיש בהם מצוה, רשומים בשמאל, בגבורה. ואלו בעלי התפילין ואות שבת ואות ברית, רשומים בצדיק, שהוא יסוד."],[7,"ובעירן עמי הארץ וכו':","ואותם מישראל, שהם, בהמות, עמי הארץ, הם רשומים בהעברת הערלה והפריעה. שהם שני סימני טהרה. וכן העופות בשני סימנים, בזפק ובקרקבן הנקלף, בהעברת הזפק, והקליפה של הקרקבן, הם רשומים בעופות לאכול. והבהמות בשני סימנים, מעלת גרה ומפרסת פרסה. כולם רשומים בשני סימנים, כמו הערלה והפריעה הנעברים מעם הקדוש."]],[[0,"","הַבּוֹר נְקֵבָה רָעָה, לִילִית, בְּבֵיתָהּ, שֶׁהִיא בֵּית הַסֹּהַר, תָּפְסָה אֶת הַגְּבִירָה וּבָנֶיהָ, הַשִּׁפְחָה רָעָה, בַּגָּלוּת שֶׁלָּהּ, וְשָׂמָה אוֹתָהּ בְּכַמָּה שַׁלְשְׁלָאוֹת, וְאָסְרוּ לְבָנֶיהָ אֶת יְדֵיהֶם מְהֻדָּקִים לְאָחוֹר. (איכה א) הִיא יָשְׁבָה בַגּוֹיִם לֹא מָצְאָה מָנוֹחַ. וְלֹא עוֹד, אֶלָּא (שם) כָּל מְכַבְּדֶיהָ הִזִּילוּהָ כִּי רָאוּ עֶרְוָתָהּ גַּם הִיא נֶאֶנְחָה וַתָּשָׁב אָחוֹר."],[1,"","וְלֹא עוֹד, אֶלָּא זוֹנָה, שֶׁהִיא הֶבְעֵר, שֶׁהַיְנוּ אֵשׁ, וַיַּצֶּת אֵשׁ בְּצִיּוֹן. אַחַר כָּךְ קָם אָדָם בְּלִיַּעַ\"ל רָשָׁע, רְבִיעִי לַאֲבוֹת הַנְּזִיקִין, שֶׁנֶּאֱמַר בּוֹ אָדָם מוּעָד לְעוֹלָם, בֵּין עֵר בֵּין יָשֵׁן, וְשִׁלַּח אֶת בְּעִירֹה, וְאָכַל וְהִשְׁמִיד וְגָדַע כְּרָמִים וּפַרְדֵּסִים שֶׁל יְרוּשָׁלַיִם, וְכִלָּה הַכֹּל."],[2,"","רִבּוֹן הָעוֹלָם, אַתָּה אֱמֶת וְתוֹרָתְךְ אֱמֶת, נָתַתָּ לָנוּ מִצְוַת תְּפִלִּין, לְצַדִּיקִים גְּמוּרִים הוּא שָׂכָר כְּפִי מַעֲשֵׂיהֶם, פְּאֵר עַל רֹאשָׁם, וּמְשַׁמְּשִׁים אֶת אֲבוֹתֵיהֶם וְאִמָּם, כְּמוֹ שֶׁהַגּוּף שֶׁכָּל אֵיבָרָיו מְשַׁמְּשִׁים אֶת הָרֹאשׁ, כָּךְ הָאִשָּׁה מְשַׁמֶּשֶׁת אֶת בַּעְלָהּ."],[3,"","וְיִשִׁ מַלְאָכִים הַמְשַׁמְּשִׁים אֶת הַגּוּף, וּמַלְאָכִים הַמְשַׁמְּשִׁים אֶת הַנְּשָׁמָה. וּכְמוֹ שֶׁיֵּשׁ הַפְרָדָה בֵּין גּוּף וּנְשָׁמָה, כָּךְ יֵשׁ הַפְרָדָהּ בֵּין הַמַּלְאָכִים שֶׁל הַגּוּף לְבֵין הַמַּלְאָכִים שֶׁל הַנְּשָׁמָה. וְיֵשׁ נְשָׁמָה לִנְשָׁמָה, וּמַלְאָכִים לְמַלְאָכִים, (קהלת ה) כִּי גָבהַּ מֵעַל גָּבֹהַּ שֹׁמֵר וּגְבֹהִים עֲלֵיהֶם. וְאֵלֶּה שֶׁהֵם נְשָׁמָה לִנְשָׁמָה, כֻּלָּם אֶחָד. וְאַף עַל גַּב שֶׁדֶּרֶךְ מָשָׁל, הֵם כְּגוּף אֵצֶל הַנְּשָׁמָה אֵלֶּה לְאֵלֶּה, מִשּׁוּם שֶׁמְּקַבְּלִים אֵלֶּה מֵאֵלֶּה. כָּךְ הַשְּׁכִינָה (הגשמה), אַף עַל גַּב שֶׁהִיא כְּנֶגֶד שְׁאָר הָאוֹרוֹת שֶׁל הַבְּרִיאָה כִּנְשָׁמָה אֵצֶל הַגּוּף, כְּנֶגֶד הַקָּדוֹשׁ בָּרוּךְ הוּא הִיא חֲשׁוּבָה כְּגוּף, אֲבָל הַכֹּל אֶחָד. כָּאן גּוּף וּנְשָׁמָה הַכֹּל אֶחָד. מַה שֶּׁאֵין כָּךְ בָּאָדָם, שֶׁגּוּפוֹ וְנִשְׁמָתוֹ בְּפֵרוּד, זֶה חֹמֶר וְזֶה שֵׂכֶל, זֶה חַיִּים וְזֶה מָוֶת. אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא חַיִּים וּשְׁכִינָתוֹ חַיִּים. זֶהוּ שֶׁכָּתוּב (משליג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ."],[4,"","וְכָל אוֹתָם שֶׁרְשׁוּמִים בְּסִימָנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ, הֵם רְשׁוּמִים בִּימֵי הַחֹל בָּאוֹת שֶׁל הַתְּפִלִּין, בָּאוֹת שֶׁל הַמִּילָה, וּרְשׁוּמִים בְּזָכוֹר וְשָׁמוֹר בְּשַׁבָּת. רְשׁוּמִים בַּתּוֹרָה שֶׁבִּכְתָב שֶׁנִּתְּנָה מִיָּמִין, וּבַתּוֹרָה שֶׁבְּעַל פֶּה שֶׁנִּתְּנָה מִשְּׂמֹאל. וְהַקָּדוֹשׁ בָּרוּךְ הוּא זָכוֹר מִיָּמִין, וְשָׁמוֹר מִשְּׂמֹאל. וְהַשְּׁכִינָה זְכִירָה מִיָּמִין, וּשְׁמִירָה מִשְּׂמֹאל. הֵן תְּפִלִּין שֶׁל רֹאשׁ שֶׁל הָאָדָם, וּתְפִלִּין שֶׁל יָד. וְכָךְ שְׁכִינָה, תּוֹרַת ה' תְּמִימָה, וְהַמִּצְוָה שֶׁלּוֹ. וְזֶה מֵהַצַּד שֶׁל הָעַמּוּד הָאֶמְצָעִי, שֶׁהוּא כּוֹלֵל דִּין וְרַחֲמִים. זָכוֹר וְשָׁמוֹר. נִקְרֵאת הִיא זְכִירָה וּשְׁמִירָה. וּבְכָל הַמִּצְווֹת הִיא שְׁקוּלָה אֵלָיו בַּמַּדְרֵגָה."],[5,"","אֲבָל מִצַּד הַחֶסֶד - הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא זָכוֹר, וְהַשְּׁכִינָה שָׁמוֹר. כְּמוֹ שֶׁבֵּאֲרוּהָ בַּעֲלֵי הַמִּשְׁנָה, זָכוֹר לְזָכָר, וְשָׁמוֹר לְכַלָּה. מִשּׁוּם שֶׁבְּיָמִין וּבִשְׂמֹאל הָעֲנָפִים מִתְפָּרְדִים, כְּמוֹ כַּנְפֵי רֵאָה שֶׁהֵן פְּרוּדוֹת מִלְמַעְלָה. כְּנֶגְדָּם חַיּוֹת, וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרֻדוֹת מִלְמָעְלָה. וּכְנֶגֶד פְּתוּחוֹת שֶׁל סֵפֶר תּוֹרָה. לְמַטָּה שְׁנֵיהֶם בְּיִחוּד אֶחָד, כְּמוֹ סְתוּמוֹת שֶׁל סֵפֶר תּוֹרָה, שֶׁאֵין שָׁם פֵּרוּד. וּמִשּׁוּם כָּךְ בְּמָקוֹם שֶׁל יִחוּד, שֶׁהוּא גּוּף, דּוֹמֶה לְשִׁדְרָה שֶׁל לוּלָב. אִם נִפְרְצוּ אוֹ נִפְרְדוּ עָלָיו - פָּסוּל."],[6,"","בְּכַמָּה רִשּׁוּמִים רָשַׁם הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל לְהִוָּדַע לַמַּלְאָכִים. אֵלּוּ מִיָּמִין, שֶׁתְּלוּיִים מֵהַקָּדוֹשׁ בָּרוּךְ הוּא, אוֹ אֵלּוּ מִשְּׂמֹאל, שֶׁתְּלוּיִים מֵהַשְּׁכִינָה, אוֹ אֵלּוּ שֶׁתְּלוּיִים מֵהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בְּיִחוּד אֶחָד. וַדַּאי אֵלֶּה שֶׁיֵּשׁ בָּהֶם תּוֹרָה רְשׁוּמִים בְּחֶסֶד, וְאֵלֶּה שֶׁיֵּשׁ בָּהֶם מִצְוָה רְשׁוּמִים בִּגְבוּרָה, וְאֵלּוּ בַּעֲלֵי הַתְּפִלִּין וְאוֹת שַׁבָּת וְאוֹת בְּרִית רְשׁוּמִים בְּצַדִּיק."],[7,"","וְהַבְּהֵמוֹת, עַמֵּי הָאָרֶץ, הֵם רְשׁוּמִים בְּהַעֲבָרַת עָרְלָה וּפְרִיעָה. עוֹפוֹת - בְּזֶפֶק וּבְקֻרְקְבָן נִקְלָף, בְּהַעֲבָרַת הַזֶּפֶק וּקְלִפַּת הַקֻּרְקְבָן, הֵם רְשׁוּמִים בָּעוֹפוֹת לֶאֱכֹל. וּבְהֵמוֹת בִּשְׁנֵי סִימָנִים - מַעֲלַת גֵּרָה וּמַפְרֶסֶת פַּרְסָה. כֻּלָּם רְשׁוּמִים בִּשְׁנֵי סִימָנִים, כְּמוֹ עָרְלָה וּפְרִיעָה, שֶׁמָּעֳבָרִים מֵהָעָם הַקָּדוֹשׁ."]]],[["אֲבָל תַּלְמִידֵי חֲכָמִים, כֻּלְּהוֹן רְשִׁימִין מִנְּהוֹן, בְּכֻרְסְיָיא. וּמִנְּהוֹן, בְּמַלְאָכֵי, בְּאַרְבַּע חֵיוָן דְּכֻרְסְיָיא. מִנְּהוֹן בְּכֹכָבַיָּא וּבְמַזָּלֵי. וּמִנְּהוֹן רְשִׁימִין, בְּמִדוֹת דְּקוּדְשָׁא בְּרִיךְ הוּא אִשְׁתְּמוֹדְעִין. וְאִינּוּן דְּמִתְעַסְּקִין בְּאוֹרַיְיתָא וּבְמִצְוֹת, לִשְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, שֶׁלֹּא עַל מְנָת לְקַבֵּל פְּרָס, אֶלָּא כִּבְרָא דְּאִיהוּ מְחוּיָיב בִּיקָרָא דַּאֲבוֹהִי וְאִמֵּיהּ, דָּא אִתְקָשָּׁר וַדַּאי וְאִתְרְשִׁים, בְּעַמּוּדָא דְּאֶמְצָעִיתָא וּשְׁכִינְתֵּיהּ, כְּאִילּוּ בֵּיהּ הֲווֹ חַד. וּמַאן דְּאִית בֵּיהּ תּוֹרָה בְּלֹא מִצְוָה, אוֹ מִצְוָה בְּלֹא תּוֹרָה, כִּבְיָכוֹל כְּאִילּוּ הֲווֹ בֵּיהּ בְּפִרוּדָא. אֲבָל בְּדָא וְדָא, כְּאִילָנָא, דְעַנְפּוֹי מִתְפָּרְדִין לִימִינָא וְלִשְׂמָאלָא, וְאִילָנָא יִחוּדָא דְּתַרְוַויְיהוּ, בְּאֶמְצָעִיתָא.","רַשִׁיעַיָּא, אִינּוּן רְשִׁימִין בְּלָא סִימָנִין דְּטָהֳרָה, אִינּוּן דְּלֵית לְהוֹן תְּפִלִּין עַל רֵישָׁא, וּדְרוֹעָא. וְאִינּוּן דְּלָא רְשִׁימִין בַּתּוֹרָה וּבַמִּצְוֹת. וְאִלֵּין דְּלָא נַטְרִין זָכוֹר וְשָׁמוֹר. וְלָא רְשִׁימִין בִּתְכֵלֶת וְלָבָן דְּצִיצִית. וְאִלֵּין דְּלָא רְשִׁימִין בְּאִלֵּין סִימָנִין, שֶׁקֶץ הֵם לָכֶם, לָאו אִינּוּן יִשְׂרָאֵל אֶלָּא עַמֵּי הָאָרֶץ. מָה אִלֵּין שֶׁקֶץ וְשֶׁרֶץ, אוּף אִינּוּן (נ\"א כן') שֶׁקֶץ וְשֶׁרֶץ. כְּמָה דְּאוּקְמוּהָ מָארֵי מַתְנִיתִין, עַמֵּי הָאָרֶץ הֵם שֶׁרֶץ, וּנְשׁוֹתֵיהֶם שֶׁקֶץ. וְעַל בְּנוֹתֵיהֶם אִתְּמַר, (דברים כ״ז:כ״א) אָרוּר שׁוֹכֵב עִם כָּל בְּהֵמָה.","וּמִיתַתְהוֹן מִיתָה בְּאִתְגַּלְיָא, וְלֵית מִיתָה אֶלָּא עֲנִיּוּתָא, וּמִיתָה דַּעֲנִיּוּתָא דִּלְהוֹן, לָא יְהֵא בְּאִתְכַּסְיָא, כְּעוֹפִין דְּדַמְיָין לְמָארֵי פִּקּוּדִין, אֶלָּא בְּאִתְגַּלְּיָיא, לְעֵינִי עַמָּא, דְּעָנִי חָשׁוּב כַּמֵּת. וְאִית עֲנִיּוּתָא בְּאִתְכַּסְיָא, מֵעֵינִי בְּנֵי נָשָׁא. וְאִית עֲנִיּוּתָא, לְעֵינִי כֹּלָּא. כִּזְרִיקוּ דְּדָם דִּבְהֵמָה, וּזְרִיקָתָהּ לְעֵינֵי כֹּלָּא, דְּשַׁפְכִין דָּמָא קָמֵי כֹּלָּא. הָכִי עֲנִיִּין שַׁפְכִין דָּמוֹי בְּאַנְפַּיְיהוּ, לְעֵינֵי בְּנִי נָשָׁא, וְאִתְהַדְּרִין יְרוֹקִין כַּמֵּתִין.","וְאִי הַדְרִין בְּתִיוּבְתָּא, וְלָא פַּתְחִין פּוּמְהוֹן לְהַטִּיחַ דְּבָרִים כְּלַפֵּי מַעְלָה וּמִיתָה דִּלְהוֹן בִּסְתִימוּ דְּפוּמָא, כִּבְעִירָא דְּאִיהִי מֵיתָא, וְלֵית לָהּ קוֹל וְדִבּוּר. וּבְוִידוּי הָכִי יִיִמָא אִיהוּ, אֵין לִי פֶּה לְהָשִׁיב, וְלא מֵצַח לְהָרִים רֹאשׁ, וְיִתְוַדֶּה וּמְיַיחֵד לְקוּדְשָׁא בְּרִיךְ הוּא בְּכָל יוֹמָא, לְמֶהֱוֵי מִיתָתֵיהּ בְּאֶחָד. כְּגַוְונָא דִּשְׁחִיטַת בְּהֵמָה, בִּתְרֵיסַר בְּדִיקוֹת דְּסַכִּין, וּבְסַכִּין דְּאִינּוּן אֶחָ\"ד.","וּמְבָרֵךָ וּמְקַדֵּשׁ לְקוּדְשָׁא בְּרִיךְ הוּא בְּכָל יוֹמָא, בְּבָרְכוּ וּבִקְדוּשָּׁה, וּבְכָל אֲכִילָה וּשְׁתִיָּה דִּילֵיהּ. כְּגַוְונָא דִּמְבָרֵךְ כַּהֲנָא, בָּרוּךְ אַתָּה, הָא בְּרָכָה. אֲשֶׁר קִדְּשָׁנוּ, הָא קְדוּשָׁה. כַּד רוּחָא מְבָרַךְ לְקוּדְשָׁא בְּרִיךְ הוּא, בְּכָל יוֹמָא בְּבָרוּך, וּמְקַדֵּשׁ לֵיהּ בִּקְדוּשָׁא דִּילֵיהּ, וּמְיַחֵד לֵיהּ בְּיִחוּדָא דְּאִיהוּ שְׁכִינְתֵּיהּ. קוּדְשָׁא בְּרִיךְ הוּא נָחִית עַל הַהוּא רוּחָא בְּכַמָּה מַשְׁרְיָין.","אֵלִיָּהוּ, וַדַּאי בַּר נָשׁ דִּמְבָרֵךְ וּמְקַדֵּשׁ, וּמְיַחֵד לְמַטְרוֹנִיתָא, כַּמָּה מַשְׁרְיָין דְּמַטְרוֹנִיתָא סַלְּקִין עִמֵּיהּ, וּמַשִּׁרְיָין דְּמַלְכָּא, נַחְתִּין לְגַבֵּיהּ. וְכֻלְּהוּ לְנַטְרָא לֵיהּ, וּלְאוֹדָעָא לֵיהּ לְהַהוּא רוּחָא, כַּמָּה חִידוּשִׁין וַעֲתִידוֹת, בְּחֶלְמִין דִּנְבוּאָה, וְכַמָּה סְתָרִים. כְּגַוְונָא דְּיַעֲקֹב, דְּאִתְּמַר בֵּיהּ, (בראשית כ״ח:י״ב) וְהִנִּה מַלְאֲכֵי אֱלֹהִים עוֹלִים וְיוֹרְדִים בּוֹ. וְעַל מַשְׁרְיָין דְּמַלְכָּא וּמַטְרוֹנִיתָא אִתְּמַר, (בראשית ל״ב:ג׳) וַיִּקְרָא שֵׁם הַמָּקוֹם הַהוּא מַחֲנַיִם. אֲבָל מַלְכָּא וּמַטְרוֹנִיתָא לָא נַחְתִּין תַּמָּן.","אָמַר אֵלִיָּהוּ, רַעְיָא מְהֵימָנָא, הָכִי הוּא וַדַּאי. אֲבָל בְּגִין דִּבְכָל פִּקּוּדָא וּפִקּוּדָא, הֲוָה אִשְׁתַּדְּלוּתָא דִּילָךְ, לְיַחֲדָא קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, בְּכָל מַשְׁרְיָין דְּעֵילָּא וְתַתָּא, הָכִי קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, וְכָל מַשִּׁרְיָיתֵיהּ עֵילָּא וְתַתָּא, מִתְיַחֲדִין בְּרוּחָא דִּילָךְ, בְּכָל פִּקּוּדָא וּפִקּוּדָא, כִּבְרָא דְּמַלְכָּא, דְּאַבָּא וְאִמָא רַחֲמִין לֵיהּ, וְנַשְׁקִין לֵיהּ, וּבַחֲבִיבוּ דִּילֵיהּ, לָא הֵמְנִין לֵיהּ בְּמַשִּׁרְיָין דִּלְהוֹן, אֶלָּא אִינּוּן גּוּפַיְיהוּ, נַטְרִין לֵיהּ.","בְּגִין דְּהַהוּא רוּחָא דִּילָךְ, מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא אִיהוּ, דְּאִיהוּ ו' כָּלִיל אַבָּא וְאִימָּא, דְּאִינּוּן יָ\"הּ. נֶפֶשׁ דִּילָךְ. בַּת יְחִידָא, מִסִּטְרָא דְּאָת ה', שְׁכִינְתָּא תַּתָּאָה, לָא זָזָת מִינָךְ. וּכְגַוְונָא דְּאַבָּא וְאִימָּא נַטְרִין בְּרָא, הָכִי נַטְרִין בְּרָתָא. בְּמַשִּׁרְיָין עִלָּאִין, דְּאִינּוּן מַחֲנַיִם. וּבְמַחֲשָׁבָה עִלָּאָה, סַלְּקִין לְרוּחָא דִּילָךְ, כְּמָה דְּאוּקְמוּהָ, יִשְׂרָאֵל עָלָה בְּמַחֲשָׁבָה, יוּ\"ד הֵ\"א וָא\"ו הֵ\"א. וְאֵימָתַי רוּחָא דִּילָךְ סְלִיקַת בְּמַחֲשָׁבָה. כַּד אִיהִי שְׁלֵימָא, וְאִתְּמַר בָּהּ, (תהילים ק״נ:ו׳) כֹּל הַנְּשָׁמָה תְּהַלֵּל יָהּ. וּבְנַפְשָׁא דְּאִיהִי ה'."],[[0,"אבל תלמידי חכמים וכו':","אבל תלמידי חכמים כולם רשומים למעלה, מהם בכסא, שהוא המלכות. ומהם במלאכים, בארבע החיות הנושאות את הכסא. מהם בככבים ומזלות ומהם רשומים במדות, בספירות, שהקב\"ה נודע בהם. ואלו העוסקים בתורה ומצות לשם הקב\"ה ושכינתו, שלא על מנת לקבל פרס, אלא כבן המחויב בכבוד אביו ואמו, זה מתקשר ודאי, ונרשם בעמוד האמצעי, שהוא הקב\"ה, ושכינתו, כאלו היו בו אחד. ומי שיש בו תורה בלא מצוה, או מצוה בלא תורה, כביכול, כאלו היו בו בפרוד. אבל בזה וזה, בתורה ומצוה, הוא כאילן שענפיו מתפרדים לימין ושמאל, והאילן הוא היחוד של שניהם באמצע."],[1,"רשיעיא אינון רשימין וכו':","הרשעים, הם רשומים בלא סימני טהרה, הם, שאין להם תפילין על הראש ועל הזרוע, והם שאינם רשומים בתורה ומצות. והם שאינם שומרים זכור ושמור. ואינם רשומים בתכלת ולבן של הציצית. ואלו שאינם רשומים בסימנים האלו, שקץ הם לכם, הם אינם ישראל, אלא עמי הארץ. מה אלו שאין להם סימני טהרה הם שקץ ושרץ, אף הם כן, שקץ ושרץ. כמו שהעמידו בעלי המשנה, עמי הארץ הם שרץ ונשותיהם שקץ, ועל בנותיהם נאמר, ארור שוכב עם בהמה."],[2,"ומיתתהון מיתה באתגליא וכו':","ומיתתם הוא מיתה בגלוי. ואין מיתה אלא עניות, והמיתה של עניות שלהם לא יהיה בסתר, כעופות המרמזים על בעלי מצות, שמכסים את דמם, אלא בגלוי לעיני העם. ומפרש. כי עני חשוב כמת, ויש עניות שהוא מכוסית מעיני בני אדם. ויש עניות לעיני כל, כמו זריקת דם בהמה, שזריקתה לעיני כל, ששופכים הדם לפני כל. כך העניים, שדמם נשפך בפניהם לעיני בני אדם ונעשים ירוקים כמתים."],[3,"ואי הדרין בתיובתא וכו':","ואם חוזרים בתשובה, ואינם פותחים פיהם להטיח דברים כלפי מעלה. והמיתה שלהם היא בסתימת פה, כבהמה, שהיא מתה ואין לה קול ודבור. ובוידוי שלהם, יאמרו כך, אין לי פה להשיב ולא מצח להרים ראש. ויתודה ויהיה מיחד להקב\"ה בכל יום, ויקבל עליו שיהיה מיתתו באחד, כעין שחיטת בהמה בי\"ב בדיקות של הסכין של שחיטה, עם הסכין עצמו, הם י\"ג, כחשבון אחד."],[4,"ומברך ומקדש וכו':","ומברך ומקדש להקב\"ה בכל יום, בברכו וקדושה, ובכל אכילה ושתיה שלו. כעין שמברך הכהן שהוא חסד. \u0003ברוך אתה\u0004 היינו ברכה. \u0003אשר קדשנו,\u0004 היינו קדושה. כשהרוח \u0003מברך\u0004 להקב\"ה בכל יום בברוך, \u0003ומקדש\u0004 לו בקדושה שלו. \u0003ומיחד\u0004 לו ביחוד שהיא שכינתו, הקב\"ה יורד על רוחההוא בכמה מחנות."],[5,"אליהו, ודאי בר נש וכו':","אמר רעיא מהימנא לאליהו. אליהו, ודאי שגם סתם בן אדם, המברך ומקדש ומיחד המטרוניתא, כמה מחנות של המטרוניתא עולים עמו, ומחנות של המלך יורדים עליו, וכולם הם לשמרו ולהודיעו לרוח ההוא כמה חדושים ועתידות בחלום של נבואה וכמה נסתרות. כמו יעקב, שנאמר בו והנה מלאכי אלקים עולים ויורדים בו. ועל המחנות של המלך ומטרוניתא נאמר ויקרא שם המקום ההוא מחנים. אבל המלך ומטרוניתא עצמם אינם יורדים שם משא\"כ הבעל תשובה הקב\"ה עצמו יורד על רוח שלו כנ\"ל."],[6,"אמר אליהו רעיא וכו':","אמר אליהו, רעיא מהימנא, כך הוא ודאי. אבל משום שבכל מצוה ומצוה היתה ההשתדלות שלך ליחד הקב\"ה ושכינתו בכל המחנות שלמעלה ומטה כך הקב\"ה ושכינתו וכל המחנות שלו של מעלה ומטה מתיחדים ברוח שלך, בכל מצוה ומצוה, כבן מלך שאביו ואמו אוהבים אותו ונושקים אותו, ובאהבה שלהם, אינם מאמינים למחנות שלהם, אלא הם עצמם שומרים אותו."],[7,"בגין דההוא רוחא וכו':","ומפרש דבריו. משום שרוח ההוא שלך הוא מצד עמוד האמצעי, דהיינו ז\"א, שהוא \u0003ו'\u0004 הכולל אבא ואמא שהם \u0003י\"ה.\u0004 נפש שלך היא בת יחידה מצד אות \u0003ה',\u0004 השכינה התחתונה, דהיינו מלכות, אינה זזה ממך. וכמו שאו\"א שומרים הבן, שהוא ז\"א, כן שומרים הבת, שהיא מלכות, במחנות העליונים, שהם מחנים. ובמחשבה העליונה, שהיא חכמה, מעלים את הרוח שלך. כמו שהעמידו, ישראל עלה במחשבה, שהיא \u0003יוד הא ואו הא.\u0004 ומתי הרוח שלך עולה במחשבה. הוא כשהוא שלם, ונאמר בו, כל הנשמה תהלל יה. ובנפש שהיא \u0003ה'\u0004 דהויה. כלומר, שגם הנפש עולה עם הרוח."]],[[0,"","אֲבָל תַּלְמִידֵי חֲכָמִים, כֻּלָּם רְשׁוּמִים מֵהֶם בַּכִּסֵּא. וּמֵהֶם בַּמַּלְאָכִים, בְּאַרְבַּע חַיּוֹת הַכִּסֵּא. מֵהֶם בַּכּוֹכָבִים וּבַמַּזָּלוֹת, וּמֵהֶם רְשׁוּמִים בַּמִּדּוֹת שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹדָע בָּהֶם. וְאוֹתָם שֶׁמִּתְעַסְּקִים בְּתוֹרָה וּמִצְווֹת לִשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא עַל מְנָת לְקַבֵּל פְּרָס, אֶלָּא כְּבֵן הַמְחֻיָּב בִּכְבוֹד אָבִיו וְאִמּוֹ, זֶה וַדַּאי נִקְשָׁר וְנִרְשָׁם בָּעַמּוּד הָאֶמְצָעִי וּשְׁכִינָתוֹ, כְּאִלּוּ בּוֹ הֵם הָיוּ אֶחָד. וּמִי שֶׁיֵּשׁ בּוֹ תּוֹרָה בְּלִי מִצְוָה אוֹ מִצְוָה בְּלִי תוֹרָה, כִּבְיָכוֹל כְּאִלּוּ הָיוּ בוֹ בְּפֵרוּד. אֲבָל בָּזֶה וְזֶה, כְּמוֹ אִילָן שֶׁעֲנָפִים נִפְרָדִים לְיָמִין וְלִשְׂמֹאל, וְהָאִילָן הַיִּחוּד שֶׁל שְׁנֵיהֶם בָּאֶמְצַע."],[1,"","הָרְשָׁעִים רְשׁוּמִים בְּלִי סִימָנֵי טָהֳרָה, אוֹתָם שֶׁאֵין לָהֶם תְּפִלִּין עַל הָרֹאשׁ וְהַזְּרוֹעַ, וְאוֹתָם שֶׁלֹּא רְשׁוּמִים בְּתוֹרָה וּמִצְווֹת, וְאֵלֶּה שֶׁלֹּא שׁוֹמְרִים זָכוֹר וְשָׁמוֹר, וְלֹא רְשׁוּמִים בִּתְכֵלֶת וְלָבָן שֶׁל צִיצִית. וְאֵלֶּה שֶׁלֹּא רְשׁוּמִים בַּסִּימָנִים הַלָּלוּ, שֶׁקֶץ הֵם לָכֶם, אֵינָם יִשְׂרָאֵל, אֶלָּא עַמֵּי הָאָרֶץ. מָה אֵלֶּה שֶׁקֶץ וְשֶׁרֶץ - אַף הֵם (כך) שֶׁקֶץ וְשֶׁרֶץ. כְּמוֹ שֶׁבֵּאֲרוּהָ בַּעֲלֵי הַמִּשְׁנָה, עַמֵּי הָאָרֶץ הֵם שֶׁרֶץ, וּנְשׁוֹתֵיהֶם שֶׁקֶץ. וְעַל בְּנוֹתֵיהֶם נֶאֱמַר, (דברים כז) אָרוּר שּכֵב עִם כָּל בְּהֵמָה."],[2,"","וּמִיתָתָם מִיתָה בְּגָלוּי, וְאֵין מִיתָה אֶלָּא עֹנִי, וּמִיתַת הָעֹנִי שֶׁלָּהֶם לֹא תִהְיֶה בְּכִסּוּי, כְּמוֹ עוֹפוֹת שֶׁדּוֹמִים לְבַעֲלֵי מִצְווֹת, אֶלָּא בְּגִלּוּי, לְעֵינֵי הָעָם, שֶׁעָנִי חָשׁוּב בְּמֵת. וְיֵשׁ עֹנִי בְּכִסּוּי מֵעֵינֵי בְּנֵי אָדָם. וְיֵשׁ עֲנִיּוּת לְעֵינֵי כֹל, כִּזְרִיקַת דַּם הַבְּהֵמָה, וּזְרִיקָתָהּ לְעֵינֵי כֹל, שֶׁשּׁוֹפְכִים דָּם לִפְנֵי הַכֹּל. כָּךְ הָעֲנִיִּים שֶׁדָּמָם נִשְׁפָּךְ בִּפְנֵיהֶם לְעֵינֵי בְּנֵי אָדָם וְנַעֲשִׂים לִירֻקִּים כְּמוֹ מֵתִים."],[3,"","וְאִם חוֹזְרִים בִּתְשׁוּבָה וְלֹא פוֹתְחִים פִּיהֶם לְהָטִיחַ דְּבָרִים כְּלַפֵּי מַעְלָה, וּמִיתָתָם בִּסְתִימַת פֶּה, כְּמוֹ בְּהֵמָה שֶׁהִיא מֵתָה וְאֵין לָהּ קוֹל וְדִבּוּר. וּבַוִּדּוּי כָּךְ הוּא יֹאמַר: אֵין לִי פֶּה לְהָשִׁיב, וְלֹא מֵצַח לְהָרִים רֹאשׁ. וְיִתְוַדֶּה, וּמְיַחֵד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל יוֹם לִהְיוֹת מִיתָתוֹ בְּאֶחָד. כְּמוֹ שְׁחִיטַת הַבְּהֵמָה בִּשְׁתֵּים עֶשְׂרֵה בְּדִיקוֹת סַכִּין, וּבְסַכִּין שֶׁהוּא אֶחָ\"ד."],[4,"","וּמְבָרֵךְ וּמְקַדֵּשׁ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל יוֹם בְּבָרְכוּ וּבִקְדֻשָּׁה, וּבְכָל אֲכִילָה וּשְׁתִיָּה שֶׁלּוֹ. כְּמוֹ שֶׁמְּבָרֵךְ הַכֹּהֵן: בָּרוּךְ אַתָּה - הֲרֵי בְּרָכָה. אֲשֶׁר קִדְּשָׁנוּ - הֲרֵי קְדֻשָּׁה. כְּשֶׁהָרוּחַ מְבָרֶכֶת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל יוֹם בְּבָרוּךְ, וּמְקַדֶּשֶׁת אוֹתוֹ בִּקְדֻשָּׁתוֹ וּמְיַחֶדֶת אוֹתוֹ בְּיִחוּד שֶׁהִיא שְׁכִינָתוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹרֵד עַל אוֹתָהּ רוּחַ בְּכַמָּה מַחֲנוֹת."],[5,"","אֵלִיָּהוּ, וַדַּאי אָדָם שֶׁמְּבָרֵךְ וּמְקַדֵּשׁ וּמְיַחֵד אֶת הַגְּבִירָה, כַּמָּה מַחֲנוֹת שֶׁל הַגְּבִירָה עוֹלִים עִמּוֹ, וּמַחֲנוֹת הַמֶּלֶךְ יוֹרְדִים אֵלָיו. וְכֻלָּם כְּדֵי לְשָׁמְרוֹ, וּלְהוֹדִיעָהּ לְאוֹתָהּ רוּחַ כַּמָּה חִדּוּשִׁים וַעֲתִידוֹת בַּחֲלוֹמוֹת בִּנְבוּאָה, וְכַמָּה סְתָרִים, כְּמוֹ שֶׁיַּעֲקֹב שֶׁנֶּאֱמַר בּוֹ, (בראשית כח) וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ. וְעַל מַחֲנוֹת הַמֶּלֶךְ וְהַגְּבִירָה נֶאֱמַר (שם לב) וַיִּקְרָא שֵׁם הַמָּקוֹם הַהוּא מַחֲנָיִם. אֲבָל הַמֶּלֶךְ וְהַגְּבִירָה לֹא יוֹרְדִים לְשָׁם."],[6,"","אָמַר אֵלִיָּהוּ, רוֹעֶה הַנֶּאֱמָן, כָּךְ זֶה וַדַּאי, אֲבָל מִשּׁוּם שֶׁבְּכָל מִצְוָה וּמִצְוָה הָיְתָה הִשְׁתַּדְּלוּת שֶׁלְּךְ לְיַחֵד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בְּכָל הַמַּחֲנוֹת שֶׁלְּמַעְלָה וּלְמַטָּה, כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ וְכָל מַחֲנוֹתָיו מַעְלָה וּמַטָּה מִתְיַחֲדִים עִם רוּחֲךְ בְּכָל מִצְוָה וּמִצְוָה, כְּבֶן הַמֶּלֶךְ שֶׁהָאָב וְהָאֵם אוֹהֲבִים אוֹתוֹ וּמְנַשְּׁקִים אוֹתוֹ, וּמֵחֲבִיבוּת שֶׁלּוֹ אֵינָם מַאֲמִינִים לְמַחֲנוֹתֵיהֶם, אֶלָּא הֵם בְּגוּפָם שׁוֹמְרִים אוֹתוֹ."],[7,"","מִשּׁוּם שֶׁאוֹתָהּ הָרוּחַ שֶׁלְּךְ הִיא מִצַּד הָעַמּוּד הָאֶמְצָעִי, שֶׁהוּא ו' כּוֹלֵל אָב וָאֵם, שֶׁהֵם י\"ה. הַנֶּפֶשׁ שֶׁלְּךְ, בַּת יְחִידָה, מִצַּד הָאוֹת ה', הַשְּׁכִינָה הַתַּחְתּוֹנָה לֹא זָזָה מִמְּךְ. וּכְמוֹ שֶׁאַבָּא וְאִמָּא שׁוֹמְרִים אֶת הַבֵּן, כָּךְ שׁוֹמְרִים אֶת הַבַּת בְּמַחֲנוֹת עֶלְיוֹנִים, שֶׁהֵם מַחֲנַיִם. וּבַמַּחֲשָׁבָה הָעֶלְיוֹנָה עוֹלִים לְרוּחֲךְ, כְּמוֹ שֶׁבֵּאֲרוּהָ, יִשְׂרָאֵל עָלָה בְּמַחֲשָׁבָה. יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. וּמָתַי רוּחֲךְ עָלְתָה בְּמַחֲשָׁבָה? כְּשֶׁהִיא שְׁלֵמָה, וְנֶאֱמַר בָּהּ (תהלים קנ) כֹּל הַנְּשָׁמָה תְּהַלֵּל יָהּ. וּבַנֶּפֶשׁ שֶׁהִיא ה'."]]],[["רוּחַ יְיָ' אִתְּמַר בֵּיהּ, (יחזקאל ל״ז:ט׳) כֹּה אָמַר יְיָ' מֵאַרְבַּע רוּחוֹת בֹּאִי הָרוּחַ. וְאִינּוּן, (ישעיהו י״א:ב׳) רוּחַ יְיָ', רוּחַ חָכְמָה וּבִינָה, רוּחַ עֵצָה וּגְבוּרָה וְגוֹ', (שלים) שָׁלוֹם בְּאַרְבַּע אַתְוָון, סָלִיק בְּמַחֲשָׁבָה, וְעִלַּת הָעִלּוֹת מְעַטֵּר לֵיהּ בְּכֶתֶר. בְּכָל הַאי יְקַר, רוּחָא דִּילָךְ, סָלִיק וְנָחִית בְּכָל לֵילְיָא. וְכָל מִלִּין דְּאִתְגַּלְּיָין (נ\"א לך בחסד ועלייהו אתמר ואתם וכו') עָל כֶּתֶר (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ', אַתֶּם, וְלָא אוּמִין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת. וּבְגִין דָּא, (שמות כ״ב:י״ט) זֹבֵחַ לֵאֱלהִים יָחֳרַם, אֱלהִים אֲחֵרִים. בִּלְתִּי לַיְיָ' לְבַדּוֹ.","זַכָּאָה עַמָּא קַדִּישָׁא, דְּאִתְקְרִיאוּ עָאנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, לְמִקְרַב גַּרְמַיְיהוּ קָרְבְּנִין קָמֵיהּ. כְּמָה דְּאִתְּמַר, (תהילים מ״ד:כ״ג) כִּי עָלֶיךָ הוֹרַגְנוּ כָּל הַיּוֹם נֶחְשַׁבְנוּ כְּצֹאן טִבְחָה. וּקַרְבִין גַּרְמַיְיהוּ כְּעָאנִין, בְּתַעֲנִיתָא. דְּמִעוּט חֶלְבָּא וְדָמָא, דְּתַעֲנִיתָא, אִיהוּ חָשִׁיב יַתִּיר מִקָּרְבְּנָא דִּבְעִירָן, דְּהֲוָה מִתְמַעֵט דָּמָא וְחֶלְבָּא וְכָל אִינּוּן אֵמוּרִין וּפְדָרִין, דְּמִתְאַכְּלִין כָּל לֵילְיָא.","זַכָּאִין אִינּוּן, (ס\"א ישראל) דִּמְקָרְבִין רוּחִין דִּלְהוֹן, קָרְבְּנִין קֳדָם יְיָ'. וּבְכָל לֵילְיָא וְלֵילְיָא, דְּרוּחָא דִּלְהוֹן הִיא הָעוֹלָה לְגַבֵּיהּ, אִי סָלִיק לָהּ, בַּתּוֹרָה וּמִצְוָה, בַּתּוֹרָה, דְּאִיהִי עֶשֶׂר אֲמִירָן, דְּאִתְיְיהִיבוּ מֵאָת י' דִּבְעֲשַׂר דִּבְּרָן, מֵאַתְוָון ה\"ה. (ס\"א בו', בשית) בְּשִׁית חוּמְשֵׁי תּוֹרָה בְּסֵפֶר בְּרֵאשִׁית. חֲמִשָׁה אִינּוּן דְּאִתְקְרִיאוּ חֲמִשָׁה חוּמְשֵׁי תּוֹרָה. שְׁתִיתָאָה סֵפֶר בְּרֵאשִׁית אִקְרֵי. וּבְמַחֲשָׁבָה דְּאִיהוּ יוּ\"ד הֵ\"א וָא\"ו הֵ\"א, דְּאִתְּמַר בֵּיהּ, יִשְׂרָאֵל עָלָה בְּמַחֲשָׁבָה. וּלְאָן אֲתָר סָלִיק. לְגַבֵּי כֶּתֶר דְּתַּמָּן עִלַּת הָעִלּוֹת, מוּפְלֵא וּמְכוּסָה.","זַכָּאָה מַאן דְּסָלִיק לֵיהּ בַּמִּצְוָה, דְּאִיהִי מִצְוַת תְּפִילִין, דִּבְּהוֹן אַרְבַּע פָּרְשִׁיּוֹת, דִּבְּהוֹן שֵׁם יְדוָֹ\"ד. י': קַדֵּשׁ לִי. ה': וְהָיָה כִּי יְבִיאֲךָ. ו': שְׁמַע יִשְׂרָאֵל. ה': וְהָיָה אִם שָׁמוֹעַ. בְּמַחֲשָׁבָה. לְקַשְּׁרָא לָהּ בְּיָד, דִּשְׁכִינְתָּא אִיהוּ י\"ה כְּלִילָא מִמַּעֲשֵׂה דְּאִיהִי ה'. וְדִבּוּר דְּאִיהִי בִּינָה, כְּלִילָא ו' סְפִירָאן. וּבְמַחֲשָׁבָה דְאִיהוּ יוּ\"ד הֵ\"א וָא\"ו הֵ\"א, יְדוָֹ\"ד. י\"ד אַתְוָון, כְּחוּשְׁבָן יָד. וְאִתְרְמִיזוּ בְּאַרְבַּע פָּרְשִׁיָין, וּבֵיתָא דִּתְפִלִין א', וּתְרֵין רְצוּעֵי דְּרֵישָׁא, (נ\"א ודידה) שֶׁבַע. דִּתְרֵין שִׁינִין תֵּשַׁע. וְקֶשֶׁר דִּרְצוּעָה עֶשֶׂר. וְד' פָּרְשִׁיָין דְּיָד, (ס\"א הרי י\"ד.) יַד דִּשְׁכִינְתָּא, יַד יְדוָֹ\"ד.","בְּגִינָהּ אִתְּמַר, (תהילים ל״א:ו׳) בְּיָדְךָ אַפְקִיד רוּחִי וְגוֹ'. רוּחַ אִתְפְּקַד לַיְדוָֹ\"ד. וְקוּדְשָׁא בְּרִיךְ הוּא נָחִית לְגַבֵּיהּ, לְקַבְּלָא לֵיהּ לְגַבֵּי שְׁכִינְתָּא. וְנַטְרֵי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ. וּמַאן גָּרִים דָּא. מַאן דִּבְכָל מִצְוָה וּמִצְוָה, סָלִיק שְׁכִינְתָּא לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא.","וְע' (ויקרא רמ\"ט ע\"ב) תֵּיבִין דְּיַעַנְךָ יְיָ' בְּיוֹם צָרָה. וּבְמָאי צְוָוחַת. אֶלָּא וַדַּאי יִשְׂרָאֵל אִית בְּהוֹן מָארֵי תּוֹרָה, מַלְאָכִים, מִסִּטְרָא דְּאַיֶּלֶת הַשַּׁחַר, דְּאִיהִי שְׁכִינְתָּא. וּתְרֵין דַּרְגִּין אִינּוּן, בֹּקֶר וְשַׁחַר, וְעָלַיְיהוּ אִתְּמַר, (תהילים ט״ז:י״א) נְעִימוֹת בִּימִינְךָ נֶצַח. (ק\"י ע\"א) בֹּקֶר דְּאַבְרָהָם, דְּאִיהוּ חֶסֶ\"ד, דָּא סָלִיק יַתִּיר בְּיוֹמָא דְּפוּרְקָנָא, אֲבָל שָׁחָר אַקְדִּים לְיוֹמָא דְּפוּרְקָנָא. וּמַאי אִיהוּ. נֶצַח, דִּשְׁכִינְתָּא מִסִּטְרֵיהּ אִתְקְרִיאַת אַיֶּלֶת הַשַּׁחַר.","וּבְגִין דָּא, ל\"מ נְצַ\"ח, תַּמָּן נֶצַ\"ח, תַּמָּן ל\"מ. דְּאִינּוּן ע' קָלִין דְּצַוָוחָת אַיֶּלֶת הַשַּׁחַר עַל בְּנָהָא, דְּאִתְתָּקַּף עָלַיְיהוּ קַדְרוּתָא בְּגָלוּתָא, שַׁחֲרוּת הַשַּׁחַר בְּע' שְׁנִין בַּתְרָאִין, (בשבעים) בְּהַהוּא זִמְנָא יִתְקַיֵּים בְּיִשְׂרָאֵל, (ישעיהו כ״ו:י״ז) כְּמוֹ הָרָה תַּקְרִיב לָלֶדֶת תָּחִיל תִּזְעַק בַּחֲבָלֶיהָ כֵּן הָיִינוּ מִפָּנֶיךָ יְיָ'. וְעַל כֵּן נְקַוֶּה לָךְ יְיָ' אֱלהֵינוּ.","וּבְהוֹן אַיֶּלֶת אֲעִילַת רֵישָׁהָא בֵּין בִּרְכָּהָא. רֵישָׁא, אִיהוּ צַדִּיק יְסוֹד עוֹלָם. בֵּין בִּרְכָּהָא דְּאִינּוּן נֶצַח וְהוֹד. וְאוּמֵי לָהּ בֵּיהּ, לְמִפְרַק לִבְנָהָא בַּבֹּקֶר, דְּאִיהוּ אַרְיֵה בֹּקֶר יְמִינָא דְּאַבְרָהָם, מָשִׁיחַ בֶּן דָּוִד דְּנָפִיק מִיהוּדָה, דְּאִתְּמַר בֵּיהּ, (בראשית מ״ט:ט׳) גּוּר אַרְיֵה יְהוּדָה. וּבְגִין דָּא, (רות ג׳:י״ג) חַי יְיָ' שִׁכְבִי עַד הַבֹּקֶר.","וּבָהּ (ישעיהו ס״ג:י״ב) מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ בּוֹקֵעַ מַיִם וְגוֹ', בְּגִין דְּתִפְאֶרֶת דַּרְגָּא דְּמֹשֶׁה גּוּפָא, וְחֶסֶד דְּרוֹעָא דִּילֵיהּ, וּמֹשֶׁה אִתְקָשָּׁר בְּע\"ב דְּאִיהוּ חֶסֶד, דַּרְגָּא דְּאַבְרָהָם. דְּהָכִי סָלִיק בְּחוּשְׁבָן ח\"י. וו\"ו מִן וַיִּסַּע וַיָּבֹא וַיֵּט, תְּלַת עַנְפֵי אֲבָהָן, ש. דְּאִתְקָשָּׁר בְּשׁ' שֶׁל מֹשֶׁה. דְּאִתְּמַר בְּהוֹן (יחזקאל א׳:י׳) וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּן וּפְנִי שׁוֹר מֵהַשְּׂמֹאל וְגוֹ', וּפְנֵי נְשֶׁר לְאַרְבַּעְתָּן. מ\"ה מִן מֹשֶׁה, וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם."],[[0,"רוח ה', אתמר וכו':","רוח הויה, נאמר בו כה אמר ה' מארבע רוחות באי הרוח. שאם כלול מד' רוחות נקרא רוח הוי\"ה, והם, רוח הויה, רוח חכמה ובינה רוח עצה וגבורה וגו', ואם הוא שלם בד' אותיות הויה, עולה במחשבה, שהיא חכמה, ועלת העלות מעטרהו בכתר. בכל הכבוד הזה, הרוח שלך עולה ויורד בכל לילה. וכל הדברים שנתגלו לך בחסד, עליהם נאמר, ואתם הדבקים בהוי\"ה וגו'. אתם, ולא אומות העולם. ומשום זה, זובח לאלהים יחרם, דהיינו לאלהים אחרים, בלתי להויה לבדו."],[1,"זכאה עמא קדישא וכו':","אשרי העם הקדוש, שנקראים צאן של הקב\"ה, להקריב עצמם קרבן לפניו, כמו שכתוב, כי עליך הורגנו כל היום נחשבנו כצאן טבחה. ומקריבים עצמם כצאן בתענית. כי מיעוט החלב והדם של התענית הוא חשוב יותר מקרבן של בהמות, שהיה מתמעט מהם דם וחלב וכל אלו אמורים ופדרים של הקרבנות הנשרפים כל הלילה."],[2,"זכאין אינון דמקרבין וכו':","אשרי הם שמקריבים הרוחות שלהם קרבנות לפני ה'. ובכל לילה ולילה שהרוח שלהם עולה אליו, אם הוא עולה \u0003בתורה ומצוה,\u0004 בתורה, שהוא עשרת הדברות שניתנו מאת \u0003י'\u0004 של הוי\"ה, שמספר עשרת הדברות הם מאותיות \u0003ה' ה'\u0004 של הויה, שבגימטריא עשרה. ב \u0003ו'\u0004 דהויה בששה חומשי תורה עם ספר בראשית. חמשה הם שנקראים חמשה חומשי תורה שחושב ב' הפסוקים של ויהי בנסוע הארון וגו' לספר בפני עצמו כדברי חז\"ל. ויש חמשה ספרים משמות והלאה, ספר הששי ספר בראשית נקרא. ואם הוא עולה \u0003במחשבה,\u0004 שהוא יוד הא ואו הא, שבג\"ר, שנאמר בו, ישראל עלה במחשבה. ולאיזה מקום עלה. אצל הכתר, ששם עלת העלות מופלא ומכוסה."],[3,"זכאה מאן דסליק וכו':","אשרי מי שעולה במצוה, שהיא מצות תפילין, שבהם ד' פרשיות, שבהם שם הוי\"ה: \u0003י'\u0004 דהויה, הוא קדש לי. \u0003ה'\u0004 דהויה, הוא והיה כי יביאך. \u0003ו'\u0004 דהויה הוא שמע ישראל, \u0003ה'\u0004 אחרונה דהויה, הוא והיה אם שמוע. שהם במחשבה, דהיינו בג\"ר, ב \u0003ראש.\u0004 ולקשר המחשבה ב \u0003יד,\u0004 שהיא השכינה, הנקראת תפלין של \u0003יד.\u0004 כי השכינה היא כלולה ממעשה, דבור, ו' ספירות ומחשבה. כלולה ממעשה שהיא \u0003ה'\u0004 דהיינו המלכות שלה, ומדיבור שהוא בינה שלה, ומן ו' ספירות שהוא ת\"ת שלה, ומן מחשבה, שהיא יוד הא ואו הא הויה, שהם י\"ד אותיות כחשבון יד. שהם ג\"ר שלה. וי\"ד אלו נרמזו: בד' פרשיות, והבית א' של התפלין של יד, וב' רצועות, הרי שבעה. וב' שינין, שבימין ושמאל של הבית של תפלין, הם תשעה. ועם הקשר של הרצועה, הם עשרה ועם ד' פרשיות שבתפלין של יד, הם י\"ד, שבשביל זה נקראת השכינה \u0003יד הויה.\u0004"],[4,"בגינה אתמר בידך וגו':","בשבילה נאמר, \u0003בידך\u0004 אפקיד רוחי וגו'. הרוח נפקד אצלה להוי\"ה, והקב\"ה יורד אליו לקבלו אצל השכינה. ושומרים אותו הקב\"ה ושכינתו, ומי גרם זה, מי שבכל מצוה ומצוה מעלה השכינה אל הקב\"ה."],[5,"וע' תיבין דיענך וגו':","וע' תיבות, שבמזמור יענך ה' ביום צרה. הרומזים על ע' קולות שנותנת האשה הכורעת לילד, שה\"ס ע' קולות שנותנת השכינה, מצערם של ישראל, לפני הגאולה. שאז הוא \u0003יום צרה.\u0004 שואל ולמה היא צועקת. ומשיב, אלא ודאי, ישראל, יש בהם בעלי תורה, ומלכים מצד אילת השחר, שהיא השכינה. ושתי מדרגות הן, \u0003בקר ושחר,\u0004 ועליהם נאמר, נעימות בימינך נצח. \u0003בקר,\u0004 של אברהם שהוא חסד זה עולה יותר ביום הגאולה עצמו, אבל \u0003שחר,\u0004 הוא מוקדם ליום הגאולה, ומי הוא, הוא נצח, שהשכינה נקראת מצדו אילת השחר."],[6,"ובגין דא למנצח וכו':","ומשום זה \u0003למנצ\"ח,\u0004 הכתוב לפני יענך ה' ביום צרה, שם יש \u0003נצ\"ח\u0004 שם יש \u0003ל\"מ.\u0004 כי למנצח הוא אותיות ל\"מ נצ\"ח. \u0003נצח,\u0004 הוא על שם שליטת \u0003השחר\u0004 שהוא נצח, \u0003ל\"מ\u0004 הם בגי' ע', שהם ע' הקולות שצועקת אילת השחר על בניה, שנתחזק עליהם השחרות בגלות, דהיינו שחרות \u0003השחר\u0004 שהוא בע' שנים האחרונות. בזמן ההוא יתקיים בישראל, כמו הרה תקריב ללדת תחיל תזעק בחבליה כן היינו מפניך ה'. ועל כן, כיון שהשכינה מצטערת עמנו, נקוה לך ה' אלקינו שתגאל אותנו."],[7,"ובהון אילת אעילת וכו':","ובהם, בע' קולות האילה, שהיא השכינה, מכנסת ראשה בין ברכיה. ראשה, זה צדיק יסוד עולם, בין ברכיה, שהן נצח והוד, ונשבע לה בו, בצדיק לגאול את בניה ב \u0003בקר,\u0004 שהוא \u0003אריה,\u0004 דהיינו חסד שנקרא אריה. \u0003בקר,\u0004 הוא ימינו של אברהם, שהוא חסד, והוא משיח בן דוד היוצא מיהודה שנאמר בו גור \u0003אריה\u0004 יהודה ומשום זה אמר הכתוב, חי ה' שכבי עד \u0003הבקר,\u0004 עד שיופיע משיח בן דוד, שהוא \u0003אריה\u0004 והוא \u0003בקר,\u0004 דהיינו אור החסד."],[8,"ובה מוליך לימין משה זרוע וגו':","משום שת\"ת, שהוא מדרגת משה, הוא גוף, הכולל כל שש הספירות חג\"ת נה\"י, וחסד הוא זרוע ימין שלו. ומשה נקשר בשם \u0003ע\"ב,\u0004 שהוא חסד, שהוא מדרגת אברהם, שכן עולה ע\"ב בחשבון ד' פעמים \u0003ח\"י:\u0004 וו\"ו, שהן ראשי תיבות מן ג' הפסוקים, ויסע ויבא ויט, שה\"ס השם ע\"ב שיש בג' ענפי אבות, שהם חג\"ת, כי ויסע הוא חסד, ויבא הוא גבורה, ויט הוא תפארת. הם ג' פעמים \u0003ח\"י,\u0004 שנקשרו ב \u0003ש'\u0004 של משה, שיש בה ג' ענפים, שה\"ס, ג' פנים, אריה שור נשר, כי נאמר בהם, ופני אריה אל הימין לארבעתן ופני שור מהשמאל וגו' ופני נשר לארבעתן. שהם חג\"ת. \u0003מ\"ה\u0004 מן משה, הוא, ודמות פניהם פני אדם, שהוא מלכות, כי אדם בגי' מ\"ה, והוא \u0003ח\"י\u0004 הרביעי. שה\"ס \u0003חי\u0004 ה' שכבי עד הבקר. שע\"י אור הבקר ישלם \u0003ח\"י\u0004 הד' שהוא מלכות, וישלם השם ע\"ב, הכולל ד' פעמים \u0003ח\"י\u0004 שבז' פנים של המרכבה, המרומזים ב \u0003ש'\u0004 של משה \u0003ובמ\"ה\u0004 של משה."]],[[0,"","בְּרוּחַ ה' נֶאֱמַר, כֹּה אָמַר ה' מֵאַרְבַּע רוּחוֹת בּאִי הָרוּחַ. וְהֵם רוּחַ ה', רוּחַ חָכְמָה וּבִינָה, רוּחַ עֵצָה וּגְבוּרָה וְגוֹ'. שָׁלֵם בְּאַרְבַּע אוֹתִיּוֹת, עָלָה בְּמַחֲשָׁבָה, וְעִלַּת הָעִלּוֹת מְעַטְּרוֹ בְּכֶתֶר. בְּכָל הַכָּבוֹד הַזֶּה רוּחֲךְ עוֹלָה וְיוֹרֶדֶת כָּל לַיְלָה, וְכָל הַדְּבָרִים שֶׁהִתְגַּלּוּ (לך בחסד, ועליהם נאמר ואתם וכו') עַל כֶּתֶר (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה'. אַתֶּם, וְלֹא אֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. וּמִשּׁוּם זֶה, (שמות כב) זבֵחַ לָאֱלֹהִים יָחֳרָם. אֱלֹהִים אֲחֵרִים. בִּלְתִּי לַה' לְבַדּוֹ."],[1,"","אַשְׁרֵי הָעָם הַקָּדוֹשׁ שֶׁנִּקְרְאוּ צֹאן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, לְהַקְרִיב אֶת עַצְמָם קָרְבָּנוֹת לְפָנָיו, כְּמוֹ שֶׁנֶּאֱמַר (תהלים מד) כִּי עָלֶיךְ הֹרַגְנוּ כָל הַיּוֹם נֶחְשַׁבְנוּ כְּצֹאן טִבְחָה. וּמַקְרִיבִים אֶת עַצְמָם כְּמוֹ צֹאן, בְּתַעֲנִית. שֶׁמִּעוּט הַחֵלֶב וְהַדָּם שֶׁבַּתַּעֲנִית חָשׁוּב יוֹתֵר מִקָּרְבַּן בְּהֵמוֹת, שֶׁהָיָה מִתְמַעֵט הַדָּם וְהַחֵלֶב וְכָל אוֹתָם אֵמוּרִים וּפְדָרִים שֶׁנֶּאֱכָלִים כָּל הַלַּיְלָה."],[2,"","אַשְׁרֵיהֶם (ישראל) שֶׁמַּקְרִיבִים אֶת רוּחָם קָרְבָּנוֹת לִפְנֵי ה', וּבְכָל לַיְלָה וְלַיְלָה שֶׁרוּחָם הִיא הָעוֹלָה אֵלָיו, אִם מַעֲלֶה אוֹתָהּ בְּתוֹרָה וּמִצְוָה, בַּתּוֹרָה שֶׁהִיא עֶשֶׂר אֲמִירוֹת, שֶׁנִּתְּנוּ מֵהָאוֹת י' שֶׁבְּעֶשֶׂר דִּבְּרוֹת, מֵאוֹתִיּוֹת ה\"ה. (בו', בששה) בְּשֵׁשׁ חֻמְשֵׁי תוֹרָה בְּסֵפֶר, בְּרֵאשִׁית. חֲמִשָּׁה הֵם שֶׁנִּקְרְאוּ חֲמִשָּׁה חֻמְשֵׁי תוֹרָה. שִׁשִּׁי נִקְרָא סֵפֶר בְּרֵאשִׁית. וּבַמַּחֲשָׁבָה שֶׁהוּא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, שֶׁנֶּאֱמַר בּוֹ יִשְׂרָאֵל עָלָה בְּמַחֲשָׁבָה. וּלְאֵיזֶה מָקוֹם עוֹלֶה? לְכֶתֶר שֶׁשָּׁם עִלַּת הָעִלּוֹת, מֻפְלָא וּמְכֻסֶּה."],[3,"","י' - קַדֶּשׁ לִי. ה' - וְהָיָה כִּי יְבִיאֲךְ. ו' - שְׁמַע יִשְׂרָאֵל. ה' - וְהָיָה אִם שָׁמוֹעַ. בַּמַּחֲשָׁבָה. לְקַשֵּׁר אוֹתָהּ בַּיָּד, שֶׁהַשְּׁכִינָה הִיא י\"ה וּכְלוּלָה מִמַּעֲשֶׂה שֶׁהִיא ה'. וְדִבּוּר שֶׁהִיא בִּינָה כְּלוּלָה ו' סְפִירוֹת. וּבַמַּחֲשָׁבָה, שֶׁהוּא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, יְהֹוָ\"ה. י\"ד אוֹתִיּוֹת, כְּחֶשְׁבּוֹן יָד. וְנִרְמְזוּ בְּאַרְבַּע פָּרָשִׁיּוֹת, וּבֵית הַתְּפִלִּין א', וּשְׁתֵּי רְצוּעוֹת הָרֹאשׁ - שֶׁבַע. שֶׁשְּׁנֵי שִׁינִי\"ן תֵּשַׁע, וְקֶשֶׁר הָרְצוּעָה עֶשֶׂר. וְאַרְבַּע פָּרָשִׁיּוֹת הַיָּד - הֲרֵי י\"ד, יַד הַשְּׁכִינָה, יַד יְהֹוָ\"ה."],[4,"","בִּשְׁבִילָהּ נֶאֱמַר, (שם לא) בְּיָדְךְ אַפְקִיד רוּחִי וְגוֹ'. הָרוּחַ נִפְקְדָה לַיהֹוָ\"ה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹרֵד אֵלָיו לְקַבְּלוֹ לַשְּׁכִינָה, וְשׁוֹמְרִים אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ. וּמִי גוֹרֵם אֶת זֶה? מִי שֶׁבְּכָל מִצְוָה וּמִצְוָה מַעֲלֶה שְׁכִינָה אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא."],[5,"","וְשִׁבְעִים תֵּבוֹת שֶׁל יַעַנְךְ ה' בְּיוֹם צָרָה, וּבַמָּה הִיא צוֹוַחַת? אֶלָּא וַדַּאי בְּיִשְׂרָאֵל יֵשׁ בַּעֲלֵי תוֹרָה, מַלְאָכִים, מִצַּד שֶׁל אַיֶּלֶת הַשַּׁחַר, שֶׁהִיא שְׁכִינָה. וּשְׁתֵּי דְרָגוֹת הֵן - בֹּקֶר וְשַׁחַר, וַעֲלֵיהֶן נֶאֱמַר (תהלים טז) נְעִמוֹת בִּימִינְךְ נֶצַח. בֹּקֶר שֶׁל אַבְרָהָם, שֶׁהוּא חֶסֶ\"ד, זֶה עוֹלֶה יוֹתֵר בְּיוֹם הַגְּאֻלָּה, אֲבָל הַשַּׁחַר מַקְדִּים לְיוֹם הַגְּאֻלָּה, וּמִיהוּ? נֶצַח, שֶׁשְּׁכִינָה מִצִּדּוֹ נִקְרֵאת אַיֶּלֶת הַשַּׁחַר."],[6,"","וּמִשּׁוּם כָּךְ, ל\"מ נֶצַח, שָׁם נֶצַ\"ח, שָׁם ל'\"'מ, שֶׁהֵם שִׁבְעִים הַקּוֹלוֹת שֶׁצּוֹוַחַת אַיֶּלֶת הַשַּׁחַר עַל בָּנֶיהָ, שֶׁהִתְחַזֵּק עֲלֵיהֶם הַקַּדְרוּת בַּגָּלוּת, שַׁחֲרוּת הַשַּׁחַר בְּשִׁבְעִים הַשָּׁנִים הָאַחֲרוֹנוֹת. (בשבעים) בְּאוֹתוֹ זְמַן יִתְקַיֵּם בְּיִשְׂרָאֵל, (ישעיה כו) כְּמוֹ הָרָה תַּקְרִיב לָלֶדֶת תָּחִיל תִּזְעַק בַּחֲבָלֶיהָ כֵּן הָיִינוּ מִפָּנֶיךְ ה'. וְעַל כֵּן נְקַוֶּה לָךְ ה' אֱלֹהֵינוּ:"],[7,"","וּבָהֶם הָאַיֶּלֶת מַכְנִיסָה רֹאשָׁהּ בֵּין בִּרְכֶּיהָ. הָרֹאשׁ הוּא צַדִּיק יְסוֹד עוֹלָם. בֵּין בִּרְכֶּיהָ שֶׁהֵם נֶצַח וְהוֹד. וְנִשְׁבַּע לָהּ בּוֹ לִפְדּוֹת אֶת בָּנֶיהָ בַּבֹּקֶר, שֶׁהִיא אַרְיֵה, בֹּקֶר יָמִין שֶׁל אַבָרָהָם, מָשִׁיחַ בֶּן דָּוִד שֶׁיּוֹצֵא מִיהוּדָה, שֶׁנֶּאֱמַר בּוֹ (בראשית מט) גּוּר אַרְיֵה יְהוּדָה. וּמִשּׁוּם זֶה (רות ג) חַי ה' שִׁכְבִי עַד הַבֹּקֶר."],[8,"","וּבָהּ (ישעיה סג) מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ בּוֹקֵעַ מַיִם וְגוֹ'. מִשּׁוּם שֶׁתִּפְאֶרֶת הִיא דַּרְגַּת מֹשֶׁה, הַגּוּף, וְחֶסֶד זְרוֹעוֹ, וּמֹשֶׁה נִקְשַׁר בְּע\"ב שֶׁהוּא חֶסֶד, דַּרְגָּתוֹ שֶׁל אַבְרָהָם. שֶׁכָּךְ עוֹלֶה בְּחֶשְׁבּוֹן ח\"י - וו\"ו מִן וַיִּסַּע וַיָּבֹא וַיֵּט, שְׁלֹשֶׁת עַנְפֵי הָאָבוֹת. ש, שֶׁנִּקְשְׁרָה בַּש' שֶׁל מֹשֶׁה, שֶׁנֶּאֱמַר בָּהֶם (יחזקאל א) וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּם וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל וְגוֹ', וּפְנֵי נֶשֶׁר לְאַרְבַּעְתָּן. מ\"ה מִן מֹשֶׁה, וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם."]]],[["(ס\"א דאיהו) דְּרוֹעָא שְׂמָאלָא, אִתְּמַר בֵּיהּ, שְׂמֹאל דּוֹחָה, וִימִין מְקָרֶבֶת. דְּאַף עַל גַּב דְּאַקְדִּים בְּתִשְׁרֵי, דְּאוּקְמוּהָ בֵּיהּ מָארֵי מַתְנִיתִין, בְּתִשְׁרֵי עֲתִידִין לְהִגָּאֵל. תְּהֵא דּוֹחָה, בְּגִין דְּלָא יָמוּת מָשִׁיחַ בֶּן אֶפְרַיִם, דּוֹחָה מְתִּשְׁרֵי דְּאִיהִי שְׂמֹאל. עַד דְּיִקְרַב יָמִין, פֶּסַח דְּרוֹעָא יְמִינָא. לְקַיֵּים בָּהּ, (מיכה ז׳:ט״ו) כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת וְהַאי אִיהוּ בְּנִיסָן נִגְאֲלוּ וּבְנִיסָן עֲתִידִין לְהִגָּאֵל. לְקַיֵּים בְּהוֹן (ישעיהו נ״ד:ח׳) וּבְחֶסֶד עוֹלָם רִחַמְתִּיךְ אָמַר גֹּאֲלֵךְ יְיָ'.","וּלְבָתַר נַטְלֵי כֻּלְּהוּ מִגְּבוּרָה, דְּמִנֵּיהּ מָשִׁיחַ בֶּן אֶפְרַיִם, לְנַטְלָא נוּקְמָא מִשַּׂנְאוֹי. דְּהָכִי בָּעֵי לְנַקָּאָה עִבּוּרָא, דְּאִינּוּן יִשְׂרָאֵל, בִּימִינָא. וּלְבָתַר לְאוֹקְדָא קַשׁ, בִּשְׂמָאלָא. הֲדָא הוּא דִכְתִיב, (עובדיה א׳:י״ח) וְהָיָה בֵית יַעֲקֹב אֵשׁ וּבֵית יוֹסֵף לֶהָבָה וּבֵית עֵשָׂו לְקַשׁ וְדָלְקוּ בָּהֶם וַאֲכָלוּם. וּכְנִישׁוּ דְּעִבּוּרָא, דָּא עַמּוּדָא דְּאֶמְצָעִיתָא. בֵּיהּ (בראשית כה) וַיֵּאָסֶף (אל עמיו). לְאָן אֲתָר. לְבֵיתָא, דָּא שְׁכִינְתָּא.","אֲבָל בְּדַרְגָּא דְּמָשִׁיחַ בֶּן יוֹסֵף, אִיהוּ דְּקָא רָמִיז, (במדבר כ״ב:ד׳) עַתָּה יְלַחֲכוּ הַקָּהָל אֶת כָּל סְבִיבֹתֵינוּ כִּלְחוֹךְ הַשּׁוֹר אֵת יֶרֶק הַשָּׂדֶה. דְּעָלַיְיהוּ אִתְּמַר, (תהילים צ״ב:ח׳) בִּפְרֹחַ רְשָׁעִים כְּמוֹ עֵשֶׂב וְגוֹ'. מִפֶּסַח וְעַד תִּשְׁרֵי, יְהֵא פּוּרְקָנָא דְּאִיהוּ עַד. וּמִתַּמָּן וְאֵילָךְ יְהֵא הַשְׁמָדָה דִּלְהוֹן, (תהילים צ״ב:ח׳) לְהִשָּׁמְדָם (פורקנא) עֲדֵי עַד. (נ\"א ולא עד בכלל, אלא עד דמטי לעד, מתמן ואילך להשמדם עדי עד) כַּד מָטוּ לְתִשְׁרֵי דְּאִיהוּ שׁוֹר, בֵּיהּ כִּלְחוֹךְ הַשּׁוֹר.","וּסְמִיכָה (ס\"א דישראל ומטו דלהון בימינא וכו') דִּלְהוֹן דְּיִשְׂרָאֵל, בִּימִינָא דְּאִיהוּ אַרְיֵה. אֲבָל קִימָה דִּלְהוֹן בְּגוּפָא דְּאִילָנָא. וְהַאי אִיהוּ כָּל הַכּוֹרֵעַ כּוֹרֵעַ בְּבָרוּך, צַדִּיק. דְּאִתְּמַר בֵּיהּ בְּיוֹסֵף הַצַּדִּיק, (בראשית ל״ז:ז׳) וְהִנֵּה תְסֻבֶּינָה אֲלֻמֹּתֵיכֶם וַתִּשְׁתַּחֲוֶיןָ לַאֲלֻמָּתִי. וְהַאי אִיהוּ, (רות ג׳:י״ג) חַי יְיָ' שִׁכְבִי עַד הַבֹּקֶר. וְכָל הַזּוֹקֵף זוֹקֵף בְּשֵׁם, דַּרְגָּא דְּמֹשֶׁה רַבֵּינוּ לְעֵילָּא. (ס\"א ובמשה) וּמֹשֶׁה לְתַתָּא, בֵּיהּ יְקוּמוּן כָּל יִשְׂרָאֵל, כְּאֵבָרִין דְּגוּפָא, דְּבֵיהּ כֻּלְּהוּ זְקִיפִין בַּעֲמִידָה. וּבְהַאי אִיהוּ כָּל הַזּוֹקֵף, זוֹקֵף בְּשֵׁם, בְּגִין דְּעָלֵיהּ אִתְּמַר, (שמות לג) וָאֵדָעֲךָ בְּשֵׁם,","יְהוֹן מָשִׁיחַ בֶּן דָּוִד, דְּאִיהוּ אַרְיֵה, מִימִינֵיהּ. וּמָשִׁיחַ בֶּן יוֹסֵף, דְּאִיהוּ שׁוֹר, מִשְּׂמָאלֵיהּ. מִימִינָא אַבְרָהָם, מִשְּׂמָאלָא יִצְחָק, וְאִיהוּ נֶשֶׁר בְּאֶמְצָעִיתָא. שַׁלְשֶׁלֶת דִּלְהוֹן, מִסִּטְרָא דְּיַעֲקֹב. ש' דְּמֹשֶׁה, קְדוּשָׁה לְךָ יְשַׁלֵּשׁוּ. מִסִּטְרָא דְּאַרְיֵה, ג' אַנְפִּין דַּאֲבָהָן, אִתְקְרִיאוּ אֲרָיוֹת. בֹּקֶר. מִסִּטְרָא דִּשְׂמָאלָא אִתְקְרִיאוּ פָּרִים מְנַגְּחִים. וּמִסִּטְרָא (פ' ע\"ב) דְּאֶמְצָעִיתָא, אִתְקְרִיאוּ נְשָׁרִים. וְעָלַיְיהוּ אִתְּמַר (שמות י״ט:ד׳) וְאֶשָּׁא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים וָאָבִיא אֶתְכֶם אֵלָי. הָא אִינּוּן ט'. עֲשִׁירָאָה, וּרְבִיעָאָה, אָדָם (מה שמו) דְּמֹשֶׁה דְּרָכִיב עַל תְּלַת חֵיוָון.","וְאִתְּמַר בְּיִשְׂרָאֵל, (בראשית א׳:כ״ו) וְיִרְדוּ בִדְגַּת הַיָּם, מְמָנָן דְּיַמָּא, בְּסִטְרָא דְּנָחָשׁ, דְּהֲוָה שָׂרָה דְּמִצְרַיִם, דְּאִתְפָּשַּׁט בְּגָלוּתָא בַּתְרָאָה, מִיָּם עַד יָם. וּבְעוֹף הַשָּׁמַיִם, עִרְבּוּבְיָא בִּישָׁא. עֲמָלֵקִים, (בראשית ר\"ה ע\"א) נְפִילִים, תַּעֲרוֹבֶת דְּכָל אוּמִין, בְּכָל סִטְרָא, בְּגָלוּתָא בַּתְרָאָה, בֵּין בְּיִשְׂרָאֵל, בֵּין בְּיִשְׁמָעֵאל, בֵּין בְּעֵשָׂו. (באומות העולם) וּבַבְּהֵמָה, אִלֵּין בְּנֵי עֵשָׂו. דְּשׁוּלְטָנְתְּהוֹן בְּכָל הָאָרֶץ.","וְיִתְקַיֵּים בְּמָשִׁיחַ, (תהילים ע״ב:ח׳) וְיֵּרְדְּ מִיָּם עַד יָם וּמִנָּהָר עַד אַפְסֵי אָרֶץ. וְהָכִי בְּב' מְשִׁיחִין, וְהָכִי בְּיִשְׂרָאֵל, וְכֹלָּא בִּזְכוּת מ\"ה (שמו) דְּמֹשֶׁה. וְיֵיתוּן, נֵס דְּמָשִׁיחַ בֶּן דָּוִד, מִיהוּדָה, אַרְיֵה רָשִׁים עָלֵיהּ, וְנִס דְּמָשִׁיחַ בֶּן יוֹסֵף, שׁוֹר רָשִׁים עָלֵיהּ. וְנֵס דְּשִׁילה, אַרְיֵה לִימִינָא, שׁוֹר לִשְׂמָאלָא, נֶשֶׁר בְּאֶמְצָעִיתָא, וְאָדָם עַל כֻּלְּהוּ. וְד' אַנְפִּין לְכָל חַד. ד' שְׁבָטִין דְּג' חֵיוָן, י\"ב. וּלְגַבֵּי אָדָם, דְּאִיהוּ מַה שְּׁמוֹ, בְּנֵי מֹשֶׁה, דִּבְהַהוּא זִמְנָא יִתְקְיָים בְּמֹשֶׁה (במדבר י״ד:י״ב) וְאֶעֱשֶׂה אוֹתְךָ לְגוֹי גָּדוֹל וְעָצוּם מִמֶּנּוּ. בְּהַהוּא זִמְנָא, (קהלת ג') מַ\"ה שֶׁ\"הָיָה הוּ\"א שֶׁיִּהְיֶה. (קהלת ג׳:ט״ו) וַאֲשֶׁר לִהְיוֹת כְּבָר הָיָה.","וְהָאֱלהִים יְבַקֵּשׁ אֶת נִרְדָּף, יִשְׂרָאֵל דְּאִתְּמַר בְּהוֹן, (יחזקאל לה) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם, הֲווֹ נִרְדָּפִים קדַם עֵרֶב רַב, זְאֵבִים בִּישִׁין, הָא (בראשית מ״ט:כ״ז) בִּנְיָמִין זְאֵב יִטְרָף לְגַבַּיְיהוּ, דְּטָרִיף לוֹן, וְיִתְקַיֵּים בְּהַהוּא זִמְנָא, בַּבֹּקֶר יֹאכַל עַד. דְּהַיְינוּ עַד כִּי יָבֹא שִׁילֹה, וְדָא בֹּקֶר דְּאַבְרָהָם. וּלָעֶרֶב יְחַלֵּק שָׁלָל דָּא עֶרֶב דְּיִצְחָק, דְּתַּמָּן תְּרֵין מְשִׁיחִין. בְּחַד יֵיכוּל (ס\"א ממונא) מְמָנָא דְּאוּמִין דְּעָלְמָא. וּבְחַד יְחַלֵּק לוֹן לְיִשְׂרָאֵל.","יִשְׂרָאֵל דְּאִינּוּן אַיֶּלֶת, נִרְדָּפִין קֳדָם רַשִּׁיעַיָּא אֲרָיוֹת. וְיִתְּעַר נַפְתָּלִי, דְּאִיהוּ אַיָּלָה שְׁלוּחָה הַנּוֹתֵן אִמְרֵי שָׁפֶר. יִתְּעַר בִּימִינָא דְּאִיהוּ אַרְיֵה מָשִׁיחַ בֶּן דָּוִד, דְּאִתְּמַר בֵּיהּ, (בראשית מ״ט:ט׳) גּוּר אַרְיֵה יְהוּדָה מִטֶּרֶף בְּנִי עָלִיתָ. וְיְחזְקוּן (ד\"א ויחזור) עַל אוּמִין דְּעָלְמָא, כָּרַע שָׁכַב עָלַיְיהוּ, לְמִטְרַף לוֹן מִי יְקִימֶנּוּ, בְּהַהוּא זִמְנָא נֶחזֵי מַאן הוּא אֱלֹהַּ אַחֲרָא, דְּיָקִים לֵיהּ מִלִּטְרוֹף עָלַיְיהוּ, אוֹ אוּמָה וְלִישָׁן."],[[0,"דרועא שמאלא אתמר וכו':","זרוע השמאל, שהוא גבורה, נאמר בו שמאל דוחה וימין מקרבת. שאע\"פ שהקדים זמן הגאולה לחדש תשרי, שהעמידו בו בעלי המשנה, בתשרי עתידים להגאל. אמנם כיון שתשרי הוא שמאל לחדשים, תהיה דוחה את הגאולה, כדי שלא ימות משיח בן אפרים, בדינים של השמאל. כי משיח בן אפרים, הוא גלגול של ירבעם, שיש קטרוגים עליו מחמת שחטא והחטיא את הרבים. וע\"כ דוחה מתשרי (כצ\"ל) שהוא שמאל עד דיקרב הימין, שהוא פסח, זרוע ימין, דהיינו חסד. ואז יגאלו, לקיים בהם, כימי צאתך מארץ מצרים אראנו נפלאות. וזה הוא, בניסן נגאלו ובניסן עתידים להגאל. לקיים בהם ובחסד עליון רחמתיך אמר גאלך ה'."],[1,"ולבתר נטלי כלהו וכו':","ואח\"כ נוטלים כולם מגבורה, שממנו הוא משיח בן אפרים, שבא לקבל נקמה משונאיו. כי כך צריכים תחלה לנקות התבואה, שהוא ישראל, בימין. ואח\"כ לשרוף הקש, שהוא בשמאל, ז\"ש והיה בית יעקב אש ובית יוסף להבה ובית עשו לקש ודלקו בהם ואכלום. ואסיפת התבואה היא בעמוד האמצעי שבו נאמר ויאסף, לאיזה מקום נאסף. לבית, שהוא השכינה."],[2,"אבל בדרגא דמשיח וכו':","אבל במדרגת משיח בן יוסף, הוא שרומז, עתה ילחכו הקהל את כל סביבותינו כלחוך \u0003השור\u0004 את ירק השדה, דהיינו משיח בן יוסף שנקרא שור. שעליהם נאמר, בפרח רשעים כמו עשב וגו'. מפסח עד תשרי תהיה הגאולה, שנקראת \u0003עד,\u0004 ומשם ואילך תהיה השמדה שלהם, כמ\"ש להשמדם עדי עד. עד שמגיע לתשרי, שהוא שור, בו יתקיים כלחוך \u0003השור.\u0004"],[3,"וסמיכה דלהון דישראל וכו':","והסמיכה שלהם, של ישראל בזמן הגלות, הוא בימין, שהוא אריה, חסד. אבל הקימה שלהם הגאולה הוא בגוף האילן, שהוא ז\"א, וזה הוא, \u0003כל הכורע כורע בברוך,\u0004 שהוא צדיק, דהיינו יסוד, שנאמר בו ביוסף הצדיק, והנה תסבנה אלומותיכם ותשתחוין לאלומותי. וזה הוא חי ה' שכבי עד הבקר. שלהיותם בחינת כריעה ושכיבה, הם צריכים לסמיכה בחסדים מן היסוד. \u0003וכל הזוקף זוקף בשם,\u0004 שהוא מדרגת משה רבינו למעלה, דהיינו דעת, ומשה למטה, דהיינו ת\"ת. בו יקומו כל ישראל, כאברי הגוף, שכולם זקופים בו בעת שהוא בעמידה. ובזה הוא כל הזוקף זוקף בשם, שעליו נאמר, ואדעך בשם."],[4,"יהון משיח בן דוד וכו':","משיח בן דוד שהוא אריה, חסד, יהיה מימינו של משה, משיח בן יוסף, שהוא שור, גבורה, משמאלו דהיינו בסוד ג' קוין, שמימין אברהם, שהוא חסד, ומשמאל יצחק שהוא גבורה, ומשה עצמו שהוא נשר, תפארת, הוא באמצע. שלשלת שלהם, דהיינו ג' הקוין המכונים שלשלת, הוא מצד יעקב, כלומר, שהם ג' קוין הכלולים ביעקב שהיא ת\"ת, וה\"ס \u0003ש\u0004 של משה הרומזים על ג' קוין הכלולים במשה, שהוא קו האמצעי, דעת. שז\"ס, קדושה לך ישלשו, שפירושו, שכל קו כלול משלשתם, שמצד \u0003אריה,\u0004 שהוא חסד, יש ג' פנים של האבות חג\"ת, ונקראים שלשתם, אריות. בקר, היינו מן ג' פנים הכלולים בצד שמאל, נקראים שלשתם פרים מנגחים. וג' פנים הכלולים בעמוד האמצעי, שהוא משה ויעקב, נקראים נשרים. ועליהם נאמר ואשא אתכם על כנפי נשרים ואביא אתכם אלי. ונמצא שג' קוין אלו הם ט', שכל אחד כלול משלשה. והעשירית, או הרביעית לג' קוין הכוללים, היא אדם שהוא מ\"ה בשמו של משה, הרוכב על ג' חיות, אריה שור נשר. שהם ג' ענפי \u0003ש'\u0004 שבשמו דמשה."],[5,"ואתמר בישראל וכו':","ונאמר בישראל, \u0003וירדו בדגת הים,\u0004 היינו הממונים שבים שהם מצד הנחש, שהוא השר של מצרים שנתפשט בגלות האחרונה. מים עד ים. \u0003ובעוף השמים,\u0004 היינו ערב רע, מן עמלקים נפילים, תערובת של כל האומות בגלות האחרונה, בכל צד, בין בישראל, בין בישמעאל, בין בעשו. \u0003ובבהמה,\u0004 אלו הם בני עשו, שממשלתם בכל הארץ."],[6,"ויתקיים במשיח וכו':","ויתקיים במשיח, וירד מים עד ים ומנהר עד אפסי ארץ. וכך בב' משיחים, וכך בישראל. והכל בזכות \u0003מ\"ה\u0004 דמשה, שהוא פני אדם, ויבואו, דגל של משיח בן דוד, שהוא מיהודה. שאריה רשום עליו והדגל של משיח בן יוסף, אשר שור רשום עליו, והדגל של שילה, שהוא משה שהוא בגי' שילה, הוא אריה לימין שור לשמאל נשר באמצע, כי משה ה\"ס נשר, דהיינו קו האמצעי, הכולל בתוכו ימין ושמאל, ואדם על כולם, שבכל אחד מג' פנים כלול בו אדם, שד' פנים לכל אחד מג' חיות, שה\"ס ד' שבטים, שבכל אחד מהם ג' חיות, אריה שור נשר, שהם י\"ב. ואצל פני אדם שהוא \u0003מ\"ה\u0004 שמו, דהיינו שהוא בגי' מ\"ה יהיו בני משה, שבזמן ההוא יתקיים במשה, ואעשך לגוי גדול ועצום ממנו. בזמן ההוא, \u0003מ\"ה שהיה הוא שיהיה.\u0004 דהיינו משה, שהיה גואל במצרים, הוא שיהיה גואל לעתיד. \u0003ואשר להיות כבר היה,\u0004 דהיינו ב' משיחים, בן יוסף ובן דוד, כבר היו, כי כבר היה יוסף וכבר היה דוד."],[7,"והאלקים יבקש את נרדף:","היינו ישראל, שנאמר בהם, ואתנה צאני צאן מרעיתי אדם אתם. שהיו נרדפים לפני הערב רב, זאבים הרעים, הרי בנימין זאב יטרף לנגדם, שטורף אותם. ויתקיים בעת ההוא, בבקר יאכל \u0003עד,\u0004 דהיינו \u0003עד\u0004 כי יבא שילה, שהוא משה, \u0003ובקר,\u0004 זה הוא בקר דאברהם, שהוא החסד. כלומר, בבקר, בעת שיתגלה החסד הגדול, יתגלה \u0003עד\u0004 שהוא משה. ולערב יחלק שלל, זהו ערב של יצחק, שהוא המלכות הנבנית מקו שמאל, ששם ב' המשיחים. בימינה משיח בן דוד ובשמאלה משיח בן יוסף. באחד, יאכל וישחית הממונים של אומות העולם שזה מב\"י, ובאחד יחלק אותם לישראל, שהוא מב\"ד."],[8,"ישראל דאינון אילת וכו':","ישראל שהם, אילה, נרדפים מן הרשעים שהם אריות. ויתעורר נפתלי שהוא אילה שלוחה הנותן אמרי שפר, יתעורר בימין, שהוא אריה, משיח בן דוד, שנאמר בו, \u0003גור אריה יהודה מטרף בני עלית.\u0004 ויחזור על אומות העולם, \u0003כרע שכב,\u0004 עליהם לטרוף אותם. \u0003מי יקימנו,\u0004 פירושו, שבזמן ההוא, מי הוא אל אחר שיקים אותו ולא יתן לו לטרוף אותם. או אומה ולשון שיוכלו לקום אותו מלטרוף אותם."]],[[0,"","בִּזְרוֹעַ שְׂמֹאל נֶאֱמַר שְׂמֹאל דּוֹחָה, וְיָמִין מְקָרֶבֶת. שֶׁאַף עַל גַּב שֶׁהִקְדִּים בְּתִשְׁרֵי, שֶׁבֵּאֲרוּהָ בּוֹ בַּעֲלֵי הַמִּשְׁנָה, בְּתִשְׁרֵי עֲתִידִים לְהִגָּאֵל - תִּהְיֶה דּוֹחָה, כְּדֵי שֶׁלֹּא יָמוּת מָשִׁיחַ בֶּן אֶפְרַיִם. דּוֹחֶה מִתִּשְׁרֵי שֶׁהִיא שְׂמֹאל, עַד שֶׁיִּקְרַב יָמִין, פֶּסַח זְרוֹעַ יָמִין. לְקַיֵּם בָּהּ (מיכה ז) כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת, וְזֶהוּ בְּנִיסָן נִגְאֲלוּ וּבְנִיסָן עֲתִידִין לְהִגָּאֵל, לְקַיֵּם בָּהֶם (ישעיה נד) וּבְחֶסֶד עוֹלָם רִחַמְתִּיךְ אָמַר גֹּאֲלֵךְ ה'."],[1,"","וְאַחַר כָּךְ כֻּלָּם נוֹטְלִים מִגְּבוּרָה, שֶׁמִּמֶּנָּה מָשִׁיחַ בֶּן אֶפְרַיִם, לִטֹּל נְקָמָה מִשּׂוֹנְאָיו. שֶׁכָּךְ צָרִיךְ לְנַקּוֹת אֶת הַתְּבוּאָה, שֶׁהֵם יִשְׂרָאֵל, בְּיָמִין, וְאַחַר כָּךְ לִשְׂרֹף אֶת הַקַּשׁ בִּשְׂמֹאל. זֶהוּ שֶׁכָּתוּב (עובדיה א) וְהָיָה בֵית יַעֲקֹב אֵשׁ וּבֵית יוֹסֵף לֶהָבָה וּבֵית עֵשָׂו לְקַשׁ וְדָלְקוּ בָהֶם וַאֲכָלוּם. וְכִנּוּס הַתְּבוּאָה זֶהוּ הָעַמּוּד הָאֶמְצָעִי, בּוֹ (בראשית כה) וַיֵּאָסֶף (אל עמיו). לְאֵיזֶה מָקוֹם? לַבַּיִת, זוֹ הַשְּׁכִינָה."],[2,"","אֲבָל בְּדַרְגַּת מָשִׁיחַ בֶּן יוֹסֵף הוּא רוֹמֵז, (במדברכה) עַתָּה יְלַחֲכוּ הַקָּהָל אֶת כָּל סְבִיבתֵינוּ כִּלְחֹךְ הַשּׁוֹר אֵת יֶרֶק הַשָּׂדֶה. שֶׁעֲלֵיהֶם נֶאֱמַר (תהלים צא) בִּפְרֹחַ רְשָׁעִים כְּמוֹ עֵשֶׂב וְגוֹ'. מִפֶּסַח וְעַד תִּשְׁרֵי תִּהְיֶה הַגְּאֻלָּה, שֶׁהוּא עַד. וּמִשָּׁם וְאֵילָךְ תִּהְיֶה הַשְׁמָדָתָם, לְהִשָּׁמְדָם (גאלה) עֲדֵי עַד. (ולאעדבכלל, אלאעדשמגיעלעד. משם ואילך להשמדם עדי עד) כְּשֶׁהִגִּיעוּ לְתִשְׁרֵי, שֶׁהוּא שׁוֹר, בּוֹ כִּלְחֹךְ הַשּׁוֹר."],[3,"","וּסְמִיכָתָם (של ישראל והנטיה שלהם בימין) שֶׁל יִשְׂרָאֵל בְּיָמִין, שֶׁהוּא אַרְיֵה. אֲבָל הַקִּימָה שֶׁלָּהֶם בְּגוּף הָאִילָן. וְזֶהוּ כָּל הַכּוֹרֵעַ כּוֹרֵעַ בְּבָרוּךְ, צַדִּיק. שֶׁנֶּאֱמַר בּוֹ בְּיוֹסֵף הַצַּדִּיק, (בראשית לז) וְהִנֵּה תְסֻבֶּינָה אֲלֻמֹּתֵיכֶם וַתִּשְׁתַּחֲוֶיןָ לַאֲלֻמָּתִי. וְזֶהוּ (רות ג) חַי ה' שִׁכְבִי עַד הַבֹּקֶר. וְכָל הַזּוֹקֵף זוֹקֵף בַּשֵּׁם - דַּרְגַּת מֹשֶׁה רַבֵּנוּ לְמַעְלָה. (ובמשה) וּמֹשֶׁה לְמַטָּה, בּוֹ יָקוּמוּ כָּל יִשְׂרָאֵל כְּמוֹ אֵיבָרִים שֶׁל הַגּוּף, שֶׁבּוֹ כֻּלָּם זְקוּפִים בַּעֲמִידָה. וּבָזֶה הוּא כָּל הַזּוֹקֵף זוֹקֵף בַּשֵּׁם, מִשּׁוּם שֶׁעָלָיו נֶאֱמַר (שמות לג) וָאֵדָעֲךְ בְּשֵׁם."],[4,"","יִהְיוּ מָשִׁיחַ בֶּן דָּוִד, שֶׁהוּא אַרְיֵה, מִימִינוֹ, וּמָשִׁיחַ בֶּן יוֹסֵף, שֶׁהוּא שׁוֹר, מִשְּׂמֹאל. מִיָּמִין אַבְרָהָם, מִשְּׂמֹאל יִצְחָק, וְהוּא הַנֶּשֶׁר בָּאֶמְצַע. הַשַּׁלְשֶׁלֶת שֶׁלָּהֶם מִצַּד שֶׁל יַעֲקֹב. ש' שֶׁל מֹשֶׁה, קְדֻשָּׁה לְךְ יְשַׁלֵּשׁוּ. מִצַּד שֶׁל אַרְיֵה שְׁלֹשֶׁת פְּנֵי הָאָבוֹת נִקְרְאוּ אֲרָיוֹת. בֹּקֶר. מִצַּד שֶׁל שְׂמֹאל נִקְרְאוּ פָרִים מְנַגְּחִים. וּמִצַּד הָאֶמְצַע נִקְרְאוּ נְשָׁרִים, וַעֲלֵיהֶם נֶאֱמַר (שמות יט) וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים וָאָבִא אֶתְכֶם אֵלָי. הֲרֵי הֵם ט'. עֲשִׂירִי וּרְבִיעִי אָדָם (מה שמו) שֶׁל מֹשֶׁה שֶׁרוֹכֵב עַל שָׁלֹשׁ חַיּוֹת."],[5,"","וְנֶאֱמַר בְּיִשְׂרָאֵל, (בראשית א) וְיִרְדּוּ בִדְגַת הַיָּם - הַמְמֻנִּים עַל הַיָּם בַּצַּד שֶׁל הַנָּחָשׁ, שֶׁהָיָה שָׂרָהּ שֶׁל מִצְרַיִם, שֶׁהִתְפַּשֵּׁט בַּגָּלוּת הָאַחֲרוֹנָה מִיָּם עַד יָם. וּבְעוֹף הַשָּׁמַיִם - עִרְבּוּבְיָה רָעָה. עֲמָלֵקִים, נְפִילִים, תַּעֲרֹבֶת שֶׁל כָּל הָאֻמּוֹת בְּכָל צַד בַּגָּלוּת הָאַחֲרוֹנָה, בֵּין בְּיִשְׂרָאֵל, בֵּין בְּיִשְׁמָעֵאל, בֵּין בְּעֵשָׂו. וּבַבְּהֵמָה - אֵלּוּ בְּנֵי עֵשָׂו שֶׁשִּׁלְטוֹנָם בְּכָל הָאָרֶץ."],[6,"","וְיִתְקַיִּםִ בַּמָּשִׁיחַ, (תהלים עב) וְיֵרְדְּ מִיָּם עַל יָם וּמִנָּהָר עַד אַפְסֵי אָרֶץ. וְכָךְ בִּשְׁנֵי מְשִׁיחִים, וְכָךְ בְּיִשְׂרָאֵל, וְהַכֹּל בִּזְכוּת מָ\"ה (שמו) שֶׁל מֹשֶׁה. וְיָבִיאוּ נֵס שֶׁל מָשִׁיחַ בֶּן דָּוִד מִיהוּדָה - אַרְיֵה רָשׁוּם עָלָיו, וְנֵס שֶׁל מָשִׁיחַ בֶּן יוֹסֵף - שׁוֹר רָשׁוּם עָלָיו. וְנֵס שֶׁל שִׁילֹה - אַרְיֵה לְיָמִין, שׁוֹר לִשְׂמֹאל, וְנֶשֶׁר בָּאֶמְצַע, וְאָדָם עַל כֻּלָּם. וְאַרְבַּע פָּנִים לְכָל אֶחָד, אַרְבָּעָה שְׁבָטִים שֶׁל שָׁלֹשׁ חַיּוֹת - שְׁנֵים עָשָׂר. וּלְאָדָם שֶׁהוּא מַה שְּׁמוֹ, בְּנֵי מֹשֶׁה, שֶׁבְּאוֹתוֹ זְמַן יִתְקַיֵּם בְּמֹשֶׁה (במדבר יד) וְאֶעֱשֶׂה אוֹתְךְ לְגוֹי גָּדוֹל וְעָצוּם מִמֶּנּוּ. בְּאוֹתוֹ זְמַן, (קהלת ג) מַ\"ה שֶּׁ\"הָיָה ה\"וּא שֶׁיִּהְיֶה, וַאֲשֶׁר לִהְיוֹת כְּבָר הָיָה."],[7,"","וְהָאֱלֹהִים יְבַקֵּשׁ אֶת נִרְדָּף - יִשְׂרָאֵל שֶׁנֶּאֱמַר בָּהֶם (יחזקאל לד) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם, הָיוּ נִרְדָּפִים לִפְנֵי הָעֵרֶב רַב, זְאֵבִים רָעִים, הֲרֵי בִּנְיָמִין זְאֵב יִטְרַף אֲלֵיהֶם, שֶׁטּוֹרֵף אוֹתָם, וְיִתְקַיֵּם בְּאוֹתוֹ זְמַן - בַּבֹּקֶר יֹאכַל עַד, שֶׁהַיְנוּ עַד כִּי יָבא שִׁילֹה, וְזֶה בּקֶר שֶׁל אַבְרָהָם. (בראשית מט) וְלָעֶרֶב יְחַלֵּק שָׁלָל - זֶה עֶרֶב שֶׁל יִצְחָק, שֶׁשָּׁם שְׁנֵי מְשִׁיחִים. בְּאֶחָד יֹאכַל (הממון) הַמְמֻנֶּה שֶׁל אֻמּוֹת הָעוֹלָם, וּבְאֶחָד יְחַלֵּק לָהֶם לְיִשְׂרָאֵל."],[8,"","יִשְׂרָאֵל, שֶׁהֵם אַיֶּלֶת, נִרְדָּפִים לִפְנֵי הָרְשָׁעִים אֲרָיוֹת, וְיִתְעוֹרֵר נַפְתָּלִי, שֶׁהוּא אַיָּלָה שְׁלֻחָה הַנֹּתֵן אִמְרֵי שָׁפֶר. יִתְעוֹרֵר בַּיָּמִין, שֶׁהוּא אַרְיֵה, מָשִׁיחַ בֶּן דָּוִד, שֶׁנֶּאֱמַר בּוֹ גּוּר אַרְיֵה יְהוּדָה מִטֶּרֶף בְּנִי עָלִיתָ. וְיֶחֱזַק (ויחזר) עַל אֻמּוֹת הָעוֹלָם, כָּרַע שָׁכַב עֲלֵיהֶם לִטְרֹף אוֹתָם, מִי יְקִימֶנּוּ. בְּאוֹתוֹ זְמַן נִרְאֶה מִי הוּא אֱלוֹהַּ אַחֵר שֶׁיָּקִים אוֹתוֹ מִלִּטְרֹף עֲלֵיהֶם אוֹ אֻמָּה וְלָשׁוֹן."]]],[["וְיִשְׂרָאֵל דַּהֲווֹ כַּיּוֹנָה, נִרְדָּפִין קָדָם נְשֶׁר, מִסִּטְרָא דְּעוֹפִין דְּאוּמִין דְּעָלְמָא. בְּהַהוּא זִמְנָא, יִתְּעַר נֶשֶׁר, וְיִתְפְּרַשׁ גַּדְפָהָא, עַל עִרְבּוּבֵי דְּאוּמִין, וְעֵשָׂו וְיִשְׁמָעֵאל, דְּאִינּוּן עֲמָלֵקִים, וְעִרְבּוּבְיָא בִּישָׁא דְּיִשְׂרָאֵל, וְטָרִיף לוֹן, דְּלָא יִשְׁתְּאַר חַד מִנַּיְיהוּ, לְקַיֵּים מַה שֶׁנְּאֱמַר בְּיִשְׂרָאֵל, (דברים ל״ב:י״ב) יְיָ' בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר.","מִתַּמָּן וְאֵילָךְ, אֵין מְקַבְּלִים גֵּרִים, כְּמָה דְּאוּקְמוּהָ מָארֵי מַתְנִיתִין אֵין מְקַבְּלִים גֵּרִים לִימוֹת הַמָּשִׁיחַ. וְאוּמִין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת דְּעָלְמָא דְּיִשְׁתַּאֲרוּן, יִתְּעַר קוּדְשָׁא בְּרִיךְ הוּא חַיָּה דְּאָדָם, לְשַׁלְּטָאָה עָלַיְיהוּ. לְקַיְּימָא בְּהוֹן, (ישעיהו ס׳:י״ב) כִּי הַגּוֹי וְהַמַּמְלָכָה אֲשֶׁר לא יַעַבְדוּךְ יֹאבֵדוּ. לְקַיֵּים בְּיִשְׂרָאֵל, (בראשית א׳:כ״ו) וְיִּרְדוּ בִדְגַת הַיָּם וְגוֹ'. (בראשית ט׳:ב׳) וּמוֹרַאֲכֶם וְחִתְּכֶם וְגוֹ'.","וּמִסִּטְרָא דִּתְבוּאוֹת, ה' מִינֵי נָהֲמָא, תְּבִירִין מִכֻּלְּהוּ. וְאִינּוּן, חִטָּה, וּשְׂעוֹרָה, וּכֻסֶּמֶת, וְשִׁבֹּלֶת שׁוּעָל, וְשִׁיפוֹן. אִמְתִּיל לוֹן לְיִשְׂרָאֵל, הֲדָא הוּא דִכְתִיב, (ירמיהו ב׳:ג׳) קֹדֶשׁ יִשְׂרָאֵל לַיְיָ' רֵאשִׁית תְּבוּאָתֹה, בְּה'. כַּד יִפְקוּן מִגָּלוּתָא, הָכִי יְהוֹן תְּבִירִין, עַד דְּיִתְבְּרִיר אוֹכֶל מִתּוֹךְ פְּסוֹלֶת, דְּהַיְינוּ קַשׁ, עֵרֶב רַב, עַד דְּיִתְבָּרְרוּ וְיִשְׁתְּמוֹדְעוּ יִשְׂרָאֵל בֵּינַיְיהוּ, כְּבָר, דְּאִתְבְּרִיר מִגּוֹ מוֹץ וָתֶבֶן.","וְעַד דְּיִתְבְּרִירוּ מִנַּיְיהוּ, י' דְּאִיהוּ מַעֲשֵׂר, לָא שַׁרְיָא עַל ה', דְּאִיהוּ נָהֲמָא, דְּה' מִינִין, לְקַיְּימָא אוּמָאָה, (שמות י״ז:ט״ז) כִּי יָד עַל כֵּס יָ\"הּ. וּבְגִין דָּא, מוֹץ וָתֶבֶן, אֵינוֹ מְחוּיָיב בְּמַעֲשֵׂר, עַד דְּיִתְבְּרִיר. לְבָתַר דְּיִתְבְּרִיר, מִתְכַּנְּשִׁין לְהַהוּא אֲתָר דְּאִקְרֵי יְרוּשָׁלַ ם. כְּמָה דְּחִטָּה, דְּבָתַר דְּאִתְבְּרִיר קַשׁ וָתֶבֶן, מַכְנִיסִין לָהּ לָאוֹצָר. הָכִי יִתְכַּנְּשׁוּן יִשְׂרָאֵל, דְּאִינּוּן בַּר, לִיְרוּשָׁלַ ם, דְּאִיהִי בְּנוּיָה עַל הַר יְיָ', דְּאִתְּמַר בָּהּ, (תהילים כ״ד:ג׳-ד׳) מִי יַעֲלֶה בְהַר יְיָ' וּמִי יָקוּם בִּמְקוֹם קָדְשׁוֹ נְקִי כַפַּיִם וּבַר לְבָב. נָקִי כַּבָּר, דְּאִיהִי עִבּוּרָא כַּד בָּרִיר מִגּוֹ פְּסוֹלֶת. בְּהַהוּא זִמְנָא, נַשְּׁקוּ בַּר כְּדִבְקַדְמֵיתָא, דְּאִתְּמַר בֵּיהּ, (שיר השירים א׳:ב׳) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ. בַּר תַּרְגּוּם בֵּן, בְּהַהוּא זִמְנָא דִּיהוֹן נְקִיִּים כַּבָּר, מִגּוֹ קָשׁ וְתֶבֶן. שַׁרְיָא שְׁמֵיהּ עָלַיְיהוּ, וְקָרָא לוֹן, (שמות ד) בְּנִי בְכוֹרִי יִשְׂרָאֵל.","וְהָכִי מִכָּל אִילָנִין, לֵית תְּבִיר כַּגֶּפֶן. בִּנְטִיעוּ דִּילֵיהּ תְּבִיר, בַּעֲנָבִים דִּילֵיהּ תְּבִיר, דְּאִינּוּן כְּתִישִׁין בֵּין רַגְלִין. וְהָכִי זַיִת זֵיתִים דִּילָהּ כְּתִישִׁין. בְּגָלוּתָא אַמְתִּילוּ יִשְׂרָאֵל בְּהוֹן, הֲדָא הוּא דִכְתִיב, (תהילים פ׳:ט׳) גֶּפֶן מִמִּצְרַיִם תַּסִּיעַ. וְכֵן בְּגָלוּת רְבִיעָאָה, (ישעיהו ה׳:ז׳) כִּי כֶרֶם יְיָ' צְבָאוֹת בֵּית יִשְׂרָאֵל. וּכְגַוְונָא דָּא לַזַּיִת מְשׁוּלִים יִשְׂרָאֵל, (ירמיהו י״א:ט״ז) זַיִת רַעֲנָן יְפֵה פְרִי תֹאַר. וּבְגִין דָּא, (תהילים קכ״ח:ג׳) אֶשְׁתְּךָ כְּגֶפֶן פּוֹרִיָּה בְּיַרְכְּתֵי בֵיתֶךָ בָּנֶיךָ כִּשְׁתִילֵי זֵיתִים. סָמִיךְ דָּא לְדָא, בְּגִין דְּאִינּוּן תְּבִירִין בְּגָלוּתָא.","וּלְבָתַר דִּיהוֹן נְקִיִּים מִגּוֹ פְּסוֹלֶת, יִתְקַדְּשׁוּן לְבֵי מַקְדְּשָׁא, בְּיַיִן לְנַסְּכָא עַל גַּבֵּי מַדְבְּחָא, וְזֵיתִים לְאַדְלְקָא בּוֹצִינָא שְׁרָגִּין לִמְנַרְתָּא. וּמַאן זָכָה לְהַאי. יַיִן דְּלָא יִתְנְסַךְ לְכּוֹכָבִים וּמַזָּלוֹת. דְּעֵרֶב רַב אִינּוּן יַיִן דְּנִתְנְסַךְ לְכּוֹכָבִים וּמַזָּלוֹת, וּמִנְּהוֹן מְשׁוּמָדִים, מִינִים, אֶפִּיקוֹרְסִים מְשׁוּמָדִים לַעֲבֵירוֹת שֶׁבְּכָל הַתּוֹרָה כֻּלָהּ.","וְיִשְׂרָאֵל דְּאִתְּמַר בְּהוֹן (תהלים קכו) וַיִּתְעָרְבוּ בַגּוֹיִם וַיִּלְמְדוּ מַעֲשֵׂיהֶם. עַד דִּיהוֹן דְּרוּכִין בֵּין רַגְלַיְיהוּ, בְּגָלוּתָא לָא אִתְבְּרִירוּ מִנַּיְיהוּ. וּבְגִינַיְיהוּ אָמַר דָּוִד עָלָיו הֲשָׁלוֹם, (תהילים מ״ט:ו׳-ז׳) לָמָּה אִירָא בִּימֵי רָע עֲוֹן עֲקֵבַי יְסֻבֵּנִי. וְעָלַיְיהוּ אָמַר שְׁלמֹה, (שיר השירים א׳:ח׳) צְאִי לָךְ בְּעִקְבֵ\"י הַצֹּאן. בְּיַעֲקֹ\"ב. דְּעָלֵיהּ אִתְּמַר, לְגַבֵּי נָחָשׁ הַקַּדְמוֹנִי דְּפַתֵּי לְחַוָּה, (בראשית ג׳:ט״ו) הוּא יְשׁוּפְךָ רֹאשׁ וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב. בָּתַר דְּיִפְקוּן מִן גָּלוּתָא, נִמְשָׁלִים לְתַפּוּחִים, וּלְכָל רֵיחִין טָבִין. כְּגַוְונָא דְּמַפְקָנוּ דְּמִצְרַיִם, דִּכְתִּיב בֵּיהּ (שיר השירים ח׳:ה׳) תַּחַת הַתַּפּוּחַ עוֹרַרְתִּיךָ.","פִּקּוּדָא בָּתַר דָּא, לְהָבִיא בִּכּוּרִים, וַאֲבַתְרֵיהּ לְהִתְוַדּוֹת עַל הַבִּכּוּרִים, וַאֲבַתְרֵיהּ לְהִתְוַדּוֹת עַל הַמַּעֲשֵׂר. וּמָארֵי מַתְנִיתִין, מַקְשִׁים עַל הַמַּעֲשֵׂר, דְּאִי יְהֵא קֹדֶם לְקִיטָתוֹ, אוֹ אַחַר לְקִיטָתוֹ עִשּׂוּרוֹ. כְּגוֹן אֶתְרוֹג, דְּאִתְּמַר בֵּיהּ בְּאִילָן, הָלַךְ אַחַר חֲנָטָה. אִית מַאן דְּאָמַר, אַחַר בִּשּׁוּל הַפֵּירוֹת. וְאֶתְרוֹג מִקְצָתוֹ דּוֹמֶה לְאִילָן, וּמִקְצָתוֹ לַתְּבוּאָה, דְּאִינּוּן זְרָעִים, דְּאִתְּמַר בְּהוֹן, דִּלְאַחַר לְקִיטָתוֹ עִשּׂוּרוֹ. דְּאִילָן לָאו אִיהוּ, אֶלָּא עַד אַחַר גְּמַר בִּשּׁוּלוֹ."],[[0,"וישראל דהוו כיונה וכו':","וישראל, שהיו כיונה, נרדפים מפני הנשר, שהוא מצד העופות של אומות העולם, בזמן ההוא יתעורר נשר דקדושה, ויפרש כנפיו על ערב האומות ועשו וישמעאל, שהם עמלקים, וערב רע של ישראל, וטרף אותם, שלא ישאר אחד מהם, לקיים מה שנאמר בישראל, ה' בדד ינחנו ואין עמו אל נכר."],[1,"מתמן ואילך אין וכו':","משם והלאה אין מקבלים גרים, כמו שהעמידו בעלי המשנה אין מקבלים גרים לימות המשיח, ואומות העולם שישארו, יעורר הקב\"ה חיה דאדם לשלוט עליהם, לקיים בהם, כי הגוי והממלכה אשר לא יעבדוך יאבדו. ולקיים בישראל, וירדו בדגת הים וגו'. ומוראכם וחתכם וגו'."],[2,"ומסטרא דתבואות וכו':","ומצד התבואות, ה' מיני לחם השבורים מכולם, בדישה וטחינה וכו', והם חטה ושעורה וכסמת ושבלת שועל ושיפון. המשיל אותם לישראל. ז\"ש, קדש ישראל לה' ראשית תבואתה. תבואת \u0003ה\u0004 כתוב עם \u0003ה'\u0004 שיורה על ה' מיני לחם. כשיצאו ישראל מגלות יהיו שבורים כך עד שיתברר אוכל מתוך פסולת, דהיינו קש, שהוא ערב רב, עד שיתבררו ויהיו ניכרים ישראל שביניהם, שכבר נבררו מתוך מוץ ותבן."],[3,"ועד דיתברירו מנייהו וכו':","ועד שיתבררו מהם, \u0003י\u0004 שבשם הויה שהיא רומזת על מעשר, אינו שורה על \u0003ה'\u0004 דהויה, שהוא רומזת על לחם דה' מינים, לקיים השבועה, כי יד על כס \u0003יה,\u0004 שנשבע, שאין השם שלם ואין הכסא שלם עד שיכריתו זרעו של עמלק. ומשום זה מוץ ותבן אינם מחויבים במעשר עד שנתבררו. אחר שיתבררו ישראל, מתקבצים למקום ההוא הנקרא ירושלים, כמו החטה, שאחר שנברר ממנה הקש והתבן מכניסים אותה לאוצר. כך יתקבצו ישראל, שהם תבואה לירושלים, שהיא בנויה על הר ה'. שנאמר בה, מי יעלה על הר ה' ומי יקום במקום קדשו נקי כפים וגו'. נקי כמו בר, שהוא תבואה אחר שברר האוכל מתוך הפסולת. בזמן ההוא, נשקו בר, כבתחילה, שנאמר בו ישקני מנשיקות פיהו. בר, תרגום בן, שבזמן ההוא שכבר יהיו נקיים מן קש ותבן, שורה שמו עליהם, וקורא אותם בני בכורי ישראל."],[4,"והכי מכל אילנין וכו':","וכך מכל האילנות אין אילן שבור כמו גפן, בנטיעה שלו הוא שבור, שאין לו כח לעמוד אלא שוכב על הארץ, ובענבים שלו הוא שבור. שהם נכתשים בין רגלים. וכן הזית הזיתים שלו נכתשים. בגלות נמשלו להם ישראל, ז\"ש גפן ממצרים תסיע, וכן בגלות הרביעית, כי כרם ה' צבאות בית ישראל. וכעין זה משולים ישראל לזית, שכתוב, זית רענן יפה פרי תואר. ומשום זה כתוב, אשתך כגפן פוריה בירכתי ביתך בניך כשתילי זתים. סמוכים זה לזה, משום שישראל שבורים כמוהם בגלות."],[5,"ולבתר דיהון נקיים וכו':","ואחר שהענבים והזיתים יהיו נקיים מכל פסולת, יתקדשו לבית המקדש, יין לנסך על המזבח, וזיתים להדליק הנר, דהיינו הנרות של המנרה. ומי זכה לזה. יין שלא ניסך לע\"ז. כי הערב רב הם יין שניסך לעבודה זרה, ומהם משומדים מינים אפיקורסים, משומדים לעבירות שבכל התורה כולה."],[6,"וישראל דאתמר בהון וכו':","וישראל שנאמר בהם, ויתערבו בגוים וילמדו מעשיהם, ועד שיהיו דרוכים בין רגליהם בגלות, לא יתבררו מהם. ובשבילם אמר דוד, למה אירא בימי רע עון \u0003עקבי\u0004 יסבני. ועליהם אמר שלמה, צאי לך \u0003בעקבי\u0004 הצאן. בעקבי הוא אותיות ביעקב, שעליו נאמר אצל נחש הקדמוני שפתה את חוה, הוא ישופך ראש ואתה תשופנו \u0003עקב\u0004. אחר שיצאו מן הגלות נמשלים לתפוחים, ולכל ריחות טובים, כמו ביציאת מצרים, שנאמר בהם, תחת התפוח עוררתיך."],[7,"פקודא בתר דא וכו':","המצוה שלאחר זו, הוא, להביא בכורים, ואחריה, להתודות על הבכורים, ואחריה, להתודות על המעשר. ובעלי המשנה מקשים להבין על המעשר, אם יהיה לפני לקיטתו עשורו, דהיינו משעת חנטה יתעשר כדין אותה השנה, או אחר לקיטתו עשורו. כגון אתרוג, שאמרו באילן הלך אחר חנטה, ויש מי שאומר שבאתרוג הולכים אחר בישול הפירות, כי אתרוג דומה מקצתו לאילן ומקצתו לתבואה, שהם זרעים, שאמרו בהם שלאחר לקיטתו עשורו, ולא כאילן, אלא עד אחר גמר בישולו. (עי' מסכת קדושין ג' ע\"א) דהיינו אחר לקיטתו, כזרעים."]],[[0,"","וְיִשְׂרָאֵל שֶׁהָיוּ כַּיּוֹנָה, נִרְדָּפִים לִפְנֵי נֶשֶׁר מִצַּד שֶׁל הָעוֹפוֹת שֶׁל אֻמּוֹת הָעוֹלָם. בְּאוֹתוֹ זְמַן יִתְעוֹרֵר נֶשֶׁר וְיִפְרֹשׂ כְּנָפָיו עַל עִרְבּוּבֵי הָאֻמּוֹת, וְעֵשָׂו וְיִשְׁמָעֵאל, שֶׁהֵם עֲמָלֵקִים, וְעִרְבּוּבְיָה רָעָה שֶׁל יִשְׂרָאֵל, וְטוֹרֵף אוֹתָם שֶׁלֹּא יִשָּׁאֵר אֶחָד מֵהֶם, לְקַיֵּם מַה שֶּׁנֶּאֱמַר בְּיִשְׂרָאֵל, (דברים לב) ה' בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר."],[1,"","מִשָּׁם וְאֵילָךְ אֵין מְקַבְּלִים גֵּרִים, כְּמוֹ שֶׁבֵּאֲרוּהָ בַּעֲלֵי הַמִּשְׁנָה, אֵין מְקַבְּלִים גֵּרִים לִימוֹת הַמָּשִׁיחַ. וְאֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שֶׁל הָעוֹלָם שֶׁיִּשָּׁאֲרוּ, יְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא חַיָּה שֶׁל אָדָם לִשְׁלֹט עֲלֵיהֶם, לְקַיֵּם בָּהֶם (ישעיה ס) כִּי הַגּוֹי וְהַמַּמְלָכָה אֲשֶׁר לֹא יַעַבְדוּךְ יאבֵדוּ. לְקַיֵּם בְּיִשְׂרָאֵל, (בראשית א) וְיִרְדּוּ בִדְגַת הַיָּם וְגוֹ'. (שם ט) וּמוֹרַאֲכֶם וְחִתְּכֶם וְגוֹ'."],[2,"","וּמִצַד שֶׁל תְּבוּאוֹת חֲמִשָּׁה מִינֵי לֶחֶם, שְׁבוּרִים מִכֻּלָּם, וְהֵם: חִטָּה, וּשְׂעוֹרָה, וְכֻסֶּמֶת, וְשִׁבֹּלֶת שׁוּעָל, וְשִׁיפוֹן. הִמְשִׁיל אוֹתָם לְיִשְׂרָאֵל, זֶהוּ שֶׁכָּתוּב (ירמיהכ) קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה, בְּה'. כְּשֶׁיֵּצְאוּ מֵהַגָּלוּת, כָּךְ יִהְיוּ שְׁבוּרִים, עַד שֶׁיִּתְבָּרֵר אֹכֶל מִתּוֹךְ פְּסֹלֶת, שֶׁהַיְנוּ קַשׁ, עֵרֶב רַב, עַד שֶׁיִּתְבָּרְרוּ וְיִוָּדְעוּ יִשְׂרָאֵל בֵּינֵיהֶם, כְּמוֹ בַּר שֶׁנִּבְרָר מִתּוֹךְ מוֹץ וָתֶבֶן."],[3,"","וְעַד שֶׁיִּתְבָּרְרוּ מֵהֶם, י', שֶׁהִיא מַעֲשֵׂר, לֹא שׁוֹרָה עַל ה', שֶׁהוּא לֶחֶם שֶׁל חֲמִשָּׁה מִינִים, לְקַיֵּם אֶת הַשְּׁבוּעָה (שמות יז) כִּי יָד עַל כֵּס יָ\"הּ. וּמִשּׁוּם כָּךְ מוֹץ וָתֶבֶן אֵינוֹ מְחֻיָּב בְּמַעֲשֵׂר עַד שֶׁיִּתְבָּרֵר. אַחַר שֶׁיִּתְבָּרֵר, מִתְכַּנְּסִים לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא יְרוּשָׁלַיִם, כְּמוֹ שֶׁאֶת הַחִטָּה, אַחַר שֶׁנִּבְרָר קַשׁ וָתֶבֶן, מַכְנִיסִים אוֹתָהּ לְאוֹצָר. כָּךְ יִתְכַּנְּסוּ יִשְׂרָאֵל, שֶׁהֵם בַּר, לִירוּשָׁלַיִם, שֶׁהִיא בְּנוּיָה עַל הַר ה', שֶׁנֶּאֱמַר בָּהּ (תהלים כד) מִי יַעֲלֶה בְהַר ה' וּמִי יָקוּם בִּמְקוֹם קָדְשׁוֹ נְקִי כַפַּיִם וּבַר לֵבָב. נָקִי כְּמוֹ בַּר, שֶׁהִיא תְבוּאָה כְּשֶׁנִּבְרֶרֶת מִתּוֹךְ פְּסֹלֶת. בְּאוֹתוֹ זְמַן - נַשְּׁקוּ בַר, כְּבַתְּחִלָּה, שֶׁנֶּאֱמַר בּוֹ (שיר א) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ. בַּר תַּרְגּוּם בֵּן. בְּאוֹתוֹ זְמַן שֶׁיִּהְיוּ נְקִיִּים כְּמוֹ בַּר מִתּוֹךְ קַשׁ וָתֶבֶן, שׁוֹרֶה שְׁמוֹ עֲלֵיהֶם, וְקוֹרֵא לָהֶם בְּנִי בְכֹרִי יִשְׂרָאֵל."],[4,"","וְכָךְ מִכָּל הָאִילָנוֹת אֵין שָׁבוּר כַּגֶּפֶן. בִּנְטִיעָתוֹ שָׁבוּר, בַּעֲנָבָיו שָׁבוּר, שֶׁהֵם כְּתוּשִׁים בֵּין הָרַגְלַיִם. וְכָךְ זַיִת, הַזֵּיתִים שֶׁלָּהּ כְּתוּשִׁים. בַּגָּלוּת נִמְשְׁלוּ יִשְׂרָאֵל לָהֶם, זֶהוּ שֶׁכָּתוּב (תהלים פ) גֶּפֶן מִמִּצְרַיִם תַּסִּיעַ. וְכֵן בַּגָּלוּת הָרְבִיעִית, (ישעיה ה) כִּי כֶרֶם ה' צְבָאוֹת בֵּית יִשְׂרָאֵל. וּכְמוֹ זֶה יִשְׂרָאֵל מְשׁוּלִים לְזַיִת, (ירמיה יא) זַיִת רַעֲנָן יְפֵה פְרִי תֹאַר. וּמִשּׁוּם כָּךְ (תהלים קכח) אֶשְׁתְּךְ כְּגֶפֶן פֹּרִיָּה בְּיַרְכְּתֵי בֵיתֶךְ בָּנֶיךְ כִּשְׁתִלֵי זֵיתִים. סָמוּךְ זֶה לָזֶה, מִשּׁוּם שֶׁהֵם שְׁבוּרִים בַּגָּלוּת."],[5,"","וְאַחַר שֶׁיִּהְיוּ נְקִיִּים מִתּוֹךְ פְּסֹלֶת, יִתְקַדְּשׁוּ לְבֵית הַמִּקְדָּשׁ בְּיַיִן לְנַסֵּךְ עַל גַּבֵּי הַמִּזְבֵּחַ, וְזֵיתִים לְהַדְלִיק מָאוֹר נֵרוֹת לַמְּנוֹרָה. וּמִי זוֹכֶה לָזֶה? יַיִן שֶׁלֹּא הִתְנַסֵּךְ לְכּוֹכָבִים וּמַזָּלוֹת. שֶׁעֵרֶב רַב הֵם יַיִן שֶׁהִתְנַסֵּךְ לְכוֹכָבִים וּמַזָּלוֹת, וּמֵהֶם מְשֻׁמָּדִים, מִינִים, אֶפִּיקוֹרְסִים, מְשֻׁמָּדִים לָעֲבֵרוֹת שֶׁבְּכָל הַתּוֹרָה כֻּלָּהּ."],[6,"","וְיִשְׂרָאֵל שֶׁנֶּאֱמַר בָּהֶם, וַיְּתְעָרְבוּ בַגּוֹיִם וַיִּלְמְדוּ מַעֲשֵׂיהֶם. עַד שֶׁיִּהְיוּ דְרוּכִים בֵּין רַגְלֵיהֶם, בַּגָּלוּת הֵם לֹא נִבְרְרוּ מֵהֶם. וּבִשְׁבִילָם אָמַר דָּוִד, עָלָיו הַשָּׁלוֹם, (שם מט) לָמָּה אִירָא בִּימֵי רָע עֲוֹן עֲקֵבַי יְסֻבֵּנִי. וַעֲלֵיהֶם אָמַר שְׁלֹמֹה (שיר השירים א) צְאִי לָךְ בְּעִקְבֵ\"י הַצּאן. בְּיַעֲקֹ\"ב. שֶׁעָלָיו נֶאֱמַר אֶל הַנָּחָשׁ הַקַּדְמוֹנִי שֶׁפִּתָּה אֶת חַוָּה, (בראשית ג) הוּא יְשׁוּפְךְ רֹאשׁ וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב. אַחַר שֶׁיָּצְאוּ מִן הַגָּלוּת נִמְשָׁלִים לְתַפּוּחִים וּלְכָל הָרֵיחוֹת הַטּוֹבִים, כְּמוֹ שֶׁבִּיצִיאַת מִצְרַיִם, שֶׁכָּתוּב בָּהּ (שיר השירים ח) תַּחַת הַתַּפּוּחַ עוֹרַרְתִּיךְ."],[7,"","הַמִּצְוָה שֶׁאַחַר זוֹ - לְהָבִיא בִּכּוּרִים, וְאַחֲרֶיהָ - לְהִתְוַדּוֹת עַל הַבִּכּוּרִים, וְאַחֲרֶיהָ - לְהִתְוַדּוֹת עַל הַמַּעֲשֵׂר. וּבַעֲלֵי הַמִּשְׁנָה מַקְשִׁים עַל הַמַּעֲשֵׂר, שֶׁאִם יִהְיֶה קֹדֶם לְקִיטָתוֹ, אוֹ אַחַר לְקִיטָתוֹ עִשּׂוּרוֹ, כְּמוֹ אֶתְרוֹג, שֶׁנֶּאֱמַר בּוֹ בְּאִילָן, הָלַךְ אַחַר חֲנָטָה. יֵשׁ מִי שֶׁאוֹמֵר אַחַר בִּשּׁוּל הַפֵּרוֹת. וְאֶתְרוֹג מִקְצָתוֹ דּוֹמֶה לְאִילָן וּמִקְצָתוֹ לִתְבוּאָה, שֶׁהֵם זְרָעִים, שֶׁנֶּאֱמַר בָּהֶם שֶׁלְּאַחַר לְקִיטָתוֹ עִשּׂוּרוֹ. שֶׁאִילָן אֵינוֹ אֶלָּא עַד אַחַר גְּמַר בִּשּׁוּלוֹ."]]],[["וּבְגִין דָּא, תַּקִּינוּ הַמּוֹצִיא מֵאֲתָר דְּבִשׁוּלוֹ יָפֶה. לְאַפָּקָא פַּת שָׂרוּף, אֶלָּא מִמָּקוֹם שֶׁהוּא מוּטְעָם. וְהָכִי תְּבוּאָה, בָּתַר לְקִיטָתוֹ, אִיהוּ כְּבִישׁוּל פֵּירוֹת.","וְיִשְׂרָאֵל, אִינּוּן מְשׁוּלִים לָאִילָן וְלַתְּבוּאָה, דְּאִתְּמַר בְּהוֹן (שמות כ״ג:י״ט) רֵאשִׁית בִּכּוּרֵי אַדְמָתְךָ תָּבִיא בֵּית יְיָ' אֱלֹהֶיךָ. וְהָכִי (דברים י״ח:ד׳) רֵאשִׁית גֵּז צֹאנְךָ תִּתֶּן לוֹ. דְּאִינּוּן יִשְׂרָאֵל. דְּאִתְּמַר בְּהוֹן, (יחזקאל לה) וְאַתֵּן צֹאנִי. וְהָכִי יִשְׂרָאֵל, (ירמיהו ב׳:ג׳) קֹדֶשׁ (נ\"א קדש ישראל) לַיְיָ' רֵאשִׁית תְּבוּאָתֹה, לְאַחַר לְקִיטָתוֹ מִן גָּלוּתָא, עִשׂוּרֹ. וְאִתְקְרִיאוּ קֹדֶשׁ לַיְיָ'.","וְיִשְׂרָאֵל אִתְקְרִיאוּ אִילָנָא רַבָּא וְתַקִּיף, וּמָזוֹן לְכֹלָּא בֵּיהּ. בֵּיהּ אוֹרַיְיתָא, דְּאִיהִי מְזוֹנָא לְעֵילָּא. בֵּיהּ צְלוֹתָא, דְּאִיהִי מְזוֹנָא לְתַתָּא. (נ\"א לעילא) וַאֲפִילּוּ מַלְאָכִין לֵית לוֹן מְזוֹנָא, אֶלָּא בְּיִשְׂרָאֵל. דְּאִי לָאו דְּיִשְׂרָאֵל יִתְעַסְּקוּן בְּאוֹרַיְיתָא, לָא הֲוָה נָחִית לוֹן מְזוֹנָא, מִסְטַר דְּאוֹרַיְיתָא, דְּאַמְתִּילָא לָעֵץ, הֲדָא הוּא דִכְתִיב, (משלי ג׳:י״ח) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. וּלְאִיבָא, דְּאִיהִי מִצְוָה.","וְהָכִי אוֹרַיְיתָא אַמְתִּילַא לְמַיָּא. וְהָנֵי לְאֶשָּׁא. וְלָא הֲוָה נָחִית מַיָּא מִלְּעֵילָּא, וְחַמָה דְּאִיהִי אֶשָּׁא, לָא הֲוָה נָחִית (ס\"א מלעילא) לְבַשְּׁלָא פֵּירוֹת הָאִילָן. אֶלָּא, בְּגִין יִשְׂרָאֵל. וּבְגִין דָּא אִתְּמַר בְּיִשְׂרָאֵל, (שיר השירים ב׳:י״ג) הַתְּאֵנָה חָנְטָה פַגֶּיהָ, אִלֵּין מָארֵי מִצְוֹת. וְהַגְּפָנִים סְמָדָר נָתְנוּ רֵיחַ, כַּד פַּתְחִין בְּתִיוּבְתָּא, וּמִיַּד אִתְּמַר בְּיִשְׂרָאֵל, קוּמִי לָךְ רַעְיָתִי יָפָתִי וּלְכִי לָךְ, מִן גָּלוּתָא.","וּבְגִין דָּא בְּאִילָן, דְּאִיהוּ עֵץ הַחַיִּים, בְּאוֹרַיְיתָא, בְּאִלֵּין דְּמִשְׁתַּדְּלִין בָּהּ, אָזְלִין בָּתַר חֲנָטָה, וּמְעַשְּׂרִין לֵיהּ, דְּשַׁרְיָא יוּ\"ד עָלַיְיהוּ, דְּאִיהִי חָכְמָ\"ה, א' מִי' וּבָה מִתְכַּנְּשִׁין ה\"ה, דְּאִינּוּן פֵּירוֹת הָאִילָן. וּמַאן אִילָן. ו'. אֲבָל שְׁאַר עַמָּא, אַחַר לְקִיטָתוֹ מִן גָּלוּתָא, עִשּׂוּרוֹ. אִינּוּן צַדִּיקִים דְּאִתְּמַר בְּהוֹן, (ויקרא כ״ג:מ׳) וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן פְּרִי עֵץ הָדָר. הָדָר בְּעוֹבָדֵיהוֹן, דַּאֲחִידָאן בְּמָארֵי תּוֹרָה וּמִצְוֹת, וְאַחַר חֲנָטָה אָזְלֵינָן לְגַבַּיְיהוּ (נ\"א ולגבי זרעים דתבואה ואחר חנטה אזלינן לגבייהו) כְּאִילָן.","וּבְגִין דָּא אוּקְמוּהָ בְּמַסֶּכֶת קִדּוּשִׁין, וְקָא מַשְׁמַע לָן דְּאֶתְרוֹג כְּיָרָק, מַה יָּרָק דַּרְכּוֹ לִיגָדֵל עַל כָּל מַיִם, וּבִשְׁעַת לְקִיטָתוֹ עִשׂוּרוֹ. אוּף אֶתְרוֹג נָמֵי דַּרְכּוֹ לִיגָדֵל וְכוּ' וּמִסִּטְרָא דְּחָכְמָה, אֵין מַיִם אֶלָּא תּוֹרָה. וּבַאֲתַר אַחֲרָא לְעֵילָּא, וְהָא דִּתְנָן, אֶתְרוֹג שָׁוְה לָאִילָן בִּשְׁלֹשָׁה דְּרָכִים, הָא אֶתְרוֹג, אָחִיד ב' סִטְרִין, וְאֶתְרוֹג אִיהוּ דִּיּוּקְנָא דְּלִבָּא, דְּאָחִיד לְעֵילָּא וְאָחִיד לְתַתָּא. אָחִיד לְעֵילָּא, הַלֵּב רוֹאֶה. אָחִיד לְתַתָּא, בְּדַעַת. כְּמָה דְּאוּקְמוּהָ, הַלֵּב יוֹדֵעַ. דַּעַת אִיהִי אִילָנָא, תּוֹרָה אִיבָא דִּילֵיהּ. עַיְינִין דְּאִינּוּן פִּקּוּדִין, דִּבְּהוֹן הַלֵּב רוֹאֶה. (ע\"כ רעיא מהימנא, שלח לך דף קע\"ד ע\"א ראשית עריסותיכם וכו').","(שמות כ״ב:ל׳) וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (איוב כ״ח:י״ב) וְהַחָכְמָה מֵאַיִן תִּמָּצֵא וְאֵיזֶה מְקוֹם בִּינָה. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְיַקְּרָא לוֹן, יַתִיר (נ\"א ביקרא דלהון) עַל כָּל שְׁאַר בְּנִי עָלְמָא. בְּקַדְמִיתָא אָמַר לוֹן, (שמות י״ט:ו׳) וְאַתֶּם תִּהְיוּ לִי מַמְלֶכֶת כֹּהֲנִים. לָא אַעְדֵי רְחִימוּתָא סַגִיאָה מִנְּהוֹן, עַד דְּקָרָא לוֹן וְגוֹי קָדוֹשׁ דְּאִיהוּ יַתִיר. לָא אַעְדֵּי רְחִימוּתָא מִנְּהוֹן, עַד דְּקָרָא לוֹן (דברים י״ד:ב׳) כִּי עַם קָדוֹשׁ אַתָּה. לָא אַעְדֵי רְחִימוּתָא מִנְּהוֹן, עַד דְּקָרָא לוֹן (שמות כ״ב:ל׳) וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי דְּאִיהוּ יַתִיר מִכֹּלָּא.","כְּתִיב וְהַחָכְמָה מֵאַיִן תִּמָּצֵא. אוֹרַיְיתָא (בראשית מ\"ז ע\"ב) מֵחָכְמָה נַפְקַת, מֵאֲתָר דְּאִקְרֵי (נ\"ט) קֹדֶשׁ. וְהַחָכְמָה נַפְקַת, מֵאֲתָר דְּאִקְרֵי קֹדֶשׁ הַקֳּדָשִׁים. רִבִּי יִצְחָק אָמַר, וְכֵן יוֹבְלָא אִתְקְרֵי קֹדֶשׁ. דִּכְתִּיב, (ויקרא כ״ה:י״ב) יוֹבֵל הִיא קֹדֶשׁ תִּהְיֶה לָכֶם. וְיִשְׂרָאֵל כְּלִילָן מִנַּיְיהוּ, הֲדָא הוּא דִכְתִיב וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי.","בְּקַדְמִיתָא קָדוֹשׁ, וְהַשְׁתָּא קֹדֶשׁ. מַה (ויקרא רצ\"ט ע\"א) בֵּין הַאי לְהַאי. אָמַר רִבִּי יוֹסִי, דָּא לְעֵילָּא לְעֵילָּא, וְדָא לָאו הָכִי. דִּכְתִּיב, (ישעיהו ד׳:ג׳) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּיְרוּשָׁלַ ם קָדוֹשׁ יֵאָמֶר לוֹ. בְּהַאי אֲתָר אִקְרֵי קָדוֹשׁ וּלְעֵילָּא לְעֵילָּא קֹדֶשׁ."],[[0,"ובג\"ד תקינו המוציא וכו':","ומשום שתקנו לברך המוציא, מן המקום שבשולו יפה, להוציא, לחם שרוף, אלא ממקום שהוא מוטעם. כך התבואה, הולכים אחר לקיטתה, שאז היא כבישול פירות. והיא מוטעמה."],[1,"וישראל אינון משולים וכו':","וישראל משולים לאילן ולתבואה, כמו אתרוג לאילן שנאמר בו, ראשית בכורי אדמתך תביא בית ה' אלקיך. וכך, ראשית גז צאנך תתן לו רומז על ישראל, שנאמר בהם, ואתן צאני. וכך ישראל נמשלו לתבואה, שנאמר בה, קדש ישראל לה' ראשית תבואתה, וע\"כ אחר לקיטתו מן הגלות עשורו, שאז נקראו קדש לה'."],[2,"וישראל אתקריאו אילנא וכו':","וישראל נקראו, אילן גדול וחזק ומזון לכל בו. בו התורה שהיא מזון למעלה, מבחינת ז\"א. בו התפלה, שהיא מזון למטה, מבחינת הנוקבא. ואפילו המלאכים אין להם מזון אלא ע\"י ישראל, שאם לא היו ישראל עוסקים בתורה, לא היה יורד להם מזון מצד התורה שנמשלה לאילן, ז\"ש עץ חיים היא למחזיקים בה, ומצד הפרי של התורה, שהיא מצוה."],[3,"והכי אוריתא אמתילא וכו':","וכך נמשלה התורה למים, וכך לאש, ולא היו יורדים מים מלמעלה, והשמש שהוא אש, לא היתה יורדת לבשל פירות האילן. אלא בשביל ישראל. ומשום זה נאמר בישראל, התאנה חנטה פגיה, שהם בעלי מצות. והגפנים סמדר נתנו ריח, כשפותחים בתשובה. ואז, מיד נאמר בישראל, קומי לך רעיתי יפתי ולכי לך, מן הגלות."],[4,"ובגין דא באילן וכו':","ומשום זה באילן, שהוא עץ החיים, דהיינו התורה, שהוא ז\"א, באלו שעוסקים בה, בתורה, הולכים אחר חנטה דהיינו תכף בתחילת העסק, ומעשרים אותם, כי ה \u0003י'\u0004 שהיא חכמה שורה עליהם, וע\"כ מתעשרים אחד מ \u0003י'.\u0004 ובה מתאספים מן הגלות, \u0003הה\u0004 אחרונה דהויה, שהיא ישראל, שהם פירות האילן, שהוא התורה. ומי הוא האילן. הוא \u0003ו',\u0004 שהוא ז\"א, שה\"ס התורה אבל שאר העם אחר לקיטתו מן הגלות עשורו. אבל הצדיקים נאמר בהם, ולקחתם לכם ביום הראשון פרי עץ \u0003הדר,\u0004 דהיינו \u0003הדר\u0004 במעשים האחוזים ונעשים על ידי בעלי תורה ומצות, בהם הולכים אחר חנטה כאילן. וע\"כ נאמר בהם ביום הראשון. שאינם צריכים לחכות לשעת לקיטה מן הגלות."],[5,"ובג\"ד אוקמוה וכו':","ומשום זה העמידו במסכת קדושין (דף ג' ע\"א) קמ\"ל דאתרוג כירק, מה ירק דרכו ליגדל על כל מים ובשעת לקיטתו עשורו, אף אתרוג נמי דרכו ליגדל על כל מים וכו'. וגם ישראל הדומים לאתרוג דרכם ליגדל על כל מים, שמצד החכמה אין מים אלא תורה, שישראל גדלים עליה. ובמקום אחר למעלה (דף ב' ע\"ב) מה שלמדנו, אתרוג שוה לאילן בשלשה דרכים, פירושו אתרוג, שהיא מלכות, אחוז בב' צדדים, בחסד ובגבורה, שהם ב' דרכים, ואתרוג עצמו יש לו צורת הלב, שאחוז למעלה ואחוז למטה, אחוז למעלה, היינו הלב רואה, שהיא חכמה הנקראת ראיה. אחוז למטה, היינו בדעת כמו שהעמידו הלב יודע. וזהו דרך השלישי. דעת היא אילן, שהוא פנימיות ז\"א, תורה שהוא גופא דז\"א, היא פרי של הדעת, שהיא מתפשטת מן הדעת. עיינין שהן מצוות, בהן הלב רואה. (ע\"כ רע\"מ)."],[6,"ואנשי קדש תהיון לי וגו':","ר' יהודה פתח, והחכמה מאין תמצא ואיזה מקום בינה. אשרי הם ישראל, שהקב\"ה רצה להוקיר אותם יותר מכל שאר בני העולם. בתחלה אמר להם, ואתם תהיו לי ממלכת כהנים. לא הוסרה מהם אהבה רבה, עד שקרא אותם, וגוי קדוש. שהוא יותר חשוב. לא הוסרה מהם האהבה, עד שקרא אותם, כי עם קדוש אתה. לא הוסרה מהם האהבה, עד שקרא אותם, ואנשי קדש תהיון לי, שהוא יותר חשוב מכל."],[7,"כתיב, והחכמה מאין תמצא:","התורה יצאה מחכמה ממקום שנקרא \u0003קדש,\u0004 שהוא החכמה. והחכמה יצאה ממקום שנקרא קדש הקדשים. שהוא כתר. ר' יצחק אמר, וכן היובל, שהוא בינה, נקרא קדש, שכתוב, יובל היא קדש תהיה לכם. וישראל כלולים מהם, מחכמה ומבינה, ז\"ש ואנשי קדש תהיון לי."],[8,"בקדמיתא קדוש והשתא וכו':","בתחילה קרא אותם הקב\"ה \u0003קדוש,\u0004 ועתה קורא אותם \u0003קדש,\u0004 מהו ההבדל בין זה לזה. א\"ר יוסי, זה, קדש, הוא למעלה למעלה, בחו\"ב כנ\"ל, וזה, קדוש, אינו כן, כי קדוש הוא המלכות, שכתוב, והיה הנשאר בציון והנותר בירושלים קדש יאמר לו. במקום זה בציון וירושלים שהיא המלכות, נקרא קדוש. ולמעלה למעלה, בחו\"ב נקרא קדש."]],[[0,"","וּמִשּׁוּם כָּךְ תִּקְּנוּ הַמּוֹצִיא מִמָּקוֹם שֶׁבִּשּׁוּלוֹ יָפֶה, לְהוֹצִיא פַּת שָׂרוּף, אֶלָּא מִמָּקוֹם שֶׁהוּא מֻטְעָם. וְכָךְ תְּבוּאָה, אַחַר לְקִיטָתוֹ הוּא כְּבִשּׁוּל פֵּרוֹת."],[1,"","וְיִשְׂרָאֵל מְשׁוּלִים לָאִילָן וְלַתְּבוּאָה, שֶׁנֶּאֱמַר בָּהֶם (שמות כג) רֵאשִׁית בִּכּוּרֵי אַדְמָתְךְ תָּבִיא בֵּית ה' אֱלֹהֶיךְ. וְכָךְ (דברים יח) רֵאשִׁית גֵּז צֹאנְךְ תִּתֶּן לוֹ, שֶׁהֵם יִשְׂרָאֵל, שֶׁנֶּאֱמַר בָּהֶם (יחזקאל לד) וְאַתֵּן צֹאנִי. וְכָךְ יִשְׂרָאֵל, קֹדֶשׁ (קדש ישראל) יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה, לְאַחַר לְקִיטָתוֹ מִן הַגָּלוּת - עִשּׂוּר. וְנִקְרְאוּ קֹדֶשׁ לַה'."],[2,"","וְיִשְׂרָאֵל נִקְרְאוּ אִילָן גָּדוֹל וְתַקִּיף וּבוֹ מָזוֹן לַכֹּל. בּוֹ תּוֹרָה, שֶׁהִיא מָזוֹן לְמַעְלָה. בּוֹ תְּפִלָּה, שֶׁהִיא מָזוֹן לְמַטָּה. וַאֲפִלּוּ לַמַּלְאָכִים אֵין מָזוֹן אֶלָּא בְּיִשְׂרָאֵל. שֶׁאִם יִשְׂרָאֵל לֹא יִתְעַסְּקוּ בַּתּוֹרָה, לֹא הָיָה יוֹרֵד לָהֶם מָזוֹן מִצַּד שֶׁל הַתּוֹרָה שֶׁנִּמְשְׁלָה לְעֵץ. זֶהוּ שֶׁכָּתוּב (משלי ג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. וְלַפְּרִי, שֶׁהוּא מִצְוָה."],[3,"","וְכָךָ הַתּוֹרָה נִמְשְׁלָה לְמַיִם, וְאֵלֶּה לְאֵשׁ, וְלֹא הָיוּ יוֹרְדִים מַיִם מִלְמַעְלָה, וְחַמָּה שֶׁהִיא אֵשׁ, לֹא הָיְתָה יוֹרֶדֶת (מלמעלה) לְבַשֵּׁל אֶת פֵּרוֹת הָאִילָן, אֶלָּא בִּשְׁבִיל יִשְׂרָאֵל, וּמִשּׁוּם זֶה נֶאֱמַר בְּיִשְׂרָאֵל, (שיר ב) הַתְּאֵנָה חָנְטָה פַגֶּיהָ. אֵלּוּ בַּעֲלֵי מִצְווֹת. וְהַגְּפָנִים סְמָדַר נָתְנוּ רֵיחַ, כְּשֶׁפּוֹתְחִים בִּתְשׁוּבָה, וּמִיָּד נֶאֱמַר בְּיִשְׂרָאֵל, קוּמִי לָךְ רַעְיָתִי יָפָתִי וּלְכִי לָךְ, מִן הַגָּלוּת."],[4,"","וּמִשּׁוּם זֶה בָּאִילָן, שֶׁהוּא עֵץ הַחַיִּים, בַּתּוֹרָה, בְּאֵלּוּ שֶׁמִּשְׁתַּדְּלִים בָּהּ הוֹלְכִים אַחַר חֲנָטָה וּמְעַשְּׂרִים אוֹתוֹ, שֶׁשּׁוֹרֶה עֲלֵיהֶם יוֹ\"ד, שֶׁהִיא חָכְמָ\"ה, א' מִי', וּבָהּ מִתְכַּנְּסִים ה\"ה, שֶׁהֵם פֵּרוֹת הָאִילָן. וּמַהוּ הָאִילָן? ו'. אֲבָל שְׁאָר הָעָם, אַחַר לְקִיטָתוֹ מִן הַגָּלוּת - עִשּׂוּרוֹ, אוֹתָם צַדִּיקִים שֶׁנֶּאֱמַר בָּהֶם (ויקרא כג) וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן פְּרִי עֵץ הָדָר. הָדָר בְּמַעֲשֵׂיהֶם, שֶׁאֲחוּזִים בְּבַעֲלֵי תוֹרָה וּמִצְווֹת, וְאַחַר לְקִיטָה הוֹלְכִים לְגַבֵּיהֶם (ולגבי זרעים של תבואה. ואחר חנטה הולכים אליהם) כְּאִילָן."],[5,"","וּמִשּׁוּם זֶה פֵּרְשׁוּהָ בְּמַסֶּכֶת קִדּוּשִׁין, בָּא לְהַשְׁמִיעֵנוּ שֶׁאֶתְרוֹג כְּיָרָק. מַה יָּרָק דַּרְכּוֹ לִגָּדֵל עַל כָּל מַיִם וּבִשְׁעַת לְקִיטָתוֹ עִשּׂוּרוֹ, אַף אֶתְרוֹג גַּם דַּרְכּוֹ לִגָּדֵל וְכוּ' וּמִצַּד שֶׁל הַחָכְמָה, אֵין מַיִם אֶלָּא תּוֹרָה. וּבְמָקוֹם אַחֵר לְמַעְלָה, וְזֶה שֶׁשָּׁנִינוּ, אֶתְרוֹג שָׁוֶה לָאִילָן בִּשְׁלֹשָׁה דְרָכִים., הֲרֵי אֶתְרוֹג אוֹחֵז שְׁנֵי צְדָדִים, וְאֶתְרוֹג הוּא דְּיוֹקַן הַלֵּב שֶׁאָחוּז לְמַעְלָה וְאָחוּז לְמַטָּה. אָחוּז לְמַעְלָה - הַלֵּב רוֹאֶה. אָחוּז לְמַטָּה - בְּדַעַת, כְּמוֹ שֶׁבֵּאֲרוּהָ, הַלֵּב יוֹדֵעַ. דַּעַת הִיא אִילָן, הַתּוֹרָה הַפְּרִי שֶׁלּוֹ. הָעֵינַיִם שֶׁהֵן הַמִּצְווֹת שֶׁבָּהֶן - הַלֵּב רוֹאֶה. (ע\"כ רעיא מהימנא)"],[6,"","וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (איוב כח) וְהַחָכְמָה מֵאַיִן תִּמָּצֵא וְאֵי זֶה מְקוֹם בִּינָה. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְכַבְּדָם יוֹתֵר (בכבוד שלהם) מִכָּל שְׁאָר בְּנֵי הָעוֹלָם. בַּתְּחִלָּה אָמַר לָהֶם, (שמות יט) וְאַתֶּם תִּהְיוּ לִי מַמְלֶכֶת כֹּהֲנִים. לֹא זָזָה הָאַהֲבָה הָרַבָּה מֵהֶם עַד שֶׁקָּרָא לָהֶם וְגוֹי קָדוֹשׁ, שֶׁהוּא יוֹתֵר. לֹא זָזָה הָאַהֲבָה מֵהֶם עַד שֶׁקָּרָא לָהֶם (דברים יד) כִּי עַם קָדוֹשׁ אַתָּה. לֹא זָזָה הָאַהֲבָה מֵהֶם עַד שֶׁקָּרָא לָהֶם (שמות כב) וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי, שֶׁהוּא יוֹתֵר מִן הַכֹּל."],[7,"","כָּתוּב וְהַחָכְמָה מֵאַיִן תִּמָּצֵא. הַתּוֹרָה יָצְאָה מֵחָכְמָה, מִמָּקוֹם שֶׁנִּקְרָא קֹדֶשׁ, וְהַחָכְמָה יָצְאָה מִמָּקוֹם שֶׁנִּקְרָא קֹדֶשׁ הַקְּדָשִׁים. רַבִּי יִצְחָק אָמַר, וְכֵן יוֹבֵל נִקְרָא קֹדֶשׁ, שֶׁכָּתוּב (ויקרא כה) יוֹבֵל הִיא קֹדֶשׁ תִּהְיֶה לָכֶם. וְיִשְׂרָאֵל כְּלוּלִים מֵהֶם. זֶהוּ שֶׁכָּתוּב וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי."],[8,"","בַּתְּחִלָּה קָדוֹשׁ, וְעַכְשָׁו קֹדֶשׁ. מַה בֵּין זֶה לָזֶה? אָמַר רַבִּי יוֹסֵי, זֶה לְמַעְלָה וְזֶה לְמַטָּה. וְזֶה לֹא כָּךְ, שֶׁכָּתוּב (ישעיה ד) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלם קָדוֹשׁ יֵאָמֶר לוֹ. בְּמָקוֹם זֶה נִקְרָא קָדוֹשׁ, וּלְמַעְלָה לְמַעְלָה קֹדֶשׁ."]]],[["רַבִּי אַבָּא הֲוָה אָזִיל בְּאָרְחָא, וַהֲווּ אָזְלֵי עִמֵּיהּ רִבִּי יוֹסִי וְרִבִּי חִיָּיא, אָמַר רִבִּי חִיָּיא, (ס\"א דתנינן) וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי, מְנָלָן. אֲמַר לֵיהּ, הָא רִבִּי יוֹסִי וְכֻלְּהוּ חַבְרַיָּיא שַׁפִּיר קַאמְרוּ, וְהָכִי הוּא. מְנָלָן. דִּכְתִּיב, (ירמיהו ב׳:ג׳) קֹדֶשׁ יִשְׂרָאֵל לַיְיָ' רֵאשִׁית תְּבוּאָתֹה, רֵאשִׁית: וַדַּאי חָכְמָה אִקְרֵי רִאשִׁית, דִּכְתִּיב, (תהילים קי״א:י׳) רֵאשִׁית חָכְמָה יִרְאַת יְיָ'.","וּמִשּׁוּם דְּיִשְׂרָאֵל אִקְרוּן קֹדֶשׁ (ישראל) בִּשְׁלִימוּ דְּכֹלָּא, כְּתִיב (שמות כ״ב:ל׳) וּבָשָׂר בַּשָּׂדֶה טְרֵפָה לֹא תֹאכֵלוּ. דְּהָא יִשְׂרָאֵל דְּאִינּוּן שְׁלֵמִין עַל כֹּלָּא, לָא יַנְקִין מִסִּטְרָא דְּדִינָא קַשְׁיָא. לַכֶּלֶב תַּשְׁלִיכוּן אוֹתוֹ. לַכֶּלֶב וַדַּאי, דְּהוּא דִּינָא חֲצִיפָא תַּקִּיפָא עַל כֹּלָּא. כֵּיוָן דְּדִינָא תַּקִּיפָא שַׁרְיָא עֲלוֹי, וְאָטִיל זוּהֲמָא בֵּיהּ, אָסִיר לְהוּ לְאִינוּן דְּאִקְרוּן קֹדֶשׁ. אֶלָּא לַכֶּלֶב תַּשְׁלִיכוּן אוֹתוֹ וַדַּאי, דְּאִיהוּ דִּינָא חֲצִיפָא, דִּינָא תַּקִּיפָא יַתִּיר מִכֹּלָּא, דִּכְתִּיב, (ישעיהו נ״ו:י״א) וְהַכְּלָבִים עַזֵּי נֶפֶשׁ.","תָּא חֲזֵי, כַּד אִדְכַּר נְבֵלָה בְּאוֹרַיְיתָא, כְּתִיב בְּיִשְׂרָאֵל קָדוֹשׁ, וְלָא קֹדֶשׁ. הָכָא כְּתִיב, וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי וּבָשָׂר בַּשָּׂדֶה טְרֵפָה לֹא תֹאכֵלוּ. וְהָתָם בִּנְּבֵלָה כְּתִיב, (דברים י״ד:כ״א) לֹא תֹאכְלוּ כָל נְבֵלָה לַגֵּר אֲשֶׁר בִּשְׁעָרֶיךָ תִּתְּנְנָּה וְגוֹ', כִּי עַם קָדוֹשׁ אַתָּה. קָדוֹשׁ וְלֹא קֹדֶשׁ, דְּהָא נְבֵלָה מִסִּטְרָא דְּיִשְׂרָאֵל אִתְעָבִיד, דְּלָא פָּסִיל הַאי אֶלָּא יִשְׂרָאֵל. וְסַגִּיאִין גַּוְונִין, אִית בָּהּ בִּנְּבֵלָה. כְּמָה דְּאוֹקִימְנָא.","אָמַר רַבִּי שִׁמְעוֹן, כְּתִיב הָכָא וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי, וּכְתִיב הָתָם כִּי עַם קָדוֹשׁ אַתָּה לַיְיָ' אֱלֹהֶיךָ. לַיְיָ' אֱלהֶיךָ, לִי מִבָּעֵי לֵיהּ. אֶלָּא הָתָם (ס\"א אלא הכא) לְעֵילָּא לְעֵילָּא. וְהָכָא (ס\"א והתם) שְׁכִינְתָּא. וּכְתִיב, (ישעיהו ד׳:ג׳) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּיְרוּשָׁלַם קָדוֹשׁ יֵאָמֶר לוֹ וְלָא קֹדֶשׁ. בְּכָאן קָדוֹשׁ, וּלְעֵילָּא קֹדֶשׁ. כְּתִיב קֹדֶשׁ יִשְׂרָאֵל לַיְיָ' רֵאשִׁית תְּבוּאָתֹה, בְּהֵ\"א כְּמָה דְּאוֹקִימְנָא. וְעַל דָּא וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי וַדַּאי.","רַבִּי יִצְחָק הֲוָה יָתִיב קָמֵיהּ דְּרַבִּי שִׁמְעוֹן, אֲמַר לֵיהּ הָא כְּתִיב קֹדֶשׁ יִשְׂרָאֵל לַיְיָ' סוֹפְיֵהּ דִּקְרָא כְּתִיב כָּל אוֹכְלָיו יֶאְשָׁמוּ, מַאי קָא מַיְירֵי. אֲמַר לֵיהּ רַבִּי שִׁמְעוֹן, שַׁפִּיר קָא אָמַר, כָּל אֹכְלָיו יֶאְשָׁמוּ, הַיְינוּ דִּכְתִּיב, (ויקרא כ״ב:י״ד) וְאִישׁ כִּי יֹאכַל קֹדֶשׁ בִּשְׁגָגָה וְגוֹ'. וּכְתִיב, וְכָל זָר לא יֹאכַל קֹדֶשׁ. וּמִשּׁוּם דְּיִשְׂרָאֵל אִקְרוּן קֹדֶשׁ, כְּתִיב כָּל אֹכְלָיו יֶאְשָׁמוּ. אָתָא רִבִּי יִצְחָק וְנָשִׁיק יְדוֹי, אָמַר, אִי לָא אַתֵּינָא הָכָא אֶלָּא לְמִשְׁמַע מִלָּה דָּא סַגֵּי.","אֲמַר לֵיהּ רַבִּי, הָא תָּנֵינָן, דְּקֹדֶשׁ, יַתִּיר לְעֵילָּא מִן קָדוֹשׁ. אִי הָכִי, הָא כְּתִיב (ישעיה ו) ק' ק' ק' יְיָ' צְבָאוֹת, וְדָא שְׁלִימוּ דְּכֹלָּא. אֲמַר לֵיהּ תָּא חֲזֵי, כַּד מִתְחַבְּרָן כַּחֲדָא, כֻּלְּהוּ אִתְעָבִידוּ חַד בֵּיתָא, וְהַאי (ויקרא צ\"ג) בֵּיתָא, אִקְרֵי קֹדֶשׁ. כְּלָלָא דְּכֻלְּהוּ קָדוֹשׁ וּבְגִינֵי כַּךְ קֹדֶשׁ, הוּא כְּלָלָא, דְּכֹלָּא אִתְכְּלִיל בֵּיהּ. וְיִשְׂרָאֵל כַּד אִתְכְּלִל בְּהוּ מְהֵימְנוּתָא שְׁלֵימָתָא קֹדֶשׁ אִקְרוּן, כְּלָלָא דְּכֹלָּא, דִּכְתִּיב קֹדֶשׁ יִשְׂרָאֵל לַיְיָ'. וּבְגִינֵי כַּךְ, וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי.","לִגְיוֹן חַד שָׁאִיל לְרַ' אַבָּא, אֲמַר לֵיהּ, לָא כְּתִיב וּבָשָׂר בַּשָּׂדֶה טְרֵפָה לֹא תֹאכֵלוּ, אִי הָכִי, מַאי דִּכְתִּיב, (תהילים קי״א:ה׳) טֶרֶף נָתַן לִירֵאָיו. טֶרֶף נָתַן לַכְּלָבִים מִבָּעֵי לֵיהּ, אֲמַאי נָתַן לִירֵאָיו. אֲמַר לֵיהּ, רֵיקָא, מִי כְּתִיב טְרֵפָה נָתַן לִירֵאָיו, טֶרֶף כְּתִיב. וְאִי תֵּימָא, טֶרֶף כִּטְרֵפָה. נָתַן לִירֵאָיו וַדַּאי דְּמִלָּה דָּא, לָא יָהֲבֵיהּ לְאִזְדַּהֲרָא בֵּיהּ, אֶלָּא לְאִינוּן דַּחֲלֵי שְׁמֵיהּ, וְדַחֲלִין לֵיהּ. בְּגִין כָּךְ הַאי מִלָּה לָא יָהִיב לְכוּ, דְּהָא יָדַע דְּאַתּוּן לָא דַּחֲלִין לֵיהּ, וְלָא נַטְרִין פִּקּוּדוֹי, וּבְגִין דְּהַאי מִלָּה חוּמְרָא דְּאוֹרַיְיתָא, וּבָעֵי לְאִזְדַּהֲרָא בָּהּ, נָתַן לִירֵאָיו, לִירֵאָיו וַדַּאי, וְלָא לְאָחֳרֵי. וְכָל חוֹמְרֵי דְּאוֹרַיְיתָא, לָא יָהִיב לוֹן קוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא לְאִינוּן דַּחֲלֵי חַטָּאָה, לְאִינוּן דַּחֲלֵי פִּקּוּדוֹי וְלָא לְכוּ.","תָּאנֵי רִבִּי אֶלְעָזָר, כְּתִיב (ס\"א קדש ישראל וכתיב ואנשי וגו') וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי, מַהוּ וְאַנְשֵׁי. וּלְבָתַר קֹדֶשׁ, אֶלָּא וְאַנְשֵׁי קֹדֶשׁ וַדַּאי. דְּתָנֵינָן, לָא נָפְקוּ יִשְׂרָאֵל לְחֵירוּ, אֶלָּא (בראשית ל\"א ע\"ב) מִסִּטְרָא דְּיוֹבְלָא. בָּתַר דְּנָפְקוּ לְחֵירוּ, נָקִיט לוֹן הַאי יוֹבְלָא בְּגַדְפּוֹי, וְאִקְרוּן גּוּבְרִין דִּילֵיהּ. בְּנִין דִּילֵיהּ, וּכְתִיב בֵּיהּ בְּיוֹבְלָא, (ויקרא כ״ה:י״ב) יוֹבֵל הִיא קֹדֶשׁ תִּהְיֶה לָכֶם, קֹדֶשׁ וַדַּאי, לָכֶם וַדַּאי. וּבְגִינֵי כַּךְ, וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי, אַנְשֵׁי קֹדֶשׁ וַדַּאי, גּוּבְרִין דִּילֵיהּ מַמָּשׁ."],[[0,"רבי אבא הוה וכו':","ר\"א היה הולך בדרך, והלכו עמו ר' יוסי ור' חייא. אמר ר' חייא, ואנשי קדש תהיון לי, שאמרו שהוא חכמה, מאין לנו זה, א\"ל הרי ר' יוסי וכל החברים יפה אמרו, שהוא חכמה, וכן הוא. מאין לנו, כי כתוב, קדש ישראל לה' \u0003ראשית\u0004 תבואתה, ראשית, ודאי החכמה נקראת ראשית, שכתוב \u0003ראשית\u0004 חכמה יראת ה'."],[1,"ומשום דישראל אקרון וכו':","ומשום שישראל נקראים קדש, שהוא כל השלמות, כתוב, ובשר בשדה טרפה לא תאכלו. כי ישראל שהם שלמים מכל, אינם יונקים מצד דין הקשה, אשר טרפה רומזת עליו, לכלב תשליכון אותו. לכלב ודאי, שהוא דין חצוף חזק על כל. כי כיון שדין חזק שורה על הטרפה, והטיל זוהמא בו, אסור לאלו הנקראים קדש לאכול ממנו. וזה שאומר הכתוב, ואנשי קדש תהיון לי ובשר בשדה טרפה לא תאכלו, שתלה הכתוב איסור הטרפה באנשי קדש. אלא לכלב תשליכון אותו ודאי, שהוא דין חצוף ודין חזק יותר מכל, שכתוב, והכלבים עזי נפש."],[2,"ת\"ח כד אדכר וכו':","בוא וראה, כשנזכרה נבלה בתורה כתוב בישראל, קדוש, ולא קדש, וכאן בטרפה, כתוב ואנשי \u0003קדש\u0004 תהיון לי ובשר בשדה טרפה לא תאכלו. ושם בנבלה, כתוב לא תאכלו כל נבלה וגו' כי עם \u0003קדוש\u0004 אתה. כתוב, קדוש ולא קדש. משום שמצד ישראל נעשה הנבלה, דהיינו שנבלוה בשחיטה, נמצא שלא פסל אותה אלא ישראל. שהדין אינו חזק כל כך, מה שאין כן הטרפה שנפסלה ע\"י חיות רעות הדין קשה. וע\"כ הפרישה מטרפה נקרא קדש, ומנבלה נקרא קדוש. ואופנים הרבה יש בנבלה כמו שהעמדנו."],[3,"אמר ר\"ש כתיב וכו':","אר\"ש, כתוב כאן, ואנשי קדש תהיון לי, וכתוב שם, כי עם קדוש אתה לה' אלקיך שואל, לה' אלקיך, לי היה צריך לומר. ומשיב, אלא כאן הוא למעלה למעלה, בחו\"ב, ושם הוא השכינה, דהיינו המלכות, וע\"כ כתוב, לה' אלקיך שהמלכות נקראת אלקים. וכתוב, והיה הנשאר בציון והנותר בירושלים \u0003קדוש\u0004 יאמר לו, ולא קדש, שבכאן, במלכות הנקראת ציון וירושלים, הוא קדוש, ולמעלה בחכמה ובינה, קדש. וכתוב \u0003קדש\u0004 ישראל לה' ראשית תבואת \u0003ה\u0004 עם \u0003ה'\u0004 יתרה, הרומזת על בינה שהיא ה' ראשונה דהויה, וראשית הוא חכמה. כמו שהעמדנו, וע\"כ, ואנשי קדש תהיון לי ודאי."],[4,"ר' יצחק הוה יתיב וכו':","ר\"י היה יושב לפני ר' שמעון, אמר לו והרי כתוב, קדש ישראל לה', וסופו של הכתוב, כל אוכליו יאשמו. מה הוא אומר. אמר לו ר\"ש, יפה אומר, כל אוכליו יאשמו. כי היינו שכתוב, ואיש כי יאכל קדש בשגגה וגו'. וכתוב וכל זר לא יאכל קדש. ומשום שישראל נקראים קדש, כתוב כל אכליו יאשמו. בא ר' יצחק ונשק ידיו. אמר, אם לא באתי כאן אלא לשמוע דבר זה, די לי."],[5,"א\"ל רבי הא וכו':","אמר לו ר' יצחק, רבי, הרי למדנו, שקדש הוא יותר למעלה מן קדוש. א\"כ, הרי כתוב, קדוש קדוש קדוש ה' צבאות, שזה הוא שלמות הכל, וכתוב קדוש. אמר לו בוא וראה, כשמתחברים ג' הקדושות יחד, נעשו בית אחד, ובית הזה נקרא קדש, שהוא הכלל של כל ג' קדוש. וע\"כ הוא שלמות הכל. ומשום זה, קדש הוא כלל שהכל נכלל בו, וישראל כשנכלל בהם אמונה השלמה, נקראים קדש, שהוא כלל הכל, שכתוב, קדש ישראל לה'. ומשום זה כתוב, ואנשי קדש תהיון לי."],[6,"לגיון חד שאיל וכו':","לגיון אחד, דהיינו שר צבא, שאל את ר' אבא, וכי לא כתוב, ובשר בשדה טרפה לא תאכלו, אם כן, מה שכתוב, טרף נתן ליראיו, טרף נתן לכלבים, היה צריך לומר, למה נתן ליראיו. אמר לו, ריק, מי כתוב, טרפה נתן ליראיו, טרף כתוב, שפירושו מזון. ואפילו תאמר, טרף הוא כטרפה, נתן ליראיו ודאי, שיזהרו בו ולא יאכלו. ומה שאומר ליראיו, הוא, כי דבר זה לא ניתן להזהר בו, אלא לאותם יראי שמו, שיראים ממנו. ומשום זה לא ניתן לכם דבר הזה, כי ידע, שאתם אינכם יראים אותו, ולא שומרים מצותיו, ומשום שדבר זה הוא מן הקשים שבתורה, וצריכים להזהר בו, נתן ליראיו, ליראיו ודאי, ולא לאחר. וכל דברים הקשים שבתורה לא נתן אותם הקב\"ה אלא לאלו יראי חטא, לאלו היראים לשמור מצותיו, ולא לכם."],[7,"תאני ר' אלעזר וכו':","למד ר' אלעזר, כתוב, ואנשי קדש תהיון לי. מהו ואנשי ואח\"כ קדש. שהיה מספיק לומר קדושים תהיון לי. ומשיב, אלא ואנשי קדש ודאי, שלמדנו, לא יצאו ישראל לחירות אלא מצד יובל, שהוא בינה, ואחר שיצאו לחירות קבל אותם יובל ההוא בכנפיו, ונקראים אנשים שלו, בנים שלו. וכתוב ביובל, יובל היא קדש תהיה לכם. קדש ודאי, לכם ודאי. ומשום זה, כתוב, ואנשי קדש תהיון לי, אנשי קדש ודאי, אנשים שלו ממש."]],[[0,"","רַבִּי אַבָּא הָיָה הוֹלֵךְ בַּדֶּרֶךְ, וְהָיוּ הוֹלְכִים עִמּוֹ רַבִּי יוֹסֵי וְרַבִּי חִיָּיא. אָמַר רַבִּי חִיָּיא, וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי, מִנַּיִן לָנוּ? אָמַר לוֹ, הֲרֵי רַבִּי יוֹסֵי וְכָל הַחֲבֵרִים יָפֶה אָמְרוּ, וְכָךְ זֶה. מִנַּיִן לָנוּ? שֶׁכָּתוּב (ירמיהב) קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה. רֵאשִׁית, וַדַּאי חָכְמָה נִקְרֵאת רֵאשִׁית, שֶׁכָּתוּב (תהליםקיא) רֵאשִׁית חָכְמָה יִרְאַת ה'."],[1,"","וּמִשּׁוּם שֶׁיִּשְׂרָאֵל נִקְרְאוּ קֹדֶשׁ (ישראל) בִּשְׁלֵמוּת הַכֹּל, כָּתוּב (שמות כב) וּבָשָׂר בַּשָּׂדֶה טְרֵפָה לֹא תֹאכֵלוּ, שֶׁהֲרֵי יִשְׂרָאֵל, שֶׁהֵם שְׁלֵמִים עַל הַכֹּל, לֹא יוֹנְקִים מִצַּד הַדִּין הַקָּשֶׁה. לַכֶּלֶב תַּשְׁלִכוּן אֹתוֹ, לַכֶּלֶב וַדַּאי, שֶׁהוּא הַדִּין הֶחָצוּף הֶחָזָק עַל הַכֹּל. כֵּיוָן שֶׁהַדִּין הַקָּשֶׁה שָׁרוּי עָלָיו וְהִטִּיל בּוֹ זֻהֲמָה, אָסוּר לָהֶם לְאוֹתָם שֶׁנִּקְרָאִים קֹדֶשׁ. אֶלָּא לַכֶּלֶב תַּשְׁלִכוּן אֹתוֹ וַדַּאי, שֶׁהוּא הַדִּין הֶחָצוּף, דִּין הַקָּשֶׁה יוֹתֵר מִן הַכֹּל, שֶׁכָּתוּב (ישעיה כו) וְהַכְּלָבִים עַזֵּי נֶפֶשׁ."],[2,"","בֹּא וּרְאֵה, כְּשֶׁנִּזְכְּרָה נְבֵלָה בַּתּוֹרָה, כָּתוּב בְּיִשְׂרָאל קָדוֹשׁ, וְלֹא קֹדֶשׁ. כָּאן כָּתוּב וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי וּבָשָׂר בַּשָּׂדֶה טְרֵפָה לֹא תֹאכֵלוּ. וְשָׁם בִּנְבֵלָה כָּתוּב (דברים יד) לֹא תֹאכְלוּ כָל נְבֵלָה לַגֵּר אֲשֶׁר בִּשְׁעָרֶיךְ תִּתְּנֶנָּה וְגוֹ', כִּי עַם קָדוֹשׁ אַתָּה. קָדוֹשׁ וְלֹא קֹדֶשׁ, שֶׁהֲרֵי נְבֵלָה מִצַּד שֶׁל יִשְׂרָאֵל נֶעֶשְׂתָה, שֶׁלֹּא פוֹסֵל אֶת זֶה אֶלָּא יִשְׂרָאֵל. וְרַבִּים הַגְּוָנִים יֵשׁ בָּהּ בִּנְבֵלָה, כְּמוֹ שֶׁבֵּאַרְנוּ."],[3,"","אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב כָּאן וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי, וְכָתוּב שָׁם, כִּי עַם קָדוֹשׁ אַתָּה לַה' אֱלֹהֶיךְ. לַה' אֱלֹהֶיךְ? לִי הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא שָׁם (כאן) לְמַעְלָה לְמַעְלָה, וְכָאן (ושם) הַשְּׁכִינָה. וְכָתוּב (ישעיה ד) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁ לם קָדוֹשׁ יֵאָמֶר לוֹ, וְלֹא קֹדֶשׁ. בְּכָאן קָדוֹשׁ וּלְמַעְלָה קֹדֶשׁ. כָּתוּב קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה, בְּהֵ\"א, כְּמוֹ שֶׁבֵּאַרְנוּ. וְעַל כָּךְ אַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי וַדַּאי."],[4,"","רַבִּי יִצְחָק הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לוֹ, הֲרֵי כָּתוּב קֹדֶשׁ יִשְׂרָאֵל לַה'. בְּסוֹף הַפָּסוּק כָּתוּב כָּל אֹכְלָיו יֶאְשָׁמוּ, מַה זֶּה אוֹמֵר? אָמַר לוֹ רַבִּי שִׁמְעוֹן, יָפֶה אָמַר, כָּל אֹכְלָיו יֶאְשָׁמוּ - הַיְנוּ שֶׁכָּתוּב וְאִישׁ כִּי יֹאכַל קֹדֶשׁ בִּשְׁגָגָה וְכוּ'. וְכָתוּב וְכָל זָר לֹא יֹאכַל קֹדֶשׁ. וּמִשּׁוּם שֶׁיִּשְׂרָאֵל נִקְרְאוּ קֹדֶשׁ, כָּתוּב כָּל אֹכְלָיו יֶאְשָׁמוּ. בָּא רַבִּי יִצְחָק וְנָשַׁק יָדוֹ וְאָמַר, אִם לֹא בָאתִי לְכָאן אֶלָּא לִשְׁמֹעַ דָּבָר זֶה - מַסְפִּיק."],[5,"","אָמַר לוֹ, רַבִּי, הֲרֵי שָׁנִינוּ שֶׁקֹּדֶשׁ יוֹתֵר לְמַעְלָה מִקָּדוֹשׁ. אִם כָּךְ, הֲרֵי כָּתוּב (ישעיה ו) קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ ה' צְבָאוֹת, וְזוֹ שְׁלֵמוּת הַכֹּל? אָמַר לוֹ, בּא וּרְאֵה, כְּשֶׁמִּתְחַבְּרִים כְּאֶחָד, כֻּלָּם נַעֲשִׂים בַּיִת אֶחָד, וְהַבַּיִת הַזֶּה נִקְרָא קֹדֶשׁ. הַכְּלָל שֶׁל הַכֹּל קָדוֹשׁ, וּמִשּׁוּם כָּךְ קֹדֶשׁ. הוּא כְּלָל שֶׁהַכֹּל נִכְלָל בּוֹ. וּכְשֶׁנִּכְלֶלֶת בְּיִשְׂרָאֵל הָאֱמוּנָה הַשְּׁלֵמָה, הֵם נִקְרָאִים קֹדֶשׁ, הַכְּלָל שֶׁל הַכֹּל, שֶׁכָּתוּב קֹדֶשׁ יִשְׂרָאֵל לַה'. וּמִשּׁוּם כָּךְ, וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי."],[6,"","לִגְיוֹן אֶחָד שָׁאַל אֶת רַבִּי אַבָּא וְאָמַר לוֹ, לֹא כָתוּב וּבָשָׂר בַּשָּׂדֶה טְרֵפָה לֹא תֹאכֵלוּ?! אִם כָּךְ, מַהוּ שֶׁכָּתוּב (תהלים קיא) טֶרֶף נָתַן לִירֵאָיו? טֶרֶף נָתַן לַכְּלָבִים הָיָה צָרִיךְ לִהְיוֹת! לָמָּה נָתַן לִירֵאָיו? אָמַר לוֹ, רֵיקָא, הַאִם כָּתוּב טְרֵפָה נָתַן לִירֵאָיו?! טֶרֶף כָּתוּב! וְאִם תֹּאמַר, טֶרֶף כְּמוֹ טְרֵפָה, נָתַן לִירֵאָיו וַדַּאי, שֶׁדָּבָר זֶה לֹא נָתְנוּ לְהִזָּהֵר בּוֹ אֶלָּא לְאוֹתָם יִרְאֵי שְׁמוֹ וִירֵאִים מִמֶּנּוּ. מִשּׁוּם זֶה דָּבָר זֶה לֹא נָתַן לָכֶם, שֶׁהֲרֵי יָדַע שֶׁאֵינְכֶם יְרֵאִים מִמֶּנּוּ וְלֹא שׁוֹמְרִים מִצְווֹתָיו, וּמִשּׁוּם דָּבָר זֶה חֻמְרָה שֶׁל הַתּוֹרָה וְצָרִיךְ לְהִזָּהֵר בָּהּ. נָתַן לִירֵאָיו, נָתַן לִירֵאָיו וַדַּאי, וְלֹא לַאֲחֵרִים. וְכָל חֻמְרוֹת הַתּוֹרָה לֹא נְתָנָם הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא לְאוֹתָם יִרְאֵי חֵטְא, לְאוֹתָם יִרְאֵי מִצְווֹתָיו וְלֹא לָכֶם."],[7,"","שָׁנָה רַבִּי אֶלְעָזָר, כָּתוּב (קדש ישראל, וכתוב ואנשי וכו') וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי. מַה זֶּה וְאַנְשֵׁי, וְאַחֲרָיו קֹדֶשׁ? אֶלָּא וְאַנְשֵׁי קֹדֶשׁ וַדַּאי. שֶׁשָּׁנִינוּ, לֹא יָצְאוּ יִשְׂרָאֵל לַחֵרוּת אֶלָּא מִצַּד הַיּוֹבֵל. אַחַר שֶׁיָּצְאוּ לַחֵרוּת, לָקַח אוֹתָם הַיּוֹבֵל הַזֶּה בִּכְנָפָיו, וְנִקְרְאוּ אֲנָשִׁים שֶׁלּוֹ, בָּנִים שֶׁלּוֹ. וְכָתוּב בּוֹ בַּיּוֹבֵל, (ויקרא כה) יוֹבֵל הִיא קֹדֶשׁ תִּהְיֶה לָכֶם, קֹדֶשׁ וַדַּאי, לָכֶם וַדַּאי. וּמִשּׁוּם כָּךְ, וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי, אַנְשֵׁי קֹדֶשׁ וַדַּאי, אֲנָשִׁים שֶׁלּוֹ מַמָּשׁ."]]],[["וְקוּדְשָׁא בְּרִיךְ הוּא אָמַר דָּא, וְעַל דָּא זָכוּ יִשְׂרָאֵל לְאִתְקְרֵי אַחִים לְקוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (תהילים קכ״ב:ח׳) לְמַעַן אַחַי וְרֵעָי וְגוֹ'. לְבָתַר אִקְרוּן קֹדֶשׁ מַמָּשׁ. דִּכְתִּיב, (ירמיהו ב׳:ג׳) קֹדֶשׁ יִשְׂרָאֵל לַיְיָ' רֵאשִׁית תְּבוּאָתֹה, קֹדֶשׁ וְלָא אַנְשֵׁי קֹדֶשׁ, בְּגִינִי כַּךְ כָּל אֹכְלָיו יֶאְשָׁמוּ, וּכְתִיב, (ויקרא כ״ב:י׳) וְכָל זָר לא יאכַל קֹדֶשׁ. (ויקרא כ״ב:י״ד) וְאִישׁ כִּי יֹאכַל קֹדֶשׁ בִּשְׁגָגָה.","תָּאנָא, יִשְׂרָאֵל אִקְרוּן קֹדֶשׁ, וּבְגִין דְּאִינּוּן קֹדֶשׁ, אָסִיר לֵיהּ לֶאֱינָשׁ, לְמִקְרֵי לְחַבְרֵיהּ בִּשְׁמָא דִּגְנָאי, וְלָא לְכַנָּאָה שְׁמָא לְחַבְרֵיהּ, וְעֹנְשֵׁיהּ סַגִּי. וְכָל שֶׁכֵּן בְּמִלִּין אַחֲרָנִין. תָּאנָא, כְּתִיב (תהלים לה) נְצוֹר לְשׁוֹנְךָ מֵרָע וְגוֹ'. מַהוּ מֵרָע. דִּבְגִין לִישָׁנָא בִּישָׁא, מַרְעִין נַחְתִּין לְעָלְמָא.","אָמַר רִבִּי יוֹסִי כָּל מַאן דְּקָרֵי לְחַבְרֵיהּ בִּשְׁמָא דְּלֵית בֵּיהּ, וְגָנֵּי לֵיהּ, אִתְּפַּס בְּמָה דְּלֵית בֵּיהּ, דְּאָמַר רִבִּי חִיָּיא אָמַר רִבִּי חִזְקִיָּה, כָּל מַאן דְּקָרֵי לְחַבְרֵיהּ רָשָׁע, נַחְתִּין לֵיהּ לַגֵּיהִנָּם. וְנַחְתִּין לֵיהּ לְעִלְעוֹי, בַּר אִינּוּן חֲצִיפִין דְּאוֹרַיְיתָא, דִּשְׁרֵי לֵיהּ לְאִינִישׁ לְמִקְרֵי לְהוּ רָשָׁע.","הַהוּא גַּבְרָא, דְּלָיִיט לְחַבְרֵיהּ, אַעְבָּר רִבִּי יֵיסָא, אָמַר לֵיהּ כְּרָשָׁע עַבָדְתְּ. אַתְיֵיהּ לְקָמֵיהּ דְּרִבִּי יְהוּדָה, אֲמַר לֵיהּ רָשָׁע לָא קָאמֵינָא לֵיהּ, אֶלָּא כְּרָשָׁע, דְּאַחְזֵי מִלּוֹי כְּרָשָׁע, וְלָא אֲמֵינָא דְּאִיהוּ רָשָׁע. אָתָא רִבִּי יְהוּדָה, וְשָׁאִיל לְעוֹבָדָא קָמֵיהּ דְּרַבִּי אֶלְעָזָר, אָמַר לֵיהּ, וַדַּאי לָא אִתְחַיָּיב. מְנָלָן. דִּכְתִּיב, (איכה ב) הָיָה יְיָ' כְּאוֹיֵב, וְלָא אוֹיֵב. דְּאִי לָאו הָכִי, לָא אִשְׁתְּאַר מִיִּשְׂרָאֵל גִּזְעִין בְּעָלְמָא. כְּגַוְונָא דָּא, (איכה ב) הָיְתָה כְּאַלְמָנָה, וְלָא אַלְמָנָה, כְּאַלְמָנָה דְּאָזִיל בַּעְלָהּ לְעִבְרָא דְּיַמָּא, וּמְחַכָּאת לֵיהּ.","אָמַר רִבִּי חִיָּיא, וּמֵהָכָא מַשְׁמַע, מֵהָתָם מַשְׁמַע, דְּהוּא עִקָרָא דְּכֹלָּא, דִּכְתִּיב, (יחזקאל א׳:כ״ו) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם. כְּמַרְאֵה אָדָם, וְלָא מַרְאֶה אָדָם. אָמַר רִבִּי יִצְחָק, כְּתִיב, (שיר השירים ב׳:ג׳) כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר וְגוֹ', כְּתַפּוּחַ וְלָא תַּפּוּחַ. כְּתַפּוּחַ: דְּמִתְפָּרְשָׁא בִּגְוָונוֹי, וּבִגְוָונִין אִתְאַחֲדָא מִלָּה. אָמַר רַבִּי יְהוּדָה, אִלּוּ לָא אֲתֵינָא הָכָא אֶלָּא לְמִשְׁמַע מִלִּין אִלֵּין, דַּיָי.","תָּאנָא כְּתִיב, (זכריה י״ב:ח׳) וְהָיָה הַנִּכְשָׁל בָּהֶם בַּיּוֹם הַהוּא כְּדָוִד. כְּדָוִד, וְלָא דָּוִד. כְּדָוִד, דְּאָמַר, (דברי הימים א כ״ב:י״ד) וְהִנֵּה בְעָנְיִי הֲכִינוֹתִי לְבֵית יְיָ'. וּכְתִיב, (תהילים פ״ו:א׳) כִּי עָנִי וְאֶבְיוֹן אָנִי. וְהוּא מַלְכָּא עַל מַלְכִּין הֲוָה, וַהֲוָה קָרֵי לְגַרְמֵיהּ הָכִי. אָמַר רַבִּי אַבָּא, זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא לָא קְרָא לוֹן כְּקֹדֶשׁ, אֶלָּא קֹדֶשׁ מַמָּשׁ, דִּכְתִּיב קֹדֶשׁ יִשְׂרָאֵל לַיְיָ', וּבְּגִין כָּךְ כָּל אֹכְלָיו יֶאְשָׁמוּ וְגוֹ'.","תָּאנָא, אָמַר רִבִּי יוֹסִי, מַאי קָא חָמָא קוּדְשָׁא בְּרִיךְ הוּא, לְמֵיהַב דִּינִין לְיִשְׂרָאֵל, בָּתַר עֶשֶׂר אֲמִירָן. אֶלָּא הָכִי תָּנֵינָן, מִסִּטְרָא (פ\"ד ע\"א) דִּגְבוּרָה, אִתְיְיהִיבַת אוֹרַיְיתָא לְיִשְׂרָאֵל. בְּגִינֵי כַּךְ, בָּעָא לְמֵיתַן שְׁלָמָא בֵּינַיְיהוּ, בְּגִין דְּאוֹרַיְיתָא תְּהֵא נְטִירָא מִכָּל סִטְרוֹי. דְּאָמַר רַבִּי אַבָּא אָמַר רַבִּי יִצְחָק, לֵית עָלְמָא מִתְקַיְּימָא, אֶלָּא עַל דִּינָא, דְּאִלְמָלֵא דִּינָא, לָא מִתְקַיְּימָא. וּבְּגִין כָּךְ עָלְמָא בְּדִינָא אִתְבְּרֵי, וְאִתְקַיַּים.","תָּאנָא, רִבִּי אַבָּא, כְּתִיב (ירמיהו כ״א:י״ב) דִּינוּ לַבֹּקֶר מִשְׁפָּט. וְכִי לַבֹּקֶר, וְלָאו בְּכָל יוֹמָא. אֶלָּא לַבֹּקֶר, עַד לָא יֵיכְלוּן דַּיָּינִין, וְלָא יִשְׁתּוּן, דְּכָל מַאן דְּדָאִין דִּינָא בָּתַר דְּאָכַל וְשָׁתָה, לָאו דִּינָא דִּקְשׁוֹט הוּא, דִּכְתִּיב, (ויקרא י״ט:כ״ו) לא תֹאכְלוּ עַל הַדָּם. מַאי עַל הַדָּם. אַזְהָרָה לְדַיָּינֵי, דְּלָא יֵיכְלוּן עַד דְּדַיְינֵי דִּינָא, דְּכָל מַאן דְּדָאִין דִּינָא בָּתַר דְּאָכִיל וְשָתֵי, כְּאִלּוּ חִיֵּיב דָּמָא דְּחַבְרֵיהּ לְאַחֲרָא, דְּהָא דָּמֵיהּ מַמָּשׁ יָהִיב לְאַחֲרָא. הַאי בְּמָמוֹנָא, כָּל שֶׁכֵּן בְּדִינִי נְפָשׁוֹת, דְּבָעוּ דַּיָּינֵי לְאִסְתַּמְּרָא, דְּלָא לְמֵידָן דִּינָא אֶלָּא קֹדֶם דְּאַכְלוּ וְשָׁתוּ, וְעַל דָּא כְּתִיב דִּינוּ לַבֹּקֶר מִשְׁפָּט וּכְתִיב, (ירמיה יט) אֲנִי יְיָ' עוֹשֶׂה חֶסֶד וּמִשְׁפָּט וּצְדָקָה בָּאָרֶץ כִּי בְאֵלֶּה חָפַצְתִּי נְאֻם יְיָ'.","תַּנְיָא, אָמַר רִבִּי יְהוּדָה, מַאן דִּמְשַׁקֵּר בְּדִינָא, מְשַׁקֵּר בְּתִקּוּנֵי מַלְכָּא. מַאן תִּקּוּנֵי מַלְכָּא. אִינּוּן דְּאִתְּמַר, דִּכְתִּיב עוֹשֶׂה חֶסֶד מִשְׁפָּט וּצְדָקָה בָּאָרֶץ. וּכְתִיב כִּי בְאֵלֶּה חָפַצְתִּי נְאֻם יְיָ'. וְכֹלָּא הַאי בְּהַאי תַּלְיָא. (נ\"א והלא בהאי תליא) רִבִּי יוֹסִי אָמַר, אִלֵּין אִינּוּן תִּקּוּנֵי כֻּרְסְיָיא, דִּכְתִּיב, (תהילים פ״ט:ט״ו) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֶךָ. וּכְתִיב (ישעיהו ט״ז:ה׳) וְהוּכַן בַּחֶסֶד כִּסֵּא."],[[0,"וקב\"האמר דא וכו':","והקב\"ה אמר זה. ואנשי קדש תהיון לי. ועל כן זכו ישראל להקרא אחים אל הקב\"ה, שכתוב למען אחי ורעי וגו'. כי ישראל הם בנים ליובל, שהיא בינה, כנ\"ל, וגם ז\"א היא בן הבינה, ונמצא שהם אחים לז\"א. (ועי' בתלמוד עשר ספירות שיעור ט' דף תר\"ח ד\"ה שאין לך ודף תר\"ט ד\"ה בנים בכורים) ואח\"כ נקראים קדש ממש, שכתוב קדש ישראל לה' ראשית תבואתה, שכתוב קדש, ולא אנשי קדש. ומשום זה כל אכליו יאשמו, שכתוב, וכל זר לא יאכל קדש. ואיש כי יאכל קדש בשגגה וגו'. (כנ\"ל אות תק\"ז)."],[1,"תאנא ישראל אקרון וכו':","למדנו, ישראל נקראים קדש, ומשום שהם קדש, אסור לאדם לקרות לחבירו בשם של בזיון, ולא לכנות שם לחבירו, וענשו גדול. וכל שכן בדברים אחרים. למדנו, כתוב, נצור לשונך מרע, מהו מרע. הוא כי בשביל לשון הרע, מחלות יורדות לעולם."],[2,"אמר ר' יוסי וכו':","אר\"י, כל מי שקורא לחבירו, בשם שאין בו, ומבזה אותו, הוא נתפש לדין, על מה שאין בו. שאמר ר' חייא אמר ר' חזקיה, כל מי שקורא לחבירו רשע, מורידים אותו לגיהנם, ויורדים לו ללחייו, דהיינו שמכים אותו על לחייו. חוץ מאלו עזי הפנים שעל התורה, שמותר לאדם לקראם רשע."],[3,"ההוא גברא דלייט וכו':","איש אחד קלל את חבירו. עבר שם ר' ייסא, ואמר לו, כרשע עשית. בא לפני ר' יהודה, לדין. אמר לו, לא אמרתי לו רשע, אלא כרשע, שהראה מעשיו כרשע, ולא אמרתי שהוא רשע. בא ר' יהודה ושאל על המעשה לפני ר' אלעזר. אמר לו, ודאי שלא נתחייב, מאין לנו, כי כתוב, היה ה' כאויב, ולא אויב, שאם לא כן לא היה נשאר גזע מישראל בעולם. כעין זה היתה כאלמנה. ולא אלמנה, דהיינו כאלמנה, שבעלה הלך למדינת הים והיא מחכית עליו. שלהיותה לבדה בלי בעלה מדמה אותה לאלמנה."],[4,"אמר ר' חייא וכו':","אר\"ח, מכאן משמע זה, הלא משם נשמע, שהוא עיקר הכל, דהיינו האיסור של פסל ותמונה, שכתוב, ועל דמות הכסא דמות כמראה אדם. שבהכרח, כמראה אדם ולא מראה אדם. הרי אשר כמראה אינו דומה אל מראה. א\"ר יצחק, כתוב, כתפוח בעצי היער וגו'. היינו כתפוח ולא תפוח, שפירושו, כתפוח הניכר בצבעיו, ובצבעים מתאחד הדבר. כי יחוד הקב\"ה הוא בסוד ג' קוין שהם סוד לבן אדום ירוק, כמו שיש בתפוח. שפירושם חסד דין רחמים. אמר ר' יהודה, אלו לא באתי כאן אלא לשמוע דברים אלו היה די לי."],[5,"תאנא כתיב והיה וגו':","למדנו, כתוב, והיה הנכשל בהם ביום ההוא כדוד. היינו, רק כדוד, ולא דוד. שפירושו, כדוד, שאמר, והנה בעניי הכינותי לבית ה'. וכתוב, כי עני ואביון אני, והוא היה מלך על מלכים וקרא עצמו כן. אמר ר' אבא, אשרי הם ישראל, שהקב\"ה לא קרא אותם, כקדש, אלא קדש ממש. שכתוב, קדש ישראל לה', ומשום זה כל אוכליו יאשמו, כמו זר האוכל קדש."],[6,"תאנא אמר ר' יוסי וכו':","למדנו אר\"י, מה ראה הקב\"ה לתת הדינים לישראל, דהיינו פרשת משפטים, אחר עשרת הדברות. ומשיב, אלא כך למדנו, מצד הגבורה ניתנה התורה לישראל, משום זה, צריכים לתת שלום ביניהם, ע\"י דינים ומשפטים, כדי שהתורה תהיה שמירה מכל צדדיה. שאמר ר' אבא אמר ר' יצחק, אין העולם מתקיים אלא על דין, שלולא הדין לא היה מתקיים, ומשום זה נברא העולם בדין ונתקיים."],[7,"תאנא ר' אבא וכו':","למד ר' אבא, כתוב, דינו לבקר משפט. שואל וכי רק לבקר, ולא כל היום. ומשיב, אלא לבקר פירושו, עד שלא יאכלו השופטים ולא ישתו, שכל מי שדן דין אחר שאכל ושתה, אין הוא דין אמת, שכתוב לא תאכלו על הדם. מהו, על הדם. הוא אזהרה לשופטים, שלא יאכלו קודם שדנו דין, שכל מי שדן דין אחר שאכל ושתה, כאלו מחיב דם חבירו ונותנו לאחר, כי דמו ממש נותן לאחר, ע\"י דין שקר. זהו בכסף. כל שכן בדיני נפשות, שצריכים השופטים להשמר, שלא לדון דין, אלא לפני שאכלו ושתו. ועל זה כתוב, דינו לבקר משפט. וכתוב, אני ה' עושה חסד ומשפט וגו'."],[8,"תניא, אמר ר' יהודה וכו':","למדנו, אר\"י, מי שמשקר בדין, משקר בתקוני המלך, מה הם תקוני המלך. הם אלו שלמדנו, שכתוב, עושה חסד ומשפט וצדקה בארץ, וכתוב, כי באלה חפצתי נאום ה'. והכל, חסד ומשפט וצדקה, זה בזה תלוי. ר' יוסי אמר, אלו הם תקונים של הכסא, שהוא מלכות, שכתוב, צדק ומשפט מכון כסאך. וכתוב, והוכן בחסד כסא."]],[[0,"","וְהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר אֶת זֶה, וְעַל זֶה זָכוּ יִשְׂרָאֵל לְהִקָּרֵא אַחִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא, שֶׁכָּתוּב (תהלים קכב) לְמַעַן אַחַי וְרֵעָי וְגוֹ'. אַחַר כָּךְ נִקְרְאוּ קֹדֶשׁ מַמָּשׁ, שֶׁכָּתוּב (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה. קֹדֶשׁ וְלֹא אַנְשֵׁי קֹדֶשׁ. מִשּׁוּם כָּךְ כָּל אֹכְלָיו יֶאְשָׁמוּ, וְכָתוּב (ויקרא כב) וְכָל זָר לֹא יֹאכַל קֹדֶשׁ. (שם) וְאִישׁ כִּי יֹאכַל קֹדֶשׁ בִּשְׁגָגָה."],[1,"","שָׁנִינוּ, יִשְׂרָאֵל נִקְרְאוּ קֹדֶשׁ, וּמִשּׁוּם שֶׁהֵם קֹדֶשׁ אָסוּר לְאָדָם לִקְרֹא לַחֲבֵרוֹ בְּשֵׁם גְּנַאי וְלֹא לְכַנּוֹת שֵׁם לַחֲבֵרוֹ, וְעָנְשׁוֹ גָּדוֹל, וְכָל שֶׁכֵּן בִּדְבָרִים אֲחֵרִים. שָׁנִינוּ, כָּתוּב (תהלים לד) נְצֹר לְשׁוֹנְךְ מֵרָע וְגוֹ'. מַהוּ מֵרָע? שֶׁבִּגְלַל לָשׁוֹן הָרָע מַחֲלוֹת יוֹרְדוֹת לָעוֹלָם."],[2,"","אָמַר רַבִּי יוֹסֵי, כָּל מִי שֶׁקּוֹרֵא לַחֲבֵרוֹ בְּשֵׁם שֶׁאֵין בּוֹ וּמְגַנֶּה אוֹתוֹ, נִתְפָּס בְּמַה שֶּׁאֵין בּוֹ. שֶׁאָמַר רַבִּי חִיָּא אָמַר רַבִּי חִזְקִיָּה, כָּל מִי שֶׁקּוֹרֵא לַחֲבֵרוֹ רָשָׁע, מוֹרִידִים אוֹתוֹ לַגֵּיהִנֹּם, וְיוֹרְדִים לוֹ לִלְחָיָיו, פְּרָט לְאוֹתָם חֲצוּפִים שֶׁל הַתּוֹרָה שֶׁמֻּתָּר לָאָדָם לִקְרֹא לָהֶם רָשָׁע."],[3,"","אוֹתוֹ אִישׁ שֶׁקִּלֵּל אֶת חֲבֵרוֹ, עָבַר רַבִּי יֵיסָא, אָמַר לוֹ, כְּמוֹ רָשָׁע עָשִׂיתָ. בָּא לִפְנֵי רַבִּי יְהוּדָה. אָמַר לוֹ, רָשָׁע לֹא אָמַרְתִּי לוֹ, אֶלָּא כְּרָשָׁע, שֶׁמַּרְאֵה דְבָרָיו כְּרָשָׁע, וְלֹא אָמַרְתִּי שֶׁהוּא רָשָׁע. בָּא רַבִּי יְהוּדָה וְשָׁאַל לַמַּעֲשֶׂה לִפְנֵי רַבִּי אֶלְעָזָר. אָמַר לוֹ, וַדַּאי שֶׁלֹּא הִתְחַיֵּב. מִנַּיִן לָנוּ? שֶׁכָּתוּב (איכהב) הָיָה ה' כְּאוֹיֵב, וְלֹא אוֹיֵב. שֶׁאִם לֹא כָּךְ, לֹא נִשְׁאַר מִיִּשְׂרָאֵל גְּזָעִים בָּעוֹלָם. כְּמוֹ זֶה, (שם א) הָיְתָה כְּאַלְמָנָה, וְלֹא אַלְמָנָה. כְּאַלְמָנָה שֶׁהָלַךְ בַּעְלָהּ לְעֵבֶר הַיָּם וּמְחַכָּה לוֹ."],[4,"","אָמַר רַבִּי חִיָּיא, וּמִכָּאן מַשְׁמָע? מִשָּׁם מַשְׁמָע, שֶׁהוּא עִקַּר הַכֹּל, שֶׁכָּתוּב (יחזקאל א) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם. כְּמַרְאֵה אָדָם, וְלֹא מַרְאֵה אָדָם. אָמַר רַבִּי יִצְחָק, כָּתוּב כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר וְגוֹ'. כְּתַפּוּחַ, וְלֹא תַפּוּחַ. כְּתַפּוּחַ, שֶׁנִּפְרָד בִּגְוָנָיו, וּבִגְוָנִים אָחוּז הַדָּבָר. אָמַר רַבִּי יְהוּדָה, אִלּוּ לֹא בָאתָ לְכָאן אֶלָּא לִשְׁמֹעַ הַדְּבָרִים הַלָּלוּ - דַּי."],[5,"","שָׁנִינוּ, כָּתוּב (זכריהיב) וְהָיָה הַנִּכְשָׁל בָּהֶם בַּיּוֹם הַהוּא כְּדָוִד. כְּדָוִד, וְלֹא דָוִד. כְּדָוִד שֶׁאָמַר וְהִנֵּה בְעָנְיִי הֲכִינוֹתִי לְבֵית ה'. וְכָתוּב (תהלים פו) כִּי עָנִי וְאֶבְיוֹן אָנִי. וְהוּא הָיָה מֶלֶךְ עַל מְלָכִים וְהָיָה קוֹרֵא לְעַצְמוֹ כָּךְ. אָמַר רַבִּי אַבָּא, אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא קָרָא לָהֶם כְּקֹדֶשׁ, אֶלָּא קֹדֶשׁ מַמָּשׁ, שֶׁכָּתוּב קֹדֶשׁ יִשְׂרָאֵל לַה', וּמִשּׁוּם כָּךְ כָּל אֹכְלָיו יֶאְשָׁמוּ וְגוֹ'."],[6,"","שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, מָה רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לָתֵת דִּינִים לְיִשְׂרָאֵל אַחַר עֶשֶׂר הָאֲמִירוֹת? אֶלָּא כָּךְ שָׁנִינוּ, מִצַּד הַגְּבוּרָה נִתְּנָה תּוֹרָה לְיִשְׂרָאֵל, מִשּׁוּם כָּךְ צָרִיךְ לָתֵת שָׁלוֹם בֵּינֵיהֶם כְּדֵי שֶׁהַתּוֹרָה תִּהְיֶה שְׁמוּרָה מִכָּל צְדָדֶיהָ. שֶׁאָמַר רַבִּי אַבָּא אָמַר רַבִּי יִצְחָק, אֵין הָעוֹלָם מִתְקַיֵּם אֶלָּא עַל דִּין, שֶׁאִלְמָלֵא הַדִּין לֹא יַעֲמֹד, וּמִשּׁוּם כָּךְ הָעוֹלָם נִבְרָא בְדִין וְהִתְקַיֵּם."],[7,"","שָׁנִינוּ, רַבִּי אַבָּא, כָּתוּב (ירמיה כא) דִּינוּ לַבּקֶר מִשְׁפָּט. וְכִי לַבֹּקֶר וְלֹא בְּכָל הַיּוֹם? אֶלָּא לַבּקֶר, טֶרֶם שֶׁיֹּאכְלוּ הַדַּיָּנִים וְלֹא יִשְׁתּוּ, שֶׁכָּל מִי שֶׁדָּן דִּין אַחַר שֶׁאָכַל וְשָׁתָה, אֵינוֹ דִּין אֱמֶת, שֶׁכָּתוּב (ויקראיט) לֹא תֹאכְלוּ עַל הַדָּם. מַה זֶּה עַל הַדָּם? אַזְהָרָה לְדַיָּנִים שֶׁלֹּא יֹאכְלוּ עַד שֶׁדָּנִים דִּין. שֶׁכָּל מִי שֶׁדָּן דִּין אַחַר שֶׁאָכַל וְשָׁתָה, כְּאִלּוּ חִיֵּב אֶת דַּם חֲבֵרוֹ לְאַחֵר, שֶׁהֲרֵי דָּמוֹ מַמָּשׁ נָתַן לְאַחֵר. זֶה בְּמָמוֹן, כָּל שֶׁכֵּן בְּדִינֵי נְפָשׁוֹת שֶׁצְּרִיכִים הַדַּיָּנִים לְהִשָּׁמֵר שֶׁלֹּא לָדוּן דִּין אֶלָּא קֹדֶם שֶׁאָכְלוּ וְשָׁתוּ, וְעַל זֶה כָתוּב דִּינוֹ לַבֹּקֶר מִשְׁפָּט, וְכָתוּב (ירמיה ט) אֲנִי ה' עֹשֶׂה חֶסֶד וּמִשְׁפָּט וּצְדָקָה בָּאָרֶץ כִּי בְאֵלֶּה חָפַצְתִּי נְאֻם ה'."],[8,"","שָׁנִינוּ, אָמַר רַבִּי יְהוּדָה, מִי שֶׁמְּשַׁקֵּר בַּדִּין, מְשַׁקֵּר בְּתִקּוּנֵי הַמֶּלֶךְ. מָהֵם תִּקּוּנֵי הַמֶּלֶךְ? אוֹתָם שֶׁנֶּאֱמַר, שֶׁכָּתוּב עֹשֶׂה חֶסֶד מִשְׁפָּט וּצְדָקָה בָּאָרֶץ. וְכָתוּב כִּי בְאֵלֶּה חָפַצְתִּי נְאֻם ה'. וְהַכֹּל תָּלוּי זֶה בָּזֶה (והלא בזה תלוי). רַבִּי יוֹסֵי אָמַר, אֵלֶּה הֵם תִּקּוּנֵי הַכִּסֵּא, שֶׁכָּתוּב (תהלים פט) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֶךְ. וְכָתוּב (ישעיה טז) וְהוּכַן בַּחֶסֶד כִּסֵּא."]]],[["\u0003כאן מתחיל אידרא דמשכנא\u0004 תַּנְיָא בְּרָזָא דְּרָזִין, רֵישָׁא דְּמַלְכָּא, אִתְתָּקַּן בְּחֶסֶד וּבִגְבוּרָה. בְּהַאי רֵישָׁא, תַּלְיָין שַׁעֲרֵי, נִימִין עַל נִימִין, דְּאִינּוּן כֹּל מְשִׁיכוּתָא דְּמִתְאַחֲדָן בְּהוּ עִלָּאֵי וְתַתָּאֵי. מָארֵי דְּמָארִין, מָארֵי דִּקְשׁוֹט, מָארֵי דְּמִתְקְלָא, מָארֵי דִּיבָבָא, מָארֵי דִּילָלָה, מָארֵי דְּדִינָא, מָארֵי דְּרַחֲמֵי, וְטַעֲמֵי אוֹרַיְיתָא, וְרָזֵי אוֹרַיְיתָא דַּכְיָין, מִסְאָבָן, כֻּלְּהוּ אִקְרוּן שַׁעֲרֵי דְּמַלְכָּא, כְּלוֹמַר מְשִׁיכוּתָא דְּאִתְמְשַׁךְ מִמַּלְכָּא קַדִּישָׁא, וְכֹלָּא נָחִית מֵעַתִּיקָא סְתִימָאָה. (קדישא)","מִצְחָא דְּמַלְכָּא, פְּקִידוּתָא דְּחַיָּבַיָּא, כַּד אִתְפַּקְּדָן בְּעוֹבָדַיְיהוּ, וְכַד אִתְגַּלְּיָין חוֹבַיְיהוּ, כְּדֵין אִקְרֵי מִצְחָא דְּמַלְכָּא. כְּלוֹמַר, גְּבוּרָה אִתְתָּקַּף בְּדִינוֹי, וְאִתְפָּשַּׁט בְּסִטְרוֹי, וְדָא אִשְׁתָּנֵי מִמִּצְחָא דְּעַתִּיקָא קַדִּישָׁא, דְּאִקְרֵי רָצוֹן.","עַיְינִין דְּמַלְכָּא, אַשְׁגָּחוּתָא דְּכֹלָּא, אַשְׁגָּחוּתָא דְּעִלָּאִין וְתַתָּאִין, וְכָל אִינּוּן מָארֵי אַשְׁגָּחוּתָא הָכִי אִקְרוּן. בְּעַיְינִין, גַּוְונִין אִתְאַחֲדָן, וְאִינּוּן גַּוְונִין אִקְרוּן, כָּל אִינּוּן מָארֵי אַשְׁגָּחוּתָא דְּמַלְכָּא, כָּל חַד כְּפוּם אָרְחֵיהּ, וְכֻלְּהוּ גַּוְונִין דְּעֵינָא אִקְרוּן. כְּמָה דְּאִתְחָזֵי אַשְׁגָּחוּתָא דְּמַלְכָּא, הָכִי גַּוְונִין מִתְעָרִין.","גְּבִינֵי דְּעַיְינִין, אִקְרוּן, אֲתָר דְּיַהֲבִין אַשְׁגָּחוּתָא, לְכֻלְּהוּ גַּוְונִין מָארֵי אַשְׁגָּחוּתָא. הָנֵי גְּבִינִין לְגַבֵּי דִּלְתַתָּא, גְּבִינִין לְאַשְׁגָּחוּתָא מֵהַהוּא נַהֲרָא דְּנָגִיד וְנָפִיק, אֲתָר לְאִתְמַשְּׁכָא מֵהַהוּא נַהֲרָא, לְאִסְתַּחֲאָה בְּחִוָּורָא דְּעַתִּיקָא, מֵחֲלָבָא דְּנָגִיד מֵאִמָא. דְּכַד גְּבוּרָה מִתְפַּשְּׁטָא, וְעַיְינִין מְלַהֲטָן בְּגָוֶון סוּמָקָא, נָהִיר עַתִּיקָא קַדִּישָׁא חִיוָּרָא דִּילֵיהּ, וְלָהֲטָא בְּאִמָּא, וְאִתְמַלְּיָיא מֵחֲלָבָא, וְיָנְקָא לְהָנֵי, (לכלא) וְאִסְתְּחָן כֻּלְּהוּ עַיְינִין, בְּהַהוּא חֲלָבָא דְּאִמָּא, דְּאִתְנְגִיד וְנָפִיק תָּדִיר. הֲדָא הוּא דִכְתִיב, (שיר השירים ה׳:י״ב) רוֹחֲצוֹת בֶּחָלָב. בֶּחָלָב דְּאִמָא, דְּנָגִיד תָּדִירָא וְלָא פָּסִיק.","חוֹטָמָא דְּמַלְכָּא קַדִּישָׁא, תִּקּוּנָא דְּפַרְצוּפָא, כַּד מִתְפַּשְּׁטָן גְּבוּרָן, וּמִתְאַחֲדָן כַּחֲדָא, אִינּוּן חוֹטָמָא דְּמַלְכָּא קַדִּישָׁא. וְאִינּוּן גְּבוּרָן מֵחַד גְּבוּרָה אֲחִידָן וְנָפְקִין. וְכַד דִּינִין מִתְעָרִין, וְנָפְקִין מִסִּטְרַיְיהוּ, לָא מִתְבַּסְּמָן, אֶלָּא בִּתְנָנָא דְּמַדְבְּחָא. וּכְדֵין כְּתִיב, (בראשית ח׳:כ״א) וַיָּרַח יְיָ' אֶת רֵיחַ הַנִּיחוֹחַ. שָׁאנֵי חוֹטָמָא דְּעַתִּיקָא, דְּלָא אִצְטְרִיךְ, דְּחוֹטָמָא דְּעַתִּיקָא, אֹרֶךְ אַפַּיִם בְּכֹלָּא אִקְרֵי, וְהַהוּא נְהִירוּ דְּחָכְמְתָא סְתִימָאָה, אִקְרֵי חוֹטָמָא דִּילֵיהּ. וְהַיְינוּ תְּהִלָּה, דִּכְתִּיב, (ישעיהו מ״ח:ט׳) וּתְהִלָּתִי אֶחטָם לָךְ. וְעַל דָּא אִתְּעַר דָּוִד מַלְכָּא, (תהילים קמ״ה:א׳) תְּהִלָּה לְדָוִד וְגוֹ'.","אוּדְנִין דְּמַלְכָּא, כַּד רַעֲוָא אִשְׁתְּכַח, וְאִמָא יַנְקָא, וּנְהִירוּ דְּעַתִּיקָא קַדִּישָׁא אִתְנְהִיר, מִתְעֲרִין נְהִירוּ דִּתְרֵין מוֹחֵי, וּנְהִירוּ דְּאַבָּא וְאִמָא, כָּל אִינּוּן דְּאִקְרוּן מוֹחֵי דְּמַלְכָּא, וּמִתְלַהֲטִין כַּחֲדָא. וְכַד מִתְלַהֲטָן כַּחֲדָא, אִקְרוּן אָזְנֵי יְיָ'. דְּהָא אִתְקַבִּילַת צְלוֹתֵהוֹן דְּיִשְׂרָאֵל. וּכְדֵין אִתְעָרוּתָא לְטָב וּלְבִישׁ, וּבְאִתְעָרוּתָא דָּא, מִתְעֲרִין מָארֵי דְּגַדְפִּין, דְּנַטְלִין קָלִין דְּעָלְמָא, וְכֻלְּהוּ אִקְרוּן אָזְנֵי יְיָ'.","אַנְפּוֹי דְּמַלְכָּא, נְהִירוּ דְּאַבָּא וְאִמָּא, וְאִתְפַּשְּׁטוּתָא דִּלְהוֹן, דְּנַהֲרִין וְסַחֲרִין, וְלָהֲטִין בְּהַאי רֵישָׁא דְּמַלְכָּא. וּכְדֵין סַהֲדוּתָא אִסִתְּהַד בְּמַלְכָּא (נ\"א במלכא דמלכא) מִנַּיְיהוּ. דִּיּוּקְנָא דְּמַלְכָּא, יַקִּירוּתָא מִכֹּלָּא. מֵרִישָׁא שָׁארֵי חֶסֶד עִלָּאָה, וּגְבוּרָה. וּנְהִירוּ דְּאַבָּא וְאִמָּא אִתְפְּלַג, נְהִירוּ דְּאַבָּא בִּתְלַת נְהוֹרִין, וְאִמָא בִּתְרֵין, הָא חֲמִשָּׁה. חֶסֶד וּגְבוּרָה בְּחַד נְהוֹרָא, הָא שִׁיתָא. לְבָתַר, אִתְעַטָּר חֶסֶ\"ד, וְאִתְלְהִיט (ואתנהיר) בִּתְרֵין נְהוֹרִין דְּאִתְנְהִיר וְאִינּוּן תְּמַנְיָיא. (נ\"א לבתר אתעטר') וּגְבוּרָה, אִתְנְהִיר בְּחַד, הָא תִּשְׁעָה. וְכַד מִתְחַבְּרָן כֻּלְּהוּ נְהוֹרִין כַּחֲדָא, אִקְרוּן דִּיּוּקְנָא דְּמַלְכָּא, וּכְדֵין כְּתִיב, (ישעיהו מ״ב:י״ג) יְיָ' כַּגִבּוֹר יֵצֵא כְּאִישׁ מִלְחָמוֹת יָעִיר קִנְאָה וְגוֹ'.","שִׁפְוָון דְּמַלְכָּא, הָכִי תָּאנָא, כַּד אִתְנְהִיר נְהִירוּ דְּאַבָּא, נָהִיר בִּתְלַת נְהוֹרִין. מֵחַד נְהוֹרָא, נָהִיר חֶסֶד עִלָּאָה. מֵחָד נְהוֹרָא, אִתְנְהִיר נְהִירוּ דְּאִקְרֵי מוֹחָא דְּמַלְכָּא. וְחַד נְהוֹרָא, הֲוָה תָּלֵי, עַד דְּאִתְנְהִיר נְהִירוּ דְּאִמָא. וְכַד אִתְנְהִיר אִתְנְהִיר בְּחָמֵשׁ נְהוֹרִין."],[[0,"תניא ברזא דרזין וכו':","למדנו בסוד הסודות, הראש של המלך, נתתקן בחסד וגבורה."],[0,"","פירוש. הג\"ר שהם חב\"ד, נקראים ראש. המלך, הוא ז\"א. וכיון שחב\"ד אלו אינם בקביעות בז\"א, אלא בשעת התפלה ובמועדים ובשבתות, אינם נחשבים לחו\"ב אלא לחסד וגבורה. דהיינו ו\"ק. וזה הפרש הגדול בין א\"א שג\"ר שלו הם בקביעות שהמה ג\"ר ממש, כולו רחמים, לבין ז\"א, שג\"ר שלו אינם בקביעות, וע\"כ אפילו בזמן שיש לו ג\"ר שהם חב\"ד, נחשבים לו כמו חג\"ת, ויש בהם דינים. ומה שאין הזהר חושב גם ת\"ת, הוא, משום שאפילו בא\"א אין הדעת מבחינת ראש אלא שהוא ת\"ת שעלה לראש, והכריע בין חו\"ב, ונעשה משום זה בחינת ראש וע\"כ אין בו חידוש. \u0003בהאי רישא תליין וכו':\u0004 בראש ההוא, דז\"א, תלוים שערות, שערות על שערות, שהם כל ההמשכות שעל ידיהן מתאחדות מדרגות עליונות ותחתונות. כלומר, שעל ידיהן עולה מדרגה התחתונה אל העליונה, ונעשות אחת. ומהם, מן השערות, נמשכים, אדוני האדונים, בעלי אמת, בעלי המשקל, בעלי אנחה, בעלי בכיה, בעלי דין, בעלי רחמים, טעמי תורה, סודות התורה, טהרות, וטומאות. כולם נקראים שערות המלך, כלומר, המשכות הנמשכות ממלך הקדוש. והכל יורד מעתיקא סתימאה. שהוא א\"א."],[0,"","ביאור הדברים. מדרגה הראשונה, שבה עלתה ה\"ת לנקבי עינים, וסיימה שם המדרגה, ואח\"פ נפלו ממנה למדרגה שמתחתיה \u0003שה\"ס צמצום ב',\u0004 היא מדרגת ראש הס\"ג דא\"ק, אמנם בראש הס\"ג עצמו לא נעשה שום שינוי משהו, אלא שיצאה מדרגה חדשה של עשר ספירות, שנתלו בע\"ס דראש הס\"ג דא\"ק, והיא מכונה \u0003פרצוף השערות\u0004 דראש הס\"ג, אשר החלק שנשאר במדרגה, שהם גלגלתא ועינים ונקבי עינים, הם מכונים \u0003שערות רישא,\u0004 והחלק שיצא ממדרגת ראש דס\"ג שהם אזן חוטם פה, שנפלו למדרגה שמתחתיה, לג\"ר דנקודים, הם מכונים \u0003שערות דיקנא\u0004, דראש הס\"ג. (כמ\"ש בתלמוד עשר ספירות בשיעור ו' דף שס\"א ד\"ה שערות עש\"ה)."],[0,"","ובעולם התיקון נתלה פרצוף השערות בראש אריך אנפין דאצילות, אשר האח\"פ שלו שהם שערות דיקנא, נפלו למדרגה שמתחתיו, שהם או\"א דאצילות ומלובשים שם בעת קטנות. ולעת גדלות, שנעשה זווג דע\"ב ס\"ג דא\"ק, ומוריד ה\"ת מפאתי הראש דס\"ג דא\"ק לסיום הדיקנא והדיקנא דס\"ג עולה ומתחבר בשערות רישא למדרגה אחת, אז יורדת ג\"כ ה\"ת מפאתי הראש דא\"א לסיום הדיקנא שלו ואז חוזר הדיקנא דא\"א ועולה לשערות רישא דא\"א, ומתחבר עמו למדרגה אחת. ובשעת חזרתו הוא מעלה עמו גם או\"א לראש א\"א, ומקבלים שם מחכמה סתימאה דא\"א. ואחרי עלית הדיקנא עם או\"א לראש א\"א, נמשכות אחריהם כל חצאי מדרגות שלמטה מהם, שנפלו למדרגות שמתחתיהן, ועולות בחזרה למדרגתן שעל ידי זה גם כל מדרגה תחתונה שבעת קטנות היתה לה האח\"פ מעליונה, עולה גם היא עם אח\"פ אלו לעליונה, שכן ישסו\"ת עולים לאו\"א ע\"י אח\"פ דאו\"א שהיו בהם בקטנות. וכן זו\"ן עולים לישסו\"ת ע\"י אח\"פ דישסו\"ת שהיו בהם בקטנות, וכן נשמות הצדיקים עולים לזו\"ן ע\"י אח\"פ דזו\"ן שהיו בהם בעת קטנות. הרי שכל עלית התחתון לעליון להתאחד עמו לאחד, נעשה ע\"י שערות דיקנא דא\"א שהעלו את או\"א לראש דא\"א. שאחריה נמשכות עלית כל תחתון לעליון, כנ\"ל. (עי' לעיל בראשית א' דף צ' ד\"ה בגין)."],[0,"","וזה אמרו, \u0003דאינון כל משיכותא דמתאחדן בהו עלאי ותתאי,\u0004 שהשערות הן כל ההמשכה שעל ידיהן מתאחדות מדרגות העליונות והתחתונות לאחת, כי על ידיהן עולה כל מדרגה תחתונה לעליונה שלה, שאו\"א עולים לא\"א, וישסו\"ת לאו\"א, וזו\"ן לישסו\"ת, ונשמות הצדיקים לזו\"ן כמבואר."],[0,"","וכל המוחין דאצילות ובי\"ע, הן כל מיני הקטנות והן כל מיני הגדלות יוצאים מפרצוף השערות האלו שבראש א\"א, וכן מפרצוף השערות שעל ראש ז\"א, נמשכות כל מיני המדרגות, של נשמות הצדיקים וז\"ש, שנמשכין מהן, \u0003מארי דמארין,\u0004 היינו מדרגת ג\"ר דג\"ר, כי ג\"ר מכונה מארי. והיינו חכמה. \u0003מארי דקשוט,\u0004 היינו בינה. \u0003מארי דמתקלא,\u0004 היינו דעת שהוא קו האמצעי, השוקל הארת ימין ושמאל שיוכלו להאיר יחד. \u0003מארי דיבב אמארי דיללה,\u0004 שבשליטת קו השמאל בלי ימין נמשכים ממנו דינים קשים, וכל הדבוק בו, מיבב ומילל, ומכונים מארי דיבבא ומארי דיללה. וכן מכונים \u0003מארי דדינא.\u0004 וכשקו האמצעי מיחד השמאל עם הימין, יוצא מקו אמצעי \u0003מארי דרחמי.\u0004 וכן, \u0003טעמי תורה,\u0004 בסו\"ה טעמו וראו כי טוב ה'. \u0003וסודות התורה,\u0004 ובעת הגדלות נמשכת מהם טהרה. ובעת הקטנות נמשכת מהם טומאה. \u0003כלהו אקרון שערי דמלכא, כלומר משיכותא דאתמשך ממלכא קדישא.\u0004 שכל מיני המשכות שנמשכים מז\"א באים מן השערות שלו, כמבואר בשערות ראש א\"א. וז\"ש, \u0003וכלא נחית מעתיקא סתימאה,\u0004 שהוא א\"א, ששערות ראש דא\"א הן השורש לשערות ראש ז\"א."],[1,"מצחא דמלכא פקידותא וכו':","המצח של המלך, שהוא ז\"א, הוא פקידה של הרשעים. כשמעשיהם נפקדים, ונתגלה עונותיהם, אז נקרא מצח המלך. כלומר, הגבורה מתגברת בדיניה ומתפשטת בצד שלה. וזה נשתנה ממצח עתיקא קדישא שנקרא רצון."],[1,"","פירוש. \u0003ב' אזנים,\u0004 ה\"ס אבא ואמא עלאין. שה\"ס ג\"ר דבינה. \u0003המצח,\u0004 ה\"ס הדעת, המזווג לאו\"א, כי שם נתקן המסך מן ה \u0003י'\u0004, שה\"ס מלכות, שעלתה ל \u0003אור\u0004 הבינה ומיעטה אותה לבחינת אויר, שה\"ס אור החסדים, ועל המסך הזה ד \u0003י',\u0004 שבתוך \u0003המצח\u0004 מזדווגים או\"א עלאין בזווג גדול ונפלא מאד להשפיע שפע אור החסדים לכל העולמות, וזווג הזה הוא זווג שאינו נפסק לעולם, שאין דוגמתו במדרגה אחרת. ולפיכך, אין ה \u0003י'\u0004 יורדת מן אויר דאו\"א לעולם, כי אם היתה יורדת היה נפסק הזווג הגדול והנפלא הזה. וז\"ס, כי חפץ חסד \u0003הוא\u0004, כי \u0003הוא,\u0004 שהיא הבינה הנקראת \u0003הוא, חפץ\u0004 בזווג הגדול להשפיע \u0003חסדים,\u0004 ואינה חפצה שה \u0003י'\u0004 תרד מאויר שלה, ולהשפיע אור החכמה, כמבואר. וז\"ס אשר \u0003מצח דא\"א,\u0004 נקרא \u0003מצח הרצון,\u0004 כי הדינים שב \u0003י'\u0004 שעלתה שם, נתקנו למסך המזווג את או\"א עלאין מחמת \u0003הרצון\u0004 להשפיע לעולמות מאור החסדים הנמשך מזווג דלא פסיק של או\"א עלאין."],[1,"","אמנם המצח של ז\"א, בשעה שאינו מקבל ממצח דא\"א, אין שם הזווג הגדול דאו\"א עלאין על הדינים של ה \u0003י'\u0004 שנכנסה באור הבינה, ונמצא שמסך הזה ד \u0003י',\u0004 משמש רק להעניש את הרשעים שחטאו, שלא יהנו מאור החכמה. וע\"כ נכנסה ב \u0003אור\u0004 ומיעטה אותו ל \u0003אויר.\u0004"],[1,"","וזה אמרו. \u0003כד אתפקדן בעובדייהו וכד אתגליין חובייהו, כדין אקרי מצחא דמלכא,\u0004 דהיינו שבשעה שנגלו עונות התחתונים ואינם ראוים לקבל אור החכמה, אז משמש המצח של המלך להעלים מהם אור הזה, מכח ה \u0003י'\u0004 שעלתה לאור אשר שם, ומיעטה אותו לאויר. וז\"ש, \u0003כלומר, גבורה אתתקף בדינוי,\u0004 לדון הרשעים, \u0003ואתפשט בסטרוי\u0004 שהדין נתפשט להעלים האור מן הרשעים, ולהענישם. \u0003ודא אשתני ממצחא דעתיקא קדישא דאקרי רצון,\u0004 כי במצח דעתיקא, שהוא א\"א, נתתקן המסך הזה בסוד המצח שלו, כדי לזווג או\"א עלאין בסוד הזווג דלא פסק לעלמין, וע\"כ ה \u0003י'\u0004 שעלתה באור אשר שם, ונעשתה למסך, הוא \u0003לרצון\u0004 גדול, שהרי עליה נעשה הזווג הגדול דאו\"א עלאין, כמבואר לעיל. וע\"כ נקרא \u0003מצח הרצון.\u0004"],[2,"עיינין דמלכא אשגחותא וכו':","העינים של המלך, היינו ההשגחה על כל, ההשגחה על עליונים ועל תחתונים. וכל אלו בעלי ההשגחה של המלך, נקראים כך, עינים. בעינים מתאחדים צבעים, דהיינו לבן אדום ירוק, ובאלו הצבעים נקראים כל בעלי ההשגחה של המלך, כל אחד לפי דרכו, וכולם נקראים צבעי העין. כמו שמתראה ההשגחה של המלך, כך מתעוררים הצבעים. אם הוא השגחה של חסד, הוא לבן, ואם של דין, הוא אדום, ואם של רחמים, הוא ירוק."],[2,"","פירוש. השגחה ה\"ס חכמה, כי אין השגחה אלא מאור החכמה, בסו\"ה, כולם בחכמה עשית. ואומר, שעינים ה\"ס ההשגחה, דהיינו חכמה. \u0003וג' גווני עינא,\u0004 ה\"ס ג' קוין ימין שמאל אמצעי, שאין החכמה מתגלה זולת על כולם יחד. וע\"כ כל גוון הוא בחינת השגחה מיוחדת, להיותו חלק מחכמה."],[3,"גביני דעיינין אקרון וכו':","גבות עינים, נקרא המקום שנותן השגחה לכל צבעי בעלי השגחה. גבות האלו כלפי מה שלמטה, דהיינו כלפי העינים, הן גבות, להסתכל ולהמשיך מנהר ההוא הנמשך ויוצא, שהוא בינה. הוא מקום למשוך מנהר ההוא, להתרחץ בלובן של עתיקא, דהיינו אור החסדים, מחלב הנמשך מאמא. ומפרש דבריו. כי כאשר הגבורה, שהוא קו שמאל, מתפשטת, והעינים, שה\"ס החכמה, לוהטות בצבע אדום מרוב הדינים, להיותה חכמה בלי חסדים. אז מאיר עתיקא קדישא, שהוא הכתר, את הלובן שלו, שהוא אור החסדים, ולוהט באמא, דהיינו באבא ואמא עלאין, ונתמלאה מחלב, שהוא אור החסדים, שקבלה מן הכתר, ויונקת את אלו העינים, ומתרחצות כל העינים מחלב ההוא דאמא עלאה, הנמשך ויוצא תמיד. שהחכמה שהיא העינים, מתלבשת בחסדים ההם. ז\"ש רוחצות בחלב. דהיינו, עיניו כיונים על אפיקי מים רוחצות בחלב יושבות על מלאת שהן רוחצות בחלב דאמא שנמשך תמיד ולא נפסק. כי זווג דאו\"א עלאין הוא זווג דלא פסיק כנ\"ל בדבור הסמוך."],[3,"","פירוש. השערות הנקראים גבות עינים ה\"ס כחות הדין הנמשחים מן המצח, דהיינו מן המסך ד \u0003י'\u0004 שבאויר אשר שם, שעליו מזדווגים או\"א עלאין בזווג דלא פסיק, ונתלות בסיום המצח. ולפיכך, כחן יפה לעורר את אמא עלאה, שתשפיע החלב שלה, שה\"ס אור החסדים, לרחוץ בו העינים, שה\"ס חכמה. ולולא השערות האלו, לא היתה אמא עלאה משפעת החסדים לרחיצת העינים. ובלי חסדים אין החכמה יכולה להאיר, שזה נבחן, שהעינים לוהטות בצבע אדום. כמ\"ש בפנים."],[3,"","וזה אמרו. \u0003גביני דעיינין אקרון אתר דיהבין אשגחותא לכלהו גוונין מארי אשגחותא.\u0004 כי הגבות מעוררות אמא עלאה להשפיע חסדים לרחיצת העינים שזולת החסדים ההם לא היתה החכמה מאירה, ונמצא שגבות העינים נותנות כח ההשגחה, לכל בעלי ההשגחה, דהיינו שנותנות כח לחכמה שתוכל להאיר שזולתן לא היתה מאירה. וז\"ש, \u0003הני גבינין לגבי דלתתא,\u0004 כי הן אותם הדינים שבמצח עצמו, אלא אותם שבמצח הם לזווג או\"א עלאין, ואותן שבקעו ויצאו לחוץ, הן למה שלמטה מן המצח, דהיינו בשביל העינים. (והשאר כבר מבואר)."],[4,"חוטמא דמלכא קדישא וכו':","החוטם של המלך הקדוש, שהוא ז\"א, הוא תקון הפרצוף. כאשר הגבורות מתפשטות ומתאחדות יחד, הן החוטם של המלך הקדוש. ואלו הגבורות בגבורה אחת מתאחדות ויוצאות. וכשהדינים מתעוררים ויוצאים כל אחד מצד שלו, אינם מתבשמים אלא בעשן המזבח. ואז כתוב, וירח ה' את ריח הניחוח. ומשונה הוא החוטם של עתיקא, שהוא א\"א, שאינו צריך, לעשן המזבח, כי ארך אפים נקרא לגמרי, והארת החכמה סתימאה נקראת חוטם שלו. וזהו \u0003תהלה,\u0004 שכתוב, ותהלתי א \u0003חטם\u0004 לך. ועל זה העיר דוד המלך. תהלה לדוד וגו'."],[4,"","פירוש. החוטם ה\"ס קו אמצעי המיחד ב' הקוין ימין ושמאל זה בזה, שהם ב' העינים. כי ב' פעמים חב\"ד יש בראש. א) ב' אודנין ומצחא, והם חב\"ד דאו\"א עלאין, שהחכמה נעלמת בהם. ב) ב' עיינין וחוטמא, והם חב\"ד דישסו\"ת, שבהם מתגלית החכמה, והיינו על ידי קו האמצעי, שהוא החוטם. ונודע, שקו האמצעי, הוא הנושא להדינים של מסך דחירק, שהם ב' מיני דינים, של צמצום א' ושל צמצום ב',כמ\"ש לעיל פרשת לך דף י\"ג ד\"ה ונתבאר). ומלבד אלו יש בו גם הדינים שבקו שמאל שהוא העליון שלו ודינים שבעליון מוכרחים להיות בתחתון. ונמצא שיש בו ג' מיני דינים. דינים עליונים דקו שמאל מסוד נקודת השורק, וב' מיני דינים דמסך דנקודת החירק. וכשמתאחדים יחד, אז נשלם כחו של קו האמצעי להכריע וליחד ב' הקוין ימין ושמאל זה בזה. וז\"ש, \u0003כד מתפשטן גבורן ומתאחדן כחדא אינון חוטמא דמלכא קדישא,\u0004 שמיחודם יחד נעשה קו האמצעי הנקרא חוטם, ומגלה החכמה. אמנם כשמתאחדים יחד, עולים כולם לגבורה עליונה, דהיינו לדינים דקו שמאל, ומתבשמים שמה. וז\"ש, \u0003ואינון גבורן מחד גבורה אחידן ונפקין,\u0004 דהיינו שנכללו בגבורה דקו שמאל, ומשם יוצאים ופועלים. ואם מתקלקל יחודם זה בזה, ופועלים בפרוד, אין להם תקון אלא ע\"י עשן המזבח, העולה מן הקרבנות, כי עשן הקרבן כולל האיחוד של ג' מיני גבורות ההם, וז\"ש, \u0003וכד דינין מתערין ונפקין מסטרייהו,\u0004 דהיינו שכל אחד יוצא לצד שלו ואינם מאוחדים, \u0003לא מתבסמן אלא בתננא דמדבחא,\u0004 שעשן המזבח מאחד אותם שוב, ואז כתוב, וירח ה' את ריח הניחוח. דהיינו שמתגלה החכמה הנקראת \u0003ריח.\u0004"],[4,"","וכל זה אמור בחוטם דז\"א, ששם מתגלה החכמה דישסו\"ת, כנ\"ל, שחכמה זו אינה מתגלה, אלא על ידי תקון הדינים, בסוד ריח. והיא אינה חכמה ממש, אלא בינה שחזרה להיות הכמה. אבל בחוטם דא\"א, אינו צריך לתיקונים הנ\"ל, כי בו מאיר חכמה ממש שלו, הנקרא חכמה סתימאה. וז\"ש \u0003שאני חוטמא דעתיקא וכו' וההוא נהירו דחכמתא סתימאה,אקרי חוטמא דיליה.\u0004 והטעם שנקרא \u0003חוטם,\u0004 הוא מלשון גבול וסיום, וז\"ש, ותהלתי א \u0003חטם\u0004 לך. אחטם הוא מלשון חתימה, והוא כמו אחתם, שמסיים ההארה שנקראת תהלה. מלשון בהלו נרו עלי ראשי. וז\"ש \u0003והיינו תהלה.\u0004 כי הארת החוטם מכונה תהלה."],[5,"אודנין דמלכא, כד וכו':","האזנים של המלך, הם, כאשר הרצון נמצא, ואמא מניקה אור החסדים לז\"א, והארת עתיקא קדישא האירה, מתעוררת הארת ב' מוחות, והארת אבא ואמא, וכל אלו הנקראים מוחות המלך, ומתלהטים יחד. וכשמתלהטים יחד נקראים אזני ה'. כי נתקבלה תפלותיהם של ישראל, ואז נמצא התעוררות לטוב ולרע, ובהתעוררות הזו מתעוררים בעלי כנפים, שמקבלים קולות העולם, וכולם נקראים אזני ה'."],[5,"","פירוש. יש הארת ג' מוחין, שהם חכמה בינה דעת, והוא להשפעת החכמה. ויש הארת ב' מוחין, שהם חכמה ובינה בלבדם, והוא להשפעת אור החסדים. וב' אודנין ה\"ס או\"א עלאין המשפיעים חסדים בזווג דלא פסיק, כנ\"ל, שהם הארת ב' מוחין. וז\"ש, \u0003כד רעוא אשתכח ואמא ינקא\u0004 שאמא עלאה מניקה אור החסדים לז\"א, \u0003ונהירו דעתיקא קדישא אתנהיר,\u0004 כי אור החסדים נמשך מהארת הכתר, שנקרא עתיקא קדישא, אז \u0003מתערין נהירו דתרין מוחי\u0004 שאז נעשה זווג מן ב' מוחין בלבד, כי הזווג של ב' מוחין הוא להשפעת חסדים לז\"א, \u0003ונהירו דאו\"א,\u0004 שהוא זווג או\"א עלאין, \u0003כל אינון דאקרון מוחי דמלכא\u0004 דהיינו חו\"ב, כי רק חכמה ובינה נקראים מוחין דמלכא, אבל הדעת, אינו בעקרו אלא ת\"ת שעלה והכריע בין חו\"ב, וע\"כ אינו מוח גמור. \u0003וכד מתלהטן כחדא, אקרון אזני ה',\u0004 והוא משום ב' טעמים, א) דהא אתקבילת צלותהון דישראל, שהתפללו לגילוי אור החסדים ונתקבלה תפלתם ונשפעו החסדים. וע\"כ נקראים \u0003אזנים\u0004 השומעים את התפלה. ב), \u0003וכדין אתערותא לטב ולביש,\u0004 כי יש שם משפט אם המסך שעליו נעשה הזווג הוא טוב או רע, כי בעת הקטנות הוא \u0003רע,\u0004 שאז הוא מעניש את הרשעים. ואם בעת הגדלות הוא \u0003טוב,\u0004 שכולו רחמים. ולפיכך הם נקראים \u0003אזנים,\u0004 מלשון מאזני משפט. \u0003ובאתערתא דא מתערין מארי דגדפין דנטלין קלין דעלמא,\u0004 שבעלי כנפים, שהם המלאכים המקבלים קולות העולם, שה\"ס העלאת מ\"ן, בסו\"ה ועוף השמים יוליך את הקול, הם מתעוררים ע\"י הזווג הזה דאו\"א עלאין, להעלות שמה מ\"ן."],[6,"אנפוי דמלכא, נהירו וכו':","הפנים של המלך, שהוא ז\"א, הוא הארת אבא ואמא והתפשטות שלהם, על סדר ג' נקודות, חולם שורק וחירק (כנ\"ל ב\"א דף ט\"ו ד\"ה ההוא ע\"ש) שמאירים בחולם, ומסבבים בשורק, ולוהטים בחירק, בראש הזה של המלך. ואז נמשך מהם עדות, דהיינו הארת החכמה, המעידים במלך, שהוא ז\"א. צורת המלך, היא יקרה מכל. הראש, שורה בו חסד עליון וגבורה. (כנ\"ל אות תק\"כ) והארת אבא ואמא מתחלקת הארת אבא בשלשה אורות, והארת אמא בשני אורות, הרי חמשה אורות. חסד וגבורה נכללים באור אחד, הרי ששה. לאחר כך, מתעטר החסד ולוהט בשני אורות שהאירו, והם שמונה, והגבורה האירה באור אחד, הרי תשעה אורות. וכאשר כל האורות מתחברים יחד, הם נקראים צורת המלך. ואז כתוב, ה' כגבור יצא כאיש מלחמות יעיר קנאה וגו'. כי אין הארת החכמה נמשכת אלא בגבורה."],[6,"","פירוש. כי נתבאר לעיל (בראשית א' דף ט\"ו ד\"ה ההוא) איך האורות דבינה עלאה שיצאה מראש דא\"א, שה\"ס או\"א, אינה נשלמת אלא בביאתה בסדר ג' נקודות, חולם שורק וחירק, בזה אחר זה. שתחילה יוצאת נקודת החולם, שה\"ס עלית המלכות למקום בינה, שאז מתחלקת הבינה לשני חצאים, שכתר וחכמה שלה נשארו במדרגה, ובינה ותו\"מ שלה נפלו למדרגה שלאחריה, דהיינו לז\"ת דבינה שנקראים \u0003אמא,\u0004 או ישסו\"ת. וכתר וחכמה שנשארו במדרגה, נתקנו ונעשו לג\"ר, חב\"ד, אע\"פ שאין בהם אלא אור דחסדים, ונקראים \u0003אבא\u0004 או או\"א עלאין. וכן נתחלקו הז\"ת דבינה, הנקראות אמא, לב' חצאים, שכתר וחכמה נשארו במדרגה, ובינה ותו\"מ נפלו ממנה למדרגת ז\"א. אבל היא לא נתקנה בג\"ר, אלא נשארה בו\"ק חסר ראש, דהיינו בב' אורות נפש רוח המלובשים בב' כלים, כתר וחכמה. וז\"ש, \u0003ונהירו דאבא ואמא אתפלג,\u0004 דהיינו ביציאת נקודת החולם, שה\"ס עלית המלכות לבינה, שאז נתחלקה בינה עלאה לשתי מדרגות ל \u0003אבא,\u0004 שה\"ס ג\"ר דבינה, ול \u0003אמא,\u0004 שה\"ס ז\"ת דבינה. \u0003נהירו דאבא בתלת נהורין,\u0004 כי אבא נתקן בבחינת ג\"ר דהיינו ג' אורות חב\"ד. ונקראים ג\"כ או\"א עלאין. \u0003ואמא בתרין,\u0004 כי אמא אין בה אלא ב' כלים כתר וחכמה עם ב' אורות נפש רוח, והיא לא נתקנה בג\"ר מחמת שצריכה לאור החכמה. והיא נקראת ג\"כ ישסו\"ת. ועד כאן ה\"ס נקודת החולם."],[6,"","ואח\"כ יוצאת נקודת השורק, שה\"ס ירידת המלכות ממקום בינה למקומה עצמה, שאז בינה ותו\"מ שנפלו מאמא חוזרים ועולים ומתחברים במדרגת אמא, ונשלמה בה' כלים כו\"ח בינה ותו\"מ, ובה' אורות נרנח\"י. אמנם הבינה ותו\"מ שעלו לא נתחברו בכו\"ח לגמרי אך כו\"ח שנשארו במדרגה נתקנו לקו ימין. שהוא חסד, ובינה ותו\"מ שנפלו וחזרו, נתקנו לקו שמאל, שהוא גבורה, והשליטה היא לקו שמאל. וז\"ש \u0003חסד וגבורה בחד נהורא,\u0004 שאז יצאה נקודת השורק, שהחזירה בינה ותו\"מ למדרגתם, ונתקנו לקו שמאל, שהוא \u0003גבורה,\u0004 וכו\"ח לקו ימין שהוא \u0003חסד,\u0004 אבל בשליטת אור השמאל, ואור הימין שהוא חסד נעלם משם. וע\"כ הוא נקודת השורק."],[6,"","ואח\"כ יוצאת נקודת החירק, שה\"ס, ביאת קו האמצעי, המיחד ב' הקוין חסד וגבורה זה בזה ומקיים הארת שניהם. וז\"ש, \u0003לבתר אתעטר חסד,\u0004 דהיינו ע\"י הכרעת קו האמצעי \u0003ואתלהט ואתנהיר בתרין נהורין,\u0004 שהחסד נתפשט בב' אורות, בקו ימין שהוא חסד ובקו שמאל שהוא גבורה. דהיינו בכח קו האמצעי. ובזה יש ב' בחינות, א) שאחר שנתיחדו זה בזה מאיר רק קו ימין שהוא חסד. והיינו המדרגה של תרין נהורין. ב) שאחר שמתיחדים זה בזה מאיר אור השמאל בהתלבשות הימין, וז\"ש, \u0003לבתר אתעטר, וגבורה אתנהיר בחד,\u0004 שאח\"כ נתעטר פעם ב', והגבורה, שהוא אור קו השמאל מאירה בהארתה לבדה ע\"י התלבשות בחסד. ע\"כ נקודת החירק. וכשמתחברים כל האורות הללו יחד, נקראים צורת המלך."],[7,"שפוון דמלכא, הכי וכו':","השפתים של המלך. כך למדנו, כשהאיר אור אבא, שהוא או\"א עלאין, האיר בשלשה אורות: מאור אחד שהוא חכמה, האיר חסד עליון. ומאור אחד שהוא בינה, האיר אור הנקרא מוח המלך. ואור אחד שהוא דעת, ששם עלתה ה \u0003י'\u0004 באויר, כנ\"ל בדבור הסמוך, היה תלוי ועומד, עד שהאיר אור אמא, שהוא ישסו\"ת, שבה חזרה ויצאה ה \u0003י'\u0004 מאויר, וחזר האור למקומו. וכשחזר האור, האיר בחמשה אורות, נרנח\"י, בכלים דכח\"ב תו\"מ, כנ\"ל בדבור הסמוך."]],[]],[["בְּמַאי אִתְנְהִיר, מֵחָד שְׁבִילָא דְּטָמִיר וְגָנִיז, דְּאִתְדָּבַּק בֵּיהּ אַבָּא, דִּכְתִּיב, (איוב כ״ח:ז׳) נָתִיב לא יְדָעוֹ עָיִט וְגוֹ'. כְּמָה דְּאִתְדָּבַּק דְּכוּרָא בְּנוּקְבָא, וְאִתְעַבְּרָת, וְאוֹלִידַת, וְאַפִּיקַת חָמֵשׁ נְהוֹרִין. (ד\"א מאינון חמש) וּמֵאִינּוּן חָמֵשׁ נְהוֹרִין, אִתְגְּלִיפוּ חַמְשִׁין תַּרְעִין, דִּנְהוֹרִין סַגִּיאִין. חַמְשִׁין אִינּוּן, לָקֳבְלֵיהוֹן, מ\"ט פָּנִים טָהוֹר, מ\"ט פָּנִים טָמֵא, בְּאוֹרַיְיתָא, אִשְׁתְּאַר חַד, וְהַאי חַד אִתְנְהִיר בְּכֹלָּא, וְהַהוּא דְּאַבָּא, הֲוָה תָּלֵי. כַּד מִתְחַבְּרָן כַּחֲדָא, וּמִתְיַישְּׁבָן בְּמַלְכָּא, אִקְרוּן שִׁפְוָון דְּמַלְכָּא. וּבְגִינִי כַּךְ, גָּזַר מִלִּין דִּקְשׁוֹט.","וּפוּמָא, בְּהוּ תַּלְיָיא, פְּתִיחוּתָא דְּפוּמָא. מַאי פּוּמָא. אֶלָּא דַּעַת גָּנִיז בְּפוּמָא דְּמַלְכָּא, דְּאִקְרֵי תִפְאֶרֶת. פְּשִׁיטוּתָא דְּתִפְאֶרֶת, דְּכָל אוֹצָרִין וְכָל גְּוָונִין אִתְאַחֲדָן בֵּיהּ. דִּכְתִּיב, (משלי כ״ד:ד׳) וּבְדַעַת חֲדָרִים יִמָּלְאוּ. וְהַהוּא דַּעַת, הוּא גָּנִיז, בְּפוּמָא דְּמַלְכָּא. וּמַלְיָיא כָּל אִדָּרִין וְאַכְסַדְרָאִין. וְכַד אִתְּעַר נְהִירוּ דְּבֵיהּ וְנָפִיק, כְּדֵין אִקְרֵי פֶּה יְיָ'. וְשִׁפְוָון דְּאִינּוּן תְּרֵין נְהוֹרִין מֵאַבָּא וּמֵאִימָּא, בְּשַׁעֲתָא דְּאִתְעַרְעַן בְּהַהִיא נְהִירוּ דְּדַעַת, מִתְחַבְּרָן כַּחֲדָא, וּמִלִּין אִתְגְּזָרוּ בִּקְשׁוֹט, בְּחָכְמָה בִּתְבוּנָה וּבְדַעַת. וּכְדֵין, כָּל מִלִּין דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּאִלֵּין אִתְגְּזָרוּ.","נַהֲרִין תְּלַת אִלֵּין, וְעַיְילִין בְּגוֹ לְגוֹ, וְאִתְעַטָּרוּ בְּחַד. וְכַד מִתְחַבְּרָן בְּעִטּוּרָא חַד, כְּדֵין (ס\"א וכד מתחברן תלת אלין בעטורא חד ועיילין בגו לגו ואתעטרן בחד כדין) אִקְרוּן (שיר השירים ה׳:ט״ז) חִכּוֹ מַמְתַּקִּים. וְאִינּוּן חֵיךְ דְּמַלְכָּא, וְאִקְרוּן, מְתִיקָא דְּמַלְכָּא. וְעַל הַאי כְּתִיב, (תהלים לה) טַעֲמוּ וּרְאוּ כִּי טוֹב יְיָ'. וּבְהַאי חֵיךְ, תַּלְיָין כָּל אִינּוּן שְׁלִיטִין וְהוּרְמָנִין דְּמַלְכָּא, דִּכְתִּיב, (תהילים ל״ג:ו׳) וּבְרוּחַ פִּיו כָּל צְבָאָם.","בְּהַאי חֵיךְ שְׁלֵימוּתָא דְּכֹלָּא אִשְׁתְּכַח. וּבְגִינֵי כַּךְ, כָּל אַתְוָון דְּאִינּוּן בְּהַאי אֲתָר שְׁלֵימוּתָא אִתְחַזְיָיא בְּהוּ. (ויקרא רכ\"ט ע\"ב) אחה\"ע, א', (נ\"ד) נְהִירוּ דְּעַתִּיקָא קַדִּישָׁא סְתִימָאָה דְּכָל סְתִימִין. ח', נְהִירוּ דְּחָכְמְתָא, דְּלָא אִשְׁתְּכַח וְלָא אִתִדְּבַק דִּכְתִּיב, (איוב כ״ח:י״ג) לא יָדַע אֱנוֹשׁ עֶרְכָּהּ. ה', נְהִירוּ דְּאִימָּא, דְּנָהִיר וְנָגִיד וְנָפִיק, וּמַשְׁקֵי לְכֹלָּא, וְיָנְקָא לִבְנִין, עַד דְּמָטֵי הַהוּא רְבוּת, וּמַלֵּי לַצַּדִּיק, וְאִיהוּ אִתְקְטַר בְּנוּקְבָּא תַּתָּאָה, וְאִתְבָּרְכָא מִנֵיהּ, וְלָא מִתְפָּרְשִׁין דָּא מִן דָּא. חִוָּור מִגּוֹ סוּמָק, דִּכְתִּיב, (שיר השירים ד׳:ו׳) הַר הַמּוֹר גִּבְעַת הַלְּבוֹנָה. ע', נְהִירוּ דְּע' אַנְפִּין, דְּאִתְזָנוּ מֵהַאי רוּחָא, דְּנָפִיק מִן פּוּמָא, כְּדֵין ע' שְׁמָהָן דְּקוּדְשָׁא בְּרִיךְ הוּא. לָקֳבְלֵהוֹן בְּאַרְעָא, (בראשית מ״ו:כ״ז) כָּל הַנֶּפֶשׁ לְבֵית יַעֲקֹב הַבָּאָה מִצְרַיְמָה שִׁבְעִים. דְּהָא יַעֲקֹב אִילָנָא בְּאַרְעָא, וְאִינּוּן ע' נֶפֶשׁ, ע' עַנְפִּין.","מֵאִלֵּין אַתְוָון, נְהִירִין אַרְבַּע אַחֲרָנִין. מֵא' נָהִיר גִּימֶ\"ל, דְּאִיהִי אֲגָר טָב לְצַדִּיקַיָּיא, דְּאִקְרֵי גְּמוּל, וְעַל דָּא כְּתִיב (ישעיהו נ״ח:י״ד) אָז תִּתְעַנַּג עַל יְיָ'. מֵח' נָהִיר יוּ\"ד, דְּהִיא חָכְמָה, כֹּלָּא אַסְתִּים בְּיוּ\"ד, דְּאִיהִי סְתִימָא מִכָּל סִטְרוֹי, וּבְּגִין כָּךְ, לֹא אִשְׁתְּכַח, דִּכְתִּיב, (איוב כ״ח:י״ג) וְלֹא תִמָּצֵא בְּאֶרֶץ הַחַיִּים. מֵה', נָהִיר כָּ\"ף. דְּאִיהוּ נְהִירוּ וּמְשַׁח רְבוּת, דְּאִתְּרָק מֵאִימָּא, לְהַהוּא אֲתָר דְּאִתְקְרֵי קֶרֶן, וְאִקְרֵי קֶרֶן הַיּוֹבֵל. וְדָא מַלְכוּת דָּוִד. וּבְגִין כַּךְ, לֵית מְשִׁיחָא, אֶלָּא בְּרָזָא דְּכַ\"ף.","ק' מֵע' נָהִיר ק', כְּמָה דְּע' שִׁבְעִין, כַּךְ ק' מְאָה, דְּאִינּוּן שְׁלִימוּ, וְהָכִי הוּא, וּבְגִין כַּךְ, בְּהַאי חֵיךְ שְׁלִימוּ דְּכֹלָּא. (ד\"א שלמא דכלא) וְכָל מַאן דְּיָדַע רָזָא דָּא, וְאִזְדְּהַר בֵּיהּ, זַכָּאָה חוּלָקֵיהּ.","גּוּפָא דְּמַלְכָּא, אִתְפַּשְּׁטוּתָא דְּתִפְאֶרֶת, דְּגְוָונִין בֵּיהּ מִתְחַבְּרָן. דְּרוֹעִין דְּמַלְכָּא, נְהִירוּ דְּחֶסֶד וּגְבוּרָה. וּבְגִין כַּךְ יָמִין וּשְׂמֹאל. מֵעוֹי בְּדַעַת אִתְתַּקְנָן, עָיֵיל בְּרֵישָׁא, אִתְתָּקַּן וְאִתְפָּשַּׁט לְגוֹ, וּבְגוֹ גּוּפָא.","שׁוֹקִין אִתְאַחֲדָן בִּתְרֵין נְהוֹרִין, וְאִינּוּן תְּרֵין נְהוֹרִין מַמָּשׁ. שׁוֹקִין וּתְרֵין כֻּלְּיָין. כֻּלְּהוּ (ס\"א תליין ומתחברן) מִתְחַבְּרָן בְּאֲתָר חַד, דְּתַּמָּן אִתְכְּנַשׁ כָּל רְבוּת, וְכָל מִשְׁחָא דְּגוּפָא. וּמִתַּמָּן, שַׁרְיָין כָּל הַהוּא רְבוּת, לַאֲתָר דְּאִתְקְרֵי יְסוֹד עוֹלָם. יְסוֹד, מֵהַהוּא אֲתָר דְּאִקְרֵי עוֹלָם. וּמַאן אִיהוּ. נְצַח וְהוֹד, וְעַל כֵּן, יְיָ' צְבָאוֹת שְׁמוֹ בְּרִיךְ הוּא בְּרִיךְ שְׁמֵיהּ לְעָלַם וּלְעָלְמֵי עָלְמִין.","כָּל הָנֵי תִּקּוּנִין, אַתְיָין לְאִתְחַבְּרָא בְּחַד, עַד דְּכָל רְבוּת קֻדְשָׁא, נָטִיל כֹּלָּא הַאי יְסוֹד, וְאַשְׁדֵּי לְנוּקְבָּא, וּמִתְבָּרְכָא מִנֵיהּ. אֵימָתַי מִתְבָּרְכָא מִנֵיהּ. בְּשַׁעֲתָא דְּאִתְתַּקָּנוּ דִּינִין דִּלְתַתָּא. וְכַד דִּינִין מִתְתַּקְנִין לְתַתָּא, מִתְתַּקְנִין לְעֵילָּא, וְכָל תִּקּוּנִין דְּמַלְכָּא, בְּחֶדְוָותָא, בִּשְׁלִימוּ, דְּאִינּוּן שְׁמָא קַדִּישָׁא, וַהֲוָה כֹּלָּא חַד. וּכְדֵין הוּא שַׁארִי בְּגַוַּויְיהוּ, דִּכְתִּיב, (תהילים פ״ב:א׳) אֱלהִים נִצָּב בְּעַדַת אֵל בְּקֶרֶב אֱלֹהִים יִשְׁפוֹט."],[[0,"במאי אתנהיר מחד וכו':","שואל, ממה האירה אמא. ומשיב, משביל אחד הנעלם וגנוז, שנתדבק בו אבא, שכתוב נתיב לא ידעו עיט, כמו שמתדבק דכר בנוקבא. פירוש. מן המלכות שעלתה למקום בינה, נתקנו ב' יסודות, כי נתערבו זו בזו, והמלכות שקבלה צורת בינה, נעשתה יסוד הבינה שבאבא, ומן צורת המלכות עצמה, נעשתה יסוד החכמה דאבא. הנקרא שביל ונתדבק בו כדכר בנוקבא, שה\"ס שער הנ' שעליה נאמר נתיב לא ידעו עיט. והשביל דחכמה דאבא, האיר בנתיב דבינה דאבא, והבינה שבאבא נתעברה והולידה והוציאה חמשה אורות, כח\"ב תו\"מ דאמא, שהיא ישסו\"ת. והיינו על סדר ג' הנקודות חלם שורק חירק כמבואר בדבור הסמוך. ומאלו חמשה אורות, נחקקו חמשים שערים של אורות רבים. שהם כח\"ב תו\"מ שכל אחת נכללה מעשר ספירות. חמשים הם, וכנגדם מ\"ט פנים טהור ומ\"ט פנים טמא בתורה, נשאר אחד שאינו בחשבון זה, דהיינו שער הן', ואחד הזה האיר את הכל. שה\"ס השביל דאבא, שעליו נאמר, נתיב לא ידעו עיט, שהוא משה, המכונה עיט, שגם לו לא נמסר שער הנ'. ואור ההוא דאבא, שהוא אור הג' שנשאר תלוי עד שהאיר אור אמא, כנ\"ל, נשאר תלוי גם לאחר יציאת ה \u0003י'\u0004 מאויר דאמא. כי באבא אין ה \u0003י'\u0004 יוצאת מאויר שלו לעולם, כנ\"ל בדבור הסמוך. כאשר אבא ואמא מתחברים יחד ומתלבשים במלך, שהוא ז\"א, הם נקראים, \u0003שפתי המלך.\u0004 כי אבא התלבש בשפה עלאה, ואמא בשפה תתאה. ומשום זה, גוזר דברי אמת."],[1,"ופומא, בהו תלייא וכו':","והפה של ז\"א, הנה בהם, בשפתים, תלוי פתחון הפה. שואל. מהו פה. ומשיב, אלא דעת גנוז בפה המלך, שנקרא תפארת, דהיינו ז\"א, כי הדעת הוא התפשטות של תפארת, דהיינו ז\"א, שה\"ס ז\"א, שעלה ונעשה קו אמצעי ליחד אבא ואמא זה בזה. שכל האוצרות וכל הצבעים נתאחדו בו, בדעת להיותו קו האמצעי, שכתוב, ובדעת חדרים ימלאו. ודעת ההוא גנוז בפומא דמלכא (כצ\"ל) וממלא כל החדרים והאכסדרות. דהיינו שנתפשט בחג\"ת נה\"י דז\"א, שחג\"ת נקראין אידרין ונה\"י אכסדרין. וכשנתעורר האור של הדעת ויוצא, אז נקרא \u0003פה ה'.\u0004 והשפתים, שהם ב' אורות של אבא ואמא, בשעה שנפגשים באור ההוא של הדעת, מתחברים על ידו יחד, והדברים נחתכים באמת, בחכמה בתבונה ובדעת. ואז כל דברי הקב\"ה באלו חב\"ד נחתכים."],[2,"נהרין תלת אלין וכו':","אלו השלשה, חב\"ד, מאירים ובאים לפני ולפנים, דהיינו בראש ז\"א, בבחינת אמא, ומשם מתפשטים ומתעטרים באחד, שהוא גופו של ז\"א, דהיינו מטעם האמור לעיל, כיון דתלת דאמא \u0003מחד נפקי\u0004 מתפארת שעלה לשם בבחינת קו אמצעי, ע\"כ \u0003חד,\u0004 שהוא ת\"ת \u0003בתלת קיימא\u0004 (בראשית א' אות שס\"ג) וכשמתחברים החב\"ד בעטרה אחת, אז נקראת העטרה חכו ממתקים, והם \u0003חיך המלך\u0004 הנמצא בתחילת הגוף. ונקרא מתיקות המלך. ועל זה כתוב, \u0003טעמו\u0004 וראו כי טוב ה'. כי חוש הטעם הוא בחיך ובחיך הזה תלוים כל אלו השליטים ושרים של המלך. שכתוב, וברוח פיו כל צבאם."],[3,"בהאי חיך שלימותא וכו':","בחיך הזה נמצא השלמות של הכל, ומשום זה כל האותיות הנמצאות במקום הזה, השלמות נראתה בהם. ד' אותיות \u0003אחה\"ע,\u0004 הן ממוצא הגרון. וסודן, \u0003א'\u0004 היא, האור דעתיקא קדישא, הסתום מכל הסתומים, שהוא כתר. \u0003ח',\u0004 היא אור החכמה, שאינה נמצאת ואינה מושגת, כי היא נסתמה במוחא סתימאה דא\"א ואינה נמשכת לפרצופי אצילות, שכתוב, לא ידע אנוש ערכה. \u0003ה'\u0004 היא אור אמא, שהיא בינה החוזרת להיות חכמה, שכל החכמה, שבפרצופי אצילות, ממנה באה, המאירה ונמשכת ויוצאת ומשקה את כל, ומניקה את הבנים, שהם זו\"ן, עד שמגיע משחת קדש הזה וממלא את הצדיק, שהוא יסוד, והוא מתחבר בנוקבא התחתונה, שהיא המלכות, המתברכת ממנו, ואינם נפרדים זה מן זה, ושפע הזה דאמא, הוא לבן מתוך אדום, כלומר, שהשמאל שהוא אדום כלול בימין שהוא לבן, שכתוב, הר המור גבעת הלבונה. שמקרא הזה נאמר על אמא, אשר מור הוא אדום ולבונה הוא לבן. \u0003ע',\u0004 היא אור של ע' פנים, הניזונים מן הרוח היוצא מן הפה, והם ע' שמות של הקב\"ה, שהוא ז\"א, שכנגדם בארץ, כל הנפש לבית יעקב הבאה מצרימה שבעים. כי יעקב הוא אילן בארץ, כנגד ז\"א, וע' נפש שלו הם ע' ענפים של האילן."],[4,"מאלין אתוון נהירין וכו':","מאלו ד' אותיות אחה\"ע, מאירים ארבע אותיות אחרות, \u0003גיכ\"ק,\u0004 שהם ממוצא ה \u0003חיך.\u0004 מ \u0003א'\u0004 דאחה\"ע מאירה ה \u0003ג'\u0004 דגיכ\"ק, שהיא שכר טוב לצדיקים שנקרא \u0003גמול,\u0004 דהיינו גימל, ועל זה כתוב, אז תתענג על ה'. מ \u0003ח'\u0004 דאחה\"ע, מאירה ה \u0003י'\u0004 דגיכ\"ק, שהיא חכמה, וכולה נסתמה ב \u0003י',\u0004 שהיא סתומא מכל צדדיה, שאין בתוכה לבן ומשום זה לא נמצא החכמה, שכתוב, ולא תמצא בארץ החיים. כמ\"ש לעיל. מן \u0003ה'\u0004 דאחה\"ע מאירה \u0003כ'\u0004 דגיכ\"ק, שהיא אור ושמן המשחה שהורק מאמא למקום ההוא שנקרא קרן. ונקרא קרן היובל. כי קרן הוא מלכות, ויובל הוא בינה, וכס המלכות מקבלת שפע הבינה, נקראת קרן היובל. וזהו מלכות דוד. ומשום זה אין משיחה למלכים אלא בסוד \u0003כף.\u0004"],[5,"ק' מע' נהיר וכו': ק'",", של גיכ\"ק, הוא, כי מ \u0003ע'\u0004 דאחה\"ע מאירה ה \u0003ק'\u0004 דגיכ\"ק, כמו שה \u0003ע'\u0004 הוא שבעים שיש בה ז\"ס חג\"ת נהי\"מ שבכל אחת עשר ספירות, כנ\"ל, כך \u0003ק'\u0004 הוא מאה, כי יש בה גם ג\"ס ראשונות, חב\"ד, שהם השלמות של הע\"ס. וכך הוא. ומשום זה, בחיך הזה נמצא השלמות של הכל. וכל מי שיודע סוד הזה ונזהר בו, אשרי חלקו."],[6,"גופא דמלכא אתפשטותא וכו':","הגוף של המלך, הוא התפשטות של ספירת ת\"ת, אשר בו מתחברים הצבעים לבן ואדום, שהם ב' קוין ימין ושמאל, והגוף הוא קו האמצעי המיחדם. \u0003זרועות המלך,\u0004 הן האורות של חסד וגבורה, ומשום זה הן ב' קוין ימין ושמאל, אשר הגוף הוא קו האמצעי המיחדם. \u0003מעיו,\u0004 פירושו פנימיות, והם מתתקנים בדעת, הנכנס בראש ומכריע בין ב' הקוין חכמה ובינה, ומתפשט לפנימיות ובתוך הגוף, שהוא ת\"ת."],[7,"שוקין אתאחדן בתרין וכו':","השוקים, מתאחדים בשני אורות, והם שני אורות ממש. דהיינו נצח והוד. השוקים ושתי כליות, כולם מתחברים במקום אחד, כי שתי כליות הן ג\"כ נצח והוד, ששם מתקבץ כל המשחה, וכל השמן של הגוף. ומשם, מנו\"ה, נמשכת כל שמן משחת קדש ההיא למקום שנקרא יסוד עולם. דהיינו יסוד ממקום ההוא שנקרא עולם, ומי הוא, הוא נצח והוד. ועל כן. ה' צבאות שמו, כי נו\"ה נק' צבאות, ברוך הוא ברוך שמו לעולם ולעולמי עולמים."],[8,"כל הני תקונין וכו':","כל אלו התקונים באים להתחבר באחד, דהיינו הנוקובא, עד שכל השמן משחת קדש, מקבלו כולו, יסוד הזה, והוא שופכו אל הנוקבא, שהיא מלכות, ומתברכת ממנו. מתי מתברכת ממנו. הוא בשעה שהדינים מתתקנים למטה, וכשהדינים מתתקנים למטה, מתתקנים למעלה, וכל התקונים של המלך, שהם השם הקדוש, הם בחדוה בשלמות, וכולם אחד. ואז הוא שורה בתוכם, שכתוב, אלקים נצב בעדת אל בקרב אלקים ישפוט, ולפיכך נמשלו הדינים לאש, מה האש כשהוא מתוקן בכלים המתאימים, ממנו המאור והבישול וכו'. וכשאינו מתוקן הוא אוכל ומשחית את כל. כך הם הדינים."]],[]],[["וְכַד דִּינִין לָא מִתְתַּקְנָן לְתַתָּא, כִּבְיָכוֹל הָכִי לְעֵילָּא. דְּכָל תִּקּוּנִין לָא מִתְיַשְּׁרָן הָכִי, דְּהָא אִימָא אִסְתָּלָקַת מֵעַל בְּנִין, וּבְנִין לָא יַנְקֵי, דְּהָא יְסוֹד לָא אַשְׁדֵי בְּנוּקְבָּא, וְכָל דִּינִין מִתְעָרִין, וְחִוְיָא תַּקִּיפָא שָׁלְטָא. כִּבְיָכוֹל, תִּקּוּנִי מַלְכָּא עַל דִּינָא אִסְתַּלָקוּ, דְּכֵיוָן דְּהַאי נוּקְבָּא לָא מִתְבָּרְכָא, וְצַדִיק לָא נָטִיל. וְחִוְיָא תַּקִּיפָא שָׁלְטָא. וַוי לְעָלְמָא דְּיָנְקָא מִנַּיְיהוּ.","אָמַר רִבִּי אֶלְעָזָר, כָּל הָנִי תִּקּוּנִין, אַבָּא גַּלֵּי לוֹן, בְּגִין דְּלָא יֵיעוּל בְּכִסוּפָא לְעָלְמָא דְּאָתֵי. הַשְׁתָּא אֲמַאי אִצְטְרִיכוּ לְאִתְגַּלָּאָה. אָמַר לֵיהּ רִבִּי אַבָּא, הַהוּא דַּאֲנָא כָּתַבְנָא מִבּוּצִינָא קַדִּישָׁא, אֲמֵינָא (כתבוה) לְגַבֵּי חַבְרַיָּא, דְּהָא אִינּוּן יַדְעִין מִלִּין, וְהָא אִצְטְרִיךְ לְמִנְדַּע, דִּכְתִּיב, (שמות י׳:ב׳) וִידַעְתֶּם כִּי אֲנִי יְיָ'. וּכְתִיב (שמות כ״ט:מ״ו) וְיָדְעוּ כִּי אֲנִי יְיָ'. בְּגִין דְּאִתְיַישְּׁבָן מִלִּין. בְּלִבָּנָא. וּמִכָּאן וּלְהָלְאָה, סְתִימִין מִלִּין בְּגַוָּון. זַכָּאָה חוּלָקָנָא בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי, דְּהָא עַד כְּעָן בּוּצִינָא קַדִּישָׁא אִתְעַטָּר, בְּמִלִּין דִּבְגַוָּון.","תָּא חֲזֵי, אֲנָא חָזֵינָא לֵיהּ בְּחֶלְמָא, וְשָׁאִילְנָא קָמֵיהּ דְּרַבִּי שִׁמְעוֹן, הָא אוֹלִיפְנָא קָמֵיהּ דְּמַר, י' דְּאִיהִי חָכְמָה, וְהָכִי הוּא וַדַּאי. ה' אֲמַאי אִיהוּ בִּינָה. אָמַר לִי, תָּא חֲזֵי, הָא כְּתִיב (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. מַאן הוּא נָהָר דְּיוֹצֵא מֵעֵדֶן דָּא בִּינָה. וּבְּגִין כָּךְ הַהוּא נָהָר, י' סָתִים בְּגַוֵּיהּ. וְיוּ\"ד פָּשִׁיט נַהֲרָא דָּא מִכָּל סִטְרוֹי. וְדָא הִיא ה', בְּגִין כָּךְ הוּא י\"ה. לְבָתַר אַפִּיקַת בֵּן תְּחוֹתָהּ דְּאִיהוּ ו', כְּגַוְונָא דָּא ה'. לְבָתַר אוֹלִידַת וְאַפִּיקַת הַאי בֵּן, וְשַׁוְיֵהּ לְקַמָּהּ, וּבְגִין כַּךְ יה\"ו, דְּהָא ו' לְקַמָּהּ יָתִיב, לְיַנְקָא לֵיהּ. וְעַל כַּךְ תָּנֵינָן בְּמַתְנִיתָא דִּילָן, ה' ד' הֲוַת, מִדְּאִתְחַבָּר דְּכוּרָא עִמָּהּ אִתְעַבְּרַת מֵחָד בֵּן, וְאִקְרֵי ה'. לְבָתַר אוֹלִידַת וְאַפִּיקַת ו' הַהוּא בֵּן, וְקָאִים לְקַמָּהּ. וְעַל הַאי כְּתִיב, וְנָהָר יוֹצֵא מֵעֵדֶן, מִנֵּיהּ נָפִיק וַדַּאי, לְהַשְׁקוֹת אֶת הַגָּן, לְיָנְקָא לֵיהּ.","הֲוִינָא אָחִיד בִּידֵיהּ, (נ\"א ביה) וְנָשִׁיק בִּידוֹי. אֲנָא בְּהַאי עִדּוּנָא אִתְּעַרְנָא, בָּכֵי וְחַיִיךְ, וַהֲווּ תְּלָתָא יוֹמִין דְּלָא אֲכִילְנָא מִידִי. חַד מֵחֶדְוָותָא, וְחַד דְּלָא זָכֵינָא לְמֶחמֵי לֵיהּ זִמְנָא אַחֲרָא. וְעִם כָּל דָּא, בֵּיהּ אִתְקָשַׁרְנָא תָּדִירָא. דְּהָא כַּד נְהִירָא לִי שְׁמַעְתְּתָא, חֲמֵינָא דִּיּוּקְנֵיהּ, דְּאִתְּעַר קָמָּאי, זַכָּאִין אִינּוּן צַדִּיקַיָּיא, בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי, עֲלַיְיהוּ כְּתִיב, (תהילים ק״מ:י״ד) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךָ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךָ. (ע\"כ האידרא).","(שמות כ״ג:י״ג) וּבְכֹל אֲשֶׁר אָמַרְתִּי אֲלֵיכֶם תִּשָּׁמֵרוּ וְגוֹ'. מַאי תִּשָּׁמֵרוּ, תִּשְׁמוֹרוּ מִבָּעֵי לֵיהּ. אֶלָּא תִּשָּׁמֵרוּ וַדַּאי, מַאי אֲשֶׁר אָמַרְתִּי אֲלֵיכֶם, כְּלוֹמַר דְּאַגְזִימִית לְכוֹן עַל מֵימָר פּוּלְחָנִי. תִּשָּׁמֵרוּ, דְּלָא יַמְטֵי עֲלֵיכוֹן שׁוּם בִּישׁ. תִּשָּׁמֵרוּ מֵהַהִיא שְׁמִירָה וּנְטוּרָא דִּילִי בִּלְבַד. וְשֵׁם אֱלֹהִים אֲחֵרִים לא תַזְכִּירוּ, לֹא תַזְכִּירוּ כְּמָה דְּאוֹקִימְנָא. דָּבָר אַחֵר וְשֵׁם אֱלהִים אֲחֵרִים לֹא תַזְכִּירוּ, כְּלוֹמַר, לא תְּסַבְּבוּן, דְּתִפְּלוּן בֵּינִי עֲמַמְיָא בְּאַרְעָא אַחֲרָא. וִיקוּיָם בְּכוּ מַה דִּכְתִּיב, (דברים כ״ח:ל״ו) וְעָבַדְתָּ שָׁם אֱלהִים אֲחֵרִים וְגוֹ'.","דָּבָר אַחֵר וּבְכֹל אֲשֶׁר אָמַרְתִּי אֲלֵיכֶם תִּשָּׁמֵרוּ. רַבִּי יְהוּדָה פָּתַח, (תהילים פ״א:ט׳) שְׁמַע עַמִּי וְאָעִידָה בָּךְ וְגוֹ', לֹא יִהְיֶה בְךָ אֵל זָר וְגוֹ'. אָנֹכִי יְיָ' אֱלֹהֶיךָ הַמַּעַלְךָ מֵאֶרֶץ מִצְרָיִם וְגוֹ'. הָנֵי קָרָאן, אֲמָרָן דָּוִד בְּרוּחַ קוּדְשָׁא, וְאִית לְאִסְתַּכָּל בְּהוּ. שְׁמַע עַמִּי בְּכַמָּה אַתְרִין אַזְהָרָא אוֹרַיְיתָא לְבַּר נָשׁ. בְּכַמָּה אַתְרִין קוּדְשָׁא בְּרִיךְ הוּא אַזְהִיר בֵּיהּ בְּבַר נָשׁ. וְכֹלָּא לְתוֹעַלְתָּא דְּבַר נָשׁ. בְּגִין דְּיִנְטַר פִּקּוּדֵי אוֹרַיְיתָא, דְּכָל מַאן דְּיִנְטַר אָרְחֵי דְּאוֹרַיְיתָא, וְאִשְׁתָּדַּל בָּהּ, כְּמַאן דְּאִשְׁתָּדַּל בִּשְׁמָא קַדִּישָׁא."],[[0,"וכד דינין לא וכו':","וכשהדינים אינם מתתקנים למטה, כביכול, כך הוא למעלה, שכל התקונים אינם מסודרים כך, לפי הדרך הנ\"ל שאמרנו, כי אמא מסתלקת מעל הבנים, שהם זו\"ן, והבנים אינם יונקים, והיסוד אינו שופך אל הנוקבא שהיא המלכות, וכל הדינים מתעוררים, ונחש החזק שולט. כביכול, תקוני המלך נסתלקו מחמת הדין. כיון שנוקבא הזו לא נתברכה, והצדיק, שהוא יסוד, אינו מקבל בשבילה, ונחש החזק שולט. אוי לעולם היונק מהם."],[1,"אמר ר' אליעזר וכו':","אר\"א, כל אלו התקונים, אבא גילה אותם, כדי שלא יבא בבזיון לעולם הבא. אבל עתה למה צריכים להתגלות. אמר לו ר' אבא, זה מה שכתבתי ממאור הקדוש, אמרתי שהוא בשביל החברים, כי הם יודעים ומבינים הדברים, והרי צריכים לדעת אותם, שכתוב וידעתם כי אני ה'. וכתוב, וידעו כי אני ה', והרי הדברים התישבו בלבנו. מכאן והלאה, הדברים סתומים בינינו. אשרי חלקינו בעולם הזה ובעולם הבא, כי עד עתה נתעטר המאור הקדוש בדברים שבינינו."],[2,"ת\"ח אנא חזינא וכו':","בוא וראה אני ראיתי אותו בחלום, ושאלתי לפני ר' שמעון הרי למדתי לפני אדוני, כי \u0003י'\u0004 של שם הויה, היא חכמה. וכן הוא ודאי. \u0003ה'\u0004 של הויה, למה היא בינה. אמר לי, ת\"ח, הרי כתוב, ונהר יוצא מעדן להשקות את הגן. מי הוא הנהר היוצא מעדן. זה הוא בינה, היוצא מעדן שהוא חכמה. ומשום זה נהר ההוא, \u0003י'\u0004 סתומה בתוכו, דהיינו החכמה, וה \u0003י'\u0004 פושטת אור זה של הבינה מכל צדדיו, דהיינו למעלה, שה\"ס ימין, ולמטה, שה\"ס שמאל, וזה הוא \u0003ד'\u0004 ואח\"כ הוציאה הבינה בן תחתיה, שהוא \u0003ו',\u0004 דהיינו קו האמצעי ונעשתה כעין זה \u0003ה.\u0004 ומשום זה הוא \u0003י\"ה,\u0004 דהיינו חכמה ובינה. ואח\"כ הולידה והוציאה את בן ההוא ושמהו לפניה. ומשום זה הוא, \u0003יה\"ו,\u0004 כי ה \u0003ו'\u0004 ישבה לפניה שתינק אותו. ועל כך למדנו בברייתא שלנו, \u0003ה'\u0004 היתה מתחילה \u0003ד',\u0004 וכשנתחבר עמה דכר, שהוא חכמה, נתעברה מבן אחד, ונקראת \u0003ה'.\u0004 ואח\"כ הולידה והוציאה \u0003הו'\u0004 מחוץ לה, שהוא בן ההוא, ושמה אותו לפניה. ועל זה כתוב, ונהר יוצא מעדן, שהוא בינה היוצאת מחכמה שנקראת עדן, ממנה יצאה ודאי כדי להשקות את הגן, שהוא המלכות לינק אותו."],[3,"הוינא אחיד בידיה וכו':","אחזתי את ידו ונשקתי אותו בידו. אני בעדון הזה נערתי, בכיתי וצחקתי, ועברו שלשה ימים שלא אכלתי כלום, אחד מטעם השמחה, ואחד, שלא זכיתי לראותו פעם אחר. ועם כל זה בו התקשרתי תמיד, כי כאשר הלכה מאירה לי, אני רואה צורתו המתעוררה לפני. אשרי הם הצדיקים בעולם הזה ובעולם הבא, עליהם כתוב, אך צדיקים יודו לשמך ישבו ישרים את פניך (ע\"כ אידרא דמשכנא)."],[4,"ובכל אשר אמרתי אליכם תשמרו וגו':","שואל, מהו תשמרו, תשמורו היה צריך לומר. ומשיב, אלא תשמרו ודאי, מהו אשר אמרתי אליכם, כלומר, שהרביתי לכם על דבר עבודתי, \u0003תשמרו,\u0004 שלא יגיע לכם שום דבר רע. \u0003תשמרו,\u0004 משמירה ונטירה שלי בלבד. ושם אלהים אחרים לא תזכירו. לא תזכירו, כמו שהעמדנו. פירוש אחר, על, ושם אלהים אחרים לא תזכירו. כלומר, אל תסבבו שתפלו בין העמים בארץ אחרת, ויקוים בכם מה שכתוב ועבדת שם אלהים אחרים וגו'."],[5,"ד\"א ובכל אשר וגו':","פירוש אחר על, ובכל אשר אמרתי אליכם תשמרו. ר' יהודה פתח, שמע עמי ואעידה בך וגו'. לא יהיה בך אל זר וגו'. אנכי ה' אלקיך המעלך מארץ מצרים וגו'. מקראות אלו אמרם דוד ברוח הקדש, ויש להסתכל בהם. \u0003שמע עמי\u0004, בכמה מקומות הזהירה התורה לאדם, בכמה מקומות הקב\"ה מזהיר באדם, והכל לתועלת האדם, כדי שישמור מצות התורה, שכל מי שישמור דרכי התורה, ועוסק בה, כמי שעוסק בשם הקדוש."]],[[4,"","וּבְכֹל אֲשֶׁר אָמַרְתִּי אֲלֵיכֶם תִּשָּׁמֵרוּ וְגוֹ'. מַה זֶּה תִּשָּׁמֵרוּ? תִּשְׁמֹרוּ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא תִּשָּׁמֵרוּ וַדַּאי. מַה זֶּה אֲשֶׁר אָמַרְתִּי אֲלֵיכֶם? כְּלוֹמַר שֶׁהִזְהַרְתִּיכֶם עַל מַאֲמַר עֲבוֹדָתִי. תִּשָּׁמֵרוּ, שֶׁלֹּא יַגִּיעַ אֲלֵיכֶם שׁוּם רַע. תִּשָּׁמֵרוּ מֵאוֹתָהּ שְׁמִירָה וּנְטִירָה שֶׁלִּי בִּלְבַד. וְשֵׁם אֱלֹהִים אֲחֵרִים לֹא תַזְכִּירוּ - לֹא תַזְכִּירוּ כְּמוֹ שֶׁבֵּאַרְנוּ. דָּבָר אַחֵר וְשֵׁם אֱלֹהִים לֹא תַזְכִּירוּ - כְּלוֹמַר לֹא תְסַבְּבוּ, שֶׁתִּפְּלוּ בֵּין הָעַמִּים בְּאֶרֶץ אַחֶרֶת, וִיקֻיַּם בָּכֶם מַה שֶּׁכָּתוּב (דברים כח) וְעָבַדְתָּ שָּׁם אֱלֹהִים אֲחֵרִים וְגוֹ'."],[5,"","דָּבָר אַחֵר וּבְכֹל אֲשֶׁר אָמַרְתִּי אֲלֵיכֶם תִּשָּׁמֵרוּ - רַבִּי יְהוּדָה פָּתַח, (תהלים פא) שְׁמַע עַמִּי וְאָעִידָה בָּךְ וְגוֹ', לֹא יִהְיֶה בְךְ אֵל זָר וְגוֹ'. אָנֹכִי ה' אֱלֹהֶיךְ הַמַּעַלְךְ מֵאֶרֶץ מִצְרָיִם וְגוֹ'. הַפְּסוּקִים הַלָּלוּ אֲמָרָם דָּוִד בְּרוּחַ הַקֹּדֶשׁ, וְיֵשׁ לְהִתְבּוֹנֵן בָּהֶם. שְׁמַע עַמִּי - בְּכַמָּה מְקוֹמוֹת הִזְהִירָה הַתּוֹרָה אֶת הָאָדָם, בְּכַמָּה מְקוֹמוֹת מַזְהִיר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם, וְהַכֹּל לְתוֹעֶלֶת הָאָדָם כְּדֵי שֶׁיִּשְׁמֹר אֶת מִצְווֹת הַתּוֹרָה. שֶׁכָּל מִי שֶׁיִּשְׁמֹר אֶת מִצְווֹת הַתּוֹרָה וּמִשְׁתַּדֵּל בָּהּ, כְּמִי שֶׁמִּשְׁתַּדֵּל בַּשֵּׁם הַקָּדוֹשׁ."]]],[["דְּתָנֵינָן, אוֹרַיְיתָא כֹּלָּא שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא. וּמַאן דְּמִשְׁתַּדַּל בָּהּ, כְּמַאן דְּמִשְׁתַּדַּל בִּשְׁמָא קַדִּישָׁא. בְּגִין דְּאוֹרַיְיתָא כֹּלָּא, חַד שְׁמָא קַדִּישָׁא הוּא. שְׁמָא עִלָּאָה, שְׁמָא דְּכָלִיל כָּל שְׁמָהָן. וּמַאן דְּגָרַע אוֹת חַד מִינָהּ, כְּאִילּוּ עָבִיד פְּגִימוּתָא בִּשְׁמָא קַדִּישָׁא. תָּאנָא, וְשֵׁם אֱלֹהִים אֲחֵרִים לֹא תַזְכִּירוּ, לֹא תּוֹסִיף עַל אוֹרַיְיתָא, וְלָא תִּגְרַע מִינָּהּ. רַבִּי חִיָּיא אָמַר, וְשֵׁם אֱלֹהִים אֲחֵרִים, דָּא מַאן דְּיִתְעֲסָק בְּסִפְרִין אַחֲרָנִין, דְּלָא מִסִּטְרָא דְּאוֹרַיְיתָא. לָא יִשָּׁמַע עַל פִּיךָ, דְּאָסוּר אֲפִילּוּ לְאַדְכְּרָא לוֹן, וּלְמֵילַף מִנַּיְיהוּ טַעֲמָא, כָּל שֶׁכֵּן עַל אוֹרַיְיתָא.","רַבִּי יְהוּדָה מַתְנֵי הָכִי, מַאי טַעֲמָא כְּתִיב וְשֵׁם אֱלֹהִים אֲחֵרִים, וְסָמִיךְ לֵיהּ אֶת חַג הַמַּצּוֹת תִּשְׁמֹר. אֶלָּא, מַאן דְּלָא נָטִיר הַאי, כְּמַאן דְּלָא נָטִיר מְהֵימְנוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא. מַאי טַעֲמָא. מִשּׁוּם דְּבֵיהּ אֲחִידָא מִלָּה. אָמַר רַבִּי יִצְחָק, וְכֵן בְּכָל שְׁאַר זִמְנִין וְחַגִּין, דְּהָא כֻּלְּהוּ אֲחִידָן בִּשְׁמָא קַדִּישָׁא עִלָּאָה. וְעַל דָּא תָּנִינָן, מַאי דִּכְתִּיב שָׁלשׁ פְּעָמִים בַּשָּׁנָה, מִשּׁוּם דִּבְהוּ תַּלְיָא מְהֵימְנוּתָא.","יֵרָאֶה כָּל זְכוּרְךָ, אֲמַאי כָּל זְכוּרְךָ. (ויקרא קס\"ה ע\"ב) אָמַר רִבִּי אֶלְעָזָר כָּל זְכוּרְךָ מַמָּשׁ. בְּגִין דְּנַטְלִין בִּרְכָּתָא, מִמַּבּוּעָא דְּנַחֲלָא. מִכָּאן תָּנֵינָן, כָּל בַּר יִשְׂרָאֵל דְּאִתְגְּזַר, בָּעֵי לְאִתְחֲזָאָה קָמֵי מַלְכָּא קַדִּישָׁא, בְּגִין דְּנָטִיל בִּרְכָּתָא, מִמַּבּוּעָא דְּנַחֲלָא. הֲדָא הוּא דִכְתִיב, (דברים ט״ז:י״ז) כְּבִרְכַּת יְיָ' אֱלהֶיךָ אֲשֶׁר נָתַן לָךְ. וּכְתִיב אֶל פְּנֵי (בראשית ב' ע\"א) הָאָדוֹן יְיָ', כְּמָה דְּאוֹקִימְנָא, דְּמִתַּמָּן מְרִיקָן בִּרְכָּאן, וְנַטְלִין בִּרְכָּתָא. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, מִכָּל שְׁאַר עַמִּין.","זִמְנָא חֲדָא, סְלִיקוּ יִשְׂרָאֵל לְמֵחַג חַגָּא, וְאִתְעָרְבוּ עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת בַּהֲדַיְיהוּ, וְהַהוּא שַׁתָּא לָא אִשְׁתְּכַח בִּרְכָּתָא בְּעָלְמָא. אָתוּ שָׁאִילּוּ לְרַב הַמְנוּנָא סָבָא, אָמַר לְהוּ, חֲמֵיתוּן סִימָנָא בְּקַדְמִיתָא בְּהַאי. אֲמַר לֵיהּ, סִימָנָא חֲמֵינָן, דְּכַד תַּבְנָא מֵהָתָם, כָּל אָרְחִין אַסְתִּימוּ מִמַּיָּא, וַעֲנָנָא, וַחֲשׁוֹכָא אִשְׁתְּכַח, דְּלָא יַכְלִין לְמֵהַךְ כָּל אִינּוּן דְּסָלִיקוּ לְתַמָּן. וְעוֹד, בְּשַׁעֲתָא דְּעָאלָנָא לְאִתְחֲזָאָה אַפֵּי שְׁמַיָא אִתְחַשָּׁכוּ וְאִתְרְגִיזוּ. (אתרגיש בחמא) אָמַר לְהוּ, וַדַּאי אוֹ אִית בֵּינַיְיכוּ בְּנֵי נָשָׁא דְּלָא אִתְגְּזָרוּ, אוֹ עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת סְלִיקוּ בַּהֲדַיְיכוּ. דְּהָא לָא אִתְבָּרְכָאן בְּהַהִיא שַׁעֲתָא, בַּר מֵאִינּוּן יִשְׂרָאֵל דְּאִתְגְּזָרוּ. וּבְהַאי אָת קַדִּישָׁא מִסְתַּכֵּל קוּדְשָׁא בְּרִיךְ הוּא, וּבָרִיךְ לוֹן.","לְשַׁתָּא אַחֲרָא סְלִיקוּ, וּסְלִיקוּ אִינּוּן עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, דְּאִתְעָרְבוּ בַּהֲדַיְיהוּ, כַּד הֲווֹ אַכְלִין קָרְבְּנַיָּיא, וַהֲווּ חַדָּאן. וְחָמוּ לְאִינוּן עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, דְּטַפְסָאן בְּקוּטְרַיְיהוּ לְקוּטְרָא דְּכוֹתָלָא. אַשְׁגָּחוּ בְּהוּ דְּכֹלָּא מְבָרְכִין, וְאִינּוּן לָא בְּרִיכוּ. אָתוּ וְאָמְרוּ מִלָּה לְבֵי דִּינָא, אָתוּ וְשָׁאִילּוּ לוֹן, אָמְרוּ, הַאי דַּאֲכַלְתּוּן, חוּלָקָא דִּלְכוֹן, מַאן קוּרְבָּנָא הֲוָה. לָא הֲוָה בִּידַיְיהוּ. בָּדְקוּ וְאַשְׁכָּחוּ דְּאִינּוּן עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וְקָטְלוּ לוֹן. אָמְרוּ, בְּרִיךְ רַחֲמָנָא דְּשֵׁזִיב לְעַמֵּיהּ, דְּוַדַּאי לֵית בִּרְכְתָא שַׁרְיָא, אֶלָּא בְּיִשְׂרָאֵל, זַרְעָא קַדִּישָׁא, בְּנִי מְהֵימְנוּתָא, בְּנֵי קְשׁוֹט. וְהַהִיא שַׁתָּא אִשְׁתְּכַח בִּרְכְתָא בְּעָלְמָא, בִּשְׁלִימוּ. פָּתְחוּ וְאָמְרוּ, (תהילים ק״מ:י״ד) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךָ וְגוֹ'.","רִבִּי חִיָּיא אָמַר, בִּזְכוּת יִשְׂרָאֵל גְּזִירִין, אִתְכְּנָעוּ שַׂנְאֵיהוֹן תְּחוֹתֵיהוֹן, וְיַרְתֵּי אַחֲסַנְתֵּהוֹן. תָּא חֲזֵי מַה כְּתִיב, (שמות לה) יֵרָאֶה כָּל זְכוּרְךָ. וּכְתִיב בַּתְרֵיהּ, כִּי אוֹרִישׁ גּוֹיִם מִפָּנְיךָ וְהִרְחַבְתִּי אֶת גְּבֻלֶךָ. דְּקוּדְשָׁא בְּרִיךְ הוּא עָקַר דִּיּוּרִין מֵאַתְרַיְיהוּ, וְאָתִיב דִּיּוּרִין, לְאַתְרַיְיהוּ. וּבְגִינִי כַּךְ יֵרָאֶה כָּל זְכוּרְךָ אֶת פְּנֵי הָאָדוֹן יְיָ'. רַבִּי יְהוּדָה אָמַר, הָאָדוֹן. כְּמָה דִּכְתִּיב, (ישעיהו י׳:ל״ג) הִנֵּה הָאָדוֹן יְיָ' צְבָאוֹת מְסָעֵף פֻּארָה וְגוֹ', וְיָצָא חוֹטֶר וְגוֹ', וְכֹלָּא חַד, מְעַקֵּר דִּיּוּרִין וְאָתִיב דִּיּוּרִין. רִבִּי יִצְחָק אָמַר, אִית אָדוֹן, וְאִית אָדוֹן, וְכֹלָּא בְּחַד תַּלְיָא."],[[0,"דתנינן אורייתא וכו':","שלמדנו, התורה כולה היא השם של הקב\"ה, ומי שעוסק בה כאלו עוסק בשם הקדוש, משום שהתורה כולה שם אחד קדוש הוא, שם עליון, שם הכולל שאר השמות, ומי שגורע אות אחת ממנה, כאלו עשה פגם בשם הקדוש. למדנו, ושם אלהים אחרים לא תזכירו, פירושו, אל תוסיף על התורה ואל תגרע ממנה. שעושה פגם בשם הקדוש, ומחזק את אלהים אחרים. ר' חייא אמר, ושם אלהים אחרים, זה מי שעוסק בספרים אחרים, שאינם מצד התורה. לא ישמע על פיך. שאסור אפילו להזכירם וללמוד מהם טעם. וכל שכן, טעם על התורה."],[1,"ר' יהודה מתני וכו':","ר' יהודה לומד כך. מה הטעם שכתוב, ושם אלהים אחרים. וסמוך לו, ואת חג המצות תשמר, אלא מי שאינו שומר זה, את חג המצות, כמי שאינו שומר אמונת הקב\"ה, מה הטעם. משום שבו אחוז הדבר. אמר ר' יצחק, וכן בכל שאר הזמנים וחגים, שכולם אחוזים בשמו הקדוש העליון. ועל זה למדנו, מה שכתוב, שלש פעמים בשנה, משום שבהם. תלויה האמונה. שה\"ס ג' קוין, שהמלכות, שנקראת אמונה, נבנית מהם."],[2,"יראה כל זכורך:","שואל למה כל זכורך. אמר ר' אלעזר, כל זכורך ממש משום שמקבלים ברכה ממבוע של הנחל, שהוא יסוד. מכאן למדנו, שכל איש ישראל שנימול, צריך להראות לפני המלך הקדוש, משום שמקבל ברכה מן המבוע של הנחל. ז\"ש, כברכת ה' אלקיך אשר נתן לך. וכתוב אל פני האדון ה', כמו שהעמדנו, שהאדון הוא יסוד, שמשם נשפעות הברכות, ומקבלים הברכות. אשרי חלקם של ישראל משאר העמים."],[3,"זמנא חדא סליקו וכו':","פעם אחת עלו ישראל לירושלים, לחוג את החג, ונתערבו עכו\"ם עמהם, ובשנה ההיא לא נמצאו ברכות בעולם. באו ושאלו את ר' המנונא סבא, אמר להם, ראיתם בתחילה סימן לזה, שהעליה לא היתה לרצון, אמרו לו, ראינו סימן, כשחזרנו משם, היו כל הדרכים נסתמים ממים, וענן וחשך היה נמצא, שלא יכלו ללכת ולחזור כל אלו שעלו שמה. ועוד, בשעה שבאנו להראות, נתחשכו פני השמים ונרגזו. אמר להם ודאי, או שיש ביניכם אנשים שלא נמולו, או עובדי עכו\"ם עלו עמכם. כי בשעה ההיא אינם מתברכים חוץ מבני ישראל שנמולו, ובאות קדוש הזה מסתכל הקב\"ה, ומברך אותם."],[4,"לשתא אחרא סליקו וכו':","לשנה האחרת עלו, ועלו אלו עובדי עכו\"ם שנתערבו עמהם, כשהיו אוכלים הקרבנות והיו שמחים, ראו אלו עובדי עכו\"ם שהיו דומים בצורתם לצורת הכותל, כלומר שהיו עצובים. השגיחו בהם שהכל מברכים והם אינם מברכים. באו ואמרו הדבר אל הבית דין. באו ושאלו אותם: אמרו, זה שאכלתם, החלק שלכם מאיזה קרבן היה. לא היה בידיהם, כלומר שלא ידעו להשיב. בדקו ומצאו שהם עובדי עכו\"ם והרגו אותם. אמרו, ברוך הרחמן שהציל את עמו. כי ודאי אין הברכה שורה אלא בישראל, זרע קדוש, בני אמונה, בני אמת. ובשנה ההיא נמצאו ברכות בעולם בשלמות. פתחו ואמרו, אך צדיקים יודו לשמך וגו'."],[5,"ר' חייא אמר וכו':","רח\"א, בזכות ישראל נמולים, נכנעים אויביהם תחתיהם, ויורשים את נחלתם, בוא וראה, מה כתוב, יראה כל זכורך, שפירושו זכרים הנמולים, וכתוב אח\"כ, כי אוריש גוים מפניך והרחבתי את גבולך. שבזכות המילה, הקב\"ה שיש בו דין ורחמים, עוקר דירים ממקומם, שהם האויבים, ומשיב דירים למקומם, שהם ישראל. ומשום זה, יראה כל זכורך את פני האדון ה', דהיינו הקב\"ה שהוא ת\"ת, שיש בו דין ורחמים, וע\"כ עוקר דירים ומשיב דירים. ר' יהודה אומר, האדון, הוא כמו שכתוב, הנה האדון ה' צבאות מסעף פארה במערצה וגו' דהיינו עוקר דיורים, ויצא חוטר וגו' דהיינו משיב דיורים. והכל אחד. שהדין והרחמים פועלים ביחד, ועוקר דירים ומשיב דירים כאחד. ר' יצחק אמר יש אדון, שהוא ת\"ת, ויש אדון שהוא יסוד, והכל תלוי באחד, שהוא מלכות. הנקראת אדני."]],[[0,"","שֶׁשָּׁנִינוּ, כָּל הַתּוֹרָה הִיא שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִי שֶׁמִּשְׁתַּדֵּל בָּהּ כְּמִי שֶׁמִּשְׁתַּדֵּל בַּשֵּׁם הַקָּדוֹשׁ, מִשּׁוּם שֶׁכָּל הַתּוֹרָה הִיא שֵׁם קָדוֹשׁ אֶחָד, שֵׁם עֶלְיוֹן, שֵׁם שֶׁכּוֹלֵל אֶת כָּל הַשֵּׁמוֹת, וּמִי שֶׁגּוֹרֵעַ מִמֶּנָּה אוֹת אַחַת כְּאִלּוּ עָשָׂה פְּגָם בַּשֵּׁם הַקָּדוֹשׁ. שָׁנִינוּ, וְשֵׁם אֱלֹהִים אֲחֵרִים לֹא תַזְכִּירוּ - לֹא תוֹסִיף עַל הַתּוֹרָה וְלֹא תִגְרַע מִמֶּנָּה. רַבִּי חִיָּיא אָמַר, וְשֵׁם אֱלֹהִים אֲחֵרִים - זֶה מִי שֶׁמִּתְעַסֵּק בִּסְפָרִים אֲחֵרִים שֶׁאֵינָם מִצַּד הַתּוֹרָה. לֹא יִשָּׁמַע עַל פִּיךְ - שֶׁאָסוּר אֲפִלּוּ לְהַזְכִּירָם וְלִלְמֹד מֵהֶם טַעַם, כָּל שֶׁכֵּן עַל הַתּוֹרָה."],[1,"","רַבִּי יְהוּדָה שׁוֹנֶה כָּךְ, מָה הַטַּעַם כָּתוּב וְשֵׁם אֱלֹהִים אֲחֵרִים, וְסוֹמֵךְ לוֹ אֶת חַג הַמַּצּוֹת תִּשְׁמֹר? אֶלָּא מִי שֶׁמִּי שֶׁלֹּא שׁוֹמֵר אֶת זֶה, כְּמִי שֶׁלֹּא שׁוֹמֵר אֶת אֱמוּנַת הַקָּדוֹשׁ בָּרוּךְ הוּא. מָה הַטַּעַם? מִשּׁוּם שֶׁבּוֹ הַדָּבָר אָחוּז. אָמַר רַבִּי יִצְחָק, וְכֵן בְּכָל שְׁאָר הַחַגִּים וְהַזְּמַנִּים, שֶׁהֲרֵי כֻּלָּם אֲחוּזִים בַּשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן. וְעַל זֶה שָׁנִינוּ, מַה שֶּׁכָּתוּב שָׁלֹשׁ פְּעָמִים בַּשָּׁנָה, מִשּׁוּם שֶׁבָּהֶם תְּלוּיָה הָאֱמוּנָה."],[2,"","יֵרָאֶה כָּל זְכוּרְךְ, לָמָּה כָּל זְכוּרְךְ? אָמַר רַבִּי אֶלְעָזָר, כָּל זְכוּרְךְ מַמָּשׁ, מִשּׁוּם שֶׁנּוֹטְלִים בְּרָכָה מֵהַמַּעְיָן שֶׁל הַנַּחַל. מִכָּאן שָׁנִינוּ, כָּל בֶּן יִשְׂרָאֵל שֶׁנִּמּוֹל, צָרִיךְ לְהֵרָאוֹת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, מִשּׁוּם שֶׁנּוֹטֵל בְּרָכָה מִמַּבּוּעַ הַנַּחַל. זֶהוּ שֶׁכָּתוּב כְּבִרְכַּת ה' אֱלֹהֶיךְ אֲשֶׁר נָתַן לָךְ. וְכָתוּב אֶל פְּנֵי הָאָדן ה', כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁמִּשָּׁם מְרִיקִים בְּרָכוֹת וְנוֹטְלִים בְּרָכָה. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל מִכָּל שְׁאָר הָעַמִּים."],[3,"","פַּעַם אַחַת עָלוּ יִשְׂרָאֵל לָחֹג אֶת הֶחָג, וְהִתְעָרְבוּ עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת עִמָּם, וְאוֹתָהּ שָׁנָה לֹא נִמְצְאָה בְּרָכָה בָּעוֹלָם. בָּאוּ וְשָׁאֲלוּ אֶת רַב הַמְנוּנָא סָבָא. אָמַר לָהֶם, רְאִיתֶם בַּתְּחִלָּה סִימָן לָזֶה? אָמְרוּ לוֹ, רָאִינוּ סִימָן, שֶׁכְּשֶׁשַּׁבְנוּ מִשָּׁם כָּל הַדְּרָכִים הָיוּ סְתוּמִים מִמַּיִם, וְעָנָן וַחֲשֵׁכָה נִמְצְאוּ, שֶׁלֹּא יָכְלוּ לָלֶכֶת כָּל אוֹתָם שֶׁעָלוּ לְשָׁם. וְעוֹד, בְּשָׁעָה שֶׁנִּכְנַסְנוּ לְהֵרָאוֹת, פְּנֵי הַשָּׁמַיִם נֶחְשְׁכוּ וְרָגְזוּ. (נחרד וראה) אָמַר לָהֶם, וַדַּאי אוֹ שֶׁיֵּשׁ בָּכֶם אֲנָשִׁים לֹא נִמּוֹלִים, אוֹ עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת עָלוּ עִמָּכֶם, שֶׁהֲרֵי לֹא הִתְבָּרְכוּ בְּאוֹתָה שָׁעָה, פְּרָט לְאוֹתָם יִשְׂרְאֵלִים שֶׁנִּמּוֹלוּ, וּבָאוֹת הַקְּדוֹשָׁה הַזּוֹ מִסְתַּכֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא וּמְבָרֵךְ אוֹתָם."],[4,"","לַשָּׁנָה הָאַחֶרֶת עָלוּ, וְעָלוּ אוֹתָם עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, שֶׁהִתְעָרְבוּ עִמָּם כְּשֶׁהָיוּ אוֹכְלִים קָרְבָּנוֹת וְהָיוּ שְׂמֵחִים. וְרָאוּ אֶת אוֹתָם עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת שֶׁדְּפוּסָם בְּקִשְׁרֵיהֶם לְקֶשֶׁר הַכֹּתֶל. הִשְׁגִּיחוּ בָהֶם שֶׁכֻּלָּם מְבָרְכִים וְהֵם לֹא בֵרְכוּ. בָּאוּ וְאָמְרוּ אֶת הַדָּבָר לְבֵית הַדִּין. בָּאוּ וְשָׁאֲלוּ אוֹתָם. אָמְרוּ, זֶה שֶׁאֲכַלְתֶּם, הַחֵלֶק שֶׁלָּכֶם אֵיזֶה קָרְבָּן הָיָה? לֹא הָיָה בְיָדָם. בָּדְקוּ וּמָצְאוּ שֶׁהֵם עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת וְהָרְגוּ אוֹתָם. אָמְרוּ, בָּרוּךְ הָרַחֲמָן שֶׁהִצִּיל אֶת עַמּוֹ, שֶׁוַּדַּאי אֵין בְּרָכָה שְׁרוּיָה אֶלָּא רַק בְּיִשְׂרָאֵל, הַזֶּרַע הַקָּדוֹשׁ, בְּנֵי הָאֱמוּנָה, בְּנֵי הָאֱמֶת. וְאוֹתָהּ הַשָּׁנָה נִמְצְאָה בְּרָכָה בָּעוֹלָם בִּשְׁלֵמוּת. פָּתְחוּ וְאָמְרוּ, (תהלים קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ וְגוֹ'."],[5,"","רַבִּי חִיָּיא אָמַר, בִּזְכוּת יִשְׂרָאֵל מְהוּלִים, נִכְנָעִים שׂוֹנְאֵיהֶם תַּחְתֵּיהֶם וְיוֹרְשִׁים נַחֲלָתָם. בֹּא וּרְאֵה מַה כָּתוּב, יֵרָאֶה כָּל זְכוּרְךְ. וְכָתוּב אַחֲרָיו, כִּי אוֹרִישׁ גּוֹיִם מִפָּנֶיךְ וְהִרְחַבְתִּי אֶת גְּבֻלֶךְ. שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹקֵר דַּיָּרִים מִמְּקוֹמָם וּמוֹשִׁיב דַּיָּרִים לִמְקוֹמָם, וּמִשּׁוּם כָּךְ, (שמות לד) יֵרָאֶה כָּל זְכוּרְךְ אֶת פְּנֵי הָאָדֹן ה'. רַבִּי יְהוּדָה אָמַר, הָאָדוֹן, כְּמוֹ שֶׁכָּתוּב (ישעיה י) הִנֵּה הָאָדוֹן ה' צְבָאוֹת מְסָעֵף פֻּארָה וְגוֹ', וְיָצָא חֹטֶר וְגוֹ'. וְהַכֹּל אֶחָד, מְעַקֵּר דַּיָּרִים וּמוֹשִׁיב דַּיָּרִים. רַבִּי יִצְחָק אָמַר, יֵשׁ אָדוֹן וְיֵשׁ אָדוֹן, וְהַכֹּל בְּאֶחָד תָּלוּי."]]],[["רַבִּי יְהוּדָה אָמַר, אֲדֹנָי: אָלֶף דַּלֶית נוּן יוֹד, קוּדְשָׁא בְּרִיךְ הוּא אִקְרֵי, וְהַהוּא דְּאִקְרֵי, כְּמָה דְּאִיהוּ כְּתִיב. וּמַאן הוּא. רַבִּי יוֹסִי אוֹמֵר, (יחזקאל א׳:א׳) מַרְאֹת אֱלהִים. מַרְאַת כְּתִיב. וּמַהוּ מַרְאַת. שְׁלִימוּ דְּכֹלָּא, יוּ\"ד הֵ\"א וָא\"ו הֵ\"א. (נ\"א מראת איהו א' כו') מַרְאַת לְמַאי אִיהוּ אָלֶ\"ף דָּלֶי\"ת נוּ\"ן יוּ\"ד, הַאי אִקְרֵי כִּכְתָבוֹ, וְהַאי לָא אִקְרֵי כִּכְתָבוֹ, וּבְגִינֵי כַּךְ אִקְרֵי בְּהַאי, וְעַל כַּךְ מַרְאַת אֱלֹהִים כְּתִיב.","רַבִּי יְהוּדָה אָמַר, לְזִמְנִין, עִלָּאִין אִקְרוּן בִּשְׁמָא דְּתַּתָּאִין. וּלְזִמְנָא, תַּתָּאִין אִקְרוּן בִּשְׁמָא דְּעִלָּאִין. הָאָדֹן יְיָ', בִּשְׁמָא עִלָּאָה אֲדֹנָי הוּא. וְהָא אוֹקִימְנָא מִלֵּי. וּבִגְוָונִין סַגִּיאִין אִתְפָּרְשָׁן מִלֵּי, וְכֹלָּא חַד. בְּרִיךְ רַחֲמָנָא בְּרִיךְ שְׁמֵיהּ לְעָלַם וּלְעָלְמֵי עָלְמִין.","(שמות כ״ג:כ׳) הִנֵּה אָנֹכִי שׁוֹלֵחַ מַלְאָךְ לְפָנֶיךָ וְגוֹ'. רַבִּי יִצְחָק פָּתַח, (שיר השירים א׳:ב׳) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ וְגוֹ' אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ. מַאי טַעֲמָא יִשָּׁקֵנִי, יֶאֱהָבֵנִי מִבָּעֵי לֵיהּ, אֲמַאי יִשָּׁקֵנִי. אֶלָּא הָכִי תָּנֵינָן, מַאי נְשִׁיקוֹת אַדְבְּקוּתָא דְּרוּחָא בְּרוּחָא. דִּבְגִינִי כַּךְ נְשִׁיקָה בַּפֶּה, דְּהָא פּוּמָא אַפְקוּתָא וּמְקוֹרָא דְּרוּחָא הוּא, וְעַל דָּא נְשִׁיקִין בְּפוּמָא, בַּחֲבִיבוּתָא, וְדַבְקִין רוּחָא בְּרוּחָא, דְּלָא מִתְפָּרְשָׁן דָּא מִן דָּא.","וְעַל דָּא מַאן דְּנָפִיק נִשְׁמָתֵיהּ בִּנְשִׁיקָה, מִתְדְּבַּק בְּרוּחָא אַחֲרָא. בְּרוּחָא דְּלָא מִתְפְּרַשׁ מִנֵּיהּ. וְהַיְינוּ אִקְרֵי נְשִׁיקָה. וְעַל דָּא אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ, לְאַדְבְּקָא רוּחָא בְּרוּחָא, דְּלָא יִתְפְּרִישׁ דָּא מִן דָּא.","כִּי טוֹבִים דּוֹדֶיךָ מִיָּיִן, מַאי בָּעֵי הָכָא יַיִן, וְהָא כְּתִיב (ישעיהו כ״ח:ז׳) וְגַם אֵלֶּה בְּיַיִן שָׁגוּ וְגוֹ', וּכְתִיב (ויקרא י׳:ט׳) יַיִן וְשֵׁכָר אַל תֵּשְׁתְּ אַתָּה וּבָנֶיךָ, מַאי טַעֲמָא הָכָא יַיִן. רַבִּי חִיָּיא אָמַר, מִיֵּינָהּ דְּאוֹרַיְיתָא. רַבִּי חִזְקִיָּה אָמַר, דָּא דִּכְתִּיב, (תהילים ק״ד:ט״ו) וְיַיִן יְשַׂמַּח לְבַב אֱנוֹשׁ, וְעַל דָּא כְּתִיב, כִּי טוֹבִים דּוֹדֶיךָ מִיָּיִן, לְחֶדְוָותָא דְּלִבָּא. מִיָּיִן, דְּחַדֵּי לִי יַתִּיר מִכֹּלָּא.","רַבִּי יְהוּדָה אָמַר, כְּתִיב, (בראשית כ״ט:י״א) וַיִּשַּׁק יַעֲקֹב לְרָחֵל וְיִשָּׂא אֶת קוֹלוֹ וַיֵּבְךְ, אֲמַאי קָא בָּכָה. אֶלָּא בְּאִתְדַּבְּקוּתָא דְּרוּחָא בָּהּ, לָא יָכִיל לִבָּא לְמִסְבַּל, וּבָכָה. וְאִי תֵּימָא, הָא כְּתִיב, (בראשית ל״ג:ד׳) וַיִּשָּׁקֵהוּ וַיִּבְכּוּ. תָּנֵינָן, אֲמַאי נָקוּד וַיִּשָּׁקֵהוּ, אֶלָּא דְּלָא אִתְדָּבַּק בֵּיהּ רוּחָא כְּלָל, וְעַל דָּא כְּתִיב, (משלי כ״ז:ו׳) וְנַעְתָּרוֹת נְשִׁיקוֹת שׂוֹנֵא. מַאי וְנַעְתָּרוֹת נְשִׁיקוֹת שׂוֹנֵא. אֶלָּא מַאן דְּנָשִׁיק בַּחֲבִיבוּתָא, מִתְדָּבַק רוּחֵיהּ בְּרוּחֵיהּ, בִּדְבֵיקוּתָא דַּחֲבִיבוּתָא וּמַאן דְּלָא נָשִׁיק בַּחֲבִיבוּתָא, לָאו בִּדְבֵיקוּתָא הוּא, אֶלָּא וְנַעְתָּרוֹת. מַאי נַעְתָּרוֹת. גַּסּוּתָא, דְּלָא דָּבִיק רוּחֵיהּ בְּהַהוּא נְשִׁיקָה. וְלָא אִתְדָּבַּק בֵּיהּ כְּלָל. וּבְגִינֵי כַּךְ כְּתִיב, יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ, דְּהוּא דְּבֵקוּתָא רוּחָא בְּרוּחָא.","תָּנָא, כָּל זִמְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא אָזִיל בְּיִשְׂרָאֵל, כִּבְיָכוֹל אִתְדָּבַּק רוּחָא בְּרוּחָא, וְעַל דָּא כְּתִיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ', בְּכָל אִינּוּן גַּוְונֵי דְּבֵיקוּתָא, וְלָא מִתְפָּרְשָׁא דָּא מִן דָּא. בְּשַׁעֲתָא דְּאִתְּמַר הִנֵּה אָנֹכִי שֹׂלֵחַ מַלְאָךְ לְפָנֶיךָ, יָדַע מֹשֶׁה דִּפְרִישׁוּתָא הוּא. אָמַר (שמות ל״ג:ט״ו) אִם אֵין פָּנֶיךָ הוֹלְכִים אַל תַּעֲלֵנוּ מִזֶּה.","רַבִּי אַבָּא אָמַר, מַה כְּתִיב לְעֵילָּא מִן דָּא, (שמות לה) רֵאשִׁית בִּכּוּרֵי אַדְמָתְךָ תָּבִיא בֵּית יְיָ' אֱלהֶיךָ לא תְבַשֵּׁל גְּדִי בַּחֲלֵב אִמּוֹ. מַאי קָא מַיְירֵי. אֶלָּא דְּלָא לְעָרְבָא מִלָּה תַּתָּאָה בְּעִלָּאָה, דְּלָא יָנְקָא סִטְרָא דִּלְבַר, מִסִּטְרָא פְּנִימָאָה. מַה בֵּין הַאי לְהַאי. דָּא דִּלְבַר, מִסִּטְרָא דִּמְסַאֲבָא. וְדָא דִּלְגוֹ, בְּסִטְרָא קַדִּישָׁא. מַאן אִמּוֹ. דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּאִתְקְרֵי אֵם. בַּחֲלֵב אִמּוֹ, דְּלָא יָנִיק מֵהַאי סִטְרָא, מַאן דְּלָא אִצְטְרִיךְ.","וְהָכָא כְּתִיב, הִנֵּה אָנֹכִי שֹׁלֵחַ מַלְאָךְ לְפָנֶיךָ. אָמַר מֹשֶׁה, הָא קַבִּילְנָא בִּטְחוֹנָא מִינָךְ, דְּלָא תִּתְפְּרַשׁ מִינָן, וַדַּאי אִם אֵין פָּנְיךָ הוֹלְכִים אַל תַּעֲלֵנוּ מִזֶּה. וּבַמֶּה יִוָּדַע אֵיפוֹא וְגוֹ'."],[[0,"ר' יהודה אמר וכו':","ר\"י אמר, אדני. שבמילואו הוא אלף דלת נון יוד, נקרא הקב\"ה, שהוא ז\"א, ולא הויה, כמו שהוא נכתב, וההוא שנקרא כמו שהוא נכתב, נקרא אדני. ומי הוא. ר' יוסי אומר שהוא מראת אלקים, דהיינו המלכות שנקראת מראה. שואל, מראת כתוב, לשון רבים, ומהו שכתוב מראת. ומשיב, שכולל ג\"כ שלמות הכל, יוד הא ואו הא, שהוא ז\"א. שואל, מראת למאי, אם לשם הוי\"ה אם לשם אדני. ומשיב, הוא אלף דלת נון יוד, ששניהם נקראו בו, זה, מלכות, נקרא ככתבו, וזה, ז\"א, לא נקרא ככתבו, בשם הויה, וע\"כ נקרא בזה, בשם אדני. ועל כך מראת אלקים כתוב, שהוא לשון רבים, כי כולל ז\"א ומלכות. ומטעם זה, נקראים שניהם גם בשם אדון, וזהו טעם על דברי ר' יצחק."],[1,"רבי יהודה אמר וכו':","ועוד אמר ר\"י, לפעמים נקראים העליונים בשם התחתונים ולפעמים נקראים התחתונים בשם העליונים. וע\"כ כתוב, האדון ה' בשם העליון, ז\"א, שהוא אדני שהוא שם התחתון, מלכות. והרי העמדנו הדברים. ובאפנים הרבה מתבארים הדברים, והכל אחד. ברוך הרחמן ברוך שמו לעולם ולעולמי עולמים."],[2,"הנה אנכי שולח מלאך וגו':","ר' יצחק פתח, ישקני מנשיקות פיהו וגו'. אמרה כנסת ישראל, דהיינו השכינה, ישקני מנשיקות פיהו. שואל, מהו הטעם ישקני, יאהבני היה צריך לומר, למה ישקני. ומשיב, אלא כך למדנו, מהו נשיקות. הוא התדבקות רוח ברוח, שמשום זה, נשיקה היא בפה, כי הפה הוא המוצא והמקור של הרוח, ועל כן, הנשיקין הן בפה באהבה, ודבקים רוח ברוח, שאינם מתפרדים זה מן זה."],[3,"ועל דא מאן וכו':","ועל כן, מי שיוצא נשמתו בנשיקה, מתדבק ברוח אחר, דהיינו ברוח של הקב\"ה, ברוח שאינו נפרד ממנו והיינו שנקרא נשיקה. ועל כן אמרה כנסת ישראל, ישקני מנשיקות פיהו, כדי להדביק רוח ברוח, שלא יפרדו זה מן זה."],[4,"כי טובים דודיך מיין:","שואל, מה רוצה כאן יין, והרי כתוב, וגם אלה ביין שגו וגו'. וכתוב, יין ושכר אל תשת אתה ובניך. מהו הטעם שכתוב כאן יין. רבי חייא אמר, מיין של תורה, דהיינו המוחין דז\"א הנקרא תורה, והמוחין דהארת חכמה נקראים יין. רבי חזקיה אמר, זהו שכתוב, ויין ישמח לבב אנוש, שזה נאמר על יינה של תורה, ועל זה כתוב, כי טובים דודיך מיין, שטובים לשמחת הלב, מיין, המשמח אותי יותר מכל."],[4,"","ביאור הדברים. סוד הנשיקין הן בשפתים, ובשפתים יש ב' בחינות, ששפה עלאה, ה\"ס או\"א עלאין המשפיעים שמה אוירא דכיא, שה\"ס אור החסדים, הנקרא רוח, בזווג דלא פסיק לעלמין. ובהם אין יוצא ה \u0003י'\u0004 מאויר שלהם. ושפה תתאה, ה\"ס ישסו\"ת, שבהם יוצא ה \u0003י'\u0004 מאויר שלהם, וחזרו להיות אור החכמה, ומשפיעים שמה הארת חכמה. (כמ\"ש לעיל אות קכ\"ז ד\"ה שפוון דמלכא, ע\"ש כל ההמשך) ואע\"פ שהארת החסדים דאו\"א עלאין ה\"ס ג\"ר ממש, כמ\"ש שם, עם כל זה ז\"א הצריך להארת חכמה, אין אור החסדים דאו\"א אצלו אלא בחינת ו\"ק בלי ראש, משום החסרון של הארת החכמה. אמנם אחר שז\"א מקבל המוחין דישסו\"ת שהם הארת חכמה, אז נעשים אצלו החסדים דאו\"א בחינת ג\"ר ממש כמו שהם באו\"א עלאין עצמם, כי עתה גם הוא נשלם בהארת חכמה ואין בו פגם, כמו או\"א עלאין. והארת החסדים שלהם חשובים יותר מהארת החכמה שבישסו\"ת, להיותם עליונים מהם והמשפיעים שלהם."],[4,"","וזה אמרו. \u0003ישקני מנשיקות פיהו לאדבקא רוחא ברוחא,\u0004 דהיינו הארת החסדים שנקרא רוח, שהם בשפה עלאה, שה\"ס או\"א עלאין, ושפה תתאה, שה\"ס הארת ישסו\"ת שבהם, שהוא הארת חכמה, היא משלמת הרוח של שפה עלאה שיהיה בבחינת ג\"ר כמו באו\"א עצמם. כנ\"ל. וז\"ש \u0003כי טובים דודיך מיין\u0004 וכו' \u0003מיינה דאורייתא,\u0004 כי מתוך שמאיר שם גם שפה תתאה, שהוא הארת חכמה מישסו\"ת, הנקראת יין, נעשו טובים דודיך, שהוא הרוח משפה עלאה, כי עי\"ז נעשו החסדים בבחינת ג\"ר. וזה שאומרת השכינה בסוד הזווג דנשיקין, כי טובים דודיך מיין."],[5,"ר' יהודה אמר וכו':","ר\"י אמר, כתוב, וישק יעקב לרחל וישא את קולו ויבך. שואל, למה בכה. ומשיב, אלא כשהיה בהתדבקות הרוח בה, לא היה יכול הלב לסבול, ובכה. ואם תאמר, הרי כתוב, וישקהו, ויבכו. ומשיב, למדנו, למה נקוד על וישקהו, הוא משום שלא נתדבק בו רוח כלל, ועל זה כתוב, ונעתרות נשיקות שונא. מהו ונעתרות נשיקות שונא. אלא מי שנושק באהבה, מתדבק רוחו ברוחו, בדביקות האהבה, ומי שאינו נושק באהבה, אינו בדבקות, אלא ונעתרות. מהו נעתרות, הוא עוביות, כי לא דבוק רוחו בנשיקה ההוא, ולא נתדבק בה כלל. משום זה כתוב, ישקני מנשיקות פיהו, שהוא דבקות רוח ברוח."],[6,"תאנא כל זמנא וכו':","למדנו, כל זמן שהקב\"ה הולך בישראל, כביכול, נתדבק רוח ברוח. ועל זה כתוב, ואתם הדבקים בה', בכל אלו אפני הדבקות, ואינם נפרדים זה מזה. בשעה שנאמר, הנה אנכי שולח מלאך לפניך, ידע משה שזהו פרישה מישראל, אמר אם אין פניך הולכים אל תעלנו מזה."],[7,"רבי אבא אמר וכו':","רא\"א, מה כתוב למעלה מן זה ראשית בכורי אדמתך תביא בית ה' אלקיך לא תבשל גדי בחלב אמו, שואל, מה הוא אומר. ומשיב, אלא שלא לערב דבר תחתון בעליון, שלא יינק הצד שבחוץ, מן הצד שבפנים. מה בין זה לזה. זה שבחוץ, דהיינו הגדי, הוא מצד הטומאה, וזה שבפנים, דהיינו אמו, היא מצד הקדושה. מי היא אמו. זהו כנסת ישראל, שהיא המלכות, הנקראת אם. כי התפשטות המלכות היא עד הקליפות בסוד ורגליה יורדות מות. בחלב אמו, היינו שלא יינק מצד הזה מי שאינו צריך. ושיעור הכתוב הוא, ראשית בכורי אדמתך תביא בית ה' אלקיך, ובזכות מצוה זו תהיו מובטחים שלא תבשל גדי בחלב אמו, שהחצוניות לא תתערב בפנימיות. כמ\"ש להלאה (אות תקסד)."],[8,"והכא כתיב הנה וגו':","וכאן כתוב, הנה אנכי שולח מלאך לפניך, ונמצאו ישראל שהם פנימיות ודבקים בה', נמסרים תחת המלאך, שהוא חיצוניות. אמר משה, הרי קבלתי בטחון ממך, שלא תפרד ממנו, שבזכות מצות בכורים לא תתערב חיצוניות בפנימיות, כנ\"ל, ודאי אם אין פניך הולכים אל תעלנו מזה. ובמה יודע איפוא וגו'. ולא יקשה הרי הכתוב הזה הוא בפרשת תשא, כי אין מוקדם ומאוחר בתורה."]],[[0,"","רַבִּי יְהוּדָה אָמַר, אֲדנָי - אָלֶ\"ף דָּלֶי\"ת נוּ\"ן יוֹ\"ד, הַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא, וְאוֹתוֹ שֶׁנִּקְרָא כְּמוֹ שֶׁהוּא כָּתוּב, וּמִיהוּ? רַבִּי יוֹסֵי אוֹמֵר, מַרְאֹת אֱלֹהִים. מַרְאַת כָּתוּב. וּמַהוּ מַרְאַת? שְׁלֵמוּת הַכֹּל - יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. (מראת הוא א'כו') מַרְאַת לָמָּה הוּא אָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוֹ\"ד? זֶה נִקְרָא כִּכְתָבוֹ, וְזֶה לֹא נִקְרָא כִּכְתָבוֹ, וּמִשּׁוּם כָּךְ בָּזֶה נִקְרָא, וְעַל כָּךְ מַרְאַת אֱלֹהִים כָּתוּב."],[1,"","רַבִּי יְהוּדָה אָמַר, לִפְעָמִים עֶלְיוֹנִים שֶׁנִּקְרְאוּ בְּשֵׁם תַּחְתּוֹנִים, וְלִפְעָמִים תַּחְתּוֹנִים נִקְרָאִים בְּשֵׁם הָעֶלְיוֹנִים. הָאָדן ה' - בְּשֵׁם עֶלְיוֹן הוּא אֲדנָי, וַהֲרֵי בֵּאַרְנוּ הַדְּבָרִים. וּבִגְוָנִים רַבִּים נִתְפָּרְשׁוּ הַדְּבָרִים, וְהַכֹּל אֶחָד. בָּרוּךְ הָרַחֲמָן וּבָרוּךְ שְׁמוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים."],[2,"","הִנֵּה אָנֹכִי שֹׁלֵחַ מַלְאָךְ לְפָנֶיךְ וְגוֹ'. רַבִּי יִצְחָק פָּתַח, (שיר א) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ וְגוֹ'. אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ. מָה הַטַּעַם יִשָּׁקֵנִי? יֹאהֲבֵנִי הָיָה צָרִיךְ לִהְיוֹת! לָמָּה יִשָּׁקֵנִי? אֶלָּא כָּךְ שָׁנִינוּ, מַה נְּשִׁיקוֹת שֶׁל דְּבֵקוּת שֶׁל רוּחַ בְּרוּחַ, שֶׁבִּגְלַל כָּךְ נְשִׁיקָה בַּפֶּה, שֶׁהֲרֵי הַפֶּה הוּא הַמּוֹצִיא וְהַמָּקוֹר שֶׁל הָרוּחַ, וְלָכֵן נְשִׁיקוֹת בַּפֶּה בַּחֲבִיבוּת, וּדְבֵקִים רוּחַ בְּרוּחַ, שֶׁלֹּא נִפְרָדִים זֶה מִזֶּה."],[3,"","וְלָכֵן מִי שֶׁמּוֹצִיא נִשְׁמָתוֹ בִּנְשִׁיקָה, נִדְבָּק בְּרוּחַ אַחֶרֶת, בְּרוּחַ שֶׁלֹּא נִפְרֶדֶת מִמֶּנּוּ. וְהַיְנוּ נִקְרָא נְשִׁיקָה. וְעַל זֶה אָמְרָה כְּנֶסֶת יִשְׂרָאֵל יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ, לְהַדְבִּיק רוּחַ בְּרוּחַ, שֶׁלֹּא יִפָּרֵד זֶה מִזֶּה."],[4,"","כִּי טוֹבִים דֹּדֶיךְ מִיָּיִן. מָה עוֹשֶׂה כָּאן יַיִן? וַהֲרֵי כָּתוּב (ישעיה כח) וְגַם אֵלֶּה בְּיַיִן שָׁגוּ וְגוֹ', וְכָתוּב (ויקרא י) יַיִן וְשֵׁכָר אַל תֵּשְׁתְּ אַתָּה וּבָנֶיךְ. מָה הַטַּעַם כָּאן יַיִן? רַבִּי חִיָּיא אָמַר, מִיֵּינָהּ שֶׁל תּוֹרָה. רַבִּי חִזְקִיָּה אָמַר, זֶה שֶׁכָּתוּב (תהלים קד) וְיַיִן יְשַׂמַּח לְבַב אֱנוֹשׁ. וְעַל זֶה כָּתוּב כִּי טוֹבִים דֹּדֶיךְ מִיָּיִן, לְחֶדְוַת הַלֵּב. מִיָּיִן - שֶׁמְּשַׂמְּחֵנִי יוֹתֵר מֵהַכֹּל."],[5,"","רַבִּי יְהוּדָה אָמַר, כָּתוּב (בראשית כט) וַיִּשַּׁק יַעֲקֹב לְרָחֵל וַיִּשָּׂא אֶת קוֹלוֹ וַיֵּבְךָּ. לָמָּה בָכָה? אֶלָּא בִּדְבֵקוּת הָרוּחַ בָּהּ לֹא יָכֹל הַלֵּב לִסְבֹּל, וּבָכָה. וְאִם תֹּאמַר, הֲרֵי כָּתוּב וַיִּשָּׁקֵהוּ וַיִּבְכּוּ? שָׁנִינוּ, לָמָּה נָקוּד עַל וַיִּשָּׁקֵהוּ? אֶלָּא שֶׁלֹּא נִדְבְּקָה בּוֹ רוּחַ כְּלָל, וְעַל זֶה כָּתוּב וְנַעְתָּרוֹת נְשִׁיקוֹת שׂוֹנֵא. מַה זֶּה (משלי כז) וְנַעְתָּרוֹת נְשִׁיקוֹת שׂוֹנֵא? אֶלָּא מִי שֶׁנּוֹשֵׁק בַּחֲבִיבוּת, מַדְבִּיק רוּחוֹ בְּרוּחוֹ בִּדְבֵקוּת הַחֲבִיבוּת, וּמִי שֶׁלֹּא נוֹשֵׁק בַּחֲבִיבוּת, זֶה לֹא בִּדְבֵקוּת, אֶלָּא וְנַעְתָּרוֹת. מַה זֶּה נַעְתָּרוֹת? גַּסּוּת, שֶׁלֹּא דָבְקָה רוּחוֹ בְּאוֹתָהּ נְשִׁיקָה וְלֹא נִדְבַּק בּוֹ כְּלָל. וּמִשּׁוּם כָּךְ כָּתוּב, יִשָּׁקֵהוּ מִנְּשִׁיקוֹת פִּיהוּ, שֶׁהִיא דְבֵקוּת רוּחַ בְּרוּחַ."],[6,"","שָׁנִינוּ, כָּל זְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הוֹלֵךְ עִם יִשְׂרָאֵל, כִּבְיָכוֹל נִדְבֶּקֶת רוּחַ בְּרוּחַ, וְעַל זֶה כָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה', בְּכָל אוֹתָם גּוֹנֵי הַדְּבֵקוּת, וְלֹא נִפְרָדִים זֶה מִזֶּה. בְּשָׁעָה שֶׁנֶּאֱמַר הִנֵּה אָנֹכִי שֹׁלֵחַ מַלְאָךְ לְפָנֶיךְ, יָדַע מֹשֶׁה שֶׁזּוֹ פְּרִישָׁה. אָמַר, (שמות לג) אִם אֵין פָּנֶיךְ הֹלְכִים אַל תַּעֲלֵנוּ מִזֶּה."],[7,"","רַבִּי אַבָּא אָמַר, מַה כָּתוּב לְמַעְלָה מִזֶּה? (שם לד) רֵאשִׁית בִּכּוּרֵי אַדְמָתְךְ תָּבִיא בֵּית ה' אֱלֹהֶיךְ לֹא תְבַשֵּׁל גְּדִי בַּחֲלֵב אִמּוֹ. מַה זֶּה אוֹמֵר? אֶלָּא שֶׁלֹּא לְעָרֵב דָּבָר תַּחְתּוֹן בְּעֶלְיוֹן, שֶׁלֹּא יָנַק הַצַּד הַחִיצוֹן מֵהַצַּד הַפְּנִימִי. מַה בֵּין זֶה לָזֶה? זֶה שֶׁבַּחוּץ מִצַּד הַטֻּמְאָה, וְזֶה שֶׁלְּפָנִים בְּצַד הַקְּדֻשָּׁה. מִי הִיא אִמּוֹ? זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרֵאת אֵם. בַּחֲלֵב אִמּוֹ - שֶׁלֹּא יוֹנֵק מִצַּד זֶה מִי שֶׁלֹּא צָרִיךְ."],[8,"","וְכָאן כָּתוּב, הִנֵּה אָנֹכִי שֹׁלֵחַ מַלְאָךְ לְפָנֶיךְ. אָמַר מֹשֶׁה, הֲרֵי קִבַּלְתִּי בִּטָּחוֹן מִמְּךְ שֶׁלֹּא תִפָּרֵד מֵעִמָּנוּ, וַדַּאי אִם אֵין פָּנֶיךְ הֹלְכִים אַל תַּעֲלֵנוּ מִזֶּה. וּבַמֶּה יִוָּדַע אֵפוֹא וְגוֹ'."]]],[["אָמַר רַבִּי אֶלְעָזָר, מִלָּה דָּא לָא קָאָמַר קוּדְשָׁא בְּרִיךְ הוּא אֶלָּא בִּרְחִימוּתָא דְּיִשְׂרָאֵל, וּלְאִתְפַּיְּיסָא בַּהֲדַיְיהוּ. לְמַלְכָּא דְּהֲוָה בָּעֵי לְמֵיזַל עִם בְּרֵיהּ. וְלָא בָּעֵי לְשָׁבְקָא לֵיהּ. אָתָא בְּרֵיהּ, וּמִסְתָּפֵי לְמִבָּעֵי לֵיהּ לְמַלְכָּא דְּיֵיזִיל בַּהֲדֵיהּ. אַקְדִּים מַלְכָּא וְאָמַר, הָא לִגְיוֹן פְּלָן יֵזִיל בַּהֲדָךְ, לְמִנְטַר לָךְ בְּאָרְחָא. לְבָתַר אָמַר אִסְתָּמַּר לָךְ מִנֵּיהּ, (בארחא) דְּהָא לָא גְּבָר שְׁלִים הוּא. אָמַר בְּרֵיהּ, אִי הָכִי, אוֹ אֲנָא אוֹתִיב הָכָא, אוֹ אַתְּ תֵּזִּיל עִמִּי, וְלָא אִתְפְּרַשׁ מִינָךְ. כָּךְ קוּדְשָׁא בְּרִיךְ הוּא, בְּקַדְמִיתָא אָמַר, הִנֵּה אָנֹכִי שֹׂלֵחַ מַלְאָךְ לְפָנֶיךָ לִשְׁמָרְךָ בַּדָּרֶךְ. וּלְבָתַר אָמַר הִשָּׁמֶר מִפָּנָיו וְגוֹ', בֵּיהּ שַׁעֲתָא אָמַר מֹשֶׁה, אִם אֵין פָּנֶיךָ הוֹלְכִים וְגוֹ'.","אָתָא רַבִּי שִׁמְעוֹן, אַשְׁכַּח לְהוּ בְּהַאי. אָמַר, אֶלְעָזָר בְּרִי שַׁפִּיר קָאָמַרְתְּ. אֲבָל תָּא חֲזֵי, בַּאֲתַר דָּא לָא אָמַר מֹשֶׁה מִדִי, וְלָא אָתִיב מִלָּה לָקֳבְלֵיה. מַאי טַעֲמָא. מִשּׁוּם דְּהָכָא לָא אִשְׁתְּכַח פְּרִישׁוּתָא מִנֵּיהּ. וְהָא אוֹקִימְנָא מִלָּה דָּא, לְגַבֵּי חַבְרַיָּיא. וְאִית דְּמַתְנֵי אִיפְּכָא וְלָא הָכִי פֵּירְשׁוּהָ קַדְמָאֵי. וְכַד יִסְתַּכְּלוּן מִלֵּי כֹּלָּא שַׁפִּיר, וְכֹלָּא בְּחַד מִלָּה אַמְרֵי טַעֲמַיְיהוּ.","אֵימָתַי אָתִיב מֹשֶׁה. בְּזִמְנָא דְּאָמַר, (שמות ל״ג:ב׳) וְשָׁלַחְתִּי לְפָנֶיךָ מַלְאָךְ. וּכְתִיב כִּי יֵלֵךְ מַלְאָכִי לְפָנֶיךָ, סָתַם וְלָא פָּרִישׁ מִלָּה. וְעַל דָּא כְּתִיב, הָכָא, כִּי אִם שָׁמוֹעַ תִּשְׁמַע בְּקוֹלוֹ וְעָשִׂיתָ כֹּל אֲשֶׁר אֲדַבֵּר. אֲשֶׁר אֲדַבֵּר דַּוְקָא וּכְתִיב וְאָיַבְתִּי אֶת אוֹיְבֶיךָ וְצַרְתִּי אֶת צוֹרֲרֶיךָ, וְכֹלָּא בֵּיהּ תַּלְיָא.","רִבִּי יְהוּדָה אָמַר, אִי תֵּימָא דְּתַרְוַויְיהוּ מַלְאָךְ מַמָּשׁ, מֹשֶׁה לָא אָתִיב עָלַיְיהוּ, דְּלָא חָמָא דּוּכְתָּא. אֵימָתַי אָתִיב. בְּזִמְנָא דִּכְתִּיב אִם אֵין פָּנְיךָ הוֹלְכִים וְגוֹ'. אָמַר רִבִּי שִׁמְעוֹן, כְּלָל דְּכֹלָּא, מֹשֶׁה לָא בָּעָא מַלְאָכָא. דְּהָא כְּתִיב (שמות לה) וַיֹּאמֶר אִם נָא מָצָאתִי חֵן בְּעֵינֶיךָ אֲדֹנָי יֵלֵךְ נָא אֲדֹנָי בְּקִרְבֵּנוּ.","אָמַר רִבִּי יְהוּדָה, הַאי דְּאָמַר רִבִּי אַבָּא, דִּכְתִּיב לא תְּבַשֵּׁל גְּדִי בַּחֲלֵב אִמּוֹ, בַּחֲלֵב הָאֵם מִבָּעֵי לֵיהּ, מַאי אִמּוֹ. וְאִי תֵּימָא, כְּנֶסֶת יִשְׂרָאֵל אִמּוֹ דְּסִטְרָא דִּמְסָאֳבָא, לָאו הָכִי, דְּהָא שְׁמַעְנָא דְּאָמַר רִבִּי שִׁמְעוֹן, כְּנֶסֶת יִשְׂרָאֵל אִימָּא קַדִּישָׁא בְּחוּלָקֵיהּ דְּיִשְׂרָאֵל אִתְאַחֲדָא, דִּכְתִּיב, (דברים לב) כִּי חֵלֶק יְיָ' עַמּוֹ.","אָמַר רִבִּי שִׁמְעוֹן, שַׁפִּיר קָאָמַרְתְּ. וְהָא דְּרַבִּי אַבָּא שַׁפִּיר וְכֹלָּא דָּא בְּדָא תַּלְיָא. תָּא חֲזִי, אִמָא אִתְאַחֲדָא לְהוּ לְעֵילָּא, לְסִטְרָא דָּא וּלְסִטְרָא דָּא, וּתְרֵין אִינּוּן, חֲדָא לִימִינָא, וַחֲדָא לִשְׂמָאלָא. וּבְגִינֵי כַּךְ, מִנְּהוֹן לִימִינָא, וּמִנְּהוֹן לִשְׂמָאלָא. וְכֻלְּהוּ תַּלְיָין בְּהַאי אֵ\"ם, אִמָּא קַדִּישָׁא, וְאִתְאַחֲדָן בָּהּ.","אֵימָתַי אִתְאַחֲדָן בָּהּ. בְּשַׁעֲתָא דְּהַאי אֵם יָנְקָא מִסִּטְרָא אַחֲרָא, וּמִקְדְּשָׁא אִסְתְּאָב, וְחִוְיָא תַּקִּיפָא שַׁארִי לְאִתְגַּלָּאָה, כְּדֵין גַּדְיָא יַנְקָא מֵחָלָבָא דְּאִמֵּיהּ, וְדִינִין מִתְעָרִין. וְעַל דָּא, יִשְׂרָאֵל קַדְּמִין וְאֵייתָאן בִּכּוּרִים, וּבְשַׁעֲתָא דְּמַיְיתִין לְהוּ, בַּעְיָין לְמֵימַר וּלְמִפְתַּח בֵּיהּ בְּלָבָן, דְּבָעָא בְּחַרְשׁוֹי אִלֵּין, לְשַׁלְּטָאָה בְּיַעֲקֹב, וּבְזַרְעָא קַדִּישָׁא, וְלָא אִתְיְיהִיבוּ בִּידֵיהּ, וְלָא אִתְמַסְּרָן יִשְׂרָאֵל לְסִטְרָא דָּא. וְעַל דָּא כְּתִיב, רֵאשִׁית בִּכּוּרֵי אַדְמָתְךָ וְגוֹ', לא תְּבַשֵּׁל גְּדִי בַּחֲלֵב אִמּוֹ. וְלָא יָנְקָא הַהוּא סִטְרָא, מֵחָלָבָא דְּאִמֵּיהּ, דְּהָא לָא יִסְתְּאָב מַקְדְּשָׁא, וְדִינִין לָא מִתְעָרִין.","בְּגִינֵי כַּךְ, לָא יֵיכוּל בִּשְׂרָא בְּחָלָבָא כָּל זַרְעָא קַדִּישָׁא, וְכָל מַאן דְּאָתֵי מִסְּטַר דָּא, דְּלָא יָהִיב דּוּכְתָּא, לְמַאן דְּלָא אִצְטְרִיךְ, דְּהָא בְּעוֹבָדָא תַּלְיָא מִלְּתָא, בְּעוֹבָדָא דִּלְתַתָּא, לְאַתְעֲרָא לְעֵילָּא. זַכָּאִין אִינּוּן יִשְׂרָאֵל מִכָּל עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, דְמָרֵיהוֹן קָרֵי עָלַיְיהוּ, (דברים י״ד:ב׳) וּבְךָ בָּחַר יְיָ' לִהְיוֹת לוֹ לְעַם סְגֻלָּה. וּכְתִיב (דברים י״ד:ב׳) כִּי עַם קָדוֹשׁ אַתָּה לַיְיָ' אֱלהֶיךָ (וכלא חד מילה) וּכְתִיב (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ' אֱלהֵיכֶם וְגוֹ'.","תָּא חֲזִי, בְּשַׁעֲתָא דְּיִשְׂרָאֵל לָא אִתְכְּשָׁרוּ עוֹבָדַיְיהוּ, מַה כְּתִיב, (ישעיהו ג׳:י״ב) עַמִּי נוֹגְשָׂיו מְעוֹלֵל וְנָשִׁים מָשְׁלוּ בוֹ. מָשְׁלוּ בוֹ דַּיְיקָא, וְהָא אוֹקִימְנָא מִלֵּי בְּרָזָא דְּסִפְרָא דְּשְׁלֹמֹה מַלְכָּא. וְהָכִי אַשְׁכְּחָן בֵּיהּ. תּוּ אַשְׁכְּחָאן, דְּכָל מַאן דְּאָכִיל הַאי מֵיכְלָא דְּאִתְחַבָּר כַּחֲדָא. (או) בְּשַׁעֲתָא חֲדָא, אוֹ בִּסְעוּדָתָא חֲדָא. אַרְבְּעִין יוֹמִין אִתְחַזְיָא גַּדְיָא מְקֻלָּסָא בִּקְלִפּוֹי, לְגַבֵּי אִינּוּן דִּלְעֵילָּא, וְסִיַּעְתָּא מְסָאֲבָא מִתְקָרְבִין בַּהֲדֵיהּ, וְגָרִים לְאַתְעֲרָא דִּינִין בְּעָלְמָא, דִּינִין דְּלָא קַדִּישִׁין."],[[0,"אמר ר' אלעזר וכו':","אר\"א, דבר זה לא אמר הקב\"ה אלא מאהבת ישראל, ולהתרצות עמהם. בדומה למלך שהיה רוצה ללכת עם בנו, ולא רצה לעזוב אותו. בא בנו, והיה מתירא לבקש את המלך שילך עמו. הקדים המלך ואמר, הרי שר צבא פלוני ילך עמך לשמרך בדרך, ואח\"כ אמר, השמר לך ממנו, כי אינו אדם שלם. אמר בנו, אם כן, או שאני אשב פה, או שאתה תלך עמי ולא אפרד ממך. כך הקב\"ה, בתחילה אמר, הנה אנכי שולח מלאך לפניך לשמרך בדרך. ואח\"כ אמר, השמר מפניו וגו'. בו בשעה אמר משה, אם אין פניך הלכים וגו'."],[1,"אתא ר\"ש אשכח וכו':","בא ר' שמעון, ומצאו כשאמר ר\"א מאמר הזה. אמר, אלעזר בני אתה אומר יפה. אבל בוא וראה במקום הזה, כשאמר הקב\"ה הנה אנכי שולח מלאך וגו', לא אמר משה משהו, ולא השיב דבר כנגדו. מה הטעם. משום שכאן לא נמצא פרוד ממנו ית', כי לא נשלח המלאך אלא לשמירה, שכבר העמדנו דבר זה אל החברים. משא\"כ שם כתוב ושלחתי לפניך מלאך וגרשתי וגו' כי לא אעלה בקרבך וגו'. ויש שלמדו בהיפך, שכאן יש פרוד ושם אין פרוד. ולא כן פרשוה הקדמונים. וכשיסתכלו בדברים הכל יפה, וכולם בדבר אחד אמרו טעמם."],[2,"אימתי אתיב משה וכו':","מתי השיב משה, בזמן שאמר, ושלחתי לפניך מלאך, שאח\"כ כתוב, כי לא אעלה בקרבך. וכאן כתוב, כי ילך מלאכי לפניך, סתם ואינו מפרש הדבר, שיאמר, כי לא אעלה בקרבך. וע\"כ כתוב כאן, כי אם שמוע תשמע בקולו ועשית כל אשר אדבר. אשר אדבר בדיוק. וכתוב, ואיבתי את אויביך וצרתי את צורריך. שהכל תלוי בו ית'. ואין כאן פרוד, וע\"כ לא השיב כאן משה."],[3,"ר' יהודה אמר וכו':","רי\"א, ואם תאמר שבשני הפסוקים הוא מלאך ממש, בפרוד, עכ\"ז משה לא השיב עליהם משום שלא היה לו מקום, כי גם על הכתוב שבפרשת תשא, ושלחתי לפניך מלאך, לא השיב משה תיכף, ומתי השיב, בזמן שכתוב אם אין פניך הולכים אל תעלנו מזה, שהשיב זה על מה שכתוב, פני ילכו והנחותי לך. כי אז היה לו מקום להשיב. אמר רבי שמעון, כלל הכל, משה לא רצה במלאך, כי כתוב, ויאמר אם נא מצאתי חן בעיניך אדני ילך נא אדני בקרבנו."],[4,"א\"ר יהודה האי וכו':","אר\"י, זה שאמר ר' אבא, על הכתוב, לא תבשל גדי בחלב אמו. אשר גדי הוא מס\"א, שלא יינק מן השכינה, (לעיל אות ת\"ק) בחלב האם היה צריך לומר, מהו אמו. ואם תאמר שכנסת ישראל, שהיא המלכות, היא אמו של צד הטומאה, אינו כן, כי שמעתי שאמר ר' שמעון, כנסת ישראל שהיא אמא הקדושה, בחלקם של ישראל נתאחדה, שכתוב, כי חלק ה' עמו."],[5,"אמר ר' שמעון וכו':","אר\"ש, יפה אמרת. וזה של ר' אבא יפה. והכל תלוי זה בזה. בוא וראה, אמא, שהיא המלכות, התאחדה להם למעלה לצד זה של הקדושה ולצד זה של הטומאה, ושנים הם: אחד, לימין, ואחד לשמאל, כלומר, שבכל צד יש ימין ושמאל, ומשום זה מהם הם לימין, ומהם הם לשמאל. וכולם תלוים באם הזו, שהיא אמא הקדושה, דהיינו המלכות, ונאחזים בה."],[6,"אימתי אתאחדן בה וכו':","מתי נאחזים בה. בשעה שאם הזו יונקת מצד האחר, והמקדש נטמא, ונחש החזק מתחיל להגלות, אז יונק הגדי מחלב אמו והדינים מתעוררים. ועל כן ישראל מקדימים ומביאים בכורים, ובשעה שמביאים אותם, צריכים לומר ולפתח בלבן דהיינו ארמי אבד אבי, שרצה בכשפיו האלו לשלוט על יעקב ועל זרע הקדוש, ולא ניתנו בידו, ולא נמסרו ישראל לצד הזה. וע\"כ מעבירים בזה כח הנחש, והגדי לא יוכל לינק מחלב אמו. וע\"כ כתוב, ראשית בכורי אדמתך וגו' לא תבשל גדי בחלב אמו, שלא יינק צד הזה מחלב אמו, שהיא המלכות, שלא יטמא המקדש, ולא יתעוררו הדינים."],[7,"בגיני כך לא וכו':","משום זה לא יאכלו בשר בחלב כל זרע הקדוש, וכל מי שבא מצד זה הקדוש, כדי שלא לתת מקום למי שאינו צריך, כי במעשה תלוי הדבר, שצריכים מעשה למטה כדי לעורר למעלה. אשרי הם ישראל מכל העמים עובדי עכו\"ם, שרבונם קרא עליהם, ובך בחר ה' להיות לו לעם סגולה. וכתוב, כי עם קדוש אתה לה' אלקיך, וכתוב בנים אתם לה' אלקיכם וגו'."],[8,"תא חזי בשעתא וכו':","בוא וראה, בשעה שמעשיהם של ישראל אינם טובים, מה כתוב, עמי נוגשיו מעולל ונשים משלו בו, משלובו הוא בדיוק, וכך העמדנו הדברים בסוד הספר של שלמה המלך, וכך מצאנו בו. עוד מצאנו שם, שכל מי שאוכל מאכל ההוא של בשר ושל חלב בשעה אחת, או בסעודה אחת, שהם מתחברים יחד. והוא כמו שאוכל בשר בחלב ביחד. ארבעים יום נראה גדי מקולס בעורו, דהיינו שנצלה כולו כאחת ביחד עם ראשו, לאלו של מעלה, וחבורה של הטומאה מתקרבת עמו, וגורם לעורר בעולם דינים שאינם קדושים."]],[[0,"","אָמַר רַבִּי אֶלְעָזָר, דָּבָר זֶה לֹא אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא בְּאַהֲבַת יִשְׂרָאֵל וּלְהִתְפַּיֵּס עִמָּם. לְמֶלֶךְ שֶׁהָיָה רוֹצֶה לֶלֶכֶת עִם בְּנוֹ, וְלֹא רָצָה לַעֲזֹב אוֹתוֹ. בָּא בְנוֹ וּפָחַד לְבַקֵּשׁ מֵהַמֶּלֶךְ שֶׁיֵּלֵךְ עִמּוֹ. הִקְדִּים הַמֶּלֶךְ וְאָמַר, הֲרֵי לִגְיוֹנֵר פְּלוֹנִי יֵלֵךְ עִמְּךְ לִשְׁמָרְךְ בַּדֶּרֶךְ. לְאַחַר מִכֵּן אָמַר, הִשָּׁמֵר לְךְ מִמֶּנּוּ (בדרך), שֶׁהֲרֵי אֵינוֹ גֶבֶר שָׁלֵם. אָמַר בְּנוֹ, אִם כָּךְ, אוֹ שֶׁאֲנִי אֵשֵׁב כָּאן, אוֹ שֶׁאַתָּה תֵּלֵךְ עִמִּי וְלֹא אֶפָּרֵד מִמְּךְ. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא, בַּתְּחִלָּה אָמַר, הִנֵּה אָנֹכִי שֹׁלֵחַ מַלְאָךְ לְפָנֶיךְ לִשְׁמָרְךְ בַּדָּרֶךְ. וְאַחַר כָּךְ אָמַר, הִשָּׁמֶר מִפָּנָיו וְגוֹ'. בְּאוֹתָהּ שָׁעָה אָמַר מֹשֶׁה, אִם אֵין פָּנֶיךְ הֹלְכִים וְגוֹ'."],[1,"","בָּא רַבִּי שִׁמְעוֹן, מָצָא אוֹתָם בָּזֶה. אָמַר, אֶלְעָזָר בְּנִי, יָפֶה אָמַרְתָּ, אֲבָל בֹּא וּרְאֵה, בַּמָּקוֹם הַזֶּה לֹא אָמַר מֹשֶׁה דָּבָר וְלֹא הֵשִׁיב דָּבָר כְּנֶגְדּוֹ, מָה הַטַּעַם? מִשּׁוּם שֶׁכָּאן לֹא נִמְצֵאת פְּרִישָׁה מִמֶּנּוּ, וַהֲרֵי בֵּאַרְנוּ דָבָר זֶה לַחֲבֵרִים. וְיֵשׁ שׁוֹנִים לְהֵפֶךְ, וְלֹא כָּךְ פֵּרְשׁוּהָ הָרִאשׁוֹנִים. וּכְשֶׁיִּסְתַּכְּלוּ הַדְּבָרִים, הַכֹּל יָפֶה, וְכֻלָּם אָמְרוּ הַטְּעָמִים שֶׁלָּהֶם בְּדָבָר אֶחָד."],[2,"","מָתַי הֵשִׁיב מֹשֶׁה? בִּזְמַן שֶׁאָמַר וְשָׁלַחְתִּי לְפָנֶיךְ מַלְאָךְ. וְכָתוּב, כִּי יֵלֵךְ מַלְאָכִי לְפָנֶיךְ. סָתַם וְלֹא פֵרַשׁ אֶת הַדָּבָר. וְעַל כֵּן כָּתוּב כָּאן, כִּי אִם שָׁמוֹעַ תִּשְׁמַע בְּקֹלוֹ וְעָשִׂיתָ כֹּל אֲשֶׁר אֲדַבֵּר. אֲשֶׁר אֲדַבֵּר דַּוְקָא. וְכָתוּב, וְאָיַבְתִּי אֶת אֹיְבֶיךְ וְצַרְתִּי אֶת צֹרֲרֶיךְ, וְהַכֹּל תָּלוּי בּוֹ."],[3,"","רַבִּי יְהוּדָה אָמַר, אִם תֹּאמַר שֶׁשְּׁנֵיהֶם מַמָּשׁ מַלְאָךְ - מֹשֶׁה לֹא הֵשִׁיב עֲלֵיהֶם, שֶׁלֹּא רָאָה מָקוֹם. וּמָתַי הֵשִׁיב? בִּזְמַן שֶׁכָּתוּב אִם אֵין פָּנֶיךְ הֹלְכִים אַל תַּעֲלֵנוּ וְגוֹ'. אָמַר רַבִּי שִׁמְעוֹן, כְּלָל שֶׁל הַכֹּל - מֹשֶׁה לֹא רָצָה מַלְאָךְ. שֶׁהֲרֵי כָּתוּב, (שמות לד) וַיֹּאמֶר אִם נָא מָצָאתִי חֵן בְּעֵינֶיךְ אֲדנָי יֵלֵךְ נָא אֲדנָי בְּקִרְבֵּנוּ."],[4,"","אָמַר רַבִּי יְהוּדָה, זֶה שֶׁאָמַר רַבִּי אַבָּא, שֶׁכָּתוּב לֹא תְבַשֵּׁל גְּדִי בַּחֲלֵב אִמּוֹ, בַּחֲלֵב הָאֵם הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה אִמּוֹ? וְאִם תֹּאמַר, כְּנֶסֶת יִשְׂרָאֵל אִמּוֹ שֶׁמִּצַּד הַטֻּמְאָה - לֹא כָּךְ! שֶׁהֲרֵי שָׁמַעְתִּי שֶׁאָמַר רַבִּי שִׁמְעוֹן, כְּנֶסֶת יִשְׂרָאֵל הָאֵם הַקְּדוֹשָׁה נֶאֶחְזָה בַּחֵלֶק שֶׁל יִשְׂרָאֵל, שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ."],[5,"","אָמַר רַבִּי שִׁמְעוֹן, יָפֶה אָמַרְתָּ, וְזֶה שֶׁל רַבִּי אַבָּא יָפֶה, וְהַכֹּל תָּלוּי זֶה בָּזֶה. בּא וּרְאֵה, הָאֵם נֶאֶחְזָה לָהֶם לְמַעְלָה לְצַד זֶה וּלְצַד זֶה, וּשְׁנַיִם הֵם - אֶחָד לְיָמִין וְאֶחָד לִשְׂמֹאל. וּמִשּׁוּם כָּךְ, מֵהֶם לְיָמִין וּמֵהֶם לִשְׂמֹאל, וְכֻלָּם תְּלוּיִים בָּאֵם הַזֹּאת, הָאֵם הַקְּדוֹשָׁה, וְנֶאֱחָזִים בָּהּ."],[6,"","מָתַי הֵם נֶאֱחָזִים בָּהּ? בְּשָׁעָה שֶׁהָאֵם הַזּוֹ יוֹנֶקֶת מִן הַצַּד הָאַחֵר וְהַמִּקְדָּשׁ נִטְמָא, וְהַנָּחָשׁ הֶחָזָק מַתְחִיל לְהִתְגַּלּוֹת, וְאָז הַגְּדִי יוֹנֵק מֵחֲלֵב אִמּוֹ, וּמִתְעוֹרְרִים הַדִּינִים. וְעַל זֶה יִשְׂרָאֵל מַקְדִּימִים וּמְבִיאִים בִּכּוּרִים. וּבְשָׁעָה שֶׁהֵם מְבִיאִים אוֹתָם, צְרִיכִים לוֹמַר וְלִפְתֹּחַ בְּלָבָן, שֶׁרָצָה בִּכְשָׁפָיו אֵלּוּ לִשְׁלֹט בְּיַעֲקֹב וּבְזֶרַע הַקֹּדֶשׁ, וְלֹא נִתְּנוּ בְיָדוֹ וְלֹא נִמְסְרוּ יִשְׂרָאֵל לְצַד זֶה. וְעַל זֶה כָּתוּב, רֵאשִׁית בִּכּוּרֵי אַדְמָתְךְ וְגוֹ', לֹא תְבַשֵּׁל גְּדִי בַּחֲלֵב אִמּוֹ. וְלֹא יוֹנֵק אוֹתוֹ הַצַּד מֵחֲלֵב אִמּוֹ, שֶׁהֲרֵי לֹא נִטְמָא הַמִּקְדָּשׁ, וְהַדִּינִים לֹא מִתְעוֹרְרִים."],[7,"","מִשּׁוּם כָּךְ לֹא יֹאכַל בָּשָׂר בְּחָלָב כָּל זֶרַע הַקֹּדֶשׁ, וְכָל מִי שֶׁבָּא מֵהַצַּד הַזֶּה, שֶׁלֹּא יִתֵּן מָקוֹם לְמִי שֶׁלֹּא צָרִיךְ, שֶׁהֲרֵי בְּמַעֲשֶׂה תָּלוּי הַדָּבָר, בְּמַעֲשֶׂה שֶׁלְּמַטָּה לְעוֹרֵר לְמַעְלָה. אַשְׁרֵיהֶם יִשְׂרָאֵל מִכָּל הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, שֶׁרִבּוֹנָם קוֹרֵא עֲלֵיהֶם, (שם יד) וּבְךְ בָּחַר ה' לִהְיוֹת לוֹ לְעַם סְגֻלָּה. וְכָתוּב (שם) כִּי עַם קָדוֹשׁ אַתָּה לַה' אֱלֹהֶיךְ. וְכָתוּב (שם) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם וְגוֹ'."],[8,"","בֹּא וּרְאֵה, בְּשָׁעָה שֶׁיִּשְׂרָאֵל לֹא הֻכְשְׁרוּ מַעֲשֵׂיהֶם, מַה כָּתוּב? (ישעיה ג) עַמִּי נֹגְשָׂיו מְעוֹלֵל וְנָשִׁים מָשְׁלוּ בוֹ. דַּוְקָא מָשְׁלוּ בוֹ, וַהֲרֵי בֵּאַרְנוּ הַדְּבָרִים בְּסוֹד סִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ, וְכָךְ מָצָאנוּ בוֹ. וְעוֹד מָצָאנוּ, שֶׁכָּל מִי שֶׁאוֹכֵל מַאֲכָל זֶה שֶׁהִתְחַבֵּר כְּאֶחָד, (או) בְּשָׁעָה אַחַת אוֹ בִּסְעוּדָה אַחַת, אַרְבָּעִים יוֹם נִרְאֶה גְדִי מְקֻלָּס בִּקְלִפָּתוֹ אֶל אוֹתָם שֶׁלְּמַעְלָה, וְסִיעָה טְמֵאָה מִתְקָרְבִים עִמּוֹ, וְגוֹרֵם לְעוֹרֵר דִּינִים בָּעוֹלָם, דִּינִים שֶׁאֵינָם קְדוֹשִׁים."]]],[["וְאִי אוֹלִיד בַּר בְּאִינּוּן יוֹמִין, אוֹזְפִין לֵיהּ נִשְׁמְתָא, מִסִּטְרָא אַחֲרָא, דְּלָא אִצְטְרִיכָא. וּכְתִיב (ויקרא י״א:מ״ד) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים וְגוֹ'. אָתֵי לְאִסְתַּאֲבָא, מְסָאֲבִין לֵיהּ וַדַּאי. דִּכְתִּיב, (ויקרא י״א:מ״ד) וְנִטְמֵתֶם בָּם, חָסֵר א', מְסָאֳבוּתָא אֲטִימָא מִכֹּלָּא, דְּלֵית רְשׁוּ לְאִתְדַּכְּאָה הָכִי, כִּשְׁאַר זִינֵי דִּמְסָאֳבוּתָא דְּמִתְדַּכִּין. וְתוּ, דְּמִסְתָּפֵי מֵחֵיוָן בִּישָׁן, דְּהָא בְּעֵינַיְיהוּ גַּדְיָא אִשְׁתְּכַח, וְיָכִיל לְאַתְּזְקָא, דְּהָא צֻלְמָא דְּבַר נָשׁ אִתְעֲבָר מִנֵּיהּ.","רַבִּי יֵיסָא, שָׁרֵי לְמֵיכַל לְתַרְנְגוֹלָא בִּגְבִינָה אוֹ בְּחָלָבָא. אָמַר רִבִּי שִׁמְעוֹן אָסִיר לָךְ דְּלָא יָהִיב אִינִישׁ פִּתְחָא לְזִינִין בִּישִׁין. לֵךְ לֵךְ אַמְרִין נְזִירָא, סְחוֹר סְחוֹר לְכַרְמָא לָא תִּקְרַב. וַדַּאי אָסִיר לָךְ הוּא, דְּחוּמְרָא אִית בֵּיהּ, כִּבְעִירָא לַשְּׁחִיטָה. וּמַאן דְּשָׁרֵי הַאי, מַה כְּתִיב (עמוס ב׳:י״ב) וַתַּשְׁקוּ אֶת הַנְּזִירִים יָיִן, מַאן דְּשָׁרֵי הַאי, כְּמַאָן דְּשָׁרֵי הַאי. וּכְתִיב (דברים י״ד:ג׳) לֹא תֹאכַל כָּל תּוֹעֵבָה, כָּל, לְאַכְלָלָא כֹּלָּא.","תָּאנָא, בְּמָה זָכוּ דָּנִיֵאל חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה, דְּאִשְׁתְּזִיבוּ מֵאִינּוּן נִסְיוֹנֵי, אֶלָּא בְּגִין דְּלָא אִסְתָּאֲבוּ בְּמֵיכְלֵיהוֹן. אָמַר רִבִּי יְהוּדָה, כְּתִיב (דניאל א׳:ח׳) וַיָּשֶׂם דָּנִיֵאל עַל לִבּוֹ אֲשֶׁר לא יִתְגָּאַל בְּפַת בַּג הַמֶּלֶךְ וְגוֹ'. וְתָאנָא בִּסְתִימָא דְּמַתְנִיתִין, מֵיכְלָא דְּהַהוּא רָשָׁע, בִּשְׂרָא בְּחָלָבָא הֲוָה וּגְבִינָה עִם בִּשְׂרָא, בַּר מֵיכְלָן אַחֲרָנִין, וְדָא סָלִיק לֵיהּ בְּפָתוֹרֵיהּ, בְּכָל יוֹמָא.","וְדָנִיֵאל דְּאִסְתָּמַּר מֵהַאי, כַּד רָמוּ יָתֵיהּ לְגוּבָא דְּאַרְיָיוָותָא, אִשְׁתְּלִים בְּצוּלְמָא דְּמָארֵיהּ, וְלָא שָׁנֵי (בראשית קצ\"א ע\"א) צוּלְמֵיהּ לְצוּלְמָא אַחֲרָא, וְעַל דָּא דַּחֲלוּ אַרְיָיוָותָא מִנֵּיהּ, וְלָא חַבְּלוּהוּ. וְהַהוּא רָשָׁע, בְּשַׁעֲתָא דְּמַלְכוּתָא אִתְעָדֵי מִנֵּיהּ, (דניאל ד׳:כ׳) וְעִם חֵיוַת בָּרָא הֲוָה מָדוֹרֵיהּ, אַעְדֵּי צוּלְמָא דְּאַנְפּוֹי מִנֵּיהּ, וּמֵהַהוּא יוֹמָא, לָא אִתְחָזֵי צוּלְמֵיהּ, צוּלְמָא דְּבַר נָשׁ. וְכָל בְּעִירָא דְּאָתֵי, אִתְחָזֵי לֵיהּ, צוּלְמָא דְּזִינֵיהּ, וְנוּקְבֵיהּ, וַהֲווּ אַתְיָין עָלֵיהּ כֻּלְּהוּ, וּבְכַמָּה זִמְנִין הֲווֹ אַכְלִין לֵיהּ חֵיוָת בָּרָא, בַּר דְּאִתְגְּזַר הַאי עוֹנְשָׁא עָלֵיהּ, בְּגִין דִּכְתִּיב, (חבקוק א׳:י׳) וְהוּא בַּמְּלָכִים יִתְקַלָּס, בְּגִין כַּךְ, כֹּלָּא יִתְקַלְּסוּ בֵּיהּ, כָּל הַהוּא זִמְנָא.","תָּא חֲזִי, מַה כְּתִיב, (דניאל א׳:י״ג) וּלְמִקְצַת יָמִים עֲשָׂרָה נִרְאָה מַרְאֵיהֶן טוֹב מִכָּל הַיְלָדִים הָאוֹכְלִים אֶת פַּת בַּג הַמֶּלֶךְ. נִרְאָה מַרְאֵיהֶן טוֹב, דְּצוּלְמָא דְּמָארֵיהוֹן לָא אַעְדִּיאוּ מִנְּהוֹן, וּמֵאַחֲרִנֵי אַעְדִּיאוּ. מַאן גָּרִים הַאי. בְּגִין דְּלָא אִתְגַּעֲלוּ בְּגִיעוּלֵי מֵיכְלֵיהוֹן. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דִּכְתִּיב בְּהוּ, וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי.","(שמות כ״ד:א׳) וְאֶל מֹשֶׁה אָמַר עֲלֵה אֶל יְיָ' וְגוֹ'. וְאֶל מֹשֶׁה אָמַר, (קל\"א ע\"א) מַאן אָמַר. דָּא שְׁכִינְתָּא. עֲלֵהּ אֶל יְיָ', כְּמָה דִּכְתִּיב, (שמות י״ט:ג׳) וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים וְגוֹ'. (ס\"א ויקרא אליו יי') אֲמַאי כָּל דָּא, לְקַיְּימָא עִמְּהוֹן קַיָּים, בְּגִין דְּהָא אִתְפְּרָעוּ, מַה דְּלָא נָפְקוּ הָכִי מִמִּצְרַיִם, דְּאִתְגְּזָרוּ, וְלָא אִתְפְּרָעוּ, (מ' ע\"א) וְהָכָא הָא אִתְפְּרָעוּ, וְעָאלוּ בִּבְרִית קַיָּימָא, דִּכְתִּיב, (שמות ט״ו:כ״ה) שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט. דַּיְיקָא וְשָׁם נִסָּהוּ, בְּהַאי אָת קַדִּישָׁא, דְּאִתְגַּלְיָיא בְּהוּ, וְהָכָא אִתְקַיָּים בְּהוּ, עַל יְדָא דְּמֹשֶׁה גְּזִירָה דְּקַיָּימָא, דִּכְתִּיב, וַיִּקַּח מֹשֶׁה אֶת הַדָּם וַיִּזְרֹק עַל הָעָם וְגוֹ'.","אָמַר רִבִּי יִצְחָק מַאי דִּכְתִּיב, וַחֲצִי הַדָּם זָרַק עַל הַמִּזְבֵּחַ, בַּמִּזְבֵּחַ לָא כְּתִיב, אֶלָּא עַל הַמִּזְבֵּחַ דַּיְיקָא. וְהִשְׁתַּחֲוִיתֶם מֵרָחֹק, מַהוּ מֵרָחֹק. כְּמָה דְאַתְּ אָמֵר (ירמיהו ל״א:ג׳) מֵרָחוֹק יְיָ' נִרְאָה לִי. וּכְתִיב, (שמות ב׳:ד׳) וַתֵּתַצַּב אֲחֹתוֹ מֵרָחֹק. תָּאנֵי רִבִּי אַבָּא, דְּקַיְּימָא סִיהֲרָא בִּפְגִימוּתָא, וּבֵיהּ שַׁעֲתָא, זָכוּ יִשְׂרָאֵל יַתִּיר בְּחוּלָקָא קַדִּישָׁא, וְגָזְרוּ קַיָּימָא קַדִּישָׁא בְּקוּדְשָׁא בְּרִיךְ הוּא.","וְאֶל מֹשֶׁה אָמַר עֲלֵה אֶל יְיָ'. מַאי טַעְמָא. אָמְרָה לֵיהּ שְׁכִינְתָּא, אִסְתְּלִיק לְעֵילָּא, דְּהָא אֲנָא וְיִשְׂרָאֵל, נִשְׁתַּתֵּף כַּחֲדָא בִּשְׁלֵימוּתָא עַל יְדָךְ, מַה דְּלָא הֲוָה עַד הָכָא. מַה כְּתִיב וַיִּקַּח מֹשֶׁה חֲצִי הַדָּם וְגוֹ', פָּלַג לֵיהּ לִתְרֵין. חֲצִי הַדָּם זָרַק עַל הָעָם, וַחֲצִי הַדָּם זָרַק עַל הַמִּזְבֵּחַ, כְּמָה דְּאוֹקִימְנָא. וּכְתִיב, הִנִּה דַּם הַבְּרִית אֲשֶׁר כָּרַת יְיָ' עִמָּכֶם. וַיָּשֶׂם בָּאַגָּנֹת, בָּאַגָּנַת כְּתִיב, חָסֵר וָא\"ו. כְּמָה דִּכְתִּיב, (שיר השירים ז׳:ג׳) שָׁרְרֵךְ אַגַן הַסַּהַר אַל יֶחְסַר הַמָּזֶג."],[[0,"ואי אוליד בר וכו':","ואם הוליד בן בימים האלו, משאילים לו נשמה מצד האחר, שאינה צריכה לו, כי מטמאת אותו, וכתוב, והתקדשתם והיתם קדושים וגו' הבא לטמא מטמאים אותו ודאי שכתוב, ונטמתם בם חסר א', שהיא טומאה אטומה יותר מכל הטומאות, שאין לו רשות להטהר כמו שאר מיני טומאות שמטהרות. ועוד שמפחד מחיות רעות כי נראה בעיניהם כמו גדי ויכולות להזיקו, כי הצלם של אדם נעבר ממנו."],[1,"ר' ייסא שרי וכו':","ר' ייסא התיר לאכול תרנגול בגבינה או בחלב. אמר ר' שמעון אסור לך. שאיש אינו צריך לתת פתח למינים הרעים לך לך אומרים לנזיר, סבב סבב, אל הכרם לא תקרב. ודאי הוא אסור לך כי יש בו חומרת השחיטה כמו בבהמה. ומי שמתיר זה מה כתוב בו, ותשקו את הנזירים יין, כי מי שמתיר זה מתיר זה. שהפגם הנעשה למעלה, אחד בהם. וכתוב, לא תאכלו כל תועבה. כל בא לכלול הכל."],[2,"תאנא במה זכו וכו':","למדנו, במה זכו דניאל חנניא מישאל ועזריה, שנצולו מנסיונות האלו, אלא משום שלא נטמאו במאכלם. אמר ר' יהודה כתוב, וישם דניאל על לבו אשר לא יתגאל בפת בג המלך וגו', ולמדנו בסוד המשנה, שהמאכל של אותו רשע, של נבוכדנצר, היה בשר בחלב, וגבינה עם בשר, חוץ ממאכלים אחרים, וזה עלה על שלחנו בכל יום."],[3,"ודניאל דאסתמר מהאי וכו':","ודניאל שנשמר מזה, כשהשליכו אותו לבור האריות, היה שלם בצלם רבונו, ולא נשתנה צלמו לצלם אחר, וע\"כ יראו האריות ממנו, ולא חבלו אותו. ורשע ההוא, בשעה שהמלכות הוסרה ממנו, ועם חיות השדה היה מגורו, הוסר צלם פניו ממנו, ומיום ההוא לא נראה צלמו כצלם האדם, וכל בהמה שבאה, נראה לה שהוא צלם של מינה, ונקבה שלה, והיו כולם באים עליו. והרבה פעמים היו אוכלים אותו חיות השדה לולא שנגזר עליו אותו עונש, כמו שכתוב, והוא במלכים יתקלס. משום זה כולם יתקלסו בו כל זמן ההוא."],[4,"תא חזי מה וכו':","בוא וראה, מה כתוב, ולמקצת ימים עשרה נראה מראיהן טוב מכל הילדים האוכלים את פת בג המלך. נראה מראיהן טוב, פירושו שצלם רבונם לא הוסר מהם, ומאחרים הוסר. מי גרם זה, משום שלא נגעלו בגיעולי מאכלם. אשרי חלקם של ישראל, שכתוב בהם, ואנשי קדש תהיון לי."],[5,"ואל משה אמר:","שואל, מי אמר. ומשיב זה השכינה. עלה אל ה', כמ\"ש, ומשה עלה אל האלקים. ולמה כל זה, הוא כדי להקים עמהם ברית, משום שנפרעו, מה שלא יצאו כן ממצרים, שאז נמולו ולא נפרעו, וכאן כבר נפרעו ונכנסו באות ברית, שכתוב, שם שם לו חוק ומשפט, שפירושו מילה ופריעה, (כנ\"ל בשלח אות שמ\"ט) ושם נסהו. באות הקדוש שנתגלה בהם. וכאן נתקיים בהם על ידי משה כריתת הברית, שכתוב, ויקח משה את הדם ויזרק על העם וגו'."],[6,"א\"ר יצחק מה וכו':","אר\"י, מה שכתוב, וחצי הדם זרק על המזבח. במזבח לא כתוב, כי מזבח רומז על מלכות, וכריתת הברית הוא ביסוד, אלא \u0003על\u0004 המזבח בדיוק, אשר \u0003על\u0004 המזבח רומז ליסוד שהוא ממעל המלכות. והשתחויתם מרחק. שואל, מהו מרחק. ומשיב, הוא כמש\"א מרחוק ה' נראה לי (שפירשו תמצא בפ' וירא אות מ\"ה בהסולם) וכתוב, ותתצב אחותו מרחק. תאני ר' אבא, שעמדה הלבנה, שהיא המלכות, במיעוטה, וע\"כ נאמר, והשתחויתם מרחוק. ובה בשעה זכו ישראל יותר בחלק הקדוש, וכריתת ברית קדש בהקב\"ה."],[7,"ואל משה אמר עלה אל ה':","שואל, מהו הטעם. ומשיב, אמרה לו השכינה, הסתלק למעלה, כי אני וישראל נשתתף יחד בשלמות על ידך, מה שלא היה כן עד עתה. מה כתוב, ויקח משה חצי הדם וישם באגנת וגו', שחלקו לשנים כדרך שעושים בכריתת ברית, חצי הדם זרק על העם, וחצי הדם זרק על המזבח, כמו שהעמדנו, שעל המזבח הוא יסוד, וכתוב, הנה דם הברית אשר כרת ה' עמכם. וישם באגנת, באגנת כתוב, חסר ו', שהוא כמ\"ש, שררך אגן הסהר וגו'. שאגנת הוא מלכות שהוא אגן הסהר, וע\"כ כתוב חסר \u0003ו'\u0004. הרי שחצי הדם שזרק על העם, קשר בהשכינה שנקראת אגנת, ונמצא שהשכינה וישראל נשלמו יחד על ידי משה. כנ\"ל."]],[[0,"","וְאִם מוֹלִיד בֵּן בְּאוֹתָם יָמִים, מַלְוִים לוֹ נְשָׁמָה מֵהַצַּד הָאַחֵר, שֶׁלֹּא צָרִיךְ אוֹתוֹ. וְכָתוּב (ויקרא יא) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדֹשִׁים וְגוֹ'. בָּא לְהִטָּמֵא - מְטַמְּאִים אוֹתוֹ וַדַּאי, שֶׁכָּתוּב (שם) וְנִטְמֵתֶם בָּם. חָסֵר א'. טֻמְאָה אֲטוּמָה יוֹתֵר מִכֹּל, שֶׁאֵין רְשׁוּת לְהִטָּהֵר כָּךְ כְּמוֹ שְׁאָר מִינֵי הַטֻּמְאוֹת שֶׁנִּטְהָרוֹת. וְעוֹד, שֶׁפּוֹחֵד מֵחַיּוֹת רָעוֹת, שֶׁהֲרֵי בְעֵינֵיהֶם נִמְצָא גְדִי וְיָכוֹל לְהִנָּזֵק, שֶׁהֲרֵי צֶלֶם אָדָם הָעֳבַר מִמֶּנּוּ."],[1,"","רַבִּי יֵיסָא הִתִּיר לֶאֱכֹל תַּרְנְגוֹל בִּגְבִינָה אוֹ בְּחָלָב. אָמַר רַבִּי שִׁמְעוֹן, אָסוּר לְךְ, שֶׁלֹּא יִתֵּן אִישׁ פֶּתַח לַמִּינִים הָרָעִים. לֵךְ לֵךְ אוֹמְרִים לְנָזִיר, סָבִיב סָבִיב לַכֶּרֶם לֹא תִקְרַב. וַדַּאי אָסוּר לְךְ הוּא, שֶׁחֻמְרָה יֵשׁ בּוֹ כִּבְהֵמָה לִשְׁחִיטָה, וּמִי שֶׁמַּתִּיר אֶת זֶה מַה כָּתוּב? (עמוס ב) וַתַּשְׁקוּ אֶת הַנְּזִרִים יָיִן. מִי שֶׁמַּתִּיר אֶת זֶה, כְּמִי שֶׁמַּתִּיר אֶת זֶה. וְכָתוּב (דברים יד) לֹא תֹאכַל כָּל תּוֹעֵבָה. כָּל - לְהַכְלִיל הַכֹּל."],[2,"","שָׁנִינוּ, בַּמֶּה זָכוּ דָנִיֵּאל, חֲנַנְיָה, מִישָׁאֵל וַעֲזַרְיָה שֶׁנִּצְלוּ מֵאוֹתָם נִסְיוֹנוֹת? אֶלָּא מִשּׁוּם שֶׁלֹּא נִטְמְאוּ בְמַאַכְלֵיהֶם. אָמַר רַבִּי יְהוּדָה, כָּתוּב (דניאל א) וַיָּשֶׂם דָּנִיֵּאל עַל לִבּוֹ אֲשֶׁר לֹא יִתְגָּאַל בְּפַת בַּג הַמֶּלֶךְ וְגוֹ'. וְשָׁנִינוּ בְּסֵתֶר הַמִּשְׁנָה, מַאֲכַל אוֹתוֹ הָרָשָׁע, בָּשָׂר בְּחָלָב הָיָה וּגְבִינָה עִם בָּשָׂר, פְּרָט לְמַאֲכָלִים אֲחֵרִים, וְזֶה עָלָה לוֹ עַל שֻׁלְחָנוֹ בְּכָל יוֹם."],[3,"","וְדָנִיִּאִל שֶׁנִּשְׁמַר מִזֶּה, כְּשֶׁזְּרָקוּהוּ לְגֹב הָאֲרָיוֹת, הִשְׁתַּלֵּם בְּצֶלֶם רִבּוֹנוֹ, וְלֹא שִׁנָּה צַלְמוֹ לְצֶלֶם אַחֵר, וְלָכֵן פָּחֲדוּ מִמֶּנּוּ הָאֲרָיוֹת וְלֹא חִבְּלוּ בוֹ. וְאוֹתוֹ רָשָׁע, בְּשָׁעָה שֶׁהָעָבְרָה מִמֶּנּוּ מַלְכוּתוֹ וּמְדוֹרוֹ הָיָה עִם חַיּוֹת הַשָּׂדֶה, הָעֳבַר מִמֶּנּוּ צֶלֶם פָּנָיו, וּמֵאוֹתוֹ יוֹם לֹא נִרְאָה צַלְמוֹ צֶלֶם שֶׁל אָדָם, וְכָל בְּהֵמָה שֶׁבָּאָה, נִרְאָה לָהּ בְּצֶלֶם שֶׁל מִינָהּ וּנְקֵבָתָהּ, וְכֻלָּם הָיוּ בָאִים עָלָיו, וּבְכַמָּה פְעָמִים הָיוּ אוֹכְלוֹת אוֹתוֹ חַיּוֹת הַשָּׂדֶה זוּלַת נִגְזַר עָלָיו הָעֹנֶשׁ הַזֶּה, מִשּׁוּם שֶׁכָּתוּב (חבקוק א) וְהוּא בַּמְּלָכִים יִתְקַלָּס, מִשּׁוּם כָּךְ כֻּלָּם הִתְקַלְּסוּ בוֹ כָּל אוֹתוֹ זְמַן."],[4,"","בֹּא וּרְאֵה מַה כָּתוּב, וּמִקְצָת יָמִים עֲשָׂרָה נִרְאָה מַרְאֵיהֶם טוֹב (וגו') מִן כָּל הַיְלָדִים הָאֹכְלִים אֵת פַּת בַּג הַמֶּלֶךְ. נִרְאָה מַרְאֵיהֶם טוֹב - שֶׁצֶּלֶם רִבּוֹנָם לֹא זָז מֵהֶם, וּמֵאֲחֵרִים זָז. מִי גָרַם אֶת זֶה? מִשּׁוּם שֶׁלֹּא נִגְעֲלוּ בְּגִעוּלֵי מַאַכְלֵיהֶם. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁכָּתוּב בָּהֶם, וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי."],[5,"","וְאֶל מֹשֶׁה אָמַר עֲלֵה אֶל ה' וְגוֹ'. וְאֶל מֹשֶׁה אָמַר - מִי אָמַר? זוֹ שְׁכִינָה. עֲלֵה אֶת ה', כַּכָּתוּב (שמות יט) וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים וְגוֹ'. (ויק, רא א, ליו ה') לָמָּה כָּל זֶה? לְקַיֵּם עִמָּם בְּרִית, כִּי הֲרֵי נִפְרְעוּ, מַה שֶּׁלֹּא יָצְאוּ כָּךְ מִמִּצְרַיִם, שֶׁנִּמּוֹלוּ וְלֹא נִפְרְעוּ, וְכָאן הֲרֵי נִפְרְעוּ וְנִכְנְסוּ בִּבְרִית הַקֹּדֶשׁ, שֶׁכָּתוּב שָׁם שָׂם לוֹ חֹקֶ וּמִשְׁפָּט. וְשָׁם נִסָּהוּ - בְּאוֹת הַקֹּדֶשׁ הַזּוֹ שֶׁנִּגְלְתָה בָהֶם, וְכָאן הִתְקַיְּמָה בָהֶם עַל יְדֵי מֹשֶׁה מִילַת הַבְּרִית, שֶׁכָּתוּב וַיִּקַּח מֹשֶׁה אֶת הַדָּם וַיִּזְרֹק עַל הָעָם וְגוֹ'."],[6,"","אָמַר רַבִּי יִצְחָק, מַה שֶׁכָּתוּב וַחֲצִי הַדָּם זָרַק עַל הַמִּזְבֵּחַ, בַּמִּזְבֵּחַ לֹא כָתוּב, אֶלָּא דַּוְקָא עַל הַמִּזְבֵּחַ. וְהִשְׁתַּחֲוִיתֶם מֵרָחֹק, מַהוּ מֵרָחֹק? כְּמוֹ שֶׁנֶּאֱמַר (ירמיה לא) מֵרָחוֹק ה' נִרְאָה לִי. וְכָתוּב (שמות ב) וַתֵּתַּצַּב אֲחֹתוֹ מֵרָחֹק. שָׁנָה רַבִּי אַבָּא, שֶׁעָמְדָה הַלְּבָנָה בִּפְגִימָתָהּ, וּבָהּ בְּשָׁעָה זָכוּ יִשְׂרָאֵל יוֹתֵר בְּחֵלֶק קָדוֹשׁ, וְגָזְרוּ בְּרִית קֹדֶשׁ עִם הַקָּדוֹשׁ בָּרוּךְ הוּא."],[7,"","וְאֶל מֹשֶׁה אָמַר עֲלֵה אֶל ה'. מָה הַטַּעַם? אָמְרָה לוֹ שְׁכִינָה, עֲלֵה לְמַעְלָה, שֶׁהֲרֵי אֲנִי וְיִשְׂרָאֵל נִשְׁתַּתֵּף כְּאֶחָד בִּשְׁלֵמוּת עַל יָדְךְ, מַה שֶּׁלֹּא הָיָה עַד כָּאן. מַה כָּתוּב? וַיִּקַּח מֹשֶׁה חֲצִי הַדָּם וְגוֹ'. חִלְּקוֹ לִשְׁנַיִם, חֲצִי הַדָּם זָרַק עַל הָעָם, וַחֲצִי הַדָּם זָרַק עַל הַמִּזְבֵּחַ, כְּמוֹ שֶׁבֵּאַרְנוּ. וְכָתוּב, וְהִנֵּה דַּם הַבְּרִית אֲשֶׁר כָּרַת ה' עִמָּכֶם. וַיָּשֶׂם בָּאַגָּנֹת, כָּתוּב בָּאַגָּנַת, חָסֵר וָא\"ו, כְּמוֹ שֶׁכָּתוּב (שיר השירים ז) שָׁרְרֵךְ אַגָּן הַסַּהַר אַל יֶחְסַר הַמָּזֶג."]]],[["(שמות כ״ד:ב׳) וְנִגַּשׁ מֹשֶׁה לְבַדּוֹ אֶל יְיָ', זַכָּאָה חוּלָקֵיהּ דְּמֹשֶׁה, דְּהוּא בִּלְחוֹדוֹי, זָכָה לְמָה דְּלָא זָכָה בַּר נָשׁ אַחֲרָא. יִשְׂרָאֵל זָכוּ הַשְׁתָּא, מַה דְּלָא זָכוּ עַד הַהִיא שַׁעֲתָא. וְהַהִיא שַׁעֲתָא, אִתְקְיָּימוּ, בְּקִיּוּמָא עִלָּאָה קַדִּישָׁא. וּבְהַהוּא שַׁעֲתָא אִתְבַּשָּׂרוּ לְמֶהֱוֵי בֵּינַיְיהוּ מַקְדְּשָׁא, כְּמָה דְאַתְּ אָמֵר, (שמות כ״ה:ח׳) וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם.","(שמות כ״ד:י׳) וַיִּרְאוּ אֶת אֱלֹהֵי יִשְׂרָאֵל וְתַחַת רַגְלָיו כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (שיר השירים ז׳:ח׳) זֹאת קוֹמָתֵךְ דָּמְתָה לְתָמָר וְגוֹ', כַּמָּה חֲבִיבָה כְּנֶסֶת יִשְׂרָאֵל קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, דְּלָא מִתְפָּרְשָׁא מִנִּיהּ, כְּהַאי תָּמָר, דְּלָא פָּרִישׁ דְּכַר מִן נוּקְבָּא לְעָלְמִין, וְלָא (ל\"ז ע\"ב) סָלִיק, דָּא בְּלָא דָּא. כַּךְ כְּנֶסֶת יִשְׂרָאֵל, לָא מִתְפָּרְשָׁא מְקוּדְשָׁא בְּרִיךְ הוּא.","תָּא חֲזִי, בְּשַׁעֲתָא דְּנָדָב וַאֲבִיהוּא חָמוּ, וְשִׁבְעִין סָבִין. מַה כְּתִיב בְּהוּ. וַיִּרְאוּ אֶת אֱלהֵי יִשְׂרָאֵל. דְּאִתְגְּלֵי עָלַיְיהוּ שְׁכִינְתָּא. רַבִּי יְהוּדָה וְרַבִּי יוֹסִי אַמְרֵי, אֶת דַּיְיקָא. וְדָא אֶת, הוּא מֵרָחוֹק. אֶת לְאַכְלְלָא מַה דִּי בְּגַוֵּיהּ.","רַבִּי יִצְחָק אָמַר, וְהָא כְּתִיב (יחזקאל י׳:כ׳) הִיא הַחַיָּה אֲשֶׁר רָאִיתִי תַּחַת אֱלהֵי יִשְׂרָאֵל בִּנְהַר כְּבָר, מַאן חַיָּה דָּא. אָמַר רִבִּי יוֹסִי אָמַר רַבִּי חִיָּיא, חַיָּה זוּטְרַתִּי. וְכִי אִית חַיָּה זוּטְרַתִּי, אִין. חַיָּה זוּטְרַתִּי, וְחַיָּה עִלָּאָה. וְחַיָּה זוּטְרָא (בראשית י\"א ע\"ב) דְּזוּטַרְתִּי.","וַיִּרְאוּ אֶת אֱלהֵי יִשְׂרָאֵל, דַּיְיקָא, כְּמָה דַּאֲמֵינָא. וְתַחַת רַגְלָיו כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר, כְּחֵזוּ אֶבֶן טָבָא, דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמִבְנֵי מַקְדְּשָׁא, דִּכְתִּיב, (ישעיהו נ״ד:י״א) ויסַדְתִּיךְ בַּסַּפִּירִים.","(שמות כ״ד:א׳) וְאֶל אֲצִילֵי בְּנֵי יִשְׂרָאֵל, דָּא נָדָב וַאֲבִיהוּא. לא שָׁלַח יָדוֹ, דְּסָלִיק לוֹן לְבָתַר זִמְנָא, וְלָא אִתְעֲנָשׁוּ הָכָא. רַבִּי יוֹסִי אָמַר, מִלָּה דָּא, לִשְׁבָחָא דִּלְהוֹן, דִּכְתִּיב וַיֹּאכְלוּ וַיִּשְׁתּוּ דְּזָנוּ עֵינֵיהוֹן, מִנְּהִירוּ דָּא. רַבִּי יְהוּדָה אָמַר, אֲכִילָה וַדָּאִית אָכְלוּ, וְזָנוּ גַּרְמַיְיהוּ, וְהָכָא אִתְקְשָׁרוּ לְעֵילָּא, אִי לָא דְּסָטוּ אוֹרְחַיְיהוּ לְבָתַר, כְּמָה דְּאוֹקִימְנָא.","אָמַר רַבִּי אֶלְעָזָר, וַאֲפִילּוּ יִשְׂרָאֵל, בְּהַהִיא שַׁעֲתָא אִתְכְּשָׁרוּ, וְאִתְקַשָּׁרַת בְּהוּ שְׁכִינְתָּא. וְדָא קַיָּימָא, וְאוֹרַיְיתָא כֹּלָּא, בְּחַד זִמְנָא הֲוָה. וְיִשְׂרָאֵל כְּהַהִיא שַׁעֲתָא לָא חָמוּ לְעָלְמִין. וּלְזִמְנָא דְּאָתֵי, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאִתְגַּלָּאָה עַל בְּנוֹי, וּלְמֵחמֵי כֹּלָּא יְקָרָא דִּילֵיהּ עֵינָא בְּעֵינָא, דִּכְתִּיב (ישעיהו נ״ב:ח׳) כִּי עַיִן בְּעַיִן יִרְאוּ בְּשׁוּב יְיָ' צִיּוֹן. וּכְתִיב, (ישעיהו מ׳:ה׳) ונִגְלָה כְּבוֹד יְיָ' ורָאוּ כָל בָּשָׂר יַחְדָּו וגוֹ'."],[[0,"ונגש משה לבדו אל ה':","אשרי חלקו של משה, שהוא לבדו זכה מה שלא זכה אדם אחר. ישראל זכו עתה מה שלא זכו עד שעה ההיא. ובשעה ההיא נתקיימו בקיום עליון קדוש. ובשעה ההיא נתבשרו שיהיה ביניהם מקדש. כמש\"א ועשו לי מקדש ושכנתי בתוכם."],[1,"ויראו את אלקי ישראל ותחת וגו':","ר' יהודה פתח, זאת קומתך דמתה לתמר, וגו', כמה חביבה כנסת ישראל לפני הקב\"ה, שאינה נפרדת ממנו, כתמר הזה שהזכר אינו פורש מן הנקבה לעולם, ואינם עולים זה בלא זה כך כנסת ישראל אינה נפרדת מן הקב\"ה."],[2,"תא חזי בשעתא וכו':","בוא וראה בשעה שנדב ואביהוא ראו, ושבעים זקנים, מה כתוב בהם, ויראו את אלקי ישראל, שנתגלתה עליהם השכינה. ר' יהודה ור' יוסי אמרו, \u0003את\u0004, שכתוב את אלקי, הוא מדויק, ו \u0003את\u0004 הזה יורה שהוא מרחוק. \u0003את\u0004 הוא כולל מה שיש בתוכו. שראו מה שיש בפנימיות השכינה."],[3,"ר' יצחק אמר וכו':","רי\"א, והרי כתוב, היא החיה אשר ראיתי בנהר כבר, מי היא חיה הזו. אמר ר' יוסי אמר ר' חייא, חיה קטנה, שהיא המלכות. שואל, וכי יש חיה קטנה. ומשיב, כן. כי יש חיה קטנה, שהיא המלכות. וחיה עליונה, שהיא בחג\"ת מחזה ולמעלה דז\"א. וחיה קטנה שבקטנות, שהיא חיה דעולם היצירה."],[4,"ויראו את אלקי ישראל:","את, בדיוק כמו שאמרתי. ותחת רגליו כמעשה לבנת הספיר, כמראה אבן טוב שעתיד הקב\"ה לבנות המקדש. שכתוב, ויסדתיך בספירים."],[5,"ואל אצילי בני ישראל:","זהו נדב ואביהוא. \u0003לא שלח ידו,\u0004 שהעלה אותם לדין לאחר זמן, ולא נענשו כאן. ר' יוסי אומר דבר זה, לשבחם שכתוב, ויאכלו וישתו, שפירושו, שזנו עיניהם מאור הזה. ר' יהודה אמר אכילה ודאית אכלו וזנו את עצמם, מאור הזה, וכאן נתקשרו למעלה, כלומר, שהמשיכו האור ממטה למעלה, ולא היה בזה חטא, אם לא שסרו מן הדרך לאחר כך, כמו שהעמדנו."],[6,"אמר ר' אלעזר וכו':","אר\"א, ואפילו ישראל בשעה ההיא היו כשרים ונקשרה בהם השכינה. וברית הזה וכל התורה, בזמן אחד היו, כלומר, שהיו להם אז הארה מכל התורה. וישראל כשעה ההיא לא ראו לעולם. ולעתיד לבא, עתיד הקב\"ה להתגלות על בניו, ויראו כולם כבודו עין בעין, שכתוב, כי עין בעין יראו בשוב ה' ציון, וכתוב, ונגלה כבוד ה' וראו כל בשר יחדיו וגו'."]],[[0,"","וְנִגַּשׁ מֹשֶׁה לְבַדּוֹ אֶל ה'. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה שֶׁהוּא לְבַדּוֹ זָכָה לְמַה שֶּׁלֹּא זָכָה אָדָם אַחֵר. יִשְׂרָאֵל זָכוּ עַכְשָׁו מַה שֶּׁלֹּא זָכוּ עַד לְאוֹתָהּ שָׁעָה, וְאוֹתָהּ שָׁעָה הִתְקַיְּמוּ בְקִיּוּם עֶלְיוֹן קָדוֹשׁ, וּבְאוֹתָהּ שָׁעָה הִתְבַּשְּׂרוּ לִהְיוֹת הַמִּקְדָּשׁ בֵּינֵיהֶם, כְּמוֹ שֶׁנֶּאֱמַר (שמות כה) וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם."],[1,"","וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל וְתַחַת רַגְלָיו כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (שיר השירים ז) זֹאת קוֹמָתֵךְ דָּמְתָה לְתָמָר וְגוֹ'. כַּמָּה חֲבִיבָה כְּנֶסֶת יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁלֹּא נִפְרֶדֶת מִמֶּנּוּ כַּתָּמָר הַזֶּה שֶׁלֹּא נִפְרָד הַזָּכָר מֵהַנְּקֵבָה לְעוֹלָמִים, וְלֹא עוֹלֶה זֶה בְּלִי זֶה. כָּךְ כְּנֶסֶת יִשְׂרָאֵל לֹא נִפְרֶדֶת מֵהַקָּדוֹשׁ בָּרוּךְ הוּא."],[2,"","בֹּא וּרְאֵה, בְּשָׁעָה שֶׁנָּדָב וַאֲבִיהוּא רָאוּ, וְשִׁבְעִים זְקֵנִים, מַה כָּתוּב בָּהֶם? וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל. שֶׁהִתְגַּלְּתָה עֲלֵיהֶם שְׁכִינָה. רַבִּי יְהוּדָה וְרַבִּי יוֹסֵי אוֹמְרִים, אֵת דַּוְקָא, וְזֶה אֵת הוּא מֵרָחוֹק. אֵת - לְהַכְלִיל אֶת מַה שֶּׁבְּתוֹכוֹ."],[3,"","רַבִּי יִצְחָק אָמַר, וַהֲרֵי כָּתוּב (יחזקאל י) הִיא הַחַיָּה אֲשֶׁר רָאִיתִי תַּחַת אֱלֹהֵי יִשְׂרָאֵל בִּנְהַר כְּבָר. מִי הַחַיָּה הַזּוֹ? אָמַר רַבִּי יוֹסֵי אָמַר רַבִּי חִיָּיא, חַיָּה קְטַנָּה. וְכִי יֵשׁ חַיָּה קְטַנָּה? כֵּן. חַיָּה קְטַנָּה, וְחַיָּה עֶלְיוֹנָה, וְחַיָּה קְטַנָּה שֶׁבַּקְּטַנּוֹת."],[4,"","וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל, דַּוְקָא, כְּמוֹ שֶׁאָמַרְנוּ. וְתַחַת רַגְלָיו כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר, כְּמַרְאֵה אֶבֶן טוֹבָה שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְנוֹת הַמִּקְדָּשׁ, שֶׁכָּתוּב (ישעיה נד) וִיסַדְתִּיךְ בַּסַּפִּירִים."],[5,"","וְאֶל אֲצִילֵי בְּנֵי יִשְׂרָאֵל - זֶה נָדָב וַאֲבִיהוּא. לֹא שָׁלַח יָדוֹ - שֶׁהֶעֱלָה אוֹתָם לְאַחַר זְמַן, וְכָאן לֹא נֶעֶנְשׁוּ. רַבִּי יוֹסֵי אָמַר דָּבָר זֶה לְשִׁבְחָם, שֶׁכָּתוּב וַיֹּאכְלוּ וַיִּשְׁתּוּ, שֶׁזָּנוּ עֵינֵיהֶם מֵהָאוֹר הַזֶּה. רַבִּי יְהוּדָה אָמַר, אֲכִילָה וַדָּאִית אָכְלוּ וְזָנוּ עַצְמָם, וְכָאן נִקְשְׁרוּ לְמַעְלָה אִם לֹא שֶׁסָּטוּ דַרְכֵיהֶם אַחַר כָּךְ, כְּמוֹ שֶׁבֵּאַ רְנוּ."],[6,"","אָמַר רַבִּי אֶלְעָזָר, וַאֲפִלּוּ יִשְׂרָאֵל בְּאוֹתָהּ שָׁעָה הֻכְשְׁרוּ וְנִקְשְׁרָה בָהֶם שְׁכִינָה, וְהַבְּרִית הַזּוֹ וְכָל הַתּוֹרָה בִּזְמַן אֶחָד זֶה הָיָה, וְיִשְׂרָאֵל כְּאוֹתָהּ שָׁעָה לֹא רָאוּ לְעוֹלָמִים. וְלֶעָתִיד לָבֹא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִגָּלוֹת עַל בָּנָיו וּלְהַרְאוֹת אֶת כָּל כְּבוֹדוֹ עַיִן בְּעַיִן, שֶׁכָּתוּב (שם נב) כִּי עַיִן בְּעַיִן יִרְאוּ בְּשׁוּב ה' צִיּוֹן. וְכָתוּב (שם מ) וְנִגְלָה כְּבוֹד ה' וְרָאוּ כָל בָּשָׂר יַחְדָּו וְגוֹ'."]]]]};
